/// Whether the per-column INSERT preserialize sub-timers are armed.
///
/// Cached in a `OnceLock` rather than read per call: every other env read on a
/// hot path in this workspace is already behind one, and an uncached
/// `std::env::var` here would itself be a per-row cost on the path this flag
/// exists to keep cheap.
#[inline]
fn dml_profile_deep_enabled() -> bool {
    #[cfg(test)]
    if FSQLITE_DML_PROFILE_DEEP_TEST_OVERRIDE.load(AtomicOrdering::Relaxed) {
        return true;
    }
    *FSQLITE_DML_PROFILE_DEEP_ENABLED.get_or_init(|| {
        std::env::var("FSQLITE_DML_PROFILE_DEEP")
            .map(|value| value == "1" || value.eq_ignore_ascii_case("true"))
            .unwrap_or(false)
    })
}

#[inline]
fn record_hot_path_duration(metric: &AtomicU64, start: Option<Instant>) {
    record_hot_path_elapsed_ns(metric, hot_path_elapsed_ns(start));
}

#[inline]
fn hot_path_elapsed_ns(start: Option<Instant>) -> Option<u64> {
    let start = start?;
    Some(u64::try_from(start.elapsed().as_nanos()).unwrap_or(u64::MAX))
}

#[inline]
fn record_hot_path_elapsed_ns(metric: &AtomicU64, elapsed_ns: Option<u64>) {
    if let Some(elapsed_ns) = elapsed_ns {
        metric.fetch_add(elapsed_ns, AtomicOrdering::Relaxed);
    }
}

#[inline]
fn profile_count_from_usize(value: usize) -> u64 {
    u64::try_from(value).unwrap_or(u64::MAX)
}

#[inline]
fn record_hot_path_count(metric: &AtomicU64, value: u64) {
    if hot_path_profile_enabled() {
        metric.fetch_add(value, AtomicOrdering::Relaxed);
    }
}

fn record_concurrent_commit_plan_success(plan: &PreparedConcurrentCommit) {
    if !hot_path_profile_enabled() {
        return;
    }

    FSQLITE_CONCURRENT_COMMIT_PLAN_SUCCESSES.fetch_add(1, AtomicOrdering::Relaxed);
    FSQLITE_CONCURRENT_COMMIT_PLAN_WRITE_PAGES.fetch_add(
        profile_count_from_usize(plan.write_set_pages().len()),
        AtomicOrdering::Relaxed,
    );
    FSQLITE_CONCURRENT_COMMIT_PLAN_HELD_LOCK_PAGES.fetch_add(
        profile_count_from_usize(plan.held_lock_pages().len()),
        AtomicOrdering::Relaxed,
    );
    if plan.used_uncontended_prepare_fast_path() {
        FSQLITE_CONCURRENT_COMMIT_PLAN_UNCONTENDED_FAST_PATHS.fetch_add(1, AtomicOrdering::Relaxed);
    } else if plan.used_candidate_free_prepare_fast_path() {
        FSQLITE_CONCURRENT_COMMIT_PLAN_CANDIDATE_FREE_FAST_PATHS
            .fetch_add(1, AtomicOrdering::Relaxed);
    } else {
        FSQLITE_CONCURRENT_COMMIT_PLAN_FULL_VALIDATIONS.fetch_add(1, AtomicOrdering::Relaxed);
    }
}

fn record_concurrent_commit_plan_error(error: &FrankenError) {
    if !hot_path_profile_enabled() {
        return;
    }

    FSQLITE_CONCURRENT_COMMIT_PLAN_ERRORS.fetch_add(1, AtomicOrdering::Relaxed);
    if matches!(error, FrankenError::BusySnapshot { .. }) {
        FSQLITE_CONCURRENT_COMMIT_PLAN_BUSY_SNAPSHOT_ERRORS.fetch_add(1, AtomicOrdering::Relaxed);
    }
}

fn record_prepared_direct_insert_page_run_flush(
    record_count: usize,
    byte_count: usize,
    variant_metric: &AtomicU64,
) {
    if !hot_path_profile_enabled() {
        return;
    }
    FSQLITE_PREPARED_DIRECT_INSERT_PAGE_RUN_FLUSHES.fetch_add(1, AtomicOrdering::Relaxed);
    FSQLITE_PREPARED_DIRECT_INSERT_PAGE_RUN_RECORDS.fetch_add(
        profile_count_from_usize(record_count),
        AtomicOrdering::Relaxed,
    );
    FSQLITE_PREPARED_DIRECT_INSERT_PAGE_RUN_BYTES.fetch_add(
        profile_count_from_usize(byte_count),
        AtomicOrdering::Relaxed,
    );
    variant_metric.fetch_add(1, AtomicOrdering::Relaxed);
}

fn record_prepared_direct_insert_owned_page_run_flush(records: &[(i64, Vec<u8>)]) {
    if !hot_path_profile_enabled() {
        return;
    }
    let byte_count = records
        .iter()
        .fold(0_usize, |sum, (_, record)| sum.saturating_add(record.len()));
    record_prepared_direct_insert_page_run_flush(
        records.len(),
        byte_count,
        &FSQLITE_PREPARED_DIRECT_INSERT_PAGE_RUN_OWNED_FLUSHES,
    );
}

fn record_prepared_direct_insert_arena_page_run_flush(
    records: &[(i64, Range<usize>)],
    record_bytes: &[u8],
) {
    record_prepared_direct_insert_page_run_flush(
        records.len(),
        record_bytes.len(),
        &FSQLITE_PREPARED_DIRECT_INSERT_PAGE_RUN_ARENA_FLUSHES,
    );
}

fn record_prepared_direct_insert_repeated_page_run_flush(rowids: &[i64], record: &[u8]) {
    record_prepared_direct_insert_page_run_flush(
        rowids.len(),
        rowids.len().saturating_mul(record.len()),
        &FSQLITE_PREPARED_DIRECT_INSERT_PAGE_RUN_REPEATED_FLUSHES,
    );
}

