/// Planner-dispatch sub-timings in ns (bd-5310l), accumulated while profiling is enabled.
///
/// Order: `[to_string (cache-key derivation), plan_compute (directive selection)]`.
#[must_use]
pub fn planner_dispatch_ns() -> [u64; 2] {
    [
        FSQLITE_COMPILE_TO_STRING_NS.load(AtomicOrdering::Relaxed),
        FSQLITE_PLAN_COMPUTE_NS.load(AtomicOrdering::Relaxed),
    ]
}

/// Compile sub-phase timings in ns (bd-5310l), accumulated while profiling is enabled.
///
/// Order: `[schema_clone, canonicalize+to_string, planner_directive, codegen, builder.finish]`.
#[must_use]
pub fn compile_subphase_ns() -> [u64; 5] {
    [
        FSQLITE_COMPILE_SCHEMA_CLONE_NS.load(AtomicOrdering::Relaxed),
        FSQLITE_COMPILE_CANONICAL_NS.load(AtomicOrdering::Relaxed),
        FSQLITE_COMPILE_PLANNER_NS.load(AtomicOrdering::Relaxed),
        FSQLITE_COMPILE_CODEGEN_NS.load(AtomicOrdering::Relaxed),
        FSQLITE_COMPILE_FINISH_NS.load(AtomicOrdering::Relaxed),
    ]
}

