/// Whether the core execution arm dispatches this stock PRAGMA by its
/// unqualified name. SQLite permits these forms to carry a database schema
/// prefix (for example, `PRAGMA main.table_info(t)`).
fn pragma_dispatches_without_schema(name: &str) -> bool {
    [
        "wal_checkpoint",
        "table_info",
        "table_xinfo",
        "index_list",
        "index_info",
        "index_xinfo",
        "foreign_key_check",
        "foreign_key_list",
        "compile_options",
        "database_list",
        "table_list",
        "collation_list",
        "data_version",
        "encoding",
    ]
    .iter()
    .any(|candidate| name.eq_ignore_ascii_case(candidate))
}

fn pragma_attached_scope_is_global(name: &str) -> bool {
    [
        "busy_timeout",
        "temp_store",
        "wal_autocheckpoint",
        "foreign_keys",
        "recursive_triggers",
        "query_only",
        "writable_schema",
        "case_sensitive_like",
        "trusted_schema",
        "read_uncommitted",
        "cell_size_check",
        "checkpoint_fullfsync",
        "automatic_index",
        "threads",
        "compile_options",
        "database_list",
        "collation_list",
    ]
    .iter()
    .any(|candidate| name.eq_ignore_ascii_case(candidate))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PragmaSchemaScope {
    Unqualified,
    Main,
    Temp,
}

fn pragma_schema_scope(pragma: &fsqlite_ast::PragmaStatement) -> PragmaSchemaScope {
    match pragma.name.schema.as_deref() {
        Some(schema) if schema.eq_ignore_ascii_case("main") => PragmaSchemaScope::Main,
        Some(schema) if schema.eq_ignore_ascii_case("temp") => PragmaSchemaScope::Temp,
        _ => PragmaSchemaScope::Unqualified,
    }
}

fn pragma_qualified_relation(scope: PragmaSchemaScope, relation: &str) -> String {
    let relation = quote_identifier(relation);
    match scope {
        PragmaSchemaScope::Unqualified => relation,
        PragmaSchemaScope::Main => format!("main.{relation}"),
        PragmaSchemaScope::Temp => format!("temp.{relation}"),
    }
}

/// Map a `pragma_<name>` table-valued function to its static column-name slice.
/// Returns `None` for any name that is not a supported pragma TVF, which keeps
/// the TVF surface bounded to the row-returning introspection pragmas.
fn pragma_table_function_columns(name: &str) -> Option<&'static [&'static str]> {
    let prefix = name.get(..7)?;
    if !prefix.eq_ignore_ascii_case("pragma_") {
        return None;
    }
    let pragma = &name[7..];
    if pragma.eq_ignore_ascii_case("table_info") {
        Some(&PRAGMA_TABLE_INFO_TVF_COLUMNS)
    } else if pragma.eq_ignore_ascii_case("table_xinfo") {
        Some(&PRAGMA_TABLE_XINFO_TVF_COLUMNS)
    } else if pragma.eq_ignore_ascii_case("index_list") {
        Some(&PRAGMA_INDEX_LIST_TVF_COLUMNS)
    } else if pragma.eq_ignore_ascii_case("index_info") {
        Some(&PRAGMA_INDEX_INFO_TVF_COLUMNS)
    } else if pragma.eq_ignore_ascii_case("index_xinfo") {
        Some(&PRAGMA_INDEX_XINFO_TVF_COLUMNS)
    } else if pragma.eq_ignore_ascii_case("foreign_key_list") {
        Some(&PRAGMA_FOREIGN_KEY_LIST_TVF_COLUMNS)
    } else {
        None
    }
}

struct HtmMetricsVtab;

#[derive(Clone)]
struct CachePagesVtabFactory {
    pager: PagerBackend,
}

struct CachePagesVtab {
    pager: PagerBackend,
}

#[derive(Default)]
struct HtmMetricsCursor {
    row: Vec<SqliteValue>,
    emitted: bool,
}

struct CachePagesCursor {
    pager: PagerBackend,
    rows: Vec<PageCachePageSnapshot>,
    row_idx: usize,
}

impl VirtualTable for HtmMetricsVtab {
    type Cursor = HtmMetricsCursor;

    fn connect(_cx: &Cx, _args: &[&str]) -> Result<Self> {
        Ok(Self)
    }

    fn best_index(&self, info: &mut IndexInfo) -> Result<()> {
        info.estimated_cost = 1.0;
        info.estimated_rows = 1;
        Ok(())
    }

    fn open(&self) -> Result<Self::Cursor> {
        Ok(HtmMetricsCursor::default())
    }
}

impl VirtualTableCursor for HtmMetricsCursor {
    fn filter(
        &mut self,
        _cx: &Cx,
        _idx_num: i32,
        _idx_str: Option<&str>,
        _args: &[SqliteValue],
    ) -> Result<()> {
        self.row = htm_metrics_row_values(flat_combining_metrics());
        self.emitted = false;
        Ok(())
    }

    fn next(&mut self, _cx: &Cx) -> Result<()> {
        self.emitted = true;
        Ok(())
    }

    fn eof(&self) -> bool {
        self.emitted
    }

    fn column(&self, ctx: &mut ColumnContext, col: i32) -> Result<()> {
        if self.eof() {
            ctx.set_value(SqliteValue::Null);
            return Ok(());
        }

        let value = usize::try_from(col)
            .ok()
            .and_then(|idx| self.row.get(idx).cloned())
            .unwrap_or(SqliteValue::Null);
        ctx.set_value(value);
        Ok(())
    }

    fn rowid(&self) -> Result<i64> {
        Ok(if self.eof() || self.row.is_empty() {
            0
        } else {
            1
        })
    }
}

impl VtabModuleFactory for CachePagesVtabFactory {
    fn create(&self, _cx: &Cx, _args: &[&str]) -> Result<Box<dyn ErasedVtabInstance>> {
        Ok(Box::new(CachePagesVtab {
            pager: self.pager.clone(),
        }))
    }

    fn connect(&self, _cx: &Cx, _args: &[&str]) -> Result<Box<dyn ErasedVtabInstance>> {
        Ok(Box::new(CachePagesVtab {
            pager: self.pager.clone(),
        }))
    }

    fn column_info(&self, _args: &[&str]) -> Vec<(String, char)> {
        CACHE_PAGES_TABLE_COLUMN_NAMES
            .iter()
            .map(|(name, ty)| ((*name).to_owned(), *ty))
            .collect()
    }
}

impl VirtualTable for CachePagesVtab {
    type Cursor = CachePagesCursor;

    fn create(_cx: &Cx, _args: &[&str]) -> Result<Self> {
        Err(FrankenError::Internal(
            "fsqlite_cache_pages requires the connection-local module factory".to_owned(),
        ))
    }

    fn connect(_cx: &Cx, _args: &[&str]) -> Result<Self> {
        Err(FrankenError::Internal(
            "fsqlite_cache_pages requires the connection-local module factory".to_owned(),
        ))
    }

    fn best_index(&self, info: &mut IndexInfo) -> Result<()> {
        info.estimated_cost = 1.0;
        info.estimated_rows = 64;
        Ok(())
    }

    fn open(&self) -> Result<Self::Cursor> {
        Ok(CachePagesCursor {
            pager: self.pager.clone(),
            rows: Vec::new(),
            row_idx: 0,
        })
    }
}

impl VirtualTableCursor for CachePagesCursor {
    fn filter(
        &mut self,
        _cx: &Cx,
        _idx_num: i32,
        _idx_str: Option<&str>,
        args: &[SqliteValue],
    ) -> Result<()> {
        if !args.is_empty() {
            return Err(FrankenError::Internal(
                "fsqlite_cache_pages does not accept arguments".to_owned(),
            ));
        }
        self.rows = self.pager.cache_page_snapshots()?;
        self.row_idx = 0;
        Ok(())
    }

    fn next(&mut self, _cx: &Cx) -> Result<()> {
        self.row_idx = self.row_idx.saturating_add(1);
        Ok(())
    }

    fn eof(&self) -> bool {
        self.row_idx >= self.rows.len()
    }

    fn column(&self, ctx: &mut ColumnContext, col: i32) -> Result<()> {
        let Some(row) = self.rows.get(self.row_idx) else {
            ctx.set_value(SqliteValue::Null);
            return Ok(());
        };

        let value = match col {
            0 => SqliteValue::Integer(i64::from(row.page_no.get())),
            1 => row
                .version_txn_id
                .and_then(|value| i64::try_from(value).ok())
                .map_or(SqliteValue::Null, SqliteValue::Integer),
            2 => row
                .queue
                .map(|queue| SqliteValue::Text(queue.as_str().into()))
                .unwrap_or(SqliteValue::Null),
            3 => SqliteValue::Integer(i64::from(row.dirty)),
            4 => SqliteValue::Integer(i64::from(row.ref_count)),
            5 => SqliteValue::Integer(i64::try_from(row.access_count).unwrap_or(i64::MAX)),
            _ => SqliteValue::Null,
        };
        ctx.set_value(value);
        Ok(())
    }

    fn rowid(&self) -> Result<i64> {
        let Some(row) = self.rows.get(self.row_idx) else {
            return Ok(0);
        };
        Ok(i64::from(row.page_no.get()))
    }
}

/// Map a SQL type name to its SQLite affinity byte (§3.1 Type Affinity Rules).
///
/// Encoding: A..E maps to BLOB, TEXT, NUMERIC, INTEGER, REAL:
/// `'A'` = BLOB, `'B'` = TEXT, `'C'` = NUMERIC, `'D'` = INTEGER, `'E'` = REAL.
fn type_name_to_affinity(name: &str) -> u8 {
    let upper = name.to_uppercase();
    if upper.contains("INT") {
        b'D' // INTEGER affinity
    } else if upper.contains("CHAR") || upper.contains("TEXT") || upper.contains("CLOB") {
        b'B' // TEXT affinity
    } else if upper.contains("BLOB") || upper.is_empty() {
        b'A' // BLOB affinity
    } else if upper.contains("REAL") || upper.contains("FLOA") || upper.contains("DOUB") {
        b'E' // REAL affinity
    } else {
        b'C' // NUMERIC affinity
    }
}

/// A database row produced by a query.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Row {
    values: Vec<SqliteValue>,
}

impl Row {
    /// Returns all values in this row.
    pub fn values(&self) -> &[SqliteValue] {
        &self.values
    }

    /// Returns the value at `index`, if present.
    pub fn get(&self, index: usize) -> Option<&SqliteValue> {
        self.values.get(index)
    }
}

fn rows_into_value_vectors(rows: Vec<Row>) -> Vec<Vec<SqliteValue>> {
    rows.into_iter().map(|row| row.values).collect()
}

type QueryRowHandler<'a> = dyn FnMut(&Row) -> Result<()> + 'a;

