// ── Time-travel MemDatabase snapshots ──────────────────────────────────────
// For :memory: databases (and as a fallback when the MVCC VersionStore is not
// populated), time-travel queries are satisfied by cloning the MemDatabase at
// each COMMIT and storing the snapshot keyed by commit_seq + timestamp.

/// A snapshot of the in-memory database captured at COMMIT time.
#[derive(Debug, Clone)]
struct TimeTravelSnapshotEntry {
    commit_seq: u64,
    timestamp_ns: u64,
    db: MemDatabase,
}

/// Maximum number of retained time-travel snapshots per connection.
const MAX_TIME_TRAVEL_SNAPSHOTS: usize = 256;

const PAGER_PUBLICATION_MODE: &str = "seqlock_published_pages";
const SYNTHETIC_MEMORY_PUBLICATION_MODE: &str = "synthetic_memory_commit_clock";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PagerPublicationSource {
    PagerPlane,
    SyntheticMemory,
}

impl PagerPublicationSource {
    const fn as_str(self) -> &'static str {
        match self {
            Self::PagerPlane => PAGER_PUBLICATION_MODE,
            Self::SyntheticMemory => SYNTHETIC_MEMORY_PUBLICATION_MODE,
        }
    }
}

/// Connection-bound view of the pager publication plane.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct BoundPagerPublication {
    snapshot: PagerPublishedSnapshot,
    read_retry_count: u64,
    source: PagerPublicationSource,
}

/// Proof that the prepared-DML entry checks passed for this statement
/// (bd-db300.5.2.2.3).  Returned once by the schema-validation seam,
/// consumed by the autocommit-begin path.  Replaces the ad-hoc
/// `Option<BoundPagerPublication>` handoff so all DML kinds (INSERT,
/// UPDATE, DELETE) thread the publication identically.
#[derive(Debug, Clone, Copy)]
struct PreparedDmlEntryProof {
    /// Pre-bound pager publication from schema validation (if file-backed
    /// and not already in a transaction).  `None` for `:memory:` or in-txn.
    publication: Option<BoundPagerPublication>,
    /// When true, the microbatch carry already verified that an explicit
    /// transaction is active — downstream can skip `active_txn` RefCell
    /// borrows in the in-txn fast lane.
    microbatch_carry_verified_in_txn: bool,
}

// PreparedDmlEntryProof::no_publication() removed — all callers now use
// ensure_schema_unchanged_with_prebound_publication() (bd-db300.5.2.2.4 / T13).

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PreparedDmlAutocommitProfileMode {
    None,
    PreparedDirectInsert,
}

/// Result of the fused prepared-DML entry body after the route decision has
/// already been made.
///
/// `execution_ok` captures whether the DML body itself succeeded (or should be
/// treated as success for partial-progress constraint handling). Callers use
/// `resolve_succeeded` to preserve the existing rule that statement-reuse and
/// compat-profile logging only fire after autocommit resolution succeeds.
#[derive(Debug)]
struct PreparedDmlEntryExecutionOutcome {
    result: Result<usize>,
    execution_ok: bool,
    resolve_succeeded: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PreparedSchemaRefreshOutcome {
    Noop,
    Lightweight,
    FullReloadRequired,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PreparedSchemaRefreshResult {
    outcome: PreparedSchemaRefreshOutcome,
    publication: BoundPagerPublication,
}

