type PreparedDirectInsertRowScratch = SmallVec<[SqliteValue; 16]>;

// Expected-loss admission gate for monotone explicit-txn page runs. Below this
// size, per-row buffering tends to cost more than the avoided B-tree work; at
// medium+ row widths, bulk page layout wins by removing repeated split work.
const PREPARED_DIRECT_INSERT_PAGE_RUN_MIN_RECORD_BYTES: usize = 16;
const PREPARED_DIRECT_INSERT_PAGE_RUN_ARENA_MAX_RECORD_BYTES: usize = 384;

#[derive(Debug, Clone)]
enum PendingDirectInsertPageRunRecords {
    Owned(Vec<(i64, Vec<u8>)>),
    Arena {
        records: Vec<(i64, Range<usize>)>,
        record_bytes: Vec<u8>,
    },
    Repeated {
        rowids: Vec<i64>,
        record: Vec<u8>,
    },
}

impl PendingDirectInsertPageRunRecords {
    fn accepts_record(&self, record_bytes: &[u8]) -> bool {
        match self {
            Self::Owned(_) | Self::Arena { .. } => true,
            Self::Repeated { record, .. } => record.as_slice() == record_bytes,
        }
    }
}

