/// Quote a SQL identifier only when necessary (contains special chars,
/// starts with a digit, or is empty).  Matches C SQLite's behavior of
/// storing unquoted identifiers in `sqlite_master.sql`.
pub(crate) fn maybe_quote_ident(name: &str) -> String {
    let needs_quoting = name.is_empty()
        || name.as_bytes()[0].is_ascii_digit()
        || !name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_');
    if needs_quoting {
        let escaped = name.replace('"', "\"\"");
        format!("\"{escaped}\"")
    } else {
        name.to_owned()
    }
}

fn parse_create_table_for_schema_rewrite(
    original_sql: &str,
    expected_table_name: &str,
) -> Result<fsqlite_ast::CreateTableStatement> {
    let statement = parse_single_statement(original_sql).map_err(|error| {
        FrankenError::Internal(format!(
            "cannot safely rewrite CREATE TABLE for `{expected_table_name}`: {error}"
        ))
    })?;
    let Statement::CreateTable(create) = statement else {
        return Err(FrankenError::Internal(format!(
            "cannot safely rewrite `{expected_table_name}`: cached schema SQL is not CREATE TABLE"
        )));
    };
    if !create.name.name.eq_ignore_ascii_case(expected_table_name) {
        return Err(FrankenError::Internal(format!(
            "cannot safely rewrite `{expected_table_name}`: cached CREATE TABLE names `{}`",
            create.name.name
        )));
    }
    Ok(create)
}

fn create_table_columns_and_constraints_mut(
    create: &mut fsqlite_ast::CreateTableStatement,
) -> Result<(
    &mut Vec<fsqlite_ast::ColumnDef>,
    &mut Vec<fsqlite_ast::TableConstraint>,
)> {
    let CreateTableBody::Columns {
        columns,
        constraints,
    } = &mut create.body
    else {
        return Err(FrankenError::Internal(format!(
            "cannot safely rewrite CREATE TABLE AS SELECT for `{}`",
            create.name.name
        )));
    };
    Ok((columns, constraints))
}

fn visit_create_table_foreign_key_clauses_mut(
    columns: &mut [fsqlite_ast::ColumnDef],
    constraints: &mut [fsqlite_ast::TableConstraint],
    mut visit: impl FnMut(&mut fsqlite_ast::ForeignKeyClause),
) {
    for column in columns {
        for constraint in &mut column.constraints {
            if let ColumnConstraintKind::ForeignKey(clause) = &mut constraint.kind {
                visit(clause);
            }
        }
    }
    for constraint in constraints {
        if let TableConstraintKind::ForeignKey { clause, .. } = &mut constraint.kind {
            visit(clause);
        }
    }
}

fn rename_identifier_if_matches(value: &mut String, old: &str, new: &str) -> bool {
    if !value.eq_ignore_ascii_case(old) {
        return false;
    }
    value.clear();
    value.push_str(new);
    true
}

fn rename_indexed_column_identifier(
    indexed: &mut fsqlite_ast::IndexedColumn,
    old: &str,
    new: &str,
) -> bool {
    fn rename_indexed_expr(expr: &mut Expr, old: &str, new: &str) -> bool {
        match expr {
            // SQLite's indexed-column grammar historically treats a
            // single-quoted token as a column identifier. Preserve that
            // interpretation while rewriting table constraints, including
            // when the token is wrapped in one or more COLLATE nodes.
            Expr::Literal(Literal::String(name), _) => rename_identifier_if_matches(name, old, new),
            Expr::Collate { expr, .. } => rename_indexed_expr(expr, old, new),
            _ => rename_column_refs_in_expr(expr, old, new),
        }
    }

    rename_indexed_expr(&mut indexed.expr, old, new)
}

/// Map a VDBE halt (`ExecOutcome::Error`) to a specific `FrankenError` variant
/// for C-SQLite error parity. A CHECK-constraint halt (stock SQLite returns
/// `SQLITE_CONSTRAINT_CHECK`, not a generic error) becomes `CheckViolation`,
/// whose `Display` reproduces the same `CHECK constraint failed: <name>` text;
/// other halts fall back to `Internal`.
fn frankenerror_from_vdbe_halt(code: i32, message: String) -> FrankenError {
    if let Some(name) = message.strip_prefix("CHECK constraint failed: ") {
        return FrankenError::CheckViolation {
            name: name.to_owned(),
        };
    }
    if message == "CHECK constraint failed" {
        return FrankenError::CheckViolation {
            name: String::new(),
        };
    }
    FrankenError::Internal(format!("VDBE halted with code {code}: {message}"))
}

/// Strip leading whitespace and SQL comments (`-- ...` line comments and
/// `/* ... */` block comments) so a captured verbatim statement text begins
/// at its first real token, the way stock sqlite3 stores CREATE text in
/// sqlite_master. A leading comment persisted into the schema makes
/// canonical SQLite fail the whole schema load with
/// "malformed database schema (<name>)" (bd-lgolw).
fn strip_leading_sql_comments(mut text: &str) -> &str {
    loop {
        let trimmed = text.trim_start();
        if let Some(rest) = trimmed.strip_prefix("--") {
            match rest.find('\n') {
                Some(idx) => text = &rest[idx + 1..],
                None => return "",
            }
        } else if let Some(rest) = trimmed.strip_prefix("/*") {
            match rest.find("*/") {
                Some(idx) => text = &rest[idx + 2..],
                None => return "",
            }
        } else {
            return trimmed;
        }
    }
}

/// Byte offset just past the last real SQL token in `text`, skipping trailing
/// whitespace and comments. A single forward scan tracks string literals
/// (`'...'`), quoted identifiers (`"..."`, `` `...` ``, `[...]`), `-- ...`
/// line comments, and `/* ... */` block comments, so a `--` inside a literal
/// never truncates the statement (bd-lgolw tail parity: stock sqlite3 stores
/// CREATE text up to its last token, excluding the terminator and any
/// trailing comment).
fn sql_text_end_before_trailing_comments(text: &str) -> usize {
    let bytes = text.as_bytes();
    let mut i = 0;
    let mut last_token_end = 0;
    while i < bytes.len() {
        match bytes[i] {
            quote @ (b'\'' | b'"' | b'`') => {
                i += 1;
                while i < bytes.len() {
                    if bytes[i] == quote {
                        if bytes.get(i + 1) == Some(&quote) {
                            i += 2;
                            continue;
                        }
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                last_token_end = i;
            }
            b'[' => {
                i += 1;
                while i < bytes.len() && bytes[i] != b']' {
                    i += 1;
                }
                i = (i + 1).min(bytes.len());
                last_token_end = i;
            }
            b'-' if bytes.get(i + 1) == Some(&b'-') => {
                while i < bytes.len() && bytes[i] != b'\n' {
                    i += 1;
                }
            }
            b'/' if bytes.get(i + 1) == Some(&b'*') => {
                i += 2;
                while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') {
                    i += 1;
                }
                i = (i + 2).min(bytes.len());
            }
            c if c.is_ascii_whitespace() => {
                i += 1;
            }
            _ => {
                i += 1;
                last_token_end = i;
            }
        }
    }
    last_token_end
}

/// Strip trailing whitespace, comments, and the statement terminator from a
/// captured verbatim CREATE, mirroring stock sqlite3's sqlite_master text
/// (which ends at the statement's final token). Alternating comment/`;`
/// strips handle tails like `); -- done` and `) /* x */ ;`.
fn strip_trailing_sql_comments_and_terminator(text: &str) -> &str {
    let mut text = &text[..sql_text_end_before_trailing_comments(text)];
    while let Some(without_semi) = text.trim_end().strip_suffix(';') {
        text = &without_semi[..sql_text_end_before_trailing_comments(without_semi)];
    }
    text
}

/// bd-67tdh Phase 2: stock sqlite3 3.46.1 (oracle) implements ALTER TABLE ADD
/// COLUMN by splicing the new column definition into the *original* CREATE text
/// verbatim -- immediately after the last column definition and before any
/// table-level constraint -- rather than re-serializing the parsed schema. This
/// keeps a verbatim-stored CREATE (see `Connection::pending_ddl_source`)
/// byte-faithful to sqlite3's `.schema` across ADD COLUMN, matching what stock
/// SQLite reads back from the same file. Returns `None` when the column-list
/// structure cannot be located, so the caller falls back to AST re-serialization.
fn splice_added_column_into_create_sql(original_sql: &str, new_column_sql: &str) -> Option<String> {
    let bytes = original_sql.as_bytes();

    // Advance past a string literal or quoted identifier starting at `i`,
    // honouring doubled-quote escapes; returns the index just past the close.
    let skip_quoted = |bytes: &[u8], mut i: usize| -> usize {
        let quote = bytes[i];
        i += 1;
        while i < bytes.len() {
            if bytes[i] == quote {
                if i + 1 < bytes.len() && bytes[i + 1] == quote {
                    i += 2;
                    continue;
                }
                return i + 1;
            }
            i += 1;
        }
        i
    };

    // Find the column-list opening paren (first top-level '(').
    // bd-lgolw: comments and `[...]` identifiers must be skipped like quoted
    // spans — a paren/comma inside `-- ...`, `/* ... */`, or brackets is
    // content, not structure; counting it corrupts the splice point on
    // multi-line comment-bearing CREATEs.
    let mut i = 0usize;
    let open = loop {
        if i >= bytes.len() {
            return None;
        }
        match bytes[i] {
            b'\'' | b'"' | b'`' => i = skip_quoted(bytes, i),
            b'[' => {
                while i < bytes.len() && bytes[i] != b']' {
                    i += 1;
                }
                i = (i + 1).min(bytes.len());
            }
            b'-' if bytes.get(i + 1) == Some(&b'-') => {
                while i < bytes.len() && bytes[i] != b'\n' {
                    i += 1;
                }
            }
            b'/' if bytes.get(i + 1) == Some(&b'*') => {
                i += 2;
                while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') {
                    i += 1;
                }
                i = (i + 2).min(bytes.len());
            }
            b'(' => break i,
            _ => i += 1,
        }
    };

    // A top-level list item is a table constraint (rather than a column def)
    // when its first keyword is one of these; columns start with an identifier.
    let is_table_constraint = |start: usize, end: usize| -> bool {
        let item = original_sql[start..end].trim_start();
        let keyword_end = item
            .find(|c: char| !c.is_ascii_alphabetic())
            .unwrap_or(item.len());
        matches!(
            item[..keyword_end].to_ascii_uppercase().as_str(),
            "CONSTRAINT" | "PRIMARY" | "UNIQUE" | "CHECK" | "FOREIGN"
        )
    };

    let mut depth = 1usize;
    let mut item_start = open + 1;
    let mut last_column_end: Option<usize> = None;
    let mut j = open + 1;
    while j < bytes.len() {
        match bytes[j] {
            b'\'' | b'"' | b'`' => {
                j = skip_quoted(bytes, j);
                continue;
            }
            b'[' => {
                while j < bytes.len() && bytes[j] != b']' {
                    j += 1;
                }
                j = (j + 1).min(bytes.len());
                continue;
            }
            b'-' if bytes.get(j + 1) == Some(&b'-') => {
                while j < bytes.len() && bytes[j] != b'\n' {
                    j += 1;
                }
                continue;
            }
            b'/' if bytes.get(j + 1) == Some(&b'*') => {
                j += 2;
                while j + 1 < bytes.len() && !(bytes[j] == b'*' && bytes[j + 1] == b'/') {
                    j += 1;
                }
                j = (j + 2).min(bytes.len());
                continue;
            }
            b'(' => depth += 1,
            b')' => {
                depth -= 1;
                if depth == 0 {
                    if !is_table_constraint(item_start, j) {
                        last_column_end = Some(j);
                    }
                    break;
                }
            }
            b',' if depth == 1 => {
                if !is_table_constraint(item_start, j) {
                    last_column_end = Some(j);
                }
                item_start = j + 1;
            }
            _ => {}
        }
        j += 1;
    }

    let insert_at = last_column_end?;
    let mut out = String::with_capacity(original_sql.len() + new_column_sql.len() + 2);
    out.push_str(&original_sql[..insert_at]);
    out.push_str(", ");
    out.push_str(new_column_sql);
    out.push_str(&original_sql[insert_at..]);
    Some(out)
}

#[cfg(test)]
mod splice_added_column_tests {
    use super::splice_added_column_into_create_sql;

    #[test]
    fn test_splice_ignores_close_paren_inside_line_comment() {
        // bd-lgolw: a ')' inside `-- pk)` must not terminate the column-list
        // scan — the new column belongs before the REAL closing paren, never
        // inside the comment line.
        let original = "CREATE TABLE t (\n    id INTEGER PRIMARY KEY, -- pk)\n    note TEXT\n)";
        let spliced = splice_added_column_into_create_sql(original, "extra INTEGER")
            .expect("comment-bearing CREATE must still splice");
        assert_eq!(
            spliced,
            "CREATE TABLE t (\n    id INTEGER PRIMARY KEY, -- pk)\n    note TEXT\n, extra INTEGER)",
        );
    }

    #[test]
    fn test_splice_ignores_unbalanced_open_paren_inside_comment() {
        // An unbalanced '(' in a comment must not inflate depth: the real ')'
        // still ends the list and the splice lands before it.
        let original =
            "CREATE TABLE t (\n    id INTEGER PRIMARY KEY, -- (see docs\n    note TEXT\n)";
        let spliced = splice_added_column_into_create_sql(original, "extra INTEGER")
            .expect("unbalanced comment paren must not break the splice");
        assert_eq!(
            spliced,
            "CREATE TABLE t (\n    id INTEGER PRIMARY KEY, -- (see docs\n    note TEXT\n, extra INTEGER)",
        );
    }

    #[test]
    fn test_splice_ignores_block_comment_and_bracket_identifier() {
        let original = "CREATE TABLE t (\n    [weird(col] TEXT /* opener ( */,\n    note TEXT\n)";
        let spliced = splice_added_column_into_create_sql(original, "extra INTEGER")
            .expect("bracket identifiers and block comments must be skipped");
        assert_eq!(
            spliced,
            "CREATE TABLE t (\n    [weird(col] TEXT /* opener ( */,\n    note TEXT\n, extra INTEGER)",
        );
    }

    #[test]
    fn test_splice_comment_free_input_is_unchanged_behavior() {
        // The comment/bracket arms must be inert on comment-free inputs.
        let original = "CREATE TABLE t (id INTEGER PRIMARY KEY, note TEXT)";
        let spliced = splice_added_column_into_create_sql(original, "extra INTEGER")
            .expect("plain CREATE must splice");
        assert_eq!(
            spliced,
            "CREATE TABLE t (id INTEGER PRIMARY KEY, note TEXT, extra INTEGER)",
        );
    }
}

fn rewrite_create_table_sql_for_alter(
    original_sql: &str,
    expected_table_name: &str,
    action: &AlterTableAction,
) -> Result<String> {
    let mut create = parse_create_table_for_schema_rewrite(original_sql, expected_table_name)?;
    let self_table_name = create.name.name.clone();

    match action {
        AlterTableAction::RenameTo(new_name) => {
            let (columns, constraints) = create_table_columns_and_constraints_mut(&mut create)?;
            visit_create_table_foreign_key_clauses_mut(columns, constraints, |clause| {
                let _ =
                    rename_identifier_if_matches(&mut clause.table, expected_table_name, new_name);
            });
            create.name.name.clone_from(new_name);
        }
        AlterTableAction::RenameColumn { old, new } => {
            let (columns, constraints) = create_table_columns_and_constraints_mut(&mut create)?;
            let Some(column) = columns
                .iter_mut()
                .find(|column| column.name.eq_ignore_ascii_case(old))
            else {
                return Err(FrankenError::Internal(format!(
                    "cannot safely rewrite `{expected_table_name}`: no such column `{old}`"
                )));
            };
            column.name.clone_from(new);

            for column in columns {
                for constraint in &mut column.constraints {
                    match &mut constraint.kind {
                        ColumnConstraintKind::Check(expr)
                        | ColumnConstraintKind::Generated { expr, .. } => {
                            let _ = rename_column_refs_in_expr(expr, old, new);
                        }
                        ColumnConstraintKind::ForeignKey(clause)
                            if clause.table.eq_ignore_ascii_case(&self_table_name) =>
                        {
                            for parent_column in &mut clause.columns {
                                let _ = rename_identifier_if_matches(parent_column, old, new);
                            }
                        }
                        _ => {}
                    }
                }
            }
            for constraint in constraints {
                match &mut constraint.kind {
                    TableConstraintKind::PrimaryKey { columns, .. }
                    | TableConstraintKind::Unique { columns, .. } => {
                        for indexed in columns {
                            let _ = rename_indexed_column_identifier(indexed, old, new);
                        }
                    }
                    TableConstraintKind::Check(expr) => {
                        let _ = rename_column_refs_in_expr(expr, old, new);
                    }
                    TableConstraintKind::ForeignKey { columns, clause } => {
                        for child_column in columns {
                            let _ = rename_identifier_if_matches(child_column, old, new);
                        }
                        if clause.table.eq_ignore_ascii_case(&self_table_name) {
                            for parent_column in &mut clause.columns {
                                let _ = rename_identifier_if_matches(parent_column, old, new);
                            }
                        }
                    }
                }
            }
        }
        AlterTableAction::AddColumn(column) => {
            // Match stock sqlite3: splice the new column into the original CREATE
            // text verbatim (after the last column, before any table constraint)
            // so a verbatim-stored CREATE stays byte-faithful to `.schema` across
            // ADD COLUMN. Fall back to AST re-serialization when the column-list
            // structure cannot be located.
            if let Some(spliced) =
                splice_added_column_into_create_sql(original_sql, &column.to_string())
            {
                return Ok(spliced);
            }
            let (columns, _) = create_table_columns_and_constraints_mut(&mut create)?;
            columns.push(column.clone());
        }
        AlterTableAction::DropColumn(column_name) => {
            let (columns, _) = create_table_columns_and_constraints_mut(&mut create)?;
            let Some(column_index) = columns
                .iter()
                .position(|column| column.name.eq_ignore_ascii_case(column_name))
            else {
                return Err(FrankenError::Internal(format!(
                    "cannot safely rewrite `{expected_table_name}`: no such column `{column_name}`"
                )));
            };
            columns.remove(column_index);
        }
    }

    // SQLite's ALTER rewrite emits the table name immediately followed by the
    // opening parenthesis. The general AST formatter uses a readability space;
    // normalize that one known formatter boundary for sqlite_schema parity.
    Ok(create.to_string().replacen(" (", "(", 1))
}

fn rewrite_create_table_foreign_key_parent_sql(
    original_sql: &str,
    expected_table_name: &str,
    parent_table: &str,
    renamed_parent_table: Option<&str>,
    renamed_parent_column: Option<(&str, &str)>,
) -> Result<String> {
    let mut create = parse_create_table_for_schema_rewrite(original_sql, expected_table_name)?;
    let (columns, constraints) = create_table_columns_and_constraints_mut(&mut create)?;
    visit_create_table_foreign_key_clauses_mut(columns, constraints, |clause| {
        if !clause.table.eq_ignore_ascii_case(parent_table) {
            return;
        }
        if let Some((old, new)) = renamed_parent_column {
            for parent_column in &mut clause.columns {
                let _ = rename_identifier_if_matches(parent_column, old, new);
            }
        }
        if let Some(new_parent_table) = renamed_parent_table {
            clause.table.clear();
            clause.table.push_str(new_parent_table);
        }
    });
    Ok(create.to_string().replacen(" (", "(", 1))
}

fn render_create_table_sql<F>(
    table: &TableSchema,
    is_autoincrement: bool,
    is_implicit_autoindex: F,
) -> String
where
    F: Fn(&IndexSchema) -> bool,
{
    let is_single_column_primary_key = |column_name: &str| {
        table
            .primary_key_constraints
            .iter()
            .any(|pk| pk.len() == 1 && pk[0].eq_ignore_ascii_case(column_name))
    };
    let primary_key_matches_index = |index: &IndexSchema| {
        table.primary_key_constraints.iter().any(|pk| {
            pk.len() == index.columns.len()
                && pk
                    .iter()
                    .zip(&index.columns)
                    .all(|(lhs, rhs)| lhs.eq_ignore_ascii_case(rhs))
        })
    };
    let mut defs: Vec<String> = table
        .columns
        .iter()
        .map(|col| {
            let mut part = maybe_quote_ident(&col.name);
            if let Some(type_decl) = col.type_name.as_deref() {
                part.push(' ');
                part.push_str(type_decl);
            }
            if col.is_ipk {
                part.push_str(" PRIMARY KEY");
                if is_autoincrement {
                    part.push_str(" AUTOINCREMENT");
                }
            }
            if col.notnull && !col.is_ipk {
                part.push_str(" NOT NULL");
            }
            if col.unique && !col.is_ipk && !is_single_column_primary_key(&col.name) {
                part.push_str(" UNIQUE");
            }
            if let Some(ref default) = col.default_value {
                part.push_str(" DEFAULT ");
                part.push_str(default);
            }
            if let Some(ref collation) = col.collation {
                part.push_str(" COLLATE ");
                part.push_str(collation);
            }
            if let Some(ref gen_expr) = col.generated_expr {
                part.push_str(" GENERATED ALWAYS AS (");
                part.push_str(gen_expr);
                part.push(')');
                if col.generated_stored == Some(true) {
                    part.push_str(" STORED");
                } else {
                    part.push_str(" VIRTUAL");
                }
            }
            for check in table.check_constraints.iter().filter(|check| {
                check
                    .owner_column
                    .as_deref()
                    .is_some_and(|owner| owner.eq_ignore_ascii_case(&col.name))
            }) {
                part.push_str(" CHECK(");
                part.push_str(&check.expr);
                part.push(')');
            }
            for fk in table.foreign_keys.iter().filter(|fk| {
                fk.owner_column
                    .as_deref()
                    .is_some_and(|owner| owner.eq_ignore_ascii_case(&col.name))
            }) {
                append_fk_reference_clause_sql(&mut part, fk);
            }
            part
        })
        .collect();

    // Append table-level UNIQUE constraints for multi-column implicit indexes
    // so the rendered SQL round-trips correctly through sqlite_master.
    for index in &table.indexes {
        if !index.is_unique || index.columns.is_empty() {
            continue;
        }
        if primary_key_matches_index(index) {
            continue;
        }
        if !is_implicit_autoindex(index) {
            continue;
        }
        // Single-column UNIQUE constraints are already rendered inline above.
        if index.columns.len() == 1
            && table.columns.iter().any(|column| {
                column.unique
                    && !column.is_ipk
                    && column.name.eq_ignore_ascii_case(&index.columns[0])
            })
        {
            continue;
        }
        let cols = index
            .columns
            .iter()
            .map(|name| maybe_quote_ident(name))
            .collect::<Vec<_>>()
            .join(", ");
        defs.push(format!("UNIQUE ({cols})"));
    }
    for pk in &table.primary_key_constraints {
        if pk.len() == 1
            && table
                .columns
                .iter()
                .any(|column| column.is_ipk && column.name.eq_ignore_ascii_case(&pk[0]))
        {
            continue;
        }
        let cols = pk
            .iter()
            .map(|name| maybe_quote_ident(name))
            .collect::<Vec<_>>()
            .join(", ");
        defs.push(format!("PRIMARY KEY ({cols})"));
    }

    let column_defs = defs.join(", ");
    // Append table-level FOREIGN KEY constraints so they survive
    // round-tripping through sqlite_master.
    let mut fk_clauses = String::new();
    for fk in table
        .foreign_keys
        .iter()
        .filter(|fk| fk.owner_column.is_none())
    {
        use std::fmt::Write;
        let child_cols: Vec<&str> = fk
            .child_columns
            .iter()
            .filter_map(|&idx| table.columns.get(idx).map(|c| c.name.as_str()))
            .collect();
        if child_cols.is_empty() {
            continue;
        }
        write!(
            fk_clauses,
            ", FOREIGN KEY({})",
            child_cols
                .iter()
                .map(|c| maybe_quote_ident(c))
                .collect::<Vec<_>>()
                .join(", "),
        )
        .ok();
        append_fk_reference_clause_sql(&mut fk_clauses, fk);
    }
    // Append table-level CHECK constraints.
    let mut check_clauses = String::new();
    for check in table
        .check_constraints
        .iter()
        .filter(|check| check.owner_column.is_none())
    {
        use std::fmt::Write;
        write!(check_clauses, ", CHECK({})", check.expr).ok();
    }
    let mut table_options = Vec::new();
    if table.without_rowid {
        table_options.push("WITHOUT ROWID");
    }
    if table.strict {
        table_options.push("STRICT");
    }
    let table_options_suffix = if table_options.is_empty() {
        String::new()
    } else {
        format!(" {}", table_options.join(", "))
    };
    format!(
        "CREATE TABLE {}({column_defs}{fk_clauses}{check_clauses}){table_options_suffix}",
        maybe_quote_ident(&table.name)
    )
}

fn fk_action_sql(action: FkActionType) -> &'static str {
    match action {
        FkActionType::NoAction => "NO ACTION",
        FkActionType::Restrict => "RESTRICT",
        FkActionType::SetNull => "SET NULL",
        FkActionType::SetDefault => "SET DEFAULT",
        FkActionType::Cascade => "CASCADE",
    }
}

fn append_fk_reference_clause_sql(sql: &mut String, fk: &FkDef) {
    use std::fmt::Write;

    write!(sql, " REFERENCES {}", maybe_quote_ident(&fk.parent_table)).ok();
    if !fk.parent_columns.is_empty() {
        write!(
            sql,
            "({})",
            fk.parent_columns
                .iter()
                .map(|column| maybe_quote_ident(column))
                .collect::<Vec<_>>()
                .join(", ")
        )
        .ok();
    }
    if fk.on_delete != FkActionType::NoAction {
        write!(sql, " ON DELETE {}", fk_action_sql(fk.on_delete)).ok();
    }
    if fk.on_update != FkActionType::NoAction {
        write!(sql, " ON UPDATE {}", fk_action_sql(fk.on_update)).ok();
    }
    if fk.deferred {
        sql.push_str(" DEFERRABLE INITIALLY DEFERRED");
    }
}

fn render_create_index_sql(index: &IndexSchema, table_name: &str) -> String {
    let unique = if index.is_unique { "UNIQUE " } else { "" };
    let cols = render_create_index_terms_sql(index);
    let where_clause = index
        .where_clause
        .as_ref()
        .map(|predicate| format!(" WHERE {predicate}"))
        .unwrap_or_default();
    format!(
        "CREATE {unique}INDEX {} ON {}({}){where_clause}",
        quote_identifier(&index.name),
        quote_identifier(table_name),
        cols
    )
}

fn render_create_index_terms_sql(index: &IndexSchema) -> String {
    let term_count = index.key_term_count();
    (0..term_count)
        .filter_map(|i| {
            let mut term = if index.key_expressions.is_empty() {
                quote_identifier(index.columns.get(i)?)
            } else {
                index.key_expressions.get(i)?.clone()
            };
            let expression_declares_collation =
                !index.key_expressions.is_empty() && term_has_unquoted_collation_keyword(&term);
            if !expression_declares_collation
                && let Some(collation) = index.key_collations.get(i).and_then(|c| c.as_deref())
            {
                term.push_str(" COLLATE ");
                term.push_str(&quote_identifier(collation));
            }
            match index.key_sort_directions.get(i).copied() {
                Some(SortDirection::Asc) => term.push_str(" ASC"),
                Some(SortDirection::Desc) => term.push_str(" DESC"),
                None => {}
            }
            Some(term)
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn term_has_unquoted_collation_keyword(term: &str) -> bool {
    collect_unquoted_sql_tokens(term)
        .into_iter()
        .any(|token| token.eq_ignore_ascii_case("COLLATE"))
}

fn collect_unquoted_sql_tokens(input: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut current = String::new();
    let mut chars = input.chars().peekable();
    while let Some(ch) = chars.next() {
        match ch {
            '\'' | '"' | '`' => {
                push_sql_token(&mut tokens, &mut current);
                skip_quoted_sql_chars(&mut chars, ch);
            }
            '[' => {
                push_sql_token(&mut tokens, &mut current);
                skip_bracket_sql_identifier_chars(&mut chars);
            }
            '-' if chars.peek().is_some_and(|next| *next == '-') => {
                let _ = chars.next();
                push_sql_token(&mut tokens, &mut current);
                skip_line_sql_comment_chars(&mut chars);
            }
            '/' if chars.peek().is_some_and(|next| *next == '*') => {
                let _ = chars.next();
                push_sql_token(&mut tokens, &mut current);
                skip_block_sql_comment_chars(&mut chars);
            }
            _ if ch.is_ascii_alphanumeric() || ch == '_' => current.push(ch),
            _ => push_sql_token(&mut tokens, &mut current),
        }
    }
    push_sql_token(&mut tokens, &mut current);
    tokens
}

fn push_sql_token(tokens: &mut Vec<String>, current: &mut String) {
    if current.is_empty() {
        return;
    }
    tokens.push(std::mem::take(current));
}

fn skip_quoted_sql_chars(chars: &mut std::iter::Peekable<std::str::Chars<'_>>, quote: char) {
    while let Some(ch) = chars.next() {
        if ch == quote {
            if chars.peek().is_some_and(|next| *next == quote) {
                let _ = chars.next();
            } else {
                break;
            }
        }
    }
}

fn skip_bracket_sql_identifier_chars(chars: &mut std::iter::Peekable<std::str::Chars<'_>>) {
    while let Some(ch) = chars.next() {
        if ch == ']' {
            if chars.peek().is_some_and(|next| *next == ']') {
                let _ = chars.next();
            } else {
                break;
            }
        }
    }
}

fn skip_line_sql_comment_chars(chars: &mut std::iter::Peekable<std::str::Chars<'_>>) {
    for ch in chars.by_ref() {
        if ch == '\n' || ch == '\r' {
            break;
        }
    }
}

fn skip_block_sql_comment_chars(chars: &mut std::iter::Peekable<std::str::Chars<'_>>) {
    let mut previous = '\0';
    for ch in chars.by_ref() {
        if previous == '*' && ch == '/' {
            break;
        }
        previous = ch;
    }
}

/// Check whether a `SelectCore` references a named table/CTE in any FROM source.
fn select_core_references_table(core: &SelectCore, table_name: &str) -> bool {
    match core {
        SelectCore::Select {
            from: Some(from), ..
        } => from_clause_references_table(from, table_name),
        SelectCore::Select { from: None, .. } | SelectCore::Values(_) => false,
    }
}

fn from_clause_references_table(from: &fsqlite_ast::FromClause, table_name: &str) -> bool {
    table_or_subquery_references_table(&from.source, table_name)
        || from
            .joins
            .iter()
            .any(|join| table_or_subquery_references_table(&join.table, table_name))
}

fn table_or_subquery_references_table(table: &TableOrSubquery, table_name: &str) -> bool {
    match table {
        TableOrSubquery::Table { name, .. } => {
            name.schema.is_none() && name.name.eq_ignore_ascii_case(table_name)
        }
        TableOrSubquery::Subquery { query, .. } => select_references_table(query, table_name),
        TableOrSubquery::ParenJoin(from) => from_clause_references_table(from, table_name),
        TableOrSubquery::TableFunction { .. } => false,
    }
}

fn select_references_table(select: &SelectStatement, table_name: &str) -> bool {
    select_core_references_table(&select.body.select, table_name)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_references_table(core, table_name))
}

/// Recursively resolve column names for a subquery that uses `SELECT *`.
/// Walks through nested subqueries and schema tables to find the actual
/// column names that will appear in the result set.
#[allow(dead_code)] // superseded by Connection::select_result_column_names; kept for fallback
fn resolve_subquery_star_columns(select: &SelectStatement, schema: &[TableSchema]) -> Vec<String> {
    let basic = infer_select_column_names(select);
    if !basic.iter().any(|n| n == "*" || n.ends_with(".*")) {
        return basic;
    }
    // Has unresolved stars — try to expand from FROM sources.
    let core = &select.body.select;
    if let SelectCore::Select {
        from: Some(from), ..
    } = core
    {
        let mut result = Vec::new();
        for name in &basic {
            if name == "*" {
                let expanded = expand_from_clause_column_names(from, schema);
                if !expanded.is_empty() {
                    result.extend(expanded);
                } else {
                    result.push(name.clone());
                }
            } else if let Some(prefix) = name.strip_suffix(".*") {
                if let Some(expanded) = expand_named_source_column_names(from, prefix, schema) {
                    result.extend(expanded);
                } else {
                    result.push(name.clone());
                }
            } else {
                result.push(name.clone());
            }
        }
        if !result.is_empty() && !result.iter().any(|n| n == "*" || n.ends_with(".*")) {
            return result;
        }
    }
    basic
}

fn compound_op_error_name(op: CompoundOp) -> &'static str {
    match op {
        CompoundOp::Union | CompoundOp::UnionAll => "UNION",
        CompoundOp::Intersect => "INTERSECT",
        CompoundOp::Except => "EXCEPT",
    }
}

/// Infer column names from a SELECT statement's result columns.
fn infer_select_column_names(select: &SelectStatement) -> Vec<String> {
    let core = &select.body.select;
    match core {
        SelectCore::Select { columns, .. } => columns
            .iter()
            .enumerate()
            .map(|(i, col)| match col {
                ResultColumn::Expr {
                    alias: Some(alias), ..
                } => alias.clone(),
                ResultColumn::Expr { expr, .. } => match expr {
                    Expr::Column(col_ref, _) => col_ref.column.to_string(),
                    _ => format!("_c{i}"),
                },
                ResultColumn::Star => "*".to_owned(),
                ResultColumn::TableStar(name) => format!("{name}.*"),
            })
            .collect(),
        SelectCore::Values(rows) => {
            // SQLite names VALUES columns as "column1", "column2", etc.
            let width = rows.first().map_or(0, Vec::len);
            (0..width).map(|i| format!("column{}", i + 1)).collect()
        }
    }
}

#[allow(dead_code)] // superseded by Connection::select_result_column_names
fn expand_from_clause_column_names(from: &FromClause, schema: &[TableSchema]) -> Vec<String> {
    let mut names = expand_table_or_subquery_column_names(&from.source, schema);
    for join in &from.joins {
        let right_names = expand_table_or_subquery_column_names(&join.table, schema);
        let using_cols = if join.join_type.natural {
            right_names
                .iter()
                .filter(|right_name| {
                    names
                        .iter()
                        .any(|left_name| left_name.eq_ignore_ascii_case(right_name))
                })
                .cloned()
                .collect::<Vec<_>>()
        } else if let Some(JoinConstraint::Using(cols)) = join.constraint.as_ref() {
            cols.clone()
        } else {
            Vec::new()
        };
        names.extend(right_names.into_iter().filter(|right_name| {
            !using_cols
                .iter()
                .any(|using_col| using_col.eq_ignore_ascii_case(right_name))
        }));
    }
    names
}

#[allow(dead_code)] // superseded by Connection::select_result_column_names
fn expand_named_source_column_names(
    from: &FromClause,
    source_name: &str,
    schema: &[TableSchema],
) -> Option<Vec<String>> {
    let source_name = source_name.split_once('.').map_or_else(
        || QualifiedName::bare(source_name),
        |(schema_name, table_name)| QualifiedName::qualified(schema_name, table_name),
    );
    std::iter::once(&from.source)
        .chain(from.joins.iter().map(|join| &join.table))
        .find(|source| source_matches_name(source, &source_name))
        .map(|source| expand_table_or_subquery_column_names(source, schema))
}

#[allow(dead_code)] // superseded by Connection::select_result_column_names
fn expand_table_or_subquery_column_names(
    source: &TableOrSubquery,
    schema: &[TableSchema],
) -> Vec<String> {
    match source {
        TableOrSubquery::Table { name, .. } => schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(&name.name))
            .map(|table| {
                table
                    .columns
                    .iter()
                    .map(|column| column.name.clone())
                    .collect()
            })
            .unwrap_or_default(),
        TableOrSubquery::Subquery { query, .. } => resolve_subquery_star_columns(query, schema),
        TableOrSubquery::TableFunction { name, .. } => table_function_column_names(name)
            .map(|cols| cols.iter().map(|col| (*col).to_owned()).collect())
            .unwrap_or_default(),
        TableOrSubquery::ParenJoin(from) => expand_from_clause_column_names(from, schema),
    }
}

fn qualified_name_matches_table_binding(
    target: &QualifiedName,
    name: &QualifiedName,
    alias: Option<&str>,
) -> bool {
    if let Some(alias) = alias {
        return target.schema.is_none() && alias.eq_ignore_ascii_case(&target.name);
    }
    normalized_attached_schema_name(target.schema.as_deref())
        == normalized_attached_schema_name(name.schema.as_deref())
        && name.name.eq_ignore_ascii_case(&target.name)
}

fn normalized_attached_schema_name(schema: Option<&str>) -> Option<&str> {
    match schema {
        Some(name) if name.eq_ignore_ascii_case("main") => None,
        other => other,
    }
}

fn source_projection_label(source: &TableOrSubquery) -> Option<String> {
    match source {
        TableOrSubquery::Table { name, alias, .. } => {
            Some(alias.clone().unwrap_or_else(|| name.name.clone()))
        }
        TableOrSubquery::Subquery { alias, .. } => alias.clone(),
        TableOrSubquery::TableFunction { name, alias, .. } => {
            Some(alias.clone().unwrap_or_else(|| name.clone()))
        }
        TableOrSubquery::ParenJoin(_) => None,
    }
}

fn source_matches_name(source: &TableOrSubquery, target: &QualifiedName) -> bool {
    match source {
        TableOrSubquery::Table { name, alias, .. } => {
            qualified_name_matches_table_binding(target, name, alias.as_deref())
        }
        TableOrSubquery::Subquery { alias, .. } => {
            target.schema.is_none()
                && alias
                    .as_ref()
                    .is_some_and(|alias| alias.eq_ignore_ascii_case(&target.name))
        }
        TableOrSubquery::TableFunction { name, alias, .. } => {
            target.schema.is_none()
                && alias.as_deref().map_or_else(
                    || name.eq_ignore_ascii_case(&target.name),
                    |alias| alias.eq_ignore_ascii_case(&target.name),
                )
        }
        TableOrSubquery::ParenJoin(_) => false,
    }
}

// ---------------------------------------------------------------------------
// Subquery rewriting helpers (IN, EXISTS, scalar subqueries)
// ---------------------------------------------------------------------------

/// Walk a `SelectCore` and rewrite subquery expressions found in its
/// result columns, WHERE clause, or HAVING clause.
///
/// When `rewrite_in` is true, also eagerly evaluate `IN (SELECT ...)`
/// into literal lists (needed for interpreted fallback paths).
async fn rewrite_in_select_core(
    core: &mut SelectCore,
    conn: &Connection,
    rewrite_in: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    if let SelectCore::Select {
        columns,
        where_clause,
        group_by,
        having,
        windows,
        ..
    } = core
    {
        for col in columns.iter_mut() {
            if let ResultColumn::Expr { expr, .. } = col {
                rewrite_in_expr(expr, conn, rewrite_in, params).await?;
            }
        }
        if let Some(wh) = where_clause.as_mut() {
            rewrite_in_expr(wh, conn, rewrite_in, params).await?;
        }
        for expr in group_by.iter_mut() {
            rewrite_in_expr(expr, conn, rewrite_in, params).await?;
        }
        if let Some(hv) = having.as_mut() {
            rewrite_in_expr(hv, conn, rewrite_in, params).await?;
        }
        for window in windows.iter_mut() {
            rewrite_in_window_spec(&mut window.spec, conn, rewrite_in, params).await?;
        }
    }
    Ok(())
}

/// bd-8ewbk: rewrite a single `UPDATE ... FROM` source that is a subquery into a
/// named-table reference to a freshly-minted CTE, accumulating the CTE in `ctes`.
/// Non-subquery sources pass through unchanged.
///
/// An aliased subquery keeps its alias as the CTE name so every `alias.col`
/// reference resolves to the materialized relation by name. An unaliased
/// subquery (legal but rare, e.g. `FROM src, (SELECT 1)`) gets a synthetic,
/// collision-resistant name derived from its FROM position; its columns remain
/// reachable only unqualified, exactly as SQLite treats an unaliased FROM
/// subquery.
fn hoist_update_from_source_to_cte(
    src: &TableOrSubquery,
    position: usize,
    ctes: &mut Vec<fsqlite_ast::Cte>,
) -> TableOrSubquery {
    let TableOrSubquery::Subquery { query, alias } = src else {
        return src.clone();
    };
    let cte_name = match alias {
        Some(alias) => alias.clone(),
        None => format!("__fsqlite_update_from_subquery_{position}"),
    };
    ctes.push(fsqlite_ast::Cte {
        name: cte_name.clone(),
        columns: Vec::new(),
        materialized: None,
        query: (**query).clone(),
    });
    TableOrSubquery::Table {
        name: QualifiedName {
            schema: None,
            name: cte_name,
        },
        alias: None,
        index_hint: None,
        time_travel: None,
    }
}

/// bd-8ewbk: hoist non-flattenable `UPDATE ... FROM (subquery) AS alias` sources
/// into CTEs so the existing CTE-materialization path turns each subquery into a
/// temporary relation, after which the named-table nested-loop codegen
/// (`codegen_update_from`) drives the join. This handles subquery FROM sources
/// that `try_flatten_update_from_subquery` cannot flatten (GROUP BY, aggregates,
/// joins, column renames, DISTINCT, compounds, ...), including a subquery that is
/// one arm of a multi-source FROM.
///
/// Each subquery FROM source becomes a CTE (named after its alias, or a
/// synthetic positional name when unaliased) and the source is replaced with a
/// named-table reference to that CTE. Returns `None` when there is nothing to
/// hoist (no FROM clause, or no subquery source), leaving simple/flattened
/// shapes on their existing fast paths. The hoisted CTEs are appended after any
/// pre-existing WITH CTEs so they may reference them.
fn hoist_update_from_subqueries_to_ctes(
    update: &fsqlite_ast::UpdateStatement,
) -> Option<fsqlite_ast::UpdateStatement> {
    let from = update.from.as_ref()?;
    let leading_is_subquery = matches!(&from.source, TableOrSubquery::Subquery { .. });
    let joined_has_subquery = from
        .joins
        .iter()
        .any(|join| matches!(&join.table, TableOrSubquery::Subquery { .. }));
    if !leading_is_subquery && !joined_has_subquery {
        return None;
    }

    let mut hoisted_ctes: Vec<fsqlite_ast::Cte> = Vec::new();
    let new_source = hoist_update_from_source_to_cte(&from.source, 0, &mut hoisted_ctes);
    let mut new_joins = Vec::with_capacity(from.joins.len());
    for (position, join) in from.joins.iter().enumerate() {
        new_joins.push(JoinClause {
            join_type: join.join_type,
            table: hoist_update_from_source_to_cte(&join.table, position + 1, &mut hoisted_ctes),
            constraint: join.constraint.clone(),
        });
    }

    let mut result = update.clone();
    result.from = Some(FromClause {
        source: new_source,
        joins: new_joins,
    });
    let mut with = result.with.take().unwrap_or(fsqlite_ast::WithClause {
        recursive: false,
        ctes: Vec::new(),
    });
    with.ctes.extend(hoisted_ctes);
    result.with = Some(with);
    Some(result)
}

/// bd-kkfok: flatten a simple-projection subquery used as an `UPDATE ... FROM`
/// source into its underlying base table, so the existing named-table nested-loop
/// codegen (`codegen_update_from`) can drive it without materialization.
///
/// Only the collision-safe shape is flattened: `(SELECT <plain cols | *> FROM
/// <single base table> [WHERE ...]) AS s` with no DISTINCT / GROUP BY / HAVING /
/// window / LIMIT / compound / WITH / joins and no column renames. The subquery
/// alias is kept as the base table's alias, so every reference of the form
/// `s.col` stays qualified and resolves to the FROM source — never colliding with
/// a like-named column on the UPDATE target. Any inner WHERE is re-qualified with
/// the alias and merged (AND) into the UPDATE's WHERE. Returns `true` when a
/// flatten was applied (renamed/aggregated/filtered-with-rename/multi-table
/// sources are left untouched and rejected later by codegen with a clear error).
fn try_flatten_update_from_subquery(update: &mut fsqlite_ast::UpdateStatement) -> bool {
    let Some(from) = update.from.as_ref() else {
        return false;
    };
    if !from.joins.is_empty() {
        return false; // multi-source FROM is bd-p0xje, not this path
    }
    let TableOrSubquery::Subquery {
        query,
        alias: Some(alias),
    } = &from.source
    else {
        return false; // need a subquery source with an alias to keep refs qualified
    };
    if query.with.is_some()
        || !query.body.compounds.is_empty()
        || !query.order_by.is_empty()
        || query.limit.is_some()
    {
        return false;
    }
    let SelectCore::Select {
        distinct,
        columns,
        from: Some(inner_from),
        where_clause: inner_where,
        group_by,
        having,
        windows,
    } = &query.body.select
    else {
        return false;
    };
    if *distinct != Distinctness::All
        || !inner_from.joins.is_empty()
        || !group_by.is_empty()
        || having.is_some()
        || !windows.is_empty()
    {
        return false;
    }
    let TableOrSubquery::Table {
        name: base_name,
        index_hint,
        time_travel,
        ..
    } = &inner_from.source
    else {
        return false;
    };
    // Every projected column must be a plain column ref with no rename (exposed
    // name == base column name) or `*`. Otherwise a reference to `s.<exposed>`
    // would not exist on the base table and flattening would be unsound.
    for column in columns {
        match column {
            ResultColumn::Star => {}
            ResultColumn::Expr {
                expr: Expr::Column(col_ref, _),
                alias: col_alias,
            } => {
                let exposed = col_alias
                    .clone()
                    .unwrap_or_else(|| col_ref.column.to_string());
                if !exposed.eq_ignore_ascii_case(&col_ref.column) {
                    return false;
                }
            }
            ResultColumn::Expr { .. } | ResultColumn::TableStar(_) => return false,
        }
    }

    let base_name = base_name.clone();
    let index_hint = index_hint.clone();
    let time_travel = time_travel.clone();
    let alias_arc: Arc<str> = Arc::from(alias.as_str());
    let mut merged_inner_where = inner_where.as_deref().cloned();
    if let Some(where_expr) = merged_inner_where.as_mut() {
        qualify_column_refs_with_alias(where_expr, &alias_arc);
    }

    update.from = Some(fsqlite_ast::FromClause {
        source: TableOrSubquery::Table {
            name: base_name,
            alias: Some(alias.clone()),
            index_hint,
            time_travel,
        },
        joins: Vec::new(),
    });

    if let Some(inner_where) = merged_inner_where {
        update.where_clause = Some(match update.where_clause.take() {
            Some(outer) => Expr::BinaryOp {
                left: Box::new(outer),
                op: BinaryOp::And,
                right: Box::new(inner_where),
                span: Span::ZERO,
            },
            None => inner_where,
        });
    }
    true
}

/// Re-qualify every (non-subquery-nested) column reference in `expr` with
/// `alias`. Used when merging a flattened `UPDATE ... FROM` subquery's inner
/// WHERE into the outer WHERE: the inner predicate only references the single
/// base table, so forcing the alias qualifier makes those references resolve to
/// the FROM source (aliased as `alias`) instead of accidentally binding to a
/// like-named column on the UPDATE target. Nested subqueries are not descended
/// into — they carry their own name scope. Mirrors the variant coverage of
/// [`rename_column_refs_in_expr`].
fn qualify_column_refs_with_alias(expr: &mut Expr, alias: &Arc<str>) {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => {}
        Expr::Column(col_ref, _) => {
            col_ref.table = Some(alias.clone());
        }
        Expr::BinaryOp { left, right, .. } => {
            qualify_column_refs_with_alias(left, alias);
            qualify_column_refs_with_alias(right, alias);
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => qualify_column_refs_with_alias(expr, alias),
        Expr::Between {
            expr, low, high, ..
        } => {
            qualify_column_refs_with_alias(expr, alias);
            qualify_column_refs_with_alias(low, alias);
            qualify_column_refs_with_alias(high, alias);
        }
        Expr::In { expr, set, .. } => {
            qualify_column_refs_with_alias(expr, alias);
            if let InSet::List(values) = set {
                for value in values {
                    qualify_column_refs_with_alias(value, alias);
                }
            }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            qualify_column_refs_with_alias(expr, alias);
            qualify_column_refs_with_alias(pattern, alias);
            if let Some(escape) = escape.as_deref_mut() {
                qualify_column_refs_with_alias(escape, alias);
            }
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand.as_deref_mut() {
                qualify_column_refs_with_alias(operand, alias);
            }
            for (when, then) in whens {
                qualify_column_refs_with_alias(when, alias);
                qualify_column_refs_with_alias(then, alias);
            }
            if let Some(else_expr) = else_expr.as_deref_mut() {
                qualify_column_refs_with_alias(else_expr, alias);
            }
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            ..
        } => {
            if let FunctionArgs::List(args) = args {
                for arg in args {
                    qualify_column_refs_with_alias(arg, alias);
                }
            }
            for term in order_by {
                qualify_column_refs_with_alias(&mut term.expr, alias);
            }
            if let Some(filter) = filter.as_deref_mut() {
                qualify_column_refs_with_alias(filter, alias);
            }
        }
        Expr::JsonAccess { expr, path, .. } => {
            qualify_column_refs_with_alias(expr, alias);
            qualify_column_refs_with_alias(path, alias);
        }
        Expr::RowValue(values, _) => {
            for value in values {
                qualify_column_refs_with_alias(value, alias);
            }
        }
        // Do not descend into nested subqueries / window specs: they introduce
        // their own name scope and must not be re-qualified with this alias.
        Expr::Exists { .. } | Expr::Subquery(..) => {}
    }
}

fn flatten_simple_from_subquery_select(select: &SelectStatement) -> Option<SelectStatement> {
    if select.with.is_some() || !select.body.compounds.is_empty() {
        return None;
    }

    let SelectCore::Select {
        columns: outer_columns,
        from: Some(outer_from),
        where_clause: outer_where,
        group_by,
        having,
        windows,
        ..
    } = &select.body.select
    else {
        return None;
    };

    if !outer_from.joins.is_empty()
        || !group_by.is_empty()
        || having.is_some()
        || !windows.is_empty()
    {
        return None;
    }

    let TableOrSubquery::Subquery {
        query: inner_query,
        alias: outer_alias,
    } = &outer_from.source
    else {
        return None;
    };

    if inner_query.with.is_some()
        || !inner_query.body.compounds.is_empty()
        || !inner_query.order_by.is_empty()
        || inner_query.limit.is_some()
    {
        return None;
    }

    let SelectCore::Select {
        distinct,
        columns: inner_columns,
        from: Some(inner_from),
        where_clause: inner_where,
        group_by: inner_group_by,
        having: inner_having,
        windows: inner_windows,
    } = &inner_query.body.select
    else {
        return None;
    };

    if *distinct != Distinctness::All
        || !inner_from.joins.is_empty()
        || !matches!(inner_from.source, TableOrSubquery::Table { .. })
        || !inner_group_by.is_empty()
        || inner_having.is_some()
        || !inner_windows.is_empty()
    {
        return None;
    }

    let projection_map = build_flatten_projection_map(inner_columns)?;
    let flattened_columns = flatten_outer_result_columns(
        outer_columns,
        inner_columns,
        outer_alias.as_deref(),
        &projection_map,
    )?;
    let flattened_where = flatten_expr_option(
        outer_where.as_deref(),
        outer_alias.as_deref(),
        &projection_map,
    )?;
    let flattened_order_by =
        flatten_order_by_terms(&select.order_by, outer_alias.as_deref(), &projection_map)?;

    let mut flattened = select.clone();
    if let SelectCore::Select {
        columns,
        from,
        where_clause,
        ..
    } = &mut flattened.body.select
    {
        *columns = flattened_columns;
        *from = Some(inner_from.clone());
        *where_clause = combine_where_clauses(inner_where.clone(), flattened_where);
    }
    flattened.order_by = flattened_order_by;
    Some(flattened)
}

#[derive(Debug, Clone, Default)]
struct FlattenProjectionMap {
    passthrough_columns: bool,
    columns: HashMap<String, Expr>,
}

fn build_flatten_projection_map(columns: &[ResultColumn]) -> Option<FlattenProjectionMap> {
    let mut projection = FlattenProjectionMap::default();

    for column in columns {
        match column {
            ResultColumn::Star | ResultColumn::TableStar(_) => {
                projection.passthrough_columns = true;
            }
            ResultColumn::Expr {
                expr: Expr::Column(column_ref, span),
                alias,
            } => {
                let exposed_name = alias
                    .clone()
                    .unwrap_or_else(|| column_ref.column.to_string())
                    .to_ascii_lowercase();
                if projection.columns.contains_key(&exposed_name) {
                    return None;
                }
                projection
                    .columns
                    .insert(exposed_name, Expr::Column(column_ref.clone(), *span));
            }
            ResultColumn::Expr { .. } => return None,
        }
    }

    Some(projection)
}

fn flatten_outer_result_columns(
    outer_columns: &[ResultColumn],
    inner_columns: &[ResultColumn],
    outer_alias: Option<&str>,
    projection_map: &FlattenProjectionMap,
) -> Option<Vec<ResultColumn>> {
    let mut flattened = Vec::new();

    for column in outer_columns {
        match column {
            ResultColumn::Star => flattened.extend(inner_columns.iter().cloned()),
            ResultColumn::TableStar(qualifier) => {
                if qualifier.schema.is_some()
                    || !outer_alias.is_some_and(|alias| qualifier.name.eq_ignore_ascii_case(alias))
                {
                    return None;
                }
                flattened.extend(inner_columns.iter().cloned());
            }
            ResultColumn::Expr {
                expr: Expr::Column(column_ref, _),
                alias,
            } => {
                let rewritten_expr =
                    flatten_expr(column, outer_alias, projection_map).and_then(|rewritten| {
                        match rewritten {
                            ResultColumn::Expr { expr, .. } => Some(expr),
                            ResultColumn::Star | ResultColumn::TableStar(_) => None,
                        }
                    })?;
                flattened.push(ResultColumn::Expr {
                    expr: rewritten_expr,
                    alias: alias
                        .clone()
                        .or_else(|| Some(column_ref.column.to_string())),
                });
            }
            ResultColumn::Expr { .. } => return None,
        }
    }

    Some(flattened)
}

#[allow(clippy::option_option)]
fn flatten_expr_option(
    expr: Option<&Expr>,
    outer_alias: Option<&str>,
    projection_map: &FlattenProjectionMap,
) -> Option<Option<Box<Expr>>> {
    match expr {
        Some(inner) => flatten_expr_tree(inner, outer_alias, projection_map)
            .map(Box::new)
            .map(Some),
        None => Some(None),
    }
}

fn flatten_order_by_terms(
    order_by: &[OrderingTerm],
    outer_alias: Option<&str>,
    projection_map: &FlattenProjectionMap,
) -> Option<Vec<OrderingTerm>> {
    order_by
        .iter()
        .map(|term| {
            Some(OrderingTerm {
                expr: flatten_expr_tree(&term.expr, outer_alias, projection_map)?,
                direction: term.direction,
                nulls: term.nulls,
            })
        })
        .collect()
}

fn flatten_expr(
    column: &ResultColumn,
    outer_alias: Option<&str>,
    projection_map: &FlattenProjectionMap,
) -> Option<ResultColumn> {
    let ResultColumn::Expr { expr, alias } = column else {
        return None;
    };
    Some(ResultColumn::Expr {
        expr: flatten_expr_tree(expr, outer_alias, projection_map)?,
        alias: alias.clone(),
    })
}

fn flatten_expr_tree(
    expr: &Expr,
    outer_alias: Option<&str>,
    projection_map: &FlattenProjectionMap,
) -> Option<Expr> {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Subquery(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => Some(expr.clone()),
        Expr::Column(column_ref, span) => {
            flatten_column_ref(column_ref, *span, outer_alias, projection_map)
        }
        Expr::BinaryOp {
            left,
            op,
            right,
            span,
        } => Some(Expr::BinaryOp {
            left: Box::new(flatten_expr_tree(left, outer_alias, projection_map)?),
            op: *op,
            right: Box::new(flatten_expr_tree(right, outer_alias, projection_map)?),
            span: *span,
        }),
        Expr::UnaryOp {
            op,
            expr: inner,
            span,
        } => Some(Expr::UnaryOp {
            op: *op,
            expr: Box::new(flatten_expr_tree(inner, outer_alias, projection_map)?),
            span: *span,
        }),
        Expr::Between {
            expr: inner,
            low,
            high,
            not,
            span,
        } => Some(Expr::Between {
            expr: Box::new(flatten_expr_tree(inner, outer_alias, projection_map)?),
            low: Box::new(flatten_expr_tree(low, outer_alias, projection_map)?),
            high: Box::new(flatten_expr_tree(high, outer_alias, projection_map)?),
            not: *not,
            span: *span,
        }),
        Expr::In {
            expr: inner,
            set,
            not,
            span,
        } => {
            let rewritten_set = match set {
                InSet::List(items) => InSet::List(
                    items
                        .iter()
                        .map(|item| flatten_expr_tree(item, outer_alias, projection_map))
                        .collect::<Option<Vec<_>>>()?,
                ),
                _ => set.clone(),
            };
            Some(Expr::In {
                expr: Box::new(flatten_expr_tree(inner, outer_alias, projection_map)?),
                set: rewritten_set,
                not: *not,
                span: *span,
            })
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            op,
            not,
            span,
        } => Some(Expr::Like {
            expr: Box::new(flatten_expr_tree(inner, outer_alias, projection_map)?),
            pattern: Box::new(flatten_expr_tree(pattern, outer_alias, projection_map)?),
            escape: flatten_expr_option(escape.as_deref(), outer_alias, projection_map)?,
            op: *op,
            not: *not,
            span: *span,
        }),
        Expr::Case {
            operand,
            whens,
            else_expr,
            span,
        } => Some(Expr::Case {
            operand: flatten_expr_option(operand.as_deref(), outer_alias, projection_map)?,
            whens: whens
                .iter()
                .map(|(when_expr, then_expr)| {
                    Some((
                        flatten_expr_tree(when_expr, outer_alias, projection_map)?,
                        flatten_expr_tree(then_expr, outer_alias, projection_map)?,
                    ))
                })
                .collect::<Option<Vec<_>>>()?,
            else_expr: flatten_expr_option(else_expr.as_deref(), outer_alias, projection_map)?,
            span: *span,
        }),
        Expr::Cast {
            expr: inner,
            type_name,
            span,
        } => Some(Expr::Cast {
            expr: Box::new(flatten_expr_tree(inner, outer_alias, projection_map)?),
            type_name: type_name.clone(),
            span: *span,
        }),
        Expr::Exists {
            subquery,
            not,
            span,
        } => Some(Expr::Exists {
            subquery: subquery.clone(),
            not: *not,
            span: *span,
        }),
        Expr::FunctionCall {
            name,
            args,
            distinct,
            order_by,
            filter,
            over,
            span,
        } => {
            let rewritten_args = match args {
                FunctionArgs::Star => FunctionArgs::Star,
                FunctionArgs::List(exprs) => FunctionArgs::List(
                    exprs
                        .iter()
                        .map(|inner| flatten_expr_tree(inner, outer_alias, projection_map))
                        .collect::<Option<Vec<_>>>()?,
                ),
            };
            Some(Expr::FunctionCall {
                name: name.clone(),
                args: rewritten_args,
                distinct: *distinct,
                order_by: flatten_order_by_terms(order_by, outer_alias, projection_map)?,
                filter: flatten_expr_option(filter.as_deref(), outer_alias, projection_map)?,
                over: over.clone(),
                span: *span,
            })
        }
        Expr::Collate {
            expr: inner,
            collation,
            span,
        } => Some(Expr::Collate {
            expr: Box::new(flatten_expr_tree(inner, outer_alias, projection_map)?),
            collation: collation.clone(),
            span: *span,
        }),
        Expr::IsNull {
            expr: inner,
            not,
            span,
        } => Some(Expr::IsNull {
            expr: Box::new(flatten_expr_tree(inner, outer_alias, projection_map)?),
            not: *not,
            span: *span,
        }),
        Expr::JsonAccess {
            expr: inner,
            path,
            arrow,
            span,
        } => Some(Expr::JsonAccess {
            expr: Box::new(flatten_expr_tree(inner, outer_alias, projection_map)?),
            path: Box::new(flatten_expr_tree(path, outer_alias, projection_map)?),
            arrow: *arrow,
            span: *span,
        }),
        Expr::RowValue(values, span) => Some(Expr::RowValue(
            values
                .iter()
                .map(|value| flatten_expr_tree(value, outer_alias, projection_map))
                .collect::<Option<Vec<_>>>()?,
            *span,
        )),
    }
}

fn flatten_column_ref(
    column_ref: &ColumnRef,
    span: Span,
    outer_alias: Option<&str>,
    projection_map: &FlattenProjectionMap,
) -> Option<Expr> {
    let exposed_name = column_ref.column.to_ascii_lowercase();
    let explicitly_qualified = column_ref
        .table
        .as_ref()
        .is_some_and(|table| outer_alias.is_some_and(|alias| table.eq_ignore_ascii_case(alias)));

    if explicitly_qualified || column_ref.table.is_none() {
        if let Some(mapped) = projection_map.columns.get(&exposed_name) {
            return Some(mapped.clone());
        }
        if projection_map.passthrough_columns {
            return Some(Expr::Column(
                ColumnRef::bare(column_ref.column.clone()),
                span,
            ));
        }
        if explicitly_qualified {
            return None;
        }
    }

    Some(Expr::Column(column_ref.clone(), span))
}

fn combine_where_clauses(
    inner_where: Option<Box<Expr>>,
    outer_where: Option<Box<Expr>>,
) -> Option<Box<Expr>> {
    match (inner_where, outer_where) {
        (Some(inner), Some(outer)) => {
            let span = inner.span().merge(outer.span());
            Some(Box::new(Expr::BinaryOp {
                left: inner,
                op: BinaryOp::And,
                right: outer,
                span,
            }))
        }
        (Some(inner), None) => Some(inner),
        (None, Some(outer)) => Some(outer),
        (None, None) => None,
    }
}

/// Returns true when any expression position inside the SELECT still carries a
/// bind placeholder (`?`, `?N`, `:name`, `@name`, `$name`).
///
/// frankensim-kl17o: a subquery whose predicate references placeholders is
/// parameter-DEPENDENT — its result is not knowable until execution supplies
/// bindings. Prepare-time paths call the eager subquery rewrite with
/// `params = None`; evaluating such a subquery there reads every placeholder
/// as NULL and bakes the wrong literal (`WHERE 0`) into the compiled program.
/// This walker is the guard both for that rewrite and for the
/// `*_subquery_supported_by_vdbe` routing predicates, which must keep
/// parameter-dependent subqueries on dispatch paths that bind at execution.
fn select_contains_any_placeholder(select: &SelectStatement) -> bool {
    fn core(core: &SelectCore) -> bool {
        match core {
            SelectCore::Select {
                columns,
                from,
                where_clause,
                group_by,
                having,
                windows,
                ..
            } => {
                columns.iter().any(|column| match column {
                    ResultColumn::Expr { expr: e, .. } => expr(e),
                    ResultColumn::Star | ResultColumn::TableStar(_) => false,
                }) || from.as_ref().is_some_and(from_clause)
                    || where_clause.as_deref().is_some_and(expr)
                    || group_by.iter().any(expr)
                    || having.as_deref().is_some_and(expr)
                    || windows.iter().any(|window| window_spec(&window.spec))
            }
            SelectCore::Values(rows) => rows.iter().flatten().any(expr),
        }
    }
    fn from_clause(from: &fsqlite_ast::FromClause) -> bool {
        source(&from.source)
            || from.joins.iter().any(|join| {
                source(&join.table)
                    || matches!(&join.constraint, Some(JoinConstraint::On(e)) if expr(e))
            })
    }
    fn source(src: &TableOrSubquery) -> bool {
        match src {
            TableOrSubquery::Table { .. } => false,
            TableOrSubquery::Subquery { query, .. } => select_contains_any_placeholder(query),
            TableOrSubquery::TableFunction { args, .. } => args.iter().any(expr),
            TableOrSubquery::ParenJoin(from) => from_clause(from),
        }
    }
    fn window_spec(spec: &fsqlite_ast::WindowSpec) -> bool {
        spec.partition_by.iter().any(expr)
            || spec.order_by.iter().any(|ordering| expr(&ordering.expr))
            || spec.frame.as_ref().is_some_and(|frame| {
                frame_bound(&frame.start) || frame.end.as_ref().is_some_and(frame_bound)
            })
    }
    fn frame_bound(bound: &fsqlite_ast::FrameBound) -> bool {
        match bound {
            fsqlite_ast::FrameBound::Preceding(e) | fsqlite_ast::FrameBound::Following(e) => {
                expr(e)
            }
            fsqlite_ast::FrameBound::UnboundedPreceding
            | fsqlite_ast::FrameBound::CurrentRow
            | fsqlite_ast::FrameBound::UnboundedFollowing => false,
        }
    }
    fn expr(e: &Expr) -> bool {
        match e {
            Expr::Placeholder(_, _) => true,
            Expr::BoundOuterValue { .. }
            | Expr::Literal(_, _)
            | Expr::Column(_, _)
            | Expr::Raise { .. } => false,
            Expr::BinaryOp { left, right, .. } => expr(left) || expr(right),
            Expr::UnaryOp { expr: inner, .. }
            | Expr::IsNull { expr: inner, .. }
            | Expr::Cast { expr: inner, .. }
            | Expr::Collate { expr: inner, .. } => expr(inner),
            Expr::Between {
                expr: inner,
                low,
                high,
                ..
            } => expr(inner) || expr(low) || expr(high),
            Expr::In {
                expr: inner, set, ..
            } => {
                expr(inner)
                    || match set {
                        InSet::List(values) => values.iter().any(expr),
                        InSet::Subquery(query) => select_contains_any_placeholder(query),
                        InSet::Table(_) => false,
                    }
            }
            Expr::Like {
                expr: inner,
                pattern,
                escape,
                ..
            } => expr(inner) || expr(pattern) || escape.as_deref().is_some_and(expr),
            Expr::Case {
                operand,
                whens,
                else_expr,
                ..
            } => {
                operand.as_deref().is_some_and(expr)
                    || whens.iter().any(|(when, then)| expr(when) || expr(then))
                    || else_expr.as_deref().is_some_and(expr)
            }
            Expr::Exists { subquery, .. } => select_contains_any_placeholder(subquery),
            Expr::Subquery(query, _) => select_contains_any_placeholder(query),
            Expr::FunctionCall {
                args,
                order_by,
                filter,
                over,
                ..
            } => {
                matches!(args, FunctionArgs::List(list) if list.iter().any(expr))
                    || order_by.iter().any(|ordering| expr(&ordering.expr))
                    || filter.as_deref().is_some_and(expr)
                    || over.as_ref().is_some_and(window_spec)
            }
            Expr::JsonAccess {
                expr: inner, path, ..
            } => expr(inner) || expr(path),
            Expr::RowValue(values, _) => values.iter().any(expr),
        }
    }
    core(&select.body.select)
        || select.body.compounds.iter().any(|(_, c)| core(c))
        || select.order_by.iter().any(|term| expr(&term.expr))
        || select
            .limit
            .as_ref()
            .is_some_and(|limit| expr(&limit.limit) || limit.offset.as_ref().is_some_and(expr))
        || select.with.as_ref().is_some_and(|with| {
            with.ctes
                .iter()
                .any(|cte| select_contains_any_placeholder(&cte.query))
        })
}

/// Returns true when statement-level subquery rewrite can mutate this statement.
///
/// This intentionally tracks only expression positions visited by
/// `rewrite_subquery_statement` with `rewrite_in_subqueries = false`.
fn statement_contains_rewritable_subquery(statement: &Statement) -> bool {
    match statement {
        Statement::Select(select) => select_contains_rewritable_subquery(select),
        Statement::Insert(insert) => insert_contains_rewritable_subquery(insert),
        Statement::Update(update) => update_contains_rewritable_subquery(update),
        Statement::Delete(delete) => delete_contains_rewritable_subquery(delete),
        _ => false,
    }
}

/// Returns true when SELECT rewrite-covered expression sites contain
/// EXISTS/scalar-subquery forms that `rewrite_in_expr(..., false, ...)` mutates.
fn select_contains_rewritable_subquery(select: &SelectStatement) -> bool {
    select_core_contains_rewritable_subquery(&select.body.select)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_contains_rewritable_subquery(core))
        || select
            .order_by
            .iter()
            .any(|term| expr_contains_rewritable_subquery(&term.expr))
        || select
            .limit
            .as_ref()
            .is_some_and(limit_clause_contains_rewritable_subquery)
}

fn insert_contains_rewritable_subquery(insert: &fsqlite_ast::InsertStatement) -> bool {
    let source_has_subquery = match &insert.source {
        fsqlite_ast::InsertSource::Values(rows) => {
            rows.iter().flatten().any(expr_contains_rewritable_subquery)
        }
        fsqlite_ast::InsertSource::Select(select) => select_contains_rewritable_subquery(select),
        fsqlite_ast::InsertSource::DefaultValues => false,
    };
    source_has_subquery
        || insert.upsert.iter().any(|upsert| {
            upsert
                .target
                .as_ref()
                .and_then(|target| target.where_clause.as_ref())
                .is_some_and(expr_contains_rewritable_subquery)
                || match &upsert.action {
                    fsqlite_ast::UpsertAction::Nothing => false,
                    fsqlite_ast::UpsertAction::Update {
                        assignments,
                        where_clause,
                    } => {
                        assignments
                            .iter()
                            .any(|assignment| expr_contains_rewritable_subquery(&assignment.value))
                            || where_clause
                                .as_ref()
                                .is_some_and(|expr| expr_contains_rewritable_subquery(expr))
                    }
                }
        })
        || insert.returning.iter().any(|column| match column {
            ResultColumn::Expr { expr, .. } => expr_contains_rewritable_subquery(expr),
            ResultColumn::Star | ResultColumn::TableStar(_) => false,
        })
}

fn update_contains_rewritable_subquery(update: &fsqlite_ast::UpdateStatement) -> bool {
    update
        .assignments
        .iter()
        .any(|assignment| expr_contains_rewritable_subquery(&assignment.value))
        || update
            .from
            .as_ref()
            .is_some_and(from_clause_contains_rewritable_subquery)
        || update
            .where_clause
            .as_ref()
            .is_some_and(expr_contains_rewritable_subquery)
        || update.returning.iter().any(|column| match column {
            ResultColumn::Expr { expr, .. } => expr_contains_rewritable_subquery(expr),
            ResultColumn::Star | ResultColumn::TableStar(_) => false,
        })
        || update
            .order_by
            .iter()
            .any(|term| expr_contains_rewritable_subquery(&term.expr))
        || update
            .limit
            .as_ref()
            .is_some_and(limit_clause_contains_rewritable_subquery)
}

fn delete_contains_rewritable_subquery(delete: &fsqlite_ast::DeleteStatement) -> bool {
    delete
        .where_clause
        .as_ref()
        .is_some_and(expr_contains_rewritable_subquery)
        || delete.returning.iter().any(|column| match column {
            ResultColumn::Expr { expr, .. } => expr_contains_rewritable_subquery(expr),
            ResultColumn::Star | ResultColumn::TableStar(_) => false,
        })
        || delete
            .order_by
            .iter()
            .any(|term| expr_contains_rewritable_subquery(&term.expr))
        || delete
            .limit
            .as_ref()
            .is_some_and(limit_clause_contains_rewritable_subquery)
}

fn from_clause_contains_rewritable_subquery(from: &fsqlite_ast::FromClause) -> bool {
    table_or_subquery_contains_rewritable_subquery(&from.source)
        || from.joins.iter().any(|join| {
            table_or_subquery_contains_rewritable_subquery(&join.table)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr))
                        if expr_contains_rewritable_subquery(expr)
                )
        })
}

fn table_or_subquery_contains_rewritable_subquery(source: &TableOrSubquery) -> bool {
    match source {
        TableOrSubquery::Table { .. } => false,
        TableOrSubquery::Subquery { query, .. } => select_contains_rewritable_subquery(query),
        TableOrSubquery::TableFunction { args, .. } => {
            args.iter().any(expr_contains_rewritable_subquery)
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            from_clause_contains_rewritable_subquery(from_clause)
        }
    }
}

fn limit_clause_contains_rewritable_subquery(limit: &LimitClause) -> bool {
    expr_contains_rewritable_subquery(&limit.limit)
        || limit
            .offset
            .as_ref()
            .is_some_and(expr_contains_rewritable_subquery)
}

fn select_core_contains_rewritable_subquery(core: &SelectCore) -> bool {
    match core {
        SelectCore::Select {
            columns,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns.iter().any(|column| match column {
                ResultColumn::Expr { expr, .. } => expr_contains_rewritable_subquery(expr),
                ResultColumn::Star | ResultColumn::TableStar(_) => false,
            }) || where_clause
                .as_ref()
                .is_some_and(|expr| expr_contains_rewritable_subquery(expr))
                || group_by.iter().any(expr_contains_rewritable_subquery)
                || having
                    .as_ref()
                    .is_some_and(|expr| expr_contains_rewritable_subquery(expr))
                || windows.iter().any(window_contains_rewritable_subquery)
        }
        SelectCore::Values(_) => false,
    }
}

fn window_contains_rewritable_subquery(window: &fsqlite_ast::WindowDef) -> bool {
    window_spec_contains_subquery_match(&window.spec, &mut |_| true)
}

fn select_contains_prepared_dispatch_subquery(select: &SelectStatement, conn: &Connection) -> bool {
    select_core_contains_prepared_dispatch_subquery(&select.body.select, conn)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_contains_prepared_dispatch_subquery(core, conn))
        || select
            .order_by
            .iter()
            .any(|term| expr_requires_prepared_select_dispatch(&term.expr, conn))
        || select.limit.as_ref().is_some_and(|limit| {
            expr_requires_prepared_select_dispatch(&limit.limit, conn)
                || limit
                    .offset
                    .as_ref()
                    .is_some_and(|expr| expr_requires_prepared_select_dispatch(expr, conn))
        })
}

fn select_core_contains_prepared_dispatch_subquery(core: &SelectCore, conn: &Connection) -> bool {
    match core {
        SelectCore::Select {
            columns,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns.iter().any(|column| match column {
                ResultColumn::Expr { expr, .. } => {
                    expr_requires_prepared_select_dispatch(expr, conn)
                }
                ResultColumn::Star | ResultColumn::TableStar(_) => false,
            }) || where_clause
                .as_ref()
                .is_some_and(|expr| expr_requires_prepared_select_dispatch(expr, conn))
                || group_by
                    .iter()
                    .any(|expr| expr_requires_prepared_select_dispatch(expr, conn))
                || having
                    .as_ref()
                    .is_some_and(|expr| expr_requires_prepared_select_dispatch(expr, conn))
                || windows
                    .iter()
                    .any(|window| window_contains_prepared_dispatch_subquery(window, conn))
        }
        SelectCore::Values(_) => false,
    }
}

fn window_contains_prepared_dispatch_subquery(
    window: &fsqlite_ast::WindowDef,
    conn: &Connection,
) -> bool {
    window
        .spec
        .partition_by
        .iter()
        .any(|expr| expr_requires_prepared_select_dispatch(expr, conn))
        || window
            .spec
            .order_by
            .iter()
            .any(|term| expr_requires_prepared_select_dispatch(&term.expr, conn))
        || window.spec.frame.as_ref().is_some_and(|frame| {
            frame_bound_contains_prepared_dispatch_subquery(&frame.start, conn)
                || frame.end.as_ref().is_some_and(|bound| {
                    frame_bound_contains_prepared_dispatch_subquery(bound, conn)
                })
        })
}

fn frame_bound_contains_prepared_dispatch_subquery(bound: &FrameBound, conn: &Connection) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_requires_prepared_select_dispatch(expr, conn)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

enum SubqueryExprRef<'a> {
    Scalar(&'a SelectStatement),
    Exists(&'a SelectStatement),
    In(&'a SelectStatement),
}

fn select_has_unsupported_correlated_scalar_subquery(
    select: &SelectStatement,
    conn: &Connection,
) -> bool {
    fn unsupported(subquery: SubqueryExprRef<'_>, conn: &Connection) -> bool {
        matches!(
            subquery,
            SubqueryExprRef::Scalar(inner)
                if is_correlated_subquery_with_schema(inner, &conn.schema.borrow())
                    && !scalar_subquery_supported_by_vdbe(inner, conn)
        )
    }

    select_contains_subquery_matching(select, conn, unsupported)
}

/// Whether a SELECT needs the lexical preflight used before subquery-width and
/// source-layout diagnostics. CTE and derived-table scopes matter even when
/// their bodies contain no scalar/EXISTS/IN expression node.
fn select_requires_column_reference_preflight(select: &SelectStatement, conn: &Connection) -> bool {
    select.with.is_some()
        || select_core_has_derived_source(&select.body.select)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_has_derived_source(core))
        || select_contains_subquery_matching(select, conn, |_, _| true)
}

fn select_core_has_derived_source(core: &SelectCore) -> bool {
    matches!(
        core,
        SelectCore::Select {
            from: Some(from), ..
        } if from_has_derived_source(from)
    )
}

fn from_has_derived_source(from: &FromClause) -> bool {
    table_or_subquery_is_or_contains_derived_source(&from.source)
        || from
            .joins
            .iter()
            .any(|join| table_or_subquery_is_or_contains_derived_source(&join.table))
}

fn table_or_subquery_is_or_contains_derived_source(source: &TableOrSubquery) -> bool {
    match source {
        TableOrSubquery::Subquery { .. } => true,
        TableOrSubquery::ParenJoin(from) => from_has_derived_source(from),
        TableOrSubquery::Table { .. } | TableOrSubquery::TableFunction { .. } => false,
    }
}

/// Whether source metadata can expose a layout error before LIMIT/OFFSET name
/// resolution. Ordinary `SELECT ... FROM table LIMIT ...` statements need no
/// metadata-only pass; relation validation and the normal executor already own
/// their diagnostics.
fn select_requires_layout_preflight_before_limit(select: &SelectStatement) -> bool {
    std::iter::once(&select.body.select)
        .chain(select.body.compounds.iter().map(|(_, core)| core))
        .any(select_core_requires_layout_preflight_before_limit)
}

fn select_core_requires_layout_preflight_before_limit(core: &SelectCore) -> bool {
    match core {
        SelectCore::Values(rows) => rows
            .first()
            .is_some_and(|first| rows.iter().any(|row| row.len() != first.len())),
        SelectCore::Select { columns, from, .. } => {
            columns.iter().any(|column| {
                matches!(column, ResultColumn::TableStar(_))
                    || matches!(column, ResultColumn::Star) && from.is_none()
            }) || from.as_ref().is_some_and(from_has_explicit_using)
        }
    }
}

fn from_has_explicit_using(from: &FromClause) -> bool {
    table_or_subquery_contains_explicit_using(&from.source)
        || from.joins.iter().any(|join| {
            matches!(join.constraint.as_ref(), Some(JoinConstraint::Using(_)))
                || table_or_subquery_contains_explicit_using(&join.table)
        })
}

fn table_or_subquery_contains_explicit_using(source: &TableOrSubquery) -> bool {
    matches!(source, TableOrSubquery::ParenJoin(from) if from_has_explicit_using(from))
}

fn select_references_view_for_layout(
    select: &SelectStatement,
    connection: &Connection,
) -> Result<bool> {
    for core in std::iter::once(&select.body.select)
        .chain(select.body.compounds.iter().map(|(_, core)| core))
    {
        if let SelectCore::Select {
            from: Some(from), ..
        } = core
            && from_references_view_for_layout(from, connection)?
        {
            return Ok(true);
        }
    }
    Ok(false)
}

fn from_references_view_for_layout(from: &FromClause, connection: &Connection) -> Result<bool> {
    if table_or_subquery_references_view_for_layout(&from.source, connection)? {
        return Ok(true);
    }
    for join in &from.joins {
        if table_or_subquery_references_view_for_layout(&join.table, connection)? {
            return Ok(true);
        }
    }
    Ok(false)
}

fn table_or_subquery_references_view_for_layout(
    source: &TableOrSubquery,
    connection: &Connection,
) -> Result<bool> {
    match source {
        TableOrSubquery::Table { name, .. } => named_relation_is_view_for_layout(name, connection),
        TableOrSubquery::Subquery { query, .. } => {
            select_references_view_for_layout(query, connection)
        }
        TableOrSubquery::ParenJoin(from) => from_references_view_for_layout(from, connection),
        TableOrSubquery::TableFunction { .. } => Ok(false),
    }
}

fn named_relation_is_view_for_layout(
    name: &QualifiedName,
    connection: &Connection,
) -> Result<bool> {
    match name.schema.as_deref() {
        None => {
            if connection.table_exists_for_scope(&name.name, PragmaSchemaScope::Temp) {
                return Ok(false);
            }
            if connection
                .view_index_for_scope(&name.name, PragmaSchemaScope::Temp)
                .is_some()
            {
                return Ok(true);
            }
            if connection.table_exists_for_scope(&name.name, PragmaSchemaScope::Main)
                || connection.has_live_vtab_instance(&name.name)
            {
                return Ok(false);
            }
            if connection
                .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                .is_some()
            {
                return Ok(true);
            }
            let schema_names = connection
                .attached_schemas
                .borrow()
                .all_schemas()
                .into_iter()
                .skip(2)
                .map(str::to_owned)
                .collect::<Vec<_>>();
            for schema_name in schema_names {
                let found = connection.with_attached_connection(&schema_name, |attached| {
                    if attached.table_exists_for_scope(&name.name, PragmaSchemaScope::Main)
                        || attached.has_live_vtab_instance(&name.name)
                    {
                        Ok(Some(false))
                    } else {
                        Ok(attached
                            .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                            .map(|_| true))
                    }
                })?;
                if let Some(is_view) = found {
                    return Ok(is_view);
                }
            }
            Ok(false)
        }
        Some(schema) if schema.eq_ignore_ascii_case("main") => Ok(!connection
            .table_exists_for_scope(&name.name, PragmaSchemaScope::Main)
            && !connection.has_live_vtab_instance(&name.name)
            && connection
                .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                .is_some()),
        Some(schema) if schema.eq_ignore_ascii_case("temp") => Ok(!connection
            .table_exists_for_scope(&name.name, PragmaSchemaScope::Temp)
            && connection
                .view_index_for_scope(&name.name, PragmaSchemaScope::Temp)
                .is_some()),
        Some(schema) if is_builtin_schema(schema) => Ok(false),
        Some(schema) => connection.with_attached_connection(schema, |attached| {
            Ok(
                !attached.table_exists_for_scope(&name.name, PragmaSchemaScope::Main)
                    && !attached.has_live_vtab_instance(&name.name)
                    && attached
                        .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                        .is_some(),
            )
        }),
    }
}

/// Walk every expression-bearing SELECT position, including nested FROM
/// sources, and apply `predicate` to each scalar/EXISTS/IN subquery.
///
/// `expr_contains_subquery_match` intentionally stops at the matched subquery
/// node. This wrapper explicitly recurses into that SELECT as well so deeply
/// nested unsupported correlated scalar shapes cannot evade dispatch routing.
fn select_contains_subquery_matching(
    select: &SelectStatement,
    conn: &Connection,
    predicate: fn(SubqueryExprRef<'_>, &Connection) -> bool,
) -> bool {
    select.with.as_ref().is_some_and(|with| {
        with.ctes
            .iter()
            .any(|cte| select_contains_subquery_matching(&cte.query, conn, predicate))
    }) || select_core_contains_subquery_matching(&select.body.select, conn, predicate)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_contains_subquery_matching(core, conn, predicate))
        || select
            .order_by
            .iter()
            .any(|term| expr_contains_subquery_matching_deep(&term.expr, conn, predicate))
        || select.limit.as_ref().is_some_and(|limit| {
            expr_contains_subquery_matching_deep(&limit.limit, conn, predicate)
                || limit.offset.as_ref().is_some_and(|offset| {
                    expr_contains_subquery_matching_deep(offset, conn, predicate)
                })
        })
}

fn select_core_contains_subquery_matching(
    core: &SelectCore,
    conn: &Connection,
    predicate: fn(SubqueryExprRef<'_>, &Connection) -> bool,
) -> bool {
    match core {
        SelectCore::Values(rows) => rows
            .iter()
            .flatten()
            .any(|expr| expr_contains_subquery_matching_deep(expr, conn, predicate)),
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns.iter().any(|column| {
                matches!(
                    column,
                    ResultColumn::Expr { expr, .. }
                        if expr_contains_subquery_matching_deep(expr, conn, predicate)
                )
            }) || from
                .as_ref()
                .is_some_and(|from| from_clause_contains_subquery_matching(from, conn, predicate))
                || where_clause
                    .as_deref()
                    .is_some_and(|expr| expr_contains_subquery_matching_deep(expr, conn, predicate))
                || group_by
                    .iter()
                    .any(|expr| expr_contains_subquery_matching_deep(expr, conn, predicate))
                || having
                    .as_deref()
                    .is_some_and(|expr| expr_contains_subquery_matching_deep(expr, conn, predicate))
                || windows.iter().any(|window| {
                    window
                        .spec
                        .partition_by
                        .iter()
                        .any(|expr| expr_contains_subquery_matching_deep(expr, conn, predicate))
                        || window.spec.order_by.iter().any(|term| {
                            expr_contains_subquery_matching_deep(&term.expr, conn, predicate)
                        })
                        || window.spec.frame.as_ref().is_some_and(|frame| {
                            frame_bound_contains_subquery_matching(&frame.start, conn, predicate)
                                || frame.end.as_ref().is_some_and(|end| {
                                    frame_bound_contains_subquery_matching(end, conn, predicate)
                                })
                        })
                })
        }
    }
}

fn from_clause_contains_subquery_matching(
    from: &FromClause,
    conn: &Connection,
    predicate: fn(SubqueryExprRef<'_>, &Connection) -> bool,
) -> bool {
    table_or_subquery_contains_subquery_matching(&from.source, conn, predicate)
        || from.joins.iter().any(|join| {
            table_or_subquery_contains_subquery_matching(&join.table, conn, predicate)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr))
                        if expr_contains_subquery_matching_deep(expr, conn, predicate)
                )
        })
}

fn table_or_subquery_contains_subquery_matching(
    source: &TableOrSubquery,
    conn: &Connection,
    predicate: fn(SubqueryExprRef<'_>, &Connection) -> bool,
) -> bool {
    match source {
        TableOrSubquery::Table { .. } => false,
        TableOrSubquery::Subquery { query, .. } => {
            select_contains_subquery_matching(query, conn, predicate)
        }
        TableOrSubquery::TableFunction { args, .. } => args
            .iter()
            .any(|expr| expr_contains_subquery_matching_deep(expr, conn, predicate)),
        TableOrSubquery::ParenJoin(from) => {
            from_clause_contains_subquery_matching(from, conn, predicate)
        }
    }
}

fn frame_bound_contains_subquery_matching(
    bound: &FrameBound,
    conn: &Connection,
    predicate: fn(SubqueryExprRef<'_>, &Connection) -> bool,
) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_contains_subquery_matching_deep(expr, conn, predicate)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn expr_contains_subquery_matching_deep(
    expr: &Expr,
    conn: &Connection,
    predicate: fn(SubqueryExprRef<'_>, &Connection) -> bool,
) -> bool {
    expr_contains_subquery_match(expr, &mut |subquery| match subquery {
        SubqueryExprRef::Scalar(inner) => {
            predicate(SubqueryExprRef::Scalar(inner), conn)
                || select_contains_subquery_matching(inner, conn, predicate)
        }
        SubqueryExprRef::Exists(inner) => {
            predicate(SubqueryExprRef::Exists(inner), conn)
                || select_contains_subquery_matching(inner, conn, predicate)
        }
        SubqueryExprRef::In(inner) => {
            predicate(SubqueryExprRef::In(inner), conn)
                || select_contains_subquery_matching(inner, conn, predicate)
        }
    })
}

fn frame_bound_contains_subquery_match(
    bound: &FrameBound,
    matcher: &mut impl FnMut(SubqueryExprRef<'_>) -> bool,
) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_contains_subquery_match(expr, matcher)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn frame_spec_contains_subquery_match(
    frame: &FrameSpec,
    matcher: &mut impl FnMut(SubqueryExprRef<'_>) -> bool,
) -> bool {
    frame_bound_contains_subquery_match(&frame.start, matcher)
        || frame
            .end
            .as_ref()
            .is_some_and(|bound| frame_bound_contains_subquery_match(bound, matcher))
}

fn window_spec_contains_subquery_match(
    window: &WindowSpec,
    matcher: &mut impl FnMut(SubqueryExprRef<'_>) -> bool,
) -> bool {
    window
        .partition_by
        .iter()
        .any(|expr| expr_contains_subquery_match(expr, matcher))
        || window
            .order_by
            .iter()
            .any(|term| expr_contains_subquery_match(&term.expr, matcher))
        || window
            .frame
            .as_ref()
            .is_some_and(|frame| frame_spec_contains_subquery_match(frame, matcher))
}

fn expr_contains_subquery_match(
    expr: &Expr,
    matcher: &mut impl FnMut(SubqueryExprRef<'_>) -> bool,
) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => false,
        Expr::BinaryOp { left, right, .. } => {
            expr_contains_subquery_match(left, matcher)
                || expr_contains_subquery_match(right, matcher)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => expr_contains_subquery_match(expr, matcher),
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_contains_subquery_match(expr, matcher)
                || expr_contains_subquery_match(low, matcher)
                || expr_contains_subquery_match(high, matcher)
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return false;
            }
            expr_contains_subquery_match(expr, matcher)
                || match set {
                    InSet::List(exprs) => exprs
                        .iter()
                        .any(|item| expr_contains_subquery_match(item, matcher)),
                    InSet::Subquery(subquery) => matcher(SubqueryExprRef::In(subquery)),
                    InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_contains_subquery_match(expr, matcher)
                || expr_contains_subquery_match(pattern, matcher)
                || escape
                    .as_ref()
                    .is_some_and(|inner| expr_contains_subquery_match(inner, matcher))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_ref()
                .is_some_and(|inner| expr_contains_subquery_match(inner, matcher))
                || whens.iter().any(|(when_expr, then_expr)| {
                    expr_contains_subquery_match(when_expr, matcher)
                        || expr_contains_subquery_match(then_expr, matcher)
                })
                || else_expr
                    .as_ref()
                    .is_some_and(|inner| expr_contains_subquery_match(inner, matcher))
        }
        Expr::Subquery(subquery, _) => matcher(SubqueryExprRef::Scalar(subquery)),
        Expr::Exists { subquery, .. } => matcher(SubqueryExprRef::Exists(subquery)),
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_have_subquery = match args {
                FunctionArgs::Star => false,
                FunctionArgs::List(exprs) => exprs
                    .iter()
                    .any(|inner| expr_contains_subquery_match(inner, matcher)),
            };
            args_have_subquery
                || order_by
                    .iter()
                    .any(|term| expr_contains_subquery_match(&term.expr, matcher))
                || filter
                    .as_ref()
                    .is_some_and(|inner| expr_contains_subquery_match(inner, matcher))
                || over
                    .as_ref()
                    .is_some_and(|window| window_spec_contains_subquery_match(window, matcher))
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => {
            expr_contains_subquery_match(inner, matcher)
                || expr_contains_subquery_match(path, matcher)
        }
        Expr::RowValue(values, _) => values
            .iter()
            .any(|value| expr_contains_subquery_match(value, matcher)),
    }
}

/// Mirror the native IN-probe expression boundary in `fsqlite-vdbe`.
///
/// These nodes need connection-level semantic evaluation: native probing
/// either has no lowering for them, loses scalar-subquery affinity, or would
/// ignore function modifiers/window state.
fn in_probe_expr_requires_semantic_fallback(expr: &Expr) -> bool {
    match expr {
        Expr::RowValue(..) | Expr::Raise { .. } | Expr::Exists { .. } | Expr::Subquery(..) => true,
        Expr::BinaryOp { left, right, .. }
        | Expr::JsonAccess {
            expr: left,
            path: right,
            ..
        } => {
            in_probe_expr_requires_semantic_fallback(left)
                || in_probe_expr_requires_semantic_fallback(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => in_probe_expr_requires_semantic_fallback(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            in_probe_expr_requires_semantic_fallback(expr)
                || in_probe_expr_requires_semantic_fallback(low)
                || in_probe_expr_requires_semantic_fallback(high)
        }
        Expr::In { expr, set, .. } => {
            in_probe_expr_requires_semantic_fallback(expr)
                || match set {
                    InSet::List(values) => {
                        values.iter().any(in_probe_expr_requires_semantic_fallback)
                    }
                    InSet::Table(_) | InSet::Subquery(_) => true,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            in_probe_expr_requires_semantic_fallback(expr)
                || in_probe_expr_requires_semantic_fallback(pattern)
                || escape
                    .as_deref()
                    .is_some_and(in_probe_expr_requires_semantic_fallback)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(in_probe_expr_requires_semantic_fallback)
                || whens.iter().any(|(when_expr, then_expr)| {
                    in_probe_expr_requires_semantic_fallback(when_expr)
                        || in_probe_expr_requires_semantic_fallback(then_expr)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(in_probe_expr_requires_semantic_fallback)
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            !order_by.is_empty()
                || filter.is_some()
                || over.is_some()
                || matches!(
                    args,
                    FunctionArgs::List(values)
                        if values
                            .iter()
                            .any(in_probe_expr_requires_semantic_fallback)
                )
        }
        Expr::BoundOuterValue { .. }
        | Expr::Literal(..)
        | Expr::Column(..)
        | Expr::Placeholder(..) => false,
    }
}

fn scalar_in_operand_expr_contains_function_call(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall { .. } | Expr::JsonAccess { .. } => true,
        Expr::BinaryOp { left, right, .. } => {
            scalar_in_operand_expr_contains_function_call(left)
                || scalar_in_operand_expr_contains_function_call(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => scalar_in_operand_expr_contains_function_call(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            scalar_in_operand_expr_contains_function_call(expr)
                || scalar_in_operand_expr_contains_function_call(low)
                || scalar_in_operand_expr_contains_function_call(high)
        }
        Expr::In { expr, set, .. } => {
            scalar_in_operand_expr_contains_function_call(expr)
                || match set {
                    InSet::List(values) => values
                        .iter()
                        .any(scalar_in_operand_expr_contains_function_call),
                    InSet::Table(_) => false,
                    InSet::Subquery(_) => true,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            scalar_in_operand_expr_contains_function_call(expr)
                || scalar_in_operand_expr_contains_function_call(pattern)
                || escape
                    .as_deref()
                    .is_some_and(scalar_in_operand_expr_contains_function_call)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(scalar_in_operand_expr_contains_function_call)
                || whens.iter().any(|(when_expr, then_expr)| {
                    scalar_in_operand_expr_contains_function_call(when_expr)
                        || scalar_in_operand_expr_contains_function_call(then_expr)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(scalar_in_operand_expr_contains_function_call)
        }
        Expr::RowValue(values, _) => values
            .iter()
            .any(scalar_in_operand_expr_contains_function_call),
        Expr::Subquery(..) | Expr::Exists { .. } => true,
        Expr::BoundOuterValue { .. }
        | Expr::Literal(..)
        | Expr::Column(..)
        | Expr::Raise { .. }
        | Expr::Placeholder(..) => false,
    }
}

/// Mirror `fsqlite-vdbe::scalar_in_operand_metadata` for the one native
/// complex-IN carve-out that preserves scalar-subquery affinity.
///
/// The VDBE helper is intentionally syntax/schema based and accepts no
/// function calls because codegen cannot distinguish scalar overrides from
/// custom aggregates at that layer. Keep this connection dispatch predicate
/// equally narrow: simple probe-source IN paths still cannot lower a scalar
/// left operand, so only an ORDER/LIMIT RHS may use the complex emitter.
fn scalar_in_operand_supported_by_complex_vdbe(
    operand: &Expr,
    rhs: &SelectStatement,
    conn: &Connection,
) -> bool {
    if rhs.order_by.is_empty() && rhs.limit.is_none() {
        return false;
    }
    let Expr::Subquery(select, _) = operand else {
        return false;
    };
    if select.with.is_some()
        || !select.body.compounds.is_empty()
        || !select.order_by.is_empty()
        || select.limit.is_some()
    {
        return false;
    }
    let SelectCore::Select {
        columns,
        from,
        where_clause,
        group_by,
        having,
        windows,
        ..
    } = &select.body.select
    else {
        return false;
    };
    if !group_by.is_empty()
        || having.is_some()
        || !windows.is_empty()
        || columns.iter().any(|column| {
            matches!(
                column,
                ResultColumn::Expr { expr, .. }
                    if conn.expr_contains_aggregate_with_registry(expr)
                        || expr_has_window_function(expr)
                        || in_probe_expr_requires_semantic_fallback(expr)
                        || scalar_in_operand_expr_contains_function_call(expr)
            )
        })
        || where_clause.as_deref().is_some_and(|expr| {
            conn.expr_contains_aggregate_with_registry(expr)
                || expr_has_window_function(expr)
                || in_probe_expr_requires_semantic_fallback(expr)
                || scalar_in_operand_expr_contains_function_call(expr)
        })
    {
        return false;
    }
    let Some(from_clause) = from.as_ref() else {
        if where_clause.is_some() {
            return false;
        }
        let [ResultColumn::Expr { expr, .. }] = columns.as_slice() else {
            return false;
        };
        return !expr_has_external_column_ref(expr, &[]);
    };
    if !from_clause.joins.is_empty() {
        return false;
    }
    let TableOrSubquery::Table {
        name,
        alias,
        index_hint: None,
        time_travel: None,
    } = &from_clause.source
    else {
        return false;
    };
    if name.schema.is_some() {
        return false;
    }
    let schema = conn.schema.borrow();
    let Some(table) = schema
        .iter()
        .find(|table| table.name.eq_ignore_ascii_case(&name.name))
    else {
        return false;
    };
    let table_label = alias.as_deref().unwrap_or(&name.name);
    let output_is_local = match columns.as_slice() {
        [ResultColumn::Expr { expr, .. }] => {
            !scalar_expr_has_invalid_local_binding(expr, table, table_label)
        }
        [ResultColumn::Star] => table.columns.len() == 1,
        [ResultColumn::TableStar(qualifier)] => {
            table.columns.len() == 1 && source_matches_name(&from_clause.source, qualifier)
        }
        _ => false,
    };
    output_is_local
        && where_clause
            .as_deref()
            .is_none_or(|expr| !scalar_expr_has_invalid_local_binding(expr, table, table_label))
}

fn select_has_in_subquery_operand_requiring_semantic_fallback(
    select: &SelectStatement,
    conn: &Connection,
) -> bool {
    select.with.as_ref().is_some_and(|with| {
        with.ctes
            .iter()
            .any(|cte| select_has_in_subquery_operand_requiring_semantic_fallback(&cte.query, conn))
    }) || select_core_has_in_subquery_operand_requiring_semantic_fallback(&select.body.select, conn)
        || select.body.compounds.iter().any(|(_, core)| {
            select_core_has_in_subquery_operand_requiring_semantic_fallback(core, conn)
        })
        || select
            .order_by
            .iter()
            .any(|term| expr_has_in_subquery_operand_requiring_semantic_fallback(&term.expr, conn))
        || select.limit.as_ref().is_some_and(|limit| {
            expr_has_in_subquery_operand_requiring_semantic_fallback(&limit.limit, conn)
                || limit.offset.as_ref().is_some_and(|offset| {
                    expr_has_in_subquery_operand_requiring_semantic_fallback(offset, conn)
                })
        })
}

fn select_core_has_in_subquery_operand_requiring_semantic_fallback(
    core: &SelectCore,
    conn: &Connection,
) -> bool {
    match core {
        SelectCore::Values(rows) => rows
            .iter()
            .flatten()
            .any(|expr| expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)),
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns.iter().any(|column| {
                matches!(
                    column,
                    ResultColumn::Expr { expr, .. }
                        if expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
                )
            }) || from.as_ref().is_some_and(|from| {
                from_clause_has_in_subquery_operand_requiring_semantic_fallback(from, conn)
            }) || where_clause.as_deref().is_some_and(|expr| {
                expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
            }) || group_by
                .iter()
                .any(|expr| expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn))
                || having.as_deref().is_some_and(|expr| {
                    expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
                })
                || windows.iter().any(|window| {
                    window_spec_has_in_subquery_operand_requiring_semantic_fallback(
                        &window.spec,
                        conn,
                    )
                })
        }
    }
}

fn from_clause_has_in_subquery_operand_requiring_semantic_fallback(
    from: &FromClause,
    conn: &Connection,
) -> bool {
    source_has_in_subquery_operand_requiring_semantic_fallback(&from.source, conn)
        || from.joins.iter().any(|join| {
            source_has_in_subquery_operand_requiring_semantic_fallback(&join.table, conn)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr))
                        if expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
                )
        })
}

fn source_has_in_subquery_operand_requiring_semantic_fallback(
    source: &TableOrSubquery,
    conn: &Connection,
) -> bool {
    match source {
        TableOrSubquery::Table { .. } => false,
        TableOrSubquery::Subquery { query, .. } => {
            select_has_in_subquery_operand_requiring_semantic_fallback(query, conn)
        }
        TableOrSubquery::TableFunction { args, .. } => args
            .iter()
            .any(|expr| expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)),
        TableOrSubquery::ParenJoin(from) => {
            from_clause_has_in_subquery_operand_requiring_semantic_fallback(from, conn)
        }
    }
}

fn window_spec_has_in_subquery_operand_requiring_semantic_fallback(
    window: &WindowSpec,
    conn: &Connection,
) -> bool {
    window
        .partition_by
        .iter()
        .any(|expr| expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn))
        || window
            .order_by
            .iter()
            .any(|term| expr_has_in_subquery_operand_requiring_semantic_fallback(&term.expr, conn))
        || window.frame.as_ref().is_some_and(|frame| {
            frame_bound_has_in_subquery_operand_requiring_semantic_fallback(&frame.start, conn)
                || frame.end.as_ref().is_some_and(|end| {
                    frame_bound_has_in_subquery_operand_requiring_semantic_fallback(end, conn)
                })
        })
}

fn frame_bound_has_in_subquery_operand_requiring_semantic_fallback(
    bound: &FrameBound,
    conn: &Connection,
) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

#[allow(clippy::too_many_lines)]
fn expr_has_in_subquery_operand_requiring_semantic_fallback(
    expr: &Expr,
    conn: &Connection,
) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(..)
        | Expr::Column(..)
        | Expr::Raise { .. }
        | Expr::Placeholder(..) => false,
        Expr::BinaryOp { left, right, .. }
        | Expr::JsonAccess {
            expr: left,
            path: right,
            ..
        } => {
            expr_has_in_subquery_operand_requiring_semantic_fallback(left, conn)
                || expr_has_in_subquery_operand_requiring_semantic_fallback(right, conn)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => {
            expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
                || expr_has_in_subquery_operand_requiring_semantic_fallback(low, conn)
                || expr_has_in_subquery_operand_requiring_semantic_fallback(high, conn)
        }
        Expr::In { expr, set, .. } => {
            (conn.in_lhs_column_count(expr) > 1 && matches!(set, InSet::List(_)))
                || (matches!(set, InSet::Subquery(_))
                    && in_probe_expr_requires_semantic_fallback(expr)
                    && !matches!(
                        set,
                        InSet::Subquery(subquery)
                            if scalar_in_operand_supported_by_complex_vdbe(expr, subquery, conn)
                    ))
                || expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
                || match set {
                    InSet::List(values) => values.iter().any(|value| {
                        expr_has_in_subquery_operand_requiring_semantic_fallback(value, conn)
                    }),
                    InSet::Subquery(subquery) => {
                        select_has_in_subquery_operand_requiring_semantic_fallback(subquery, conn)
                    }
                    InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
                || expr_has_in_subquery_operand_requiring_semantic_fallback(pattern, conn)
                || escape.as_deref().is_some_and(|escape| {
                    expr_has_in_subquery_operand_requiring_semantic_fallback(escape, conn)
                })
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_deref().is_some_and(|operand| {
                expr_has_in_subquery_operand_requiring_semantic_fallback(operand, conn)
            }) || whens.iter().any(|(when_expr, then_expr)| {
                expr_has_in_subquery_operand_requiring_semantic_fallback(when_expr, conn)
                    || expr_has_in_subquery_operand_requiring_semantic_fallback(then_expr, conn)
            }) || else_expr.as_deref().is_some_and(|else_expr| {
                expr_has_in_subquery_operand_requiring_semantic_fallback(else_expr, conn)
            })
        }
        Expr::Subquery(subquery, _) | Expr::Exists { subquery, .. } => {
            select_has_in_subquery_operand_requiring_semantic_fallback(subquery, conn)
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            matches!(
                args,
                FunctionArgs::List(values)
                    if values
                        .iter()
                        .any(|value| {
                            expr_has_in_subquery_operand_requiring_semantic_fallback(value, conn)
                        })
            ) || order_by.iter().any(|term| {
                expr_has_in_subquery_operand_requiring_semantic_fallback(&term.expr, conn)
            }) || filter.as_deref().is_some_and(|filter| {
                expr_has_in_subquery_operand_requiring_semantic_fallback(filter, conn)
            }) || over.as_ref().is_some_and(|window| {
                window_spec_has_in_subquery_operand_requiring_semantic_fallback(window, conn)
            })
        }
        Expr::RowValue(values, _) => values
            .iter()
            .any(|value| expr_has_in_subquery_operand_requiring_semantic_fallback(value, conn)),
    }
}

fn expr_requires_prepared_select_dispatch(expr: &Expr, conn: &Connection) -> bool {
    expr_has_in_subquery_operand_requiring_semantic_fallback(expr, conn)
        || expr_contains_subquery_match(expr, &mut |subquery| match subquery {
            SubqueryExprRef::Scalar(subquery) => !scalar_subquery_supported_by_vdbe(subquery, conn),
            SubqueryExprRef::Exists(subquery) => !exists_subquery_supported_by_vdbe(subquery, conn),
            SubqueryExprRef::In(subquery) => !in_subquery_supported_by_vdbe(subquery, conn),
        })
}

fn exists_subquery_supported_by_vdbe(sub: &SelectStatement, conn: &Connection) -> bool {
    if subquery_references_view(sub, conn)
        || subquery_references_sqlite_schema(sub, conn)
        || sub.with.is_some()
        || !sub.body.compounds.is_empty()
        || !sub.order_by.is_empty()
        || sub.limit.is_some()
        // frankensim-kl17o: parameter-dependent subqueries survive the
        // prepare-time rewrite un-folded and must route through dispatch
        // paths that bind placeholders at execution.
        //
        // bd-8sfs3 carve-out: the correlated count-semijoin probe shape
        // never goes through the prepare-time rewrite — its residual bound
        // lowers through emit_expr to Opcode::Variable and is bound fresh at
        // every execution, so placeholders are native to its compiled form.
        // Without this exception the parameterized variant of the shape fell
        // to the per-outer-row nested-statement fallback (one full
        // execute_statement per outer row: ~26,000x slower than the
        // compiled CountIndexEqRun plan at 10k outer rows).
        || (select_contains_any_placeholder(sub)
            && !correlated_exists_matches_count_semijoin_shape(
                sub,
                &conn.schema.borrow(),
            ))
    {
        return false;
    }
    // Correlated EXISTS subqueries (those referencing outer table columns)
    // generally must be evaluated per-row by the connection-level fallback
    // path. The VDBE emit_exists_subquery has a known issue where the AND of
    // a correlated equality and a correlated inequality (e.g.,
    // `t2.a = t.a AND t2.id <> t.id`) produces incorrect results for some
    // outer rows: after the single-row SeekRowid probe it still applies a
    // residual term that references the *outer* row, which the probe path
    // mishandles. Such multi-correlated-term shapes stay on the connection
    // fallback, which correctly substitutes outer refs per row.
    //
    // The one correlated shape the VDBE *does* handle correctly is the
    // indexed COUNT(*) EXISTS-semijoin: exactly one correlated equality term
    // `inner.col = outer.col` (the rowid/index probe key) plus inner-only,
    // non-correlated residual bounds (e.g. `c.id <= 2`). That is precisely
    // what the codegen recognizer `extract_count_indexed_exists_target`
    // (and the `emit_exists_subquery` rowid-probe fallback) accept. Keeping
    // it on the compiled path lets the `CountIndexEqRun` semijoin fast path
    // fire instead of the deferred/interpreted fallback. Narrow the blanket
    // rejection accordingly while still routing every other correlated shape
    // — multiple correlated terms, correlated inequality, multi-table inner
    // — to the fallback.
    if is_correlated_subquery_with_schema(sub, &conn.schema.borrow())
        && !correlated_exists_matches_count_semijoin_shape(sub, &conn.schema.borrow())
    {
        return false;
    }

    match &sub.body.select {
        SelectCore::Select {
            from,
            group_by,
            having,
            windows,
            ..
        } => {
            if !group_by.is_empty() || having.is_some() || !windows.is_empty() {
                return false;
            }
            from.as_ref().is_none_or(|from_clause| {
                from_clause.joins.is_empty()
                    && matches!(&from_clause.source, TableOrSubquery::Table { .. })
            })
        }
        SelectCore::Values(_) => false,
    }
}

/// Returns `true` only for the one correlated EXISTS shape the VDBE compiles
/// correctly: the indexed COUNT(*) EXISTS-semijoin probe.
///
/// This mirrors the structural requirements of the codegen recognizer
/// `extract_count_indexed_exists_target` / `extract_exists_rowid_probe`
/// (crates/fsqlite-vdbe/src/codegen.rs) — operating on the subquery AST and
/// correlation analysis rather than the (here-unavailable) outer table schema:
///
/// * a single inner table source (no joins; a plain base table);
/// * an inner WHERE clause whose AND-terms contain *exactly one* correlated
///   equality `inner.col = outer.col` — the probe key — where exactly one side
///   references the outer scan and the other does not; and
/// * the remaining (residual) terms are *non-correlated* inner-only bounds
///   (e.g. `c.id <= 2`), of which there is at most one.
///
/// The correctness-critical exclusion is the warned-about
/// `t2.a = t.a AND t2.id <> t.id` family: those carry a *second* correlated
/// term, so they have either more than one correlated term or a correlated
/// (non-inner-only) residual, and are rejected here — staying on the
/// per-row connection fallback.
fn correlated_exists_matches_count_semijoin_shape(
    sub: &SelectStatement,
    schema: &[TableSchema],
) -> bool {
    // No inner WITH/compound/ORDER/LIMIT — the recognizer rejects these too.
    // (The caller already screens these, but keep the check local + explicit.)
    if sub.with.is_some()
        || !sub.body.compounds.is_empty()
        || !sub.order_by.is_empty()
        || sub.limit.is_some()
    {
        return false;
    }

    let SelectCore::Select {
        from: Some(from),
        where_clause: Some(where_clause),
        group_by,
        having,
        windows,
        ..
    } = &sub.body.select
    else {
        return false;
    };
    if !group_by.is_empty() || having.is_some() || !windows.is_empty() {
        return false;
    }
    // Single inner base table only (no joins, no subquery/table-function source).
    if !from.joins.is_empty() || !matches!(&from.source, TableOrSubquery::Table { .. }) {
        return false;
    }

    let mut terms = Vec::new();
    flatten_and_terms(where_clause, &mut terms);

    let mut correlated_probe_terms = 0usize;
    let mut residual_terms = 0usize;
    for term in terms {
        if let Expr::BinaryOp {
            left,
            op: BinaryOp::Eq,
            right,
            ..
        } = term
        {
            let left_external =
                expr_has_external_column_ref_with_schema_in_core(left, &sub.body.select, schema);
            let right_external =
                expr_has_external_column_ref_with_schema_in_core(right, &sub.body.select, schema);
            // A valid probe is a correlated equality with exactly one outer
            // side (`inner.col = outer.col`). Both sides correlated, or an
            // equality where the "inner" side still references the outer
            // scan, is not the supported probe shape.
            if left_external != right_external {
                correlated_probe_terms += 1;
                continue;
            }
            if left_external || right_external {
                // Equality with outer refs on both sides — not the probe shape.
                return false;
            }
        }

        // Any non-probe term must be a NON-correlated, inner-only residual
        // bound. A correlated residual (e.g. `t2.id <> t.id`) is exactly the
        // shape the VDBE mishandles — reject it.
        if expr_has_external_column_ref_with_schema_in_core(term, &sub.body.select, schema) {
            return false;
        }
        residual_terms += 1;
    }

    // Exactly one correlated probe key, and at most one inner-only residual,
    // matching `extract_exists_rowid_probe` + the recognizer's single-residual
    // ceiling.
    correlated_probe_terms == 1 && residual_terms <= 1
}

fn scalar_subquery_supported_by_vdbe(sub: &SelectStatement, conn: &Connection) -> bool {
    if subquery_references_view(sub, conn)
        || subquery_references_sqlite_schema(sub, conn)
        || sub.with.is_some()
        || !sub.body.compounds.is_empty()
        || !sub.order_by.is_empty()
        || sub.limit.is_some()
        // frankensim-kl17o: see exists_subquery_supported_by_vdbe.
        || select_contains_any_placeholder(sub)
    {
        return false;
    }

    match &sub.body.select {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            let [ResultColumn::Expr { expr, .. }] = columns.as_slice() else {
                return false;
            };
            if conn.select_result_column_count(sub, &[], &mut Vec::new()) != 1
                || !group_by.is_empty()
                || having.is_some()
                || !windows.is_empty()
                || conn.expr_contains_aggregate_with_registry(expr)
                || expr_has_window_function(expr)
                || in_probe_expr_requires_semantic_fallback(expr)
            {
                return false;
            }
            let Some(from_clause) = from.as_ref() else {
                // emit_scalar_subquery returns the result expression
                // immediately for a no-FROM SELECT. It therefore cannot
                // enforce WHERE cardinality, nor run aggregate finalization.
                return where_clause.is_none() && !expr_has_external_column_ref(expr, &[]);
            };
            if !from_clause.joins.is_empty() {
                return false;
            }
            let TableOrSubquery::Table {
                name,
                alias,
                index_hint,
                time_travel,
            } = &from_clause.source
            else {
                return false;
            };
            if name.schema.is_some() || index_hint.is_some() || time_travel.is_some() {
                return false;
            }
            let schema = conn.schema.borrow();
            let Some(table) = schema
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(&name.name))
            else {
                return false;
            };
            let table_label = alias.as_deref().unwrap_or(&name.name);
            // The projection must bind strictly to the inner table: outer
            // refs in the SELECT list keep routing to the connection
            // evaluator (affinity/rewrite receipts depend on that).
            if scalar_expr_has_invalid_local_binding(expr, table, table_label) {
                return false;
            }
            if where_clause.as_deref().is_some_and(|where_expr| {
                conn.expr_contains_aggregate_with_registry(where_expr)
                    || expr_has_window_function(where_expr)
            }) {
                return false;
            }
            if !where_clause.as_deref().is_some_and(|where_expr| {
                scalar_expr_has_invalid_local_binding(where_expr, table, table_label)
            }) {
                return true;
            }
            // bd-phboe mechanism (a): the strict WHERE check rejected the
            // clause — admit exactly the one correlated shape the VDBE
            // compiles correctly (the b612eb7b-lineage keeper shape): a
            // single correlated equality probe `inner.col = outer.col` with
            // at most one inner-only residual, per the same recognizer the
            // correlated-EXISTS count-semijoin carve-out uses. Every other
            // correlated shape keeps routing to the connection evaluator.
            correlated_exists_matches_count_semijoin_shape(sub, &conn.schema.borrow())
        }
        SelectCore::Values(_) => false,
    }
}

/// Check the portion of scalar-subquery name resolution that can be proven
/// from the inner single-table schema alone.
///
/// Missing or foreign names may be legitimate outer references, but this
/// predicate does not have the enclosing scan's binding map. It therefore
/// routes every such name conservatively to connection-level evaluation,
/// which can distinguish a valid correlation from `no such column`. It also
/// rejects row-value/RAISE nodes that `emit_scalar_subquery` cannot lower.
fn scalar_expr_has_invalid_local_binding(
    expr: &Expr,
    table: &TableSchema,
    table_label: &str,
) -> bool {
    match expr {
        Expr::Column(column, _) => {
            if let Some(qualifier) = column.table.as_deref() {
                return !qualifier.eq_ignore_ascii_case(table_label)
                    || (table.column_index(&column.column).is_none()
                        && !table_exposes_hidden_rowid_alias(table, &column.column));
            }
            table.column_index(&column.column).is_none()
                && !table_exposes_hidden_rowid_alias(table, &column.column)
            // A missing bare name might be a SELECT alias or a valid outer
            // reference, but this predicate lacks the enclosing scan's
            // binding map. Route it conservatively: the connection evaluator
            // can distinguish those cases from `no such column`.
        }
        Expr::BinaryOp { left, right, .. } => {
            scalar_expr_has_invalid_local_binding(left, table, table_label)
                || scalar_expr_has_invalid_local_binding(right, table, table_label)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            scalar_expr_has_invalid_local_binding(expr, table, table_label)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            scalar_expr_has_invalid_local_binding(expr, table, table_label)
                || scalar_expr_has_invalid_local_binding(low, table, table_label)
                || scalar_expr_has_invalid_local_binding(high, table, table_label)
        }
        Expr::In { expr, set, .. } => {
            scalar_expr_has_invalid_local_binding(expr, table, table_label)
                || matches!(
                    set,
                    InSet::List(values)
                        if values.iter().any(|value| scalar_expr_has_invalid_local_binding(
                            value,
                            table,
                            table_label,
                        ))
                )
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            scalar_expr_has_invalid_local_binding(expr, table, table_label)
                || scalar_expr_has_invalid_local_binding(pattern, table, table_label)
                || escape.as_deref().is_some_and(|escape| {
                    scalar_expr_has_invalid_local_binding(escape, table, table_label)
                })
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_deref().is_some_and(|operand| {
                scalar_expr_has_invalid_local_binding(operand, table, table_label)
            }) || whens.iter().any(|(when_expr, then_expr)| {
                scalar_expr_has_invalid_local_binding(when_expr, table, table_label)
                    || scalar_expr_has_invalid_local_binding(then_expr, table, table_label)
            }) || else_expr.as_deref().is_some_and(|else_expr| {
                scalar_expr_has_invalid_local_binding(else_expr, table, table_label)
            })
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            ..
        } => {
            matches!(
                args,
                FunctionArgs::List(args)
                    if args.iter().any(|arg| scalar_expr_has_invalid_local_binding(
                        arg,
                        table,
                        table_label,
                    ))
            ) || order_by
                .iter()
                .any(|term| scalar_expr_has_invalid_local_binding(&term.expr, table, table_label))
                || filter.as_deref().is_some_and(|filter| {
                    scalar_expr_has_invalid_local_binding(filter, table, table_label)
                })
        }
        Expr::JsonAccess { expr, path, .. } => {
            scalar_expr_has_invalid_local_binding(expr, table, table_label)
                || scalar_expr_has_invalid_local_binding(path, table, table_label)
        }
        Expr::RowValue(_, _) | Expr::Raise { .. } => true,
        Expr::BoundOuterValue { .. }
        | Expr::Exists { .. }
        | Expr::Subquery(_, _)
        | Expr::Literal(_, _)
        | Expr::Placeholder(_, _) => false,
    }
}

fn in_subquery_supported_by_vdbe(sub: &SelectStatement, conn: &Connection) -> bool {
    if in_subquery_needs_eager_eval(sub, conn)
        || in_subquery_contains_semantic_fallback_expr(sub)
        || is_correlated_subquery_with_schema(sub, &conn.schema.borrow())
        || in_subquery_has_forbidden_outer_reference_position(sub, conn)
        || in_subquery_has_unresolved_local_name(sub, conn)
        || in_subquery_references_view(sub, conn)
        || in_subquery_references_sqlite_schema(sub, conn)
        || conn.select_result_column_count(sub, &[], &mut Vec::new()) != 1
        // frankensim-kl17o: see exists_subquery_supported_by_vdbe.
        //
        // bd-2dgf5 carve-out: a non-correlated native probe-source IN
        // subquery never goes through the prepare-time IN-rewrite fold. Both
        // the simple and ORDER/LIMIT emitters lower numbered placeholders to
        // Opcode::Variable and rebind fresh each run. Without this exception
        // parameterized probes fall to interpreted outer scans.
        || (select_contains_any_placeholder(sub)
            && !in_subquery_matches_native_probe_source_shape(sub, conn))
    {
        return false;
    }

    match &sub.body.select {
        SelectCore::Select { columns, from, .. } => {
            let Some(from_clause) = from.as_ref() else {
                return false;
            };
            if !from_clause.joins.is_empty() {
                return false;
            }
            let TableOrSubquery::Table {
                index_hint,
                time_travel,
                ..
            } = &from_clause.source
            else {
                return false;
            };
            if index_hint.is_some() || time_travel.is_some() {
                return false;
            }
            matches!(
                columns.as_slice(),
                [ResultColumn::Expr { .. } | ResultColumn::Star | ResultColumn::TableStar(_)]
            )
        }
        SelectCore::Values(_) => false,
    }
}

/// Return whether eager complex-IN fallback would evaluate a volatile
/// projection at the wrong DISTINCT/ORDER stage.
///
/// Native VDBE lowering stores the projected value at the SQLite-compatible
/// stage. The generic eager connection fallback still evaluates this shape too
/// early or too often, so only paths that would leave native lowering must fail
/// closed.
fn in_subquery_has_ordered_distinct_function_fallback_hazard(sub: &SelectStatement) -> bool {
    let SelectCore::Select {
        distinct,
        columns,
        from,
        ..
    } = &sub.body.select
    else {
        return false;
    };
    if *distinct == Distinctness::All {
        return false;
    }
    let [ResultColumn::Expr { expr, .. }] = columns.as_slice() else {
        return false;
    };
    if !expr_contains_function_call(expr) {
        return false;
    }
    sub.order_by.iter().any(|term| {
        if resolve_order_term_idx(&term.expr, columns).is_some() {
            return true;
        }
        let Some(FromClause {
            source: TableOrSubquery::Table { name, alias, .. },
            joins,
        }) = from.as_ref()
        else {
            return false;
        };
        if !joins.is_empty() {
            return false;
        }
        planner_directive_expression_matches_index_key(
            &term.expr,
            expr,
            &name.name,
            alias.as_deref(),
        )
    })
}

fn select_has_ordered_distinct_function_in_fallback_hazard(
    select: &SelectStatement,
    conn: &Connection,
) -> bool {
    fn is_hazard(subquery: SubqueryExprRef<'_>, conn: &Connection) -> bool {
        matches!(
            subquery,
            SubqueryExprRef::In(subquery)
                if in_subquery_has_ordered_distinct_function_fallback_hazard(subquery)
                    && !in_subquery_supported_by_vdbe(subquery, conn)
        )
    }

    select_contains_subquery_matching(select, conn, is_hazard)
}

fn in_subquery_contains_semantic_fallback_expr(sub: &SelectStatement) -> bool {
    let core_requires_fallback = match &sub.body.select {
        SelectCore::Values(rows) => rows
            .iter()
            .flatten()
            .any(in_probe_expr_requires_semantic_fallback),
        SelectCore::Select {
            columns,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns.iter().any(|column| {
                matches!(
                    column,
                    ResultColumn::Expr { expr, .. }
                        if in_probe_expr_requires_semantic_fallback(expr)
                )
            }) || where_clause
                .as_deref()
                .is_some_and(in_probe_expr_requires_semantic_fallback)
                || group_by
                    .iter()
                    .any(in_probe_expr_requires_semantic_fallback)
                || having
                    .as_deref()
                    .is_some_and(in_probe_expr_requires_semantic_fallback)
                || windows.iter().any(|window| {
                    window
                        .spec
                        .partition_by
                        .iter()
                        .any(in_probe_expr_requires_semantic_fallback)
                        || window
                            .spec
                            .order_by
                            .iter()
                            .any(|term| in_probe_expr_requires_semantic_fallback(&term.expr))
                        || window.spec.frame.as_ref().is_some_and(|frame| {
                            in_probe_frame_bound_requires_semantic_fallback(&frame.start)
                                || frame
                                    .end
                                    .as_ref()
                                    .is_some_and(in_probe_frame_bound_requires_semantic_fallback)
                        })
                })
        }
    };
    core_requires_fallback
        || sub
            .order_by
            .iter()
            .any(|term| in_probe_expr_requires_semantic_fallback(&term.expr))
        || sub.limit.as_ref().is_some_and(|limit| {
            in_probe_expr_requires_semantic_fallback(&limit.limit)
                || limit
                    .offset
                    .as_ref()
                    .is_some_and(in_probe_expr_requires_semantic_fallback)
        })
}

fn in_probe_frame_bound_requires_semantic_fallback(bound: &FrameBound) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            in_probe_expr_requires_semantic_fallback(expr)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

/// Return `true` when the native IN-probe emitters would encounter a column
/// name they cannot resolve against their single RHS table.
///
/// The VDBE validators deliberately decline these shapes rather than emitting
/// NULL for an unknown name. Keep the connection dispatch gate in lock-step so
/// the complete SELECT evaluator gets a chance to report the SQLite-compatible
/// `no such column`/`no such table` error. Bare SELECT aliases are accepted in
/// WHERE and ORDER BY only as a fallback after a real RHS table column; result
/// expressions themselves cannot refer to their own aliases.
fn in_subquery_has_unresolved_local_name(sub: &SelectStatement, conn: &Connection) -> bool {
    let SelectCore::Select {
        columns,
        from: Some(from),
        where_clause,
        ..
    } = &sub.body.select
    else {
        return true;
    };
    if !from.joins.is_empty() {
        return true;
    }
    let TableOrSubquery::Table {
        name,
        alias,
        index_hint: _,
        time_travel: _,
    } = &from.source
    else {
        return true;
    };
    // The native probe lookup is a flat table-name lookup. Schema-qualified
    // sources need the connection's attached/TEMP-aware resolver.
    if name.schema.is_some() {
        return true;
    }
    let schema = conn.schema.borrow();
    let Some(table) = schema
        .iter()
        .find(|table| table.name.eq_ignore_ascii_case(&name.name))
    else {
        return true;
    };
    let table_label = alias.as_deref().unwrap_or(&name.name);
    let output_aliases = collect_select_core_result_aliases(&sub.body.select);

    let result_names_valid = columns.iter().all(|column| match column {
        ResultColumn::Star => true,
        ResultColumn::TableStar(qualifier) => {
            qualifier.schema.is_none() && qualifier.name.eq_ignore_ascii_case(table_label)
        }
        ResultColumn::Expr { expr, .. } => {
            in_subquery_expr_names_resolve(expr, table, table_label, &HashSet::new())
        }
    });
    if !result_names_valid {
        return true;
    }
    if where_clause.as_deref().is_some_and(|expr| {
        !in_subquery_expr_names_resolve(expr, table, table_label, &output_aliases)
    }) {
        return true;
    }
    if sub.order_by.iter().any(|term| {
        connection_order_by_integer_ordinal(&term.expr).is_some_and(|ordinal| ordinal != 1)
            || (resolve_order_term_idx(&term.expr, columns).is_none()
                && !in_subquery_expr_names_resolve(&term.expr, table, table_label, &output_aliases))
    }) {
        return true;
    }
    sub.limit.as_ref().is_some_and(|limit| {
        !in_subquery_limit_expr_is_vdbe_safe(&limit.limit)
            || limit
                .offset
                .as_ref()
                .is_some_and(|offset| !in_subquery_limit_expr_is_vdbe_safe(offset))
    })
}

fn in_subquery_expr_names_resolve(
    expr: &Expr,
    table: &TableSchema,
    table_label: &str,
    output_aliases: &HashSet<String>,
) -> bool {
    match expr {
        Expr::Column(column, _) => {
            if column
                .table
                .as_deref()
                .is_some_and(|qualifier| !qualifier.eq_ignore_ascii_case(table_label))
            {
                return false;
            }
            table.column_index(&column.column).is_some()
                || table_exposes_hidden_rowid_alias(table, &column.column)
                || (column.table.is_none()
                    && output_aliases.contains(&column.column.to_ascii_lowercase()))
        }
        Expr::BinaryOp { left, right, .. } => {
            in_subquery_expr_names_resolve(left, table, table_label, output_aliases)
                && in_subquery_expr_names_resolve(right, table, table_label, output_aliases)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            in_subquery_expr_names_resolve(expr, table, table_label, output_aliases)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            in_subquery_expr_names_resolve(expr, table, table_label, output_aliases)
                && in_subquery_expr_names_resolve(low, table, table_label, output_aliases)
                && in_subquery_expr_names_resolve(high, table, table_label, output_aliases)
        }
        Expr::In { expr, set, .. } => {
            in_subquery_expr_names_resolve(expr, table, table_label, output_aliases)
                && match set {
                    InSet::List(values) => values.iter().all(|value| {
                        in_subquery_expr_names_resolve(value, table, table_label, output_aliases)
                    }),
                    // Nested SELECTs introduce their own name scope. Their
                    // dispatch eligibility is checked by the general recursive
                    // subquery walker.
                    InSet::Subquery(_) | InSet::Table(_) => true,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            in_subquery_expr_names_resolve(expr, table, table_label, output_aliases)
                && in_subquery_expr_names_resolve(pattern, table, table_label, output_aliases)
                && escape.as_deref().is_none_or(|escape| {
                    in_subquery_expr_names_resolve(escape, table, table_label, output_aliases)
                })
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_deref().is_none_or(|operand| {
                in_subquery_expr_names_resolve(operand, table, table_label, output_aliases)
            }) && whens.iter().all(|(when_expr, then_expr)| {
                in_subquery_expr_names_resolve(when_expr, table, table_label, output_aliases)
                    && in_subquery_expr_names_resolve(then_expr, table, table_label, output_aliases)
            }) && else_expr.as_deref().is_none_or(|else_expr| {
                in_subquery_expr_names_resolve(else_expr, table, table_label, output_aliases)
            })
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            ..
        } => {
            (match args {
                FunctionArgs::List(args) => args.iter().all(|arg| {
                    in_subquery_expr_names_resolve(arg, table, table_label, output_aliases)
                }),
                FunctionArgs::Star => true,
            }) && order_by.iter().all(|term| {
                in_subquery_expr_names_resolve(&term.expr, table, table_label, output_aliases)
            }) && filter.as_deref().is_none_or(|filter| {
                in_subquery_expr_names_resolve(filter, table, table_label, output_aliases)
            })
        }
        Expr::JsonAccess { expr, path, .. } => {
            in_subquery_expr_names_resolve(expr, table, table_label, output_aliases)
                && in_subquery_expr_names_resolve(path, table, table_label, output_aliases)
        }
        // Native IN probing has no row-value or RAISE lowering. Let the
        // complete evaluator preserve valid row comparisons and report
        // `row value misused`/RAISE-context errors for invalid shapes.
        Expr::RowValue(_, _) | Expr::Raise { .. } => false,
        Expr::BoundOuterValue { .. }
        | Expr::Exists { .. }
        | Expr::Subquery(_, _)
        | Expr::Literal(_, _)
        | Expr::Placeholder(_, _) => true,
    }
}

/// LIMIT/OFFSET has no row-source name scope. The complex native IN emitter
/// accepts constants/placeholders and scalar function expressions, but must
/// decline any column or nested-query reference for semantic evaluation.
fn in_subquery_limit_expr_is_vdbe_safe(expr: &Expr) -> bool {
    match expr {
        Expr::Column(_, _) | Expr::Subquery(_, _) | Expr::Exists { .. } => false,
        Expr::BinaryOp { left, right, .. } => {
            in_subquery_limit_expr_is_vdbe_safe(left) && in_subquery_limit_expr_is_vdbe_safe(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => in_subquery_limit_expr_is_vdbe_safe(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            in_subquery_limit_expr_is_vdbe_safe(expr)
                && in_subquery_limit_expr_is_vdbe_safe(low)
                && in_subquery_limit_expr_is_vdbe_safe(high)
        }
        Expr::In { expr, set, .. } => {
            in_subquery_limit_expr_is_vdbe_safe(expr)
                && matches!(
                    set,
                    InSet::List(values)
                        if values.iter().all(in_subquery_limit_expr_is_vdbe_safe)
                )
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            in_subquery_limit_expr_is_vdbe_safe(expr)
                && in_subquery_limit_expr_is_vdbe_safe(pattern)
                && escape
                    .as_deref()
                    .is_none_or(in_subquery_limit_expr_is_vdbe_safe)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_none_or(in_subquery_limit_expr_is_vdbe_safe)
                && whens.iter().all(|(when_expr, then_expr)| {
                    in_subquery_limit_expr_is_vdbe_safe(when_expr)
                        && in_subquery_limit_expr_is_vdbe_safe(then_expr)
                })
                && else_expr
                    .as_deref()
                    .is_none_or(in_subquery_limit_expr_is_vdbe_safe)
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            over.is_none()
                && (match args {
                    FunctionArgs::List(args) => {
                        args.iter().all(in_subquery_limit_expr_is_vdbe_safe)
                    }
                    FunctionArgs::Star => true,
                })
                && order_by
                    .iter()
                    .all(|term| in_subquery_limit_expr_is_vdbe_safe(&term.expr))
                && filter
                    .as_deref()
                    .is_none_or(in_subquery_limit_expr_is_vdbe_safe)
        }
        Expr::JsonAccess { expr, path, .. } => {
            in_subquery_limit_expr_is_vdbe_safe(expr) && in_subquery_limit_expr_is_vdbe_safe(path)
        }
        Expr::RowValue(_, _) | Expr::Raise { .. } => false,
        Expr::Literal(_, _) | Expr::BoundOuterValue { .. } | Expr::Placeholder(_, _) => true,
    }
}

fn in_subquery_has_forbidden_outer_reference_position(
    sub: &SelectStatement,
    conn: &Connection,
) -> bool {
    let schema = conn.schema.borrow();
    let group_has_external = std::iter::once(&sub.body.select)
        .chain(sub.body.compounds.iter().map(|(_, core)| core))
        .any(|core| {
            let SelectCore::Select { group_by, .. } = core else {
                return false;
            };
            let output_aliases = collect_select_core_result_aliases(core);
            group_by.iter().any(|expr| {
                expr_has_external_column_ref_with_schema_in_core_and_locals(
                    expr,
                    core,
                    &schema,
                    &output_aliases,
                )
            })
        });
    let output_aliases = collect_select_core_result_aliases(&sub.body.select);
    group_has_external
        || sub.order_by.iter().any(|term| {
            !ordering_term_resolves_to_any_select_output(term, sub)
                && expr_has_external_column_ref_with_schema_in_core_and_locals(
                    &term.expr,
                    &sub.body.select,
                    &schema,
                    &output_aliases,
                )
        })
        || sub.limit.as_ref().is_some_and(|limit| {
            expr_has_external_column_ref_with_schema_in_core(
                &limit.limit,
                &sub.body.select,
                &schema,
            ) || limit.offset.as_ref().is_some_and(|offset| {
                expr_has_external_column_ref_with_schema_in_core(offset, &sub.body.select, &schema)
            })
        })
}

fn ordering_term_resolves_to_any_select_output(
    term: &OrderingTerm,
    select: &SelectStatement,
) -> bool {
    let resolves_in_core = |core: &SelectCore| match core {
        SelectCore::Select { columns, .. } => resolve_order_term_idx(&term.expr, columns).is_some(),
        SelectCore::Values(_) => false,
    };
    resolves_in_core(&select.body.select)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| resolves_in_core(core))
}

/// Check if an IN subquery uses features that VDBE codegen cannot handle
/// in IN-probe expressions (GROUP BY, HAVING, windows, compounds, WITH).
/// These need eager evaluation or VDBE will emit NULL.
fn in_subquery_needs_eager_eval(sub: &SelectStatement, conn: &Connection) -> bool {
    // VDBE rejects compounds and WITH in resolve_in_probe_source
    if sub.with.is_some() || !sub.body.compounds.is_empty() {
        return true;
    }
    // VDBE probe paths project and sort one source row at a time. Aggregate
    // or window expressions in either the result or top-level ORDER BY change
    // the query's row-production semantics and therefore require connection
    // dispatch/eager materialization as a complete SELECT.
    let structural_rejection = matches!(
        &sub.body.select,
        SelectCore::Select {
            group_by, having, windows, ..
        } if !group_by.is_empty()
            || having.is_some()
            || !windows.is_empty()
    );
    if structural_rejection {
        return true;
    }
    let SelectCore::Select {
        columns,
        where_clause,
        ..
    } = &sub.body.select
    else {
        return true;
    };
    columns.iter().any(|column| {
        matches!(
            column,
            ResultColumn::Expr { expr, .. }
                if conn.expr_contains_aggregate_with_registry(expr)
                    || expr_has_window_function(expr)
        )
    }) || where_clause.as_deref().is_some_and(|expr| {
        conn.expr_contains_aggregate_with_registry(expr) || expr_has_window_function(expr)
    }) || sub.order_by.iter().any(|term| {
        conn.expr_contains_aggregate_with_registry(&term.expr)
            || expr_has_window_function(&term.expr)
    }) || sub.limit.as_ref().is_some_and(|limit| {
        conn.expr_contains_aggregate_with_registry(&limit.limit)
            || expr_has_window_function(&limit.limit)
            || limit.offset.as_ref().is_some_and(|offset| {
                conn.expr_contains_aggregate_with_registry(offset)
                    || expr_has_window_function(offset)
            })
    })
}

/// Structural mirror of the VDBE's simple and complex IN-probe admission,
/// minus schema lookup: one plain base table, no joins, one projection, and no
/// feature rejected by both emitters. Only shapes consumed natively may carry
/// placeholders past dispatch routing.
fn in_subquery_matches_native_probe_source_shape(sub: &SelectStatement, conn: &Connection) -> bool {
    if sub.with.is_some() || !sub.body.compounds.is_empty() {
        return false;
    }
    let SelectCore::Select {
        columns,
        from: Some(from),
        group_by,
        having,
        windows,
        ..
    } = &sub.body.select
    else {
        return false;
    };
    if !group_by.is_empty()
        || having.is_some()
        || !windows.is_empty()
        || in_subquery_needs_eager_eval(sub, conn)
        || conn.select_result_column_count(sub, &[], &mut Vec::new()) != 1
    {
        return false;
    }
    if !from.joins.is_empty() {
        return false;
    }
    let TableOrSubquery::Table {
        index_hint,
        time_travel,
        ..
    } = &from.source
    else {
        return false;
    };
    if index_hint.is_some() || time_travel.is_some() {
        return false;
    }
    matches!(
        columns.as_slice(),
        [ResultColumn::Expr { .. } | ResultColumn::Star | ResultColumn::TableStar(_)]
    )
}

fn select_contains_relation_reference(
    select: &SelectStatement,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    if let Some(with_clause) = &select.with
        && with_clause
            .ctes
            .iter()
            .any(|cte| select_contains_relation_reference(&cte.query, predicate))
    {
        return true;
    }

    select_core_contains_relation_reference(&select.body.select, predicate)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_contains_relation_reference(core, predicate))
        || select
            .order_by
            .iter()
            .any(|term| expr_contains_relation_reference(&term.expr, predicate))
        || select
            .limit
            .as_ref()
            .is_some_and(|limit| limit_clause_contains_relation_reference(limit, predicate))
}

fn select_core_contains_relation_reference(
    core: &SelectCore,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    match core {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns.iter().any(|column| match column {
                ResultColumn::Expr { expr, .. } => {
                    expr_contains_relation_reference(expr, predicate)
                }
                ResultColumn::Star | ResultColumn::TableStar(_) => false,
            }) || from.as_ref().is_some_and(|from_clause| {
                from_clause_contains_relation_reference(from_clause, predicate)
            }) || where_clause
                .as_ref()
                .is_some_and(|expr| expr_contains_relation_reference(expr, predicate))
                || group_by
                    .iter()
                    .any(|expr| expr_contains_relation_reference(expr, predicate))
                || having
                    .as_ref()
                    .is_some_and(|expr| expr_contains_relation_reference(expr, predicate))
                || windows
                    .iter()
                    .any(|window| window_contains_relation_reference(window, predicate))
        }
        SelectCore::Values(rows) => rows
            .iter()
            .flatten()
            .any(|expr| expr_contains_relation_reference(expr, predicate)),
    }
}

fn from_clause_contains_relation_reference(
    from: &fsqlite_ast::FromClause,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    table_or_subquery_contains_relation_reference(&from.source, predicate)
        || from.joins.iter().any(|join| {
            table_or_subquery_contains_relation_reference(&join.table, predicate)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr))
                        if expr_contains_relation_reference(expr, predicate)
                )
        })
}

fn table_or_subquery_contains_relation_reference(
    source: &TableOrSubquery,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    match source {
        TableOrSubquery::Table { name, .. } => predicate(name),
        TableOrSubquery::Subquery { query, .. } => {
            select_contains_relation_reference(query, predicate)
        }
        TableOrSubquery::TableFunction { args, .. } => args
            .iter()
            .any(|expr| expr_contains_relation_reference(expr, predicate)),
        TableOrSubquery::ParenJoin(from_clause) => {
            from_clause_contains_relation_reference(from_clause, predicate)
        }
    }
}

fn expr_contains_relation_reference(
    expr: &Expr,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => false,
        Expr::BinaryOp { left, right, .. } => {
            expr_contains_relation_reference(left, predicate)
                || expr_contains_relation_reference(right, predicate)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => expr_contains_relation_reference(expr, predicate),
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_contains_relation_reference(expr, predicate)
                || expr_contains_relation_reference(low, predicate)
                || expr_contains_relation_reference(high, predicate)
        }
        Expr::In { expr, set, .. } => {
            expr_contains_relation_reference(expr, predicate)
                || match set {
                    InSet::List(exprs) => exprs
                        .iter()
                        .any(|item| expr_contains_relation_reference(item, predicate)),
                    InSet::Subquery(subquery) => {
                        select_contains_relation_reference(subquery, predicate)
                    }
                    InSet::Table(name) => predicate(name),
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_contains_relation_reference(expr, predicate)
                || expr_contains_relation_reference(pattern, predicate)
                || escape
                    .as_ref()
                    .is_some_and(|inner| expr_contains_relation_reference(inner, predicate))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_ref()
                .is_some_and(|inner| expr_contains_relation_reference(inner, predicate))
                || whens.iter().any(|(when_expr, then_expr)| {
                    expr_contains_relation_reference(when_expr, predicate)
                        || expr_contains_relation_reference(then_expr, predicate)
                })
                || else_expr
                    .as_ref()
                    .is_some_and(|inner| expr_contains_relation_reference(inner, predicate))
        }
        Expr::Subquery(subquery, _) | Expr::Exists { subquery, .. } => {
            select_contains_relation_reference(subquery, predicate)
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_have_reference = match args {
                FunctionArgs::Star => false,
                FunctionArgs::List(exprs) => exprs
                    .iter()
                    .any(|inner| expr_contains_relation_reference(inner, predicate)),
            };
            args_have_reference
                || order_by
                    .iter()
                    .any(|term| expr_contains_relation_reference(&term.expr, predicate))
                || filter
                    .as_ref()
                    .is_some_and(|inner| expr_contains_relation_reference(inner, predicate))
                || over.as_ref().is_some_and(|window| {
                    window_spec_contains_relation_reference(window, predicate)
                })
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => {
            expr_contains_relation_reference(inner, predicate)
                || expr_contains_relation_reference(path, predicate)
        }
        Expr::RowValue(values, _) => values
            .iter()
            .any(|value| expr_contains_relation_reference(value, predicate)),
    }
}

fn window_contains_relation_reference(
    window: &fsqlite_ast::WindowDef,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    window_spec_contains_relation_reference(&window.spec, predicate)
}

fn window_spec_contains_relation_reference(
    spec: &fsqlite_ast::WindowSpec,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    spec.partition_by
        .iter()
        .any(|expr| expr_contains_relation_reference(expr, predicate))
        || spec
            .order_by
            .iter()
            .any(|term| expr_contains_relation_reference(&term.expr, predicate))
        || spec
            .frame
            .as_ref()
            .is_some_and(|frame| frame_spec_contains_relation_reference(frame, predicate))
}

fn frame_spec_contains_relation_reference(
    frame: &fsqlite_ast::FrameSpec,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    frame_bound_contains_relation_reference(&frame.start, predicate)
        || frame
            .end
            .as_ref()
            .is_some_and(|bound| frame_bound_contains_relation_reference(bound, predicate))
}

fn frame_bound_contains_relation_reference(
    bound: &fsqlite_ast::FrameBound,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    match bound {
        fsqlite_ast::FrameBound::Preceding(expr) | fsqlite_ast::FrameBound::Following(expr) => {
            expr_contains_relation_reference(expr, predicate)
        }
        fsqlite_ast::FrameBound::UnboundedPreceding
        | fsqlite_ast::FrameBound::CurrentRow
        | fsqlite_ast::FrameBound::UnboundedFollowing => false,
    }
}

fn limit_clause_contains_relation_reference(
    limit: &LimitClause,
    predicate: &mut impl FnMut(&QualifiedName) -> bool,
) -> bool {
    expr_contains_relation_reference(&limit.limit, predicate)
        || limit
            .offset
            .as_ref()
            .is_some_and(|expr| expr_contains_relation_reference(expr, predicate))
}

fn qualified_relation_name(name: &QualifiedName) -> Option<&str> {
    match name.schema.as_deref() {
        None => Some(&name.name),
        Some(schema) if is_builtin_schema(schema) => Some(&name.name),
        Some(_) => None,
    }
}

fn qualified_relation_matches_name(name: &QualifiedName, target: &str) -> bool {
    qualified_relation_name(name).is_some_and(|local_name| local_name.eq_ignore_ascii_case(target))
}

fn qualified_relation_matches_unhidden_name(
    name: &QualifiedName,
    target: &str,
    hidden_tables: &HashSet<String>,
) -> bool {
    qualified_relation_matches_name(name, target)
        && !(name.schema.is_none() && hidden_tables.contains(&target.to_ascii_lowercase()))
}

/// Check whether the subquery's FROM clause references an unmaterialized view.
/// VDBE codegen cannot resolve views in IN-probe paths (it only looks in the
/// materialized table schema), so such subqueries must be eagerly evaluated at
/// the connection level where views can be materialized.
fn subquery_references_view(sub: &SelectStatement, conn: &Connection) -> bool {
    if conn.views.borrow().is_empty() {
        return false;
    }
    select_contains_relation_reference(sub, &mut |name| {
        conn.local_view_index_for_relation(name).is_some()
    })
}

fn in_subquery_references_view(sub: &SelectStatement, conn: &Connection) -> bool {
    subquery_references_view(sub, conn)
}

fn subquery_references_sqlite_schema(sub: &SelectStatement, conn: &Connection) -> bool {
    let schema = conn.schema.borrow();
    select_contains_relation_reference(sub, &mut |name| {
        qualified_relation_name(name)
            .and_then(|local_name| {
                canonical_sqlite_schema_name(local_name)
                    .or_else(|| canonical_sqlite_temp_schema_name(local_name))
            })
            .is_some_and(|canonical| {
                !schema
                    .iter()
                    .any(|table| table.name.eq_ignore_ascii_case(canonical))
            })
    })
}

fn in_subquery_references_sqlite_schema(sub: &SelectStatement, conn: &Connection) -> bool {
    subquery_references_sqlite_schema(sub, conn)
}

/// Recursively detect expression forms that the non-IN rewrite pass mutates.
fn expr_contains_rewritable_subquery(expr: &Expr) -> bool {
    matches!(
        expr,
        Expr::In { expr, .. } if matches!(expr.as_ref(), Expr::RowValue(..))
    ) || expr_contains_subquery_match(expr, &mut |_| true)
}

fn statement_requires_in_table_name_rewrite(statement: &Statement) -> bool {
    match statement {
        Statement::Select(select) => select_contains_rewritable_in_table_name(select),
        Statement::Insert(insert) => {
            let source_has_table_name_in = match &insert.source {
                fsqlite_ast::InsertSource::Values(rows) => rows
                    .iter()
                    .flatten()
                    .any(expr_contains_rewritable_in_table_name),
                fsqlite_ast::InsertSource::Select(select) => {
                    select_contains_rewritable_in_table_name(select)
                }
                fsqlite_ast::InsertSource::DefaultValues => false,
            };
            source_has_table_name_in
                || insert.upsert.iter().any(|upsert| {
                    upsert
                        .target
                        .as_ref()
                        .and_then(|target| target.where_clause.as_ref())
                        .is_some_and(expr_contains_rewritable_in_table_name)
                        || match &upsert.action {
                            fsqlite_ast::UpsertAction::Nothing => false,
                            fsqlite_ast::UpsertAction::Update {
                                assignments,
                                where_clause,
                            } => {
                                assignments.iter().any(|assignment| {
                                    expr_contains_rewritable_in_table_name(&assignment.value)
                                }) || where_clause.as_ref().is_some_and(|expr| {
                                    expr_contains_rewritable_in_table_name(expr)
                                })
                            }
                        }
                })
                || insert.returning.iter().any(|column| match column {
                    ResultColumn::Expr { expr, .. } => expr_contains_rewritable_in_table_name(expr),
                    ResultColumn::Star | ResultColumn::TableStar(_) => false,
                })
        }
        Statement::Update(update) => update_contains_rewritable_in_table_name(update),
        Statement::Delete(delete) => delete_contains_rewritable_in_table_name(delete),
        _ => false,
    }
}

fn update_contains_rewritable_in_table_name(update: &fsqlite_ast::UpdateStatement) -> bool {
    update
        .assignments
        .iter()
        .any(|assignment| expr_contains_rewritable_in_table_name(&assignment.value))
        || update
            .from
            .as_ref()
            .is_some_and(from_clause_contains_rewritable_in_table_name)
        || update
            .where_clause
            .as_ref()
            .is_some_and(expr_contains_rewritable_in_table_name)
        || update.returning.iter().any(|column| match column {
            ResultColumn::Expr { expr, .. } => expr_contains_rewritable_in_table_name(expr),
            ResultColumn::Star | ResultColumn::TableStar(_) => false,
        })
        || update
            .order_by
            .iter()
            .any(|term| expr_contains_rewritable_in_table_name(&term.expr))
        || update
            .limit
            .as_ref()
            .is_some_and(limit_clause_contains_rewritable_in_table_name)
}

fn delete_contains_rewritable_in_table_name(delete: &fsqlite_ast::DeleteStatement) -> bool {
    delete
        .where_clause
        .as_ref()
        .is_some_and(expr_contains_rewritable_in_table_name)
        || delete.returning.iter().any(|column| match column {
            ResultColumn::Expr { expr, .. } => expr_contains_rewritable_in_table_name(expr),
            ResultColumn::Star | ResultColumn::TableStar(_) => false,
        })
        || delete
            .order_by
            .iter()
            .any(|term| expr_contains_rewritable_in_table_name(&term.expr))
        || delete
            .limit
            .as_ref()
            .is_some_and(limit_clause_contains_rewritable_in_table_name)
}

fn from_clause_contains_rewritable_in_table_name(from: &fsqlite_ast::FromClause) -> bool {
    table_or_subquery_contains_rewritable_in_table_name(&from.source)
        || from.joins.iter().any(|join| {
            table_or_subquery_contains_rewritable_in_table_name(&join.table)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr))
                        if expr_contains_rewritable_in_table_name(expr)
                )
        })
}

fn table_or_subquery_contains_rewritable_in_table_name(source: &TableOrSubquery) -> bool {
    match source {
        TableOrSubquery::Table { .. } => false,
        TableOrSubquery::Subquery { query, .. } => select_contains_rewritable_in_table_name(query),
        TableOrSubquery::TableFunction { args, .. } => {
            args.iter().any(expr_contains_rewritable_in_table_name)
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            from_clause_contains_rewritable_in_table_name(from_clause)
        }
    }
}

fn select_contains_rewritable_in_table_name(select: &SelectStatement) -> bool {
    select_core_contains_rewritable_in_table_name(&select.body.select)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_contains_rewritable_in_table_name(core))
        || select
            .order_by
            .iter()
            .any(|term| expr_contains_rewritable_in_table_name(&term.expr))
        || select
            .limit
            .as_ref()
            .is_some_and(limit_clause_contains_rewritable_in_table_name)
}

fn select_core_contains_rewritable_in_table_name(core: &SelectCore) -> bool {
    match core {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns.iter().any(|column| match column {
                ResultColumn::Expr { expr, .. } => expr_contains_rewritable_in_table_name(expr),
                ResultColumn::Star | ResultColumn::TableStar(_) => false,
            }) || from
                .as_ref()
                .is_some_and(from_clause_contains_rewritable_in_table_name)
                || where_clause
                    .as_ref()
                    .is_some_and(|expr| expr_contains_rewritable_in_table_name(expr))
                || group_by.iter().any(expr_contains_rewritable_in_table_name)
                || having
                    .as_ref()
                    .is_some_and(|expr| expr_contains_rewritable_in_table_name(expr))
                || windows
                    .iter()
                    .any(window_spec_contains_rewritable_in_table_name)
        }
        SelectCore::Values(rows) => rows
            .iter()
            .flatten()
            .any(expr_contains_rewritable_in_table_name),
    }
}

fn window_spec_contains_rewritable_in_table_name(window: &fsqlite_ast::WindowDef) -> bool {
    window
        .spec
        .partition_by
        .iter()
        .any(expr_contains_rewritable_in_table_name)
        || window
            .spec
            .order_by
            .iter()
            .any(|term| expr_contains_rewritable_in_table_name(&term.expr))
        || window
            .spec
            .frame
            .as_ref()
            .is_some_and(frame_spec_contains_rewritable_in_table_name)
}

fn frame_spec_contains_rewritable_in_table_name(frame: &FrameSpec) -> bool {
    frame_bound_contains_rewritable_in_table_name(&frame.start)
        || frame
            .end
            .as_ref()
            .is_some_and(frame_bound_contains_rewritable_in_table_name)
}

fn frame_bound_contains_rewritable_in_table_name(bound: &FrameBound) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_contains_rewritable_in_table_name(expr)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn limit_clause_contains_rewritable_in_table_name(limit: &LimitClause) -> bool {
    expr_contains_rewritable_in_table_name(&limit.limit)
        || limit
            .offset
            .as_ref()
            .is_some_and(expr_contains_rewritable_in_table_name)
}

fn expr_contains_rewritable_in_table_name(expr: &Expr) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => false,
        Expr::BinaryOp { left, right, .. } => {
            expr_contains_rewritable_in_table_name(left)
                || expr_contains_rewritable_in_table_name(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => expr_contains_rewritable_in_table_name(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_contains_rewritable_in_table_name(expr)
                || expr_contains_rewritable_in_table_name(low)
                || expr_contains_rewritable_in_table_name(high)
        }
        Expr::In { expr, set, .. } => {
            expr_contains_rewritable_in_table_name(expr)
                || match set {
                    InSet::List(exprs) => exprs.iter().any(expr_contains_rewritable_in_table_name),
                    InSet::Table(_) => true,
                    InSet::Subquery(_) => false,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_contains_rewritable_in_table_name(expr)
                || expr_contains_rewritable_in_table_name(pattern)
                || escape
                    .as_ref()
                    .is_some_and(|inner| expr_contains_rewritable_in_table_name(inner))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_ref()
                .is_some_and(|inner| expr_contains_rewritable_in_table_name(inner))
                || whens.iter().any(|(when_expr, then_expr)| {
                    expr_contains_rewritable_in_table_name(when_expr)
                        || expr_contains_rewritable_in_table_name(then_expr)
                })
                || else_expr
                    .as_ref()
                    .is_some_and(|inner| expr_contains_rewritable_in_table_name(inner))
        }
        Expr::Subquery(_, _) | Expr::Exists { .. } => false,
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_have_table_name_set = match args {
                FunctionArgs::Star => false,
                FunctionArgs::List(exprs) => {
                    exprs.iter().any(expr_contains_rewritable_in_table_name)
                }
            };
            args_have_table_name_set
                || order_by
                    .iter()
                    .any(|term| expr_contains_rewritable_in_table_name(&term.expr))
                || filter
                    .as_ref()
                    .is_some_and(|inner| expr_contains_rewritable_in_table_name(inner))
                || over.as_ref().is_some_and(|window| {
                    window
                        .partition_by
                        .iter()
                        .any(expr_contains_rewritable_in_table_name)
                        || window
                            .order_by
                            .iter()
                            .any(|term| expr_contains_rewritable_in_table_name(&term.expr))
                        || window.frame.as_ref().is_some_and(|frame| {
                            frame_bound_contains_rewritable_in_table_name(&frame.start)
                                || frame
                                    .end
                                    .as_ref()
                                    .is_some_and(frame_bound_contains_rewritable_in_table_name)
                        })
                })
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => {
            expr_contains_rewritable_in_table_name(inner)
                || expr_contains_rewritable_in_table_name(path)
        }
        Expr::RowValue(values, _) => values.iter().any(expr_contains_rewritable_in_table_name),
    }
}

struct SharedRuntimeState {
    key: SharedMvccKey,
    regions: RegionTree,
    db_root_region: Region,
    write_coordinator_region: Region,
    write_coordinator_service_starting: bool,
    write_coordinator_service_running: bool,
    #[cfg_attr(any(target_arch = "wasm32", not(feature = "native")), allow(dead_code))]
    write_coordinator_service_generation: u64,
    #[cfg_attr(any(target_arch = "wasm32", not(feature = "native")), allow(dead_code))]
    write_coordinator_service_launch_count: u64,
    write_coordinator_shutdown: Option<WriteCoordinatorShutdownTx>,
    open_connections: usize,
    poisoned: Option<String>,
}

#[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
struct WriteCoordinatorServiceStart {
    generation: u64,
    path_key: String,
}

#[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
enum WriteCoordinatorServiceReservation {
    Running,
    Starting,
    Reserved(WriteCoordinatorServiceStart),
}

#[derive(Clone, PartialEq, Eq, Hash)]
struct SharedMvccKey {
    path_key: String,
    file_identity: Option<FileIdentity>,
    runtime_id: u64,
}

impl SharedMvccKey {
    fn new(
        path_key: String,
        file_identity: Option<FileIdentity>,
        runtime: &RuntimeContext,
    ) -> Self {
        Self {
            path_key,
            file_identity,
            runtime_id: runtime.runtime_id(),
        }
    }
}

/// Process-wide MVCC coordination for one file-backed database identity.
///
/// Runtime regions and background services remain isolated per
/// [`RuntimeContext`], but page ownership, FCW publication, rowid allocation,
/// and commit clocks must be shared by every connection to the same file.
/// Keying those data-plane structures by runtime let connections created on
/// separate thread-local runtimes silently bypass one another's page locks.
struct SharedMvccCoordinationState {
    registry: Arc<Mutex<ConcurrentRegistry>>,
    conflict_observer: Arc<MetricsObserver>,
    connection_pool_registry: Arc<SharedConnectionPoolRegistry>,
    lock_table: Arc<InProcessPageLockTable>,
    commit_index: Arc<CommitIndex>,
    rowid_allocator: Arc<ConcurrentRowIdAllocator>,
    active_commit_seqs: Arc<Mutex<smallvec::SmallVec<[u64; 16]>>>,
    next_commit_seq: Arc<AtomicU64>,
    stable_commit_seq: Arc<AtomicU64>,
    committed_schema_cookie: Arc<AtomicU32>,
    open_connection_count: Arc<AtomicUsize>,
    /// bd-pragma-data-version-approximation-b3dpn: shared count of write commits
    /// across every connection to this database. `PRAGMA data_version` returns
    /// this minus the reading connection's own write-commit count, so it moves
    /// only when ANOTHER connection commits (stock semantics).
    data_version_global: Arc<AtomicU64>,
}

impl SharedMvccCoordinationState {
    fn new() -> Self {
        let conflict_observer = Arc::new(MetricsObserver::new(1024));
        Self {
            registry: Arc::new(Mutex::new(ConcurrentRegistry::new())),
            conflict_observer: Arc::clone(&conflict_observer),
            connection_pool_registry: Arc::new(SharedConnectionPoolRegistry::new()),
            lock_table: Arc::new(InProcessPageLockTable::with_observer(
                conflict_observer as Arc<dyn fsqlite_observability::ConflictObserver>,
            )),
            commit_index: Arc::new(CommitIndex::new()),
            rowid_allocator: Arc::new(ConcurrentRowIdAllocator::new(SchemaEpoch::ZERO)),
            active_commit_seqs: Arc::new(Mutex::new(smallvec::SmallVec::new())),
            next_commit_seq: Arc::new(AtomicU64::new(1)),
            stable_commit_seq: Arc::new(AtomicU64::new(0)),
            committed_schema_cookie: Arc::new(AtomicU32::new(0)),
            open_connection_count: Arc::new(AtomicUsize::new(0)),
            data_version_global: Arc::new(AtomicU64::new(0)),
        }
    }
}

struct SharedMvccState {
    registry: Arc<Mutex<ConcurrentRegistry>>,
    conflict_observer: Arc<MetricsObserver>,
    connection_pool_registry: Arc<SharedConnectionPoolRegistry>,
    lock_table: Arc<InProcessPageLockTable>,
    commit_index: Arc<CommitIndex>,
    rowid_allocator: Arc<ConcurrentRowIdAllocator>,
    active_commit_seqs: Arc<Mutex<smallvec::SmallVec<[u64; 16]>>>,
    next_commit_seq: Arc<AtomicU64>,
    stable_commit_seq: Arc<AtomicU64>,
    committed_schema_cookie: Arc<AtomicU32>,
    open_connection_count: Arc<AtomicUsize>,
    data_version_global: Arc<AtomicU64>,
    _coordination: Arc<SharedMvccCoordinationState>,
    _runtime: Arc<RuntimeContext>,
    runtime_state: Mutex<SharedRuntimeState>,
    /// Fast-path poison check: single atomic load instead of mutex lock.
    /// Set to `true` when a background worker reports a fatal error.
    /// `background_status()` checks this first and only acquires the
    /// mutex when the flag is set (to read the error details).
    is_poisoned: AtomicBool,
}

impl SharedMvccState {
    fn new(
        key: SharedMvccKey,
        runtime: Arc<RuntimeContext>,
        coordination: Arc<SharedMvccCoordinationState>,
    ) -> Result<Self> {
        let mut regions = RegionTree::new();
        let db_root_cx = runtime
            .root_cx
            .create_child()
            .with_trace_context(next_trace_id(), 0, 0);
        let db_root_region = regions.create_root(RegionKind::DbRoot, db_root_cx)?;
        let write_coordinator_cx = regions
            .cx(db_root_region)
            .ok_or_else(|| FrankenError::internal("database root region missing Cx"))?
            .create_child()
            .with_trace_context(next_trace_id(), 0, 0);
        let write_coordinator_region = regions.create_child(
            db_root_region,
            RegionKind::WriteCoordinator,
            write_coordinator_cx,
        )?;

        tracing::info!(
            target: "fsqlite::runtime",
            event = "region_created",
            db_path = %key.path_key,
            region_id = db_root_region.get(),
            region_kind = "db_root"
        );
        tracing::info!(
            target: "fsqlite::runtime",
            event = "region_created",
            db_path = %key.path_key,
            region_id = write_coordinator_region.get(),
            region_kind = "write_coordinator"
        );

        Ok(Self {
            registry: Arc::clone(&coordination.registry),
            conflict_observer: Arc::clone(&coordination.conflict_observer),
            connection_pool_registry: Arc::clone(&coordination.connection_pool_registry),
            lock_table: Arc::clone(&coordination.lock_table),
            commit_index: Arc::clone(&coordination.commit_index),
            rowid_allocator: Arc::clone(&coordination.rowid_allocator),
            active_commit_seqs: Arc::clone(&coordination.active_commit_seqs),
            next_commit_seq: Arc::clone(&coordination.next_commit_seq),
            stable_commit_seq: Arc::clone(&coordination.stable_commit_seq),
            committed_schema_cookie: Arc::clone(&coordination.committed_schema_cookie),
            open_connection_count: Arc::clone(&coordination.open_connection_count),
            data_version_global: Arc::clone(&coordination.data_version_global),
            _coordination: coordination,
            _runtime: runtime,
            runtime_state: Mutex::new(SharedRuntimeState {
                key,
                regions,
                db_root_region,
                write_coordinator_region,
                write_coordinator_service_starting: false,
                write_coordinator_service_running: false,
                write_coordinator_service_generation: 0,
                write_coordinator_service_launch_count: 0,
                write_coordinator_shutdown: None,
                open_connections: 0,
                poisoned: None,
            }),
            is_poisoned: AtomicBool::new(false),
        })
    }

    #[inline]
    fn align_commit_clock_floor(&self, visible_commit_seq: CommitSeq) {
        self.stable_commit_seq
            .fetch_max(visible_commit_seq.get(), AtomicOrdering::Release);
        self.next_commit_seq.fetch_max(
            visible_commit_seq.get().saturating_add(1),
            AtomicOrdering::AcqRel,
        );
    }

    fn shared_open_connection_count(&self) -> Arc<AtomicUsize> {
        Arc::clone(&self.open_connection_count)
    }

    fn register_connection_pool_metrics(&self) -> Arc<ConnectionPoolLiveMetrics> {
        self.connection_pool_registry.register_connection()
    }

    fn release_connection_pool_metrics(&self, connection_id: u64) {
        self.connection_pool_registry
            .release_connection(connection_id);
    }

    fn note_connection_prepare(&self, metrics: &ConnectionPoolLiveMetrics) {
        metrics.note_prepare(self.connection_pool_registry.now_ms());
    }

    fn note_connection_statement_execution_count(
        &self,
        metrics: &ConnectionPoolLiveMetrics,
        count: usize,
    ) {
        if metrics.note_statement_execution_count_should_refresh_activity(count) {
            metrics.note_activity(self.connection_pool_registry.now_ms());
        }
    }

    fn note_connection_transaction_started(&self, metrics: &ConnectionPoolLiveMetrics) {
        metrics.note_transaction_started(self.connection_pool_registry.now_ms());
    }

    fn note_connection_transaction_finished(&self, metrics: &ConnectionPoolLiveMetrics) {
        metrics.note_transaction_finished(self.connection_pool_registry.now_ms());
    }

    #[cfg(feature = "diagnostic-pragmas")]
    fn connection_pool_snapshot(&self) -> ConnectionPoolRegistrySnapshot {
        self.connection_pool_registry.snapshot()
    }

    fn background_status(&self) -> Result<()> {
        let profile_enabled = hot_path_profile_enabled();
        let start = profile_enabled.then(Instant::now);
        if profile_enabled {
            FSQLITE_BACKGROUND_STATUS_CHECKS.fetch_add(1, AtomicOrdering::Relaxed);
        }
        // Fast path: single atomic load avoids mutex lock on every statement.
        // is_poisoned is only set when a background worker reports a fatal
        // error — on the normal hot path this is a single cache-line read.
        let result = if !self.is_poisoned.load(AtomicOrdering::Relaxed) {
            Ok(())
        } else {
            let state = lock_unpoisoned(&self.runtime_state);
            match &state.poisoned {
                Some(details) => Err(FrankenError::BackgroundWorkerFailed(details.clone())),
                None => Ok(()),
            }
        };
        if profile_enabled {
            record_hot_path_duration(&FSQLITE_BACKGROUND_STATUS_TIME_NS, start);
        }
        result
    }

    fn register_connection(&self) -> Result<(Region, Cx)> {
        let mut state = lock_unpoisoned(&self.runtime_state);
        if let Some(details) = &state.poisoned {
            return Err(FrankenError::BackgroundWorkerFailed(details.clone()));
        }

        let db_root_cx = state
            .regions
            .cx(state.db_root_region)
            .ok_or_else(|| FrankenError::internal("database root region missing Cx"))?;
        let db_root_region = state.db_root_region;
        let connection_cx = db_root_cx
            .create_child()
            .with_trace_context(next_trace_id(), 0, 0);
        let connection_region = state.regions.create_child(
            db_root_region,
            RegionKind::PerConnection,
            connection_cx.clone(),
        )?;
        state.open_connections = state.open_connections.saturating_add(1);
        self.open_connection_count
            .fetch_add(1, AtomicOrdering::Release);

        tracing::info!(
            target: "fsqlite::runtime",
            event = "region_created",
            db_path = %state.key.path_key,
            region_id = connection_region.get(),
            region_kind = "per_connection"
        );

        Ok((connection_region, connection_cx))
    }

    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    fn reserve_write_coordinator_service_start(
        &self,
    ) -> Result<WriteCoordinatorServiceReservation> {
        let mut state = lock_unpoisoned(&self.runtime_state);
        if let Some(details) = &state.poisoned {
            return Err(FrankenError::BackgroundWorkerFailed(details.clone()));
        }

        if state.write_coordinator_service_running
            && state.regions.active_tasks(state.write_coordinator_region) == 0
        {
            state.write_coordinator_service_running = false;
            state.write_coordinator_shutdown = None;
        }

        if state.write_coordinator_service_running {
            return Ok(WriteCoordinatorServiceReservation::Running);
        }

        if state.write_coordinator_service_starting {
            return Ok(WriteCoordinatorServiceReservation::Starting);
        }

        state.write_coordinator_service_starting = true;
        state.write_coordinator_service_generation =
            state.write_coordinator_service_generation.saturating_add(1);
        Ok(WriteCoordinatorServiceReservation::Reserved(
            WriteCoordinatorServiceStart {
                generation: state.write_coordinator_service_generation,
                path_key: state.key.path_key.clone(),
            },
        ))
    }

    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    fn revert_write_coordinator_service_start(&self, reservation: &WriteCoordinatorServiceStart) {
        let mut state = lock_unpoisoned(&self.runtime_state);
        if !state.write_coordinator_service_starting
            || state.write_coordinator_service_generation != reservation.generation
        {
            return;
        }

        state.write_coordinator_service_starting = false;
        state.write_coordinator_service_running = false;
        state.write_coordinator_shutdown = None;
    }

    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    fn record_write_coordinator_service_launch(
        &self,
        reservation: &WriteCoordinatorServiceStart,
        shutdown: WriteCoordinatorShutdownTx,
    ) {
        let mut state = lock_unpoisoned(&self.runtime_state);
        if !state.write_coordinator_service_starting
            || state.write_coordinator_service_generation != reservation.generation
        {
            return;
        }

        state.write_coordinator_service_starting = false;
        state.write_coordinator_service_running = true;
        state.write_coordinator_service_launch_count = state
            .write_coordinator_service_launch_count
            .saturating_add(1);
        state.write_coordinator_shutdown = Some(shutdown);
    }

    #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
    fn ensure_write_coordinator_service_started(&self) -> Result<()> {
        let wait_deadline = Instant::now()
            + if cfg!(test) {
                Duration::from_millis(100)
            } else {
                Duration::from_secs(1)
            };

        let reservation = loop {
            match self.reserve_write_coordinator_service_start()? {
                WriteCoordinatorServiceReservation::Running => return Ok(()),
                WriteCoordinatorServiceReservation::Reserved(start) => break start,
                WriteCoordinatorServiceReservation::Starting => {
                    if Instant::now() >= wait_deadline {
                        return Err(FrankenError::internal(
                            "write coordinator service start timed out while another launcher remained in Starting state",
                        ));
                    }
                    std::hint::spin_loop();
                    #[cfg(not(target_arch = "wasm32"))]
                    std::thread::yield_now();
                    #[cfg(not(target_arch = "wasm32"))]
                    std::thread::sleep(Duration::from_millis(1));
                }
            }
        };

        let (shutdown_tx, mut shutdown_rx) = asupersync::channel::oneshot::channel::<()>();
        let task_path_key = reservation.path_key.clone();
        let launched = match self.try_spawn_write_coordinator_task(move |task_cx| async move {
            let Some(native_task_cx) = task_cx.attached_native_cx() else {
                tracing::error!(
                    target: "fsqlite::runtime",
                    bead_id = WRITE_COORDINATOR_SERVICE_BEAD_ID,
                    event = "write_coordinator_service_missing_native_cx",
                    db_path = %task_path_key
                );
                return;
            };

            tracing::info!(
                target: "fsqlite::runtime",
                bead_id = WRITE_COORDINATOR_SERVICE_BEAD_ID,
                event = "write_coordinator_service_started",
                db_path = %task_path_key
            );

            match shutdown_rx.recv(&native_task_cx).await {
                Ok(())
                | Err(
                    asupersync::channel::oneshot::RecvError::Closed
                    | asupersync::channel::oneshot::RecvError::Cancelled,
                ) => {}
                Err(asupersync::channel::oneshot::RecvError::PolledAfterCompletion) => {
                    tracing::warn!(
                        target: "fsqlite::runtime",
                        bead_id = WRITE_COORDINATOR_SERVICE_BEAD_ID,
                        event = "write_coordinator_service_invalid_recv_state",
                        db_path = %task_path_key
                    );
                }
            }

            let _ = task_cx.checkpoint_with("write coordinator service shutdown");
            tracing::info!(
                target: "fsqlite::runtime",
                bead_id = WRITE_COORDINATOR_SERVICE_BEAD_ID,
                event = "write_coordinator_service_stopped",
                db_path = %task_path_key
            );
        }) {
            Ok(launched) => launched,
            Err(err) => {
                self.revert_write_coordinator_service_start(&reservation);
                return Err(err);
            }
        };

        if launched {
            self.record_write_coordinator_service_launch(&reservation, shutdown_tx);
        } else {
            self.revert_write_coordinator_service_start(&reservation);
            tracing::debug!(
                target: "fsqlite::runtime",
                bead_id = WRITE_COORDINATOR_SERVICE_BEAD_ID,
                event = "write_coordinator_service_deferred",
                db_path = %reservation.path_key
            );
        }

        Ok(())
    }

    #[cfg(any(target_arch = "wasm32", not(feature = "native")))]
    fn ensure_write_coordinator_service_started(&self) -> Result<()> {
        Ok(())
    }

    #[cfg_attr(not(test), allow(dead_code))]
    fn register_write_coordinator_task(&self) -> Result<(TaskHandle, Cx)> {
        let state = lock_unpoisoned(&self.runtime_state);
        if let Some(details) = &state.poisoned {
            return Err(FrankenError::BackgroundWorkerFailed(details.clone()));
        }

        let region = state.write_coordinator_region;
        let task = state.regions.register_task(region)?;
        let cx = state
            .regions
            .cx(region)
            .ok_or_else(|| FrankenError::internal("write coordinator region missing Cx"))?
            .create_child();
        Ok((task, cx))
    }

    fn try_spawn_write_coordinator_task<F, Fut>(&self, task: F) -> Result<bool>
    where
        F: FnOnce(Cx) -> Fut + Send + 'static,
        Fut: Future<Output = ()> + Send + 'static,
    {
        #[cfg(any(target_arch = "wasm32", not(feature = "native")))]
        {
            let _ = task;
            return Ok(false);
        }

        #[cfg(all(not(target_arch = "wasm32"), feature = "native"))]
        {
            let Some(runtime_handle) = self._runtime.native_runtime_handle() else {
                return Ok(false);
            };
            let (region_task, task_cx) = self.register_write_coordinator_task()?;
            runtime_handle
                .try_spawn(async move {
                    let _region_task = region_task;
                    if let Some(native_task_cx) = asupersync::Cx::current() {
                        task_cx.set_native_cx(native_task_cx);
                    }
                    if task_cx.checkpoint().is_err() {
                        return;
                    }
                    task(task_cx).await;
                })
                .map_err(|err| {
                    FrankenError::internal(format!(
                        "failed to spawn write coordinator task on active asupersync runtime: {err}"
                    ))
                })?;
            Ok(true)
        }
    }

    #[cfg_attr(not(test), allow(dead_code))]
    fn spawn_write_coordinator_task<F, Fut>(&self, task: F) -> Result<()>
    where
        F: FnOnce(Cx) -> Fut + Send + 'static,
        Fut: Future<Output = ()> + Send + 'static,
    {
        if self.try_spawn_write_coordinator_task(task)? {
            return Ok(());
        }

        Err(FrankenError::internal(
            "write coordinator tasks require an active asupersync runtime",
        ))
    }

    /// Drop-path analog of [`Self::release_connection`]: request cancellation
    /// everywhere that teardown would drain, without ever blocking.
    ///
    /// `RegionTree::begin_close` cancels a region's `Cx` and propagates to
    /// descendant regions, but explicitly does not wait for quiescence.
    /// `release_connection` (which calls `close_and_drain`) spin-waits and
    /// therefore must not run on the drop path.
    ///
    /// Without this, a `Connection` dropped without an awaited `close()` leaks
    /// every task spawned into its region: nothing ever cancels their `Cx`, so
    /// a task looping on `cx.checkpoint()` spins for the lifetime of the
    /// process. Cancelling only the per-connection region is not enough: the
    /// shared write-coordinator service task lives under the database *root*
    /// region, so dropping the last connection must also cancel the root.
    ///
    /// Mirrors the bookkeeping of `release_connection`: decrements the
    /// open-connection count, and on the last connection clears the
    /// write-coordinator service state (dropping the shutdown sender wakes the
    /// service's shutdown listener), cancels the database root region, and
    /// removes the shared-state map entry so a future `open` builds a fresh
    /// generation instead of trying to join a closing region tree.
    fn release_connection_on_drop(&self, connection_region: Region) {
        let mut state = lock_unpoisoned(&self.runtime_state);
        if let Err(err) = state.regions.begin_close(connection_region) {
            tracing::debug!(
                target: "fsqlite::runtime",
                event = "region_cancel_request_failed",
                region_id = connection_region.get(),
                error = %err,
                "could not request region cancellation during drop"
            );
        }
        if state.open_connections > 0 {
            state.open_connections -= 1;
            self.open_connection_count
                .fetch_sub(1, AtomicOrdering::Release);
        }
        if state.open_connections == 0 {
            state.write_coordinator_service_starting = false;
            state.write_coordinator_service_running = false;
            let _ = state.write_coordinator_shutdown.take();
            let db_root_region = state.db_root_region;
            if let Err(err) = state.regions.begin_close(db_root_region) {
                tracing::debug!(
                    target: "fsqlite::runtime",
                    event = "region_cancel_request_failed",
                    region_id = db_root_region.get(),
                    error = %err,
                    "could not request database-root region cancellation during drop"
                );
            }
            if state.key.path_key != ":memory:"
                && let Some(state_map) = SHARED_MVCC_STATE_BY_PATH.get()
            {
                lock_unpoisoned(state_map).remove(&state.key);
            }
        }
    }

    fn release_connection(&self, connection_region: Region, best_effort: bool) -> Result<()> {
        let mut state = lock_unpoisoned(&self.runtime_state);

        let connection_close_started = Instant::now();
        tracing::info!(
            target: "fsqlite::runtime",
            event = "region_closing",
            db_path = %state.key.path_key,
            region_id = connection_region.get(),
            active_tasks = state.regions.active_tasks(connection_region)
        );
        if let Err(err) = state.regions.close_and_drain(connection_region) {
            tracing::warn!(
                target: "fsqlite::runtime",
                event = "region_close_failed",
                db_path = %state.key.path_key,
                region_id = connection_region.get(),
                error = %err
            );
            if !best_effort {
                return Err(err);
            }
        }
        if state.open_connections > 0 {
            state.open_connections -= 1;
            self.open_connection_count
                .fetch_sub(1, AtomicOrdering::Release);
        }
        tracing::info!(
            target: "fsqlite::runtime",
            event = "region_closed",
            db_path = %state.key.path_key,
            region_id = connection_region.get(),
            elapsed_ms = u64::try_from(connection_close_started.elapsed().as_millis())
                .unwrap_or(u64::MAX)
        );

        if state.open_connections == 0 {
            state.write_coordinator_service_starting = false;
            state.write_coordinator_service_running = false;
            let _ = state.write_coordinator_shutdown.take();
            let db_root_region = state.db_root_region;
            let root_close_started = Instant::now();
            tracing::info!(
                target: "fsqlite::runtime",
                event = "region_closing",
                db_path = %state.key.path_key,
                region_id = db_root_region.get(),
                active_tasks = state.regions.active_tasks(db_root_region)
            );
            if let Err(err) = state.regions.close_and_drain(db_root_region) {
                tracing::warn!(
                    target: "fsqlite::runtime",
                    event = "region_close_failed",
                    db_path = %state.key.path_key,
                    region_id = db_root_region.get(),
                    error = %err
                );
                if !best_effort {
                    return Err(err);
                }
            }
            tracing::info!(
                target: "fsqlite::runtime",
                event = "region_closed",
                db_path = %state.key.path_key,
                region_id = db_root_region.get(),
                elapsed_ms = u64::try_from(root_close_started.elapsed().as_millis())
                    .unwrap_or(u64::MAX)
            );

            if state.key.path_key != ":memory:"
                && let Some(state_map) = SHARED_MVCC_STATE_BY_PATH.get()
            {
                lock_unpoisoned(state_map).remove(&state.key);
            }
        }

        Ok(())
    }

    #[cfg_attr(not(test), allow(dead_code))]
    fn poison(&self, details: impl Into<String>) {
        let details = details.into();
        let mut state = lock_unpoisoned(&self.runtime_state);
        if state.poisoned.is_some() {
            return;
        }

        state.poisoned = Some(details.clone());
        self.is_poisoned.store(true, AtomicOrdering::Release);
        if let Some(db_root_cx) = state.regions.cx(state.db_root_region) {
            db_root_cx.cancel_with_reason(CancelReason::Abort);
        }
        tracing::error!(
            target: "fsqlite::runtime",
            event = "poisoned",
            db_path = %state.key.path_key,
            cause = %details
        );
    }
}

static SHARED_MVCC_STATE_BY_PATH: OnceLock<Mutex<HashMap<SharedMvccKey, Weak<SharedMvccState>>>> =
    OnceLock::new();
static SHARED_MVCC_COORDINATION: OnceLock<
    Mutex<HashMap<SharedMvccCoordinationKey, Weak<SharedMvccCoordinationState>>>,
> = OnceLock::new();

#[derive(Clone, PartialEq, Eq, Hash)]
enum SharedMvccCoordinationKey {
    File(FileIdentity),
    Path(String),
}

fn lock_unpoisoned<T>(mutex: &Mutex<T>) -> std::sync::MutexGuard<'_, T> {
    mutex
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
}

/// Registry guard for the validate → physical write → publish commit window.
///
/// The wait sample is recorded immediately after lock acquisition. The hold
/// sample is recorded by `Drop`, so every exit path that releases the guard is
/// accounted exactly once, including commit errors and early returns.
struct TimedRegistryCommitGuard<'a> {
    guard: std::sync::MutexGuard<'a, ConcurrentRegistry>,
    acquired_at: Instant,
}

impl std::ops::Deref for TimedRegistryCommitGuard<'_> {
    type Target = ConcurrentRegistry;

    fn deref(&self) -> &Self::Target {
        &self.guard
    }
}

impl std::ops::DerefMut for TimedRegistryCommitGuard<'_> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.guard
    }
}

impl Drop for TimedRegistryCommitGuard<'_> {
    fn drop(&mut self) {
        let hold_ns = u64::try_from(self.acquired_at.elapsed().as_nanos()).unwrap_or(u64::MAX);
        record_registry_commit_lock_hold(hold_ns);
    }
}

fn lock_registry_for_commit(registry: &Mutex<ConcurrentRegistry>) -> TimedRegistryCommitGuard<'_> {
    let wait_started = Instant::now();
    let guard = lock_unpoisoned(registry);
    let wait_ns = u64::try_from(wait_started.elapsed().as_nanos()).unwrap_or(u64::MAX);
    record_registry_commit_lock_wait(wait_ns);
    TimedRegistryCommitGuard {
        guard,
        // Start the hold clock after publishing the wait sample so the two
        // intervals remain disjoint.
        acquired_at: Instant::now(),
    }
}

fn mvcc_state_path_key(path: &str) -> String {
    if path == ":memory:" {
        return path.to_owned();
    }
    std::fs::canonicalize(path)
        .unwrap_or_else(|_| PathBuf::from(path))
        .to_string_lossy()
        .into_owned()
}

fn shared_mvcc_coordination_for_file(
    path_key: &str,
    file_identity: Option<FileIdentity>,
) -> Arc<SharedMvccCoordinationState> {
    let key = file_identity.map_or_else(
        || SharedMvccCoordinationKey::Path(path_key.to_owned()),
        SharedMvccCoordinationKey::File,
    );
    let coordination_map = SHARED_MVCC_COORDINATION.get_or_init(|| Mutex::new(HashMap::new()));
    let mut map = lock_unpoisoned(coordination_map);
    if let Some(existing) = map.get(&key).and_then(Weak::upgrade) {
        return existing;
    }
    let coordination = Arc::new(SharedMvccCoordinationState::new());
    map.insert(key, Arc::downgrade(&coordination));
    coordination
}

fn shared_mvcc_state_for_path(
    path: &str,
    file_identity: Option<FileIdentity>,
    runtime: Arc<RuntimeContext>,
) -> Result<Arc<SharedMvccState>> {
    if path == ":memory:" {
        let coordination = Arc::new(SharedMvccCoordinationState::new());
        return Ok(Arc::new(SharedMvccState::new(
            SharedMvccKey::new(path.to_owned(), None, &runtime),
            runtime,
            coordination,
        )?));
    }

    let path_key = mvcc_state_path_key(path);
    let coordination = shared_mvcc_coordination_for_file(&path_key, file_identity);
    let key = SharedMvccKey::new(path_key, file_identity, &runtime);
    let state_map = SHARED_MVCC_STATE_BY_PATH.get_or_init(|| Mutex::new(HashMap::new()));
    let mut map = lock_unpoisoned(state_map);

    if let Some(existing) = map.get(&key).and_then(Weak::upgrade) {
        return Ok(existing);
    }

    let state = Arc::new(SharedMvccState::new(key.clone(), runtime, coordination)?);
    map.insert(key, Arc::downgrade(&state));
    Ok(state)
}

/// Recursively walk an expression tree and eagerly evaluate subquery
/// expressions: `EXISTS (SELECT ...)` and scalar `(SELECT ...)`.
/// Check whether a SELECT subquery is correlated — i.e., its row-filtering
/// expressions reference column names qualified with a table that is NOT one
/// of the subquery's own FROM/JOIN sources. Correlated subqueries must be
/// evaluated per-row rather than eagerly before the scan.
fn is_correlated_subquery(subquery: &SelectStatement) -> bool {
    select_statement_has_external_column_ref(subquery, &[])
}

/// Schema-aware correlation check for connection routing.
///
/// The schema-free detector above can prove qualified outer references, but it
/// must treat an unqualified name as local whenever a FROM source exists.
/// SQLite instead searches outward when no inner source exposes that name.
/// Probe-mode substitution mirrors the runtime scope walker exactly: known
/// base-table inventories protect their real columns, while opaque inventories
/// conservatively leave the subquery on the correlated path.
fn is_correlated_subquery_with_schema(subquery: &SelectStatement, schema: &[TableSchema]) -> bool {
    if is_correlated_subquery(subquery) {
        return true;
    }

    let mut probed = subquery.clone();
    let lookup = OuterReferenceLookup {
        row: &[],
        col_map: &[],
        using_skip: None,
        replacement_exprs: None,
        column_collations: None,
        column_affinities: None,
        schema,
        shadowed_main_tables: None,
        temp_table_names: None,
        probe_unqualified_external_ref: true,
    };
    substitute_outer_refs_in_select_scoped(
        &mut probed,
        &lookup,
        &[],
        Some(&HashSet::new()),
        &HashSet::new(),
    );
    probed != *subquery
}

/// bd-2fong: derive a view's output column names for correlation probing.
///
/// Prefers the explicit `CREATE VIEW v (cols...)` list; otherwise reads the
/// stored definition's projection, accepting aliased expressions and plain
/// column references. Star/complex unaliased projections return `None` and
/// the view stays opaque (conservatively correlated) for the probe.
fn view_output_column_names(view: &ViewDef) -> Option<Vec<String>> {
    if !view.columns.is_empty() {
        return Some(view.columns.clone());
    }
    let SelectCore::Select { columns, .. } = &view.query.body.select else {
        return None;
    };
    let mut names = Vec::with_capacity(columns.len());
    for column in columns {
        match column {
            ResultColumn::Expr {
                alias: Some(alias), ..
            } => names.push(alias.clone()),
            ResultColumn::Expr {
                expr: Expr::Column(column_ref, _),
                ..
            } => names.push(column_ref.column.to_string()),
            ResultColumn::Expr { .. } | ResultColumn::Star | ResultColumn::TableStar(_) => {
                return None;
            }
        }
    }
    Some(names)
}

/// bd-2fong: correlation verdict for the eager subquery-rewrite decision.
///
/// The schema-aware probe treats bare columns in scopes whose FROM relation
/// is absent from the base-table schema as potential outer references —
/// which classified every view- or sqlite_schema-sourced nested probe as
/// correlated and starved the eager IN-rewrite that keeps
/// `... IN (SELECT ... WHERE x IN (SELECT ... FROM view_or_sqlite_schema))`
/// on the compiled path. When (and only when) the subquery tree references
/// such a relation, probe against a schema augmented with synthetic
/// inventories: the fixed sqlite_schema/sqlite_master columns and each
/// view's derivable output columns. Views whose output cannot be derived
/// stay opaque and keep the conservative correlated verdict.
fn rewrite_probe_is_correlated(conn: &Connection, sub: &SelectStatement) -> bool {
    let schema = conn.schema.borrow();
    let views = conn.views.borrow();
    let references_synthetic_relation = select_contains_relation_reference(sub, &mut |name| {
        name.schema.is_none()
            && (is_sqlite_schema_name(&name.name)
                || views
                    .iter()
                    .any(|view| view.name.eq_ignore_ascii_case(&name.name)))
    });
    if !references_synthetic_relation {
        return is_correlated_subquery_with_schema(sub, &schema);
    }
    let synthetic_table = |name: &str, columns: Vec<String>| TableSchema {
        name: name.to_owned(),
        root_page: 1,
        columns: columns
            .into_iter()
            .map(|column| ColumnInfo::basic(column, 'A', false))
            .collect(),
        indexes: Vec::new(),
        strict: false,
        without_rowid: false,
        primary_key_constraints: Vec::new(),
        foreign_keys: Vec::new(),
        check_constraints: Vec::new(),
    };
    let mut augmented = schema.clone();
    for builtin in ["sqlite_schema", "sqlite_master"] {
        augmented.push(synthetic_table(
            builtin,
            ["type", "name", "tbl_name", "rootpage", "sql"]
                .into_iter()
                .map(str::to_owned)
                .collect(),
        ));
    }
    for view in views.iter() {
        if let Some(columns) = view_output_column_names(view) {
            augmented.push(synthetic_table(&view.name, columns));
        }
    }
    is_correlated_subquery_with_schema(sub, &augmented)
}

fn expr_has_external_column_ref_with_schema_in_core(
    expr: &Expr,
    core: &SelectCore,
    schema: &[TableSchema],
) -> bool {
    expr_has_external_column_ref_with_schema_in_core_and_locals(expr, core, schema, &HashSet::new())
}

fn expr_has_external_column_ref_with_schema_in_core_and_locals(
    expr: &Expr,
    core: &SelectCore,
    schema: &[TableSchema],
    local_output_names: &HashSet<String>,
) -> bool {
    let protected_tables = protected_tables_for_core(core, &[]);
    if expr_has_external_column_ref(expr, &protected_tables) {
        return true;
    }
    let opaque_cte_names = HashSet::new();
    let lookup = OuterReferenceLookup {
        row: &[],
        col_map: &[],
        using_skip: None,
        replacement_exprs: None,
        column_collations: None,
        column_affinities: None,
        schema,
        shadowed_main_tables: None,
        temp_table_names: None,
        probe_unqualified_external_ref: true,
    };
    let protected_unqualified_columns = protected_unqualified_columns_for_core(
        core,
        &lookup,
        &opaque_cte_names,
        Some(&HashSet::new()),
    );
    substitute_outer_refs_in_expr(
        expr,
        &lookup,
        &protected_tables,
        protected_unqualified_columns.as_ref(),
        local_output_names,
        &opaque_cte_names,
    ) != *expr
}

fn select_statement_has_external_column_ref(
    select: &SelectStatement,
    ancestor_tables: &[String],
) -> bool {
    select.with.as_ref().is_some_and(|with| {
        with.ctes
            .iter()
            .any(|cte| select_statement_has_external_column_ref(&cte.query, ancestor_tables))
    }) || select_core_has_external_column_ref(&select.body.select, ancestor_tables)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_has_external_column_ref(core, ancestor_tables))
        // bd-2fong red 4: statement-level ORDER BY and LIMIT resolve in the
        // primary core's scope and can carry correlated outer references
        // (`... ORDER BY abs(y - outer.x) LIMIT 1`). Skipping them made the
        // correlation detector misjudge such subqueries as non-correlated, so
        // the compiled IN-probe lane admitted a shape whose codegen cannot
        // resolve the outer name (NoSuchColumn at prepare). Mirror the
        // substitution walker's statement-level extension.
        || {
            let inner_tables =
                protected_tables_for_core(&select.body.select, ancestor_tables);
            // ORDER BY resolves output aliases before any outer scope
            // (`SELECT 1 AS x ORDER BY x` is fully local), so aliases join
            // the local set unconditionally here.
            let output_aliases = collect_select_core_result_aliases(&select.body.select);
            select.order_by.iter().any(|term| {
                expr_has_external_column_ref_with_locals(
                    &term.expr,
                    &inner_tables,
                    &output_aliases,
                )
            }) || select.limit.as_ref().is_some_and(|limit| {
                expr_has_external_column_ref_with_locals(
                    &limit.limit,
                    &inner_tables,
                    &output_aliases,
                ) || limit.offset.as_ref().is_some_and(|offset| {
                    expr_has_external_column_ref_with_locals(
                        offset,
                        &inner_tables,
                        &output_aliases,
                    )
                })
            })
        }
}

fn select_core_has_external_column_ref(core: &SelectCore, ancestor_tables: &[String]) -> bool {
    let inner_tables = protected_tables_for_core(core, ancestor_tables);
    match core {
        SelectCore::Values(rows) => rows
            .iter()
            .flatten()
            .any(|expr| expr_has_external_column_ref(expr, &inner_tables)),
        SelectCore::Select {
            columns,
            from,
            where_clause,
            having,
            windows,
            ..
        } => {
            let output_aliases = if from.is_none() {
                collect_select_core_result_aliases(core)
            } else {
                HashSet::new()
            };
            columns
                .iter()
                .any(|column| result_column_has_external_column_ref(column, &inner_tables))
                || from
                    .as_ref()
                    .is_some_and(|from| from_clause_has_external_column_ref(from, &inner_tables))
                || where_clause.as_deref().is_some_and(|wh| {
                    expr_has_external_column_ref_with_locals(wh, &inner_tables, &output_aliases)
                })
                || having.as_deref().is_some_and(|expr| {
                    expr_has_external_column_ref_with_locals(expr, &inner_tables, &output_aliases)
                })
                || windows
                    .iter()
                    .any(|window| window_spec_has_external_column_ref(&window.spec, &inner_tables))
        }
    }
}

fn protected_tables_for_core(core: &SelectCore, ancestor_tables: &[String]) -> Vec<String> {
    let mut tables = ancestor_tables.to_vec();
    collect_select_core_inner_aliases(core, &mut tables);
    tables
}

fn collect_select_core_inner_aliases(core: &SelectCore, out: &mut Vec<String>) {
    let SelectCore::Select {
        from: Some(from), ..
    } = core
    else {
        return;
    };
    collect_table_or_subquery_inner_alias(&from.source, out);
    for join in &from.joins {
        collect_table_or_subquery_inner_alias(&join.table, out);
    }
}

fn result_column_has_external_column_ref(column: &ResultColumn, inner_tables: &[String]) -> bool {
    match column {
        ResultColumn::Expr { expr, .. } => expr_has_external_column_ref(expr, inner_tables),
        ResultColumn::Star | ResultColumn::TableStar(_) => false,
    }
}

fn window_spec_has_external_column_ref(window: &WindowSpec, inner_tables: &[String]) -> bool {
    window
        .partition_by
        .iter()
        .any(|expr| expr_has_external_column_ref(expr, inner_tables))
        || window
            .order_by
            .iter()
            .any(|term| expr_has_external_column_ref(&term.expr, inner_tables))
        || window
            .frame
            .as_ref()
            .is_some_and(|frame| frame_spec_has_external_column_ref(frame, inner_tables))
}

fn frame_spec_has_external_column_ref(frame: &FrameSpec, inner_tables: &[String]) -> bool {
    frame_bound_has_external_column_ref(&frame.start, inner_tables)
        || frame
            .end
            .as_ref()
            .is_some_and(|bound| frame_bound_has_external_column_ref(bound, inner_tables))
}

fn frame_bound_has_external_column_ref(bound: &FrameBound, inner_tables: &[String]) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_has_external_column_ref(expr, inner_tables)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn collect_table_or_subquery_inner_alias(source: &TableOrSubquery, out: &mut Vec<String>) {
    match source {
        TableOrSubquery::Table { name, alias, .. } => {
            out.push(alias.as_ref().unwrap_or(&name.name).clone());
        }
        TableOrSubquery::Subquery { alias, .. } => {
            // Aliased subqueries (`FROM (SELECT ...) AS s`) act as inner
            // tables under their alias. Anonymous subqueries can't be
            // referenced by qualifier so they don't contribute aliases.
            if let Some(a) = alias {
                out.push(a.clone());
            }
        }
        TableOrSubquery::TableFunction { name, alias, .. } => {
            out.push(alias.clone().unwrap_or_else(|| name.clone()));
        }
        TableOrSubquery::ParenJoin(from) => {
            collect_table_or_subquery_inner_alias(&from.source, out);
            for join in &from.joins {
                collect_table_or_subquery_inner_alias(&join.table, out);
            }
        }
    }
}

fn collect_main_qualified_table_names(select: &SelectStatement, out: &mut HashSet<String>) {
    if let Some(with) = &select.with {
        for cte in &with.ctes {
            collect_main_qualified_table_names(&cte.query, out);
        }
    }
    collect_main_qualified_select_core(&select.body.select, out);
    for (_, core) in &select.body.compounds {
        collect_main_qualified_select_core(core, out);
    }
    for term in &select.order_by {
        collect_main_qualified_expr(&term.expr, out);
    }
    if let Some(limit) = &select.limit {
        collect_main_qualified_expr(&limit.limit, out);
        if let Some(offset) = &limit.offset {
            collect_main_qualified_expr(offset, out);
        }
    }
}

fn collect_main_qualified_select_core(core: &SelectCore, out: &mut HashSet<String>) {
    match core {
        SelectCore::Values(rows) => {
            for expr in rows.iter().flatten() {
                collect_main_qualified_expr(expr, out);
            }
        }
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            for column in columns {
                match column {
                    ResultColumn::Expr { expr, .. } => collect_main_qualified_expr(expr, out),
                    ResultColumn::TableStar(name) => collect_main_qualified_name(name, out),
                    ResultColumn::Star => {}
                }
            }
            if let Some(from) = from {
                collect_main_qualified_from_clause(from, out);
            }
            if let Some(expr) = where_clause {
                collect_main_qualified_expr(expr, out);
            }
            for expr in group_by {
                collect_main_qualified_expr(expr, out);
            }
            if let Some(expr) = having {
                collect_main_qualified_expr(expr, out);
            }
            for window in windows {
                collect_main_qualified_window_spec(&window.spec, out);
            }
        }
    }
}

fn collect_main_qualified_from_clause(from: &FromClause, out: &mut HashSet<String>) {
    collect_main_qualified_table_or_subquery(&from.source, out);
    for join in &from.joins {
        collect_main_qualified_table_or_subquery(&join.table, out);
        if let Some(JoinConstraint::On(expr)) = &join.constraint {
            collect_main_qualified_expr(expr, out);
        }
    }
}

fn collect_main_qualified_table_or_subquery(source: &TableOrSubquery, out: &mut HashSet<String>) {
    match source {
        TableOrSubquery::Table { name, .. } => collect_main_qualified_name(name, out),
        TableOrSubquery::Subquery { query, .. } => collect_main_qualified_table_names(query, out),
        TableOrSubquery::TableFunction { args, .. } => {
            for expr in args {
                collect_main_qualified_expr(expr, out);
            }
        }
        TableOrSubquery::ParenJoin(from) => collect_main_qualified_from_clause(from, out),
    }
}

fn collect_main_qualified_expr(expr: &Expr, out: &mut HashSet<String>) {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => {}
        Expr::BinaryOp { left, right, .. } => {
            collect_main_qualified_expr(left, out);
            collect_main_qualified_expr(right, out);
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => collect_main_qualified_expr(expr, out),
        Expr::Between {
            expr, low, high, ..
        } => {
            collect_main_qualified_expr(expr, out);
            collect_main_qualified_expr(low, out);
            collect_main_qualified_expr(high, out);
        }
        Expr::In { expr, set, .. } => {
            collect_main_qualified_expr(expr, out);
            match set {
                InSet::List(items) => {
                    for item in items {
                        collect_main_qualified_expr(item, out);
                    }
                }
                InSet::Subquery(query) => collect_main_qualified_table_names(query, out),
                InSet::Table(name) => collect_main_qualified_name(name, out),
            }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            collect_main_qualified_expr(expr, out);
            collect_main_qualified_expr(pattern, out);
            if let Some(escape) = escape {
                collect_main_qualified_expr(escape, out);
            }
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                collect_main_qualified_expr(operand, out);
            }
            for (when, then) in whens {
                collect_main_qualified_expr(when, out);
                collect_main_qualified_expr(then, out);
            }
            if let Some(else_expr) = else_expr {
                collect_main_qualified_expr(else_expr, out);
            }
        }
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            collect_main_qualified_table_names(subquery, out);
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if let FunctionArgs::List(items) = args {
                for item in items {
                    collect_main_qualified_expr(item, out);
                }
            }
            for term in order_by {
                collect_main_qualified_expr(&term.expr, out);
            }
            if let Some(filter) = filter {
                collect_main_qualified_expr(filter, out);
            }
            if let Some(over) = over {
                collect_main_qualified_window_spec(over, out);
            }
        }
        Expr::JsonAccess { expr, path, .. } => {
            collect_main_qualified_expr(expr, out);
            collect_main_qualified_expr(path, out);
        }
        Expr::RowValue(items, _) => {
            for item in items {
                collect_main_qualified_expr(item, out);
            }
        }
    }
}

fn collect_main_qualified_window_spec(window: &WindowSpec, out: &mut HashSet<String>) {
    for expr in &window.partition_by {
        collect_main_qualified_expr(expr, out);
    }
    for term in &window.order_by {
        collect_main_qualified_expr(&term.expr, out);
    }
    if let Some(frame) = &window.frame {
        collect_main_qualified_frame_bound(&frame.start, out);
        if let Some(end) = &frame.end {
            collect_main_qualified_frame_bound(end, out);
        }
    }
}

fn collect_main_qualified_frame_bound(bound: &FrameBound, out: &mut HashSet<String>) {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            collect_main_qualified_expr(expr, out);
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => {}
    }
}

fn collect_main_qualified_name(name: &QualifiedName, out: &mut HashSet<String>) {
    if name
        .schema
        .as_deref()
        .is_some_and(|schema| schema.eq_ignore_ascii_case("main"))
    {
        out.insert(name.name.to_ascii_lowercase());
    }
}

fn from_clause_has_external_column_ref(from: &FromClause, inner_tables: &[String]) -> bool {
    table_or_subquery_has_external_column_ref(&from.source, inner_tables)
        || from.joins.iter().any(|join| {
            table_or_subquery_has_external_column_ref(&join.table, inner_tables)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr))
                        if expr_has_external_column_ref(expr, inner_tables)
                )
        })
}

fn table_or_subquery_has_external_column_ref(
    source: &TableOrSubquery,
    inner_tables: &[String],
) -> bool {
    match source {
        TableOrSubquery::Table { .. } => false,
        TableOrSubquery::Subquery { query, .. } => {
            select_statement_has_external_column_ref(query, inner_tables)
        }
        TableOrSubquery::TableFunction { args, .. } => args
            .iter()
            .any(|expr| expr_has_external_column_ref(expr, inner_tables)),
        TableOrSubquery::ParenJoin(from) => from_clause_has_external_column_ref(from, inner_tables),
    }
}

/// Return true if `expr` contains a column reference that is provably external
/// to `inner_tables`.
///
/// An empty `inner_tables` slice means "no inner table is known"; in that
/// case every column reference, qualified or unqualified, is external. That
/// keeps subqueries without FROM sources and value-only paths correlated when
/// they reference an outer row. With an inner source, only a qualifier that
/// does not match an inner table can be proven external without schema-aware
/// name resolution.
fn expr_has_external_column_ref(expr: &Expr, inner_tables: &[String]) -> bool {
    expr_has_external_column_ref_with_locals(expr, inner_tables, &HashSet::new())
}

fn expr_has_external_column_ref_with_locals(
    expr: &Expr,
    inner_tables: &[String],
    local_output_names: &HashSet<String>,
) -> bool {
    match expr {
        Expr::Column(col_ref, _) => {
            if let Some(qualifier) = &col_ref.table {
                if inner_tables.is_empty() {
                    return true;
                }
                return !inner_tables
                    .iter()
                    .any(|name| name.eq_ignore_ascii_case(qualifier));
            }
            inner_tables.is_empty()
                && !local_output_names.contains(&col_ref.column.to_ascii_lowercase())
        }
        Expr::BinaryOp { left, right, .. } => {
            expr_has_external_column_ref_with_locals(left, inner_tables, local_output_names)
                || expr_has_external_column_ref_with_locals(right, inner_tables, local_output_names)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => {
            expr_has_external_column_ref_with_locals(inner, inner_tables, local_output_names)
        }
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            expr_has_external_column_ref_with_locals(inner, inner_tables, local_output_names)
                || expr_has_external_column_ref_with_locals(low, inner_tables, local_output_names)
                || expr_has_external_column_ref_with_locals(high, inner_tables, local_output_names)
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return false;
            }
            expr_has_external_column_ref_with_locals(inner, inner_tables, local_output_names)
                || match set {
                    InSet::List(items) => items.iter().any(|item| {
                        expr_has_external_column_ref_with_locals(
                            item,
                            inner_tables,
                            local_output_names,
                        )
                    }),
                    InSet::Subquery(subquery) => {
                        select_statement_has_external_column_ref(subquery, inner_tables)
                    }
                    InSet::Table(_) => false,
                }
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_have_external_ref = matches!(
                args,
                FunctionArgs::List(items)
                    if items
                        .iter()
                        .any(|item| expr_has_external_column_ref_with_locals(
                            item,
                            inner_tables,
                            local_output_names,
                        ))
            );
            args_have_external_ref
                || order_by.iter().any(|term| {
                    expr_has_external_column_ref_with_locals(
                        &term.expr,
                        inner_tables,
                        local_output_names,
                    )
                })
                || filter.as_ref().is_some_and(|expr| {
                    expr_has_external_column_ref_with_locals(expr, inner_tables, local_output_names)
                })
                || over
                    .as_ref()
                    .is_some_and(|window| window_spec_has_external_column_ref(window, inner_tables))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_ref().is_some_and(|operand| {
                expr_has_external_column_ref_with_locals(operand, inner_tables, local_output_names)
            }) || whens.iter().any(|(c, t)| {
                expr_has_external_column_ref_with_locals(c, inner_tables, local_output_names)
                    || expr_has_external_column_ref_with_locals(t, inner_tables, local_output_names)
            }) || else_expr.as_ref().is_some_and(|else_expr| {
                expr_has_external_column_ref_with_locals(
                    else_expr,
                    inner_tables,
                    local_output_names,
                )
            })
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            expr_has_external_column_ref_with_locals(inner, inner_tables, local_output_names)
                || expr_has_external_column_ref_with_locals(
                    pattern,
                    inner_tables,
                    local_output_names,
                )
                || escape.as_ref().is_some_and(|escape| {
                    expr_has_external_column_ref_with_locals(
                        escape,
                        inner_tables,
                        local_output_names,
                    )
                })
        }
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            select_statement_has_external_column_ref(subquery, inner_tables)
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => {
            expr_has_external_column_ref_with_locals(inner, inner_tables, local_output_names)
                || expr_has_external_column_ref_with_locals(path, inner_tables, local_output_names)
        }
        Expr::RowValue(values, _) => values.iter().any(|value| {
            expr_has_external_column_ref_with_locals(value, inner_tables, local_output_names)
        }),
        _ => false,
    }
}

// ---------------------------------------------------------------------------
// B2.2 EXISTS direct-probe helpers
// ---------------------------------------------------------------------------

/// Decompose a WHERE expression into AND-connected terms.
fn decompose_where_simple(expr: &Expr) -> Vec<&Expr> {
    let mut terms = Vec::new();
    decompose_where_simple_inner(expr, &mut terms);
    terms
}

fn decompose_where_simple_inner<'a>(expr: &'a Expr, terms: &mut Vec<&'a Expr>) {
    if let Expr::BinaryOp {
        left,
        op: BinaryOp::And,
        right,
        ..
    } = expr
    {
        decompose_where_simple_inner(left, terms);
        decompose_where_simple_inner(right, terms);
    } else {
        terms.push(expr);
    }
}

struct CorrelatedEqualityProbe {
    inner_column: String,
    outer_index: usize,
    outer_value: SqliteValue,
    inner_on_left: bool,
}

/// Extract a direct-column correlated equality while preserving operand order
/// and the resolved outer slot. Unqualified outer references are declined:
/// the inner scope can shadow them, and this fast path must not duplicate the
/// full resolver's scope rules.
fn extract_correlated_equality(
    expr: &Expr,
    inner_table_names: &[&str],
    inner_columns: &[ColumnInfo],
    row: &[SqliteValue],
    col_map: &[(String, String, bool)],
) -> Option<CorrelatedEqualityProbe> {
    let Expr::BinaryOp {
        left, op, right, ..
    } = expr
    else {
        return None;
    };
    if *op != BinaryOp::Eq {
        return None;
    }
    // Try left = inner, right = outer.
    if let Some(result) = try_correlated_pair(
        left,
        right,
        inner_table_names,
        inner_columns,
        row,
        col_map,
        true,
    ) {
        return Some(result);
    }
    // Try right = inner, left = outer.
    try_correlated_pair(
        right,
        left,
        inner_table_names,
        inner_columns,
        row,
        col_map,
        false,
    )
}

fn try_correlated_pair(
    inner_candidate: &Expr,
    outer_candidate: &Expr,
    inner_table_names: &[&str],
    inner_columns: &[ColumnInfo],
    row: &[SqliteValue],
    col_map: &[(String, String, bool)],
    inner_on_left: bool,
) -> Option<CorrelatedEqualityProbe> {
    let Expr::Column(inner_ref, _) = inner_candidate else {
        return None;
    };
    if inner_ref.table.as_deref().is_some_and(|qualifier| {
        !inner_table_names
            .iter()
            .any(|name| qualifier.eq_ignore_ascii_case(name))
    }) || !inner_columns
        .iter()
        .any(|column| column.name.eq_ignore_ascii_case(&inner_ref.column))
    {
        return None;
    }

    let Expr::Column(outer_ref, _) = outer_candidate else {
        return None;
    };
    let outer_qualifier = outer_ref.table.as_deref()?;
    if inner_table_names
        .iter()
        .any(|name| outer_qualifier.eq_ignore_ascii_case(name))
    {
        return None;
    }
    let outer_index =
        find_col_in_map(col_map, Some(outer_qualifier), &outer_ref.column, None).ok()?;
    let outer_value = row.get(outer_index)?.clone();
    Some(CorrelatedEqualityProbe {
        inner_column: inner_ref.column.to_string(),
        outer_index,
        outer_value,
        inner_on_left,
    })
}

/// Compare two SQLite values for ordering (NULL sorts before everything).
fn cmp_values_sqlite(a: &SqliteValue, b: &SqliteValue) -> std::cmp::Ordering {
    cmp_sqlite_values(a, b)
}

/// Check if an expression tree contains any `Expr::Subquery`.
fn expr_has_any_subquery(expr: &Expr) -> bool {
    expr_contains_subquery_match(expr, &mut |_| true)
}

/// Check if an expression contains a correlated scalar subquery whose
/// FROM clause has JOINs (multi-table subquery). These cannot be handled
/// by the VDBE `emit_scalar_subquery` which only opens one table cursor.
fn expr_has_correlated_join_subquery(expr: &Expr) -> bool {
    match expr {
        Expr::Subquery(sub, _) => {
            if let SelectCore::Select {
                from: Some(from), ..
            } = &sub.body.select
                && !from.joins.is_empty()
            {
                return true;
            }
            false
        }
        Expr::FunctionCall { args, .. } => match args {
            FunctionArgs::List(exprs) => exprs.iter().any(expr_has_correlated_join_subquery),
            FunctionArgs::Star => false,
        },
        Expr::BinaryOp { left, right, .. } => {
            expr_has_correlated_join_subquery(left) || expr_has_correlated_join_subquery(right)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => expr_has_correlated_join_subquery(inner),
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_ref()
                .is_some_and(|e| expr_has_correlated_join_subquery(e))
                || whens.iter().any(|(w, t)| {
                    expr_has_correlated_join_subquery(w) || expr_has_correlated_join_subquery(t)
                })
                || else_expr
                    .as_ref()
                    .is_some_and(|e| expr_has_correlated_join_subquery(e))
        }
        _ => false,
    }
}

/// Check if a SELECT's WHERE clause contains a correlated EXISTS subquery.
fn select_has_correlated_exists_in_where(select: &SelectStatement, schema: &[TableSchema]) -> bool {
    let SelectCore::Select { where_clause, .. } = &select.body.select else {
        return false;
    };
    where_clause
        .as_deref()
        .is_some_and(|expr| expr_has_correlated_exists(expr, schema))
}

/// True when every correlated EXISTS subquery in the WHERE clause matches the
/// indexed count-semijoin probe shape (`correlated_exists_matches_count_semijoin_shape`)
/// — the one correlated shape the compiled path handles correctly, including
/// placeholder residual bounds (bd-8sfs3). Callers must have already
/// established that at least one correlated EXISTS is present.
fn select_correlated_exists_in_where_all_match_count_semijoin_shape(
    select: &SelectStatement,
    schema: &[TableSchema],
) -> bool {
    let SelectCore::Select { where_clause, .. } = &select.body.select else {
        return false;
    };
    let Some(where_expr) = where_clause.as_deref() else {
        return false;
    };
    !expr_contains_subquery_match(where_expr, &mut |sub| {
        matches!(
            sub,
            SubqueryExprRef::Exists(inner)
                if is_correlated_subquery_with_schema(inner, schema)
                    && !correlated_exists_matches_count_semijoin_shape(inner, schema)
        )
    })
}

/// Return true if the WHERE clause contains a correlated `x IN (SELECT ...)`
/// predicate — a subquery on the RHS of `IN` that references an outer column.
///
/// bd-zvk68: such predicates must be evaluated per outer row. SELECT routing
/// uses this to keep them on the connection-level fallback, where
/// `eval_expr_with_subqueries` substitutes outer references per row (the
/// `InSet::Subquery` arm). The eager IN-rewrite already leaves correlated IN
/// subqueries intact (`is_correlated_subquery`), but the VDBE codegen IN path
/// then materializes the candidate set once with no outer binding, so without
/// this gate the predicate matches nothing.
fn select_has_correlated_in_subquery(select: &SelectStatement, schema: &[TableSchema]) -> bool {
    select.with.as_ref().is_some_and(|with| {
        with.ctes
            .iter()
            .any(|cte| select_has_correlated_in_subquery(&cte.query, schema))
    }) || select_core_has_correlated_in_subquery(&select.body.select, schema)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_has_correlated_in_subquery(core, schema))
        || select
            .order_by
            .iter()
            .any(|term| expr_has_correlated_in_subquery(&term.expr, schema))
        || select.limit.as_ref().is_some_and(|limit| {
            expr_has_correlated_in_subquery(&limit.limit, schema)
                || limit
                    .offset
                    .as_ref()
                    .is_some_and(|offset| expr_has_correlated_in_subquery(offset, schema))
        })
}

fn select_core_has_correlated_in_subquery(core: &SelectCore, schema: &[TableSchema]) -> bool {
    match core {
        SelectCore::Values(rows) => rows
            .iter()
            .flatten()
            .any(|expr| expr_has_correlated_in_subquery(expr, schema)),
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns.iter().any(|column| {
                matches!(
                    column,
                    ResultColumn::Expr { expr, .. }
                        if expr_has_correlated_in_subquery(expr, schema)
                )
            }) || from
                .as_ref()
                .is_some_and(|from| from_clause_has_correlated_in_subquery(from, schema))
                || where_clause
                    .as_deref()
                    .is_some_and(|expr| expr_has_correlated_in_subquery(expr, schema))
                || group_by
                    .iter()
                    .any(|expr| expr_has_correlated_in_subquery(expr, schema))
                || having
                    .as_deref()
                    .is_some_and(|expr| expr_has_correlated_in_subquery(expr, schema))
                || windows.iter().any(|window| {
                    window
                        .spec
                        .partition_by
                        .iter()
                        .any(|expr| expr_has_correlated_in_subquery(expr, schema))
                        || window
                            .spec
                            .order_by
                            .iter()
                            .any(|term| expr_has_correlated_in_subquery(&term.expr, schema))
                        || window.spec.frame.as_ref().is_some_and(|frame| {
                            frame_bound_has_correlated_in_subquery(&frame.start, schema)
                                || frame.end.as_ref().is_some_and(|end| {
                                    frame_bound_has_correlated_in_subquery(end, schema)
                                })
                        })
                })
        }
    }
}

fn from_clause_has_correlated_in_subquery(from: &FromClause, schema: &[TableSchema]) -> bool {
    table_or_subquery_has_correlated_in_subquery(&from.source, schema)
        || from.joins.iter().any(|join| {
            table_or_subquery_has_correlated_in_subquery(&join.table, schema)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr))
                        if expr_has_correlated_in_subquery(expr, schema)
                )
        })
}

fn table_or_subquery_has_correlated_in_subquery(
    source: &TableOrSubquery,
    schema: &[TableSchema],
) -> bool {
    match source {
        TableOrSubquery::Table { .. } => false,
        TableOrSubquery::Subquery { query, .. } => select_has_correlated_in_subquery(query, schema),
        TableOrSubquery::TableFunction { args, .. } => args
            .iter()
            .any(|expr| expr_has_correlated_in_subquery(expr, schema)),
        TableOrSubquery::ParenJoin(from) => from_clause_has_correlated_in_subquery(from, schema),
    }
}

fn frame_bound_has_correlated_in_subquery(bound: &FrameBound, schema: &[TableSchema]) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_has_correlated_in_subquery(expr, schema)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn expr_has_correlated_in_subquery(expr: &Expr, schema: &[TableSchema]) -> bool {
    expr_contains_subquery_match(expr, &mut |subquery| match subquery {
        SubqueryExprRef::In(inner) => {
            is_correlated_subquery_with_schema(inner, schema)
                || select_has_correlated_in_subquery(inner, schema)
        }
        SubqueryExprRef::Scalar(inner) | SubqueryExprRef::Exists(inner) => {
            select_has_correlated_in_subquery(inner, schema)
        }
    })
}

/// Return true if `expr` contains a correlated EXISTS subquery.
///
/// SELECT routing uses this to keep unsupported correlated EXISTS predicates on
/// the connection-level fallback where `eval_expr_with_subqueries` substitutes
/// outer references per row. The one validated compiled exception is checked
/// separately by `select_correlated_exists_where_can_use_indexed_count_probe`.
fn expr_has_correlated_exists(expr: &Expr, schema: &[TableSchema]) -> bool {
    match expr {
        Expr::Exists { subquery, .. } => is_correlated_subquery_with_schema(subquery, schema),
        Expr::BinaryOp { left, right, .. } => {
            expr_has_correlated_exists(left, schema) || expr_has_correlated_exists(right, schema)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => expr_has_correlated_exists(inner, schema),
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            expr_has_correlated_exists(inner, schema)
                || expr_has_correlated_exists(low, schema)
                || expr_has_correlated_exists(high, schema)
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            expr_has_correlated_exists(inner, schema)
                || matches!(set, InSet::List(items) if items
                    .iter()
                    .any(|item| expr_has_correlated_exists(item, schema)))
        }
        Expr::FunctionCall {
            args: FunctionArgs::List(args),
            ..
        } => args
            .iter()
            .any(|argument| expr_has_correlated_exists(argument, schema)),
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(|operand| expr_has_correlated_exists(operand, schema))
                || whens.iter().any(|(condition, value)| {
                    expr_has_correlated_exists(condition, schema)
                        || expr_has_correlated_exists(value, schema)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(|else_expr| expr_has_correlated_exists(else_expr, schema))
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            expr_has_correlated_exists(inner, schema)
                || expr_has_correlated_exists(pattern, schema)
                || escape
                    .as_deref()
                    .is_some_and(|escape| expr_has_correlated_exists(escape, schema))
        }
        Expr::RowValue(values, _) => values
            .iter()
            .any(|value| expr_has_correlated_exists(value, schema)),
        Expr::JsonAccess { expr, path, .. } => {
            expr_has_correlated_exists(expr, schema) || expr_has_correlated_exists(path, schema)
        }
        Expr::Subquery(_, _) | Expr::Raise { .. } => false,
        _ => false,
    }
}

/// Return true if `expr` contains a correlated EXISTS that scans the same
/// underlying table as `outer_table`. DELETE uses this narrower predicate for
/// its rowid rewrite path, whose assumptions are specific to the target table.
fn expr_has_self_referencing_correlated_exists(
    expr: &Expr,
    outer_table: &str,
    schema: &[TableSchema],
) -> bool {
    match expr {
        Expr::Exists { subquery, .. } => {
            is_correlated_subquery_with_schema(subquery, schema)
                && subquery_references_table(subquery, outer_table)
        }
        Expr::BinaryOp { left, right, .. } => {
            expr_has_self_referencing_correlated_exists(left, outer_table, schema)
                || expr_has_self_referencing_correlated_exists(right, outer_table, schema)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => {
            expr_has_self_referencing_correlated_exists(inner, outer_table, schema)
        }
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            expr_has_self_referencing_correlated_exists(inner, outer_table, schema)
                || expr_has_self_referencing_correlated_exists(low, outer_table, schema)
                || expr_has_self_referencing_correlated_exists(high, outer_table, schema)
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            expr_has_self_referencing_correlated_exists(inner, outer_table, schema)
                || matches!(set, InSet::List(items) if items
                .iter()
                .any(|item| expr_has_self_referencing_correlated_exists(
                    item,
                    outer_table,
                    schema,
                )))
        }
        Expr::FunctionCall {
            args: FunctionArgs::List(args),
            ..
        } => args
            .iter()
            .any(|arg| expr_has_self_referencing_correlated_exists(arg, outer_table, schema)),
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_deref().is_some_and(|inner| {
                expr_has_self_referencing_correlated_exists(inner, outer_table, schema)
            }) || whens.iter().any(|(condition, value)| {
                expr_has_self_referencing_correlated_exists(condition, outer_table, schema)
                    || expr_has_self_referencing_correlated_exists(value, outer_table, schema)
            }) || else_expr.as_deref().is_some_and(|inner| {
                expr_has_self_referencing_correlated_exists(inner, outer_table, schema)
            })
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            expr_has_self_referencing_correlated_exists(inner, outer_table, schema)
                || expr_has_self_referencing_correlated_exists(pattern, outer_table, schema)
                || escape.as_deref().is_some_and(|inner| {
                    expr_has_self_referencing_correlated_exists(inner, outer_table, schema)
                })
        }
        Expr::RowValue(values, _) => values
            .iter()
            .any(|value| expr_has_self_referencing_correlated_exists(value, outer_table, schema)),
        Expr::JsonAccess { expr, path, .. } => {
            expr_has_self_referencing_correlated_exists(expr, outer_table, schema)
                || expr_has_self_referencing_correlated_exists(path, outer_table, schema)
        }
        Expr::Subquery(_, _) | Expr::Raise { .. } => false,
        _ => false,
    }
}

/// Check if an expression contains an uncorrelated scalar subquery that
/// references `outer_table` in its FROM clause — used to detect
/// `DELETE FROM t WHERE val > (SELECT AVG(val) FROM t)` patterns.
fn expr_has_self_referencing_scalar_subquery(
    expr: &Expr,
    outer_table: &str,
    schema: &[TableSchema],
) -> bool {
    match expr {
        Expr::Subquery(subquery, _) => {
            !is_correlated_subquery_with_schema(subquery, schema)
                && subquery_references_table(subquery, outer_table)
        }
        Expr::BinaryOp { left, right, .. } => {
            expr_has_self_referencing_scalar_subquery(left, outer_table, schema)
                || expr_has_self_referencing_scalar_subquery(right, outer_table, schema)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => {
            expr_has_self_referencing_scalar_subquery(inner, outer_table, schema)
        }
        Expr::FunctionCall {
            args: FunctionArgs::List(args),
            ..
        } => args
            .iter()
            .any(|a| expr_has_self_referencing_scalar_subquery(a, outer_table, schema)),
        _ => false,
    }
}

/// Check if a subquery references `table_name` in its FROM clause.
fn subquery_references_table(subquery: &SelectStatement, table_name: &str) -> bool {
    if let SelectCore::Select {
        from: Some(from), ..
    } = &subquery.body.select
    {
        if let TableOrSubquery::Table { name, .. } = &from.source
            && qualified_relation_matches_name(name, table_name)
        {
            return true;
        }
        for join in &from.joins {
            if let TableOrSubquery::Table { name, .. } = &join.table
                && qualified_relation_matches_name(name, table_name)
            {
                return true;
            }
        }
    }
    false
}

/// Check if a SELECT statement contains any correlated scalar subquery
/// with JOINs in any of its result columns, WHERE clause, or ORDER BY.
fn select_has_correlated_join_subquery(select: &SelectStatement) -> bool {
    let SelectCore::Select {
        columns,
        where_clause,
        ..
    } = &select.body.select
    else {
        return false;
    };
    for col in columns {
        if let ResultColumn::Expr { expr, .. } = col
            && expr_has_correlated_join_subquery(expr)
        {
            return true;
        }
    }
    if let Some(wh) = where_clause
        && expr_has_correlated_join_subquery(wh)
    {
        return true;
    }
    for term in &select.order_by {
        if expr_has_correlated_join_subquery(&term.expr) {
            return true;
        }
    }
    false
}

struct OuterReferenceLookup<'a> {
    row: &'a [SqliteValue],
    col_map: &'a [(String, String, bool)],
    using_skip: Option<&'a HashSet<usize>>,
    /// Optional AST replacements parallel to `col_map`.
    ///
    /// Runtime correlation normally substitutes concrete values from `row`.
    /// FROM-less WHERE-alias expansion uses the same scope-aware walker but
    /// replaces an outer alias with its SELECT-list expression instead.
    replacement_exprs: Option<&'a [Expr]>,
    /// Declared metadata parallel to `col_map` for runtime correlation.
    ///
    /// A present collation slice makes `None` at a particular index a known
    /// BINARY declaration. Analysis and alias-replacement walks leave both
    /// slices absent and continue producing ordinary literals.
    column_collations: Option<&'a [Option<String>]>,
    column_affinities: Option<&'a [TypeAffinity]>,
    schema: &'a [TableSchema],
    shadowed_main_tables: Option<&'a HashMap<String, TableSchema>>,
    temp_table_names: Option<&'a HashSet<String>>,
    /// Analysis-only mode: replace any unqualified reference that survives
    /// local-scope protection with a sentinel literal. Runtime substitution
    /// always leaves this false and resolves through `row`/`col_map`.
    probe_unqualified_external_ref: bool,
}

/// Extend the set of unqualified column names protected by the nested SELECT's
/// local FROM sources.
///
/// This is deliberately fail-closed. Base tables present in the connection
/// schema have a complete column inventory, so an unqualified name absent from
/// all of them may continue resolving through outer scopes. Sources whose
/// output cannot be established from that inventory (CTEs, views, derived
/// tables, table functions, attached/unknown relations) return `None`.
/// Runtime substitution then leaves every unqualified reference untouched
/// rather than accidentally capturing a local column as an outer value. The
/// correlation-analysis probe still marks such a surviving reference as
/// potentially external, which is the conservative dispatch decision.
fn protected_unqualified_columns_for_core(
    core: &SelectCore,
    lookup: &OuterReferenceLookup<'_>,
    opaque_cte_names: &HashSet<String>,
    ancestor_columns: Option<&HashSet<String>>,
) -> Option<HashSet<String>> {
    let mut columns = ancestor_columns?.clone();
    let SelectCore::Select {
        from: Some(from), ..
    } = core
    else {
        return Some(columns);
    };
    collect_known_source_columns(&from.source, lookup, opaque_cte_names, &mut columns)?;
    for join in &from.joins {
        collect_known_source_columns(&join.table, lookup, opaque_cte_names, &mut columns)?;
    }
    Some(columns)
}

fn collect_known_source_columns(
    source: &TableOrSubquery,
    lookup: &OuterReferenceLookup<'_>,
    opaque_cte_names: &HashSet<String>,
    out: &mut HashSet<String>,
) -> Option<()> {
    match source {
        TableOrSubquery::Table { name, .. } => {
            if opaque_cte_names.contains(&name.name.to_ascii_lowercase()) {
                return None;
            }
            let name_key = name.name.to_ascii_lowercase();
            let table = match name.schema.as_deref() {
                None => lookup
                    .schema
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case(&name.name)),
                Some(schema) if schema.eq_ignore_ascii_case("main") => {
                    let (Some(shadowed_main), Some(temp_names)) =
                        (lookup.shadowed_main_tables, lookup.temp_table_names)
                    else {
                        return None;
                    };
                    if let Some(table) = shadowed_main.get(&name_key) {
                        Some(table)
                    } else if temp_names.contains(&name_key) {
                        None
                    } else {
                        lookup
                            .schema
                            .iter()
                            .find(|table| table.name.eq_ignore_ascii_case(&name.name))
                    }
                }
                Some(schema) if schema.eq_ignore_ascii_case("temp") => {
                    let temp_names = lookup.temp_table_names?;
                    if temp_names.contains(&name_key) {
                        lookup
                            .schema
                            .iter()
                            .find(|table| table.name.eq_ignore_ascii_case(&name.name))
                    } else {
                        None
                    }
                }
                // Attached schemas live behind separate Connection instances;
                // this local inventory cannot prove their output names.
                Some(_) => None,
            }?;
            out.extend(
                table
                    .columns
                    .iter()
                    .map(|column| column.name.to_ascii_lowercase()),
            );
            for rowid_name in ["rowid", "_rowid_", "oid"] {
                if table_exposes_hidden_rowid_alias(table, rowid_name) {
                    out.insert(rowid_name.to_owned());
                }
            }
            Some(())
        }
        TableOrSubquery::ParenJoin(from) => {
            collect_known_source_columns(&from.source, lookup, opaque_cte_names, out)?;
            for join in &from.joins {
                collect_known_source_columns(&join.table, lookup, opaque_cte_names, out)?;
            }
            Some(())
        }
        TableOrSubquery::Subquery { .. } | TableOrSubquery::TableFunction { .. } => None,
    }
}

struct ResolvedOuterColumn {
    semantic_index: usize,
    value: SqliteValue,
}

fn resolve_outer_column_value(
    column: &ColumnRef,
    lookup: &OuterReferenceLookup<'_>,
) -> Option<ResolvedOuterColumn> {
    let table = column.table.as_deref();
    let index = find_col_in_map(lookup.col_map, table, &column.column, lookup.using_skip).ok()?;
    let value = lookup.row.get(index).cloned().unwrap_or(SqliteValue::Null);
    if !value.is_null() || table.is_some() {
        return Some(ResolvedOuterColumn {
            semantic_index: index,
            value,
        });
    }
    let Some(using_skip) = lookup.using_skip else {
        return Some(ResolvedOuterColumn {
            semantic_index: index,
            value,
        });
    };
    // `using_skip` is a set because membership checks dominate most callers,
    // but coalescing a chained USING/NATURAL column must follow source order.
    // Iterating the set directly would make the first non-NULL duplicate depend
    // on the hash iteration order instead of SQLite's left-to-right join order.
    for skipped_index in 0..lookup.col_map.len() {
        if !using_skip.contains(&skipped_index) {
            continue;
        }
        if lookup
            .col_map
            .get(skipped_index)
            .is_some_and(|(_, name, _)| name.eq_ignore_ascii_case(&column.column))
            && let Some(skipped_value) = lookup.row.get(skipped_index)
            && !skipped_value.is_null()
        {
            return Some(ResolvedOuterColumn {
                semantic_index: index,
                value: skipped_value.clone(),
            });
        }
    }
    Some(ResolvedOuterColumn {
        semantic_index: index,
        value,
    })
}

fn resolve_outer_column_expr(
    column: &ColumnRef,
    span: fsqlite_ast::Span,
    lookup: &OuterReferenceLookup<'_>,
) -> Option<Expr> {
    if let Some(replacements) = lookup.replacement_exprs {
        let index = find_col_in_map(
            lookup.col_map,
            column.table.as_deref(),
            &column.column,
            lookup.using_skip,
        )
        .ok()?;
        return replacements.get(index).cloned();
    }
    if column.table.is_none() && lookup.probe_unqualified_external_ref {
        return Some(value_to_literal_expr(SqliteValue::Null));
    }
    if column.table.is_none()
        && lookup.using_skip.is_some()
        && find_col_in_map(lookup.col_map, None, &column.column, lookup.using_skip).is_ok()
        && let Some(projection) = current_join_using_column_projection(&column.column)
    {
        let value = projection.value(lookup.row);
        if lookup.column_collations.is_none() {
            return Some(value_to_literal_expr(value));
        }
        return Some(Expr::BoundOuterValue {
            value,
            collation: projection.collation,
            affinity: Some(projection.affinity),
            span,
        });
    }
    let ResolvedOuterColumn {
        semantic_index,
        value,
    } = resolve_outer_column_value(column, lookup)?;
    let Some(declared_collation) = lookup
        .column_collations
        .and_then(|collations| collations.get(semantic_index))
    else {
        return Some(value_to_literal_expr(value));
    };
    let affinity = lookup
        .column_affinities
        .and_then(|affinities| affinities.get(semantic_index))
        .copied();
    Some(Expr::BoundOuterValue {
        value,
        collation: declared_collation
            .clone()
            .map_or(BoundCollation::Binary, BoundCollation::Named),
        affinity,
        span,
    })
}

fn substitute_outer_refs_in_expr(
    expr: &Expr,
    lookup: &OuterReferenceLookup<'_>,
    protected_tables: &[String],
    protected_unqualified_columns: Option<&HashSet<String>>,
    local_output_names: &HashSet<String>,
    opaque_cte_names: &HashSet<String>,
) -> Expr {
    let mut resolved = expr.clone();
    substitute_outer_refs_in_expr_mut(
        &mut resolved,
        lookup,
        protected_tables,
        protected_unqualified_columns,
        local_output_names,
        opaque_cte_names,
    );
    resolved
}

fn substitute_outer_refs_in_expr_mut(
    expr: &mut Expr,
    lookup: &OuterReferenceLookup<'_>,
    protected_tables: &[String],
    protected_unqualified_columns: Option<&HashSet<String>>,
    local_output_names: &HashSet<String>,
    opaque_cte_names: &HashSet<String>,
) {
    match expr {
        Expr::Column(column, span) => {
            let is_protected = column.table.as_ref().is_some_and(|qualifier| {
                protected_tables
                    .iter()
                    .any(|table| table.eq_ignore_ascii_case(qualifier))
            });
            let is_local_output = column.table.is_none()
                && local_output_names.contains(&column.column.to_ascii_lowercase())
                && protected_unqualified_columns
                    .is_some_and(|columns| !columns.contains(&column.column.to_ascii_lowercase()));
            let may_resolve_unqualified = column.table.is_some()
                || protected_unqualified_columns
                    .is_some_and(|columns| !columns.contains(&column.column.to_ascii_lowercase()))
                || (protected_unqualified_columns.is_none()
                    && lookup.probe_unqualified_external_ref);
            if !is_protected
                && !is_local_output
                && may_resolve_unqualified
                && let Some(replacement) = resolve_outer_column_expr(column, *span, lookup)
            {
                *expr = replacement;
            }
        }
        Expr::BinaryOp { left, right, .. } => {
            substitute_outer_refs_in_expr_mut(
                left,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
            substitute_outer_refs_in_expr_mut(
                right,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            substitute_outer_refs_in_expr_mut(
                expr,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            substitute_outer_refs_in_expr_mut(
                expr,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
            substitute_outer_refs_in_expr_mut(
                low,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
            substitute_outer_refs_in_expr_mut(
                high,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return;
            }
            substitute_outer_refs_in_expr_mut(
                expr,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
            match set {
                InSet::List(items) => {
                    for item in items {
                        substitute_outer_refs_in_expr_mut(
                            item,
                            lookup,
                            protected_tables,
                            protected_unqualified_columns,
                            local_output_names,
                            opaque_cte_names,
                        );
                    }
                }
                InSet::Subquery(subquery) => {
                    substitute_outer_refs_in_select_scoped(
                        subquery,
                        lookup,
                        protected_tables,
                        protected_unqualified_columns,
                        opaque_cte_names,
                    );
                }
                InSet::Table(_) => {}
            }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            substitute_outer_refs_in_expr_mut(
                expr,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
            substitute_outer_refs_in_expr_mut(
                pattern,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
            if let Some(escape) = escape {
                substitute_outer_refs_in_expr_mut(
                    escape,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    local_output_names,
                    opaque_cte_names,
                );
            }
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                substitute_outer_refs_in_expr_mut(
                    operand,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    local_output_names,
                    opaque_cte_names,
                );
            }
            for (when_expr, then_expr) in whens {
                substitute_outer_refs_in_expr_mut(
                    when_expr,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    local_output_names,
                    opaque_cte_names,
                );
                substitute_outer_refs_in_expr_mut(
                    then_expr,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    local_output_names,
                    opaque_cte_names,
                );
            }
            if let Some(else_expr) = else_expr {
                substitute_outer_refs_in_expr_mut(
                    else_expr,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    local_output_names,
                    opaque_cte_names,
                );
            }
        }
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            substitute_outer_refs_in_select_scoped(
                subquery,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                opaque_cte_names,
            );
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if let FunctionArgs::List(args) = args {
                for argument in args {
                    substitute_outer_refs_in_expr_mut(
                        argument,
                        lookup,
                        protected_tables,
                        protected_unqualified_columns,
                        local_output_names,
                        opaque_cte_names,
                    );
                }
            }
            for term in order_by {
                substitute_outer_refs_in_expr_mut(
                    &mut term.expr,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    local_output_names,
                    opaque_cte_names,
                );
            }
            if let Some(filter) = filter {
                substitute_outer_refs_in_expr_mut(
                    filter,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    local_output_names,
                    opaque_cte_names,
                );
            }
            if let Some(window) = over {
                substitute_outer_refs_in_window_spec(
                    window,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    opaque_cte_names,
                );
            }
        }
        Expr::JsonAccess { expr, path, .. } => {
            substitute_outer_refs_in_expr_mut(
                expr,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
            substitute_outer_refs_in_expr_mut(
                path,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                local_output_names,
                opaque_cte_names,
            );
        }
        Expr::RowValue(values, _) => {
            for value in values {
                substitute_outer_refs_in_expr_mut(
                    value,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    local_output_names,
                    opaque_cte_names,
                );
            }
        }
        Expr::Literal(_, _)
        | Expr::BoundOuterValue { .. }
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => {}
    }
}

/// Substitute external column references in a subquery with literal values
/// from the outer row before executing it in a per-row correlated context.
#[cfg(test)]
fn substitute_outer_refs_in_select(
    select: &mut SelectStatement,
    row: &[SqliteValue],
    outer_col_map: &[(String, String, bool)],
    using_skip: Option<&HashSet<usize>>,
    schema: &[TableSchema],
) {
    substitute_outer_refs_in_select_with_schema_context(
        select,
        row,
        outer_col_map,
        using_skip,
        None,
        None,
        schema,
        None,
        None,
    );
}

fn substitute_outer_refs_in_select_with_schema_context(
    select: &mut SelectStatement,
    row: &[SqliteValue],
    outer_col_map: &[(String, String, bool)],
    using_skip: Option<&HashSet<usize>>,
    column_collations: Option<&[Option<String>]>,
    column_affinities: Option<&[TypeAffinity]>,
    schema: &[TableSchema],
    shadowed_main_tables: Option<&HashMap<String, TableSchema>>,
    temp_table_names: Option<&HashSet<String>>,
) {
    let lookup = OuterReferenceLookup {
        row,
        col_map: outer_col_map,
        using_skip,
        replacement_exprs: None,
        column_collations,
        column_affinities,
        schema,
        shadowed_main_tables,
        temp_table_names,
        probe_unqualified_external_ref: false,
    };
    substitute_outer_refs_in_select_scoped(
        select,
        &lookup,
        &[],
        Some(&HashSet::new()),
        &HashSet::new(),
    );
}

fn substitute_outer_refs_in_select_scoped(
    select: &mut SelectStatement,
    lookup: &OuterReferenceLookup<'_>,
    ancestor_tables: &[String],
    ancestor_unqualified_columns: Option<&HashSet<String>>,
    outer_cte_names: &HashSet<String>,
) {
    let mut visible_cte_names = outer_cte_names.clone();
    if let Some(with) = &select.with {
        visible_cte_names.extend(with.ctes.iter().map(|cte| cte.name.to_ascii_lowercase()));
    }
    if let Some(with) = &mut select.with {
        for cte in &mut with.ctes {
            substitute_outer_refs_in_select_scoped(
                &mut cte.query,
                lookup,
                ancestor_tables,
                ancestor_unqualified_columns,
                &visible_cte_names,
            );
        }
    }
    substitute_outer_refs_in_select_core(
        &mut select.body.select,
        lookup,
        ancestor_tables,
        ancestor_unqualified_columns,
        &visible_cte_names,
    );
    for (_, core) in &mut select.body.compounds {
        substitute_outer_refs_in_select_core(
            core,
            lookup,
            ancestor_tables,
            ancestor_unqualified_columns,
            &visible_cte_names,
        );
    }
    // bd-2fong: statement-level ORDER BY and LIMIT resolve in the primary
    // core's scope, so correlated outer references there must substitute
    // exactly like WHERE/HAVING do. Previously only the cores were walked and
    // `... ORDER BY abs(y - outer.x) LIMIT 1` failed with NoSuchColumn on the
    // outer-qualified name. Output aliases stay local (not substituted),
    // matching WHERE/HAVING alias handling.
    if !select.order_by.is_empty() || select.limit.is_some() {
        let (protected_tables, protected_unqualified_columns, local_output_names) = {
            let core = &select.body.select;
            (
                protected_tables_for_core(core, ancestor_tables),
                protected_unqualified_columns_for_core(
                    core,
                    lookup,
                    &visible_cte_names,
                    ancestor_unqualified_columns,
                ),
                collect_select_core_result_aliases(core),
            )
        };
        for term in &mut select.order_by {
            term.expr = substitute_outer_refs_in_expr(
                &term.expr,
                lookup,
                &protected_tables,
                protected_unqualified_columns.as_ref(),
                &local_output_names,
                &visible_cte_names,
            );
        }
        if let Some(limit) = &mut select.limit {
            limit.limit = substitute_outer_refs_in_expr(
                &limit.limit,
                lookup,
                &protected_tables,
                protected_unqualified_columns.as_ref(),
                &local_output_names,
                &visible_cte_names,
            );
            if let Some(offset) = &mut limit.offset {
                *offset = substitute_outer_refs_in_expr(
                    offset,
                    lookup,
                    &protected_tables,
                    protected_unqualified_columns.as_ref(),
                    &local_output_names,
                    &visible_cte_names,
                );
            }
        }
    }
}

fn substitute_outer_refs_in_select_core(
    core: &mut SelectCore,
    lookup: &OuterReferenceLookup<'_>,
    ancestor_tables: &[String],
    ancestor_unqualified_columns: Option<&HashSet<String>>,
    opaque_cte_names: &HashSet<String>,
) {
    let protected_tables = protected_tables_for_core(core, ancestor_tables);
    let protected_unqualified_columns = protected_unqualified_columns_for_core(
        core,
        lookup,
        opaque_cte_names,
        ancestor_unqualified_columns,
    );
    let local_output_names = collect_select_core_result_aliases(core);
    let no_local_outputs = HashSet::new();
    match core {
        SelectCore::Values(rows) => {
            for expr in rows.iter_mut().flatten() {
                *expr = substitute_outer_refs_in_expr(
                    expr,
                    lookup,
                    &protected_tables,
                    protected_unqualified_columns.as_ref(),
                    &no_local_outputs,
                    opaque_cte_names,
                );
            }
        }
        SelectCore::Select {
            columns,
            from,
            where_clause,
            having,
            windows,
            ..
        } => {
            for column in columns {
                if let ResultColumn::Expr { expr, .. } = column {
                    *expr = substitute_outer_refs_in_expr(
                        expr,
                        lookup,
                        &protected_tables,
                        protected_unqualified_columns.as_ref(),
                        &no_local_outputs,
                        opaque_cte_names,
                    );
                }
            }
            if let Some(where_clause) = where_clause {
                **where_clause = substitute_outer_refs_in_expr(
                    where_clause,
                    lookup,
                    &protected_tables,
                    protected_unqualified_columns.as_ref(),
                    &local_output_names,
                    opaque_cte_names,
                );
            }
            if let Some(from) = from {
                substitute_outer_refs_in_from_clause(
                    from,
                    lookup,
                    &protected_tables,
                    protected_unqualified_columns.as_ref(),
                    opaque_cte_names,
                );
            }
            if let Some(having) = having {
                **having = substitute_outer_refs_in_expr(
                    having,
                    lookup,
                    &protected_tables,
                    protected_unqualified_columns.as_ref(),
                    &local_output_names,
                    opaque_cte_names,
                );
            }
            for window in windows {
                substitute_outer_refs_in_window_spec(
                    &mut window.spec,
                    lookup,
                    &protected_tables,
                    protected_unqualified_columns.as_ref(),
                    opaque_cte_names,
                );
            }
        }
    }
}

fn substitute_outer_refs_in_window_spec(
    window: &mut WindowSpec,
    lookup: &OuterReferenceLookup<'_>,
    protected_tables: &[String],
    protected_unqualified_columns: Option<&HashSet<String>>,
    opaque_cte_names: &HashSet<String>,
) {
    let no_local_outputs = HashSet::new();
    for expr in &mut window.partition_by {
        *expr = substitute_outer_refs_in_expr(
            expr,
            lookup,
            protected_tables,
            protected_unqualified_columns,
            &no_local_outputs,
            opaque_cte_names,
        );
    }
    for term in &mut window.order_by {
        term.expr = substitute_outer_refs_in_expr(
            &term.expr,
            lookup,
            protected_tables,
            protected_unqualified_columns,
            &no_local_outputs,
            opaque_cte_names,
        );
    }
    if let Some(frame) = &mut window.frame {
        substitute_outer_refs_in_frame_spec(
            frame,
            lookup,
            protected_tables,
            protected_unqualified_columns,
            opaque_cte_names,
        );
    }
}

fn substitute_outer_refs_in_frame_spec(
    frame: &mut FrameSpec,
    lookup: &OuterReferenceLookup<'_>,
    protected_tables: &[String],
    protected_unqualified_columns: Option<&HashSet<String>>,
    opaque_cte_names: &HashSet<String>,
) {
    substitute_outer_refs_in_frame_bound(
        &mut frame.start,
        lookup,
        protected_tables,
        protected_unqualified_columns,
        opaque_cte_names,
    );
    if let Some(end) = &mut frame.end {
        substitute_outer_refs_in_frame_bound(
            end,
            lookup,
            protected_tables,
            protected_unqualified_columns,
            opaque_cte_names,
        );
    }
}

fn substitute_outer_refs_in_frame_bound(
    bound: &mut FrameBound,
    lookup: &OuterReferenceLookup<'_>,
    protected_tables: &[String],
    protected_unqualified_columns: Option<&HashSet<String>>,
    opaque_cte_names: &HashSet<String>,
) {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            let no_local_outputs = HashSet::new();
            **expr = substitute_outer_refs_in_expr(
                expr,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                &no_local_outputs,
                opaque_cte_names,
            );
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => {}
    }
}

fn substitute_outer_refs_in_from_clause(
    from: &mut FromClause,
    lookup: &OuterReferenceLookup<'_>,
    protected_tables: &[String],
    protected_unqualified_columns: Option<&HashSet<String>>,
    opaque_cte_names: &HashSet<String>,
) {
    substitute_outer_refs_in_table_or_subquery(
        &mut from.source,
        lookup,
        protected_tables,
        protected_unqualified_columns,
        opaque_cte_names,
    );
    for join in &mut from.joins {
        substitute_outer_refs_in_table_or_subquery(
            &mut join.table,
            lookup,
            protected_tables,
            protected_unqualified_columns,
            opaque_cte_names,
        );
        if let Some(JoinConstraint::On(on_expr)) = &mut join.constraint {
            let no_local_outputs = HashSet::new();
            *on_expr = substitute_outer_refs_in_expr(
                on_expr,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                &no_local_outputs,
                opaque_cte_names,
            );
        }
    }
}

fn substitute_outer_refs_in_table_or_subquery(
    source: &mut TableOrSubquery,
    lookup: &OuterReferenceLookup<'_>,
    protected_tables: &[String],
    protected_unqualified_columns: Option<&HashSet<String>>,
    opaque_cte_names: &HashSet<String>,
) {
    match source {
        TableOrSubquery::Table { .. } => {}
        TableOrSubquery::Subquery { query, .. } => {
            substitute_outer_refs_in_select_scoped(
                query,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                opaque_cte_names,
            );
        }
        TableOrSubquery::TableFunction { args, .. } => {
            let no_local_outputs = HashSet::new();
            for expr in args {
                *expr = substitute_outer_refs_in_expr(
                    expr,
                    lookup,
                    protected_tables,
                    protected_unqualified_columns,
                    &no_local_outputs,
                    opaque_cte_names,
                );
            }
        }
        TableOrSubquery::ParenJoin(from) => {
            substitute_outer_refs_in_from_clause(
                from,
                lookup,
                protected_tables,
                protected_unqualified_columns,
                opaque_cte_names,
            );
        }
    }
}

async fn rewrite_in_ordering_terms(
    order_by: &mut [OrderingTerm],
    conn: &Connection,
    rewrite_in_subqueries: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    for term in order_by {
        rewrite_in_expr(&mut term.expr, conn, rewrite_in_subqueries, params).await?;
    }
    Ok(())
}

async fn rewrite_in_frame_bound(
    bound: &mut FrameBound,
    conn: &Connection,
    rewrite_in_subqueries: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            rewrite_in_expr(expr, conn, rewrite_in_subqueries, params).await
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => Ok(()),
    }
}

async fn rewrite_in_frame_spec(
    frame: &mut FrameSpec,
    conn: &Connection,
    rewrite_in_subqueries: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    rewrite_in_frame_bound(&mut frame.start, conn, rewrite_in_subqueries, params).await?;
    if let Some(end) = &mut frame.end {
        rewrite_in_frame_bound(end, conn, rewrite_in_subqueries, params).await?;
    }
    Ok(())
}

async fn rewrite_in_window_spec(
    window: &mut WindowSpec,
    conn: &Connection,
    rewrite_in_subqueries: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    for expr in &mut window.partition_by {
        rewrite_in_expr(expr, conn, rewrite_in_subqueries, params).await?;
    }
    rewrite_in_ordering_terms(&mut window.order_by, conn, rewrite_in_subqueries, params).await?;
    if let Some(frame) = &mut window.frame {
        rewrite_in_frame_spec(frame, conn, rewrite_in_subqueries, params).await?;
    }
    Ok(())
}

fn in_table_name_to_select_statement(name: &QualifiedName) -> SelectStatement {
    SelectStatement {
        with: None,
        body: SelectBody {
            select: SelectCore::Select {
                distinct: Distinctness::All,
                columns: vec![ResultColumn::Star],
                from: Some(FromClause {
                    source: TableOrSubquery::Table {
                        name: name.clone(),
                        alias: None,
                        index_hint: None,
                        time_travel: None,
                    },
                    joins: Vec::new(),
                }),
                where_clause: None,
                group_by: Vec::new(),
                having: None,
                windows: Vec::new(),
            },
            compounds: Vec::new(),
        },
        order_by: Vec::new(),
        limit: None,
    }
}

async fn rewrite_dml_in_expr(
    expr: &mut Expr,
    conn: &Connection,
    rewrite_in_subqueries: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    rewrite_in_expr(expr, conn, rewrite_in_subqueries, params).await
}

async fn rewrite_dml_result_columns(
    columns: &mut [ResultColumn],
    conn: &Connection,
    rewrite_in_subqueries: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    for column in columns {
        if let ResultColumn::Expr { expr, .. } = column {
            rewrite_dml_in_expr(expr, conn, rewrite_in_subqueries, params).await?;
        }
    }
    Ok(())
}

async fn rewrite_dml_limit_clause(
    limit: &mut LimitClause,
    conn: &Connection,
    rewrite_in_subqueries: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    rewrite_in_limit_clause(limit, conn, rewrite_in_subqueries, params).await
}

async fn rewrite_in_limit_clause(
    limit: &mut LimitClause,
    conn: &Connection,
    rewrite_in_subqueries: bool,
    params: Option<&[SqliteValue]>,
) -> Result<()> {
    rewrite_dml_in_expr(&mut limit.limit, conn, rewrite_in_subqueries, params).await?;
    if let Some(offset) = limit.offset.as_mut() {
        rewrite_dml_in_expr(offset, conn, rewrite_in_subqueries, params).await?;
    }
    Ok(())
}

/// bd-l2si0: Expand a row-value (tuple) comparison `(a0,..) OP (b0,..)` into the
/// equivalent scalar boolean expression. SQLite defines row-value comparisons
/// element-wise (`=`/`<>`) and lexicographically (`<`/`<=`/`>`/`>=`) with the
/// usual three-valued logic; the VDBE codegen otherwise silently collapses such
/// comparisons to false, and the table-less expression path errors on a bare
/// `RowValue`. Both operands must be the same non-empty length; returns `None`
/// for unsupported operators (e.g. `IS`) so the caller leaves the node intact.
fn expand_row_value_comparison(a: &[Expr], b: &[Expr], op: BinaryOp, span: Span) -> Option<Expr> {
    let cmp = |l: &Expr, r: &Expr, o: BinaryOp| Expr::BinaryOp {
        left: Box::new(l.clone()),
        op: o,
        right: Box::new(r.clone()),
        span,
    };
    let join = |op: BinaryOp| {
        move |acc: Expr, e: Expr| Expr::BinaryOp {
            left: Box::new(acc),
            op,
            right: Box::new(e),
            span,
        }
    };
    match op {
        // (a,b) = (c,d)  ->  a = c AND b = d
        BinaryOp::Eq => a
            .iter()
            .zip(b)
            .map(|(l, r)| cmp(l, r, BinaryOp::Eq))
            .reduce(join(BinaryOp::And)),
        // (a,b) <> (c,d)  ->  a <> c OR b <> d
        BinaryOp::Ne => a
            .iter()
            .zip(b)
            .map(|(l, r)| cmp(l, r, BinaryOp::Ne))
            .reduce(join(BinaryOp::Or)),
        // (a,b) IS (c,d)  ->  a IS c AND b IS d  (NULL-safe, componentwise).
        // Also covers `IS NOT DISTINCT FROM`, which parses to IS. (GH #170, #243)
        BinaryOp::Is => a
            .iter()
            .zip(b)
            .map(|(l, r)| cmp(l, r, BinaryOp::Is))
            .reduce(join(BinaryOp::And)),
        // (a,b) IS NOT (c,d)  ->  a IS NOT c OR b IS NOT d. Also covers
        // `IS DISTINCT FROM`, which parses to IS NOT. (GH #170, #243)
        BinaryOp::IsNot => a
            .iter()
            .zip(b)
            .map(|(l, r)| cmp(l, r, BinaryOp::IsNot))
            .reduce(join(BinaryOp::Or)),
        // Lexicographic: a0 STRICT b0 OR (a0 = b0 AND <rest>), last element uses
        // the original (possibly non-strict) operator.
        BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge => {
            let strict = match op {
                BinaryOp::Lt | BinaryOp::Le => BinaryOp::Lt,
                _ => BinaryOp::Gt,
            };
            Some(expand_row_value_order(a, b, strict, op, span))
        }
        _ => None,
    }
}

/// Recursive lexicographic expansion helper for [`expand_row_value_comparison`].
fn expand_row_value_order(
    a: &[Expr],
    b: &[Expr],
    strict: BinaryOp,
    last: BinaryOp,
    span: Span,
) -> Expr {
    let cmp = |l: &Expr, r: &Expr, o: BinaryOp| Expr::BinaryOp {
        left: Box::new(l.clone()),
        op: o,
        right: Box::new(r.clone()),
        span,
    };
    if a.len() == 1 {
        return cmp(&a[0], &b[0], last);
    }
    let head_strict = cmp(&a[0], &b[0], strict);
    let head_eq = cmp(&a[0], &b[0], BinaryOp::Eq);
    let rest = expand_row_value_order(&a[1..], &b[1..], strict, last, span);
    let and_part = Expr::BinaryOp {
        left: Box::new(head_eq),
        op: BinaryOp::And,
        right: Box::new(rest),
        span,
    };
    Expr::BinaryOp {
        left: Box::new(head_strict),
        op: BinaryOp::Or,
        right: Box::new(and_part),
        span,
    }
}

/// bd-l2si0: Recursively expand every `RowValue OP RowValue` comparison in an
/// expression tree. `IN (list)` / `IN (SELECT ...)` row values are handled by
/// `rewrite_in_expr` and are only descended into here, not transformed.
fn rewrite_row_value_comparisons(expr: &Expr) -> Expr {
    match expr {
        Expr::BinaryOp {
            left,
            op,
            right,
            span,
        } => {
            let l = rewrite_row_value_comparisons(left);
            let r = rewrite_row_value_comparisons(right);
            if let (Expr::RowValue(la, _), Expr::RowValue(ra, _)) = (&l, &r)
                && !la.is_empty()
                && la.len() == ra.len()
                && let Some(expanded) = expand_row_value_comparison(la, ra, *op, *span)
            {
                return expanded;
            }
            Expr::BinaryOp {
                left: Box::new(l),
                op: *op,
                right: Box::new(r),
                span: *span,
            }
        }
        Expr::UnaryOp {
            op,
            expr: inner,
            span,
        } => Expr::UnaryOp {
            op: *op,
            expr: Box::new(rewrite_row_value_comparisons(inner)),
            span: *span,
        },
        Expr::Between {
            expr: e,
            low,
            high,
            not,
            span,
        } => {
            let e2 = rewrite_row_value_comparisons(e);
            let low2 = rewrite_row_value_comparisons(low);
            let high2 = rewrite_row_value_comparisons(high);
            // Row-value BETWEEN expands to (e >= low) AND (e <= high); row-value
            // NOT BETWEEN to (e < low) OR (e > high) — each side compared
            // lexicographically via the row-value comparison expansion. (GH #171)
            if let (Expr::RowValue(ea, _), Expr::RowValue(la, _), Expr::RowValue(ha, _)) =
                (&e2, &low2, &high2)
                && !ea.is_empty()
                && ea.len() == la.len()
                && ea.len() == ha.len()
            {
                let (lo_op, hi_op, combine) = if *not {
                    (BinaryOp::Lt, BinaryOp::Gt, BinaryOp::Or)
                } else {
                    (BinaryOp::Ge, BinaryOp::Le, BinaryOp::And)
                };
                if let (Some(lo_cmp), Some(hi_cmp)) = (
                    expand_row_value_comparison(ea, la, lo_op, *span),
                    expand_row_value_comparison(ea, ha, hi_op, *span),
                ) {
                    return Expr::BinaryOp {
                        left: Box::new(lo_cmp),
                        op: combine,
                        right: Box::new(hi_cmp),
                        span: *span,
                    };
                }
            }
            Expr::Between {
                expr: Box::new(e2),
                low: Box::new(low2),
                high: Box::new(high2),
                not: *not,
                span: *span,
            }
        }
        Expr::In {
            expr: e,
            set,
            not,
            span,
        } => Expr::In {
            expr: Box::new(rewrite_row_value_comparisons(e)),
            set: match set {
                InSet::List(items) => {
                    InSet::List(items.iter().map(rewrite_row_value_comparisons).collect())
                }
                other => other.clone(),
            },
            not: *not,
            span: *span,
        },
        Expr::Like {
            expr: e,
            pattern,
            escape,
            op,
            not,
            span,
        } => Expr::Like {
            expr: Box::new(rewrite_row_value_comparisons(e)),
            pattern: Box::new(rewrite_row_value_comparisons(pattern)),
            escape: escape
                .as_ref()
                .map(|x| Box::new(rewrite_row_value_comparisons(x))),
            op: *op,
            not: *not,
            span: *span,
        },
        Expr::Case {
            operand,
            whens,
            else_expr,
            span,
        } => Expr::Case {
            operand: operand
                .as_ref()
                .map(|x| Box::new(rewrite_row_value_comparisons(x))),
            whens: whens
                .iter()
                .map(|(w, t)| {
                    (
                        rewrite_row_value_comparisons(w),
                        rewrite_row_value_comparisons(t),
                    )
                })
                .collect(),
            else_expr: else_expr
                .as_ref()
                .map(|x| Box::new(rewrite_row_value_comparisons(x))),
            span: *span,
        },
        Expr::Cast {
            expr: e,
            type_name,
            span,
        } => Expr::Cast {
            expr: Box::new(rewrite_row_value_comparisons(e)),
            type_name: type_name.clone(),
            span: *span,
        },
        Expr::FunctionCall {
            name,
            args,
            distinct,
            order_by,
            filter,
            over,
            span,
        } => Expr::FunctionCall {
            name: name.clone(),
            args: match args {
                FunctionArgs::List(exprs) => {
                    FunctionArgs::List(exprs.iter().map(rewrite_row_value_comparisons).collect())
                }
                FunctionArgs::Star => FunctionArgs::Star,
            },
            distinct: *distinct,
            order_by: order_by.clone(),
            filter: filter
                .as_ref()
                .map(|x| Box::new(rewrite_row_value_comparisons(x))),
            over: over.clone(),
            span: *span,
        },
        Expr::Collate {
            expr: e,
            collation,
            span,
        } => Expr::Collate {
            expr: Box::new(rewrite_row_value_comparisons(e)),
            collation: collation.clone(),
            span: *span,
        },
        Expr::IsNull { expr: e, not, span } => Expr::IsNull {
            expr: Box::new(rewrite_row_value_comparisons(e)),
            not: *not,
            span: *span,
        },
        Expr::JsonAccess {
            expr: e,
            path,
            arrow,
            span,
        } => Expr::JsonAccess {
            expr: Box::new(rewrite_row_value_comparisons(e)),
            path: Box::new(rewrite_row_value_comparisons(path)),
            arrow: *arrow,
            span: *span,
        },
        Expr::RowValue(items, span) => Expr::RowValue(
            items.iter().map(rewrite_row_value_comparisons).collect(),
            *span,
        ),
        Expr::BoundOuterValue { .. }
        | Expr::Literal(..)
        | Expr::Column(..)
        | Expr::Exists { .. }
        | Expr::Subquery(..)
        | Expr::Raise { .. }
        | Expr::Placeholder(..) => expr.clone(),
    }
}

/// bd-l2si0: Apply [`rewrite_row_value_comparisons`] across every expression in
/// a SELECT (result columns, WHERE/HAVING, GROUP BY, ORDER BY, and compounds).
fn rewrite_row_value_comparisons_in_select(select: &mut SelectStatement) {
    rewrite_row_value_comparisons_in_select_core(&mut select.body.select);
    for (_, core) in &mut select.body.compounds {
        rewrite_row_value_comparisons_in_select_core(core);
    }
    for term in &mut select.order_by {
        term.expr = rewrite_row_value_comparisons(&term.expr);
    }
}

fn rewrite_row_value_comparisons_in_select_core(core: &mut SelectCore) {
    match core {
        SelectCore::Select {
            columns,
            where_clause,
            group_by,
            having,
            ..
        } => {
            for col in columns.iter_mut() {
                if let ResultColumn::Expr { expr, .. } = col {
                    *expr = rewrite_row_value_comparisons(expr);
                }
            }
            if let Some(w) = where_clause.as_mut() {
                **w = rewrite_row_value_comparisons(w.as_ref());
            }
            for g in group_by.iter_mut() {
                *g = rewrite_row_value_comparisons(g);
            }
            if let Some(h) = having.as_mut() {
                **h = rewrite_row_value_comparisons(h.as_ref());
            }
        }
        SelectCore::Values(rows) => {
            for row in rows.iter_mut() {
                for e in row.iter_mut() {
                    *e = rewrite_row_value_comparisons(e);
                }
            }
        }
    }
}

///
/// When `rewrite_in_subqueries` is true, eagerly evaluate ALL
/// `IN (SELECT ...)` into literal lists.  When false, only eagerly
/// evaluate IN subqueries that VDBE codegen cannot handle (those with
/// GROUP BY, HAVING, windows, compounds, or WITH clauses) — simple
/// ones are left intact for VDBE runtime probe scans.
#[allow(clippy::too_many_lines)]
// Recurses into sub-expressions, so it returns a boxed future rather than using
// `async fn` sugar (a plain `async fn` cannot call itself without indirection).
fn rewrite_in_expr<'a>(
    expr: &'a mut Expr,
    conn: &'a Connection,
    rewrite_in_subqueries: bool,
    params: Option<&'a [SqliteValue]>,
) -> Pin<Box<dyn Future<Output = Result<()>> + 'a>> {
    Box::pin(async move {
        match expr {
            Expr::In {
                set,
                expr: inner,
                not,
                span,
            } => {
                let mut preserve_native_scalar_operand = false;
                if let Cow::Owned(normalized) = normalize_bare_singleton_in_subquery(set) {
                    *set = normalized;
                }
                if matches!(set, InSet::List(values) if values.is_empty()) {
                    return Ok(());
                }
                if let InSet::Table(name) = set {
                    *set = InSet::Subquery(Box::new(in_table_name_to_select_statement(name)));
                }
                if let InSet::Subquery(sub) = set {
                    // Correlated IN subqueries reference outer table columns and
                    // must be evaluated per-row; skip eager rewrite.
                    let vdbe_supported = in_subquery_supported_by_vdbe(sub, conn);
                    let is_correlated = rewrite_probe_is_correlated(conn, sub);
                    let should_eager_rewrite = !is_correlated
                        && (!vdbe_supported
                            || (rewrite_in_subqueries
                                && !conn.skip_statement_memdb_refresh.get()))
                        // frankensim-kl17o: parameter-dependent IN subqueries must
                        // not be materialized without bindings (see the Exists arm).
                        && !(params.is_none() && select_contains_any_placeholder(sub));
                    preserve_native_scalar_operand = vdbe_supported
                        && !should_eager_rewrite
                        && scalar_in_operand_supported_by_complex_vdbe(inner, sub, conn);
                    if in_subquery_has_ordered_distinct_function_fallback_hazard(sub)
                        && (!vdbe_supported || should_eager_rewrite)
                    {
                        return Err(FrankenError::NotImplemented(
                            "ordered DISTINCT function projection in an IN subquery requires \
                             deferred projection semantics"
                                .to_owned(),
                        ));
                    }
                    if should_eager_rewrite {
                        // Keep VDBE/prepare-time-compatible IN subqueries intact so
                        // the direct fast paths and one-time materialized probe code
                        // can still see the original shape. Only eager-rewrite when
                        // the caller explicitly asked for it or the compiled path
                        // cannot handle the subquery natively. Execution paths that
                        // temporarily install mirrored temp tables keep supported
                        // IN subqueries intact so recursive rewrite-time dispatch
                        // does not lose those ephemeral relations.
                        conn.validate_select_column_references(sub)?;
                        conn.validate_in_subquery_column_count(inner, sub)?;
                        let rows = conn
                            .execute_statement(&Statement::Select(*sub.clone()), params)
                            .await?;
                        if rows.is_empty() {
                            // The RHS has already run once. Keep its empty-set
                            // result without retaining the live subquery AST,
                            // which would execute it a second time downstream.
                            // SQLite still evaluates the LHS after a runtime-
                            // empty subquery (unlike a syntactic `IN ()`).
                            rewrite_in_expr(inner, conn, rewrite_in_subqueries, params).await?;
                            let replacement = empty_in_result_after_evaluating_lhs(
                                inner.as_ref().clone(),
                                *not,
                                *span,
                            );
                            *expr = replacement;
                            return Ok(());
                        }
                        let literals = conn.materialize_in_subquery_rows(inner, sub, rows)?;
                        *set = InSet::List(literals);
                    }
                }
                if let InSet::List(exprs) = set {
                    for e in exprs.iter_mut() {
                        rewrite_in_expr(e, conn, rewrite_in_subqueries, params).await?;
                    }
                }
                if !preserve_native_scalar_operand {
                    // bd-2fong: a vector-IN left-hand side legitimately carries
                    // a multi-column subquery; its width is validated against
                    // the RHS downstream (validate_in_list_lhs_shape /
                    // materialization), not by the scalar arity rule.
                    let _row_value_guard = BoolCellRestoreGuard::new(
                        &conn.scalar_subquery_row_value_context,
                        matches!(inner.as_ref(), Expr::Subquery(_, _) | Expr::RowValue(..)),
                    );
                    rewrite_in_expr(inner, conn, rewrite_in_subqueries, params).await?;
                }
                // Keep vector IN intact. The connection evaluator compares a
                // row operand once, preserves three-valued tuple semantics,
                // and applies the final RHS row's per-field affinity/collation
                // donors. Expanding to OR-of-equalities both duplicated a
                // volatile LHS and changed SQLite's vector-IN metadata rules.
            }
            Expr::Exists {
                subquery,
                not,
                span,
            } => {
                // Correlated EXISTS subqueries reference outer table columns and
                // must be evaluated per-row; skip the eager rewrite so they survive
                // into the row-level filter evaluation (eval_join_expr).
                if rewrite_probe_is_correlated(conn, subquery) {
                    return Ok(());
                }
                // frankensim-kl17o: a placeholder-bearing subquery is
                // parameter-dependent. Without bindings (prepare-time rewrite runs
                // with `params = None`) evaluating it reads NULL for every
                // placeholder and bakes the wrong literal into the compiled
                // statement for every later execution.
                if params.is_none() && select_contains_any_placeholder(subquery) {
                    return Ok(());
                }
                let rows = conn
                    .execute_statement(&Statement::Select(*subquery.clone()), params)
                    .await?;
                let exists = !rows.is_empty();
                let result = if *not { !exists } else { exists };
                *expr = Expr::Literal(Literal::Integer(i64::from(result)), *span);
            }
            Expr::Subquery(sub, span) => {
                // Correlated scalar subqueries reference outer table columns and
                // must be evaluated per-row; skip the eager rewrite so they survive
                // into the VDBE codegen which handles them via emit_scalar_subquery.
                if rewrite_probe_is_correlated(conn, sub) {
                    return Ok(());
                }
                // frankensim-kl17o: parameter-dependent subqueries must not be
                // folded without bindings (see the Exists arm above).
                if params.is_none() && select_contains_any_placeholder(sub) {
                    return Ok(());
                }
                // Only fold a *scalar* (single-column) subquery to a literal. A
                // multi-column row subquery — e.g. the RHS of a row-value assignment
                // `SET (a, b) = (SELECT a, b FROM ...)` — must survive to codegen,
                // which binds each output column to its target. Folding it here takes
                // only the first row's first value and would silently drop the rest.
                // bd-6utze. bd-2fong: outside a row-value-accepting position that
                // survival is an error, not a silent NULL — stock SQLite rejects
                // `SELECT (SELECT * FROM two_col_table)` at prepare with
                // "sub-select returns 2 columns - expected 1", while our codegen's
                // emit_scalar_subquery_result_value has no lowering for the shape
                // and would leave the register NULL.
                let column_count = conn.select_result_column_count(sub, &[], &mut Vec::new());
                if column_count != 1 {
                    if conn.scalar_subquery_row_value_context.get() {
                        return Ok(());
                    }
                    return Err(FrankenError::FunctionError(format!(
                        "sub-select returns {column_count} columns - expected 1"
                    )));
                }
                // bd-2fong red 2: a scalar subquery donates its result
                // expression's affinity to enclosing comparisons — SQLite
                // evaluates `(SELECT CAST(1 AS INTEGER)) = '1'` as 1. Folding
                // to a bare literal dropped that donor, so comparisons ran
                // with no affinity. Fold to BoundOuterValue (value +
                // affinity) whenever the subquery has a derivable affinity;
                // resolve_operand_affinity already reads it back first.
                let folded_affinity = scalar_subquery_result_affinity(sub, &conn.schema.borrow());
                let rows = conn
                    .execute_statement(&Statement::Select(*sub.clone()), params)
                    .await?;
                let val = rows
                    .into_iter()
                    .next()
                    .and_then(|row| row.values.into_iter().next())
                    .unwrap_or(SqliteValue::Null);
                *expr = if folded_affinity == TypeAffinity::Blob {
                    Expr::Literal(
                        match val {
                            SqliteValue::Integer(i) => Literal::Integer(i),
                            SqliteValue::Float(f) => Literal::Float(f),
                            SqliteValue::Text(s) => Literal::String(s.to_string()),
                            SqliteValue::Blob(b) => Literal::Blob(b.to_vec()),
                            SqliteValue::Null => Literal::Null,
                        },
                        *span,
                    )
                } else {
                    Expr::BoundOuterValue {
                        value: val,
                        collation: BoundCollation::Unspecified,
                        affinity: Some(folded_affinity),
                        span: *span,
                    }
                };
            }
            Expr::BinaryOp { left, right, .. } => {
                // bd-2fong: a comparison operand faces a row value when the
                // OTHER side is a row value (explicit tuple or a multi-column
                // subquery); only then may a multi-column subquery survive the
                // rewrite for codegen's vector comparison. `x = (SELECT a, b)`
                // stays an arity error.
                let operand_width = |expr: &Expr| -> usize {
                    match expr {
                        Expr::RowValue(values, _) => values.len(),
                        Expr::Subquery(sub, _) => {
                            conn.select_result_column_count(sub, &[], &mut Vec::new())
                        }
                        _ => 1,
                    }
                };
                // Grant the exemption only when the operand IS the subquery:
                // if it merely contains one deeper down (CASE arm, function
                // argument), that inner position is scalar and must keep the
                // arity error.
                let left_faces_row_value =
                    matches!(left.as_ref(), Expr::Subquery(_, _)) && operand_width(right) > 1;
                let right_faces_row_value =
                    matches!(right.as_ref(), Expr::Subquery(_, _)) && operand_width(left) > 1;
                {
                    let _row_value_guard = BoolCellRestoreGuard::new(
                        &conn.scalar_subquery_row_value_context,
                        left_faces_row_value,
                    );
                    rewrite_in_expr(left, conn, rewrite_in_subqueries, params).await?;
                }
                {
                    let _row_value_guard = BoolCellRestoreGuard::new(
                        &conn.scalar_subquery_row_value_context,
                        right_faces_row_value,
                    );
                    rewrite_in_expr(right, conn, rewrite_in_subqueries, params).await?;
                }
            }
            Expr::UnaryOp { expr: inner, .. }
            | Expr::IsNull { expr: inner, .. }
            | Expr::Cast { expr: inner, .. }
            | Expr::Collate { expr: inner, .. } => {
                rewrite_in_expr(inner, conn, rewrite_in_subqueries, params).await?;
            }
            Expr::Between {
                expr: inner,
                low,
                high,
                ..
            } => {
                rewrite_in_expr(inner, conn, rewrite_in_subqueries, params).await?;
                rewrite_in_expr(low, conn, rewrite_in_subqueries, params).await?;
                rewrite_in_expr(high, conn, rewrite_in_subqueries, params).await?;
            }
            Expr::Case {
                operand,
                whens,
                else_expr,
                ..
            } => {
                if let Some(op) = operand.as_mut() {
                    rewrite_in_expr(op, conn, rewrite_in_subqueries, params).await?;
                }
                for (cond, then) in whens.iter_mut() {
                    rewrite_in_expr(cond, conn, rewrite_in_subqueries, params).await?;
                    rewrite_in_expr(then, conn, rewrite_in_subqueries, params).await?;
                }
                if let Some(el) = else_expr.as_mut() {
                    rewrite_in_expr(el, conn, rewrite_in_subqueries, params).await?;
                }
            }
            Expr::FunctionCall {
                args,
                order_by,
                filter,
                over,
                ..
            } => {
                if let FunctionArgs::List(exprs) = args {
                    for e in exprs.iter_mut() {
                        rewrite_in_expr(e, conn, rewrite_in_subqueries, params).await?;
                    }
                }
                rewrite_in_ordering_terms(order_by, conn, rewrite_in_subqueries, params).await?;
                if let Some(filter_expr) = filter.as_mut() {
                    rewrite_in_expr(filter_expr, conn, rewrite_in_subqueries, params).await?;
                }
                if let Some(window) = over.as_mut() {
                    rewrite_in_window_spec(window, conn, rewrite_in_subqueries, params).await?;
                }
            }
            Expr::Like {
                expr: inner,
                pattern,
                escape,
                ..
            } => {
                rewrite_in_expr(inner, conn, rewrite_in_subqueries, params).await?;
                rewrite_in_expr(pattern, conn, rewrite_in_subqueries, params).await?;
                if let Some(escape_expr) = escape.as_mut() {
                    rewrite_in_expr(escape_expr, conn, rewrite_in_subqueries, params).await?;
                }
            }
            Expr::JsonAccess {
                expr: inner, path, ..
            } => {
                rewrite_in_expr(inner, conn, rewrite_in_subqueries, params).await?;
                rewrite_in_expr(path, conn, rewrite_in_subqueries, params).await?;
            }
            Expr::RowValue(values, _) => {
                for value in values.iter_mut() {
                    rewrite_in_expr(value, conn, rewrite_in_subqueries, params).await?;
                }
            }
            // Leaf nodes that contain no sub-expressions.
            _ => {}
        }
        Ok(())
    })
}

/// Convert a `SqliteValue` into a synthetic `Expr::Literal`.
fn value_to_literal_expr(val: SqliteValue) -> Expr {
    use fsqlite_ast::Span;
    match val {
        SqliteValue::Integer(i) => Expr::Literal(Literal::Integer(i), Span::ZERO),
        SqliteValue::Float(f) => Expr::Literal(Literal::Float(f), Span::ZERO),
        SqliteValue::Text(s) => Expr::Literal(Literal::String(s.to_string()), Span::ZERO),
        SqliteValue::Blob(b) => Expr::Literal(Literal::Blob(b.to_vec()), Span::ZERO),
        SqliteValue::Null => Expr::Literal(Literal::Null, Span::ZERO),
    }
}

/// Known aggregate function names (must match codegen.rs).
const AGG_NAMES: &[&str] = &[
    "avg",
    "count",
    "group_concat",
    "string_agg",
    "max",
    "median",
    "min",
    "percentile",
    "percentile_cont",
    "percentile_disc",
    "sum",
    "total",
];

/// Check whether a function name is a known aggregate.
fn is_agg_fn(name: &str) -> bool {
    let lower = name.to_ascii_lowercase();
    AGG_NAMES.iter().any(|&n| n == lower)
}

fn is_registry_backed_builtin_aggregate(name: &str) -> bool {
    ["median", "percentile", "percentile_cont", "percentile_disc"]
        .iter()
        .any(|builtin| name.eq_ignore_ascii_case(builtin))
}

fn builtin_aggregate_has_exact_arity(name: &str, arity: i32) -> bool {
    // GROUP_CONCAT is registered variadically for its supported 1- and
    // 2-argument forms, so a custom variadic registration replaces the
    // built-in registry entry instead of losing to an exact lookup.
    (name.eq_ignore_ascii_case("count") && matches!(arity, 0 | 1))
        || (name.eq_ignore_ascii_case("string_agg") && arity == 2)
        || (arity == 1
            && ["avg", "max", "median", "min", "sum", "total"]
                .iter()
                .any(|builtin| name.eq_ignore_ascii_case(builtin)))
        || (arity == 2
            && ["percentile", "percentile_cont", "percentile_disc"]
                .iter()
                .any(|builtin| name.eq_ignore_ascii_case(builtin)))
}

fn builtin_aggregate_accepts_arity(name: &str, arity: i32) -> bool {
    builtin_aggregate_has_exact_arity(name, arity)
        || (name.eq_ignore_ascii_case("group_concat") && matches!(arity, 1 | 2))
}

fn current_application_function_kind(name: &str, arity: i32) -> Option<ApplicationFunctionKind> {
    with_current_sync_function_registry(|registry| {
        registry
            .and_then(|registry| registry.resolve_application_function(name, arity))
            .map(|resolution| resolution.kind())
    })
}

fn custom_aggregate_overrides_builtin(
    custom_keys: &CustomAggregateArities,
    name: &str,
    arity: i32,
) -> bool {
    custom_keys
        .iter()
        .any(|((registered_name, _), registered_arity)| {
            registered_name.eq_ignore_ascii_case(name)
                && registered_arity.accepts(arity)
                && (registered_arity.declared_args() != -1
                    || !builtin_aggregate_has_exact_arity(name, arity))
        })
}

/// bd-cnwdm: the JSON1 aggregate functions `json_group_array(v)` and
/// `json_group_object(k, v)`. They are intentionally NOT in [`AGG_NAMES`] — that
/// would route them to the registry-unaware GROUP BY storage substrate. Instead
/// they are recognized here so the connection-level grouped-aggregate
/// interpreter (`eval_group_agg_join_expr`) computes them directly, preserving
/// the NULL-keeping / two-argument semantics the generic aggregate path lacks.
#[cfg(feature = "ext-json")]
fn is_builtin_json_aggregate(name: &str) -> bool {
    let lower = name.to_ascii_lowercase();
    matches!(lower.as_str(), "json_group_array" | "json_group_object")
}

#[cfg(not(feature = "ext-json"))]
fn is_builtin_json_aggregate(_name: &str) -> bool {
    false
}

/// Returns true if this is a scalar max/min call (2+ arguments), not aggregate.
fn is_scalar_max_min(name: &str, args: &FunctionArgs) -> bool {
    let lower = name.to_ascii_lowercase();
    let scalar_shape =
        (lower == "max" || lower == "min") && matches!(args, FunctionArgs::List(a) if a.len() >= 2);
    if !scalar_shape {
        return false;
    }
    let arity = aggregate_args_len_for_lookup(args);
    if let Some(kind) = current_application_function_kind(name, arity) {
        return kind == ApplicationFunctionKind::Scalar;
    }
    !with_current_sync_custom_aggregate_keys(|keys| {
        keys.is_some_and(|keys| custom_aggregate_overrides_builtin(keys, name, arity))
    })
}

fn validate_nonaggregate_index_function(
    registry: &FunctionRegistry,
    name: &str,
    arity: i32,
    allow_unresolved: bool,
) -> std::result::Result<(), String> {
    match registry.scalar_accepts_arg_count(name, arity) {
        Some(true) => {
            return match registry.scalar_is_deterministic(name, arity) {
                Some(true) => Ok(()),
                Some(false) | None => Err(format!(
                    "non-deterministic functions prohibited in index expressions: {name}()"
                )),
            };
        }
        Some(false) => {
            return Err(format!("wrong number of arguments to function {name}()"));
        }
        None => {}
    }

    if registry.aggregate_accepts_arg_count(name, arity).is_some() {
        return Err(format!("misuse of aggregate function {name}()"));
    }
    if registry.window_accepts_arg_count(name, arity).is_some() {
        return Err(format!("misuse of window function {name}()"));
    }
    if allow_unresolved {
        Ok(())
    } else {
        Err(format!("no such function: {name}"))
    }
}

fn visit_index_expr_function_calls(
    expr: &Expr,
    visit: &mut impl FnMut(&str, &FunctionArgs) -> std::result::Result<(), String>,
) -> std::result::Result<(), String> {
    match expr {
        Expr::BoundOuterValue { .. } => {
            Err("internal bound outer value is not valid in persisted index expressions".to_owned())
        }
        Expr::Literal(
            Literal::CurrentDate | Literal::CurrentTime | Literal::CurrentTimestamp,
            ..,
        ) => Err(format!(
            "non-deterministic functions prohibited in index expressions: {expr}"
        )),
        Expr::Literal(..)
        | Expr::Column(..)
        | Expr::Exists { .. }
        | Expr::Subquery(..)
        | Expr::Raise { .. }
        | Expr::Placeholder(..) => Ok(()),
        Expr::BinaryOp { left, right, .. } => {
            visit_index_expr_function_calls(left, visit)?;
            visit_index_expr_function_calls(right, visit)
        }
        Expr::JsonAccess {
            expr, path, arrow, ..
        } => {
            let name = match arrow {
                JsonArrow::Arrow => "->",
                JsonArrow::DoubleArrow => "->>",
            };
            let args = FunctionArgs::List(vec![expr.as_ref().clone(), path.as_ref().clone()]);
            visit(name, &args)?;
            visit_index_expr_function_calls(expr, visit)?;
            visit_index_expr_function_calls(path, visit)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => visit_index_expr_function_calls(expr, visit),
        Expr::Between {
            expr, low, high, ..
        } => {
            visit_index_expr_function_calls(expr, visit)?;
            visit_index_expr_function_calls(low, visit)?;
            visit_index_expr_function_calls(high, visit)
        }
        Expr::In { expr, set, .. } => {
            visit_index_expr_function_calls(expr, visit)?;
            if let InSet::List(values) = set {
                for value in values {
                    visit_index_expr_function_calls(value, visit)?;
                }
            }
            Ok(())
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            op,
            ..
        } => {
            let name = match op {
                LikeOp::Like => "LIKE",
                LikeOp::Glob => "GLOB",
                LikeOp::Match => "MATCH",
                LikeOp::Regexp => "REGEXP",
            };
            let mut args = vec![pattern.as_ref().clone(), expr.as_ref().clone()];
            if let Some(escape) = escape {
                args.push(escape.as_ref().clone());
            }
            visit(name, &FunctionArgs::List(args))?;
            visit_index_expr_function_calls(expr, visit)?;
            visit_index_expr_function_calls(pattern, visit)?;
            if let Some(escape) = escape {
                visit_index_expr_function_calls(escape, visit)?;
            }
            Ok(())
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                visit_index_expr_function_calls(operand, visit)?;
            }
            for (when_expr, then_expr) in whens {
                visit_index_expr_function_calls(when_expr, visit)?;
                visit_index_expr_function_calls(then_expr, visit)?;
            }
            if let Some(else_expr) = else_expr {
                visit_index_expr_function_calls(else_expr, visit)?;
            }
            Ok(())
        }
        Expr::FunctionCall {
            name,
            args,
            order_by,
            filter,
            ..
        } => {
            visit(name, args)?;
            if let FunctionArgs::List(values) = args {
                for value in values {
                    visit_index_expr_function_calls(value, visit)?;
                }
            }
            for term in order_by {
                visit_index_expr_function_calls(&term.expr, visit)?;
            }
            if let Some(filter) = filter {
                visit_index_expr_function_calls(filter, visit)?;
            }
            Ok(())
        }
        Expr::RowValue(values, _) => {
            for value in values {
                visit_index_expr_function_calls(value, visit)?;
            }
            Ok(())
        }
    }
}

pub(crate) fn validate_builtin_persisted_index_expr_functions(
    expr: &Expr,
) -> std::result::Result<(), String> {
    visit_index_expr_function_calls(expr, &mut |name, args| {
        let builtin_scalar_max_min = (name.eq_ignore_ascii_case("max")
            || name.eq_ignore_ascii_case("min"))
            && matches!(args, FunctionArgs::List(values) if values.len() >= 2);
        if (is_agg_fn(name) || is_builtin_json_aggregate(name)) && !builtin_scalar_max_min {
            return Err(format!("misuse of aggregate function {name}()"));
        }
        validate_nonaggregate_index_function(
            shared_builtin_function_registry().as_ref(),
            name,
            aggregate_args_len_for_lookup(args),
            true,
        )
    })
}

fn is_current_aggregate_fn(name: &str, args: &FunctionArgs) -> bool {
    let arity = aggregate_args_len_for_lookup(args);
    if let Some(kind) = current_application_function_kind(name, arity) {
        return kind.is_aggregate_callable();
    }
    is_agg_fn(name)
        || with_current_sync_custom_aggregate_keys(|keys| {
            keys.is_some_and(|keys| custom_aggregate_overrides_builtin(keys, name, arity))
        })
}

fn is_current_aggregate_or_json_fn(name: &str, args: &FunctionArgs) -> bool {
    let arity = aggregate_args_len_for_lookup(args);
    if let Some(kind) = current_application_function_kind(name, arity) {
        return kind.is_aggregate_callable();
    }
    is_agg_fn(name)
        || is_builtin_json_aggregate(name)
        || with_current_sync_custom_aggregate_keys(|keys| {
            keys.is_some_and(|keys| custom_aggregate_overrides_builtin(keys, name, arity))
        })
}

/// Check whether an expression tree contains any aggregate function calls.
fn expr_contains_agg(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall {
            name, args, over, ..
        } => {
            // A windowed function (`f(...) OVER (...)`) is a window function, not a
            // bare aggregate; e.g. `ORDER BY count(*) OVER ()` is legal, so a windowed
            // call must not make an expression count as aggregate-bearing.
            if over.is_none()
                && is_current_aggregate_or_json_fn(name, args)
                && !is_scalar_max_min(name, args)
            {
                return true;
            }
            match args {
                FunctionArgs::List(exprs) => exprs.iter().any(expr_contains_agg),
                FunctionArgs::Star => false,
            }
        }
        Expr::BinaryOp { left, right, .. } => expr_contains_agg(left) || expr_contains_agg(right),
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => expr_contains_agg(inner),
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => expr_contains_agg(inner) || expr_contains_agg(low) || expr_contains_agg(high),
        Expr::In {
            expr: inner, set, ..
        } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return false;
            }
            expr_contains_agg(inner)
                || match set {
                    InSet::List(exprs) => exprs.iter().any(expr_contains_agg),
                    InSet::Subquery(_) | InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            expr_contains_agg(inner)
                || expr_contains_agg(pattern)
                || escape.as_deref().is_some_and(expr_contains_agg)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_ref().is_some_and(|e| expr_contains_agg(e))
                || whens
                    .iter()
                    .any(|(w, t)| expr_contains_agg(w) || expr_contains_agg(t))
                || else_expr.as_ref().is_some_and(|e| expr_contains_agg(e))
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => expr_contains_agg(inner) || expr_contains_agg(path),
        Expr::RowValue(values, _) => values.iter().any(expr_contains_agg),
        _ => false,
    }
}

fn aggregate_args_len_for_lookup(args: &FunctionArgs) -> i32 {
    match args {
        FunctionArgs::List(exprs) => i32::try_from(exprs.len()).unwrap_or(i32::MAX),
        FunctionArgs::Star => 0,
    }
}

fn json_access_function_name(arrow: JsonArrow) -> &'static str {
    match arrow {
        JsonArrow::Arrow => "->",
        JsonArrow::DoubleArrow => "->>",
    }
}

fn expr_contains_registered_agg(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall {
            name, args, over, ..
        } => {
            if over.is_none()
                && is_current_aggregate_or_json_fn(name, args)
                && !is_scalar_max_min(name, args)
            {
                return true;
            }
            match args {
                FunctionArgs::List(exprs) => exprs.iter().any(expr_contains_registered_agg),
                FunctionArgs::Star => false,
            }
        }
        Expr::BinaryOp { left, right, .. } => {
            expr_contains_registered_agg(left) || expr_contains_registered_agg(right)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => expr_contains_registered_agg(inner),
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            expr_contains_registered_agg(inner)
                || expr_contains_registered_agg(low)
                || expr_contains_registered_agg(high)
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return false;
            }
            expr_contains_registered_agg(inner)
                || match set {
                    InSet::List(exprs) => exprs.iter().any(expr_contains_registered_agg),
                    InSet::Subquery(_) | InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            expr_contains_registered_agg(inner)
                || expr_contains_registered_agg(pattern)
                || escape.as_deref().is_some_and(expr_contains_registered_agg)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_ref()
                .is_some_and(|expr| expr_contains_registered_agg(expr))
                || whens.iter().any(|(when_expr, then_expr)| {
                    expr_contains_registered_agg(when_expr)
                        || expr_contains_registered_agg(then_expr)
                })
                || else_expr
                    .as_ref()
                    .is_some_and(|expr| expr_contains_registered_agg(expr))
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => expr_contains_registered_agg(inner) || expr_contains_registered_agg(path),
        Expr::RowValue(values, _) => values.iter().any(expr_contains_registered_agg),
        _ => false,
    }
}

fn expr_contains_custom_registered_agg(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall {
            name, args, over, ..
        } => {
            let arity = aggregate_args_len_for_lookup(args);
            let custom_or_json_aggregate = current_application_function_kind(name, arity)
                .map_or_else(
                    || {
                        is_builtin_json_aggregate(name)
                            || with_current_sync_custom_aggregate_keys(|keys| {
                                keys.is_some_and(|keys| {
                                    custom_aggregate_overrides_builtin(keys, name, arity)
                                })
                            })
                    },
                    ApplicationFunctionKind::is_aggregate_callable,
                );
            if over.is_none() && !is_scalar_max_min(name, args) && custom_or_json_aggregate {
                return true;
            }
            match args {
                FunctionArgs::List(exprs) => exprs.iter().any(expr_contains_custom_registered_agg),
                FunctionArgs::Star => false,
            }
        }
        Expr::BinaryOp { left, right, .. } => {
            expr_contains_custom_registered_agg(left) || expr_contains_custom_registered_agg(right)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => expr_contains_custom_registered_agg(inner),
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            expr_contains_custom_registered_agg(inner)
                || expr_contains_custom_registered_agg(low)
                || expr_contains_custom_registered_agg(high)
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return false;
            }
            expr_contains_custom_registered_agg(inner)
                || match set {
                    InSet::List(exprs) => exprs.iter().any(expr_contains_custom_registered_agg),
                    InSet::Subquery(_) | InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            expr_contains_custom_registered_agg(inner)
                || expr_contains_custom_registered_agg(pattern)
                || escape
                    .as_deref()
                    .is_some_and(expr_contains_custom_registered_agg)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_ref()
                .is_some_and(|expr| expr_contains_custom_registered_agg(expr))
                || whens.iter().any(|(when_expr, then_expr)| {
                    expr_contains_custom_registered_agg(when_expr)
                        || expr_contains_custom_registered_agg(then_expr)
                })
                || else_expr
                    .as_ref()
                    .is_some_and(|expr| expr_contains_custom_registered_agg(expr))
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => {
            expr_contains_custom_registered_agg(inner) || expr_contains_custom_registered_agg(path)
        }
        Expr::RowValue(values, _) => values.iter().any(expr_contains_custom_registered_agg),
        _ => false,
    }
}

fn insert_may_observe_change_tracking(insert: &InsertStatement) -> bool {
    insert.with.as_ref().is_some_and(|with| {
        with.ctes
            .iter()
            .any(|cte| select_may_observe_change_tracking(&cte.query))
    }) || match &insert.source {
        InsertSource::Values(rows) => rows.iter().flatten().any(expr_may_observe_change_tracking),
        InsertSource::Select(select) => select_may_observe_change_tracking(select),
        InsertSource::DefaultValues => false,
    } || insert
        .upsert
        .iter()
        .any(upsert_clause_may_observe_change_tracking)
        || insert
            .returning
            .iter()
            .any(result_column_may_observe_change_tracking)
}

fn table_schema_may_observe_change_tracking(table: &TableSchema) -> bool {
    table
        .columns
        .iter()
        .any(column_info_may_observe_change_tracking)
}

fn column_info_may_observe_change_tracking(column: &ColumnInfo) -> bool {
    column
        .default_value
        .as_deref()
        .is_some_and(expr_sql_may_observe_change_tracking)
        || column
            .generated_expr
            .as_deref()
            .is_some_and(expr_sql_may_observe_change_tracking)
}

fn expr_sql_may_observe_change_tracking(expr_sql: &str) -> bool {
    fsqlite_parser::expr::parse_expr(expr_sql)
        .map(|expr| expr_may_observe_change_tracking(&expr))
        .unwrap_or(true)
}

fn upsert_clause_may_observe_change_tracking(clause: &UpsertClause) -> bool {
    clause.target.as_ref().is_some_and(|target| {
        target
            .where_clause
            .as_ref()
            .is_some_and(expr_may_observe_change_tracking)
    }) || match &clause.action {
        UpsertAction::Nothing => false,
        UpsertAction::Update {
            assignments,
            where_clause,
        } => {
            assignments
                .iter()
                .any(|assignment| expr_may_observe_change_tracking(&assignment.value))
                || where_clause
                    .as_deref()
                    .is_some_and(expr_may_observe_change_tracking)
        }
    }
}

fn select_may_observe_change_tracking(select: &SelectStatement) -> bool {
    select.with.as_ref().is_some_and(|with| {
        with.ctes
            .iter()
            .any(|cte| select_may_observe_change_tracking(&cte.query))
    }) || select_core_may_observe_change_tracking(&select.body.select)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_may_observe_change_tracking(core))
        || select
            .order_by
            .iter()
            .any(|term| expr_may_observe_change_tracking(&term.expr))
        || select
            .limit
            .as_ref()
            .is_some_and(limit_clause_may_observe_change_tracking)
}

fn select_core_may_observe_change_tracking(core: &SelectCore) -> bool {
    match core {
        SelectCore::Values(rows) => rows
            .iter()
            .flat_map(|row| row.iter())
            .any(expr_may_observe_change_tracking),
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            columns
                .iter()
                .any(result_column_may_observe_change_tracking)
                || from
                    .as_ref()
                    .is_some_and(from_clause_may_observe_change_tracking)
                || where_clause
                    .as_deref()
                    .is_some_and(expr_may_observe_change_tracking)
                || group_by.iter().any(expr_may_observe_change_tracking)
                || having
                    .as_deref()
                    .is_some_and(expr_may_observe_change_tracking)
                || windows
                    .iter()
                    .any(|window| window_spec_may_observe_change_tracking(&window.spec))
        }
    }
}

fn result_column_may_observe_change_tracking(column: &ResultColumn) -> bool {
    match column {
        ResultColumn::Expr { expr, .. } => expr_may_observe_change_tracking(expr),
        ResultColumn::Star | ResultColumn::TableStar(_) => false,
    }
}

fn from_clause_may_observe_change_tracking(from: &FromClause) -> bool {
    table_or_subquery_may_observe_change_tracking(&from.source)
        || from.joins.iter().any(|join| {
            table_or_subquery_may_observe_change_tracking(&join.table)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr)) if expr_may_observe_change_tracking(expr)
                )
        })
}

fn table_or_subquery_may_observe_change_tracking(source: &TableOrSubquery) -> bool {
    match source {
        TableOrSubquery::Table { .. } => false,
        TableOrSubquery::Subquery { query, .. } => select_may_observe_change_tracking(query),
        TableOrSubquery::TableFunction { args, .. } => {
            args.iter().any(expr_may_observe_change_tracking)
        }
        TableOrSubquery::ParenJoin(from) => from_clause_may_observe_change_tracking(from),
    }
}

fn limit_clause_may_observe_change_tracking(limit: &LimitClause) -> bool {
    expr_may_observe_change_tracking(&limit.limit)
        || limit
            .offset
            .as_ref()
            .is_some_and(expr_may_observe_change_tracking)
}

fn window_spec_may_observe_change_tracking(spec: &WindowSpec) -> bool {
    spec.partition_by
        .iter()
        .any(expr_may_observe_change_tracking)
        || spec
            .order_by
            .iter()
            .any(|term| expr_may_observe_change_tracking(&term.expr))
        || spec
            .frame
            .as_ref()
            .is_some_and(frame_spec_may_observe_change_tracking)
}

fn frame_spec_may_observe_change_tracking(frame: &FrameSpec) -> bool {
    frame_bound_may_observe_change_tracking(&frame.start)
        || frame
            .end
            .as_ref()
            .is_some_and(frame_bound_may_observe_change_tracking)
}

fn frame_bound_may_observe_change_tracking(bound: &FrameBound) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_may_observe_change_tracking(expr)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn function_name_observes_change_tracking(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "changes" | "total_changes" | "last_insert_rowid"
    )
}

fn expr_may_observe_change_tracking(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall {
            name,
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            function_name_observes_change_tracking(name)
                || match args {
                    FunctionArgs::List(exprs) => exprs.iter().any(expr_may_observe_change_tracking),
                    FunctionArgs::Star => false,
                }
                || order_by
                    .iter()
                    .any(|term| expr_may_observe_change_tracking(&term.expr))
                || filter
                    .as_deref()
                    .is_some_and(expr_may_observe_change_tracking)
                || over
                    .as_ref()
                    .is_some_and(window_spec_may_observe_change_tracking)
        }
        Expr::BinaryOp { left, right, .. } => {
            expr_may_observe_change_tracking(left) || expr_may_observe_change_tracking(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => expr_may_observe_change_tracking(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_may_observe_change_tracking(expr)
                || expr_may_observe_change_tracking(low)
                || expr_may_observe_change_tracking(high)
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return false;
            }
            expr_may_observe_change_tracking(expr)
                || match set {
                    InSet::List(values) => values.iter().any(expr_may_observe_change_tracking),
                    InSet::Subquery(query) => select_may_observe_change_tracking(query),
                    InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_may_observe_change_tracking(expr)
                || expr_may_observe_change_tracking(pattern)
                || escape
                    .as_deref()
                    .is_some_and(expr_may_observe_change_tracking)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(expr_may_observe_change_tracking)
                || whens.iter().any(|(when_expr, then_expr)| {
                    expr_may_observe_change_tracking(when_expr)
                        || expr_may_observe_change_tracking(then_expr)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(expr_may_observe_change_tracking)
        }
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            select_may_observe_change_tracking(subquery)
        }
        Expr::JsonAccess { expr, path, .. } => {
            expr_may_observe_change_tracking(expr) || expr_may_observe_change_tracking(path)
        }
        Expr::RowValue(values, _) => values.iter().any(expr_may_observe_change_tracking),
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => false,
    }
}

/// Compare two evaluated in-aggregate `ORDER BY` key tuples, honoring each
/// term's direction (`ASC`/`DESC`) and NULLS placement. Used by interpreted
/// aggregates and windows. (GH #266, #267)
fn cmp_in_aggregate_order_keys(
    order_by: &[OrderingTerm],
    order_collations: &[Option<String>],
    a: &[SqliteValue],
    b: &[SqliteValue],
    collation_registry: &CollationRegistry,
) -> std::cmp::Ordering {
    for (i, term) in order_by.iter().enumerate() {
        let av = &a[i];
        let bv = &b[i];
        let ord = if av.is_null() || bv.is_null() {
            if av.is_null() && bv.is_null() {
                std::cmp::Ordering::Equal
            } else {
                let nulls = term
                    .nulls
                    .unwrap_or_else(|| default_nulls_order(term.direction));
                match (av.is_null(), nulls) {
                    (true, NullsOrder::First) | (false, NullsOrder::Last) => {
                        std::cmp::Ordering::Less
                    }
                    (true, NullsOrder::Last) | (false, NullsOrder::First) => {
                        std::cmp::Ordering::Greater
                    }
                }
            }
        } else {
            let collation = order_collations.get(i).and_then(|value| value.as_deref());
            let mut o = cmp_sqlite_values_collated_snapshot(av, bv, collation, collation_registry);
            if term.direction == Some(SortDirection::Desc) {
                o = o.reverse();
            }
            o
        };
        if ord != std::cmp::Ordering::Equal {
            return ord;
        }
    }
    std::cmp::Ordering::Equal
}

fn prepare_application_aggregate_rows(
    mut entries: Vec<(Vec<SqliteValue>, Vec<SqliteValue>)>,
    distinct: bool,
    collation: Option<&str>,
    order_by: &[OrderingTerm],
    col_map: &[(String, String, bool)],
    collation_registry: &CollationRegistry,
) -> Vec<Vec<SqliteValue>> {
    if distinct {
        let mut seen = Vec::new();
        let mut saw_zero_arg_row = false;
        entries.retain(|(args, _)| {
            let Some(value) = args.first() else {
                let keep = !saw_zero_arg_row;
                saw_zero_arg_row = true;
                return keep;
            };
            if seen.iter().any(|previous| {
                cmp_sqlite_values_collated_snapshot(previous, value, collation, collation_registry)
                    == std::cmp::Ordering::Equal
            }) {
                false
            } else {
                seen.push(value.clone());
                true
            }
        });
    }
    if !order_by.is_empty() {
        let order_collations = order_by
            .iter()
            .map(|term| join_expr_effective_collation(&term.expr, col_map))
            .collect::<Vec<_>>();
        entries.sort_by(|(_, left), (_, right)| {
            cmp_in_aggregate_order_keys(
                order_by,
                &order_collations,
                left,
                right,
                collation_registry,
            )
        });
    }
    entries.into_iter().map(|(args, _)| args).collect()
}

/// Evaluate an expression that may contain aggregate function calls against
/// a group of rows. Aggregate sub-expressions are computed over the full
/// group; the remaining scalar parts are evaluated against the first row.
fn eval_group_agg_join_expr(
    expr: &Expr,
    group_rows: &[&Vec<SqliteValue>],
    col_map: &[(String, String, bool)],
) -> Result<SqliteValue> {
    match expr {
        // bd-cnwdm: JSON1 aggregates computed directly (NULL-preserving for
        // json_group_array; two-argument key/value pairs for json_group_object).
        #[cfg(feature = "ext-json")]
        Expr::FunctionCall {
            name,
            args,
            filter,
            order_by,
            distinct,
            ..
        } if is_builtin_json_aggregate(name)
            && current_application_function_kind(name, aggregate_args_len_for_lookup(args))
                .is_none() =>
        {
            let exprs = match args {
                FunctionArgs::List(e) => e.as_slice(),
                FunctionArgs::Star => &[][..],
            };
            let collation_registry = current_join_eval_collation_registry_snapshot();
            let order_collations = order_by
                .iter()
                .map(|term| join_expr_effective_collation(&term.expr, col_map))
                .collect::<Vec<_>>();
            if name.eq_ignore_ascii_case("json_group_array") {
                let arg = exprs.first().ok_or_else(|| {
                    FrankenError::function_error("json_group_array() requires 1 argument")
                })?;
                // Collect (value, ORDER BY keys) for each row that passes FILTER.
                let mut items: Vec<(SqliteValue, Vec<SqliteValue>)> = Vec::new();
                for row in group_rows {
                    if let Some(filter_expr) = filter
                        && !is_sqlite_truthy(&eval_join_expr(filter_expr, row, col_map)?)
                    {
                        continue;
                    }
                    // NULLs are preserved (rendered as JSON null).
                    let value = eval_join_expr(arg, row, col_map)?;
                    let mut keys = Vec::with_capacity(order_by.len());
                    for term in order_by {
                        keys.push(eval_join_expr(&term.expr, row, col_map)?);
                    }
                    items.push((value, keys));
                }
                // DISTINCT removes duplicate values (first occurrence wins). (GH #268)
                if *distinct {
                    let mut seen: Vec<SqliteValue> = Vec::new();
                    let distinct_collation = join_expr_effective_collation(arg, col_map);
                    items.retain(|(v, _)| {
                        if seen.iter().any(|s| {
                            cmp_sqlite_values_collated_snapshot(
                                s,
                                v,
                                distinct_collation.as_deref(),
                                &collation_registry,
                            ) == std::cmp::Ordering::Equal
                        }) {
                            false
                        } else {
                            seen.push(v.clone());
                            true
                        }
                    });
                }
                // In-aggregate ORDER BY sorts the collected values. (GH #266)
                if !order_by.is_empty() {
                    items.sort_by(|(_, ak), (_, bk)| {
                        cmp_in_aggregate_order_keys(
                            order_by,
                            &order_collations,
                            ak,
                            bk,
                            &collation_registry,
                        )
                    });
                }
                let vals: Vec<SqliteValue> = items.into_iter().map(|(v, _)| v).collect();
                Ok(SqliteValue::Text(
                    fsqlite_ext_json::json_group_array(&vals)?.into(),
                ))
            } else {
                // json_group_object(key, value)
                if exprs.len() != 2 {
                    return Err(FrankenError::function_error(
                        "json_group_object() requires 2 arguments",
                    ));
                }
                let mut items: Vec<((SqliteValue, SqliteValue), Vec<SqliteValue>)> = Vec::new();
                for row in group_rows {
                    if let Some(filter_expr) = filter
                        && !is_sqlite_truthy(&eval_join_expr(filter_expr, row, col_map)?)
                    {
                        continue;
                    }
                    let key = eval_join_expr(&exprs[0], row, col_map)?;
                    let value = eval_join_expr(&exprs[1], row, col_map)?;
                    let mut keys = Vec::with_capacity(order_by.len());
                    for term in order_by {
                        keys.push(eval_join_expr(&term.expr, row, col_map)?);
                    }
                    items.push(((key, value), keys));
                }
                // In-aggregate ORDER BY sorts the key/value pairs. (GH #267)
                if !order_by.is_empty() {
                    items.sort_by(|(_, ak), (_, bk)| {
                        cmp_in_aggregate_order_keys(
                            order_by,
                            &order_collations,
                            ak,
                            bk,
                            &collation_registry,
                        )
                    });
                }
                let pairs: Vec<(SqliteValue, SqliteValue)> =
                    items.into_iter().map(|(kv, _)| kv).collect();
                Ok(SqliteValue::Text(
                    fsqlite_ext_json::json_group_object(&pairs)?.into(),
                ))
            }
        }
        Expr::FunctionCall {
            name,
            args,
            distinct,
            filter,
            order_by,
            ..
        } if is_current_aggregate_fn(name, args) && !is_scalar_max_min(name, args) => {
            let func = name.to_ascii_lowercase();
            // Apply FILTER clause: only include rows where the filter
            // expression evaluates to true.
            let filtered_rows: Vec<&Vec<SqliteValue>> = if let Some(filter_expr) = filter {
                let mut filtered = Vec::with_capacity(group_rows.len());
                for &row in group_rows {
                    if is_sqlite_truthy(&eval_join_expr(filter_expr, row, col_map)?) {
                        filtered.push(row);
                    }
                }
                filtered
            } else {
                group_rows.to_vec()
            };
            let effective_rows: &[&Vec<SqliteValue>] = &filtered_rows;
            match args {
                FunctionArgs::Star => {
                    let aggregate_args = vec![Vec::new(); effective_rows.len()];
                    if let Some(result) =
                        invoke_current_registered_aggregate(&func, &aggregate_args, 0)
                    {
                        return result;
                    }
                    if func == "count" {
                        #[allow(clippy::cast_possible_wrap)]
                        return Ok(SqliteValue::Integer(effective_rows.len() as i64));
                    }
                    Ok(SqliteValue::Null)
                }
                FunctionArgs::List(exprs) if exprs.is_empty() => {
                    let aggregate_args = vec![Vec::new(); effective_rows.len()];
                    if let Some(result) =
                        invoke_current_registered_aggregate(&func, &aggregate_args, 0)
                    {
                        return result;
                    }
                    if func == "count" {
                        #[allow(clippy::cast_possible_wrap)]
                        return Ok(SqliteValue::Integer(effective_rows.len() as i64));
                    }
                    Ok(SqliteValue::Null)
                }
                FunctionArgs::List(exprs) => {
                    let mut aggregate_rows = Vec::with_capacity(effective_rows.len());
                    for row in effective_rows {
                        let mut values = Vec::with_capacity(exprs.len());
                        for expr in exprs {
                            values.push(eval_join_expr(expr, row, col_map)?);
                        }
                        let mut keys = Vec::with_capacity(order_by.len());
                        for term in order_by {
                            keys.push(eval_join_expr(&term.expr, row, col_map)?);
                        }
                        aggregate_rows.push((values, keys));
                    }
                    let collation_registry = current_join_eval_collation_registry_snapshot();
                    let distinct_collation = exprs
                        .first()
                        .and_then(|expr| join_expr_effective_collation(expr, col_map));
                    let aggregate_args = prepare_application_aggregate_rows(
                        aggregate_rows,
                        *distinct,
                        distinct_collation.as_deref(),
                        order_by,
                        col_map,
                        &collation_registry,
                    );
                    if let Some(result) = invoke_current_registered_aggregate(
                        &func,
                        &aggregate_args,
                        i32::try_from(exprs.len()).unwrap_or(i32::MAX),
                    ) {
                        return result;
                    }
                    let owned_values: Vec<SqliteValue> = aggregate_args
                        .into_iter()
                        .filter_map(|values| values.into_iter().next())
                        .filter(|value| !value.is_null())
                        .collect();
                    let separator = if func == "group_concat" || func == "string_agg" {
                        exprs
                            .get(1)
                            .and_then(|e| {
                                if let Expr::Literal(Literal::String(s), _) = e {
                                    Some(s.as_str())
                                } else {
                                    None
                                }
                            })
                            .or(Some(","))
                    } else {
                        None
                    };
                    let agg_refs: Vec<&SqliteValue> = owned_values.iter().collect();
                    compute_aggregate_ext(&func, &agg_refs, separator)
                }
            }
        }
        Expr::FunctionCall { name, args, .. } => {
            // Scalar function — evaluate args which may themselves contain aggs.
            let row = group_rows.first().map_or(&[][..], |row| row.as_slice());
            let application_kind =
                current_application_function_kind(name, aggregate_args_len_for_lookup(args));
            if application_kind.is_none()
                && fts5_aux_function_requires_context(name, args, row, col_map)
            {
                if let Some(result) = try_eval_fts5_aux_function(name, args, row, col_map) {
                    return result;
                }
                return Err(FrankenError::function_error(format!(
                    "unable to use function {name} in the requested context",
                )));
            }
            let arg_vals: Vec<SqliteValue> = match args {
                FunctionArgs::List(exprs) => exprs
                    .iter()
                    .map(|e| eval_group_agg_join_expr(e, group_rows, col_map))
                    .collect::<Result<Vec<_>>>()?,
                FunctionArgs::Star => vec![],
            };
            #[cfg(feature = "ext-fts5")]
            if application_kind.is_none()
                && let Some(value) = eval_fts5_scalar_fallback(name, &arg_vals)?
            {
                return Ok(value);
            }
            let collation = function_argument_collation(args, col_map);
            if let Some(result) =
                invoke_current_registered_scalar(name, &arg_vals, collation.as_deref())
            {
                return result;
            }
            Ok(eval_scalar_fn(name, &arg_vals))
        }
        Expr::BinaryOp {
            left, op, right, ..
        } => {
            let lv = eval_group_agg_join_expr(left, group_rows, col_map)?;
            let rv = eval_group_agg_join_expr(right, group_rows, col_map)?;
            Ok(eval_join_binary_op(left, &lv, *op, right, &rv, col_map))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            let base = operand
                .as_ref()
                .map(|e| eval_group_agg_join_expr(e, group_rows, col_map))
                .transpose()?;
            for (when_expr, then_expr) in whens {
                let when_val = eval_group_agg_join_expr(when_expr, group_rows, col_map)?;
                let matches = if let (Some(operand_expr), Some(b)) =
                    (operand.as_deref(), base.as_ref())
                {
                    !b.is_null()
                        && !when_val.is_null()
                        && compare_join_expr_values(operand_expr, b, when_expr, &when_val, col_map)
                            == std::cmp::Ordering::Equal
                } else {
                    is_sqlite_truthy(&when_val)
                };
                if matches {
                    return eval_group_agg_join_expr(then_expr, group_rows, col_map);
                }
            }
            if let Some(else_e) = else_expr {
                eval_group_agg_join_expr(else_e, group_rows, col_map)
            } else {
                Ok(SqliteValue::Null)
            }
        }
        Expr::IsNull { expr, not, .. } => {
            let val = eval_group_agg_join_expr(expr, group_rows, col_map)?;
            let result = if *not { !val.is_null() } else { val.is_null() };
            Ok(if result {
                SqliteValue::Integer(1)
            } else {
                SqliteValue::Integer(0)
            })
        }
        Expr::UnaryOp { op, expr, .. } => {
            let val = eval_group_agg_join_expr(expr, group_rows, col_map)?;
            match op {
                UnaryOp::Negate => match &val {
                    SqliteValue::Integer(n) => Ok(n
                        .checked_neg()
                        .map_or_else(|| SqliteValue::Float(-(*n as f64)), SqliteValue::Integer)),
                    SqliteValue::Float(f) => Ok(SqliteValue::Float(-f)),
                    _ => Ok(SqliteValue::Null),
                },
                UnaryOp::Plus => Ok(val),
                UnaryOp::Not => {
                    if val.is_null() {
                        Ok(SqliteValue::Null)
                    } else {
                        Ok(SqliteValue::Integer(i64::from(!is_sqlite_truthy(&val))))
                    }
                }
                UnaryOp::BitNot => {
                    if val.is_null() {
                        Ok(SqliteValue::Null)
                    } else {
                        Ok(SqliteValue::Integer(!val.to_integer()))
                    }
                }
            }
        }
        Expr::In {
            expr,
            set: InSet::List(list),
            not,
            ..
        } => {
            if list.is_empty() {
                return Ok(SqliteValue::Integer(i64::from(*not)));
            }
            if let Expr::RowValue(lhs_exprs, _) = expr.as_ref() {
                validate_vector_in_list_arity(lhs_exprs.len(), list)?;
                let rhs_rows = list
                    .iter()
                    .map(|list_item| {
                        let rhs_exprs = match list_item {
                            Expr::RowValue(values, _) => values.as_slice(),
                            other => std::slice::from_ref(other),
                        };
                        rhs_exprs
                            .iter()
                            .map(|rhs_expr| eval_group_agg_join_expr(rhs_expr, group_rows, col_map))
                            .collect::<Result<Vec<_>>>()
                    })
                    .collect::<Result<Vec<_>>>()?;
                let lhs = lhs_exprs
                    .iter()
                    .map(|lhs_expr| eval_group_agg_join_expr(lhs_expr, group_rows, col_map))
                    .collect::<Result<Vec<_>>>()?;
                let donor_exprs = list.last().map(|list_item| match list_item {
                    Expr::RowValue(values, _) => values.as_slice(),
                    other => std::slice::from_ref(other),
                });
                let mut saw_null = false;
                for (list_item, rhs) in list.iter().zip(&rhs_rows) {
                    let rhs_exprs = match list_item {
                        Expr::RowValue(values, _) => values.as_slice(),
                        other => std::slice::from_ref(other),
                    };
                    debug_assert_eq!(rhs_exprs.len(), lhs.len());
                    let mut tuple_has_null = false;
                    let mut tuple_all_equal = true;
                    for (field_index, (lhs_expr, lhs_value)) in
                        lhs_exprs.iter().zip(&lhs).enumerate()
                    {
                        let rhs_value = &rhs[field_index];
                        if lhs_value.is_null() || rhs_value.is_null() {
                            tuple_has_null = true;
                        } else if donor_exprs
                            .and_then(|donors| donors.get(field_index))
                            .is_none_or(|donor_expr| {
                                compare_join_expr_values(
                                    lhs_expr, lhs_value, donor_expr, rhs_value, col_map,
                                ) != std::cmp::Ordering::Equal
                            })
                        {
                            tuple_all_equal = false;
                            break;
                        }
                    }
                    if tuple_all_equal && !tuple_has_null {
                        return Ok(SqliteValue::Integer(i64::from(!*not)));
                    }
                    if tuple_all_equal {
                        saw_null = true;
                    }
                }
                return if saw_null {
                    Ok(SqliteValue::Null)
                } else {
                    Ok(SqliteValue::Integer(i64::from(*not)))
                };
            }
            let val = eval_group_agg_join_expr(expr, group_rows, col_map)?;
            if val.is_null() {
                return Ok(SqliteValue::Null);
            }
            let list_vals: Vec<SqliteValue> = list
                .iter()
                .map(|e| eval_group_agg_join_expr(e, group_rows, col_map))
                .collect::<Result<Vec<_>>>()?;
            // Three-valued IN logic: NULL list elements produce UNKNOWN,
            // so `5 IN (1, NULL, 3)` returns NULL (not FALSE).
            let mut saw_null = false;
            let mut found = false;
            let singleton_constant = list.len() == 1
                && list
                    .first()
                    .is_some_and(current_singleton_in_rhs_is_constant);
            for (list_expr, lv) in list.iter().zip(&list_vals) {
                if lv.is_null() {
                    saw_null = true;
                    continue;
                }
                let singleton_list_expr = (singleton_constant
                    || in_list_expr_is_bound_donor(list_expr))
                .then_some(list_expr);
                let ordering = compare_join_in_values(expr, &val, singleton_list_expr, lv, col_map);
                if ordering == std::cmp::Ordering::Equal {
                    found = true;
                    break;
                }
            }
            if found {
                Ok(SqliteValue::Integer(i64::from(!*not)))
            } else if saw_null {
                Ok(SqliteValue::Null)
            } else {
                Ok(SqliteValue::Integer(i64::from(*not)))
            }
        }
        Expr::Between {
            expr,
            low,
            high,
            not,
            ..
        } => {
            let val = eval_group_agg_join_expr(expr, group_rows, col_map)?;
            let lo = eval_group_agg_join_expr(low, group_rows, col_map)?;
            let hi = eval_group_agg_join_expr(high, group_rows, col_map)?;
            // Three-valued BETWEEN: `val >= lo AND val <= hi`.
            // `5 BETWEEN 10 AND NULL` → FALSE (5 >= 10 is FALSE,
            // FALSE AND UNKNOWN = FALSE).
            let ge_low = if val.is_null() || lo.is_null() {
                None // UNKNOWN
            } else {
                Some(
                    compare_join_expr_values(expr, &val, low, &lo, col_map)
                        != std::cmp::Ordering::Less,
                )
            };
            let le_high = if val.is_null() || hi.is_null() {
                None
            } else {
                Some(
                    compare_join_expr_values(expr, &val, high, &hi, col_map)
                        != std::cmp::Ordering::Greater,
                )
            };
            // Three-valued AND: FALSE ∧ UNKNOWN = FALSE.
            let in_range = match (ge_low, le_high) {
                (Some(false), _) | (_, Some(false)) => Some(false),
                (Some(true), Some(true)) => Some(true),
                _ => None, // at least one UNKNOWN, no FALSE
            };
            let result = match in_range {
                None => return Ok(SqliteValue::Null),
                Some(b) => {
                    if *not {
                        !b
                    } else {
                        b
                    }
                }
            };
            Ok(SqliteValue::Integer(i64::from(result)))
        }
        Expr::Cast {
            expr: inner,
            type_name,
            ..
        } => {
            let val = eval_group_agg_join_expr(inner, group_rows, col_map)?;
            if val.is_null() {
                return Ok(SqliteValue::Null);
            }
            Ok(apply_cast(val, &type_name.name))
        }
        Expr::Collate { expr: inner, .. } => eval_group_agg_join_expr(inner, group_rows, col_map),
        // No aggregate sub-expressions: delegate to per-row eval on first row.
        // When group_rows is empty (implicit aggregation on an empty table),
        // still try evaluating with an empty row — this correctly handles
        // literals, constants, and expressions that don't reference columns
        // (e.g. the `1` in `SELECT COUNT(*) + 1 FROM empty_table`).
        other => {
            let empty = Vec::new();
            let row: &Vec<SqliteValue> = group_rows.first().copied().unwrap_or(&empty);
            eval_join_expr(other, row, col_map)
        }
    }
}

/// Describes one result column in a GROUP BY query.
#[derive(Clone)]
enum GroupByColumn {
    /// A non-aggregate expression that appears in GROUP BY; evaluated per-group.
    Plain(Box<Expr>),
    /// An aggregate function; stores (func_name_lower, arg_col_index_or_None_for_star).
    Agg {
        name: String,
        /// Complete SQL argument syntax for an application-defined aggregate.
        /// Builtins keep this `None` so their fallback descriptor does not pay
        /// for a redundant AST clone alongside the optimized fields below.
        application_args: Option<FunctionArgs>,
        arg_col: Option<usize>,
        arg_expr: Option<Box<Expr>>,
        distinct: bool,
        separator: Option<String>,
        separator_expr: Option<Box<Expr>>,
        /// FILTER clause expression, e.g. `COUNT(*) FILTER (WHERE x > 5)`.
        filter: Option<Box<Expr>>,
        /// Collation sequence for the aggregate argument column (e.g. "NOCASE").
        /// Used for DISTINCT dedup and MIN/MAX comparison.
        collation: Option<String>,
        /// In-aggregate ORDER BY (SQLite 3.44+), e.g. `GROUP_CONCAT(x ORDER BY y)`.
        order_by: Vec<fsqlite_ast::OrderingTerm>,
    },
}

#[derive(Debug, Clone, Copy)]
struct RowidBucketSumGroupByMemScanPlan {
    group_divisor: i64,
    group_out_idx: usize,
    sum_out_idx: usize,
    sum_col_idx: usize,
}

#[derive(Debug, Clone)]
struct RowidBucketSumAccumulator {
    sum: f64,
    err: f64,
    int_sum: i64,
    has_int: bool,
    all_int: bool,
    int_overflowed: bool,
    saw_value: bool,
}

impl Default for RowidBucketSumAccumulator {
    fn default() -> Self {
        Self {
            sum: 0.0,
            err: 0.0,
            int_sum: 0,
            has_int: false,
            all_int: true,
            int_overflowed: false,
            saw_value: false,
        }
    }
}

impl RowidBucketSumAccumulator {
    fn add(&mut self, value: &SqliteValue) {
        if matches!(value, SqliteValue::Null) {
            return;
        }
        self.saw_value = true;
        match value.to_sum_numeric_value() {
            SqliteValue::Integer(n) => {
                self.has_int = true;
                if self.all_int && !self.int_overflowed {
                    match self.int_sum.checked_add(n) {
                        Some(next) => self.int_sum = next,
                        None => self.int_overflowed = true,
                    }
                }
                kbn_step(&mut self.sum, &mut self.err, n as f64);
            }
            SqliteValue::Float(f) => {
                self.all_int = false;
                kbn_step(&mut self.sum, &mut self.err, f);
            }
            SqliteValue::Null | SqliteValue::Text(_) | SqliteValue::Blob(_) => {}
        }
    }

    fn finish(&self) -> Result<SqliteValue> {
        if !self.saw_value {
            Ok(SqliteValue::Null)
        } else if self.all_int && self.int_overflowed {
            Err(FrankenError::IntegerOverflow)
        } else if self.has_int && self.all_int {
            Ok(SqliteValue::Integer(self.int_sum))
        } else {
            Ok(SqliteValue::Float(self.sum + self.err))
        }
    }
}

fn rowid_bucket_sum_group_by_mem_scan_plan(
    table: &TableSchema,
    table_label: &str,
    group_by_exprs: &[Expr],
    result_descriptors: &[GroupByColumn],
    rowid_alias_col_idx: Option<usize>,
) -> Option<RowidBucketSumGroupByMemScanPlan> {
    let [group_expr] = group_by_exprs else {
        return None;
    };
    if result_descriptors.len() != 2 {
        return None;
    }
    let rowid_alias_name = rowid_alias_col_idx
        .and_then(|idx| table.columns.get(idx).map(|column| column.name.as_str()));
    let group_divisor =
        rowid_bucket_group_divisor(group_expr, table, table_label, rowid_alias_name)?;
    let mut group_out_idx = None;
    let mut sum_out_idx = None;
    let mut sum_col_idx = None;
    for (out_idx, descriptor) in result_descriptors.iter().enumerate() {
        match descriptor {
            GroupByColumn::Plain(expr)
                if exprs_match(expr, group_expr)
                    && rowid_bucket_group_divisor(expr, table, table_label, rowid_alias_name)
                        == Some(group_divisor) =>
            {
                if group_out_idx.replace(out_idx).is_some() {
                    return None;
                }
            }
            GroupByColumn::Agg {
                name,
                application_args: _,
                arg_col: Some(col_idx),
                arg_expr: None,
                distinct: false,
                separator: None,
                separator_expr: None,
                filter: None,
                collation: _,
                order_by,
            } if name == "sum" && order_by.is_empty() && *col_idx < table.columns.len() => {
                if sum_out_idx.replace(out_idx).is_some() {
                    return None;
                }
                sum_col_idx = Some(*col_idx);
            }
            _ => return None,
        }
    }
    Some(RowidBucketSumGroupByMemScanPlan {
        group_divisor,
        group_out_idx: group_out_idx?,
        sum_out_idx: sum_out_idx?,
        sum_col_idx: sum_col_idx?,
    })
}

fn rowid_bucket_group_divisor(
    expr: &Expr,
    table: &TableSchema,
    table_label: &str,
    rowid_alias_name: Option<&str>,
) -> Option<i64> {
    let Expr::BinaryOp {
        left,
        op: BinaryOp::Divide,
        right,
        ..
    } = expr
    else {
        return None;
    };
    let Expr::Column(col_ref, _) = left.as_ref() else {
        return None;
    };
    if !column_ref_matches_table_rowid(col_ref, table, table_label, rowid_alias_name) {
        return None;
    }
    match right.as_ref() {
        Expr::Literal(Literal::Integer(divisor), _) if *divisor > 0 => Some(*divisor),
        _ => None,
    }
}

fn execute_rowid_bucket_sum_group_by_mem_rows<'a>(
    rows: impl IntoIterator<Item = (i64, &'a [SqliteValue])>,
    group_divisor: i64,
    group_out_idx: usize,
    sum_out_idx: usize,
    sum_col_idx: usize,
    rowid_alias_col_idx: Option<usize>,
) -> Result<Vec<Row>> {
    let mut result = Vec::new();
    let mut current_group = None;
    let mut accumulator = RowidBucketSumAccumulator::default();

    for (rowid, values) in rows {
        let group = rowid / group_divisor;
        if let Some(current) = current_group
            && current != group
        {
            push_rowid_bucket_sum_group_by_row(
                &mut result,
                current,
                &accumulator,
                group_out_idx,
                sum_out_idx,
            )?;
            accumulator = RowidBucketSumAccumulator::default();
        }
        current_group = Some(group);
        if Some(sum_col_idx) == rowid_alias_col_idx {
            accumulator.add(&SqliteValue::Integer(rowid));
        } else if let Some(value) = values.get(sum_col_idx) {
            accumulator.add(value);
        }
    }

    if let Some(group) = current_group {
        push_rowid_bucket_sum_group_by_row(
            &mut result,
            group,
            &accumulator,
            group_out_idx,
            sum_out_idx,
        )?;
    }
    Ok(result)
}

fn push_rowid_bucket_sum_group_by_row(
    rows: &mut Vec<Row>,
    group: i64,
    accumulator: &RowidBucketSumAccumulator,
    group_out_idx: usize,
    sum_out_idx: usize,
) -> Result<()> {
    let mut values = vec![SqliteValue::Null; 2];
    values[group_out_idx] = SqliteValue::Integer(group);
    values[sum_out_idx] = accumulator.finish()?;
    rows.push(Row { values });
    Ok(())
}

#[derive(Debug, Clone)]
enum SimpleStreamingGroupByOutput {
    Plain(Box<Expr>),
    CountStar,
    CountValue {
        arg_col: Option<usize>,
        arg_expr: Option<Box<Expr>>,
    },
    SumValue {
        arg_col: Option<usize>,
        arg_expr: Option<Box<Expr>>,
    },
    AvgValue {
        arg_col: Option<usize>,
        arg_expr: Option<Box<Expr>>,
    },
    MinValue {
        arg_col: Option<usize>,
        arg_expr: Option<Box<Expr>>,
    },
    MaxValue {
        arg_col: Option<usize>,
        arg_expr: Option<Box<Expr>>,
    },
}

#[derive(Debug, Clone)]
enum SimpleStreamingGroupByAccumulator {
    Plain,
    Count(i64),
    Sum {
        sum: f64,
        err: f64,
        int_sum: i64,
        has_int: bool,
        all_int: bool,
        int_overflowed: bool,
        saw_value: bool,
    },
    Avg {
        sum: f64,
        err: f64,
        count: u64,
    },
    Min(Option<SqliteValue>),
    Max(Option<SqliteValue>),
}

#[derive(Debug, Clone)]
struct SimpleStreamingGroupByState {
    representative_row: Vec<SqliteValue>,
    accumulators: Vec<SimpleStreamingGroupByAccumulator>,
}

fn build_simple_streaming_group_by_outputs(
    result_descriptors: &[GroupByColumn],
    having_expr: Option<&Expr>,
    order_by: &[OrderingTerm],
    expanded_columns: &[ResultColumn],
    group_collations: &[Option<String>],
) -> Option<Vec<SimpleStreamingGroupByOutput>> {
    if having_expr.is_some()
        || group_collations.iter().any(Option::is_some)
        || order_by
            .iter()
            .any(|term| resolve_order_term_idx(&term.expr, expanded_columns).is_none())
    {
        return None;
    }

    result_descriptors
        .iter()
        .map(simple_streaming_group_by_output_from_descriptor)
        .collect()
}

fn simple_streaming_group_by_output_from_descriptor(
    descriptor: &GroupByColumn,
) -> Option<SimpleStreamingGroupByOutput> {
    match descriptor {
        GroupByColumn::Plain(expr) => {
            if expr_contains_agg(expr) || expr_has_any_subquery(expr) {
                None
            } else {
                Some(SimpleStreamingGroupByOutput::Plain(expr.clone()))
            }
        }
        GroupByColumn::Agg {
            name,
            application_args: _,
            arg_col,
            arg_expr,
            distinct,
            separator,
            separator_expr,
            filter,
            collation,
            order_by,
        } => {
            if *distinct
                || filter.is_some()
                || !order_by.is_empty()
                || separator.is_some()
                || separator_expr.is_some()
                || (matches!(name.as_str(), "min" | "max") && collation.is_some())
                || arg_expr
                    .as_ref()
                    .is_some_and(|expr| expr_has_any_subquery(expr))
            {
                return None;
            }

            match name.as_str() {
                "count" if arg_col.is_none() && arg_expr.is_none() => {
                    Some(SimpleStreamingGroupByOutput::CountStar)
                }
                "count" => Some(SimpleStreamingGroupByOutput::CountValue {
                    arg_col: *arg_col,
                    arg_expr: arg_expr.clone(),
                }),
                "sum" => Some(SimpleStreamingGroupByOutput::SumValue {
                    arg_col: *arg_col,
                    arg_expr: arg_expr.clone(),
                }),
                "avg" => Some(SimpleStreamingGroupByOutput::AvgValue {
                    arg_col: *arg_col,
                    arg_expr: arg_expr.clone(),
                }),
                "min" => Some(SimpleStreamingGroupByOutput::MinValue {
                    arg_col: *arg_col,
                    arg_expr: arg_expr.clone(),
                }),
                "max" => Some(SimpleStreamingGroupByOutput::MaxValue {
                    arg_col: *arg_col,
                    arg_expr: arg_expr.clone(),
                }),
                _ => None,
            }
        }
    }
}

impl SimpleStreamingGroupByOutput {
    fn initial_accumulator(&self) -> SimpleStreamingGroupByAccumulator {
        match self {
            Self::Plain(_) => SimpleStreamingGroupByAccumulator::Plain,
            Self::CountStar | Self::CountValue { .. } => {
                SimpleStreamingGroupByAccumulator::Count(0)
            }
            Self::SumValue { .. } => SimpleStreamingGroupByAccumulator::Sum {
                sum: 0.0,
                err: 0.0,
                int_sum: 0,
                has_int: false,
                all_int: true,
                int_overflowed: false,
                saw_value: false,
            },
            Self::AvgValue { .. } => SimpleStreamingGroupByAccumulator::Avg {
                sum: 0.0,
                err: 0.0,
                count: 0,
            },
            Self::MinValue { .. } => SimpleStreamingGroupByAccumulator::Min(None),
            Self::MaxValue { .. } => SimpleStreamingGroupByAccumulator::Max(None),
        }
    }
}

impl SimpleStreamingGroupByState {
    fn new(representative_row: Vec<SqliteValue>, outputs: &[SimpleStreamingGroupByOutput]) -> Self {
        Self {
            representative_row,
            accumulators: outputs
                .iter()
                .map(SimpleStreamingGroupByOutput::initial_accumulator)
                .collect(),
        }
    }
}

fn simple_streaming_group_by_value(
    arg_col: Option<usize>,
    arg_expr: Option<&Expr>,
    row: &[SqliteValue],
    col_map: &[(String, String, bool)],
) -> Result<SqliteValue> {
    if let Some(idx) = arg_col {
        Ok(row.get(idx).cloned().unwrap_or(SqliteValue::Null))
    } else if let Some(expr) = arg_expr {
        eval_join_expr(expr, row, col_map)
    } else {
        Ok(SqliteValue::Null)
    }
}

fn update_simple_streaming_group_by_state(
    state: &mut SimpleStreamingGroupByState,
    outputs: &[SimpleStreamingGroupByOutput],
    row: &[SqliteValue],
    col_map: &[(String, String, bool)],
) -> Result<()> {
    for (output, accumulator) in outputs.iter().zip(state.accumulators.iter_mut()) {
        match (output, accumulator) {
            (SimpleStreamingGroupByOutput::Plain(_), SimpleStreamingGroupByAccumulator::Plain) => {}
            (
                SimpleStreamingGroupByOutput::CountStar,
                SimpleStreamingGroupByAccumulator::Count(count),
            ) => {
                *count += 1;
            }
            (
                SimpleStreamingGroupByOutput::CountValue { arg_col, arg_expr },
                SimpleStreamingGroupByAccumulator::Count(count),
            ) => {
                let value =
                    simple_streaming_group_by_value(*arg_col, arg_expr.as_deref(), row, col_map)?;
                if !matches!(value, SqliteValue::Null) {
                    *count += 1;
                }
            }
            (
                SimpleStreamingGroupByOutput::SumValue { arg_col, arg_expr },
                SimpleStreamingGroupByAccumulator::Sum {
                    sum,
                    err,
                    int_sum,
                    has_int,
                    all_int,
                    int_overflowed,
                    saw_value,
                },
            ) => {
                let value =
                    simple_streaming_group_by_value(*arg_col, arg_expr.as_deref(), row, col_map)?;
                if matches!(value, SqliteValue::Null) {
                    continue;
                }
                *saw_value = true;
                match value.to_sum_numeric_value() {
                    SqliteValue::Integer(n) => {
                        *has_int = true;
                        if *all_int && !*int_overflowed {
                            match int_sum.checked_add(n) {
                                Some(next) => *int_sum = next,
                                None => *int_overflowed = true,
                            }
                        }
                        kbn_step(sum, err, n as f64);
                    }
                    SqliteValue::Float(f) => {
                        *all_int = false;
                        kbn_step(sum, err, f);
                    }
                    SqliteValue::Null | SqliteValue::Text(_) | SqliteValue::Blob(_) => {}
                }
            }
            (
                SimpleStreamingGroupByOutput::AvgValue { arg_col, arg_expr },
                SimpleStreamingGroupByAccumulator::Avg { sum, err, count },
            ) => {
                let value =
                    simple_streaming_group_by_value(*arg_col, arg_expr.as_deref(), row, col_map)?;
                if matches!(value, SqliteValue::Null) {
                    continue;
                }
                match value {
                    SqliteValue::Integer(n) => kbn_step(sum, err, n as f64),
                    SqliteValue::Float(f) => kbn_step(sum, err, f),
                    other => kbn_step(sum, err, other.to_float()),
                }
                *count += 1;
            }
            (
                SimpleStreamingGroupByOutput::MinValue { arg_col, arg_expr },
                SimpleStreamingGroupByAccumulator::Min(current),
            ) => {
                let value =
                    simple_streaming_group_by_value(*arg_col, arg_expr.as_deref(), row, col_map)?;
                if matches!(value, SqliteValue::Null) {
                    continue;
                }
                match current {
                    Some(existing)
                        if cmp_sqlite_values(&value, existing) != std::cmp::Ordering::Less => {}
                    _ => *current = Some(value),
                }
            }
            (
                SimpleStreamingGroupByOutput::MaxValue { arg_col, arg_expr },
                SimpleStreamingGroupByAccumulator::Max(current),
            ) => {
                let value =
                    simple_streaming_group_by_value(*arg_col, arg_expr.as_deref(), row, col_map)?;
                if matches!(value, SqliteValue::Null) {
                    continue;
                }
                match current {
                    Some(existing)
                        if cmp_sqlite_values(&value, existing) != std::cmp::Ordering::Greater => {}
                    _ => *current = Some(value),
                }
            }
            _ => {
                return Err(FrankenError::internal(
                    "simple streaming GROUP BY output/accumulator mismatch",
                ));
            }
        }
    }
    Ok(())
}

fn finalize_simple_streaming_group_by_row(
    state: &SimpleStreamingGroupByState,
    outputs: &[SimpleStreamingGroupByOutput],
    col_map: &[(String, String, bool)],
) -> Result<Vec<SqliteValue>> {
    outputs
        .iter()
        .zip(state.accumulators.iter())
        .map(|(output, accumulator)| match (output, accumulator) {
            (SimpleStreamingGroupByOutput::Plain(expr), _) => {
                eval_join_expr(expr, &state.representative_row, col_map)
            }
            (_, SimpleStreamingGroupByAccumulator::Count(count)) => {
                Ok(SqliteValue::Integer(*count))
            }
            (
                SimpleStreamingGroupByOutput::SumValue { .. },
                SimpleStreamingGroupByAccumulator::Sum {
                    sum,
                    err,
                    int_sum,
                    has_int,
                    all_int,
                    int_overflowed,
                    saw_value,
                },
            ) => {
                if !*saw_value {
                    Ok(SqliteValue::Null)
                } else if *all_int && *int_overflowed {
                    Err(FrankenError::IntegerOverflow)
                } else if *has_int && *all_int {
                    Ok(SqliteValue::Integer(*int_sum))
                } else {
                    Ok(SqliteValue::Float(*sum + *err))
                }
            }
            (
                SimpleStreamingGroupByOutput::AvgValue { .. },
                SimpleStreamingGroupByAccumulator::Avg { sum, err, count },
            ) => {
                if *count == 0 {
                    Ok(SqliteValue::Null)
                } else {
                    Ok(SqliteValue::Float((*sum + *err) / *count as f64))
                }
            }
            (
                _,
                SimpleStreamingGroupByAccumulator::Min(value)
                | SimpleStreamingGroupByAccumulator::Max(value),
            ) => Ok(value.clone().unwrap_or(SqliteValue::Null)),
            _ => Ok(SqliteValue::Null),
        })
        .collect()
}

#[allow(clippy::too_many_lines)]
fn execute_simple_streaming_group_by_rows<I>(
    raw_rows: I,
    group_by_exprs: &[Expr],
    outputs: &[SimpleStreamingGroupByOutput],
    col_map: &[(String, String, bool)],
) -> Result<Vec<Row>>
where
    I: IntoIterator<Item = Vec<SqliteValue>>,
{
    let mut groups: BTreeMap<Vec<SqliteValue>, SimpleStreamingGroupByState> = BTreeMap::new();

    for row in raw_rows {
        let row_values = row;
        let key: Vec<SqliteValue> = group_by_exprs
            .iter()
            .map(|expr| eval_join_expr(expr, &row_values, col_map))
            .collect::<Result<_>>()?;
        match groups.entry(key) {
            std::collections::btree_map::Entry::Occupied(mut entry) => {
                update_simple_streaming_group_by_state(
                    entry.get_mut(),
                    outputs,
                    &row_values,
                    col_map,
                )?;
            }
            std::collections::btree_map::Entry::Vacant(entry) => {
                let mut state = SimpleStreamingGroupByState::new(row_values.clone(), outputs);
                update_simple_streaming_group_by_state(&mut state, outputs, &row_values, col_map)?;
                entry.insert(state);
            }
        }
    }

    if groups.is_empty() && group_by_exprs.is_empty() {
        groups.insert(
            Vec::new(),
            SimpleStreamingGroupByState::new(Vec::new(), outputs),
        );
    }

    groups
        .into_values()
        .map(|state| {
            Ok(Row {
                values: finalize_simple_streaming_group_by_row(&state, outputs, col_map)?,
            })
        })
        .collect()
}

fn execute_simple_streaming_group_by_select(
    raw_rows: Vec<Row>,
    group_by_exprs: &[Expr],
    outputs: &[SimpleStreamingGroupByOutput],
    col_map: &[(String, String, bool)],
) -> Result<Vec<Row>> {
    execute_simple_streaming_group_by_rows(
        raw_rows.into_iter().map(|row| row.values),
        group_by_exprs,
        outputs,
        col_map,
    )
}

/// Compare two expressions for structural equality, ignoring source spans.
fn exprs_match(a: &Expr, b: &Expr) -> bool {
    match (a, b) {
        (Expr::Column(ca, _), Expr::Column(cb, _)) => {
            ca.column.eq_ignore_ascii_case(&cb.column)
                && ca.table.as_deref().map(str::to_ascii_lowercase)
                    == cb.table.as_deref().map(str::to_ascii_lowercase)
        }
        (Expr::Literal(la, _), Expr::Literal(lb, _)) => la == lb,
        (
            Expr::BinaryOp {
                left: la,
                op: oa,
                right: ra,
                ..
            },
            Expr::BinaryOp {
                left: lb,
                op: ob,
                right: rb,
                ..
            },
        ) => oa == ob && exprs_match(la, lb) && exprs_match(ra, rb),
        (
            Expr::UnaryOp {
                op: oa, expr: ea, ..
            },
            Expr::UnaryOp {
                op: ob, expr: eb, ..
            },
        ) => oa == ob && exprs_match(ea, eb),
        (
            Expr::FunctionCall {
                name: na,
                args: aa,
                distinct: da,
                ..
            },
            Expr::FunctionCall {
                name: nb,
                args: ab,
                distinct: db,
                ..
            },
        ) => {
            na.eq_ignore_ascii_case(nb)
                && da == db
                && match (aa, ab) {
                    (FunctionArgs::Star, FunctionArgs::Star) => true,
                    (FunctionArgs::List(la), FunctionArgs::List(lb)) => {
                        la.len() == lb.len()
                            && la.iter().zip(lb.iter()).all(|(x, y)| exprs_match(x, y))
                    }
                    _ => false,
                }
        }
        (
            Expr::IsNull {
                expr: ea, not: na, ..
            },
            Expr::IsNull {
                expr: eb, not: nb, ..
            },
        ) => na == nb && exprs_match(ea, eb),
        (
            Expr::Cast {
                expr: ea,
                type_name: ta,
                ..
            },
            Expr::Cast {
                expr: eb,
                type_name: tb,
                ..
            },
        ) => ta.name.eq_ignore_ascii_case(&tb.name) && exprs_match(ea, eb),
        // Fallback: use the AST-level PartialEq for variants not handled
        // above (Subquery, Exists, In, Between, Case, etc.).
        _ => a == b,
    }
}

/// Resolve a column name from an expression (simple Expr::Column case).
fn expr_col_name(expr: &Expr) -> Option<&str> {
    match expr {
        Expr::Column(col_ref, _) => Some(col_ref.column.as_ref()),
        _ => None,
    }
}

#[derive(Debug, Clone)]
#[allow(dead_code)]
struct NormalizedIndexedColumnTerm {
    column_name: String,
    collation: Option<String>,
    direction: Option<SortDirection>,
}

#[derive(Debug, Clone)]
struct ReconstructedIndexDefinition {
    columns: Vec<String>,
    key_expressions: Vec<String>,
    key_sort_directions: Vec<SortDirection>,
    key_collations: Vec<Option<String>>,
    where_clause: Option<String>,
    is_unique: bool,
    /// Per-constraint `ON CONFLICT <algo>` for an implicit UNIQUE/PK autoindex
    /// (reconstructed from the CREATE TABLE SQL on reload). `None` for explicit
    /// CREATE INDEX (which cannot declare a conflict clause).
    conflict_action: Option<fsqlite_ast::ConflictAction>,
}

/// One declaration-order slot in SQLite's implicit autoindex layout.
///
/// WITHOUT ROWID primary keys retain their slot/name for schema semantics but
/// use the table B-tree itself, so they must never be inserted into
/// `TableSchema::indexes` as though they owned an independent root page.
#[derive(Debug, Clone)]
pub(crate) struct ImplicitAutoindexSlot {
    definition: ReconstructedIndexDefinition,
    primary_key: bool,
    hidden_without_rowid_primary_key: bool,
}

impl ImplicitAutoindexSlot {
    #[must_use]
    pub(crate) const fn is_hidden_without_rowid_primary_key(&self) -> bool {
        self.hidden_without_rowid_primary_key
    }

    #[must_use]
    pub(crate) fn columns(&self) -> &[String] {
        &self.definition.columns
    }

    #[must_use]
    pub(crate) fn key_collations(&self) -> &[Option<String>] {
        &self.definition.key_collations
    }

    #[must_use]
    pub(crate) fn into_index_schema(
        self,
        table_name: &str,
        ordinal: usize,
        root_page: i32,
    ) -> IndexSchema {
        IndexSchema {
            name: format!("sqlite_autoindex_{table_name}_{ordinal}"),
            root_page,
            columns: self.definition.columns,
            key_expressions: self.definition.key_expressions,
            key_sort_directions: self.definition.key_sort_directions,
            key_collations: self.definition.key_collations,
            where_clause: self.definition.where_clause,
            is_unique: self.definition.is_unique,
            conflict_action: self.definition.conflict_action,
        }
    }
}

fn parse_autoindex_ordinal(index_name: &str, table_name: &str) -> Option<usize> {
    let index_name_lower = index_name.to_ascii_lowercase();
    let prefix = format!("sqlite_autoindex_{}_", table_name.to_ascii_lowercase());
    let suffix = index_name_lower.strip_prefix(&prefix)?;
    if suffix.is_empty() || suffix.starts_with('0') || !suffix.chars().all(|ch| ch.is_ascii_digit())
    {
        return None;
    }
    let ordinal = suffix.parse::<usize>().ok()?;
    (ordinal.to_string() == suffix).then_some(ordinal)
}

fn column_def_declared_collation(column: &fsqlite_ast::ColumnDef) -> Option<String> {
    // SQLite applies the final column COLLATE clause when a malformed-but-
    // accepted declaration repeats it. Use the same effective collation for
    // schema metadata and implicit-index deduplication.
    column.constraints.iter().rev().find_map(|constraint| {
        if let ColumnConstraintKind::Collate(name) = &constraint.kind {
            Some(name.clone())
        } else {
            None
        }
    })
}

fn implicit_autoindex_collations_match(lhs: Option<&str>, rhs: Option<&str>) -> bool {
    match (lhs, rhs) {
        (None, None) => true,
        (Some(lhs), Some(rhs)) => lhs.eq_ignore_ascii_case(rhs),
        (Some(collation), None) | (None, Some(collation)) => {
            collation.eq_ignore_ascii_case("BINARY")
        }
    }
}

fn implicit_autoindex_keys_match(
    lhs: &ReconstructedIndexDefinition,
    rhs: &ReconstructedIndexDefinition,
) -> bool {
    lhs.columns.len() == rhs.columns.len()
        && lhs.key_collations.len() == rhs.key_collations.len()
        && lhs
            .columns
            .iter()
            .zip(&rhs.columns)
            .all(|(lhs, rhs)| lhs.eq_ignore_ascii_case(rhs))
        && lhs
            .key_collations
            .iter()
            .zip(&rhs.key_collations)
            .all(|(lhs, rhs)| implicit_autoindex_collations_match(lhs.as_deref(), rhs.as_deref()))
}

fn merge_implicit_autoindex_slot(
    slots: &mut Vec<ImplicitAutoindexSlot>,
    mut candidate: ImplicitAutoindexSlot,
    without_rowid: bool,
) -> Result<()> {
    if let Some(existing) = slots
        .iter_mut()
        .find(|slot| implicit_autoindex_keys_match(&slot.definition, &candidate.definition))
    {
        match (
            existing.definition.conflict_action,
            candidate.definition.conflict_action,
        ) {
            (Some(existing_action), Some(candidate_action))
                if existing_action != candidate_action =>
            {
                return Err(FrankenError::FunctionError(
                    "conflicting ON CONFLICT clauses specified".to_owned(),
                ));
            }
            (None, Some(candidate_action)) => {
                existing.definition.conflict_action = Some(candidate_action);
            }
            _ => {}
        }
        if candidate.primary_key {
            existing.primary_key = true;
            existing.hidden_without_rowid_primary_key = without_rowid;
        }
        return Ok(());
    }

    candidate.hidden_without_rowid_primary_key = without_rowid && candidate.primary_key;
    slots.push(candidate);
    Ok(())
}

fn implicit_autoindex_slot(
    columns: Vec<String>,
    directions: Vec<SortDirection>,
    collations: Vec<Option<String>>,
    conflict_action: Option<fsqlite_ast::ConflictAction>,
    primary_key: bool,
) -> ImplicitAutoindexSlot {
    ImplicitAutoindexSlot {
        definition: ReconstructedIndexDefinition {
            columns,
            key_expressions: Vec::new(),
            key_sort_directions: directions,
            key_collations: collations,
            where_clause: None,
            is_unique: true,
            conflict_action,
        },
        primary_key,
        hidden_without_rowid_primary_key: false,
    }
}

pub(crate) fn column_def_is_exact_integer(column: &fsqlite_ast::ColumnDef) -> bool {
    column.type_name.as_ref().is_some_and(|type_name| {
        type_name.name.eq_ignore_ascii_case("INTEGER")
            && type_name.arg1.is_none()
            && type_name.arg2.is_none()
    })
}

/// Reconstruct SQLite's declaration-slot layout for implicit UNIQUE/PRIMARY
/// KEY indexes. Distinct candidates consume ordinals even when a WITHOUT
/// ROWID primary key is hidden on the table root. Provisional INTEGER PRIMARY
/// KEY declarations are handled after ordinary candidates, matching SQLite's
/// WITHOUT ROWID conversion pass.
pub(crate) fn implicit_autoindex_layout(
    columns: &[fsqlite_ast::ColumnDef],
    constraints: &[fsqlite_ast::TableConstraint],
    without_rowid: bool,
) -> Result<Vec<ImplicitAutoindexSlot>> {
    let primary_key_count = columns
        .iter()
        .flat_map(|column| &column.constraints)
        .filter(|constraint| matches!(constraint.kind, ColumnConstraintKind::PrimaryKey { .. }))
        .count()
        + constraints
            .iter()
            .filter(|constraint| matches!(constraint.kind, TableConstraintKind::PrimaryKey { .. }))
            .count();
    if primary_key_count > 1 {
        return Err(FrankenError::FunctionError(
            "table has more than one primary key".to_owned(),
        ));
    }

    let mut slots = Vec::new();
    let mut deferred_integer_primary_keys = Vec::new();

    for column in columns {
        let collation = column_def_declared_collation(column);
        let exact_integer = column_def_is_exact_integer(column);
        for constraint in &column.constraints {
            let (primary_key, direction, conflict_action, provisional_ipk) = match &constraint.kind
            {
                ColumnConstraintKind::Unique { conflict } => {
                    (false, SortDirection::Asc, *conflict, false)
                }
                ColumnConstraintKind::PrimaryKey {
                    direction,
                    conflict,
                    ..
                } => {
                    let direction = direction.unwrap_or(SortDirection::Asc);
                    (
                        true,
                        direction,
                        *conflict,
                        exact_integer && direction != SortDirection::Desc,
                    )
                }
                _ => continue,
            };
            let candidate = implicit_autoindex_slot(
                vec![column.name.clone()],
                vec![direction],
                vec![collation.clone()],
                conflict_action,
                primary_key,
            );
            if provisional_ipk {
                deferred_integer_primary_keys.push(candidate);
            } else {
                merge_implicit_autoindex_slot(&mut slots, candidate, without_rowid)?;
            }
        }
    }

    for constraint in constraints {
        let (indexed_columns, primary_key, conflict_action) = match &constraint.kind {
            TableConstraintKind::Unique {
                columns, conflict, ..
            } => (columns, false, *conflict),
            TableConstraintKind::PrimaryKey {
                columns, conflict, ..
            } => (columns, true, *conflict),
            _ => continue,
        };
        let normalized_terms =
            collect_effective_index_terms_for_column_defs(indexed_columns, columns).ok_or_else(
                || {
                    FrankenError::FunctionError(
                        "expressions prohibited in PRIMARY KEY and UNIQUE constraints".to_owned(),
                    )
                },
            )?;
        if normalized_terms.is_empty() {
            continue;
        }
        for term in &normalized_terms {
            if !columns
                .iter()
                .any(|column| column.name.eq_ignore_ascii_case(&term.column_name))
            {
                return Err(FrankenError::FunctionError(format!(
                    "no such column: {}",
                    term.column_name
                )));
            }
        }
        let provisional_ipk = primary_key
            && normalized_terms.len() == 1
            && columns.iter().any(|column| {
                column
                    .name
                    .eq_ignore_ascii_case(&normalized_terms[0].column_name)
                    && column_def_is_exact_integer(column)
            });
        let mut candidate_collations = normalized_terms
            .iter()
            .map(|term| term.collation.clone())
            .collect::<Vec<_>>();
        if provisional_ipk {
            // SQLite rebuilds a deferred table-level INTEGER PRIMARY KEY from
            // the bare column token during WITHOUT ROWID conversion. The term
            // direction survives, but an explicit term COLLATE does not; the
            // column's final declared collation becomes effective instead.
            candidate_collations[0] = columns
                .iter()
                .find(|column| {
                    column
                        .name
                        .eq_ignore_ascii_case(&normalized_terms[0].column_name)
                })
                .and_then(column_def_declared_collation);
        }
        let candidate = implicit_autoindex_slot(
            normalized_terms
                .iter()
                .map(|term| term.column_name.clone())
                .collect(),
            normalized_terms
                .iter()
                .map(|term| term.direction.unwrap_or(SortDirection::Asc))
                .collect(),
            candidate_collations,
            conflict_action,
            primary_key,
        );
        if provisional_ipk {
            deferred_integer_primary_keys.push(candidate);
        } else {
            merge_implicit_autoindex_slot(&mut slots, candidate, without_rowid)?;
        }
    }

    // A rowid table's provisional INTEGER PRIMARY KEY is the rowid alias and
    // owns no index slot. WITHOUT ROWID conversion instead appends/promotes it
    // after all ordinary candidates and binds that final PK slot to the table.
    if without_rowid {
        for candidate in deferred_integer_primary_keys {
            merge_implicit_autoindex_slot(&mut slots, candidate, true)?;
        }
    }

    Ok(slots)
}

fn column_def_collation_by_name(
    columns: &[fsqlite_ast::ColumnDef],
    column_name: &str,
) -> Option<String> {
    columns
        .iter()
        .find(|column| column.name.eq_ignore_ascii_case(column_name))
        .and_then(column_def_declared_collation)
}

fn collect_effective_index_terms_for_column_defs(
    indexed_columns: &[fsqlite_ast::IndexedColumn],
    columns: &[fsqlite_ast::ColumnDef],
) -> Option<Vec<NormalizedIndexedColumnTerm>> {
    indexed_columns
        .iter()
        .map(|indexed| {
            let mut term = normalize_indexed_column_term(indexed)?;
            if term.collation.is_none() {
                term.collation = column_def_collation_by_name(columns, &term.column_name);
            }
            Some(term)
        })
        .collect()
}

fn rename_fk_parent_table(fk: &mut FkDef, old: &str, new: &str) -> bool {
    if !fk.parent_table.eq_ignore_ascii_case(old) {
        return false;
    }
    fk.parent_table.clear();
    fk.parent_table.push_str(new);
    true
}

fn rename_fk_parent_columns(fk: &mut FkDef, parent_table: &str, old: &str, new: &str) -> bool {
    if !fk.parent_table.eq_ignore_ascii_case(parent_table) {
        return false;
    }
    fk.parent_columns.iter_mut().fold(false, |changed, column| {
        if column.eq_ignore_ascii_case(old) {
            column.clear();
            column.push_str(new);
            true
        } else {
            changed
        }
    })
}

fn schema_table_index_or_view_name_exists(
    schema: &[TableSchema],
    views: &[ViewDef],
    name: &str,
) -> bool {
    schema.iter().any(|table| {
        table.name.eq_ignore_ascii_case(name)
            || table
                .indexes
                .iter()
                .any(|index| index.name.eq_ignore_ascii_case(name))
    }) || views
        .iter()
        .any(|view| view.name.eq_ignore_ascii_case(name))
}

fn render_create_view_sql(view: &ViewDef) -> String {
    fsqlite_ast::CreateViewStatement {
        if_not_exists: false,
        temporary: view.temporary,
        name: QualifiedName::bare(view.name.clone()),
        columns: view.columns.clone(),
        query: view.query.clone(),
    }
    .to_string()
}

fn render_create_trigger_sql(trigger: &TriggerDef) -> String {
    fsqlite_ast::CreateTriggerStatement {
        if_not_exists: false,
        temporary: trigger.temporary,
        name: QualifiedName::bare(trigger.name.clone()),
        timing: trigger.timing,
        event: trigger.event.clone(),
        table: trigger.table_name.clone(),
        for_each_row: trigger.for_each_row,
        when: trigger.when_clause.clone(),
        body: trigger.body.clone(),
    }
    .to_string()
}

#[derive(Default)]
struct TableRenameScope {
    changed: bool,
    renamed_unaliased_source: bool,
    old_alias_present: bool,
}

impl TableRenameScope {
    fn merge(&mut self, other: Self) {
        self.changed |= other.changed;
        self.renamed_unaliased_source |= other.renamed_unaliased_source;
        self.old_alias_present |= other.old_alias_present;
    }

    const fn should_rename_qualifiers(&self) -> bool {
        self.renamed_unaliased_source && !self.old_alias_present
    }
}

fn rename_table_refs_in_statement(statement: &mut Statement, old: &str, new: &str) -> bool {
    let mut changed = false;
    match statement {
        Statement::Select(select) => rename_table_refs_in_select(select, old, new),
        Statement::Insert(insert) => rename_table_refs_in_insert_statement(insert, old, new),
        Statement::Update(update) => rename_table_refs_in_update_statement(update, old, new),
        Statement::Delete(delete) => rename_table_refs_in_delete_statement(delete, old, new),
        Statement::Explain { stmt, .. } => rename_table_refs_in_statement(stmt, old, new),
        Statement::Reindex(Some(name)) | Statement::Analyze(Some(name)) => {
            rename_qualified_table_name(name, old, new, &HashSet::new())
        }
        Statement::CreateView(view) => rename_table_refs_in_select(&mut view.query, old, new),
        Statement::CreateIndex(index) => {
            if index.table.eq_ignore_ascii_case(old) {
                index.table.clear();
                index.table.push_str(new);
                changed = true;
            }
            for column in &mut index.columns {
                changed |=
                    rename_table_refs_in_expr(&mut column.expr, old, new, &HashSet::new(), false);
            }
            if let Some(where_clause) = &mut index.where_clause {
                changed |=
                    rename_table_refs_in_expr(where_clause, old, new, &HashSet::new(), false);
            }
            changed
        }
        _ => false,
    }
}

fn rename_table_refs_in_select(select: &mut SelectStatement, old: &str, new: &str) -> bool {
    rename_table_refs_in_select_with_hidden(select, old, new, &HashSet::new())
}

fn rename_table_refs_in_select_with_hidden(
    select: &mut SelectStatement,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
) -> bool {
    let mut changed = false;
    let scoped_hidden = if let Some(with) = &mut select.with {
        let (with_changed, hidden) =
            rename_table_refs_in_with_clause(with, old, new, hidden_tables);
        changed |= with_changed;
        hidden
    } else {
        hidden_tables.clone()
    };

    let mut body_scope =
        rename_table_refs_in_select_core(&mut select.body.select, old, new, &scoped_hidden);
    for (_, core) in &mut select.body.compounds {
        body_scope.merge(rename_table_refs_in_select_core(
            core,
            old,
            new,
            &scoped_hidden,
        ));
    }
    changed |= body_scope.changed;
    let rename_qualifiers = body_scope.should_rename_qualifiers();
    for term in &mut select.order_by {
        changed |=
            rename_table_refs_in_expr(&mut term.expr, old, new, &scoped_hidden, rename_qualifiers);
    }
    if let Some(limit) = &mut select.limit {
        changed |= rename_table_refs_in_expr(
            &mut limit.limit,
            old,
            new,
            &scoped_hidden,
            rename_qualifiers,
        );
        if let Some(offset) = &mut limit.offset {
            changed |=
                rename_table_refs_in_expr(offset, old, new, &scoped_hidden, rename_qualifiers);
        }
    }
    changed
}

fn rename_table_refs_in_with_clause(
    with: &mut fsqlite_ast::WithClause,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
) -> (bool, HashSet<String>) {
    let mut changed = false;
    let mut scoped_hidden = hidden_tables.clone();
    scoped_hidden.extend(with.ctes.iter().map(|cte| cte.name.to_ascii_lowercase()));
    for cte in &mut with.ctes {
        changed |=
            rename_table_refs_in_select_with_hidden(&mut cte.query, old, new, &scoped_hidden);
    }
    (changed, scoped_hidden)
}

fn rename_table_refs_in_insert_statement(
    insert: &mut InsertStatement,
    old: &str,
    new: &str,
) -> bool {
    let old_alias_present = insert
        .alias
        .as_deref()
        .is_some_and(|alias| alias.eq_ignore_ascii_case(old));
    let renamed_target = rename_qualified_table_name(&mut insert.table, old, new, &HashSet::new());
    let mut changed = renamed_target;
    let hidden_tables = if let Some(with) = &mut insert.with {
        let (with_changed, hidden) =
            rename_table_refs_in_with_clause(with, old, new, &HashSet::new());
        changed |= with_changed;
        hidden
    } else {
        HashSet::new()
    };
    match &mut insert.source {
        InsertSource::Values(rows) => {
            for row in rows {
                for expr in row {
                    changed |= rename_table_refs_in_expr(expr, old, new, &hidden_tables, false);
                }
            }
        }
        InsertSource::Select(select) => {
            changed |= rename_table_refs_in_select_with_hidden(select, old, new, &hidden_tables);
        }
        InsertSource::DefaultValues => {}
    }
    for upsert in &mut insert.upsert {
        if let Some(target) = &mut upsert.target {
            for column in &mut target.columns {
                changed |=
                    rename_table_refs_in_expr(&mut column.expr, old, new, &hidden_tables, false);
            }
            if let Some(where_clause) = &mut target.where_clause {
                changed |= rename_table_refs_in_expr(where_clause, old, new, &hidden_tables, false);
            }
        }
        if let UpsertAction::Update {
            assignments,
            where_clause,
        } = &mut upsert.action
        {
            let rename_target_qualifiers = renamed_target && !old_alias_present;
            for assignment in assignments {
                changed |= rename_table_refs_in_expr(
                    &mut assignment.value,
                    old,
                    new,
                    &hidden_tables,
                    rename_target_qualifiers,
                );
            }
            if let Some(where_clause) = where_clause {
                changed |= rename_table_refs_in_expr(
                    where_clause,
                    old,
                    new,
                    &hidden_tables,
                    rename_target_qualifiers,
                );
            }
        }
    }
    let rename_target_qualifiers = renamed_target && !old_alias_present;
    for column in &mut insert.returning {
        changed |= rename_table_refs_in_result_column(
            column,
            old,
            new,
            &hidden_tables,
            rename_target_qualifiers,
        );
    }
    changed
}

fn rename_table_refs_in_update_statement(
    update: &mut fsqlite_ast::UpdateStatement,
    old: &str,
    new: &str,
) -> bool {
    let mut changed = false;
    let hidden_tables = if let Some(with) = &mut update.with {
        let (with_changed, hidden) =
            rename_table_refs_in_with_clause(with, old, new, &HashSet::new());
        changed |= with_changed;
        hidden
    } else {
        HashSet::new()
    };
    let mut scope = rename_table_refs_in_qualified_table_ref(&mut update.table, old, new);
    if let Some(from_clause) = &mut update.from {
        scope.merge(rename_table_refs_in_table_or_subquery(
            &mut from_clause.source,
            old,
            new,
            &hidden_tables,
        ));
        for join in &mut from_clause.joins {
            scope.merge(rename_table_refs_in_table_or_subquery(
                &mut join.table,
                old,
                new,
                &hidden_tables,
            ));
        }
        let rename_qualifiers = scope.should_rename_qualifiers();
        for join in &mut from_clause.joins {
            if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
                scope.changed |=
                    rename_table_refs_in_expr(expr, old, new, &hidden_tables, rename_qualifiers);
            }
        }
    }
    changed |= scope.changed;
    let rename_qualifiers = scope.should_rename_qualifiers();
    for assignment in &mut update.assignments {
        changed |= rename_table_refs_in_expr(
            &mut assignment.value,
            old,
            new,
            &hidden_tables,
            rename_qualifiers,
        );
    }
    if let Some(where_expr) = &mut update.where_clause {
        changed |=
            rename_table_refs_in_expr(where_expr, old, new, &hidden_tables, rename_qualifiers);
    }
    for column in &mut update.returning {
        changed |=
            rename_table_refs_in_result_column(column, old, new, &hidden_tables, rename_qualifiers);
    }
    for term in &mut update.order_by {
        changed |=
            rename_table_refs_in_expr(&mut term.expr, old, new, &hidden_tables, rename_qualifiers);
    }
    if let Some(limit) = &mut update.limit {
        changed |= rename_table_refs_in_expr(
            &mut limit.limit,
            old,
            new,
            &hidden_tables,
            rename_qualifiers,
        );
        if let Some(offset) = &mut limit.offset {
            changed |=
                rename_table_refs_in_expr(offset, old, new, &hidden_tables, rename_qualifiers);
        }
    }
    changed
}

fn rename_table_refs_in_delete_statement(
    delete: &mut fsqlite_ast::DeleteStatement,
    old: &str,
    new: &str,
) -> bool {
    let mut changed = false;
    let hidden_tables = if let Some(with) = &mut delete.with {
        let (with_changed, hidden) =
            rename_table_refs_in_with_clause(with, old, new, &HashSet::new());
        changed |= with_changed;
        hidden
    } else {
        HashSet::new()
    };
    let scope = rename_table_refs_in_qualified_table_ref(&mut delete.table, old, new);
    changed |= scope.changed;
    let rename_qualifiers = scope.should_rename_qualifiers();
    if let Some(where_expr) = &mut delete.where_clause {
        changed |=
            rename_table_refs_in_expr(where_expr, old, new, &hidden_tables, rename_qualifiers);
    }
    for column in &mut delete.returning {
        changed |=
            rename_table_refs_in_result_column(column, old, new, &hidden_tables, rename_qualifiers);
    }
    for term in &mut delete.order_by {
        changed |=
            rename_table_refs_in_expr(&mut term.expr, old, new, &hidden_tables, rename_qualifiers);
    }
    if let Some(limit) = &mut delete.limit {
        changed |= rename_table_refs_in_expr(
            &mut limit.limit,
            old,
            new,
            &hidden_tables,
            rename_qualifiers,
        );
        if let Some(offset) = &mut limit.offset {
            changed |=
                rename_table_refs_in_expr(offset, old, new, &hidden_tables, rename_qualifiers);
        }
    }
    changed
}

fn rename_table_refs_in_select_core(
    core: &mut SelectCore,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
) -> TableRenameScope {
    match core {
        SelectCore::Values(rows) => {
            let mut scope = TableRenameScope::default();
            for row in rows.iter_mut() {
                for expr in row {
                    scope.changed |=
                        rename_table_refs_in_expr(expr, old, new, hidden_tables, false);
                }
            }
            scope
        }
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            let mut scope = TableRenameScope::default();
            if let Some(from_clause) = from {
                scope.merge(rename_table_refs_in_table_or_subquery(
                    &mut from_clause.source,
                    old,
                    new,
                    hidden_tables,
                ));
                for join in &mut from_clause.joins {
                    scope.merge(rename_table_refs_in_table_or_subquery(
                        &mut join.table,
                        old,
                        new,
                        hidden_tables,
                    ));
                }
                let rename_qualifiers = scope.should_rename_qualifiers();
                for join in &mut from_clause.joins {
                    if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
                        scope.changed |= rename_table_refs_in_expr(
                            expr,
                            old,
                            new,
                            hidden_tables,
                            rename_qualifiers,
                        );
                    }
                }
            }
            let rename_qualifiers = scope.should_rename_qualifiers();
            for column in columns {
                scope.changed |= rename_table_refs_in_result_column(
                    column,
                    old,
                    new,
                    hidden_tables,
                    rename_qualifiers,
                );
            }
            if let Some(expr) = where_clause {
                scope.changed |=
                    rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers);
            }
            for expr in group_by {
                scope.changed |=
                    rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers);
            }
            if let Some(expr) = having {
                scope.changed |=
                    rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers);
            }
            for window in windows {
                scope.changed |= rename_table_refs_in_window_spec(
                    &mut window.spec,
                    old,
                    new,
                    hidden_tables,
                    rename_qualifiers,
                );
            }
            scope
        }
    }
}

fn rename_table_refs_in_table_or_subquery(
    source: &mut TableOrSubquery,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
) -> TableRenameScope {
    let mut scope = TableRenameScope::default();
    match source {
        TableOrSubquery::Table { name, alias, .. } => {
            scope.old_alias_present = alias
                .as_deref()
                .is_some_and(|alias| alias.eq_ignore_ascii_case(old));
            if rename_qualified_table_name(name, old, new, hidden_tables) {
                scope.changed = true;
                scope.renamed_unaliased_source = alias.is_none();
            }
        }
        TableOrSubquery::Subquery { query, alias } => {
            scope.changed |=
                rename_table_refs_in_select_with_hidden(query, old, new, hidden_tables);
            scope.old_alias_present = alias
                .as_deref()
                .is_some_and(|alias| alias.eq_ignore_ascii_case(old));
        }
        TableOrSubquery::TableFunction { args, alias, .. } => {
            for expr in args {
                scope.changed |= rename_table_refs_in_expr(expr, old, new, hidden_tables, false);
            }
            scope.old_alias_present = alias
                .as_deref()
                .is_some_and(|alias| alias.eq_ignore_ascii_case(old));
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            scope.merge(rename_table_refs_in_table_or_subquery(
                &mut from_clause.source,
                old,
                new,
                hidden_tables,
            ));
            for join in &mut from_clause.joins {
                scope.merge(rename_table_refs_in_table_or_subquery(
                    &mut join.table,
                    old,
                    new,
                    hidden_tables,
                ));
            }
            let rename_qualifiers = scope.should_rename_qualifiers();
            for join in &mut from_clause.joins {
                if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
                    scope.changed |=
                        rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers);
                }
            }
        }
    }
    scope
}

fn rename_table_refs_in_qualified_table_ref(
    table: &mut fsqlite_ast::QualifiedTableRef,
    old: &str,
    new: &str,
) -> TableRenameScope {
    let mut scope = TableRenameScope {
        old_alias_present: table
            .alias
            .as_deref()
            .is_some_and(|alias| alias.eq_ignore_ascii_case(old)),
        ..TableRenameScope::default()
    };
    if rename_qualified_table_name(&mut table.name, old, new, &HashSet::new()) {
        scope.changed = true;
        scope.renamed_unaliased_source = table.alias.is_none();
    }
    scope
}

fn rename_qualified_table_name(
    name: &mut QualifiedName,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
) -> bool {
    if !qualified_relation_matches_unhidden_name(name, old, hidden_tables) {
        return false;
    }
    name.name.clear();
    name.name.push_str(new);
    true
}

fn rename_table_refs_in_result_column(
    column: &mut ResultColumn,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
    rename_qualifiers: bool,
) -> bool {
    match column {
        ResultColumn::Expr { expr, .. } => {
            rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
        }
        ResultColumn::TableStar(name) if rename_qualifiers => {
            rename_qualified_table_name(name, old, new, hidden_tables)
        }
        ResultColumn::Star | ResultColumn::TableStar(_) => false,
    }
}

fn rename_table_refs_in_expr(
    expr: &mut Expr,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
    rename_qualifiers: bool,
) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => false,
        Expr::Column(col_ref, _) => {
            if rename_qualifiers
                && col_ref
                    .table
                    .as_deref()
                    .is_some_and(|table| table.eq_ignore_ascii_case(old))
            {
                col_ref.table = Some(Arc::from(new));
                true
            } else {
                false
            }
        }
        Expr::BinaryOp { left, right, .. } => {
            rename_table_refs_in_expr(left, old, new, hidden_tables, rename_qualifiers)
                | rename_table_refs_in_expr(right, old, new, hidden_tables, rename_qualifiers)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => {
            rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
                | rename_table_refs_in_expr(low, old, new, hidden_tables, rename_qualifiers)
                | rename_table_refs_in_expr(high, old, new, hidden_tables, rename_qualifiers)
        }
        Expr::In { expr, set, .. } => {
            let expr_changed =
                rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers);
            let set_changed = match set {
                InSet::List(values) => values.iter_mut().fold(false, |changed, value| {
                    rename_table_refs_in_expr(value, old, new, hidden_tables, rename_qualifiers)
                        | changed
                }),
                InSet::Subquery(query) => {
                    rename_table_refs_in_select_with_hidden(query, old, new, hidden_tables)
                }
                InSet::Table(name) => rename_qualified_table_name(name, old, new, hidden_tables),
            };
            expr_changed | set_changed
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
                | rename_table_refs_in_expr(pattern, old, new, hidden_tables, rename_qualifiers)
                | escape.as_deref_mut().is_some_and(|expr| {
                    rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
                })
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            let operand_changed = operand.as_deref_mut().is_some_and(|expr| {
                rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
            });
            let whens_changed = whens.iter_mut().fold(false, |changed, (when, then)| {
                changed
                    | rename_table_refs_in_expr(when, old, new, hidden_tables, rename_qualifiers)
                    | rename_table_refs_in_expr(then, old, new, hidden_tables, rename_qualifiers)
            });
            let else_changed = else_expr.as_deref_mut().is_some_and(|expr| {
                rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
            });
            operand_changed | whens_changed | else_changed
        }
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            rename_table_refs_in_select_with_hidden(subquery, old, new, hidden_tables)
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_changed = match args {
                FunctionArgs::List(args) => args.iter_mut().fold(false, |changed, arg| {
                    rename_table_refs_in_expr(arg, old, new, hidden_tables, rename_qualifiers)
                        | changed
                }),
                FunctionArgs::Star => false,
            };
            let order_changed = order_by.iter_mut().fold(false, |changed, term| {
                rename_table_refs_in_expr(
                    &mut term.expr,
                    old,
                    new,
                    hidden_tables,
                    rename_qualifiers,
                ) | changed
            });
            let filter_changed = filter.as_deref_mut().is_some_and(|expr| {
                rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
            });
            let over_changed = over.as_mut().is_some_and(|window| {
                rename_table_refs_in_window_spec(window, old, new, hidden_tables, rename_qualifiers)
            });
            args_changed | order_changed | filter_changed | over_changed
        }
        Expr::JsonAccess { expr, path, .. } => {
            rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
                | rename_table_refs_in_expr(path, old, new, hidden_tables, rename_qualifiers)
        }
        Expr::RowValue(values, _) => values.iter_mut().fold(false, |changed, value| {
            rename_table_refs_in_expr(value, old, new, hidden_tables, rename_qualifiers) | changed
        }),
    }
}

fn rename_table_refs_in_window_spec(
    window: &mut WindowSpec,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
    rename_qualifiers: bool,
) -> bool {
    let partition_changed = window.partition_by.iter_mut().fold(false, |changed, expr| {
        rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers) | changed
    });
    let order_changed = window.order_by.iter_mut().fold(false, |changed, term| {
        rename_table_refs_in_expr(&mut term.expr, old, new, hidden_tables, rename_qualifiers)
            | changed
    });
    let frame_changed = window.frame.as_mut().is_some_and(|frame| {
        rename_table_refs_in_frame_spec(frame, old, new, hidden_tables, rename_qualifiers)
    });
    partition_changed | order_changed | frame_changed
}

fn rename_table_refs_in_frame_spec(
    frame: &mut FrameSpec,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
    rename_qualifiers: bool,
) -> bool {
    rename_table_refs_in_frame_bound(&mut frame.start, old, new, hidden_tables, rename_qualifiers)
        | frame.end.as_mut().is_some_and(|bound| {
            rename_table_refs_in_frame_bound(bound, old, new, hidden_tables, rename_qualifiers)
        })
}

fn rename_table_refs_in_frame_bound(
    bound: &mut FrameBound,
    old: &str,
    new: &str,
    hidden_tables: &HashSet<String>,
    rename_qualifiers: bool,
) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            rename_table_refs_in_expr(expr, old, new, hidden_tables, rename_qualifiers)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn rename_column_refs_in_expr_sql(expr_sql: &str, old: &str, new: &str) -> Result<Option<String>> {
    let mut expr = fsqlite_parser::expr::parse_expr(expr_sql).map_err(|err| {
        FrankenError::Internal(format!(
            "failed to parse schema expression `{expr_sql}` during column rename: {err}"
        ))
    })?;
    if rename_column_refs_in_expr(&mut expr, old, new) {
        Ok(Some(expr.to_string()))
    } else {
        Ok(None)
    }
}

fn rename_column_refs_in_stored_expr_sql(
    expr_sql: &mut String,
    old: &str,
    new: &str,
) -> Result<()> {
    if let Some(renamed) = rename_column_refs_in_expr_sql(expr_sql, old, new)? {
        *expr_sql = renamed;
    }
    Ok(())
}

fn stored_expr_references_column(expr_sql: &str, column_name: &str) -> Result<bool> {
    let expr = fsqlite_parser::expr::parse_expr(expr_sql).map_err(|err| {
        FrankenError::Internal(format!(
            "failed to parse schema expression `{expr_sql}` during column drop: {err}"
        ))
    })?;
    let mut column_refs = Vec::new();
    collect_expr_column_refs(&expr, &mut column_refs);
    Ok(column_refs
        .iter()
        .any(|referenced| referenced.eq_ignore_ascii_case(column_name)))
}

#[derive(Clone, Copy, Default, PartialEq, Eq)]
struct ColumnRenameOutputStatus {
    exposes_old: bool,
    exposes_renamed: bool,
}

impl ColumnRenameOutputStatus {
    fn old() -> Self {
        Self {
            exposes_old: true,
            exposes_renamed: false,
        }
    }

    fn renamed() -> Self {
        Self {
            exposes_old: false,
            exposes_renamed: true,
        }
    }

    fn merge(&mut self, other: Self) {
        self.exposes_old |= other.exposes_old;
        self.exposes_renamed |= other.exposes_renamed;
    }
}

#[derive(Default)]
struct ColumnRenameOutputSources {
    all: ColumnRenameOutputStatus,
    by_binding: HashMap<String, ColumnRenameOutputStatus>,
}

impl ColumnRenameOutputSources {
    fn add_source(&mut self, binding: Option<&str>, status: ColumnRenameOutputStatus) {
        self.all.merge(status);
        if let Some(binding) = binding {
            self.by_binding
                .entry(binding.to_ascii_lowercase())
                .or_default()
                .merge(status);
        }
    }

    fn status_for_binding(&self, binding: &str) -> ColumnRenameOutputStatus {
        self.by_binding
            .get(&binding.to_ascii_lowercase())
            .copied()
            .unwrap_or_default()
    }
}

struct ColumnRenameSourceCatalog {
    renamed_table: String,
    known_tables: HashSet<String>,
    tables_with_old_column: HashSet<String>,
    view_outputs: HashMap<String, ColumnRenameOutputStatus>,
}

impl ColumnRenameSourceCatalog {
    fn set_view_output_status(
        &mut self,
        view_name: &str,
        status: ColumnRenameOutputStatus,
    ) -> bool {
        self.view_outputs
            .insert(view_name.to_ascii_lowercase(), status)
            != Some(status)
    }

    fn table_may_expose_old_column(
        &self,
        name: &QualifiedName,
        hidden_tables: &HashSet<String>,
    ) -> bool {
        let Some(local_name) = qualified_relation_name(name) else {
            return true;
        };
        let key = local_name.to_ascii_lowercase();
        if name.schema.is_none() && hidden_tables.contains(&key) {
            return hidden_tables.contains(&hidden_old_column_marker(&key));
        }
        if let Some(status) = self.view_outputs.get(&key) {
            return status.exposes_old;
        }
        self.tables_with_old_column.contains(&key) || !self.known_tables.contains(&key)
    }

    fn table_outputs_renamed_column(
        &self,
        name: &QualifiedName,
        hidden_tables: &HashSet<String>,
    ) -> bool {
        let Some(local_name) = qualified_relation_name(name) else {
            return false;
        };
        let key = local_name.to_ascii_lowercase();
        if name.schema.is_none() && hidden_tables.contains(&key) {
            return hidden_tables.contains(&hidden_renamed_column_marker(&key));
        }
        self.view_outputs
            .get(&key)
            .is_some_and(|status| status.exposes_renamed)
    }

    fn table_output_status_after_column_rename(
        &self,
        name: &QualifiedName,
        hidden_tables: &HashSet<String>,
    ) -> ColumnRenameOutputStatus {
        let Some(local_name) = qualified_relation_name(name) else {
            return ColumnRenameOutputStatus::old();
        };
        let key = local_name.to_ascii_lowercase();
        if name.schema.is_none() && hidden_tables.contains(&key) {
            let mut status = ColumnRenameOutputStatus::default();
            if hidden_tables.contains(&hidden_old_column_marker(&key)) {
                status.merge(ColumnRenameOutputStatus::old());
            }
            if hidden_tables.contains(&hidden_renamed_column_marker(&key)) {
                status.merge(ColumnRenameOutputStatus::renamed());
            }
            return status;
        }
        if let Some(status) = self.view_outputs.get(&key) {
            return *status;
        }
        if key == self.renamed_table {
            ColumnRenameOutputStatus::renamed()
        } else if self.tables_with_old_column.contains(&key) || !self.known_tables.contains(&key) {
            ColumnRenameOutputStatus::old()
        } else {
            ColumnRenameOutputStatus::default()
        }
    }
}

fn hidden_old_column_marker(name: &str) -> String {
    format!("\0old-column:{name}")
}

fn hidden_renamed_column_marker(name: &str) -> String {
    format!("\0renamed-column:{name}")
}

fn add_hidden_cte_for_column_rename(
    hidden_tables: &mut HashSet<String>,
    cte: &fsqlite_ast::Cte,
    old_column: &str,
) {
    let key = cte.name.to_ascii_lowercase();
    if cte_may_expose_old_column(cte, old_column) {
        hidden_tables.insert(hidden_old_column_marker(&key));
    }
    hidden_tables.insert(key);
}

fn refresh_hidden_cte_for_column_rename(
    hidden_tables: &mut HashSet<String>,
    cte: &fsqlite_ast::Cte,
    old_column: &str,
    new_column: &str,
    source_catalog: &ColumnRenameSourceCatalog,
) {
    let key = cte.name.to_ascii_lowercase();
    let old_marker = hidden_old_column_marker(&key);
    let renamed_marker = hidden_renamed_column_marker(&key);
    let had_old_marker = hidden_tables.remove(&old_marker);
    let had_renamed_marker = hidden_tables.remove(&renamed_marker);
    let output_status =
        cte_column_rename_output_status(cte, old_column, new_column, hidden_tables, source_catalog);
    if output_status.exposes_old {
        hidden_tables.insert(old_marker);
    }
    if (had_old_marker || had_renamed_marker) && output_status.exposes_renamed {
        hidden_tables.insert(renamed_marker);
    }
    hidden_tables.insert(key);
}

fn cte_may_expose_old_column(cte: &fsqlite_ast::Cte, old_column: &str) -> bool {
    cte_may_expose_column(cte, old_column)
}

fn cte_may_expose_column(cte: &fsqlite_ast::Cte, column_name: &str) -> bool {
    if !cte.columns.is_empty() {
        return cte
            .columns
            .iter()
            .any(|column| column.eq_ignore_ascii_case(column_name));
    }
    select_statement_may_output_column(&cte.query, column_name)
}

fn select_statement_may_output_column(select: &SelectStatement, old_column: &str) -> bool {
    select_core_may_output_column(&select.body.select, old_column)
}

fn select_core_may_output_column(core: &SelectCore, old_column: &str) -> bool {
    let SelectCore::Select { columns, .. } = core else {
        return false;
    };
    columns
        .iter()
        .any(|column| result_column_may_output_column(column, old_column))
}

fn result_column_may_output_column(column: &ResultColumn, old_column: &str) -> bool {
    match column {
        ResultColumn::Expr {
            alias: Some(alias), ..
        } => alias.eq_ignore_ascii_case(old_column),
        ResultColumn::Expr { expr, alias: None } => match expr {
            Expr::Column(col_ref, _) => col_ref.column.eq_ignore_ascii_case(old_column),
            _ => false,
        },
        ResultColumn::Star | ResultColumn::TableStar(_) => true,
    }
}

fn cte_column_rename_output_status(
    cte: &fsqlite_ast::Cte,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
) -> ColumnRenameOutputStatus {
    if !cte.columns.is_empty() {
        return if cte
            .columns
            .iter()
            .any(|column| column.eq_ignore_ascii_case(old_column))
        {
            ColumnRenameOutputStatus::old()
        } else {
            ColumnRenameOutputStatus::default()
        };
    }
    select_column_rename_output_status(
        &cte.query,
        old_column,
        new_column,
        hidden_tables,
        source_catalog,
    )
}

fn view_column_rename_initial_output_status(
    view: &ViewDef,
    old_column: &str,
) -> ColumnRenameOutputStatus {
    if !view.columns.is_empty() {
        return if view
            .columns
            .iter()
            .any(|column| column.eq_ignore_ascii_case(old_column))
        {
            ColumnRenameOutputStatus::old()
        } else {
            ColumnRenameOutputStatus::default()
        };
    }
    if select_statement_may_output_column(&view.query, old_column) {
        ColumnRenameOutputStatus::old()
    } else {
        ColumnRenameOutputStatus::default()
    }
}

fn view_column_rename_output_status(
    view: &ViewDef,
    old_column: &str,
    new_column: &str,
    source_catalog: &ColumnRenameSourceCatalog,
) -> ColumnRenameOutputStatus {
    if !view.columns.is_empty() {
        return if view
            .columns
            .iter()
            .any(|column| column.eq_ignore_ascii_case(old_column))
        {
            ColumnRenameOutputStatus::old()
        } else {
            ColumnRenameOutputStatus::default()
        };
    }
    select_column_rename_output_status(
        &view.query,
        old_column,
        new_column,
        &HashSet::new(),
        source_catalog,
    )
}

fn select_column_rename_output_status(
    select: &SelectStatement,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
) -> ColumnRenameOutputStatus {
    let mut scoped_hidden = hidden_tables.clone();
    if let Some(with) = &select.with {
        for cte in &with.ctes {
            add_hidden_cte_for_column_rename(&mut scoped_hidden, cte, old_column);
        }
        for _ in 0..=with.ctes.len() {
            let before = scoped_hidden.clone();
            for cte in &with.ctes {
                refresh_hidden_cte_for_column_rename(
                    &mut scoped_hidden,
                    cte,
                    old_column,
                    new_column,
                    source_catalog,
                );
            }
            if scoped_hidden == before {
                break;
            }
        }
    }
    select_core_column_rename_output_status(
        &select.body.select,
        old_column,
        new_column,
        &scoped_hidden,
        source_catalog,
    )
}

fn select_core_column_rename_output_status(
    core: &SelectCore,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
) -> ColumnRenameOutputStatus {
    let SelectCore::Select { columns, from, .. } = core else {
        return ColumnRenameOutputStatus::default();
    };
    let sources = from
        .as_ref()
        .map_or_else(ColumnRenameOutputSources::default, |from| {
            column_rename_output_sources(
                from,
                old_column,
                new_column,
                hidden_tables,
                source_catalog,
            )
        });
    columns
        .iter()
        .fold(ColumnRenameOutputStatus::default(), |mut status, column| {
            status.merge(result_column_rename_output_status(
                column, old_column, new_column, &sources,
            ));
            status
        })
}

fn result_column_rename_output_status(
    column: &ResultColumn,
    old_column: &str,
    new_column: &str,
    sources: &ColumnRenameOutputSources,
) -> ColumnRenameOutputStatus {
    match column {
        ResultColumn::Expr {
            alias: Some(alias), ..
        } => {
            if alias.eq_ignore_ascii_case(old_column) {
                ColumnRenameOutputStatus::old()
            } else {
                ColumnRenameOutputStatus::default()
            }
        }
        ResultColumn::Expr { expr, alias: None } => match expr {
            Expr::Column(col_ref, _) if col_ref.column.eq_ignore_ascii_case(old_column) => {
                ColumnRenameOutputStatus::old()
            }
            Expr::Column(col_ref, _) if col_ref.column.eq_ignore_ascii_case(new_column) => {
                col_ref.table.as_deref().map_or_else(
                    || {
                        if sources.all.exposes_renamed {
                            ColumnRenameOutputStatus::renamed()
                        } else {
                            ColumnRenameOutputStatus::default()
                        }
                    },
                    |table| {
                        let source_status = sources.status_for_binding(table);
                        if source_status.exposes_renamed {
                            ColumnRenameOutputStatus::renamed()
                        } else {
                            ColumnRenameOutputStatus::default()
                        }
                    },
                )
            }
            _ => ColumnRenameOutputStatus::default(),
        },
        ResultColumn::Star => sources.all,
        ResultColumn::TableStar(name) => sources.status_for_binding(&name.name),
    }
}

fn column_rename_output_sources(
    from: &FromClause,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
) -> ColumnRenameOutputSources {
    let mut sources = ColumnRenameOutputSources::default();
    collect_column_rename_output_sources_from_table_or_subquery(
        &from.source,
        old_column,
        new_column,
        hidden_tables,
        source_catalog,
        &mut sources,
    );
    for join in &from.joins {
        collect_column_rename_output_sources_from_table_or_subquery(
            &join.table,
            old_column,
            new_column,
            hidden_tables,
            source_catalog,
            &mut sources,
        );
    }
    sources
}

fn collect_column_rename_output_sources_from_table_or_subquery(
    source: &TableOrSubquery,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
    sources: &mut ColumnRenameOutputSources,
) {
    match source {
        TableOrSubquery::Table { name, alias, .. } => {
            let status =
                source_catalog.table_output_status_after_column_rename(name, hidden_tables);
            sources.add_source(Some(alias.as_deref().unwrap_or(&name.name)), status);
            if alias.is_none() {
                sources.add_source(Some(&name.name), status);
            }
        }
        TableOrSubquery::Subquery { query, alias } => {
            let status = select_column_rename_output_status(
                query,
                old_column,
                new_column,
                hidden_tables,
                source_catalog,
            );
            sources.add_source(alias.as_deref(), status);
        }
        TableOrSubquery::TableFunction { name, alias, .. } => {
            sources.add_source(
                Some(alias.as_deref().unwrap_or(name)),
                ColumnRenameOutputStatus::old(),
            );
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            collect_column_rename_output_sources_from_table_or_subquery(
                &from_clause.source,
                old_column,
                new_column,
                hidden_tables,
                source_catalog,
                sources,
            );
            for join in &from_clause.joins {
                collect_column_rename_output_sources_from_table_or_subquery(
                    &join.table,
                    old_column,
                    new_column,
                    hidden_tables,
                    source_catalog,
                    sources,
                );
            }
        }
    }
}

#[derive(Clone, Default)]
struct ColumnRenameBindings {
    /// Source aliases/names that refer to the table whose column is being renamed.
    bindings: HashSet<String>,
    /// All source aliases/names in this SELECT scope.  Used to prevent an
    /// inner query source from accidentally capturing an outer correlated
    /// reference with the same qualifier.
    source_bindings: HashSet<String>,
    /// Number of local sources that may expose the old column name.  Known
    /// tables without the old column do not block correlated outer refs.
    source_count: usize,
}

impl ColumnRenameBindings {
    fn add_source(&mut self) {
        self.source_count = self.source_count.saturating_add(1);
    }

    fn add_source_binding(&mut self, binding: &str) {
        self.source_bindings.insert(binding.to_ascii_lowercase());
    }

    fn add_source_alias_or_name(&mut self, alias: Option<&str>, name: &str) {
        self.add_source_binding(alias.unwrap_or(name));
    }

    fn add_matching_binding(&mut self, binding: &str) {
        let binding = binding.to_ascii_lowercase();
        self.source_bindings.insert(binding.clone());
        self.bindings.insert(binding);
    }

    fn has_matching_source(&self) -> bool {
        !self.bindings.is_empty()
    }

    fn can_rename_unqualified(&self) -> bool {
        self.has_matching_source() && self.source_count == 1
    }

    fn table_matches(&self, table: &str) -> bool {
        self.bindings.contains(&table.to_ascii_lowercase())
    }

    fn source_binding_shadows(&self, table: &str) -> bool {
        self.source_bindings.contains(&table.to_ascii_lowercase())
    }

    fn nested_outer_bindings(&self, outer: &Self) -> Self {
        let mut merged = self.clone();
        for binding in &outer.source_bindings {
            if !self.source_bindings.contains(binding) {
                merged.source_bindings.insert(binding.clone());
            }
        }
        for binding in &outer.bindings {
            if !self.source_bindings.contains(binding) {
                merged.bindings.insert(binding.clone());
            }
        }
        merged.source_count = self.source_count.saturating_add(outer.source_count);
        merged
    }

    fn absorb(&mut self, other: Self) {
        self.bindings.extend(other.bindings);
        self.source_bindings.extend(other.source_bindings);
        self.source_count = self.source_count.saturating_add(other.source_count);
    }
}

fn rename_column_refs_in_select_for_table(
    select: &mut SelectStatement,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    rename_column_refs_in_select_for_table_with_hidden(
        select,
        table_name,
        old_column,
        new_column,
        &HashSet::new(),
        source_catalog,
    )
}

fn rename_column_refs_in_select_for_table_with_hidden(
    select: &mut SelectStatement,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    rename_column_refs_in_select_for_table_with_outer(
        select,
        table_name,
        old_column,
        new_column,
        hidden_tables,
        &ColumnRenameBindings::default(),
        false,
        source_catalog,
    )
}

fn rename_column_refs_in_select_for_table_with_outer(
    select: &mut SelectStatement,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    let mut changed = false;
    let scoped_hidden = if let Some(with) = &mut select.with {
        let (with_changed, hidden) = rename_column_refs_in_with_clause_for_table_with_outer(
            with,
            table_name,
            old_column,
            new_column,
            hidden_tables,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        );
        changed |= with_changed;
        hidden
    } else {
        hidden_tables.clone()
    };

    let (first_core_changed, first_core_bindings) =
        rename_column_refs_in_select_core_for_table_with_outer(
            &mut select.body.select,
            table_name,
            old_column,
            new_column,
            &scoped_hidden,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        );
    changed |= first_core_changed;
    let mut top_level_bindings = first_core_bindings.clone();
    for (_, core) in &mut select.body.compounds {
        let (core_changed, core_bindings) = rename_column_refs_in_select_core_for_table_with_outer(
            core,
            table_name,
            old_column,
            new_column,
            &scoped_hidden,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        );
        changed |= core_changed;
        top_level_bindings.absorb(core_bindings);
    }
    let has_compound_cores = !select.body.compounds.is_empty();
    let top_level_allow_unqualified = if has_compound_cores {
        first_core_bindings.can_rename_unqualified()
    } else {
        top_level_bindings.can_rename_unqualified()
    };
    let top_level_order_bindings = if has_compound_cores {
        &first_core_bindings
    } else {
        &top_level_bindings
    };
    let top_level_output_aliases = collect_select_core_result_aliases(&select.body.select);
    changed |= rename_column_refs_in_top_level_ordering_terms_for_table(
        &mut select.order_by,
        table_name,
        old_column,
        new_column,
        top_level_order_bindings,
        top_level_allow_unqualified,
        &top_level_output_aliases,
        &scoped_hidden,
        outer_bindings,
        outer_allow_unqualified,
        source_catalog,
    );
    if let Some(limit) = &mut select.limit {
        changed |= rename_column_refs_in_expr_for_table_with_outer(
            &mut limit.limit,
            table_name,
            old_column,
            new_column,
            &ColumnRenameBindings::default(),
            false,
            &scoped_hidden,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        );
        if let Some(offset) = &mut limit.offset {
            changed |= rename_column_refs_in_expr_for_table_with_outer(
                offset,
                table_name,
                old_column,
                new_column,
                &ColumnRenameBindings::default(),
                false,
                &scoped_hidden,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            );
        }
    }
    changed
}

fn rename_column_refs_in_with_clause_for_table(
    with: &mut fsqlite_ast::WithClause,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
) -> (bool, HashSet<String>) {
    rename_column_refs_in_with_clause_for_table_with_outer(
        with,
        table_name,
        old_column,
        new_column,
        hidden_tables,
        &ColumnRenameBindings::default(),
        false,
        source_catalog,
    )
}

fn rename_column_refs_in_with_clause_for_table_with_outer(
    with: &mut fsqlite_ast::WithClause,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> (bool, HashSet<String>) {
    let mut changed = false;
    let mut scoped_hidden = hidden_tables.clone();
    for cte in &with.ctes {
        add_hidden_cte_for_column_rename(&mut scoped_hidden, cte, old_column);
    }
    for _ in 0..=with.ctes.len() {
        let mut pass_changed = false;
        for cte in &mut with.ctes {
            pass_changed |= rename_column_refs_in_select_for_table_with_outer(
                &mut cte.query,
                table_name,
                old_column,
                new_column,
                &scoped_hidden,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            );
            refresh_hidden_cte_for_column_rename(
                &mut scoped_hidden,
                cte,
                old_column,
                new_column,
                source_catalog,
            );
        }
        changed |= pass_changed;
        if !pass_changed {
            break;
        }
    }
    (changed, scoped_hidden)
}

fn rename_column_refs_in_select_core_for_table_with_outer(
    core: &mut SelectCore,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> (bool, ColumnRenameBindings) {
    match core {
        SelectCore::Values(rows) => {
            let changed = rows.iter_mut().fold(false, |changed, row| {
                row.iter_mut().fold(changed, |changed, expr| {
                    rename_column_refs_in_expr_for_table_with_outer(
                        expr,
                        table_name,
                        old_column,
                        new_column,
                        &ColumnRenameBindings::default(),
                        false,
                        hidden_tables,
                        outer_bindings,
                        outer_allow_unqualified,
                        source_catalog,
                    ) | changed
                })
            });
            (changed, ColumnRenameBindings::default())
        }
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            let mut changed = false;
            let mut bindings = ColumnRenameBindings::default();
            if let Some(from_clause) = from {
                changed |= collect_column_rename_bindings_from_table_or_subquery_with_outer(
                    &mut from_clause.source,
                    table_name,
                    old_column,
                    new_column,
                    hidden_tables,
                    &mut bindings,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                );
                for join in &mut from_clause.joins {
                    changed |= collect_column_rename_bindings_from_table_or_subquery_with_outer(
                        &mut join.table,
                        table_name,
                        old_column,
                        new_column,
                        hidden_tables,
                        &mut bindings,
                        outer_bindings,
                        outer_allow_unqualified,
                        source_catalog,
                    );
                }
                for join in &mut from_clause.joins {
                    if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
                        changed |= rename_column_refs_in_expr_for_table_with_outer(
                            expr,
                            table_name,
                            old_column,
                            new_column,
                            &bindings,
                            bindings.can_rename_unqualified(),
                            hidden_tables,
                            outer_bindings,
                            outer_allow_unqualified,
                            source_catalog,
                        );
                    }
                }
            }
            for column in columns {
                changed |= rename_column_refs_in_result_column_for_table_with_outer(
                    column,
                    table_name,
                    old_column,
                    new_column,
                    &bindings,
                    bindings.can_rename_unqualified(),
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                );
            }
            if let Some(expr) = where_clause {
                changed |= rename_column_refs_in_expr_for_table_with_outer(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    &bindings,
                    bindings.can_rename_unqualified(),
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                );
            }
            for expr in group_by {
                changed |= rename_column_refs_in_expr_for_table_with_outer(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    &bindings,
                    bindings.can_rename_unqualified(),
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                );
            }
            if let Some(expr) = having {
                changed |= rename_column_refs_in_expr_for_table_with_outer(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    &bindings,
                    bindings.can_rename_unqualified(),
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                );
            }
            for window in windows {
                changed |= rename_column_refs_in_window_spec_for_table_with_outer(
                    &mut window.spec,
                    table_name,
                    old_column,
                    new_column,
                    &bindings,
                    bindings.can_rename_unqualified(),
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                );
            }
            (changed, bindings)
        }
    }
}

fn collect_select_core_result_aliases(core: &SelectCore) -> HashSet<String> {
    let SelectCore::Select { columns, .. } = core else {
        return HashSet::new();
    };
    columns
        .iter()
        .filter_map(|column| match column {
            ResultColumn::Expr {
                alias: Some(alias), ..
            } => Some(alias.to_ascii_lowercase()),
            ResultColumn::Star
            | ResultColumn::TableStar(_)
            | ResultColumn::Expr { alias: None, .. } => None,
        })
        .collect()
}

fn collect_column_rename_bindings_from_table_or_subquery(
    source: &mut TableOrSubquery,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    bindings: &mut ColumnRenameBindings,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    collect_column_rename_bindings_from_table_or_subquery_with_outer(
        source,
        table_name,
        old_column,
        new_column,
        hidden_tables,
        bindings,
        &ColumnRenameBindings::default(),
        false,
        source_catalog,
    )
}

fn collect_column_rename_bindings_from_table_or_subquery_with_outer(
    source: &mut TableOrSubquery,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    hidden_tables: &HashSet<String>,
    bindings: &mut ColumnRenameBindings,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    let mut changed = false;
    match source {
        TableOrSubquery::Table { name, alias, .. } => {
            let hidden_outputs_renamed =
                source_catalog.table_outputs_renamed_column(name, hidden_tables);
            if hidden_outputs_renamed
                || source_catalog.table_may_expose_old_column(name, hidden_tables)
            {
                bindings.add_source();
            }
            bindings.add_source_alias_or_name(alias.as_deref(), &name.name);
            if hidden_outputs_renamed {
                bindings.add_matching_binding(alias.as_deref().unwrap_or(&name.name));
                if alias.is_none() {
                    bindings.add_matching_binding(&name.name);
                }
            }
            if qualified_relation_matches_unhidden_name(name, table_name, hidden_tables) {
                bindings.add_matching_binding(alias.as_deref().unwrap_or(&name.name));
                if alias.is_none() {
                    bindings.add_matching_binding(table_name);
                }
            }
        }
        TableOrSubquery::Subquery { query, alias } => {
            let exposed_old_before = select_statement_may_output_column(query, old_column);
            if let Some(alias) = alias {
                bindings.add_source_binding(alias);
            }
            changed |= rename_column_refs_in_select_for_table_with_outer(
                query,
                table_name,
                old_column,
                new_column,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            );
            let output_status = select_column_rename_output_status(
                query,
                old_column,
                new_column,
                hidden_tables,
                source_catalog,
            );
            let output_was_renamed =
                exposed_old_before && output_status.exposes_renamed && !output_status.exposes_old;
            if output_status.exposes_old || output_was_renamed {
                bindings.add_source();
            }
            if output_was_renamed {
                bindings.add_matching_binding(alias.as_deref().unwrap_or("subquery"));
            }
        }
        TableOrSubquery::TableFunction { name, args, alias } => {
            bindings.add_source();
            bindings.add_source_alias_or_name(alias.as_deref(), name);
            for expr in args {
                changed |= rename_column_refs_in_expr_for_table_with_outer(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    &ColumnRenameBindings::default(),
                    false,
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                );
            }
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            changed |= collect_column_rename_bindings_from_table_or_subquery_with_outer(
                &mut from_clause.source,
                table_name,
                old_column,
                new_column,
                hidden_tables,
                bindings,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            );
            for join in &mut from_clause.joins {
                changed |= collect_column_rename_bindings_from_table_or_subquery_with_outer(
                    &mut join.table,
                    table_name,
                    old_column,
                    new_column,
                    hidden_tables,
                    bindings,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                );
            }
        }
    }
    changed
}

fn rename_column_refs_in_statement_for_table(
    statement: &mut Statement,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    match statement {
        Statement::Select(select) => rename_column_refs_in_select_for_table(
            select,
            table_name,
            old_column,
            new_column,
            source_catalog,
        ),
        Statement::Insert(insert) => rename_column_refs_in_insert_for_table(
            insert,
            table_name,
            old_column,
            new_column,
            source_catalog,
        ),
        Statement::Update(update) => rename_column_refs_in_update_for_table(
            update,
            table_name,
            old_column,
            new_column,
            source_catalog,
        ),
        Statement::Delete(delete) => rename_column_refs_in_delete_for_table(
            delete,
            table_name,
            old_column,
            new_column,
            source_catalog,
        ),
        Statement::Explain { stmt, .. } => rename_column_refs_in_statement_for_table(
            stmt,
            table_name,
            old_column,
            new_column,
            source_catalog,
        ),
        _ => false,
    }
}

fn rename_column_refs_in_insert_for_table(
    insert: &mut InsertStatement,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    let mut changed = false;
    let target_matches = qualified_relation_matches_name(&insert.table, table_name);
    let hidden_tables = if let Some(with) = &mut insert.with {
        let (with_changed, hidden) = rename_column_refs_in_with_clause_for_table(
            with,
            table_name,
            old_column,
            new_column,
            &HashSet::new(),
            source_catalog,
        );
        changed |= with_changed;
        hidden
    } else {
        HashSet::new()
    };
    if target_matches {
        for column in &mut insert.columns {
            if column.eq_ignore_ascii_case(old_column) {
                column.clear();
                column.push_str(new_column);
                changed = true;
            }
        }
    }
    let bindings = ColumnRenameBindings::default();
    let mut target_bindings = ColumnRenameBindings::default();
    let target_may_expose_old_column =
        source_catalog.table_may_expose_old_column(&insert.table, &hidden_tables);
    if target_may_expose_old_column {
        target_bindings.add_source();
    }
    target_bindings.add_source_alias_or_name(insert.alias.as_deref(), &insert.table.name);
    if target_matches {
        target_bindings.add_matching_binding(insert.alias.as_deref().unwrap_or(&insert.table.name));
        target_bindings.add_matching_binding(table_name);
        target_bindings.add_matching_binding("excluded");
    }
    let target_allow_unqualified = target_bindings.can_rename_unqualified();
    match &mut insert.source {
        InsertSource::Values(rows) => {
            for row in rows {
                for expr in row {
                    changed |= rename_column_refs_in_expr_for_table_with_hidden(
                        expr,
                        table_name,
                        old_column,
                        new_column,
                        &bindings,
                        false,
                        &hidden_tables,
                        source_catalog,
                    );
                }
            }
        }
        InsertSource::Select(select) => {
            changed |= rename_column_refs_in_select_for_table_with_hidden(
                select,
                table_name,
                old_column,
                new_column,
                &hidden_tables,
                source_catalog,
            );
        }
        InsertSource::DefaultValues => {}
    }
    for upsert in &mut insert.upsert {
        if let Some(target) = &mut upsert.target {
            for column in &mut target.columns {
                changed |= rename_column_refs_in_expr_for_table_with_hidden(
                    &mut column.expr,
                    table_name,
                    old_column,
                    new_column,
                    &target_bindings,
                    target_allow_unqualified,
                    &hidden_tables,
                    source_catalog,
                );
            }
            if let Some(where_clause) = &mut target.where_clause {
                changed |= rename_column_refs_in_expr_for_table_with_hidden(
                    where_clause,
                    table_name,
                    old_column,
                    new_column,
                    &target_bindings,
                    target_allow_unqualified,
                    &hidden_tables,
                    source_catalog,
                );
            }
        }
        if let UpsertAction::Update {
            assignments,
            where_clause,
        } = &mut upsert.action
        {
            for assignment in assignments {
                if target_matches {
                    changed |= rename_assignment_target_columns(
                        &mut assignment.target,
                        old_column,
                        new_column,
                    );
                }
                changed |= rename_column_refs_in_expr_for_table_with_hidden(
                    &mut assignment.value,
                    table_name,
                    old_column,
                    new_column,
                    &target_bindings,
                    target_allow_unqualified,
                    &hidden_tables,
                    source_catalog,
                );
            }
            if let Some(where_clause) = where_clause {
                changed |= rename_column_refs_in_expr_for_table_with_hidden(
                    where_clause,
                    table_name,
                    old_column,
                    new_column,
                    &target_bindings,
                    target_allow_unqualified,
                    &hidden_tables,
                    source_catalog,
                );
            }
        }
    }
    for column in &mut insert.returning {
        changed |= rename_column_refs_in_result_column_for_table_with_hidden(
            column,
            table_name,
            old_column,
            new_column,
            &target_bindings,
            target_allow_unqualified,
            &hidden_tables,
            source_catalog,
        );
    }
    changed
}

fn rename_assignment_target_columns(
    target: &mut fsqlite_ast::AssignmentTarget,
    old_column: &str,
    new_column: &str,
) -> bool {
    match target {
        fsqlite_ast::AssignmentTarget::Column(column) => {
            if column.eq_ignore_ascii_case(old_column) {
                column.clear();
                column.push_str(new_column);
                true
            } else {
                false
            }
        }
        fsqlite_ast::AssignmentTarget::ColumnList(columns) => {
            columns.iter_mut().fold(false, |changed, column| {
                if column.eq_ignore_ascii_case(old_column) {
                    column.clear();
                    column.push_str(new_column);
                    true
                } else {
                    changed
                }
            })
        }
    }
}

fn rename_column_refs_in_update_for_table(
    update: &mut fsqlite_ast::UpdateStatement,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    let mut changed = false;
    let hidden_tables = if let Some(with) = &mut update.with {
        let (with_changed, hidden) = rename_column_refs_in_with_clause_for_table(
            with,
            table_name,
            old_column,
            new_column,
            &HashSet::new(),
            source_catalog,
        );
        changed |= with_changed;
        hidden
    } else {
        HashSet::new()
    };
    let mut bindings = ColumnRenameBindings::default();
    if source_catalog.table_may_expose_old_column(&update.table.name, &hidden_tables) {
        bindings.add_source();
    }
    bindings.add_source_alias_or_name(update.table.alias.as_deref(), &update.table.name.name);
    if qualified_relation_matches_name(&update.table.name, table_name) {
        bindings.add_matching_binding(
            update
                .table
                .alias
                .as_deref()
                .unwrap_or(&update.table.name.name),
        );
        bindings.add_matching_binding(table_name);
        for assignment in &mut update.assignments {
            changed |=
                rename_assignment_target_columns(&mut assignment.target, old_column, new_column);
        }
    }
    if let Some(from_clause) = &mut update.from {
        changed |= collect_column_rename_bindings_from_table_or_subquery(
            &mut from_clause.source,
            table_name,
            old_column,
            new_column,
            &hidden_tables,
            &mut bindings,
            source_catalog,
        );
        for join in &mut from_clause.joins {
            changed |= collect_column_rename_bindings_from_table_or_subquery(
                &mut join.table,
                table_name,
                old_column,
                new_column,
                &hidden_tables,
                &mut bindings,
                source_catalog,
            );
        }
        for join in &mut from_clause.joins {
            if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
                changed |= rename_column_refs_in_expr_for_table_with_hidden(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    &bindings,
                    bindings.can_rename_unqualified(),
                    &hidden_tables,
                    source_catalog,
                );
            }
        }
    }
    let allow_unqualified = bindings.can_rename_unqualified();
    for assignment in &mut update.assignments {
        changed |= rename_column_refs_in_expr_for_table_with_hidden(
            &mut assignment.value,
            table_name,
            old_column,
            new_column,
            &bindings,
            allow_unqualified,
            &hidden_tables,
            source_catalog,
        );
    }
    if let Some(where_expr) = &mut update.where_clause {
        changed |= rename_column_refs_in_expr_for_table_with_hidden(
            where_expr,
            table_name,
            old_column,
            new_column,
            &bindings,
            allow_unqualified,
            &hidden_tables,
            source_catalog,
        );
    }
    for column in &mut update.returning {
        changed |= rename_column_refs_in_result_column_for_table_with_hidden(
            column,
            table_name,
            old_column,
            new_column,
            &bindings,
            allow_unqualified,
            &hidden_tables,
            source_catalog,
        );
    }
    changed |= rename_column_refs_in_ordering_terms_for_table_with_hidden(
        &mut update.order_by,
        table_name,
        old_column,
        new_column,
        &bindings,
        allow_unqualified,
        &hidden_tables,
        source_catalog,
    );
    if let Some(limit) = &mut update.limit {
        changed |= rename_column_refs_in_expr_for_table_with_hidden(
            &mut limit.limit,
            table_name,
            old_column,
            new_column,
            &bindings,
            allow_unqualified,
            &hidden_tables,
            source_catalog,
        );
        if let Some(offset) = &mut limit.offset {
            changed |= rename_column_refs_in_expr_for_table_with_hidden(
                offset,
                table_name,
                old_column,
                new_column,
                &bindings,
                allow_unqualified,
                &hidden_tables,
                source_catalog,
            );
        }
    }
    changed
}

