fn rename_column_refs_in_expr_for_table_with_hidden(
    expr: &mut Expr,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    bindings: &ColumnRenameBindings,
    allow_unqualified: bool,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    rename_column_refs_in_expr_for_table_with_outer(
        expr,
        table_name,
        old_column,
        new_column,
        bindings,
        allow_unqualified,
        hidden_tables,
        &ColumnRenameBindings::default(),
        false,
        source_catalog,
    )
}

fn rename_column_refs_in_expr_for_table_with_outer(
    expr: &mut Expr,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    bindings: &ColumnRenameBindings,
    allow_unqualified: bool,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => false,
        Expr::Column(col_ref, _) => {
            if !col_ref.column.eq_ignore_ascii_case(old_column) {
                return false;
            }
            let qualified_match = col_ref
                .table
                .as_deref()
                .is_some_and(|table| bindings.table_matches(table));
            let outer_qualified_match = col_ref.table.as_deref().is_some_and(|table| {
                !bindings.source_binding_shadows(table) && outer_bindings.table_matches(table)
            });
            let unqualified_match = col_ref.table.is_none()
                && (allow_unqualified || (bindings.source_count == 0 && outer_allow_unqualified));
            if qualified_match || outer_qualified_match || unqualified_match {
                col_ref.column = Arc::from(new_column);
                true
            } else {
                false
            }
        }
        Expr::BinaryOp { left, right, .. } => {
            rename_column_refs_in_expr_for_table_with_outer(
                left,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            ) | rename_column_refs_in_expr_for_table_with_outer(
                right,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            )
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => rename_column_refs_in_expr_for_table_with_outer(
            expr,
            table_name,
            old_column,
            new_column,
            bindings,
            allow_unqualified,
            hidden_tables,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        ),
        Expr::Between {
            expr, low, high, ..
        } => {
            rename_column_refs_in_expr_for_table_with_outer(
                expr,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            ) | rename_column_refs_in_expr_for_table_with_outer(
                low,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            ) | rename_column_refs_in_expr_for_table_with_outer(
                high,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            )
        }
        Expr::In { expr, set, .. } => {
            let expr_changed = rename_column_refs_in_expr_for_table_with_outer(
                expr,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            );
            let set_changed = match set {
                InSet::List(values) => values.iter_mut().fold(false, |changed, value| {
                    rename_column_refs_in_expr_for_table_with_outer(
                        value,
                        table_name,
                        old_column,
                        new_column,
                        bindings,
                        allow_unqualified,
                        hidden_tables,
                        outer_bindings,
                        outer_allow_unqualified,
                        source_catalog,
                    ) | changed
                }),
                InSet::Subquery(query) => {
                    let nested_outer = bindings.nested_outer_bindings(outer_bindings);
                    let nested_outer_allow = allow_unqualified
                        || (bindings.source_count == 0 && outer_allow_unqualified);
                    rename_column_refs_in_select_for_table_with_outer(
                        query,
                        table_name,
                        old_column,
                        new_column,
                        hidden_tables,
                        &nested_outer,
                        nested_outer_allow,
                        source_catalog,
                    )
                }
                InSet::Table(_) => false,
            };
            expr_changed | set_changed
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            rename_column_refs_in_expr_for_table_with_outer(
                expr,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            ) | rename_column_refs_in_expr_for_table_with_outer(
                pattern,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            ) | escape.as_deref_mut().is_some_and(|expr| {
                rename_column_refs_in_expr_for_table_with_outer(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    bindings,
                    allow_unqualified,
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                )
            })
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            let operand_changed = operand.as_deref_mut().is_some_and(|expr| {
                rename_column_refs_in_expr_for_table_with_outer(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    bindings,
                    allow_unqualified,
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                )
            });
            let whens_changed = whens.iter_mut().fold(false, |changed, (when, then)| {
                changed
                    | rename_column_refs_in_expr_for_table_with_outer(
                        when,
                        table_name,
                        old_column,
                        new_column,
                        bindings,
                        allow_unqualified,
                        hidden_tables,
                        outer_bindings,
                        outer_allow_unqualified,
                        source_catalog,
                    )
                    | rename_column_refs_in_expr_for_table_with_outer(
                        then,
                        table_name,
                        old_column,
                        new_column,
                        bindings,
                        allow_unqualified,
                        hidden_tables,
                        outer_bindings,
                        outer_allow_unqualified,
                        source_catalog,
                    )
            });
            let else_changed = else_expr.as_deref_mut().is_some_and(|expr| {
                rename_column_refs_in_expr_for_table_with_outer(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    bindings,
                    allow_unqualified,
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                )
            });
            operand_changed | whens_changed | else_changed
        }
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            let nested_outer = bindings.nested_outer_bindings(outer_bindings);
            let nested_outer_allow =
                allow_unqualified || (bindings.source_count == 0 && outer_allow_unqualified);
            rename_column_refs_in_select_for_table_with_outer(
                subquery,
                table_name,
                old_column,
                new_column,
                hidden_tables,
                &nested_outer,
                nested_outer_allow,
                source_catalog,
            )
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_changed = match args {
                FunctionArgs::List(args) => args.iter_mut().fold(false, |changed, arg| {
                    rename_column_refs_in_expr_for_table_with_outer(
                        arg,
                        table_name,
                        old_column,
                        new_column,
                        bindings,
                        allow_unqualified,
                        hidden_tables,
                        outer_bindings,
                        outer_allow_unqualified,
                        source_catalog,
                    ) | changed
                }),
                FunctionArgs::Star => false,
            };
            let order_changed = rename_column_refs_in_ordering_terms_for_table_with_outer(
                order_by,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            );
            let filter_changed = filter.as_deref_mut().is_some_and(|expr| {
                rename_column_refs_in_expr_for_table_with_outer(
                    expr,
                    table_name,
                    old_column,
                    new_column,
                    bindings,
                    allow_unqualified,
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                )
            });
            let over_changed = over.as_mut().is_some_and(|window| {
                rename_column_refs_in_window_spec_for_table_with_outer(
                    window,
                    table_name,
                    old_column,
                    new_column,
                    bindings,
                    allow_unqualified,
                    hidden_tables,
                    outer_bindings,
                    outer_allow_unqualified,
                    source_catalog,
                )
            });
            args_changed | order_changed | filter_changed | over_changed
        }
        Expr::JsonAccess { expr, path, .. } => {
            rename_column_refs_in_expr_for_table_with_outer(
                expr,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            ) | rename_column_refs_in_expr_for_table_with_outer(
                path,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            )
        }
        Expr::RowValue(values, _) => values.iter_mut().fold(false, |changed, value| {
            rename_column_refs_in_expr_for_table_with_outer(
                value,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            ) | changed
        }),
    }
}

fn rename_column_refs_in_ordering_terms_for_table_with_hidden(
    order_by: &mut [OrderingTerm],
    table_name: &str,
    old_column: &str,
    new_column: &str,
    bindings: &ColumnRenameBindings,
    allow_unqualified: bool,
    hidden_tables: &HashSet<String>,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    rename_column_refs_in_ordering_terms_for_table_with_outer(
        order_by,
        table_name,
        old_column,
        new_column,
        bindings,
        allow_unqualified,
        hidden_tables,
        &ColumnRenameBindings::default(),
        false,
        source_catalog,
    )
}

fn rename_column_refs_in_ordering_terms_for_table_with_outer(
    order_by: &mut [OrderingTerm],
    table_name: &str,
    old_column: &str,
    new_column: &str,
    bindings: &ColumnRenameBindings,
    allow_unqualified: bool,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    order_by.iter_mut().fold(false, |changed, term| {
        rename_column_refs_in_expr_for_table_with_outer(
            &mut term.expr,
            table_name,
            old_column,
            new_column,
            bindings,
            allow_unqualified,
            hidden_tables,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        ) | changed
    })
}

fn rename_column_refs_in_top_level_ordering_terms_for_table(
    order_by: &mut [OrderingTerm],
    table_name: &str,
    old_column: &str,
    new_column: &str,
    bindings: &ColumnRenameBindings,
    allow_unqualified: bool,
    output_aliases: &HashSet<String>,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    order_by.iter_mut().fold(false, |changed, term| {
        let allow_unqualified =
            allow_unqualified && !ordering_term_resolves_to_output_alias(term, output_aliases);
        rename_column_refs_in_expr_for_table_with_outer(
            &mut term.expr,
            table_name,
            old_column,
            new_column,
            bindings,
            allow_unqualified,
            hidden_tables,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        ) | changed
    })
}

fn ordering_term_resolves_to_output_alias(
    term: &OrderingTerm,
    output_aliases: &HashSet<String>,
) -> bool {
    expr_resolves_to_output_alias(&term.expr, output_aliases)
}

fn expr_resolves_to_output_alias(expr: &Expr, output_aliases: &HashSet<String>) -> bool {
    match expr {
        Expr::Column(col_ref, _) if col_ref.table.is_none() => {
            output_aliases.contains(&col_ref.column.to_ascii_lowercase())
        }
        Expr::Collate { expr, .. } => expr_resolves_to_output_alias(expr, output_aliases),
        _ => false,
    }
}

fn rename_column_refs_in_window_spec_for_table_with_outer(
    window: &mut WindowSpec,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    bindings: &ColumnRenameBindings,
    allow_unqualified: bool,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    window.partition_by.iter_mut().fold(false, |changed, expr| {
        rename_column_refs_in_expr_for_table_with_outer(
            expr,
            table_name,
            old_column,
            new_column,
            bindings,
            allow_unqualified,
            hidden_tables,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        ) | changed
    }) | rename_column_refs_in_ordering_terms_for_table_with_outer(
        &mut window.order_by,
        table_name,
        old_column,
        new_column,
        bindings,
        allow_unqualified,
        hidden_tables,
        outer_bindings,
        outer_allow_unqualified,
        source_catalog,
    ) | window.frame.as_mut().is_some_and(|frame| {
        rename_column_refs_in_frame_spec_for_table_with_outer(
            frame,
            table_name,
            old_column,
            new_column,
            bindings,
            allow_unqualified,
            hidden_tables,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        )
    })
}

fn rename_column_refs_in_frame_spec_for_table_with_outer(
    frame: &mut FrameSpec,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    bindings: &ColumnRenameBindings,
    allow_unqualified: bool,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    rename_column_refs_in_frame_bound_for_table_with_outer(
        &mut frame.start,
        table_name,
        old_column,
        new_column,
        bindings,
        allow_unqualified,
        hidden_tables,
        outer_bindings,
        outer_allow_unqualified,
        source_catalog,
    ) | frame.end.as_mut().is_some_and(|bound| {
        rename_column_refs_in_frame_bound_for_table_with_outer(
            bound,
            table_name,
            old_column,
            new_column,
            bindings,
            allow_unqualified,
            hidden_tables,
            outer_bindings,
            outer_allow_unqualified,
            source_catalog,
        )
    })
}

fn rename_column_refs_in_frame_bound_for_table_with_outer(
    bound: &mut FrameBound,
    table_name: &str,
    old_column: &str,
    new_column: &str,
    bindings: &ColumnRenameBindings,
    allow_unqualified: bool,
    hidden_tables: &HashSet<String>,
    outer_bindings: &ColumnRenameBindings,
    outer_allow_unqualified: bool,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            rename_column_refs_in_expr_for_table_with_outer(
                expr,
                table_name,
                old_column,
                new_column,
                bindings,
                allow_unqualified,
                hidden_tables,
                outer_bindings,
                outer_allow_unqualified,
                source_catalog,
            )
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn rename_trigger_event_columns(
    event: &mut fsqlite_ast::TriggerEvent,
    old: &str,
    new: &str,
) -> bool {
    let fsqlite_ast::TriggerEvent::Update(columns) = event else {
        return false;
    };
    columns.iter_mut().fold(false, |changed, column| {
        if column.eq_ignore_ascii_case(old) {
            column.clear();
            column.push_str(new);
            true
        } else {
            changed
        }
    })
}

#[derive(Clone, Default)]
struct TriggerRowRenameScope {
    shadowed_row_names: HashSet<String>,
    bare_old_column_shadowed: bool,
}

impl TriggerRowRenameScope {
    fn shadows_trigger_row(&self, name: &str) -> bool {
        self.shadowed_row_names.contains(&name.to_ascii_lowercase())
    }

    fn shadows_bare_old_column(&self) -> bool {
        self.bare_old_column_shadowed
    }

    fn add_source_binding(&mut self, name: &str) {
        if is_trigger_row_name(name) {
            self.shadowed_row_names.insert(name.to_ascii_lowercase());
        }
    }

    fn add_old_column_source(&mut self) {
        self.bare_old_column_shadowed = true;
    }

    fn add_source_alias_or_name(&mut self, alias: Option<&str>, name: &str) {
        self.add_source_binding(alias.unwrap_or(name));
    }

    fn add_table_source_if_may_expose_old_column(
        &mut self,
        alias: Option<&str>,
        name: &QualifiedName,
        hidden_tables: &HashSet<String>,
        source_catalog: &ColumnRenameSourceCatalog,
    ) {
        if source_catalog.table_may_expose_old_column(name, hidden_tables) {
            self.add_old_column_source();
            self.add_source_alias_or_name(alias, &name.name);
        }
    }

    fn add_subquery_alias_if_may_expose_old_column(
        &mut self,
        alias: Option<&str>,
        query: &SelectStatement,
        old_column: &str,
    ) {
        if select_statement_may_output_column(query, old_column) {
            self.add_old_column_source();
            if let Some(alias) = alias {
                self.add_source_binding(alias);
            }
        }
    }
}

fn is_trigger_row_name(name: &str) -> bool {
    name.eq_ignore_ascii_case("old") || name.eq_ignore_ascii_case("new")
}

fn rename_trigger_row_column_refs_in_statement(
    statement: &mut Statement,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    let hidden_tables = HashSet::new();
    rename_trigger_row_column_refs_in_statement_with_scope(
        statement,
        old,
        new,
        source_catalog,
        &TriggerRowRenameScope::default(),
        &hidden_tables,
    )
}

fn rename_trigger_row_column_refs_in_statement_with_scope(
    statement: &mut Statement,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    scope: &TriggerRowRenameScope,
    hidden_tables: &HashSet<String>,
) -> bool {
    match statement {
        Statement::Select(select) => rename_trigger_row_column_refs_in_select_with_scope(
            select,
            old,
            new,
            source_catalog,
            scope,
            hidden_tables,
        ),
        Statement::Insert(insert) => {
            let mut changed = false;
            let scoped_hidden = if let Some(with) = &mut insert.with {
                let (with_changed, hidden) =
                    rename_trigger_row_column_refs_in_with_clause_with_scope(
                        with,
                        old,
                        new,
                        source_catalog,
                        scope,
                        hidden_tables,
                    );
                changed |= with_changed;
                hidden
            } else {
                hidden_tables.clone()
            };
            match &mut insert.source {
                InsertSource::Values(rows) => {
                    for row in rows {
                        for expr in row {
                            changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                                expr,
                                old,
                                new,
                                source_catalog,
                                &scoped_hidden,
                                scope,
                            );
                        }
                    }
                }
                InsertSource::Select(select) => {
                    changed |= rename_trigger_row_column_refs_in_select_with_scope(
                        select,
                        old,
                        new,
                        source_catalog,
                        scope,
                        &scoped_hidden,
                    );
                }
                InsertSource::DefaultValues => {}
            }
            let mut target_scope = scope.clone();
            target_scope.add_table_source_if_may_expose_old_column(
                insert.alias.as_deref(),
                &insert.table,
                &scoped_hidden,
                source_catalog,
            );
            for upsert in &mut insert.upsert {
                if let Some(target) = &mut upsert.target {
                    for column in &mut target.columns {
                        changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                            &mut column.expr,
                            old,
                            new,
                            source_catalog,
                            &scoped_hidden,
                            &target_scope,
                        );
                    }
                    if let Some(where_clause) = &mut target.where_clause {
                        changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                            where_clause,
                            old,
                            new,
                            source_catalog,
                            &scoped_hidden,
                            &target_scope,
                        );
                    }
                }
                if let UpsertAction::Update {
                    assignments,
                    where_clause,
                } = &mut upsert.action
                {
                    for assignment in assignments {
                        changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                            &mut assignment.value,
                            old,
                            new,
                            source_catalog,
                            &scoped_hidden,
                            &target_scope,
                        );
                    }
                    if let Some(where_clause) = where_clause {
                        changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                            where_clause,
                            old,
                            new,
                            source_catalog,
                            &scoped_hidden,
                            &target_scope,
                        );
                    }
                }
            }
            for column in &mut insert.returning {
                changed |= rename_trigger_row_column_refs_in_result_column_with_scope(
                    column,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    &target_scope,
                );
            }
            changed
        }
        Statement::Update(update) => {
            let mut changed = false;
            let scoped_hidden = if let Some(with) = &mut update.with {
                let (with_changed, hidden) =
                    rename_trigger_row_column_refs_in_with_clause_with_scope(
                        with,
                        old,
                        new,
                        source_catalog,
                        scope,
                        hidden_tables,
                    );
                changed |= with_changed;
                hidden
            } else {
                hidden_tables.clone()
            };
            let mut statement_scope = scope.clone();
            statement_scope.add_table_source_if_may_expose_old_column(
                update.table.alias.as_deref(),
                &update.table.name,
                &scoped_hidden,
                source_catalog,
            );
            if let Some(from_clause) = &mut update.from {
                changed |= rename_trigger_row_column_refs_in_table_or_subquery_with_scope(
                    &mut from_clause.source,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    scope,
                    &mut statement_scope,
                );
                for join in &mut from_clause.joins {
                    changed |= rename_trigger_row_column_refs_in_table_or_subquery_with_scope(
                        &mut join.table,
                        old,
                        new,
                        source_catalog,
                        &scoped_hidden,
                        scope,
                        &mut statement_scope,
                    );
                }
                for join in &mut from_clause.joins {
                    if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
                        changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                            expr,
                            old,
                            new,
                            source_catalog,
                            &scoped_hidden,
                            &statement_scope,
                        );
                    }
                }
            }
            for assignment in &mut update.assignments {
                changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                    &mut assignment.value,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    &statement_scope,
                );
            }
            if let Some(where_clause) = &mut update.where_clause {
                changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                    where_clause,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    &statement_scope,
                );
            }
            for column in &mut update.returning {
                changed |= rename_trigger_row_column_refs_in_result_column_with_scope(
                    column,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    &statement_scope,
                );
            }
            changed |= rename_trigger_row_column_refs_in_ordering_terms_with_scope(
                &mut update.order_by,
                old,
                new,
                source_catalog,
                &scoped_hidden,
                &statement_scope,
            );
            if let Some(limit) = &mut update.limit {
                changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                    &mut limit.limit,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    &statement_scope,
                );
                if let Some(offset) = &mut limit.offset {
                    changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                        offset,
                        old,
                        new,
                        source_catalog,
                        &scoped_hidden,
                        &statement_scope,
                    );
                }
            }
            changed
        }
        Statement::Delete(delete) => {
            let mut changed = false;
            let scoped_hidden = if let Some(with) = &mut delete.with {
                let (with_changed, hidden) =
                    rename_trigger_row_column_refs_in_with_clause_with_scope(
                        with,
                        old,
                        new,
                        source_catalog,
                        scope,
                        hidden_tables,
                    );
                changed |= with_changed;
                hidden
            } else {
                hidden_tables.clone()
            };
            let mut statement_scope = scope.clone();
            statement_scope.add_table_source_if_may_expose_old_column(
                delete.table.alias.as_deref(),
                &delete.table.name,
                &scoped_hidden,
                source_catalog,
            );
            if let Some(where_clause) = &mut delete.where_clause {
                changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                    where_clause,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    &statement_scope,
                );
            }
            for column in &mut delete.returning {
                changed |= rename_trigger_row_column_refs_in_result_column_with_scope(
                    column,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    &statement_scope,
                );
            }
            changed |= rename_trigger_row_column_refs_in_ordering_terms_with_scope(
                &mut delete.order_by,
                old,
                new,
                source_catalog,
                &scoped_hidden,
                &statement_scope,
            );
            if let Some(limit) = &mut delete.limit {
                changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                    &mut limit.limit,
                    old,
                    new,
                    source_catalog,
                    &scoped_hidden,
                    &statement_scope,
                );
                if let Some(offset) = &mut limit.offset {
                    changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                        offset,
                        old,
                        new,
                        source_catalog,
                        &scoped_hidden,
                        &statement_scope,
                    );
                }
            }
            changed
        }
        Statement::Explain { stmt, .. } => rename_trigger_row_column_refs_in_statement_with_scope(
            stmt,
            old,
            new,
            source_catalog,
            scope,
            hidden_tables,
        ),
        _ => false,
    }
}

fn rename_trigger_row_column_refs_in_with_clause_with_scope(
    with: &mut fsqlite_ast::WithClause,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    scope: &TriggerRowRenameScope,
    hidden_tables: &HashSet<String>,
) -> (bool, HashSet<String>) {
    let mut scoped_hidden = hidden_tables.clone();
    for cte in &with.ctes {
        add_hidden_cte_for_column_rename(&mut scoped_hidden, cte, old);
    }
    let mut changed = false;
    for _ in 0..=with.ctes.len() {
        let mut pass_changed = false;
        for cte in &mut with.ctes {
            pass_changed |= rename_trigger_row_column_refs_in_select_with_scope(
                &mut cte.query,
                old,
                new,
                source_catalog,
                scope,
                &scoped_hidden,
            );
            refresh_hidden_cte_for_column_rename(&mut scoped_hidden, cte, old, new, source_catalog);
        }
        changed |= pass_changed;
        if !pass_changed {
            break;
        }
    }
    (changed, scoped_hidden)
}

fn rename_trigger_row_column_refs_in_select_with_scope(
    select: &mut SelectStatement,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    scope: &TriggerRowRenameScope,
    hidden_tables: &HashSet<String>,
) -> bool {
    let mut changed = false;
    let scoped_hidden = if let Some(with) = &mut select.with {
        let (with_changed, hidden) = rename_trigger_row_column_refs_in_with_clause_with_scope(
            with,
            old,
            new,
            source_catalog,
            scope,
            hidden_tables,
        );
        changed |= with_changed;
        hidden
    } else {
        hidden_tables.clone()
    };
    let mut first_core_scope = scope.clone();
    changed |= rename_trigger_row_column_refs_in_select_core_with_scope(
        &mut select.body.select,
        old,
        new,
        source_catalog,
        &scoped_hidden,
        scope,
        &mut first_core_scope,
    );
    for (_, core) in &mut select.body.compounds {
        let mut compound_core_scope = scope.clone();
        changed |= rename_trigger_row_column_refs_in_select_core_with_scope(
            core,
            old,
            new,
            source_catalog,
            &scoped_hidden,
            scope,
            &mut compound_core_scope,
        );
    }
    let order_scope = &first_core_scope;
    changed |= rename_trigger_row_column_refs_in_ordering_terms_with_scope(
        &mut select.order_by,
        old,
        new,
        source_catalog,
        &scoped_hidden,
        order_scope,
    );
    if let Some(limit) = &mut select.limit {
        changed |= rename_trigger_row_column_refs_in_expr_with_scope(
            &mut limit.limit,
            old,
            new,
            source_catalog,
            &scoped_hidden,
            order_scope,
        );
        if let Some(offset) = &mut limit.offset {
            changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                offset,
                old,
                new,
                source_catalog,
                &scoped_hidden,
                order_scope,
            );
        }
    }
    changed
}

fn rename_trigger_row_column_refs_in_select_core_with_scope(
    core: &mut SelectCore,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    hidden_tables: &HashSet<String>,
    outer_scope: &TriggerRowRenameScope,
    expression_scope: &mut TriggerRowRenameScope,
) -> bool {
    match core {
        SelectCore::Values(rows) => rows.iter_mut().fold(false, |changed, row| {
            row.iter_mut().fold(changed, |changed, expr| {
                rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    expression_scope,
                ) | changed
            })
        }),
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            let mut changed = false;
            if let Some(from_clause) = from {
                changed |= rename_trigger_row_column_refs_in_table_or_subquery_with_scope(
                    &mut from_clause.source,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    outer_scope,
                    expression_scope,
                );
                for join in &mut from_clause.joins {
                    changed |= rename_trigger_row_column_refs_in_table_or_subquery_with_scope(
                        &mut join.table,
                        old,
                        new,
                        source_catalog,
                        hidden_tables,
                        outer_scope,
                        expression_scope,
                    );
                }
                for join in &mut from_clause.joins {
                    if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
                        changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                            expr,
                            old,
                            new,
                            source_catalog,
                            hidden_tables,
                            expression_scope,
                        );
                    }
                }
            }
            for column in columns {
                changed |= rename_trigger_row_column_refs_in_result_column_with_scope(
                    column,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    expression_scope,
                );
            }
            if let Some(expr) = where_clause {
                changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    expression_scope,
                );
            }
            for expr in group_by {
                changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    expression_scope,
                );
            }
            if let Some(expr) = having {
                changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    expression_scope,
                );
            }
            for window in windows {
                changed |= rename_trigger_row_column_refs_in_window_spec_with_scope(
                    &mut window.spec,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    expression_scope,
                );
            }
            changed
        }
    }
}

fn rename_trigger_row_column_refs_in_table_or_subquery_with_scope(
    source: &mut TableOrSubquery,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    hidden_tables: &HashSet<String>,
    outer_scope: &TriggerRowRenameScope,
    expression_scope: &mut TriggerRowRenameScope,
) -> bool {
    match source {
        TableOrSubquery::Subquery { query, alias } => {
            let changed = rename_trigger_row_column_refs_in_select_with_scope(
                query,
                old,
                new,
                source_catalog,
                outer_scope,
                hidden_tables,
            );
            expression_scope.add_subquery_alias_if_may_expose_old_column(
                alias.as_deref(),
                query,
                old,
            );
            changed
        }
        TableOrSubquery::TableFunction { name, args, alias } => {
            let changed = args.iter_mut().fold(false, |changed, expr| {
                rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    outer_scope,
                ) | changed
            });
            expression_scope.add_old_column_source();
            expression_scope.add_source_alias_or_name(alias.as_deref(), name);
            changed
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            let mut changed = rename_trigger_row_column_refs_in_table_or_subquery_with_scope(
                &mut from_clause.source,
                old,
                new,
                source_catalog,
                hidden_tables,
                outer_scope,
                expression_scope,
            );
            for join in &mut from_clause.joins {
                changed |= rename_trigger_row_column_refs_in_table_or_subquery_with_scope(
                    &mut join.table,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    outer_scope,
                    expression_scope,
                );
            }
            for join in &mut from_clause.joins {
                if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
                    changed |= rename_trigger_row_column_refs_in_expr_with_scope(
                        expr,
                        old,
                        new,
                        source_catalog,
                        hidden_tables,
                        expression_scope,
                    );
                }
            }
            changed
        }
        TableOrSubquery::Table { name, alias, .. } => {
            expression_scope.add_table_source_if_may_expose_old_column(
                alias.as_deref(),
                name,
                hidden_tables,
                source_catalog,
            );
            false
        }
    }
}

fn rename_trigger_row_column_refs_in_result_column_with_scope(
    column: &mut ResultColumn,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    hidden_tables: &HashSet<String>,
    scope: &TriggerRowRenameScope,
) -> bool {
    match column {
        ResultColumn::Expr { expr, .. } => rename_trigger_row_column_refs_in_expr_with_scope(
            expr,
            old,
            new,
            source_catalog,
            hidden_tables,
            scope,
        ),
        ResultColumn::Star | ResultColumn::TableStar(_) => false,
    }
}

fn rename_trigger_row_column_refs_in_expr(
    expr: &mut Expr,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
) -> bool {
    let hidden_tables = HashSet::new();
    rename_trigger_row_column_refs_in_expr_with_scope(
        expr,
        old,
        new,
        source_catalog,
        &hidden_tables,
        &TriggerRowRenameScope::default(),
    )
}

fn rename_trigger_row_column_refs_in_expr_with_scope(
    expr: &mut Expr,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    hidden_tables: &HashSet<String>,
    scope: &TriggerRowRenameScope,
) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => false,
        Expr::Column(col_ref, _) => match col_ref.table.as_deref() {
            Some(table)
                if is_trigger_row_name(table)
                    && !scope.shadows_trigger_row(table)
                    && col_ref.column.eq_ignore_ascii_case(old) =>
            {
                col_ref.column = Arc::from(new);
                true
            }
            None if !scope.shadows_bare_old_column()
                && col_ref.column.eq_ignore_ascii_case(old) =>
            {
                col_ref.column = Arc::from(new);
                true
            }
            Some(_) | None => false,
        },
        Expr::BinaryOp { left, right, .. } => {
            rename_trigger_row_column_refs_in_expr_with_scope(
                left,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            ) | rename_trigger_row_column_refs_in_expr_with_scope(
                right,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            )
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => rename_trigger_row_column_refs_in_expr_with_scope(
            expr,
            old,
            new,
            source_catalog,
            hidden_tables,
            scope,
        ),
        Expr::Between {
            expr, low, high, ..
        } => {
            rename_trigger_row_column_refs_in_expr_with_scope(
                expr,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            ) | rename_trigger_row_column_refs_in_expr_with_scope(
                low,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            ) | rename_trigger_row_column_refs_in_expr_with_scope(
                high,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            )
        }
        Expr::In { expr, set, .. } => {
            let expr_changed = rename_trigger_row_column_refs_in_expr_with_scope(
                expr,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            );
            let set_changed = match set {
                InSet::List(values) => values.iter_mut().fold(false, |changed, value| {
                    rename_trigger_row_column_refs_in_expr_with_scope(
                        value,
                        old,
                        new,
                        source_catalog,
                        hidden_tables,
                        scope,
                    ) | changed
                }),
                InSet::Subquery(query) => rename_trigger_row_column_refs_in_select_with_scope(
                    query,
                    old,
                    new,
                    source_catalog,
                    scope,
                    hidden_tables,
                ),
                InSet::Table(_) => false,
            };
            expr_changed | set_changed
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            rename_trigger_row_column_refs_in_expr_with_scope(
                expr,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            ) | rename_trigger_row_column_refs_in_expr_with_scope(
                pattern,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            ) | escape.as_deref_mut().is_some_and(|expr| {
                rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    scope,
                )
            })
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            let operand_changed = operand.as_deref_mut().is_some_and(|expr| {
                rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    scope,
                )
            });
            let whens_changed = whens.iter_mut().fold(false, |changed, (when, then)| {
                changed
                    | rename_trigger_row_column_refs_in_expr_with_scope(
                        when,
                        old,
                        new,
                        source_catalog,
                        hidden_tables,
                        scope,
                    )
                    | rename_trigger_row_column_refs_in_expr_with_scope(
                        then,
                        old,
                        new,
                        source_catalog,
                        hidden_tables,
                        scope,
                    )
            });
            let else_changed = else_expr.as_deref_mut().is_some_and(|expr| {
                rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    scope,
                )
            });
            operand_changed | whens_changed | else_changed
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_changed = match args {
                FunctionArgs::List(args) => args.iter_mut().fold(false, |changed, arg| {
                    rename_trigger_row_column_refs_in_expr_with_scope(
                        arg,
                        old,
                        new,
                        source_catalog,
                        hidden_tables,
                        scope,
                    ) | changed
                }),
                FunctionArgs::Star => false,
            };
            let order_changed = rename_trigger_row_column_refs_in_ordering_terms_with_scope(
                order_by,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            );
            let filter_changed = filter.as_deref_mut().is_some_and(|expr| {
                rename_trigger_row_column_refs_in_expr_with_scope(
                    expr,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    scope,
                )
            });
            let over_changed = over.as_mut().is_some_and(|window| {
                rename_trigger_row_column_refs_in_window_spec_with_scope(
                    window,
                    old,
                    new,
                    source_catalog,
                    hidden_tables,
                    scope,
                )
            });
            args_changed | order_changed | filter_changed | over_changed
        }
        Expr::JsonAccess { expr, path, .. } => {
            rename_trigger_row_column_refs_in_expr_with_scope(
                expr,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            ) | rename_trigger_row_column_refs_in_expr_with_scope(
                path,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            )
        }
        Expr::RowValue(values, _) => values.iter_mut().fold(false, |changed, value| {
            rename_trigger_row_column_refs_in_expr_with_scope(
                value,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            ) | changed
        }),
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            rename_trigger_row_column_refs_in_select_with_scope(
                subquery,
                old,
                new,
                source_catalog,
                scope,
                hidden_tables,
            )
        }
    }
}

fn rename_trigger_row_column_refs_in_ordering_terms_with_scope(
    order_by: &mut [OrderingTerm],
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    hidden_tables: &HashSet<String>,
    scope: &TriggerRowRenameScope,
) -> bool {
    order_by.iter_mut().fold(false, |changed, term| {
        rename_trigger_row_column_refs_in_expr_with_scope(
            &mut term.expr,
            old,
            new,
            source_catalog,
            hidden_tables,
            scope,
        ) | changed
    })
}

fn rename_trigger_row_column_refs_in_window_spec_with_scope(
    window: &mut WindowSpec,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    hidden_tables: &HashSet<String>,
    scope: &TriggerRowRenameScope,
) -> bool {
    window.partition_by.iter_mut().fold(false, |changed, expr| {
        rename_trigger_row_column_refs_in_expr_with_scope(
            expr,
            old,
            new,
            source_catalog,
            hidden_tables,
            scope,
        ) | changed
    }) | rename_trigger_row_column_refs_in_ordering_terms_with_scope(
        &mut window.order_by,
        old,
        new,
        source_catalog,
        hidden_tables,
        scope,
    ) | window.frame.as_mut().is_some_and(|frame| {
        rename_trigger_row_column_refs_in_frame_spec_with_scope(
            frame,
            old,
            new,
            source_catalog,
            hidden_tables,
            scope,
        )
    })
}

fn rename_trigger_row_column_refs_in_frame_spec_with_scope(
    frame: &mut FrameSpec,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    hidden_tables: &HashSet<String>,
    scope: &TriggerRowRenameScope,
) -> bool {
    rename_trigger_row_column_refs_in_frame_bound_with_scope(
        &mut frame.start,
        old,
        new,
        source_catalog,
        hidden_tables,
        scope,
    ) | frame.end.as_mut().is_some_and(|bound| {
        rename_trigger_row_column_refs_in_frame_bound_with_scope(
            bound,
            old,
            new,
            source_catalog,
            hidden_tables,
            scope,
        )
    })
}

fn rename_trigger_row_column_refs_in_frame_bound_with_scope(
    bound: &mut FrameBound,
    old: &str,
    new: &str,
    source_catalog: &ColumnRenameSourceCatalog,
    hidden_tables: &HashSet<String>,
    scope: &TriggerRowRenameScope,
) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            rename_trigger_row_column_refs_in_expr_with_scope(
                expr,
                old,
                new,
                source_catalog,
                hidden_tables,
                scope,
            )
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn rename_column_refs_in_expr(expr: &mut Expr, old: &str, new: &str) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => false,
        Expr::Column(col_ref, _) => {
            if col_ref.column.eq_ignore_ascii_case(old) {
                col_ref.column = Arc::from(new);
                true
            } else {
                false
            }
        }
        Expr::BinaryOp { left, right, .. } => {
            rename_column_refs_in_expr(left, old, new) | rename_column_refs_in_expr(right, old, new)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => rename_column_refs_in_expr(expr, old, new),
        Expr::Between {
            expr, low, high, ..
        } => {
            rename_column_refs_in_expr(expr, old, new)
                | rename_column_refs_in_expr(low, old, new)
                | rename_column_refs_in_expr(high, old, new)
        }
        Expr::In { expr, set, .. } => {
            let expr_changed = rename_column_refs_in_expr(expr, old, new);
            let set_changed = match set {
                InSet::List(values) => rename_column_refs_in_exprs(values, old, new),
                InSet::Subquery(_) | InSet::Table(_) => false,
            };
            expr_changed | set_changed
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            rename_column_refs_in_expr(expr, old, new)
                | rename_column_refs_in_expr(pattern, old, new)
                | escape
                    .as_deref_mut()
                    .is_some_and(|expr| rename_column_refs_in_expr(expr, old, new))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            let operand_changed = operand
                .as_deref_mut()
                .is_some_and(|expr| rename_column_refs_in_expr(expr, old, new));
            let whens_changed = whens.iter_mut().fold(false, |changed, (when, then)| {
                changed
                    | rename_column_refs_in_expr(when, old, new)
                    | rename_column_refs_in_expr(then, old, new)
            });
            let else_changed = else_expr
                .as_deref_mut()
                .is_some_and(|expr| rename_column_refs_in_expr(expr, old, new));
            operand_changed | whens_changed | else_changed
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_changed = match args {
                FunctionArgs::List(args) => rename_column_refs_in_exprs(args, old, new),
                FunctionArgs::Star => false,
            };
            let order_changed = rename_column_refs_in_ordering_terms(order_by, old, new);
            let filter_changed = filter
                .as_deref_mut()
                .is_some_and(|expr| rename_column_refs_in_expr(expr, old, new));
            let over_changed = over
                .as_mut()
                .is_some_and(|window| rename_column_refs_in_window_spec(window, old, new));
            args_changed | order_changed | filter_changed | over_changed
        }
        Expr::JsonAccess { expr, path, .. } => {
            rename_column_refs_in_expr(expr, old, new) | rename_column_refs_in_expr(path, old, new)
        }
        Expr::RowValue(values, _) => rename_column_refs_in_exprs(values, old, new),
        Expr::Exists { .. } | Expr::Subquery(..) => false,
    }
}

fn rename_column_refs_in_exprs(exprs: &mut [Expr], old: &str, new: &str) -> bool {
    exprs.iter_mut().fold(false, |changed, expr| {
        rename_column_refs_in_expr(expr, old, new) | changed
    })
}

fn rename_column_refs_in_ordering_terms(
    order_by: &mut [OrderingTerm],
    old: &str,
    new: &str,
) -> bool {
    order_by.iter_mut().fold(false, |changed, term| {
        rename_column_refs_in_expr(&mut term.expr, old, new) | changed
    })
}

fn rename_column_refs_in_window_spec(window: &mut WindowSpec, old: &str, new: &str) -> bool {
    rename_column_refs_in_exprs(&mut window.partition_by, old, new)
        | rename_column_refs_in_ordering_terms(&mut window.order_by, old, new)
        | window
            .frame
            .as_mut()
            .is_some_and(|frame| rename_column_refs_in_frame_spec(frame, old, new))
}

fn rename_column_refs_in_frame_spec(frame: &mut FrameSpec, old: &str, new: &str) -> bool {
    rename_column_refs_in_frame_bound(&mut frame.start, old, new)
        | frame
            .end
            .as_mut()
            .is_some_and(|bound| rename_column_refs_in_frame_bound(bound, old, new))
}

fn rename_column_refs_in_frame_bound(bound: &mut FrameBound, old: &str, new: &str) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            rename_column_refs_in_expr(expr, old, new)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn collect_primary_key_constraints(
    columns: &[fsqlite_ast::ColumnDef],
    constraints: &[fsqlite_ast::TableConstraint],
) -> Vec<Vec<String>> {
    let mut primary_keys = columns
        .iter()
        .filter(|column| {
            column.constraints.iter().any(|constraint| {
                matches!(constraint.kind, ColumnConstraintKind::PrimaryKey { .. })
            })
        })
        .map(|column| vec![column.name.clone()])
        .collect::<Vec<_>>();

    primary_keys.extend(constraints.iter().filter_map(|constraint| {
        let TableConstraintKind::PrimaryKey {
            columns: indexed_columns,
            ..
        } = &constraint.kind
        else {
            return None;
        };
        let columns = indexed_columns
            .iter()
            .map(normalize_indexed_column_term)
            .collect::<Option<Vec<_>>>()?
            .into_iter()
            .map(|term| term.column_name)
            .collect::<Vec<_>>();
        (!columns.is_empty()).then_some(columns)
    }));

    primary_keys
}

/// bd-w9r11 (GH#222/#223): per-PRIMARY-KEY-column descending flags, parallel
/// to [`collect_primary_key_constraints`] (same group order, same filtering:
/// expression PK terms disqualify the whole table-level group there and here).
fn collect_primary_key_desc_flags(
    columns: &[fsqlite_ast::ColumnDef],
    constraints: &[fsqlite_ast::TableConstraint],
) -> Vec<Vec<bool>> {
    let mut flags = columns
        .iter()
        .filter_map(|column| {
            column.constraints.iter().find_map(|constraint| {
                if let ColumnConstraintKind::PrimaryKey { direction, .. } = &constraint.kind {
                    Some(vec![matches!(direction, Some(SortDirection::Desc))])
                } else {
                    None
                }
            })
        })
        .collect::<Vec<_>>();

    flags.extend(constraints.iter().filter_map(|constraint| {
        let TableConstraintKind::PrimaryKey {
            columns: indexed_columns,
            ..
        } = &constraint.kind
        else {
            return None;
        };
        let directions = indexed_columns
            .iter()
            .map(normalize_indexed_column_term)
            .collect::<Option<Vec<_>>>()?
            .into_iter()
            .map(|term| matches!(term.direction, Some(SortDirection::Desc)))
            .collect::<Vec<_>>();
        (!directions.is_empty()).then_some(directions)
    }));

    flags
}

/// Normalize an indexed-column AST node into a column name + collation + direction.
///
/// Returns `Some` for plain column references (optionally with `COLLATE`),
/// `None` for expression terms (e.g. `LOWER(name)`, `score / 10`).
/// Expression indexes use `key_expressions` instead of `columns`.
fn normalize_indexed_column_term(
    indexed: &fsqlite_ast::IndexedColumn,
) -> Option<NormalizedIndexedColumnTerm> {
    fn extract(expr: &Expr) -> Option<(&str, Option<&str>)> {
        match expr {
            Expr::Column(col_ref, _) if col_ref.table.is_none() => {
                Some((col_ref.column.as_ref(), None))
            }
            // SQLite's indexed-term grammar historically accepts a
            // single-quoted identifier token here (index3.test). It converts
            // the string token back to an identifier before resolving the
            // constrained column.
            Expr::Literal(Literal::String(name), _) => Some((name.as_str(), None)),
            Expr::Collate {
                expr, collation, ..
            } => {
                let (column_name, _) = extract(expr)?;
                Some((column_name, Some(collation.as_str())))
            }
            _ => None,
        }
    }

    let (column_name, expr_collation) = extract(&indexed.expr)?;
    let collation = indexed
        .collation
        .clone()
        .or_else(|| expr_collation.map(str::to_owned));

    Some(NormalizedIndexedColumnTerm {
        column_name: column_name.to_owned(),
        collation,
        direction: indexed.direction,
    })
}

/// Collect all column names referenced by an expression (recursive).
/// Used to validate that expression-index terms only reference existing columns.
#[allow(clippy::collapsible_match)]
fn collect_expr_column_refs<'a>(expr: &'a Expr, out: &mut Vec<&'a str>) {
    match expr {
        Expr::Column(col_ref, _) => out.push(col_ref.column.as_ref()),
        Expr::BinaryOp { left, right, .. } => {
            collect_expr_column_refs(left, out);
            collect_expr_column_refs(right, out);
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => collect_expr_column_refs(inner, out),
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            collect_expr_column_refs(inner, out);
            collect_expr_column_refs(low, out);
            collect_expr_column_refs(high, out);
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            collect_expr_column_refs(inner, out);
            if let InSet::List(items) = set {
                for e in items {
                    collect_expr_column_refs(e, out);
                }
            }
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if let FunctionArgs::List(items) = args {
                for e in items {
                    collect_expr_column_refs(e, out);
                }
            }
            for term in order_by {
                collect_expr_column_refs(&term.expr, out);
            }
            if let Some(filter_expr) = filter {
                collect_expr_column_refs(filter_expr, out);
            }
            if let Some(window) = over {
                for partition_expr in &window.partition_by {
                    collect_expr_column_refs(partition_expr, out);
                }
                for term in &window.order_by {
                    collect_expr_column_refs(&term.expr, out);
                }
                if let Some(frame) = &window.frame {
                    collect_frame_bound_column_refs(&frame.start, out);
                    if let Some(end) = &frame.end {
                        collect_frame_bound_column_refs(end, out);
                    }
                }
            }
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(o) = operand {
                collect_expr_column_refs(o, out);
            }
            for (cond, val) in whens {
                collect_expr_column_refs(cond, out);
                collect_expr_column_refs(val, out);
            }
            if let Some(el) = else_expr {
                collect_expr_column_refs(el, out);
            }
        }
        Expr::Like {
            expr: operand,
            pattern,
            escape,
            ..
        } => {
            collect_expr_column_refs(operand, out);
            collect_expr_column_refs(pattern, out);
            if let Some(esc) = escape {
                collect_expr_column_refs(esc, out);
            }
        }
        Expr::JsonAccess { expr, path, .. } => {
            collect_expr_column_refs(expr, out);
            collect_expr_column_refs(path, out);
        }
        Expr::RowValue(values, _) => {
            for value in values {
                collect_expr_column_refs(value, out);
            }
        }
        // Literals, placeholders, subqueries, etc. have no column refs.
        _ => {}
    }
}

fn collect_frame_bound_column_refs<'a>(bound: &'a FrameBound, out: &mut Vec<&'a str>) {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            collect_expr_column_refs(expr, out);
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => {}
    }
}

fn window_frame_offset_expr_is_constant(expr: &Expr) -> bool {
    match expr {
        Expr::Literal(_, _) | Expr::Placeholder(_, _) => true,
        Expr::BoundOuterValue { .. }
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Exists { .. }
        | Expr::Subquery(_, _)
        | Expr::FunctionCall { .. }
        | Expr::Like { .. }
        | Expr::JsonAccess { .. }
        | Expr::RowValue(_, _) => false,
        Expr::BinaryOp { left, right, .. } => {
            window_frame_offset_expr_is_constant(left)
                && window_frame_offset_expr_is_constant(right)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. } => window_frame_offset_expr_is_constant(inner),
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            window_frame_offset_expr_is_constant(inner)
                && window_frame_offset_expr_is_constant(low)
                && window_frame_offset_expr_is_constant(high)
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return true;
            }
            window_frame_offset_expr_is_constant(inner)
                && matches!(set, InSet::List(values) if values
                    .iter()
                    .all(window_frame_offset_expr_is_constant))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_none_or(window_frame_offset_expr_is_constant)
                && whens.iter().all(|(when_expr, then_expr)| {
                    window_frame_offset_expr_is_constant(when_expr)
                        && window_frame_offset_expr_is_constant(then_expr)
                })
                && else_expr
                    .as_deref()
                    .is_none_or(window_frame_offset_expr_is_constant)
        }
    }
}

fn window_frame_offset_error(frame_type: FrameType, is_start: bool) -> FrankenError {
    let position = if is_start { "starting" } else { "ending" };
    let kind = if matches!(frame_type, FrameType::Range) {
        "number"
    } else {
        "integer"
    };
    FrankenError::function_error(format!(
        "frame {position} offset must be a non-negative {kind}"
    ))
}

fn normalize_window_frame_offset_value(
    value: &SqliteValue,
    frame_type: FrameType,
) -> Option<Literal> {
    if matches!(frame_type, FrameType::Rows | FrameType::Groups) {
        let integer = match value {
            SqliteValue::Integer(value) => Some(*value),
            SqliteValue::Float(value) => nth_value_integral_f64_to_i64(*value),
            SqliteValue::Text(value) => nth_value_parse_integral_text(value),
            SqliteValue::Null | SqliteValue::Blob(_) => None,
        }?;
        return (integer >= 0).then_some(Literal::Integer(integer));
    }

    match value {
        SqliteValue::Integer(value) => (*value >= 0).then_some(Literal::Integer(*value)),
        SqliteValue::Float(value) => {
            (!value.is_nan() && *value >= 0.0).then_some(Literal::Float(*value))
        }
        SqliteValue::Text(value) => {
            let trimmed = value.trim();
            if trimmed
                .bytes()
                .any(|byte| byte.is_ascii_alphabetic() && !matches!(byte, b'e' | b'E'))
            {
                return None;
            }
            if let Ok(integer) = trimmed.parse::<i64>() {
                (integer >= 0).then_some(Literal::Integer(integer))
            } else {
                let number = trimmed.parse::<f64>().ok()?;
                (!number.is_nan() && number >= 0.0).then_some(Literal::Float(number))
            }
        }
        SqliteValue::Null | SqliteValue::Blob(_) => None,
    }
}

/// Resolve a `FrameBound` to a numeric row offset for ROWS frames.
/// Returns `None` for `UnboundedPreceding`/`UnboundedFollowing`/`CurrentRow`.
fn resolve_frame_bound_offset(bound: &FrameBound) -> Option<usize> {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => match expr.as_ref() {
            Expr::Literal(Literal::Integer(n), _) => {
                Some(usize::try_from(*n).unwrap_or(usize::MAX))
            }
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            Expr::Literal(Literal::Float(f), _) => Some(*f as usize),
            _ => Some(0),
        },
        FrameBound::CurrentRow => Some(0),
        FrameBound::UnboundedPreceding | FrameBound::UnboundedFollowing => None,
    }
}

fn rows_groups_offset_interval_is_statically_reversed(frame: &FrameSpec) -> bool {
    let end = frame.end.as_ref().unwrap_or(&FrameBound::CurrentRow);
    match (&frame.start, end) {
        (FrameBound::Preceding(start), FrameBound::Preceding(end)) => {
            resolve_frame_bound_offset(&FrameBound::Preceding(start.clone())).unwrap_or(0)
                < resolve_frame_bound_offset(&FrameBound::Preceding(end.clone())).unwrap_or(0)
        }
        (FrameBound::Following(start), FrameBound::Following(end)) => {
            resolve_frame_bound_offset(&FrameBound::Following(start.clone())).unwrap_or(0)
                > resolve_frame_bound_offset(&FrameBound::Following(end.clone())).unwrap_or(0)
        }
        _ => false,
    }
}

fn rows_groups_initial_nominal_width(frame: &FrameSpec, partition_units: usize) -> usize {
    let end = frame.end.as_ref().unwrap_or(&FrameBound::CurrentRow);
    if matches!(
        frame.start,
        FrameBound::UnboundedPreceding | FrameBound::UnboundedFollowing
    ) || matches!(
        end,
        FrameBound::UnboundedPreceding | FrameBound::UnboundedFollowing
    ) {
        return partition_units;
    }

    let relative_position = |bound: &FrameBound| -> i128 {
        match bound {
            FrameBound::Preceding(expr) => {
                let offset =
                    resolve_frame_bound_offset(&FrameBound::Preceding(expr.clone())).unwrap_or(0);
                -i128::try_from(offset).unwrap_or(i128::MAX)
            }
            FrameBound::CurrentRow => 0,
            FrameBound::Following(expr) => {
                let offset =
                    resolve_frame_bound_offset(&FrameBound::Following(expr.clone())).unwrap_or(0);
                i128::try_from(offset).unwrap_or(i128::MAX)
            }
            FrameBound::UnboundedPreceding | FrameBound::UnboundedFollowing => 0,
        }
    };
    let width = relative_position(end) - relative_position(&frame.start) + 1;
    usize::try_from(width.max(0)).unwrap_or(usize::MAX)
}

/// Compute the ROWS frame start/end indices for a given row position in a partition.
/// Returns `(frame_start, frame_end_exclusive)` clamped to `[0, partition_size)`.
#[allow(clippy::cast_possible_truncation)]
fn rows_frame_bounds(pos: usize, partition_size: usize, frame: &FrameSpec) -> (usize, usize) {
    let start = match &frame.start {
        FrameBound::UnboundedPreceding => 0,
        FrameBound::CurrentRow => pos,
        FrameBound::Preceding(expr) => {
            let n = resolve_frame_bound_offset(&FrameBound::Preceding(expr.clone())).unwrap_or(0);
            pos.saturating_sub(n)
        }
        FrameBound::Following(expr) => {
            let n = resolve_frame_bound_offset(&FrameBound::Following(expr.clone())).unwrap_or(0);
            pos.saturating_add(n).min(partition_size)
        }
        FrameBound::UnboundedFollowing => partition_size,
    };
    let end = match frame.end.as_ref().unwrap_or(&FrameBound::CurrentRow) {
        FrameBound::UnboundedFollowing => partition_size,
        FrameBound::CurrentRow => pos.saturating_add(1).min(partition_size),
        FrameBound::Following(expr) => {
            let n = resolve_frame_bound_offset(&FrameBound::Following(expr.clone())).unwrap_or(0);
            pos.saturating_add(n).saturating_add(1).min(partition_size)
        }
        FrameBound::Preceding(expr) => {
            let n = resolve_frame_bound_offset(&FrameBound::Preceding(expr.clone())).unwrap_or(0);
            if n > pos { 0 } else { pos - n + 1 }
        }
        FrameBound::UnboundedPreceding => usize::from(partition_size > 0),
    };
    if end < start {
        (start, start)
    } else {
        (start, end)
    }
}

/// Check if a frame spec uses ROWS with explicit numeric bounds (not all unbounded).
fn is_rows_sliding_frame(frame: Option<&FrameSpec>) -> bool {
    let Some(f) = frame else { return false };
    if !matches!(f.frame_type, FrameType::Rows) {
        return false;
    }
    let start_explicit = matches!(
        f.start,
        FrameBound::Preceding(_) | FrameBound::Following(_) | FrameBound::CurrentRow
    );
    let end_explicit = f.end.as_ref().is_some_and(|e| {
        matches!(
            e,
            FrameBound::Preceding(_) | FrameBound::Following(_) | FrameBound::CurrentRow
        )
    });
    // At least one bound is not UNBOUNDED.
    start_explicit || end_explicit
}

fn build_peer_groups_collated_snapshot(
    partition_indices: &[usize],
    order_keys: &[Vec<SqliteValue>],
    order_collations: &[Option<String>],
    registry: &CollationRegistry,
) -> Vec<Vec<usize>> {
    if partition_indices.is_empty() {
        return Vec::new();
    }
    let mut groups: Vec<Vec<usize>> = vec![vec![partition_indices[0]]];
    for &ri in &partition_indices[1..] {
        let Some(prev_ri) = groups.last().and_then(|group| group.last()).copied() else {
            groups.push(vec![ri]);
            continue;
        };
        let same = order_by_keys_equal_collated_snapshot(
            prev_ri,
            ri,
            order_keys,
            order_collations,
            registry,
        );
        if same {
            if let Some(group) = groups.last_mut() {
                group.push(ri);
            } else {
                groups.push(vec![ri]);
            }
        } else {
            groups.push(vec![ri]);
        }
    }
    groups
}

fn order_by_keys_equal_collated_snapshot(
    left_ri: usize,
    right_ri: usize,
    order_keys: &[Vec<SqliteValue>],
    order_collations: &[Option<String>],
    registry: &CollationRegistry,
) -> bool {
    order_keys[left_ri]
        .iter()
        .zip(&order_keys[right_ri])
        .enumerate()
        .all(|(idx, (va, vb))| {
            let coll = order_collations.get(idx).and_then(|c| c.as_deref());
            cmp_sqlite_values_collated_snapshot(va, vb, coll, registry) == std::cmp::Ordering::Equal
        })
}

fn peer_rows_for_current_row(peer_groups: &[Vec<usize>], current_ri: usize) -> Vec<usize> {
    peer_groups
        .iter()
        .find(|group| group.contains(&current_ri))
        .cloned()
        .unwrap_or_else(|| vec![current_ri])
}

#[allow(clippy::too_many_arguments)]
fn window_frame_rows_for_current(
    pos: usize,
    partition_indices: &[usize],
    order_by: &[OrderingTerm],
    order_keys: &[Vec<SqliteValue>],
    order_collations: &[Option<String>],
    registry: &CollationRegistry,
    frame: &FrameSpec,
    peer_groups: &[Vec<usize>],
) -> Vec<usize> {
    match frame.frame_type {
        FrameType::Rows => {
            let (frame_start, frame_end) = rows_frame_bounds(pos, partition_indices.len(), frame);
            partition_indices[frame_start..frame_end].to_vec()
        }
        FrameType::Groups => {
            let current_ri = partition_indices[pos];
            let group_pos = peer_groups
                .iter()
                .position(|group| group.contains(&current_ri))
                .unwrap_or(0);
            let (group_start, group_end) = groups_frame_bounds(group_pos, peer_groups.len(), frame);
            peer_groups[group_start..group_end]
                .iter()
                .flatten()
                .copied()
                .collect()
        }
        FrameType::Range => {
            if order_by.is_empty() {
                partition_indices.to_vec()
            } else if !range_frame_has_value_offset(frame) {
                let current_ri = partition_indices[pos];
                let group_pos = peer_groups
                    .iter()
                    .position(|group| group.contains(&current_ri))
                    .unwrap_or(0);
                let (group_start, group_end) =
                    groups_frame_bounds(group_pos, peer_groups.len(), frame);
                peer_groups[group_start..group_end]
                    .iter()
                    .flatten()
                    .copied()
                    .collect()
            } else {
                let (frame_start, frame_end) = range_value_frame_bounds(
                    pos,
                    partition_indices,
                    order_by,
                    order_keys,
                    order_collations,
                    registry,
                    frame,
                );
                partition_indices[frame_start..frame_end].to_vec()
            }
        }
    }
}

fn apply_frame_exclusion(
    frame_rows: Vec<usize>,
    current_ri: usize,
    peer_rows: &[usize],
    exclude: Option<FrameExclude>,
) -> Vec<usize> {
    match exclude.unwrap_or(FrameExclude::NoOthers) {
        FrameExclude::NoOthers => frame_rows,
        FrameExclude::CurrentRow => frame_rows
            .into_iter()
            .filter(|&ri| ri != current_ri)
            .collect(),
        FrameExclude::Group => {
            let peer_set: HashSet<usize> = peer_rows.iter().copied().collect();
            frame_rows
                .into_iter()
                .filter(|ri| !peer_set.contains(ri))
                .collect()
        }
        FrameExclude::Ties => {
            let peer_set: HashSet<usize> = peer_rows.iter().copied().collect();
            frame_rows
                .into_iter()
                .filter(|&ri| ri == current_ri || !peer_set.contains(&ri))
                .collect()
        }
    }
}

fn window_frame_type_label(frame: Option<&FrameSpec>, has_order: bool) -> &'static str {
    match frame {
        Some(frame) => match frame.frame_type {
            FrameType::Rows => "rows",
            FrameType::Range => "range",
            FrameType::Groups => "groups",
        },
        None if has_order => "range_default",
        None => "partition",
    }
}

fn default_window_frame(has_order: bool) -> FrameSpec {
    FrameSpec {
        frame_type: FrameType::Range,
        start: FrameBound::UnboundedPreceding,
        end: Some(if has_order {
            FrameBound::CurrentRow
        } else {
            FrameBound::UnboundedFollowing
        }),
        exclude: None,
    }
}

const INVALID_NTH_VALUE_ARGUMENT: &str = "second argument to nth_value must be a positive integer";

fn nth_value_integral_f64_to_i64(value: f64) -> Option<i64> {
    const I64_MIN_AS_F64: f64 = -9_223_372_036_854_775_808.0;
    const I64_MAX_EXCLUSIVE_AS_F64: f64 = 9_223_372_036_854_775_808.0;

    if !value.is_finite()
        || value.fract() != 0.0
        || !(I64_MIN_AS_F64..I64_MAX_EXCLUSIVE_AS_F64).contains(&value)
    {
        return None;
    }
    Some(value as i64)
}

fn nth_value_parse_integral_text(text: &str) -> Option<i64> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return None;
    }
    trimmed
        .parse()
        .ok()
        .or_else(|| trimmed.parse().ok().and_then(nth_value_integral_f64_to_i64))
}

fn nth_value_positive_integer_arg(value: Option<&SqliteValue>) -> Result<i64> {
    let Some(value) = value else {
        return Err(FrankenError::function_error(INVALID_NTH_VALUE_ARGUMENT));
    };
    let n = match value {
        SqliteValue::Integer(n) => Some(*n),
        SqliteValue::Float(n) => nth_value_integral_f64_to_i64(*n),
        SqliteValue::Text(text) => nth_value_parse_integral_text(text),
        SqliteValue::Null | SqliteValue::Blob(_) => None,
    };
    match n {
        Some(n) if n > 0 => Ok(n),
        _ => Err(FrankenError::function_error(INVALID_NTH_VALUE_ARGUMENT)),
    }
}

fn nth_value_target_index(current_args: &[SqliteValue]) -> Result<usize> {
    let n = nth_value_positive_integer_arg(current_args.get(1))?;
    usize::try_from(n - 1).map_err(|_| FrankenError::function_error(INVALID_NTH_VALUE_ARGUMENT))
}

fn nth_value_from_frame_args(
    current_args: &[SqliteValue],
    frame_arg_rows: &[Vec<SqliteValue>],
) -> Result<SqliteValue> {
    let target_index = nth_value_target_index(current_args)?;
    Ok(frame_arg_rows
        .get(target_index)
        .and_then(|args| args.first())
        .cloned()
        .unwrap_or(SqliteValue::Null))
}

/// Compute GROUPS frame bounds (start group index, end group index exclusive).
fn groups_frame_bounds(group_pos: usize, num_groups: usize, frame: &FrameSpec) -> (usize, usize) {
    let start = match &frame.start {
        FrameBound::UnboundedPreceding => 0,
        FrameBound::CurrentRow => group_pos,
        FrameBound::Preceding(expr) => {
            let n = resolve_frame_bound_offset(&FrameBound::Preceding(expr.clone())).unwrap_or(0);
            group_pos.saturating_sub(n)
        }
        FrameBound::Following(expr) => {
            let n = resolve_frame_bound_offset(&FrameBound::Following(expr.clone())).unwrap_or(0);
            group_pos.saturating_add(n).min(num_groups)
        }
        FrameBound::UnboundedFollowing => num_groups,
    };
    let end = match frame.end.as_ref().unwrap_or(&FrameBound::CurrentRow) {
        FrameBound::UnboundedFollowing => num_groups,
        FrameBound::CurrentRow => group_pos.saturating_add(1).min(num_groups),
        FrameBound::Following(expr) => {
            let n = resolve_frame_bound_offset(&FrameBound::Following(expr.clone())).unwrap_or(0);
            group_pos
                .saturating_add(n)
                .saturating_add(1)
                .min(num_groups)
        }
        FrameBound::Preceding(expr) => {
            let n = resolve_frame_bound_offset(&FrameBound::Preceding(expr.clone())).unwrap_or(0);
            if n > group_pos { 0 } else { group_pos - n + 1 }
        }
        FrameBound::UnboundedPreceding => usize::from(num_groups > 0),
    };
    if end < start {
        (start, start)
    } else {
        (start, end)
    }
}

#[derive(Clone, Copy)]
enum RangeBoundaryComparison {
    GreaterOrEqual,
    Greater,
    LessOrEqual,
    Less,
}

impl RangeBoundaryComparison {
    const fn reversed(self) -> Self {
        match self {
            Self::GreaterOrEqual => Self::LessOrEqual,
            Self::Greater => Self::Less,
            Self::LessOrEqual => Self::GreaterOrEqual,
            Self::Less => Self::Greater,
        }
    }

    fn matches(self, ordering: std::cmp::Ordering) -> bool {
        match self {
            Self::GreaterOrEqual => ordering != std::cmp::Ordering::Less,
            Self::Greater => ordering == std::cmp::Ordering::Greater,
            Self::LessOrEqual => ordering != std::cmp::Ordering::Greater,
            Self::Less => ordering == std::cmp::Ordering::Less,
        }
    }
}

fn sqlite_range_bound_offset(bound: &FrameBound) -> SqliteValue {
    let expr = match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => expr.as_ref(),
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => return SqliteValue::Integer(0),
    };
    match expr {
        Expr::Literal(Literal::Integer(value), _) => SqliteValue::Integer(*value),
        Expr::Literal(Literal::Float(value), _) => SqliteValue::Float(*value),
        _ => SqliteValue::Integer(0),
    }
}

/// Apply SQLite VDBE numeric arithmetic for a RANGE boundary test.
///
/// Text and blob ORDER values are left unchanged, while NULL remains NULL.
/// Integer arithmetic stays exact until overflow; any REAL operand promotes
/// the operation to binary64 exactly as OP_Add/OP_Subtract do.
fn sqlite_range_offset_order_value(
    value: &SqliteValue,
    offset: &SqliteValue,
    subtract: bool,
) -> SqliteValue {
    match (value, offset) {
        (SqliteValue::Integer(value), SqliteValue::Integer(offset)) => {
            let exact = if subtract {
                value.checked_sub(*offset)
            } else {
                value.checked_add(*offset)
            };
            exact.map_or_else(
                || {
                    #[allow(clippy::cast_precision_loss)]
                    let promoted = if subtract {
                        *value as f64 - *offset as f64
                    } else {
                        *value as f64 + *offset as f64
                    };
                    SqliteValue::Float(promoted)
                },
                SqliteValue::Integer,
            )
        }
        (SqliteValue::Integer(value), SqliteValue::Float(offset)) => {
            #[allow(clippy::cast_precision_loss)]
            let value = *value as f64;
            SqliteValue::Float(if subtract {
                value - offset
            } else {
                value + offset
            })
        }
        (SqliteValue::Float(value), SqliteValue::Integer(offset)) => {
            #[allow(clippy::cast_precision_loss)]
            let offset = *offset as f64;
            SqliteValue::Float(if subtract {
                value - offset
            } else {
                value + offset
            })
        }
        (SqliteValue::Float(value), SqliteValue::Float(offset)) => {
            SqliteValue::Float(if subtract {
                value - offset
            } else {
                value + offset
            })
        }
        (SqliteValue::Null, _) => SqliteValue::Null,
        (SqliteValue::Text(_) | SqliteValue::Blob(_), _) => value.clone(),
        (_, SqliteValue::Null | SqliteValue::Text(_) | SqliteValue::Blob(_)) => value.clone(),
    }
}

/// Mirror SQLite's `windowCodeRangeTest()` rather than algebraically moving
/// the offset to the other side of the comparison.
///
/// Those forms are not equivalent in binary floating point. SQLite also
/// performs one pre-arithmetic comparison for `lhs + offset >= rhs` (or the
/// descending `lhs - offset <= rhs`) so rounding can never move a PRECEDING
/// start past the current row or a FOLLOWING end before it.
#[allow(clippy::too_many_arguments)]
fn sqlite_range_boundary_test(
    lhs: &SqliteValue,
    bound: &FrameBound,
    rhs: &SqliteValue,
    comparison: RangeBoundaryComparison,
    order_desc: bool,
    big_null: bool,
    collation: Option<&str>,
    registry: &CollationRegistry,
) -> bool {
    let comparison = if order_desc {
        comparison.reversed()
    } else {
        comparison
    };
    let subtract = order_desc;

    if big_null && (lhs.is_null() || rhs.is_null()) {
        let ordering = match (lhs.is_null(), rhs.is_null()) {
            (true, true) => std::cmp::Ordering::Equal,
            (true, false) => std::cmp::Ordering::Greater,
            (false, true) => std::cmp::Ordering::Less,
            (false, false) => unreachable!("BIGNULL branch requires a NULL operand"),
        };
        return comparison.matches(ordering);
    }

    let compare = |left: &SqliteValue, right: &SqliteValue| {
        comparison.matches(cmp_sqlite_values_collated_snapshot(
            left, right, collation, registry,
        ))
    };
    if matches!(
        (comparison, subtract),
        (RangeBoundaryComparison::GreaterOrEqual, false)
            | (RangeBoundaryComparison::LessOrEqual, true)
    ) && matches!(lhs, SqliteValue::Integer(_) | SqliteValue::Float(_))
        && !matches!(rhs, SqliteValue::Null)
        && comparison.matches(cmp_sqlite_values(lhs, rhs))
    {
        return true;
    }

    let offset = sqlite_range_bound_offset(bound);
    let adjusted_lhs = sqlite_range_offset_order_value(lhs, &offset, subtract);
    compare(&adjusted_lhs, rhs)
}

fn range_frame_has_value_offset(frame: &FrameSpec) -> bool {
    matches!(
        frame.start,
        FrameBound::Preceding(_) | FrameBound::Following(_)
    ) || frame
        .end
        .as_ref()
        .is_some_and(|end| matches!(end, FrameBound::Preceding(_) | FrameBound::Following(_)))
}

fn window_range_values_are_peers(
    current: &SqliteValue,
    candidate: &SqliteValue,
    collation: Option<&str>,
    registry: &CollationRegistry,
) -> bool {
    cmp_sqlite_values_collated_snapshot(current, candidate, collation, registry)
        == std::cmp::Ordering::Equal
}

/// Compute RANGE frame bounds based on ORDER BY values.
/// Returns `(start_row_idx, end_row_idx_exclusive)` within the partition.
#[allow(clippy::too_many_arguments)]
fn range_value_frame_raw_bounds(
    pos: usize,
    partition_indices: &[usize],
    order_by: &[OrderingTerm],
    order_keys: &[Vec<SqliteValue>],
    order_collations: &[Option<String>],
    registry: &CollationRegistry,
    frame: &FrameSpec,
) -> (usize, usize) {
    let Some(order_term) = order_by.first() else {
        return (0, partition_indices.len());
    };
    let order_desc = order_term.direction == Some(SortDirection::Desc);
    let big_null = matches!(
        (order_desc, order_term.nulls),
        (false, Some(NullsOrder::Last)) | (true, Some(NullsOrder::First))
    );

    let order_values: Vec<SqliteValue> = partition_indices
        .iter()
        .map(|&ri| order_keys[ri].first().cloned().unwrap_or(SqliteValue::Null))
        .collect();
    let current_value = order_values.get(pos).cloned().unwrap_or(SqliteValue::Null);
    let order_collation = order_collations
        .first()
        .and_then(|collation| collation.as_deref());
    let first_peer = order_values
        .iter()
        .position(|value| {
            window_range_values_are_peers(&current_value, value, order_collation, registry)
        })
        .unwrap_or(pos);
    let last_peer_exclusive = order_values
        .iter()
        .rposition(|value| {
            window_range_values_are_peers(&current_value, value, order_collation, registry)
        })
        .map_or(pos + 1, |idx| idx + 1);

    let boundary_test = |lhs: &SqliteValue, bound: &FrameBound, rhs: &SqliteValue, comparison| {
        sqlite_range_boundary_test(
            lhs,
            bound,
            rhs,
            comparison,
            order_desc,
            big_null,
            order_collation,
            registry,
        )
    };

    let start = match &frame.start {
        FrameBound::UnboundedPreceding => 0,
        FrameBound::CurrentRow => first_peer,
        FrameBound::Preceding(_) => order_values
            .iter()
            .position(|candidate| {
                boundary_test(
                    candidate,
                    &frame.start,
                    &current_value,
                    RangeBoundaryComparison::GreaterOrEqual,
                )
            })
            .unwrap_or(first_peer),
        FrameBound::Following(_) => order_values
            .iter()
            .position(|candidate| {
                boundary_test(
                    &current_value,
                    &frame.start,
                    candidate,
                    RangeBoundaryComparison::LessOrEqual,
                )
            })
            .unwrap_or(order_values.len()),
        FrameBound::UnboundedFollowing => order_values.len(),
    };

    let end_bound = frame.end.as_ref().unwrap_or(&FrameBound::CurrentRow);
    let end = match end_bound {
        FrameBound::UnboundedFollowing => order_values.len(),
        FrameBound::CurrentRow => last_peer_exclusive,
        FrameBound::Preceding(_) => order_values
            .iter()
            .position(|candidate| {
                boundary_test(
                    candidate,
                    end_bound,
                    &current_value,
                    RangeBoundaryComparison::Greater,
                )
            })
            .unwrap_or(order_values.len()),
        FrameBound::Following(_) => order_values
            .iter()
            .position(|candidate| {
                !boundary_test(
                    &current_value,
                    end_bound,
                    candidate,
                    RangeBoundaryComparison::GreaterOrEqual,
                )
            })
            .unwrap_or(order_values.len()),
        FrameBound::UnboundedPreceding => 0,
    };
    let end = if matches!(frame.start, FrameBound::Preceding(_))
        && matches!(end_bound, FrameBound::Preceding(_))
    {
        // SQLite keeps same-direction PRECEDING cursors ordered while the
        // current peer is being materialized. In particular, REAL rounding
        // must not let the ending cursor step into a future peer even when
        // `candidate + offset > current` remains false there.
        end.min(last_peer_exclusive)
    } else {
        end
    };

    (start, end)
}

#[allow(clippy::too_many_arguments)]
fn range_value_frame_bounds(
    pos: usize,
    partition_indices: &[usize],
    order_by: &[OrderingTerm],
    order_keys: &[Vec<SqliteValue>],
    order_collations: &[Option<String>],
    registry: &CollationRegistry,
    frame: &FrameSpec,
) -> (usize, usize) {
    let (start, end) = range_value_frame_raw_bounds(
        pos,
        partition_indices,
        order_by,
        order_keys,
        order_collations,
        registry,
        frame,
    );
    if end < start {
        (start, start)
    } else {
        (start, end)
    }
}

/// Build the SQL-visible argument list for a window function `step()` call.
///
/// `COUNT()` and `COUNT(*)` both pass no per-row values. Peer comparisons use
/// the window `ORDER BY` expressions separately, not as hidden function args.
fn build_window_args(
    func_args: &[Expr],
    args_are_star: bool,
    _order_by: &[OrderingTerm],
    row: &[SqliteValue],
    col_map: &[(String, String, bool)],
) -> Result<Vec<SqliteValue>> {
    // `COUNT()` is valid SQLite syntax and behaves like `COUNT(*)`;
    // zero SQL-visible arguments must not become hidden ORDER BY arguments.
    if args_are_star || func_args.is_empty() {
        Ok(Vec::new())
    } else {
        func_args
            .iter()
            .map(|expr| eval_join_expr(expr, row, col_map))
            .collect()
    }
}

fn evaluate_application_window_finalized_frame(
    function: &ErasedWindowFunction,
    args_by_row: &[Vec<SqliteValue>],
    target_rows: &[usize],
) -> Result<SqliteValue> {
    let mut state = function.initial_state();
    let step_result = (|| -> Result<()> {
        for &row_index in target_rows {
            function.step(&mut state, &args_by_row[row_index])?;
        }
        Ok(())
    })();
    let finalize_result = function.finalize(state);
    match step_result {
        Ok(()) => finalize_result,
        Err(error) => {
            let _ = finalize_result;
            Err(error)
        }
    }
}

fn evaluate_single_row_window_lifecycle(
    function: &ErasedWindowFunction,
    should_step: bool,
    args: &[SqliteValue],
) -> Result<SqliteValue> {
    let mut state = function.initial_state();
    let evaluation = (|| -> Result<SqliteValue> {
        if should_step {
            function.step(&mut state, args)?;
        }
        function.value(&state)
    })();
    let finalize_result = function.finalize(state);
    match evaluation {
        Ok(value) => {
            finalize_result?;
            Ok(value)
        }
        Err(error) => {
            let _ = finalize_result;
            Err(error)
        }
    }
}

/// Evaluate one application-defined window function over one non-empty
/// partition.
///
/// Application callbacks observe SQLite's window lifecycle.  Without an
/// explicit EXCLUDE clause, one accumulator is created per partition, rows
/// enter through `step`, rows leaving a moving frame exit through `inverse`,
/// peer groups obtain values through `value`, and `finalize` consumes the
/// accumulator exactly once.  Explicit EXCLUDE clauses instead use a fresh
/// `step`/`finalize` aggregate lifecycle per output frame, including empty
/// frames, matching
/// SQLite.  Arguments and FILTER predicates are materialized by the caller so
/// frame evaluation never re-evaluates a user expression.
#[allow(clippy::too_many_arguments)]
fn evaluate_application_window_partition(
    function: &ErasedWindowFunction,
    partition_indices: &[usize],
    args_by_row: &[Vec<SqliteValue>],
    filter_matches: &[bool],
    order_by: &[OrderingTerm],
    order_keys: &[Vec<SqliteValue>],
    order_collations: &[Option<String>],
    collation_registry: &CollationRegistry,
    explicit_frame: Option<&FrameSpec>,
) -> Result<Vec<SqliteValue>> {
    debug_assert!(!partition_indices.is_empty());
    let default_frame;
    let frame = if let Some(frame) = explicit_frame {
        frame
    } else {
        default_frame = default_window_frame(!order_by.is_empty());
        &default_frame
    };
    // SQLite evaluates any syntactically explicit EXCLUDE frame by building a
    // fresh aggregate state for each output frame and consuming it through
    // xFinal.  It does not call xValue/xInverse on this route; even an empty
    // excluded frame finalizes a fresh empty state.  This also applies to
    // explicit EXCLUDE NO OTHERS (omitting EXCLUDE uses the normal sliding
    // lifecycle below).
    if frame.exclude.is_some() {
        let peer_groups = build_peer_groups_collated_snapshot(
            partition_indices,
            order_keys,
            order_collations,
            collation_registry,
        );

        let mut values = Vec::with_capacity(partition_indices.len());
        for (position, &current_row) in partition_indices.iter().enumerate() {
            let frame_rows = window_frame_rows_for_current(
                position,
                partition_indices,
                order_by,
                order_keys,
                order_collations,
                collation_registry,
                frame,
                &peer_groups,
            );
            let peer_rows = peer_rows_for_current_row(&peer_groups, current_row);
            let target_rows =
                apply_frame_exclusion(frame_rows, current_row, &peer_rows, frame.exclude)
                    .into_iter()
                    .filter(|&row_index| filter_matches[row_index])
                    .collect::<Vec<_>>();
            values.push(evaluate_application_window_finalized_frame(
                function,
                args_by_row,
                &target_rows,
            )?);
        }
        return Ok(values);
    }

    let mut state = function.initial_state();

    let evaluation = (|| -> Result<Vec<SqliteValue>> {
        let mut values = Vec::with_capacity(partition_indices.len());
        let row_is_included = |row_index: usize| filter_matches[row_index];

        // ROWS bounds move monotonically as the current row advances.  Keep
        // the same step/inverse cursors as SQLite, including its observable
        // warm-up callbacks for rows before a FOLLOWING frame first becomes
        // visible.  Raw frame positions advance even when FILTER suppresses
        // the corresponding application callback.
        if matches!(frame.frame_type, FrameType::Rows) {
            let partition_size = partition_indices.len();
            if rows_groups_offset_interval_is_statically_reversed(frame) {
                for _ in partition_indices {
                    values.push(function.value(&state)?);
                }
                return Ok(values);
            }
            let (initial_start, initial_end) = rows_frame_bounds(0, partition_size, frame);
            let initial_width = rows_groups_initial_nominal_width(frame, partition_size);
            let mut entered = 0usize;
            let mut removed = 0usize;
            while entered < initial_end {
                if removed < initial_start
                    && removed < entered
                    && entered - removed >= initial_width
                {
                    let row_index = partition_indices[removed];
                    if row_is_included(row_index) {
                        function.inverse(&mut state, &args_by_row[row_index])?;
                    }
                    removed += 1;
                    continue;
                }
                let row_index = partition_indices[entered];
                if row_is_included(row_index) {
                    function.step(&mut state, &args_by_row[row_index])?;
                }
                entered += 1;
            }
            while removed < initial_start {
                let row_index = partition_indices[removed];
                if row_is_included(row_index) {
                    function.inverse(&mut state, &args_by_row[row_index])?;
                }
                removed += 1;
            }
            values.push(function.value(&state)?);

            for position in 1..partition_size {
                let (next_start, next_end) = rows_frame_bounds(position, partition_size, frame);
                while removed < next_start && removed < entered {
                    let row_index = partition_indices[removed];
                    if row_is_included(row_index) {
                        function.inverse(&mut state, &args_by_row[row_index])?;
                    }
                    removed += 1;
                }
                while entered < next_end {
                    let row_index = partition_indices[entered];
                    if row_is_included(row_index) {
                        function.step(&mut state, &args_by_row[row_index])?;
                    }
                    entered += 1;
                }
                while removed < next_start {
                    let row_index = partition_indices[removed];
                    if row_is_included(row_index) {
                        function.inverse(&mut state, &args_by_row[row_index])?;
                    }
                    removed += 1;
                }
                debug_assert_eq!(entered, next_end);
                debug_assert_eq!(removed, next_start);
                values.push(function.value(&state)?);
            }
            return Ok(values);
        }

        let end = frame.end.as_ref().unwrap_or(&FrameBound::CurrentRow);

        let peer_groups = build_peer_groups_collated_snapshot(
            partition_indices,
            order_keys,
            order_collations,
            collation_registry,
        );

        // SQLite recognizes an offset interval whose end is statically before
        // its start as empty without advancing either GROUPS cursor.  Unlike
        // ordinary GROUPS frames, xValue is still called once per output row,
        // including every row in a peer group.
        if matches!(frame.frame_type, FrameType::Groups)
            && rows_groups_offset_interval_is_statically_reversed(frame)
        {
            for _ in partition_indices {
                values.push(function.value(&state)?);
            }
            return Ok(values);
        }

        // RANGE and GROUPS produce one application value per peer group, even
        // when the frame covers the whole partition.  Reuse that result for
        // every peer; an unordered partition is one peer group.  (The ROWS
        // case returned through the interval path above and remains per-row.)
        if matches!(frame.start, FrameBound::UnboundedPreceding)
            && matches!(end, FrameBound::UnboundedFollowing)
        {
            for &row_index in partition_indices {
                if row_is_included(row_index) {
                    function.step(&mut state, &args_by_row[row_index])?;
                }
            }
            for peer_group in &peer_groups {
                let value = function.value(&state)?;
                for _ in peer_group {
                    values.push(value.clone());
                }
            }
            return Ok(values);
        }

        // The default ordered frame (and its explicit RANGE/GROUPS form) is
        // a prefix that advances a peer group at a time.  Preserve peer-equal
        // results without replaying the prefix for every row.
        if matches!(frame.frame_type, FrameType::Range | FrameType::Groups)
            && matches!(frame.start, FrameBound::UnboundedPreceding)
            && matches!(end, FrameBound::CurrentRow)
        {
            for peer_group in &peer_groups {
                for &row_index in peer_group {
                    if row_is_included(row_index) {
                        function.step(&mut state, &args_by_row[row_index])?;
                    }
                }
                let value = function.value(&state)?;
                for _ in peer_group {
                    values.push(value.clone());
                }
            }
            return Ok(values);
        }

        // Numeric RANGE offsets use separate monotonic end/start cursors in
        // SQLite.  FOLLOWING starts and PRECEDING ends advance the ending
        // cursor before the starting cursor; the other valid offset shapes
        // remove rows first.  This order is observable to application
        // callbacks and determines which callback error wins.
        if matches!(frame.frame_type, FrameType::Range) && range_frame_has_value_offset(frame) {
            let mut entered = 0usize;
            let mut removed = 0usize;
            let mut previous_current_row = None;
            let mut previous_value: Option<SqliteValue> = None;
            let end = frame.end.as_ref().unwrap_or(&FrameBound::CurrentRow);
            let enter_before_remove = matches!(frame.start, FrameBound::Following(_))
                || matches!(end, FrameBound::Preceding(_));
            for (position, &current_row) in partition_indices.iter().enumerate() {
                let peer_rows = peer_rows_for_current_row(&peer_groups, current_row);
                if previous_current_row.is_some_and(|row| peer_rows.contains(&row)) {
                    let value = previous_value.clone().ok_or_else(|| {
                        FrankenError::Internal(
                            "application window RANGE peer value was not materialized".to_owned(),
                        )
                    })?;
                    values.push(value);
                    previous_current_row = Some(current_row);
                    continue;
                }

                let (raw_start, next_end) = range_value_frame_raw_bounds(
                    position,
                    partition_indices,
                    order_by,
                    order_keys,
                    order_collations,
                    collation_registry,
                    frame,
                );
                // When same-direction offsets are reversed, SQLite advances
                // both cursors only through the nearer raw ending boundary,
                // leaving an empty state without probing as far as the
                // semantic start.
                let next_start = raw_start.min(next_end);
                if enter_before_remove {
                    while entered < next_end {
                        let row_index = partition_indices[entered];
                        if row_is_included(row_index) {
                            function.step(&mut state, &args_by_row[row_index])?;
                        }
                        entered += 1;
                    }
                    while removed < next_start {
                        let row_index = partition_indices[removed];
                        if row_is_included(row_index) {
                            function.inverse(&mut state, &args_by_row[row_index])?;
                        }
                        removed += 1;
                    }
                } else {
                    while removed < next_start {
                        let row_index = partition_indices[removed];
                        if row_is_included(row_index) {
                            function.inverse(&mut state, &args_by_row[row_index])?;
                        }
                        removed += 1;
                    }
                    while entered < next_end {
                        let row_index = partition_indices[entered];
                        if row_is_included(row_index) {
                            function.step(&mut state, &args_by_row[row_index])?;
                        }
                        entered += 1;
                    }
                }
                let value = function.value(&state)?;
                previous_current_row = Some(current_row);
                previous_value = Some(value.clone());
                values.push(value);
            }
            return Ok(values);
        }

        // General RANGE/GROUPS transitions can remove rows from the front or
        // reintroduce rows before the retained suffix.  The WindowFunction API
        // only appends through step, so retain the largest suffix of the active
        // frame that is a prefix of the next frame, then drain/rebuild the
        // remainder in frame order when necessary.
        let mut active_rows: Vec<usize> = Vec::new();
        let mut previous_current_row = None;
        let mut previous_value = None;
        for (position, &current_row) in partition_indices.iter().enumerate() {
            let frame_rows = window_frame_rows_for_current(
                position,
                partition_indices,
                order_by,
                order_keys,
                order_collations,
                collation_registry,
                frame,
                &peer_groups,
            );
            let peer_rows = peer_rows_for_current_row(&peer_groups, current_row);
            if matches!(frame.frame_type, FrameType::Range | FrameType::Groups)
                && previous_current_row.is_some_and(|row| peer_rows.contains(&row))
            {
                let value = previous_value.clone().ok_or_else(|| {
                    FrankenError::Internal(
                        "application window peer value was not materialized".to_owned(),
                    )
                })?;
                values.push(value);
                previous_current_row = Some(current_row);
                continue;
            }
            let target_rows =
                apply_frame_exclusion(frame_rows, current_row, &peer_rows, frame.exclude)
                    .into_iter()
                    .filter(|&row_index| row_is_included(row_index))
                    .collect::<Vec<_>>();

            if position == 0 {
                match frame.frame_type {
                    FrameType::Groups | FrameType::Range => {
                        // GROUPS, and RANGE frames expressed in peer-group
                        // bounds, advance SQLite's warm-up cursors one peer
                        // group at a time.  This intentionally invokes
                        // step/inverse for groups preceding a FOLLOWING start.
                        let (initial_start, initial_end) =
                            groups_frame_bounds(0, peer_groups.len(), frame);
                        let initial_width =
                            rows_groups_initial_nominal_width(frame, peer_groups.len());
                        let mut entered_group = 0usize;
                        let mut removed_group = 0usize;
                        while entered_group < initial_end {
                            if removed_group < initial_start
                                && removed_group < entered_group
                                && entered_group - removed_group >= initial_width
                            {
                                for &row_index in &peer_groups[removed_group] {
                                    if row_is_included(row_index) {
                                        function.inverse(&mut state, &args_by_row[row_index])?;
                                    }
                                }
                                removed_group += 1;
                                continue;
                            }
                            for &row_index in &peer_groups[entered_group] {
                                if row_is_included(row_index) {
                                    function.step(&mut state, &args_by_row[row_index])?;
                                }
                            }
                            entered_group += 1;
                        }
                        while removed_group < initial_start {
                            for &row_index in &peer_groups[removed_group] {
                                if row_is_included(row_index) {
                                    function.inverse(&mut state, &args_by_row[row_index])?;
                                }
                            }
                            removed_group += 1;
                        }
                    }
                    FrameType::Rows => unreachable!("ROWS returned through its cursor path"),
                }
                active_rows = target_rows;
                let value = function.value(&state)?;
                previous_current_row = Some(current_row);
                previous_value = Some(value.clone());
                values.push(value);
                continue;
            }

            // Raw row indices are unique and frame order is stable, so only
            // the suffix beginning at the target's first row can overlap its
            // prefix.  Locate and compare that one candidate instead of
            // trying every length (which made exclusion workloads cubic).
            let overlap = target_rows.first().map_or(0, |target_first| {
                active_rows
                    .iter()
                    .position(|active_row| active_row == target_first)
                    .map_or(0, |active_position| {
                        let suffix = &active_rows[active_position..];
                        if suffix.len() <= target_rows.len()
                            && suffix == &target_rows[..suffix.len()]
                        {
                            suffix.len()
                        } else {
                            0
                        }
                    })
            });
            let outgoing_count = active_rows.len() - overlap;
            for &row_index in &active_rows[..outgoing_count] {
                function.inverse(&mut state, &args_by_row[row_index])?;
            }
            for &row_index in &target_rows[overlap..] {
                function.step(&mut state, &args_by_row[row_index])?;
            }
            active_rows = target_rows;
            let value = function.value(&state)?;
            previous_current_row = Some(current_row);
            previous_value = Some(value.clone());
            values.push(value);
        }
        Ok(values)
    })();

    // Finalization is part of the observable application lifecycle even when
    // a preceding callback failed.  Preserve the first execution error, but
    // propagate a lone finalize failure.
    let finalize_result = function.finalize(state);
    match evaluation {
        Ok(values) => {
            finalize_result?;
            Ok(values)
        }
        Err(error) => {
            let _ = finalize_result;
            Err(error)
        }
    }
}

fn find_window_function_checked(
    registry: &FunctionRegistry,
    name: &str,
    num_args: i32,
) -> Result<Arc<ErasedWindowFunction>> {
    match registry.window_accepts_arg_count(name, num_args) {
        Some(true) => registry.find_window(name, num_args).ok_or_else(|| {
            FrankenError::Internal(format!("no such window function: {name}/{num_args}"))
        }),
        Some(false) => Err(FrankenError::function_error(format!(
            "wrong number of arguments to function {}()",
            name.to_ascii_lowercase()
        ))),
        None => Err(FrankenError::Internal(format!(
            "no such window function: {name}/{num_args}"
        ))),
    }
}

/// Build a `SELECT *` scan from a GROUP BY SELECT (strips aggregates and GROUP BY).
struct GroupByProjectionScanPlan {
    select: SelectStatement,
    col_map: Vec<(String, String, bool)>,
    projected_indices: HashMap<String, usize>,
    source_indices: Vec<usize>,
}

#[allow(clippy::too_many_arguments)]
fn build_group_by_projection_scan_plan(
    select: &SelectStatement,
    table_schema: &TableSchema,
    effective_label: &str,
    group_by_exprs: &[Expr],
    result_descriptors: &[GroupByColumn],
    expanded_columns: &[ResultColumn],
    having_expr: Option<&Expr>,
    order_by: &[OrderingTerm],
    rowid_real_col: Option<&str>,
) -> Option<GroupByProjectionScanPlan> {
    if expanded_columns
        .iter()
        .any(|column| !matches!(column, ResultColumn::Expr { .. }))
    {
        return None;
    }

    let mut needed_columns = BTreeSet::new();
    for expr in group_by_exprs {
        collect_projectable_group_by_columns_from_expr(
            expr,
            table_schema,
            effective_label,
            rowid_real_col,
            &mut needed_columns,
        )?;
    }
    for descriptor in result_descriptors {
        collect_projectable_group_by_columns_from_descriptor(
            descriptor,
            table_schema,
            effective_label,
            rowid_real_col,
            &mut needed_columns,
        )?;
    }
    if let Some(expr) = having_expr {
        collect_projectable_group_by_columns_from_expr(
            expr,
            table_schema,
            effective_label,
            rowid_real_col,
            &mut needed_columns,
        )?;
    }
    for term in order_by {
        if resolve_order_term_idx(&term.expr, expanded_columns).is_none() {
            collect_projectable_group_by_columns_from_expr(
                &term.expr,
                table_schema,
                effective_label,
                rowid_real_col,
                &mut needed_columns,
            )?;
        }
    }

    if needed_columns.is_empty() || needed_columns.len() >= table_schema.columns.len() {
        return None;
    }

    let mut projected_columns = Vec::with_capacity(needed_columns.len());
    let mut projected_indices = HashMap::with_capacity(needed_columns.len());
    let mut col_map = Vec::with_capacity(needed_columns.len());
    let mut source_indices = Vec::with_capacity(needed_columns.len());
    for (source_index, column) in table_schema.columns.iter().enumerate() {
        let lookup = column.name.to_ascii_lowercase();
        if !needed_columns.contains(&lookup) {
            continue;
        }
        let projected_index = projected_columns.len();
        projected_indices.insert(lookup, projected_index);
        projected_columns.push(ResultColumn::Expr {
            expr: Expr::Column(
                ColumnRef::qualified(effective_label.to_owned(), column.name.clone()),
                Span::new(0, 0),
            ),
            alias: None,
        });
        col_map.push((effective_label.to_owned(), column.name.clone(), false));
        source_indices.push(source_index);
    }

    if projected_columns.is_empty() || projected_columns.len() >= table_schema.columns.len() {
        return None;
    }

    let new_core = match &select.body.select {
        SelectCore::Select {
            from, where_clause, ..
        } => SelectCore::Select {
            distinct: Distinctness::All,
            columns: projected_columns,
            from: from.clone(),
            where_clause: where_clause.clone(),
            group_by: vec![],
            having: None,
            windows: vec![],
        },
        other => other.clone(),
    };

    Some(GroupByProjectionScanPlan {
        select: SelectStatement {
            with: select.with.clone(),
            body: SelectBody {
                select: new_core,
                compounds: vec![],
            },
            order_by: vec![],
            limit: None,
        },
        col_map,
        projected_indices,
        source_indices,
    })
}

fn collect_projectable_group_by_columns_from_descriptor(
    descriptor: &GroupByColumn,
    table_schema: &TableSchema,
    effective_label: &str,
    rowid_real_col: Option<&str>,
    needed_columns: &mut BTreeSet<String>,
) -> Option<()> {
    match descriptor {
        GroupByColumn::Plain(expr) => collect_projectable_group_by_columns_from_expr(
            expr,
            table_schema,
            effective_label,
            rowid_real_col,
            needed_columns,
        ),
        GroupByColumn::Agg {
            application_args,
            arg_col,
            arg_expr,
            separator_expr,
            filter,
            order_by,
            ..
        } => {
            if let Some(FunctionArgs::List(expressions)) = application_args {
                for expression in expressions {
                    collect_projectable_group_by_columns_from_expr(
                        expression,
                        table_schema,
                        effective_label,
                        rowid_real_col,
                        needed_columns,
                    )?;
                }
            }
            if let Some(arg_col) = arg_col {
                let column = table_schema.columns.get(*arg_col)?;
                needed_columns.insert(column.name.to_ascii_lowercase());
            }
            if let Some(expr) = arg_expr {
                collect_projectable_group_by_columns_from_expr(
                    expr,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            if let Some(expr) = separator_expr {
                collect_projectable_group_by_columns_from_expr(
                    expr,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            if let Some(expr) = filter {
                collect_projectable_group_by_columns_from_expr(
                    expr,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            for term in order_by {
                collect_projectable_group_by_columns_from_expr(
                    &term.expr,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            Some(())
        }
    }
}

fn collect_projectable_group_by_columns_from_expr(
    expr: &Expr,
    table_schema: &TableSchema,
    effective_label: &str,
    rowid_real_col: Option<&str>,
    needed_columns: &mut BTreeSet<String>,
) -> Option<()> {
    match expr {
        Expr::Column(column_ref, _) => {
            if let Some(table_name) = column_ref.table.as_deref()
                && !table_name.eq_ignore_ascii_case(effective_label)
            {
                return None;
            }
            let column_name = if table_exposes_hidden_rowid_alias(table_schema, &column_ref.column)
            {
                rowid_real_col?
            } else {
                column_ref.column.as_ref()
            };
            let column_idx = table_schema.column_index(column_name)?;
            needed_columns.insert(table_schema.columns[column_idx].name.to_ascii_lowercase());
            Some(())
        }
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => Some(()),
        Expr::BinaryOp { left, right, .. } => {
            collect_projectable_group_by_columns_from_expr(
                left,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )?;
            collect_projectable_group_by_columns_from_expr(
                right,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => collect_projectable_group_by_columns_from_expr(
            expr,
            table_schema,
            effective_label,
            rowid_real_col,
            needed_columns,
        ),
        Expr::Between {
            expr, low, high, ..
        } => {
            collect_projectable_group_by_columns_from_expr(
                expr,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )?;
            collect_projectable_group_by_columns_from_expr(
                low,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )?;
            collect_projectable_group_by_columns_from_expr(
                high,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )
        }
        Expr::In { expr, set, .. } => {
            collect_projectable_group_by_columns_from_expr(
                expr,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )?;
            match set {
                InSet::List(values) => {
                    for value in values {
                        collect_projectable_group_by_columns_from_expr(
                            value,
                            table_schema,
                            effective_label,
                            rowid_real_col,
                            needed_columns,
                        )?;
                    }
                    Some(())
                }
                InSet::Subquery(_) | InSet::Table(_) => None,
            }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            collect_projectable_group_by_columns_from_expr(
                expr,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )?;
            collect_projectable_group_by_columns_from_expr(
                pattern,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )?;
            if let Some(escape) = escape {
                collect_projectable_group_by_columns_from_expr(
                    escape,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            Some(())
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                collect_projectable_group_by_columns_from_expr(
                    operand,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            for (when_expr, then_expr) in whens {
                collect_projectable_group_by_columns_from_expr(
                    when_expr,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
                collect_projectable_group_by_columns_from_expr(
                    then_expr,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            if let Some(else_expr) = else_expr {
                collect_projectable_group_by_columns_from_expr(
                    else_expr,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            Some(())
        }
        Expr::Exists { .. } | Expr::Subquery(_, _) => None,
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if over.is_some() {
                return None;
            }
            if let FunctionArgs::List(args) = args {
                for arg in args {
                    collect_projectable_group_by_columns_from_expr(
                        arg,
                        table_schema,
                        effective_label,
                        rowid_real_col,
                        needed_columns,
                    )?;
                }
            }
            for term in order_by {
                collect_projectable_group_by_columns_from_expr(
                    &term.expr,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            if let Some(filter) = filter {
                collect_projectable_group_by_columns_from_expr(
                    filter,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            Some(())
        }
        Expr::JsonAccess { expr, path, .. } => {
            collect_projectable_group_by_columns_from_expr(
                expr,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )?;
            collect_projectable_group_by_columns_from_expr(
                path,
                table_schema,
                effective_label,
                rowid_real_col,
                needed_columns,
            )
        }
        Expr::RowValue(values, _) => {
            for value in values {
                collect_projectable_group_by_columns_from_expr(
                    value,
                    table_schema,
                    effective_label,
                    rowid_real_col,
                    needed_columns,
                )?;
            }
            Some(())
        }
    }
}

fn remap_group_by_descriptors_for_projection(
    descriptors: &[GroupByColumn],
    table_schema: &TableSchema,
    projected_indices: &HashMap<String, usize>,
) -> Vec<GroupByColumn> {
    descriptors
        .iter()
        .map(|descriptor| match descriptor {
            GroupByColumn::Plain(expr) => GroupByColumn::Plain(expr.clone()),
            GroupByColumn::Agg {
                name,
                application_args,
                arg_col,
                arg_expr,
                distinct,
                separator,
                separator_expr,
                filter,
                collation,
                order_by,
            } => GroupByColumn::Agg {
                name: name.clone(),
                application_args: application_args.clone(),
                arg_col: arg_col.map(|idx| {
                    let column_name = table_schema
                        .columns
                        .get(idx)
                        .map(|column| column.name.to_ascii_lowercase())
                        .expect("GROUP BY projection remap should target an existing column");
                    *projected_indices
                        .get(&column_name)
                        .expect("GROUP BY projection plan should include aggregate input columns")
                }),
                arg_expr: arg_expr.clone(),
                distinct: *distinct,
                separator: separator.clone(),
                separator_expr: separator_expr.clone(),
                filter: filter.clone(),
                collation: collation.clone(),
                order_by: order_by.clone(),
            },
        })
        .collect()
}

fn build_raw_scan_select(select: &SelectStatement) -> SelectStatement {
    let new_core = match &select.body.select {
        SelectCore::Select {
            from, where_clause, ..
        } => SelectCore::Select {
            distinct: Distinctness::All,
            columns: vec![ResultColumn::Star],
            from: from.clone(),
            where_clause: where_clause.clone(),
            group_by: vec![],
            having: None,
            windows: vec![],
        },
        other @ SelectCore::Values(_) => other.clone(),
    };
    SelectStatement {
        with: select.with.clone(),
        body: SelectBody {
            select: new_core,
            compounds: vec![],
        },
        order_by: vec![],
        limit: None,
    }
}

/// Test whether a `SqliteValue` is truthy (non-zero, non-NULL).
/// C SQLite-compatible shift: negative shift reverses direction, large shift
/// produces 0 (or -1 for arithmetic right-shift of negative values).
/// Mirrors upstream VDBE shift opcode behavior.
fn sqlite_shift(val: i64, shift: i64, is_left: bool) -> i64 {
    let v = val;
    let mut s = shift;
    let mut left = is_left;
    if s < 0 {
        // Negative shift amount reverses direction.
        left = !left;
        s = if s > -64 { -s } else { 64 };
    }
    if s >= 64 {
        // Large shift: 0 for left or non-negative right; -1 for arithmetic
        // right-shift of a negative value (sign extension).
        return if v >= 0 || left { 0 } else { -1 };
    }
    #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
    if left {
        (v as u64).wrapping_shl(s as u32) as i64
    } else {
        v.wrapping_shr(s as u32) // arithmetic right shift (Rust >> on i64)
    }
}

/// C SQLite truthiness for `OP_If`/`OP_IfNot` (CASE WHEN, WHERE, HAVING):
/// uses `sqlite3VdbeRealValue() != 0.0`, so 0.1 and 0.5 are truthy.
pub(crate) fn is_sqlite_truthy(v: &SqliteValue) -> bool {
    match v {
        SqliteValue::Null => false,
        SqliteValue::Integer(n) => *n != 0,
        SqliteValue::Float(f) => *f != 0.0,
        SqliteValue::Text(_) | SqliteValue::Blob(_) => {
            let i = v.to_integer();
            if i != 0 {
                return true;
            }
            v.to_float() != 0.0
        }
    }
}

/// Evaluate a HAVING predicate against a group's computed result values.
///
/// `group_rows` and `col_map` allow computing aggregates that are not in the
/// SELECT list (e.g. `HAVING COUNT(*) > 1` when COUNT(*) is not a result column).
fn evaluate_having_predicate(
    expr: &Expr,
    values: &[SqliteValue],
    columns: &[ResultColumn],
    group_rows: &[Vec<SqliteValue>],
    col_map: &[(String, String, bool)],
) -> Result<bool> {
    Ok(is_sqlite_truthy(&evaluate_having_value(
        expr, values, columns, group_rows, col_map,
    )?))
}

/// Check if `op` IS/IS NOT with `rhs` TRUE/FALSE should use `IsTrue`.
/// Returns `(p3, p4)` for the `IsTrue` opcode.
fn is_true_false_params_core(op: BinaryOp, rhs: &Expr) -> Option<(i32, P4)> {
    let is_not = matches!(op, BinaryOp::IsNot);
    match rhs {
        Expr::Literal(Literal::True, _) => {
            if is_not {
                Some((0, P4::Int(1)))
            } else {
                Some((0, P4::None))
            }
        }
        Expr::Literal(Literal::False, _) => {
            if is_not {
                Some((1, P4::None))
            } else {
                Some((1, P4::Int(1)))
            }
        }
        _ => None,
    }
}

/// Evaluate a HAVING expression to a `SqliteValue`.
///
/// Resolves result aliases and columns from the already-computed values, and
/// computes aggregate expressions directly from `group_rows` when HAVING
/// references an aggregate that is not in the SELECT list.
#[allow(clippy::too_many_lines)]
fn evaluate_having_value(
    expr: &Expr,
    values: &[SqliteValue],
    columns: &[ResultColumn],
    group_rows: &[Vec<SqliteValue>],
    col_map: &[(String, String, bool)],
) -> Result<SqliteValue> {
    match expr {
        // Recompute the complete aggregate expression from the raw group rows.
        // Reusing a SELECT-list descriptor here is unsafe unless every argument,
        // FILTER, DISTINCT modifier, and in-aggregate ORDER BY term matches.
        // The shared evaluator already implements that full contract and also
        // resolves connection-local custom aggregates by exact/variadic arity.
        Expr::FunctionCall { name, args, .. }
            if is_current_aggregate_fn(name, args) && !is_scalar_max_min(name, args) =>
        {
            let group_row_refs = group_rows.iter().collect::<Vec<_>>();
            eval_group_agg_join_expr(expr, &group_row_refs, col_map)
        }

        // Column reference — find matching plain column in result set or raw data.
        Expr::Column(col_ref, _) => {
            let col_name = &col_ref.column;
            let table_prefix = col_ref.table.as_deref();
            // First check result column aliases.
            if table_prefix.is_none() {
                for (i, rc) in columns.iter().enumerate() {
                    if let ResultColumn::Expr {
                        alias: Some(alias), ..
                    } = rc
                        && alias.eq_ignore_ascii_case(col_name)
                    {
                        return Ok(values.get(i).cloned().unwrap_or(SqliteValue::Null));
                    }
                }
            }
            // Then check result column names.
            for (i, rc) in columns.iter().enumerate() {
                if let ResultColumn::Expr {
                    expr: Expr::Column(result_col_ref, _),
                    ..
                } = rc
                {
                    if !result_col_ref.column.eq_ignore_ascii_case(col_name) {
                        continue;
                    }
                    let qualifier_matches = table_prefix.is_none_or(|table| {
                        result_col_ref
                            .table
                            .as_deref()
                            .is_some_and(|result_table| result_table.eq_ignore_ascii_case(table))
                    });
                    if qualifier_matches {
                        return Ok(values.get(i).cloned().unwrap_or(SqliteValue::Null));
                    }
                } else if table_prefix.is_none()
                    && let ResultColumn::Expr { expr, .. } = rc
                    && let Some(name) = expr_col_name(expr)
                    && name.eq_ignore_ascii_case(col_name)
                {
                    return Ok(values.get(i).cloned().unwrap_or(SqliteValue::Null));
                }
            }
            // Fall back to resolving from raw group data via col_map.
            if let Ok(idx) = find_col_in_map(col_map, table_prefix, col_name, None) {
                return Ok(group_rows
                    .first()
                    .and_then(|r| r.get(idx))
                    .cloned()
                    .unwrap_or(SqliteValue::Null));
            }
            Ok(SqliteValue::Null)
        }

        // Literal values.
        Expr::Literal(lit, _) => Ok(match lit {
            fsqlite_ast::Literal::Integer(n) => SqliteValue::Integer(*n),
            fsqlite_ast::Literal::Float(f) => SqliteValue::Float(*f),
            fsqlite_ast::Literal::String(s) => SqliteValue::Text(s.clone().into()),
            fsqlite_ast::Literal::True => SqliteValue::Integer(1),
            fsqlite_ast::Literal::False => SqliteValue::Integer(0),
            _ => SqliteValue::Null,
        }),
        Expr::BoundOuterValue { value, .. } => Ok(value.clone()),

        // Binary operations.
        Expr::BinaryOp {
            left, op, right, ..
        } => {
            let lv = evaluate_having_value(left, values, columns, group_rows, col_map)?;
            let rv = evaluate_having_value(right, values, columns, group_rows, col_map)?;
            let is_null_op = matches!(lv, SqliteValue::Null) || matches!(rv, SqliteValue::Null);
            let comparison = || compare_join_expr_values(left, &lv, right, &rv, col_map);
            Ok(match op {
                fsqlite_ast::BinaryOp::Gt => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(i64::from(comparison() == std::cmp::Ordering::Greater))
                    }
                }
                fsqlite_ast::BinaryOp::Lt => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(i64::from(comparison() == std::cmp::Ordering::Less))
                    }
                }
                fsqlite_ast::BinaryOp::Ge => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(i64::from(comparison() != std::cmp::Ordering::Less))
                    }
                }
                fsqlite_ast::BinaryOp::Le => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(i64::from(comparison() != std::cmp::Ordering::Greater))
                    }
                }
                fsqlite_ast::BinaryOp::Eq => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(i64::from(comparison() == std::cmp::Ordering::Equal))
                    }
                }
                fsqlite_ast::BinaryOp::Ne => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(i64::from(comparison() != std::cmp::Ordering::Equal))
                    }
                }
                fsqlite_ast::BinaryOp::Is | fsqlite_ast::BinaryOp::IsNot => {
                    let equal = match (lv.is_null(), rv.is_null()) {
                        (true, true) => true,
                        (true, false) | (false, true) => false,
                        (false, false) => comparison() == std::cmp::Ordering::Equal,
                    };
                    SqliteValue::Integer(i64::from(if matches!(op, fsqlite_ast::BinaryOp::IsNot) {
                        !equal
                    } else {
                        equal
                    }))
                }
                fsqlite_ast::BinaryOp::And => {
                    // OP_And uses sqlite3VdbeIntValue (integer truncation).
                    let l_null = matches!(lv, SqliteValue::Null);
                    let r_null = matches!(rv, SqliteValue::Null);
                    let l_truthy = is_sqlite_truthy(&lv);
                    let r_truthy = is_sqlite_truthy(&rv);
                    if (!l_truthy && !l_null) || (!r_truthy && !r_null) {
                        SqliteValue::Integer(0)
                    } else if l_null || r_null {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(1)
                    }
                }
                fsqlite_ast::BinaryOp::Or => {
                    // OP_Or uses sqlite3VdbeIntValue (integer truncation).
                    let l_null = matches!(lv, SqliteValue::Null);
                    let r_null = matches!(rv, SqliteValue::Null);
                    let l_truthy = is_sqlite_truthy(&lv);
                    let r_truthy = is_sqlite_truthy(&rv);
                    if l_truthy || r_truthy {
                        SqliteValue::Integer(1)
                    } else if l_null || r_null {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(0)
                    }
                }
                fsqlite_ast::BinaryOp::Add => lv.sql_add(&rv),
                fsqlite_ast::BinaryOp::Subtract => lv.sql_sub(&rv),
                fsqlite_ast::BinaryOp::Multiply => lv.sql_mul(&rv),
                fsqlite_ast::BinaryOp::Divide => numeric_div(&lv, &rv),
                fsqlite_ast::BinaryOp::Modulo => numeric_mod(&lv, &rv),
                fsqlite_ast::BinaryOp::Concat => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Text(format!("{}{}", lv.to_text(), rv.to_text()).into())
                    }
                }
                fsqlite_ast::BinaryOp::BitAnd => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(lv.to_integer() & rv.to_integer())
                    }
                }
                fsqlite_ast::BinaryOp::BitOr => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(lv.to_integer() | rv.to_integer())
                    }
                }
                fsqlite_ast::BinaryOp::ShiftLeft | fsqlite_ast::BinaryOp::ShiftRight => {
                    if is_null_op {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(sqlite_shift(
                            lv.to_integer(),
                            rv.to_integer(),
                            matches!(op, fsqlite_ast::BinaryOp::ShiftLeft),
                        ))
                    }
                }
            })
        }

        // Unary operations.
        Expr::UnaryOp {
            op, expr: inner, ..
        } => {
            let v = evaluate_having_value(inner, values, columns, group_rows, col_map)?;
            Ok(match op {
                fsqlite_ast::UnaryOp::Negate => match v {
                    SqliteValue::Integer(n) => n
                        .checked_neg()
                        .map_or_else(|| SqliteValue::Float(-(n as f64)), SqliteValue::Integer),
                    SqliteValue::Float(f) => SqliteValue::Float(-f),
                    _ => SqliteValue::Null,
                },
                fsqlite_ast::UnaryOp::Not => {
                    // OP_Not uses sqlite3VdbeIntValue (integer truncation).
                    if matches!(v, SqliteValue::Null) {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(i64::from(!is_sqlite_truthy(&v)))
                    }
                }
                fsqlite_ast::UnaryOp::BitNot => {
                    if matches!(v, SqliteValue::Null) {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Integer(!v.to_integer())
                    }
                }
                fsqlite_ast::UnaryOp::Plus => v,
            })
        }

        // IS NULL / IS NOT NULL.
        Expr::IsNull {
            expr: inner, not, ..
        } => {
            let v = evaluate_having_value(inner, values, columns, group_rows, col_map)?;
            let is_null = matches!(v, SqliteValue::Null);
            Ok(SqliteValue::Integer(i64::from(if *not {
                !is_null
            } else {
                is_null
            })))
        }

        // BETWEEN with three-valued NULL logic.
        Expr::Between {
            expr: inner,
            low,
            high,
            not,
            ..
        } => {
            let eval = |e| evaluate_having_value(e, values, columns, group_rows, col_map);
            let val = eval(inner)?;
            let low_val = eval(low)?;
            let high_val = eval(high)?;
            let ge_low = if val.is_null() || low_val.is_null() {
                None
            } else {
                Some(
                    compare_join_expr_values(inner, &val, low, &low_val, col_map)
                        != std::cmp::Ordering::Less,
                )
            };
            let le_high = if val.is_null() || high_val.is_null() {
                None
            } else {
                Some(
                    compare_join_expr_values(inner, &val, high, &high_val, col_map)
                        != std::cmp::Ordering::Greater,
                )
            };
            Ok(match (ge_low, le_high) {
                (Some(false), _) | (_, Some(false)) => SqliteValue::Integer(i64::from(*not)),
                (Some(true), Some(true)) => SqliteValue::Integer(i64::from(!*not)),
                _ => SqliteValue::Null,
            })
        }

        // IN with three-valued NULL logic.
        Expr::In {
            expr: inner,
            set,
            not,
            ..
        } => {
            if matches!(set, InSet::List(exprs) if exprs.is_empty()) {
                return Ok(SqliteValue::Integer(i64::from(*not)));
            }
            if let Expr::RowValue(lhs_exprs, _) = inner.as_ref() {
                let InSet::List(list_exprs) = set else {
                    return Ok(SqliteValue::Null);
                };
                validate_vector_in_list_arity(lhs_exprs.len(), list_exprs)?;
                let rhs_rows = list_exprs
                    .iter()
                    .map(|list_item| {
                        let rhs_exprs = match list_item {
                            Expr::RowValue(fields, _) => fields.as_slice(),
                            other => std::slice::from_ref(other),
                        };
                        rhs_exprs
                            .iter()
                            .map(|rhs_expr| {
                                evaluate_having_value(
                                    rhs_expr, values, columns, group_rows, col_map,
                                )
                            })
                            .collect::<Result<Vec<_>>>()
                    })
                    .collect::<Result<Vec<_>>>()?;
                let lhs = lhs_exprs
                    .iter()
                    .map(|lhs_expr| {
                        evaluate_having_value(lhs_expr, values, columns, group_rows, col_map)
                    })
                    .collect::<Result<Vec<_>>>()?;
                let donor_exprs = list_exprs.last().map(|list_item| match list_item {
                    Expr::RowValue(fields, _) => fields.as_slice(),
                    other => std::slice::from_ref(other),
                });
                let mut saw_null = false;
                for (list_item, rhs) in list_exprs.iter().zip(&rhs_rows) {
                    let rhs_exprs = match list_item {
                        Expr::RowValue(fields, _) => fields.as_slice(),
                        other => std::slice::from_ref(other),
                    };
                    debug_assert_eq!(rhs_exprs.len(), lhs.len());
                    let mut tuple_has_null = false;
                    let mut tuple_all_equal = true;
                    for (field_index, (lhs_expr, lhs_value)) in
                        lhs_exprs.iter().zip(&lhs).enumerate()
                    {
                        let rhs_value = &rhs[field_index];
                        if lhs_value.is_null() || rhs_value.is_null() {
                            tuple_has_null = true;
                        } else if donor_exprs
                            .and_then(|donors| donors.get(field_index))
                            .is_none_or(|donor_expr| {
                                compare_join_expr_values(
                                    lhs_expr, lhs_value, donor_expr, rhs_value, col_map,
                                ) != std::cmp::Ordering::Equal
                            })
                        {
                            tuple_all_equal = false;
                            break;
                        }
                    }
                    if tuple_all_equal && !tuple_has_null {
                        return Ok(SqliteValue::Integer(i64::from(!*not)));
                    }
                    if tuple_all_equal {
                        saw_null = true;
                    }
                }
                return if saw_null {
                    Ok(SqliteValue::Null)
                } else {
                    Ok(SqliteValue::Integer(i64::from(*not)))
                };
            }
            let val = evaluate_having_value(inner, values, columns, group_rows, col_map)?;
            if val.is_null() {
                return Ok(SqliteValue::Null);
            }
            match set {
                InSet::List(exprs) => {
                    let mut found = false;
                    let mut saw_null = false;
                    let singleton_constant = exprs.len() == 1
                        && exprs
                            .first()
                            .is_some_and(current_singleton_in_rhs_is_constant);
                    for e in exprs {
                        let set_val =
                            evaluate_having_value(e, values, columns, group_rows, col_map)?;
                        if set_val.is_null() {
                            saw_null = true;
                            continue;
                        }
                        let singleton_list_expr =
                            (singleton_constant || in_list_expr_is_bound_donor(e)).then_some(e);
                        let ordering = compare_join_in_values(
                            inner,
                            &val,
                            singleton_list_expr,
                            &set_val,
                            col_map,
                        );
                        if ordering == std::cmp::Ordering::Equal {
                            found = true;
                            break;
                        }
                    }
                    if found {
                        Ok(SqliteValue::Integer(i64::from(!*not)))
                    } else if saw_null {
                        Ok(SqliteValue::Null)
                    } else {
                        Ok(SqliteValue::Integer(i64::from(*not)))
                    }
                }
                _ => Ok(SqliteValue::Null),
            }
        }

        // CASE expression.
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            let eval = |e| evaluate_having_value(e, values, columns, group_rows, col_map);
            let base = operand.as_deref().map(eval).transpose()?;
            for (when_expr, then_expr) in whens {
                let when_val = eval(when_expr)?;
                let matches = if let (Some(operand_expr), Some(b)) =
                    (operand.as_deref(), base.as_ref())
                {
                    // Simple CASE: NULL base never matches (NULL = x is NULL).
                    !b.is_null()
                        && !when_val.is_null()
                        && compare_join_expr_values(operand_expr, b, when_expr, &when_val, col_map)
                            == std::cmp::Ordering::Equal
                } else {
                    // Searched CASE: evaluate condition truthiness.
                    is_sqlite_truthy(&when_val)
                };
                if matches {
                    return eval(then_expr);
                }
            }
            Ok(else_expr
                .as_deref()
                .map(eval)
                .transpose()?
                .unwrap_or(SqliteValue::Null))
        }

        // CAST expression.
        Expr::Cast {
            expr: inner,
            type_name,
            ..
        } => {
            let v = evaluate_having_value(inner, values, columns, group_rows, col_map)?;
            if v.is_null() {
                return Ok(SqliteValue::Null);
            }
            let upper = type_name.name.to_ascii_uppercase();
            Ok(if upper.contains("INT") {
                SqliteValue::Integer(v.to_integer())
            } else if upper.contains("TEXT") || upper.contains("CHAR") || upper.contains("CLOB") {
                SqliteValue::Text(v.to_text().into())
            } else if upper.contains("BLOB") || upper.is_empty() {
                match v {
                    SqliteValue::Blob(_) => v,
                    _ => SqliteValue::Blob(v.to_text().into_bytes().into()),
                }
            } else if upper.contains("REAL") || upper.contains("FLOA") || upper.contains("DOUB") {
                SqliteValue::Float(v.to_float())
            } else {
                // NUMERIC affinity: try integer, then float, else text.
                let txt = v.to_text();
                if let Ok(i) = txt.parse::<i64>() {
                    SqliteValue::Integer(i)
                } else if let Ok(f) = txt.parse::<f64>() {
                    // Reject non-finite (NaN/Inf) — sqlite3AtoF doesn't recognize them.
                    if f.is_finite() {
                        SqliteValue::Float(f)
                    } else {
                        SqliteValue::Text(txt.into())
                    }
                } else {
                    SqliteValue::Text(txt.into())
                }
            })
        }

        Expr::Like {
            expr: inner,
            pattern,
            op,
            not,
            escape,
            ..
        } => {
            let val = evaluate_having_value(inner, values, columns, group_rows, col_map)?;
            let pat = evaluate_having_value(pattern, values, columns, group_rows, col_map)?;
            let escape_value = if let Some(escape_expr) = escape.as_deref() {
                Some(evaluate_having_value(
                    escape_expr,
                    values,
                    columns,
                    group_rows,
                    col_map,
                )?)
            } else {
                None
            };
            if let Some(result) = invoke_current_registered_pattern_operator(
                *op,
                pattern,
                inner,
                escape.as_deref(),
                &pat,
                &val,
                escape_value.as_ref(),
                *not,
                col_map,
            ) {
                return result;
            }
            if val.is_null()
                || pat.is_null()
                || escape_value.as_ref().is_some_and(SqliteValue::is_null)
            {
                return Ok(SqliteValue::Null);
            }
            let s = val.to_text();
            let p = pat.to_text();
            let esc_char = escape_value
                .as_ref()
                .and_then(|value| value.to_text().chars().next());
            let matched = match op {
                LikeOp::Like => simple_like_match(&p, &s, esc_char),
                LikeOp::Glob => simple_glob_match(&p, &s),
                LikeOp::Match => {
                    let match_row = group_rows.first().map_or(&[][..], Vec::as_slice);
                    match_query_with_table_columns(inner, &p, &s, match_row, col_map)
                }
                // REGEXP requires a user-defined function; this fallback
                // eval path cannot call it, so return NULL (parity: SQLite
                // errors if no regexp() function is registered).
                LikeOp::Regexp => return Ok(SqliteValue::Null),
            };
            Ok(SqliteValue::Integer(i64::from(*not != matched)))
        }

        // Non-aggregate scalar function call — evaluate arguments and delegate.
        Expr::FunctionCall { name, args, .. } => {
            let arg_values: Vec<SqliteValue> = match args {
                FunctionArgs::Star => vec![],
                FunctionArgs::List(exprs) => exprs
                    .iter()
                    .map(|e| evaluate_having_value(e, values, columns, group_rows, col_map))
                    .collect::<Result<Vec<_>>>()?,
            };
            #[cfg(feature = "ext-fts5")]
            if current_application_function_kind(name, aggregate_args_len_for_lookup(args))
                .is_none()
                && let Some(value) = eval_fts5_scalar_fallback(name, &arg_values)?
            {
                return Ok(value);
            }
            let collation = function_argument_collation(args, col_map);
            if let Some(result) =
                invoke_current_registered_scalar(name, &arg_values, collation.as_deref())
            {
                return result;
            }
            Ok(eval_scalar_fn(name, &arg_values))
        }

        // COLLATE just wraps an expression — evaluate the inner expression.
        Expr::Collate { expr: inner, .. } => {
            evaluate_having_value(inner, values, columns, group_rows, col_map)
        }

        _ => Ok(SqliteValue::Null),
    }
}

/// SQL division with NULL propagation, division-by-zero → NULL, and overflow
/// promotion to REAL (matching VDBE `sql_div` semantics).
#[allow(clippy::cast_precision_loss)]
fn numeric_div(a: &SqliteValue, b: &SqliteValue) -> SqliteValue {
    if a.is_null() || b.is_null() {
        return SqliteValue::Null;
    }
    if let (SqliteValue::Integer(ai), SqliteValue::Integer(bi)) = (a, b) {
        if *bi == 0 {
            SqliteValue::Null
        } else {
            match ai.checked_div(*bi) {
                Some(result) => SqliteValue::Integer(result),
                // i64::MIN / -1 overflows; C SQLite promotes to the floating
                // point arithmetic path.
                #[allow(clippy::cast_precision_loss)]
                None => {
                    let result = *ai as f64 / *bi as f64;
                    if result.is_nan() {
                        SqliteValue::Null
                    } else {
                        SqliteValue::Float(result)
                    }
                }
            }
        }
    } else {
        let bf = b.to_float();
        if bf == 0.0 {
            SqliteValue::Null
        } else {
            let result = a.to_float() / bf;
            if result.is_nan() {
                SqliteValue::Null
            } else {
                SqliteValue::Float(result)
            }
        }
    }
}

/// SQL remainder with NULL propagation and division-by-zero → NULL.
///
/// C SQLite: both-integer → Integer result; otherwise converts both to integer
/// and computes `iB % iA`, storing as Float.
#[allow(clippy::cast_precision_loss)]
fn numeric_mod(a: &SqliteValue, b: &SqliteValue) -> SqliteValue {
    if a.is_null() || b.is_null() {
        return SqliteValue::Null;
    }
    // C SQLite converts both operands to integer for OP_Remainder in ALL
    // paths: iA = intValue(pIn1), iB = intValue(pIn2).
    // Both-integer → Integer result; mixed/float → Float result.
    let both_int = matches!((a, b), (SqliteValue::Integer(_), SqliteValue::Integer(_)));
    let ai = a.to_integer();
    let bi = b.to_integer();
    if bi == 0 {
        return SqliteValue::Null;
    }
    let rem = ai.checked_rem(bi).unwrap_or(0);
    if both_int {
        SqliteValue::Integer(rem)
    } else {
        #[allow(clippy::cast_precision_loss)]
        {
            SqliteValue::Float(rem as f64)
        }
    }
}

/// Compare two `SqliteValue`s for ordering.
///
/// SQLite type ordering: NULL < INTEGER/REAL < TEXT < BLOB.
/// Within the same type class, values compare naturally.
/// Integer-float comparisons use precision-preserving algorithm.
/// bd-wwqen.2 B2.3: Cached pre-computed HashSet for a materialized IN list.
/// Built once on first probe, reused on all subsequent outer rows.
struct PrecomputedInSetCache {
    set: std::collections::HashSet<SqliteValueHashable>,
    has_null: bool,
}

/// GH#117: query-scoped memo for the correlated `EXISTS`/`NOT EXISTS` direct
/// probe (`try_direct_exists_probe`). `depth` counts the nesting of armed
/// `execute_join_select` WHERE loops; the memo is consulted only when
/// `depth > 0`, and `sets` is cleared when the outermost loop exits (depth
/// returns to 0). Because the child tables are read-only for the whole dynamic
/// extent of a SELECT, all cached value-sets stay valid across nested
/// subquery evaluation, and the memo is empty between statements (no
/// cross-statement staleness).
#[derive(Default)]
struct ExistsProbeMemo {
    depth: u32,
    /// Cumulative child rows inspected by allocation-free linear probes for
    /// each shape in the current query scope. This is the evidence used by the
    /// adaptive build gate; early matches therefore delay or entirely avoid a
    /// full-column value-set build.
    linear_rows_scanned: std::collections::HashMap<ExistsProbeMemoKey, usize>,
    sets: std::collections::HashMap<ExistsProbeMemoKey, ExistsValueSet>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum ExistsProbeMode {
    Raw,
    Text,
    Numeric,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct ExistsProbeMemoKey {
    root_page: i32,
    column_index: usize,
    mode: ExistsProbeMode,
    collation: ExistsProbeCollation,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum ExistsProbeCollation {
    Binary,
    NoCase,
    Rtrim,
}

fn exists_probe_mode(
    inner_affinity: TypeAffinity,
    outer_affinity: TypeAffinity,
) -> ExistsProbeMode {
    match TypeAffinity::comparison_affinity(inner_affinity, outer_affinity) {
        Some(TypeAffinity::Text) => ExistsProbeMode::Text,
        Some(TypeAffinity::Integer | TypeAffinity::Real | TypeAffinity::Numeric) => {
            ExistsProbeMode::Numeric
        }
        Some(TypeAffinity::Blob) => ExistsProbeMode::Raw,
        // `None` is a meaningful comparison-affinity result, not a request
        // to infer a coercion from the two declared affinities. The
        // authoritative evaluator compares the runtime storage classes as-is
        // in this case, so the memo must retain that exact behavior too.
        None => ExistsProbeMode::Raw,
    }
}

fn canonical_exists_probe_value(
    value: &SqliteValue,
    mode: ExistsProbeMode,
    collation: ExistsProbeCollation,
) -> SqliteValue {
    let canonical = match mode {
        ExistsProbeMode::Raw => value.clone(),
        ExistsProbeMode::Text => value.clone().apply_affinity(TypeAffinity::Text),
        ExistsProbeMode::Numeric => value.clone().apply_affinity(TypeAffinity::Numeric),
    };
    match canonical {
        SqliteValue::Text(text) => match collation {
            ExistsProbeCollation::Binary => SqliteValue::Text(text),
            ExistsProbeCollation::NoCase => {
                let mut folded = text.to_string();
                folded.make_ascii_uppercase();
                SqliteValue::Text(folded.into())
            }
            ExistsProbeCollation::Rtrim => {
                SqliteValue::Text(text.trim_end_matches(' ').to_owned().into())
            }
        },
        other => other,
    }
}

fn exists_probe_values_equal(
    left: &SqliteValue,
    right: &SqliteValue,
    mode: ExistsProbeMode,
    collation: ExistsProbeCollation,
) -> bool {
    if left.is_null() || right.is_null() {
        return false;
    }
    let left = canonical_exists_probe_value(left, mode, collation);
    let right = canonical_exists_probe_value(right, mode, collation);
    if matches!(&left, SqliteValue::Float(value) if value.is_nan())
        || matches!(&right, SqliteValue::Float(value) if value.is_nan())
    {
        return false;
    }
    cmp_sqlite_values(&left, &right) == std::cmp::Ordering::Equal
}

/// Exact, affinity-mode-specific value membership for one child column.
/// NULL never matches. INTEGER/REAL equivalence uses the shared
/// precision-preserving comparator rather than an `i64 as f64` cast.
struct ExistsValueSet {
    mode: ExistsProbeMode,
    collation: ExistsProbeCollation,
    /// TEXT and BLOB cells after the mode's deterministic affinity transform.
    /// `SqliteValueHashable` agrees with `cmp_sqlite_values` on exact binary
    /// equality for these storage classes.
    exact: std::collections::HashSet<SqliteValueHashable>,
    /// Exact INTEGER cell values (the `Integer == Integer` case).
    ints: std::collections::HashSet<i64>,
    /// Canonical non-integral REAL bit patterns, with signed zero collapsed.
    floats: std::collections::HashSet<u64>,
}

impl Default for ExistsValueSet {
    fn default() -> Self {
        Self::new(ExistsProbeMode::Raw, ExistsProbeCollation::Binary)
    }
}

/// Canonicalize a non-NaN `f64` to a `u64` hash key such that two values share
/// a key iff they are `==` (IEEE): `-0.0` and `+0.0` collapse to the same key,
/// every other finite/infinite value maps to its bit pattern. Callers must
/// guarantee `f` is not NaN (NaN never compares equal, so NaN cells/probes are
/// excluded before reaching here).
fn canon_match_f64(f: f64) -> u64 {
    // `f + 0.0` rewrites `-0.0` to `+0.0` while leaving every other value
    // unchanged, so the bit pattern is a faithful equality key without a
    // float comparison.
    (f + 0.0).to_bits()
}

impl ExistsValueSet {
    fn new(mode: ExistsProbeMode, collation: ExistsProbeCollation) -> Self {
        Self {
            mode,
            collation,
            exact: std::collections::HashSet::new(),
            ints: std::collections::HashSet::new(),
            floats: std::collections::HashSet::new(),
        }
    }

    fn add(&mut self, v: &SqliteValue) {
        let canonical = canonical_exists_probe_value(v, self.mode, self.collation);
        match &canonical {
            SqliteValue::Null => {}
            SqliteValue::Integer(x) => {
                self.ints.insert(*x);
            }
            SqliteValue::Float(y) => {
                if let Some(integer) = exact_i64_for_float(*y) {
                    self.ints.insert(integer);
                } else if !y.is_nan() {
                    self.floats.insert(canon_match_f64(*y));
                }
            }
            SqliteValue::Text(_) | SqliteValue::Blob(_) => {
                self.exact.insert(SqliteValueHashable(canonical));
            }
        }
    }

    /// Membership test matching
    /// `exists_probe_values_equal(cell, outer, mode, collation)` for some cell
    /// in the column. `outer` is guaranteed non-NULL by the caller.
    fn contains(&self, outer: &SqliteValue) -> bool {
        let canonical = canonical_exists_probe_value(outer, self.mode, self.collation);
        match &canonical {
            SqliteValue::Null => false,
            SqliteValue::Integer(x) => self.ints.contains(x),
            SqliteValue::Float(x) => {
                if let Some(integer) = exact_i64_for_float(*x) {
                    self.ints.contains(&integer)
                } else if x.is_nan() {
                    false
                } else {
                    self.floats.contains(&canon_match_f64(*x))
                }
            }
            SqliteValue::Text(_) | SqliteValue::Blob(_) => {
                self.exact.contains(&SqliteValueHashable(canonical))
            }
        }
    }
}

fn exact_i64_for_float(value: f64) -> Option<i64> {
    if !value.is_finite() {
        return None;
    }
    #[allow(clippy::cast_possible_truncation)]
    let candidate = value as i64;
    (fsqlite_types::value::int_float_cmp(candidate, value) == std::cmp::Ordering::Equal)
        .then_some(candidate)
}

/// RAII guard that disarms the `exists_probe_memo` when an `execute_join_select`
/// WHERE loop exits (on any path, including `?`/panic). Decrements the nesting
/// depth and clears the cached value-sets once the outermost loop finishes.
struct ExistsProbeMemoGuard<'a> {
    conn: &'a Connection,
}

impl Drop for ExistsProbeMemoGuard<'_> {
    fn drop(&mut self) {
        let mut memo = self.conn.exists_probe_memo.borrow_mut();
        memo.depth = memo.depth.saturating_sub(1);
        if memo.depth == 0 {
            memo.linear_rows_scanned.clear();
            memo.sets.clear();
        }
    }
}

#[cfg(test)]
mod exists_value_set_tests {
    use super::{
        ExistsProbeCollation, ExistsProbeMode, ExistsValueSet, exists_probe_mode,
        exists_probe_values_equal,
    };
    use fsqlite_types::{SqliteValue, TypeAffinity};
    use std::sync::Arc;

    /// A spread of values covering every storage class plus the tricky numeric
    /// boundaries (cross-type INTEGER/REAL, large ints beyond f64 precision,
    /// signed zero, infinities, fractional reals) and binary text/blob.
    fn sample_values() -> Vec<SqliteValue> {
        vec![
            SqliteValue::Null,
            SqliteValue::Integer(0),
            SqliteValue::Integer(1),
            SqliteValue::Integer(-1),
            SqliteValue::Integer(42),
            SqliteValue::Integer(9_007_199_254_740_993), // 2^53 + 1 (not exact in f64)
            SqliteValue::Integer(i64::MAX),
            SqliteValue::Float(0.0),
            SqliteValue::Float(-0.0),
            SqliteValue::Float(1.0),
            SqliteValue::Float(42.0),
            SqliteValue::Float(2.5),
            SqliteValue::Float(f64::INFINITY),
            SqliteValue::Float(9_007_199_254_740_992.0), // 2^53 exactly
            SqliteValue::Text("alice".into()),
            SqliteValue::Text("ALICE".into()),
            SqliteValue::Text("alice  ".into()),
            SqliteValue::Text("42".into()),
            SqliteValue::Text(String::new().into()),
            SqliteValue::Blob(Arc::from(&b"alice"[..])),
            SqliteValue::Blob(Arc::from(&[42u8][..])),
        ]
    }

    /// The memo's `contains` must agree with the per-row scan for every mode
    /// and every (cell, outer) pair where the outer value is non-NULL.
    #[test]
    fn single_cell_matches_mode_specific_scan() {
        let values = sample_values();
        for mode in [
            ExistsProbeMode::Raw,
            ExistsProbeMode::Text,
            ExistsProbeMode::Numeric,
        ] {
            for collation in [
                ExistsProbeCollation::Binary,
                ExistsProbeCollation::NoCase,
                ExistsProbeCollation::Rtrim,
            ] {
                for cell in &values {
                    let mut set = ExistsValueSet::new(mode, collation);
                    set.add(cell);
                    for outer in &values {
                        if matches!(outer, SqliteValue::Null) {
                            continue;
                        }
                        let expected = exists_probe_values_equal(cell, outer, mode, collation);
                        let got = set.contains(outer);
                        assert_eq!(
                            got, expected,
                            "contains mismatch: mode={mode:?} collation={collation:?} cell={cell:?} outer={outer:?} (memo={got}, scan={expected})",
                        );
                    }
                }
            }
        }
    }

    /// A multi-cell set must answer "does ANY cell equal the outer value?"
    /// under the selected canonicalization mode.
    #[test]
    fn multi_cell_matches_any_scan() {
        let values = sample_values();
        // Build a set from a subset of cells.
        let cells: Vec<SqliteValue> = values.iter().step_by(2).cloned().collect();
        for mode in [
            ExistsProbeMode::Raw,
            ExistsProbeMode::Text,
            ExistsProbeMode::Numeric,
        ] {
            for collation in [
                ExistsProbeCollation::Binary,
                ExistsProbeCollation::NoCase,
                ExistsProbeCollation::Rtrim,
            ] {
                let mut set = ExistsValueSet::new(mode, collation);
                for cell in &cells {
                    set.add(cell);
                }
                for outer in &values {
                    if matches!(outer, SqliteValue::Null) {
                        continue;
                    }
                    let expected = cells
                        .iter()
                        .any(|cell| exists_probe_values_equal(cell, outer, mode, collation));
                    assert_eq!(
                        set.contains(outer),
                        expected,
                        "multi-cell contains mismatch for mode={mode:?} collation={collation:?} outer={outer:?}",
                    );
                }
            }
        }
    }

    /// NULL cells never satisfy a correlated equality and must never be matched.
    #[test]
    fn null_cells_never_match() {
        let mut set = ExistsValueSet::default();
        set.add(&SqliteValue::Null);
        for outer in sample_values() {
            if matches!(outer, SqliteValue::Null) {
                continue;
            }
            assert!(!set.contains(&outer), "NULL cell wrongly matched {outer:?}");
        }
    }

    #[test]
    fn no_comparison_affinity_keeps_runtime_storage_classes_raw() {
        assert_eq!(
            exists_probe_mode(TypeAffinity::Text, TypeAffinity::Text),
            ExistsProbeMode::Raw
        );
        assert_eq!(
            exists_probe_mode(TypeAffinity::Numeric, TypeAffinity::Numeric),
            ExistsProbeMode::Raw
        );

        let mut set = ExistsValueSet::new(
            exists_probe_mode(TypeAffinity::Text, TypeAffinity::Text),
            ExistsProbeCollation::Binary,
        );
        set.add(&SqliteValue::Text("1".into()));
        assert!(set.contains(&SqliteValue::Text("1".into())));
        assert!(
            !set.contains(&SqliteValue::Integer(1)),
            "a no-affinity memo probe must not coerce an INTEGER runtime value to TEXT"
        );
    }
}

struct FkParentValidationCache {
    /// The child table being replayed for a statement-scoped cache (the single
    /// `INSERT … SELECT`/`VALUES` target). `None` for a transaction-scoped
    /// cache, which spans inserts into many different child tables; self-
    /// reference is then guarded per-FK at key-build time instead.
    target_table: Option<String>,
    validated: HashSet<FkParentValidationKey>,
}

impl FkParentValidationCache {
    /// Statement-scoped cache for a single `INSERT … SELECT`/`VALUES` replay.
    fn new(target_table: &str) -> Self {
        Self {
            target_table: Some(target_table.to_ascii_lowercase()),
            validated: HashSet::new(),
        }
    }

    /// Transaction-scoped cache (issue #110): not bound to a single target
    /// table. Self-referential FKs are excluded per-FK in
    /// `build_fk_parent_validation_cache_key`.
    fn new_transaction_scoped() -> Self {
        Self {
            target_table: None,
            validated: HashSet::new(),
        }
    }

    fn can_cache_parent(&self, parent_table: &str) -> bool {
        // A statement-scoped cache must never cache a parent that is the same
        // table being inserted into (self-referential / single-target replay):
        // a later row in the same statement may reference an earlier in-flight
        // row, so the target table's membership is not stable for caching.
        // A transaction-scoped cache makes the equivalent decision per-FK using
        // the child table recorded in the key (see the key builder).
        self.target_table
            .as_deref()
            .is_none_or(|target| !target.eq_ignore_ascii_case(parent_table))
    }
}

#[derive(Clone, PartialEq, Eq, Hash)]
struct FkParentValidationKey {
    child_table: String,
    parent_table: String,
    parent_columns: Vec<String>,
    values: Vec<SqliteValueHashable>,
}

struct FkParentValidationCacheScope<'a> {
    cache: &'a RefCell<Option<FkParentValidationCache>>,
    previous: Option<FkParentValidationCache>,
}

impl Drop for FkParentValidationCacheScope<'_> {
    fn drop(&mut self) {
        *self.cache.borrow_mut() = self.previous.take();
    }
}

/// Hashable wrapper for `SqliteValue` used by the IN-list HashSet probe
/// (bd-wwqen.2).  Hash and equality use the same comparison semantics as
/// `cmp_values` (type-affinity-aware, Integer/Float cross-comparable).
#[derive(Clone)]
struct SqliteValueHashable(SqliteValue);

impl std::hash::Hash for SqliteValueHashable {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        match &self.0 {
            SqliteValue::Null => 0u8.hash(state),
            SqliteValue::Integer(i) => {
                1u8.hash(state);
                i.hash(state);
            }
            SqliteValue::Float(f) => {
                // Normalize: if the float is an exact integer, hash as integer
                // so that 1.0 and 1 hash identically (matching cmp_values).
                let bits = f.to_bits();
                if *f == (*f as i64) as f64 {
                    1u8.hash(state);
                    (*f as i64).hash(state);
                } else {
                    2u8.hash(state);
                    bits.hash(state);
                }
            }
            SqliteValue::Text(s) => {
                3u8.hash(state);
                s.hash(state);
            }
            SqliteValue::Blob(b) => {
                4u8.hash(state);
                b.hash(state);
            }
        }
    }
}

impl PartialEq for SqliteValueHashable {
    fn eq(&self, other: &Self) -> bool {
        cmp_values(&self.0, &other.0) == std::cmp::Ordering::Equal
    }
}

impl Eq for SqliteValueHashable {}

fn cmp_values(a: &SqliteValue, b: &SqliteValue) -> std::cmp::Ordering {
    use std::cmp::Ordering;

    /// Return a numeric rank for the SQLite type affinity ordering.
    fn type_rank(v: &SqliteValue) -> u8 {
        match v {
            SqliteValue::Null => 0,
            SqliteValue::Integer(_) | SqliteValue::Float(_) => 1,
            SqliteValue::Text(_) => 2,
            SqliteValue::Blob(_) => 3,
        }
    }

    /// Precision-preserving integer-float comparison (avoids lossy `as f64`).
    fn int_float_cmp(i: i64, r: f64) -> Ordering {
        fsqlite_types::value::int_float_cmp(i, r)
    }

    /// Try to coerce a text string to a numeric `SqliteValue`.
    /// Returns `Some(Integer|Float)` if the *entire* string (after trimming
    /// whitespace) is a valid number, matching SQLite's affinity coercion
    /// rule for TEXT-vs-numeric comparisons.
    fn try_text_to_numeric(s: &str) -> Option<SqliteValue> {
        let trimmed = s.trim();
        if trimmed.is_empty() {
            return None;
        }
        let bytes = trimmed.as_bytes();
        let end = {
            let mut i = 0usize;
            if bytes[i] == b'+' || bytes[i] == b'-' {
                i += 1;
            }
            let digit_start = i;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
            }
            if i < bytes.len() && bytes[i] == b'.' {
                i += 1;
                while i < bytes.len() && bytes[i].is_ascii_digit() {
                    i += 1;
                }
            }
            if i == digit_start {
                return None;
            }
            if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
                let exp_start = i;
                i += 1;
                if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
                    i += 1;
                }
                if i < bytes.len() && bytes[i].is_ascii_digit() {
                    while i < bytes.len() && bytes[i].is_ascii_digit() {
                        i += 1;
                    }
                } else {
                    i = exp_start;
                }
            }
            i
        };
        // Entire string (after trim) must be consumed for coercion.
        if end != trimmed.len() {
            return None;
        }
        let has_decimal = trimmed.bytes().any(|b| matches!(b, b'.' | b'e' | b'E'));
        if !has_decimal && let Ok(v) = trimmed.parse::<i64>() {
            return Some(SqliteValue::Integer(v));
        }
        if let Ok(v) = trimmed.parse::<f64>() {
            // If it's an exact integer value, store as Integer.
            #[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss)]
            if v.is_finite()
                && (-9_223_372_036_854_775_808.0..9_223_372_036_854_775_808.0).contains(&v)
            {
                let truncated = v as i64;
                #[allow(clippy::float_cmp)]
                if truncated as f64 == v && !has_decimal {
                    return Some(SqliteValue::Integer(truncated));
                }
            }
            return Some(SqliteValue::Float(v));
        }
        None
    }

    let rank_a = type_rank(a);
    let rank_b = type_rank(b);
    if rank_a != rank_b {
        // Apply affinity coercion: TEXT vs numeric → try to coerce TEXT to number.
        // This matches SQLite's column-affinity comparison rule (Section 4.2).
        match (a, b) {
            (SqliteValue::Text(s), SqliteValue::Integer(_) | SqliteValue::Float(_)) => {
                if let Some(coerced) = try_text_to_numeric(s) {
                    return cmp_values(&coerced, b);
                }
            }
            (SqliteValue::Integer(_) | SqliteValue::Float(_), SqliteValue::Text(s)) => {
                if let Some(coerced) = try_text_to_numeric(s) {
                    return cmp_values(a, &coerced);
                }
            }
            _ => {}
        }
        return rank_a.cmp(&rank_b);
    }

    match (a, b) {
        (SqliteValue::Null, SqliteValue::Null) => Ordering::Equal,
        (SqliteValue::Integer(ai), SqliteValue::Integer(bi)) => ai.cmp(bi),
        (SqliteValue::Float(af), SqliteValue::Float(bf)) => {
            af.partial_cmp(bf).unwrap_or(Ordering::Equal)
        }
        (SqliteValue::Integer(ai), SqliteValue::Float(bf)) => int_float_cmp(*ai, *bf),
        (SqliteValue::Float(af), SqliteValue::Integer(bi)) => int_float_cmp(*bi, *af).reverse(),
        (SqliteValue::Text(at), SqliteValue::Text(bt)) => at.cmp(bt),
        (SqliteValue::Blob(ab), SqliteValue::Blob(bb)) => ab.cmp(bb),
        _ => unreachable!("same rank guarantees same type class"),
    }
}

/// Compare two values using pure storage-class ordering **without** TEXT→numeric
/// coercion. In SQLite, TEXT→numeric coercion only applies when a column with
/// INTEGER/REAL/NUMERIC affinity is involved (Section 4.2). When both operands
/// come from untyped (BLOB/NONE affinity) columns, values of different storage
/// classes are ordered by class rank: NULL < numeric < TEXT < BLOB.
#[allow(dead_code)]
fn cmp_values_no_affinity(a: &SqliteValue, b: &SqliteValue) -> std::cmp::Ordering {
    use std::cmp::Ordering;

    fn type_rank(v: &SqliteValue) -> u8 {
        match v {
            SqliteValue::Null => 0,
            SqliteValue::Integer(_) | SqliteValue::Float(_) => 1,
            SqliteValue::Text(_) => 2,
            SqliteValue::Blob(_) => 3,
        }
    }

    fn int_float_cmp(i: i64, r: f64) -> Ordering {
        fsqlite_types::value::int_float_cmp(i, r)
    }

    let rank_a = type_rank(a);
    let rank_b = type_rank(b);
    if rank_a != rank_b {
        return rank_a.cmp(&rank_b);
    }

    match (a, b) {
        (SqliteValue::Null, SqliteValue::Null) => Ordering::Equal,
        (SqliteValue::Integer(ai), SqliteValue::Integer(bi)) => ai.cmp(bi),
        (SqliteValue::Float(af), SqliteValue::Float(bf)) => {
            af.partial_cmp(bf).unwrap_or(Ordering::Equal)
        }
        (SqliteValue::Integer(ai), SqliteValue::Float(bf)) => int_float_cmp(*ai, *bf),
        (SqliteValue::Float(af), SqliteValue::Integer(bi)) => int_float_cmp(*bi, *af).reverse(),
        (SqliteValue::Text(at), SqliteValue::Text(bt)) => at.cmp(bt),
        (SqliteValue::Blob(ab), SqliteValue::Blob(bb)) => ab.cmp(bb),
        _ => unreachable!("same rank guarantees same type class"),
    }
}

/// Determine whether a comparison between two expressions should apply
/// TEXT→numeric affinity coercion (SQLite Section 4.2 rules).
/// Returns true if at least one expression references a column with
/// INTEGER, REAL, or NUMERIC type affinity.
#[allow(dead_code)]
fn should_coerce_for_comparison(
    left: &Expr,
    right: &Expr,
    col_map: &[(String, String, bool)],
    schemas: &[TableSchema],
) -> bool {
    fn expr_has_numeric_affinity(
        expr: &Expr,
        col_map: &[(String, String, bool)],
        schemas: &[TableSchema],
    ) -> bool {
        if let Expr::Column(col_ref, _) = expr {
            let col_name = &col_ref.column;
            let table_prefix = col_ref.table.as_deref();
            // Look up the table name from col_map.
            if let Some((table_name, _, _)) = col_map.iter().find(|(tbl, col, _)| {
                col.eq_ignore_ascii_case(col_name)
                    && table_prefix.is_none_or(|p| tbl.eq_ignore_ascii_case(p))
            }) {
                // Find the table schema.
                if let Some(schema) = schemas
                    .iter()
                    .find(|s| s.name.eq_ignore_ascii_case(table_name))
                    && let Some(col_def) = schema
                        .columns
                        .iter()
                        .find(|c| c.name.eq_ignore_ascii_case(col_name))
                {
                    // Check if the column's declared type implies numeric affinity.
                    let ty = col_def.type_name.as_deref().unwrap_or("").to_uppercase();
                    // SQLite affinity rules: INT → INTEGER, REAL/FLOA/DOUB → REAL,
                    // TEXT/CHAR/CLOB → TEXT, BLOB or empty → NONE.
                    // NUMERIC affinity for anything else.
                    if ty.is_empty() || ty.contains("BLOB") {
                        return false; // NONE affinity
                    }
                    if ty.contains("INT")
                        || ty.contains("REAL")
                        || ty.contains("FLOA")
                        || ty.contains("DOUB")
                        || ty.contains("NUMERIC")
                        || ty.contains("NUM")
                    {
                        return true;
                    }
                    if ty.contains("TEXT") || ty.contains("CHAR") || ty.contains("CLOB") {
                        return false; // TEXT affinity
                    }
                    // Default: NUMERIC affinity
                    return true;
                }
            }
        }
        false
    }
    expr_has_numeric_affinity(left, col_map, schemas)
        || expr_has_numeric_affinity(right, col_map, schemas)
}

/// Return the empty-set default for an aggregate function.
///
/// SQLite: `COUNT` → 0, `TOTAL` → 0.0, everything else → NULL.
fn empty_aggregate_default(name: &str) -> SqliteValue {
    match name {
        "count" => SqliteValue::Integer(0),
        "total" => SqliteValue::Float(0.0),
        _ => SqliteValue::Null,
    }
}

/// Kahan-Babuska-Neumaier compensated summation step matching upstream
/// aggregate precision behavior.
#[inline]
fn kbn_step(sum: &mut f64, err: &mut f64, value: f64) {
    let s = *sum;
    let t = s + value;
    if s.abs() > value.abs() {
        *err += (s - t) + value;
    } else {
        *err += (value - t) + s;
    }
    *sum = t;
}

/// Compute the aggregate value for a group of values.
#[allow(clippy::cast_possible_wrap)]
fn compute_aggregate(name: &str, values: &[&SqliteValue]) -> Result<SqliteValue> {
    match name {
        "count" => Ok(SqliteValue::Integer(values.len() as i64)),
        "sum" | "total" => {
            // SQLite: total() always returns 0.0 for empty input;
            // sum() returns NULL when all values are NULL (empty after pre-filter).
            if values.is_empty() {
                return Ok(if name == "total" {
                    SqliteValue::Float(0.0)
                } else {
                    SqliteValue::Null
                });
            }
            let mut sum = 0.0_f64;
            let mut err = 0.0_f64;
            let mut has_int = false;
            let mut all_int = true;
            let mut int_sum = 0_i64;
            let mut int_overflowed = false;
            for v in values {
                match v.to_sum_numeric_value() {
                    SqliteValue::Integer(n) => {
                        has_int = true;
                        if all_int && !int_overflowed {
                            match int_sum.checked_add(n) {
                                Some(s) => int_sum = s,
                                None => int_overflowed = true,
                            }
                        }
                        kbn_step(&mut sum, &mut err, n as f64);
                    }
                    SqliteValue::Float(f) => {
                        all_int = false;
                        kbn_step(&mut sum, &mut err, f);
                    }
                    SqliteValue::Null | SqliteValue::Text(_) | SqliteValue::Blob(_) => {}
                }
            }
            if name == "total" {
                Ok(SqliteValue::Float(sum + err))
            } else if all_int && int_overflowed {
                Err(FrankenError::IntegerOverflow)
            } else if has_int && all_int {
                Ok(SqliteValue::Integer(int_sum))
            } else {
                Ok(SqliteValue::Float(sum + err))
            }
        }
        "avg" => {
            if values.is_empty() {
                return Ok(SqliteValue::Null);
            }
            let mut sum = 0.0_f64;
            let mut err = 0.0_f64;
            let mut count = 0_u64;
            for v in values {
                match v {
                    SqliteValue::Null => {}
                    SqliteValue::Integer(n) => {
                        kbn_step(&mut sum, &mut err, *n as f64);
                        count += 1;
                    }
                    SqliteValue::Float(f) => {
                        kbn_step(&mut sum, &mut err, *f);
                        count += 1;
                    }
                    other => {
                        // Text/Blob: coerce to float (C SQLite's sqlite3_value_double).
                        kbn_step(&mut sum, &mut err, other.to_float());
                        count += 1;
                    }
                }
            }
            if count == 0 {
                Ok(SqliteValue::Null)
            } else {
                Ok(SqliteValue::Float((sum + err) / count as f64))
            }
        }
        "min" => Ok(values
            .iter()
            .filter(|v| !matches!(v, SqliteValue::Null))
            .min_by(|a, b| cmp_sqlite_values(a, b))
            .map_or(SqliteValue::Null, |v| (*v).clone())),
        "max" => Ok(values
            .iter()
            .filter(|v| !matches!(v, SqliteValue::Null))
            .max_by(|a, b| cmp_sqlite_values(a, b))
            .map_or(SqliteValue::Null, |v| (*v).clone())),
        "group_concat" | "string_agg" => {
            let parts: Vec<String> = values
                .iter()
                .filter(|v| !matches!(v, SqliteValue::Null))
                .map(|v| v.to_text())
                .collect();
            // SQLite: GROUP_CONCAT returns NULL when all values are NULL.
            if parts.is_empty() {
                Ok(SqliteValue::Null)
            } else {
                Ok(SqliteValue::Text(parts.join(",").into()))
            }
        }
        _ => Ok(SqliteValue::Null),
    }
}

/// Extended aggregate computation with optional DISTINCT dedup already applied
/// and an explicit separator for `GROUP_CONCAT`.
#[allow(clippy::cast_possible_wrap)]
fn compute_aggregate_ext(
    name: &str,
    values: &[&SqliteValue],
    separator: Option<&str>,
) -> Result<SqliteValue> {
    if (name == "group_concat" || name == "string_agg") && separator.is_some() {
        let sep = separator.unwrap_or(",");
        let parts: Vec<String> = values
            .iter()
            .filter(|v| !matches!(v, SqliteValue::Null))
            .map(|v| v.to_text())
            .collect();
        Ok(if parts.is_empty() {
            SqliteValue::Null
        } else {
            SqliteValue::Text(parts.join(sep).into())
        })
    } else {
        compute_aggregate(name, values)
    }
}

/// Remove duplicate values in-place, preserving first-occurrence order.
fn dedup_values(values: &mut Vec<&SqliteValue>) {
    let mut seen = Vec::new();
    values.retain(|v| {
        if seen.contains(v) {
            false
        } else {
            seen.push(*v);
            true
        }
    });
}

/// Collation-aware duplicate removal. When a collation is specified (e.g.
/// `NOCASE`), text values are compared through the collation registry so
/// that `'Alice'` and `'alice'` are treated as equal.
fn dedup_values_collated(
    values: &mut Vec<&SqliteValue>,
    collation: Option<&str>,
    collation_registry: &Mutex<CollationRegistry>,
) {
    if collation.is_none() {
        dedup_values(values);
        return;
    }
    let snap = lock_unpoisoned(collation_registry).clone();
    let mut seen: Vec<&SqliteValue> = Vec::new();
    values.retain(|v| {
        let already = seen.iter().any(|s| {
            cmp_sqlite_values_collated_snapshot(v, s, collation, &snap) == std::cmp::Ordering::Equal
        });
        if already {
            false
        } else {
            seen.push(*v);
            true
        }
    });
}

/// Extended aggregate computation with optional collation for MIN/MAX.
#[allow(clippy::cast_possible_wrap)]
fn compute_aggregate_ext_collated(
    name: &str,
    values: &[&SqliteValue],
    separator: Option<&str>,
    collation: Option<&str>,
    collation_registry: &Mutex<CollationRegistry>,
) -> Result<SqliteValue> {
    // For MIN/MAX with a non-default collation, use collation-aware comparison.
    if collation.is_some() && (name == "min" || name == "max") {
        let snap = lock_unpoisoned(collation_registry).clone();
        let filtered = values.iter().filter(|v| !matches!(v, SqliteValue::Null));
        let result = if name == "min" {
            filtered.min_by(|a, b| cmp_sqlite_values_collated_snapshot(a, b, collation, &snap))
        } else {
            filtered.max_by(|a, b| cmp_sqlite_values_collated_snapshot(a, b, collation, &snap))
        };
        return Ok(result.map_or(SqliteValue::Null, |v| (*v).clone()));
    }
    compute_aggregate_ext(name, values, separator)
}

/// Compare two `SqliteValue`s for ordering.
///
/// SQLite type ordering: NULL < INTEGER/REAL < TEXT < BLOB.
/// Within the same type class, values compare naturally.
fn cmp_sqlite_values(a: &SqliteValue, b: &SqliteValue) -> std::cmp::Ordering {
    use std::cmp::Ordering;

    /// Return a numeric rank for the SQLite type affinity ordering.
    fn type_rank(v: &SqliteValue) -> u8 {
        match v {
            SqliteValue::Null => 0,
            SqliteValue::Integer(_) | SqliteValue::Float(_) => 1,
            SqliteValue::Text(_) => 2,
            SqliteValue::Blob(_) => 3,
        }
    }

    let rank_a = type_rank(a);
    let rank_b = type_rank(b);
    if rank_a != rank_b {
        return rank_a.cmp(&rank_b);
    }

    /// Precision-preserving integer-float comparison.
    fn int_float_cmp(i: i64, r: f64) -> Ordering {
        fsqlite_types::value::int_float_cmp(i, r)
    }

    // Same type class — compare within class.
    match (a, b) {
        (SqliteValue::Null, SqliteValue::Null) => Ordering::Equal,
        (SqliteValue::Integer(a), SqliteValue::Integer(b)) => a.cmp(b),
        (SqliteValue::Float(a), SqliteValue::Float(b)) => {
            a.partial_cmp(b).unwrap_or(Ordering::Equal)
        }
        (SqliteValue::Integer(a), SqliteValue::Float(b)) => int_float_cmp(*a, *b),
        (SqliteValue::Float(a), SqliteValue::Integer(b)) => int_float_cmp(*b, *a).reverse(),
        (SqliteValue::Text(a), SqliteValue::Text(b)) => a.cmp(b),
        (SqliteValue::Blob(a), SqliteValue::Blob(b)) => a.cmp(b),
        _ => unreachable!("unreachable given rank check above"),
    }
}

/// Compare text bytes using a pre-snapshotted collation registry.
/// Avoids mutex acquisition on every comparison in O(N log N) sort loops.
#[cfg_attr(not(test), allow(dead_code))]
fn compare_text_bytes_collated(
    left: &[u8],
    right: &[u8],
    collation: &str,
    collation_registry: &Mutex<CollationRegistry>,
) -> std::cmp::Ordering {
    let compare_with = |registry: &CollationRegistry| {
        registry
            .find(collation)
            .map(|collation| collation.compare(left, right))
    };

    compare_with(&lock_unpoisoned(collation_registry)).unwrap_or_else(|| left.cmp(right))
}

/// Compare text bytes using a pre-snapshotted collation registry.
/// Avoids mutex acquisition on every comparison in O(N log N) sort loops.
fn compare_text_bytes_collated_snapshot(
    left: &[u8],
    right: &[u8],
    collation: &str,
    registry: &CollationRegistry,
) -> std::cmp::Ordering {
    registry
        .find(collation)
        .map(|coll_fn| coll_fn.compare(left, right))
        .unwrap_or_else(|| left.cmp(right))
}

/// Lock-free variant using a pre-snapshotted registry.
#[allow(dead_code)]
fn cmp_sqlite_values_collated(
    a: &SqliteValue,
    b: &SqliteValue,
    collation: Option<&str>,
    collation_registry: &Mutex<CollationRegistry>,
) -> std::cmp::Ordering {
    if let (Some(coll), SqliteValue::Text(at), SqliteValue::Text(bt)) = (collation, a, b) {
        return compare_text_bytes_collated(at.as_bytes(), bt.as_bytes(), coll, collation_registry);
    }
    cmp_sqlite_values(a, b)
}

/// Lock-free variant using a pre-snapshotted registry.
fn cmp_sqlite_values_collated_snapshot(
    a: &SqliteValue,
    b: &SqliteValue,
    collation: Option<&str>,
    registry: &CollationRegistry,
) -> std::cmp::Ordering {
    if let (Some(coll), SqliteValue::Text(at), SqliteValue::Text(bt)) = (collation, a, b) {
        return compare_text_bytes_collated_snapshot(at.as_bytes(), bt.as_bytes(), coll, registry);
    }
    cmp_sqlite_values(a, b)
}

/// Compare two GROUP BY key vectors with per-element collation.
fn group_keys_equal_collated(
    a: &[SqliteValue],
    b: &[SqliteValue],
    collations: &[Option<String>],
    coll_snap: &CollationRegistry,
) -> bool {
    if a.len() != b.len() {
        return false;
    }
    a.iter().zip(b.iter()).enumerate().all(|(i, (av, bv))| {
        let coll = collations.get(i).and_then(|c| c.as_deref());
        cmp_sqlite_values_collated_snapshot(av, bv, coll, coll_snap) == std::cmp::Ordering::Equal
    })
}

/// Per-column collation-aware lexicographic ordering for two value slices.
///
/// Returns `Ordering::Less` / `Greater` / `Equal` consistent with
/// `group_keys_equal_collated` (so equal slices under collation produce
/// `Ordering::Equal`). Compares pairwise from index 0; on the first
/// non-equal pair, returns that ordering. Slices of differing length
/// compare by length when all common prefix entries are equal.
fn compare_value_slices_collated_snapshot(
    a: &[SqliteValue],
    b: &[SqliteValue],
    collations: &[Option<String>],
    registry: &CollationRegistry,
) -> std::cmp::Ordering {
    let common = a.len().min(b.len());
    for i in 0..common {
        let coll = collations.get(i).and_then(|c| c.as_deref());
        let ord = cmp_sqlite_values_collated_snapshot(&a[i], &b[i], coll, registry);
        if ord != std::cmp::Ordering::Equal {
            return ord;
        }
    }
    a.len().cmp(&b.len())
}

#[must_use]
fn group_keys_support_hash_grouping(collations: &[Option<String>]) -> bool {
    collations.iter().all(|collation| {
        collation
            .as_deref()
            .is_none_or(|name| name.eq_ignore_ascii_case("BINARY"))
    })
}

/// Determine the effective collation for a GROUP BY expression.
/// Explicit COLLATE in the expression takes priority, otherwise
/// inherit the column's declared collation from the table schema.
fn expr_effective_collation_for_table(expr: &Expr, schema: &TableSchema) -> Option<String> {
    if let Some(collation) = first_explicit_collation_name(expr) {
        return Some(collation.to_owned());
    }
    let source = index_declared_collation_source_expr(expr);
    if let Expr::BoundOuterValue { collation, .. } = source {
        return match collation {
            BoundCollation::Unspecified => None,
            BoundCollation::Binary => Some("BINARY".to_owned()),
            BoundCollation::Named(name) => Some(name.clone()),
        };
    }
    if let Expr::Column(cr, _) = source {
        if cr
            .table
            .as_deref()
            .is_some_and(|table| !table.eq_ignore_ascii_case(&schema.name))
        {
            return None;
        }
        return schema
            .columns
            .iter()
            .find(|c| c.name.eq_ignore_ascii_case(&cr.column))
            .and_then(|c| c.collation.clone());
    }
    None
}

fn resolve_operand_collation(expr: &Expr, schemas: &[TableSchema]) -> Option<String> {
    if let Some(collation) = first_explicit_collation_name(expr) {
        return Some(collation.to_owned());
    }
    let source = index_declared_collation_source_expr(expr);
    if let Expr::BoundOuterValue { collation, .. } = source {
        return match collation {
            BoundCollation::Unspecified => None,
            BoundCollation::Binary => Some("BINARY".to_owned()),
            BoundCollation::Named(name) => Some(name.clone()),
        };
    }
    if let Expr::Column(cr, _) = source {
        for schema in schemas {
            let name_matches = cr
                .table
                .as_ref()
                .is_none_or(|t| t.eq_ignore_ascii_case(&schema.name));
            if name_matches
                && let Some(coll) = schema
                    .columns
                    .iter()
                    .find(|c| c.name.eq_ignore_ascii_case(&cr.column))
                    .and_then(|c| c.collation.clone())
            {
                return Some(coll);
            }
        }
    }
    None
}

fn operand_explicit_collation(expr: &Expr) -> Option<&str> {
    first_explicit_collation_name(expr)
}

/// Affinity crossing a direct scalar-subquery boundary follows the parser
/// root: the final compound core, and for a VALUES core its frozen
/// representation donor. This is intentionally separate from
/// derived-table/view column metadata, whose compound rules differ in SQLite.
fn scalar_subquery_result_affinity(
    select: &SelectStatement,
    schemas: &[TableSchema],
) -> TypeAffinity {
    let core = in_rhs_donor_core(select);
    match core {
        // bd-di4he: the project oracle (bundled SQLite 3.53.2 via rusqlite)
        // donates VALUES affinity from the coroutine's donor row — the LAST
        // row when no donor has been frozen: `(VALUES(1),(random() AND 0),
        // (CAST(1 AS NUMERIC))) = '1'` is 1 there. (System sqlite3 3.46.1
        // predates that donor model and answers 0; the bundled reference is
        // authoritative for keepers.)
        SelectCore::Values(rows) => rows
            .donor_row()
            .or_else(|| rows.rows().last().map(Vec::as_slice))
            .and_then(<[Expr]>::first)
            .map_or(TypeAffinity::Blob, |expr| {
                resolve_operand_affinity(expr, schemas)
            }),
        SelectCore::Select {
            columns,
            from: None,
            ..
        } => match columns.first() {
            Some(ResultColumn::Expr { expr, .. }) => resolve_operand_affinity(expr, schemas),
            Some(ResultColumn::Star | ResultColumn::TableStar(_)) | None => TypeAffinity::Blob,
        },
        SelectCore::Select { .. } => select_core_result_affinities(core, schemas)
            .first()
            .copied()
            .unwrap_or(TypeAffinity::Blob),
    }
}

fn resolve_operand_affinity(expr: &Expr, schemas: &[TableSchema]) -> TypeAffinity {
    if let Expr::BoundOuterValue { affinity, .. } = expr {
        return affinity.unwrap_or(TypeAffinity::Blob);
    }
    if let Expr::Cast { type_name, .. } = expr {
        return TypeAffinity::from_type_name(&type_name.name);
    }
    if let Expr::Collate { expr: inner, .. } = expr {
        return resolve_operand_affinity(inner, schemas);
    }
    if let Expr::Subquery(select, _) = expr {
        return scalar_subquery_result_affinity(select, schemas);
    }
    if let Expr::Column(cr, _) = expr {
        for schema in schemas {
            let name_matches = cr
                .table
                .as_ref()
                .is_none_or(|t| t.eq_ignore_ascii_case(&schema.name));
            if name_matches
                && let Some(col) = schema
                    .columns
                    .iter()
                    .find(|c| c.name.eq_ignore_ascii_case(&cr.column))
            {
                return match col.affinity {
                    'B' | 'b' => TypeAffinity::Text,
                    'C' | 'c' => TypeAffinity::Numeric,
                    'D' | 'd' => TypeAffinity::Integer,
                    'E' | 'e' => TypeAffinity::Real,
                    _ => TypeAffinity::Blob,
                };
            }
        }
    }
    TypeAffinity::Blob
}

fn resolve_named_order_term_idx(
    col_name: &str,
    order_table: Option<&str>,
    columns: &[ResultColumn],
) -> Option<usize> {
    // SQLite resolves an unqualified output alias before consulting source
    // column names, even when the alias appears later in the result list.
    if order_table.is_none()
        && let Some(index) = columns.iter().position(|column| {
            matches!(
                column,
                ResultColumn::Expr {
                    alias: Some(alias),
                    ..
                } if alias.eq_ignore_ascii_case(col_name)
            )
        })
    {
        return Some(index);
    }

    columns.iter().position(|column| match column {
        ResultColumn::Expr { expr, .. } => {
            let result_expr = match expr {
                Expr::Collate { expr, .. } => expr.as_ref(),
                _ => expr,
            };
            let Expr::Column(result_col_ref, _) = result_expr else {
                return false;
            };
            if !result_col_ref.column.eq_ignore_ascii_case(col_name) {
                return false;
            }
            order_table.is_none_or(|table| {
                result_col_ref
                    .table
                    .as_deref()
                    .is_some_and(|result_table| result_table.eq_ignore_ascii_case(table))
            })
        }
        ResultColumn::Star | ResultColumn::TableStar(_) => false,
    })
}

/// Try to resolve an ORDER BY expression to a column index in `columns`.
/// Returns `None` if the expression doesn't match any column.
fn strip_collate_wrappers(mut expr: &Expr) -> &Expr {
    while let Expr::Collate { expr: inner, .. } = expr {
        expr = inner;
    }
    expr
}

fn resolve_order_term_idx(expr: &Expr, columns: &[ResultColumn]) -> Option<usize> {
    // A compound ORDER BY may wrap an output name, alias, or 1-based position
    // in COLLATE. Resolve those SQLite-defined output references against the
    // inner expression first; the caller still applies the outer collation
    // while sorting.
    let base_expr = strip_collate_wrappers(expr);

    if let Some(ordinal) = connection_order_by_integer_ordinal(base_expr) {
        let pos = usize::try_from(ordinal).unwrap_or(0);
        return pos.checked_sub(1).filter(|&index| index < columns.len());
    }
    if let Some(col_name) = expr_col_name(base_expr) {
        let order_table = if let Expr::Column(col_ref, _) = base_expr {
            col_ref.table.as_deref()
        } else {
            None
        };
        if let Some(found) = resolve_named_order_term_idx(col_name, order_table, columns) {
            return Some(found);
        }
    }

    // After ordinal and output-name/alias precedence, preserve an exact
    // selected expression before falling back to the unwrapped expression.
    // This matters for non-column COLLATE expressions while preventing a
    // selected integer literal from stealing `ORDER BY 1`.
    if let Some(index) = columns.iter().position(|column| match column {
        ResultColumn::Expr {
            expr: output_expr, ..
        } => exprs_match(expr, output_expr),
        ResultColumn::Star | ResultColumn::TableStar(_) => false,
    }) {
        return Some(index);
    }

    columns.iter().position(|c| match c {
        ResultColumn::Expr { expr: e, .. } => exprs_match(base_expr, e),
        _ => false,
    })
}

/// Resolve SQLite's signed integer ORDER BY ordinal syntax.
///
/// Keeping this check ahead of structural expression matching prevents an
/// invalid `ORDER BY -1` or `ORDER BY +2` from being reclassified as a
/// harmless expression merely because an equivalent temporary sort column was
/// appended by a fallback executor.
fn connection_order_by_integer_ordinal(expr: &Expr) -> Option<i64> {
    if expr_folds_to_integer_zero_via_and(expr) {
        return Some(0);
    }
    match expr {
        Expr::Literal(Literal::Integer(value), _) => Some(*value),
        Expr::UnaryOp {
            op: UnaryOp::Plus,
            expr,
            ..
        }
        | Expr::Collate { expr, .. } => connection_order_by_integer_ordinal(expr),
        Expr::UnaryOp {
            op: UnaryOp::Negate,
            expr,
            ..
        } => connection_order_by_integer_ordinal(expr)?.checked_neg(),
        _ => None,
    }
}

/// Sort result rows by ORDER BY terms (for GROUP BY post-processing).
/// `col_collations` maps result column index to collation name
/// (e.g. "NOCASE") for collation-aware sorting.
fn sort_rows_by_order_terms(
    rows: &mut [Row],
    order_by: &[OrderingTerm],
    columns: &[ResultColumn],
    col_collations: &[Option<String>],
    collation_registry: &Mutex<CollationRegistry>,
) -> Result<()> {
    let resolved: Vec<(usize, bool, NullsOrder, Option<String>)> = order_by
        .iter()
        .map(|term| {
            let idx = resolve_order_term_idx(&term.expr, columns).ok_or_else(|| {
                FrankenError::Internal("ORDER BY expression not found in SELECT list".to_owned())
            })?;
            let desc = matches!(term.direction, Some(SortDirection::Desc));
            let nulls = term
                .nulls
                .unwrap_or_else(|| default_nulls_order(term.direction));
            let coll = match &term.expr {
                Expr::Collate { collation, .. } => Some(collation.clone()),
                _ => col_collations.get(idx).cloned().flatten(),
            };
            Ok((idx, desc, nulls, coll))
        })
        .collect::<Result<Vec<_>>>()?;

    // Snapshot collation registry once before the sort to avoid locking the
    // mutex on every comparison (§14.9 seqlock-inspired optimization).
    // Under O(N log N) sorting, this eliminates N×log(N) mutex acquisitions.
    let coll_snapshot = lock_unpoisoned(collation_registry).clone();

    rows.sort_by(|a, b| {
        for (idx, desc, nulls, coll) in &resolved {
            let av = &a.values()[*idx];
            let bv = &b.values()[*idx];
            let a_null = av.is_null();
            let b_null = bv.is_null();
            if a_null || b_null {
                if a_null && b_null {
                    continue;
                }
                let ord = match (a_null, *nulls) {
                    (true, NullsOrder::First) | (false, NullsOrder::Last) => {
                        std::cmp::Ordering::Less
                    }
                    (true, NullsOrder::Last) | (false, NullsOrder::First) => {
                        std::cmp::Ordering::Greater
                    }
                };
                return ord;
            }
            let ord = cmp_sqlite_values_collated_snapshot(av, bv, coll.as_deref(), &coll_snapshot);
            let ord = if *desc { ord.reverse() } else { ord };
            if ord != std::cmp::Ordering::Equal {
                return ord;
            }
        }
        std::cmp::Ordering::Equal
    });

    Ok(())
}

/// Convert an AST `ForeignKeyClause` to a codegen `FkDef`.
fn fk_clause_to_def(
    child_indices: &[usize],
    owner_column: Option<String>,
    clause: &fsqlite_ast::ForeignKeyClause,
) -> FkDef {
    let mut on_delete = FkActionType::NoAction;
    let mut on_update = FkActionType::NoAction;
    for action in &clause.actions {
        let action_type = match action.action {
            fsqlite_ast::ForeignKeyActionType::SetNull => FkActionType::SetNull,
            fsqlite_ast::ForeignKeyActionType::SetDefault => FkActionType::SetDefault,
            fsqlite_ast::ForeignKeyActionType::Cascade => FkActionType::Cascade,
            fsqlite_ast::ForeignKeyActionType::Restrict => FkActionType::Restrict,
            fsqlite_ast::ForeignKeyActionType::NoAction => FkActionType::NoAction,
        };
        match action.trigger {
            fsqlite_ast::ForeignKeyTrigger::OnDelete => on_delete = action_type,
            fsqlite_ast::ForeignKeyTrigger::OnUpdate => on_update = action_type,
        }
    }
    FkDef {
        child_columns: child_indices.to_vec(),
        owner_column,
        parent_table: clause.table.clone(),
        parent_columns: clause.columns.clone(),
        on_delete,
        on_update,
        deferred: fk_clause_initially_deferred(clause),
    }
}

/// `true` when a foreign-key clause is declared `DEFERRABLE INITIALLY DEFERRED`,
/// whose parent-existence check is postponed to COMMIT (bd-do0d6).
fn fk_clause_initially_deferred(clause: &fsqlite_ast::ForeignKeyClause) -> bool {
    clause.deferrable.as_ref().is_some_and(|d| {
        !d.not
            && matches!(
                d.initially,
                Some(fsqlite_ast::DeferrableInitially::Deferred)
            )
    })
}

/// Map an AST type name to a codegen affinity character.
fn type_name_to_affinity_char(name: &str) -> char {
    let upper = name.to_uppercase();
    if upper.contains("INT") {
        'D' // INTEGER affinity
    } else if upper.contains("CHAR") || upper.contains("TEXT") || upper.contains("CLOB") {
        'B' // TEXT affinity
    } else if upper.contains("BLOB") || upper.is_empty() {
        'A' // BLOB (none) affinity
    } else if upper.contains("REAL") || upper.contains("FLOA") || upper.contains("DOUB") {
        'E' // REAL affinity
    } else {
        'C' // NUMERIC affinity
    }
}

fn affinity_char_to_type(ch: char) -> TypeAffinity {
    match ch {
        'B' | 'b' => TypeAffinity::Text,
        'C' | 'c' => TypeAffinity::Numeric,
        'D' | 'd' => TypeAffinity::Integer,
        'E' | 'e' => TypeAffinity::Real,
        _ => TypeAffinity::Blob,
    }
}

fn type_affinity_to_char(affinity: TypeAffinity) -> char {
    match affinity {
        TypeAffinity::Blob => 'A',
        TypeAffinity::Text => 'B',
        TypeAffinity::Numeric => 'C',
        TypeAffinity::Integer => 'D',
        TypeAffinity::Real => 'E',
    }
}

/// Format a `DefaultValue` AST node as SQL text for PRAGMA table_info output.
fn format_default_value(dv: &DefaultValue) -> String {
    match dv {
        DefaultValue::Expr(expr) => expr.to_string(),
        DefaultValue::ParenExpr(expr) => format!("({})", expr),
    }
}

fn default_expr_is_self_contained(expr: &Expr) -> bool {
    match expr {
        Expr::Literal(_, _) => true,
        Expr::BoundOuterValue { .. }
        | Expr::Column(_, _)
        | Expr::Exists { .. }
        | Expr::Subquery(_, _)
        | Expr::Raise { .. }
        | Expr::RowValue(_, _)
        | Expr::Placeholder(_, _) => false,
        Expr::BinaryOp { left, right, .. } => {
            default_expr_is_self_contained(left) && default_expr_is_self_contained(right)
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. } => default_expr_is_self_contained(inner),
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            default_expr_is_self_contained(inner)
                && default_expr_is_self_contained(low)
                && default_expr_is_self_contained(high)
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            default_expr_is_self_contained(inner)
                && match set {
                    InSet::List(exprs) => exprs.iter().all(default_expr_is_self_contained),
                    InSet::Subquery(_) | InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            default_expr_is_self_contained(inner)
                && default_expr_is_self_contained(pattern)
                && escape.as_deref().is_none_or(default_expr_is_self_contained)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_none_or(default_expr_is_self_contained)
                && whens.iter().all(|(when_expr, then_expr)| {
                    default_expr_is_self_contained(when_expr)
                        && default_expr_is_self_contained(then_expr)
                })
                && else_expr
                    .as_deref()
                    .is_none_or(default_expr_is_self_contained)
        }
        Expr::FunctionCall {
            args,
            distinct,
            order_by,
            filter,
            over,
            ..
        } => {
            !distinct
                && order_by.is_empty()
                && filter.is_none()
                && over.is_none()
                && match args {
                    FunctionArgs::Star => false,
                    FunctionArgs::List(exprs) => exprs.iter().all(default_expr_is_self_contained),
                }
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => default_expr_is_self_contained(inner) && default_expr_is_self_contained(path),
    }
}

/// Convert a `CodegenError` to a `FrankenError`.
/// Shared empty Arc for column defaults — avoids per-statement heap allocation
/// when no tables have column defaults (the common case for read-only queries).
fn empty_column_defaults_arc() -> Arc<HbHashMap<i32, Vec<Option<SqliteValue>>>> {
    use std::sync::OnceLock;
    static EMPTY: OnceLock<Arc<HbHashMap<i32, Vec<Option<SqliteValue>>>>> = OnceLock::new();
    Arc::clone(EMPTY.get_or_init(|| Arc::new(HbHashMap::new())))
}

fn codegen_error_to_franken(e: CodegenError) -> FrankenError {
    match e {
        CodegenError::TableNotFound(name) => {
            FrankenError::Internal(format!("no such table: {name}"))
        }
        CodegenError::ColumnNotFound { table, column } => {
            FrankenError::Internal(format!("no such column: {column} in table {table}"))
        }
        CodegenError::AmbiguousColumn(name) => FrankenError::AmbiguousColumn { name },
        CodegenError::Unsupported(msg) => FrankenError::NotImplemented(msg),
    }
}

fn create_index_bind_error_to_franken(error: CodegenError) -> FrankenError {
    match error {
        CodegenError::TableNotFound(name) => FrankenError::NoSuchTable { name },
        CodegenError::ColumnNotFound { column, .. } => FrankenError::NoSuchColumn { name: column },
        CodegenError::AmbiguousColumn(name) => FrankenError::AmbiguousColumn { name },
        CodegenError::Unsupported(message) => FrankenError::FunctionError(message),
    }
}

/// Short label for a statement type, used in EXPLAIN error messages.
fn stmt_kind_label(stmt: &Statement) -> &'static str {
    match stmt {
        Statement::Select(_) => "SELECT",
        Statement::Insert(_) => "INSERT",
        Statement::Update(_) => "UPDATE",
        Statement::Delete(_) => "DELETE",
        Statement::CreateTable(_) => "CREATE TABLE",
        Statement::CreateVirtualTable(_) => "CREATE VIRTUAL TABLE",
        Statement::Drop(_) => "DROP",
        Statement::AlterTable(_) => "ALTER TABLE",
        Statement::CreateIndex(_) => "CREATE INDEX",
        Statement::CreateView(_) => "CREATE VIEW",
        Statement::CreateTrigger(_) => "CREATE TRIGGER",
        Statement::Pragma(_) => "PRAGMA",
        Statement::Begin(_) => "BEGIN",
        Statement::Commit => "COMMIT",
        Statement::Rollback(_) => "ROLLBACK",
        Statement::Savepoint(_) => "SAVEPOINT",
        Statement::Release(_) => "RELEASE",
        Statement::Vacuum(_) => "VACUUM",
        Statement::Analyze(_) => "ANALYZE",
        Statement::Reindex(_) => "REINDEX",
        Statement::Explain { .. } => "EXPLAIN",
        _ => "unknown",
    }
}

/// bd-33sht: an `INSERT ... VALUES` / `DEFAULT VALUES` whose value expressions
/// read nothing from the database never consults the MemDatabase mirror during
/// execution.
///
/// Such a statement can skip the eager per-statement mirror *reload* (its pending
/// direct writes are still flushed, since its own uniqueness/rowid checks read
/// the txn b-tree): the mirror stays stale through a bulk-insert streak and is
/// rebuilt once at the next actual read boundary, turning O(rows x statements)
/// ingest into O(rows + statements). Conservative — anything not provably
/// read-free (a `SELECT` source, a subquery/EXISTS/IN, a column or function
/// reference) keeps the full refresh.
fn insert_source_is_memdb_read_free(source: &fsqlite_ast::InsertSource) -> bool {
    match source {
        fsqlite_ast::InsertSource::DefaultValues => true,
        fsqlite_ast::InsertSource::Select(_) => false,
        fsqlite_ast::InsertSource::Values(rows) => {
            rows.iter().all(|row| row.iter().all(expr_is_memdb_read_free))
        }
    }
}

fn expr_is_memdb_read_free(expr: &fsqlite_ast::Expr) -> bool {
    use fsqlite_ast::Expr;
    match expr {
        Expr::Literal(..) | Expr::Placeholder(..) => true,
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => expr_is_memdb_read_free(expr),
        Expr::BinaryOp { left, right, .. } => {
            expr_is_memdb_read_free(left) && expr_is_memdb_read_free(right)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_is_memdb_read_free(expr)
                && expr_is_memdb_read_free(low)
                && expr_is_memdb_read_free(high)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_deref().is_none_or(expr_is_memdb_read_free)
                && whens
                    .iter()
                    .all(|(w, t)| expr_is_memdb_read_free(w) && expr_is_memdb_read_free(t))
                && else_expr.as_deref().is_none_or(expr_is_memdb_read_free)
        }
        // Subquery / EXISTS / IN / column / function / row-value / bound-outer /
        // and every other form: conservatively keep the full refresh.
        _ => false,
    }
}

fn statement_starts_fresh_schema_change_boundary(statement: &Statement) -> bool {
    matches!(
        statement,
        Statement::CreateTable(_)
            | Statement::CreateVirtualTable(_)
            | Statement::CreateView(_)
            | Statement::CreateTrigger(_)
            | Statement::Drop(_)
            | Statement::AlterTable(_)
            | Statement::CreateIndex(_)
            | Statement::Analyze(_)
            | Statement::Reindex(_)
    )
}

fn statement_writes_under_query_only(statement: &Statement) -> bool {
    matches!(
        statement,
        Statement::Insert(_)
            | Statement::Update(_)
            | Statement::Delete(_)
            | Statement::CreateTable(_)
            | Statement::CreateVirtualTable(_)
            | Statement::CreateView(_)
            | Statement::CreateTrigger(_)
            | Statement::Drop(_)
            | Statement::AlterTable(_)
            | Statement::CreateIndex(_)
            | Statement::Analyze(_)
            | Statement::Reindex(_)
            | Statement::Vacuum(_)
    ) || matches!(
        statement,
        Statement::Pragma(pragma)
            if pragma.value.is_some()
                && [
                    "user_version",
                    "application_id",
                    "schema_version",
                    "auto_vacuum",
                ]
                .iter()
                .any(|name| pragma.name.name.eq_ignore_ascii_case(name))
    )
}

fn eqp_detail_is_scan_or_search(detail: &str) -> bool {
    detail.starts_with("SCAN ") || detail.starts_with("SEARCH ")
}

fn first_source_eqp_detail_from_table_or_subquery(source: &TableOrSubquery) -> Option<String> {
    match source {
        TableOrSubquery::Table { name, .. } => Some(format!("SCAN {}", name.name)),
        TableOrSubquery::TableFunction { name, alias, .. } => {
            let source_name = alias.as_deref().unwrap_or(name);
            Some(format!("SCAN {source_name} VIRTUAL TABLE INDEX 1:"))
        }
        TableOrSubquery::Subquery { query, .. } => {
            first_source_eqp_detail_from_core(&query.body.select)
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            first_source_eqp_detail_from_from_clause(from_clause)
        }
    }
}

/// `EXPLAIN QUERY PLAN` detail for an aggregate whose emitted program seeks an index.
///
/// bd-2dgf5 / bd-jyyae. The *decision* — SEARCH vs SCAN, COVERING vs not — arrives in
/// `seek`, having been read off the opcodes the program will actually run. Only the
/// names are resolved here: the displayed source comes from the FROM clause and the
/// key column from the schema. Nothing in this function re-decides the access path,
/// which is the whole point: a second copy of codegen's gates is exactly how EQP text
/// and the emitted program drift apart.
fn aggregate_index_seek_eqp_detail(
    select: &SelectStatement,
    seek: &crate::explain::AggregateIndexSeek,
    schema: &[TableSchema],
) -> Option<String> {
    let SelectCore::Select { from, .. } = &select.body.select else {
        return None;
    };
    let TableOrSubquery::Table { name, alias, .. } = &from.as_ref()?.source else {
        return None;
    };
    let table = schema
        .iter()
        .find(|candidate| candidate.name.eq_ignore_ascii_case(&name.name))?;
    let index = table
        .indexes
        .iter()
        .find(|candidate| candidate.name.eq_ignore_ascii_case(&seek.index_name))?;
    let key_column = index.columns.first()?;
    let displayed = alias.as_deref().unwrap_or(&table.name);
    let covering = if seek.covering { "COVERING " } else { "" };
    Some(format!(
        "SEARCH {displayed} USING {covering}INDEX {} ({key_column}=?)",
        index.name
    ))
}

fn first_source_eqp_detail_from_from_clause(from_clause: &FromClause) -> Option<String> {
    first_source_eqp_detail_from_table_or_subquery(&from_clause.source).or_else(|| {
        from_clause
            .joins
            .iter()
            .find_map(|join| first_source_eqp_detail_from_table_or_subquery(&join.table))
    })
}

fn table_or_subquery_is_or_wraps_table_function(source: &TableOrSubquery) -> bool {
    match source {
        TableOrSubquery::TableFunction { .. } => true,
        TableOrSubquery::Subquery { query, .. } => match &query.body.select {
            SelectCore::Select { from, .. } => from.as_ref().is_some_and(|from_clause| {
                table_or_subquery_is_or_wraps_table_function(&from_clause.source)
            }),
            SelectCore::Values(_) => false,
        },
        TableOrSubquery::ParenJoin(from_clause) => {
            table_or_subquery_is_or_wraps_table_function(&from_clause.source)
        }
        TableOrSubquery::Table { .. } => false,
    }
}

/// `true` when every `ORDER BY` term references only the implicit `rowid`
/// alias (`rowid`/`oid`/`_rowid_`). SQLite's virtual-table scan already yields
/// rows in `rowid` order, so such an `ORDER BY` is satisfied by the scan and
/// does NOT add a temp B-tree. Any other column does, because json_each /
/// json_tree report (via xBestIndex INDEX 1) that they cannot satisfy ordering
/// on their declared columns.
fn order_by_is_only_implicit_rowid(order_by: &[OrderingTerm]) -> bool {
    order_by.iter().all(|term| match &term.expr {
        Expr::Column(column_ref, _) => {
            let name = column_ref.column.as_ref();
            name.eq_ignore_ascii_case("rowid")
                || name.eq_ignore_ascii_case("oid")
                || name.eq_ignore_ascii_case("_rowid_")
        }
        _ => false,
    })
}

fn select_requires_temp_btree_fallback_for_order_by(select: &SelectStatement) -> bool {
    if select.order_by.is_empty() {
        return false;
    }
    // A virtual-table scan delivers rows in rowid order; ordering purely by the
    // rowid alias is satisfied without a sorter (matches SQLite's EXPLAIN QUERY
    // PLAN, which omits "USE TEMP B-TREE FOR ORDER BY" for `ORDER BY rowid`).
    if order_by_is_only_implicit_rowid(&select.order_by) {
        return false;
    }
    let SelectCore::Select {
        from: Some(from_clause),
        ..
    } = &select.body.select
    else {
        return false;
    };
    table_or_subquery_is_or_wraps_table_function(&from_clause.source)
}

/// Build a fallback EXPLAIN QUERY PLAN detail for the first FROM source.
fn first_source_eqp_detail_from_core(core: &SelectCore) -> Option<String> {
    match core {
        SelectCore::Select { from, .. } => from
            .as_ref()
            .and_then(first_source_eqp_detail_from_from_clause),
        SelectCore::Values(_) => None,
    }
}

fn planner_needed_columns(
    columns: &[ResultColumn],
    table_name: &str,
    table_alias: Option<&str>,
) -> Option<Vec<String>> {
    let mut needed = Vec::with_capacity(columns.len());
    for column in columns {
        let ResultColumn::Expr { expr, .. } = column else {
            return None;
        };
        let Expr::Column(column_ref, _) = expr else {
            return None;
        };
        if let Some(qualifier) = column_ref.table.as_deref()
            && !qualifier.eq_ignore_ascii_case(table_name)
            && !table_alias.is_some_and(|alias| qualifier.eq_ignore_ascii_case(alias))
        {
            return None;
        }
        needed.push(column_ref.column.to_string());
    }
    Some(needed)
}

fn planner_where_column_matches(
    column: &fsqlite_planner::WhereColumn,
    table_name: &str,
    table_alias: Option<&str>,
    expected_column: &str,
) -> bool {
    column.column.eq_ignore_ascii_case(expected_column)
        && column.table.as_deref().is_none_or(|qualifier| {
            qualifier.eq_ignore_ascii_case(table_name)
                || table_alias.is_some_and(|alias| qualifier.eq_ignore_ascii_case(alias))
        })
}

fn planner_promote_ipk_equality_terms(
    where_terms: &mut [fsqlite_planner::WhereTerm<'_>],
    table_name: &str,
    table_alias: Option<&str>,
    ipk_column_name: &str,
) -> bool {
    let mut promoted = false;
    for term in where_terms {
        if !matches!(term.kind, WhereTermKind::Equality) {
            continue;
        }
        let matches_ipk = term.column.as_ref().is_some_and(|column| {
            planner_where_column_matches(column, table_name, table_alias, ipk_column_name)
        });
        if matches_ipk {
            term.kind = WhereTermKind::RowidEquality;
            promoted = true;
        }
    }
    promoted
}

fn planner_directive_index_column(
    table: &TableSchema,
    table_alias: Option<&str>,
    where_terms: &[fsqlite_planner::WhereTerm<'_>],
    index_name: &str,
) -> Option<String> {
    let index = table
        .indexes
        .iter()
        .find(|candidate| candidate.name.eq_ignore_ascii_case(index_name))?;
    let leading_column = index.columns.first()?.clone();
    where_terms.iter().find_map(|term| {
        term.column.as_ref().and_then(|column| {
            planner_where_column_matches(column, &table.name, table_alias, &leading_column)
                .then_some(leading_column.clone())
        })
    })
}

fn planner_directive_index_key_label(index: &IndexSchema) -> Option<String> {
    index.key_term_sql(0).map(str::to_owned)
}

fn planner_directive_index_is_expression(index: &IndexSchema) -> bool {
    index.columns.is_empty() && !index.key_expressions.is_empty()
}

fn planner_collation_is_binary(collation: Option<&str>) -> bool {
    collation.is_none_or(|name| name.trim().eq_ignore_ascii_case("BINARY"))
}

fn planner_collations_equivalent(left: Option<&str>, right: Option<&str>) -> bool {
    match (
        left.filter(|name| !name.trim().eq_ignore_ascii_case("BINARY")),
        right.filter(|name| !name.trim().eq_ignore_ascii_case("BINARY")),
    ) {
        (None, None) => true,
        (Some(left), Some(right)) => left.trim().eq_ignore_ascii_case(right.trim()),
        (None, Some(_)) | (Some(_), None) => false,
    }
}

fn select_where_contains_explicit_collate(select: &SelectStatement) -> bool {
    matches!(
        &select.body.select,
        SelectCore::Select {
            where_clause: Some(where_clause),
            ..
        } if expr_contains_explicit_collate(where_clause)
    )
}

fn expr_contains_explicit_collate(expr: &Expr) -> bool {
    match expr {
        Expr::Collate { .. } => true,
        Expr::BinaryOp { left, right, .. } => {
            expr_contains_explicit_collate(left) || expr_contains_explicit_collate(right)
        }
        Expr::UnaryOp { expr, .. } | Expr::Cast { expr, .. } | Expr::IsNull { expr, .. } => {
            expr_contains_explicit_collate(expr)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_contains_explicit_collate(expr)
                || expr_contains_explicit_collate(low)
                || expr_contains_explicit_collate(high)
        }
        Expr::In { expr, set, .. } => {
            expr_contains_explicit_collate(expr)
                || matches!(
                    set,
                    InSet::List(values) if values.iter().any(expr_contains_explicit_collate)
                )
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            matches!(
                args,
                FunctionArgs::List(values)
                    if values.iter().any(expr_contains_explicit_collate)
            ) || order_by
                .iter()
                .any(|term| expr_contains_explicit_collate(&term.expr))
                || filter
                    .as_deref()
                    .is_some_and(expr_contains_explicit_collate)
                || over.as_ref().is_some_and(|window| {
                    window
                        .partition_by
                        .iter()
                        .any(expr_contains_explicit_collate)
                        || window
                            .order_by
                            .iter()
                            .any(|term| expr_contains_explicit_collate(&term.expr))
                })
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(expr_contains_explicit_collate)
                || whens.iter().any(|(condition, value)| {
                    expr_contains_explicit_collate(condition)
                        || expr_contains_explicit_collate(value)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(expr_contains_explicit_collate)
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_contains_explicit_collate(expr)
                || expr_contains_explicit_collate(pattern)
                || escape
                    .as_deref()
                    .is_some_and(expr_contains_explicit_collate)
        }
        Expr::JsonAccess { expr, path, .. } => {
            expr_contains_explicit_collate(expr) || expr_contains_explicit_collate(path)
        }
        Expr::RowValue(values, _) => values.iter().any(expr_contains_explicit_collate),
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _)
        | Expr::Subquery(_, _)
        | Expr::Exists { .. } => false,
    }
}

fn expr_contains_function_call(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall { .. } => true,
        Expr::BinaryOp { left, right, .. } => {
            expr_contains_function_call(left) || expr_contains_function_call(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => expr_contains_function_call(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_contains_function_call(expr)
                || expr_contains_function_call(low)
                || expr_contains_function_call(high)
        }
        Expr::In { expr, set, .. } => {
            expr_contains_function_call(expr)
                || match set {
                    InSet::List(values) => values.iter().any(expr_contains_function_call),
                    // Subqueries are not legal in partial-index predicates.
                    // Treat one as unsafe if malformed legacy metadata reaches
                    // this final directive gate.
                    InSet::Subquery(_) => true,
                    InSet::Table(_) => false,
                }
        }
        // LIKE-family operators dispatch through replaceable scalar-function
        // slots (`like`, `glob`, `match`, and `regexp`). A partial-index
        // directive compiled before one of those slots is replaced can become
        // semantically stale even when neither operand contains an explicit
        // FunctionCall node.
        Expr::Like { .. } => true,
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_deref().is_some_and(expr_contains_function_call)
                || whens.iter().any(|(when, then)| {
                    expr_contains_function_call(when) || expr_contains_function_call(then)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(expr_contains_function_call)
        }
        // JSON operators dispatch through replaceable `->`/`->>` scalar
        // slots, so the operator itself is a function call even when both
        // operands are literals or columns.
        Expr::JsonAccess { .. } => true,
        Expr::RowValue(values, _) => values.iter().any(expr_contains_function_call),
        Expr::Exists { .. } | Expr::Subquery(..) => true,
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Placeholder(_, _)
        | Expr::Raise { .. } => false,
    }
}

fn planner_directive_expression_matches_index_key(
    query: &Expr,
    key: &Expr,
    table_name: &str,
    table_alias: Option<&str>,
) -> bool {
    let mut normalized_query = query.clone();
    let mut normalized_key = key.clone();
    planner_normalize_expression_index_columns(&mut normalized_query, table_name, table_alias)
        && planner_normalize_expression_index_columns(&mut normalized_key, table_name, table_alias)
        && normalized_query == normalized_key
}

/// Canonicalize table-local columns before structural expression matching.
///
/// Index definitions are parsed independently from the SELECT and normally
/// contain bare columns. Query expressions can refer to the same columns
/// through either the table name or its visible alias. Strip only those local
/// qualifiers and fold column identifiers to SQLite's case-insensitive form.
/// Foreign qualifiers and nested scopes fail closed.
fn planner_normalize_expression_index_columns(
    expr: &mut Expr,
    table_name: &str,
    table_alias: Option<&str>,
) -> bool {
    let normalize =
        |expr: &mut Expr| planner_normalize_expression_index_columns(expr, table_name, table_alias);
    match expr {
        Expr::BoundOuterValue { .. } => false,
        Expr::Literal(..) | Expr::Placeholder(..) => true,
        Expr::Column(column, _) => {
            if column.table.as_deref().is_some_and(|qualifier| {
                !qualifier.eq_ignore_ascii_case(table_name)
                    && !table_alias.is_some_and(|alias| qualifier.eq_ignore_ascii_case(alias))
            }) {
                return false;
            }
            column.table = None;
            column.column = column.column.to_ascii_lowercase().into();
            true
        }
        Expr::BinaryOp { left, right, .. }
        | Expr::JsonAccess {
            expr: left,
            path: right,
            ..
        } => normalize(left) && normalize(right),
        Expr::UnaryOp { expr, .. } | Expr::Collate { expr, .. } | Expr::IsNull { expr, .. } => {
            normalize(expr)
        }
        Expr::Cast {
            expr, type_name, ..
        } => {
            type_name.name.make_ascii_lowercase();
            if let Some(arg) = &mut type_name.arg1 {
                arg.make_ascii_lowercase();
            }
            if let Some(arg) = &mut type_name.arg2 {
                arg.make_ascii_lowercase();
            }
            normalize(expr)
        }
        Expr::Between {
            expr, low, high, ..
        } => normalize(expr) && normalize(low) && normalize(high),
        Expr::In { expr, set, .. } => {
            normalize(expr)
                && match set {
                    InSet::List(items) => items.iter_mut().all(normalize),
                    InSet::Subquery(_) | InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => normalize(expr) && normalize(pattern) && escape.as_deref_mut().is_none_or(normalize),
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand.as_deref_mut().is_none_or(normalize)
                && whens
                    .iter_mut()
                    .all(|(when, then)| normalize(when) && normalize(then))
                && else_expr.as_deref_mut().is_none_or(normalize)
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let args_local = match args {
                FunctionArgs::Star => false,
                FunctionArgs::List(args) => args.iter_mut().all(normalize),
            };
            args_local
                && order_by.iter_mut().all(|term| normalize(&mut term.expr))
                && filter.as_deref_mut().is_none_or(normalize)
                && over.is_none()
        }
        Expr::RowValue(items, _) => items.iter_mut().all(normalize),
        Expr::Exists { .. } | Expr::Subquery(..) | Expr::Raise { .. } => false,
    }
}

fn planner_directive_expression_index_equality_target(
    where_clause: Option<&Expr>,
    index: &IndexSchema,
    table_name: &str,
    table_alias: Option<&str>,
) -> Option<Expr> {
    let root = where_clause?;
    let key_expr = fsqlite_parser::expr::parse_expr(index.key_term_sql(0)?).ok()?;

    // Equality probes may sit beside the predicate guaranteed by a partial
    // index. Walk only AND conjuncts: descending through OR would incorrectly
    // turn a conditional probe into a mandatory one. Any other residual must
    // fail closed because the directive equality emitter does not evaluate
    // arbitrary residuals on its fast path.
    let mut pending = SmallVec::<[&Expr; 8]>::new();
    let mut residuals = SmallVec::<[&Expr; 8]>::new();
    let mut target = None;
    pending.push(root);
    while let Some(expr) = pending.pop() {
        let Expr::BinaryOp {
            left, op, right, ..
        } = expr
        else {
            residuals.push(expr);
            continue;
        };
        if *op == BinaryOp::And {
            pending.push(right);
            pending.push(left);
            continue;
        }
        if *op != BinaryOp::Eq {
            residuals.push(expr);
            continue;
        }
        let candidate = if planner_directive_expression_matches_index_key(
            left,
            &key_expr,
            table_name,
            table_alias,
        ) && planner_directive_index_probe_constant(right)
        {
            Some(right.as_ref().clone())
        } else if planner_directive_expression_matches_index_key(
            right,
            &key_expr,
            table_name,
            table_alias,
        ) && planner_directive_index_probe_constant(left)
        {
            Some(left.as_ref().clone())
        } else {
            None
        };
        if let Some(candidate) = candidate {
            if target.replace(candidate).is_some() {
                return None;
            }
        } else {
            residuals.push(expr);
        }
    }
    target.filter(|_| {
        planner_expression_index_residuals_match(&residuals, index, table_name, table_alias)
    })
}

fn planner_directive_expression_index_range_target(
    where_clause: Option<&Expr>,
    index: &IndexSchema,
    table_name: &str,
    table_alias: Option<&str>,
) -> Option<PlannerIndexRangeTarget> {
    let expr = where_clause?;
    let key_expr = fsqlite_parser::expr::parse_expr(index.key_term_sql(0)?).ok()?;
    let mut target = PlannerIndexRangeTarget::default();
    let mut residuals = SmallVec::<[&Expr; 8]>::new();
    if planner_collect_expression_index_range_bounds(
        expr,
        &key_expr,
        table_name,
        table_alias,
        &mut target,
        &mut residuals,
    ) && (target.lower.is_some() || target.upper.is_some())
        && planner_expression_index_residuals_match(&residuals, index, table_name, table_alias)
    {
        Some(target)
    } else {
        None
    }
}

fn planner_collect_expression_index_range_bounds<'a>(
    root: &'a Expr,
    key_expr: &Expr,
    table_name: &str,
    table_alias: Option<&str>,
    target: &mut PlannerIndexRangeTarget,
    residuals: &mut SmallVec<[&'a Expr; 8]>,
) -> bool {
    let mut found_bound = false;
    let mut pending = SmallVec::<[&Expr; 8]>::new();
    pending.push(root);
    while let Some(expr) = pending.pop() {
        if let Expr::BinaryOp {
            left,
            op: BinaryOp::And,
            right,
            ..
        } = expr
        {
            pending.push(right);
            pending.push(left);
            continue;
        }

        if let Expr::BinaryOp {
            left, op, right, ..
        } = expr
            && let Some((slot, bound)) = planner_extract_expression_index_range_bound(
                left,
                *op,
                right,
                key_expr,
                table_name,
                table_alias,
            )
        {
            if !planner_assign_expression_index_range_bound(target, slot, bound) {
                return false;
            }
            found_bound = true;
            continue;
        }

        if let Expr::Between {
            expr: operand,
            low,
            high,
            not: false,
            ..
        } = expr
            && planner_directive_expression_matches_index_key(
                operand,
                key_expr,
                table_name,
                table_alias,
            )
            && planner_directive_index_range_constant(low)
            && planner_directive_index_range_constant(high)
        {
            if !planner_assign_expression_index_range_bound(
                target,
                PlannerExpressionIndexRangeSlot::Lower,
                PlannerIndexRangeBound {
                    expr: low.as_ref().clone(),
                    inclusive: true,
                },
            ) || !planner_assign_expression_index_range_bound(
                target,
                PlannerExpressionIndexRangeSlot::Upper,
                PlannerIndexRangeBound {
                    expr: high.as_ref().clone(),
                    inclusive: true,
                },
            ) {
                return false;
            }
            found_bound = true;
            continue;
        }
        residuals.push(expr);
    }
    found_bound
}

fn planner_expression_index_residuals_match(
    residuals: &[&Expr],
    index: &IndexSchema,
    table_name: &str,
    table_alias: Option<&str>,
) -> bool {
    let Some(predicate_sql) = index.where_clause.as_deref() else {
        return residuals.is_empty();
    };
    let Ok(predicate) = fsqlite_parser::expr::parse_expr(predicate_sql) else {
        return false;
    };
    let predicate_terms = decompose_where(&predicate);

    predicate_terms.iter().all(|predicate_term| {
        residuals.iter().any(|residual| {
            planner_directive_expression_matches_index_key(
                residual,
                predicate_term,
                table_name,
                table_alias,
            )
        })
    }) && residuals.iter().all(|residual| {
        predicate_terms.iter().any(|predicate_term| {
            planner_directive_expression_matches_index_key(
                residual,
                predicate_term,
                table_name,
                table_alias,
            )
        })
    })
}

#[derive(Clone, Copy)]
enum PlannerExpressionIndexRangeSlot {
    Lower,
    Upper,
}

fn planner_extract_expression_index_range_bound(
    left: &Expr,
    op: BinaryOp,
    right: &Expr,
    key_expr: &Expr,
    table_name: &str,
    table_alias: Option<&str>,
) -> Option<(PlannerExpressionIndexRangeSlot, PlannerIndexRangeBound)> {
    use BinaryOp::{Ge, Gt, Le, Lt};

    if planner_directive_expression_matches_index_key(left, key_expr, table_name, table_alias)
        && planner_directive_index_range_constant(right)
    {
        return match op {
            Ge => Some((
                PlannerExpressionIndexRangeSlot::Lower,
                PlannerIndexRangeBound {
                    expr: right.clone(),
                    inclusive: true,
                },
            )),
            Gt => Some((
                PlannerExpressionIndexRangeSlot::Lower,
                PlannerIndexRangeBound {
                    expr: right.clone(),
                    inclusive: false,
                },
            )),
            Le => Some((
                PlannerExpressionIndexRangeSlot::Upper,
                PlannerIndexRangeBound {
                    expr: right.clone(),
                    inclusive: true,
                },
            )),
            Lt => Some((
                PlannerExpressionIndexRangeSlot::Upper,
                PlannerIndexRangeBound {
                    expr: right.clone(),
                    inclusive: false,
                },
            )),
            _ => None,
        };
    }

    if planner_directive_expression_matches_index_key(right, key_expr, table_name, table_alias)
        && planner_directive_index_range_constant(left)
    {
        return match op {
            Le => Some((
                PlannerExpressionIndexRangeSlot::Lower,
                PlannerIndexRangeBound {
                    expr: left.clone(),
                    inclusive: true,
                },
            )),
            Lt => Some((
                PlannerExpressionIndexRangeSlot::Lower,
                PlannerIndexRangeBound {
                    expr: left.clone(),
                    inclusive: false,
                },
            )),
            Ge => Some((
                PlannerExpressionIndexRangeSlot::Upper,
                PlannerIndexRangeBound {
                    expr: left.clone(),
                    inclusive: true,
                },
            )),
            Gt => Some((
                PlannerExpressionIndexRangeSlot::Upper,
                PlannerIndexRangeBound {
                    expr: left.clone(),
                    inclusive: false,
                },
            )),
            _ => None,
        };
    }

    None
}

fn planner_assign_expression_index_range_bound(
    target: &mut PlannerIndexRangeTarget,
    slot: PlannerExpressionIndexRangeSlot,
    bound: PlannerIndexRangeBound,
) -> bool {
    let target_slot = match slot {
        PlannerExpressionIndexRangeSlot::Lower => &mut target.lower,
        PlannerExpressionIndexRangeSlot::Upper => &mut target.upper,
    };
    if target_slot.is_some() {
        false
    } else {
        *target_slot = Some(bound);
        true
    }
}

fn planner_directive_index_probe_constant(expr: &Expr) -> bool {
    matches!(expr, Expr::Placeholder(..) | Expr::Literal(..))
}

fn planner_directive_index_range_constant(expr: &Expr) -> bool {
    planner_directive_index_probe_constant(expr)
        || matches!(
            expr,
            Expr::UnaryOp {
                op: fsqlite_ast::UnaryOp::Negate,
                expr,
                ..
            } if matches!(
                expr.as_ref(),
                Expr::Literal(Literal::Integer(_) | Literal::Float(_), _)
            )
        )
}

type PlannerDirectiveAccessSpec = (
    PlannerSelectAccessKind,
    String,
    bool,
    Option<Expr>,
    Option<PlannerIndexRangeTarget>,
);

fn planner_directive_covering_access_kind(
    table: &TableSchema,
    table_alias: Option<&str>,
    where_clause: Option<&Expr>,
    where_terms: &[fsqlite_planner::WhereTerm<'_>],
    index_name: &str,
) -> Option<PlannerDirectiveAccessSpec> {
    let index = table
        .indexes
        .iter()
        .find(|candidate| candidate.name.eq_ignore_ascii_case(index_name))?;
    if planner_directive_index_is_expression(index) {
        let index_key_label = planner_directive_index_key_label(index)?;
        if let Some(target) = planner_directive_expression_index_equality_target(
            where_clause,
            index,
            &table.name,
            table_alias,
        ) {
            return Some((
                PlannerSelectAccessKind::IndexEquality,
                index_key_label,
                true,
                Some(target),
                None,
            ));
        }
        if let Some(target) = planner_directive_expression_index_range_target(
            where_clause,
            index,
            &table.name,
            table_alias,
        ) {
            return Some((
                PlannerSelectAccessKind::IndexRange,
                index_key_label,
                true,
                None,
                Some(target),
            ));
        }
        return None;
    }

    let index_column = planner_directive_index_column(table, table_alias, where_terms, index_name)?;
    let mut saw_equality = false;
    let mut saw_range = false;
    for term in where_terms {
        let Some(column) = term.column.as_ref() else {
            continue;
        };
        if !planner_where_column_matches(column, &table.name, table_alias, &index_column) {
            continue;
        }
        match &term.kind {
            WhereTermKind::Equality => saw_equality = true,
            WhereTermKind::Range | WhereTermKind::Between | WhereTermKind::LikePrefix { .. } => {
                saw_range = true;
            }
            _ => {}
        }
    }
    if saw_equality {
        Some((
            PlannerSelectAccessKind::IndexEquality,
            index_column,
            false,
            None,
            None,
        ))
    } else if saw_range {
        Some((
            PlannerSelectAccessKind::IndexRange,
            index_column,
            false,
            None,
            None,
        ))
    } else {
        None
    }
}

fn explain_query_plan_detail_from_directive(directive: &SelectPlannerDirective) -> String {
    let index_key_label = if directive.index_key_is_expression {
        "<expr>"
    } else {
        directive.index_key_label.as_deref().unwrap_or("(expr)")
    };
    match directive.access_kind {
        PlannerSelectAccessKind::FullTableScan => format!("SCAN {}", directive.table_name),
        PlannerSelectAccessKind::RowidLookup => {
            format!(
                "SEARCH {} USING INTEGER PRIMARY KEY (rowid=?)",
                directive.table_name
            )
        }
        PlannerSelectAccessKind::IndexEquality => format!(
            "SEARCH {} USING {}INDEX {} ({}=?)",
            directive.table_name,
            if directive.covering { "COVERING " } else { "" },
            directive.index_name.as_deref().unwrap_or("(unknown)"),
            index_key_label,
        ),
        PlannerSelectAccessKind::IndexRange => format!(
            "SEARCH {} USING {}INDEX {} ({} range)",
            directive.table_name,
            if directive.covering { "COVERING " } else { "" },
            directive.index_name.as_deref().unwrap_or("(unknown)"),
            index_key_label,
        ),
    }
}

/// Process-wide placeholder `VdbeProgram` shared across all prepared
/// statements that don't compile to real bytecode (the SELECT-dispatch
/// and deferred paths hand this to the `PreparedStatement::program`
/// field as a filler).
///
/// `ProgramBuilder::new().finish()` is a pure constant — an empty `ops`
/// SmallVec, zero labels, zero bind parameters, zero registers. Before
/// caching it, `build_placeholder_program()` was invoked from five
/// distinct `prepare()` branches and showed up as 2.66% self-time of
/// `__memmove_avx_unaligned_erms` on the 2026-04-23 MT 8t DWARF capture
/// (`fsqlite-memmove-dwarf-213322`), with the memcpy coming from
/// `Arc::new(VdbeProgram { .. })` moving the struct into a fresh arc
/// allocation every call.
///
/// The cached arc is cloned on each call — a single atomic refcount inc
/// instead of a full allocation + struct memcpy.
static PLACEHOLDER_PROGRAM: OnceLock<Arc<VdbeProgram>> = OnceLock::new();

fn build_placeholder_program() -> Result<Arc<VdbeProgram>> {
    if let Some(cached) = PLACEHOLDER_PROGRAM.get() {
        return Ok(Arc::clone(cached));
    }
    let program = ProgramBuilder::new()
        .finish()
        .map_err(|e| FrankenError::Internal(format!("failed to build placeholder program: {e}")))?;
    let arc = Arc::new(program);
    // If another thread raced ahead and populated the OnceLock, prefer its
    // arc and drop ours; either way the returned clone is authoritative.
    let canonical = PLACEHOLDER_PROGRAM.get_or_init(|| arc);
    Ok(Arc::clone(canonical))
}

/// Hex-encode a byte slice (lowercase).
fn hex_encode(bytes: &[u8]) -> String {
    use std::fmt::Write;
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        let _ = write!(s, "{b:02x}");
    }
    s
}

async fn execute_program_with_row_cap(
    program: &VdbeProgram,
    params: Option<&[SqliteValue]>,
    func_registry: Option<&Arc<FunctionRegistry>>,
    collation_registry: Option<&Arc<Mutex<CollationRegistry>>>,
    execution_cx: &Cx,
    page_size: PageSize,
    max_collected_result_rows: Option<usize>,
) -> Result<Vec<Row>> {
    let mut engine =
        VdbeEngine::new_with_execution_cx(program.register_count(), execution_cx, page_size);
    if let Some(params) = params {
        validate_bound_parameters(program, params)?;
    }
    if let Some(registry) = func_registry {
        engine.set_function_registry(Arc::clone(registry));
    }
    if let Some(registry) = collation_registry {
        engine.set_collation_registry(Arc::clone(registry));
    }
    engine.set_max_collected_result_rows(max_collected_result_rows);

    let exec_outcome = if let Some(params) = params {
        engine
            .execute_with_borrowed_bindings(program, Some(params))
            .await?
    } else {
        engine.execute(program).await?
    };

    match exec_outcome {
        ExecOutcome::Done => Ok(engine
            .take_results()
            .into_iter()
            .map(|values| Row {
                values: values.into_vec(),
            })
            .collect()),
        ExecOutcome::Error { code, message } => Err(FrankenError::Internal(format!(
            "VDBE halted with code {code}: {message}",
        ))),
    }
}

async fn execute_program_with_postprocess(
    program: &VdbeProgram,
    params: Option<&[SqliteValue]>,
    func_registry: Option<&Arc<FunctionRegistry>>,
    collation_registry: Option<&Arc<Mutex<CollationRegistry>>>,
    execution_cx: &Cx,
    expression_postprocess: Option<&ExpressionPostprocess>,
    page_size: PageSize,
) -> Result<Vec<Row>> {
    execute_program_with_postprocess_row_cap(
        program,
        params,
        func_registry,
        collation_registry,
        execution_cx,
        expression_postprocess,
        page_size,
        None,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn execute_program_with_postprocess_row_cap(
    program: &VdbeProgram,
    params: Option<&[SqliteValue]>,
    func_registry: Option<&Arc<FunctionRegistry>>,
    collation_registry: Option<&Arc<Mutex<CollationRegistry>>>,
    execution_cx: &Cx,
    expression_postprocess: Option<&ExpressionPostprocess>,
    page_size: PageSize,
    max_collected_result_rows: Option<usize>,
) -> Result<Vec<Row>> {
    let mut rows = execute_program_with_row_cap(
        program,
        params,
        func_registry,
        collation_registry,
        execution_cx,
        page_size,
        max_collected_result_rows,
    )
    .await?;
    if let Some(postprocess) = expression_postprocess {
        apply_expression_postprocess(&mut rows, postprocess)?;
    }
    Ok(rows)
}

async fn execute_program_exactly_one_row_with_row_cap(
    program: &VdbeProgram,
    params: Option<&[SqliteValue]>,
    func_registry: Option<&Arc<FunctionRegistry>>,
    collation_registry: Option<&Arc<Mutex<CollationRegistry>>>,
    execution_cx: &Cx,
    page_size: PageSize,
    max_collected_result_rows: Option<usize>,
) -> Result<Row> {
    let mut engine =
        VdbeEngine::new_with_execution_cx(program.register_count(), execution_cx, page_size);
    if let Some(params) = params {
        validate_bound_parameters(program, params)?;
    }
    if let Some(registry) = func_registry {
        engine.set_function_registry(Arc::clone(registry));
    }
    if let Some(registry) = collation_registry {
        engine.set_collation_registry(Arc::clone(registry));
    }
    engine.set_max_collected_result_rows(max_collected_result_rows);

    let exec_outcome = if let Some(params) = params {
        engine
            .execute_with_borrowed_bindings(program, Some(params))
            .await?
    } else {
        engine.execute(program).await?
    };

    match exec_outcome {
        ExecOutcome::Done => match take_exactly_one_engine_row(&mut engine) {
            QueryRowCollectionOutcome::Row(row) => Ok(row),
            QueryRowCollectionOutcome::NoRows => Err(FrankenError::QueryReturnedNoRows),
            QueryRowCollectionOutcome::MultipleRows => Err(FrankenError::QueryReturnedMultipleRows),
        },
        ExecOutcome::Error { code, message } => Err(FrankenError::Internal(format!(
            "VDBE halted with code {code}: {message}",
        ))),
    }
}

/// MVCC concurrent context for page-level locking (bd-kivg / 5E.2).
/// Passed to `execute_table_program_with_db` when in concurrent mode.
struct ConcurrentExecContext {
    session_id: u64,
    handle: SharedConcurrentHandle,
    lock_table: Arc<InProcessPageLockTable>,
    commit_index: Arc<CommitIndex>,
    rowid_allocator: Arc<ConcurrentRowIdAllocator>,
    schema_epoch: SchemaEpoch,
    busy_timeout_ms: u64,
}

/// Minimal MVCC context for direct B-tree DML.
///
/// The direct INSERT/UPDATE/DELETE fast paths only need enough state to wrap
/// the active pager transaction in `SharedTxnPageIo`. They never enter VDBE
/// rowid allocation, so carrying `ConcurrentExecContext` there paid for an
/// extra allocator `Arc` clone plus schema-cookie read on every row.
struct ConcurrentPageIoContext {
    session_id: u64,
    handle: SharedConcurrentHandle,
    lock_table: Arc<InProcessPageLockTable>,
    commit_index: Arc<CommitIndex>,
    busy_timeout_ms: u64,
}

#[derive(Debug, Clone, Copy)]
struct TableProgramErrorState {
    changes: usize,
    last_insert_rowid: Option<i64>,
    rollback_visible_total_changes: usize,
    force_statement_rollback: bool,
}

#[derive(Debug)]
struct TableProgramExecError {
    error: FrankenError,
    changes: usize,
    last_insert_rowid: Option<i64>,
}

type TableProgramExecResult =
    std::result::Result<(Vec<Row>, usize, Option<i64>), TableProgramExecError>;
type TableProgramExecOutcome = (TableProgramExecResult, Option<TransactionKind>);
type TableProgramSingleRowExecResult =
    std::result::Result<(QueryRowCollectionOutcome, usize, Option<i64>), TableProgramExecError>;
type TableProgramSingleRowExecOutcome = (TableProgramSingleRowExecResult, Option<TransactionKind>);

fn take_exactly_one_engine_row(engine: &mut VdbeEngine) -> QueryRowCollectionOutcome {
    match engine.take_exactly_one_result_row() {
        ExactResultRowOutcome::NoRows => QueryRowCollectionOutcome::NoRows,
        ExactResultRowOutcome::Row(values) => QueryRowCollectionOutcome::Row(Row {
            values: (*values).into_vec(),
        }),
        ExactResultRowOutcome::MultipleRows => QueryRowCollectionOutcome::MultipleRows,
    }
}

// bd-perf: Reusable MemDatabase placeholder for the db-swap pattern in
// execute_table_program_with_db / execute_table_program_exactly_one_row_with_db.
// Avoids allocating MemDatabase::new() per VDBE execution.
thread_local! {
    static MEMDB_PLACEHOLDER: std::cell::RefCell<Option<MemDatabase>> =
        std::cell::RefCell::new(Some(MemDatabase::new()));
}

#[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
async fn execute_table_program_with_db(
    program: &VdbeProgram,
    params: Option<&[SqliteValue]>,
    func_registry: &Arc<FunctionRegistry>,
    collation_registry: &Arc<Mutex<CollationRegistry>>,
    execution_cx: &Cx,
    db: &Rc<RefCell<MemDatabase>>,
    txn: Option<TransactionKind>,
    schema_cookie: u32,
    concurrent_ctx: Option<ConcurrentExecContext>,
    autoincrement_seq_by_root_page: HbHashMap<i32, i64>,
    rowid_alias_col_by_root_page: Arc<HbHashMap<i32, usize>>,
    table_column_count_by_root_page: Arc<HbHashMap<i32, usize>>,
    first_not_null_non_ipk_col_by_root_page: Arc<HbHashMap<i32, usize>>,
    column_defaults_by_root_page: Arc<HbHashMap<i32, Vec<Option<SqliteValue>>>>,
    index_desc_flags_by_root_page: Arc<HbHashMap<i32, Vec<bool>>>,
    index_collations_by_root_page: Arc<HbHashMap<i32, Vec<Option<String>>>>,
    reject_mem_fallback: bool,
    memdb_rows_loaded: bool,
    storage_cursor_memdb_count_shortcuts_safe: bool,
    version_store: Option<Arc<VersionStore>>,
    page_size: PageSize,
    collect_rows: bool,
    max_collected_result_rows: Option<usize>,
    mut row_handler: Option<&mut QueryRowHandler<'_>>,
    allow_retained_cursor_reuse: bool,
    prepared_engine_reuse_profile: bool,
    cached_engine: Option<VdbeEngine>,
) -> (TableProgramExecOutcome, Option<VdbeEngine>) {
    let execution_span = tracing::enabled!(target: "fsqlite.execution", tracing::Level::DEBUG)
        .then(|| {
            let span = tracing::span!(
                target: "fsqlite.execution",
                tracing::Level::DEBUG,
                "execution",
                mode = "vdbe"
            );
            record_trace_span_created();
            span
        });
    let _execution_guard = execution_span.as_ref().map(tracing::Span::enter);
    // Reuse a cached engine if available (avoids 21+ collection allocations).
    // If no cached engine exists, create a fresh one.
    // bd-perf: When reusing AND a transaction is available AND the engine
    // already has a txn_page_io from a previous retain, keep cursors alive
    // to avoid StorageCursor recreation (~500-1000ns/row). The Rc refill
    // pattern keeps cursor references valid across executions of the SAME
    // prepared statement. On the first call or when the engine has no
    // existing txn_page_io, create fresh cursors.
    let reusing_engine = cached_engine.is_some();
    if prepared_engine_reuse_profile && hot_path_profile_enabled() {
        if reusing_engine {
            FSQLITE_PREPARED_TABLE_ENGINE_REUSES.fetch_add(1, AtomicOrdering::Relaxed);
        } else {
            FSQLITE_PREPARED_TABLE_ENGINE_FRESH_ALLOCS.fetch_add(1, AtomicOrdering::Relaxed);
        }
    }
    let mut engine = if let Some(mut cached) = cached_engine {
        let can_retain = allow_retained_cursor_reuse && txn.is_some() && cached.has_txn_page_io();
        cached.reset_for_reuse_preserving_runtime_setup(
            program.register_count(),
            execution_cx,
            page_size,
            can_retain,
        );
        cached
    } else {
        VdbeEngine::new_with_execution_cx(program.register_count(), execution_cx, page_size)
    };
    engine.set_retain_storage_cursors_on_close(allow_retained_cursor_reuse);
    if let Some(params) = params
        && let Err(e) = validate_bound_parameters(program, params)
    {
        return (
            (
                Err(TableProgramExecError {
                    error: e,
                    changes: 0,
                    last_insert_rowid: None,
                }),
                txn,
            ),
            Some(engine),
        );
    }

    let _setup_outcome = engine.apply_reusable_table_execution_state(ReusableTableExecutionState {
        func_registry: Arc::clone(func_registry),
        collation_registry: Arc::clone(collation_registry),
        schema_cookie,
        autoincrement_seq_by_root_page,
        rowid_alias_col_by_root_page,
        table_column_count_by_root_page,
        first_not_null_non_ipk_col_by_root_page,
        column_defaults_by_root_page,
        index_desc_flags_by_root_page,
        index_collations_by_root_page,
        reject_mem_fallback,
        memdb_rows_loaded,
        storage_cursor_memdb_count_shortcuts_safe,
        version_store,
        collect_result_rows: collect_rows,
        max_collected_result_rows,
    });

    // Phase 5 (bd-2a3y): if a transaction handle is available, lend it to
    // the engine so storage cursors route through the real pager/WAL stack.
    // bd-kivg / 5E.2: if concurrent context is provided, use set_transaction_concurrent
    // to enable MVCC page-level locking.
    // bd-perf: set_transaction* now refills any retained shared txn state in
    // place so cached cursors keep the same Rc while both txn and concurrent
    // metadata are refreshed together.
    if let Some(txn) = txn {
        if let Some(ctx) = concurrent_ctx {
            engine.set_transaction_concurrent(
                txn,
                ctx.session_id,
                ctx.handle,
                ctx.lock_table,
                ctx.commit_index,
                ctx.busy_timeout_ms,
            );
            engine.set_concurrent_rowid_allocator(ctx.rowid_allocator, ctx.schema_epoch);
        } else {
            engine.set_transaction(txn);
        }
    } else {
        engine.enable_storage_read_cursors(true);
    }

    let attach_memdb = !reject_mem_fallback || program.requires_attached_memdb();
    if attach_memdb {
        // Lend the MemDatabase to the engine for the duration of execution.
        // bd-perf: Reuse a thread-local placeholder to avoid MemDatabase::new()
        // allocation per execution. The placeholder is never read — it just
        // satisfies the RefCell while the real DB is in the engine.
        let placeholder = MEMDB_PLACEHOLDER
            .with(|p| p.borrow_mut().take())
            .unwrap_or_else(MemDatabase::new);
        let db_value = db.replace(placeholder);
        engine.set_database(db_value);
    }

    // Always take the DB and txn back, even if execution returns Err.
    let trace_export_enabled =
        tracing::enabled!(target: "fsqlite.trace_export", tracing::Level::DEBUG);
    let export_started = trace_export_enabled.then(fsqlite_types::sync_primitives::Instant::now);
    let exec_res = if let Some(params) = params {
        if let Some(handler) = row_handler.as_mut() {
            engine.set_collect_result_rows(false);
            let mut bridge = |values: SmallVec<[SqliteValue; 16]>| {
                let row = Row {
                    values: values.into_vec(),
                };
                (*handler)(&row)
            };
            engine
                .execute_with_borrowed_bindings_and_row_handler(program, Some(params), &mut bridge)
                .await
        } else {
            engine
                .execute_with_borrowed_bindings(program, Some(params))
                .await
        }
    } else {
        if let Some(handler) = row_handler.as_mut() {
            engine.set_collect_result_rows(false);
            let mut bridge = |values: SmallVec<[SqliteValue; 16]>| {
                let row = Row {
                    values: values.into_vec(),
                };
                (*handler)(&row)
            };
            engine
                .execute_with_borrowed_bindings_and_row_handler(program, None, &mut bridge)
                .await
        } else {
            engine.execute(program).await
        }
    };
    if let Some(export_started) = export_started {
        let export_latency_us =
            u64::try_from(export_started.elapsed().as_micros()).unwrap_or(u64::MAX);
        record_trace_export(1, export_latency_us);
    }
    if exec_res.is_err() || matches!(exec_res, Ok(ExecOutcome::Error { .. })) {
        record_trace_export_error();
    }
    let engine_rowid = engine.last_insert_rowid();

    if attach_memdb && let Some(db_value) = engine.take_database() {
        // bd-perf: Return placeholder to thread-local for reuse.
        let old_placeholder = db.replace(db_value);
        MEMDB_PLACEHOLDER.with(|p| {
            *p.borrow_mut() = Some(old_placeholder);
        });
    }
    // bd-perf: When the engine has a live txn_page_io with retained cursors,
    // drain the txn (keeps Rc alive for cursor refs on next execution).
    // Otherwise take_transaction drops everything cleanly.
    let has_retained_cursors = !engine.storage_cursors_empty() && engine.has_txn_page_io();
    let txn_back = if has_retained_cursors {
        engine.drain_transaction()
    } else {
        match engine.take_transaction() {
            Ok(txn) => txn,
            Err(e) => {
                return (
                    (
                        Err(TableProgramExecError {
                            error: e,
                            changes: engine.changes(),
                            last_insert_rowid: engine_rowid,
                        }),
                        None,
                    ),
                    Some(engine),
                );
            }
        }
    };

    let changes = engine.changes();
    let result = match exec_res {
        Ok(ExecOutcome::Done) => {
            if !collect_rows && hot_path_profile_enabled() {
                FSQLITE_PREPARED_TABLE_DML_AFFECTED_ONLY_RUNS.fetch_add(1, AtomicOrdering::Relaxed);
            }
            let rows = if collect_rows {
                engine
                    .take_results()
                    .into_iter()
                    .map(|values| Row {
                        values: values.into_vec(),
                    })
                    .collect()
            } else {
                Vec::new()
            };
            Ok((rows, changes, engine_rowid))
        }
        Ok(ExecOutcome::Error { code, message }) => Err(TableProgramExecError {
            error: frankenerror_from_vdbe_halt(code, message),
            changes,
            last_insert_rowid: engine_rowid,
        }),
        Err(e) => Err(TableProgramExecError {
            error: e,
            changes,
            last_insert_rowid: engine_rowid,
        }),
    };
    ((result, txn_back), Some(engine))
}

#[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
async fn execute_table_program_exactly_one_row_with_db(
    program: &VdbeProgram,
    params: Option<&[SqliteValue]>,
    func_registry: &Arc<FunctionRegistry>,
    collation_registry: &Arc<Mutex<CollationRegistry>>,
    execution_cx: &Cx,
    db: &Rc<RefCell<MemDatabase>>,
    txn: Option<TransactionKind>,
    schema_cookie: u32,
    concurrent_ctx: Option<ConcurrentExecContext>,
    autoincrement_seq_by_root_page: HbHashMap<i32, i64>,
    rowid_alias_col_by_root_page: Arc<HbHashMap<i32, usize>>,
    table_column_count_by_root_page: Arc<HbHashMap<i32, usize>>,
    first_not_null_non_ipk_col_by_root_page: Arc<HbHashMap<i32, usize>>,
    column_defaults_by_root_page: Arc<HbHashMap<i32, Vec<Option<SqliteValue>>>>,
    index_desc_flags_by_root_page: Arc<HbHashMap<i32, Vec<bool>>>,
    index_collations_by_root_page: Arc<HbHashMap<i32, Vec<Option<String>>>>,
    reject_mem_fallback: bool,
    memdb_rows_loaded: bool,
    storage_cursor_memdb_count_shortcuts_safe: bool,
    version_store: Option<Arc<VersionStore>>,
    page_size: PageSize,
    max_collected_result_rows: usize,
    prepared_engine_reuse_profile: bool,
    cached_engine: Option<VdbeEngine>,
) -> (TableProgramSingleRowExecOutcome, Option<VdbeEngine>) {
    let execution_span = tracing::enabled!(target: "fsqlite.execution", tracing::Level::DEBUG)
        .then(|| {
            let span = tracing::span!(
                target: "fsqlite.execution",
                tracing::Level::DEBUG,
                "execution",
                mode = "vdbe_query_row"
            );
            record_trace_span_created();
            span
        });
    let _execution_guard = execution_span.as_ref().map(tracing::Span::enter);
    let reusing_engine = cached_engine.is_some();
    if prepared_engine_reuse_profile && hot_path_profile_enabled() {
        if reusing_engine {
            FSQLITE_PREPARED_TABLE_ENGINE_REUSES.fetch_add(1, AtomicOrdering::Relaxed);
        } else {
            FSQLITE_PREPARED_TABLE_ENGINE_FRESH_ALLOCS.fetch_add(1, AtomicOrdering::Relaxed);
        }
    }
    let mut engine = if let Some(mut cached) = cached_engine {
        cached.reset_for_reuse_preserving_runtime_setup(
            program.register_count(),
            execution_cx,
            page_size,
            false,
        );
        cached
    } else {
        VdbeEngine::new_with_execution_cx(program.register_count(), execution_cx, page_size)
    };
    if let Some(params) = params
        && let Err(e) = validate_bound_parameters(program, params)
    {
        return (
            (
                Err(TableProgramExecError {
                    error: e,
                    changes: 0,
                    last_insert_rowid: None,
                }),
                txn,
            ),
            Some(engine),
        );
    }

    let _setup_outcome = engine.apply_reusable_table_execution_state(ReusableTableExecutionState {
        func_registry: Arc::clone(func_registry),
        collation_registry: Arc::clone(collation_registry),
        schema_cookie,
        autoincrement_seq_by_root_page,
        rowid_alias_col_by_root_page,
        table_column_count_by_root_page,
        first_not_null_non_ipk_col_by_root_page,
        column_defaults_by_root_page,
        index_desc_flags_by_root_page,
        index_collations_by_root_page,
        reject_mem_fallback,
        memdb_rows_loaded,
        storage_cursor_memdb_count_shortcuts_safe,
        version_store,
        collect_result_rows: true,
        max_collected_result_rows: Some(max_collected_result_rows),
    });

    if let Some(txn) = txn {
        if let Some(ctx) = concurrent_ctx {
            engine.set_transaction_concurrent(
                txn,
                ctx.session_id,
                ctx.handle,
                ctx.lock_table,
                ctx.commit_index,
                ctx.busy_timeout_ms,
            );
            engine.set_concurrent_rowid_allocator(ctx.rowid_allocator, ctx.schema_epoch);
        } else {
            engine.set_transaction(txn);
        }
    } else {
        engine.enable_storage_read_cursors(true);
    }

    let attach_memdb = !reject_mem_fallback || program.requires_attached_memdb();
    if attach_memdb {
        // bd-perf: Reuse thread-local placeholder (same pattern as execute_table_program_with_db).
        let placeholder = MEMDB_PLACEHOLDER
            .with(|p| p.borrow_mut().take())
            .unwrap_or_else(MemDatabase::new);
        let db_value = db.replace(placeholder);
        engine.set_database(db_value);
    }

    let trace_export_enabled =
        tracing::enabled!(target: "fsqlite.trace_export", tracing::Level::DEBUG);
    let export_started = trace_export_enabled.then(fsqlite_types::sync_primitives::Instant::now);
    let exec_res = if let Some(params) = params {
        engine
            .execute_with_borrowed_bindings(program, Some(params))
            .await
    } else {
        engine.execute(program).await
    };
    if let Some(export_started) = export_started {
        let export_latency_us =
            u64::try_from(export_started.elapsed().as_micros()).unwrap_or(u64::MAX);
        record_trace_export(1, export_latency_us);
    }
    if exec_res.is_err() || matches!(exec_res, Ok(ExecOutcome::Error { .. })) {
        record_trace_export_error();
    }
    let engine_rowid = engine.last_insert_rowid();

    if attach_memdb && let Some(db_value) = engine.take_database() {
        // bd-perf: Return placeholder to thread-local for reuse.
        let old_placeholder = db.replace(db_value);
        MEMDB_PLACEHOLDER.with(|p| {
            *p.borrow_mut() = Some(old_placeholder);
        });
    }
    let txn_back = match engine.take_transaction() {
        Ok(txn) => txn,
        Err(e) => {
            return (
                (
                    Err(TableProgramExecError {
                        error: e,
                        changes: engine.changes(),
                        last_insert_rowid: engine_rowid,
                    }),
                    None,
                ),
                Some(engine),
            );
        }
    };

    let changes = engine.changes();
    let result = match exec_res {
        Ok(ExecOutcome::Done) => Ok((
            take_exactly_one_engine_row(&mut engine),
            changes,
            engine_rowid,
        )),
        Ok(ExecOutcome::Error { code, message }) => Err(TableProgramExecError {
            error: frankenerror_from_vdbe_halt(code, message),
            changes,
            last_insert_rowid: engine_rowid,
        }),
        Err(e) => Err(TableProgramExecError {
            error: e,
            changes,
            last_insert_rowid: engine_rowid,
        }),
    };
    ((result, txn_back), Some(engine))
}

fn expression_only_limit_requires_dynamic_evaluation(select: &SelectStatement) -> bool {
    select.limit.as_ref().is_some_and(|limit| {
        parse_limit_offset_expr(&limit.limit).is_err()
            || limit
                .offset
                .as_ref()
                .is_some_and(|offset| parse_limit_offset_expr(offset).is_err())
    })
}

/// Enforce the static projection rule for a SELECT without a FROM source.
///
/// This must run before the LIMIT-zero short circuit: SQLite resolves `*`
/// during statement preparation and reports the missing source even though no
/// result expression will be executed.
fn validate_fromless_projection_shape(select: &SelectStatement) -> Result<()> {
    let SelectCore::Select {
        columns,
        from: None,
        where_clause,
        ..
    } = &select.body.select
    else {
        return Ok(());
    };
    for column in columns {
        match column {
            ResultColumn::Expr { .. } => {}
            ResultColumn::Star => {
                return Err(FrankenError::ParseError {
                    offset: 0,
                    detail: "no tables specified".to_owned(),
                });
            }
            ResultColumn::TableStar(name) => {
                return Err(FrankenError::NoSuchTable {
                    name: name.name.clone(),
                });
            }
        }
    }
    for column in columns {
        if let ResultColumn::Expr { expr, .. } = column
            && expr_has_external_column_ref(expr, &[])
        {
            return Err(FrankenError::FunctionError(
                "no such column in result expression".to_owned(),
            ));
        }
    }
    let output_aliases = collect_select_core_result_aliases(&select.body.select);
    if where_clause.as_deref().is_some_and(|where_clause| {
        expr_has_external_column_ref_with_locals(where_clause, &[], &output_aliases)
    }) {
        return Err(FrankenError::FunctionError(
            "no such column in WHERE".to_owned(),
        ));
    }
    if select.limit.as_ref().is_some_and(|limit| {
        expr_has_external_column_ref(&limit.limit, &[])
            || limit
                .offset
                .as_ref()
                .is_some_and(|offset| expr_has_external_column_ref(offset, &[]))
    }) {
        return Err(FrankenError::FunctionError(
            "no such column in LIMIT or OFFSET".to_owned(),
        ));
    }
    Ok(())
}

fn validate_fromless_window_value_shapes(select: &SelectStatement) -> Result<()> {
    let SelectCore::Values(rows) = &select.body.select else {
        return Ok(());
    };
    let Some(first_row) = rows.first() else {
        return Err(FrankenError::ParseError {
            offset: 0,
            detail: "VALUES must include at least one row".to_owned(),
        });
    };
    if first_row.is_empty() {
        return Err(FrankenError::ParseError {
            offset: 0,
            detail: "VALUES row must include at least one expression".to_owned(),
        });
    }
    let output_width = first_row.len();
    for row in rows {
        if row.len() != output_width {
            return Err(FrankenError::ParseError {
                offset: 0,
                detail: "VALUES rows must have matching column counts".to_owned(),
            });
        }
        if row
            .iter()
            .any(|expr| expr_has_external_column_ref(expr, &[]))
        {
            return Err(FrankenError::FunctionError(
                "no such column in VALUES expression".to_owned(),
            ));
        }
    }
    Ok(())
}

fn validate_fromless_used_window_scopes(
    connection: &Connection,
    select: &SelectStatement,
    named_windows: &NamedWindowSpecs<'_>,
    resolved_order_named_windows: &NamedWindowSpecs<'_>,
    resolved_order_expressions: &[Expr],
    collation_registry: &CollationRegistry,
) -> Result<()> {
    let validate_expr = |expr: &Expr, visible_windows: &NamedWindowSpecs<'_>| -> Result<()> {
        if expr_folds_to_integer_zero_via_and(expr) {
            return Ok(());
        }
        let mut remaining = expr.clone();
        while expr_has_window_function(&remaining) {
            let ExtractedWindowFunction {
                name: _,
                args,
                call_order_by,
                window,
                filter,
            } = extract_inner_window_function(&remaining).ok_or_else(|| {
                FrankenError::Internal(
                    "window scope validation could not expose a window call".to_owned(),
                )
            })?;
            let resolved = resolve_used_window_spec(&window, visible_windows)?;
            if window_spec_has_external_column_ref(&resolved, &[]) {
                return Err(FrankenError::FunctionError(
                    "no such column in window specification".to_owned(),
                ));
            }
            if let Some(filter) = &filter {
                validate_window_key_expr_collations(connection, filter, collation_registry)?;
            }
            if let FunctionArgs::List(values) = &args {
                for value in values.iter().rev() {
                    validate_window_key_expr_collations(connection, value, collation_registry)?;
                }
            }
            for term in call_order_by.iter().rev() {
                validate_window_key_expr_collations(connection, &term.expr, collation_registry)?;
            }
            validate_used_window_key_collations(connection, &resolved, collation_registry)?;
            let mut replaced = false;
            remaining =
                replace_first_window_with_literal(&remaining, &SqliteValue::Null, &mut replaced);
            if !replaced {
                return Err(FrankenError::Internal(
                    "window scope validation replacement made no progress".to_owned(),
                ));
            }
        }
        Ok(())
    };

    // SQLite prepares DISTINCT keys before outer ORDER BY keys. A key's own
    // winner is resolved before nested window-call boundaries, so an explicit
    // outer COLLATE has diagnostic precedence over a window argument/key.
    if let SelectCore::Select {
        distinct: Distinctness::Distinct,
        columns,
        ..
    } = &select.body.select
    {
        for column in columns.iter().rev() {
            if let ResultColumn::Expr { expr, .. } = column {
                validate_expr_collation_winner(expr, collation_registry)?;
                validate_expr(expr, named_windows)?;
            }
        }
    }
    for expr in resolved_order_expressions.iter().rev() {
        validate_expr_collation_boundary(connection, expr, collation_registry)?;
        validate_expr(expr, resolved_order_named_windows)?;
    }

    // Non-DISTINCT projection windows are prepared after the outer ORDER BY,
    // but before GROUP/LIMIT/runtime predicates. DISTINCT projections were
    // handled above as key boundaries.
    match &select.body.select {
        SelectCore::Values(rows) => {
            for expr in rows.iter().flatten() {
                validate_expr(expr, named_windows)?;
            }
        }
        SelectCore::Select {
            distinct,
            columns,
            where_clause,
            group_by,
            having,
            ..
        } => {
            if *distinct != Distinctness::Distinct {
                for column in columns {
                    if let ResultColumn::Expr { expr, .. } = column {
                        validate_expr(expr, named_windows)?;
                    }
                }
            }
            if let Some(predicate) = where_clause {
                validate_expr(predicate, named_windows)?;
            }
            for expr in group_by {
                let resolved =
                    connection.resolve_fromless_group_expr_with_aliases(expr, columns)?;
                validate_expr(&resolved, named_windows)?;
            }
            if let Some(predicate) = having {
                validate_expr(predicate, named_windows)?;
            }
        }
    }

    if let SelectCore::Select {
        columns, group_by, ..
    } = &select.body.select
    {
        for expr in group_by.iter().rev() {
            let resolved = connection.resolve_fromless_group_expr_with_aliases(expr, columns)?;
            validate_expr_collation_boundary(connection, &resolved, collation_registry)?;
        }
    }
    if let SelectCore::Select {
        where_clause,
        having,
        ..
    } = &select.body.select
    {
        if let Some(predicate) = where_clause {
            validate_expr_collation_consumers(connection, predicate, collation_registry)?;
        }
        if let Some(predicate) = having {
            validate_expr_collation_consumers(connection, predicate, collation_registry)?;
        }
    }
    if let Some(limit) = &select.limit {
        validate_expr_collation_consumers(connection, &limit.limit, collation_registry)?;
        if let Some(offset) = &limit.offset {
            validate_expr_collation_consumers(connection, offset, collation_registry)?;
        }
    }
    match &select.body.select {
        SelectCore::Values(rows) => {
            for expr in rows.iter().flatten() {
                validate_expr_collation_consumers(connection, expr, collation_registry)?;
            }
        }
        SelectCore::Select { columns, .. } => {
            for column in columns {
                if let ResultColumn::Expr { expr, .. } = column {
                    validate_expr_collation_consumers(connection, expr, collation_registry)?;
                }
            }
        }
    }
    Ok(())
}

/// Validate collation names that participate in a used window's partition or
/// ordering keys.
///
/// SQLite resolves these names during statement preparation, before a false
/// predicate or `LIMIT 0` can suppress runtime evaluation. The caller
/// separately validates a used window call's filter and arguments. Collations
/// that occur only as unconsumed annotations inside frame offsets, nested
/// scalar subqueries, or ordinary non-window expressions intentionally remain
/// deferred. Operations inside frame offsets and subqueries still consume
/// collations during preparation and are validated below.
fn validate_used_window_key_collations(
    connection: &Connection,
    window: &WindowSpec,
    registry: &CollationRegistry,
) -> Result<()> {
    for term in window.order_by.iter().rev() {
        validate_window_key_expr_collations(connection, &term.expr, registry)?;
    }
    for expr in window.partition_by.iter().rev() {
        validate_window_key_expr_collations(connection, expr, registry)?;
    }
    if let Some(frame) = &window.frame {
        validate_window_frame_collation_consumers(frame, registry)?;
    }
    Ok(())
}

fn validate_window_key_expr_collations(
    connection: &Connection,
    expr: &Expr,
    registry: &CollationRegistry,
) -> Result<()> {
    validate_expr_collation_boundary(connection, expr, registry)
}

fn validate_registered_collation(collation: &str, registry: &CollationRegistry) -> Result<()> {
    if registry.contains(collation) {
        Ok(())
    } else {
        Err(FrankenError::FunctionError(format!(
            "no such collation sequence: {collation}"
        )))
    }
}

/// Return whether SQLite's parser folds this exact expression to integer zero.
///
/// SQLite performs this special fold only for a literal integer `0` and for
/// recursively nested `AND` expressions containing such a zero. Keywords such
/// as `FALSE`, numeric `0.0`, unary `+0`, and COLLATE-wrapped zero remain live.
fn expr_folds_to_integer_zero_via_and(expr: &Expr) -> bool {
    match expr {
        Expr::Literal(Literal::Integer(0), _) => true,
        Expr::BinaryOp {
            left,
            op: BinaryOp::And,
            right,
            ..
        } => expr_folds_to_integer_zero_via_and(left) || expr_folds_to_integer_zero_via_and(right),
        _ => false,
    }
}

/// Return whether a statement contains any connection-local `VALUES` clause
/// whose representation has not yet been frozen for a function-registry
/// snapshot.
fn statement_contains_deferred_values(statement: &Statement) -> bool {
    match statement {
        Statement::Select(select) => select_contains_deferred_values(select),
        Statement::Insert(insert) => {
            with_contains_deferred_values(insert.with.as_ref())
                || match &insert.source {
                    InsertSource::Values(rows) => {
                        rows.iter().flatten().any(expr_contains_deferred_values)
                    }
                    InsertSource::Select(select) => select_contains_deferred_values(select),
                    InsertSource::DefaultValues => false,
                }
                || insert.upsert.iter().any(|upsert| {
                    upsert.target.as_ref().is_some_and(|target| {
                        target
                            .columns
                            .iter()
                            .any(|column| expr_contains_deferred_values(&column.expr))
                            || target
                                .where_clause
                                .as_ref()
                                .is_some_and(expr_contains_deferred_values)
                    }) || match &upsert.action {
                        UpsertAction::Nothing => false,
                        UpsertAction::Update {
                            assignments,
                            where_clause,
                        } => {
                            assignments
                                .iter()
                                .any(|assignment| expr_contains_deferred_values(&assignment.value))
                                || where_clause
                                    .as_deref()
                                    .is_some_and(expr_contains_deferred_values)
                        }
                    }
                })
                || result_columns_contain_deferred_values(&insert.returning)
        }
        Statement::Update(update) => {
            with_contains_deferred_values(update.with.as_ref())
                || update
                    .assignments
                    .iter()
                    .any(|assignment| expr_contains_deferred_values(&assignment.value))
                || update
                    .from
                    .as_ref()
                    .is_some_and(from_contains_deferred_values)
                || update
                    .where_clause
                    .as_ref()
                    .is_some_and(expr_contains_deferred_values)
                || result_columns_contain_deferred_values(&update.returning)
                || update
                    .order_by
                    .iter()
                    .any(|term| expr_contains_deferred_values(&term.expr))
                || update
                    .limit
                    .as_ref()
                    .is_some_and(limit_contains_deferred_values)
        }
        Statement::Delete(delete) => {
            with_contains_deferred_values(delete.with.as_ref())
                || delete
                    .where_clause
                    .as_ref()
                    .is_some_and(expr_contains_deferred_values)
                || result_columns_contain_deferred_values(&delete.returning)
                || delete
                    .order_by
                    .iter()
                    .any(|term| expr_contains_deferred_values(&term.expr))
                || delete
                    .limit
                    .as_ref()
                    .is_some_and(limit_contains_deferred_values)
        }
        Statement::CreateTable(create) => match &create.body {
            CreateTableBody::Columns {
                columns,
                constraints,
            } => {
                columns.iter().any(column_def_contains_deferred_values)
                    || constraints.iter().any(|constraint| match &constraint.kind {
                        TableConstraintKind::PrimaryKey { columns, .. }
                        | TableConstraintKind::Unique { columns, .. } => columns
                            .iter()
                            .any(|column| expr_contains_deferred_values(&column.expr)),
                        TableConstraintKind::Check(expr) => expr_contains_deferred_values(expr),
                        TableConstraintKind::ForeignKey { .. } => false,
                    })
            }
            CreateTableBody::AsSelect(select) => select_contains_deferred_values(select),
        },
        Statement::CreateIndex(create) => {
            create
                .columns
                .iter()
                .any(|column| expr_contains_deferred_values(&column.expr))
                || create
                    .where_clause
                    .as_ref()
                    .is_some_and(expr_contains_deferred_values)
        }
        Statement::CreateView(create) => select_contains_deferred_values(&create.query),
        Statement::CreateTrigger(create) => {
            create
                .when
                .as_ref()
                .is_some_and(expr_contains_deferred_values)
                || create.body.iter().any(statement_contains_deferred_values)
        }
        Statement::AlterTable(alter) => matches!(
            &alter.action,
            AlterTableAction::AddColumn(column) if column_def_contains_deferred_values(column)
        ),
        Statement::Attach(attach) => expr_contains_deferred_values(&attach.expr),
        Statement::Pragma(pragma) => pragma.value.as_ref().is_some_and(|value| match value {
            PragmaValue::Assign(expr) | PragmaValue::Call(expr) => {
                expr_contains_deferred_values(expr)
            }
        }),
        Statement::Vacuum(vacuum) => vacuum
            .into
            .as_ref()
            .is_some_and(expr_contains_deferred_values),
        Statement::Explain { stmt, .. } => statement_contains_deferred_values(stmt),
        Statement::CreateVirtualTable(_)
        | Statement::Drop(_)
        | Statement::Begin(_)
        | Statement::Commit
        | Statement::Rollback(_)
        | Statement::Savepoint(_)
        | Statement::Release(_)
        | Statement::Detach(_)
        | Statement::Reindex(_)
        | Statement::Analyze(_) => false,
    }
}

fn column_def_contains_deferred_values(column: &fsqlite_ast::ColumnDef) -> bool {
    column
        .constraints
        .iter()
        .any(|constraint| match &constraint.kind {
            ColumnConstraintKind::Check(expr)
            | ColumnConstraintKind::Generated { expr, .. }
            | ColumnConstraintKind::Default(
                DefaultValue::Expr(expr) | DefaultValue::ParenExpr(expr),
            ) => expr_contains_deferred_values(expr),
            ColumnConstraintKind::PrimaryKey { .. }
            | ColumnConstraintKind::NotNull { .. }
            | ColumnConstraintKind::Null
            | ColumnConstraintKind::Unique { .. }
            | ColumnConstraintKind::Collate(_)
            | ColumnConstraintKind::ForeignKey(_) => false,
        })
}

fn with_contains_deferred_values(with: Option<&fsqlite_ast::WithClause>) -> bool {
    with.is_some_and(|with| {
        with.ctes
            .iter()
            .any(|cte| select_contains_deferred_values(&cte.query))
    })
}

fn select_contains_deferred_values(select: &SelectStatement) -> bool {
    with_contains_deferred_values(select.with.as_ref())
        || select_core_contains_deferred_values(&select.body.select)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_contains_deferred_values(core))
        || select
            .order_by
            .iter()
            .any(|term| expr_contains_deferred_values(&term.expr))
        || select
            .limit
            .as_ref()
            .is_some_and(limit_contains_deferred_values)
}

fn select_core_contains_deferred_values(core: &SelectCore) -> bool {
    match core {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            result_columns_contain_deferred_values(columns)
                || from.as_ref().is_some_and(from_contains_deferred_values)
                || where_clause
                    .as_deref()
                    .is_some_and(expr_contains_deferred_values)
                || group_by.iter().any(expr_contains_deferred_values)
                || having.as_deref().is_some_and(expr_contains_deferred_values)
                || windows
                    .iter()
                    .any(|window| window_contains_deferred_values(&window.spec))
        }
        SelectCore::Values(values) => {
            !values.is_frozen() || values.iter().flatten().any(expr_contains_deferred_values)
        }
    }
}

fn from_contains_deferred_values(from: &FromClause) -> bool {
    source_contains_deferred_values(&from.source)
        || from.joins.iter().any(|join| {
            source_contains_deferred_values(&join.table)
                || matches!(
                    &join.constraint,
                    Some(JoinConstraint::On(expr)) if expr_contains_deferred_values(expr)
                )
        })
}

fn source_contains_deferred_values(source: &TableOrSubquery) -> bool {
    match source {
        TableOrSubquery::Subquery { query, .. } => select_contains_deferred_values(query),
        TableOrSubquery::TableFunction { args, .. } => {
            args.iter().any(expr_contains_deferred_values)
        }
        TableOrSubquery::ParenJoin(from) => from_contains_deferred_values(from),
        TableOrSubquery::Table { .. } => false,
    }
}

fn result_columns_contain_deferred_values(columns: &[ResultColumn]) -> bool {
    columns.iter().any(|column| {
        matches!(
            column,
            ResultColumn::Expr { expr, .. } if expr_contains_deferred_values(expr)
        )
    })
}

fn limit_contains_deferred_values(limit: &LimitClause) -> bool {
    expr_contains_deferred_values(&limit.limit)
        || limit
            .offset
            .as_ref()
            .is_some_and(expr_contains_deferred_values)
}

fn expr_contains_deferred_values(expr: &Expr) -> bool {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => false,
        Expr::BinaryOp { left, right, .. }
        | Expr::JsonAccess {
            expr: left,
            path: right,
            ..
        } => expr_contains_deferred_values(left) || expr_contains_deferred_values(right),
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => expr_contains_deferred_values(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_contains_deferred_values(expr)
                || expr_contains_deferred_values(low)
                || expr_contains_deferred_values(high)
        }
        Expr::In { expr, set, .. } => {
            expr_contains_deferred_values(expr)
                || match set {
                    InSet::List(values) => values.iter().any(expr_contains_deferred_values),
                    InSet::Subquery(select) => select_contains_deferred_values(select),
                    InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_contains_deferred_values(expr)
                || expr_contains_deferred_values(pattern)
                || escape.as_deref().is_some_and(expr_contains_deferred_values)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(expr_contains_deferred_values)
                || whens.iter().any(|(condition, value)| {
                    expr_contains_deferred_values(condition) || expr_contains_deferred_values(value)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(expr_contains_deferred_values)
        }
        Expr::Subquery(select, _)
        | Expr::Exists {
            subquery: select, ..
        } => select_contains_deferred_values(select),
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            matches!(args, FunctionArgs::List(values) if values
                .iter()
                .any(expr_contains_deferred_values))
                || order_by
                    .iter()
                    .any(|term| expr_contains_deferred_values(&term.expr))
                || filter.as_deref().is_some_and(expr_contains_deferred_values)
                || over.as_ref().is_some_and(window_contains_deferred_values)
        }
        Expr::RowValue(values, _) => values.iter().any(expr_contains_deferred_values),
    }
}

fn window_contains_deferred_values(window: &WindowSpec) -> bool {
    window
        .partition_by
        .iter()
        .any(expr_contains_deferred_values)
        || window
            .order_by
            .iter()
            .any(|term| expr_contains_deferred_values(&term.expr))
        || window.frame.as_ref().is_some_and(|frame| {
            frame_bound_contains_deferred_values(&frame.start)
                || frame
                    .end
                    .as_ref()
                    .is_some_and(frame_bound_contains_deferred_values)
        })
}

fn frame_bound_contains_deferred_values(bound: &FrameBound) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_contains_deferred_values(expr)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ValuesFreezeContext {
    Statement,
    StoredSchema,
}

fn freeze_values_donors_in_statement(
    statement: &mut Statement,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    match statement {
        Statement::Select(select) => {
            freeze_values_donors_in_select(select, function_registry, context);
        }
        Statement::Insert(insert) => {
            freeze_values_donors_in_with(insert.with.as_mut(), function_registry, context);
            match &mut insert.source {
                InsertSource::Values(rows) => {
                    for row in rows {
                        freeze_values_donors_in_exprs(row, function_registry, context);
                    }
                }
                InsertSource::Select(select) => {
                    freeze_values_donors_in_select(select, function_registry, context);
                }
                InsertSource::DefaultValues => {}
            }
            for upsert in &mut insert.upsert {
                if let Some(target) = &mut upsert.target {
                    for column in &mut target.columns {
                        freeze_values_donors_in_expr(&mut column.expr, function_registry, context);
                    }
                    if let Some(predicate) = &mut target.where_clause {
                        freeze_values_donors_in_expr(predicate, function_registry, context);
                    }
                }
                if let UpsertAction::Update {
                    assignments,
                    where_clause,
                } = &mut upsert.action
                {
                    for assignment in assignments {
                        freeze_values_donors_in_expr(
                            &mut assignment.value,
                            function_registry,
                            context,
                        );
                    }
                    if let Some(predicate) = where_clause {
                        freeze_values_donors_in_expr(predicate, function_registry, context);
                    }
                }
            }
            freeze_values_donors_in_result_columns(
                &mut insert.returning,
                function_registry,
                context,
            );
        }
        Statement::Update(update) => {
            freeze_values_donors_in_with(update.with.as_mut(), function_registry, context);
            for assignment in &mut update.assignments {
                freeze_values_donors_in_expr(&mut assignment.value, function_registry, context);
            }
            if let Some(from) = &mut update.from {
                freeze_values_donors_in_from(from, function_registry, context);
            }
            if let Some(predicate) = &mut update.where_clause {
                freeze_values_donors_in_expr(predicate, function_registry, context);
            }
            freeze_values_donors_in_result_columns(
                &mut update.returning,
                function_registry,
                context,
            );
            for term in &mut update.order_by {
                freeze_values_donors_in_expr(&mut term.expr, function_registry, context);
            }
            freeze_values_donors_in_limit(update.limit.as_mut(), function_registry, context);
        }
        Statement::Delete(delete) => {
            freeze_values_donors_in_with(delete.with.as_mut(), function_registry, context);
            if let Some(predicate) = &mut delete.where_clause {
                freeze_values_donors_in_expr(predicate, function_registry, context);
            }
            freeze_values_donors_in_result_columns(
                &mut delete.returning,
                function_registry,
                context,
            );
            for term in &mut delete.order_by {
                freeze_values_donors_in_expr(&mut term.expr, function_registry, context);
            }
            freeze_values_donors_in_limit(delete.limit.as_mut(), function_registry, context);
        }
        Statement::CreateTable(create) => match &mut create.body {
            CreateTableBody::Columns {
                columns,
                constraints,
            } => {
                for column in columns {
                    freeze_values_donors_in_column_def(column, function_registry, context);
                }
                for constraint in constraints {
                    match &mut constraint.kind {
                        TableConstraintKind::PrimaryKey { columns, .. }
                        | TableConstraintKind::Unique { columns, .. } => {
                            for column in columns {
                                freeze_values_donors_in_expr(
                                    &mut column.expr,
                                    function_registry,
                                    context,
                                );
                            }
                        }
                        TableConstraintKind::Check(expr) => {
                            freeze_values_donors_in_expr(expr, function_registry, context);
                        }
                        TableConstraintKind::ForeignKey { .. } => {}
                    }
                }
            }
            CreateTableBody::AsSelect(select) => {
                freeze_values_donors_in_select(select, function_registry, context);
            }
        },
        Statement::CreateIndex(create) => {
            for column in &mut create.columns {
                freeze_values_donors_in_expr(&mut column.expr, function_registry, context);
            }
            if let Some(predicate) = &mut create.where_clause {
                freeze_values_donors_in_expr(predicate, function_registry, context);
            }
        }
        Statement::CreateView(create) => {
            freeze_values_donors_in_select(
                &mut create.query,
                function_registry,
                ValuesFreezeContext::StoredSchema,
            );
        }
        Statement::CreateTrigger(create) => {
            if let Some(predicate) = &mut create.when {
                freeze_values_donors_in_expr(
                    predicate,
                    function_registry,
                    ValuesFreezeContext::StoredSchema,
                );
            }
            for body_statement in &mut create.body {
                freeze_values_donors_in_statement(
                    body_statement,
                    function_registry,
                    ValuesFreezeContext::StoredSchema,
                );
            }
        }
        Statement::AlterTable(alter) => {
            if let AlterTableAction::AddColumn(column) = &mut alter.action {
                freeze_values_donors_in_column_def(column, function_registry, context);
            }
        }
        Statement::Attach(attach) => {
            freeze_values_donors_in_expr(&mut attach.expr, function_registry, context);
        }
        Statement::Pragma(pragma) => {
            if let Some(PragmaValue::Assign(value) | PragmaValue::Call(value)) = &mut pragma.value {
                freeze_values_donors_in_expr(value, function_registry, context);
            }
        }
        Statement::Vacuum(vacuum) => {
            if let Some(path) = &mut vacuum.into {
                freeze_values_donors_in_expr(path, function_registry, context);
            }
        }
        Statement::Explain { stmt, .. } => {
            freeze_values_donors_in_statement(stmt, function_registry, context);
        }
        Statement::CreateVirtualTable(_)
        | Statement::Drop(_)
        | Statement::Begin(_)
        | Statement::Commit
        | Statement::Rollback(_)
        | Statement::Savepoint(_)
        | Statement::Release(_)
        | Statement::Detach(_)
        | Statement::Reindex(_)
        | Statement::Analyze(_) => {}
    }
}

fn freeze_values_donors_in_column_def(
    column: &mut fsqlite_ast::ColumnDef,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    for constraint in &mut column.constraints {
        match &mut constraint.kind {
            ColumnConstraintKind::Check(expr)
            | ColumnConstraintKind::Generated { expr, .. }
            | ColumnConstraintKind::Default(
                DefaultValue::Expr(expr) | DefaultValue::ParenExpr(expr),
            ) => {
                freeze_values_donors_in_expr(expr, function_registry, context);
            }
            ColumnConstraintKind::PrimaryKey { .. }
            | ColumnConstraintKind::NotNull { .. }
            | ColumnConstraintKind::Null
            | ColumnConstraintKind::Unique { .. }
            | ColumnConstraintKind::Collate(_)
            | ColumnConstraintKind::ForeignKey(_) => {}
        }
    }
}

fn freeze_values_donors_in_with(
    with: Option<&mut fsqlite_ast::WithClause>,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    if let Some(with) = with {
        for cte in &mut with.ctes {
            freeze_values_donors_in_select(&mut cte.query, function_registry, context);
        }
    }
}

fn freeze_values_donors_in_select(
    select: &mut SelectStatement,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    freeze_values_donors_in_with(select.with.as_mut(), function_registry, context);
    freeze_values_donors_in_select_core(&mut select.body.select, function_registry, context);
    for (_, core) in &mut select.body.compounds {
        freeze_values_donors_in_select_core(core, function_registry, context);
    }
    for term in &mut select.order_by {
        freeze_values_donors_in_expr(&mut term.expr, function_registry, context);
    }
    freeze_values_donors_in_limit(select.limit.as_mut(), function_registry, context);
}

fn freeze_values_donors_in_select_core(
    core: &mut SelectCore,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    match core {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            freeze_values_donors_in_result_columns(columns, function_registry, context);
            if let Some(from) = from {
                freeze_values_donors_in_from(from, function_registry, context);
            }
            if let Some(predicate) = where_clause {
                freeze_values_donors_in_expr(predicate, function_registry, context);
            }
            freeze_values_donors_in_exprs(group_by, function_registry, context);
            if let Some(predicate) = having {
                freeze_values_donors_in_expr(predicate, function_registry, context);
            }
            for window in windows {
                freeze_values_donors_in_window(&mut window.spec, function_registry, context);
            }
        }
        SelectCore::Values(values) => {
            if !values.is_frozen() {
                let donor_index = match context {
                    ValuesFreezeContext::Statement => {
                        deferred_values_donor_row_index(values, function_registry)
                    }
                    ValuesFreezeContext::StoredSchema => values.len().checked_sub(1),
                };
                values.freeze_donor_row(donor_index);
            }
            for row in values.iter_mut() {
                freeze_values_donors_in_exprs(row, function_registry, context);
            }
        }
    }
}

fn freeze_values_donors_in_from(
    from: &mut FromClause,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    freeze_values_donors_in_source(&mut from.source, function_registry, context);
    for join in &mut from.joins {
        freeze_values_donors_in_source(&mut join.table, function_registry, context);
        if let Some(JoinConstraint::On(predicate)) = &mut join.constraint {
            freeze_values_donors_in_expr(predicate, function_registry, context);
        }
    }
}

fn freeze_values_donors_in_source(
    source: &mut TableOrSubquery,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    match source {
        TableOrSubquery::Subquery { query, .. } => {
            freeze_values_donors_in_select(query, function_registry, context);
        }
        TableOrSubquery::TableFunction { args, .. } => {
            freeze_values_donors_in_exprs(args, function_registry, context);
        }
        TableOrSubquery::ParenJoin(from) => {
            freeze_values_donors_in_from(from, function_registry, context);
        }
        TableOrSubquery::Table { .. } => {}
    }
}

fn freeze_values_donors_in_result_columns(
    columns: &mut [ResultColumn],
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    for column in columns {
        if let ResultColumn::Expr { expr, .. } = column {
            freeze_values_donors_in_expr(expr, function_registry, context);
        }
    }
}

fn freeze_values_donors_in_limit(
    limit: Option<&mut LimitClause>,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    if let Some(limit) = limit {
        freeze_values_donors_in_expr(&mut limit.limit, function_registry, context);
        if let Some(offset) = &mut limit.offset {
            freeze_values_donors_in_expr(offset, function_registry, context);
        }
    }
}

fn freeze_values_donors_in_exprs(
    exprs: &mut [Expr],
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    for expr in exprs {
        freeze_values_donors_in_expr(expr, function_registry, context);
    }
}

fn freeze_values_donors_in_expr(
    expr: &mut Expr,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => {}
        Expr::BinaryOp { left, right, .. }
        | Expr::JsonAccess {
            expr: left,
            path: right,
            ..
        } => {
            freeze_values_donors_in_expr(left, function_registry, context);
            freeze_values_donors_in_expr(right, function_registry, context);
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            freeze_values_donors_in_expr(expr, function_registry, context);
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            freeze_values_donors_in_expr(expr, function_registry, context);
            freeze_values_donors_in_expr(low, function_registry, context);
            freeze_values_donors_in_expr(high, function_registry, context);
        }
        Expr::In { expr, set, .. } => {
            freeze_values_donors_in_expr(expr, function_registry, context);
            match set {
                InSet::List(values) => {
                    freeze_values_donors_in_exprs(values, function_registry, context);
                }
                InSet::Subquery(select) => {
                    freeze_values_donors_in_select(select, function_registry, context);
                }
                InSet::Table(_) => {}
            }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            freeze_values_donors_in_expr(expr, function_registry, context);
            freeze_values_donors_in_expr(pattern, function_registry, context);
            if let Some(escape) = escape {
                freeze_values_donors_in_expr(escape, function_registry, context);
            }
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                freeze_values_donors_in_expr(operand, function_registry, context);
            }
            for (condition, value) in whens {
                freeze_values_donors_in_expr(condition, function_registry, context);
                freeze_values_donors_in_expr(value, function_registry, context);
            }
            if let Some(else_expr) = else_expr {
                freeze_values_donors_in_expr(else_expr, function_registry, context);
            }
        }
        Expr::Subquery(select, _)
        | Expr::Exists {
            subquery: select, ..
        } => {
            freeze_values_donors_in_select(select, function_registry, context);
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if let FunctionArgs::List(args) = args {
                freeze_values_donors_in_exprs(args, function_registry, context);
            }
            for term in order_by {
                freeze_values_donors_in_expr(&mut term.expr, function_registry, context);
            }
            if let Some(filter) = filter {
                freeze_values_donors_in_expr(filter, function_registry, context);
            }
            if let Some(window) = over {
                freeze_values_donors_in_window(window, function_registry, context);
            }
        }
        Expr::RowValue(values, _) => {
            freeze_values_donors_in_exprs(values, function_registry, context);
        }
    }
}

fn freeze_values_donors_in_window(
    window: &mut WindowSpec,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    freeze_values_donors_in_exprs(&mut window.partition_by, function_registry, context);
    for term in &mut window.order_by {
        freeze_values_donors_in_expr(&mut term.expr, function_registry, context);
    }
    if let Some(frame) = &mut window.frame {
        freeze_values_donors_in_frame_bound(&mut frame.start, function_registry, context);
        if let Some(end) = &mut frame.end {
            freeze_values_donors_in_frame_bound(end, function_registry, context);
        }
    }
}

fn freeze_values_donors_in_frame_bound(
    bound: &mut FrameBound,
    function_registry: &FunctionRegistry,
    context: ValuesFreezeContext,
) {
    if let FrameBound::Preceding(expr) | FrameBound::Following(expr) = bound {
        freeze_values_donors_in_expr(expr, function_registry, context);
    }
}

/// Resolve the same row that SQLite's parser-built SELECT tree exposes as the
/// direct scalar/vector comparison donor for a syntactic `VALUES` clause.
fn deferred_values_donor_row_index(
    values: &ValuesClause,
    function_registry: &FunctionRegistry,
) -> Option<usize> {
    let rows = values.rows();
    if rows.is_empty() {
        return None;
    }

    let force_union_all_from = values.force_union_all_from();
    let mut donor_index = 0;
    let mut coroutine_active = false;
    for row_index in 1..rows.len() {
        let sticky_with_forces_union =
            force_union_all_from.is_some_and(|first_row| row_index >= first_row);
        let new_row_is_constant = values_row_is_query_constant(
            rows.get(row_index).expect("VALUES row index is in bounds"),
            function_registry,
        );
        let current_root_allows_coroutine = coroutine_active
            || values_row_is_constant_without_affinity(
                rows.get(donor_index)
                    .expect("VALUES donor index is in bounds"),
                function_registry,
            );

        if sticky_with_forces_union || !new_row_is_constant || !current_root_allows_coroutine {
            // sqlite3MultiValues() appends this row as the rightmost UNION ALL
            // core. A later constant/no-affinity row may start a new coroutine
            // wrapper and retain this row as its donor.
            donor_index = row_index;
            coroutine_active = false;
        } else {
            coroutine_active = true;
        }
    }
    Some(donor_index)
}

fn values_row_is_query_constant(row: &[Expr], function_registry: &FunctionRegistry) -> bool {
    row.iter()
        .all(|expr| values_expr_is_query_constant(expr, function_registry))
}

fn values_row_is_constant_without_affinity(
    row: &[Expr],
    function_registry: &FunctionRegistry,
) -> bool {
    values_row_is_query_constant(row, function_registry)
        && row.iter().all(|expr| !values_expr_has_affinity(expr))
}

/// Match `sqlite3ExprIsConstant()` for the VALUES coroutine decision without
/// invoking application code. Slow-changing built-ins are query-constant;
/// volatile application replacements are not.
fn values_expr_is_query_constant(expr: &Expr, function_registry: &FunctionRegistry) -> bool {
    // bd-di4he: NO semantic short-circuits here. sqlite3ExprIsConstant() is
    // purely syntactic — `random() AND 0`, `0 AND random()`, and
    // `random() IN ()` are all NON-constant to stock SQLite, which forces
    // such VALUES rows into UNION ALL cores and moves the coroutine donor to
    // the rightmost core. Folding them to constants here froze donor row 0
    // and dropped the CAST donor affinity the bundled-3.53.2 oracle requires
    // ((VALUES(1),(random() AND 0),(CAST(1 AS NUMERIC))) = '1' is 1).
    match expr {
        Expr::Literal(_, _) | Expr::Placeholder(_, _) => true,
        Expr::BinaryOp { left, right, .. } => {
            values_expr_is_query_constant(left, function_registry)
                && values_expr_is_query_constant(right, function_registry)
        }
        Expr::JsonAccess {
            expr: left,
            path: right,
            arrow,
            ..
        } => {
            function_registry
                .resolve_scalar(json_access_function_name(*arrow), 2)
                .is_some_and(|resolved| resolved.query_constancy().is_query_constant())
                && values_expr_is_query_constant(left, function_registry)
                && values_expr_is_query_constant(right, function_registry)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => values_expr_is_query_constant(expr, function_registry),
        Expr::Between {
            expr, low, high, ..
        } => {
            values_expr_is_query_constant(expr, function_registry)
                && values_expr_is_query_constant(low, function_registry)
                && values_expr_is_query_constant(high, function_registry)
        }
        Expr::In { expr, set, .. } => {
            values_expr_is_query_constant(expr, function_registry)
                && matches!(set, InSet::List(values) if values
                    .iter()
                    .all(|value| values_expr_is_query_constant(value, function_registry)))
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            op,
            ..
        } => {
            let (name, arity) = match op {
                LikeOp::Like => ("like", if escape.is_some() { 3 } else { 2 }),
                LikeOp::Glob => ("glob", 2),
                LikeOp::Match => ("match", 2),
                LikeOp::Regexp => ("regexp", 2),
            };
            function_registry
                .resolve_scalar(name, arity)
                .is_some_and(|resolved| resolved.query_constancy().is_query_constant())
                && values_expr_is_query_constant(expr, function_registry)
                && values_expr_is_query_constant(pattern, function_registry)
                && escape
                    .as_deref()
                    .is_none_or(|value| values_expr_is_query_constant(value, function_registry))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_none_or(|value| values_expr_is_query_constant(value, function_registry))
                && whens.iter().all(|(condition, value)| {
                    values_expr_is_query_constant(condition, function_registry)
                        && values_expr_is_query_constant(value, function_registry)
                })
                && else_expr
                    .as_deref()
                    .is_none_or(|value| values_expr_is_query_constant(value, function_registry))
        }
        Expr::FunctionCall {
            name,
            args,
            distinct,
            order_by,
            filter,
            over,
            ..
        } => {
            if *distinct || !order_by.is_empty() || filter.is_some() || over.is_some() {
                return false;
            }
            let FunctionArgs::List(args) = args else {
                return false;
            };
            let Ok(arity) = i32::try_from(args.len()) else {
                return false;
            };
            args.iter()
                .all(|value| values_expr_is_query_constant(value, function_registry))
                && function_registry
                    .resolve_scalar(name, arity)
                    .is_some_and(|resolved| resolved.query_constancy().is_query_constant())
        }
        Expr::RowValue(values, _) => values
            .iter()
            .all(|value| values_expr_is_query_constant(value, function_registry)),
        Expr::BoundOuterValue { .. }
        | Expr::Column(_, _)
        | Expr::Subquery(_, _)
        | Expr::Exists { .. }
        | Expr::Raise { .. } => false,
    }
}

/// Return whether `sqlite3ExprAffinity()` observes affinity on a VALUES cell
/// before name resolution. A top-level CAST is decisive even for BLOB; unary
/// arithmetic and ordinary computed expressions do not inherit child
/// affinity. COLLATE is the one parser wrapper that SQLite skips.
fn values_expr_has_affinity(expr: &Expr) -> bool {
    match expr {
        Expr::BoundOuterValue { affinity, .. } => affinity.is_some(),
        Expr::Column(_, _) | Expr::Cast { .. } | Expr::Subquery(_, _) => true,
        Expr::Collate { expr, .. } => values_expr_has_affinity(expr),
        Expr::RowValue(values, _) => values.first().is_some_and(values_expr_has_affinity),
        _ => false,
    }
}

/// Match SQLite's constant-expression eligibility for the one-element IN-list
/// rewrite that turns `lhs IN (rhs)` into a binary comparison.  The rewrite is
/// semantically observable because only that form allows an explicit RHS
/// collation to participate.  Frozen registry metadata is consulted without
/// invoking user code; dynamic date/time and non-deterministic scalars remain
/// genuine IN-list terms.
fn singleton_in_rhs_is_constant(expr: &Expr, registry: &FunctionRegistry) -> bool {
    match expr {
        Expr::Literal(
            Literal::CurrentTime | Literal::CurrentDate | Literal::CurrentTimestamp,
            _,
        ) => false,
        Expr::Literal(_, _) | Expr::Placeholder(_, _) => true,
        Expr::BinaryOp { left, right, .. } => {
            singleton_in_rhs_is_constant(left, registry)
                && singleton_in_rhs_is_constant(right, registry)
        }
        Expr::JsonAccess {
            expr: left,
            path: right,
            arrow,
            ..
        } => {
            let name = match arrow {
                fsqlite_ast::JsonArrow::Arrow => "->",
                fsqlite_ast::JsonArrow::DoubleArrow => "->>",
            };
            registry.scalar_schema_safety(name, 2) == Some(ScalarSchemaSafety::Always)
                && singleton_in_rhs_is_constant(left, registry)
                && singleton_in_rhs_is_constant(right, registry)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. } => singleton_in_rhs_is_constant(expr, registry),
        Expr::Between {
            expr, low, high, ..
        } => {
            singleton_in_rhs_is_constant(expr, registry)
                && singleton_in_rhs_is_constant(low, registry)
                && singleton_in_rhs_is_constant(high, registry)
        }
        Expr::In { expr, set, .. } => {
            singleton_in_rhs_is_constant(expr, registry)
                && matches!(set, InSet::List(values) if values
                    .iter()
                    .all(|value| singleton_in_rhs_is_constant(value, registry)))
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            op,
            ..
        } => {
            let (name, arity) = match op {
                LikeOp::Like => ("like", if escape.is_some() { 3 } else { 2 }),
                LikeOp::Glob => ("glob", 2),
                LikeOp::Match => ("match", 2),
                LikeOp::Regexp => ("regexp", 2),
            };
            registry.scalar_schema_safety(name, arity) == Some(ScalarSchemaSafety::Always)
                && singleton_in_rhs_is_constant(expr, registry)
                && singleton_in_rhs_is_constant(pattern, registry)
                && escape
                    .as_deref()
                    .is_none_or(|value| singleton_in_rhs_is_constant(value, registry))
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_none_or(|value| singleton_in_rhs_is_constant(value, registry))
                && whens.iter().all(|(condition, value)| {
                    singleton_in_rhs_is_constant(condition, registry)
                        && singleton_in_rhs_is_constant(value, registry)
                })
                && else_expr
                    .as_deref()
                    .is_none_or(|value| singleton_in_rhs_is_constant(value, registry))
        }
        Expr::FunctionCall {
            name,
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if !order_by.is_empty() || filter.is_some() || over.is_some() {
                return false;
            }
            let (arity, arguments_are_constant) = match args {
                FunctionArgs::Star => (0, true),
                FunctionArgs::List(values) => {
                    let Ok(arity) = i32::try_from(values.len()) else {
                        return false;
                    };
                    (
                        arity,
                        values
                            .iter()
                            .all(|value| singleton_in_rhs_is_constant(value, registry)),
                    )
                }
            };
            arguments_are_constant
                && registry.scalar_schema_safety(name, arity) == Some(ScalarSchemaSafety::Always)
        }
        Expr::RowValue(values, _) => values
            .iter()
            .all(|value| singleton_in_rhs_is_constant(value, registry)),
        Expr::BoundOuterValue { .. }
        | Expr::Column(_, _)
        | Expr::Subquery(_, _)
        | Expr::Exists { .. }
        | Expr::Raise { .. } => false,
    }
}

/// Return the single explicit COLLATE name inherited by `expr`.
///
/// This mirrors SQLite's `EP_Collate` winner walk: an outer COLLATE stops the
/// search, and otherwise the first collated child in SQLite's expression-list
/// order wins. It deliberately does not enumerate every COLLATE descendant.
fn first_explicit_collation_name(expr: &Expr) -> Option<&str> {
    if expr_folds_to_integer_zero_via_and(expr) {
        return None;
    }
    match expr {
        Expr::Literal(_, _)
        | Expr::BoundOuterValue { .. }
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _)
        | Expr::Subquery(_, _)
        | Expr::Exists { .. } => None,
        Expr::BinaryOp { left, right, .. } => {
            first_explicit_collation_name(left).or_else(|| first_explicit_collation_name(right))
        }
        Expr::UnaryOp { expr, .. } | Expr::IsNull { expr, .. } | Expr::Cast { expr, .. } => {
            first_explicit_collation_name(expr)
        }
        Expr::Collate { collation, .. } => Some(collation),
        Expr::Between {
            expr, low, high, ..
        } => first_explicit_collation_name(expr)
            .or_else(|| first_explicit_collation_name(low))
            .or_else(|| first_explicit_collation_name(high)),
        Expr::In { expr, set, .. } => match set {
            InSet::List(values) if values.is_empty() => None,
            InSet::List(values) => first_explicit_collation_name(expr)
                .or_else(|| values.iter().find_map(first_explicit_collation_name)),
            InSet::Subquery(_) | InSet::Table(_) => first_explicit_collation_name(expr),
        },
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => first_explicit_collation_name(pattern)
            .or_else(|| first_explicit_collation_name(expr))
            .or_else(|| escape.as_deref().and_then(first_explicit_collation_name)),
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => operand
            .as_deref()
            .and_then(first_explicit_collation_name)
            .or_else(|| {
                whens.iter().find_map(|(condition, value)| {
                    first_explicit_collation_name(condition)
                        .or_else(|| first_explicit_collation_name(value))
                })
            })
            .or_else(|| else_expr.as_deref().and_then(first_explicit_collation_name)),
        Expr::FunctionCall { args, .. } => match args {
            FunctionArgs::Star => None,
            FunctionArgs::List(values) => values.iter().find_map(first_explicit_collation_name),
        },
        Expr::JsonAccess { expr, path, .. } => {
            first_explicit_collation_name(expr).or_else(|| first_explicit_collation_name(path))
        }
        Expr::RowValue(values, _) => values.first().and_then(first_explicit_collation_name),
    }
}

fn validate_expr_collation_boundary(
    connection: &Connection,
    expr: &Expr,
    registry: &CollationRegistry,
) -> Result<()> {
    validate_expr_collation_winner(expr, registry)?;
    validate_expr_collation_consumers(connection, expr, registry)
}

/// Validate every collation dependency that VDBE codegen can inherit from the
/// indexed table's declared column collations.
///
/// The general expression boundary above handles explicit `COLLATE` operators,
/// but it deliberately has no table-binding context. Index expressions and
/// partial predicates do: comparisons such as `tag > 'x'` inherit `tag`'s
/// declared collation during codegen. Missing that dependency would let an
/// unresolved application collation silently fall back to binary comparison
/// while rebuilding or maintaining the index.
fn validate_index_expr_collation_dependencies(
    connection: &Connection,
    expr: &Expr,
    table: &TableSchema,
    registry: &CollationRegistry,
) -> Result<()> {
    // The bound index metadata validates the root key collation separately.
    // A nested COLLATE is otherwise opaque until an internal comparison,
    // DISTINCT/order operation, or collation-consuming scalar actually uses
    // it.  Validating the expression's generic winner here would incorrectly
    // reject SQLite-valid keys such as `lower(x COLLATE missing)`, whose stored
    // ordering is BINARY and whose function is collation-opaque.
    validate_expr_collation_consumers(connection, expr, registry)?;
    validate_index_expr_inherited_collation_consumers(connection, expr, table, registry)
}

/// Reach a column whose declared collation is inherited by a comparison
/// operand. This mirrors VDBE codegen's `declared_collation_source_expr` walk.
fn index_declared_collation_source_expr(expr: &Expr) -> &Expr {
    match expr {
        Expr::Collate { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::UnaryOp {
            op: UnaryOp::Plus,
            expr,
            ..
        } => index_declared_collation_source_expr(expr),
        _ => expr,
    }
}

fn index_expr_effective_collation<'a>(expr: &'a Expr, table: &'a TableSchema) -> Option<&'a str> {
    if let Some(collation) = first_explicit_collation_name(expr) {
        return Some(collation);
    }
    index_expr_declared_collation(expr, table)
}

fn index_expr_declared_collation<'a>(expr: &Expr, table: &'a TableSchema) -> Option<&'a str> {
    let Expr::Column(column, _) = index_declared_collation_source_expr(expr) else {
        return None;
    };
    if column
        .table
        .as_deref()
        .is_some_and(|qualifier| !qualifier.eq_ignore_ascii_case(&table.name))
    {
        return None;
    }
    if let Some(index) = table.column_index(&column.column) {
        return Some(
            table.columns[index]
                .collation
                .as_deref()
                .unwrap_or("BINARY"),
        );
    }
    table_exposes_hidden_rowid_alias(table, &column.column).then_some("BINARY")
}

fn index_comparison_collation<'a>(
    left: &'a Expr,
    right: &'a Expr,
    table: &'a TableSchema,
) -> Option<&'a str> {
    first_explicit_collation_name(left)
        .or_else(|| first_explicit_collation_name(right))
        .or_else(|| index_expr_declared_collation(left, table))
        .or_else(|| index_expr_declared_collation(right, table))
}

fn index_comparison_uses_collation(
    left: &Expr,
    right: &Expr,
    table: &TableSchema,
    target: &str,
) -> bool {
    index_comparison_collation(left, right, table)
        .is_some_and(|collation| collation.eq_ignore_ascii_case(target))
}

#[allow(clippy::too_many_lines)]
fn index_expr_uses_collation_dependency(
    connection: &Connection,
    expr: &Expr,
    table: &TableSchema,
    target: &str,
) -> bool {
    if expr_folds_to_integer_zero_via_and(expr) {
        return false;
    }
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _)
        | Expr::Subquery(_, _)
        | Expr::Exists { .. } => false,
        Expr::BinaryOp {
            left, op, right, ..
        } => {
            let consumes = binary_op_consumes_collation(*op)
                && !matches!(
                    (*op, right.as_ref()),
                    (
                        BinaryOp::Is | BinaryOp::IsNot,
                        Expr::Literal(Literal::True | Literal::False, _)
                    )
                )
                && index_comparison_uses_collation(left, right, table, target);
            consumes
                || index_expr_uses_collation_dependency(connection, left, table, target)
                || index_expr_uses_collation_dependency(connection, right, table, target)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            index_expr_uses_collation_dependency(connection, expr, table, target)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            index_comparison_uses_collation(expr, low, table, target)
                || index_comparison_uses_collation(expr, high, table, target)
                || index_expr_uses_collation_dependency(connection, expr, table, target)
                || index_expr_uses_collation_dependency(connection, low, table, target)
                || index_expr_uses_collation_dependency(connection, high, table, target)
        }
        Expr::In { expr, set, .. } => {
            let consumes = match set {
                InSet::List(values) if values.is_empty() => false,
                InSet::List(values) if values.len() == 1 => {
                    let registry = connection.func_registry.borrow();
                    if singleton_in_rhs_is_constant(&values[0], &registry) {
                        index_comparison_uses_collation(expr, &values[0], table, target)
                    } else {
                        index_expr_effective_collation(expr, table)
                            .is_some_and(|collation| collation.eq_ignore_ascii_case(target))
                    }
                }
                InSet::List(_) | InSet::Subquery(_) | InSet::Table(_) => {
                    index_expr_effective_collation(expr, table)
                        .is_some_and(|collation| collation.eq_ignore_ascii_case(target))
                }
            };
            consumes
                || index_expr_uses_collation_dependency(connection, expr, table, target)
                || match set {
                    InSet::List(values) => values.iter().any(|value| {
                        index_expr_uses_collation_dependency(connection, value, table, target)
                    }),
                    InSet::Subquery(_) | InSet::Table(_) => false,
                }
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            index_expr_uses_collation_dependency(connection, expr, table, target)
                || index_expr_uses_collation_dependency(connection, pattern, table, target)
                || escape.as_deref().is_some_and(|escape| {
                    index_expr_uses_collation_dependency(connection, escape, table, target)
                })
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            let simple_case_consumes = operand.as_deref().is_some_and(|operand| {
                whens.iter().any(|(condition, _)| {
                    index_comparison_uses_collation(operand, condition, table, target)
                })
            });
            simple_case_consumes
                || operand.as_deref().is_some_and(|operand| {
                    index_expr_uses_collation_dependency(connection, operand, table, target)
                })
                || whens.iter().any(|(condition, value)| {
                    index_expr_uses_collation_dependency(connection, condition, table, target)
                        || index_expr_uses_collation_dependency(connection, value, table, target)
                })
                || else_expr.as_deref().is_some_and(|else_expr| {
                    index_expr_uses_collation_dependency(connection, else_expr, table, target)
                })
        }
        Expr::FunctionCall {
            name,
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let values = match args {
                FunctionArgs::Star => &[][..],
                FunctionArgs::List(values) => values.as_slice(),
            };
            let function_consumes =
                function_consumes_argument_collation(connection, name, args, over.as_ref())
                    && values
                        .iter()
                        .find_map(|value| index_expr_effective_collation(value, table))
                        .is_some_and(|collation| collation.eq_ignore_ascii_case(target));
            function_consumes
                || values.iter().any(|value| {
                    index_expr_uses_collation_dependency(connection, value, table, target)
                })
                || order_by.iter().any(|term| {
                    index_expr_uses_collation_dependency(connection, &term.expr, table, target)
                })
                || filter.as_deref().is_some_and(|filter| {
                    index_expr_uses_collation_dependency(connection, filter, table, target)
                })
        }
        Expr::JsonAccess {
            expr, path, arrow, ..
        } => {
            let function_consumes = connection
                .func_registry
                .borrow()
                .scalar_consumes_argument_collation(json_access_function_name(*arrow), 2)
                .unwrap_or(false)
                && [expr.as_ref(), path.as_ref()]
                    .into_iter()
                    .find_map(|value| index_expr_effective_collation(value, table))
                    .is_some_and(|collation| collation.eq_ignore_ascii_case(target));
            function_consumes
                || index_expr_uses_collation_dependency(connection, expr, table, target)
                || index_expr_uses_collation_dependency(connection, path, table, target)
        }
        Expr::RowValue(values, _) => values
            .iter()
            .any(|value| index_expr_uses_collation_dependency(connection, value, table, target)),
    }
}

fn validate_index_binary_comparison_collation(
    left: &Expr,
    right: &Expr,
    table: &TableSchema,
    registry: &CollationRegistry,
) -> Result<()> {
    if let Some(collation) = index_comparison_collation(left, right, table) {
        validate_registered_collation(collation, registry)?;
    }
    Ok(())
}

#[allow(clippy::too_many_lines)]
fn validate_index_expr_inherited_collation_consumers(
    connection: &Connection,
    expr: &Expr,
    table: &TableSchema,
    registry: &CollationRegistry,
) -> Result<()> {
    if expr_folds_to_integer_zero_via_and(expr) {
        return Ok(());
    }
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => Ok(()),
        Expr::BinaryOp {
            left, op, right, ..
        } => {
            if matches!(
                *op,
                BinaryOp::Eq
                    | BinaryOp::Ne
                    | BinaryOp::Lt
                    | BinaryOp::Le
                    | BinaryOp::Gt
                    | BinaryOp::Ge
                    | BinaryOp::Is
                    | BinaryOp::IsNot
            ) && !matches!(
                (*op, right.as_ref()),
                (
                    BinaryOp::Is | BinaryOp::IsNot,
                    Expr::Literal(Literal::True | Literal::False, _)
                )
            ) {
                validate_index_binary_comparison_collation(left, right, table, registry)?;
            }
            validate_index_expr_inherited_collation_consumers(connection, left, table, registry)?;
            validate_index_expr_inherited_collation_consumers(connection, right, table, registry)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            validate_index_expr_inherited_collation_consumers(connection, expr, table, registry)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            validate_index_binary_comparison_collation(expr, low, table, registry)?;
            validate_index_binary_comparison_collation(expr, high, table, registry)?;
            validate_index_expr_inherited_collation_consumers(connection, expr, table, registry)?;
            validate_index_expr_inherited_collation_consumers(connection, low, table, registry)?;
            validate_index_expr_inherited_collation_consumers(connection, high, table, registry)
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return Ok(());
            }
            if let InSet::List(values) = set
                && let [value] = values.as_slice()
            {
                let function_registry = connection.func_registry.borrow();
                if singleton_in_rhs_is_constant(value, &function_registry) {
                    validate_index_binary_comparison_collation(expr, value, table, registry)?;
                } else if let Some(collation) = index_expr_effective_collation(expr, table) {
                    validate_registered_collation(collation, registry)?;
                }
            } else if let Some(collation) = index_expr_effective_collation(expr, table) {
                validate_registered_collation(collation, registry)?;
            }
            validate_index_expr_inherited_collation_consumers(connection, expr, table, registry)?;
            if let InSet::List(values) = set {
                for value in values {
                    validate_index_expr_inherited_collation_consumers(
                        connection, value, table, registry,
                    )?;
                }
            }
            Ok(())
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            validate_index_expr_inherited_collation_consumers(connection, expr, table, registry)?;
            validate_index_expr_inherited_collation_consumers(
                connection, pattern, table, registry,
            )?;
            if let Some(escape) = escape {
                validate_index_expr_inherited_collation_consumers(
                    connection, escape, table, registry,
                )?;
            }
            Ok(())
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                for (condition, _) in whens {
                    validate_index_binary_comparison_collation(
                        operand, condition, table, registry,
                    )?;
                }
                validate_index_expr_inherited_collation_consumers(
                    connection, operand, table, registry,
                )?;
            }
            for (condition, value) in whens {
                validate_index_expr_inherited_collation_consumers(
                    connection, condition, table, registry,
                )?;
                validate_index_expr_inherited_collation_consumers(
                    connection, value, table, registry,
                )?;
            }
            if let Some(else_expr) = else_expr {
                validate_index_expr_inherited_collation_consumers(
                    connection, else_expr, table, registry,
                )?;
            }
            Ok(())
        }
        Expr::FunctionCall {
            name,
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if let FunctionArgs::List(values) = args {
                if function_consumes_argument_collation(connection, name, args, over.as_ref())
                    && let Some(collation) = values
                        .iter()
                        .find_map(|value| index_expr_effective_collation(value, table))
                {
                    validate_registered_collation(collation, registry)?;
                }
                for value in values {
                    validate_index_expr_inherited_collation_consumers(
                        connection, value, table, registry,
                    )?;
                }
            }
            for term in order_by {
                validate_index_expr_inherited_collation_consumers(
                    connection, &term.expr, table, registry,
                )?;
            }
            if let Some(filter) = filter {
                validate_index_expr_inherited_collation_consumers(
                    connection, filter, table, registry,
                )?;
            }
            Ok(())
        }
        Expr::JsonAccess {
            expr, path, arrow, ..
        } => {
            if connection
                .func_registry
                .borrow()
                .scalar_consumes_argument_collation(json_access_function_name(*arrow), 2)
                .unwrap_or(false)
                && let Some(collation) = [expr.as_ref(), path.as_ref()]
                    .into_iter()
                    .find_map(|value| index_expr_effective_collation(value, table))
            {
                validate_registered_collation(collation, registry)?;
            }
            validate_index_expr_inherited_collation_consumers(connection, expr, table, registry)?;
            validate_index_expr_inherited_collation_consumers(connection, path, table, registry)
        }
        Expr::RowValue(values, _) => {
            for value in values {
                validate_index_expr_inherited_collation_consumers(
                    connection, value, table, registry,
                )?;
            }
            Ok(())
        }
        // Subqueries are rejected by the index binder. Leave their own schema
        // scopes to the general expression validator if a corrupt catalog ever
        // reaches this defensive runtime boundary.
        Expr::Subquery(_, _) | Expr::Exists { .. } => Ok(()),
    }
}

fn validate_expr_collation_winner(expr: &Expr, registry: &CollationRegistry) -> Result<()> {
    if let Some(collation) = first_explicit_collation_name(expr) {
        validate_registered_collation(collation, registry)?;
    }
    Ok(())
}

fn validate_binary_comparison_collation(
    left: &Expr,
    right: &Expr,
    registry: &CollationRegistry,
) -> Result<()> {
    if let (Some(left_values), Some(right_values)) = (
        vector_comparison_fields(left),
        vector_comparison_fields(right),
    ) {
        for (left_value, right_value) in left_values.iter().zip(right_values) {
            validate_binary_comparison_collation(left_value, right_value, registry)?;
        }
        return Ok(());
    }
    if let Some(collation) =
        first_explicit_collation_name(left).or_else(|| first_explicit_collation_name(right))
    {
        validate_registered_collation(collation, registry)?;
    }
    Ok(())
}

fn binary_op_consumes_collation(op: BinaryOp) -> bool {
    matches!(
        op,
        BinaryOp::Eq
            | BinaryOp::Ne
            | BinaryOp::Lt
            | BinaryOp::Le
            | BinaryOp::Gt
            | BinaryOp::Ge
            | BinaryOp::Is
            | BinaryOp::IsNot
    )
}

fn selected_function_is_builtin(
    connection: &Connection,
    name: &str,
    args: &FunctionArgs,
    over: Option<&WindowSpec>,
) -> bool {
    let arity = aggregate_args_len_for_lookup(args);
    let current = connection.func_registry.borrow();
    let builtin = shared_builtin_function_registry();

    if over.is_some() {
        if current.window_accepts_arg_count(name, arity) != Some(true)
            || builtin.window_accepts_arg_count(name, arity) != Some(true)
        {
            return false;
        }
        return match (
            current.find_window(name, arity),
            builtin.find_window(name, arity),
        ) {
            (Some(current), Some(builtin)) => Arc::ptr_eq(&current, &builtin),
            _ => false,
        };
    }

    if connection.function_call_is_current_aggregate(name, args) {
        if current.aggregate_accepts_arg_count(name, arity) != Some(true)
            || builtin.aggregate_accepts_arg_count(name, arity) != Some(true)
        {
            return false;
        }
        return match (
            current.find_aggregate(name, arity),
            builtin.find_aggregate(name, arity),
        ) {
            (Some(current), Some(builtin)) => Arc::ptr_eq(&current, &builtin),
            _ => false,
        };
    }

    if current.scalar_accepts_arg_count(name, arity) != Some(true)
        || builtin.scalar_accepts_arg_count(name, arity) != Some(true)
    {
        return false;
    }
    match (
        current.find_scalar(name, arity),
        builtin.find_scalar(name, arity),
    ) {
        (Some(current), Some(builtin)) => Arc::ptr_eq(&current, &builtin),
        _ => false,
    }
}

fn function_consumes_argument_collation(
    connection: &Connection,
    name: &str,
    args: &FunctionArgs,
    over: Option<&WindowSpec>,
) -> bool {
    if over.is_some() || connection.function_call_is_current_aggregate(name, args) {
        return false;
    }
    connection
        .func_registry
        .borrow()
        .scalar_consumes_argument_collation(name, aggregate_args_len_for_lookup(args))
        .unwrap_or(false)
}

#[allow(clippy::too_many_lines)]
fn validate_expr_collation_consumers(
    connection: &Connection,
    expr: &Expr,
    registry: &CollationRegistry,
) -> Result<()> {
    if expr_folds_to_integer_zero_via_and(expr) {
        return Ok(());
    }
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => Ok(()),
        Expr::BinaryOp {
            left, op, right, ..
        } => {
            if binary_op_consumes_collation(*op) {
                validate_direct_subquery_collation_consumers(connection, left, registry)?;
                validate_direct_subquery_collation_consumers(connection, right, registry)?;
                validate_binary_comparison_collation(left, right, registry)?;
            }
            validate_expr_collation_consumers(connection, left, registry)?;
            validate_expr_collation_consumers(connection, right, registry)?;
            Ok(())
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            validate_expr_collation_consumers(connection, expr, registry)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            validate_direct_subquery_collation_consumers(connection, expr, registry)?;
            validate_direct_subquery_collation_consumers(connection, low, registry)?;
            validate_binary_comparison_collation(expr, low, registry)?;
            validate_expr_collation_consumers(connection, expr, registry)?;
            validate_expr_collation_consumers(connection, low, registry)?;
            validate_direct_subquery_collation_consumers(connection, high, registry)?;
            validate_binary_comparison_collation(expr, high, registry)?;
            validate_expr_collation_consumers(connection, high, registry)?;
            Ok(())
        }
        Expr::In { expr, set, .. } => {
            let normalized_set = normalize_bare_singleton_in_subquery(set);
            let set = normalized_set.as_ref();
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return Ok(());
            }
            match set {
                InSet::List(values) => {
                    validate_in_list_membership_collations(connection, expr, values, registry)?;
                    validate_expr_collation_consumers(connection, expr, registry)?;
                    for value in values {
                        validate_expr_collation_consumers(connection, value, registry)?;
                    }
                }
                InSet::Subquery(subquery) => {
                    let multirow_values = matches!(
                        &subquery.body.select,
                        SelectCore::Values(rows) if rows.len() > 1
                    );
                    if multirow_values {
                        validate_select_collation_consumers(
                            connection,
                            subquery,
                            SubqueryCollationUse::InRhs,
                            registry,
                        )?;
                    }
                    validate_expr_collation_consumers(connection, expr, registry)?;
                    if !multirow_values {
                        validate_select_collation_consumers(
                            connection,
                            subquery,
                            SubqueryCollationUse::InRhs,
                            registry,
                        )?;
                    }
                    validate_in_subquery_comparison_collations(expr, subquery, registry)?;
                }
                InSet::Table(_) => {
                    validate_expr_collation_consumers(connection, expr, registry)?;
                }
            }
            Ok(())
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            validate_expr_collation_consumers(connection, pattern, registry)?;
            validate_expr_collation_consumers(connection, expr, registry)?;
            if let Some(escape) = escape {
                validate_expr_collation_consumers(connection, escape, registry)?;
            }
            Ok(())
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                if let Some((first_condition, _)) = whens.first() {
                    validate_direct_subquery_collation_consumers(connection, operand, registry)?;
                    validate_direct_subquery_collation_consumers(
                        connection,
                        first_condition,
                        registry,
                    )?;
                    validate_binary_comparison_collation(operand, first_condition, registry)?;
                }
                validate_expr_collation_consumers(connection, operand, registry)?;
                for (index, (condition, value)) in whens.iter().enumerate() {
                    if index != 0 {
                        validate_direct_subquery_collation_consumers(
                            connection, condition, registry,
                        )?;
                        validate_binary_comparison_collation(operand, condition, registry)?;
                    }
                    validate_expr_collation_consumers(connection, condition, registry)?;
                    validate_expr_collation_consumers(connection, value, registry)?;
                }
            } else {
                for (condition, value) in whens {
                    validate_expr_collation_consumers(connection, condition, registry)?;
                    validate_expr_collation_consumers(connection, value, registry)?;
                }
            }
            if let Some(else_expr) = else_expr {
                validate_expr_collation_consumers(connection, else_expr, registry)?;
            }
            Ok(())
        }
        Expr::FunctionCall {
            name,
            args,
            distinct,
            order_by,
            filter,
            over,
            ..
        } => {
            let unary_min_or_max = matches!(args, FunctionArgs::List(values) if values.len() == 1)
                && (name.eq_ignore_ascii_case("min") || name.eq_ignore_ascii_case("max"))
                && selected_function_is_builtin(connection, name, args, over.as_ref());
            if !unary_min_or_max {
                for term in order_by.iter().rev() {
                    validate_expr_collation_boundary(connection, &term.expr, registry)?;
                }
            }
            if let FunctionArgs::List(values) = args {
                if *distinct {
                    for value in values {
                        validate_expr_collation_boundary(connection, value, registry)?;
                    }
                }
                if function_consumes_argument_collation(connection, name, args, over.as_ref()) {
                    validate_function_argument_collation(values, registry)?;
                }
            }
            if let Some(filter) = filter {
                validate_expr_collation_consumers(connection, filter, registry)?;
            }
            if let FunctionArgs::List(values) = args {
                for value in values {
                    validate_expr_collation_consumers(connection, value, registry)?;
                }
            }
            Ok(())
        }
        Expr::Subquery(subquery, _) => validate_select_collation_consumers(
            connection,
            subquery,
            SubqueryCollationUse::Scalar,
            registry,
        ),
        Expr::Exists { subquery, .. } => validate_select_collation_consumers(
            connection,
            subquery,
            SubqueryCollationUse::Exists,
            registry,
        ),
        Expr::JsonAccess {
            expr, path, arrow, ..
        } => {
            if connection
                .func_registry
                .borrow()
                .scalar_consumes_argument_collation(json_access_function_name(*arrow), 2)
                .unwrap_or(false)
            {
                validate_function_argument_collation([expr.as_ref(), path.as_ref()], registry)?;
            }
            validate_expr_collation_consumers(connection, expr, registry)?;
            validate_expr_collation_consumers(connection, path, registry)
        }
        Expr::RowValue(values, _) => {
            for value in values {
                validate_expr_collation_consumers(connection, value, registry)?;
            }
            Ok(())
        }
    }
}

fn validate_direct_subquery_collation_consumers(
    connection: &Connection,
    expr: &Expr,
    registry: &CollationRegistry,
) -> Result<()> {
    match expr {
        Expr::Subquery(select, _) => validate_select_collation_consumers(
            connection,
            select,
            SubqueryCollationUse::Scalar,
            registry,
        ),
        Expr::Exists { subquery, .. } => validate_select_collation_consumers(
            connection,
            subquery,
            SubqueryCollationUse::Exists,
            registry,
        ),
        _ => Ok(()),
    }
}

fn validate_in_list_membership_collations(
    connection: &Connection,
    lhs: &Expr,
    values: &[Expr],
    registry: &CollationRegistry,
) -> Result<()> {
    if let Some(lhs_values) = vector_comparison_fields(lhs)
        && let Some(rhs_values) = values.last().and_then(vector_comparison_fields)
    {
        for (lhs_value, rhs_value) in lhs_values.iter().zip(rhs_values).rev() {
            validate_binary_comparison_collation(lhs_value, rhs_value, registry)?;
        }
        Ok(())
    } else if let [value] = values {
        let function_registry = connection.func_registry.borrow();
        if singleton_in_rhs_is_constant(value, &function_registry) {
            validate_binary_comparison_collation(lhs, value, registry)
        } else {
            validate_in_lhs_collations(lhs, registry)
        }
    } else {
        validate_in_lhs_collations(lhs, registry)
    }
}

fn validate_in_lhs_collations(lhs: &Expr, registry: &CollationRegistry) -> Result<()> {
    if let Expr::RowValue(values, _) = lhs {
        for value in values {
            if let Some(collation) = first_explicit_collation_name(value) {
                validate_registered_collation(collation, registry)?;
            }
        }
    } else if let Some(collation) = first_explicit_collation_name(lhs) {
        validate_registered_collation(collation, registry)?;
    }
    Ok(())
}

fn validate_in_subquery_comparison_collations(
    lhs: &Expr,
    subquery: &SelectStatement,
    registry: &CollationRegistry,
) -> Result<()> {
    let final_core = subquery
        .body
        .compounds
        .last()
        .map_or(&subquery.body.select, |(_, core)| core);
    let rhs_values = select_core_result_exprs(final_core);
    if let Some(lhs_values) = vector_comparison_fields(lhs) {
        for (index, lhs_value) in lhs_values.iter().enumerate().rev() {
            if let Some(rhs_value) = rhs_values
                .as_ref()
                .and_then(|values| values.get(index).copied())
            {
                validate_binary_comparison_collation(lhs_value, rhs_value, registry)?;
            } else if let Some(collation) = first_explicit_collation_name(lhs_value) {
                validate_registered_collation(collation, registry)?;
            }
        }
    } else if let Some(rhs_value) = rhs_values
        .as_ref()
        .and_then(|values| values.first().copied())
    {
        validate_binary_comparison_collation(lhs, rhs_value, registry)?;
    } else {
        validate_in_lhs_collations(lhs, registry)?;
    }
    Ok(())
}

fn vector_comparison_fields(expr: &Expr) -> Option<Vec<&Expr>> {
    match expr {
        Expr::RowValue(values, _) if values.len() > 1 => Some(values.iter().collect()),
        Expr::Subquery(select, _) => {
            let final_core = select
                .body
                .compounds
                .last()
                .map_or(&select.body.select, |(_, core)| core);
            select_core_result_exprs(final_core).filter(|values| values.len() > 1)
        }
        _ => None,
    }
}

/// SQLite parses `IN ((SELECT ...))` as a one-element expression list, but
/// treats that exact bare-subquery shape as the set-producing `IN (SELECT ...)`
/// form. Wrapping the subquery in any other expression keeps scalar semantics.
fn normalize_bare_singleton_in_subquery(set: &InSet) -> Cow<'_, InSet> {
    if let InSet::List(values) = set
        && let [Expr::Subquery(subquery, _)] = values.as_slice()
    {
        Cow::Owned(InSet::Subquery(subquery.clone()))
    } else {
        Cow::Borrowed(set)
    }
}

/// Preserve the runtime evaluation of an `IN` LHS after an executed subquery
/// produces no rows. A syntactic `IN ()` is folded earlier and skips its LHS,
/// while a runtime-empty subquery still evaluates every LHS field before
/// returning false (or true for `NOT IN`).
fn empty_in_result_after_evaluating_lhs(lhs: Expr, not: bool, span: Span) -> Expr {
    let fields = match lhs {
        Expr::RowValue(fields, _) => fields,
        scalar => vec![scalar],
    };
    let mut evaluations = fields
        .into_iter()
        .map(|field| Expr::IsNull {
            expr: Box::new(field),
            not: false,
            span,
        })
        .collect::<Vec<_>>();
    // Build a balanced arithmetic tree. Binary arithmetic evaluates both
    // operands from left to right, so every field remains observable without
    // recreating the deep, left-nested expression trees that previously
    // overflowed the worker stack for generated predicates.
    while evaluations.len() > 1 {
        let mut next = Vec::with_capacity(evaluations.len().div_ceil(2));
        let mut pairs = evaluations.into_iter();
        while let Some(left) = pairs.next() {
            if let Some(right) = pairs.next() {
                next.push(Expr::BinaryOp {
                    left: Box::new(left),
                    op: BinaryOp::Add,
                    right: Box::new(right),
                    span,
                });
            } else {
                next.push(left);
            }
        }
        evaluations = next;
    }
    let evaluated = evaluations
        .pop()
        .unwrap_or(Expr::Literal(Literal::Integer(0), span));
    let false_result = Expr::BinaryOp {
        left: Box::new(evaluated),
        op: BinaryOp::Multiply,
        right: Box::new(Expr::Literal(Literal::Integer(0), span)),
        span,
    };
    if not {
        Expr::BinaryOp {
            left: Box::new(false_result),
            op: BinaryOp::Add,
            right: Box::new(Expr::Literal(Literal::Integer(1), span)),
            span,
        }
    } else {
        false_result
    }
}

fn validate_vector_in_list_arity(lhs_width: usize, values: &[Expr]) -> Result<()> {
    for value in values {
        let actual = match value {
            Expr::RowValue(fields, _) => fields.len(),
            _ => 1,
        };
        if actual != lhs_width {
            let plural = if actual == 1 { "" } else { "s" };
            return Err(FrankenError::FunctionError(format!(
                "IN(...) element has {actual} term{plural} - expected {lhs_width}"
            )));
        }
    }
    Ok(())
}

fn validate_function_argument_collation<'expr>(
    values: impl IntoIterator<Item = &'expr Expr>,
    registry: &CollationRegistry,
) -> Result<()> {
    let mut pending_missing = None;
    for collation in values.into_iter().filter_map(first_explicit_collation_name) {
        if registry.contains(collation) {
            if let Some(missing) = pending_missing {
                return validate_registered_collation(missing, registry);
            }
            return Ok(());
        }
        pending_missing = Some(collation);
    }
    if let Some(missing) = pending_missing {
        validate_registered_collation(missing, registry)?;
    }
    Ok(())
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SubqueryCollationUse {
    Scalar,
    Exists,
    InRhs,
}

fn sqlite_ordinal(position: usize) -> String {
    let suffix = if (11..=13).contains(&(position % 100)) {
        "th"
    } else {
        match position % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        }
    };
    format!("{position}{suffix}")
}

fn nested_order_column_error(error: FrankenError) -> FrankenError {
    match error {
        FrankenError::Internal(detail) => detail.strip_prefix("column not found: ").map_or_else(
            || FrankenError::Internal(detail.clone()),
            |name| FrankenError::NoSuchColumn {
                name: name.to_owned(),
            },
        ),
        other => other,
    }
}

fn values_column_order_output_index(expr: &Expr, output_width: usize) -> Option<usize> {
    let Expr::Column(column, _) = strip_collate_wrappers(expr) else {
        return None;
    };
    if column.table.is_some() {
        return None;
    }
    let name = column.column.as_ref();
    let suffix = name.get("column".len()..)?;
    if !name.get(.."column".len())?.eq_ignore_ascii_case("column")
        || suffix.is_empty()
        || suffix.starts_with('0')
        || !suffix.bytes().all(|byte| byte.is_ascii_digit())
    {
        return None;
    }
    let ordinal = suffix.parse::<usize>().ok()?;
    let index = ordinal.checked_sub(1)?;
    (index < output_width).then_some(index)
}

#[derive(Debug)]
enum CompoundSourceQualifier {
    Table(QualifiedName),
    Unqualified(String),
}

impl CompoundSourceQualifier {
    fn binding(&self) -> &str {
        match self {
            Self::Table(name) => &name.name,
            Self::Unqualified(name) => name,
        }
    }

    fn matches(&self, target: &QualifiedName) -> bool {
        match self {
            Self::Table(name) => qualified_name_matches_table_binding(target, name, None),
            Self::Unqualified(name) => {
                target.schema.is_none() && name.eq_ignore_ascii_case(&target.name)
            }
        }
    }
}

#[derive(Debug)]
struct CompoundSourceProjection {
    qualifier: Option<CompoundSourceQualifier>,
}

#[derive(Debug)]
struct CompoundSourceOutputSlot {
    source_index: usize,
    column: String,
}

fn compound_source_qualifier(source: &TableOrSubquery) -> Option<CompoundSourceQualifier> {
    match source {
        TableOrSubquery::Table { name, alias, .. } => alias.as_ref().map_or_else(
            || Some(CompoundSourceQualifier::Table(name.clone())),
            |alias| Some(CompoundSourceQualifier::Unqualified(alias.clone())),
        ),
        TableOrSubquery::Subquery { alias, .. } => alias
            .as_ref()
            .map(|alias| CompoundSourceQualifier::Unqualified(alias.clone())),
        TableOrSubquery::TableFunction { name, alias, .. } => Some(
            CompoundSourceQualifier::Unqualified(alias.clone().unwrap_or_else(|| name.clone())),
        ),
        TableOrSubquery::ParenJoin(_) => None,
    }
}

fn collect_compound_source_output_slots(
    connection: &Connection,
    source: &TableOrSubquery,
    visible_ctes: &[fsqlite_ast::Cte],
    active_ctes: &mut Vec<String>,
    sources: &mut Vec<CompoundSourceProjection>,
    slots: &mut Vec<CompoundSourceOutputSlot>,
) -> Vec<usize> {
    if let TableOrSubquery::ParenJoin(from) = source {
        return collect_compound_from_output_slots(
            connection,
            from,
            visible_ctes,
            active_ctes,
            sources,
            slots,
        );
    }

    let source_index = sources.len();
    sources.push(CompoundSourceProjection {
        qualifier: compound_source_qualifier(source),
    });
    let column_names =
        connection.table_or_subquery_result_column_names(source, visible_ctes, active_ctes);
    let first_slot = slots.len();
    slots.extend(
        column_names
            .into_iter()
            .map(|column| CompoundSourceOutputSlot {
                source_index,
                column,
            }),
    );
    (first_slot..slots.len()).collect()
}

fn collect_compound_from_output_slots(
    connection: &Connection,
    from: &FromClause,
    visible_ctes: &[fsqlite_ast::Cte],
    active_ctes: &mut Vec<String>,
    sources: &mut Vec<CompoundSourceProjection>,
    slots: &mut Vec<CompoundSourceOutputSlot>,
) -> Vec<usize> {
    let mut visible = collect_compound_source_output_slots(
        connection,
        &from.source,
        visible_ctes,
        active_ctes,
        sources,
        slots,
    );
    for join in &from.joins {
        let right = collect_compound_source_output_slots(
            connection,
            &join.table,
            visible_ctes,
            active_ctes,
            sources,
            slots,
        );
        let using_columns = if join.join_type.natural {
            right
                .iter()
                .filter_map(|index| slots.get(*index))
                .filter(|right_slot| {
                    visible.iter().any(|left_index| {
                        slots.get(*left_index).is_some_and(|left_slot| {
                            left_slot.column.eq_ignore_ascii_case(&right_slot.column)
                        })
                    })
                })
                .map(|slot| slot.column.clone())
                .collect::<Vec<_>>()
        } else if let Some(JoinConstraint::Using(columns)) = &join.constraint {
            columns.clone()
        } else {
            Vec::new()
        };
        visible.extend(right.into_iter().filter(|index| {
            slots.get(*index).is_none_or(|slot| {
                !using_columns
                    .iter()
                    .any(|column| column.eq_ignore_ascii_case(&slot.column))
            })
        }));
    }
    visible
}

#[derive(Debug)]
enum CompoundOrderOutput<'a> {
    Explicit {
        expr: &'a Expr,
        alias: Option<&'a str>,
    },
    Source(usize),
}

#[derive(Debug)]
struct CompoundSelectOrderProjection<'a> {
    sources: Vec<CompoundSourceProjection>,
    source_slots: Vec<CompoundSourceOutputSlot>,
    outputs: Vec<CompoundOrderOutput<'a>>,
}

impl<'a> CompoundSelectOrderProjection<'a> {
    fn new(
        connection: &Connection,
        select: &SelectStatement,
        columns: &'a [ResultColumn],
        from: Option<&FromClause>,
        outer_ctes: &[fsqlite_ast::Cte],
    ) -> Self {
        let mut visible_ctes = outer_ctes.to_vec();
        if let Some(with) = &select.with {
            visible_ctes.extend(with.ctes.clone());
        }
        let mut active_ctes = Vec::new();
        let mut sources = Vec::new();
        let mut source_slots = Vec::new();
        let star_slots = from.map_or_else(Vec::new, |from_clause| {
            collect_compound_from_output_slots(
                connection,
                from_clause,
                &visible_ctes,
                &mut active_ctes,
                &mut sources,
                &mut source_slots,
            )
        });

        let mut outputs = Vec::new();
        for column in columns {
            match column {
                ResultColumn::Expr { expr, alias } => {
                    outputs.push(CompoundOrderOutput::Explicit {
                        expr,
                        alias: alias.as_deref(),
                    });
                }
                ResultColumn::Star => {
                    outputs.extend(star_slots.iter().copied().map(CompoundOrderOutput::Source));
                }
                ResultColumn::TableStar(qualifier) => {
                    outputs.extend(
                        source_slots
                            .iter()
                            .enumerate()
                            .filter(|(_, slot)| {
                                sources
                                    .get(slot.source_index)
                                    .and_then(|source| source.qualifier.as_ref())
                                    .is_some_and(|source_qualifier| {
                                        source_qualifier.matches(qualifier)
                                    })
                            })
                            .map(|(index, _)| CompoundOrderOutput::Source(index)),
                    );
                }
            }
        }

        Self {
            sources,
            source_slots,
            outputs,
        }
    }

    fn resolve(&self, expr: &Expr) -> Option<usize> {
        let base_expr = strip_collate_wrappers(expr);
        let order_column = if let Expr::Column(column, _) = base_expr {
            Some(column)
        } else {
            None
        };

        if let Some(column) = order_column
            && column.table.is_none()
            && let Some(index) = self.outputs.iter().position(|output| {
                matches!(
                    output,
                    CompoundOrderOutput::Explicit {
                        alias: Some(alias),
                        ..
                    } if alias.eq_ignore_ascii_case(&column.column)
                )
            })
        {
            return Some(index);
        }

        if let Some(column) = order_column
            && let Some(index) = self.outputs.iter().position(|output| match output {
                CompoundOrderOutput::Explicit { expr, .. } => {
                    let result_expr = match expr {
                        Expr::Collate { expr, .. } => expr.as_ref(),
                        _ => expr,
                    };
                    let Expr::Column(result_column, _) = result_expr else {
                        return false;
                    };
                    result_column.column.eq_ignore_ascii_case(&column.column)
                        && column.table.as_deref().is_none_or(|table| {
                            result_column.table.as_deref().is_some_and(|result_table| {
                                result_table.eq_ignore_ascii_case(table)
                            })
                        })
                }
                CompoundOrderOutput::Source(slot_index) => {
                    self.source_slots.get(*slot_index).is_some_and(|slot| {
                        slot.column.eq_ignore_ascii_case(&column.column)
                            && column.table.as_deref().is_none_or(|table| {
                                self.sources
                                    .get(slot.source_index)
                                    .and_then(|source| source.qualifier.as_ref())
                                    .is_some_and(|qualifier| {
                                        qualifier.binding().eq_ignore_ascii_case(table)
                                    })
                            })
                    })
                }
            })
        {
            return Some(index);
        }

        if let Some(index) = self.outputs.iter().position(|output| {
            matches!(
                output,
                CompoundOrderOutput::Explicit {
                    expr: output_expr,
                    ..
                } if exprs_match(expr, output_expr)
            )
        }) {
            return Some(index);
        }

        self.outputs.iter().position(|output| {
            matches!(
                output,
                CompoundOrderOutput::Explicit {
                    expr: output_expr,
                    ..
                } if exprs_match(base_expr, output_expr)
            )
        })
    }
}

#[derive(Debug)]
enum CompoundCoreOrderProjection<'a> {
    Values(&'a [Vec<Expr>]),
    Select(CompoundSelectOrderProjection<'a>),
}

impl CompoundCoreOrderProjection<'_> {
    fn resolve(&self, expr: &Expr) -> Option<usize> {
        match self {
            Self::Values(rows) => {
                let values = rows.first()?;
                if let Some(index) = values_column_order_output_index(expr, values.len()) {
                    return Some(index);
                }
                if rows.len() != 1 {
                    return None;
                }
                let base_expr = strip_collate_wrappers(expr);
                values
                    .iter()
                    .position(|value| exprs_match(expr, value))
                    .or_else(|| {
                        values
                            .iter()
                            .position(|value| exprs_match(base_expr, value))
                    })
            }
            Self::Select(projection) => projection.resolve(expr),
        }
    }
}

fn resolve_compound_order_output_indices(
    connection: &Connection,
    select: &SelectStatement,
    outer_ctes: &[fsqlite_ast::Cte],
) -> Result<Vec<usize>> {
    let mut cores = Vec::with_capacity(select.body.compounds.len() + 1);
    cores.push(&select.body.select);
    cores.extend(select.body.compounds.iter().map(|(_, core)| core));
    let projections = cores
        .iter()
        .map(|core| match core {
            SelectCore::Values(rows) => CompoundCoreOrderProjection::Values(rows),
            SelectCore::Select { columns, from, .. } => {
                CompoundCoreOrderProjection::Select(CompoundSelectOrderProjection::new(
                    connection,
                    select,
                    columns,
                    from.as_ref(),
                    outer_ctes,
                ))
            }
        })
        .collect::<Vec<_>>();
    let output_width = connection.compound_select_core_column_count_with_outer_ctes(
        select,
        &select.body.select,
        outer_ctes,
    );
    let output_width_i64 = i64::try_from(output_width).unwrap_or(i64::MAX);

    for (index, term) in select.order_by.iter().enumerate() {
        if let Some(ordinal) = connection_order_by_integer_ordinal(&term.expr)
            && (ordinal < 1 || ordinal > output_width_i64)
        {
            return Err(FrankenError::FunctionError(format!(
                "{} ORDER BY term out of range - should be between 1 and {output_width}",
                sqlite_ordinal(index + 1)
            )));
        }
    }

    select
        .order_by
        .iter()
        .enumerate()
        .map(|(index, term)| {
            if let Some(ordinal) = connection_order_by_integer_ordinal(&term.expr) {
                return usize::try_from(ordinal - 1).map_err(|_| {
                    FrankenError::FunctionError(format!(
                        "{} ORDER BY term out of range - should be between 1 and {output_width}",
                        sqlite_ordinal(index + 1)
                    ))
                });
            }
            projections
                .iter()
                .find_map(|projection| projection.resolve(&term.expr))
                .ok_or_else(|| {
                    FrankenError::FunctionError(format!(
                        "{} ORDER BY term does not match any column in the result set",
                        sqlite_ordinal(index + 1)
                    ))
                })
        })
        .collect()
}

fn compound_order_expr_for_resolved_index(expr: &Expr, index: usize) -> Expr {
    match expr {
        Expr::Collate {
            expr: inner,
            collation,
            span,
        } => Expr::Collate {
            expr: Box::new(compound_order_expr_for_resolved_index(inner, index)),
            collation: collation.clone(),
            span: *span,
        },
        _ => Expr::Literal(
            Literal::Integer(i64::try_from(index.saturating_add(1)).unwrap_or(i64::MAX)),
            Span::ZERO,
        ),
    }
}

fn resolved_window_spec_chain<'a>(
    window: &'a WindowSpec,
    named_windows: &'a [fsqlite_ast::WindowDef],
) -> Result<Vec<&'a WindowSpec>> {
    let Some(window_ref) = window.window_ref.as_ref() else {
        return Ok(Vec::new());
    };
    let named_specs = named_windows
        .iter()
        .map(|definition| (definition.name.to_ascii_uppercase(), &definition.spec))
        .collect::<Vec<_>>();
    // Keep semantic base lookup and derived-clause legality identical to the
    // canonical window resolver. The borrowed chain below exists only to
    // preserve structural traversal of the original AST without cloning it.
    let _ = resolve_used_window_spec(window, &named_specs)?;

    let base_name = window_ref.name();
    let Some((mut definition_index, definition)) = named_windows
        .iter()
        .enumerate()
        .rev()
        .find(|(_, definition)| definition.name.eq_ignore_ascii_case(base_name))
    else {
        return Err(FrankenError::FunctionError(format!(
            "no such window: {base_name}"
        )));
    };

    let mut chain = Vec::new();
    let mut current = &definition.spec;
    loop {
        chain.push(current);
        let Some(current_ref) = current.window_ref.as_ref() else {
            break;
        };
        let current_base_name = current_ref.name();
        let Some((base_index, base)) = named_windows[..definition_index]
            .iter()
            .enumerate()
            .rev()
            .find(|(_, candidate)| candidate.name.eq_ignore_ascii_case(current_base_name))
        else {
            // SQLite treats an unresolved, self, or forward base spelling on
            // the first WINDOW definition as an empty base. Later definitions
            // must resolve against their strict prior prefix.
            if definition_index == 0 {
                break;
            }
            return Err(FrankenError::FunctionError(format!(
                "no such window: {current_base_name}"
            )));
        };
        definition_index = base_index;
        current = &base.spec;
    }
    chain.reverse();
    Ok(chain)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum CteCollationVisit {
    Active,
    Done,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum TableFunctionCatalogMatch {
    Missing,
    Ordinary,
    CallableVirtual,
}

fn insert_source_select_for_validation<'a>(
    insert: &'a fsqlite_ast::InsertStatement,
    select: &'a SelectStatement,
) -> std::borrow::Cow<'a, SelectStatement> {
    if select.with.is_some() || insert.with.is_none() {
        return std::borrow::Cow::Borrowed(select);
    }
    let mut scoped = select.clone();
    scoped.with.clone_from(&insert.with);
    std::borrow::Cow::Owned(scoped)
}

struct SelectRelationResolver<'connection, 'select> {
    connection: &'connection Connection,
    /// Persistent view bodies are pinned to the owning connection's MAIN
    /// catalog. The string is the logical schema spelling used for qualified
    /// self-references and missing-relation diagnostics (`main` or an attached
    /// alias such as `aux`). TEMP view bodies leave this as `None` and use the
    /// ordinary TEMP -> MAIN -> attached search order.
    persistent_owner_label: Option<String>,
    scopes: Vec<&'select [fsqlite_ast::Cte]>,
    visits: HashMap<*const fsqlite_ast::Cte, CteCollationVisit>,
    active_views: HashSet<String>,
    named_window_scopes: Vec<&'select [fsqlite_ast::WindowDef]>,
    suppressed_window_relations: HashSet<*const WindowSpec>,
}

impl<'connection, 'select> SelectRelationResolver<'connection, 'select> {
    fn new(connection: &'connection Connection) -> Self {
        Self {
            connection,
            persistent_owner_label: None,
            scopes: Vec::new(),
            visits: HashMap::new(),
            active_views: HashSet::new(),
            named_window_scopes: Vec::new(),
            suppressed_window_relations: HashSet::new(),
        }
    }

    fn with_active_views(
        connection: &'connection Connection,
        active_views: HashSet<String>,
    ) -> Self {
        Self {
            connection,
            persistent_owner_label: None,
            scopes: Vec::new(),
            visits: HashMap::new(),
            active_views,
            named_window_scopes: Vec::new(),
            suppressed_window_relations: HashSet::new(),
        }
    }

    fn for_persistent_owner(
        connection: &'connection Connection,
        owner_label: String,
        active_views: HashSet<String>,
    ) -> Self {
        Self {
            connection,
            persistent_owner_label: Some(owner_label),
            scopes: Vec::new(),
            visits: HashMap::new(),
            active_views,
            named_window_scopes: Vec::new(),
            suppressed_window_relations: HashSet::new(),
        }
    }

    fn validate_select(&mut self, select: &'select SelectStatement) -> Result<()> {
        let scope_depth = self.scopes.len();
        if let Some(with) = &select.with {
            self.scopes.push(&with.ctes);
        }

        let rightmost_index = select.body.compounds.len();
        let result: Result<()> = (|| {
            for index in (0..=rightmost_index).rev() {
                let core = if index == 0 {
                    &select.body.select
                } else {
                    &select.body.compounds[index - 1].1
                };
                self.validate_named_window_definition_legality(core)?;
                self.validate_core_early(core)?;
                if index == rightmost_index {
                    let window_scope_depth = self.named_window_scopes.len();
                    self.named_window_scopes
                        .push(select_core_named_windows(core));
                    let top_level_result: Result<()> = (|| {
                        for term in &select.order_by {
                            self.validate_expr(&term.expr)?;
                        }
                        if let Some(limit) = &select.limit {
                            self.validate_expr(&limit.limit)?;
                            if let Some(offset) = &limit.offset {
                                self.validate_expr(offset)?;
                            }
                        }
                        Ok(())
                    })();
                    self.named_window_scopes.truncate(window_scope_depth);
                    top_level_result?;
                }
                self.validate_core_late(core)?;
            }
            Ok(())
        })();
        self.scopes.truncate(scope_depth);
        result
    }

    fn validate_named_window_definition_legality(&self, core: &SelectCore) -> Result<()> {
        let SelectCore::Select { windows, .. } = core else {
            return Ok(());
        };
        let named_windows = windows
            .iter()
            .map(|definition| (definition.name.to_ascii_uppercase(), &definition.spec))
            .collect::<Vec<_>>();
        validate_named_window_definitions(&named_windows)
    }

    fn validate_core_early(&mut self, core: &'select SelectCore) -> Result<()> {
        match core {
            SelectCore::Values(rows) => {
                let window_scope_depth = self.named_window_scopes.len();
                self.named_window_scopes.push(&[]);
                let result: Result<()> = (|| {
                    for row in rows.iter().rev() {
                        for expr in row {
                            self.validate_expr(expr)?;
                        }
                    }
                    Ok(())
                })();
                self.named_window_scopes.truncate(window_scope_depth);
                result?;
            }
            SelectCore::Select {
                columns,
                from,
                where_clause,
                group_by,
                having,
                windows,
                ..
            } => {
                let window_scope_depth = self.named_window_scopes.len();
                self.named_window_scopes.push(windows);
                let result: Result<()> = (|| {
                    if let Some(from) = from {
                        self.validate_from_sources(from)?;
                    }
                    for column in columns {
                        if let ResultColumn::Expr { expr, .. } = column {
                            self.validate_expr(expr)?;
                        }
                    }
                    if let Some(predicate) = where_clause {
                        self.validate_expr(predicate)?;
                    }
                    if let Some(from) = from {
                        self.validate_join_on_expressions(from)?;
                    }
                    for expr in group_by {
                        self.validate_expr(expr)?;
                    }
                    if let Some(predicate) = having {
                        self.validate_expr(predicate)?;
                    }
                    Ok(())
                })();
                self.named_window_scopes.truncate(window_scope_depth);
                result?;
            }
        }
        Ok(())
    }

    fn validate_core_late(&mut self, core: &'select SelectCore) -> Result<()> {
        let SelectCore::Select { from, windows, .. } = core else {
            return Ok(());
        };
        for definition in windows.iter().rev() {
            let key = std::ptr::from_ref(&definition.spec);
            if !self.suppressed_window_relations.contains(&key) {
                self.validate_window_clauses(&definition.spec)?;
            }
        }
        if let Some(from) = from {
            self.validate_table_function_args(from)?;
        }
        Ok(())
    }

    fn validate_from_sources(&mut self, from: &'select FromClause) -> Result<()> {
        self.validate_source(&from.source)?;
        for join in &from.joins {
            self.validate_source(&join.table)?;
        }
        Ok(())
    }

    fn validate_source(&mut self, source: &'select TableOrSubquery) -> Result<()> {
        match source {
            TableOrSubquery::Table { name, .. } => self.validate_relation(name),
            TableOrSubquery::Subquery { query, .. } => self.validate_select(query),
            TableOrSubquery::TableFunction { name, .. } => {
                self.validate_table_function_source(name)
            }
            TableOrSubquery::ParenJoin(from) => self.validate_from_sources(from),
        }
    }

    fn validate_table_function_source(&self, name: &str) -> Result<()> {
        match self.unqualified_table_function_catalog_match(name)? {
            TableFunctionCatalogMatch::CallableVirtual => return Ok(()),
            TableFunctionCatalogMatch::Ordinary => {
                return Err(FrankenError::FunctionError(format!(
                    "'{name}' is not a function"
                )));
            }
            TableFunctionCatalogMatch::Missing => {}
        }
        if self
            .connection
            .table_function_result_column_names(name)
            .is_some()
        {
            Ok(())
        } else {
            Err(FrankenError::NoSuchTable {
                name: name.to_owned(),
            })
        }
    }

    fn validate_join_on_expressions(&mut self, from: &'select FromClause) -> Result<()> {
        if let TableOrSubquery::ParenJoin(nested) = &from.source {
            self.validate_join_on_expressions(nested)?;
        }
        for join in &from.joins {
            if let TableOrSubquery::ParenJoin(nested) = &join.table {
                self.validate_join_on_expressions(nested)?;
            }
            if let Some(JoinConstraint::On(expr)) = &join.constraint {
                self.validate_expr(expr)?;
            }
        }
        Ok(())
    }

    fn validate_table_function_args(&mut self, from: &'select FromClause) -> Result<()> {
        self.validate_source_table_function_args(&from.source)?;
        for join in &from.joins {
            self.validate_source_table_function_args(&join.table)?;
        }
        Ok(())
    }

    fn validate_source_table_function_args(
        &mut self,
        source: &'select TableOrSubquery,
    ) -> Result<()> {
        match source {
            TableOrSubquery::TableFunction { args, .. } => {
                for arg in args {
                    self.validate_expr(arg)?;
                }
                Ok(())
            }
            TableOrSubquery::ParenJoin(from) => self.validate_table_function_args(from),
            TableOrSubquery::Table { .. } | TableOrSubquery::Subquery { .. } => Ok(()),
        }
    }

    fn validate_expr(&mut self, expr: &'select Expr) -> Result<()> {
        if expr_folds_to_integer_zero_via_and(expr) {
            return Ok(());
        }
        match expr {
            Expr::BoundOuterValue { .. }
            | Expr::Literal(_, _)
            | Expr::Column(_, _)
            | Expr::Raise { .. }
            | Expr::Placeholder(_, _) => Ok(()),
            Expr::BinaryOp { left, right, .. }
            | Expr::JsonAccess {
                expr: left,
                path: right,
                ..
            } => {
                self.validate_expr(left)?;
                self.validate_expr(right)
            }
            Expr::UnaryOp { expr, .. }
            | Expr::IsNull { expr, .. }
            | Expr::Cast { expr, .. }
            | Expr::Collate { expr, .. } => self.validate_expr(expr),
            Expr::Between {
                expr, low, high, ..
            } => {
                self.validate_expr(expr)?;
                self.validate_expr(low)?;
                self.validate_expr(high)
            }
            Expr::In { expr, set, .. } => {
                if matches!(set, InSet::List(values) if values.is_empty()) {
                    return Ok(());
                }
                self.validate_expr(expr)?;
                match set {
                    InSet::List(values) => {
                        for value in values {
                            self.validate_expr(value)?;
                        }
                    }
                    InSet::Subquery(query) => self.validate_select(query)?,
                    InSet::Table(name) => self.validate_relation(name)?,
                }
                Ok(())
            }
            Expr::Like {
                expr,
                pattern,
                escape,
                ..
            } => {
                self.validate_expr(pattern)?;
                self.validate_expr(expr)?;
                if let Some(escape) = escape {
                    self.validate_expr(escape)?;
                }
                Ok(())
            }
            Expr::Case {
                operand,
                whens,
                else_expr,
                ..
            } => {
                if let Some(operand) = operand {
                    self.validate_expr(operand)?;
                }
                for (condition, value) in whens {
                    self.validate_expr(condition)?;
                    self.validate_expr(value)?;
                }
                if let Some(else_expr) = else_expr {
                    self.validate_expr(else_expr)?;
                }
                Ok(())
            }
            Expr::Subquery(query, _) => self.validate_select(query),
            Expr::Exists { subquery, .. } => self.validate_select(subquery),
            Expr::FunctionCall {
                args,
                order_by,
                filter,
                over,
                ..
            } => {
                for term in order_by {
                    self.validate_expr(&term.expr)?;
                }
                if let FunctionArgs::List(values) = args {
                    for value in values {
                        self.validate_expr(value)?;
                    }
                }
                if let Some(window) = over {
                    self.validate_used_window(window)?;
                }
                if let Some(filter) = filter {
                    self.validate_expr(filter)?;
                }
                Ok(())
            }
            Expr::RowValue(values, _) => {
                for value in values {
                    self.validate_expr(value)?;
                }
                Ok(())
            }
        }
    }

    fn validate_used_window(&mut self, window: &'select WindowSpec) -> Result<()> {
        let named_windows = self.current_named_windows().unwrap_or_default();
        match resolved_window_spec_chain(window, named_windows) {
            Ok(_) => {}
            Err(FrankenError::FunctionError(message))
                if message.starts_with("cannot override ")
                    && matches!(window.window_ref.as_ref(), Some(WindowReference::Direct(_))) =>
            {
                self.suppress_used_window_chain(window, named_windows);
                return Ok(());
            }
            Err(_) => {}
        }
        self.validate_window_clauses(window)
    }

    fn suppress_used_window_chain(
        &mut self,
        window: &'select WindowSpec,
        named_windows: &'select [fsqlite_ast::WindowDef],
    ) {
        let Some(window_ref) = window.window_ref.as_ref() else {
            return;
        };
        let Some((mut definition_index, definition)) = named_windows
            .iter()
            .enumerate()
            .rev()
            .find(|(_, definition)| definition.name.eq_ignore_ascii_case(window_ref.name()))
        else {
            return;
        };

        let mut current = &definition.spec;
        loop {
            self.suppressed_window_relations
                .insert(std::ptr::from_ref(current));
            let Some(current_ref) = current.window_ref.as_ref() else {
                break;
            };
            let Some((base_index, base)) = named_windows[..definition_index]
                .iter()
                .enumerate()
                .rev()
                .find(|(_, candidate)| candidate.name.eq_ignore_ascii_case(current_ref.name()))
            else {
                break;
            };
            definition_index = base_index;
            current = &base.spec;
        }
    }

    fn validate_window_clauses(&mut self, window: &'select WindowSpec) -> Result<()> {
        for term in &window.order_by {
            self.validate_expr(&term.expr)?;
        }
        for expr in &window.partition_by {
            self.validate_expr(expr)?;
        }
        Ok(())
    }

    fn current_named_windows(&self) -> Option<&'select [fsqlite_ast::WindowDef]> {
        self.named_window_scopes.last().copied()
    }

    fn visible_cte(&self, name: &QualifiedName) -> Option<(usize, &'select fsqlite_ast::Cte)> {
        if name.schema.is_some() {
            return None;
        }
        self.scopes
            .iter()
            .enumerate()
            .rev()
            .find_map(|(scope_index, scope)| {
                scope
                    .iter()
                    .find(|cte| cte.name.eq_ignore_ascii_case(&name.name))
                    .map(|cte| (scope_index, cte))
            })
    }

    fn validate_relation(&mut self, name: &QualifiedName) -> Result<()> {
        if let Some(schema_name) = name.schema.as_deref()
            && let Some(scope) = if schema_name.eq_ignore_ascii_case("main") {
                Some(PragmaSchemaScope::Main)
            } else if schema_name.eq_ignore_ascii_case("temp") {
                Some(PragmaSchemaScope::Temp)
            } else {
                None
            }
            && self.scopes.iter().rev().any(|ctes| {
                ctes.iter()
                    .any(|cte| cte.name.eq_ignore_ascii_case(&name.name))
            })
            && (self.connection.table_exists_for_scope(&name.name, scope)
                || self
                    .connection
                    .view_index_for_scope(&name.name, scope)
                    .is_some())
        {
            // Materialized CTEs and persistent local relations currently feed
            // a name-only execution catalog. Unqualified lookup has deterministic
            // front precedence, but honoring an explicit MAIN/TEMP qualifier
            // while a same-name CTE is installed would require a namespace in
            // that storage key. Reject the mixed shape before materialization
            // instead of silently reading the CTE through a qualified name.
            return Err(FrankenError::NotImplemented(format!(
                "qualified relation {schema_name}.{} is not supported while a same-name CTE is active",
                name.name
            )));
        }
        if let Some((scope_index, cte)) = self.visible_cte(name) {
            let hidden_reference_scopes = self.scopes.split_off(scope_index + 1);
            let result = self.validate_cte(cte);
            self.scopes.extend(hidden_reference_scopes);
            return result;
        }
        self.validate_catalog_relation(name)
    }

    fn validate_cte(&mut self, cte: &'select fsqlite_ast::Cte) -> Result<()> {
        let key = std::ptr::from_ref(cte);
        if matches!(
            self.visits.get(&key),
            Some(CteCollationVisit::Active | CteCollationVisit::Done)
        ) {
            return Ok(());
        }
        self.visits.insert(key, CteCollationVisit::Active);
        self.validate_select(&cte.query)?;
        self.visits.insert(key, CteCollationVisit::Done);
        Ok(())
    }

    fn validate_catalog_relation(&mut self, name: &QualifiedName) -> Result<()> {
        let relation_error_name = match name.schema.as_deref() {
            Some(schema) => format!("{schema}.{}", name.name),
            None => name.name.clone(),
        };
        if let Some(owner_label) = self.persistent_owner_label.clone() {
            if let Some(schema) = name.schema.as_deref()
                && !schema.eq_ignore_ascii_case(&owner_label)
            {
                return Err(FrankenError::NoSuchTable {
                    name: relation_error_name,
                });
            }
            let owner_error_name = name.schema.as_ref().map_or_else(
                || format!("{owner_label}.{}", name.name),
                |_| relation_error_name,
            );
            return self.validate_local_catalog_relation(
                &name.name,
                PragmaSchemaScope::Main,
                &owner_label,
                || owner_error_name,
            );
        }
        let Some(schema_name) = name.schema.as_deref() else {
            let local_result = self.validate_local_catalog_relation(
                &name.name,
                PragmaSchemaScope::Unqualified,
                "main",
                || relation_error_name.clone(),
            );
            match local_result {
                Ok(()) => return Ok(()),
                Err(FrankenError::NoSuchTable { name: missing })
                    if missing == relation_error_name => {}
                Err(error) => return Err(error),
            }
            for attached_schema in self.attached_schema_names() {
                let active_views = self.active_views.clone();
                let attached_result =
                    self.connection
                        .with_attached_connection(&attached_schema, |attached| {
                            let mut resolver =
                                SelectRelationResolver::with_active_views(attached, active_views);
                            resolver.validate_local_catalog_relation(
                                &name.name,
                                PragmaSchemaScope::Main,
                                &attached_schema,
                                || relation_error_name.clone(),
                            )
                        });
                match attached_result {
                    Ok(()) => return Ok(()),
                    Err(FrankenError::NoSuchTable { name: missing })
                        if missing == relation_error_name => {}
                    Err(error) => return Err(error),
                }
            }
            return Err(FrankenError::NoSuchTable {
                name: relation_error_name,
            });
        };
        if schema_name.eq_ignore_ascii_case("main") {
            return self.validate_local_catalog_relation(
                &name.name,
                PragmaSchemaScope::Main,
                "main",
                || relation_error_name,
            );
        }
        if schema_name.eq_ignore_ascii_case("temp") {
            return self.validate_local_catalog_relation(
                &name.name,
                PragmaSchemaScope::Temp,
                "main",
                || relation_error_name,
            );
        }
        if self
            .connection
            .attached_schemas
            .borrow()
            .find(schema_name)
            .is_none()
        {
            return Err(FrankenError::NoSuchTable {
                name: relation_error_name,
            });
        }

        let active_views = self.active_views.clone();
        self.connection
            .with_attached_connection(schema_name, |attached| {
                let mut resolver =
                    SelectRelationResolver::with_active_views(attached, active_views);
                resolver.validate_local_catalog_relation(
                    &name.name,
                    PragmaSchemaScope::Main,
                    schema_name,
                    || relation_error_name,
                )
            })
    }

    fn validate_local_catalog_relation(
        &mut self,
        relation_name: &str,
        scope: PragmaSchemaScope,
        main_label: &str,
        relation_error_name: impl FnOnce() -> String,
    ) -> Result<()> {
        if self.builtin_schema_relation_exists(relation_name, scope) {
            return Ok(());
        }

        let resolved_scope = if scope == PragmaSchemaScope::Unqualified
            && (self.local_table_exists(relation_name, PragmaSchemaScope::Temp)
                || self
                    .connection
                    .view_index_for_scope(relation_name, PragmaSchemaScope::Temp)
                    .is_some())
        {
            PragmaSchemaScope::Temp
        } else if scope == PragmaSchemaScope::Unqualified {
            PragmaSchemaScope::Main
        } else {
            scope
        };
        if self.local_table_exists(relation_name, resolved_scope)
            || (resolved_scope == PragmaSchemaScope::Main
                && self.connection.has_live_vtab_instance(relation_name))
        {
            return Ok(());
        }

        let view = self
            .connection
            .view_index_for_scope(relation_name, resolved_scope)
            .and_then(|index| self.connection.views.borrow().get(index).cloned());
        let Some(view) = view else {
            return Err(FrankenError::NoSuchTable {
                name: relation_error_name(),
            });
        };

        let view_key = format!(
            "{:p}:{resolved_scope:?}:{}",
            self.connection,
            relation_name.to_ascii_lowercase()
        );
        if !self.active_views.insert(view_key.clone()) {
            return Err(FrankenError::FunctionError(format!(
                "view {relation_name} is circularly defined"
            )));
        }
        let active_views = self.active_views.clone();
        let mut resolver = if view.temporary {
            SelectRelationResolver::with_active_views(self.connection, active_views)
        } else {
            SelectRelationResolver::for_persistent_owner(
                self.connection,
                self.persistent_owner_label
                    .clone()
                    .unwrap_or_else(|| main_label.to_owned()),
                active_views,
            )
        };
        let result = resolver.validate_select(&view.query).and_then(|()| {
            // View expansion is part of SQLite's relation/name-resolution
            // phase, so a broken referenced view must outrank an enclosing
            // SELECT's LIMIT/OFFSET diagnostic even when the reference is
            // nested in a scalar subquery or derived table. Relation-only
            // traversal is insufficient here: validate the expanded view's
            // lexical columns before returning to the outer SELECT.
            let mut query = view.query.clone();
            if !view.temporary {
                qualify_persistent_view_relations(&mut query);
            }
            self.connection.with_fallback_function_registry(|| {
                SelectColumnReferenceResolver::new(self.connection).validate_select(&query)
            })
        });
        self.active_views.remove(&view_key);
        result
    }

    fn attached_schema_names(&self) -> Vec<String> {
        self.connection
            .attached_schemas
            .borrow()
            .all_schemas()
            .into_iter()
            .skip(2)
            .map(str::to_owned)
            .collect()
    }

    fn unqualified_table_function_catalog_match(
        &self,
        relation_name: &str,
    ) -> Result<TableFunctionCatalogMatch> {
        if self.scopes.iter().rev().any(|scope| {
            scope
                .iter()
                .any(|cte| cte.name.eq_ignore_ascii_case(relation_name))
        }) {
            return Ok(TableFunctionCatalogMatch::Ordinary);
        }
        if self.persistent_owner_label.is_some() {
            return Ok(
                self.local_table_function_catalog_match(relation_name, PragmaSchemaScope::Main)
            );
        }
        let local =
            self.local_table_function_catalog_match(relation_name, PragmaSchemaScope::Unqualified);
        if local != TableFunctionCatalogMatch::Missing {
            return Ok(local);
        }
        for attached_schema in self.attached_schema_names() {
            let attached_match =
                self.connection
                    .with_attached_connection(&attached_schema, |attached| {
                        Ok(SelectRelationResolver::new(attached)
                            .local_table_function_catalog_match(
                                relation_name,
                                PragmaSchemaScope::Main,
                            ))
                    })?;
            if attached_match != TableFunctionCatalogMatch::Missing {
                return Ok(attached_match);
            }
        }
        Ok(TableFunctionCatalogMatch::Missing)
    }

    fn local_table_function_catalog_match(
        &self,
        relation_name: &str,
        scope: PragmaSchemaScope,
    ) -> TableFunctionCatalogMatch {
        if self.builtin_schema_relation_exists(relation_name, scope) {
            return TableFunctionCatalogMatch::Ordinary;
        }
        let resolved_scope = if scope == PragmaSchemaScope::Unqualified
            && (self.local_table_exists(relation_name, PragmaSchemaScope::Temp)
                || self
                    .connection
                    .view_index_for_scope(relation_name, PragmaSchemaScope::Temp)
                    .is_some())
        {
            PragmaSchemaScope::Temp
        } else if scope == PragmaSchemaScope::Unqualified {
            PragmaSchemaScope::Main
        } else {
            scope
        };
        if self
            .connection
            .view_index_for_scope(relation_name, resolved_scope)
            .is_some()
        {
            return TableFunctionCatalogMatch::Ordinary;
        }
        if self.local_table_exists(relation_name, resolved_scope) {
            return if resolved_scope == PragmaSchemaScope::Main
                && self.connection.has_live_vtab_instance(relation_name)
            {
                TableFunctionCatalogMatch::CallableVirtual
            } else {
                TableFunctionCatalogMatch::Ordinary
            };
        }
        if resolved_scope == PragmaSchemaScope::Main
            && self.connection.has_live_vtab_instance(relation_name)
        {
            TableFunctionCatalogMatch::CallableVirtual
        } else {
            TableFunctionCatalogMatch::Missing
        }
    }

    fn builtin_schema_relation_exists(
        &self,
        relation_name: &str,
        scope: PragmaSchemaScope,
    ) -> bool {
        if is_sqlite_schema_name(relation_name) {
            return true;
        }
        (scope == PragmaSchemaScope::Unqualified || scope == PragmaSchemaScope::Temp)
            && (relation_name.eq_ignore_ascii_case("sqlite_temp_schema")
                || relation_name.eq_ignore_ascii_case("sqlite_temp_master"))
    }

    fn local_table_exists(&self, relation_name: &str, scope: PragmaSchemaScope) -> bool {
        self.connection.table_exists_for_scope(relation_name, scope)
    }
}

#[derive(Clone)]
struct SelectOutputAlias {
    name: String,
    aggregate_name: Option<String>,
    is_aggregate: bool,
    is_window: bool,
}

struct SelectSourceColumnMetadata {
    names: Vec<String>,
    hidden_rowid: Option<String>,
    is_live_fts5: bool,
    approximate_names: Vec<bool>,
    generated_suffix_upper_bounds: Vec<Option<usize>>,
    width_is_exact: bool,
}

#[derive(Clone)]
struct SelectResultColumnMetadata {
    names: Vec<String>,
    approximate_names: Vec<bool>,
    generated_suffix_upper_bounds: Vec<Option<usize>>,
    width_is_exact: bool,
}

#[derive(Clone)]
struct SelectVisibleColumnMetadata {
    name: String,
    col_map_index: Option<usize>,
    approximate: bool,
    expression_key: Option<String>,
    generated_suffix_upper_bound: Option<usize>,
}

#[derive(Clone)]
struct SelectApproximateColumn {
    table: String,
    display_name: String,
    expression_key: Option<String>,
    generated_suffix_upper_bound: Option<usize>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SelectOutputAliasUse {
    None,
    Where,
    GroupBy,
    Having,
    JoinOn,
    OrderBy,
}

#[derive(Clone, Default)]
struct SelectColumnReferenceScope {
    identity: usize,
    col_map: Vec<(String, String, bool)>,
    using_skip: HashSet<usize>,
    output_aliases: Vec<SelectOutputAlias>,
    valid_qualifiers: Vec<String>,
    match_table_names: Vec<String>,
    fts5_rank_table_names: Vec<String>,
    approximate_col_map: Vec<SelectApproximateColumn>,
}

fn normalize_uncertain_sqlite_result_column_names(
    names: &mut [String],
    approximate_names: &mut Vec<bool>,
    generated_suffix_upper_bounds: &mut Vec<Option<usize>>,
) {
    approximate_names.resize(names.len(), true);
    approximate_names.truncate(names.len());
    generated_suffix_upper_bounds.resize(names.len(), None);
    generated_suffix_upper_bounds.truncate(names.len());

    let mut used = HashSet::new();
    let mut exact_names = Vec::new();
    let mut uncertain_names: Vec<(String, Option<String>, Option<usize>)> = Vec::new();
    for index in 0..names.len() {
        let target_keys = approximate_target_name_keys(&names[index]);
        let prior_uncertain_collision = uncertain_names.iter().any(
            |(display_name, expression_key, generated_suffix_upper_bound)| {
                approximate_source_name_may_match(
                    display_name,
                    expression_key.as_deref(),
                    *generated_suffix_upper_bound,
                    &names[index],
                    &target_keys,
                )
            },
        );
        if !approximate_names[index] && prior_uncertain_collision {
            approximate_names[index] = true;
            generated_suffix_upper_bounds[index] = Some(index);
        }

        if approximate_names[index] {
            let expression_key = approximate_result_name_key(&names[index]);
            let collides_with_exact = exact_names.iter().any(|exact_name: &String| {
                let exact_target_keys = approximate_target_name_keys(exact_name);
                approximate_source_name_may_match(
                    &names[index],
                    expression_key.as_deref(),
                    generated_suffix_upper_bounds[index],
                    exact_name,
                    &exact_target_keys,
                )
            });
            if collides_with_exact || prior_uncertain_collision {
                generated_suffix_upper_bounds[index] = Some(
                    generated_suffix_upper_bounds[index]
                        .unwrap_or_default()
                        .max(index),
                );
            }
            uncertain_names.push((
                names[index].clone(),
                expression_key,
                generated_suffix_upper_bounds[index],
            ));
            continue;
        }

        let key = names[index].to_ascii_lowercase();
        if used.insert(key) {
            exact_names.push(names[index].clone());
            continue;
        }
        let original = names[index].clone();
        let mut base = original
            .rsplit_once(':')
            .filter(|(_, suffix)| suffix.bytes().all(|byte| byte.is_ascii_digit()))
            .map_or_else(|| original.clone(), |(base, _)| base.to_owned());
        let mut suffix = 1usize;
        loop {
            let candidate = format!("{base}:{suffix}");
            if used.insert(candidate.to_ascii_lowercase()) {
                names[index] = candidate;
                exact_names.push(names[index].clone());
                break;
            }
            if let Some(next) = suffix.checked_add(1) {
                suffix = next;
            } else {
                base = candidate;
                suffix = 1;
            }
        }
    }
}

fn approximate_result_name_key(name: &str) -> Option<String> {
    fsqlite_parser::expr::parse_expr(name)
        .ok()
        .map(|expr| expr.to_string())
}

fn approximate_target_name_keys(target: &str) -> (Option<String>, Option<(String, usize)>) {
    let direct = approximate_result_name_key(target);
    let suffix_base = target
        .rsplit_once(':')
        .filter(|(_, suffix)| {
            !suffix.is_empty() && suffix.bytes().all(|byte| byte.is_ascii_digit())
        })
        .and_then(|(base, suffix)| {
            let parsed_suffix = suffix.parse::<usize>().ok()?;
            if parsed_suffix.to_string() != suffix {
                return None;
            }
            approximate_result_name_key(base).map(|base| (base, parsed_suffix))
        });
    (direct, suffix_base)
}

fn approximate_source_name_may_match(
    display_name: &str,
    expression_key: Option<&str>,
    generated_suffix_upper_bound: Option<usize>,
    target: &str,
    target_keys: &(Option<String>, Option<(String, usize)>),
) -> bool {
    display_name.eq_ignore_ascii_case(target)
        || expression_key.is_some_and(|candidate| {
            target_keys
                .0
                .as_deref()
                .is_some_and(|target_key| candidate.eq_ignore_ascii_case(target_key))
                || generated_suffix_upper_bound.is_some_and(|upper_bound| {
                    target_keys.1.as_ref().is_some_and(|(target_key, suffix)| {
                        (1..=upper_bound).contains(suffix)
                            && candidate.eq_ignore_ascii_case(target_key)
                    })
                })
        })
}

fn visible_source_names_may_match(
    left: &SelectVisibleColumnMetadata,
    right: &SelectVisibleColumnMetadata,
) -> bool {
    if !left.approximate && !right.approximate {
        return left.name.eq_ignore_ascii_case(&right.name);
    }
    left.name.eq_ignore_ascii_case(&right.name)
        || left
            .expression_key
            .as_deref()
            .zip(right.expression_key.as_deref())
            .is_some_and(|(left_key, right_key)| left_key.eq_ignore_ascii_case(right_key))
}

fn visible_source_name_may_match_target(
    candidate: &SelectVisibleColumnMetadata,
    target: &str,
    target_keys: &(Option<String>, Option<(String, usize)>),
) -> bool {
    if candidate.approximate {
        approximate_source_name_may_match(
            &candidate.name,
            candidate.expression_key.as_deref(),
            candidate.generated_suffix_upper_bound,
            target,
            target_keys,
        )
    } else {
        candidate.name.eq_ignore_ascii_case(target)
    }
}

impl SelectColumnReferenceScope {
    fn resolves_approximate_column(&self, column: &ColumnRef) -> bool {
        let target_keys = approximate_target_name_keys(&column.column);
        self.approximate_col_map.iter().any(|candidate| {
            column
                .table
                .as_deref()
                .is_none_or(|qualifier| qualifier.eq_ignore_ascii_case(&candidate.table))
                && approximate_source_name_may_match(
                    &candidate.display_name,
                    candidate.expression_key.as_deref(),
                    candidate.generated_suffix_upper_bound,
                    &column.column,
                    &target_keys,
                )
        })
    }

    fn resolves_fts5_rank_column(&self, column: &ColumnRef) -> bool {
        if !column.column.eq_ignore_ascii_case("rank") {
            return false;
        }
        column
            .table
            .as_deref()
            .map_or(!self.fts5_rank_table_names.is_empty(), |prefix| {
                self.fts5_rank_table_names
                    .iter()
                    .any(|table_name| prefix.eq_ignore_ascii_case(table_name))
            })
    }

    fn for_core<'source, F>(
        connection: &Connection,
        core: &'source SelectCore,
        mut source_column_names: F,
    ) -> Result<Self>
    where
        F: FnMut(&'source TableOrSubquery) -> Result<SelectSourceColumnMetadata>,
    {
        let mut col_map = Vec::new();
        let mut using_skip = HashSet::new();
        let mut match_table_names = Vec::new();
        let mut fts5_rank_table_names = Vec::new();
        let mut approximate_col_map = Vec::new();
        let mut layout_width_is_exact = true;
        if let SelectCore::Select {
            from: Some(from), ..
        } = core
        {
            Self::append_from_layout(
                connection,
                from,
                &mut source_column_names,
                &mut col_map,
                &mut using_skip,
                &mut match_table_names,
                &mut fts5_rank_table_names,
                &mut approximate_col_map,
                &mut layout_width_is_exact,
            )?;
        }
        let mut output_aliases = Vec::new();
        if let SelectCore::Select { columns, .. } = core {
            for column in columns {
                let ResultColumn::Expr {
                    expr,
                    alias: Some(alias),
                } = column
                else {
                    continue;
                };
                if output_aliases
                    .iter()
                    .any(|candidate: &SelectOutputAlias| candidate.name.eq_ignore_ascii_case(alias))
                {
                    continue;
                }
                let is_aggregate = connection.expr_contains_aggregate_with_registry(expr);
                let aggregate_name = is_aggregate
                    .then(|| {
                        let mut names = BTreeSet::new();
                        collect_aggregate_kind_names(expr, &mut names);
                        names.into_iter().next()
                    })
                    .flatten();
                output_aliases.push(SelectOutputAlias {
                    name: alias.clone(),
                    aggregate_name,
                    is_aggregate,
                    is_window: expr_has_window_function(expr),
                });
            }
        }
        if let SelectCore::Values(rows) = core
            && let Some(width) = rows.first().map(Vec::len)
        {
            output_aliases.extend((1..=width).map(|index| SelectOutputAlias {
                name: format!("column{index}"),
                aggregate_name: None,
                is_aggregate: false,
                is_window: false,
            }));
        }

        let mut scope = Self {
            identity: std::ptr::from_ref(core).addr(),
            col_map,
            using_skip,
            output_aliases,
            valid_qualifiers: Vec::new(),
            match_table_names,
            fts5_rank_table_names,
            approximate_col_map,
        };
        if let SelectCore::Select {
            from: Some(from), ..
        } = core
        {
            scope.record_from_qualifiers(from);
        }
        Ok(scope)
    }

    fn append_from_layout<'source, F>(
        connection: &Connection,
        from: &'source FromClause,
        source_column_names: &mut F,
        col_map: &mut Vec<(String, String, bool)>,
        using_skip: &mut HashSet<usize>,
        match_table_names: &mut Vec<String>,
        fts5_rank_table_names: &mut Vec<String>,
        approximate_col_map: &mut Vec<SelectApproximateColumn>,
        layout_width_is_exact: &mut bool,
    ) -> Result<Vec<SelectVisibleColumnMetadata>>
    where
        F: FnMut(&'source TableOrSubquery) -> Result<SelectSourceColumnMetadata>,
    {
        let mut left_visible = Self::append_source_layout(
            connection,
            &from.source,
            source_column_names,
            col_map,
            using_skip,
            match_table_names,
            fts5_rank_table_names,
            approximate_col_map,
            layout_width_is_exact,
        )?;
        for join in &from.joins {
            let right_visible = Self::append_source_layout(
                connection,
                &join.table,
                source_column_names,
                col_map,
                using_skip,
                match_table_names,
                fts5_rank_table_names,
                approximate_col_map,
                layout_width_is_exact,
            )?;
            let using_columns = if join.join_type.natural {
                if right_visible.iter().any(|right| {
                    left_visible.iter().any(|left| {
                        (left.approximate || right.approximate)
                            && visible_source_names_may_match(left, right)
                    })
                }) {
                    *layout_width_is_exact = false;
                }
                right_visible
                    .iter()
                    .filter(|right| {
                        !right.approximate
                            && left_visible.iter().any(|left| {
                                !left.approximate && left.name.eq_ignore_ascii_case(&right.name)
                            })
                    })
                    .map(|column| column.name.clone())
                    .collect::<Vec<_>>()
            } else if let Some(JoinConstraint::Using(columns)) = &join.constraint {
                columns.clone()
            } else {
                Vec::new()
            };
            if !join.join_type.natural {
                for using_column in &using_columns {
                    let target_keys = approximate_target_name_keys(using_column);
                    let left_matches = left_visible.iter().filter(|candidate| {
                        visible_source_name_may_match_target(candidate, using_column, &target_keys)
                    });
                    let right_matches = right_visible.iter().filter(|candidate| {
                        visible_source_name_may_match_target(candidate, using_column, &target_keys)
                    });
                    if left_matches.clone().next().is_none()
                        || right_matches.clone().next().is_none()
                    {
                        return Err(FrankenError::FunctionError(format!(
                            "cannot join using column {using_column} - column not present in both tables"
                        )));
                    }
                    if left_matches
                        .chain(right_matches)
                        .any(|column| column.approximate)
                    {
                        *layout_width_is_exact = false;
                    }
                }
            }
            for using_column in &using_columns {
                if let Some(index) = right_visible
                    .iter()
                    .find(|column| {
                        !column.approximate && column.name.eq_ignore_ascii_case(using_column)
                    })
                    .and_then(|column| column.col_map_index)
                {
                    using_skip.insert(index);
                }
            }
            left_visible.extend(right_visible.into_iter().filter(|column| {
                column.approximate
                    || !using_columns
                        .iter()
                        .any(|using_column| column.name.eq_ignore_ascii_case(using_column))
            }));
        }
        Ok(left_visible)
    }

    fn append_source_layout<'source, F>(
        connection: &Connection,
        source: &'source TableOrSubquery,
        source_column_names: &mut F,
        col_map: &mut Vec<(String, String, bool)>,
        using_skip: &mut HashSet<usize>,
        match_table_names: &mut Vec<String>,
        fts5_rank_table_names: &mut Vec<String>,
        approximate_col_map: &mut Vec<SelectApproximateColumn>,
        layout_width_is_exact: &mut bool,
    ) -> Result<Vec<SelectVisibleColumnMetadata>>
    where
        F: FnMut(&'source TableOrSubquery) -> Result<SelectSourceColumnMetadata>,
    {
        if let TableOrSubquery::ParenJoin(from) = source {
            return Self::append_from_layout(
                connection,
                from,
                source_column_names,
                col_map,
                using_skip,
                match_table_names,
                fts5_rank_table_names,
                approximate_col_map,
                layout_width_is_exact,
            );
        }
        let label = match source {
            TableOrSubquery::Table { name, alias, .. } => alias.as_deref().unwrap_or(&name.name),
            TableOrSubquery::Subquery { alias, .. } => alias.as_deref().unwrap_or(""),
            TableOrSubquery::TableFunction { name, alias, .. } => alias.as_deref().unwrap_or(name),
            TableOrSubquery::ParenJoin(_) => {
                unreachable!("parenthesized joins recurse before leaf layout")
            }
        };
        let SelectSourceColumnMetadata {
            mut names,
            hidden_rowid,
            is_live_fts5,
            mut approximate_names,
            mut generated_suffix_upper_bounds,
            width_is_exact,
        } = source_column_names(source)?;
        if is_live_fts5 && let TableOrSubquery::Table { name, alias, .. } = source {
            match_table_names.push(name.name.clone());
            fts5_rank_table_names.push(alias.as_ref().unwrap_or(&name.name).clone());
        }
        *layout_width_is_exact &= width_is_exact;
        if !width_is_exact {
            approximate_names.resize(names.len(), true);
            approximate_names.fill(true);
        }
        normalize_uncertain_sqlite_result_column_names(
            &mut names,
            &mut approximate_names,
            &mut generated_suffix_upper_bounds,
        );
        let visible = names
            .into_iter()
            .zip(
                approximate_names
                    .into_iter()
                    .zip(generated_suffix_upper_bounds),
            )
            .map(|(name, (approximate, generated_suffix_upper_bound))| {
                let expression_key = approximate
                    .then(|| approximate_result_name_key(&name))
                    .flatten();
                let col_map_index = if approximate {
                    approximate_col_map.push(SelectApproximateColumn {
                        table: label.to_owned(),
                        display_name: name.clone(),
                        expression_key: expression_key.clone(),
                        generated_suffix_upper_bound,
                    });
                    None
                } else {
                    let index = col_map.len();
                    col_map.push((label.to_owned(), name.clone(), false));
                    Some(index)
                };
                SelectVisibleColumnMetadata {
                    name,
                    col_map_index,
                    approximate,
                    expression_key,
                    generated_suffix_upper_bound,
                }
            })
            .collect();
        if let Some(column_name) = hidden_rowid {
            col_map.push((label.to_owned(), column_name, true));
        }
        Ok(visible)
    }

    fn record_from_qualifiers(&mut self, from: &FromClause) {
        self.record_source_qualifiers(&from.source);
        for join in &from.joins {
            self.record_source_qualifiers(&join.table);
        }
    }

    fn record_source_qualifiers(&mut self, source: &TableOrSubquery) {
        match source {
            TableOrSubquery::Table { name, alias, .. } => {
                self.valid_qualifiers
                    .push(alias.as_ref().unwrap_or(&name.name).clone());
            }
            TableOrSubquery::Subquery {
                alias: Some(alias), ..
            } => self.valid_qualifiers.push(alias.clone()),
            TableOrSubquery::TableFunction { name, alias, .. } => self
                .valid_qualifiers
                .push(alias.as_ref().unwrap_or(name).clone()),
            TableOrSubquery::ParenJoin(from) => {
                self.record_from_qualifiers(from);
            }
            TableOrSubquery::Subquery { alias: None, .. } => {}
        }
    }

    fn using_skip(&self) -> Option<&HashSet<usize>> {
        (!self.using_skip.is_empty()).then_some(&self.using_skip)
    }

    fn output_alias(&self, name: &str) -> Option<&SelectOutputAlias> {
        self.output_aliases
            .iter()
            .find(|alias| alias.name.eq_ignore_ascii_case(name))
    }

    fn is_match_table_operand(&self, expr: &Expr) -> bool {
        matches!(
            expr,
            Expr::Column(column, _)
                if column.table.is_none()
                    && self
                        .match_table_names
                        .iter()
                        .any(|name| name.eq_ignore_ascii_case(&column.column))
        )
    }

    fn from_contains_source(from: &FromClause, target: &QualifiedName) -> bool {
        Self::source_contains_name(&from.source, target)
            || from
                .joins
                .iter()
                .any(|join| Self::source_contains_name(&join.table, target))
    }

    fn source_contains_name(source: &TableOrSubquery, target: &QualifiedName) -> bool {
        match source {
            TableOrSubquery::ParenJoin(from) => Self::from_contains_source(from, target),
            _ => source_matches_name(source, target),
        }
    }
}

#[derive(Clone, PartialEq, Eq, Hash)]
struct SelectCteValidationKey {
    cte: *const fsqlite_ast::Cte,
    outer_scope_ids: Vec<usize>,
}

#[derive(Default)]
struct SelectViewValidationState {
    active: HashSet<String>,
    validated: HashSet<String>,
}

/// Non-executing lexical column resolver used before scalar/vector subquery
/// width checks. The normal join evaluator validates only the clauses it is
/// about to execute and deliberately skips nested SELECT scopes; this resolver
/// instead walks the complete SELECT tree and carries outer scopes explicitly.
struct SelectColumnReferenceResolver<'connection, 'select> {
    connection: &'connection Connection,
    outer_scopes: Vec<SelectColumnReferenceScope>,
    cte_scopes: Vec<&'select [fsqlite_ast::Cte]>,
    active_ctes: HashSet<*const fsqlite_ast::Cte>,
    metadata_active_ctes: HashSet<*const fsqlite_ast::Cte>,
    metadata_cte_columns: HashMap<*const fsqlite_ast::Cte, SelectResultColumnMetadata>,
    metadata_select_columns: HashMap<*const SelectStatement, SelectResultColumnMetadata>,
    validated_ctes: HashSet<SelectCteValidationKey>,
    view_state: Rc<RefCell<SelectViewValidationState>>,
    named_window_scopes: Vec<&'select [fsqlite_ast::WindowDef]>,
}

impl<'connection, 'select> SelectColumnReferenceResolver<'connection, 'select> {
    fn new(connection: &'connection Connection) -> Self {
        Self {
            connection,
            outer_scopes: Vec::new(),
            cte_scopes: Vec::new(),
            active_ctes: HashSet::new(),
            metadata_active_ctes: HashSet::new(),
            metadata_cte_columns: HashMap::new(),
            metadata_select_columns: HashMap::new(),
            validated_ctes: HashSet::new(),
            view_state: Rc::new(RefCell::new(SelectViewValidationState::default())),
            named_window_scopes: Vec::new(),
        }
    }

    fn with_view_state(
        connection: &'connection Connection,
        view_state: Rc<RefCell<SelectViewValidationState>>,
    ) -> Self {
        Self {
            connection,
            outer_scopes: Vec::new(),
            cte_scopes: Vec::new(),
            active_ctes: HashSet::new(),
            metadata_active_ctes: HashSet::new(),
            metadata_cte_columns: HashMap::new(),
            metadata_select_columns: HashMap::new(),
            validated_ctes: HashSet::new(),
            view_state,
            named_window_scopes: Vec::new(),
        }
    }

    fn validate_select_layout(&mut self, select: &'select SelectStatement) -> Result<()> {
        let cte_scope_depth = self.cte_scopes.len();
        if let Some(with) = &select.with {
            self.cte_scopes.push(&with.ctes);
        }
        let result = (0..=select.body.compounds.len())
            .rev()
            .try_for_each(|index| {
                let core = if index == 0 {
                    &select.body.select
                } else {
                    &select.body.compounds[index - 1].1
                };
                self.prepare_core_scope(core)?;
                if let SelectCore::Select {
                    from: Some(from), ..
                } = core
                {
                    self.validate_from_sources(from)?;
                }
                Ok(())
            });
        self.cte_scopes.truncate(cte_scope_depth);
        result
    }

    fn validate_select(&mut self, select: &'select SelectStatement) -> Result<()> {
        let cte_scope_depth = self.cte_scopes.len();
        if let Some(with) = &select.with {
            self.cte_scopes.push(&with.ctes);
        }
        let result: Result<()> = (|| {
            if select.body.compounds.is_empty() {
                // SQLite establishes source layout before resolving LIMIT. This
                // exposes non-semantic shape errors (CTE declared-column arity,
                // malformed VALUES rows, star expansion, and JOIN USING) first,
                // while expressions inside those sources still wait until after
                // LIMIT/OFFSET name resolution.
                let scope = self.prepare_core_scope(&select.body.select)?;
                self.validate_limit(select)?;
                self.validate_core_before_order(&select.body.select, &scope)?;
                let saved_outer_scopes = std::mem::take(&mut self.outer_scopes);
                self.named_window_scopes
                    .push(select_core_named_windows(&select.body.select));
                let order_result: Result<()> = (|| {
                    for term in &select.order_by {
                        if let Expr::Column(column, _) = strip_collate_wrappers(&term.expr)
                            && column.table.is_none()
                            && scope.output_alias(&column.column).is_some()
                        {
                            continue;
                        }
                        self.validate_expr(&term.expr, &scope, SelectOutputAliasUse::OrderBy)?;
                    }
                    Ok(())
                })();
                self.named_window_scopes.pop();
                self.outer_scopes = saved_outer_scopes;
                order_result?;
                self.validate_core_after_order(&select.body.select, &scope)?;
                return Ok(());
            }

            let mut prepared_cores = Vec::with_capacity(select.body.compounds.len() + 1);
            for index in (0..=select.body.compounds.len()).rev() {
                let core = if index == 0 {
                    &select.body.select
                } else {
                    &select.body.compounds[index - 1].1
                };
                let scope = self.prepare_core_scope(core)?;
                prepared_cores.push((core, scope));
            }
            self.validate_limit(select)?;
            for (core, scope) in &prepared_cores {
                self.validate_core_before_order(core, scope)?;
                self.validate_core_after_order(core, scope)?;
            }
            // Compound ORDER BY terms resolve against the output expressions of
            // every core rather than the primary core's FROM scope. The structure
            // resolver performs that authoritative cross-core match after this
            // lexical pass has already walked each projected expression.
            Ok(())
        })();
        self.cte_scopes.truncate(cte_scope_depth);
        result
    }

    fn validate_limit(&mut self, select: &'select SelectStatement) -> Result<()> {
        let Some(limit) = &select.limit else {
            return Ok(());
        };
        // LIMIT/OFFSET is not correlated to either this SELECT's source
        // columns or any outer SELECT. SQLite reports those names missing.
        let saved_outer_scopes = std::mem::take(&mut self.outer_scopes);
        let empty_scope = SelectColumnReferenceScope::default();
        self.named_window_scopes.push(&[]);
        let result: Result<()> = (|| {
            self.validate_expr(&limit.limit, &empty_scope, SelectOutputAliasUse::None)?;
            if let Some(offset) = &limit.offset {
                self.validate_expr(offset, &empty_scope, SelectOutputAliasUse::None)?;
            }
            Ok(())
        })();
        self.named_window_scopes.pop();
        self.outer_scopes = saved_outer_scopes;
        result
    }

    fn prepare_core_scope(
        &mut self,
        core: &'select SelectCore,
    ) -> Result<SelectColumnReferenceScope> {
        let connection = self.connection;
        let scope = SelectColumnReferenceScope::for_core(connection, core, |source| {
            self.metadata_source_column_names(source)
        })?;
        match core {
            SelectCore::Values(rows) => {
                if let Some(width) = rows.first().map(Vec::len)
                    && rows.iter().any(|row| row.len() != width)
                {
                    return Err(FrankenError::ParseError {
                        offset: 0,
                        detail: "all VALUES must have the same number of terms".to_owned(),
                    });
                }
            }
            SelectCore::Select { columns, from, .. } => {
                for column in columns {
                    match column {
                        ResultColumn::Star if from.is_none() => {
                            return Err(FrankenError::ParseError {
                                offset: 0,
                                detail: "no tables specified".to_owned(),
                            });
                        }
                        ResultColumn::TableStar(name)
                            if from.as_ref().is_none_or(|from| {
                                !SelectColumnReferenceScope::from_contains_source(from, name)
                            }) =>
                        {
                            return Err(FrankenError::NoSuchTable {
                                name: name.name.clone(),
                            });
                        }
                        ResultColumn::Expr { .. }
                        | ResultColumn::Star
                        | ResultColumn::TableStar(_) => {}
                    }
                }
            }
        }
        Ok(scope)
    }

    fn validate_core_before_order(
        &mut self,
        core: &'select SelectCore,
        scope: &SelectColumnReferenceScope,
    ) -> Result<()> {
        match core {
            SelectCore::Values(rows) => {
                self.named_window_scopes.push(&[]);
                let result: Result<()> = (|| {
                    for row in rows.iter().rev() {
                        for expression in row {
                            self.validate_expr(expression, scope, SelectOutputAliasUse::None)?;
                        }
                    }
                    Ok(())
                })();
                self.named_window_scopes.pop();
                result?;
            }
            SelectCore::Select {
                columns,
                from,
                where_clause,
                having,
                windows,
                ..
            } => {
                self.named_window_scopes.push(windows);
                let result: Result<()> = (|| {
                    if let Some(from) = from {
                        self.validate_from_sources(from)?;
                    }
                    for column in columns {
                        if let ResultColumn::Expr { expr, .. } = column {
                            self.validate_expr(expr, scope, SelectOutputAliasUse::None)?;
                            if matches!(expr, Expr::RowValue(_, _)) {
                                return Err(FrankenError::FunctionError(
                                    "row value misused".to_owned(),
                                ));
                            }
                        }
                    }
                    if let Some(predicate) = having {
                        self.validate_expr(predicate, scope, SelectOutputAliasUse::Having)?;
                    }
                    if let Some(predicate) = where_clause {
                        self.validate_expr(predicate, scope, SelectOutputAliasUse::Where)?;
                    }
                    if let Some(from) = from {
                        self.validate_join_on_expressions(from, scope)?;
                        self.validate_table_function_args(from, scope)?;
                    }
                    Ok(())
                })();
                self.named_window_scopes.pop();
                result?;
            }
        }
        Ok(())
    }

    fn validate_core_after_order(
        &mut self,
        core: &'select SelectCore,
        scope: &SelectColumnReferenceScope,
    ) -> Result<()> {
        if let SelectCore::Select {
            group_by, windows, ..
        } = core
        {
            let saved_outer_scopes = std::mem::take(&mut self.outer_scopes);
            self.named_window_scopes.push(windows);
            let result = group_by.iter().try_for_each(|expression| {
                self.validate_expr(expression, scope, SelectOutputAliasUse::GroupBy)
            });
            self.named_window_scopes.pop();
            self.outer_scopes = saved_outer_scopes;
            result?;
        }
        Ok(())
    }

    fn validate_from_sources(&mut self, from: &'select FromClause) -> Result<()> {
        self.validate_source_relations(&from.source)?;
        for join in &from.joins {
            self.validate_source_relations(&join.table)?;
        }
        Ok(())
    }

    fn validate_source_relations(&mut self, source: &'select TableOrSubquery) -> Result<()> {
        match source {
            TableOrSubquery::Table { name, .. } => {
                if name.schema.is_none()
                    && let Some((scope_index, cte)) = self.visible_cte(name)
                {
                    self.validate_cte(cte, scope_index)?;
                    return Ok(());
                }
                self.validate_referenced_view(name)
            }
            TableOrSubquery::Subquery { query, .. } => self.validate_select(query),
            TableOrSubquery::TableFunction { .. } => Ok(()),
            TableOrSubquery::ParenJoin(from) => self.validate_from_sources(from),
        }
    }

    fn validate_join_on_expressions(
        &mut self,
        from: &'select FromClause,
        scope: &SelectColumnReferenceScope,
    ) -> Result<()> {
        if let TableOrSubquery::ParenJoin(nested) = &from.source {
            self.validate_join_on_expressions(nested, scope)?;
        }
        for join in &from.joins {
            if let TableOrSubquery::ParenJoin(nested) = &join.table {
                self.validate_join_on_expressions(nested, scope)?;
            }
            if let Some(JoinConstraint::On(predicate)) = &join.constraint {
                self.validate_expr(predicate, scope, SelectOutputAliasUse::JoinOn)?;
            }
        }
        Ok(())
    }

    fn validate_table_function_args(
        &mut self,
        from: &'select FromClause,
        scope: &SelectColumnReferenceScope,
    ) -> Result<()> {
        self.validate_source_table_function_args(&from.source, scope)?;
        for join in &from.joins {
            self.validate_source_table_function_args(&join.table, scope)?;
        }
        Ok(())
    }

    fn validate_source_table_function_args(
        &mut self,
        source: &'select TableOrSubquery,
        scope: &SelectColumnReferenceScope,
    ) -> Result<()> {
        match source {
            TableOrSubquery::TableFunction { args, .. } => {
                for argument in args {
                    self.validate_expr(argument, scope, SelectOutputAliasUse::None)?;
                }
                Ok(())
            }
            TableOrSubquery::ParenJoin(from) => self.validate_table_function_args(from, scope),
            TableOrSubquery::Table { .. } | TableOrSubquery::Subquery { .. } => Ok(()),
        }
    }

    fn validate_cte(&mut self, cte: &'select fsqlite_ast::Cte, scope_index: usize) -> Result<()> {
        let key = std::ptr::from_ref(cte);
        if self.active_ctes.contains(&key) {
            return Ok(());
        }
        let validation_key = SelectCteValidationKey {
            cte: key,
            outer_scope_ids: self
                .outer_scopes
                .iter()
                .map(|scope| scope.identity)
                .collect(),
        };
        if self.validated_ctes.contains(&validation_key) {
            return Ok(());
        }
        self.active_ctes.insert(key);
        let hidden_scopes = self.cte_scopes.split_off(scope_index + 1);
        let result = self.validate_select(&cte.query);
        self.cte_scopes.extend(hidden_scopes);
        self.active_ctes.remove(&key);
        if result.is_ok() {
            self.validated_ctes.insert(validation_key);
        }
        result
    }

    fn visible_cte(&self, name: &QualifiedName) -> Option<(usize, &'select fsqlite_ast::Cte)> {
        if name.schema.is_some() {
            return None;
        }
        self.cte_scopes
            .iter()
            .enumerate()
            .rev()
            .find_map(|(scope_index, scope)| {
                scope
                    .iter()
                    .find(|cte| cte.name.eq_ignore_ascii_case(&name.name))
                    .map(|cte| (scope_index, cte))
            })
    }

    fn validate_referenced_view(&self, name: &QualifiedName) -> Result<()> {
        match name.schema.as_deref() {
            None => {
                if self.validate_local_referenced_relation(
                    &name.name,
                    PragmaSchemaScope::Unqualified,
                )? {
                    return Ok(());
                }
                let attached_schemas = self
                    .connection
                    .attached_schemas
                    .borrow()
                    .all_schemas()
                    .into_iter()
                    .skip(2)
                    .map(str::to_owned)
                    .collect::<Vec<_>>();
                for schema_name in attached_schemas {
                    let view_state = Rc::clone(&self.view_state);
                    let found =
                        self.connection
                            .with_attached_connection(&schema_name, |attached| {
                                SelectColumnReferenceResolver::with_view_state(attached, view_state)
                                    .validate_local_referenced_relation(
                                        &name.name,
                                        PragmaSchemaScope::Main,
                                    )
                            })?;
                    if found {
                        return Ok(());
                    }
                }
                Ok(())
            }
            Some(schema) if schema.eq_ignore_ascii_case("main") => {
                self.validate_local_referenced_relation(&name.name, PragmaSchemaScope::Main)?;
                Ok(())
            }
            Some(schema) if schema.eq_ignore_ascii_case("temp") => {
                self.validate_local_referenced_relation(&name.name, PragmaSchemaScope::Temp)?;
                Ok(())
            }
            Some(schema) if is_builtin_schema(schema) => Ok(()),
            Some(schema) => {
                let view_state = Rc::clone(&self.view_state);
                self.connection
                    .with_attached_connection(schema, |attached| {
                        SelectColumnReferenceResolver::with_view_state(attached, view_state)
                            .validate_local_referenced_relation(
                                &name.name,
                                PragmaSchemaScope::Main,
                            )?;
                        Ok(())
                    })
            }
        }
    }

    fn validate_local_referenced_relation(
        &self,
        relation_name: &str,
        requested_scope: PragmaSchemaScope,
    ) -> Result<bool> {
        let resolved_scope = if requested_scope == PragmaSchemaScope::Unqualified
            && (self
                .connection
                .table_exists_for_scope(relation_name, PragmaSchemaScope::Temp)
                || self
                    .connection
                    .view_index_for_scope(relation_name, PragmaSchemaScope::Temp)
                    .is_some())
        {
            PragmaSchemaScope::Temp
        } else if requested_scope == PragmaSchemaScope::Unqualified {
            PragmaSchemaScope::Main
        } else {
            requested_scope
        };
        if self
            .connection
            .table_exists_for_scope(relation_name, resolved_scope)
            || (resolved_scope == PragmaSchemaScope::Main
                && self.connection.has_live_vtab_instance(relation_name))
        {
            return Ok(true);
        }
        let view = self
            .connection
            .view_index_for_scope(relation_name, resolved_scope)
            .and_then(|index| self.connection.views.borrow().get(index).cloned());
        let Some(view) = view else {
            return Ok(false);
        };

        let view_key = format!(
            "{:p}:{resolved_scope:?}:{}",
            self.connection,
            relation_name.to_ascii_lowercase()
        );
        {
            let mut state = self.view_state.borrow_mut();
            if state.validated.contains(&view_key) {
                return Ok(true);
            }
            if !state.active.insert(view_key.clone()) {
                return Err(FrankenError::FunctionError(format!(
                    "view {relation_name} is circularly defined"
                )));
            }
        }

        let mut query = view.query.clone();
        if !view.temporary {
            qualify_persistent_view_relations(&mut query);
        }
        let view_state = Rc::clone(&self.view_state);
        let result = self.connection.with_fallback_function_registry(|| {
            SelectColumnReferenceResolver::with_view_state(self.connection, view_state)
                .validate_select(&query)
        });
        let mut state = self.view_state.borrow_mut();
        state.active.remove(&view_key);
        if result.is_ok() {
            state.validated.insert(view_key);
        }
        result?;
        Ok(true)
    }

    fn metadata_source_column_names(
        &mut self,
        source: &'select TableOrSubquery,
    ) -> Result<SelectSourceColumnMetadata> {
        match source {
            TableOrSubquery::Table { name, .. } => {
                if let Some((scope_index, cte)) = self.visible_cte(name) {
                    let metadata = self.metadata_cte_column_names(cte, scope_index)?;
                    return Ok(SelectSourceColumnMetadata {
                        names: metadata.names,
                        hidden_rowid: None,
                        is_live_fts5: false,
                        approximate_names: metadata.approximate_names,
                        generated_suffix_upper_bounds: metadata.generated_suffix_upper_bounds,
                        width_is_exact: metadata.width_is_exact,
                    });
                }
                if name.schema.is_none()
                    && !self.local_unqualified_relation_exists_for_metadata(&name.name)
                    && let Some(metadata) =
                        self.metadata_unqualified_attached_table_source(source, &name.name)?
                {
                    return Ok(metadata);
                }
                if let Some(metadata) = self.metadata_table_view_column_names(name)? {
                    return Ok(SelectSourceColumnMetadata {
                        names: metadata.names,
                        hidden_rowid: None,
                        is_live_fts5: false,
                        approximate_names: metadata.approximate_names,
                        generated_suffix_upper_bounds: metadata.generated_suffix_upper_bounds,
                        width_is_exact: metadata.width_is_exact,
                    });
                }
                let names = self.connection.table_or_subquery_result_column_names(
                    source,
                    &[],
                    &mut Vec::new(),
                );
                Ok(SelectSourceColumnMetadata {
                    hidden_rowid: self
                        .connection
                        .hidden_rowid_projection_for_source(source, &names),
                    is_live_fts5: self.table_source_is_live_fts5(name)?,
                    approximate_names: vec![false; names.len()],
                    generated_suffix_upper_bounds: vec![None; names.len()],
                    width_is_exact: true,
                    names,
                })
            }
            TableOrSubquery::Subquery { query, .. } => {
                let metadata = self.metadata_select_column_names(query)?;
                Ok(SelectSourceColumnMetadata {
                    names: metadata.names,
                    hidden_rowid: None,
                    is_live_fts5: false,
                    approximate_names: metadata.approximate_names,
                    generated_suffix_upper_bounds: metadata.generated_suffix_upper_bounds,
                    width_is_exact: metadata.width_is_exact,
                })
            }
            TableOrSubquery::TableFunction { .. } => {
                let names = self.connection.table_or_subquery_result_column_names(
                    source,
                    &[],
                    &mut Vec::new(),
                );
                Ok(SelectSourceColumnMetadata {
                    hidden_rowid: self
                        .connection
                        .hidden_rowid_projection_for_source(source, &names),
                    is_live_fts5: false,
                    approximate_names: vec![false; names.len()],
                    generated_suffix_upper_bounds: vec![None; names.len()],
                    width_is_exact: true,
                    names,
                })
            }
            TableOrSubquery::ParenJoin(from) => {
                let metadata = self.metadata_from_column_names(from)?;
                Ok(SelectSourceColumnMetadata {
                    names: metadata.names,
                    hidden_rowid: None,
                    is_live_fts5: false,
                    approximate_names: metadata.approximate_names,
                    generated_suffix_upper_bounds: metadata.generated_suffix_upper_bounds,
                    width_is_exact: metadata.width_is_exact,
                })
            }
        }
    }

    fn metadata_table_view_column_names(
        &self,
        name: &QualifiedName,
    ) -> Result<Option<SelectResultColumnMetadata>> {
        match name.schema.as_deref() {
            None => {
                if self
                    .connection
                    .table_exists_for_scope(&name.name, PragmaSchemaScope::Temp)
                {
                    return Ok(None);
                }
                if let Some(index) = self
                    .connection
                    .view_index_for_scope(&name.name, PragmaSchemaScope::Temp)
                {
                    return self.metadata_stored_view_column_names(index).map(Some);
                }
                if self
                    .connection
                    .table_exists_for_scope(&name.name, PragmaSchemaScope::Main)
                    || self.connection.has_live_vtab_instance(&name.name)
                {
                    return Ok(None);
                }
                if let Some(index) = self
                    .connection
                    .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                {
                    return self.metadata_stored_view_column_names(index).map(Some);
                }
                Ok(None)
            }
            Some(schema) if schema.eq_ignore_ascii_case("main") => self
                .connection
                .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                .map(|index| self.metadata_stored_view_column_names(index))
                .transpose(),
            Some(schema) if schema.eq_ignore_ascii_case("temp") => self
                .connection
                .view_index_for_scope(&name.name, PragmaSchemaScope::Temp)
                .map(|index| self.metadata_stored_view_column_names(index))
                .transpose(),
            Some(schema) if is_builtin_schema(schema) => Ok(None),
            Some(schema) => {
                let view_state = Rc::clone(&self.view_state);
                self.connection
                    .with_attached_connection(schema, |attached| {
                        let Some(index) =
                            attached.view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                        else {
                            return Ok(None);
                        };
                        SelectColumnReferenceResolver::with_view_state(attached, view_state)
                            .metadata_stored_view_column_names(index)
                            .map(Some)
                    })
            }
        }
    }

    fn metadata_stored_view_column_names(
        &self,
        index: usize,
    ) -> Result<SelectResultColumnMetadata> {
        let view = self
            .connection
            .views
            .borrow()
            .get(index)
            .cloned()
            .ok_or_else(|| FrankenError::Internal("view metadata index is stale".to_owned()))?;
        if !view.columns.is_empty() {
            return Ok(SelectResultColumnMetadata {
                approximate_names: vec![false; view.columns.len()],
                generated_suffix_upper_bounds: vec![None; view.columns.len()],
                names: view.columns,
                width_is_exact: true,
            });
        }
        let mut query = view.query;
        if !view.temporary {
            qualify_persistent_view_relations(&mut query);
        }
        let view_state = Rc::clone(&self.view_state);
        SelectColumnReferenceResolver::with_view_state(self.connection, view_state)
            .metadata_select_column_names(&query)
    }

    fn local_unqualified_relation_exists_for_metadata(&self, relation_name: &str) -> bool {
        SelectRelationResolver::new(self.connection)
            .builtin_schema_relation_exists(relation_name, PragmaSchemaScope::Unqualified)
            || self
                .connection
                .table_exists_for_scope(relation_name, PragmaSchemaScope::Temp)
            || self
                .connection
                .table_exists_for_scope(relation_name, PragmaSchemaScope::Main)
            || self
                .connection
                .view_index_for_scope(relation_name, PragmaSchemaScope::Temp)
                .is_some()
            || self
                .connection
                .view_index_for_scope(relation_name, PragmaSchemaScope::Main)
                .is_some()
            || self.connection.has_live_vtab_instance(relation_name)
    }

    fn metadata_unqualified_attached_table_source(
        &self,
        source: &TableOrSubquery,
        relation_name: &str,
    ) -> Result<Option<SelectSourceColumnMetadata>> {
        let schema_names = self
            .connection
            .attached_schemas
            .borrow()
            .all_schemas()
            .into_iter()
            .skip(2)
            .map(str::to_owned)
            .collect::<Vec<_>>();
        for schema_name in schema_names {
            let metadata = self
                .connection
                .with_attached_connection(&schema_name, |attached| {
                    let relation_exists = SelectRelationResolver::new(attached)
                        .builtin_schema_relation_exists(relation_name, PragmaSchemaScope::Main)
                        || attached.table_exists_for_scope(relation_name, PragmaSchemaScope::Main)
                        || attached
                            .view_index_for_scope(relation_name, PragmaSchemaScope::Main)
                            .is_some()
                        || attached.has_live_vtab_instance(relation_name);
                    if !relation_exists {
                        return Ok(None);
                    }

                    let view_index =
                        attached.view_index_for_scope(relation_name, PragmaSchemaScope::Main);
                    let view_metadata = view_index
                        .map(|index| {
                            SelectColumnReferenceResolver::with_view_state(
                                attached,
                                Rc::clone(&self.view_state),
                            )
                            .metadata_stored_view_column_names(index)
                        })
                        .transpose()?;
                    let (names, approximate_names, generated_suffix_upper_bounds, width_is_exact) =
                        if let Some(metadata) = view_metadata {
                            (
                                metadata.names,
                                metadata.approximate_names,
                                metadata.generated_suffix_upper_bounds,
                                metadata.width_is_exact,
                            )
                        } else {
                            let mut active_ctes = Vec::new();
                            let names = attached.named_relation_result_column_names(
                                relation_name,
                                PragmaSchemaScope::Main,
                                &[],
                                &mut active_ctes,
                            );
                            let width = names.len();
                            (names, vec![false; width], vec![None; width], true)
                        };
                    let qualified_source = match source {
                        TableOrSubquery::Table {
                            alias,
                            index_hint,
                            time_travel,
                            ..
                        } => TableOrSubquery::Table {
                            name: QualifiedName::qualified("main", relation_name),
                            alias: alias.clone(),
                            index_hint: index_hint.clone(),
                            time_travel: time_travel.clone(),
                        },
                        _ => unreachable!("attached metadata source must be a named table"),
                    };
                    Ok(Some(SelectSourceColumnMetadata {
                        hidden_rowid: attached
                            .hidden_rowid_projection_for_source(&qualified_source, &names),
                        is_live_fts5: view_index.is_none()
                            && attached.has_live_fts5_instance(relation_name),
                        approximate_names,
                        generated_suffix_upper_bounds,
                        width_is_exact,
                        names,
                    }))
                })?;
            if metadata.is_some() {
                return Ok(metadata);
            }
        }
        Ok(None)
    }

    fn table_source_is_live_fts5(&self, name: &QualifiedName) -> Result<bool> {
        match name.schema.as_deref() {
            None => {
                if self
                    .connection
                    .table_exists_for_scope(&name.name, PragmaSchemaScope::Temp)
                    || self
                        .connection
                        .view_index_for_scope(&name.name, PragmaSchemaScope::Temp)
                        .is_some()
                    || self
                        .connection
                        .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                        .is_some()
                {
                    return Ok(false);
                }
                Ok(self.connection.has_live_fts5_instance(&name.name))
            }
            Some(schema) if schema.eq_ignore_ascii_case("main") => Ok(self
                .connection
                .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                .is_none()
                && self.connection.has_live_fts5_instance(&name.name)),
            Some(schema) if schema.eq_ignore_ascii_case("temp") || is_builtin_schema(schema) => {
                Ok(false)
            }
            Some(schema) => self
                .connection
                .with_attached_connection(schema, |attached| {
                    Ok(attached
                        .view_index_for_scope(&name.name, PragmaSchemaScope::Main)
                        .is_none()
                        && attached.has_live_fts5_instance(&name.name))
                }),
        }
    }

    fn metadata_select_column_names(
        &mut self,
        select: &'select SelectStatement,
    ) -> Result<SelectResultColumnMetadata> {
        let key = std::ptr::from_ref(select);
        if let Some(metadata) = self.metadata_select_columns.get(&key) {
            return Ok(metadata.clone());
        }
        let cte_scope_depth = self.cte_scopes.len();
        if let Some(with) = &select.with {
            self.cte_scopes.push(&with.ctes);
        }
        let metadata_result: Result<SelectResultColumnMetadata> = (|| {
            for (_, core) in select.body.compounds.iter().rev() {
                self.metadata_select_core_column_names(core)?;
            }
            self.metadata_select_core_column_names(&select.body.select)
        })();
        self.cte_scopes.truncate(cte_scope_depth);
        if let Ok(metadata) = &metadata_result {
            self.metadata_select_columns.insert(key, metadata.clone());
        }
        metadata_result
    }

    fn metadata_select_core_column_names(
        &mut self,
        core: &'select SelectCore,
    ) -> Result<SelectResultColumnMetadata> {
        match core {
            SelectCore::Values(rows) => {
                let width = rows.first().map_or(0, Vec::len);
                if rows.iter().any(|row| row.len() != width) {
                    return Err(FrankenError::ParseError {
                        offset: 0,
                        detail: "all VALUES must have the same number of terms".to_owned(),
                    });
                }
                Ok(SelectResultColumnMetadata {
                    names: (1..=width)
                        .map(|index| format!("column{index}"))
                        .collect::<Vec<_>>(),
                    approximate_names: vec![false; width],
                    generated_suffix_upper_bounds: vec![None; width],
                    width_is_exact: true,
                })
            }
            SelectCore::Select { columns, from, .. } => {
                // Source layout is established even when the projection does
                // not contain `*`. In particular, an invalid nested USING
                // must precede an enclosing SELECT's LIMIT/OFFSET error.
                let from_column_names = from
                    .as_ref()
                    .map(|from| self.metadata_from_column_names(from))
                    .transpose()?;
                let mut names = Vec::with_capacity(columns.len());
                let mut approximate_names = Vec::with_capacity(columns.len());
                let mut generated_suffix_upper_bounds = Vec::with_capacity(columns.len());
                let mut width_is_exact = true;
                for column in columns {
                    match column {
                        ResultColumn::Star => {
                            if let Some(from_column_names) = &from_column_names {
                                names.extend(from_column_names.names.iter().cloned());
                                approximate_names
                                    .extend(from_column_names.approximate_names.iter().copied());
                                generated_suffix_upper_bounds.extend(
                                    from_column_names
                                        .generated_suffix_upper_bounds
                                        .iter()
                                        .copied(),
                                );
                                width_is_exact &= from_column_names.width_is_exact;
                            } else {
                                return Err(FrankenError::ParseError {
                                    offset: 0,
                                    detail: "no tables specified".to_owned(),
                                });
                            }
                        }
                        ResultColumn::TableStar(name) => {
                            if let Some(from) = from
                                && let Some(source_metadata) =
                                    self.metadata_named_source_column_names(from, name)?
                            {
                                let source_width = source_metadata.names.len();
                                names.extend(source_metadata.names);
                                approximate_names.extend(
                                    source_metadata
                                        .approximate_names
                                        .into_iter()
                                        .chain(std::iter::repeat(true))
                                        .take(source_width),
                                );
                                generated_suffix_upper_bounds.extend(
                                    source_metadata
                                        .generated_suffix_upper_bounds
                                        .into_iter()
                                        .chain(std::iter::repeat(None))
                                        .take(source_width),
                                );
                                width_is_exact &= source_metadata.width_is_exact;
                            } else {
                                return Err(FrankenError::NoSuchTable {
                                    name: name.name.clone(),
                                });
                            }
                        }
                        ResultColumn::Expr {
                            alias: Some(alias), ..
                        } => {
                            names.push(alias.clone());
                            approximate_names.push(false);
                            generated_suffix_upper_bounds.push(None);
                        }
                        ResultColumn::Expr { expr, .. } => match strip_collate_wrappers(expr) {
                            Expr::Column(column, _) => {
                                names.push(column.column.to_string());
                                approximate_names.push(false);
                                generated_suffix_upper_bounds.push(None);
                            }
                            _ => {
                                names.push(expr.to_string());
                                approximate_names.push(true);
                                generated_suffix_upper_bounds.push(None);
                            }
                        },
                    }
                }
                Ok(SelectResultColumnMetadata {
                    names,
                    approximate_names,
                    generated_suffix_upper_bounds,
                    width_is_exact,
                })
            }
        }
    }

    fn metadata_from_column_names(
        &mut self,
        from: &'select FromClause,
    ) -> Result<SelectResultColumnMetadata> {
        let connection = self.connection;
        let mut col_map = Vec::new();
        let mut using_skip = HashSet::new();
        let mut match_table_names = Vec::new();
        let mut fts5_rank_table_names = Vec::new();
        let mut approximate_col_map = Vec::new();
        let mut width_is_exact = true;
        let visible = SelectColumnReferenceScope::append_from_layout(
            connection,
            from,
            &mut |source| self.metadata_source_column_names(source),
            &mut col_map,
            &mut using_skip,
            &mut match_table_names,
            &mut fts5_rank_table_names,
            &mut approximate_col_map,
            &mut width_is_exact,
        )?;
        Ok(SelectResultColumnMetadata {
            names: visible.iter().map(|column| column.name.clone()).collect(),
            approximate_names: visible.iter().map(|column| column.approximate).collect(),
            generated_suffix_upper_bounds: visible
                .into_iter()
                .map(|column| column.generated_suffix_upper_bound)
                .collect(),
            width_is_exact,
        })
    }

    fn metadata_named_source_column_names(
        &mut self,
        from: &'select FromClause,
        target: &QualifiedName,
    ) -> Result<Option<SelectResultColumnMetadata>> {
        for source in std::iter::once(&from.source).chain(from.joins.iter().map(|join| &join.table))
        {
            if source_matches_name(source, target) {
                let source_metadata = self.metadata_source_column_names(source)?;
                let mut names = source_metadata.names;
                let mut approximate_names = source_metadata.approximate_names;
                let mut generated_suffix_upper_bounds =
                    source_metadata.generated_suffix_upper_bounds;
                if !source_metadata.width_is_exact {
                    approximate_names.resize(names.len(), true);
                    approximate_names.fill(true);
                }
                normalize_uncertain_sqlite_result_column_names(
                    &mut names,
                    &mut approximate_names,
                    &mut generated_suffix_upper_bounds,
                );
                return Ok(Some(SelectResultColumnMetadata {
                    names,
                    approximate_names,
                    generated_suffix_upper_bounds,
                    width_is_exact: source_metadata.width_is_exact,
                }));
            }
            if let TableOrSubquery::ParenJoin(nested) = source
                && let Some(names) = self.metadata_named_source_column_names(nested, target)?
            {
                return Ok(Some(names));
            }
        }
        Ok(None)
    }

    fn metadata_cte_column_names(
        &mut self,
        cte: &'select fsqlite_ast::Cte,
        scope_index: usize,
    ) -> Result<SelectResultColumnMetadata> {
        let key = std::ptr::from_ref(cte);
        if let Some(metadata) = self.metadata_cte_columns.get(&key) {
            return Ok(metadata.clone());
        }
        if !self.metadata_active_ctes.insert(key) {
            if !cte.columns.is_empty() {
                return Ok(SelectResultColumnMetadata {
                    names: cte.columns.clone(),
                    approximate_names: vec![false; cte.columns.len()],
                    generated_suffix_upper_bounds: vec![None; cte.columns.len()],
                    width_is_exact: true,
                });
            }
            let inferred = infer_select_column_names(&cte.query);
            let width = inferred.len().max(1);
            return Ok(SelectResultColumnMetadata {
                names: if inferred.is_empty() {
                    vec!["_c0".to_owned()]
                } else {
                    inferred
                },
                approximate_names: vec![true; width],
                generated_suffix_upper_bounds: vec![None; width],
                width_is_exact: false,
            });
        }
        let hidden_scopes = self.cte_scopes.split_off(scope_index + 1);
        let names_result = self.metadata_select_column_names(&cte.query);
        self.cte_scopes.extend(hidden_scopes);
        self.metadata_active_ctes.remove(&key);
        let mut metadata = names_result?;
        let mut names = metadata.names;
        if !cte.columns.is_empty() && metadata.width_is_exact && names.len() != cte.columns.len() {
            return Err(FrankenError::FunctionError(format!(
                "table {} has {} values for {} columns",
                cte.name,
                names.len(),
                cte.columns.len()
            )));
        }
        if !cte.columns.is_empty() {
            names.clone_from(&cte.columns);
            metadata.approximate_names = vec![false; names.len()];
            metadata.generated_suffix_upper_bounds = vec![None; names.len()];
            metadata.width_is_exact = true;
        }
        if names.is_empty() {
            names.push("_c0".to_owned());
            metadata.approximate_names = vec![true];
            metadata.generated_suffix_upper_bounds = vec![None];
            metadata.width_is_exact = false;
        }
        metadata.approximate_names.resize(names.len(), true);
        metadata.approximate_names.truncate(names.len());
        if !metadata.width_is_exact {
            metadata.approximate_names.fill(true);
        }
        normalize_uncertain_sqlite_result_column_names(
            &mut names,
            &mut metadata.approximate_names,
            &mut metadata.generated_suffix_upper_bounds,
        );
        metadata.names = names;
        self.metadata_cte_columns.insert(key, metadata.clone());
        Ok(metadata)
    }

    fn validate_nested_select(
        &mut self,
        select: &'select SelectStatement,
        scope: &SelectColumnReferenceScope,
    ) -> Result<()> {
        self.outer_scopes.push(scope.clone());
        let result = self.validate_select(select);
        self.outer_scopes.pop();
        result
    }

    #[allow(clippy::too_many_lines)]
    fn validate_expr(
        &mut self,
        expr: &'select Expr,
        scope: &SelectColumnReferenceScope,
        alias_use: SelectOutputAliasUse,
    ) -> Result<()> {
        if expr_folds_to_integer_zero_via_and(expr) {
            return Ok(());
        }
        match expr {
            Expr::BoundOuterValue { .. }
            | Expr::Literal(_, _)
            | Expr::Raise { .. }
            | Expr::Placeholder(_, _) => Ok(()),
            Expr::Column(column, _) => self.validate_column(column, scope, alias_use),
            Expr::BinaryOp { left, right, .. }
            | Expr::JsonAccess {
                expr: left,
                path: right,
                ..
            } => {
                self.validate_expr(left, scope, alias_use)?;
                self.validate_expr(right, scope, alias_use)
            }
            Expr::UnaryOp { expr, .. }
            | Expr::IsNull { expr, .. }
            | Expr::Cast { expr, .. }
            | Expr::Collate { expr, .. } => self.validate_expr(expr, scope, alias_use),
            Expr::Between {
                expr, low, high, ..
            } => {
                self.validate_expr(expr, scope, alias_use)?;
                self.validate_expr(low, scope, alias_use)?;
                self.validate_expr(high, scope, alias_use)
            }
            Expr::In { expr, set, .. } => {
                if matches!(set, InSet::List(values) if values.is_empty()) {
                    return Ok(());
                }
                if let InSet::List(values) = set {
                    self.connection
                        .validate_in_list_early_row_misuse(expr, values)?;
                }
                let singleton_subquery = match set {
                    InSet::Subquery(select) => Some(select.as_ref()),
                    InSet::List(values) => match values.as_slice() {
                        [Expr::Subquery(select, _)] => Some(select.as_ref()),
                        _ => None,
                    },
                    InSet::Table(_) => None,
                };
                if let Some(select) = singleton_subquery {
                    // SQLite resolves an IN-subquery's SELECT before the LHS;
                    // an ordinary expression list retains LHS-first order.
                    self.validate_nested_select(select, scope)?;
                    return self.validate_expr(expr, scope, alias_use);
                }
                if let (Expr::RowValue(lhs_values, _), InSet::List(values)) = (expr.as_ref(), set)
                    && values.len() > 1
                {
                    validate_vector_in_list_arity(lhs_values.len(), values)?;
                    // Multi-row vector lists are resolved in the same order
                    // SQLite materializes them: rightmost tuple first, each
                    // tuple's fields left-to-right, and only then the LHS.
                    for value in values.iter().rev() {
                        self.validate_expr(value, scope, alias_use)?;
                    }
                    return self.validate_expr(expr, scope, alias_use);
                }
                self.validate_expr(expr, scope, alias_use)?;
                match set {
                    InSet::List(values) => {
                        for value in values {
                            self.validate_expr(value, scope, alias_use)?;
                        }
                        Ok(())
                    }
                    InSet::Subquery(_) => {
                        unreachable!("subquery IN sets are handled before the LHS")
                    }
                    InSet::Table(_) => Ok(()),
                }
            }
            Expr::Like {
                expr,
                pattern,
                op,
                escape,
                ..
            } => {
                self.validate_expr(pattern, scope, alias_use)?;
                if !matches!(op, LikeOp::Match) || !scope.is_match_table_operand(expr) {
                    self.validate_expr(expr, scope, alias_use)?;
                }
                if let Some(escape) = escape {
                    self.validate_expr(escape, scope, alias_use)?;
                }
                Ok(())
            }
            Expr::Case {
                operand,
                whens,
                else_expr,
                ..
            } => {
                if let Some(operand) = operand {
                    self.validate_expr(operand, scope, alias_use)?;
                }
                for (condition, value) in whens {
                    self.validate_expr(condition, scope, alias_use)?;
                    self.validate_expr(value, scope, alias_use)?;
                }
                if let Some(else_expr) = else_expr {
                    self.validate_expr(else_expr, scope, alias_use)?;
                }
                Ok(())
            }
            Expr::Subquery(select, _)
            | Expr::Exists {
                subquery: select, ..
            } => self.validate_nested_select(select, scope),
            Expr::FunctionCall {
                name,
                args,
                distinct,
                order_by,
                filter,
                over,
                ..
            } => {
                let resolved_aggregate_or_window =
                    validate_function_call_resolution(name, args, over.as_ref()).is_ok()
                        && ((is_current_aggregate_or_json_fn(name, args)
                            && !is_scalar_max_min(name, args))
                            || over.is_some());
                if !resolved_aggregate_or_window {
                    self.validate_function_arguments(name, args, scope, alias_use)?;
                }
                validate_function_call_header(
                    name,
                    args,
                    *distinct,
                    order_by,
                    filter.as_deref(),
                    over.as_ref(),
                )?;
                if let Some(filter) = filter {
                    self.validate_expr(filter, scope, alias_use)?;
                }
                if let Some(window) = over {
                    self.validate_window(window, scope)?;
                }
                for term in order_by {
                    self.validate_expr(&term.expr, scope, alias_use)?;
                }
                if resolved_aggregate_or_window {
                    self.validate_function_arguments(name, args, scope, alias_use)?;
                }
                Ok(())
            }
            Expr::RowValue(values, _) => {
                for value in values {
                    self.validate_expr(value, scope, alias_use)?;
                }
                Ok(())
            }
        }
    }

    fn validate_function_arguments(
        &mut self,
        name: &str,
        args: &'select FunctionArgs,
        scope: &SelectColumnReferenceScope,
        alias_use: SelectOutputAliasUse,
    ) -> Result<()> {
        let FunctionArgs::List(arguments) = args else {
            return Ok(());
        };
        for (index, argument) in arguments.iter().enumerate() {
            if index == 0
                && is_fts5_aux_function_name(name)
                && scope.is_match_table_operand(argument)
            {
                continue;
            }
            self.validate_expr(argument, scope, alias_use)?;
        }
        Ok(())
    }

    fn validate_window(
        &mut self,
        window: &'select WindowSpec,
        scope: &SelectColumnReferenceScope,
    ) -> Result<()> {
        let named_windows = self.named_window_scopes.last().copied().unwrap_or_default();
        for definition in resolved_window_spec_chain(window, named_windows)? {
            self.validate_window_clauses(definition, scope)?;
        }
        self.validate_window_clauses(window, scope)
    }

    fn validate_window_clauses(
        &mut self,
        window: &'select WindowSpec,
        scope: &SelectColumnReferenceScope,
    ) -> Result<()> {
        for term in &window.order_by {
            self.validate_expr(&term.expr, scope, SelectOutputAliasUse::None)?;
        }
        for expression in &window.partition_by {
            self.validate_expr(expression, scope, SelectOutputAliasUse::None)?;
        }
        // SQLite treats frame offsets as runtime constant expressions rather
        // than ordinary lexical SELECT expressions. Do not resolve columns,
        // functions, or nested SELECTs here; the window executor applies the
        // dedicated non-negative-offset check if a row reaches the frame.
        Ok(())
    }

    fn validate_column(
        &self,
        column: &ColumnRef,
        scope: &SelectColumnReferenceScope,
        alias_use: SelectOutputAliasUse,
    ) -> Result<()> {
        if self.scope_resolves_column(scope, column)? {
            return Ok(());
        }
        if alias_use != SelectOutputAliasUse::None
            && column.table.is_none()
            && let Some(alias) = scope.output_alias(&column.column)
        {
            if alias.is_window && !matches!(alias_use, SelectOutputAliasUse::OrderBy) {
                return Err(FrankenError::FunctionError(format!(
                    "misuse of aliased window function {}",
                    alias.name
                )));
            }
            if alias.is_aggregate {
                match alias_use {
                    SelectOutputAliasUse::GroupBy => {
                        return Err(FrankenError::FunctionError(
                            "aggregate functions are not allowed in the GROUP BY clause".to_owned(),
                        ));
                    }
                    SelectOutputAliasUse::Where | SelectOutputAliasUse::JoinOn => {
                        let detail = alias.aggregate_name.as_ref().map_or_else(
                            || "misuse of aggregate function".to_owned(),
                            |name| format!("misuse of aggregate: {name}()"),
                        );
                        return Err(FrankenError::FunctionError(detail));
                    }
                    SelectOutputAliasUse::None
                    | SelectOutputAliasUse::Having
                    | SelectOutputAliasUse::OrderBy => {}
                }
            }
            return Ok(());
        }
        for outer_scope in self.outer_scopes.iter().rev() {
            if self.scope_resolves_column(outer_scope, column)? {
                return Ok(());
            }
        }
        let name = column.table.as_ref().map_or_else(
            || column.column.to_string(),
            |table| format!("{table}.{}", column.column),
        );
        Err(FrankenError::NoSuchColumn { name })
    }

    fn scope_resolves_column(
        &self,
        scope: &SelectColumnReferenceScope,
        column: &ColumnRef,
    ) -> Result<bool> {
        if let Some(table) = column.table.as_deref()
            && !scope
                .valid_qualifiers
                .iter()
                .any(|qualifier| qualifier.eq_ignore_ascii_case(table))
        {
            return Ok(false);
        }
        match find_col_in_map(
            &scope.col_map,
            column.table.as_deref(),
            &column.column,
            scope.using_skip(),
        ) {
            Ok(_) => Ok(true),
            Err(error @ FrankenError::AmbiguousColumn { .. }) => {
                // An approximate source-name candidate can participate in a
                // NATURAL/USING coalescence that the AST alone cannot prove.
                // Defer the ambiguous outcome instead of manufacturing a
                // false prepare-time rejection from pretty-printed names.
                if scope.resolves_approximate_column(column) {
                    Ok(true)
                } else {
                    Err(error)
                }
            }
            Err(FrankenError::Internal(_)) => Ok(scope.resolves_approximate_column(column)
                || scope.resolves_fts5_rank_column(column)),
            Err(error) => Err(error),
        }
    }
}

struct SelectStructureResolver<'a> {
    connection: &'a Connection,
    scopes: Vec<&'a [fsqlite_ast::Cte]>,
    visits: HashMap<*const fsqlite_ast::Cte, CteCollationVisit>,
    semantic_depth: usize,
    view_definition_mode: bool,
    column_reference_preflight_completed: bool,
}

impl<'a> SelectStructureResolver<'a> {
    fn new(connection: &'a Connection) -> Self {
        Self {
            connection,
            scopes: Vec::new(),
            visits: HashMap::new(),
            semantic_depth: 0,
            view_definition_mode: false,
            column_reference_preflight_completed: false,
        }
    }

    fn validate_select(&mut self, select: &'a SelectStatement) -> Result<()> {
        if self.semantic_depth == 0 {
            SelectRelationResolver::new(self.connection).validate_select(select)?;
        }
        self.validate_select_semantics(select)
    }

    fn validate_select_without_relation_preflight(
        &mut self,
        select: &'a SelectStatement,
        column_reference_preflight_completed: bool,
    ) -> Result<()> {
        self.column_reference_preflight_completed = column_reference_preflight_completed;
        self.validate_select_semantics(select)
    }

    fn validate_create_view(&mut self, select: &'a SelectStatement) -> Result<()> {
        if select_contains_any_placeholder(select) {
            return Err(FrankenError::FunctionError(
                "parameters are not allowed in views".to_owned(),
            ));
        }
        self.view_definition_mode = true;
        self.validate_select_semantics(select)
    }

    fn validate_select_semantics(&mut self, select: &'a SelectStatement) -> Result<()> {
        let semantic_depth = self.semantic_depth;
        self.semantic_depth = self.semantic_depth.saturating_add(1);
        let scope_depth = self.scopes.len();
        let outer_ctes = (!select.body.compounds.is_empty() || !select.order_by.is_empty())
            .then(|| self.visible_ctes());
        if let Some(with) = &select.with {
            self.scopes.push(&with.ctes);
        }

        let result = (|| {
            if !self.view_definition_mode
                && !self.column_reference_preflight_completed
                && select.limit.is_some()
                && (select_requires_layout_preflight_before_limit(select)
                    || select_references_view_for_layout(select, self.connection)?)
            {
                SelectColumnReferenceResolver::new(self.connection)
                    .validate_select_layout(select)?;
            }
            for index in (0..=select.body.compounds.len()).rev() {
                let core = if index == 0 {
                    &select.body.select
                } else {
                    &select.body.compounds[index - 1].1
                };
                Self::validate_core_shape_before_limit(core)?;
            }
            let top_windows = select_core_named_windows(&select.body.select);
            if let Some(limit) = &select.limit {
                self.validate_expr(&limit.limit, top_windows)?;
                if let Some(offset) = &limit.offset {
                    self.validate_expr(offset, top_windows)?;
                }
            }

            if select.body.compounds.is_empty() {
                self.validate_core_before_order(&select.body.select, top_windows)?;
                if self.view_definition_mode {
                    for term in &select.order_by {
                        self.validate_expr(&term.expr, top_windows)?;
                    }
                } else {
                    self.validate_noncompound_order_terms(
                        select,
                        top_windows,
                        outer_ctes.as_deref().unwrap_or_default(),
                    )?;
                }
                self.validate_core_after_order(&select.body.select, top_windows)?;
                return Ok(());
            }

            let mut right_width = None;
            for index in (0..=select.body.compounds.len()).rev() {
                let core = if index == 0 {
                    &select.body.select
                } else {
                    &select.body.compounds[index - 1].1
                };
                let windows = select_core_named_windows(core);
                self.validate_core_before_order(core, windows)?;
                self.validate_core_after_order(core, windows)?;

                let width = self
                    .connection
                    .compound_select_core_column_count_with_outer_ctes(
                        select,
                        core,
                        outer_ctes.as_deref().unwrap_or_default(),
                    );
                if !self.view_definition_mode
                    && let Some(right_width) = right_width
                    && width != right_width
                {
                    let (op, _) = &select.body.compounds[index];
                    return Err(FrankenError::ParseError {
                        offset: 0,
                        detail: format!(
                            "SELECTs to the left and right of {} do not have the same number of result columns",
                            compound_op_error_name(*op)
                        ),
                    });
                }
                right_width = Some(width);
            }

            if self.view_definition_mode {
                for term in &select.order_by {
                    self.validate_expr(&term.expr, top_windows)?;
                }
            } else {
                resolve_compound_order_output_indices(
                    self.connection,
                    select,
                    outer_ctes.as_deref().unwrap_or_default(),
                )?;
            }
            Ok(())
        })();
        self.scopes.truncate(scope_depth);
        self.semantic_depth = semantic_depth;
        result
    }

    fn validate_core_shape_before_limit(core: &SelectCore) -> Result<()> {
        if let SelectCore::Values(rows) = core
            && let Some(width) = rows.first().map(Vec::len)
            && rows.iter().any(|row| row.len() != width)
        {
            return Err(FrankenError::ParseError {
                offset: 0,
                detail: "all VALUES must have the same number of terms".to_owned(),
            });
        }
        Ok(())
    }

    fn validate_core_before_order(
        &mut self,
        core: &'a SelectCore,
        named_windows: &'a [fsqlite_ast::WindowDef],
    ) -> Result<()> {
        match core {
            SelectCore::Values(rows) => {
                if let Some(width) = rows.first().map(Vec::len)
                    && rows.iter().any(|row| row.len() != width)
                {
                    return Err(FrankenError::ParseError {
                        offset: 0,
                        detail: "all VALUES must have the same number of terms".to_owned(),
                    });
                }
                for row in rows.iter().rev() {
                    for expr in row {
                        self.validate_expr(expr, named_windows)?;
                    }
                }
            }
            SelectCore::Select {
                columns,
                from,
                where_clause,
                having,
                ..
            } => {
                if let Some(from) = from {
                    self.validate_from_sources(from)?;
                }
                for column in columns {
                    if let ResultColumn::Expr { expr, .. } = column {
                        self.validate_expr(expr, named_windows)?;
                    }
                }
                if let Some(predicate) = having {
                    self.validate_expr(predicate, named_windows)?;
                }
                if let Some(predicate) = where_clause {
                    self.validate_expr(predicate, named_windows)?;
                }
                if let Some(from) = from {
                    self.validate_join_on_expressions(from, named_windows)?;
                }
                if let Some(from) = from {
                    self.validate_table_function_args(from, named_windows)?;
                }
            }
        }
        Ok(())
    }

    fn validate_core_after_order(
        &mut self,
        core: &'a SelectCore,
        named_windows: &'a [fsqlite_ast::WindowDef],
    ) -> Result<()> {
        if let SelectCore::Select { group_by, .. } = core {
            for expr in group_by {
                self.validate_expr(expr, named_windows)?;
            }
            let named_specs = named_windows
                .iter()
                .map(|definition| (definition.name.to_ascii_uppercase(), &definition.spec))
                .collect::<Vec<_>>();
            validate_named_window_definitions(&named_specs)?;
        }
        Ok(())
    }

    fn validate_noncompound_order_terms(
        &mut self,
        select: &'a SelectStatement,
        named_windows: &'a [fsqlite_ast::WindowDef],
        outer_ctes: &[fsqlite_ast::Cte],
    ) -> Result<()> {
        let output_width =
            self.connection
                .select_result_column_count(select, outer_ctes, &mut Vec::new());
        let output_width_i64 = i64::try_from(output_width).unwrap_or(i64::MAX);

        let SelectCore::Select { columns, from, .. } = &select.body.select else {
            for (index, term) in select.order_by.iter().enumerate() {
                if self.order_term_records_ordinal(term, index, output_width)? {
                    continue;
                }
                self.validate_expr(&term.expr, named_windows)?;
            }
            self.validate_order_ordinal_ranges(select, output_width, output_width_i64)?;
            return Ok(());
        };

        let col_map = from.as_ref().map_or_else(Vec::new, |_| {
            self.connection
                .build_join_col_map_with_outer_ctes(select, outer_ctes)
        });
        let using_skip = from.as_ref().map(|_| {
            self.connection
                .build_join_using_skip_indices_with_outer_ctes(select, outer_ctes)
        });
        let using_skip = using_skip.as_ref().filter(|indices| !indices.is_empty());
        let output_aliases = collect_select_core_result_aliases(&select.body.select);

        // bd-2fong: SQLite rejects an aggregate in ORDER BY unless the SELECT
        // itself is an aggregate query ('misuse of aggregate: max()') — the
        // fromless lane already enforces this; the from-full lane silently
        // ordered by the aggregate's scalar value.
        let is_aggregate_query = match &select.body.select {
            SelectCore::Select {
                columns,
                group_by,
                having,
                ..
            } => {
                !group_by.is_empty()
                    || having.is_some()
                    || columns.iter().any(|column| match column {
                        ResultColumn::Expr { expr, .. } => {
                            self.connection.expr_contains_aggregate_with_registry(expr)
                        }
                        ResultColumn::Star | ResultColumn::TableStar(_) => false,
                    })
            }
            SelectCore::Values(_) => false,
        };
        if !is_aggregate_query {
            for term in &select.order_by {
                if self
                    .connection
                    .expr_contains_aggregate_with_registry(&term.expr)
                {
                    return Err(FrankenError::FunctionError(
                        "misuse of aggregate: ".to_owned(),
                    ));
                }
            }
        }

        for (index, term) in select.order_by.iter().enumerate() {
            if self.order_term_records_ordinal(term, index, output_width)? {
                continue;
            }
            if resolve_order_term_idx(&term.expr, columns).is_some() {
                continue;
            }
            self.validate_order_expr(
                &term.expr,
                named_windows,
                &col_map,
                using_skip,
                &output_aliases,
            )?;
        }
        self.validate_order_ordinal_ranges(select, output_width, output_width_i64)
    }

    fn order_term_records_ordinal(
        &self,
        term: &OrderingTerm,
        index: usize,
        output_width: usize,
    ) -> Result<bool> {
        let Some(ordinal) = connection_order_by_integer_ordinal(&term.expr) else {
            return Ok(false);
        };
        if ordinal <= 0 || ordinal > i64::from(u16::MAX) {
            return Err(FrankenError::FunctionError(format!(
                "{} ORDER BY term out of range - should be between 1 and {output_width}",
                sqlite_ordinal(index + 1)
            )));
        }
        Ok(true)
    }

    fn validate_order_ordinal_ranges(
        &self,
        select: &SelectStatement,
        output_width: usize,
        output_width_i64: i64,
    ) -> Result<()> {
        for (index, term) in select.order_by.iter().enumerate() {
            if let Some(ordinal) = connection_order_by_integer_ordinal(&term.expr)
                && (ordinal < 1 || ordinal > output_width_i64)
            {
                return Err(FrankenError::FunctionError(format!(
                    "{} ORDER BY term out of range - should be between 1 and {output_width}",
                    sqlite_ordinal(index + 1)
                )));
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn validate_order_expr(
        &mut self,
        expr: &'a Expr,
        named_windows: &'a [fsqlite_ast::WindowDef],
        col_map: &[(String, String, bool)],
        using_skip: Option<&HashSet<usize>>,
        output_aliases: &HashSet<String>,
    ) -> Result<()> {
        if expr_folds_to_integer_zero_via_and(expr) {
            return Ok(());
        }
        match expr {
            Expr::BoundOuterValue { .. }
            | Expr::Literal(_, _)
            | Expr::Raise { .. }
            | Expr::Placeholder(_, _) => Ok(()),
            Expr::Column(column, _) => {
                match validate_join_column_references(expr, col_map, using_skip, &[], &[]) {
                    Ok(()) => Ok(()),
                    Err(error @ FrankenError::AmbiguousColumn { .. }) => Err(error),
                    Err(FrankenError::Internal(detail))
                        if detail.starts_with("column not found: ")
                            && column.table.is_none()
                            && output_aliases.contains(&column.column.to_ascii_lowercase()) =>
                    {
                        Ok(())
                    }
                    Err(error) => Err(nested_order_column_error(error)),
                }
            }
            Expr::BinaryOp { left, right, .. }
            | Expr::JsonAccess {
                expr: left,
                path: right,
                ..
            } => {
                self.validate_order_expr(left, named_windows, col_map, using_skip, output_aliases)?;
                self.validate_order_expr(right, named_windows, col_map, using_skip, output_aliases)
            }
            Expr::UnaryOp { expr, .. }
            | Expr::IsNull { expr, .. }
            | Expr::Cast { expr, .. }
            | Expr::Collate { expr, .. } => {
                self.validate_order_expr(expr, named_windows, col_map, using_skip, output_aliases)
            }
            Expr::Between {
                expr, low, high, ..
            } => {
                self.validate_order_expr(expr, named_windows, col_map, using_skip, output_aliases)?;
                self.validate_order_expr(low, named_windows, col_map, using_skip, output_aliases)?;
                self.validate_order_expr(high, named_windows, col_map, using_skip, output_aliases)
            }
            Expr::In { expr, set, .. } => {
                if matches!(set, InSet::List(values) if values.is_empty()) {
                    return Ok(());
                }
                self.validate_order_expr(expr, named_windows, col_map, using_skip, output_aliases)?;
                match set {
                    InSet::List(values) => {
                        for value in values {
                            self.validate_order_expr(
                                value,
                                named_windows,
                                col_map,
                                using_skip,
                                output_aliases,
                            )?;
                        }
                        Ok(())
                    }
                    InSet::Subquery(query) => self.validate_select(query),
                    InSet::Table(name) => self.validate_relation(name),
                }
            }
            Expr::Like {
                expr,
                pattern,
                escape,
                ..
            } => {
                self.validate_order_expr(expr, named_windows, col_map, using_skip, output_aliases)?;
                self.validate_order_expr(
                    pattern,
                    named_windows,
                    col_map,
                    using_skip,
                    output_aliases,
                )?;
                if let Some(escape) = escape {
                    self.validate_order_expr(
                        escape,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
                Ok(())
            }
            Expr::Case {
                operand,
                whens,
                else_expr,
                ..
            } => {
                if let Some(operand) = operand {
                    self.validate_order_expr(
                        operand,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
                for (condition, value) in whens {
                    self.validate_order_expr(
                        condition,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                    self.validate_order_expr(
                        value,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
                if let Some(else_expr) = else_expr {
                    self.validate_order_expr(
                        else_expr,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
                Ok(())
            }
            Expr::Subquery(query, _) => self.validate_select(query),
            Expr::Exists { subquery, .. } => self.validate_select(subquery),
            Expr::FunctionCall {
                name,
                args,
                distinct,
                order_by,
                filter,
                over,
                ..
            } => {
                validate_function_call_header(
                    name,
                    args,
                    *distinct,
                    order_by,
                    filter.as_deref(),
                    over.as_ref(),
                )?;
                if let FunctionArgs::List(values) = args {
                    for value in values {
                        self.validate_order_expr(
                            value,
                            named_windows,
                            col_map,
                            using_skip,
                            output_aliases,
                        )?;
                    }
                }
                for term in order_by {
                    self.validate_order_expr(
                        &term.expr,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
                if let Some(filter) = filter {
                    self.validate_order_expr(
                        filter,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
                if let Some(window) = over {
                    self.validate_order_window(
                        window,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
                Ok(())
            }
            Expr::RowValue(values, _) => {
                for value in values {
                    self.validate_order_expr(
                        value,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
                Ok(())
            }
        }
    }

    fn validate_order_window(
        &mut self,
        window: &'a WindowSpec,
        named_windows: &'a [fsqlite_ast::WindowDef],
        col_map: &[(String, String, bool)],
        using_skip: Option<&HashSet<usize>>,
        output_aliases: &HashSet<String>,
    ) -> Result<()> {
        for definition in resolved_window_spec_chain(window, named_windows)? {
            self.validate_order_window_clauses(
                definition,
                named_windows,
                col_map,
                using_skip,
                output_aliases,
            )?;
        }
        self.validate_order_window_clauses(
            window,
            named_windows,
            col_map,
            using_skip,
            output_aliases,
        )
    }

    fn validate_order_window_clauses(
        &mut self,
        window: &'a WindowSpec,
        named_windows: &'a [fsqlite_ast::WindowDef],
        col_map: &[(String, String, bool)],
        using_skip: Option<&HashSet<usize>>,
        output_aliases: &HashSet<String>,
    ) -> Result<()> {
        for expr in &window.partition_by {
            self.validate_order_expr(expr, named_windows, col_map, using_skip, output_aliases)?;
        }
        for term in &window.order_by {
            self.validate_order_expr(
                &term.expr,
                named_windows,
                col_map,
                using_skip,
                output_aliases,
            )?;
        }
        if let Some(frame) = &window.frame {
            for bound in std::iter::once(&frame.start).chain(frame.end.as_ref()) {
                if let FrameBound::Preceding(expr) | FrameBound::Following(expr) = bound {
                    self.validate_order_expr(
                        expr,
                        named_windows,
                        col_map,
                        using_skip,
                        output_aliases,
                    )?;
                }
            }
        }
        Ok(())
    }

    fn validate_from_sources(&mut self, from: &'a FromClause) -> Result<()> {
        self.validate_source(&from.source)?;
        for join in &from.joins {
            self.validate_source(&join.table)?;
        }
        Ok(())
    }

    fn validate_join_on_expressions(
        &mut self,
        from: &'a FromClause,
        named_windows: &'a [fsqlite_ast::WindowDef],
    ) -> Result<()> {
        if let TableOrSubquery::ParenJoin(nested) = &from.source {
            self.validate_join_on_expressions(nested, named_windows)?;
        }
        for join in &from.joins {
            if let TableOrSubquery::ParenJoin(nested) = &join.table {
                self.validate_join_on_expressions(nested, named_windows)?;
            }
            if let Some(JoinConstraint::On(expr)) = &join.constraint {
                self.validate_expr(expr, named_windows)?;
            }
        }
        Ok(())
    }

    fn validate_source(&mut self, source: &'a TableOrSubquery) -> Result<()> {
        match source {
            TableOrSubquery::Table { name, .. } => self.validate_relation(name),
            TableOrSubquery::Subquery { query, .. } => self.validate_select(query),
            TableOrSubquery::TableFunction { .. } => Ok(()),
            TableOrSubquery::ParenJoin(from) => self.validate_from_sources(from),
        }
    }

    fn validate_table_function_args(
        &mut self,
        from: &'a FromClause,
        named_windows: &'a [fsqlite_ast::WindowDef],
    ) -> Result<()> {
        self.validate_source_table_function_args(&from.source, named_windows)?;
        for join in &from.joins {
            self.validate_source_table_function_args(&join.table, named_windows)?;
        }
        Ok(())
    }

    fn validate_source_table_function_args(
        &mut self,
        source: &'a TableOrSubquery,
        named_windows: &'a [fsqlite_ast::WindowDef],
    ) -> Result<()> {
        match source {
            TableOrSubquery::TableFunction { args, .. } => {
                for arg in args {
                    self.validate_expr(arg, named_windows)?;
                }
                Ok(())
            }
            TableOrSubquery::ParenJoin(from) => {
                self.validate_table_function_args(from, named_windows)
            }
            TableOrSubquery::Table { .. } | TableOrSubquery::Subquery { .. } => Ok(()),
        }
    }

    #[allow(clippy::too_many_lines)]
    fn validate_expr(
        &mut self,
        expr: &'a Expr,
        named_windows: &'a [fsqlite_ast::WindowDef],
    ) -> Result<()> {
        if expr_folds_to_integer_zero_via_and(expr) {
            return Ok(());
        }
        match expr {
            Expr::BoundOuterValue { .. }
            | Expr::Literal(_, _)
            | Expr::Column(_, _)
            | Expr::Raise { .. }
            | Expr::Placeholder(_, _) => Ok(()),
            Expr::BinaryOp { left, right, .. }
            | Expr::JsonAccess {
                expr: left,
                path: right,
                ..
            } => {
                self.validate_expr(left, named_windows)?;
                self.validate_expr(right, named_windows)
            }
            Expr::UnaryOp { expr, .. }
            | Expr::IsNull { expr, .. }
            | Expr::Cast { expr, .. }
            | Expr::Collate { expr, .. } => self.validate_expr(expr, named_windows),
            Expr::Between {
                expr, low, high, ..
            } => {
                self.validate_expr(expr, named_windows)?;
                self.validate_expr(low, named_windows)?;
                self.validate_expr(high, named_windows)
            }
            Expr::In { expr, set, .. } => {
                if matches!(set, InSet::List(values) if values.is_empty()) {
                    return Ok(());
                }
                if let InSet::List(values) = set {
                    self.connection
                        .validate_in_list_early_row_misuse(expr, values)?;
                }
                self.validate_expr(expr, named_windows)?;
                let singleton_subquery = match set {
                    InSet::List(values) => match values.as_slice() {
                        [Expr::Subquery(query, _)] => Some(query.as_ref()),
                        _ => None,
                    },
                    InSet::Subquery(query) => Some(query.as_ref()),
                    InSet::Table(_) => None,
                };
                if let Some(query) = singleton_subquery {
                    self.validate_select(query)?;
                    if !is_correlated_subquery_with_schema(query, &self.connection.schema.borrow())
                    {
                        self.connection
                            .validate_in_subquery_column_count(expr, query)?;
                    }
                } else {
                    match set {
                        InSet::List(values) => {
                            for value in values {
                                self.validate_expr(value, named_windows)?;
                            }
                        }
                        InSet::Subquery(_) => {
                            unreachable!("subquery IN sets are handled above")
                        }
                        InSet::Table(name) => self.validate_relation(name)?,
                    }
                }
                match set {
                    InSet::List(values) if singleton_subquery.is_none() => {
                        self.connection.validate_in_list_lhs_shape(expr, values)?;
                    }
                    InSet::List(_) | InSet::Subquery(_) | InSet::Table(_) => {}
                }
                Ok(())
            }
            Expr::Like {
                expr,
                pattern,
                escape,
                ..
            } => {
                self.validate_expr(expr, named_windows)?;
                self.validate_expr(pattern, named_windows)?;
                if let Some(escape) = escape {
                    self.validate_expr(escape, named_windows)?;
                }
                Ok(())
            }
            Expr::Case {
                operand,
                whens,
                else_expr,
                ..
            } => {
                if let Some(operand) = operand {
                    self.validate_expr(operand, named_windows)?;
                }
                for (condition, value) in whens {
                    self.validate_expr(condition, named_windows)?;
                    self.validate_expr(value, named_windows)?;
                }
                if let Some(else_expr) = else_expr {
                    self.validate_expr(else_expr, named_windows)?;
                }
                Ok(())
            }
            Expr::Subquery(query, _) => self.validate_select(query),
            Expr::Exists { subquery, .. } => self.validate_select(subquery),
            Expr::FunctionCall {
                name,
                args,
                distinct,
                order_by,
                filter,
                over,
                ..
            } => {
                validate_function_call_header(
                    name,
                    args,
                    *distinct,
                    order_by,
                    filter.as_deref(),
                    over.as_ref(),
                )?;
                if let FunctionArgs::List(values) = args {
                    for value in values {
                        self.validate_expr(value, named_windows)?;
                    }
                }
                for term in order_by {
                    self.validate_expr(&term.expr, named_windows)?;
                }
                if let Some(filter) = filter {
                    self.validate_expr(filter, named_windows)?;
                }
                if let Some(window) = over {
                    self.validate_window(window, named_windows)?;
                }
                Ok(())
            }
            Expr::RowValue(values, _) => {
                for value in values {
                    self.validate_expr(value, named_windows)?;
                }
                Ok(())
            }
        }
    }

    fn validate_window(
        &mut self,
        window: &'a WindowSpec,
        named_windows: &'a [fsqlite_ast::WindowDef],
    ) -> Result<()> {
        for definition in resolved_window_spec_chain(window, named_windows)? {
            self.validate_window_clauses(definition, named_windows)?;
        }
        self.validate_window_clauses(window, named_windows)
    }

    fn validate_window_clauses(
        &mut self,
        window: &'a WindowSpec,
        named_windows: &'a [fsqlite_ast::WindowDef],
    ) -> Result<()> {
        for expr in &window.partition_by {
            self.validate_expr(expr, named_windows)?;
        }
        for term in &window.order_by {
            self.validate_expr(&term.expr, named_windows)?;
        }
        Ok(())
    }

    fn visible_cte(&self, name: &QualifiedName) -> Option<(usize, &'a fsqlite_ast::Cte)> {
        if name.schema.is_some() {
            return None;
        }
        self.scopes
            .iter()
            .enumerate()
            .rev()
            .find_map(|(scope_index, scope)| {
                scope
                    .iter()
                    .find(|cte| cte.name.eq_ignore_ascii_case(&name.name))
                    .map(|cte| (scope_index, cte))
            })
    }

    fn visible_ctes(&self) -> Vec<fsqlite_ast::Cte> {
        self.scopes
            .iter()
            .flat_map(|scope| scope.iter().cloned())
            .collect()
    }

    fn validate_relation(&mut self, name: &QualifiedName) -> Result<()> {
        let Some((scope_index, cte)) = self.visible_cte(name) else {
            return Ok(());
        };
        let hidden_reference_scopes = self.scopes.split_off(scope_index + 1);
        let result = self.validate_cte(cte);
        self.scopes.extend(hidden_reference_scopes);
        result
    }

    fn validate_cte(&mut self, cte: &'a fsqlite_ast::Cte) -> Result<()> {
        let key = std::ptr::from_ref(cte);
        if matches!(
            self.visits.get(&key),
            Some(CteCollationVisit::Active | CteCollationVisit::Done)
        ) {
            return Ok(());
        }
        self.visits.insert(key, CteCollationVisit::Active);
        self.validate_select(&cte.query)?;
        if !self.view_definition_mode && !cte.columns.is_empty() {
            let value_count = self.connection.select_result_column_count(
                &cte.query,
                &self.visible_ctes(),
                &mut Vec::new(),
            );
            if value_count != cte.columns.len() {
                return Err(FrankenError::FunctionError(format!(
                    "table {} has {value_count} values for {} columns",
                    cte.name,
                    cte.columns.len()
                )));
            }
        }
        self.visits.insert(key, CteCollationVisit::Done);
        Ok(())
    }
}

fn select_core_named_windows(core: &SelectCore) -> &[fsqlite_ast::WindowDef] {
    match core {
        SelectCore::Select { windows, .. } => windows,
        SelectCore::Values(_) => &[],
    }
}

struct CteCollationResolver<'a, 'r> {
    connection: &'a Connection,
    registry: &'r CollationRegistry,
    scopes: Vec<&'a [fsqlite_ast::Cte]>,
    visits: HashMap<*const fsqlite_ast::Cte, CteCollationVisit>,
}

impl<'a, 'r> CteCollationResolver<'a, 'r> {
    fn new(connection: &'a Connection, registry: &'r CollationRegistry) -> Self {
        Self {
            connection,
            registry,
            scopes: Vec::new(),
            visits: HashMap::new(),
        }
    }

    fn validate_select(&mut self, select: &'a SelectStatement) -> Result<()> {
        let scope_depth = self.scopes.len();
        if let Some(with) = &select.with {
            self.scopes.push(&with.ctes);
        }
        let result = (|| {
            self.validate_core(&select.body.select)?;
            for (_, core) in &select.body.compounds {
                self.validate_core(core)?;
            }
            for term in &select.order_by {
                self.validate_expr(&term.expr)?;
            }
            if let Some(limit) = &select.limit {
                self.validate_expr(&limit.limit)?;
                if let Some(offset) = &limit.offset {
                    self.validate_expr(offset)?;
                }
            }
            Ok(())
        })();
        self.scopes.truncate(scope_depth);
        result
    }

    fn validate_core(&mut self, core: &'a SelectCore) -> Result<()> {
        match core {
            SelectCore::Values(rows) => {
                for expr in rows.iter().flatten() {
                    self.validate_expr(expr)?;
                }
            }
            SelectCore::Select {
                columns,
                from,
                where_clause,
                group_by,
                having,
                windows,
                ..
            } => {
                if let Some(from) = from {
                    self.validate_from(from)?;
                }
                for column in columns {
                    if let ResultColumn::Expr { expr, .. } = column {
                        self.validate_expr(expr)?;
                    }
                }
                if let Some(predicate) = where_clause {
                    self.validate_expr(predicate)?;
                }
                for expr in group_by {
                    self.validate_expr(expr)?;
                }
                if let Some(predicate) = having {
                    self.validate_expr(predicate)?;
                }
                for window in windows {
                    self.validate_window(&window.spec)?;
                }
            }
        }
        Ok(())
    }

    fn validate_from(&mut self, from: &'a FromClause) -> Result<()> {
        for join in from.joins.iter().rev() {
            self.validate_source(&join.table)?;
        }
        self.validate_source(&from.source)?;
        for join in &from.joins {
            if let Some(JoinConstraint::On(expr)) = &join.constraint {
                self.validate_expr(expr)?;
            }
        }
        Ok(())
    }

    fn validate_source(&mut self, source: &'a TableOrSubquery) -> Result<()> {
        match source {
            TableOrSubquery::Table { name, .. } => self.validate_relation(name),
            TableOrSubquery::Subquery { query, .. } => {
                validate_select_result_collation_metadata(self.connection, query, self.registry)?;
                self.validate_select(query)?;
                validate_select_collation_consumers_body(
                    self.connection,
                    query,
                    SubqueryCollationUse::Scalar,
                    self.registry,
                )
            }
            TableOrSubquery::TableFunction { args, .. } => {
                for arg in args {
                    self.validate_expr(arg)?;
                }
                Ok(())
            }
            TableOrSubquery::ParenJoin(from) => self.validate_from(from),
        }
    }

    fn validate_expr(&mut self, expr: &'a Expr) -> Result<()> {
        if expr_folds_to_integer_zero_via_and(expr) {
            return Ok(());
        }
        match expr {
            Expr::BoundOuterValue { .. }
            | Expr::Literal(_, _)
            | Expr::Column(_, _)
            | Expr::Raise { .. }
            | Expr::Placeholder(_, _) => Ok(()),
            Expr::BinaryOp { left, right, .. }
            | Expr::JsonAccess {
                expr: left,
                path: right,
                ..
            } => {
                self.validate_expr(left)?;
                self.validate_expr(right)
            }
            Expr::UnaryOp { expr, .. }
            | Expr::IsNull { expr, .. }
            | Expr::Cast { expr, .. }
            | Expr::Collate { expr, .. } => self.validate_expr(expr),
            Expr::Between {
                expr, low, high, ..
            } => {
                self.validate_expr(expr)?;
                self.validate_expr(low)?;
                self.validate_expr(high)
            }
            Expr::In { expr, set, .. } => {
                if matches!(set, InSet::List(values) if values.is_empty()) {
                    return Ok(());
                }
                self.validate_expr(expr)?;
                match set {
                    InSet::List(values) => {
                        for value in values {
                            self.validate_expr(value)?;
                        }
                        Ok(())
                    }
                    InSet::Subquery(query) => {
                        self.validate_select(query)?;
                        validate_select_collation_consumers_body(
                            self.connection,
                            query,
                            SubqueryCollationUse::InRhs,
                            self.registry,
                        )?;
                        Ok(())
                    }
                    InSet::Table(name) => self.validate_relation(name),
                }
            }
            Expr::Like {
                expr,
                pattern,
                escape,
                ..
            } => {
                self.validate_expr(expr)?;
                self.validate_expr(pattern)?;
                if let Some(escape) = escape {
                    self.validate_expr(escape)?;
                }
                Ok(())
            }
            Expr::Case {
                operand,
                whens,
                else_expr,
                ..
            } => {
                if let Some(operand) = operand {
                    self.validate_expr(operand)?;
                }
                for (condition, value) in whens {
                    self.validate_expr(condition)?;
                    self.validate_expr(value)?;
                }
                if let Some(else_expr) = else_expr {
                    self.validate_expr(else_expr)?;
                }
                Ok(())
            }
            Expr::Subquery(query, _) => {
                self.validate_select(query)?;
                validate_select_collation_consumers_body(
                    self.connection,
                    query,
                    SubqueryCollationUse::Scalar,
                    self.registry,
                )?;
                Ok(())
            }
            Expr::Exists { subquery, .. } => {
                self.validate_select(subquery)?;
                validate_select_collation_consumers_body(
                    self.connection,
                    subquery,
                    SubqueryCollationUse::Exists,
                    self.registry,
                )?;
                Ok(())
            }
            Expr::FunctionCall {
                args,
                order_by,
                filter,
                over,
                ..
            } => {
                if let FunctionArgs::List(values) = args {
                    for value in values {
                        self.validate_expr(value)?;
                    }
                }
                for term in order_by {
                    self.validate_expr(&term.expr)?;
                }
                if let Some(filter) = filter {
                    self.validate_expr(filter)?;
                }
                if let Some(window) = over {
                    self.validate_window(window)?;
                }
                Ok(())
            }
            Expr::RowValue(values, _) => {
                for value in values {
                    self.validate_expr(value)?;
                }
                Ok(())
            }
        }
    }

    fn validate_window(&mut self, window: &'a WindowSpec) -> Result<()> {
        for expr in &window.partition_by {
            self.validate_expr(expr)?;
        }
        for term in &window.order_by {
            self.validate_expr(&term.expr)?;
        }
        if let Some(frame) = &window.frame {
            self.validate_frame_bound(&frame.start)?;
            if let Some(end) = &frame.end {
                self.validate_frame_bound(end)?;
            }
        }
        Ok(())
    }

    fn validate_frame_bound(&mut self, bound: &'a FrameBound) -> Result<()> {
        match bound {
            FrameBound::Preceding(expr) | FrameBound::Following(expr) => self.validate_expr(expr),
            FrameBound::UnboundedPreceding
            | FrameBound::CurrentRow
            | FrameBound::UnboundedFollowing => Ok(()),
        }
    }

    fn visible_cte(&self, name: &QualifiedName) -> Option<(usize, &'a fsqlite_ast::Cte)> {
        if name.schema.is_some() {
            return None;
        }
        self.scopes
            .iter()
            .enumerate()
            .rev()
            .find_map(|(scope_index, scope)| {
                scope
                    .iter()
                    .find(|cte| cte.name.eq_ignore_ascii_case(&name.name))
                    .map(|cte| (scope_index, cte))
            })
    }

    fn validate_relation(&mut self, name: &QualifiedName) -> Result<()> {
        let Some((scope_index, cte)) = self.visible_cte(name) else {
            return Ok(());
        };
        // A CTE body is resolved in the lexical environment where that CTE
        // was defined, not in any deeper scope from the reference site.
        // Temporarily hide those deeper scopes so an inner same-named CTE
        // cannot capture an outer definition's dependency.
        let hidden_reference_scopes = self.scopes.split_off(scope_index + 1);
        let result = self.validate_cte(cte);
        self.scopes.extend(hidden_reference_scopes);
        result
    }

    fn validate_cte(&mut self, cte: &'a fsqlite_ast::Cte) -> Result<()> {
        let key = std::ptr::from_ref(cte);
        if matches!(
            self.visits.get(&key),
            Some(CteCollationVisit::Active | CteCollationVisit::Done)
        ) {
            return Ok(());
        }
        self.visits.insert(key, CteCollationVisit::Active);
        validate_select_result_collation_metadata(self.connection, &cte.query, self.registry)?;
        self.validate_select(&cte.query)?;
        validate_select_collation_consumers_body(
            self.connection,
            &cte.query,
            SubqueryCollationUse::Scalar,
            self.registry,
        )?;
        self.visits.insert(key, CteCollationVisit::Done);
        Ok(())
    }
}

fn validate_select_collation_consumers(
    connection: &Connection,
    select: &SelectStatement,
    use_kind: SubqueryCollationUse,
    registry: &CollationRegistry,
) -> Result<()> {
    let mut resolver = CteCollationResolver::new(connection, registry);
    resolver.validate_select(select)?;
    validate_select_collation_consumers_body(connection, select, use_kind, registry)
}

fn validate_select_collation_consumers_body(
    connection: &Connection,
    select: &SelectStatement,
    use_kind: SubqueryCollationUse,
    registry: &CollationRegistry,
) -> Result<()> {
    validate_select_core_collation_boundaries(connection, &select.body.select, use_kind, registry)?;
    for (_, core) in &select.body.compounds {
        validate_select_core_collation_boundaries(connection, core, use_kind, registry)?;
    }
    validate_compound_set_collations(connection, select, registry)?;

    let compound_order_validated = !select.body.compounds.is_empty()
        && matches!(
            use_kind,
            SubqueryCollationUse::Scalar | SubqueryCollationUse::InRhs
        );
    if compound_order_validated {
        validate_compound_order_collations(connection, select, registry)?;
    }

    match (&select.body.select, use_kind) {
        (
            SelectCore::Select {
                columns,
                from,
                windows,
                ..
            },
            SubqueryCollationUse::Scalar | SubqueryCollationUse::InRhs,
        ) if !compound_order_validated => {
            let named_windows = windows
                .iter()
                .map(|window| (window.name.to_ascii_uppercase(), &window.spec))
                .collect::<Vec<_>>();
            for term in select.order_by.iter().rev() {
                let resolved_expr;
                let expr = if from.is_none() {
                    resolved_expr = connection
                        .resolve_fromless_aliases(&term.expr, columns, false, "ORDER BY")?;
                    &resolved_expr
                } else {
                    select_order_collation_expr(&term.expr, columns)
                };
                validate_expr_collation_boundary(connection, expr, registry)?;
                validate_used_window_collation_boundaries(
                    connection,
                    expr,
                    &named_windows,
                    registry,
                )?;
            }
        }
        (SelectCore::Values(_), SubqueryCollationUse::Scalar | SubqueryCollationUse::InRhs)
            if !compound_order_validated =>
        {
            for term in select.order_by.iter().rev() {
                validate_expr_collation_boundary(connection, &term.expr, registry)?;
                validate_used_window_collation_boundaries(connection, &term.expr, &[], registry)?;
            }
        }
        (SelectCore::Select { windows, .. }, SubqueryCollationUse::Exists) => {
            let named_windows = windows
                .iter()
                .map(|window| (window.name.to_ascii_uppercase(), &window.spec))
                .collect::<Vec<_>>();
            for term in &select.order_by {
                validate_used_window_collation_boundaries(
                    connection,
                    &term.expr,
                    &named_windows,
                    registry,
                )?;
            }
        }
        (SelectCore::Values(_), SubqueryCollationUse::Exists) => {
            for term in &select.order_by {
                validate_used_window_collation_boundaries(connection, &term.expr, &[], registry)?;
            }
        }
        (
            SelectCore::Select { .. } | SelectCore::Values(_),
            SubqueryCollationUse::Scalar | SubqueryCollationUse::InRhs,
        ) => {}
    }
    validate_select_core_collation_consumers(connection, &select.body.select, use_kind, registry)?;
    for (_, core) in &select.body.compounds {
        validate_select_core_collation_consumers(connection, core, use_kind, registry)?;
    }
    if let Some(limit) = &select.limit {
        validate_expr_collation_consumers(connection, &limit.limit, registry)?;
        if let Some(offset) = &limit.offset {
            validate_expr_collation_consumers(connection, offset, registry)?;
        }
    }
    Ok(())
}

fn validate_select_core_collation_boundaries(
    connection: &Connection,
    core: &SelectCore,
    use_kind: SubqueryCollationUse,
    registry: &CollationRegistry,
) -> Result<()> {
    match core {
        SelectCore::Values(rows) => {
            if use_kind == SubqueryCollationUse::Exists {
                for expr in rows.iter().flatten() {
                    validate_exists_projection_collation_machinery(
                        connection,
                        expr,
                        &[],
                        registry,
                    )?;
                }
            }
            Ok(())
        }
        SelectCore::Select {
            distinct,
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
        } => {
            let named_windows = windows
                .iter()
                .map(|window| (window.name.to_ascii_uppercase(), &window.spec))
                .collect::<Vec<_>>();

            if let Some(from) = from {
                validate_from_clause_collation_consumers(connection, from, registry)?;
            }
            for expr in group_by.iter().rev() {
                let resolved_expr;
                let expr = if from.is_none() {
                    resolved_expr =
                        connection.resolve_fromless_group_expr_with_aliases(expr, columns)?;
                    &resolved_expr
                } else {
                    expr
                };
                validate_used_window_collation_boundaries(
                    connection,
                    expr,
                    &named_windows,
                    registry,
                )?;
                validate_expr_collation_boundary(connection, expr, registry)?;
            }
            if let Some(predicate) = where_clause {
                validate_used_window_collation_boundaries(
                    connection,
                    predicate,
                    &named_windows,
                    registry,
                )?;
            }
            if use_kind == SubqueryCollationUse::Exists {
                for column in columns {
                    if let ResultColumn::Expr { expr, .. } = column {
                        validate_exists_projection_collation_machinery(
                            connection,
                            expr,
                            &named_windows,
                            registry,
                        )?;
                    }
                }
            } else if *distinct == Distinctness::Distinct {
                for column in columns.iter().rev() {
                    if let ResultColumn::Expr { expr, .. } = column {
                        validate_expr_collation_winner(expr, registry)?;
                        validate_used_window_collation_boundaries(
                            connection,
                            expr,
                            &named_windows,
                            registry,
                        )?;
                    }
                }
            }
            if let Some(predicate) = having {
                validate_used_window_collation_boundaries(
                    connection,
                    predicate,
                    &named_windows,
                    registry,
                )?;
            }
            Ok(())
        }
    }
}

fn validate_exists_projection_collation_machinery(
    connection: &Connection,
    expr: &Expr,
    named_windows: &NamedWindowSpecs<'_>,
    registry: &CollationRegistry,
) -> Result<()> {
    validate_used_window_collation_boundaries(connection, expr, named_windows, registry)?;
    validate_exists_projection_aggregate_collations(connection, expr, registry)
}

#[allow(clippy::too_many_lines)]
fn validate_exists_projection_aggregate_collations(
    connection: &Connection,
    expr: &Expr,
    registry: &CollationRegistry,
) -> Result<()> {
    if expr_folds_to_integer_zero_via_and(expr) {
        return Ok(());
    }
    match expr {
        Expr::FunctionCall {
            name,
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            let is_aggregate = over.is_none()
                && is_current_aggregate_or_json_fn(name, args)
                && !is_scalar_max_min(name, args);
            if is_aggregate {
                return validate_expr_collation_consumers(connection, expr, registry);
            }
            if let FunctionArgs::List(values) = args {
                for value in values {
                    validate_exists_projection_aggregate_collations(connection, value, registry)?;
                }
            }
            for term in order_by {
                validate_exists_projection_aggregate_collations(connection, &term.expr, registry)?;
            }
            if let Some(filter) = filter {
                validate_exists_projection_aggregate_collations(connection, filter, registry)?;
            }
            Ok(())
        }
        Expr::BinaryOp { left, right, .. }
        | Expr::JsonAccess {
            expr: left,
            path: right,
            ..
        } => {
            validate_exists_projection_aggregate_collations(connection, left, registry)?;
            validate_exists_projection_aggregate_collations(connection, right, registry)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            validate_exists_projection_aggregate_collations(connection, expr, registry)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            validate_exists_projection_aggregate_collations(connection, expr, registry)?;
            validate_exists_projection_aggregate_collations(connection, low, registry)?;
            validate_exists_projection_aggregate_collations(connection, high, registry)
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return Ok(());
            }
            validate_exists_projection_aggregate_collations(connection, expr, registry)?;
            if let InSet::List(values) = set {
                for value in values {
                    validate_exists_projection_aggregate_collations(connection, value, registry)?;
                }
            }
            Ok(())
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            validate_exists_projection_aggregate_collations(connection, pattern, registry)?;
            validate_exists_projection_aggregate_collations(connection, expr, registry)?;
            if let Some(escape) = escape {
                validate_exists_projection_aggregate_collations(connection, escape, registry)?;
            }
            Ok(())
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                validate_exists_projection_aggregate_collations(connection, operand, registry)?;
            }
            for (condition, value) in whens {
                validate_exists_projection_aggregate_collations(connection, condition, registry)?;
                validate_exists_projection_aggregate_collations(connection, value, registry)?;
            }
            if let Some(else_expr) = else_expr {
                validate_exists_projection_aggregate_collations(connection, else_expr, registry)?;
            }
            Ok(())
        }
        Expr::RowValue(values, _) => {
            for value in values {
                validate_exists_projection_aggregate_collations(connection, value, registry)?;
            }
            Ok(())
        }
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _)
        | Expr::Subquery(_, _)
        | Expr::Exists { .. } => Ok(()),
    }
}

fn validate_select_core_collation_consumers(
    connection: &Connection,
    core: &SelectCore,
    use_kind: SubqueryCollationUse,
    registry: &CollationRegistry,
) -> Result<()> {
    match core {
        SelectCore::Values(rows) => {
            if use_kind != SubqueryCollationUse::Exists {
                for expr in rows.iter().flatten() {
                    validate_used_window_collation_boundaries(connection, expr, &[], registry)?;
                    validate_expr_collation_consumers(connection, expr, registry)?;
                }
                if rows.len() > 1
                    && let Some(first_row) = rows.first()
                {
                    for expr in first_row.iter().rev() {
                        validate_expr_collation_winner(expr, registry)?;
                    }
                }
            }
            Ok(())
        }
        SelectCore::Select {
            distinct,
            columns,
            where_clause,
            having,
            windows,
            ..
        } => {
            if use_kind != SubqueryCollationUse::Exists && *distinct != Distinctness::Distinct {
                let named_windows = windows
                    .iter()
                    .map(|window| (window.name.to_ascii_uppercase(), &window.spec))
                    .collect::<Vec<_>>();
                for column in columns {
                    if let ResultColumn::Expr { expr, .. } = column {
                        validate_used_window_collation_boundaries(
                            connection,
                            expr,
                            &named_windows,
                            registry,
                        )?;
                    }
                }
            }
            if let Some(predicate) = where_clause {
                validate_expr_collation_consumers(connection, predicate, registry)?;
            }
            if use_kind != SubqueryCollationUse::Exists {
                for column in columns {
                    if let ResultColumn::Expr { expr, .. } = column {
                        validate_expr_collation_consumers(connection, expr, registry)?;
                    }
                }
            }
            if let Some(predicate) = having {
                validate_expr_collation_consumers(connection, predicate, registry)?;
            }
            Ok(())
        }
    }
}

fn validate_from_clause_collation_consumers(
    connection: &Connection,
    from: &FromClause,
    registry: &CollationRegistry,
) -> Result<()> {
    for join in from.joins.iter().rev() {
        validate_table_or_subquery_collation_consumers(connection, &join.table, registry)?;
    }
    validate_table_or_subquery_collation_consumers(connection, &from.source, registry)?;
    for join in &from.joins {
        if let Some(JoinConstraint::On(expr)) = &join.constraint {
            validate_expr_collation_consumers(connection, expr, registry)?;
        }
    }
    Ok(())
}

fn validate_table_or_subquery_collation_consumers(
    connection: &Connection,
    source: &TableOrSubquery,
    registry: &CollationRegistry,
) -> Result<()> {
    match source {
        TableOrSubquery::Table { .. } => Ok(()),
        TableOrSubquery::Subquery { query, .. } => {
            validate_select_result_collation_metadata(connection, query, registry)?;
            validate_select_collation_consumers(
                connection,
                query,
                SubqueryCollationUse::Scalar,
                registry,
            )
        }
        TableOrSubquery::TableFunction { args, .. } => {
            for arg in args {
                validate_expr_collation_consumers(connection, arg, registry)?;
            }
            Ok(())
        }
        TableOrSubquery::ParenJoin(from) => {
            validate_from_clause_collation_consumers(connection, from, registry)
        }
    }
}

fn validate_select_result_collation_metadata(
    connection: &Connection,
    select: &SelectStatement,
    registry: &CollationRegistry,
) -> Result<()> {
    if let SelectCore::Values(rows) = &select.body.select {
        if let Some(first_row) = rows.first() {
            for expr in first_row.iter().rev() {
                validate_expr_collation_winner(expr, registry)?;
            }
        }
        return Ok(());
    }

    let schemas = connection.schema.borrow();
    let collations = select_result_collations(select, &schemas);
    drop(schemas);
    for collation in collations.iter().rev().flatten() {
        validate_registered_collation(collation, registry)?;
    }
    Ok(())
}

fn validate_compound_set_collations(
    connection: &Connection,
    select: &SelectStatement,
    registry: &CollationRegistry,
) -> Result<()> {
    if !select
        .body
        .compounds
        .iter()
        .any(|(op, _)| *op != CompoundOp::UnionAll)
    {
        return Ok(());
    }

    let mut cores = Vec::with_capacity(select.body.compounds.len() + 1);
    cores.push(&select.body.select);
    cores.extend(select.body.compounds.iter().map(|(_, core)| core));
    let schemas = connection.schema.borrow();
    let candidate_rows = cores
        .iter()
        .map(|core| select_core_result_collation_candidates(core, &schemas))
        .collect::<Vec<_>>();
    drop(schemas);
    let Some(width) = candidate_rows.iter().map(Vec::len).max() else {
        return Ok(());
    };
    for index in (0..width).rev() {
        let _ = resolve_compound_column_collation_candidate(&candidate_rows, index, registry)?;
    }
    Ok(())
}

fn validate_compound_order_collations(
    connection: &Connection,
    select: &SelectStatement,
    registry: &CollationRegistry,
) -> Result<()> {
    let resolved_indices = resolve_compound_order_output_indices(connection, select, &[])?;
    let mut cores = Vec::with_capacity(select.body.compounds.len() + 1);
    cores.push(&select.body.select);
    cores.extend(select.body.compounds.iter().map(|(_, core)| core));

    let schemas = connection.schema.borrow();
    let candidate_rows = cores
        .iter()
        .map(|core| select_core_result_collation_candidates(core, &schemas))
        .collect::<Vec<_>>();
    drop(schemas);

    let named_windows = match &select.body.select {
        SelectCore::Select { windows, .. } => windows
            .iter()
            .map(|window| (window.name.to_ascii_uppercase(), &window.spec))
            .collect::<Vec<_>>(),
        SelectCore::Values(_) => Vec::new(),
    };
    for (term, index) in select.order_by.iter().zip(resolved_indices).rev() {
        if matches!(&term.expr, Expr::Collate { .. }) {
            validate_expr_collation_boundary(connection, &term.expr, registry)?;
        } else {
            let _ = resolve_compound_column_collation_candidate(&candidate_rows, index, registry)?;
        }
        validate_used_window_collation_boundaries(
            connection,
            &term.expr,
            &named_windows,
            registry,
        )?;
    }
    Ok(())
}

fn resolve_compound_column_collation_candidate(
    candidate_rows: &[Vec<CollationCandidate>],
    index: usize,
    registry: &CollationRegistry,
) -> Result<Option<String>> {
    for candidate in candidate_rows
        .iter()
        .filter_map(|candidates| candidates.get(index))
    {
        let CollationCandidate::Named(collation) = candidate else {
            continue;
        };
        if !collation.eq_ignore_ascii_case("BINARY") {
            validate_registered_collation(collation, registry)?;
            return Ok(Some(collation.clone()));
        }
        return Ok(None);
    }
    Ok(None)
}

fn select_core_result_exprs(core: &SelectCore) -> Option<Vec<&Expr>> {
    match core {
        SelectCore::Values(rows) => Some(rows.first()?.iter().collect()),
        SelectCore::Select { columns, .. } => columns
            .iter()
            .map(|column| match column {
                ResultColumn::Expr { expr, .. } => Some(expr),
                ResultColumn::Star | ResultColumn::TableStar(_) => None,
            })
            .collect(),
    }
}

fn select_order_collation_expr<'a>(order_expr: &'a Expr, columns: &'a [ResultColumn]) -> &'a Expr {
    if matches!(order_expr, Expr::Collate { .. }) {
        return order_expr;
    }
    resolve_order_term_idx(order_expr, columns)
        .and_then(|index| columns.get(index))
        .and_then(|column| match column {
            ResultColumn::Expr { expr, .. } => Some(expr),
            ResultColumn::Star | ResultColumn::TableStar(_) => None,
        })
        .unwrap_or(order_expr)
}

fn validate_used_window_collation_boundaries(
    connection: &Connection,
    expr: &Expr,
    visible_windows: &NamedWindowSpecs<'_>,
    registry: &CollationRegistry,
) -> Result<()> {
    if expr_folds_to_integer_zero_via_and(expr) {
        return Ok(());
    }
    let mut remaining = expr.clone();
    while expr_has_window_function(&remaining) {
        let ExtractedWindowFunction {
            name: _,
            args,
            call_order_by,
            window,
            filter,
        } = extract_inner_window_function(&remaining).ok_or_else(|| {
            FrankenError::Internal(
                "window collation validation could not expose a window call".to_owned(),
            )
        })?;
        let resolved = resolve_used_window_spec(&window, visible_windows)?;
        if let Some(filter) = &filter {
            validate_expr_collation_boundary(connection, filter, registry)?;
        }
        if let FunctionArgs::List(values) = &args {
            for value in values.iter().rev() {
                validate_expr_collation_boundary(connection, value, registry)?;
            }
        }
        for term in call_order_by.iter().rev() {
            validate_expr_collation_boundary(connection, &term.expr, registry)?;
        }
        validate_used_window_key_collations(connection, &resolved, registry)?;

        let mut replaced = false;
        remaining =
            replace_first_window_with_literal(&remaining, &SqliteValue::Null, &mut replaced);
        if !replaced {
            return Err(FrankenError::Internal(
                "window collation validation replacement made no progress".to_owned(),
            ));
        }
    }
    Ok(())
}

fn validate_window_frame_collation_consumers(
    frame: &FrameSpec,
    registry: &CollationRegistry,
) -> Result<()> {
    let validate_bound = |bound: &FrameBound| match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            validate_window_frame_expr_collation_consumers(expr, registry)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => Ok(()),
    };
    validate_bound(&frame.start)?;
    if let Some(end) = &frame.end {
        validate_bound(end)?;
    }
    Ok(())
}

/// Validate only the collation operations SQLite preserves while preparing a
/// window-frame offset. Function calls and scalar subqueries are replaced by
/// opaque registers during window rewrite, so collations inside them are not
/// resolved here; direct comparison/list operators in the offset remain live.
#[allow(clippy::too_many_lines)]
fn validate_window_frame_expr_collation_consumers(
    expr: &Expr,
    registry: &CollationRegistry,
) -> Result<()> {
    if expr_folds_to_integer_zero_via_and(expr) {
        return Ok(());
    }
    if expr.as_sql_function_call().is_some() {
        return Ok(());
    }
    match expr {
        Expr::FunctionCall { .. }
        | Expr::JsonAccess { .. }
        | Expr::Subquery(_, _)
        | Expr::Exists { .. } => Ok(()),
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => Ok(()),
        Expr::BinaryOp {
            left, op, right, ..
        } => {
            if binary_op_consumes_collation(*op) {
                validate_window_frame_binary_comparison_collation(left, right, registry)?;
            }
            validate_window_frame_expr_collation_consumers(left, registry)?;
            validate_window_frame_expr_collation_consumers(right, registry)?;
            Ok(())
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            validate_window_frame_expr_collation_consumers(expr, registry)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            validate_window_frame_binary_comparison_collation(expr, low, registry)?;
            validate_window_frame_expr_collation_consumers(expr, registry)?;
            validate_window_frame_expr_collation_consumers(low, registry)?;
            validate_window_frame_binary_comparison_collation(expr, high, registry)?;
            validate_window_frame_expr_collation_consumers(high, registry)?;
            Ok(())
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty())
                || matches!(set, InSet::Subquery(_))
                || matches!(expr.as_ref(), Expr::RowValue(..))
            {
                return Ok(());
            }
            if let InSet::List(values) = set {
                if let [value] = values.as_slice() {
                    validate_window_frame_binary_comparison_collation(expr, value, registry)?;
                } else {
                    validate_window_frame_in_list_membership_collations(expr, values, registry)?;
                }
                validate_window_frame_expr_collation_consumers(expr, registry)?;
                for value in values {
                    validate_window_frame_expr_collation_consumers(value, registry)?;
                }
            }
            Ok(())
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            validate_window_frame_expr_collation_consumers(pattern, registry)?;
            validate_window_frame_expr_collation_consumers(expr, registry)?;
            if let Some(escape) = escape {
                validate_window_frame_expr_collation_consumers(escape, registry)?;
            }
            Ok(())
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(operand) = operand {
                validate_window_frame_expr_collation_consumers(operand, registry)?;
                for (condition, value) in whens {
                    validate_window_frame_expr_collation_consumers(condition, registry)?;
                    validate_window_frame_binary_comparison_collation(
                        operand, condition, registry,
                    )?;
                    validate_window_frame_expr_collation_consumers(value, registry)?;
                }
            } else {
                for (condition, value) in whens {
                    validate_window_frame_expr_collation_consumers(condition, registry)?;
                    validate_window_frame_expr_collation_consumers(value, registry)?;
                }
            }
            if let Some(else_expr) = else_expr {
                validate_window_frame_expr_collation_consumers(else_expr, registry)?;
            }
            Ok(())
        }
        Expr::RowValue(values, _) => {
            for value in values {
                validate_window_frame_expr_collation_consumers(value, registry)?;
            }
            Ok(())
        }
    }
}

fn validate_window_frame_binary_comparison_collation(
    left: &Expr,
    right: &Expr,
    registry: &CollationRegistry,
) -> Result<()> {
    if let (Expr::RowValue(left_values, _), Expr::RowValue(right_values, _)) = (left, right) {
        for (left_value, right_value) in left_values.iter().zip(right_values) {
            validate_window_frame_binary_comparison_collation(left_value, right_value, registry)?;
        }
        return Ok(());
    }
    if let Some(collation) = window_frame_explicit_collation_name(left)
        .or_else(|| window_frame_explicit_collation_name(right))
    {
        validate_registered_collation(collation, registry)?;
    }
    Ok(())
}

fn validate_window_frame_in_list_membership_collations(
    lhs: &Expr,
    values: &[Expr],
    registry: &CollationRegistry,
) -> Result<()> {
    if let Expr::RowValue(lhs_values, _) = lhs
        && let Some(Expr::RowValue(rhs_values, _)) = values.last()
    {
        for (lhs_value, rhs_value) in lhs_values.iter().zip(rhs_values) {
            validate_window_frame_binary_comparison_collation(lhs_value, rhs_value, registry)?;
        }
        Ok(())
    } else if let Some(collation) = window_frame_explicit_collation_name(lhs) {
        validate_registered_collation(collation, registry)
    } else {
        Ok(())
    }
}

fn window_frame_explicit_collation_name(expr: &Expr) -> Option<&str> {
    if expr.as_sql_function_call().is_some() {
        return None;
    }
    match expr {
        Expr::FunctionCall { .. }
        | Expr::JsonAccess { .. }
        | Expr::Subquery(_, _)
        | Expr::Exists { .. } => None,
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => None,
        Expr::BinaryOp { left, right, .. } => window_frame_explicit_collation_name(left)
            .or_else(|| window_frame_explicit_collation_name(right)),
        Expr::UnaryOp { expr, .. } | Expr::IsNull { expr, .. } | Expr::Cast { expr, .. } => {
            window_frame_explicit_collation_name(expr)
        }
        Expr::Collate { collation, .. } => Some(collation),
        Expr::Between {
            expr, low, high, ..
        } => window_frame_explicit_collation_name(expr)
            .or_else(|| window_frame_explicit_collation_name(low))
            .or_else(|| window_frame_explicit_collation_name(high)),
        Expr::In { expr, set, .. } => match set {
            InSet::List(values) if values.is_empty() => None,
            InSet::List(values) => window_frame_explicit_collation_name(expr)
                .or_else(|| values.iter().find_map(window_frame_explicit_collation_name)),
            InSet::Subquery(_) | InSet::Table(_) => None,
        },
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => window_frame_explicit_collation_name(pattern)
            .or_else(|| window_frame_explicit_collation_name(expr))
            .or_else(|| {
                escape
                    .as_deref()
                    .and_then(window_frame_explicit_collation_name)
            }),
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => operand
            .as_deref()
            .and_then(window_frame_explicit_collation_name)
            .or_else(|| {
                whens.iter().find_map(|(condition, value)| {
                    window_frame_explicit_collation_name(condition)
                        .or_else(|| window_frame_explicit_collation_name(value))
                })
            })
            .or_else(|| {
                else_expr
                    .as_deref()
                    .and_then(window_frame_explicit_collation_name)
            }),
        Expr::RowValue(values, _) => values
            .first()
            .and_then(window_frame_explicit_collation_name),
    }
}

fn expr_uses_fromless_group_stage_aggregate(
    expr: &Expr,
    named_windows: &NamedWindowSpecs<'_>,
) -> Result<bool> {
    if expr_has_fromless_group_stage_aggregate(expr) {
        return Ok(true);
    }
    let mut remaining = expr.clone();
    while expr_has_window_function(&remaining) {
        let ExtractedWindowFunction { window, .. } = extract_inner_window_function(&remaining)
            .ok_or_else(|| {
                FrankenError::Internal(
                    "aggregate-stage detection could not expose a window call".to_owned(),
                )
            })?;
        let resolved = resolve_used_window_spec(&window, named_windows)?;
        if window_spec_has_fromless_group_stage_aggregate(&resolved) {
            return Ok(true);
        }
        let mut replaced = false;
        remaining =
            replace_first_window_with_literal(&remaining, &SqliteValue::Null, &mut replaced);
        if !replaced {
            return Err(FrankenError::Internal(
                "aggregate-stage detection replacement made no progress".to_owned(),
            ));
        }
    }
    Ok(false)
}

#[allow(clippy::too_many_lines)]
fn expr_has_fromless_group_stage_aggregate(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall {
            name,
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            (over.is_none()
                && is_current_aggregate_or_json_fn(name, args)
                && !is_scalar_max_min(name, args))
                || matches!(
                    args,
                    FunctionArgs::List(values)
                        if values.iter().any(expr_has_fromless_group_stage_aggregate)
                )
                || order_by
                    .iter()
                    .any(|term| expr_has_fromless_group_stage_aggregate(&term.expr))
                || filter
                    .as_deref()
                    .is_some_and(expr_has_fromless_group_stage_aggregate)
                || over
                    .as_ref()
                    .is_some_and(window_spec_has_fromless_group_stage_aggregate)
        }
        Expr::BinaryOp { left, right, .. } => {
            expr_has_fromless_group_stage_aggregate(left)
                || expr_has_fromless_group_stage_aggregate(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => expr_has_fromless_group_stage_aggregate(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_has_fromless_group_stage_aggregate(expr)
                || expr_has_fromless_group_stage_aggregate(low)
                || expr_has_fromless_group_stage_aggregate(high)
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return false;
            }
            expr_has_fromless_group_stage_aggregate(expr)
                || matches!(
                    set,
                    InSet::List(values)
                        if values.iter().any(expr_has_fromless_group_stage_aggregate)
                )
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_has_fromless_group_stage_aggregate(expr)
                || expr_has_fromless_group_stage_aggregate(pattern)
                || escape
                    .as_deref()
                    .is_some_and(expr_has_fromless_group_stage_aggregate)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(expr_has_fromless_group_stage_aggregate)
                || whens.iter().any(|(condition, value)| {
                    expr_has_fromless_group_stage_aggregate(condition)
                        || expr_has_fromless_group_stage_aggregate(value)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(expr_has_fromless_group_stage_aggregate)
        }
        Expr::JsonAccess { expr, path, .. } => {
            expr_has_fromless_group_stage_aggregate(expr)
                || expr_has_fromless_group_stage_aggregate(path)
        }
        Expr::RowValue(values, _) => values.iter().any(expr_has_fromless_group_stage_aggregate),
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _)
        | Expr::Subquery(_, _)
        | Expr::Exists { .. } => false,
    }
}

#[allow(clippy::too_many_lines)]
fn expr_has_fromless_outside_window_aggregate(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall { over: Some(_), .. } => false,
        Expr::FunctionCall {
            name,
            args,
            order_by,
            filter,
            over: None,
            ..
        } => {
            (is_current_aggregate_or_json_fn(name, args) && !is_scalar_max_min(name, args))
                || matches!(
                    args,
                    FunctionArgs::List(values)
                        if values
                            .iter()
                            .any(expr_has_fromless_outside_window_aggregate)
                )
                || order_by
                    .iter()
                    .any(|term| expr_has_fromless_outside_window_aggregate(&term.expr))
                || filter
                    .as_deref()
                    .is_some_and(expr_has_fromless_outside_window_aggregate)
        }
        Expr::BinaryOp { left, right, .. } => {
            expr_has_fromless_outside_window_aggregate(left)
                || expr_has_fromless_outside_window_aggregate(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => expr_has_fromless_outside_window_aggregate(expr),
        Expr::Between {
            expr, low, high, ..
        } => {
            expr_has_fromless_outside_window_aggregate(expr)
                || expr_has_fromless_outside_window_aggregate(low)
                || expr_has_fromless_outside_window_aggregate(high)
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return false;
            }
            expr_has_fromless_outside_window_aggregate(expr)
                || matches!(
                    set,
                    InSet::List(values)
                        if values
                            .iter()
                            .any(expr_has_fromless_outside_window_aggregate)
                )
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expr_has_fromless_outside_window_aggregate(expr)
                || expr_has_fromless_outside_window_aggregate(pattern)
                || escape
                    .as_deref()
                    .is_some_and(expr_has_fromless_outside_window_aggregate)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_some_and(expr_has_fromless_outside_window_aggregate)
                || whens.iter().any(|(condition, value)| {
                    expr_has_fromless_outside_window_aggregate(condition)
                        || expr_has_fromless_outside_window_aggregate(value)
                })
                || else_expr
                    .as_deref()
                    .is_some_and(expr_has_fromless_outside_window_aggregate)
        }
        Expr::JsonAccess { expr, path, .. } => {
            expr_has_fromless_outside_window_aggregate(expr)
                || expr_has_fromless_outside_window_aggregate(path)
        }
        Expr::RowValue(values, _) => values
            .iter()
            .any(expr_has_fromless_outside_window_aggregate),
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _)
        | Expr::Subquery(_, _)
        | Expr::Exists { .. } => false,
    }
}

fn window_spec_has_fromless_group_stage_aggregate(window: &WindowSpec) -> bool {
    window
        .partition_by
        .iter()
        .any(expr_has_fromless_group_stage_aggregate)
        || window
            .order_by
            .iter()
            .any(|term| expr_has_fromless_group_stage_aggregate(&term.expr))
        || window.frame.as_ref().is_some_and(|frame| {
            frame_bound_has_fromless_group_stage_aggregate(&frame.start)
                || frame
                    .end
                    .as_ref()
                    .is_some_and(frame_bound_has_fromless_group_stage_aggregate)
        })
}

fn frame_bound_has_fromless_group_stage_aggregate(bound: &FrameBound) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expr_has_fromless_group_stage_aggregate(expr)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => false,
    }
}

fn resolve_fromless_group_expr<'a>(
    expr: &'a Expr,
    columns: &'a [ResultColumn],
) -> Result<&'a Expr> {
    if let Some(ordinal) = connection_order_by_integer_ordinal(expr) {
        let index = usize::try_from(ordinal)
            .ok()
            .and_then(|ordinal| ordinal.checked_sub(1))
            .filter(|index| *index < columns.len())
            .ok_or_else(|| FrankenError::OutOfRange {
                what: "GROUP BY column index".to_owned(),
                value: ordinal.to_string(),
            })?;
        return match &columns[index] {
            ResultColumn::Expr { expr, .. } => Ok(expr),
            ResultColumn::Star | ResultColumn::TableStar(_) => Err(FrankenError::ParseError {
                offset: 0,
                detail: "no tables specified".to_owned(),
            }),
        };
    }
    let Some(index) = resolve_order_term_idx(expr, columns) else {
        return Ok(expr);
    };
    match &columns[index] {
        ResultColumn::Expr { expr, .. } => Ok(expr),
        ResultColumn::Star | ResultColumn::TableStar(_) => Err(FrankenError::ParseError {
            offset: 0,
            detail: "no tables specified".to_owned(),
        }),
    }
}

fn build_expression_postprocess(select: &SelectStatement) -> ExpressionPostprocess {
    let mut output_aliases = HashMap::new();
    let output_width = match &select.body.select {
        SelectCore::Select { columns, .. } => {
            for (index, column) in columns.iter().enumerate() {
                if let ResultColumn::Expr {
                    alias: Some(alias), ..
                } = column
                {
                    output_aliases
                        .entry(alias.to_ascii_lowercase())
                        .or_insert(index);
                }
            }
            columns.len()
        }
        SelectCore::Values(rows) => rows.first().map_or(0, Vec::len),
    };

    ExpressionPostprocess {
        order_by: select.order_by.clone(),
        limit: select.limit.clone(),
        output_aliases,
        output_width,
    }
}

/// Whether an expression-only ORDER BY term is safe to leave unevaluated once
/// LIMIT has already been proven to be zero.
///
/// SQLite still resolves names and output positions before honoring LIMIT 0,
/// but it does not execute a row-independent ordering expression such as
/// `abs(1)`. Keep column, relation, nested-query, and RAISE nodes out of this
/// carve-out so invalid names and context-sensitive expressions still reach
/// normal validation.
#[allow(clippy::too_many_lines)]
fn expression_only_order_expr_can_be_skipped_under_zero_limit(expr: &Expr) -> bool {
    match expr {
        Expr::BoundOuterValue { .. } | Expr::Literal(_, _) | Expr::Placeholder(_, _) => true,
        Expr::Column(_, _) | Expr::Raise { .. } | Expr::Subquery(_, _) | Expr::Exists { .. } => {
            false
        }
        Expr::BinaryOp { left, right, .. } => {
            expression_only_order_expr_can_be_skipped_under_zero_limit(left)
                && expression_only_order_expr_can_be_skipped_under_zero_limit(right)
        }
        Expr::UnaryOp { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. } => {
            expression_only_order_expr_can_be_skipped_under_zero_limit(expr)
        }
        Expr::Between {
            expr, low, high, ..
        } => {
            expression_only_order_expr_can_be_skipped_under_zero_limit(expr)
                && expression_only_order_expr_can_be_skipped_under_zero_limit(low)
                && expression_only_order_expr_can_be_skipped_under_zero_limit(high)
        }
        Expr::In { expr, set, .. } => {
            if matches!(set, InSet::List(values) if values.is_empty()) {
                return true;
            }
            expression_only_order_expr_can_be_skipped_under_zero_limit(expr)
                && matches!(
                    set,
                    InSet::List(values)
                        if values.iter().all(
                            expression_only_order_expr_can_be_skipped_under_zero_limit
                        )
                )
        }
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            expression_only_order_expr_can_be_skipped_under_zero_limit(expr)
                && expression_only_order_expr_can_be_skipped_under_zero_limit(pattern)
                && escape
                    .as_deref()
                    .is_none_or(expression_only_order_expr_can_be_skipped_under_zero_limit)
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            operand
                .as_deref()
                .is_none_or(expression_only_order_expr_can_be_skipped_under_zero_limit)
                && whens.iter().all(|(when_expr, then_expr)| {
                    expression_only_order_expr_can_be_skipped_under_zero_limit(when_expr)
                        && expression_only_order_expr_can_be_skipped_under_zero_limit(then_expr)
                })
                && else_expr
                    .as_deref()
                    .is_none_or(expression_only_order_expr_can_be_skipped_under_zero_limit)
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            (match args {
                FunctionArgs::Star => true,
                FunctionArgs::List(values) => values
                    .iter()
                    .all(expression_only_order_expr_can_be_skipped_under_zero_limit),
            }) && order_by
                .iter()
                .all(|term| expression_only_order_expr_can_be_skipped_under_zero_limit(&term.expr))
                && filter
                    .as_deref()
                    .is_none_or(expression_only_order_expr_can_be_skipped_under_zero_limit)
                && over.as_ref().is_none_or(|window| {
                    window
                        .partition_by
                        .iter()
                        .all(expression_only_order_expr_can_be_skipped_under_zero_limit)
                        && window.order_by.iter().all(|term| {
                            expression_only_order_expr_can_be_skipped_under_zero_limit(&term.expr)
                        })
                        && window.frame.as_ref().is_none_or(|frame| {
                            expression_only_order_frame_bound_can_be_skipped(&frame.start)
                                && frame
                                    .end
                                    .as_ref()
                                    .is_none_or(expression_only_order_frame_bound_can_be_skipped)
                        })
                })
        }
        Expr::JsonAccess { expr, path, .. } => {
            expression_only_order_expr_can_be_skipped_under_zero_limit(expr)
                && expression_only_order_expr_can_be_skipped_under_zero_limit(path)
        }
        Expr::RowValue(values, _) => values
            .iter()
            .all(expression_only_order_expr_can_be_skipped_under_zero_limit),
    }
}

fn expression_only_order_frame_bound_can_be_skipped(bound: &FrameBound) -> bool {
    match bound {
        FrameBound::Preceding(expr) | FrameBound::Following(expr) => {
            expression_only_order_expr_can_be_skipped_under_zero_limit(expr)
        }
        FrameBound::UnboundedPreceding
        | FrameBound::CurrentRow
        | FrameBound::UnboundedFollowing => true,
    }
}

fn apply_expression_postprocess(
    rows: &mut Vec<Row>,
    postprocess: &ExpressionPostprocess,
) -> Result<()> {
    if !postprocess.order_by.is_empty() {
        let resolved_order_terms = resolve_order_terms(
            &postprocess.order_by,
            postprocess.output_width,
            &postprocess.output_aliases,
        )?;
        rows.sort_by(|left, right| {
            for term in &resolved_order_terms {
                let Some(left_value) = left.values.get(term.column_index) else {
                    continue;
                };
                let Some(right_value) = right.values.get(term.column_index) else {
                    continue;
                };
                let ordering = compare_order_values(left_value, right_value, *term);
                if ordering != std::cmp::Ordering::Equal {
                    return ordering;
                }
            }
            std::cmp::Ordering::Equal
        });
    }

    if let Some(limit_clause) = postprocess.limit.as_ref() {
        let limit = parse_limit_offset_expr(&limit_clause.limit)?;
        if limit == 0 {
            rows.clear();
            return Ok(());
        }
        let offset = limit_clause
            .offset
            .as_ref()
            .map_or(Ok(0_i64), parse_limit_offset_expr)?;
        if offset > 0 {
            let offset = usize::try_from(offset).unwrap_or(usize::MAX);
            if offset >= rows.len() {
                rows.clear();
                return Ok(());
            }
            rows.drain(0..offset);
        }

        if limit >= 0 {
            let limit = usize::try_from(limit).unwrap_or(usize::MAX);
            rows.truncate(limit);
        }
    }

    Ok(())
}

fn resolve_order_terms(
    order_by: &[OrderingTerm],
    output_width: usize,
    output_aliases: &HashMap<String, usize>,
) -> Result<Vec<ResolvedOrderTerm>> {
    order_by
        .iter()
        .map(|term| {
            let column_index = match &term.expr {
                Expr::Column(column_ref, _) if column_ref.table.is_none() => output_aliases
                    .get(&column_ref.column.to_ascii_lowercase())
                    .copied()
                    .ok_or_else(|| {
                        FrankenError::NotImplemented(
                            "expression-only ORDER BY currently supports output-column positions or aliases only".to_owned(),
                        )
                    })?,
                _ => order_term_positional_index(&term.expr)?,
            };
            if column_index >= output_width {
                return Err(FrankenError::OutOfRange {
                    what: "ORDER BY column index".to_owned(),
                    value: (column_index + 1).to_string(),
                });
            }
            Ok(ResolvedOrderTerm {
                column_index,
                descending: term.direction == Some(SortDirection::Desc),
                nulls_order: term
                    .nulls
                    .unwrap_or_else(|| default_nulls_order(term.direction)),
            })
        })
        .collect()
}

fn order_term_positional_index(expr: &Expr) -> Result<usize> {
    let one_based = parse_limit_offset_expr(expr)?;
    if one_based <= 0 {
        return Err(FrankenError::OutOfRange {
            what: "ORDER BY column index".to_owned(),
            value: one_based.to_string(),
        });
    }
    let zero_based = one_based - 1;
    usize::try_from(zero_based).map_err(|_| FrankenError::OutOfRange {
        what: "ORDER BY column index".to_owned(),
        value: one_based.to_string(),
    })
}

fn parse_limit_offset_expr(expr: &Expr) -> Result<i64> {
    match expr {
        Expr::Literal(Literal::Integer(value), _) => Ok(*value),
        Expr::UnaryOp {
            op: UnaryOp::Plus,
            expr: inner,
            ..
        } => parse_limit_offset_expr(inner),
        Expr::UnaryOp {
            op: UnaryOp::Negate,
            expr: inner,
            ..
        } => parse_limit_offset_expr(inner)?
            .checked_neg()
            .ok_or_else(|| FrankenError::OutOfRange {
                what: "LIMIT/OFFSET expression".to_owned(),
                value: "integer overflow".to_owned(),
            }),
        _ => Err(FrankenError::NotImplemented(
            "expression-only LIMIT/OFFSET currently supports integer literals only".to_owned(),
        )),
    }
}

fn default_nulls_order(direction: Option<SortDirection>) -> NullsOrder {
    if direction == Some(SortDirection::Desc) {
        NullsOrder::Last
    } else {
        NullsOrder::First
    }
}

fn compare_order_values(
    left: &SqliteValue,
    right: &SqliteValue,
    term: ResolvedOrderTerm,
) -> std::cmp::Ordering {
    let left_is_null = left.is_null();
    let right_is_null = right.is_null();
    if left_is_null || right_is_null {
        if left_is_null && right_is_null {
            return std::cmp::Ordering::Equal;
        }
        return match (left_is_null, term.nulls_order) {
            (true, NullsOrder::First) | (false, NullsOrder::Last) => std::cmp::Ordering::Less,
            (true, NullsOrder::Last) | (false, NullsOrder::First) => std::cmp::Ordering::Greater,
        };
    }

    let mut ordering = left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal);
    if term.descending {
        ordering = ordering.reverse();
    }
    ordering
}

fn prepared_count_having_filter(
    expr: &Expr,
    count_alias: Option<&str>,
) -> Option<PreparedCountHavingFilter> {
    fn expr_matches_count(expr: &Expr, count_alias: Option<&str>) -> bool {
        match expr {
            Expr::Column(column_ref, _) if column_ref.table.is_none() => {
                count_alias.is_some_and(|alias| column_ref.column.eq_ignore_ascii_case(alias))
            }
            Expr::FunctionCall {
                name,
                args: FunctionArgs::Star,
                distinct: false,
                order_by,
                filter: None,
                over: None,
                ..
            } => name.eq_ignore_ascii_case("count") && order_by.is_empty(),
            _ => false,
        }
    }

    let Expr::BinaryOp {
        left, op, right, ..
    } = expr
    else {
        return None;
    };

    let normalize = |op: BinaryOp| match op {
        BinaryOp::Gt => Some(PreparedCountHavingOp::GreaterThan),
        BinaryOp::Ge => Some(PreparedCountHavingOp::GreaterThanOrEqual),
        _ => None,
    };
    let flipped = |op: BinaryOp| match op {
        BinaryOp::Lt => Some(PreparedCountHavingOp::GreaterThan),
        BinaryOp::Le => Some(PreparedCountHavingOp::GreaterThanOrEqual),
        _ => None,
    };

    if expr_matches_count(left, count_alias) {
        return Some(PreparedCountHavingFilter {
            op: normalize(*op)?,
            threshold: select_numeric_literal(right)?,
        });
    }
    if expr_matches_count(right, count_alias) {
        return Some(PreparedCountHavingFilter {
            op: flipped(*op)?,
            threshold: select_numeric_literal(left)?,
        });
    }
    None
}

fn prepared_count_having_matches(count: i64, filter: Option<&PreparedCountHavingFilter>) -> bool {
    let Some(filter) = filter else {
        return true;
    };
    let ordering = cmp_sqlite_values(&SqliteValue::Integer(count), &filter.threshold);
    match filter.op {
        PreparedCountHavingOp::GreaterThan => ordering == std::cmp::Ordering::Greater,
        PreparedCountHavingOp::GreaterThanOrEqual => ordering != std::cmp::Ordering::Less,
    }
}

fn exactly_one_row_or_error(rows: Vec<Row>) -> Result<Row> {
    let mut iter = rows.into_iter();
    let row = iter.next().ok_or(FrankenError::QueryReturnedNoRows)?;
    if iter.next().is_some() {
        return Err(FrankenError::QueryReturnedMultipleRows);
    }
    Ok(row)
}

fn query_row_completed_without_engine_failure(result: &Result<Row>) -> bool {
    matches!(
        result,
        Ok(_) | Err(FrankenError::QueryReturnedNoRows | FrankenError::QueryReturnedMultipleRows)
    )
}

fn validate_bound_parameters(program: &VdbeProgram, params: &[SqliteValue]) -> Result<()> {
    let max_required =
        program
            .max_bind_parameter_index()
            .map_err(|raw_index| FrankenError::OutOfRange {
                what: "bind parameter index".to_owned(),
                value: raw_index.to_string(),
            })?;

    if max_required > usize::try_from(MAX_VARIABLE_NUMBER).expect("u32 variable limit fits usize") {
        return Err(FrankenError::OutOfRange {
            what: "bind parameter index".to_owned(),
            value: max_required.to_string(),
        });
    }

    if max_required > params.len() {
        return Err(FrankenError::OutOfRange {
            what: "bind parameter index".to_owned(),
            value: max_required.to_string(),
        });
    }
    Ok(())
}

fn parse_single_statement(sql: &str) -> Result<Statement> {
    let statements = parse_statements(sql)?;
    let mut iter = statements.into_iter();
    let statement = iter.next().ok_or_else(|| FrankenError::ParseError {
        offset: 0,
        detail: "no SQL statement provided".to_owned(),
    })?;

    if iter.next().is_some() {
        return Err(FrankenError::NotImplemented(
            "multiple statements are not supported in this API path".to_owned(),
        ));
    }

    Ok(statement)
}

fn parse_statements(sql: &str) -> Result<Vec<Statement>> {
    let mut parser = Parser::from_sql(sql);
    let (statements, errors) = parser.parse_all();

    if let Some(parse_error) = errors.first() {
        return Err(FrankenError::ParseError {
            #[allow(clippy::cast_sign_loss)]
            offset: parse_error.span.start as usize,
            detail: parse_error.message.clone(),
        });
    }

    if statements.is_empty() {
        return Err(FrankenError::ParseError {
            offset: 0,
            detail: "no SQL statement provided".to_owned(),
        });
    }

    Ok(statements)
}

fn batch_is_noop(sql: &str) -> Result<bool> {
    let bytes = sql.as_bytes();
    let mut i = 0;

    while i < bytes.len() {
        match bytes[i] {
            b';' | b' ' | b'\t' | b'\r' | b'\n' => {
                i += 1;
            }
            b'-' if i + 1 < bytes.len() && bytes[i + 1] == b'-' => {
                i += 2;
                while i < bytes.len() && bytes[i] != b'\n' {
                    i += 1;
                }
            }
            b'/' if i + 1 < bytes.len() && bytes[i + 1] == b'*' => {
                let comment_start = i;
                i += 2;
                let mut terminated = false;
                while i + 1 < bytes.len() {
                    if bytes[i] == b'*' && bytes[i + 1] == b'/' {
                        i += 2;
                        terminated = true;
                        break;
                    }
                    i += 1;
                }
                if !terminated {
                    return Err(FrankenError::ParseError {
                        offset: comment_start,
                        detail: "unterminated block comment".to_owned(),
                    });
                }
            }
            _ => return Ok(false),
        }
    }

    Ok(true)
}

#[cfg(test)]
mod batch_execution_tests {
    use super::*;

    #[test]
    fn execute_batch_treats_empty_and_comment_only_sql_as_noop() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute_batch("").await.unwrap();
            conn.execute_batch("   ;  ;  ").await.unwrap();
            conn.execute_batch("  -- nothing here\n/* still empty */ ; ")
                .await
                .unwrap();
        });
    }

    #[test]
    fn execute_batch_rejects_unterminated_block_comment() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let error = conn
                .execute_batch("/* unterminated")
                .await
                .expect_err("unterminated block comments should not be treated as empty batches");
            assert!(matches!(error, FrankenError::ParseError { offset: 0, .. }));
        });
    }
}

fn quote_identifier(identifier: &str) -> String {
    let escaped = identifier.replace('"', "\"\"");
    format!("\"{escaped}\"")
}

fn quote_qualified_name(name: &fsqlite_ast::QualifiedName) -> String {
    match &name.schema {
        Some(schema) => format!(
            "{}.{}",
            quote_identifier(schema),
            quote_identifier(&name.name)
        ),
        None => quote_identifier(&name.name),
    }
}

fn to_i64_clamped(value: u64) -> i64 {
    i64::try_from(value).unwrap_or(i64::MAX)
}

#[cfg(feature = "diagnostic-pragmas")]
fn join_page_numbers(pages: &[PageNumber]) -> String {
    pages
        .iter()
        .map(|page| page.get().to_string())
        .collect::<Vec<_>>()
        .join(",")
}

#[cfg(feature = "diagnostic-pragmas")]
fn join_txn_tokens(tokens: &[TxnToken]) -> String {
    tokens
        .iter()
        .map(|token| format!("{}:{}", token.id.get(), token.epoch.get()))
        .collect::<Vec<_>>()
        .join(",")
}

#[cfg(feature = "diagnostic-pragmas")]
fn read_set_top_k_string(summary: &SsiReadSetSummary) -> String {
    summary
        .top_k_pages
        .iter()
        .map(|page| page.get().to_string())
        .collect::<Vec<_>>()
        .join(",")
}

#[cfg(feature = "diagnostic-pragmas")]
fn ssi_decision_cards_to_rows(cards: &[SsiDecisionCard]) -> Vec<Row> {
    cards
        .iter()
        .map(|card| Row {
            values: vec![
                SqliteValue::Integer(to_i64_clamped(card.txn.id.get())),
                SqliteValue::Integer(i64::from(card.txn.epoch.get())),
                SqliteValue::Integer(to_i64_clamped(card.snapshot_seq.get())),
                SqliteValue::Integer(to_i64_clamped(card.commit_seq.map_or(0, CommitSeq::get))),
                SqliteValue::Text(card.decision_type.as_str().to_owned().into()),
                SqliteValue::Text(join_txn_tokens(&card.conflicting_txns).into()),
                SqliteValue::Text(join_page_numbers(&card.conflict_pages).into()),
                SqliteValue::Integer(
                    i64::try_from(card.read_set_summary.page_count).unwrap_or(i64::MAX),
                ),
                SqliteValue::Text(read_set_top_k_string(&card.read_set_summary).into()),
                SqliteValue::Integer(to_i64_clamped(card.read_set_summary.bloom_fingerprint)),
                SqliteValue::Text(join_page_numbers(&card.write_set).into()),
                SqliteValue::Text(card.rationale.clone().into()),
                SqliteValue::Integer(to_i64_clamped(card.timestamp_unix_ns)),
                SqliteValue::Integer(to_i64_clamped(card.decision_epoch)),
                SqliteValue::Text(card.chain_hash_hex().into()),
            ],
        })
        .collect()
}

#[cfg(not(target_arch = "wasm32"))]
fn hex_encode_blake3(bytes: [u8; 32]) -> String {
    use std::fmt::Write as _;

    let mut encoded = String::with_capacity(64);
    for byte in bytes {
        let _ = write!(&mut encoded, "{byte:02x}");
    }
    encoded
}

#[cfg(not(target_arch = "wasm32"))]
fn raptorq_repair_evidence_cards_to_rows(cards: &[WalFecRepairEvidenceCard]) -> Vec<Row> {
    cards
        .iter()
        .map(|card| Row {
            values: vec![
                SqliteValue::Integer(i64::from(card.frame_id)),
                card.wal_file_offset_bytes
                    .map_or(SqliteValue::Null, |offset| {
                        SqliteValue::Integer(to_i64_clamped(offset))
                    }),
                SqliteValue::Integer(to_i64_clamped(card.monotonic_timestamp_ns)),
                SqliteValue::Integer(to_i64_clamped(card.wall_clock_unix_ns)),
                SqliteValue::Text(card.corruption_signature_hex().into()),
                card.bit_error_pattern
                    .as_ref()
                    .map_or(SqliteValue::Null, |pattern| {
                        SqliteValue::Text(pattern.clone().into())
                    }),
                SqliteValue::Text(card.repair_source.as_str().to_owned().into()),
                SqliteValue::Integer(i64::from(card.symbols_used)),
                SqliteValue::Integer(i64::from(card.validated_source_symbols)),
                SqliteValue::Integer(i64::from(card.validated_repair_symbols)),
                SqliteValue::Integer(i64::from(card.required_symbols)),
                SqliteValue::Integer(i64::from(card.available_symbols)),
                SqliteValue::Text(hex_encode_blake3(card.witness.corrupted_hash_blake3).into()),
                SqliteValue::Text(hex_encode_blake3(card.witness.repaired_hash_blake3).into()),
                SqliteValue::Text(hex_encode_blake3(card.witness.expected_hash_blake3).into()),
                SqliteValue::Integer(to_i64_clamped(card.repair_latency_ns)),
                SqliteValue::Integer(i64::from(card.confidence_per_mille)),
                SqliteValue::Text(card.severity_bucket.as_str().to_owned().into()),
                SqliteValue::Integer(to_i64_clamped(card.ledger_epoch)),
                SqliteValue::Text(card.chain_hash_hex().into()),
            ],
        })
        .collect()
}

#[cfg(feature = "diagnostic-pragmas")]
#[derive(Debug, Clone)]
struct LineageJoinSpec {
    left_table: String,
    right_table: String,
    left_column: String,
    right_column: String,
    left_contributor_column: String,
    right_contributor_column: String,
}

#[cfg(feature = "diagnostic-pragmas")]
fn parse_lineage_identifier(raw: &str, label: &str) -> Result<String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(FrankenError::Internal(format!(
            "PRAGMA lineage {label} must be non-empty"
        )));
    }
    if !trimmed
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '_')
    {
        return Err(FrankenError::Internal(format!(
            "PRAGMA lineage {label} must use [A-Za-z0-9_], got `{trimmed}`"
        )));
    }
    Ok(trimmed.to_owned())
}

#[cfg(feature = "diagnostic-pragmas")]
fn parse_lineage_query_spec(spec: &str) -> Result<LineageJoinSpec> {
    let parts = spec.split(',').map(str::trim).collect::<Vec<_>>();
    if !(parts.len() == 4 || parts.len() == 6) {
        return Err(FrankenError::Internal(
            "PRAGMA lineage must be `left_table,right_table,left_col,right_col[,left_id_col,right_id_col]`"
                .to_owned(),
        ));
    }
    let (left_contributor_column, right_contributor_column) = if parts.len() == 6 {
        (
            parse_lineage_identifier(parts[4], "left contributor column")?,
            parse_lineage_identifier(parts[5], "right contributor column")?,
        )
    } else {
        ("rowid".to_owned(), "rowid".to_owned())
    };
    Ok(LineageJoinSpec {
        left_table: parse_lineage_identifier(parts[0], "left table")?,
        right_table: parse_lineage_identifier(parts[1], "right table")?,
        left_column: parse_lineage_identifier(parts[2], "left join column")?,
        right_column: parse_lineage_identifier(parts[3], "right join column")?,
        left_contributor_column,
        right_contributor_column,
    })
}

#[cfg(feature = "diagnostic-pragmas")]
fn parse_lineage_query(value: &fsqlite_ast::PragmaValue) -> Result<LineageJoinSpec> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    match expr {
        Expr::Literal(Literal::String(spec), _) => parse_lineage_query_spec(spec),
        Expr::Column(col_ref, _) if col_ref.table.is_none() => {
            parse_lineage_query_spec(&col_ref.column)
        }
        _ => Err(FrankenError::Internal(
            "PRAGMA lineage value must be a string like `left,right,left_col,right_col[,left_id_col,right_id_col]`".to_owned(),
        )),
    }
}

#[cfg(feature = "diagnostic-pragmas")]
async fn execute_simple_join_lineage_query(
    conn: &Connection,
    spec: &LineageJoinSpec,
) -> Result<Vec<Row>> {
    let sql = format!(
        "SELECT l.{left_id_col}, r.{right_id_col}, l.{left_col}, r.{right_col} \
         FROM {left_tbl} AS l \
         JOIN {right_tbl} AS r \
         ON l.{left_col} = r.{right_col} \
         ORDER BY 1, 2;",
        left_id_col = spec.left_contributor_column,
        right_id_col = spec.right_contributor_column,
        left_col = spec.left_column,
        right_col = spec.right_column,
        left_tbl = spec.left_table,
        right_tbl = spec.right_table
    );
    conn.query(&sql).await
}

#[cfg(feature = "diagnostic-pragmas")]
fn parse_u64_component(raw: &str, label: &str) -> Result<u64> {
    raw.trim().parse::<u64>().map_err(|_| {
        FrankenError::Internal(format!(
            "PRAGMA ssi_decisions {label} must be an unsigned integer, got `{raw}`"
        ))
    })
}

#[cfg(feature = "diagnostic-pragmas")]
fn parse_ssi_decision_query_spec(spec: &str) -> Result<SsiDecisionQuery> {
    let trimmed = spec.trim();
    if trimmed.is_empty() {
        return Ok(SsiDecisionQuery::default());
    }

    if trimmed.chars().all(|ch| ch.is_ascii_digit()) {
        return Ok(SsiDecisionQuery {
            txn_id: Some(parse_u64_component(trimmed, "txn")?),
            ..SsiDecisionQuery::default()
        });
    }

    let mut query = SsiDecisionQuery::default();
    for term in trimmed.split(',') {
        let term = term.trim();
        if term.is_empty() {
            continue;
        }

        if let Some(raw) = term.strip_prefix("txn:") {
            query.txn_id = Some(parse_u64_component(raw, "txn")?);
            continue;
        }
        if let Some(raw) = term.strip_prefix("type:") {
            let decision_type = SsiDecisionType::from_str(raw).map_err(|_| {
                FrankenError::Internal(format!(
                    "PRAGMA ssi_decisions type must be one of COMMIT_ALLOWED/ABORT_WRITE_SKEW/ABORT_PHANTOM/ABORT_CYCLE, got `{raw}`"
                ))
            })?;
            query.decision_type = Some(decision_type);
            continue;
        }
        if let Some(raw) = term.strip_prefix("time:") {
            let (start_raw, end_raw) = raw.split_once('-').ok_or_else(|| {
                FrankenError::Internal(
                    "PRAGMA ssi_decisions time filter must be `time:<start>-<end>`".to_owned(),
                )
            })?;
            query.timestamp_start_ns = if start_raw.trim().is_empty() {
                None
            } else {
                Some(parse_u64_component(start_raw, "time start")?)
            };
            query.timestamp_end_ns = if end_raw.trim().is_empty() {
                None
            } else {
                Some(parse_u64_component(end_raw, "time end")?)
            };
            continue;
        }

        if query.decision_type.is_none()
            && let Ok(decision_type) = SsiDecisionType::from_str(term)
        {
            query.decision_type = Some(decision_type);
            continue;
        }

        return Err(FrankenError::Internal(format!(
            "PRAGMA ssi_decisions filter term `{term}` is invalid; use txn:<id>, type:<decision>, or time:<start>-<end>"
        )));
    }

    Ok(query)
}

#[cfg(feature = "diagnostic-pragmas")]
fn parse_ssi_decision_query(value: &fsqlite_ast::PragmaValue) -> Result<SsiDecisionQuery> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    match expr {
        Expr::Literal(Literal::Integer(n), _) => {
            if *n < 0 {
                return Err(FrankenError::Internal(
                    "PRAGMA ssi_decisions txn id must be >= 0".to_owned(),
                ));
            }
            Ok(SsiDecisionQuery {
                txn_id: Some(u64::try_from(*n).unwrap_or(u64::MAX)),
                ..SsiDecisionQuery::default()
            })
        }
        Expr::Literal(Literal::String(s), _) => parse_ssi_decision_query_spec(s),
        Expr::Column(col_ref, _) if col_ref.table.is_none() => {
            parse_ssi_decision_query_spec(&col_ref.column)
        }
        _ => Err(FrankenError::Internal(
            "PRAGMA ssi_decisions value must be an integer txn id or string filter".to_owned(),
        )),
    }
}

#[cfg(not(target_arch = "wasm32"))]
fn parse_raptorq_u64_component(raw: &str, label: &str) -> Result<u64> {
    raw.trim().parse::<u64>().map_err(|_| {
        FrankenError::Internal(format!(
            "PRAGMA raptorq_repair_evidence {label} must be an unsigned integer, got `{raw}`"
        ))
    })
}

#[cfg(not(target_arch = "wasm32"))]
fn parse_raptorq_repair_evidence_query_spec(spec: &str) -> Result<WalFecRepairEvidenceQuery> {
    let trimmed = spec.trim();
    if trimmed.is_empty() {
        return Ok(WalFecRepairEvidenceQuery::default());
    }

    if trimmed.chars().all(|ch| ch.is_ascii_digit()) {
        let frame_id = parse_raptorq_u64_component(trimmed, "frame")?;
        return Ok(WalFecRepairEvidenceQuery {
            frame_id: Some(u32::try_from(frame_id).unwrap_or(u32::MAX)),
            ..WalFecRepairEvidenceQuery::default()
        });
    }

    let mut query = WalFecRepairEvidenceQuery::default();
    for term in trimmed.split(',') {
        let term = term.trim();
        if term.is_empty() {
            continue;
        }

        if let Some(raw) = term
            .strip_prefix("frame:")
            .or_else(|| term.strip_prefix("page:"))
        {
            let frame_id = parse_raptorq_u64_component(raw, "frame")?;
            query.frame_id = Some(u32::try_from(frame_id).unwrap_or(u32::MAX));
            continue;
        }

        if let Some(raw) = term.strip_prefix("severity:") {
            let bucket = WalFecRepairSeverityBucket::from_str(raw).map_err(|_| {
                FrankenError::Internal(format!(
                    "PRAGMA raptorq_repair_evidence severity must be one of 1|2-5|6-10|11+, got `{raw}`"
                ))
            })?;
            query.severity_bucket = Some(bucket);
            continue;
        }

        if let Some(raw) = term.strip_prefix("time:") {
            let (start_raw, end_raw) = raw.split_once('-').ok_or_else(|| {
                FrankenError::Internal(
                    "PRAGMA raptorq_repair_evidence time filter must be `time:<start>-<end>`"
                        .to_owned(),
                )
            })?;
            query.wall_clock_start_ns = if start_raw.trim().is_empty() {
                None
            } else {
                Some(parse_raptorq_u64_component(start_raw, "time start")?)
            };
            query.wall_clock_end_ns = if end_raw.trim().is_empty() {
                None
            } else {
                Some(parse_raptorq_u64_component(end_raw, "time end")?)
            };
            continue;
        }

        if let Some(raw) = term.strip_prefix("limit:") {
            let limit = parse_raptorq_u64_component(raw, "limit")?;
            query.limit = Some(usize::try_from(limit).unwrap_or(usize::MAX));
            continue;
        }

        if query.severity_bucket.is_none()
            && let Ok(bucket) = WalFecRepairSeverityBucket::from_str(term)
        {
            query.severity_bucket = Some(bucket);
            continue;
        }

        return Err(FrankenError::Internal(format!(
            "PRAGMA raptorq_repair_evidence filter term `{term}` is invalid; use frame:<id>, severity:<bucket>, time:<start>-<end>, or limit:<n>"
        )));
    }

    Ok(query)
}

#[cfg(not(target_arch = "wasm32"))]
fn parse_raptorq_repair_evidence_query(
    value: &fsqlite_ast::PragmaValue,
) -> Result<WalFecRepairEvidenceQuery> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    match expr {
        Expr::Literal(Literal::Integer(n), _) => {
            if *n < 0 {
                return Err(FrankenError::Internal(
                    "PRAGMA raptorq_repair_evidence frame id must be >= 0".to_owned(),
                ));
            }
            Ok(WalFecRepairEvidenceQuery {
                frame_id: Some(u32::try_from(*n).unwrap_or(u32::MAX)),
                ..WalFecRepairEvidenceQuery::default()
            })
        }
        Expr::Literal(Literal::String(s), _) => parse_raptorq_repair_evidence_query_spec(s),
        Expr::Column(col_ref, _) if col_ref.table.is_none() => {
            parse_raptorq_repair_evidence_query_spec(&col_ref.column)
        }
        _ => Err(FrankenError::Internal(
            "PRAGMA raptorq_repair_evidence value must be an integer frame id or string filter"
                .to_owned(),
        )),
    }
}

/// Parse a PRAGMA value as a boolean.
///
/// Accepts `on`, `off`, `true`, `false`, `1`, `0`, `yes`, `no`
/// (case-insensitive).
fn parse_pragma_bool(value: &fsqlite_ast::PragmaValue) -> Result<bool> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    let text = match expr {
        Expr::Literal(Literal::Integer(n), _) => {
            return match *n {
                0 => Ok(false),
                1 => Ok(true),
                _ => Err(FrankenError::Internal(format!(
                    "PRAGMA boolean value must be 0 or 1, got {n}"
                ))),
            };
        }
        Expr::Literal(Literal::True, _) => return Ok(true),
        Expr::Literal(Literal::False, _) => return Ok(false),
        Expr::Literal(Literal::String(s), _) => s.clone(),
        Expr::Column(col_ref, _) if col_ref.table.is_none() => col_ref.column.to_string(),
        _ => {
            return Err(FrankenError::Internal(
                "PRAGMA boolean value must be ON/OFF/TRUE/FALSE/1/0".to_owned(),
            ));
        }
    };
    match text.to_ascii_lowercase().as_str() {
        "on" | "true" | "yes" | "1" => Ok(true),
        "off" | "false" | "no" | "0" => Ok(false),
        _ => Err(FrankenError::Internal(format!(
            "PRAGMA boolean value must be ON/OFF/TRUE/FALSE/1/0, got `{text}`"
        ))),
    }
}

/// Parse a PRAGMA value as a `FusedEntryControlMode`.
///
/// Accepts: `auto`, `on`, `true`, `1` → Auto;
///          `forced_fallback`, `fallback`, `off`, `false`, `0` → ForcedFallback.
fn parse_fused_entry_control_mode(
    value: &fsqlite_ast::PragmaValue,
) -> Result<FusedEntryControlMode> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    let text = match expr {
        Expr::Literal(Literal::Integer(0) | Literal::False, _) => {
            return Ok(FusedEntryControlMode::ForcedFallback);
        }
        Expr::Literal(Literal::Integer(1) | Literal::True, _) => {
            return Ok(FusedEntryControlMode::Auto);
        }
        Expr::Literal(Literal::String(s), _) => s.clone(),
        Expr::Column(col_ref, _) if col_ref.table.is_none() => col_ref.column.to_string(),
        _ => {
            return Err(FrankenError::Internal(
                "PRAGMA fused_entry_mode: expected auto, forced_fallback, on, off, 1, or 0"
                    .to_owned(),
            ));
        }
    };
    match text.to_ascii_lowercase().as_str() {
        "auto" | "on" | "true" | "1" => Ok(FusedEntryControlMode::Auto),
        "forced_fallback" | "fallback" | "off" | "false" | "0" => {
            Ok(FusedEntryControlMode::ForcedFallback)
        }
        _ => Err(FrankenError::Internal(format!(
            "PRAGMA fused_entry_mode: expected auto or forced_fallback, got `{text}`"
        ))),
    }
}

/// Parse a PRAGMA value as a non-negative integer (`usize`).
fn parse_pragma_nonnegative_usize(value: &fsqlite_ast::PragmaValue, what: &str) -> Result<usize> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    let raw = match expr {
        Expr::Literal(Literal::Integer(n), _) => *n,
        Expr::UnaryOp {
            op: UnaryOp::Negate,
            expr,
            ..
        } => match expr.as_ref() {
            Expr::Literal(Literal::Integer(n), _) => n.saturating_neg(),
            _ => {
                return Err(FrankenError::Internal(format!(
                    "PRAGMA {what} must be a non-negative integer"
                )));
            }
        },
        Expr::Column(col_ref, _) if col_ref.table.is_none() => {
            col_ref.column.parse::<i64>().map_err(|_| {
                FrankenError::Internal(format!(
                    "PRAGMA {what} must be a non-negative integer, got `{}`",
                    col_ref.column
                ))
            })?
        }
        _ => {
            return Err(FrankenError::Internal(format!(
                "PRAGMA {what} must be a non-negative integer"
            )));
        }
    };

    if raw < 0 {
        return Err(FrankenError::Internal(format!(
            "PRAGMA {what} must be >= 0, got {raw}"
        )));
    }

    usize::try_from(raw).map_err(|_| {
        FrankenError::Internal(format!(
            "PRAGMA {what} value is too large for this platform: {raw}"
        ))
    })
}

/// Parse a PRAGMA value as a positive finite f64.
fn parse_pragma_positive_f64(value: &fsqlite_ast::PragmaValue, what: &str) -> Result<f64> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    let raw = match expr {
        Expr::Literal(Literal::Integer(n), _) => {
            #[allow(clippy::cast_precision_loss)]
            let f = *n as f64;
            f
        }
        Expr::Literal(Literal::Float(r), _) => *r,
        Expr::Literal(Literal::String(s), _) => s.parse::<f64>().map_err(|_| {
            FrankenError::Internal(format!(
                "PRAGMA {what} must be a positive finite number, got `{s}`"
            ))
        })?,
        Expr::Column(col_ref, _) if col_ref.table.is_none() => {
            col_ref.column.parse::<f64>().map_err(|_| {
                FrankenError::Internal(format!(
                    "PRAGMA {what} must be a positive finite number, got `{}`",
                    col_ref.column
                ))
            })?
        }
        _ => {
            return Err(FrankenError::Internal(format!(
                "PRAGMA {what} must be a positive finite number"
            )));
        }
    };
    if !(raw.is_finite() && raw > 0.0) {
        return Err(FrankenError::Internal(format!(
            "PRAGMA {what} must be > 0 and finite, got {raw}"
        )));
    }
    Ok(raw)
}

/// Parse a PRAGMA value as a finite `f64`.
///
/// Accepts integer and float literals (with optional unary negation), and
/// bare-identifier forms like `PRAGMA fsqlite.retry_slo_alpha = 0.05`
/// where the parser hands back the RHS as an unquoted column reference.
/// Rejects NaN / infinity to keep downstream math well-defined.
fn parse_pragma_float(value: &fsqlite_ast::PragmaValue, what: &str) -> Result<f64> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    let raw: f64 = match expr {
        Expr::Literal(Literal::Integer(n), _) => {
            #[allow(clippy::cast_precision_loss)]
            let f = *n as f64;
            f
        }
        Expr::Literal(Literal::Float(f), _) => *f,
        Expr::UnaryOp {
            op: UnaryOp::Negate,
            expr,
            ..
        } => match expr.as_ref() {
            Expr::Literal(Literal::Integer(n), _) => {
                #[allow(clippy::cast_precision_loss)]
                let f = -(*n as f64);
                f
            }
            Expr::Literal(Literal::Float(f), _) => -*f,
            _ => {
                return Err(FrankenError::Internal(format!(
                    "PRAGMA {what} must be a finite number"
                )));
            }
        },
        Expr::Literal(Literal::String(s), _) => s.parse::<f64>().map_err(|_| {
            FrankenError::Internal(format!("PRAGMA {what} must be a finite number, got `{s}`"))
        })?,
        Expr::Column(col_ref, _) if col_ref.table.is_none() => {
            col_ref.column.parse::<f64>().map_err(|_| {
                FrankenError::Internal(format!(
                    "PRAGMA {what} must be a finite number, got `{}`",
                    col_ref.column
                ))
            })?
        }
        _ => {
            return Err(FrankenError::Internal(format!(
                "PRAGMA {what} must be a finite number"
            )));
        }
    };
    if !raw.is_finite() {
        return Err(FrankenError::Internal(format!(
            "PRAGMA {what} must be finite, got {raw}"
        )));
    }
    Ok(raw)
}

/// Parse a PRAGMA value as an uppercased identifier string.
fn parse_pragma_identifier(value: &fsqlite_ast::PragmaValue, what: &str) -> Result<String> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    let text = match expr {
        Expr::Literal(Literal::String(s), _) => s.clone(),
        Expr::Column(col_ref, _) if col_ref.table.is_none() => col_ref.column.to_string(),
        _ => {
            return Err(FrankenError::Internal(format!(
                "PRAGMA {what} must be an identifier"
            )));
        }
    };
    Ok(text.to_ascii_uppercase())
}

/// Parse a PRAGMA value as a checkpoint mode.
///
/// Accepts `PASSIVE`, `FULL`, `RESTART`, `TRUNCATE` (case-insensitive).
#[cfg(feature = "diagnostic-pragmas")]
const fn checkpoint_mode_code(mode: CheckpointMode) -> i64 {
    match mode {
        CheckpointMode::Passive => 0,
        CheckpointMode::Full => 1,
        CheckpointMode::Restart => 2,
        CheckpointMode::Truncate => 3,
    }
}

#[cfg(feature = "diagnostic-pragmas")]
const fn checkpoint_mode_label(mode: CheckpointMode) -> &'static str {
    match mode {
        CheckpointMode::Passive => "PASSIVE",
        CheckpointMode::Full => "FULL",
        CheckpointMode::Restart => "RESTART",
        CheckpointMode::Truncate => "TRUNCATE",
    }
}

#[cfg(feature = "diagnostic-pragmas")]
const fn checkpoint_schedule_override_label(mode: Option<CheckpointMode>) -> &'static str {
    match mode {
        Some(mode) => checkpoint_mode_label(mode),
        None => "AUTO",
    }
}

#[cfg(feature = "diagnostic-pragmas")]
fn parse_checkpoint_schedule_override_mode(
    value: &fsqlite_ast::PragmaValue,
) -> Result<Option<CheckpointMode>> {
    let expr = match value {
        fsqlite_ast::PragmaValue::Assign(e) | fsqlite_ast::PragmaValue::Call(e) => e,
    };
    let text = match expr {
        Expr::Literal(Literal::String(s), _) => s.clone(),
        Expr::Column(col_ref, _) if col_ref.table.is_none() => col_ref.column.to_string(),
        _ => {
            return Err(FrankenError::Internal(
                "PRAGMA fsqlite_checkpoint_schedule must be AUTO/PASSIVE/FULL/RESTART/TRUNCATE"
                    .to_owned(),
            ));
        }
    };

    match text.to_uppercase().as_str() {
        "AUTO" | "DEFAULT" => Ok(None),
        "PASSIVE" => Ok(Some(CheckpointMode::Passive)),
        "FULL" => Ok(Some(CheckpointMode::Full)),
        "RESTART" => Ok(Some(CheckpointMode::Restart)),
        "TRUNCATE" => Ok(Some(CheckpointMode::Truncate)),
        _ => Err(FrankenError::Internal(format!(
            "PRAGMA fsqlite_checkpoint_schedule must be AUTO/PASSIVE/FULL/RESTART/TRUNCATE, got `{text}`"
        ))),
    }
}

fn parse_database_header(page1_bytes: &[u8]) -> Option<DatabaseHeader> {
    if page1_bytes.iter().all(|&b| b == 0) || page1_bytes.len() < DATABASE_HEADER_SIZE {
        return None;
    }
    let mut header_bytes = [0_u8; DATABASE_HEADER_SIZE];
    header_bytes.copy_from_slice(&page1_bytes[..DATABASE_HEADER_SIZE]);
    DatabaseHeader::from_bytes(&header_bytes).ok()
}

fn parse_database_header_checked(page1_bytes: &[u8]) -> Result<DatabaseHeader> {
    if page1_bytes.iter().all(|&b| b == 0) || page1_bytes.len() < DATABASE_HEADER_SIZE {
        return Err(FrankenError::DatabaseCorrupt {
            detail: "database header missing or truncated".to_owned(),
        });
    }
    let mut header_bytes = [0_u8; DATABASE_HEADER_SIZE];
    header_bytes.copy_from_slice(&page1_bytes[..DATABASE_HEADER_SIZE]);
    DatabaseHeader::from_bytes(&header_bytes).map_err(|err| FrankenError::DatabaseCorrupt {
        detail: format!("database header invalid: {err}"),
    })
}

fn sqlite_master_signature(row: &[SqliteValue]) -> Result<(String, String, String, i64)> {
    if row.len() < 4 {
        return Err(FrankenError::DatabaseCorrupt {
            detail: format!(
                "sqlite_master row has {} columns; expected at least 4",
                row.len()
            ),
        });
    }
    let entry_type = match &row[0] {
        SqliteValue::Text(text) => text.to_ascii_lowercase(),
        other => {
            return Err(FrankenError::DatabaseCorrupt {
                detail: format!("sqlite_master type column has unexpected value {other:?}"),
            });
        }
    };
    let name = match &row[1] {
        SqliteValue::Text(text) => text.clone(),
        other => {
            return Err(FrankenError::DatabaseCorrupt {
                detail: format!("sqlite_master name column has unexpected value {other:?}"),
            });
        }
    };
    let tbl_name = match &row[2] {
        SqliteValue::Text(text) => text.clone(),
        other => {
            return Err(FrankenError::DatabaseCorrupt {
                detail: format!("sqlite_master tbl_name column has unexpected value {other:?}"),
            });
        }
    };
    let root_page = match &row[3] {
        SqliteValue::Integer(value) => *value,
        other => {
            return Err(FrankenError::DatabaseCorrupt {
                detail: format!("sqlite_master rootpage column has unexpected value {other:?}"),
            });
        }
    };
    Ok((
        entry_type,
        name.to_string(),
        tbl_name.to_string(),
        root_page,
    ))
}

fn format_master_signature(signature: &(String, String, String, i64)) -> String {
    format!(
        "(type={}, name={}, tbl_name={}, rootpage={})",
        signature.0, signature.1, signature.2, signature.3
    )
}

fn sqlite_master_sql_text(row: &[SqliteValue]) -> Result<Option<&str>> {
    match row.get(4) {
        Some(SqliteValue::Text(sql)) => Ok(Some(sql.as_ref())),
        Some(SqliteValue::Null) | None => Ok(None),
        Some(other) => Err(FrankenError::DatabaseCorrupt {
            detail: format!("sqlite_master sql column has unexpected value {other:?}"),
        }),
    }
}

fn is_implicit_autoindex_entry(name: &str, table_name: &str, sql: Option<&str>) -> bool {
    sql.is_none() && parse_autoindex_ordinal(name, table_name).is_some()
}

fn is_virtual_table_sql(sql: &str) -> bool {
    sql.trim_start()
        .to_ascii_uppercase()
        .starts_with("CREATE VIRTUAL TABLE")
}

fn virtual_table_shadow_drop_names(table_name: &str, sql: &str) -> Vec<String> {
    let Ok(Statement::CreateVirtualTable(stmt)) = parse_single_statement(sql) else {
        return Vec::new();
    };
    let module = stmt.module.to_ascii_lowercase();
    match module.as_str() {
        "fts5" => fts5_shadow_drop_names(table_name, &stmt.args),
        "fts4" => fts4_shadow_drop_names(table_name, &stmt.args),
        "fts3" => vec![
            format!("{table_name}_content"),
            format!("{table_name}_segments"),
            format!("{table_name}_segdir"),
        ],
        "rtree" | "rtree_i32" => vec![
            format!("{table_name}_node"),
            format!("{table_name}_rowid"),
            format!("{table_name}_parent"),
        ],
        _ => Vec::new(),
    }
}

fn fts5_shadow_drop_names(table_name: &str, args: &[String]) -> Vec<String> {
    let mut names = vec![
        format!("{table_name}_data"),
        format!("{table_name}_idx"),
        format!("{table_name}_config"),
    ];
    if virtual_table_option_value(args, "content").is_none() {
        names.push(format!("{table_name}_content"));
    }
    if !matches!(
        virtual_table_option_value(args, "columnsize").as_deref(),
        Some("0")
    ) {
        names.push(format!("{table_name}_docsize"));
    }
    names
}

#[cfg(feature = "ext-fts5")]
fn fts5_shadow_table_defs(
    table_name: &str,
    args: &[String],
    fts_columns: &[ColumnInfo],
) -> Vec<Fts5ShadowTableDef> {
    let data_name = format!("{table_name}_data");
    let idx_name = format!("{table_name}_idx");
    let config_name = format!("{table_name}_config");
    let mut defs = vec![
        Fts5ShadowTableDef {
            create_sql: format!(
                "CREATE TABLE {}(id INTEGER PRIMARY KEY, block BLOB)",
                quote_identifier(&data_name)
            ),
            name: data_name,
        },
        Fts5ShadowTableDef {
            create_sql: format!(
                "CREATE TABLE {}(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
                quote_identifier(&idx_name)
            ),
            name: idx_name,
        },
        Fts5ShadowTableDef {
            create_sql: format!(
                "CREATE TABLE {}(k PRIMARY KEY, v) WITHOUT ROWID",
                quote_identifier(&config_name)
            ),
            name: config_name,
        },
    ];

    if virtual_table_option_value(args, "content").is_none() {
        let content_name = format!("{table_name}_content");
        let content_columns = (0..fts_columns.len())
            .map(|idx| format!("c{idx}"))
            .collect::<Vec<_>>()
            .join(", ");
        let create_sql = if content_columns.is_empty() {
            format!(
                "CREATE TABLE {}(id INTEGER PRIMARY KEY)",
                quote_identifier(&content_name)
            )
        } else {
            format!(
                "CREATE TABLE {}(id INTEGER PRIMARY KEY, {content_columns})",
                quote_identifier(&content_name)
            )
        };
        defs.push(Fts5ShadowTableDef {
            create_sql,
            name: content_name,
        });
    }

    if !matches!(
        virtual_table_option_value(args, "columnsize").as_deref(),
        Some("0")
    ) {
        let docsize_name = format!("{table_name}_docsize");
        let contentless_delete = matches!(
            virtual_table_option_value(args, "contentless_delete").as_deref(),
            Some("1")
        );
        let columns = if contentless_delete {
            "id INTEGER PRIMARY KEY, sz BLOB, origin INTEGER"
        } else {
            "id INTEGER PRIMARY KEY, sz BLOB"
        };
        defs.push(Fts5ShadowTableDef {
            create_sql: format!(
                "CREATE TABLE {}({columns})",
                quote_identifier(&docsize_name)
            ),
            name: docsize_name,
        });
    }

    defs
}

fn fts4_shadow_drop_names(table_name: &str, args: &[String]) -> Vec<String> {
    let mut names = Vec::new();
    if virtual_table_option_value(args, "content").is_none() {
        names.push(format!("{table_name}_content"));
    }
    names.extend([
        format!("{table_name}_segments"),
        format!("{table_name}_segdir"),
    ]);
    if !matches!(
        virtual_table_option_value(args, "matchinfo").as_deref(),
        Some("fts3")
    ) {
        names.push(format!("{table_name}_docsize"));
    }
    names.push(format!("{table_name}_stat"));
    names
}

fn virtual_table_option_value(args: &[String], option: &str) -> Option<String> {
    args.iter().find_map(|arg| {
        let (key, value) = arg.split_once('=')?;
        if normalize_virtual_table_option_token(key) == option {
            Some(normalize_virtual_table_option_token(value))
        } else {
            None
        }
    })
}

fn normalize_virtual_table_option_token(token: &str) -> String {
    let trimmed = token.trim();
    if trimmed.len() >= 2 {
        let bytes = trimmed.as_bytes();
        let first = bytes[0];
        let last = bytes[bytes.len() - 1];
        if matches!((first, last), (b'\'', b'\'') | (b'"', b'"') | (b'`', b'`')) {
            let body = &trimmed[1..trimmed.len() - 1];
            let quote = char::from(first);
            return body
                .replace(&format!("{quote}{quote}"), &quote.to_string())
                .to_ascii_lowercase();
        }
        if first == b'[' && last == b']' {
            return trimmed[1..trimmed.len() - 1].to_ascii_lowercase();
        }
    }
    trimmed.to_ascii_lowercase()
}

fn is_without_rowid_table_sql(sql: &str) -> bool {
    crate::compat_persist::is_without_rowid_table_sql(sql)
}

fn should_ignore_expected_master_row_for_integrity(row: &[SqliteValue]) -> Result<bool> {
    let (entry_type, name, table_name, _) = sqlite_master_signature(row)?;
    Ok(entry_type.eq_ignore_ascii_case("index")
        && is_implicit_autoindex_entry(&name, &table_name, sqlite_master_sql_text(row)?))
}

fn should_ignore_actual_master_row_for_integrity(row: &[SqliteValue]) -> Result<bool> {
    let (entry_type, name, table_name, _) = sqlite_master_signature(row)?;
    Ok(entry_type.eq_ignore_ascii_case("index")
        && is_implicit_autoindex_entry(&name, &table_name, sqlite_master_sql_text(row)?))
}

/// Live, transaction-backed [`Fts5OnDiskReader`]: point/range reads of a
/// persisted FTS5 table's shadow b-trees for the lazy query path. Built per
/// query from the query's own transaction so every read shares its snapshot.
/// Cursors are constructed per call and dropped immediately, so the held
/// `&mut` transaction borrow is only live for the duration of one read.
#[cfg(feature = "ext-fts5")]
#[allow(dead_code)] // wired into scan_live_fts5_rows in child bead .4
struct Fts5LiveShadowReader<'a> {
    cx: &'a Cx,
    txn: &'a mut TransactionKind,
    page_size: PageSize,
    reserved_per_page: u8,
    data_root: PageNumber,
    idx_root: Option<PageNumber>,
    docsize_root: Option<PageNumber>,
    content_root: Option<PageNumber>,
    collation_registry: Arc<Mutex<CollationRegistry>>,
}

#[cfg(feature = "ext-fts5")]
#[allow(dead_code)] // wired into scan_live_fts5_rows in child bead .4
impl<'a> Fts5LiveShadowReader<'a> {
    /// Resolve the shadow-table rootpages for `table_name` from `schema` and
    /// build a reader bound to `txn`. `_data` is required; `_idx`/`_docsize`/
    /// `_content` are optional (absent => the corresponding lookups return
    /// `None`, e.g. contentless tables have no `_content`).
    fn new(
        cx: &'a Cx,
        txn: &'a mut TransactionKind,
        page_size: PageSize,
        reserved_per_page: u8,
        schema: &[TableSchema],
        table_name: &str,
        collation_registry: Arc<Mutex<CollationRegistry>>,
    ) -> Result<Self> {
        let resolve = |suffix: &str| -> Result<Option<PageNumber>> {
            let name = format!("{table_name}{suffix}");
            match schema
                .iter()
                .find(|candidate| candidate.name.eq_ignore_ascii_case(&name))
            {
                Some(table) if table.root_page > 0 => Ok(Some(page_number_from_schema_root(
                    table.root_page,
                    &name,
                    "fts5 shadow",
                )?)),
                _ => Ok(None),
            }
        };
        let data_root = resolve("_data")?.ok_or_else(|| FrankenError::DatabaseCorrupt {
            detail: format!("FTS5 table `{table_name}` missing `_data` shadow table"),
        })?;
        Ok(Self::with_roots(
            cx,
            txn,
            page_size,
            reserved_per_page,
            data_root,
            resolve("_idx")?,
            resolve("_docsize")?,
            resolve("_content")?,
            collation_registry,
        ))
    }

    /// Construct directly from already-resolved shadow rootpages (used by tests
    /// and any caller that has the rootpages in hand).
    #[allow(clippy::too_many_arguments)]
    fn with_roots(
        cx: &'a Cx,
        txn: &'a mut TransactionKind,
        page_size: PageSize,
        reserved_per_page: u8,
        data_root: PageNumber,
        idx_root: Option<PageNumber>,
        docsize_root: Option<PageNumber>,
        content_root: Option<PageNumber>,
        collation_registry: Arc<Mutex<CollationRegistry>>,
    ) -> Self {
        Self {
            cx,
            txn,
            page_size,
            reserved_per_page,
            data_root,
            idx_root,
            docsize_root,
            content_root,
            collation_registry,
        }
    }

    /// Seek a rowid table and return the matched row's parsed record values.
    async fn read_table_record(
        &mut self,
        root: PageNumber,
        rowid: i64,
    ) -> Result<Option<Vec<SqliteValue>>> {
        let mut cursor = Connection::new_header_btree_cursor(
            self.txn,
            root,
            self.page_size,
            self.reserved_per_page,
            true,
        );
        if !cursor.table_move_to(self.cx, rowid).await?.is_found() {
            return Ok(None);
        }
        let payload = cursor.payload(self.cx).await?;
        let values = parse_record(&payload).ok_or_else(|| FrankenError::DatabaseCorrupt {
            detail: format!("fts5 shadow row {rowid} payload is not a valid SQLite record"),
        })?;
        Ok(Some(values))
    }
}

#[cfg(feature = "ext-fts5")]
impl Fts5OnDiskReader for Fts5LiveShadowReader<'_> {
    async fn read_data_block(&mut self, id: i64) -> Result<Option<Vec<u8>>> {
        // `_data(id INTEGER PRIMARY KEY, block BLOB)`: the block is the lone
        // stored BLOB (the rowid-alias `id` is not in the record payload).
        let Some(values) = self.read_table_record(self.data_root, id).await? else {
            return Ok(None);
        };
        Ok(values
            .iter()
            .rev()
            .find_map(|value| value.as_blob_bytes().map(<[u8]>::to_vec)))
    }

    async fn read_docsize(
        &mut self,
        rowid: i64,
        column_count: usize,
    ) -> Result<Option<Fts5DocsizeRow>> {
        let Some(root) = self.docsize_root else {
            return Ok(None);
        };
        let Some(values) = self.read_table_record(root, rowid).await? else {
            return Ok(None);
        };
        let blob = values
            .iter()
            .rev()
            .find_map(SqliteValue::as_blob_bytes)
            .unwrap_or(&[]);
        Ok(Some(Fts5DocsizeRow::new(
            rowid,
            decode_docsize_blob(blob, column_count),
        )))
    }

    async fn read_content(
        &mut self,
        rowid: i64,
        column_count: usize,
    ) -> Result<Option<Vec<String>>> {
        let Some(root) = self.content_root else {
            return Ok(None);
        };
        let Some(values) = self.read_table_record(root, rowid).await? else {
            return Ok(None);
        };
        // `_content(id INTEGER PRIMARY KEY, c0, c1, ...)`: the trailing
        // `column_count` values are the column texts (skip any rowid-alias
        // placeholder the record decoder may surface as a leading element).
        let start = values.len().saturating_sub(column_count);
        Ok(Some(
            values[start..].iter().map(SqliteValue::to_text).collect(),
        ))
    }

    async fn idx_candidate_page(&mut self, segid: u32, term: &[u8]) -> Result<Option<u32>> {
        let Some(root) = self.idx_root else {
            return Ok(None);
        };
        // `_idx(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID`.
        // Seek to (segid, term); we want the largest stored key <= it within
        // this segid (the leaf page where `term`'s postings begin).
        let probe = serialize_record(&[
            SqliteValue::Integer(i64::from(segid)),
            SqliteValue::Blob(Arc::from(term)),
        ]);
        let mut cursor = Connection::new_header_btree_index_cursor(
            self.txn,
            root,
            self.page_size,
            self.reserved_per_page,
            vec![false, false],
            vec![None, None],
            Arc::clone(&self.collation_registry),
        );
        cursor.index_move_to(self.cx, &probe).await?;
        // index_move_to lands at the smallest stored key >= probe (or EOF).
        // Decide whether the current row is already <= (segid, term); if not,
        // step back once to the largest key strictly below the probe.
        let mut positioned = !cursor.eof();
        if positioned {
            let payload = cursor.payload(self.cx).await?;
            let values = parse_record(&payload).ok_or_else(|| FrankenError::DatabaseCorrupt {
                detail: "fts5 _idx payload is not a valid SQLite record".to_owned(),
            })?;
            let cur_segid = values.first().map_or(0, SqliteValue::to_integer);
            let cur_term = values
                .get(1)
                .and_then(SqliteValue::as_blob_bytes)
                .unwrap_or(&[]);
            let cur_le = (cur_segid, cur_term) <= (i64::from(segid), term);
            if !cur_le {
                positioned = cursor.prev(self.cx).await?;
            }
        } else {
            positioned = cursor.prev(self.cx).await?;
        }
        if !positioned {
            return Ok(None);
        }
        let payload = cursor.payload(self.cx).await?;
        let values = parse_record(&payload).ok_or_else(|| FrankenError::DatabaseCorrupt {
            detail: "fts5 _idx payload is not a valid SQLite record".to_owned(),
        })?;
        if values.first().map_or(0, SqliteValue::to_integer) != i64::from(segid) {
            return Ok(None); // largest <= key belongs to an earlier segment
        }
        let encoded_pgno = values.get(2).map_or(0, SqliteValue::to_integer);
        let row_term = values
            .get(1)
            .and_then(SqliteValue::as_blob_bytes)
            .map_or_else(Vec::new, <[u8]>::to_vec);
        Ok(Fts5IdxRow::from_encoded_pgno(segid, row_term, encoded_pgno)
            .ok()
            .map(|row| row.btree_page))
    }
}

fn page_number_from_schema_root(
    root_page: i32,
    object_name: &str,
    object_kind: &str,
) -> Result<PageNumber> {
    let raw = u32::try_from(root_page).unwrap_or(0);
    PageNumber::new(raw).ok_or_else(|| FrankenError::DatabaseCorrupt {
        detail: format!("{object_kind} `{object_name}` has invalid root page number {root_page}"),
    })
}

#[allow(clippy::too_many_lines)]
fn compile_expression_select(
    select: &SelectStatement,
    function_registry: Arc<FunctionRegistry>,
) -> Result<VdbeProgram> {
    if !select.body.compounds.is_empty() {
        return Err(FrankenError::NotImplemented(
            "compound SELECT is not supported in this connection path".to_owned(),
        ));
    }

    // bd-l2si0: expand row-value (tuple) comparisons (e.g. `SELECT (1,2) < (1,3)`
    // or `SELECT 1 WHERE (1,NULL) = (1,2)`) into scalar boolean expressions; the
    // table-less expression codegen otherwise cannot lower a bare `RowValue`.
    let rewritten_select = {
        let mut owned = select.clone();
        rewrite_row_value_comparisons_in_select(&mut owned);
        owned
    };
    let select = &rewritten_select;

    let mut builder = ProgramBuilder::new();
    let mut bind_state = BindParamState {
        function_registry: Some(Arc::clone(&function_registry)),
        ..BindParamState::default()
    };
    let init_target = builder.emit_label();
    builder.emit_jump_to_label(Opcode::Init, 0, 0, init_target, P4::None, 0);

    match &select.body.select {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            // DISTINCT is handled post-execution via the collation-aware dedup
            // helper in the caller, so we can safely ignore the `distinct`
            // field here.
            if from.is_some() {
                return Err(FrankenError::NotImplemented(
                    "SELECT ... FROM is not supported in this connection path".to_owned(),
                ));
            }
            if !group_by.is_empty() {
                return Err(FrankenError::NotImplemented(
                    "GROUP BY is not supported in this connection path".to_owned(),
                ));
            }
            if having.is_some() {
                return Err(FrankenError::NotImplemented(
                    "HAVING is not supported in this connection path".to_owned(),
                ));
            }
            if !windows.is_empty() {
                return Err(FrankenError::NotImplemented(
                    "WINDOW is not supported in this connection path".to_owned(),
                ));
            }
            if columns.is_empty() {
                return Err(FrankenError::ParseError {
                    offset: 0,
                    detail: "SELECT must include at least one result column".to_owned(),
                });
            }

            let is_count_star_only = if columns.len() == 1 {
                match &columns[0] {
                    ResultColumn::Expr {
                        expr:
                            Expr::FunctionCall {
                                name,
                                args,
                                distinct,
                                filter,
                                over,
                                ..
                            },
                        ..
                    } if name.eq_ignore_ascii_case("count")
                        && (matches!(args, FunctionArgs::Star)
                            || matches!(args, FunctionArgs::List(v) if v.is_empty()))
                        && function_registry
                            .resolve_application_function(name, 0)
                            .is_none() =>
                    {
                        if *distinct || filter.is_some() || over.is_some() {
                            return Err(FrankenError::NotImplemented(
                                "function modifiers (DISTINCT/FILTER/OVER) are not supported"
                                    .to_owned(),
                            ));
                        }
                        true
                    }
                    _ => false,
                }
            } else {
                false
            };

            if is_count_star_only {
                let out_first_reg = builder.alloc_regs(1);
                if let Some(predicate) = where_clause.as_ref() {
                    let predicate_reg = builder.alloc_temp();
                    emit_expr(&mut builder, predicate, predicate_reg, &mut bind_state)?;
                    let false_label = builder.emit_label();
                    let done_label = builder.emit_label();
                    builder.emit_jump_to_label(
                        Opcode::IfNot,
                        predicate_reg,
                        1,
                        false_label,
                        P4::None,
                        0,
                    );
                    builder.free_temp(predicate_reg);
                    builder.emit_op(Opcode::Integer, 1, out_first_reg, 0, P4::None, 0);
                    builder.emit_jump_to_label(Opcode::Goto, 0, 0, done_label, P4::None, 0);
                    builder.resolve_label(false_label);
                    builder.emit_op(Opcode::Integer, 0, out_first_reg, 0, P4::None, 0);
                    builder.resolve_label(done_label);
                } else {
                    builder.emit_op(Opcode::Integer, 1, out_first_reg, 0, P4::None, 0);
                }
                builder.emit_op(Opcode::ResultRow, out_first_reg, 1, 0, P4::None, 0);
            } else {
                let out_count =
                    i32::try_from(columns.len()).map_err(|_| FrankenError::TooManyColumns {
                        count: columns.len(),
                        max: i32::MAX as usize,
                    })?;
                let out_first_reg = builder.alloc_regs(out_count);
                let skip_row_label = if let Some(predicate) = where_clause.as_ref() {
                    let predicate_reg = builder.alloc_temp();
                    emit_expr(&mut builder, predicate, predicate_reg, &mut bind_state)?;
                    let skip_label = builder.emit_label();
                    builder.emit_jump_to_label(
                        Opcode::IfNot,
                        predicate_reg,
                        1,
                        skip_label,
                        P4::None,
                        0,
                    );
                    builder.free_temp(predicate_reg);
                    Some(skip_label)
                } else {
                    None
                };

                for (idx, column) in columns.iter().enumerate() {
                    let expr = match column {
                        ResultColumn::Expr { expr, .. } => expr,
                        ResultColumn::Star | ResultColumn::TableStar(_) => {
                            return Err(FrankenError::NotImplemented(
                                "star expansion requires name resolution and FROM sources"
                                    .to_owned(),
                            ));
                        }
                    };

                    let idx_i32 = i32::try_from(idx).map_err(|_| FrankenError::OutOfRange {
                        what: "result column index".to_owned(),
                        value: idx.to_string(),
                    })?;
                    let output_reg = out_first_reg + idx_i32;
                    emit_expr(&mut builder, expr, output_reg, &mut bind_state)?;
                }

                builder.emit_op(Opcode::ResultRow, out_first_reg, out_count, 0, P4::None, 0);
                if let Some(skip_label) = skip_row_label {
                    builder.resolve_label(skip_label);
                }
            }
        }
        SelectCore::Values(rows) => {
            if rows.is_empty() {
                return Err(FrankenError::ParseError {
                    offset: 0,
                    detail: "VALUES must include at least one row".to_owned(),
                });
            }
            let first_row_len = rows[0].len();
            if first_row_len == 0 {
                return Err(FrankenError::ParseError {
                    offset: 0,
                    detail: "VALUES row must include at least one expression".to_owned(),
                });
            }
            for row in rows {
                if row.len() != first_row_len {
                    return Err(FrankenError::ParseError {
                        offset: 0,
                        detail: "VALUES rows must have matching column counts".to_owned(),
                    });
                }
            }

            let out_count =
                i32::try_from(first_row_len).map_err(|_| FrankenError::TooManyColumns {
                    count: first_row_len,
                    max: i32::MAX as usize,
                })?;
            let out_first_reg = builder.alloc_regs(out_count);

            for row in rows {
                for (idx, expr) in row.iter().enumerate() {
                    let idx_i32 = i32::try_from(idx).map_err(|_| FrankenError::OutOfRange {
                        what: "VALUES column index".to_owned(),
                        value: idx.to_string(),
                    })?;
                    emit_expr(&mut builder, expr, out_first_reg + idx_i32, &mut bind_state)?;
                }
                builder.emit_op(Opcode::ResultRow, out_first_reg, out_count, 0, P4::None, 0);
            }
        }
    }

    builder.emit_op(Opcode::Halt, 0, 0, 0, P4::None, 0);
    builder.resolve_label(init_target);
    builder.finish()
}

#[allow(clippy::too_many_lines)]
fn emit_expr(
    builder: &mut ProgramBuilder,
    expr: &Expr,
    target_reg: i32,
    bind_state: &mut BindParamState,
) -> Result<()> {
    match expr {
        Expr::Literal(literal, _) => {
            emit_literal(builder, literal, target_reg);
            Ok(())
        }
        Expr::BoundOuterValue { value, .. } => {
            emit_sqlite_value(builder, value, target_reg);
            Ok(())
        }
        Expr::BinaryOp {
            left, op, right, ..
        } => emit_binary_expr(builder, left, *op, right, target_reg, bind_state),
        Expr::UnaryOp { op, expr, .. } => {
            emit_unary_expr(builder, *op, expr, target_reg, bind_state)
        }
        Expr::FunctionCall {
            name,
            args,
            filter,
            over,
            ..
        } => emit_function_call(
            builder,
            name,
            args,
            filter.is_some(),
            over.is_some(),
            target_reg,
            bind_state,
        ),
        Expr::Placeholder(placeholder, _) => {
            let param_index = placeholder_to_index(placeholder, bind_state)?;
            builder.emit_op(Opcode::Variable, param_index, target_reg, 0, P4::None, 0);
            Ok(())
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => emit_case_expr(
            builder,
            operand.as_deref(),
            whens,
            else_expr.as_deref(),
            target_reg,
            bind_state,
        ),
        Expr::Cast {
            expr: inner,
            type_name,
            ..
        } => {
            emit_expr(builder, inner, target_reg, bind_state)?;
            let affinity = type_name_to_affinity(&type_name.name);
            builder.emit_op(
                Opcode::Cast,
                target_reg,
                i32::from(affinity),
                0,
                P4::None,
                0,
            );
            Ok(())
        }
        Expr::IsNull {
            expr: inner, not, ..
        } => {
            emit_expr(builder, inner, target_reg, bind_state)?;
            let lbl_null = builder.emit_label();
            let lbl_done = builder.emit_label();
            builder.emit_jump_to_label(Opcode::IsNull, target_reg, 0, lbl_null, P4::None, 0);
            let val_not_null = i32::from(*not);
            let val_null = i32::from(!*not);
            builder.emit_op(Opcode::Integer, val_not_null, target_reg, 0, P4::None, 0);
            builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_done, P4::None, 0);
            builder.resolve_label(lbl_null);
            builder.emit_op(Opcode::Integer, val_null, target_reg, 0, P4::None, 0);
            builder.resolve_label(lbl_done);
            Ok(())
        }
        // ── BETWEEN: expr [NOT] BETWEEN low AND high ──────────────────
        Expr::Between {
            expr: inner,
            low,
            high,
            not,
            ..
        } => emit_between_expr(builder, inner, low, high, *not, target_reg, bind_state),

        // ── IN: expr [NOT] IN (list) ──────────────────────────────────
        Expr::In {
            expr: inner,
            set,
            not,
            ..
        } => emit_in_expr(builder, inner, set, *not, target_reg, bind_state),

        // ── LIKE/GLOB/MATCH/REGEXP ────────────────────────────────────
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            op,
            not,
            ..
        } => emit_like_expr(
            builder,
            inner,
            pattern,
            escape.as_deref(),
            *op,
            *not,
            target_reg,
            bind_state,
        ),

        // ── COLLATE: transparent wrapper – evaluate inner expression ─
        Expr::Collate { expr: inner, .. } => emit_expr(builder, inner, target_reg, bind_state),

        // ── JSON ->/->> : lower through the SQL-visible operator identity so
        // application registrations can override the operator (bd-m87j8).
        Expr::JsonAccess {
            expr: inner,
            path,
            arrow,
            ..
        } => {
            let func = match arrow {
                JsonArrow::Arrow => "->",
                JsonArrow::DoubleArrow => "->>",
            };
            let args = FunctionArgs::List(vec![inner.as_ref().clone(), path.as_ref().clone()]);
            emit_function_call(builder, func, &args, false, false, target_reg, bind_state)
        }

        _ => Err(FrankenError::NotImplemented(format!(
            "expression form is not supported in this connection path: {expr:?}",
        ))),
    }
}

/// Extract the collation name from a COLLATE expression wrapper, if any.
fn extract_collation(expr: &Expr) -> Option<&str> {
    first_explicit_collation_name(expr)
}

fn fromless_comparison_metadata(left: &Expr, right: &Expr) -> (P4, u16) {
    let collation = join_comparison_collation(left, right, &[]).map_or(P4::None, P4::Collation);
    let affinity = TypeAffinity::comparison_affinity(
        resolve_operand_affinity(left, &[]),
        resolve_operand_affinity(right, &[]),
    )
    .map_or(0, |affinity| u16::from(affinity as u8));
    (collation, affinity)
}

fn fromless_in_comparison_metadata(
    operand: &Expr,
    list_expr: &Expr,
    singleton_constant: bool,
) -> (P4, u16) {
    let collation = if singleton_constant {
        join_comparison_collation(operand, list_expr, &[])
    } else {
        join_expr_effective_collation(operand, &[])
    }
    .map_or(P4::None, P4::Collation);
    let affinity = resolve_operand_affinity(operand, &[]);
    let affinity = if affinity == TypeAffinity::Blob {
        0
    } else {
        u16::from(affinity as u8)
    };
    (collation, affinity)
}

fn emit_binary_expr(
    builder: &mut ProgramBuilder,
    left: &Expr,
    op: BinaryOp,
    right: &Expr,
    target_reg: i32,
    bind_state: &mut BindParamState,
) -> Result<()> {
    let left_reg = builder.alloc_temp();
    let right_reg = builder.alloc_temp();
    emit_expr(builder, left, left_reg, bind_state)?;
    emit_expr(builder, right, right_reg, bind_state)?;

    let opcode = match op {
        BinaryOp::Add => Opcode::Add,
        BinaryOp::Subtract => Opcode::Subtract,
        BinaryOp::Multiply => Opcode::Multiply,
        BinaryOp::Divide => Opcode::Divide,
        BinaryOp::Modulo => Opcode::Remainder,
        BinaryOp::Concat => Opcode::Concat,
        BinaryOp::BitAnd => Opcode::BitAnd,
        BinaryOp::BitOr => Opcode::BitOr,
        BinaryOp::ShiftLeft => Opcode::ShiftLeft,
        BinaryOp::ShiftRight => Opcode::ShiftRight,
        BinaryOp::And => Opcode::And,
        BinaryOp::Or => Opcode::Or,
        // Comparison operators produce 0/1 via conditional jumps.
        BinaryOp::Eq | BinaryOp::Ne | BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge => {
            let cmp_opcode = match op {
                BinaryOp::Eq => Opcode::Eq,
                BinaryOp::Ne => Opcode::Ne,
                BinaryOp::Lt => Opcode::Lt,
                BinaryOp::Le => Opcode::Le,
                BinaryOp::Gt => Opcode::Gt,
                BinaryOp::Ge => Opcode::Ge,
                _ => unreachable!(),
            };
            let (coll_p4, comparison_p5) = fromless_comparison_metadata(left, right);
            // SQL three-valued logic: if either operand is NULL, result is NULL.
            let null_label = builder.emit_label();
            let true_label = builder.emit_label();
            let done_label = builder.emit_label();
            builder.emit_jump_to_label(Opcode::IsNull, left_reg, 0, null_label, P4::None, 0);
            builder.emit_jump_to_label(Opcode::IsNull, right_reg, 0, null_label, P4::None, 0);
            builder.emit_jump_to_label(
                cmp_opcode,
                right_reg,
                left_reg,
                true_label,
                coll_p4,
                comparison_p5,
            );
            builder.emit_op(Opcode::Integer, 0, target_reg, 0, P4::None, 0);
            builder.emit_jump_to_label(Opcode::Goto, 0, 0, done_label, P4::None, 0);
            builder.resolve_label(true_label);
            builder.emit_op(Opcode::Integer, 1, target_reg, 0, P4::None, 0);
            builder.emit_jump_to_label(Opcode::Goto, 0, 0, done_label, P4::None, 0);
            builder.resolve_label(null_label);
            builder.emit_op(Opcode::Null, 0, target_reg, 0, P4::None, 0);
            builder.resolve_label(done_label);
            builder.free_temp(right_reg);
            builder.free_temp(left_reg);
            return Ok(());
        }
        BinaryOp::Is | BinaryOp::IsNot => {
            // IS TRUE / IS FALSE / IS NOT TRUE / IS NOT FALSE → IsTrue opcode.
            if let Some((p3, p4)) = is_true_false_params_core(op, right) {
                builder.emit_op(Opcode::IsTrue, left_reg, target_reg, p3, p4, 0);
                builder.free_temp(right_reg);
                builder.free_temp(left_reg);
                return Ok(());
            }
            let (cmp_opcode, nulleq_flag) = match op {
                BinaryOp::Is => (Opcode::Eq, 0x80_u16),
                BinaryOp::IsNot => (Opcode::Ne, 0x80_u16),
                _ => unreachable!(),
            };
            let (coll_p4, comparison_p5) = fromless_comparison_metadata(left, right);
            let true_label = builder.emit_label();
            let done_label = builder.emit_label();
            builder.emit_jump_to_label(
                cmp_opcode,
                right_reg,
                left_reg,
                true_label,
                coll_p4,
                nulleq_flag | comparison_p5,
            );
            builder.emit_op(Opcode::Integer, 0, target_reg, 0, P4::None, 0);
            builder.emit_jump_to_label(Opcode::Goto, 0, 0, done_label, P4::None, 0);
            builder.resolve_label(true_label);
            builder.emit_op(Opcode::Integer, 1, target_reg, 0, P4::None, 0);
            builder.resolve_label(done_label);
            builder.free_temp(right_reg);
            builder.free_temp(left_reg);
            return Ok(());
        }
    };

    // Engine semantics for these opcodes consume p2 (left) and p1 (right).
    builder.emit_op(opcode, right_reg, left_reg, target_reg, P4::None, 0);
    builder.free_temp(right_reg);
    builder.free_temp(left_reg);
    Ok(())
}

fn emit_unary_expr(
    builder: &mut ProgramBuilder,
    op: UnaryOp,
    expr: &Expr,
    target_reg: i32,
    bind_state: &mut BindParamState,
) -> Result<()> {
    match op {
        UnaryOp::Plus => emit_expr(builder, expr, target_reg, bind_state),
        UnaryOp::BitNot => {
            let source_reg = builder.alloc_temp();
            emit_expr(builder, expr, source_reg, bind_state)?;
            builder.emit_op(Opcode::BitNot, source_reg, target_reg, 0, P4::None, 0);
            builder.free_temp(source_reg);
            Ok(())
        }
        UnaryOp::Not => {
            let source_reg = builder.alloc_temp();
            emit_expr(builder, expr, source_reg, bind_state)?;
            builder.emit_op(Opcode::Not, source_reg, target_reg, 0, P4::None, 0);
            builder.free_temp(source_reg);
            Ok(())
        }
        UnaryOp::Negate => {
            let source_reg = builder.alloc_temp();
            let neg_one_reg = builder.alloc_temp();
            emit_expr(builder, expr, source_reg, bind_state)?;
            builder.emit_op(Opcode::Integer, -1, neg_one_reg, 0, P4::None, 0);
            // target = source * (-1)  (preserves IEEE 754 negative zero)
            builder.emit_op(
                Opcode::Multiply,
                neg_one_reg,
                source_reg,
                target_reg,
                P4::None,
                0,
            );
            builder.free_temp(neg_one_reg);
            builder.free_temp(source_reg);
            Ok(())
        }
    }
}

/// Emit a scalar function call as a `PureFunc` opcode.
///
/// Layout: arguments are evaluated into consecutive registers starting at
/// `first_arg_reg`. The opcode carries `P4::FuncName(name)`, with `p2` =
/// first arg register, `p3` = output register, and `p5` = arg count. The
/// VDBE engine looks up the function by name in its `FunctionRegistry`.
#[allow(clippy::fn_params_excessive_bools, clippy::too_many_arguments)]
fn emit_function_call(
    builder: &mut ProgramBuilder,
    name: &str,
    args: &FunctionArgs,
    has_filter: bool,
    has_over: bool,
    target_reg: i32,
    bind_state: &mut BindParamState,
) -> Result<()> {
    if has_filter || has_over {
        return Err(FrankenError::NotImplemented(
            "function modifiers (FILTER/OVER) are not supported".to_owned(),
        ));
    }

    let arguments: &[Expr] = match args {
        FunctionArgs::List(arguments) => arguments,
        FunctionArgs::Star => &[],
    };

    let arg_count = arguments.len();
    let arg_count_u16 = u16::try_from(arg_count).map_err(|_| FrankenError::TooManyArguments {
        name: name.to_owned(),
    })?;

    #[allow(clippy::cast_possible_wrap, clippy::cast_possible_truncation)]
    let first_arg_reg = builder.alloc_regs(arg_count as i32);

    // Evaluate each argument into consecutive registers.
    for (i, arg_expr) in arguments.iter().enumerate() {
        #[allow(clippy::cast_possible_wrap, clippy::cast_possible_truncation)]
        let reg = first_arg_reg + i as i32;
        emit_expr(builder, arg_expr, reg, bind_state)?;
    }

    // Collation-consuming scalars search their arguments from left to right.
    // The contract belongs to the exact registry entry, so an opaque custom
    // replacement of a built-in keeps its own semantics and a custom
    // collation-aware scalar receives the selected collation.
    let canonical_name = name.to_ascii_uppercase();
    let consumes_argument_collation = bind_state
        .function_registry
        .as_ref()
        .and_then(|registry| {
            registry.scalar_consumes_argument_collation(&canonical_name, i32::from(arg_count_u16))
        })
        .unwrap_or(false);
    let selected_collation = if consumes_argument_collation {
        arguments
            .iter()
            .find_map(|argument| join_expr_defining_collation(argument, &[]))
    } else {
        None
    };
    let p4 = match selected_collation {
        Some(collation) => P4::FuncNameCollated(canonical_name, collation),
        None => P4::FuncName(canonical_name),
    };
    builder.emit_op(
        Opcode::PureFunc,
        0,
        first_arg_reg,
        target_reg,
        p4,
        arg_count_u16,
    );
    Ok(())
}

fn emit_literal(builder: &mut ProgramBuilder, literal: &Literal, target_reg: i32) {
    match literal {
        Literal::Integer(value) => {
            if let Ok(as_i32) = i32::try_from(*value) {
                builder.emit_op(Opcode::Integer, as_i32, target_reg, 0, P4::None, 0);
            } else {
                builder.emit_op(Opcode::Int64, 0, target_reg, 0, P4::Int64(*value), 0);
            }
        }
        Literal::Float(value) => {
            builder.emit_op(Opcode::Real, 0, target_reg, 0, P4::Real(*value), 0);
        }
        Literal::String(value) => {
            builder.emit_op(Opcode::String8, 0, target_reg, 0, P4::Str(value.clone()), 0);
        }
        Literal::Null => {
            builder.emit_op(Opcode::Null, 0, target_reg, 0, P4::None, 0);
        }
        Literal::CurrentTime | Literal::CurrentDate | Literal::CurrentTimestamp => {
            builder.emit_op(
                Opcode::String8,
                0,
                target_reg,
                0,
                P4::Str(current_utc_literal_text(literal)),
                0,
            );
        }
        Literal::True => {
            builder.emit_op(Opcode::Integer, 1, target_reg, 0, P4::None, 0);
        }
        Literal::False => {
            builder.emit_op(Opcode::Integer, 0, target_reg, 0, P4::None, 0);
        }
        Literal::Blob(value) => {
            builder.emit_op(Opcode::Blob, 0, target_reg, 0, P4::Blob(value.clone()), 0);
        }
    }
}

fn emit_sqlite_value(builder: &mut ProgramBuilder, value: &SqliteValue, target_reg: i32) {
    match value {
        SqliteValue::Null => {
            builder.emit_op(Opcode::Null, 0, target_reg, 0, P4::None, 0);
        }
        SqliteValue::Integer(value) => {
            if let Ok(as_i32) = i32::try_from(*value) {
                builder.emit_op(Opcode::Integer, as_i32, target_reg, 0, P4::None, 0);
            } else {
                builder.emit_op(Opcode::Int64, 0, target_reg, 0, P4::Int64(*value), 0);
            }
        }
        SqliteValue::Float(value) => {
            builder.emit_op(Opcode::Real, 0, target_reg, 0, P4::Real(*value), 0);
        }
        SqliteValue::Text(value) => {
            builder.emit_op(
                Opcode::String8,
                0,
                target_reg,
                0,
                P4::Str(value.to_string()),
                0,
            );
        }
        SqliteValue::Blob(value) => {
            builder.emit_op(Opcode::Blob, 0, target_reg, 0, P4::Blob(value.to_vec()), 0);
        }
    }
}

fn current_utc_literal_text(literal: &Literal) -> String {
    let secs = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    let days = secs / 86_400;
    let day_secs = secs % 86_400;
    let hour = day_secs / 3_600;
    let minute = (day_secs % 3_600) / 60;
    let second = day_secs % 60;
    let (year, month, day) = epoch_days_to_ymd(days);

    match literal {
        Literal::CurrentTimestamp => {
            format!("{year:04}-{month:02}-{day:02} {hour:02}:{minute:02}:{second:02}")
        }
        Literal::CurrentDate => format!("{year:04}-{month:02}-{day:02}"),
        Literal::CurrentTime => format!("{hour:02}:{minute:02}:{second:02}"),
        _ => unreachable!("non-current-time literal passed to current_utc_literal_text"),
    }
}

fn epoch_days_to_ymd(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    if month <= 2 {
        year += 1;
    }
    (year, month, day)
}

#[derive(Clone)]
struct BindParamState {
    next_index: i32,
    named_indices: HashMap<NamedPlaceholderKey, i32>,
    function_registry: Option<Arc<FunctionRegistry>>,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct NamedPlaceholderKey {
    prefix: char,
    name: String,
}

impl Default for BindParamState {
    fn default() -> Self {
        Self {
            next_index: 1,
            named_indices: HashMap::new(),
            function_registry: None,
        }
    }
}

impl BindParamState {
    fn claim_anonymous(&mut self) -> Result<i32> {
        let index = self.next_index;
        if index <= 0 || u32::try_from(index).map_or(true, |n| n > MAX_VARIABLE_NUMBER) {
            return Err(FrankenError::OutOfRange {
                what: "placeholder index".to_owned(),
                value: index.to_string(),
            });
        }
        self.next_index =
            self.next_index
                .checked_add(1)
                .ok_or_else(|| FrankenError::OutOfRange {
                    what: "placeholder index".to_owned(),
                    value: index.to_string(),
                })?;
        Ok(index)
    }

    fn register_numbered(&mut self, index: i32) -> Result<i32> {
        if index <= 0 || u32::try_from(index).map_or(true, |n| n > MAX_VARIABLE_NUMBER) {
            return Err(FrankenError::OutOfRange {
                what: "placeholder index".to_owned(),
                value: index.to_string(),
            });
        }
        let next = index
            .checked_add(1)
            .ok_or_else(|| FrankenError::OutOfRange {
                what: "placeholder index".to_owned(),
                value: index.to_string(),
            })?;
        self.next_index = self.next_index.max(next);
        Ok(index)
    }

    fn register_named(&mut self, prefix: char, name: &str) -> Result<i32> {
        let key = NamedPlaceholderKey {
            prefix,
            name: name.to_owned(),
        };
        if let Some(index) = self.named_indices.get(&key) {
            return Ok(*index);
        }

        let index = self.claim_anonymous()?;
        self.named_indices.insert(key, index);
        Ok(index)
    }
}

fn placeholder_to_index(
    placeholder: &PlaceholderType,
    bind_state: &mut BindParamState,
) -> Result<i32> {
    match placeholder {
        PlaceholderType::Anonymous => bind_state.claim_anonymous(),
        PlaceholderType::Numbered(index) => {
            let index = i32::try_from(*index).map_err(|_| FrankenError::OutOfRange {
                what: "placeholder index".to_owned(),
                value: index.to_string(),
            })?;
            bind_state.register_numbered(index)
        }
        PlaceholderType::ColonNamed(name) => bind_state.register_named(':', name),
        PlaceholderType::AtNamed(name) => bind_state.register_named('@', name),
        PlaceholderType::DollarNamed(name) => bind_state.register_named('$', name),
    }
}

fn canonicalize_update_placeholders(
    update: &fsqlite_ast::UpdateStatement,
) -> Result<fsqlite_ast::UpdateStatement> {
    let mut normalized = update.clone();
    let mut bind_state = BindParamState::default();

    if let Some(with_clause) = &mut normalized.with {
        for cte in &mut with_clause.ctes {
            canonicalize_select_placeholders_in_statement(&mut cte.query, &mut bind_state)?;
        }
    }
    for assignment in &mut normalized.assignments {
        canonicalize_expr_placeholders(&mut assignment.value, &mut bind_state)?;
    }
    if let Some(from_clause) = &mut normalized.from {
        canonicalize_placeholders_in_from_clause(from_clause, &mut bind_state)?;
    }
    if let Some(where_clause) = &mut normalized.where_clause {
        canonicalize_expr_placeholders(where_clause, &mut bind_state)?;
    }
    for column in &mut normalized.returning {
        if let ResultColumn::Expr { expr, .. } = column {
            canonicalize_expr_placeholders(expr, &mut bind_state)?;
        }
    }
    for ordering in &mut normalized.order_by {
        canonicalize_expr_placeholders(&mut ordering.expr, &mut bind_state)?;
    }
    if let Some(limit_clause) = &mut normalized.limit {
        canonicalize_expr_placeholders(&mut limit_clause.limit, &mut bind_state)?;
        if let Some(offset) = &mut limit_clause.offset {
            canonicalize_expr_placeholders(offset, &mut bind_state)?;
        }
    }

    Ok(normalized)
}

fn canonicalize_select_placeholders(select: &SelectStatement) -> Result<SelectStatement> {
    let mut normalized = select.clone();
    let mut bind_state = BindParamState::default();
    canonicalize_select_placeholders_in_statement(&mut normalized, &mut bind_state)?;
    Ok(normalized)
}

fn canonicalize_select_placeholders_in_statement(
    select: &mut SelectStatement,
    bind_state: &mut BindParamState,
) -> Result<()> {
    if let Some(with_clause) = &mut select.with {
        for cte in &mut with_clause.ctes {
            canonicalize_select_placeholders_in_statement(&mut cte.query, bind_state)?;
        }
    }

    canonicalize_select_placeholders_in_core(&mut select.body.select, bind_state)?;
    for (_, core) in &mut select.body.compounds {
        canonicalize_select_placeholders_in_core(core, bind_state)?;
    }

    for ordering in &mut select.order_by {
        canonicalize_expr_placeholders(&mut ordering.expr, bind_state)?;
    }
    if let Some(limit_clause) = &mut select.limit {
        canonicalize_expr_placeholders(&mut limit_clause.limit, bind_state)?;
        if let Some(offset) = &mut limit_clause.offset {
            canonicalize_expr_placeholders(offset, bind_state)?;
        }
    }

    Ok(())
}

fn canonicalize_select_placeholders_in_core(
    core: &mut SelectCore,
    bind_state: &mut BindParamState,
) -> Result<()> {
    match core {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            for column in columns {
                if let ResultColumn::Expr { expr, .. } = column {
                    canonicalize_expr_placeholders(expr, bind_state)?;
                }
            }
            if let Some(from_clause) = from {
                canonicalize_placeholders_in_from_clause(from_clause, bind_state)?;
            }
            if let Some(predicate) = where_clause {
                canonicalize_expr_placeholders(predicate, bind_state)?;
            }
            for expr in group_by {
                canonicalize_expr_placeholders(expr, bind_state)?;
            }
            if let Some(predicate) = having {
                canonicalize_expr_placeholders(predicate, bind_state)?;
            }
            for window in windows {
                canonicalize_placeholders_in_window_spec(&mut window.spec, bind_state)?;
            }
        }
        SelectCore::Values(rows) => {
            for row in rows.iter_mut() {
                for expr in row {
                    canonicalize_expr_placeholders(expr, bind_state)?;
                }
            }
        }
    }
    Ok(())
}

fn canonicalize_placeholders_in_from_clause(
    from: &mut fsqlite_ast::FromClause,
    bind_state: &mut BindParamState,
) -> Result<()> {
    canonicalize_placeholders_in_table_or_subquery(&mut from.source, bind_state)?;
    for join in &mut from.joins {
        canonicalize_placeholders_in_table_or_subquery(&mut join.table, bind_state)?;
        if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
            canonicalize_expr_placeholders(expr, bind_state)?;
        }
    }
    Ok(())
}

fn canonicalize_placeholders_in_table_or_subquery(
    source: &mut TableOrSubquery,
    bind_state: &mut BindParamState,
) -> Result<()> {
    match source {
        TableOrSubquery::Table { .. } => {}
        TableOrSubquery::Subquery { query, .. } => {
            canonicalize_select_placeholders_in_statement(query, bind_state)?;
        }
        TableOrSubquery::TableFunction { args, .. } => {
            for arg in args {
                canonicalize_expr_placeholders(arg, bind_state)?;
            }
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            canonicalize_placeholders_in_from_clause(from_clause, bind_state)?;
        }
    }
    Ok(())
}

fn canonicalize_placeholders_in_window_spec(
    spec: &mut fsqlite_ast::WindowSpec,
    bind_state: &mut BindParamState,
) -> Result<()> {
    for expr in &mut spec.partition_by {
        canonicalize_expr_placeholders(expr, bind_state)?;
    }
    for ordering in &mut spec.order_by {
        canonicalize_expr_placeholders(&mut ordering.expr, bind_state)?;
    }
    if let Some(frame) = &mut spec.frame {
        canonicalize_placeholders_in_frame_bound(&mut frame.start, bind_state)?;
        if let Some(end) = &mut frame.end {
            canonicalize_placeholders_in_frame_bound(end, bind_state)?;
        }
    }
    Ok(())
}

fn canonicalize_placeholders_in_frame_bound(
    bound: &mut fsqlite_ast::FrameBound,
    bind_state: &mut BindParamState,
) -> Result<()> {
    match bound {
        fsqlite_ast::FrameBound::Preceding(expr) | fsqlite_ast::FrameBound::Following(expr) => {
            canonicalize_expr_placeholders(expr, bind_state)?;
        }
        fsqlite_ast::FrameBound::UnboundedPreceding
        | fsqlite_ast::FrameBound::CurrentRow
        | fsqlite_ast::FrameBound::UnboundedFollowing => {}
    }
    Ok(())
}

fn canonicalize_expr_placeholders(expr: &mut Expr, bind_state: &mut BindParamState) -> Result<()> {
    match expr {
        Expr::BinaryOp { left, right, .. } => {
            canonicalize_expr_placeholders(left, bind_state)?;
            canonicalize_expr_placeholders(right, bind_state)?;
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. } => {
            canonicalize_expr_placeholders(inner, bind_state)?;
        }
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            canonicalize_expr_placeholders(inner, bind_state)?;
            canonicalize_expr_placeholders(low, bind_state)?;
            canonicalize_expr_placeholders(high, bind_state)?;
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            canonicalize_expr_placeholders(inner, bind_state)?;
            match set {
                fsqlite_ast::InSet::List(values) => {
                    for value in values {
                        canonicalize_expr_placeholders(value, bind_state)?;
                    }
                }
                fsqlite_ast::InSet::Subquery(query) => {
                    canonicalize_select_placeholders_in_statement(query, bind_state)?;
                }
                fsqlite_ast::InSet::Table(_) => {}
            }
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            canonicalize_expr_placeholders(inner, bind_state)?;
            canonicalize_expr_placeholders(pattern, bind_state)?;
            if let Some(escape_expr) = escape {
                canonicalize_expr_placeholders(escape_expr, bind_state)?;
            }
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(base) = operand {
                canonicalize_expr_placeholders(base, bind_state)?;
            }
            for (when_expr, then_expr) in whens {
                canonicalize_expr_placeholders(when_expr, bind_state)?;
                canonicalize_expr_placeholders(then_expr, bind_state)?;
            }
            if let Some(else_branch) = else_expr {
                canonicalize_expr_placeholders(else_branch, bind_state)?;
            }
        }
        Expr::Subquery(subquery, _) | Expr::Exists { subquery, .. } => {
            canonicalize_select_placeholders_in_statement(subquery, bind_state)?;
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if let FunctionArgs::List(list) = args {
                for arg in list {
                    canonicalize_expr_placeholders(arg, bind_state)?;
                }
            }
            for ordering in order_by {
                canonicalize_expr_placeholders(&mut ordering.expr, bind_state)?;
            }
            if let Some(filter_expr) = filter {
                canonicalize_expr_placeholders(filter_expr, bind_state)?;
            }
            if let Some(window_spec) = over {
                canonicalize_placeholders_in_window_spec(window_spec, bind_state)?;
            }
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => {
            canonicalize_expr_placeholders(inner, bind_state)?;
            canonicalize_expr_placeholders(path, bind_state)?;
        }
        Expr::RowValue(values, _) => {
            for value in values {
                canonicalize_expr_placeholders(value, bind_state)?;
            }
        }
        Expr::Placeholder(placeholder, span) => {
            let index = placeholder_to_index(placeholder, bind_state)?;
            let numbered = u32::try_from(index).map_err(|_| FrankenError::OutOfRange {
                what: "placeholder index".to_owned(),
                value: index.to_string(),
            })?;
            *expr = Expr::Placeholder(PlaceholderType::Numbered(numbered), *span);
        }
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. } => {}
    }
    Ok(())
}

/// Bind SELECT placeholders to literal values for fallback evaluators.
///
/// Fallback JOIN/GROUP BY paths interpret expressions directly instead of
/// executing VDBE `Variable` opcodes, so bind parameters must be substituted
/// into the AST beforehand.
fn bind_placeholders_in_select_for_fallback(
    select: &SelectStatement,
    params: Option<&[SqliteValue]>,
) -> Result<SelectStatement> {
    let params = params.unwrap_or_default();
    let mut bound = select.clone();
    let mut bind_state = BindParamState::default();
    bind_placeholders_in_select_statement(&mut bound, &mut bind_state, params)?;
    // Fallback evaluators apply LIMIT/OFFSET after materialization rather than
    // executing VDBE `MustBeInt`. Re-run the lossless-integer check after
    // placeholder substitution so `LIMIT ?` bound to NULL, a fractional real,
    // non-numeric text, or a blob reports SQLite's datatype mismatch instead
    // of being interpreted as an unlimited result. The validator preserves
    // SQLite's LIMIT-zero short-circuit over OFFSET.
    validate_limit_offset_lossless(&bound)?;
    Ok(bound)
}

fn bind_placeholders_in_select_statement(
    select: &mut SelectStatement,
    bind_state: &mut BindParamState,
    params: &[SqliteValue],
) -> Result<()> {
    if let Some(with_clause) = &mut select.with {
        for cte in &mut with_clause.ctes {
            bind_placeholders_in_select_statement(&mut cte.query, bind_state, params)?;
        }
    }

    bind_placeholders_in_select_core(&mut select.body.select, bind_state, params)?;
    for (_, core) in &mut select.body.compounds {
        bind_placeholders_in_select_core(core, bind_state, params)?;
    }

    for ordering in &mut select.order_by {
        let was_bare_placeholder = matches!(ordering.expr, Expr::Placeholder(_, _));
        bind_placeholders_in_expr(&mut ordering.expr, bind_state, params)?;
        // bd-2fong parity: stock SQLite resolves ORDER BY ordinals
        // SYNTACTICALLY at parse time, so a BOUND parameter is always a
        // constant expression, never a column ordinal (oracle 3.46.1:
        // `... ORDER BY ?` bound to 2 preserves row order while a literal
        // `ORDER BY 2` reorders). Binding just replaced a bare top-level
        // placeholder with a literal; keep an integer result in expression
        // form so the fallback sorters' ordinal classification cannot fire.
        if was_bare_placeholder && let Expr::Literal(Literal::Integer(value), span) = &ordering.expr
        {
            let (value, span) = (*value, *span);
            ordering.expr = Expr::BinaryOp {
                left: Box::new(Expr::Literal(Literal::Integer(0), span)),
                op: BinaryOp::Add,
                right: Box::new(Expr::Literal(Literal::Integer(value), span)),
                span,
            };
        }
    }
    if let Some(limit_clause) = &mut select.limit {
        bind_placeholders_in_expr(&mut limit_clause.limit, bind_state, params)?;
        if let Some(offset) = &mut limit_clause.offset {
            bind_placeholders_in_expr(offset, bind_state, params)?;
        }
    }

    Ok(())
}

fn bind_placeholders_in_select_core(
    core: &mut SelectCore,
    bind_state: &mut BindParamState,
    params: &[SqliteValue],
) -> Result<()> {
    match core {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            for column in columns {
                if let ResultColumn::Expr { expr, .. } = column {
                    bind_placeholders_in_expr(expr, bind_state, params)?;
                }
            }
            if let Some(from_clause) = from {
                bind_placeholders_in_from_clause(from_clause, bind_state, params)?;
            }
            if let Some(predicate) = where_clause {
                bind_placeholders_in_expr(predicate, bind_state, params)?;
            }
            for expr in group_by {
                bind_placeholders_in_expr(expr, bind_state, params)?;
            }
            if let Some(predicate) = having {
                bind_placeholders_in_expr(predicate, bind_state, params)?;
            }
            for window in windows {
                bind_placeholders_in_window_spec(&mut window.spec, bind_state, params)?;
            }
        }
        SelectCore::Values(rows) => {
            for row in rows.iter_mut() {
                for expr in row {
                    bind_placeholders_in_expr(expr, bind_state, params)?;
                }
            }
        }
    }
    Ok(())
}

fn bind_placeholders_in_from_clause(
    from: &mut fsqlite_ast::FromClause,
    bind_state: &mut BindParamState,
    params: &[SqliteValue],
) -> Result<()> {
    bind_placeholders_in_table_or_subquery(&mut from.source, bind_state, params)?;
    for join in &mut from.joins {
        bind_placeholders_in_table_or_subquery(&mut join.table, bind_state, params)?;
        if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
            bind_placeholders_in_expr(expr, bind_state, params)?;
        }
    }
    Ok(())
}

fn bind_placeholders_in_table_or_subquery(
    source: &mut TableOrSubquery,
    bind_state: &mut BindParamState,
    params: &[SqliteValue],
) -> Result<()> {
    match source {
        TableOrSubquery::Table { .. } => {}
        TableOrSubquery::Subquery { query, .. } => {
            bind_placeholders_in_select_statement(query, bind_state, params)?;
        }
        TableOrSubquery::TableFunction { args, .. } => {
            for arg in args {
                bind_placeholders_in_expr(arg, bind_state, params)?;
            }
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            bind_placeholders_in_from_clause(from_clause, bind_state, params)?;
        }
    }
    Ok(())
}

fn bind_placeholders_in_window_spec(
    spec: &mut fsqlite_ast::WindowSpec,
    bind_state: &mut BindParamState,
    params: &[SqliteValue],
) -> Result<()> {
    for expr in &mut spec.partition_by {
        bind_placeholders_in_expr(expr, bind_state, params)?;
    }
    for ordering in &mut spec.order_by {
        bind_placeholders_in_expr(&mut ordering.expr, bind_state, params)?;
    }
    if let Some(frame) = &mut spec.frame {
        bind_placeholders_in_frame_bound(&mut frame.start, bind_state, params)?;
        if let Some(end) = &mut frame.end {
            bind_placeholders_in_frame_bound(end, bind_state, params)?;
        }
    }
    Ok(())
}

fn bind_placeholders_in_frame_bound(
    bound: &mut fsqlite_ast::FrameBound,
    bind_state: &mut BindParamState,
    params: &[SqliteValue],
) -> Result<()> {
    match bound {
        fsqlite_ast::FrameBound::Preceding(expr) | fsqlite_ast::FrameBound::Following(expr) => {
            bind_placeholders_in_expr(expr, bind_state, params)?;
        }
        fsqlite_ast::FrameBound::UnboundedPreceding
        | fsqlite_ast::FrameBound::CurrentRow
        | fsqlite_ast::FrameBound::UnboundedFollowing => {}
    }
    Ok(())
}

fn bind_placeholder_to_literal(
    placeholder: &PlaceholderType,
    bind_state: &mut BindParamState,
    params: &[SqliteValue],
) -> Result<Literal> {
    let param_index = placeholder_to_index(placeholder, bind_state)?;
    let one_based = usize::try_from(param_index).map_err(|_| FrankenError::OutOfRange {
        what: "bind parameter index".to_owned(),
        value: param_index.to_string(),
    })?;
    if one_based == 0 || one_based > params.len() {
        return Err(FrankenError::OutOfRange {
            what: "bind parameter index".to_owned(),
            value: param_index.to_string(),
        });
    }
    Ok(sqlite_value_to_literal(&params[one_based - 1]))
}

fn eval_numbered_placeholder_param(
    placeholder: &PlaceholderType,
    params: Option<&[SqliteValue]>,
) -> Result<SqliteValue> {
    let PlaceholderType::Numbered(index) = placeholder else {
        return Err(FrankenError::Internal(
            "expected canonicalized numbered placeholder".to_owned(),
        ));
    };
    let one_based = usize::try_from(*index).map_err(|_| FrankenError::OutOfRange {
        what: "bind parameter index".to_owned(),
        value: index.to_string(),
    })?;
    let Some(params) = params else {
        return Err(FrankenError::OutOfRange {
            what: "bind parameter index".to_owned(),
            value: index.to_string(),
        });
    };
    if one_based == 0 || one_based > params.len() {
        return Err(FrankenError::OutOfRange {
            what: "bind parameter index".to_owned(),
            value: index.to_string(),
        });
    }
    Ok(params[one_based - 1].clone())
}

fn sqlite_value_to_literal(value: &SqliteValue) -> Literal {
    match value {
        SqliteValue::Null => Literal::Null,
        SqliteValue::Integer(v) => Literal::Integer(*v),
        SqliteValue::Float(v) => Literal::Float(*v),
        SqliteValue::Text(v) => Literal::String(v.to_string()),
        SqliteValue::Blob(v) => Literal::Blob(v.to_vec()),
    }
}

#[allow(clippy::too_many_lines)]
fn bind_trigger_columns_in_statement(statement: &mut Statement, frame: &TriggerFrame) {
    match statement {
        Statement::Select(select) => {
            bind_trigger_columns_in_select_statement(select, frame);
        }
        Statement::Insert(insert) => {
            if let Some(with_clause) = &mut insert.with {
                for cte in &mut with_clause.ctes {
                    bind_trigger_columns_in_select_statement(&mut cte.query, frame);
                }
            }
            match &mut insert.source {
                fsqlite_ast::InsertSource::Values(rows) => {
                    for row in rows {
                        for expr in row {
                            bind_trigger_columns_in_expr(expr, frame);
                        }
                    }
                }
                fsqlite_ast::InsertSource::Select(select) => {
                    bind_trigger_columns_in_select_statement(select, frame);
                }
                fsqlite_ast::InsertSource::DefaultValues => {}
            }
            for upsert in &mut insert.upsert {
                if let Some(target) = &mut upsert.target
                    && let Some(where_clause) = &mut target.where_clause
                {
                    bind_trigger_prefixed_only_in_expr(where_clause, frame);
                }
                if let fsqlite_ast::UpsertAction::Update {
                    assignments,
                    where_clause,
                } = &mut upsert.action
                {
                    for assignment in assignments {
                        bind_trigger_prefixed_only_in_expr(&mut assignment.value, frame);
                    }
                    if let Some(predicate) = where_clause {
                        bind_trigger_prefixed_only_in_expr(predicate, frame);
                    }
                }
            }
            bind_trigger_columns_in_result_columns(&mut insert.returning, frame, true, false);
        }
        Statement::Update(update) => {
            if let Some(with_clause) = &mut update.with {
                for cte in &mut with_clause.ctes {
                    bind_trigger_columns_in_select_statement(&mut cte.query, frame);
                }
            }
            let trigger_table_name_shadowed = update.from.as_ref().is_some_and(|from_clause| {
                from_clause_has_visible_source_named(from_clause, &frame.table_name)
            });
            // In DML trigger bodies, bare column references in SET values
            // and WHERE clauses refer to the DML's target table columns,
            // not to the trigger's NEW/OLD pseudo-columns.  Use the
            // prefix-only variant so only explicit NEW.x / OLD.x refs
            // are replaced with trigger values.
            for assignment in &mut update.assignments {
                bind_trigger_prefixed_only_in_expr(&mut assignment.value, frame);
            }
            if let Some(from_clause) = &mut update.from {
                bind_trigger_columns_in_from_clause(
                    from_clause,
                    frame,
                    trigger_table_name_shadowed,
                );
            }
            if let Some(where_clause) = &mut update.where_clause {
                bind_trigger_prefixed_only_in_expr(where_clause, frame);
            }
            bind_trigger_columns_in_result_columns(&mut update.returning, frame, true, false);
            for ordering in &mut update.order_by {
                bind_trigger_prefixed_only_in_expr(&mut ordering.expr, frame);
            }
            if let Some(limit_clause) = &mut update.limit {
                bind_trigger_prefixed_only_in_expr(&mut limit_clause.limit, frame);
                if let Some(offset) = &mut limit_clause.offset {
                    bind_trigger_prefixed_only_in_expr(offset, frame);
                }
            }
        }
        Statement::Delete(delete) => {
            if let Some(with_clause) = &mut delete.with {
                for cte in &mut with_clause.ctes {
                    bind_trigger_columns_in_select_statement(&mut cte.query, frame);
                }
            }
            if let Some(where_clause) = &mut delete.where_clause {
                bind_trigger_prefixed_only_in_expr(where_clause, frame);
            }
            bind_trigger_columns_in_result_columns(&mut delete.returning, frame, true, false);
            for ordering in &mut delete.order_by {
                bind_trigger_prefixed_only_in_expr(&mut ordering.expr, frame);
            }
            if let Some(limit_clause) = &mut delete.limit {
                bind_trigger_prefixed_only_in_expr(&mut limit_clause.limit, frame);
                if let Some(offset) = &mut limit_clause.offset {
                    bind_trigger_prefixed_only_in_expr(offset, frame);
                }
            }
        }
        Statement::CreateTrigger(create_trigger) => {
            if let Some(when_clause) = &mut create_trigger.when {
                bind_trigger_columns_in_expr(when_clause, frame);
            }
            for body_stmt in &mut create_trigger.body {
                bind_trigger_columns_in_statement(body_stmt, frame);
            }
        }
        _ => {}
    }
}

/// If `expr` is a pseudo-column reference (`NEW.col` / `OLD.col`, or a bare
/// column resolved against the trigger row) that trigger binding will rewrite
/// to a literal value, return the column identifier so it can be preserved as
/// the result column's output name. Returns `None` for anything the binder
/// would leave untouched (real subquery columns, expressions, etc.).
fn trigger_result_column_implied_name(
    expr: &Expr,
    frame: &TriggerFrame,
    prefix_only: bool,
    trigger_table_name_shadowed: bool,
) -> Option<String> {
    let Expr::Column(col_ref, _) = expr else {
        return None;
    };
    let table_prefix = col_ref.table.as_deref();
    if prefix_only {
        // Only explicit OLD/NEW-qualified refs are rewritten in prefix-only
        // scopes; bare names resolve against the enclosing query's tables.
        let is_old_or_new = table_prefix
            .is_some_and(|p| p.eq_ignore_ascii_case("old") || p.eq_ignore_ascii_case("new"));
        if !is_old_or_new {
            return None;
        }
    }
    if trigger_table_name_shadowed
        && table_prefix.is_some_and(|prefix| prefix.eq_ignore_ascii_case(&frame.table_name))
    {
        return None;
    }
    if frame.references_pseudo_column(table_prefix, &col_ref.column) {
        Some(col_ref.column.to_string())
    } else {
        None
    }
}

fn bind_trigger_columns_in_result_columns(
    columns: &mut Vec<ResultColumn>,
    frame: &TriggerFrame,
    prefix_only: bool,
    trigger_table_name_shadowed: bool,
) {
    let mut rewritten = Vec::with_capacity(columns.len());
    for column in std::mem::take(columns) {
        match column {
            ResultColumn::Expr { mut expr, alias } => {
                // A bare `NEW.col` / `OLD.col` (or unqualified pseudo-column) in
                // a SELECT result position projects a column whose output name
                // is the column identifier (`SELECT NEW.x` -> a column named
                // `x`, matching C SQLite). Binding rewrites that reference to a
                // literal value, which would otherwise lose the name and leave
                // the projected column named after the literal. When the user
                // gave no explicit alias, capture the implied name first so an
                // enclosing query (e.g. `SELECT x FROM (SELECT NEW.x) ...`) can
                // still resolve it after the rewrite.
                let alias = alias.or_else(|| {
                    trigger_result_column_implied_name(
                        &expr,
                        frame,
                        prefix_only,
                        trigger_table_name_shadowed,
                    )
                });
                if prefix_only {
                    bind_trigger_prefixed_only_in_expr(&mut expr, frame);
                } else {
                    bind_trigger_columns_in_expr_inner(
                        &mut expr,
                        frame,
                        false,
                        trigger_table_name_shadowed,
                    );
                }
                rewritten.push(ResultColumn::Expr { expr, alias });
            }
            ResultColumn::TableStar(name) => {
                let allow_trigger_table_shorthand = !prefix_only && !trigger_table_name_shadowed;
                if let Some(expanded) =
                    expand_trigger_pseudo_table_star(&name, frame, allow_trigger_table_shorthand)
                {
                    rewritten.extend(expanded);
                } else {
                    rewritten.push(ResultColumn::TableStar(name));
                }
            }
            ResultColumn::Star => rewritten.push(ResultColumn::Star),
        }
    }
    *columns = rewritten;
}

fn expand_trigger_pseudo_table_star(
    name: &QualifiedName,
    frame: &TriggerFrame,
    allow_trigger_table_shorthand: bool,
) -> Option<Vec<ResultColumn>> {
    if name.schema.is_some() {
        return None;
    }
    let prefix = name.name.as_str();
    let is_pseudo_prefix = prefix.eq_ignore_ascii_case("old")
        || prefix.eq_ignore_ascii_case("new")
        || (allow_trigger_table_shorthand && prefix.eq_ignore_ascii_case(&frame.table_name));
    if !is_pseudo_prefix {
        return None;
    }
    frame
        .column_names
        .iter()
        .map(|column_name| {
            frame
                .lookup_value(Some(prefix), column_name)
                .map(|value| ResultColumn::Expr {
                    expr: value_to_literal_expr(value),
                    alias: Some(column_name.clone()),
                })
        })
        .collect::<Option<Vec<_>>>()
}

fn select_statement_has_visible_source_named(select: &SelectStatement, source_name: &str) -> bool {
    select_core_has_visible_source_named(&select.body.select, source_name)
        || select
            .body
            .compounds
            .iter()
            .any(|(_, core)| select_core_has_visible_source_named(core, source_name))
}

fn select_core_has_visible_source_named(core: &SelectCore, source_name: &str) -> bool {
    match core {
        SelectCore::Select { from, .. } => from.as_ref().is_some_and(|from_clause| {
            from_clause_has_visible_source_named(from_clause, source_name)
        }),
        SelectCore::Values(_) => false,
    }
}

fn from_clause_has_visible_source_named(
    from_clause: &fsqlite_ast::FromClause,
    source_name: &str,
) -> bool {
    table_or_subquery_exposes_source_name(&from_clause.source, source_name)
        || from_clause
            .joins
            .iter()
            .any(|join| table_or_subquery_exposes_source_name(&join.table, source_name))
}

fn table_or_subquery_exposes_source_name(source: &TableOrSubquery, source_name: &str) -> bool {
    match source {
        TableOrSubquery::Table { name, alias, .. } => alias
            .as_deref()
            .unwrap_or(&name.name)
            .eq_ignore_ascii_case(source_name),
        TableOrSubquery::Subquery { alias, .. } => alias
            .as_deref()
            .is_some_and(|alias| alias.eq_ignore_ascii_case(source_name)),
        TableOrSubquery::TableFunction { name, alias, .. } => alias
            .as_deref()
            .unwrap_or(name)
            .eq_ignore_ascii_case(source_name),
        TableOrSubquery::ParenJoin(from_clause) => {
            from_clause_has_visible_source_named(from_clause, source_name)
        }
    }
}

fn bind_trigger_columns_in_select_statement(select: &mut SelectStatement, frame: &TriggerFrame) {
    if let Some(with_clause) = &mut select.with {
        for cte in &mut with_clause.ctes {
            bind_trigger_columns_in_select_statement(&mut cte.query, frame);
        }
    }

    let trigger_table_name_shadowed =
        select_statement_has_visible_source_named(select, &frame.table_name);

    bind_trigger_columns_in_select_core(&mut select.body.select, frame);
    for (_, core) in &mut select.body.compounds {
        bind_trigger_columns_in_select_core(core, frame);
    }

    for ordering in &mut select.order_by {
        bind_trigger_columns_in_expr_inner(
            &mut ordering.expr,
            frame,
            false,
            trigger_table_name_shadowed,
        );
    }
    if let Some(limit_clause) = &mut select.limit {
        bind_trigger_columns_in_expr_inner(
            &mut limit_clause.limit,
            frame,
            false,
            trigger_table_name_shadowed,
        );
        if let Some(offset) = &mut limit_clause.offset {
            bind_trigger_columns_in_expr_inner(offset, frame, false, trigger_table_name_shadowed);
        }
    }
}

fn bind_trigger_columns_in_select_core(core: &mut SelectCore, frame: &TriggerFrame) {
    match core {
        SelectCore::Select {
            columns,
            from,
            where_clause,
            group_by,
            having,
            windows,
            ..
        } => {
            let trigger_table_name_shadowed = from.as_ref().is_some_and(|from_clause| {
                from_clause_has_visible_source_named(from_clause, &frame.table_name)
            });
            // A nested SELECT with its own FROM clause introduces a new naming
            // scope: unqualified column references (e.g. `WHERE id = 1` in
            // `(SELECT threshold FROM gate WHERE id = 1)`) bind to the
            // subquery's own tables, NOT to the trigger's NEW/OLD pseudo-row.
            // Only explicit `NEW.`/`OLD.` references are correlated. Without
            // this, a bare `id` was rewritten to the firing row's value,
            // corrupting trigger WHEN/body subqueries (matching C SQLite, which
            // resolves the inner scope first).
            let prefix_only = from.is_some();
            bind_trigger_columns_in_result_columns(
                columns,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
            if let Some(from_clause) = from {
                bind_trigger_columns_in_from_clause(
                    from_clause,
                    frame,
                    trigger_table_name_shadowed,
                );
            }
            if let Some(predicate) = where_clause {
                bind_trigger_columns_in_expr_inner(
                    predicate,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
            for expr in group_by {
                bind_trigger_columns_in_expr_inner(
                    expr,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
            if let Some(predicate) = having {
                bind_trigger_columns_in_expr_inner(
                    predicate,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
            for window in windows {
                bind_trigger_columns_in_window_spec(
                    &mut window.spec,
                    frame,
                    trigger_table_name_shadowed,
                );
            }
        }
        SelectCore::Values(rows) => {
            for row in rows.iter_mut() {
                for expr in row {
                    bind_trigger_columns_in_expr(expr, frame);
                }
            }
        }
    }
}

fn bind_trigger_columns_in_from_clause(
    from: &mut fsqlite_ast::FromClause,
    frame: &TriggerFrame,
    trigger_table_name_shadowed: bool,
) {
    bind_trigger_columns_in_table_or_subquery(&mut from.source, frame, trigger_table_name_shadowed);
    for join in &mut from.joins {
        bind_trigger_columns_in_table_or_subquery(
            &mut join.table,
            frame,
            trigger_table_name_shadowed,
        );
        if let Some(JoinConstraint::On(expr)) = &mut join.constraint {
            bind_trigger_columns_in_expr_inner(expr, frame, false, trigger_table_name_shadowed);
        }
    }
}

fn bind_trigger_columns_in_table_or_subquery(
    source: &mut TableOrSubquery,
    frame: &TriggerFrame,
    trigger_table_name_shadowed: bool,
) {
    match source {
        TableOrSubquery::Table { .. } => {}
        TableOrSubquery::Subquery { query, .. } => {
            bind_trigger_columns_in_select_statement(query, frame);
        }
        TableOrSubquery::TableFunction { args, .. } => {
            for arg in args {
                bind_trigger_columns_in_expr_inner(arg, frame, false, trigger_table_name_shadowed);
            }
        }
        TableOrSubquery::ParenJoin(from_clause) => {
            bind_trigger_columns_in_from_clause(from_clause, frame, trigger_table_name_shadowed);
        }
    }
}

fn bind_trigger_columns_in_window_spec(
    spec: &mut fsqlite_ast::WindowSpec,
    frame: &TriggerFrame,
    trigger_table_name_shadowed: bool,
) {
    for expr in &mut spec.partition_by {
        bind_trigger_columns_in_expr_inner(expr, frame, false, trigger_table_name_shadowed);
    }
    for ordering in &mut spec.order_by {
        bind_trigger_columns_in_expr_inner(
            &mut ordering.expr,
            frame,
            false,
            trigger_table_name_shadowed,
        );
    }
    if let Some(window_frame) = &mut spec.frame {
        bind_trigger_columns_in_frame_bound(
            &mut window_frame.start,
            frame,
            trigger_table_name_shadowed,
        );
        if let Some(end) = &mut window_frame.end {
            bind_trigger_columns_in_frame_bound(end, frame, trigger_table_name_shadowed);
        }
    }
}

fn bind_trigger_columns_in_frame_bound(
    bound: &mut fsqlite_ast::FrameBound,
    frame: &TriggerFrame,
    trigger_table_name_shadowed: bool,
) {
    match bound {
        fsqlite_ast::FrameBound::Preceding(expr) | fsqlite_ast::FrameBound::Following(expr) => {
            bind_trigger_columns_in_expr_inner(expr, frame, false, trigger_table_name_shadowed);
        }
        fsqlite_ast::FrameBound::UnboundedPreceding
        | fsqlite_ast::FrameBound::CurrentRow
        | fsqlite_ast::FrameBound::UnboundedFollowing => {}
    }
}

#[allow(clippy::too_many_lines)]
fn bind_trigger_columns_in_expr(expr: &mut Expr, frame: &TriggerFrame) {
    bind_trigger_columns_in_expr_inner(expr, frame, false, false);
}

/// Like [`bind_trigger_columns_in_expr`], but only replaces column references
/// that have an explicit `OLD.` or `NEW.` prefix.  Bare column references
/// (no qualifier) and table-qualified references (`t.id`) are left untouched
/// so they resolve against the DML's target table at execution time.
///
/// Used for UPDATE/DELETE WHERE and SET clauses inside trigger bodies, where
/// `id` in `WHERE id = NEW.id` must refer to the scan row's column — not be
/// replaced with the trigger pseudo-column value (which would turn the
/// predicate into `WHERE 1 = 1`).
fn bind_trigger_prefixed_only_in_expr(expr: &mut Expr, frame: &TriggerFrame) {
    bind_trigger_columns_in_expr_inner(expr, frame, true, false);
}

#[allow(clippy::too_many_lines)]
fn bind_trigger_columns_in_expr_inner(
    expr: &mut Expr,
    frame: &TriggerFrame,
    prefix_only: bool,
    trigger_table_name_shadowed: bool,
) {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Raise { .. }
        | Expr::Placeholder(_, _) => {}
        Expr::Column(col_ref, _) => {
            let table_prefix = col_ref.table.as_deref();
            if prefix_only {
                // In prefix_only mode (DML WHERE/SET inside trigger bodies),
                // only replace column references with an explicit OLD or NEW
                // qualifier.  Bare names (`id`) and table-qualified names
                // (`t.id`) must resolve against the DML's target table at
                // execution time — they are NOT trigger pseudo-columns.
                let is_old_or_new = table_prefix.is_some_and(|p| {
                    p.eq_ignore_ascii_case("old") || p.eq_ignore_ascii_case("new")
                });
                if !is_old_or_new {
                    return;
                }
            }
            if trigger_table_name_shadowed
                && table_prefix.is_some_and(|prefix| prefix.eq_ignore_ascii_case(&frame.table_name))
            {
                return;
            }
            let column_name = col_ref.column.clone();
            if frame.references_pseudo_column(table_prefix, &column_name)
                && let Some(value) = frame.lookup_value(table_prefix, &column_name)
            {
                *expr = value_to_literal_expr(value);
            }
        }
        Expr::BinaryOp { left, right, .. } => {
            bind_trigger_columns_in_expr_inner(
                left,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
            bind_trigger_columns_in_expr_inner(
                right,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. } => {
            bind_trigger_columns_in_expr_inner(
                inner,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
        }
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            bind_trigger_columns_in_expr_inner(
                inner,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
            bind_trigger_columns_in_expr_inner(
                low,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
            bind_trigger_columns_in_expr_inner(
                high,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            bind_trigger_columns_in_expr_inner(
                inner,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
            match set {
                InSet::List(values) => {
                    for value in values {
                        bind_trigger_columns_in_expr_inner(
                            value,
                            frame,
                            prefix_only,
                            trigger_table_name_shadowed,
                        );
                    }
                }
                InSet::Subquery(query) => {
                    bind_trigger_columns_in_select_statement(query, frame);
                }
                InSet::Table(_) => {}
            }
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            bind_trigger_columns_in_expr_inner(
                inner,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
            bind_trigger_columns_in_expr_inner(
                pattern,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
            if let Some(escape_expr) = escape {
                bind_trigger_columns_in_expr_inner(
                    escape_expr,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(base) = operand {
                bind_trigger_columns_in_expr_inner(
                    base,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
            for (when_expr, then_expr) in whens {
                bind_trigger_columns_in_expr_inner(
                    when_expr,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
                bind_trigger_columns_in_expr_inner(
                    then_expr,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
            if let Some(else_branch) = else_expr {
                bind_trigger_columns_in_expr_inner(
                    else_branch,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
        }
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            bind_trigger_columns_in_select_statement(subquery, frame);
        }
        Expr::FunctionCall {
            args, filter, over, ..
        } => {
            if let FunctionArgs::List(arguments) = args {
                for arg in arguments {
                    bind_trigger_columns_in_expr_inner(
                        arg,
                        frame,
                        prefix_only,
                        trigger_table_name_shadowed,
                    );
                }
            }
            if let Some(filter_expr) = filter {
                bind_trigger_columns_in_expr_inner(
                    filter_expr,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
            if let Some(window_spec) = over {
                bind_trigger_columns_in_window_spec(
                    window_spec,
                    frame,
                    trigger_table_name_shadowed,
                );
            }
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => {
            bind_trigger_columns_in_expr_inner(
                inner,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
            bind_trigger_columns_in_expr_inner(
                path,
                frame,
                prefix_only,
                trigger_table_name_shadowed,
            );
        }
        Expr::RowValue(values, _) => {
            for value in values {
                bind_trigger_columns_in_expr_inner(
                    value,
                    frame,
                    prefix_only,
                    trigger_table_name_shadowed,
                );
            }
        }
    }
}

#[allow(clippy::too_many_lines)]
fn bind_placeholders_in_expr(
    expr: &mut Expr,
    bind_state: &mut BindParamState,
    params: &[SqliteValue],
) -> Result<()> {
    match expr {
        Expr::BoundOuterValue { .. }
        | Expr::Literal(_, _)
        | Expr::Column(_, _)
        | Expr::Raise { .. } => {}
        Expr::BinaryOp { left, right, .. } => {
            bind_placeholders_in_expr(left, bind_state, params)?;
            bind_placeholders_in_expr(right, bind_state, params)?;
        }
        Expr::UnaryOp { expr: inner, .. }
        | Expr::Cast { expr: inner, .. }
        | Expr::Collate { expr: inner, .. }
        | Expr::IsNull { expr: inner, .. } => {
            bind_placeholders_in_expr(inner, bind_state, params)?;
        }
        Expr::Between {
            expr: inner,
            low,
            high,
            ..
        } => {
            bind_placeholders_in_expr(inner, bind_state, params)?;
            bind_placeholders_in_expr(low, bind_state, params)?;
            bind_placeholders_in_expr(high, bind_state, params)?;
        }
        Expr::In {
            expr: inner, set, ..
        } => {
            bind_placeholders_in_expr(inner, bind_state, params)?;
            match set {
                InSet::List(values) => {
                    for value in values {
                        bind_placeholders_in_expr(value, bind_state, params)?;
                    }
                }
                InSet::Subquery(query) => {
                    bind_placeholders_in_select_statement(query, bind_state, params)?;
                }
                InSet::Table(_) => {}
            }
        }
        Expr::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            bind_placeholders_in_expr(inner, bind_state, params)?;
            bind_placeholders_in_expr(pattern, bind_state, params)?;
            if let Some(escape_expr) = escape {
                bind_placeholders_in_expr(escape_expr, bind_state, params)?;
            }
        }
        Expr::Case {
            operand,
            whens,
            else_expr,
            ..
        } => {
            if let Some(base) = operand {
                bind_placeholders_in_expr(base, bind_state, params)?;
            }
            for (when_expr, then_expr) in whens {
                bind_placeholders_in_expr(when_expr, bind_state, params)?;
                bind_placeholders_in_expr(then_expr, bind_state, params)?;
            }
            if let Some(else_branch) = else_expr {
                bind_placeholders_in_expr(else_branch, bind_state, params)?;
            }
        }
        Expr::Exists { subquery, .. } | Expr::Subquery(subquery, _) => {
            bind_placeholders_in_select_statement(subquery, bind_state, params)?;
        }
        Expr::FunctionCall {
            args,
            order_by,
            filter,
            over,
            ..
        } => {
            if let FunctionArgs::List(arguments) = args {
                for arg in arguments {
                    bind_placeholders_in_expr(arg, bind_state, params)?;
                }
            }
            for ordering in order_by {
                bind_placeholders_in_expr(&mut ordering.expr, bind_state, params)?;
            }
            if let Some(filter_expr) = filter {
                bind_placeholders_in_expr(filter_expr, bind_state, params)?;
            }
            if let Some(window_spec) = over {
                bind_placeholders_in_window_spec(window_spec, bind_state, params)?;
            }
        }
        Expr::JsonAccess {
            expr: inner, path, ..
        } => {
            bind_placeholders_in_expr(inner, bind_state, params)?;
            bind_placeholders_in_expr(path, bind_state, params)?;
        }
        Expr::RowValue(values, _) => {
            for value in values {
                bind_placeholders_in_expr(value, bind_state, params)?;
            }
        }
        Expr::Placeholder(placeholder, span) => {
            let literal = bind_placeholder_to_literal(placeholder, bind_state, params)?;
            *expr = Expr::Literal(literal, *span);
        }
    }
    Ok(())
}

fn emit_case_expr(
    builder: &mut ProgramBuilder,
    operand: Option<&Expr>,
    whens: &[(Expr, Expr)],
    else_expr: Option<&Expr>,
    target_reg: i32,
    bind_state: &mut BindParamState,
) -> Result<()> {
    let done_label = builder.emit_label();
    let r_operand = if let Some(op_expr) = operand {
        let r = builder.alloc_temp();
        emit_expr(builder, op_expr, r, bind_state)?;
        Some(r)
    } else {
        None
    };

    for (when_expr, then_expr) in whens {
        let next_when = builder.emit_label();

        if let (Some(r_op), Some(op_expr)) = (r_operand, operand) {
            let r_when = builder.alloc_temp();
            emit_expr(builder, when_expr, r_when, bind_state)?;
            // NULL in either operand or WHEN value means no match
            // (NULL = x is UNKNOWN in SQL, which is falsy for CASE).
            builder.emit_jump_to_label(Opcode::IsNull, r_op, 0, next_when, P4::None, 0);
            builder.emit_jump_to_label(Opcode::IsNull, r_when, 0, next_when, P4::None, 0);
            let (collation, affinity) = fromless_comparison_metadata(op_expr, when_expr);
            builder.emit_jump_to_label(Opcode::Ne, r_when, r_op, next_when, collation, affinity);
            builder.free_temp(r_when);
        } else {
            emit_expr(builder, when_expr, target_reg, bind_state)?;
            builder.emit_jump_to_label(Opcode::IfNot, target_reg, 1, next_when, P4::None, 0);
        }

        emit_expr(builder, then_expr, target_reg, bind_state)?;
        builder.emit_jump_to_label(Opcode::Goto, 0, 0, done_label, P4::None, 0);
        builder.resolve_label(next_when);
    }

    if let Some(el) = else_expr {
        emit_expr(builder, el, target_reg, bind_state)?;
    } else {
        builder.emit_op(Opcode::Null, 0, target_reg, 0, P4::None, 0);
    }

    builder.resolve_label(done_label);

    if let Some(r_op) = r_operand {
        builder.free_temp(r_op);
    }

    Ok(())
}

/// Compile `expr [NOT] BETWEEN low AND high` into comparison opcodes.
///
/// Equivalent to `(expr >= low) AND (expr <= high)`, optionally negated.
fn emit_between_expr(
    builder: &mut ProgramBuilder,
    expr: &Expr,
    low: &Expr,
    high: &Expr,
    not: bool,
    target_reg: i32,
    bind_state: &mut BindParamState,
) -> Result<()> {
    let expr_reg = builder.alloc_temp();
    let low_reg = builder.alloc_temp();
    let high_reg = builder.alloc_temp();

    emit_expr(builder, expr, expr_reg, bind_state)?;
    emit_expr(builder, low, low_reg, bind_state)?;
    emit_expr(builder, high, high_reg, bind_state)?;
    let (low_collation, low_affinity) = fromless_comparison_metadata(expr, low);
    let (high_collation, high_affinity) = fromless_comparison_metadata(expr, high);

    // Three-valued NULL logic for BETWEEN.  BETWEEN is equivalent to
    // (expr >= low) AND (expr <= high) with three-valued AND:
    //   FALSE AND x     = FALSE
    //   NULL  AND TRUE  = NULL
    //   NULL  AND NULL  = NULL
    //   TRUE  AND TRUE  = TRUE
    let lbl_false = builder.emit_label();
    let lbl_null = builder.emit_label();
    let lbl_true = builder.emit_label();
    let lbl_done = builder.emit_label();
    let lbl_low_null = builder.emit_label();

    // If operand is NULL, short-circuit to NULL result.
    builder.emit_jump_to_label(Opcode::IsNull, expr_reg, 0, lbl_null, P4::None, 0);

    // Check: expr >= low.  Ge jumps when true with non-NULL operands.
    let lbl_ge_ok = builder.emit_label();
    builder.emit_jump_to_label(
        Opcode::Ge,
        low_reg,
        expr_reg,
        lbl_ge_ok,
        low_collation,
        low_affinity,
    );
    // Ge didn't fire: either (a) low is NULL, or (b) expr < low → FALSE.
    builder.emit_jump_to_label(Opcode::IsNull, low_reg, 0, lbl_low_null, P4::None, 0);
    builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_false, P4::None, 0);

    // expr >= low confirmed (low is not NULL since Ge fired).
    builder.resolve_label(lbl_ge_ok);
    // Check: expr <= high.
    builder.emit_jump_to_label(
        Opcode::Le,
        high_reg,
        expr_reg,
        lbl_true,
        high_collation.clone(),
        high_affinity,
    );
    // Le didn't fire: either high is NULL → TRUE AND NULL = NULL,
    // or expr > high → FALSE.
    builder.emit_jump_to_label(Opcode::IsNull, high_reg, 0, lbl_null, P4::None, 0);
    builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_false, P4::None, 0);

    // Low was NULL — the >= result is NULL.  Must still evaluate <=
    // because NULL AND FALSE = FALSE (short-circuit on FALSE).
    builder.resolve_label(lbl_low_null);
    let lbl_low_null_le_ok = builder.emit_label();
    builder.emit_jump_to_label(
        Opcode::Le,
        high_reg,
        expr_reg,
        lbl_low_null_le_ok,
        high_collation,
        high_affinity,
    );
    // Le didn't fire: high is NULL → NULL AND NULL = NULL,
    // or expr > high → NULL AND FALSE = FALSE.
    builder.emit_jump_to_label(Opcode::IsNull, high_reg, 0, lbl_null, P4::None, 0);
    builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_false, P4::None, 0);
    // expr <= high confirmed but low was NULL → NULL AND TRUE = NULL.
    builder.resolve_label(lbl_low_null_le_ok);
    builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_null, P4::None, 0);

    // Both conditions satisfied with non-NULL bounds.
    builder.resolve_label(lbl_true);
    builder.emit_op(Opcode::Integer, i32::from(!not), target_reg, 0, P4::None, 0);
    builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_done, P4::None, 0);

    // At least one condition is definitely FALSE.
    builder.resolve_label(lbl_false);
    builder.emit_op(Opcode::Integer, i32::from(not), target_reg, 0, P4::None, 0);
    builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_done, P4::None, 0);

    // NULL involvement without definite FALSE → result is NULL.
    builder.resolve_label(lbl_null);
    builder.emit_op(Opcode::Null, 0, target_reg, 0, P4::None, 0);

    builder.resolve_label(lbl_done);

    builder.free_temp(high_reg);
    builder.free_temp(low_reg);
    builder.free_temp(expr_reg);
    Ok(())
}

/// Compile `expr [NOT] IN (e1, e2, ...)` into a chain of equality checks.
///
/// Only `InSet::List` is supported; subqueries and table references return
/// `NotImplemented`.
fn emit_in_expr(
    builder: &mut ProgramBuilder,
    expr: &Expr,
    set: &InSet,
    not: bool,
    target_reg: i32,
    bind_state: &mut BindParamState,
) -> Result<()> {
    let list = match set {
        InSet::List(list) => list,
        InSet::Subquery(_) => {
            return Err(FrankenError::NotImplemented(
                "IN (SELECT ...) subquery is not yet supported".to_owned(),
            ));
        }
        InSet::Table(_) => {
            return Err(FrankenError::NotImplemented(
                "IN table_name is not yet supported".to_owned(),
            ));
        }
    };

    if list.is_empty() {
        // Empty list: `expr IN ()` is always false, `NOT IN ()` always true.
        let val = i32::from(not);
        builder.emit_op(Opcode::Integer, val, target_reg, 0, P4::None, 0);
        return Ok(());
    }

    let expr_reg = builder.alloc_temp();
    emit_expr(builder, expr, expr_reg, bind_state)?;

    let lbl_null = builder.emit_label();
    let lbl_found = builder.emit_label();
    let lbl_done = builder.emit_label();

    // Three-valued NULL semantics for IN:
    //   NULL IN (...)            → NULL
    //   v IN (a, NULL, b) miss   → NULL  (NULL in list)
    //   v IN (a, b, c) miss      → FALSE (no NULLs)
    //   v IN (...) hit           → TRUE
    builder.emit_jump_to_label(Opcode::IsNull, expr_reg, 0, lbl_null, P4::None, 0);

    // r_saw_null: set to 1 at runtime if any list element is NULL.
    let r_saw_null = builder.alloc_temp();
    builder.emit_op(Opcode::Integer, 0, r_saw_null, 0, P4::None, 0);

    // Check each list element against expr.
    let function_registry = bind_state
        .function_registry
        .as_deref()
        .unwrap_or_else(|| shared_builtin_function_registry().as_ref());
    let singleton_constant = list.len() == 1
        && list
            .first()
            .is_some_and(|element| singleton_in_rhs_is_constant(element, function_registry));
    let elem_reg = builder.alloc_temp();
    for elem in list {
        emit_expr(builder, elem, elem_reg, bind_state)?;
        let (collation, affinity) = fromless_in_comparison_metadata(expr, elem, singleton_constant);
        builder.emit_jump_to_label(
            Opcode::Eq,
            elem_reg,
            expr_reg,
            lbl_found,
            collation,
            affinity,
        );
        // Eq with NULL never jumps.  If this value was NULL, flag it.
        let next_val = builder.emit_label();
        let set_flag = builder.emit_label();
        builder.emit_jump_to_label(Opcode::IsNull, elem_reg, 0, set_flag, P4::None, 0);
        builder.emit_jump_to_label(Opcode::Goto, 0, 0, next_val, P4::None, 0);
        builder.resolve_label(set_flag);
        builder.emit_op(Opcode::Integer, 1, r_saw_null, 0, P4::None, 0);
        builder.resolve_label(next_val);
    }
    builder.free_temp(elem_reg);

    // No match.  If any element was NULL → result is NULL.
    builder.emit_jump_to_label(Opcode::If, r_saw_null, 0, lbl_null, P4::None, 0);
    builder.free_temp(r_saw_null);
    builder.emit_op(Opcode::Integer, i32::from(not), target_reg, 0, P4::None, 0);
    builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_done, P4::None, 0);

    // NULL result.
    builder.resolve_label(lbl_null);
    builder.emit_op(Opcode::Null, 0, target_reg, 0, P4::None, 0);
    builder.emit_jump_to_label(Opcode::Goto, 0, 0, lbl_done, P4::None, 0);

    // Match found.
    builder.resolve_label(lbl_found);
    builder.emit_op(Opcode::Integer, i32::from(!not), target_reg, 0, P4::None, 0);

    builder.resolve_label(lbl_done);
    builder.free_temp(expr_reg);
    Ok(())
}

/// Compile `expr [NOT] LIKE/GLOB pattern [ESCAPE escape]` as a PureFunc call.
///
/// Emits a call to the `like` (or `glob`) scalar function with 2-3 arguments:
/// `like(pattern, expr)` or `like(pattern, expr, escape)`. The result is
/// negated if `not` is true.
#[allow(clippy::too_many_arguments)]
fn emit_like_expr(
    builder: &mut ProgramBuilder,
    expr: &Expr,
    pattern: &Expr,
    escape: Option<&Expr>,
    op: LikeOp,
    not: bool,
    target_reg: i32,
    bind_state: &mut BindParamState,
) -> Result<()> {
    let func_name = match op {
        LikeOp::Like => "LIKE",
        LikeOp::Glob => "GLOB",
        LikeOp::Match => "MATCH",
        LikeOp::Regexp => "REGEXP",
    };

    let has_escape = escape.is_some();
    let arg_count: i32 = if has_escape { 3 } else { 2 };
    let first_arg_reg = builder.alloc_regs(arg_count);

    // SQLite like() takes (pattern, string [, escape]).
    emit_expr(builder, pattern, first_arg_reg, bind_state)?;
    emit_expr(builder, expr, first_arg_reg + 1, bind_state)?;
    if let Some(esc) = escape {
        emit_expr(builder, esc, first_arg_reg + 2, bind_state)?;
    }

    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
    let arg_count_u16 = arg_count as u16;

    let selected_collation = bind_state
        .function_registry
        .as_ref()
        .is_some_and(|registry| {
            registry.scalar_consumes_argument_collation(func_name, arg_count) == Some(true)
        })
        .then(|| {
            [Some(pattern), Some(expr), escape]
                .into_iter()
                .flatten()
                .find_map(|argument| join_expr_defining_collation(argument, &[]))
        })
        .flatten();
    let function = selected_collation.map_or_else(
        || P4::FuncName(func_name.to_owned()),
        |collation| P4::FuncNameCollated(func_name.to_owned(), collation),
    );

    builder.emit_op(
        Opcode::PureFunc,
        0,
        first_arg_reg,
        target_reg,
        function,
        arg_count_u16,
    );

    // Negate the result if NOT LIKE / NOT GLOB.
    if not {
        builder.emit_op(Opcode::Not, target_reg, target_reg, 0, P4::None, 0);
    }

    Ok(())
}

// ──────────────────────────────────────────────────────────────────────────
//  JOIN helpers
// ──────────────────────────────────────────────────────────────────────────

/// Metadata for a table participating in a JOIN.
#[derive(Clone)]
struct JoinTableSource {
    binding_name: Option<QualifiedName>,
    scan_cache_key: String,
    table_name: String,
    alias: Option<String>,
    col_names: Vec<String>,
    hidden_rowid_projection: Option<String>,
}

impl JoinTableSource {
    fn scan_width(&self) -> usize {
        self.col_names.len() + usize::from(self.hidden_rowid_projection.is_some())
    }

    fn local_table_binding(&self) -> Option<&QualifiedName> {
        self.binding_name
            .as_ref()
            .filter(|name| name.schema.as_deref().is_none_or(is_builtin_schema))
    }
}

fn collect_join_using_skip_indices(
    table_sources: &[JoinTableSource],
    joins: &[JoinClause],
) -> HashSet<usize> {
    let mut using_skip_indices = HashSet::new();
    let Some(primary_source) = table_sources.first() else {
        return using_skip_indices;
    };
    let mut offset = primary_source.scan_width();
    for (join_idx, join) in joins.iter().enumerate() {
        let Some(right_src) = table_sources.get(join_idx + 1) else {
            break;
        };
        let using_cols: Option<Vec<&str>> = if join.join_type.natural {
            let left_cols: Vec<&str> = table_sources[..=join_idx]
                .iter()
                .flat_map(|source| source.col_names.iter().map(String::as_str))
                .collect();
            Some(
                right_src
                    .col_names
                    .iter()
                    .filter(|right_col| {
                        left_cols
                            .iter()
                            .any(|left_col| left_col.eq_ignore_ascii_case(right_col))
                    })
                    .map(String::as_str)
                    .collect(),
            )
        } else if let Some(JoinConstraint::Using(cols)) = &join.constraint {
            Some(cols.iter().map(String::as_str).collect())
        } else {
            None
        };
        if let Some(cols) = using_cols {
            for (i, col_name) in right_src.col_names.iter().enumerate() {
                if cols
                    .iter()
                    .any(|using_col| using_col.eq_ignore_ascii_case(col_name))
                {
                    using_skip_indices.insert(offset + i);
                }
            }
        }
        offset += right_src.scan_width();
    }
    using_skip_indices
}

fn join_table_supports_hidden_rowid(
    table_name: &str,
    original_ddl_sql: &HashMap<String, String>,
) -> bool {
    // Ordinary rowid tables expose a hidden rowid/_rowid_/oid column that the
    // join scanner appends to the projection (see build_join_scan_sql). Two
    // table kinds do NOT: WITHOUT ROWID tables, and virtual tables (FTS5, etc.).
    // For virtual tables the scan materializes only the declared columns, so
    // counting an extra hidden-rowid column in scan_width() over-reports the
    // width and makes `row[..primary_width]` slice out of bounds during joins.
    original_ddl_sql
        .get(&table_name.to_ascii_lowercase())
        .is_none_or(|sql| !is_without_rowid_table_sql(sql) && !is_virtual_table_sql(sql))
}

fn join_hidden_rowid_projection(columns: &[String], supports_hidden_rowid: bool) -> Option<String> {
    if !supports_hidden_rowid {
        return None;
    }
    let shadowed: HashSet<String> = columns
        .iter()
        .map(|column| column.to_ascii_lowercase())
        .collect();
    ["rowid", "_rowid_", "oid"]
        .into_iter()
        .find(|candidate| !shadowed.contains(*candidate))
        .map(str::to_owned)
}

fn join_scan_cache_key(name: &QualifiedName) -> String {
    let schema = normalized_attached_schema_name(name.schema.as_deref()).unwrap_or("main");
    format!("table:{schema}:{}", name.name.to_ascii_lowercase())
}

fn build_join_scan_sql(source: &JoinTableSource) -> String {
    let mut projections = source
        .col_names
        .iter()
        .map(|column| quote_identifier(column))
        .collect::<Vec<_>>();
    if let Some(hidden_rowid_projection) = &source.hidden_rowid_projection {
        projections.push(hidden_rowid_projection.clone());
    }
    let scan_name = source.binding_name.as_ref().map_or_else(
        || quote_identifier(&source.table_name),
        quote_qualified_name,
    );
    format!("SELECT {} FROM {}", projections.join(", "), scan_name)
}

