    #[test]
    fn test_implicit_autoindex_classification_requires_provenance_and_canonical_mapping() {
        assert!(is_implicit_autoindex_entry(
            "sqlite_autoindex_link_table_1",
            "link_table",
            None
        ));
        assert!(!is_implicit_autoindex_entry(
            "sqlite_autoindex_link_table_1",
            "link_table",
            Some("CREATE UNIQUE INDEX explicit_name ON link_table(a,b)")
        ));
        assert!(!is_implicit_autoindex_entry(
            "sqlite_autoindex_link_table_v23_1",
            "link_table",
            None
        ));
        assert!(!is_implicit_autoindex_entry(
            "sqlite_autoindex_other_table_1",
            "link_table",
            None
        ));
        assert!(!is_implicit_autoindex_entry(
            "sqlite_autoindex_link_table_0",
            "link_table",
            None
        ));
        for noncanonical in [
            "sqlite_autoindex_link_table_01",
            "sqlite_autoindex_link_table_+1",
            "sqlite_autoindex_link_table_١",
        ] {
            assert!(
                !is_implicit_autoindex_entry(noncanonical, "link_table", None),
                "{noncanonical} must not be classified as a canonical implicit autoindex"
            );
        }
        let overflowing = format!("sqlite_autoindex_link_table_{}0", usize::MAX);
        assert!(!is_implicit_autoindex_entry(
            &overflowing,
            "link_table",
            None
        ));
    }

    #[test]
    fn test_implicit_autoindex_layout_matches_sqlite_declaration_slots() {
        fn layout(sql: &str) -> Result<Vec<ImplicitAutoindexSlot>> {
            let Statement::CreateTable(create) = parse_single_statement(sql)? else {
                panic!("expected CREATE TABLE: {sql}");
            };
            let CreateTableBody::Columns {
                columns,
                constraints,
            } = &create.body
            else {
                panic!("expected column declaration: {sql}");
            };
            implicit_autoindex_layout(columns, constraints, create.without_rowid)
        }

        let signature = |sql: &str| {
            layout(sql)
                .unwrap()
                .into_iter()
                .map(|slot| {
                    (
                        slot.primary_key,
                        slot.hidden_without_rowid_primary_key,
                        slot.definition.columns,
                        slot.definition.key_sort_directions,
                        slot.definition.key_collations,
                    )
                })
                .collect::<Vec<_>>()
        };

        assert_eq!(
            signature("CREATE TABLE t(a TEXT PRIMARY KEY, b TEXT UNIQUE) WITHOUT ROWID"),
            vec![
                (
                    true,
                    true,
                    vec!["a".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
                (
                    false,
                    false,
                    vec!["b".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
            ]
        );
        assert_eq!(
            signature("CREATE TABLE t(a TEXT UNIQUE, b TEXT PRIMARY KEY) WITHOUT ROWID"),
            vec![
                (
                    false,
                    false,
                    vec!["a".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
                (
                    true,
                    true,
                    vec!["b".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
            ]
        );
        assert_eq!(
            signature("CREATE TABLE t(a INTEGER PRIMARY KEY, b UNIQUE) WITHOUT ROWID"),
            vec![
                (
                    false,
                    false,
                    vec!["b".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
                (
                    true,
                    true,
                    vec!["a".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
            ]
        );
        assert_eq!(
            signature("CREATE TABLE t(a INTEGER PRIMARY KEY DESC, b UNIQUE) WITHOUT ROWID"),
            vec![
                (
                    true,
                    true,
                    vec!["a".to_owned()],
                    vec![SortDirection::Desc],
                    vec![None],
                ),
                (
                    false,
                    false,
                    vec!["b".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
            ]
        );
        assert_eq!(
            signature(
                "CREATE TABLE t(a INTEGER COLLATE RTRIM, b UNIQUE, \
                 PRIMARY KEY(a COLLATE NOCASE DESC)) WITHOUT ROWID",
            ),
            vec![
                (
                    false,
                    false,
                    vec!["b".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
                (
                    true,
                    true,
                    vec!["a".to_owned()],
                    vec![SortDirection::Desc],
                    vec![Some("RTRIM".to_owned())],
                ),
            ]
        );
        assert_eq!(
            signature("CREATE TABLE t(a TEXT, UNIQUE(a ASC), PRIMARY KEY(a DESC)) WITHOUT ROWID",),
            vec![(
                true,
                true,
                vec!["a".to_owned()],
                vec![SortDirection::Asc],
                vec![None],
            )]
        );
        assert_eq!(
            signature("CREATE TABLE t(a TEXT, PRIMARY KEY(a, a), UNIQUE(a)) WITHOUT ROWID",).len(),
            2,
            "raw PK term multiplicity participates in slot identity"
        );
        assert_eq!(
            signature("CREATE TABLE t(a TEXT, PRIMARY KEY(a, a), UNIQUE(a, a)) WITHOUT ROWID",)
                .len(),
            1,
            "equivalent repeated-term definitions deduplicate"
        );
        assert_eq!(
            signature(
                "CREATE TABLE t(a TEXT COLLATE NOCASE, UNIQUE(a), UNIQUE(a COLLATE BINARY))",
            )
            .len(),
            2
        );
        assert_eq!(
            signature("CREATE TABLE t(a TEXT, UNIQUE(a), UNIQUE(a COLLATE BINARY))").len(),
            1,
            "implicit BINARY and an omitted collation are equivalent"
        );
        assert_eq!(
            signature("CREATE TABLE t(a TEXT COLLATE NOCASE COLLATE RTRIM UNIQUE)"),
            vec![(
                false,
                false,
                vec!["a".to_owned()],
                vec![SortDirection::Asc],
                vec![Some("RTRIM".to_owned())],
            )],
            "the final column COLLATE clause determines the autoindex collation"
        );
        assert_eq!(
            signature(
                "CREATE TABLE t(a TEXT, b TEXT, \
                 PRIMARY KEY('a'), UNIQUE('b' COLLATE nocase DESC))",
            ),
            vec![
                (
                    true,
                    false,
                    vec!["a".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
                (
                    false,
                    false,
                    vec!["b".to_owned()],
                    vec![SortDirection::Desc],
                    vec![Some("nocase".to_owned())],
                ),
            ],
            "legacy single-quoted indexed terms bind column identifiers"
        );
        assert_eq!(
            signature("CREATE TABLE t(a INTEGER PRIMARY KEY, b UNIQUE)"),
            vec![(
                false,
                false,
                vec!["b".to_owned()],
                vec![SortDirection::Asc],
                vec![None],
            )]
        );
        assert_eq!(
            signature("CREATE TABLE t(a INTEGER(8) PRIMARY KEY, b UNIQUE)"),
            vec![
                (
                    true,
                    false,
                    vec!["a".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
                (
                    false,
                    false,
                    vec!["b".to_owned()],
                    vec![SortDirection::Asc],
                    vec![None],
                ),
            ]
        );

        let conflict = layout(
            "CREATE TABLE t(a TEXT UNIQUE ON CONFLICT IGNORE, \
             UNIQUE(a) ON CONFLICT REPLACE)",
        )
        .unwrap_err();
        assert!(matches!(
            conflict,
            FrankenError::FunctionError(message)
                if message == "conflicting ON CONFLICT clauses specified"
        ));

        let rowid_ipk = layout(
            "CREATE TABLE t(a INTEGER, UNIQUE(a) ON CONFLICT IGNORE, \
             PRIMARY KEY(a) ON CONFLICT FAIL)",
        )
        .unwrap();
        assert_eq!(rowid_ipk.len(), 1);
        assert_eq!(
            rowid_ipk[0].definition.conflict_action,
            Some(fsqlite_ast::ConflictAction::Ignore),
            "a rowid-alias PK consumes no slot and does not conflict with an earlier UNIQUE"
        );
        let without_rowid_conflict = layout(
            "CREATE TABLE t(a INTEGER, UNIQUE(a) ON CONFLICT IGNORE, \
             PRIMARY KEY(a) ON CONFLICT FAIL) WITHOUT ROWID",
        )
        .unwrap_err();
        assert!(matches!(
            without_rowid_conflict,
            FrankenError::FunctionError(message)
                if message == "conflicting ON CONFLICT clauses specified"
        ));

        let expression = layout("CREATE TABLE t(a, UNIQUE(a + 1))").unwrap_err();
        assert!(matches!(
            expression,
            FrankenError::FunctionError(message)
                if message == "expressions prohibited in PRIMARY KEY and UNIQUE constraints"
        ));
        let qualified = layout("CREATE TABLE t(a, UNIQUE(t.a))").unwrap_err();
        assert!(matches!(
            qualified,
            FrankenError::FunctionError(message)
                if message == "expressions prohibited in PRIMARY KEY and UNIQUE constraints"
        ));
        let missing = layout("CREATE TABLE t(a, PRIMARY KEY(missing))").unwrap_err();
        assert!(matches!(
            missing,
            FrankenError::FunctionError(message) if message == "no such column: missing"
        ));
        for duplicate_primary_key in [
            "CREATE TABLE t(a TEXT PRIMARY KEY PRIMARY KEY)",
            "CREATE TABLE t(a INTEGER PRIMARY KEY PRIMARY KEY)",
        ] {
            let error = layout(duplicate_primary_key).unwrap_err();
            assert!(matches!(
                error,
                FrankenError::FunctionError(message)
                    if message == "table has more than one primary key"
            ));
        }
    }

