    #[test]
    fn test_execute_join_select_scans_primary_named_table_without_live_vtab() {
        use asupersync::runtime::RuntimeBuilder;

        let runtime = RuntimeBuilder::new()
            .worker_threads(1)
            .build()
            .expect("runtime build");
        runtime.block_on(async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (x INTEGER)").await.unwrap();
            conn.execute("INSERT INTO t VALUES (1), (2)").await.unwrap();

            let statement = conn
                .cached_parse_single(
                    "SELECT a.x FROM t AS a JOIN t AS b ON a.x = b.x ORDER BY a.x;",
                )
                .unwrap();
            let Statement::Select(select) = statement.as_ref() else {
                panic!("expected SELECT statement");
            };

            let rows = conn.execute_join_select(select, None).await.unwrap();
            assert_eq!(
                rows.iter().map(row_values).collect::<Vec<_>>(),
                vec![vec![SqliteValue::Integer(1)], vec![SqliteValue::Integer(2)],],
            );
        });
    }

    #[test]
    fn test_cass_orphan_not_exists_survives_subquery_rewrite_as_correlated() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let statement = conn
                .cached_parse_single(
                    "SELECT message_id FROM message_metrics \
                 WHERE NOT EXISTS (\
                     SELECT 1 FROM messages \
                     WHERE messages.id = message_metrics.message_id\
                 ) \
                 ORDER BY message_id;",
                )
                .unwrap();
            let Statement::Select(select) = statement.as_ref() else {
                panic!("expected SELECT");
            };

            assert!(
                super::select_has_correlated_exists_in_where(select, &[]),
                "cass orphan cleanup NOT EXISTS must be detected as correlated"
            );

            let rewritten = conn
                .rewrite_subquery_statement(statement.as_ref(), None)
                .await
                .unwrap();
            let Statement::Select(rewritten_select) = rewritten.as_ref() else {
                panic!("expected rewritten SELECT");
            };
            assert!(
                super::select_has_correlated_exists_in_where(rewritten_select, &[]),
                "eager subquery rewrite must leave correlated NOT EXISTS intact"
            );
        });
    }

    #[test]
    fn test_execute_table_program_restores_active_txn_when_op_cx_fails() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (x INTEGER)").await.unwrap();
            let stmt = conn.prepare("SELECT x FROM t").await.unwrap();
            conn.execute("BEGIN").await.unwrap();

            assert!(conn.in_transaction());
            assert!(conn.active_txn.borrow().is_some());

            conn._shared_mvcc_state
                .poison("simulated poisoned runtime for table execution");

            assert!(matches!(
                conn.execute_table_program(&stmt.program, None, false).await,
                Err(FrankenError::BackgroundWorkerFailed(ref msg))
                    if msg.contains("simulated poisoned runtime for table execution")
            ));
            assert!(
                conn.active_txn.borrow().is_some(),
                "failed op_cx must not drop the active pager transaction"
            );
            assert!(
                conn.in_transaction(),
                "connection transaction state must remain consistent after op_cx failure"
            );
        });
    }

    #[test]
    fn test_execute_table_program_direct_wrapper_resyncs_change_tracking_context() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'alpha');")
                .await
                .unwrap();

            fsqlite_func::set_change_tracking_state(fsqlite_func::builtins::ChangeTrackingState {
                last_insert_rowid: -7,
                last_changes: -8,
                total_changes: -9,
            });

            let stmt = conn
                .prepare("SELECT last_insert_rowid(), changes(), total_changes();")
                .await
                .unwrap();
            let (rows, _, _) = conn
                .execute_table_program(&stmt.program, None, false)
                .await
                .unwrap();

            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
            assert_eq!(rows[0].values()[1], SqliteValue::Integer(1));
            assert_eq!(rows[0].values()[2], SqliteValue::Integer(1));
        });
    }

    #[test]
    fn test_close_in_place_cleans_up_poisoned_runtime() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("close-poisoned-runtime.db");
            let db_path = db_path.to_string_lossy().into_owned();

            let mut conn = Connection::open(&db_path).await.unwrap();
            conn.execute("CREATE TABLE t (x INTEGER)").await.unwrap();
            conn.execute("BEGIN").await.unwrap();
            conn.execute("INSERT INTO t VALUES (9)").await.unwrap();

            conn._shared_mvcc_state
                .poison("simulated poisoned runtime for close");

            // Poisoned runtimes may cause release_connection to fail, so use
            // best-effort close which tolerates cleanup errors.
            conn.close_best_effort_in_place().await;

            assert!(*conn.closed.get_mut());
            assert!(!*conn.in_transaction.get_mut());
            assert!(conn.active_txn.get_mut().is_none());
        });
    }

