    #[test]
    fn test_maintenance_statement_stubs_execute_as_noops() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:")
                .await
                .expect("in-memory path should open");
            conn.execute("CREATE TABLE t (id INTEGER);")
                .await
                .expect("CREATE TABLE should succeed");
            conn.execute("INSERT INTO t VALUES (1);")
                .await
                .expect("INSERT should succeed");

            conn.execute("VACUUM;")
                .await
                .expect("VACUUM stub should succeed");
            conn.execute("ANALYZE;")
                .await
                .expect("ANALYZE stub should succeed");
            conn.execute("REINDEX;")
                .await
                .expect("REINDEX stub should succeed");

            let rows = conn
                .query("SELECT COUNT(*) FROM t;")
                .await
                .expect("COUNT should succeed");
            assert_eq!(row_values(&rows[0]), vec![SqliteValue::Integer(1)]);
        });
    }

    #[test]
    fn test_create_virtual_table_fts5_with_match_and_optimize() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE VIRTUAL TABLE docs USING fts5(subject, body, tokenize='porter')")
                .await
                .unwrap();

            conn.execute(
                "INSERT INTO docs(rowid, subject, body) VALUES (1, 'Hello', 'Rust world')",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO docs(rowid, subject, body) VALUES (2, 'Other', 'Nothing')")
                .await
                .unwrap();

            let rows = conn
                .query("SELECT rowid FROM docs WHERE docs MATCH 'hello'")
                .await
                .unwrap();
            assert_eq!(rows.len(), 1, "MATCH should find one matching row");

            let subject_rows = conn
                .query("SELECT rowid FROM docs WHERE docs MATCH 'subject:hello'")
                .await
                .unwrap();
            assert_eq!(
                subject_rows.len(),
                1,
                "column-filter MATCH should find one row"
            );
            assert_eq!(subject_rows[0].get(0), Some(&SqliteValue::Integer(1)));

            let body_rows = conn
                .query("SELECT rowid FROM docs WHERE docs MATCH 'body:rust'")
                .await
                .unwrap();
            assert_eq!(
                body_rows.len(),
                1,
                "body column filter should isolate the body text"
            );
            assert_eq!(body_rows[0].get(0), Some(&SqliteValue::Integer(1)));

            conn.execute("INSERT INTO docs(docs) VALUES('optimize')")
                .await
                .unwrap();
            let count_rows = conn.query("SELECT COUNT(*) FROM docs").await.unwrap();
            assert_eq!(count_rows[0].get(0).unwrap(), &SqliteValue::Integer(2));
        });
    }

    #[test]
    fn test_fts5_magic_delete_insert_routes_through_live_vtab_delete() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE VIRTUAL TABLE docs USING fts5(subject, body)")
                .await
                .unwrap();
            conn.execute(
                "INSERT INTO docs(rowid, subject, body) VALUES (1, 'Hello', 'Rust world')",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO docs(rowid, subject, body) VALUES (2, 'Other', 'Nothing')")
                .await
                .unwrap();

            conn.execute(
                "INSERT INTO docs(docs, rowid, subject, body)
             VALUES('delete', 1, 'Hello', 'Rust world')",
            )
            .await
            .unwrap();

            let rows = conn
                .query("SELECT rowid FROM docs WHERE docs MATCH 'hello'")
                .await
                .unwrap();
            assert!(
                rows.is_empty(),
                "magic delete must update the live FTS5 index"
            );
            let count_rows = conn.query("SELECT COUNT(*) FROM docs").await.unwrap();
            assert_eq!(count_rows[0].get(0), Some(&SqliteValue::Integer(1)));

            let stmt = conn
                .prepare(
                    "INSERT INTO docs(docs, rowid, subject, body)
                 VALUES('delete', ?1, ?2, ?3)",
                )
                .await
                .unwrap();
            let affected = stmt
                .execute_with_params(&[
                    SqliteValue::Integer(2),
                    SqliteValue::Text("Other".into()),
                    SqliteValue::Text("Nothing".into()),
                ])
                .await
                .unwrap();
            assert_eq!(affected, 1);
            let count_rows = conn.query("SELECT COUNT(*) FROM docs").await.unwrap();
            assert_eq!(count_rows[0].get(0), Some(&SqliteValue::Integer(0)));
        });
    }

