    #[test]
    fn test_expression_only_scalar_distinct_and_star_semantics() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let distinct_sql = "SELECT abs(DISTINCT 1);";
            let rows = conn.query(distinct_sql).await.unwrap();
            assert_eq!(rows[0].values(), &[SqliteValue::Integer(1)]);

            let prepared = conn.prepare(distinct_sql).await.unwrap();
            let prepared_rows = prepared.query().await.unwrap();
            assert_eq!(prepared_rows[0].values(), &[SqliteValue::Integer(1)]);

            let star_sql = "SELECT random(*);";
            let star_rows = conn.query(star_sql).await.unwrap();
            assert!(matches!(
                star_rows[0].values().first(),
                Some(SqliteValue::Integer(_))
            ));
            let prepared_star = conn.prepare(star_sql).await.unwrap();
            let prepared_star_rows = prepared_star.query().await.unwrap();
            assert!(matches!(
                prepared_star_rows[0].values().first(),
                Some(SqliteValue::Integer(_))
            ));

            conn.query("SELECT abs(*);")
                .await
                .expect_err("scalar Star must still undergo zero-arity validation");
            if let Ok(prepared_abs_star) = conn.prepare("SELECT abs(*);").await {
                prepared_abs_star
                    .query()
                    .await
                    .expect_err("prepared scalar Star must retain arity validation");
            }
        });
    }

