    async fn assert_fromless_wrong_aggregate_arity(sql: &str, name: &str) {
        let conn = Connection::open(":memory:").await.unwrap();
        let err = conn
            .query(sql)
            .await
            .expect_err("known aggregate with wrong arity should fail");
        let expected = format!("wrong number of arguments to function {name}()");
        assert!(
            matches!(&err, FrankenError::FunctionError(message) if message == &expected),
            "unexpected error for {sql}: {err:?}"
        );
    }

    #[test]
    fn test_expression_only_wrong_aggregate_arity_errors_before_defaults() {
        asupersync::test_utils::run_test(|| async {
            assert_fromless_wrong_aggregate_arity("SELECT sum();", "sum").await;
            assert_fromless_wrong_aggregate_arity("SELECT sum(1, 2);", "sum").await;
            assert_fromless_wrong_aggregate_arity("SELECT count(1, 2);", "count").await;
            assert_fromless_wrong_aggregate_arity("SELECT group_concat();", "group_concat").await;
            assert_fromless_wrong_aggregate_arity(
                "SELECT group_concat('a', '-', '!');",
                "group_concat",
            )
            .await;
        });
    }

