    #[test]
    #[allow(clippy::too_many_lines)]
    fn test_named_window_reference_form_and_declaration_validation() {
        std::thread::Builder::new()
            .name("named-window-deep-chain".to_owned())
            .stack_size(1024 * 1024)
            .spawn(|| {
                for depth in [1_000_usize, 1_001] {
                    let specs = (0..depth)
                        .map(|index| WindowSpec {
                            window_ref: (index > 0).then(|| {
                                let prior_index = index - 1;
                                WindowReference::Base(format!("w{prior_index}"))
                            }),
                            partition_by: Vec::new(),
                            order_by: if index == 0 {
                                vec![OrderingTerm {
                                    expr: Expr::Literal(Literal::Integer(1), Span::new(0, 0)),
                                    direction: None,
                                    nulls: None,
                                }]
                            } else {
                                Vec::new()
                            },
                            frame: None,
                        })
                        .collect::<Vec<_>>();
                    let named_windows = specs
                        .iter()
                        .enumerate()
                        .map(|(index, spec)| (format!("W{index}"), spec))
                        .collect::<Vec<_>>();
                    validate_named_window_definitions(&named_windows)
                        .expect("a deep prior-only window chain must validate iteratively");
                    let last_index = depth - 1;
                    let used = WindowSpec {
                        window_ref: Some(WindowReference::Direct(format!("w{last_index}"))),
                        partition_by: Vec::new(),
                        order_by: Vec::new(),
                        frame: None,
                    };
                    let resolved = resolve_used_window_spec(&used, &named_windows)
                        .expect("deep direct lookup must resolve without native recursion");
                    assert_eq!(resolved.order_by.len(), 1);
                }
            })
            .expect("the requested 1 MiB named-window thread must spawn")
            .join()
            .expect("deep named-window resolution must not overflow its requested 1 MiB stack");

        async fn assert_direct_and_prepared_error(conn: &Connection, sql: &str, expected: &str) {
            let direct_error = conn
                .query(sql)
                .await
                .expect_err("the direct path must reject the invalid window chain");
            let prepared_error = match conn.prepare(sql).await {
                Ok(statement) => statement
                    .query()
                    .await
                    .expect_err("the prepared path must reject the invalid window chain"),
                Err(error) => error,
            };
            for error in [direct_error, prepared_error] {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message) if message == expected
                    ),
                    "unexpected window error for `{sql}`: {error:?}"
                );
            }
        }

        async fn assert_direct_and_prepared_rows(
            conn: &Connection,
            sql: &str,
            expected: &[Vec<SqliteValue>],
        ) {
            let direct = conn.query(sql).await.unwrap();
            assert_eq!(
                direct.iter().map(row_values).collect::<Vec<_>>(),
                expected,
                "unexpected direct rows for `{sql}`"
            );
            let prepared = conn.prepare(sql).await.unwrap().query().await.unwrap();
            assert_eq!(
                prepared.iter().map(row_values).collect::<Vec<_>>(),
                expected,
                "unexpected prepared rows for `{sql}`"
            );
        }

        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            let ordering_term = |value| OrderingTerm {
                expr: Expr::Literal(Literal::Integer(value), Span::new(0, 0)),
                direction: None,
                nulls: None,
            };
            let programmatic_base = WindowSpec {
                window_ref: None,
                partition_by: Vec::new(),
                order_by: vec![ordering_term(1)],
                frame: None,
            };
            let programmatic_direct_with_clause = WindowSpec {
                window_ref: Some(WindowReference::Direct("w".to_owned())),
                partition_by: Vec::new(),
                order_by: vec![ordering_term(2)],
                frame: None,
            };
            let programmatic_windows = vec![("W".to_owned(), &programmatic_base)];
            let programmatic_error =
                resolve_used_window_spec(&programmatic_direct_with_clause, &programmatic_windows)
                    .expect_err("a public Direct+clauses AST must not discard its clauses");
            assert!(
                matches!(
                    &programmatic_error,
                    FrankenError::FunctionError(message)
                        if message == "cannot override ORDER BY clause of window: w"
                ),
                "unexpected programmatic Direct+clauses error: {programmatic_error:?}"
            );

            assert_direct_and_prepared_rows(
                &conn,
                "SELECT sum(1) OVER w WINDOW w AS (ROWS CURRENT ROW);",
                &[vec![SqliteValue::Integer(1)]],
            )
            .await;
            for sql in [
                "SELECT sum(1) OVER (w) WINDOW w AS (ROWS CURRENT ROW);",
                "SELECT sum(1) OVER (w) \
                 WINDOW w AS (ROWS CURRENT ROW) LIMIT 0;",
                "SELECT sum(1) OVER (w) WHERE 0 \
                 WINDOW w AS (ROWS CURRENT ROW);",
                "SELECT 1 WINDOW w AS (ROWS CURRENT ROW) \
                 ORDER BY sum(1) OVER (w);",
            ] {
                assert_direct_and_prepared_error(
                    &conn,
                    sql,
                    "cannot override frame specification of window: w",
                )
                .await;
            }
            assert_direct_and_prepared_rows(
                &conn,
                "SELECT 1 WINDOW w AS (ROWS CURRENT ROW) \
                 ORDER BY sum(1) OVER w;",
                &[vec![SqliteValue::Integer(1)]],
            )
            .await;

            for (sql, expected) in [
                (
                    "SELECT 1 WINDOW a AS (ROWS CURRENT ROW), b AS (a);",
                    "cannot override frame specification of window: a",
                ),
                (
                    "SELECT 1 WINDOW a AS (), b AS (missing);",
                    "no such window: missing",
                ),
                (
                    "SELECT row_number() OVER \
                     (a PARTITION BY 2 ORDER BY 2 ROWS CURRENT ROW) \
                     WINDOW a AS \
                     (PARTITION BY 1 ORDER BY 1 ROWS CURRENT ROW);",
                    "cannot override PARTITION clause of window: a",
                ),
                (
                    "SELECT row_number() OVER \
                     (a ORDER BY 2 ROWS CURRENT ROW) \
                     WINDOW a AS (ORDER BY 1 ROWS CURRENT ROW);",
                    "cannot override ORDER BY clause of window: a",
                ),
                (
                    "SELECT row_number() OVER (a ROWS CURRENT ROW) \
                     WINDOW a AS (ROWS CURRENT ROW);",
                    "cannot override frame specification of window: a",
                ),
                (
                    "SELECT 1 WINDOW \
                     a AS (PARTITION BY 1 ORDER BY 1 ROWS CURRENT ROW), \
                     b AS (a PARTITION BY 2 ORDER BY 2 ROWS CURRENT ROW);",
                    "cannot override PARTITION clause of window: a",
                ),
                (
                    "SELECT 1 WINDOW \
                     a AS (ORDER BY 1 ROWS CURRENT ROW), \
                     b AS (a ORDER BY 2 ROWS CURRENT ROW);",
                    "cannot override ORDER BY clause of window: a",
                ),
                (
                    "SELECT 1 WINDOW \
                     a AS (ROWS CURRENT ROW), \
                     b AS (a ROWS CURRENT ROW);",
                    "cannot override frame specification of window: a",
                ),
            ] {
                assert_direct_and_prepared_error(&conn, sql, expected).await;
            }
            for sql in [
                "SELECT 1 WINDOW a AS (missing);",
                "SELECT 1 WINDOW a AS (a), b AS ();",
                "SELECT 1 WINDOW a AS (b), b AS ();",
            ] {
                assert_direct_and_prepared_rows(&conn, sql, &[vec![SqliteValue::Integer(1)]]).await;
            }

            assert_direct_and_prepared_rows(
                &conn,
                "SELECT row_number() OVER (child ORDER BY 1) \
                 WINDOW w AS (), child AS (w), w AS (ORDER BY 2);",
                &[vec![SqliteValue::Integer(1)]],
            )
            .await;
            assert_direct_and_prepared_error(
                &conn,
                "SELECT row_number() OVER (child ORDER BY 1) \
                 WINDOW w AS (ORDER BY 0), child AS (w), w AS ();",
                "cannot override ORDER BY clause of window: child",
            )
            .await;

            conn.execute("CREATE TABLE window_rows (x INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO window_rows VALUES (1), (2), (3);")
                .await
                .unwrap();
            assert_direct_and_prepared_rows(
                &conn,
                "SELECT x, sum(x) OVER w FROM window_rows \
                 WINDOW w AS (ORDER BY x ROWS 1 PRECEDING) ORDER BY x;",
                &[
                    vec![SqliteValue::Integer(1), SqliteValue::Integer(1)],
                    vec![SqliteValue::Integer(2), SqliteValue::Integer(3)],
                    vec![SqliteValue::Integer(3), SqliteValue::Integer(5)],
                ],
            )
            .await;
            assert_direct_and_prepared_error(
                &conn,
                "SELECT x, sum(x) OVER (w) FROM window_rows \
                 WINDOW w AS (ORDER BY x ROWS 1 PRECEDING) ORDER BY x;",
                "cannot override frame specification of window: w",
            )
            .await;
            assert_direct_and_prepared_rows(
                &conn,
                "SELECT x, sum(x) OVER (w) FROM window_rows \
                 WINDOW w AS (ORDER BY x) ORDER BY x;",
                &[
                    vec![SqliteValue::Integer(1), SqliteValue::Integer(1)],
                    vec![SqliteValue::Integer(2), SqliteValue::Integer(3)],
                    vec![SqliteValue::Integer(3), SqliteValue::Integer(6)],
                ],
            )
            .await;
            assert_direct_and_prepared_rows(
                &conn,
                "SELECT x, row_number() OVER child, row_number() OVER w \
                 FROM window_rows \
                 WINDOW w AS (ORDER BY x DESC), child AS (w), \
                        w AS (ORDER BY x ASC) \
                 ORDER BY x;",
                &[
                    vec![
                        SqliteValue::Integer(1),
                        SqliteValue::Integer(3),
                        SqliteValue::Integer(1),
                    ],
                    vec![
                        SqliteValue::Integer(2),
                        SqliteValue::Integer(2),
                        SqliteValue::Integer(2),
                    ],
                    vec![
                        SqliteValue::Integer(3),
                        SqliteValue::Integer(1),
                        SqliteValue::Integer(3),
                    ],
                ],
            )
            .await;
        });
    }

    #[test]
    fn test_fromless_window_one_row_select_values_and_order_semantics() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let cases = [
                (
                    "SELECT row_number() OVER ();",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT sum(1) OVER (ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING);",
                    vec![vec![SqliteValue::Null]],
                ),
                (
                    "SELECT sum(1) OVER w \
                     WINDOW w AS (ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING);",
                    vec![vec![SqliteValue::Null]],
                ),
                (
                    "SELECT row_number() OVER w2 \
                     WINDOW w2 AS (w1), w1 AS (ROWS CURRENT ROW);",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT row_number() OVER w1 \
                     WINDOW w1 AS (w2), w2 AS (w1);",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT sum(1) OVER w \
                     WINDOW w AS \
                         (ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING), \
                            w AS ();",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT sum(1) OVER w \
                     WINDOW w AS (), \
                            w AS \
                         (ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING);",
                    vec![vec![SqliteValue::Null]],
                ),
                (
                    "SELECT count(*) FILTER (WHERE 0) OVER ();",
                    vec![vec![SqliteValue::Integer(0)]],
                ),
                (
                    "SELECT sum((SELECT 1)) OVER ();",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT sum(sum(1)) OVER ();",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT first_value(sum(1)) OVER ();",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT row_number() OVER (ORDER BY sum(1));",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT row_number() OVER (PARTITION BY sum(1));",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT abs(row_number() OVER ());",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT row_number() OVER () + rank() OVER ();",
                    vec![vec![SqliteValue::Integer(2)]],
                ),
                (
                    "SELECT 1 ORDER BY row_number() OVER ();",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "VALUES (row_number() OVER ()), (row_number() OVER ());",
                    vec![vec![SqliteValue::Integer(1)], vec![SqliteValue::Integer(1)]],
                ),
                (
                    "VALUES (2, row_number() OVER ()), \
                            (1, row_number() OVER ()) ORDER BY 1;",
                    vec![
                        vec![SqliteValue::Integer(1), SqliteValue::Integer(1)],
                        vec![SqliteValue::Integer(2), SqliteValue::Integer(1)],
                    ],
                ),
                (
                    "SELECT 7 AS keep, row_number() OVER () WHERE keep;",
                    vec![vec![SqliteValue::Integer(7), SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT 1 AS x ORDER BY sum(x) OVER ();",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT 1 AS x ORDER BY row_number() OVER (ORDER BY x);",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT 1 AS x WINDOW w AS (ORDER BY x) \
                     ORDER BY row_number() OVER w;",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT 1 AS x WINDOW w AS () \
                     ORDER BY row_number() OVER (w ORDER BY x);",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT 1 AS x WINDOW w AS () ORDER BY sum(x) OVER w;",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT row_number() OVER () GROUP BY 0 + 0;",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT row_number() OVER () GROUP BY NULL;",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT sum(1), row_number() OVER () HAVING 1;",
                    vec![vec![SqliteValue::Integer(1), SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT sum(1) OVER (), count(*) HAVING 1;",
                    vec![vec![SqliteValue::Integer(1), SqliteValue::Integer(1)]],
                ),
                ("SELECT sum(1), row_number() OVER () HAVING 0;", Vec::new()),
                (
                    "SELECT count(*), row_number() OVER () WHERE 0;",
                    vec![vec![SqliteValue::Integer(0), SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT row_number() OVER (ORDER BY sum(1)) WHERE 0;",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT sum(sum(1)) OVER () WHERE 0;",
                    vec![vec![SqliteValue::Null]],
                ),
                (
                    "SELECT sum(1) + row_number() OVER () HAVING 1;",
                    vec![vec![SqliteValue::Integer(2)]],
                ),
                (
                    "SELECT sum(1) ORDER BY \
                     row_number() OVER (ORDER BY sum(1));",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT row_number() OVER () AS x ORDER BY abs(x);",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
                (
                    "SELECT sum(1) AS x ORDER BY sum(x) OVER ();",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
            ];

            for (sql, expected) in cases {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(
                    direct.iter().map(row_values).collect::<Vec<_>>(),
                    expected,
                    "unexpected direct FROM-less window result for `{sql}`"
                );

                let prepared = conn.prepare(sql).await.unwrap();
                let prepared_rows = prepared.query().await.unwrap();
                assert_eq!(
                    prepared_rows.iter().map(row_values).collect::<Vec<_>>(),
                    expected,
                    "unexpected prepared FROM-less window result for `{sql}`"
                );
            }
        });
    }

    #[test]
    fn test_fromless_window_prepared_binding_and_runtime_suppression() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            let projected = conn
                .prepare("SELECT ?1 AS arg, row_number() OVER (ORDER BY ?2);")
                .await
                .unwrap();
            let projected_rows = projected
                .query_with_params(&[SqliteValue::Integer(7), SqliteValue::Integer(11)])
                .await
                .unwrap();
            assert_eq!(
                projected_rows[0].values(),
                &[SqliteValue::Integer(7), SqliteValue::Integer(1)]
            );

            let framed = conn
                .prepare(
                    "SELECT sum(?1) OVER \
                     (ROWS BETWEEN ?2 PRECEDING AND ?3 PRECEDING);",
                )
                .await
                .unwrap();
            let framed_rows = framed
                .query_with_params(&[
                    SqliteValue::Integer(9),
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(1),
                ])
                .await
                .unwrap();
            assert_eq!(framed_rows[0].values(), &[SqliteValue::Null]);

            let filtered = conn
                .prepare("SELECT count(*) FILTER (WHERE ?1) OVER ();")
                .await
                .unwrap();
            let filtered_rows = filtered
                .query_with_params(&[SqliteValue::Integer(0)])
                .await
                .unwrap();
            assert_eq!(filtered_rows[0].values(), &[SqliteValue::Integer(0)]);

            for sql in [
                "SELECT sum(json('malformed')) OVER () WHERE 0;",
                "SELECT row_number() OVER (ORDER BY json('malformed')) LIMIT 0;",
                "SELECT 1 ORDER BY row_number() OVER \
                 (ORDER BY json('malformed')) LIMIT 0;",
            ] {
                let direct = conn
                    .query(sql)
                    .await
                    .expect("false WHERE or LIMIT zero must suppress runtime window inputs");
                assert!(direct.is_empty(), "unexpected direct rows for `{sql}`");

                let prepared = conn.prepare(sql).await.unwrap();
                let prepared_rows = prepared
                    .query()
                    .await
                    .expect("prepared suppression must match direct execution");
                assert!(
                    prepared_rows.is_empty(),
                    "unexpected prepared rows for `{sql}`"
                );
            }

            let dynamic_limit = conn
                .prepare(
                    "SELECT row_number() OVER \
                     (ORDER BY json('malformed')) LIMIT ?1;",
                )
                .await
                .unwrap();
            assert!(
                dynamic_limit
                    .query_with_params(&[SqliteValue::Integer(0)])
                    .await
                    .unwrap()
                    .is_empty()
            );
        });
    }

    #[test]
    fn test_fromless_custom_window_functions_run_one_partition_lifecycle() {
        struct CustomRowNumber {
            num_args: i32,
            lifecycle_calls: Arc<AtomicUsize>,
        }

        impl fsqlite_func::WindowFunction for CustomRowNumber {
            type State = ();

            fn initial_state(&self) {
                self.lifecycle_calls.fetch_add(1, AtomicOrdering::SeqCst);
            }

            fn step(&self, _state: &mut (), _args: &[SqliteValue]) -> Result<()> {
                self.lifecycle_calls.fetch_add(1, AtomicOrdering::SeqCst);
                Ok(())
            }

            fn inverse(&self, _state: &mut (), _args: &[SqliteValue]) -> Result<()> {
                self.lifecycle_calls.fetch_add(1, AtomicOrdering::SeqCst);
                Ok(())
            }

            fn value(&self, _state: &()) -> Result<SqliteValue> {
                self.lifecycle_calls.fetch_add(1, AtomicOrdering::SeqCst);
                Ok(SqliteValue::Integer(42))
            }

            fn finalize(&self, _state: ()) -> Result<SqliteValue> {
                self.lifecycle_calls.fetch_add(1, AtomicOrdering::SeqCst);
                Ok(SqliteValue::Integer(42))
            }

            fn num_args(&self) -> i32 {
                self.num_args
            }

            fn name(&self) -> &str {
                "row_number"
            }
        }

        asupersync::test_utils::run_test(|| async {
            let builtin = Connection::open(":memory:").await.unwrap();
            let builtin_sql = "SELECT row_number() OVER ();";
            assert_eq!(
                builtin.query(builtin_sql).await.unwrap()[0].values(),
                &[SqliteValue::Integer(1)]
            );
            assert_eq!(
                builtin
                    .prepare(builtin_sql)
                    .await
                    .unwrap()
                    .query()
                    .await
                    .unwrap()[0]
                    .values(),
                &[SqliteValue::Integer(1)]
            );

            let exact = Connection::open(":memory:").await.unwrap();
            let exact_calls = Arc::new(AtomicUsize::new(0));
            exact.register_window_function(CustomRowNumber {
                num_args: 0,
                lifecycle_calls: Arc::clone(&exact_calls),
            });
            assert_eq!(
                exact.query(builtin_sql).await.unwrap()[0].values(),
                &[SqliteValue::Integer(42)]
            );
            assert_eq!(
                exact
                    .prepare(builtin_sql)
                    .await
                    .unwrap()
                    .query()
                    .await
                    .unwrap()[0]
                    .values(),
                &[SqliteValue::Integer(42)]
            );
            assert_eq!(
                exact_calls.load(AtomicOrdering::SeqCst),
                8,
                "each execution must call initial_state, step, value, and finalize once"
            );

            // Application registrations form the outer namespace layer, so a
            // compatible custom variadic wins before the built-in exact entry.
            let variadic = Connection::open(":memory:").await.unwrap();
            let variadic_calls = Arc::new(AtomicUsize::new(0));
            variadic.register_window_function(CustomRowNumber {
                num_args: -1,
                lifecycle_calls: Arc::clone(&variadic_calls),
            });
            assert_eq!(
                variadic.query(builtin_sql).await.unwrap()[0].values(),
                &[SqliteValue::Integer(42)]
            );
            assert_eq!(
                variadic
                    .prepare(builtin_sql)
                    .await
                    .unwrap()
                    .query()
                    .await
                    .unwrap()[0]
                    .values(),
                &[SqliteValue::Integer(42)]
            );
            assert_eq!(
                variadic
                    .query("SELECT row_number(1) OVER ();")
                    .await
                    .unwrap()[0]
                    .values(),
                &[SqliteValue::Integer(42)]
            );
            assert_eq!(
                variadic
                    .prepare("SELECT row_number(1) OVER ();")
                    .await
                    .unwrap()
                    .query()
                    .await
                    .unwrap()[0]
                    .values(),
                &[SqliteValue::Integer(42)]
            );
            assert_eq!(
                variadic_calls.load(AtomicOrdering::SeqCst),
                16,
                "each variadic execution must run one complete four-callback lifecycle"
            );
        });
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn test_fromless_window_static_validation_precedes_limit_zero() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            for sql in [
                "SELECT row_number() OVER missing LIMIT 0;",
                "SELECT sum(DISTINCT 1) OVER () LIMIT 0;",
                "SELECT sum(1 ORDER BY 1) OVER () LIMIT 0;",
                "SELECT sum(1) OVER (RANGE 1 PRECEDING) LIMIT 0;",
                "SELECT row_number() OVER w \
                 WINDOW w AS (ORDER BY no_such_window_input(1)) LIMIT 0;",
                "SELECT row_number() OVER w \
                 WINDOW w AS (ORDER BY missing_column) LIMIT 0;",
                "SELECT row_number() OVER (w PARTITION BY 1) \
                 WINDOW w AS () LIMIT 0;",
                "SELECT row_number() OVER w2 \
                 WINDOW w1 AS (ROWS CURRENT ROW), w2 AS (w1) LIMIT 0;",
                "SELECT row_number() OVER w2 \
                 WINDOW w1 AS (), w2 AS (w1 PARTITION BY 1);",
                "SELECT row_number() OVER w2 \
                 WINDOW w AS (ROWS CURRENT ROW), w2 AS (w), w AS ();",
                "SELECT sum(row_number() OVER ()) LIMIT 0;",
                "SELECT 1 AS x, sum(x) OVER ();",
                "SELECT 1 AS x, row_number() OVER (ORDER BY x);",
                "SELECT row_number() OVER () GROUP BY 1;",
                "SELECT row_number() OVER () HAVING 1;",
                "SELECT row_number() OVER () HAVING 1 LIMIT 0;",
                "SELECT sum(sum(1)) OVER () HAVING 1;",
                "SELECT first_value(sum(1)) OVER () HAVING 1;",
                "SELECT row_number() OVER (ORDER BY sum(1)) HAVING 1;",
                "SELECT 1 ORDER BY row_number() OVER (ORDER BY sum(1));",
                "SELECT row_number() OVER () \
                 ORDER BY row_number() OVER (ORDER BY sum(1));",
                "SELECT 1 ORDER BY sum(sum(1)) OVER ();",
                "SELECT row_number() OVER () AS x ORDER BY sum(x) OVER ();",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("LIMIT zero must not suppress static window validation");
                if let Ok(prepared) = conn.prepare(sql).await {
                    prepared
                        .query()
                        .await
                        .expect_err("prepared execution must retain static window validation");
                }
            }

            for sql in [
                "SELECT row_number() OVER (ORDER BY 1 COLLATE nope) LIMIT 0;",
                "SELECT row_number() OVER (PARTITION BY 1 COLLATE nope) WHERE 0;",
                "SELECT row_number() OVER used \
                 WINDOW used AS (ORDER BY 1 COLLATE nope) LIMIT 0;",
                "SELECT 1 COLLATE nope AS x \
                 WINDOW w AS (ORDER BY x) \
                 ORDER BY row_number() OVER w LIMIT 0;",
                "SELECT sum(1 COLLATE nope) OVER () LIMIT 0;",
                "SELECT sum(1 COLLATE nope) OVER () WHERE 0;",
                "VALUES (sum(1 COLLATE nope) OVER ());",
                "SELECT 1 ORDER BY sum(1 COLLATE nope) OVER () LIMIT 0;",
                "SELECT sum(1) FILTER (WHERE 1 COLLATE nope) OVER () LIMIT 0;",
            ] {
                let direct_error = conn
                    .query(sql)
                    .await
                    .expect_err("used window-key collations must resolve before suppression");
                let prepared_error = match conn.prepare(sql).await {
                    Ok(statement) => statement
                        .query()
                        .await
                        .expect_err("prepared execution must validate used window collations"),
                    Err(error) => error,
                };
                for error in [direct_error, prepared_error] {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::FunctionError(message)
                                if message == "no such collation sequence: nope"
                        ),
                        "unexpected used-window collation error for `{sql}`: {error:?}"
                    );
                }
            }

            for (sql, expected_collation) in [
                (
                    "SELECT sum(1 COLLATE argbad) \
                     FILTER (WHERE 1 COLLATE filbad) \
                     OVER (ORDER BY 1 COLLATE keybad) LIMIT 0;",
                    "filbad",
                ),
                (
                    "SELECT row_number() OVER (), \
                     (1 COLLATE siblingbad) = 1 LIMIT 0;",
                    "siblingbad",
                ),
                (
                    "SELECT row_number() OVER () \
                     ORDER BY 1 COLLATE orderboundarybad LIMIT 0;",
                    "orderboundarybad",
                ),
                (
                    "SELECT row_number() OVER () \
                     LIMIT ((1 COLLATE limitcmpbad) = 1);",
                    "limitcmpbad",
                ),
                (
                    "SELECT DISTINCT row_number() OVER (), \
                     1 COLLATE distinctsiblingbad LIMIT 0;",
                    "distinctsiblingbad",
                ),
                (
                    "SELECT row_number() OVER () \
                     GROUP BY 'x' COLLATE outergroupbad LIMIT 0;",
                    "outergroupbad",
                ),
                (
                    "SELECT lag(1 COLLATE firstbad, 2 COLLATE secondbad, \
                     3 COLLATE thirdbad) OVER () LIMIT 0;",
                    "thirdbad",
                ),
                (
                    "SELECT sum(1) OVER \
                     (ORDER BY 1 COLLATE firstbad, 2 COLLATE secondbad) LIMIT 0;",
                    "secondbad",
                ),
                (
                    "SELECT sum(1) OVER \
                     (PARTITION BY 1 COLLATE partbad ORDER BY 1 COLLATE orderbad) LIMIT 0;",
                    "orderbad",
                ),
                (
                    "SELECT sum(coalesce(1 COLLATE firstbad, \
                     2 COLLATE secondbad)) OVER () LIMIT 0;",
                    "firstbad",
                ),
                (
                    "SELECT row_number() OVER \
                     (ORDER BY group_concat(1 ORDER BY 2 COLLATE nord1bad, \
                      3 COLLATE nord2bad) FILTER (WHERE 1 COLLATE nfilbad)) \
                     LIMIT 0;",
                    "nord2bad",
                ),
                (
                    "SELECT row_number() OVER \
                     (ORDER BY ('a' COLLATE exprbad) LIKE \
                      ('b' COLLATE patternbad) ESCAPE \
                      ('x' COLLATE escapebad)) LIMIT 0;",
                    "patternbad",
                ),
                (
                    "SELECT row_number() OVER \
                     (ORDER BY (1 COLLATE BINARY) + \
                      ((2 COLLATE nestedbad) = 2)) LIMIT 0;",
                    "nestedbad",
                ),
                (
                    "SELECT sum((min(1 COLLATE firstbad, \
                     2 COLLATE secondbad)) COLLATE BINARY) OVER () LIMIT 0;",
                    "secondbad",
                ),
                (
                    "SELECT sum((nullif(1 COLLATE firstbad, \
                     2 COLLATE secondbad)) COLLATE BINARY) OVER () LIMIT 0;",
                    "secondbad",
                ),
                (
                    "SELECT sum((min(1 COLLATE firstbad, \
                     2 COLLATE BINARY)) COLLATE BINARY) OVER () LIMIT 0;",
                    "firstbad",
                ),
                (
                    "SELECT sum((1 IN (2 COLLATE singlerhsbad)) \
                     COLLATE BINARY) OVER () LIMIT 0;",
                    "singlerhsbad",
                ),
                (
                    "SELECT sum((((1 COLLATE BINARY, 2 COLLATE rowbad) = \
                     (1, 2))) COLLATE BINARY) OVER () LIMIT 0;",
                    "rowbad",
                ),
                (
                    "SELECT sum(1 IN (SELECT 2 COLLATE subbad)) \
                     OVER () LIMIT 0;",
                    "subbad",
                ),
                (
                    "SELECT sum((((1 COLLATE lhsbad) IN \
                     (SELECT 2 ORDER BY 'x' COLLATE rhsorderbad)) \
                     COLLATE BINARY)) OVER () LIMIT 0;",
                    "rhsorderbad",
                ),
                (
                    "SELECT sum((SELECT (1 COLLATE subcmpbad) = 1)) \
                     OVER () LIMIT 0;",
                    "subcmpbad",
                ),
                (
                    "SELECT sum((SELECT 1 COLLATE aliasbad AS x ORDER BY x)) \
                     OVER () LIMIT 0;",
                    "aliasbad",
                ),
                (
                    "SELECT sum((SELECT DISTINCT 1 COLLATE distinctbad)) \
                     OVER () LIMIT 0;",
                    "distinctbad",
                ),
                (
                    "SELECT sum((SELECT 1 GROUP BY 'x' COLLATE groupbad)) \
                     OVER () LIMIT 0;",
                    "groupbad",
                ),
                (
                    "SELECT sum((SELECT 1 WHERE \
                     (1 COLLATE wherebad) = 1)) OVER () LIMIT 0;",
                    "wherebad",
                ),
                (
                    "SELECT sum((WITH used AS \
                     (SELECT (1 COLLATE ctebad) = 1) \
                     SELECT * FROM used)) OVER () LIMIT 0;",
                    "ctebad",
                ),
                (
                    "SELECT sum(EXISTS(SELECT 1 WHERE \
                     (1 COLLATE existsbad) = 1)) OVER () LIMIT 0;",
                    "existsbad",
                ),
                (
                    "SELECT sum(1) OVER (ROWS \
                     (((1 COLLATE framebad) = 1)) PRECEDING) LIMIT 0;",
                    "framebad",
                ),
                (
                    "SELECT sum(1) OVER (ROWS BETWEEN CURRENT ROW AND \
                     (((1 COLLATE frameendbad) = 1)) FOLLOWING) LIMIT 0;",
                    "frameendbad",
                ),
                (
                    "SELECT sum((group_concat(DISTINCT \
                     1 COLLATE distinctargbad)) COLLATE BINARY) \
                     OVER () LIMIT 0;",
                    "distinctargbad",
                ),
                (
                    "SELECT sum((group_concat(1 COLLATE argbad) \
                     FILTER (WHERE (1 COLLATE filtercmpbad) = 1)) \
                     COLLATE BINARY) OVER () LIMIT 0;",
                    "filtercmpbad",
                ),
                (
                    "SELECT sum((SELECT 1 COLLATE setbad \
                     UNION SELECT 2 COLLATE BINARY)) OVER () LIMIT 0;",
                    "setbad",
                ),
                (
                    "SELECT sum((SELECT 1 UNION SELECT 2 \
                     UNION ALL SELECT 3 COLLATE latebad)) OVER () LIMIT 0;",
                    "latebad",
                ),
                (
                    "SELECT sum(1 IN (SELECT 2 \
                     UNION ALL SELECT 3 COLLATE finalbad)) OVER () LIMIT 0;",
                    "finalbad",
                ),
                (
                    "SELECT sum((1, 2) IN \
                     (SELECT 1, 2 COLLATE subrowbad)) OVER () LIMIT 0;",
                    "subrowbad",
                ),
                (
                    "SELECT sum(1 IN (VALUES(1 COLLATE invaluesbad))) \
                     OVER () LIMIT 0;",
                    "invaluesbad",
                ),
            ] {
                let expected = format!("no such collation sequence: {expected_collation}");
                let direct_error = conn
                    .query(sql)
                    .await
                    .expect_err("window collation diagnostics must follow SQLite precedence");
                let prepared_error = match conn.prepare(sql).await {
                    Ok(statement) => statement
                        .query()
                        .await
                        .expect_err("prepared window collation precedence must match SQLite"),
                    Err(error) => error,
                };
                for error in [direct_error, prepared_error] {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::FunctionError(message) if message == &expected
                        ),
                        "unexpected collation precedence for `{sql}`: {error:?}"
                    );
                }
            }

            for sql in [
                "SELECT row_number() OVER () \
                 WINDOW unused AS (ORDER BY no_such_window_input(1));",
                "SELECT row_number() OVER used \
                 WINDOW used AS (missing_base ORDER BY 1);",
            ] {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(direct[0].values(), &[SqliteValue::Integer(1)]);
                let prepared = conn.prepare(sql).await.unwrap();
                assert_eq!(
                    prepared.query().await.unwrap()[0].values(),
                    &[SqliteValue::Integer(1)]
                );
            }

            let unused_collation = "SELECT row_number() OVER () \
                 WINDOW unused AS (ORDER BY 1 COLLATE nope) LIMIT 0;";
            assert!(conn.query(unused_collation).await.unwrap().is_empty());
            assert!(
                conn.prepare(unused_collation)
                    .await
                    .unwrap()
                    .query()
                    .await
                    .unwrap()
                    .is_empty()
            );

            for sql in [
                "SELECT sum((SELECT 1 COLLATE nope)) OVER () LIMIT 0;",
                "SELECT sum((VALUES(1 COLLATE valuesbad))) OVER () LIMIT 0;",
                "SELECT sum(1) OVER (ROWS (1 COLLATE nope) PRECEDING) LIMIT 0;",
                "SELECT row_number() OVER (), 1 COLLATE rawbad LIMIT 0;",
                "SELECT row_number() OVER () \
                 WHERE 0 COLLATE rawwherebad LIMIT 0;",
                "SELECT row_number() OVER \
                 (ORDER BY (1 COLLATE innerbad) COLLATE BINARY) LIMIT 0;",
                "SELECT row_number() OVER \
                 (ORDER BY (1 COLLATE BINARY) + (2 COLLATE rhsbad)) LIMIT 0;",
                "SELECT sum((1 COLLATE BINARY) BETWEEN \
                 (2 COLLATE lowbad) AND (3 COLLATE highbad)) OVER () LIMIT 0;",
                "SELECT row_number() OVER \
                 (ORDER BY ('a' COLLATE subjectbad) LIKE \
                  ('b' COLLATE BINARY) ESCAPE \
                  ('x' COLLATE escapebad)) LIMIT 0;",
                "SELECT sum((1 COLLATE BINARY) IN \
                 (2 COLLATE firstbad, 3 COLLATE secondbad)) OVER () LIMIT 0;",
                "SELECT sum((1 IN (2, 3 COLLATE rhsbad)) COLLATE BINARY) \
                 OVER () LIMIT 0;",
                "SELECT sum((CASE WHEN 1 COLLATE conditionbad \
                 THEN 2 COLLATE resultbad END) COLLATE BINARY) \
                 OVER () LIMIT 0;",
                "SELECT sum((coalesce(1 COLLATE firstbad, \
                 2 COLLATE secondbad)) COLLATE BINARY) OVER () LIMIT 0;",
                "SELECT sum((min(1 COLLATE BINARY, \
                 2 COLLATE secondbad)) COLLATE BINARY) OVER () LIMIT 0;",
                "SELECT sum((group_concat(1 COLLATE argbad) \
                 FILTER (WHERE 1 COLLATE filbad)) COLLATE BINARY) \
                 OVER () LIMIT 0;",
                "SELECT sum((((1, 2) IN \
                 ((1, 2 COLLATE setrowbad), (3, 4)))) COLLATE BINARY) \
                 OVER () LIMIT 0;",
                "SELECT sum((SELECT 1 COLLATE BINARY \
                 UNION SELECT 2 COLLATE setrhsbad)) OVER () LIMIT 0;",
                "SELECT sum((SELECT 1 COLLATE unionallbad \
                 UNION ALL SELECT 2)) OVER () LIMIT 0;",
                "SELECT sum((SELECT 1 COLLATE aliasbad AS x \
                 ORDER BY x COLLATE BINARY)) OVER () LIMIT 0;",
                "SELECT sum((WITH unused AS \
                 (SELECT (1 COLLATE unusedctebad) = 1) \
                 SELECT 1)) OVER () LIMIT 0;",
                "SELECT sum(1 IN \
                 (VALUES(1), (2 COLLATE latervaluesbad))) OVER () LIMIT 0;",
                "SELECT sum(EXISTS(SELECT \
                 (1 COLLATE deadprojectionbad) = 1)) OVER () LIMIT 0;",
                "SELECT sum(0 AND ((1 COLLATE deadandbad) = 1)) \
                 OVER () LIMIT 0;",
                "SELECT sum(((1 COLLATE deadandbad) = 1) AND 0) \
                 OVER () LIMIT 0;",
                "SELECT sum(0 AND (SELECT 1 UNION SELECT 2, 3)) \
                 OVER () LIMIT 0;",
                "SELECT sum((SELECT 1 UNION SELECT 2, 3) AND 0) \
                 OVER () LIMIT 0;",
                "SELECT row_number() OVER () + \
                 (0 AND sum(1) OVER (ORDER BY 1 COLLATE deadwindowbad)) \
                 LIMIT 0;",
                "SELECT sum(1) OVER (ROWS \
                 (0 AND ((1 COLLATE deadframebad) = 1)) PRECEDING) LIMIT 0;",
            ] {
                assert!(
                    conn.query(sql).await.unwrap().is_empty(),
                    "unconsumed collations behind SQLite's deferred boundaries must remain \
                     opaque for `{sql}`"
                );
                assert!(
                    conn.prepare(sql)
                        .await
                        .unwrap()
                        .query()
                        .await
                        .unwrap()
                        .is_empty(),
                    "prepared execution must preserve selective deferred collation resolution \
                     for `{sql}`"
                );
            }

            lock_unpoisoned(conn.collation_registry.as_ref()).register(WindowLengthFirstCollation);
            for (sql, expected) in [
                (
                    "SELECT row_number() OVER (ORDER BY 'x' COLLATE NOCASE) LIMIT 0;",
                    Vec::new(),
                ),
                (
                    "SELECT sum(1) OVER (ORDER BY 'x' COLLATE LENFIRST);",
                    vec![vec![SqliteValue::Integer(1)]],
                ),
            ] {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(
                    direct.iter().map(row_values).collect::<Vec<_>>(),
                    expected,
                    "unexpected direct result for known window collation in `{sql}`"
                );
                let prepared = conn.prepare(sql).await.unwrap().query().await.unwrap();
                assert_eq!(
                    prepared.iter().map(row_values).collect::<Vec<_>>(),
                    expected,
                    "unexpected prepared result for known window collation in `{sql}`"
                );
            }
        });
    }

    #[test]
    fn test_builtin_needcoll_flags_follow_selected_function_identity() {
        use fsqlite_func::{AggregateFunction, ScalarFunction};

        struct NeverInvokedScalar {
            function_name: &'static str,
            arity: i32,
            calls: Arc<AtomicUsize>,
        }

        impl ScalarFunction for NeverInvokedScalar {
            fn invoke(&self, _args: &[SqliteValue]) -> Result<SqliteValue> {
                self.calls.fetch_add(1, AtomicOrdering::SeqCst);
                Ok(SqliteValue::Null)
            }

            fn num_args(&self) -> i32 {
                self.arity
            }

            fn name(&self) -> &str {
                self.function_name
            }
        }

        struct NeverInvokedAggregate {
            function_name: &'static str,
            arity: i32,
            calls: Arc<AtomicUsize>,
        }

        impl AggregateFunction for NeverInvokedAggregate {
            type State = ();

            fn initial_state(&self) -> Self::State {
                self.calls.fetch_add(1, AtomicOrdering::SeqCst);
            }

            fn step(&self, _state: &mut Self::State, _args: &[SqliteValue]) -> Result<()> {
                self.calls.fetch_add(1, AtomicOrdering::SeqCst);
                Ok(())
            }

            fn finalize(&self, _state: Self::State) -> Result<SqliteValue> {
                self.calls.fetch_add(1, AtomicOrdering::SeqCst);
                Ok(SqliteValue::Null)
            }

            fn num_args(&self) -> i32 {
                self.arity
            }

            fn name(&self) -> &str {
                self.function_name
            }
        }

        async fn expect_missing_collation(conn: &Connection, sql: &str) {
            let direct = conn
                .query(sql)
                .await
                .expect_err("the selected builtin must consume argument collation");
            let prepared = match conn.prepare(sql).await {
                Ok(statement) => statement
                    .query()
                    .await
                    .expect_err("prepared execution must retain builtin NEEDCOLL"),
                Err(error) => error,
            };
            for error in [direct, prepared] {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message == "no such collation sequence: missing"
                    ),
                    "unexpected collation error for `{sql}`: {error:?}"
                );
            }
        }

        async fn expect_limit_zero(conn: &Connection, sql: &str) {
            assert!(
                conn.query(sql)
                    .await
                    .unwrap_or_else(|error| {
                        panic!(
                            "custom override should leave raw collation opaque for `{sql}`: {error}"
                        )
                    })
                    .is_empty()
            );
            assert!(
                conn.prepare(sql)
                    .await
                    .unwrap_or_else(|error| {
                        panic!("custom override should prepare `{sql}`: {error}")
                    })
                    .query()
                    .await
                    .unwrap_or_else(|error| {
                        panic!("prepared custom override should execute `{sql}`: {error}")
                    })
                    .is_empty()
            );
        }

        asupersync::test_utils::run_test(|| async {
            let builtin = Connection::open(":memory:").await.unwrap();
            for sql in [
                "SELECT min(1 COLLATE missing, 2) LIMIT 0;",
                "SELECT max(1 COLLATE missing, 2) LIMIT 0;",
                "SELECT nullif(1 COLLATE missing, 2) LIMIT 0;",
            ] {
                expect_missing_collation(&builtin, sql).await;
            }
            expect_limit_zero(
                &builtin,
                "SELECT max(1 ORDER BY 2 COLLATE missing) LIMIT 0;",
            )
            .await;

            let scalar_calls = Arc::new(AtomicUsize::new(0));
            let scalar = Connection::open(":memory:").await.unwrap();
            for name in ["min", "max", "nullif"] {
                scalar.register_deterministic_scalar_function(NeverInvokedScalar {
                    function_name: name,
                    arity: 2,
                    calls: Arc::clone(&scalar_calls),
                });
            }
            for sql in [
                "SELECT min(1 COLLATE missing, 2) LIMIT 0;",
                "SELECT max(1 COLLATE missing, 2) LIMIT 0;",
                "SELECT nullif(1 COLLATE missing, 2) LIMIT 0;",
            ] {
                expect_limit_zero(&scalar, sql).await;
            }
            expect_missing_collation(&scalar, "SELECT min(1 COLLATE missing, 2, 3) LIMIT 0;").await;
            assert_eq!(scalar_calls.load(AtomicOrdering::SeqCst), 0);

            let variadic_calls = Arc::new(AtomicUsize::new(0));
            let variadic = Connection::open(":memory:").await.unwrap();
            variadic.register_deterministic_scalar_function(NeverInvokedScalar {
                function_name: "min",
                arity: -1,
                calls: Arc::clone(&variadic_calls),
            });
            for sql in [
                "SELECT min(1 COLLATE missing, 2) LIMIT 0;",
                "SELECT min(1 COLLATE missing, 2, 3) LIMIT 0;",
            ] {
                expect_limit_zero(&variadic, sql).await;
            }
            assert_eq!(variadic_calls.load(AtomicOrdering::SeqCst), 0);

            let aggregate_calls = Arc::new(AtomicUsize::new(0));
            let aggregate = Connection::open(":memory:").await.unwrap();
            for (name, arity) in [("min", 1), ("max", 1), ("nullif", 2)] {
                aggregate.register_aggregate_function(NeverInvokedAggregate {
                    function_name: name,
                    arity,
                    calls: Arc::clone(&aggregate_calls),
                });
            }
            for sql in [
                "SELECT min(1 COLLATE missing) LIMIT 0;",
                "SELECT max(1 COLLATE missing) LIMIT 0;",
                "SELECT nullif(1 COLLATE missing, 2) LIMIT 0;",
            ] {
                expect_limit_zero(&aggregate, sql).await;
            }
            expect_missing_collation(
                &aggregate,
                "SELECT max(1 ORDER BY 2 COLLATE missing) LIMIT 0;",
            )
            .await;
            assert_eq!(aggregate_calls.load(AtomicOrdering::SeqCst), 0);
        });
    }

    #[test]
    fn test_fromless_window_runtime_input_evaluation_order() {
        use fsqlite_func::ScalarFunction;

        struct RecordWindowInput {
            label: &'static str,
            calls: Arc<std::sync::Mutex<Vec<&'static str>>>,
        }

        impl ScalarFunction for RecordWindowInput {
            fn invoke(&self, _args: &[SqliteValue]) -> Result<SqliteValue> {
                self.calls
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .push(self.label);
                Ok(SqliteValue::Integer(1))
            }

            fn num_args(&self) -> i32 {
                0
            }

            fn name(&self) -> &str {
                self.label
            }
        }

        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let calls = Arc::new(std::sync::Mutex::new(Vec::new()));
            for label in ["record_part", "record_order", "record_arg", "record_filter"] {
                conn.register_nondeterministic_scalar_function(RecordWindowInput {
                    label,
                    calls: Arc::clone(&calls),
                });
            }
            let sql = "SELECT sum(record_arg()) FILTER (WHERE record_filter()) \
                       OVER (PARTITION BY record_part() ORDER BY record_order());";
            let expected_order = ["record_part", "record_order", "record_arg", "record_filter"];

            let direct = conn.query(sql).await.unwrap();
            assert_eq!(direct[0].values(), &[SqliteValue::Integer(1)]);
            assert_eq!(
                calls
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .as_slice(),
                expected_order.as_slice()
            );

            calls
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clear();
            let prepared = conn.prepare(sql).await.unwrap();
            let prepared_rows = prepared.query().await.unwrap();
            assert_eq!(prepared_rows[0].values(), &[SqliteValue::Integer(1)]);
            assert_eq!(
                calls
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .as_slice(),
                expected_order.as_slice()
            );
        });
    }

