    #[test]
    fn test_expression_only_limit_zero_short_circuits_invalid_offset() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            for sql in [
                "SELECT 42 LIMIT 0 OFFSET NULL;",
                // bd-2fong parity: a bare `VALUES ... LIMIT` is a stock
                // parse error (pinned below); the derived form carries the
                // VALUES-shaped receipt.
                "SELECT * FROM (VALUES (42)) LIMIT 0 OFFSET NULL;",
            ] {
                let rows = conn
                    .query(sql)
                    .await
                    .expect("LIMIT zero must bypass OFFSET evaluation");
                assert!(rows.is_empty(), "unexpected rows for `{sql}`");
            }
            let bare = conn.query("VALUES (42) LIMIT 0 OFFSET NULL;").await;
            assert!(
                matches!(bare, Err(FrankenError::ParseError { .. })),
                "stock SQLite (3.46.1 oracle) rejects LIMIT after a bare VALUES term: {bare:?}"
            );
        });
    }

    #[test]
    fn test_expression_only_dynamic_limit_preserves_statement_bind_order() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let params = [
                SqliteValue::Integer(11),
                SqliteValue::Integer(12),
                SqliteValue::Integer(1),
                SqliteValue::Integer(0),
            ];

            let direct = conn
                .query_with_params("SELECT ?, ? LIMIT ? OFFSET ?;", &params)
                .await
                .unwrap();
            assert_eq!(
                direct[0].values(),
                &[SqliteValue::Integer(11), SqliteValue::Integer(12)]
            );

            let prepared = conn.prepare("SELECT ?, ? LIMIT ? OFFSET ?;").await.unwrap();
            let prepared_rows = prepared.query_with_params(&params).await.unwrap();
            assert_eq!(
                prepared_rows[0].values(),
                &[SqliteValue::Integer(11), SqliteValue::Integer(12)]
            );

            // bd-2fong parity: bare `VALUES ... ORDER BY/LIMIT` is a stock
            // parse error; the derived form preserves the statement-global
            // bind-order receipt (oracle: [3,1] sorted -> LIMIT 1 OFFSET 1
            // -> 3).
            let values_rows = conn
                .query_with_params(
                    "SELECT * FROM (VALUES (?), (?)) ORDER BY 1 LIMIT ? OFFSET ?;",
                    &[
                        SqliteValue::Integer(3),
                        SqliteValue::Integer(1),
                        SqliteValue::Integer(1),
                        SqliteValue::Integer(1),
                    ],
                )
                .await
                .unwrap();
            assert_eq!(values_rows[0].values(), &[SqliteValue::Integer(3)]);
            let bare = conn
                .query_with_params(
                    "VALUES (?), (?) ORDER BY 1 LIMIT ? OFFSET ?;",
                    &[
                        SqliteValue::Integer(3),
                        SqliteValue::Integer(1),
                        SqliteValue::Integer(1),
                        SqliteValue::Integer(1),
                    ],
                )
                .await;
            assert!(
                matches!(bare, Err(FrankenError::ParseError { .. })),
                "stock SQLite (3.46.1 oracle) rejects ORDER BY/LIMIT after a bare VALUES term: {bare:?}"
            );

            let literal_text = conn.query("SELECT 42 LIMIT '1' OFFSET '0';").await.unwrap();
            assert_eq!(literal_text[0].values(), &[SqliteValue::Integer(42)]);
            let bound_text = conn
                .query_with_params(
                    "SELECT 42 LIMIT ? OFFSET ?;",
                    &[SqliteValue::Text("1".into()), SqliteValue::Text("0".into())],
                )
                .await
                .unwrap();
            assert_eq!(bound_text[0].values(), &[SqliteValue::Integer(42)]);

            for (sql, params) in [
                (
                    "SELECT 42 LIMIT ?;",
                    vec![SqliteValue::Text("not-an-integer".into())],
                ),
                ("SELECT 42 LIMIT ?;", vec![SqliteValue::Float(1.5)]),
                ("SELECT 42 LIMIT ?;", vec![SqliteValue::Null]),
            ] {
                let error = conn
                    .query_with_params(sql, &params)
                    .await
                    .expect_err("invalid dynamic LIMIT must report datatype mismatch");
                assert!(
                    matches!(
                        error,
                        FrankenError::FunctionError(ref message)
                            if message == "datatype mismatch"
                    ),
                    "unexpected error for `{sql}` with {params:?}: {error}"
                );
            }
        });
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn test_expression_only_dynamic_limit_zero_precedes_row_expression_evaluation() {
        use fsqlite_func::ScalarFunction;

        struct FailIfInvoked;
        struct CountOrderCalls {
            calls: Arc<std::sync::atomic::AtomicUsize>,
        }

        impl ScalarFunction for FailIfInvoked {
            fn invoke(&self, _args: &[SqliteValue]) -> Result<SqliteValue> {
                Err(FrankenError::FunctionError(
                    "LIMIT zero evaluated a row expression".to_owned(),
                ))
            }

            fn num_args(&self) -> i32 {
                0
            }

            fn name(&self) -> &str {
                "fail_if_invoked"
            }
        }

        impl ScalarFunction for CountOrderCalls {
            fn invoke(&self, _args: &[SqliteValue]) -> Result<SqliteValue> {
                self.calls.fetch_add(1, AtomicOrdering::Relaxed);
                Ok(SqliteValue::Integer(0))
            }

            fn num_args(&self) -> i32 {
                0
            }

            fn name(&self) -> &str {
                "count_order_calls"
            }
        }

        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.register_deterministic_scalar_function(FailIfInvoked);
            let order_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            conn.register_nondeterministic_scalar_function(CountOrderCalls {
                calls: Arc::clone(&order_calls),
            });

            for sql in [
                "SELECT fail_if_invoked() LIMIT ?;",
                // bd-2fong parity: bare `VALUES ... LIMIT` is a stock parse
                // error; the derived form still short-circuits row
                // evaluation under LIMIT 0 (oracle: derived VALUES with an
                // overflowing expression returns zero rows, no error).
                "SELECT * FROM (VALUES (fail_if_invoked())) LIMIT ?;",
            ] {
                let rows = conn
                    .query_with_params(sql, &[SqliteValue::Integer(0)])
                    .await
                    .expect("LIMIT zero must precede row expression evaluation");
                assert!(rows.is_empty(), "unexpected rows for `{sql}`");
            }

            let prepared = conn
                .prepare("SELECT fail_if_invoked() LIMIT ?;")
                .await
                .unwrap();
            let rows = prepared
                .query_with_params(&[SqliteValue::Integer(0)])
                .await
                .expect("prepared LIMIT zero must precede row expression evaluation");
            assert!(rows.is_empty());

            for sql in [
                "SELECT count(*) ORDER BY abs(1) LIMIT 0;",
                "SELECT count(*) ORDER BY count(*) LIMIT 0;",
                "SELECT (SELECT 1) ORDER BY fail_if_invoked() LIMIT 0;",
            ] {
                let rows = conn
                    .query(sql)
                    .await
                    .expect("valid FROM-less ORDER BY shape must survive LIMIT zero");
                assert!(rows.is_empty(), "unexpected rows for `{sql}`");
            }
            assert_eq!(
                order_calls.load(AtomicOrdering::Relaxed),
                0,
                "LIMIT zero must not execute a valid ORDER BY function"
            );

            for sql in [
                "SELECT (SELECT 1) ORDER BY abs(1);",
                "SELECT (SELECT 1) ORDER BY 1 + 0;",
                "SELECT (SELECT 1) ORDER BY CAST(1 AS INTEGER);",
                "SELECT (SELECT 1) ORDER BY random();",
                "SELECT (SELECT 1) ORDER BY count(*);",
            ] {
                let rows = conn.query(sql).await.unwrap();
                assert_eq!(
                    rows[0].values(),
                    &[SqliteValue::Integer(1)],
                    "unexpected independent ORDER BY result for `{sql}`"
                );
                let prepared = conn.prepare(sql).await.unwrap();
                assert_eq!(
                    prepared.query().await.unwrap()[0].values(),
                    &[SqliteValue::Integer(1)],
                    "unexpected prepared independent ORDER BY result for `{sql}`"
                );
            }

            let counted_order_sql = "SELECT (SELECT 1) ORDER BY count_order_calls();";
            conn.query(counted_order_sql).await.unwrap();
            let prepared_counted_order = conn.prepare(counted_order_sql).await.unwrap();
            prepared_counted_order.query().await.unwrap();
            assert_eq!(
                order_calls.load(AtomicOrdering::Relaxed),
                2,
                "a nonzero one-row SELECT must evaluate its ORDER BY expression once"
            );

            for sql in [
                "SELECT no_such((SELECT 1));",
                "SELECT abs((SELECT 1), 2);",
                "SELECT no_such(count(*));",
                "SELECT abs(count(*), 2);",
                "SELECT no_such(), count(*) LIMIT 0;",
                "SELECT abs(), count(*) LIMIT 0;",
                "SELECT (SELECT 1) ORDER BY no_such() LIMIT 0;",
                "SELECT (SELECT 1) ORDER BY abs() LIMIT 0;",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("function resolution must precede execution/LIMIT zero");
                if let Ok(prepared) = conn.prepare(sql).await {
                    prepared
                        .query()
                        .await
                        .expect_err("prepared function resolution must report the same error");
                }
            }

            for sql in [
                "SELECT (SELECT 1) ORDER BY missing_alias LIMIT 0;",
                "SELECT (SELECT 1) ORDER BY 2 LIMIT 0;",
                "SELECT count(*) ORDER BY 2 LIMIT 0;",
                "SELECT missing_column, count(*) LIMIT 0;",
                "SELECT count(*) WHERE missing_column LIMIT 0;",
                "SELECT count(*) LIMIT 0 OFFSET missing_column;",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("LIMIT zero must not suppress static SELECT validation");
            }

            // bd-2fong parity: stock SQLite rejects the out-of-range ORDER BY
            // ordinal at PREPARE time (oracle 3.46.1: '1st ORDER BY term out
            // of range - should be between 1 and 1', and a literal LIMIT 0
            // does not suppress it). The old arm expected prepare to succeed
            // with the error deferred to execution; the intent — LIMIT zero
            // must never suppress ORDER BY shape validation — is preserved by
            // asserting the error surfaces no later than prepare.
            let invalid_order = conn.prepare("SELECT (SELECT 1) ORDER BY 2 LIMIT ?;").await;
            match invalid_order {
                Err(error) => {
                    let message = error.to_string();
                    assert!(
                        message.contains("ORDER BY term out of range"),
                        "prepare-time rejection must be the stock out-of-range error: {message}"
                    );
                }
                Ok(prepared) => {
                    prepared
                        .query_with_params(&[SqliteValue::Integer(0)])
                        .await
                        .expect_err(
                            "prepared LIMIT zero must not suppress ORDER BY shape validation",
                        );
                }
            }
        });
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn test_fromless_aggregate_group_having_and_star_semantics() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            assert!(
                conn.query("SELECT count(*) HAVING 0;")
                    .await
                    .unwrap()
                    .is_empty()
            );
            let having_true = conn.query("SELECT count(*) HAVING 1;").await.unwrap();
            assert_eq!(having_true[0].values(), &[SqliteValue::Integer(1)]);

            assert!(
                conn.query("SELECT count(*) WHERE 0 GROUP BY 'x';")
                    .await
                    .unwrap()
                    .is_empty()
            );
            let grouped = conn
                .query("SELECT count(*) WHERE 1 GROUP BY 'x';")
                .await
                .unwrap();
            assert_eq!(grouped[0].values(), &[SqliteValue::Integer(1)]);
            for sql in [
                "SELECT 5 AS x, count(*) GROUP BY x + 1;",
                "SELECT 5 AS x, count(*) GROUP BY abs(x);",
                "SELECT 5 AS x, count(*) GROUP BY CAST(x AS INTEGER);",
            ] {
                let rows = conn.query(sql).await.unwrap();
                assert_eq!(
                    rows[0].values(),
                    &[SqliteValue::Integer(5), SqliteValue::Integer(1)],
                    "unexpected nested GROUP BY alias result for `{sql}`"
                );
                let prepared = conn.prepare(sql).await.unwrap();
                assert_eq!(
                    prepared.query().await.unwrap()[0].values(),
                    &[SqliteValue::Integer(5), SqliteValue::Integer(1)],
                    "unexpected prepared nested GROUP BY alias result for `{sql}`"
                );
            }
            for sql in [
                "SELECT 1 GROUP BY 1;",
                "SELECT 1 GROUP BY +1;",
                "SELECT 1 GROUP BY abs(1);",
                "SELECT 1 GROUP BY 1 + 0;",
                "SELECT 1 GROUP BY (SELECT 1);",
                "SELECT 1 GROUP BY 1 HAVING 1;",
            ] {
                let rows = conn.query(sql).await.unwrap();
                assert_eq!(
                    rows[0].values(),
                    &[SqliteValue::Integer(1)],
                    "unexpected nonaggregate FROM-less GROUP BY result for `{sql}`"
                );
                let prepared = conn.prepare(sql).await.unwrap();
                assert_eq!(
                    prepared.query().await.unwrap()[0].values(),
                    &[SqliteValue::Integer(1)],
                    "unexpected prepared nonaggregate GROUP BY result for `{sql}`"
                );
            }
            for sql in [
                "SELECT 10 GROUP BY -1;",
                "SELECT 10 GROUP BY +2;",
                "SELECT 10 GROUP BY 2 COLLATE BINARY;",
                "SELECT 10 GROUP BY +(+2) COLLATE BINARY;",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("signed GROUP BY ordinal must be range-checked");
                if let Ok(prepared) = conn.prepare(sql).await {
                    prepared
                        .query()
                        .await
                        .expect_err("prepared signed GROUP BY ordinal must be range-checked");
                }
            }
            for sql in [
                "SELECT 10 ORDER BY 2 COLLATE BINARY;",
                "SELECT 10 ORDER BY -(-2) COLLATE BINARY;",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("COLLATE-wrapped ORDER BY ordinal must be range-checked");
                if let Ok(prepared) = conn.prepare(sql).await {
                    prepared.query().await.expect_err(
                        "prepared COLLATE-wrapped ORDER BY ordinal must be range-checked",
                    );
                }
            }

            let empty_aggregate = conn.query("SELECT 5, count(*) WHERE 0;").await.unwrap();
            assert_eq!(
                empty_aggregate[0].values(),
                &[SqliteValue::Integer(5), SqliteValue::Integer(0)]
            );
            let empty_having = conn
                .query("SELECT count(*) AS c WHERE 0 HAVING c = 0;")
                .await
                .unwrap();
            assert_eq!(empty_having[0].values(), &[SqliteValue::Integer(0)]);

            let alias_where = conn
                .query("SELECT count(*), 1 AS x WHERE x;")
                .await
                .unwrap();
            assert_eq!(
                alias_where[0].values(),
                &[SqliteValue::Integer(1), SqliteValue::Integer(1)]
            );
            let prepared_alias_where = conn
                .prepare("SELECT count(*), 1 AS x WHERE x;")
                .await
                .unwrap();
            assert_eq!(
                prepared_alias_where.query().await.unwrap()[0].values(),
                &[SqliteValue::Integer(1), SqliteValue::Integer(1)]
            );

            for sql in [
                "SELECT count(*) GROUP BY 1;",
                "SELECT count(*) AS c GROUP BY c;",
                "SELECT count(*) AS c GROUP BY c + 1;",
                "SELECT count(*) GROUP BY 1 LIMIT 0;",
                "SELECT count(*) AS c WHERE c = 1 LIMIT 0;",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("GROUP BY must not resolve to an aggregate result");
            }
            let aggregate_alias_in_where = conn.prepare("SELECT count(*) AS c WHERE c = 1;").await;
            if let Ok(prepared) = aggregate_alias_in_where {
                prepared
                    .query()
                    .await
                    .expect_err("prepared aggregate alias in WHERE must remain a misuse");
            }

            for sql in [
                "SELECT *, (SELECT 1);",
                "SELECT *, (SELECT 1) LIMIT 0;",
                "SELECT count(*), *;",
                "SELECT count(*), * LIMIT 0;",
                "SELECT missing.* , (SELECT 1) LIMIT 0;",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("FROM-less star projection must report a source error");
            }

            let scalar_alias_sql = "SELECT (SELECT 1) AS x WHERE x;";
            let scalar_alias = conn.query(scalar_alias_sql).await.unwrap();
            assert_eq!(scalar_alias[0].values(), &[SqliteValue::Integer(1)]);
            let prepared_scalar_alias = conn.prepare(scalar_alias_sql).await.unwrap();
            assert_eq!(
                prepared_scalar_alias.query().await.unwrap()[0].values(),
                &[SqliteValue::Integer(1)]
            );

            let dynamic_alias = conn
                .prepare("SELECT 1 AS x WHERE x LIMIT ?1;")
                .await
                .unwrap();
            assert_eq!(
                dynamic_alias
                    .query_with_params(&[SqliteValue::Integer(1)])
                    .await
                    .unwrap()[0]
                    .values(),
                &[SqliteValue::Integer(1)]
            );

            for (sql, expected) in [
                (
                    "SELECT 1 AS x, 2 AS x WHERE 1;",
                    Some(vec![SqliteValue::Integer(1), SqliteValue::Integer(2)]),
                ),
                ("SELECT 0 AS x, 1 AS x WHERE x;", None),
                (
                    "SELECT 1 AS x, 0 AS x WHERE x;",
                    Some(vec![SqliteValue::Integer(1), SqliteValue::Integer(0)]),
                ),
                (
                    "SELECT 1 AS x, 2 AS x ORDER BY abs(1);",
                    Some(vec![SqliteValue::Integer(1), SqliteValue::Integer(2)]),
                ),
                (
                    "SELECT (SELECT 1) AS x, (SELECT 2) AS x WHERE 1;",
                    Some(vec![SqliteValue::Integer(1), SqliteValue::Integer(2)]),
                ),
                ("SELECT (SELECT 0) AS x, (SELECT 1) AS x WHERE x;", None),
                (
                    "SELECT (SELECT 1) AS x, (SELECT 0) AS x WHERE x;",
                    Some(vec![SqliteValue::Integer(1), SqliteValue::Integer(0)]),
                ),
                (
                    "SELECT (SELECT 1) AS x, (SELECT 2) AS x ORDER BY abs(1);",
                    Some(vec![SqliteValue::Integer(1), SqliteValue::Integer(2)]),
                ),
            ] {
                let rows = conn.query(sql).await.unwrap();
                assert_eq!(
                    rows.first().map(|row| row.values().to_vec()),
                    expected,
                    "duplicate aliases must bind to the leftmost projection for `{sql}`"
                );
                let prepared = conn.prepare(sql).await.unwrap();
                let prepared_rows = prepared.query().await.unwrap();
                assert_eq!(
                    prepared_rows.first().map(|row| row.values().to_vec()),
                    expected,
                    "prepared duplicate aliases must bind leftmost for `{sql}`"
                );
            }

            let cyclic_alias_sql = "SELECT (SELECT x) AS x WHERE x;";
            conn.query(cyclic_alias_sql)
                .await
                .expect_err("cyclic FROM-less alias must fail closed");
            if let Ok(prepared) = conn.prepare(cyclic_alias_sql).await {
                prepared
                    .query()
                    .await
                    .expect_err("prepared cyclic alias must fail closed");
            }

            let aggregate_first_alias_sql = "SELECT count(*) AS x, 1 AS x WHERE x;";
            conn.query(aggregate_first_alias_sql)
                .await
                .expect_err("leftmost aggregate alias in WHERE must remain a misuse");
            if let Ok(prepared) = conn.prepare(aggregate_first_alias_sql).await {
                prepared
                    .query()
                    .await
                    .expect_err("prepared leftmost aggregate alias must remain a misuse");
            }

            let scalar_first_alias_sql = "SELECT 1 AS x, count(*) AS x WHERE x;";
            let scalar_first = conn.query(scalar_first_alias_sql).await.unwrap();
            assert_eq!(
                scalar_first[0].values(),
                &[SqliteValue::Integer(1), SqliteValue::Integer(1)]
            );
            let prepared_scalar_first = conn.prepare(scalar_first_alias_sql).await.unwrap();
            assert_eq!(
                prepared_scalar_first.query().await.unwrap()[0].values(),
                &[SqliteValue::Integer(1), SqliteValue::Integer(1)]
            );
        });
    }

    #[test]
    fn test_expression_only_order_by_placeholder_is_constant_not_ordinal() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            // bd-2fong parity: bare `VALUES ... ORDER BY` is a stock parse
            // error (pinned below); the derived form carries the receipt.
            // Oracle (C-SQLite 3.46.1): a BOUND placeholder in ORDER BY is a
            // constant (original row order preserved), while the literal `2`
            // is a column ordinal (rows reordered).
            let sql = "SELECT * FROM (VALUES (1, 2), (2, 1)) ORDER BY ? LIMIT ?;";
            let params = [SqliteValue::Integer(2), SqliteValue::Integer(2)];
            let expected = vec![
                vec![SqliteValue::Integer(1), SqliteValue::Integer(2)],
                vec![SqliteValue::Integer(2), SqliteValue::Integer(1)],
            ];

            let direct = conn.query_with_params(sql, &params).await.unwrap();
            assert_eq!(direct.iter().map(row_values).collect::<Vec<_>>(), expected);

            let prepared = conn.prepare(sql).await.unwrap();
            let prepared_rows = prepared.query_with_params(&params).await.unwrap();
            assert_eq!(
                prepared_rows.iter().map(row_values).collect::<Vec<_>>(),
                expected
            );

            let syntactic_ordinal = conn
                .query("SELECT * FROM (VALUES (1, 2), (2, 1)) ORDER BY 2;")
                .await
                .unwrap();
            assert_eq!(
                syntactic_ordinal.iter().map(row_values).collect::<Vec<_>>(),
                vec![
                    vec![SqliteValue::Integer(2), SqliteValue::Integer(1)],
                    vec![SqliteValue::Integer(1), SqliteValue::Integer(2)],
                ]
            );

            let bare = conn
                .query_with_params("VALUES (1, 2), (2, 1) ORDER BY ? LIMIT ?;", &params)
                .await;
            assert!(
                matches!(bare, Err(FrankenError::ParseError { .. })),
                "stock SQLite (3.46.1 oracle) rejects ORDER BY after a bare VALUES term: {bare:?}"
            );
        });
    }

