    #[test]
    fn test_expression_only_subqueries_route_from_where_and_values() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            for sql in [
                "SELECT 1 WHERE (SELECT 1);",
                "SELECT 1 WHERE EXISTS(SELECT 1);",
            ] {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(
                    direct[0].values(),
                    &[SqliteValue::Integer(1)],
                    "unexpected WHERE-subquery result for `{sql}`"
                );
                let prepared = conn.prepare(sql).await.unwrap();
                assert_eq!(
                    prepared.query().await.unwrap()[0].values(),
                    &[SqliteValue::Integer(1)],
                    "unexpected prepared WHERE-subquery result for `{sql}`"
                );
            }

            let values_sql = "VALUES ((SELECT 1)), ((SELECT 2));";
            let expected = vec![vec![SqliteValue::Integer(1)], vec![SqliteValue::Integer(2)]];
            let direct = conn.query(values_sql).await.unwrap();
            assert_eq!(direct.iter().map(row_values).collect::<Vec<_>>(), expected);
            let prepared = conn.prepare(values_sql).await.unwrap();
            assert_eq!(
                prepared
                    .query()
                    .await
                    .unwrap()
                    .iter()
                    .map(row_values)
                    .collect::<Vec<_>>(),
                expected
            );

            conn.execute("CREATE TABLE in_null_rhs (v INTEGER);")
                .await
                .unwrap();
            for (sql, expected) in [
                (
                    "SELECT NULL IN (SELECT v FROM in_null_rhs);",
                    SqliteValue::Integer(0),
                ),
                (
                    "SELECT NULL NOT IN (SELECT v FROM in_null_rhs);",
                    SqliteValue::Integer(1),
                ),
            ] {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(
                    direct[0].values(),
                    &[expected.clone()],
                    "NULL membership over an empty RHS has a definite result for `{sql}`"
                );
                let prepared = conn.prepare(sql).await.unwrap();
                assert_eq!(
                    prepared.query().await.unwrap()[0].values(),
                    &[expected],
                    "prepared NULL membership must preserve empty-RHS semantics for `{sql}`"
                );
            }

            conn.execute("INSERT INTO in_null_rhs VALUES (1);")
                .await
                .unwrap();
            for sql in [
                "SELECT NULL IN (SELECT v FROM in_null_rhs);",
                "SELECT NULL NOT IN (SELECT v FROM in_null_rhs);",
            ] {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(direct[0].values(), &[SqliteValue::Null]);
                let prepared = conn.prepare(sql).await.unwrap();
                assert_eq!(
                    prepared.query().await.unwrap()[0].values(),
                    &[SqliteValue::Null]
                );
            }
        });
    }

