    #[test]
    fn test_hash_join_residual_rechecks_text_affinity_after_numeric_hash_prefilter() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            const QUERY: &str = "SELECT count(*) FROM l JOIN r
             ON r.code = l.code AND l.code IS NOT NULL";
            let cases = [
                (
                    "CREATE TABLE l(code TEXT); CREATE TABLE r(code TEXT);
                 INSERT INTO l VALUES ('01'); INSERT INTO r VALUES ('1');",
                    0_i64,
                ),
                (
                    "CREATE TABLE l(code TEXT); CREATE TABLE r(code INTEGER);
                 INSERT INTO l VALUES ('01'); INSERT INTO r VALUES (1);",
                    1_i64,
                ),
            ];

            for (setup, expected) in cases {
                let conn = Connection::open(":memory:").await.unwrap();
                conn.execute(setup).await.unwrap();
                let rows = conn.query(QUERY).await.unwrap();
                let actual = match rows[0].get(0) {
                    Some(SqliteValue::Integer(value)) => *value,
                    other => panic!("unexpected FrankenSQLite count: {other:?}"),
                };

                let oracle = rusqlite::Connection::open_in_memory().unwrap();
                oracle.execute_batch(setup).unwrap();
                let sqlite_count: i64 = oracle.query_row(QUERY, [], |row| row.get(0)).unwrap();

                assert_eq!(sqlite_count, expected);
                assert_eq!(
                    actual, sqlite_count,
                    "hash candidate validation must preserve SQLite affinity semantics"
                );
            }
        });
    }

    #[test]
    fn test_canonical_hash_join_key_equality_implies_identical_hash() {
        use std::hash::{Hash, Hasher};

        fn key_hash(key: &CanonicalHashJoinKey) -> u64 {
            let mut hasher = std::collections::hash_map::DefaultHasher::new();
            key.hash(&mut hasher);
            hasher.finish()
        }

        let values = [
            SqliteValue::Null,
            SqliteValue::Integer(i64::MIN),
            SqliteValue::Integer(-1),
            SqliteValue::Integer(0),
            SqliteValue::Integer(1),
            SqliteValue::Integer(9_007_199_254_740_993),
            SqliteValue::Integer(i64::MAX),
            SqliteValue::Float(-0.0),
            SqliteValue::Float(0.0),
            SqliteValue::Float(1.0),
            SqliteValue::Float(i64::MIN as f64),
            SqliteValue::Float(f64::INFINITY),
            SqliteValue::Float(f64::NEG_INFINITY),
            SqliteValue::Float(f64::NAN),
            SqliteValue::Text("01".into()),
            SqliteValue::Text("1".into()),
            SqliteValue::Text("9007199254740993".into()),
            SqliteValue::Blob(b"1".to_vec().into()),
        ];

        for mode in [
            HashJoinKeyMode::Raw,
            HashJoinKeyMode::Text,
            HashJoinKeyMode::NumericCandidate,
        ] {
            let pairs = [HashJoinPair {
                left_idx: 0,
                right_idx: 0,
                mode,
            }];
            for left in &values {
                for right in &values {
                    let left_key =
                        build_canonical_hash_join_key(std::slice::from_ref(left), &pairs, false);
                    let right_key =
                        build_canonical_hash_join_key(std::slice::from_ref(right), &pairs, true);
                    if let (Some(left_key), Some(right_key)) = (left_key, right_key)
                        && left_key == right_key
                    {
                        assert_eq!(
                            key_hash(&left_key),
                            key_hash(&right_key),
                            "equal canonical keys must hash identically for mode {}: left={left:?}, right={right:?}",
                            match mode {
                                HashJoinKeyMode::Raw => "raw",
                                HashJoinKeyMode::Text => "text",
                                HashJoinKeyMode::NumericCandidate => "numeric",
                            }
                        );
                    }
                }
            }
        }

        let numeric_pairs = [HashJoinPair {
            left_idx: 0,
            right_idx: 0,
            mode: HashJoinKeyMode::NumericCandidate,
        }];
        assert!(
            build_canonical_hash_join_key(&[SqliteValue::Float(f64::NAN)], &numeric_pairs, false,)
                .is_none(),
            "NaN must never enter an equality hash bucket"
        );
    }

    #[test]
    fn test_canonical_hash_join_key_equality_matches_authoritative_binary_comparison() {
        let values = [
            SqliteValue::Null,
            SqliteValue::Integer(i64::MIN),
            SqliteValue::Integer(-1),
            SqliteValue::Integer(0),
            SqliteValue::Integer(1),
            SqliteValue::Integer(9_007_199_254_740_993),
            SqliteValue::Integer(i64::MAX),
            SqliteValue::Float(-0.0),
            SqliteValue::Float(0.0),
            SqliteValue::Float(1.0),
            SqliteValue::Float(2.5),
            SqliteValue::Float(f64::INFINITY),
            SqliteValue::Float(f64::NEG_INFINITY),
            SqliteValue::Float(f64::NAN),
            SqliteValue::Text("01".into()),
            SqliteValue::Text("1".into()),
            SqliteValue::Text("9007199254740993".into()),
            SqliteValue::Text("not numeric".into()),
            SqliteValue::Blob(b"1".to_vec().into()),
        ];
        let registry = CollationRegistry::new();

        for (mode, left_affinity, right_affinity, mode_name) in [
            (
                HashJoinKeyMode::Raw,
                TypeAffinity::Blob,
                TypeAffinity::Blob,
                "raw",
            ),
            (
                HashJoinKeyMode::Text,
                TypeAffinity::Text,
                TypeAffinity::Blob,
                "text",
            ),
            (
                HashJoinKeyMode::NumericCandidate,
                TypeAffinity::Numeric,
                TypeAffinity::Blob,
                "numeric",
            ),
        ] {
            let pairs = [HashJoinPair {
                left_idx: 0,
                right_idx: 0,
                mode,
            }];
            for left in &values {
                for right in &values {
                    let actual =
                        build_canonical_hash_join_key(std::slice::from_ref(left), &pairs, false)
                            .zip(build_canonical_hash_join_key(
                                std::slice::from_ref(right),
                                &pairs,
                                true,
                            ))
                            .is_some_and(|(left_key, right_key)| left_key == right_key);
                    let canonical_left = canonical_hash_join_value(left, mode);
                    let canonical_right = canonical_hash_join_value(right, mode);
                    let has_canonical_nan = matches!(canonical_left, SqliteValue::Float(value) if value.is_nan())
                        || matches!(canonical_right, SqliteValue::Float(value) if value.is_nan());
                    let expected = !left.is_null()
                        && !right.is_null()
                        && !has_canonical_nan
                        && cmp_values_with_comparison_affinity(
                            left,
                            right,
                            left_affinity,
                            right_affinity,
                            None,
                            &registry,
                        ) == std::cmp::Ordering::Equal;
                    assert_eq!(
                        actual, expected,
                        "canonical {mode_name} key diverged from authoritative equality: left={left:?}, right={right:?}",
                    );
                }
            }
        }
    }

    #[test]
    fn test_hash_join_candidate_prefilter_matches_sqlite_affinity_edges() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let cases = [
                (
                    "CREATE TABLE l(a BLOB, b INTEGER); CREATE TABLE r(a INTEGER, b INTEGER); \
                     INSERT INTO l VALUES ('01', 7); INSERT INTO r VALUES (1, 7);",
                    "SELECT count(*) FROM l JOIN r ON l.a = r.a AND l.b = r.b",
                ),
                (
                    "CREATE TABLE l(a BLOB); CREATE TABLE r(a BLOB); \
                     INSERT INTO l VALUES ('01'); INSERT INTO r VALUES (1);",
                    "SELECT count(*) FROM l JOIN r ON l.a = r.a",
                ),
                (
                    "CREATE TABLE l(a INTEGER, b TEXT); CREATE TABLE r(a NUMERIC, b TEXT); \
                     INSERT INTO l VALUES (9007199254740993, '01'); \
                     INSERT INTO r VALUES ('9007199254740993', '1');",
                    "SELECT count(*) FROM l JOIN r ON l.a = r.a AND l.b = r.b",
                ),
                (
                    "CREATE TABLE l(a INTEGER); CREATE TABLE r(a NUMERIC); \
                     INSERT INTO l VALUES (9007199254740993); \
                     INSERT INTO r VALUES ('9007199254740993');",
                    "SELECT count(*) FROM l JOIN r ON l.a = r.a",
                ),
            ];

            for (setup, query) in cases {
                let conn = Connection::open(":memory:").await.unwrap();
                conn.execute(setup).await.unwrap();
                FSQLITE_JOIN_HASH_FAST_PATH_HITS.with(|counter| counter.set(0));
                FSQLITE_JOIN_HASH_RESIDUAL_FAST_PATH_HITS.with(|counter| counter.set(0));
                FSQLITE_JOIN_HASH_RESIDUAL_CANDIDATE_EVALS.with(|counter| counter.set(0));
                let actual = conn.query(query).await.unwrap();

                let oracle = rusqlite::Connection::open_in_memory().unwrap();
                oracle.execute_batch(setup).unwrap();
                let expected: i64 = oracle.query_row(query, [], |row| row.get(0)).unwrap();

                assert_eq!(actual[0].values(), &[SqliteValue::Integer(expected)]);
                assert_eq!(
                    FSQLITE_JOIN_HASH_FAST_PATH_HITS.with(|counter| counter.get()),
                    1,
                    "affinity edge case must exercise the hash candidate lane: {query}"
                );
                assert_eq!(
                    FSQLITE_JOIN_HASH_RESIDUAL_FAST_PATH_HITS.with(|counter| counter.get()),
                    0,
                    "a pure binary equijoin must not retain a duplicate residual predicate: {query}"
                );
                assert_eq!(
                    FSQLITE_JOIN_HASH_RESIDUAL_CANDIDATE_EVALS.with(|counter| counter.get()),
                    0,
                    "a pure binary equijoin must not re-evaluate admitted equality terms: {query}"
                );
            }
        });
    }

    #[test]
    fn test_hash_join_using_recheck_offsets_right_column_in_combined_row() {
        asupersync::test_utils::run_test(|| async {
            const SETUP: &str = "CREATE TABLE l(x INTEGER, k INTEGER); \
                 CREATE TABLE r(k INTEGER); \
                 INSERT INTO l VALUES (99, 7); \
                 INSERT INTO r VALUES (7);";
            const QUERY: &str = "SELECT l.x, l.k, r.k FROM l JOIN r USING(k)";

            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(SETUP).await.unwrap();
            let actual = conn.query(QUERY).await.unwrap();

            let oracle = rusqlite::Connection::open_in_memory().unwrap();
            oracle.execute_batch(SETUP).unwrap();
            let expected = oracle
                .prepare(QUERY)
                .unwrap()
                .query_map([], |row| {
                    Ok(vec![
                        SqliteValue::Integer(row.get(0)?),
                        SqliteValue::Integer(row.get(1)?),
                        SqliteValue::Integer(row.get(2)?),
                    ])
                })
                .unwrap()
                .collect::<std::result::Result<Vec<_>, _>>()
                .unwrap();

            assert_eq!(
                actual.iter().map(row_values).collect::<Vec<_>>(),
                expected,
                "the USING recheck must treat the right key index as relative to the right input"
            );
        });
    }

    #[test]
    fn test_hash_join_residual_full_join_tracks_matches_only_after_residual_passes() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE l(id INTEGER PRIMARY KEY, k INTEGER, enabled INTEGER);
             CREATE TABLE r(id INTEGER PRIMARY KEY, k INTEGER);
             INSERT INTO l VALUES (1, 1, 0), (2, 2, 1);
             INSERT INTO r VALUES (10, 1), (20, 2), (30, 3);",
            )
            .await
            .unwrap();

            FSQLITE_JOIN_HASH_RESIDUAL_FAST_PATH_HITS.with(|counter| counter.set(0));
            FSQLITE_JOIN_HASH_RESIDUAL_CANDIDATE_EVALS.with(|counter| counter.set(0));
            let rows = conn
                .query(
                    "SELECT l.id, r.id FROM l FULL JOIN r
                 ON r.k = l.k AND l.enabled = 1",
                )
                .await
                .unwrap();
            let values = rows.iter().map(row_values).collect::<Vec<_>>();

            assert_eq!(values.len(), 4);
            assert!(values.contains(&vec![SqliteValue::Integer(1), SqliteValue::Null]));
            assert!(values.contains(&vec![SqliteValue::Integer(2), SqliteValue::Integer(20)]));
            assert!(values.contains(&vec![SqliteValue::Null, SqliteValue::Integer(10)]));
            assert!(values.contains(&vec![SqliteValue::Null, SqliteValue::Integer(30)]));
            assert_eq!(
                FSQLITE_JOIN_HASH_RESIDUAL_FAST_PATH_HITS.with(|counter| counter.get()),
                1
            );
            assert_eq!(
                FSQLITE_JOIN_HASH_RESIDUAL_CANDIDATE_EVALS.with(|counter| counter.get()),
                2,
                "only the two equality-key candidates should reach residual evaluation"
            );
        });
    }

    #[test]
    fn test_join_bindings_do_not_leak_into_correlated_on_subqueries() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            const SETUP: &str = "CREATE TABLE l(id INTEGER PRIMARY KEY, k INTEGER);
             CREATE TABLE r(id INTEGER PRIMARY KEY, k INTEGER);
             CREATE TABLE gate(l_id INTEGER);
             INSERT INTO l VALUES (1, 1), (2, 2);
             INSERT INTO r VALUES (10, 1), (20, 2);
             INSERT INTO gate VALUES (2);";
            const QUERY: &str = "SELECT l.id, r.id FROM l LEFT JOIN r
             ON r.k = l.k
                AND EXISTS (SELECT 1 FROM gate g WHERE g.l_id = l.id)
             ORDER BY l.id";

            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(SETUP).await.unwrap();
            let actual = conn
                .query(QUERY)
                .await
                .unwrap()
                .iter()
                .map(row_values)
                .collect::<Vec<_>>();

            let oracle = rusqlite::Connection::open_in_memory().unwrap();
            oracle.execute_batch(SETUP).unwrap();
            let mut statement = oracle.prepare(QUERY).unwrap();
            let expected = statement
                .query_map([], |row| {
                    Ok(vec![
                        row.get::<_, Option<i64>>(0)?
                            .map_or(SqliteValue::Null, SqliteValue::Integer),
                        row.get::<_, Option<i64>>(1)?
                            .map_or(SqliteValue::Null, SqliteValue::Integer),
                    ])
                })
                .unwrap()
                .collect::<std::result::Result<Vec<_>, _>>()
                .unwrap();

            assert_eq!(actual, expected);
            assert_eq!(
                actual,
                vec![
                    vec![SqliteValue::Integer(1), SqliteValue::Null],
                    vec![SqliteValue::Integer(2), SqliteValue::Integer(20)],
                ]
            );
        });
    }

    #[test]
    fn test_prepared_statement_simple_left_join_uses_compiled_path() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.set_reject_mem_fallback(true);
            conn.set_strict_mem_fallback_rejection(true);
            conn.execute("CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute(
            "CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER);",
        )
        .await
        .unwrap();
            conn.execute("INSERT INTO customers VALUES (1, 'alice'), (2, 'bob');")
                .await
                .unwrap();
            conn.execute("INSERT INTO orders VALUES (1, 1, 10);")
                .await
                .unwrap();

            let stmt = conn
            .prepare(
                "SELECT c.name, o.amount FROM customers c LEFT JOIN orders o ON o.customer_id = c.id ORDER BY c.id, o.id",
            )
            .await
            .unwrap();

            assert!(
                stmt.deferred_query_statement.is_none(),
                "simple LEFT JOIN should compile onto the table-backed VDBE path"
            );

            let rows = stmt.query().await.unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(
                row_values(&rows[0]),
                vec![SqliteValue::Text("alice".into()), SqliteValue::Integer(10)]
            );
            assert_eq!(
                row_values(&rows[1]),
                vec![SqliteValue::Text("bob".into()), SqliteValue::Null]
            );
        });
    }

