    #[test]
    fn test_prepared_statement_join_group_by_count_sum_prefers_deferred_hash_dispatch_on_memory_backend()
     {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute(
            "CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER);",
        )
        .await
        .unwrap();
            conn.execute("INSERT INTO customers VALUES (1, 'alice'), (2, 'bob');")
                .await
                .unwrap();
            conn.execute("INSERT INTO orders VALUES (1, 1, 10), (2, 1, 20), (3, 2, 5);")
                .await
                .unwrap();
            conn.execute("CREATE INDEX idx_orders_cust ON orders(customer_id);")
                .await
                .unwrap();

            let stmt = conn
            .prepare(
                "SELECT c.name, COUNT(*), SUM(o.amount) FROM customers c JOIN orders o ON o.customer_id = c.id GROUP BY c.name",
            )
            .await
            .unwrap();

            assert!(
                stmt.deferred_query_statement.is_some(),
                "memory-backed grouped inner JOIN COUNT+SUM should prefer deferred hash grouping when strict parity rejection is off"
            );
            let rows = stmt.query().await.unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(
                row_values(&rows[0]),
                vec![
                    SqliteValue::Text("alice".into()),
                    SqliteValue::Integer(2),
                    SqliteValue::Integer(30),
                ]
            );
            assert_eq!(
                row_values(&rows[1]),
                vec![
                    SqliteValue::Text("bob".into()),
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(5),
                ]
            );
        });
    }

