    #[test]
    fn test_aggregate_filter_nested_view_probe_rewrites_and_executes_correctly() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE products (id INTEGER PRIMARY KEY, category_name TEXT NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute(
                "CREATE TABLE categories (name TEXT PRIMARY KEY, active INTEGER NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute(
                "INSERT INTO categories VALUES ('products', 1), ('categories', 1), ('misc', 0);",
            )
            .await
            .unwrap();
            conn.execute(
                "INSERT INTO products VALUES
                (1, 'products'),
                (2, 'categories'),
                (3, 'misc'),
                (4, 'products');",
            )
            .await
            .unwrap();
            conn.execute(
                "CREATE VIEW active_category_names AS
             SELECT name FROM categories WHERE active = 1;",
            )
            .await
            .unwrap();

            let sql = "SELECT COUNT(*) FILTER (
                       WHERE category_name IN (
                           SELECT name FROM categories
                           WHERE name IN (SELECT name FROM active_category_names)
                       )
                   ) FROM products;";

            let row = conn.query_row(sql).await.unwrap();
            assert_eq!(row.values()[0], SqliteValue::Integer(3));

            let stmt = conn.prepare(sql).await.unwrap();
            assert!(
                stmt.deferred_query_statement.is_none(),
                "aggregate FILTER probes should rewrite nested views before prepare-time dispatch"
            );
            let row = stmt.query_row().await.unwrap();
            assert_eq!(row.values()[0], SqliteValue::Integer(3));
        });
    }

    #[test]
    fn test_prepared_statement_json_each_uses_dispatch_path() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let stmt = conn
                .prepare("SELECT * FROM json_each(json_array(10, 20)) ORDER BY key;")
                .await
                .unwrap();

            assert!(
                stmt.deferred_query_statement.is_some(),
                "table-valued JSON functions should stay on the fallback dispatch path"
            );
            assert_eq!(stmt.column_count(), 8);

            let rows = stmt.query().await.unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(rows[0].values().len(), 8);
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(0));
            assert_eq!(rows[0].values()[1], SqliteValue::Integer(10));
            assert_eq!(rows[0].values()[2], SqliteValue::Text("integer".into()));
            assert_eq!(rows[0].values()[6], SqliteValue::Text("$[0]".into()));
            assert_eq!(rows[1].values()[0], SqliteValue::Integer(1));
            assert_eq!(rows[1].values()[1], SqliteValue::Integer(20));
            assert_eq!(rows[1].values()[6], SqliteValue::Text("$[1]".into()));
        });
    }

