    #[test]
    fn test_aggregate_order_by_placeholders_participate_in_statement_bind_order() {
        let Statement::Select(select) = parse_single_statement(
            "SELECT group_concat(v ORDER BY ?), ? FROM aggregate_bind_order",
        )
        .unwrap() else {
            panic!("expected SELECT statement");
        };
        assert!(
            select_contains_any_placeholder(&select),
            "an aggregate's internal ORDER BY must make the SELECT parameter-dependent"
        );

        let canonical = canonicalize_select_placeholders(&select).unwrap();
        let SelectCore::Select { columns, .. } = &canonical.body.select else {
            panic!("expected SELECT core");
        };
        let ResultColumn::Expr {
            expr:
                Expr::FunctionCall {
                    order_by,
                    args: FunctionArgs::List(_),
                    ..
                },
            ..
        } = &columns[0]
        else {
            panic!("expected ordered aggregate projection");
        };
        assert!(matches!(
            &order_by[0].expr,
            Expr::Placeholder(PlaceholderType::Numbered(1), _)
        ));
        let ResultColumn::Expr {
            expr: Expr::Placeholder(PlaceholderType::Numbered(2), _),
            ..
        } = &columns[1]
        else {
            panic!("expected the later projection to claim bind slot two");
        };

        let bound = bind_placeholders_in_select_for_fallback(
            &canonical,
            Some(&[SqliteValue::Integer(11), SqliteValue::Integer(22)]),
        )
        .unwrap();
        let SelectCore::Select { columns, .. } = &bound.body.select else {
            panic!("expected bound SELECT core");
        };
        let ResultColumn::Expr {
            expr: Expr::FunctionCall { order_by, .. },
            ..
        } = &columns[0]
        else {
            panic!("expected bound ordered aggregate projection");
        };
        assert!(matches!(
            &order_by[0].expr,
            Expr::Literal(Literal::Integer(11), _)
        ));
        assert!(matches!(
            &columns[1],
            ResultColumn::Expr {
                expr: Expr::Literal(Literal::Integer(22), _),
                ..
            }
        ));
    }

