    #[test]
    fn test_prepared_simple_full_table_scan_query_uses_fast_path_and_sees_txn_rows() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE prep_full_scan_runtime (id INTEGER PRIMARY KEY, val TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO prep_full_scan_runtime VALUES (1, 'alpha'), (2, 'beta');")
                .await
                .unwrap();

            let stmt = conn
                .prepare("SELECT * FROM prep_full_scan_runtime;")
                .await
                .unwrap();
            assert!(matches!(
                stmt.prepared_query_fast_path.as_ref(),
                Some(&super::PreparedQueryFastPath::SimpleFullTableScan { .. })
            ));

            super::reset_hot_path_profile();
            let rows = stmt.query().await.unwrap();
            let actual = rows.iter().map(row_values).collect::<Vec<_>>();
            assert_eq!(
                actual,
                vec![
                    vec![SqliteValue::Integer(1), SqliteValue::Text("alpha".into())],
                    vec![SqliteValue::Integer(2), SqliteValue::Text("beta".into())],
                ]
            );

            let profile = super::hot_path_profile_snapshot();
            assert_eq!(profile.parser.fast_path_executions, 1);
            assert_eq!(profile.parser.slow_path_executions, 0);

            conn.execute("BEGIN;").await.unwrap();
            conn.execute("INSERT INTO prep_full_scan_runtime VALUES (3, 'gamma');")
                .await
                .unwrap();
            let rows = stmt.query().await.unwrap();
            let actual = rows.iter().map(row_values).collect::<Vec<_>>();
            assert_eq!(
                actual,
                vec![
                    vec![SqliteValue::Integer(1), SqliteValue::Text("alpha".into())],
                    vec![SqliteValue::Integer(2), SqliteValue::Text("beta".into())],
                    vec![SqliteValue::Integer(3), SqliteValue::Text("gamma".into())],
                ]
            );
            conn.execute("COMMIT;").await.unwrap();
        });
    }

