    #[test]
    fn test_prepared_simple_string_projection_declines_registered_scalar_override() {
        use fsqlite_func::ScalarFunction;

        struct SentinelSubstr;

        impl ScalarFunction for SentinelSubstr {
            fn invoke(&self, _args: &[SqliteValue]) -> Result<SqliteValue> {
                Ok(SqliteValue::Text("sentinel".into()))
            }

            fn num_args(&self) -> i32 {
                2
            }

            fn name(&self) -> &str {
                "substr"
            }
        }

        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE prep_string_override (body TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO prep_string_override VALUES ('abcdef');")
                .await
                .unwrap();
            let sql = "SELECT SUBSTR(body, 1) FROM prep_string_override;";

            let builtin = conn.prepare(sql).await.unwrap();
            assert!(matches!(
                builtin.prepared_query_fast_path.as_ref(),
                Some(&super::PreparedQueryFastPath::SimpleStringScalarProjection { .. })
            ));
            super::reset_hot_path_profile();
            let builtin_rows = builtin.query().await.unwrap();
            assert_eq!(
                builtin_rows[0].values(),
                &[SqliteValue::Text("abcdef".into())]
            );
            let builtin_profile = super::hot_path_profile_snapshot();
            assert_eq!(builtin_profile.parser.fast_path_executions, 1);
            assert_eq!(builtin_profile.parser.slow_path_executions, 0);

            conn.register_deterministic_scalar_function(SentinelSubstr);
            let overridden = conn.prepare(sql).await.unwrap();
            assert!(!matches!(
                overridden.prepared_query_fast_path.as_ref(),
                Some(&super::PreparedQueryFastPath::SimpleStringScalarProjection { .. })
            ));
            let overridden_rows = overridden.query().await.unwrap();
            assert_eq!(
                overridden_rows[0].values(),
                &[SqliteValue::Text("sentinel".into())]
            );
        });
    }

