    #[test]
    fn test_prepared_count_indexed_in_rowid_probe_query_row_uses_fast_path() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL);")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE products (
                id INTEGER PRIMARY KEY,
                category_id INTEGER NOT NULL,
                name TEXT NOT NULL
            );",
            )
            .await
            .unwrap();
            conn.execute("CREATE INDEX products_category_id_idx ON products(category_id);")
                .await
                .unwrap();
            conn.execute(
                "INSERT INTO categories VALUES
                (1, 'alpha'),
                (2, 'beta'),
                (3, 'gamma'),
                (4, 'delta'),
                (5, 'epsilon');",
            )
            .await
            .unwrap();
            conn.execute(
                "INSERT INTO products VALUES
                (1, 1, 'p1'),
                (2, 1, 'p2'),
                (3, 2, 'p3'),
                (4, 3, 'p4'),
                (5, 4, 'p5'),
                (6, 5, 'p6');",
            )
            .await
            .unwrap();

            let stmt = conn
                .prepare(
                    "SELECT COUNT(*) FROM products \
                 WHERE category_id IN (SELECT id FROM categories WHERE id <= 2);",
                )
                .await
                .unwrap();
            assert!(
                matches!(
                    stmt.prepared_query_fast_path.as_ref(),
                    Some(&super::PreparedQueryFastPath::SimpleCountIndexedRowidProbe { .. })
                ),
                "actual fast path: {:?}",
                stmt.prepared_query_fast_path
            );

            let assert_fast_count = async |expected: i64, state: &str| {
                super::reset_hot_path_profile();
                let row = stmt.query_row().await.unwrap();
                let profile = super::hot_path_profile_snapshot();

                assert_eq!(
                    row.get(0),
                    Some(&SqliteValue::Integer(expected)),
                    "unexpected count for {state}"
                );
                assert_eq!(
                    profile.direct_count_indexed_rowid_probe_query_row_hits, 1,
                    "indexed rowid-probe fast path must serve exactly one query for {state}: {profile:?}"
                );
                assert_eq!(
                    profile.parser.fast_path_executions, 1,
                    "exactly one fast-path execution is expected for {state}: {profile:?}"
                );
                assert_eq!(
                    profile.parser.slow_path_executions, 0,
                    "query unexpectedly fell back to the slow path for {state}: {profile:?}"
                );
                assert_eq!(profile.direct_count_star_query_row_hits, 0);
                assert_eq!(profile.direct_rowid_lookup_query_row_hits, 0);
                assert_eq!(profile.direct_count_star_rowid_range_query_row_hits, 0);
            };

            assert_fast_count(3, "the initial fixture").await;

            conn.execute("INSERT INTO products VALUES (7, 2, 'p7');")
                .await
                .unwrap();
            assert_fast_count(4, "the product mutation").await;

            conn.execute("INSERT INTO categories VALUES (6, 'zeta');")
                .await
                .unwrap();
            assert_fast_count(4, "the non-matching category mutation").await;
        });
    }

    async fn populate_benchmark_subquery_fixture(conn: &Connection, count: usize) {
        for pragma in [
            "PRAGMA page_size = 4096;",
            "PRAGMA journal_mode = WAL;",
            "PRAGMA synchronous = NORMAL;",
            "PRAGMA cache_size = -64000;",
        ] {
            drop(conn.execute(pragma).await);
        }

        conn.execute(
            "CREATE TABLE products (
                id INTEGER PRIMARY KEY,
                name TEXT,
                price REAL,
                category_id INTEGER
            );",
        )
        .await
        .unwrap();
        conn.execute("CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT);")
            .await
            .unwrap();
        conn.execute("BEGIN;").await.unwrap();
        let cat_count = (count / 20).max(5);
        #[allow(clippy::cast_possible_wrap)]
        for i in 1..=cat_count as i64 {
            conn.execute(&format!("INSERT INTO categories VALUES ({i}, 'cat_{i}')"))
                .await
                .unwrap();
        }
        #[allow(clippy::cast_possible_wrap)]
        for i in 1..=count as i64 {
            let cid = (i % cat_count as i64) + 1;
            let price = i as f64 * 3.14;
            conn.execute(&format!(
                "INSERT INTO products VALUES ({i}, 'prod_{i}', {price}, {cid})"
            ))
            .await
            .unwrap();
        }
        conn.execute("COMMIT;").await.unwrap();
        conn.execute("CREATE INDEX idx_prod_cat ON products(category_id);")
            .await
            .unwrap();
    }

