    #[test]
    fn test_prepared_indexed_equality_repeat_probe_cache_tracks_probe_and_write() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE prep_idx_eq_repeat (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                score INTEGER
            );",
            )
            .await
            .unwrap();
            conn.execute("CREATE INDEX prep_idx_eq_repeat_name ON prep_idx_eq_repeat(name);")
                .await
                .unwrap();
            conn.execute(
                "INSERT INTO prep_idx_eq_repeat VALUES
                (1, 'alpha', 10),
                (2, 'beta', 20),
                (3, 'beta', 30);",
            )
            .await
            .unwrap();

            let stmt = conn
                .prepare("SELECT * FROM prep_idx_eq_repeat WHERE name = ?1;")
                .await
                .unwrap();

            super::reset_hot_path_profile();
            let beta = [SqliteValue::Text("beta".into())];
            let first_beta = stmt.query_with_params(&beta).await.unwrap();
            let second_beta = stmt.query_with_params(&beta).await.unwrap();
            assert_eq!(second_beta, first_beta);

            let alpha = stmt
                .query_with_params(&[SqliteValue::Text("alpha".into())])
                .await
                .unwrap();
            assert_eq!(
                alpha.iter().map(row_values).collect::<Vec<_>>(),
                vec![vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Text("alpha".into()),
                    SqliteValue::Integer(10),
                ]]
            );

            conn.execute("INSERT INTO prep_idx_eq_repeat VALUES (4, 'beta', 40);")
                .await
                .unwrap();
            let beta_after_write = stmt.query_with_params(&beta).await.unwrap();
            assert_eq!(
                beta_after_write.iter().map(row_values).collect::<Vec<_>>(),
                vec![
                    vec![
                        SqliteValue::Integer(2),
                        SqliteValue::Text("beta".into()),
                        SqliteValue::Integer(20),
                    ],
                    vec![
                        SqliteValue::Integer(3),
                        SqliteValue::Text("beta".into()),
                        SqliteValue::Integer(30),
                    ],
                    vec![
                        SqliteValue::Integer(4),
                        SqliteValue::Text("beta".into()),
                        SqliteValue::Integer(40),
                    ],
                ]
            );

            let profile = super::hot_path_profile_snapshot();
            assert!(profile.parser.fast_path_executions >= 4);
            assert_eq!(profile.parser.slow_path_executions, 0);
            assert_eq!(profile.direct_indexed_equality_query_hits, 4);
        });
    }

    #[test]
    fn test_prepared_indexed_equality_repeat_probe_cache_handles_large_table_small_result() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE prep_idx_eq_repeat_large (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                score INTEGER
            );",
            )
            .await
            .unwrap();
            conn.execute(
                "CREATE INDEX prep_idx_eq_repeat_large_name ON prep_idx_eq_repeat_large(name);",
            )
            .await
            .unwrap();
            conn.execute("BEGIN;").await.unwrap();
            for rowid in 1..=1_030_i64 {
                conn.execute(&format!(
                    "INSERT INTO prep_idx_eq_repeat_large VALUES ({rowid}, 'user_{rowid}', {});",
                    rowid * 7
                ))
                .await
                .unwrap();
            }
            conn.execute("COMMIT;").await.unwrap();

            let stmt = conn
                .prepare("SELECT * FROM prep_idx_eq_repeat_large WHERE name = ?1;")
                .await
                .unwrap();
            assert!(matches!(
                stmt.prepared_query_fast_path.as_ref(),
                Some(&super::PreparedQueryFastPath::SimpleIndexedEqualityLookup { .. })
            ));

            let probe = [SqliteValue::Text("user_1025".into())];
            super::reset_hot_path_profile();
            let first = stmt.query_with_params(&probe).await.unwrap();
            assert_eq!(
                first.iter().map(row_values).collect::<Vec<_>>(),
                vec![vec![
                    SqliteValue::Integer(1_025),
                    SqliteValue::Text("user_1025".into()),
                    SqliteValue::Integer(7_175),
                ]]
            );
            assert!(
                conn.prepared_indexed_equality_last_result
                    .borrow()
                    .is_some(),
                "single-row repeated indexed probes should be cacheable even when the table is large"
            );

            let second = stmt.query_with_params(&probe).await.unwrap();
            assert_eq!(second, first);

            let profile = super::hot_path_profile_snapshot();
            assert_eq!(profile.direct_indexed_equality_query_hits, 2);
            assert_eq!(profile.parser.slow_path_executions, 0);
        });
    }

