    #[test]
    fn test_prepared_indexed_equality_direct_path_survives_e2e_read_sequence() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            for pragma in [
                "PRAGMA page_size = 4096;",
                "PRAGMA journal_mode = WAL;",
                "PRAGMA synchronous = NORMAL;",
                "PRAGMA cache_size = -64000;",
                "PRAGMA fsqlite_capture_time_travel_snapshots=false;",
            ] {
                drop(conn.execute(pragma).await);
            }
            conn.execute(
                "CREATE TABLE bench (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                value REAL NOT NULL
            );",
            )
            .await
            .unwrap();
            conn.execute("BEGIN;").await.unwrap();
            let insert = conn
                .prepare("INSERT INTO bench VALUES (?1, ('user_' || ?1), (?1 * 0.137))")
                .await
                .unwrap();
            for id in 0..128_i64 {
                insert
                    .execute_with_params(&[SqliteValue::Integer(id)])
                    .await
                    .unwrap();
            }
            conn.execute("COMMIT;").await.unwrap();
            conn.execute("CREATE INDEX idx_name ON bench(name)")
                .await
                .unwrap();

            let scan_stmt = conn.prepare("SELECT * FROM bench").await.unwrap();
            for _ in 0..12 {
                assert_eq!(scan_stmt.query().await.unwrap().len(), 128);
            }

            let pk_stmt = conn
                .prepare("SELECT * FROM bench WHERE id = ?1")
                .await
                .unwrap();
            for _ in 0..12 {
                let pk_row = pk_stmt
                    .query_row_with_params(&[SqliteValue::Integer(64)])
                    .await
                    .unwrap();
                assert_eq!(
                    row_values(&pk_row),
                    vec![
                        SqliteValue::Integer(64),
                        SqliteValue::Text("user_64".into()),
                        SqliteValue::Float(64.0 * 0.137),
                    ]
                );
            }

            let range_stmt = conn
                .prepare("SELECT * FROM bench WHERE id >= ?1 AND id < ?2")
                .await
                .unwrap();
            for _ in 0..12 {
                assert_eq!(
                    range_stmt
                        .query_with_params(&[SqliteValue::Integer(32), SqliteValue::Integer(44)])
                        .await
                        .unwrap()
                        .len(),
                    12
                );
            }

            let count_stmt = conn.prepare("SELECT COUNT(*) FROM bench").await.unwrap();
            for _ in 0..12 {
                assert_eq!(
                    row_values(&count_stmt.query_row().await.unwrap()),
                    vec![SqliteValue::Integer(128)]
                );
            }

            let group_stmt = conn
                .prepare("SELECT (id / 12), SUM(value) FROM bench GROUP BY (id / 12)")
                .await
                .unwrap();
            for _ in 0..12 {
                assert_eq!(group_stmt.query().await.unwrap().len(), 11);
            }

            let stmt = conn
                .prepare("SELECT * FROM bench WHERE name = ?1")
                .await
                .unwrap();
            assert!(matches!(
                stmt.prepared_query_fast_path.as_ref(),
                Some(&super::PreparedQueryFastPath::SimpleIndexedEqualityLookup { .. })
            ));

            let diagnostic = format!(
                "direct_candidate={} memdb_ready={} rows_loaded={} requires_reload={} count_safe={} in_txn={} active_or_borrowed={} retained_txn={} retained_dirty_empty={} pending_upserts={} cached_write_bound={:?} visible_seq={:?} cached_write_mirror_exact={} fast_path={:?}",
                conn.clean_memory_prepared_memdb_direct_fast_path_candidate(&stmt),
                conn.prepared_memdb_query_fast_path_ready_with_mode(&stmt, false),
                conn.memdb_rows_loaded.get(),
                conn.memdb_requires_active_txn_reload.get(),
                conn.memdb_storage_count_shortcuts_safe.get(),
                conn.in_transaction.get(),
                conn.active_txn_is_open_or_borrowed(),
                conn.retained_autocommit_txn.borrow().is_some(),
                conn.retained_autocommit_dirty_tables.borrow().is_empty(),
                conn.pending_memdb_direct_upserts.borrow().len(),
                conn.cached_write_txn
                    .borrow()
                    .as_ref()
                    .and_then(|txn| txn.published_visible_commit_seq_hint()),
                *conn.memdb_visible_commit_seq.borrow(),
                conn.cached_write_txn_memdb_row_mirror_exact.get(),
                stmt.prepared_query_fast_path,
            );

            super::reset_hot_path_profile();
            let rows = stmt
                .query_with_params(&[SqliteValue::Text("user_64".into())])
                .await
                .unwrap();
            assert_eq!(
                rows.iter().map(row_values).collect::<Vec<_>>(),
                vec![vec![
                    SqliteValue::Integer(64),
                    SqliteValue::Text("user_64".into()),
                    SqliteValue::Float(64.0 * 0.137),
                ]]
            );

            let profile = super::hot_path_profile_snapshot();
            assert_eq!(
                profile.direct_indexed_equality_query_hits, 1,
                "indexed equality should hit direct path after e2e read sequence; {diagnostic}"
            );
            assert_eq!(
                profile.parser.slow_path_executions, 0,
                "indexed equality should not fall through to VDBE after e2e read sequence; {diagnostic}"
            );
        });
    }

