    #[test]
    fn test_file_backed_prepared_query_for_each_flushes_retained_autocommit_before_read() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let dir = tempfile::TempDir::new().unwrap();
            let db_path = dir.path().join("prep_idx_eq_refresh.db");
            let conn = Connection::open(db_path.to_string_lossy().into_owned())
                .await
                .unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode = OFF;")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE prep_idx_eq_refresh (id INTEGER PRIMARY KEY, name TEXT NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute("CREATE INDEX prep_idx_eq_refresh_name ON prep_idx_eq_refresh(name);")
                .await
                .unwrap();
            conn.execute("INSERT INTO prep_idx_eq_refresh VALUES (1, 'beta');")
                .await
                .unwrap();

            let stmt = conn
                .prepare("SELECT id, name FROM prep_idx_eq_refresh WHERE name = ?1 ORDER BY id;")
                .await
                .unwrap();

            super::reset_hot_path_profile();
            let mut initial_rows = Vec::new();
            stmt.query_with_params_for_each(&[SqliteValue::Text("beta".into())], |row| {
                initial_rows.push(row_values(row));
                Ok(())
            })
            .await
            .unwrap();
            assert_eq!(
                initial_rows,
                vec![vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Text("beta".into())
                ]]
            );

            conn.execute("INSERT INTO prep_idx_eq_refresh VALUES (2, 'beta');")
                .await
                .unwrap();

            let mut refreshed_rows = Vec::new();
            stmt.query_with_params_for_each(&[SqliteValue::Text("beta".into())], |row| {
                refreshed_rows.push(row_values(row));
                Ok(())
            })
            .await
            .unwrap();
            assert_eq!(
                refreshed_rows,
                vec![
                    vec![SqliteValue::Integer(1), SqliteValue::Text("beta".into())],
                    vec![SqliteValue::Integer(2), SqliteValue::Text("beta".into())],
                ],
                "prepared query_for_each must observe the same-connection committed write"
            );

            // bd-792q5: file-backed autocommit writes commit before execute
            // returns, so there is no parked retained batch to flush before this
            // read — the prepared query simply observes the durable committed
            // write. (The retained overlay / read-after-write flush is now a
            // `:memory:`-only mechanism.)
            assert!(
                conn.retained_autocommit_txn.borrow().is_none(),
                "file-backed autocommit write must commit before returning, never park"
            );
        });
    }

    #[test]
    fn test_file_backed_prepared_query_for_each_fallback_shape_observes_immediate_insert() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let dir = tempfile::TempDir::new().unwrap();
            let db_path = dir.path().join("prep_union_refresh.db");
            let conn = Connection::open(db_path.to_string_lossy().into_owned())
                .await
                .unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode = OFF;")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE prep_union_refresh (id INTEGER PRIMARY KEY, name TEXT NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO prep_union_refresh VALUES (1, 'beta');")
                .await
                .unwrap();

            let stmt = conn
                .prepare(
                    "SELECT id, name FROM prep_union_refresh WHERE name = ?1
                 UNION
                 SELECT id, name FROM prep_union_refresh WHERE name = ?1
                 ORDER BY id;",
                )
                .await
                .unwrap();
            assert!(
                stmt.deferred_query_statement.is_some() || stmt.db.is_none(),
                "UNION query should use the non-streaming prepared fallback path"
            );

            super::reset_hot_path_profile();
            let mut initial_rows = Vec::new();
            stmt.query_with_params_for_each(&[SqliteValue::Text("beta".into())], |row| {
                initial_rows.push(row_values(row));
                Ok(())
            })
            .await
            .unwrap();
            assert_eq!(
                initial_rows,
                vec![vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Text("beta".into())
                ]]
            );

            conn.execute("INSERT INTO prep_union_refresh VALUES (2, 'beta');")
                .await
                .unwrap();

            let mut refreshed_rows = Vec::new();
            stmt.query_with_params_for_each(&[SqliteValue::Text("beta".into())], |row| {
                refreshed_rows.push(row_values(row));
                Ok(())
            })
            .await
            .unwrap();
            assert_eq!(
                refreshed_rows,
                vec![
                    vec![SqliteValue::Integer(1), SqliteValue::Text("beta".into())],
                    vec![SqliteValue::Integer(2), SqliteValue::Text("beta".into())],
                ],
                "fallback prepared query_for_each path should see the just-inserted row"
            );

            let profile = super::hot_path_profile_snapshot();
            // bd-792q5: file-backed autocommit writes commit immediately, so the
            // fallback prepared query_for_each observes the committed insert with
            // no retained-batch flush (the row assertion above is the coverage).
            assert_eq!(
                profile.retained_autocommit_read_after_write_flushes, 0,
                "file-backed reads never flush a retained batch (none is parked): {profile:?}"
            );
        });
    }

    #[test]
    fn test_file_backed_query_with_params_observes_manual_insert_immediately() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let dir = tempfile::TempDir::new().unwrap();
            let db_path = dir.path().join("manual-read-after-write.db");
            let conn = Connection::open(db_path.to_string_lossy().into_owned())
                .await
                .unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode = OFF;")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE messages (
                id INTEGER PRIMARY KEY,
                conversation_id INTEGER NOT NULL,
                idx INTEGER NOT NULL,
                role TEXT NOT NULL,
                author TEXT,
                created_at INTEGER,
                content TEXT NOT NULL
            );",
            )
            .await
            .unwrap();
            conn.execute("CREATE INDEX idx_messages_conv_idx ON messages(conversation_id, idx);")
                .await
                .unwrap();
            conn.execute(
                "INSERT INTO messages
             (id, conversation_id, idx, role, author, created_at, content)
             VALUES (1, 1, 0, 'user', 'tester', 1700000000000, 'manual body');",
            )
            .await
            .unwrap();
            // bd-792q5: file-backed autocommit writes commit immediately and never
            // park, so no retained dirty-table set is populated.
            assert!(
                conn.retained_autocommit_txn.borrow().is_none(),
                "file-backed autocommit write must commit before returning, never park",
            );
            assert!(
                conn.retained_autocommit_dirty_tables.borrow().is_empty(),
                "committed file-backed writes leave no retained dirty-table state",
            );

            super::reset_hot_path_profile();
            let literal_rows = conn
                .query(
                    "SELECT id, idx, content FROM messages WHERE conversation_id = 1 ORDER BY idx",
                )
                .await;
            let profile_after_literal = super::hot_path_profile_snapshot();
            // bd-792q5: no parked batch to flush; the literal SELECT observes the
            // committed write directly.
            assert_eq!(
                profile_after_literal.retained_autocommit_read_after_write_flushes, 0,
                "file-backed reads never flush a retained batch (none is parked): {profile_after_literal:?}",
            );
            let literal_rows = literal_rows.unwrap();
            assert_eq!(
                literal_rows.len(),
                1,
                "literal SELECT should observe same-connection autocommit INSERT immediately"
            );

            conn.execute(
                "INSERT INTO messages
             (id, conversation_id, idx, role, author, created_at, content)
             VALUES (2, 1, 1, 'assistant', 'tester', 1700000000001, 'parameterized body');",
            )
            .await
            .unwrap();
            assert!(
                conn.retained_autocommit_txn.borrow().is_none(),
                "second file-backed INSERT also commits immediately, never parks",
            );

            super::reset_hot_path_profile();
            let parameterized_rows = conn
                .query_with_params(
                    "SELECT id, idx, content FROM messages WHERE conversation_id = ?1 ORDER BY idx",
                    &[SqliteValue::Integer(1)],
                )
                .await
                .unwrap();
            let profile_after_param = super::hot_path_profile_snapshot();
            assert_eq!(
                profile_after_param.retained_autocommit_read_after_write_flushes, 0,
                "file-backed reads never flush a retained batch (none is parked): {profile_after_param:?}",
            );
            assert_eq!(
                parameterized_rows.len(),
                2,
                "parameterized SELECT should observe same-connection autocommit INSERT immediately"
            );
        });
    }

