            conn.execute("CREATE VIEW v AS SELECT old_col FROM t;")
                .await
                .unwrap();
            conn.execute(
                "CREATE VIEW wrapper AS
             WITH v(old_col) AS (SELECT 1)
             SELECT old_col AS seen FROM v;",
            )
            .await
            .unwrap();

            conn.execute("ALTER TABLE t RENAME COLUMN old_col TO new_col;")
                .await
                .unwrap();

