    #[test]
    fn test_temp_and_main_view_namespaces_resolve_and_materialize_independently() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE VIEW main.same_name AS SELECT 1 AS value;")
                .await
                .unwrap();
            let persistent_cookie = conn.schema_cookie();
            conn.execute("CREATE TEMP VIEW temp.same_name AS SELECT 2 AS value;")
                .await
                .unwrap();
            assert_eq!(conn.schema_cookie(), persistent_cookie);

            let bare = conn.query("SELECT value FROM same_name;").await.unwrap();
            let main = conn
                .query("SELECT value FROM main.same_name;")
                .await
                .unwrap();
            let temp = conn
                .query("SELECT value FROM temp.same_name;")
                .await
                .unwrap();
            assert_eq!(bare[0].values(), &[SqliteValue::Integer(2)]);
            assert_eq!(main[0].values(), &[SqliteValue::Integer(1)]);
            assert_eq!(temp[0].values(), &[SqliteValue::Integer(2)]);

            let indices = conn.views_by_name.borrow()["same_name"];
            assert!(indices.main.is_some());
            assert!(indices.temp.is_some());
            let persisted = conn
                .query(
                    "SELECT count(*) FROM main.sqlite_schema \
                     WHERE type = 'view' AND name = 'same_name';",
                )
                .await
                .unwrap();
            assert_eq!(persisted[0].values(), &[SqliteValue::Integer(1)]);

            let cookie_before_temp_drop = conn.schema_cookie();
            conn.execute("DROP VIEW same_name;").await.unwrap();
            assert_eq!(conn.schema_cookie(), cookie_before_temp_drop);
            assert!(
                conn.view_index_for_scope("same_name", PragmaSchemaScope::Temp)
                    .is_none()
            );
            assert!(
                conn.view_index_for_scope("same_name", PragmaSchemaScope::Main)
                    .is_some()
            );
            let remaining = conn.query("SELECT * FROM same_name;").await.unwrap();
            assert_eq!(remaining[0].values(), &[SqliteValue::Integer(1)]);
        });
    }

    #[test]
    fn test_view_namespace_precedence_and_persistent_owner_binding() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE main.base (value INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO main.base VALUES (1);")
                .await
                .unwrap();
            conn.execute("CREATE VIEW main.owner_view(explicit_name) AS SELECT value FROM base;")
                .await
                .unwrap();
            conn.execute("CREATE TEMP TABLE temp.base (value INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO temp.base VALUES (2);")
                .await
                .unwrap();
            conn.execute("CREATE TEMP VIEW temp.temp_view AS SELECT value FROM base;")
                .await
                .unwrap();

            let persistent = conn
                .query("SELECT explicit_name FROM main.owner_view;")
                .await
                .unwrap();
            let temporary = conn
                .query("SELECT value FROM temp.temp_view;")
                .await
                .unwrap();
            assert_eq!(persistent[0].values(), &[SqliteValue::Integer(1)]);
            assert_eq!(temporary[0].values(), &[SqliteValue::Integer(2)]);

            let error = conn.execute("DROP VIEW base;").await.unwrap_err();
            assert!(matches!(error, FrankenError::Internal(message)
                    if message == "use DROP TABLE to delete table base"));
            assert!(conn.table_exists_for_scope("base", PragmaSchemaScope::Temp));
            assert!(conn.table_exists_for_scope("base", PragmaSchemaScope::Main));

            conn.execute("ATTACH ':memory:' AS aux;").await.unwrap();
            for sql in [
                "CREATE TEMP VIEW main.invalid_temp_view AS SELECT 1;",
                "CREATE TEMP VIEW aux.invalid_temp_view AS SELECT 1;",
            ] {
                let error = conn.execute(sql).await.unwrap_err();
                assert!(
                    matches!(&error, FrankenError::FunctionError(message)
                        if message == "temporary table name must be unqualified"),
                    "unexpected error for `{sql}`: {error:?}"
                );
            }

            for (sql, expected_schema) in [
                (
                    "CREATE VIEW main.cross_temp AS SELECT * FROM temp.base;",
                    "temp",
                ),
                (
                    "CREATE VIEW main.cross_aux AS SELECT * FROM aux.missing;",
                    "aux",
                ),
                (
                    "CREATE VIEW aux.cross_main AS SELECT * FROM main.base;",
                    "main",
                ),
            ] {
                let error = conn.execute(sql).await.unwrap_err();
                let expected = format!(
                    "view {} cannot reference objects in database {expected_schema}",
                    if expected_schema == "main" {
                        "cross_main"
                    } else if expected_schema == "temp" {
                        "cross_temp"
                    } else {
                        "cross_aux"
                    }
                );
                assert!(
                    matches!(&error, FrankenError::FunctionError(message)
                        if message.as_str() == expected.as_str()),
                    "unexpected cross-schema error for `{sql}`: {error:?}"
                );
            }

            // Object lookup precedes the cross-schema definition check for an
            // existing IF NOT EXISTS target, matching SQLite's no-op behavior.
            conn.execute("CREATE VIEW IF NOT EXISTS main.owner_view AS SELECT * FROM aux.missing;")
                .await
                .unwrap();
        });
    }

