    #[test]
    fn test_persistent_view_qualification_preserves_all_cte_names() {
        let Statement::Select(mut select) = parse_single_statement(
            "WITH first AS (SELECT * FROM later), \
             later AS (SELECT * FROM base) \
             SELECT * FROM first;",
        )
        .unwrap() else {
            panic!("expected SELECT");
        };

        qualify_persistent_view_relations(&mut select);
        let mut relations = Vec::new();
        visit_select_qualified_names(&select, &mut |name| {
            relations.push((name.schema.clone(), name.name.clone()));
            Ok(())
        })
        .unwrap();
        assert!(relations.contains(&(None, "later".to_owned())));
        assert!(relations.contains(&(None, "first".to_owned())));
        assert!(relations.contains(&(Some("main".to_owned()), "base".to_owned())));
    }

    #[test]
    fn test_create_view_rejects_parameters_even_with_if_not_exists() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE VIEW v AS SELECT 1;").await.unwrap();

            for sql in [
                "CREATE VIEW parameterized AS SELECT ?;",
                "CREATE VIEW IF NOT EXISTS v AS SELECT :value;",
            ] {
                let error = conn.execute(sql).await.unwrap_err();
                assert!(
                    matches!(&error, FrankenError::FunctionError(message)
                        if message == "parameters are not allowed in views"),
                    "unexpected error for `{sql}`: {error:?}"
                );
            }
        });
    }

