    #[test]
    fn test_trigger_dml_returning_trigger_table_star_keeps_inner_target_star() {
        let mut stmt = super::parse_single_statement(
            "UPDATE t SET name = 'inner' WHERE id = 1 RETURNING t.*;",
        )
        .unwrap();
        let frame = super::TriggerFrame {
            table_name: "t".to_owned(),
            trigger_name: "trg".to_owned(),
            column_names: vec!["id".to_owned(), "name".to_owned()],
            rowid_alias_col_idx: None,
            old_row: None,
            new_row: Some(vec![
                SqliteValue::Integer(1),
                SqliteValue::Text("outer".into()),
            ]),
        };

        super::bind_trigger_columns_in_statement(&mut stmt, &frame);

        let Statement::Update(update) = stmt else {
            panic!("expected UPDATE statement after trigger binding");
        };
        assert!(matches!(
            update.returning.as_slice(),
            [fsqlite_ast::ResultColumn::TableStar(name)]
                if name.schema.is_none() && name.name.eq_ignore_ascii_case("t")
        ));
    }

