    /// bd-wymdl (defect 3): every prepared-statement entry point must settle a
    /// deferred transaction-cleanup obligation before it runs.
    ///
    /// A statement prepared *before* a transaction and executed *after* that
    /// transaction's guard was dropped must observe a rolled-back transaction
    /// rather than silently continuing the abandoned one. `Connection::prepare`
    /// settles, but the prepared handle outlives that call, so each execution
    /// entry point needs its own settlement.
    ///
    /// Every arm asserts on `in_transaction()` *immediately* after the call
    /// under test, before any other SQL. That ordering is load-bearing: almost
    /// every other entry point settles too, so a later `query` would roll the
    /// transaction back itself and mask a missing settlement. Each arm fails
    /// without the `settle_pending_transaction_cleanup()` call in its own path.
    #[test]
    fn test_prepared_statement_entry_points_settle_abandoned_transaction() {
        asupersync::test_utils::run_test(|| async {
            async fn setup() -> Connection {
                let conn = Connection::open(":memory:").await.unwrap();
                conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER);")
                    .await
                    .unwrap();
                conn.execute("INSERT INTO t VALUES (1, 10);").await.unwrap();
                conn
            }

            // Open a transaction, dirty it, then abandon it exactly the way
            // `compat::Transaction::drop` does: record the obligation without
            // awaiting the rollback.
            async fn abandon_dirty_txn(conn: &Connection) {
                conn.begin_transaction().await.unwrap();
                conn.execute("INSERT INTO t VALUES (99, 990);")
                    .await
                    .unwrap();
                assert!(conn.in_transaction(), "setup: transaction should be open");
                conn.mark_transaction_cleanup_required();
            }

            // CONTROL ARM -- keeps every assertion below from passing
            // vacuously. Recording the obligation must NOT settle it by
            // itself; only an entry point may. If this arm ever fails, the
            // `!in_transaction()` assertions below prove nothing, because the
            // transaction would already be closed before the call under test.
            {
                let conn = setup().await;
                abandon_dirty_txn(&conn).await;
                assert!(
                    conn.in_transaction(),
                    "control: marking cleanup must not settle on its own -- \
                     if this fails, every arm below is vacuous"
                );
            }

            // PreparedStatement::query
            {
                let conn = setup().await;
                let stmt = conn.prepare("SELECT id FROM t;").await.unwrap();
                abandon_dirty_txn(&conn).await;
                stmt.query().await.unwrap();
                assert!(
                    !conn.in_transaction(),
                    "PreparedStatement::query must settle the abandoned transaction"
                );
            }

            // PreparedStatement::query_with_params -- settlement must also
            // precede the clean-memory indexed-equality fast path.
            {
                let conn = setup().await;
                let stmt = conn
                    .prepare("SELECT id FROM t WHERE id = ?1;")
                    .await
                    .unwrap();
                abandon_dirty_txn(&conn).await;
                stmt.query_with_params(&[SqliteValue::Integer(1)])
                    .await
                    .unwrap();
                assert!(
                    !conn.in_transaction(),
                    "PreparedStatement::query_with_params must settle before its fast path"
                );
            }

            // PreparedStatement::query_with_params_for_each
            {
                let conn = setup().await;
                let stmt = conn
                    .prepare("SELECT id FROM t WHERE id = ?1;")
                    .await
                    .unwrap();
                abandon_dirty_txn(&conn).await;
                stmt.query_with_params_for_each(&[SqliteValue::Integer(1)], |_row| Ok(()))
                    .await
                    .unwrap();
                assert!(
                    !conn.in_transaction(),
                    "PreparedStatement::query_with_params_for_each must settle"
                );
            }

            // PreparedStatement::query_row_with_params -- funnels through
            // `query_row_internal`, which also has fast paths to guard.
            {
                let conn = setup().await;
                let stmt = conn
                    .prepare("SELECT id FROM t WHERE id = ?1;")
                    .await
                    .unwrap();
                abandon_dirty_txn(&conn).await;
                stmt.query_row_with_params(&[SqliteValue::Integer(1)])
                    .await
                    .unwrap();
                assert!(
                    !conn.in_transaction(),
                    "query_row_internal must settle before its rowid-lookup fast path"
                );
            }

            // PreparedStatement::execute_with_params -- DML, routes to
            // Connection::execute_prepared_with_params. This is the arm that
            // could durably write into an abandoned transaction.
            {
                let conn = setup().await;
                let stmt = conn
                    .prepare("INSERT INTO t VALUES (?1, ?2);")
                    .await
                    .unwrap();
                abandon_dirty_txn(&conn).await;
                stmt.execute_with_params(&[SqliteValue::Integer(5), SqliteValue::Integer(50)])
                    .await
                    .unwrap();
                assert!(
                    !conn.in_transaction(),
                    "prepared DML must settle the abandoned transaction before writing"
                );
                // The abandoned transaction's row must be gone, and the new
                // write must have landed in autocommit.
                let abandoned = conn.query("SELECT id FROM t WHERE id = 99;").await.unwrap();
                assert!(
                    abandoned.is_empty(),
                    "row written inside the abandoned transaction should have been rolled back"
                );
                let committed = conn.query("SELECT id FROM t WHERE id = 5;").await.unwrap();
                assert_eq!(
                    committed.len(),
                    1,
                    "the prepared write itself should have committed"
                );
            }

            // Connection::execute_prepared (no-params entry)
            {
                let conn = setup().await;
                let stmt = conn.prepare("INSERT INTO t VALUES (7, 70);").await.unwrap();
                abandon_dirty_txn(&conn).await;
                conn.execute_prepared(&stmt).await.unwrap();
                assert!(
                    !conn.in_transaction(),
                    "Connection::execute_prepared must settle the abandoned transaction"
                );
            }
        });
    }

    #[test]
    fn test_recursive_trigger_depth_limit() {
        // A native stack overflow aborts the process rather than unwinding.
        // Keep the ordinary test runner alive by placing the pinned-stack
        // workload in a dedicated helper process and asserting on its exit.
        let helper_name = "connection::tests::helper_recursive_trigger_depth_limit_on_pinned_stack";
        let mut child = std::process::Command::new(
            std::env::current_exe().expect("test binary path should be available"),
        )
        .arg(helper_name)
        .arg("--exact")
        .arg("--nocapture")
        .env("FSQLITE_TRIGGER_DEPTH_HELPER", "1")
        .spawn()
        .expect("trigger-depth helper process should launch");
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(60);
        loop {
            match child.try_wait() {
                Ok(Some(status)) => {
                    assert!(
                        status.success(),
                        "the configured trigger cap did not fail cleanly on a requested 1 MiB \
                         stack: {status}"
                    );
                    break;
                }
                Ok(None) if std::time::Instant::now() < deadline => {
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
                Ok(None) => {
                    let kill_result = child.kill();
                    let wait_result = child.wait();
                    panic!(
                        "the configured trigger cap did not finish within 60 seconds on a \
                         requested 1 MiB stack; kill={kill_result:?}, wait={wait_result:?}"
                    );
                }
                Err(error) => {
                    let kill_result = child.kill();
                    let wait_result = child.wait();
                    panic!(
                        "could not wait for trigger-depth helper process: {error}; \
                         kill={kill_result:?}, wait={wait_result:?}"
                    );
                }
            }
        }
    }

    #[test]
    fn helper_recursive_trigger_depth_limit_on_pinned_stack() {
        if !std::env::var("FSQLITE_TRIGGER_DEPTH_HELPER").is_ok_and(|value| value == "1") {
            return;
        }

        // F-PGM.11: Recursive triggers must be bounded at MAX_TRIGGER_DEPTH.
        // Request a 1 MiB helper-thread stack so compiler frame growth cannot
        // silently move the process-abort boundary below the configured typed
        // error boundary. Platforms may provide a larger stack; the parent
        // test above contains either an abort or a hang.
        std::thread::Builder::new()
            .name("recursive-trigger-depth-limit".to_owned())
            .stack_size(1024 * 1024)
            .spawn(|| {
                asupersync::test_utils::run_test(|| async {
                    // Without recursive_triggers=ON, the default behavior
                    // suppresses same-table re-entry. Two tables therefore
                    // ping-pong until admission reaches the configured cap.
                    let conn = Connection::open(":memory:").await.unwrap();
                    conn.execute("PRAGMA recursive_triggers = ON;")
                        .await
                        .unwrap();
                    conn.execute("CREATE TABLE a (n INTEGER);").await.unwrap();
                    conn.execute("CREATE TABLE b (n INTEGER);").await.unwrap();
                    conn.execute("INSERT INTO a VALUES (0);").await.unwrap();
                    conn.execute("INSERT INTO b VALUES (0);").await.unwrap();
                    conn.execute(
                        "CREATE TRIGGER trg_a AFTER UPDATE ON a \
                         BEGIN UPDATE b SET n = NEW.n + 1; END;",
                    )
                    .await
                    .unwrap();
                    conn.execute(
                        "CREATE TRIGGER trg_b AFTER UPDATE ON b \
                         BEGIN UPDATE a SET n = NEW.n + 1; END;",
                    )
                    .await
                    .unwrap();
                    let error = conn
                        .execute("UPDATE a SET n = 1;")
                        .await
                        .expect_err("the recursive trigger cap should fire");
                    assert!(
                        matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                        "depth limit must use the typed recursion error, got {error:?}"
                    );
                    assert_eq!(
                        error.to_string(),
                        "too many levels of trigger recursion",
                        "unexpected trigger-depth error"
                    );
                    assert!(
                        conn.trigger_frame_stack.borrow().is_empty(),
                        "every admitted trigger frame must unwind after the depth error"
                    );
                    assert!(
                        !conn.in_transaction(),
                        "a failed autocommit trigger statement must leave no transaction open"
                    );
                    assert_eq!(
                        conn.internal_statement_savepoint_depth.get(),
                        0,
                        "the failed trigger statement must unwind its internal savepoint"
                    );
                    assert!(
                        conn.savepoints.borrow().is_empty(),
                        "the failed trigger statement must leave no user-visible savepoint"
                    );
                    let rows = conn
                        .query("SELECT (SELECT n FROM a), (SELECT n FROM b);")
                        .await
                        .expect("the connection must remain reusable after trigger-depth failure");
                    assert_eq!(
                        row_values(&rows[0]),
                        vec![SqliteValue::Integer(0), SqliteValue::Integer(0)],
                        "the failed recursive statement must roll back every nested write"
                    );
                });
            })
            .expect("spawn requested-1-MiB trigger-depth helper thread")
            .join()
            .expect("trigger-depth helper thread panicked");
    }

    #[test]
    fn trigger_depth_limit_charges_only_admitted_triggers() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let event = fsqlite_ast::TriggerEvent::Delete;

            // A zero budget catches any check performed before trigger matching.
            // Calls with no matching trigger do not recurse and must remain no-ops.
            set_trigger_depth_limit_override(Some(0));
            let before = conn
                .fire_before_triggers("missing", &event, None, None)
                .await;
            let after = conn
                .fire_after_triggers("missing", &event, None, None)
                .await;
            let instead_of = conn
                .fire_instead_of_triggers("missing_view", &[], &event, None, None)
                .await;
            set_trigger_depth_limit_override(None);

            assert!(!before.unwrap());
            after.unwrap();
            instead_of.unwrap();
        });
    }

    /// Build the two-table ping-pong trigger chain used by the depth
    /// diagnostics, bounded by a `WHEN` clause so the chain terminates at
    /// `depth` frames without relying on `MAX_TRIGGER_DEPTH`.
    async fn build_bounded_trigger_chain(depth: usize) -> Connection {
        let conn = Connection::open(":memory:").await.unwrap();
        conn.execute("PRAGMA recursive_triggers = ON;")
            .await
            .unwrap();
        conn.execute("CREATE TABLE a (n INTEGER);").await.unwrap();
        conn.execute("CREATE TABLE b (n INTEGER);").await.unwrap();
        conn.execute("INSERT INTO a VALUES (0);").await.unwrap();
        conn.execute("INSERT INTO b VALUES (0);").await.unwrap();
        conn.execute(&format!(
            "CREATE TRIGGER trg_a AFTER UPDATE ON a WHEN NEW.n < {depth} \
             BEGIN UPDATE b SET n = NEW.n + 1; END;"
        ))
        .await
        .unwrap();
        conn.execute(&format!(
            "CREATE TRIGGER trg_b AFTER UPDATE ON b WHEN NEW.n < {depth} \
             BEGIN UPDATE a SET n = NEW.n + 1; END;"
        ))
        .await
        .unwrap();
        conn
    }

    #[test]
    fn recursive_trigger_depth_limit_accepts_exact_boundary_and_rejects_next() {
        run_on_large_stack("recursive-depth-boundary", || {
            recursive_trigger_depth_limit_accepts_exact_boundary_and_rejects_next_body();
        });
    }

    fn recursive_trigger_depth_limit_accepts_exact_boundary_and_rejects_next_body() {
        asupersync::test_utils::run_test(|| async {
            let at_limit = build_bounded_trigger_chain(MAX_TRIGGER_DEPTH).await;
            at_limit
                .execute("UPDATE a SET n = 1;")
                .await
                .expect("the configured trigger-depth boundary must be admitted");
            assert!(
                at_limit.trigger_frame_stack.borrow().is_empty(),
                "successful boundary execution must unwind every trigger frame"
            );

            let over_limit = build_bounded_trigger_chain(MAX_TRIGGER_DEPTH + 1).await;
            let error = over_limit
                .execute("UPDATE a SET n = 1;")
                .await
                .expect_err("one trigger level beyond the configured boundary must fail");
            assert!(
                matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                "the first rejected level must use the typed depth error: {error:?}"
            );
            assert!(
                over_limit.trigger_frame_stack.borrow().is_empty(),
                "rejected boundary execution must unwind every admitted trigger frame"
            );
        });
    }

    // ─── bd-wymdl.1: charge trigger depth only after recursive_triggers
    //     suppression ─────────────────────────────────────────────────────

    /// Build a ring of `tables` distinct tables, each carrying one `timing`
    /// UPDATE trigger whose body updates the next table in the ring. With
    /// `PRAGMA recursive_triggers` at its default OFF, the last trigger's
    /// re-entry into the first is SUPPRESSED (same trigger name already on
    /// the frame stack), so a ring of exactly `tables` admitted bodies must
    /// complete without any depth charge for the suppressed entry.
    async fn build_recursive_off_trigger_ring(timing: &str, tables: usize) -> Connection {
        let conn = Connection::open(":memory:").await.unwrap();
        for i in 1..=tables {
            conn.execute(&format!("CREATE TABLE ring{i} (n INTEGER);"))
                .await
                .unwrap();
            conn.execute(&format!("INSERT INTO ring{i} VALUES (0);"))
                .await
                .unwrap();
        }
        for i in 1..=tables {
            let next = if i == tables { 1 } else { i + 1 };
            conn.execute(&format!(
                "CREATE TRIGGER ring_trg{i} {timing} UPDATE ON ring{i} \
                 BEGIN UPDATE ring{next} SET n = n + 1; END;"
            ))
            .await
            .unwrap();
        }
        conn
    }

    /// Assert the recursion, transaction, and savepoint state a suppressed or
    /// completed trigger program must leave behind (bd-wymdl.1 criterion 3).
    fn assert_trigger_program_state_clean(conn: &Connection) {
        assert!(
            conn.trigger_frame_stack.borrow().is_empty(),
            "trigger frame stack must unwind completely"
        );
        assert_eq!(conn.fk_cascade_depth.get(), 0, "FK depth must be restored");
        assert_eq!(
            conn.inherited_recursive_program_depth.get(),
            0,
            "inherited budget must be zero outside delegation"
        );
        assert!(!conn.in_transaction(), "no transaction may remain open");
        assert!(
            conn.savepoints.borrow().is_empty(),
            "no user savepoint may remain"
        );
        assert_eq!(
            conn.internal_statement_savepoint_depth.get(),
            0,
            "internal statement savepoints must unwind"
        );
    }

    async fn ring_values(conn: &Connection, tables: usize) -> Vec<i64> {
        let mut values = Vec::with_capacity(tables);
        for i in 1..=tables {
            let rows = conn
                .query(&format!("SELECT n FROM ring{i};"))
                .await
                .unwrap();
            match row_values(&rows[0])[0] {
                SqliteValue::Integer(n) => values.push(n),
                ref other => panic!("unexpected ring{i} value {other:?}"),
            }
        }
        values
    }

    /// bd-wymdl.1: with `recursive_triggers = OFF`, an exact
    /// `MAX_TRIGGER_DEPTH`-trigger re-entry ring reaches all eight admitted
    /// bodies. The suppressed ninth entry (ring_trg1 re-entered by ring_trg8's
    /// body) must NOT be charged against the depth budget: charging before
    /// suppression would reject this statement at the cap.
    #[test]
    fn recursive_off_after_ring_admits_exact_depth_and_rejects_next() {
        run_on_large_stack("recursive-off-after-ring-boundary", || {
            asupersync::test_utils::run_test(|| async {
                let at_limit = build_recursive_off_trigger_ring("AFTER", MAX_TRIGGER_DEPTH).await;
                at_limit
                    .execute("UPDATE ring1 SET n = n + 1;")
                    .await
                    .expect("suppressed re-entry must not consume the depth budget");
                // ring1 is updated by the outer statement AND by the last
                // trigger's body (whose own trigger is suppressed); every other
                // table is updated exactly once by its predecessor's body.
                let mut expected = vec![1_i64; MAX_TRIGGER_DEPTH];
                expected[0] = 2;
                assert_eq!(ring_values(&at_limit, MAX_TRIGGER_DEPTH).await, expected);
                assert_trigger_program_state_clean(&at_limit);

                // One more distinct trigger in the ring is a ninth ADMITTED body
                // and must be rejected with the typed depth error, unwinding all
                // charged frames and rolling back every nested write.
                let over_limit =
                    build_recursive_off_trigger_ring("AFTER", MAX_TRIGGER_DEPTH + 1).await;
                let error = over_limit
                    .execute("UPDATE ring1 SET n = n + 1;")
                    .await
                    .expect_err("the ninth admitted trigger body must exceed the cap");
                assert!(
                    matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                    "expected typed depth error, got {error:?}"
                );
                assert_eq!(
                    ring_values(&over_limit, MAX_TRIGGER_DEPTH + 1).await,
                    vec![0_i64; MAX_TRIGGER_DEPTH + 1],
                    "the failed statement must roll back every nested trigger write"
                );
                assert_trigger_program_state_clean(&over_limit);
            });
        });
    }

    /// bd-wymdl.1: same exact boundary for BEFORE-timing triggers.
    #[test]
    fn recursive_off_before_ring_admits_exact_depth_and_rejects_next() {
        run_on_large_stack("recursive-off-before-ring-boundary", || {
            asupersync::test_utils::run_test(|| async {
                let at_limit = build_recursive_off_trigger_ring("BEFORE", MAX_TRIGGER_DEPTH).await;
                at_limit
                    .execute("UPDATE ring1 SET n = n + 1;")
                    .await
                    .expect("suppressed BEFORE re-entry must not consume the depth budget");
                assert_eq!(
                    ring_values(&at_limit, MAX_TRIGGER_DEPTH).await,
                    vec![1_i64; MAX_TRIGGER_DEPTH],
                    "BEFORE bodies must not make the outer UPDATE re-evaluate its SET expression"
                );
                assert_trigger_program_state_clean(&at_limit);

                let over_limit =
                    build_recursive_off_trigger_ring("BEFORE", MAX_TRIGGER_DEPTH + 1).await;
                let error = over_limit
                    .execute("UPDATE ring1 SET n = n + 1;")
                    .await
                    .expect_err("the ninth admitted BEFORE trigger body must exceed the cap");
                assert!(
                    matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                    "expected typed depth error, got {error:?}"
                );
                assert_eq!(
                    ring_values(&over_limit, MAX_TRIGGER_DEPTH + 1).await,
                    vec![0_i64; MAX_TRIGGER_DEPTH + 1],
                    "the failed statement must roll back every nested trigger write"
                );
                assert_trigger_program_state_clean(&over_limit);
            });
        });
    }

    /// Build a ring of `views` INSTEAD OF UPDATE triggers. Each body records
    /// its execution in `body_log` and re-enters the next view; the final
    /// view's re-entry of view 1 is suppressed under `recursive_triggers=OFF`.
    async fn build_recursive_off_instead_of_ring(views: usize) -> Connection {
        let conn = Connection::open(":memory:").await.unwrap();
        conn.execute("CREATE TABLE body_log (entry INTEGER);")
            .await
            .unwrap();
        for i in 1..=views {
            conn.execute(&format!("CREATE TABLE base{i} (n INTEGER);"))
                .await
                .unwrap();
            conn.execute(&format!("INSERT INTO base{i} VALUES (0);"))
                .await
                .unwrap();
            conn.execute(&format!("CREATE VIEW v{i} AS SELECT n FROM base{i};"))
                .await
                .unwrap();
        }
        for i in 1..=views {
            let next = if i == views { 1 } else { i + 1 };
            conn.execute(&format!(
                "CREATE TRIGGER v_trg{i} INSTEAD OF UPDATE ON v{i} \
                 BEGIN INSERT INTO body_log VALUES ({i}); \
                 UPDATE v{next} SET n = 1; END;"
            ))
            .await
            .unwrap();
        }
        conn
    }

    /// bd-wymdl.1: INSTEAD OF triggers charge depth only after suppression.
    #[test]
    fn recursive_off_instead_of_ring_admits_exact_depth_and_rejects_next() {
        run_on_large_stack("recursive-off-instead-of-ring-boundary", || {
            asupersync::test_utils::run_test(|| async {
                let at_limit = build_recursive_off_instead_of_ring(MAX_TRIGGER_DEPTH).await;
                at_limit
                    .execute("UPDATE v1 SET n = 1;")
                    .await
                    .expect("suppressed INSTEAD OF re-entry must not consume the depth budget");
                let rows = at_limit
                    .query("SELECT entry FROM body_log ORDER BY entry;")
                    .await
                    .unwrap();
                let executed: Vec<SqliteValue> =
                    rows.iter().map(|row| row_values(row)[0].clone()).collect();
                let expected: Vec<SqliteValue> = (1..=MAX_TRIGGER_DEPTH)
                    .map(|i| SqliteValue::Integer(i64::try_from(i).unwrap()))
                    .collect();
                assert_eq!(
                    executed, expected,
                    "every admitted INSTEAD OF body must run exactly once"
                );
                assert_trigger_program_state_clean(&at_limit);

                let over_limit = build_recursive_off_instead_of_ring(MAX_TRIGGER_DEPTH + 1).await;
                let error = over_limit
                    .execute("UPDATE v1 SET n = 1;")
                    .await
                    .expect_err("the ninth admitted INSTEAD OF body must exceed the cap");
                assert!(
                    matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                    "expected typed depth error, got {error:?}"
                );
                let rows = over_limit
                    .query("SELECT COUNT(*) FROM body_log;")
                    .await
                    .unwrap();
                assert_eq!(
                    row_values(&rows[0])[0],
                    SqliteValue::Integer(0),
                    "the failed statement must roll back every logged body"
                );
                assert_trigger_program_state_clean(&over_limit);
            });
        });
    }

    /// bd-wymdl.1 differential: the recursive_triggers=OFF suppression ring
    /// must produce byte-identical table values in C SQLite (rusqlite, where
    /// SQLITE_MAX_TRIGGER_DEPTH=1000 leaves an 8-ring far below every cap) and
    /// FrankenSQLite (where the ring sits exactly AT the local cap, so any
    /// false charge for the suppressed entry diverges).
    #[test]
    fn differential_recursive_off_ring_matches_rusqlite() {
        run_on_large_stack(
            "connection::tests::differential_recursive_off_ring_matches_rusqlite",
            || {
                asupersync::test_utils::run_test(|| async {
                    for timing in ["BEFORE", "AFTER"] {
                        let sqlite = rusqlite::Connection::open_in_memory().unwrap();
                        for i in 1..=MAX_TRIGGER_DEPTH {
                            sqlite
                                .execute_batch(&format!(
                                    "CREATE TABLE ring{i} (n INTEGER); \
                                     INSERT INTO ring{i} VALUES (0);"
                                ))
                                .unwrap();
                        }
                        for i in 1..=MAX_TRIGGER_DEPTH {
                            let next = if i == MAX_TRIGGER_DEPTH { 1 } else { i + 1 };
                            sqlite
                                .execute_batch(&format!(
                                    "CREATE TRIGGER ring_trg{i} {timing} UPDATE ON ring{i} \
                                     BEGIN UPDATE ring{next} SET n = n + 1; END;"
                                ))
                                .unwrap();
                        }
                        sqlite.execute("UPDATE ring1 SET n = n + 1;", []).unwrap();
                        let reference: Vec<i64> = (1..=MAX_TRIGGER_DEPTH)
                            .map(|i| {
                                sqlite
                                    .query_row(&format!("SELECT n FROM ring{i};"), [], |row| {
                                        row.get(0)
                                    })
                                    .unwrap()
                            })
                            .collect();

                        let franken =
                            build_recursive_off_trigger_ring(timing, MAX_TRIGGER_DEPTH).await;
                        franken
                            .execute("UPDATE ring1 SET n = n + 1;")
                            .await
                            .expect("stock-SQLite-compatible suppression semantics");
                        assert_eq!(
                            ring_values(&franken, MAX_TRIGGER_DEPTH).await,
                            reference,
                            "{timing} ring diverged from C SQLite suppression semantics"
                        );
                    }
                });
            },
        );
    }

    /// bd-wymdl.1 criterion 4: the RAII guards that a dropped (cancelled)
    /// execution future runs are exactly what restores recursion state.
    #[test]
    fn trigger_frame_and_fk_guards_restore_state_on_drop() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let frame_guard = conn.push_trigger_frame(TriggerFrame {
                table_name: "t".to_owned(),
                trigger_name: "trg".to_owned(),
                column_names: Vec::new(),
                rowid_alias_col_idx: None,
                old_row: None,
                new_row: None,
            });
            assert_eq!(conn.trigger_frame_stack.borrow().len(), 1);
            let fk_guard = conn.enter_fk_cascade().unwrap();
            assert_eq!(conn.fk_cascade_depth.get(), 1);
            assert_eq!(conn.active_recursive_program_depth(), 2);
            // Dropping mid-program — which is what dropping an execute()
            // future at any await point does — must restore both counters.
            drop(fk_guard);
            assert_eq!(conn.fk_cascade_depth.get(), 0);
            drop(frame_guard);
            assert_trigger_program_state_clean(&conn);
        });
    }

    /// bd-wymdl.1 criterion 4: drop the execution future mid-flight if a
    /// pending point with charged frames is observable; in every case the
    /// connection must come back with zeroed recursion counters, no partial
    /// writes, and remain usable.
    #[test]
    fn dropping_recursive_trigger_execute_future_restores_recursion_state() {
        run_on_large_stack(
            "connection::tests::dropping_recursive_trigger_execute_future_restores_recursion_state",
            || {
                asupersync::test_utils::run_test(|| async {
                    let conn = build_bounded_trigger_chain(MAX_TRIGGER_DEPTH).await;
                    let completed = {
                        let mut future = std::pin::pin!(conn.execute("UPDATE a SET n = 1;"));
                        let mut task_cx = std::task::Context::from_waker(std::task::Waker::noop());
                        let mut completed = None;
                        for _ in 0..100_000 {
                            match future.as_mut().poll(&mut task_cx) {
                                std::task::Poll::Ready(result) => {
                                    completed = Some(result);
                                    break;
                                }
                                std::task::Poll::Pending => {
                                    if !conn.trigger_frame_stack.borrow().is_empty() {
                                        // Mid-program pending point observed:
                                        // cancel here by dropping the future
                                        // (loop exit).
                                        break;
                                    }
                                }
                            }
                        }
                        completed
                    };
                    // Whether the future completed or was dropped mid-program,
                    // the recursion counters must be fully restored ...
                    assert_trigger_program_state_clean(&conn);
                    // ... and the statement must have been atomic: either fully
                    // applied or fully rolled back.
                    let rows = conn
                        .query("SELECT (SELECT n FROM a), (SELECT n FROM b);")
                        .await
                        .expect("connection must remain usable after cancellation");
                    let observed = row_values(&rows[0]);
                    if let Some(result) = completed {
                        result.expect("bounded chain at the cap must succeed");
                        assert_ne!(
                            observed,
                            vec![SqliteValue::Integer(0), SqliteValue::Integer(0)],
                            "a completed statement must have applied its writes"
                        );
                    } else {
                        assert_eq!(
                            observed,
                            vec![SqliteValue::Integer(0), SqliteValue::Integer(0)],
                            "a cancelled statement must leave no partial writes"
                        );
                    }
                });
            },
        );
    }

    // ─── bd-wymdl.2: coherent trigger/FK depth overrides and the exact
    //     50/51 aggregate recursive-program boundary ──────────────────────

    /// bd-wymdl.2 criterion 1: the test-only override updates BOTH the local
    /// trigger cap and the aggregate trigger/FK cap coherently, and restores
    /// both on Drop (including nested overrides).
    #[test]
    fn depth_override_guard_updates_both_limits_and_restores_on_drop() {
        assert_eq!(trigger_depth_limit(), MAX_TRIGGER_DEPTH);
        assert_eq!(trigger_program_depth_limit(), MAX_TRIGGER_PROGRAM_DEPTH);
        {
            let _outer = TriggerDepthLimitOverrideGuard::new(64);
            assert_eq!(trigger_depth_limit(), 64);
            assert_eq!(
                trigger_program_depth_limit(),
                64,
                "raising the local cap must raise the aggregate cap with it"
            );
            {
                let _inner = TriggerDepthLimitOverrideGuard::new(3);
                assert_eq!(trigger_depth_limit(), 3);
                assert_eq!(
                    trigger_program_depth_limit(),
                    MAX_TRIGGER_PROGRAM_DEPTH,
                    "lowering the local cap must not shrink the aggregate budget"
                );
            }
            assert_eq!(trigger_depth_limit(), 64, "inner Drop must restore outer");
            assert_eq!(trigger_program_depth_limit(), 64);
        }
        assert_eq!(trigger_depth_limit(), MAX_TRIGGER_DEPTH);
        assert_eq!(trigger_program_depth_limit(), MAX_TRIGGER_PROGRAM_DEPTH);
    }

    /// Run `test` on a thread with an explicit large stack: aggregate-depth
    /// boundary programs execute ~50 nested statement pipelines, far beyond a
    /// default 2 MiB test stack in debug builds (~186 KiB/level measured).
    fn run_on_large_stack(name: &str, test: impl FnOnce() + Send + 'static) {
        std::thread::Builder::new()
            .name(name.to_owned())
            .stack_size(64 * 1024 * 1024)
            .spawn(test)
            .expect("spawn large-stack test thread")
            .join()
            .expect("large-stack test thread panicked");
    }

    /// bd-wymdl.2 criterion 5: a 64-entry chain proves the override itself
    /// (both caps observed at 64) without changing production policy.
    #[test]
    fn override_sixty_four_entry_trigger_chain_proves_coherent_override() {
        run_on_large_stack("override-64-entry-chain", || {
            asupersync::test_utils::run_test(|| async {
                let _override = TriggerDepthLimitOverrideGuard::new(64);
                let at_limit = build_bounded_trigger_chain(64).await;
                at_limit
                    .execute("UPDATE a SET n = 1;")
                    .await
                    .expect("64 trigger entries must be admitted under the 64 override");
                assert_trigger_program_state_clean(&at_limit);

                let over_limit = build_bounded_trigger_chain(65).await;
                let error = over_limit
                    .execute("UPDATE a SET n = 1;")
                    .await
                    .expect_err("the 65th entry must be rejected under the 64 override");
                assert!(
                    matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                    "expected typed depth error, got {error:?}"
                );
                assert_trigger_program_state_clean(&over_limit);
            });
        });
        // Production policy is unchanged: the override is thread-local and
        // scoped, and the compile-time constants keep their released values.
        assert_eq!(MAX_TRIGGER_DEPTH, 8);
        assert_eq!(MAX_TRIGGER_PROGRAM_DEPTH, 50);
        assert_eq!(trigger_depth_limit(), MAX_TRIGGER_DEPTH);
        assert_eq!(trigger_program_depth_limit(), MAX_TRIGGER_PROGRAM_DEPTH);
    }

    /// Build `trigger → fk_links FK cascades → trigger`: DELETE FROM start
    /// fires start_trg (program 1), whose body deletes the FK chain root;
    /// the chain charges `fk_links` FK-action programs; the deepest table's
    /// AFTER DELETE trigger is the final admitted program.
    /// Aggregate admitted depth = `fk_links + 2`.
    async fn build_trigger_fk_trigger_chain(fk_links: usize) -> Connection {
        let conn = Connection::open(":memory:").await.unwrap();
        conn.execute("PRAGMA foreign_keys = ON;").await.unwrap();
        conn.execute("CREATE TABLE trigger_log (entry INTEGER);")
            .await
            .unwrap();
        conn.execute("CREATE TABLE f0 (id INTEGER PRIMARY KEY);")
            .await
            .unwrap();
        for i in 1..=fk_links {
            let parent = i - 1;
            conn.execute(&format!(
                "CREATE TABLE f{i} (id INTEGER PRIMARY KEY, \
                 parent INTEGER REFERENCES f{parent}(id) ON DELETE CASCADE);"
            ))
            .await
            .unwrap();
        }
        conn.execute("INSERT INTO f0 VALUES (1);").await.unwrap();
        for i in 1..=fk_links {
            conn.execute(&format!("INSERT INTO f{i} VALUES (1, 1);"))
                .await
                .unwrap();
        }
        conn.execute("CREATE TABLE start (id INTEGER PRIMARY KEY);")
            .await
            .unwrap();
        conn.execute("INSERT INTO start VALUES (1);").await.unwrap();
        conn.execute(
            "CREATE TRIGGER start_trg AFTER DELETE ON start \
             BEGIN DELETE FROM f0 WHERE id = OLD.id; END;",
        )
        .await
        .unwrap();
        conn.execute(&format!(
            "CREATE TRIGGER tail_trg AFTER DELETE ON f{fk_links} \
             BEGIN INSERT INTO trigger_log VALUES (1); END;"
        ))
        .await
        .unwrap();
        conn
    }

    /// bd-wymdl.2 criterion 2: trigger → 48 FK → trigger succeeds at the
    /// exact aggregate depth of 50; trigger → 49 FK → trigger rejects the
    /// 51st admission with full unwind and rollback.
    #[test]
    fn mixed_trigger_fk_trigger_boundary_is_exactly_fifty() {
        run_on_large_stack("trigger-fk-trigger-50", || {
            asupersync::test_utils::run_test(|| async {
                // 48 FK links + the two trigger programs = aggregate 50.
                let at_limit = build_trigger_fk_trigger_chain(MAX_TRIGGER_PROGRAM_DEPTH - 2).await;
                at_limit
                    .execute("DELETE FROM start WHERE id = 1;")
                    .await
                    .expect("aggregate depth of exactly 50 must be admitted");
                let rows = at_limit
                    .query("SELECT COUNT(*) FROM trigger_log;")
                    .await
                    .unwrap();
                assert_eq!(
                    row_values(&rows[0])[0],
                    SqliteValue::Integer(1),
                    "the 50th program (tail trigger) must have executed"
                );
                let rows = at_limit
                    .query(&format!(
                        "SELECT COUNT(*) FROM f{};",
                        MAX_TRIGGER_PROGRAM_DEPTH - 2
                    ))
                    .await
                    .unwrap();
                assert_eq!(
                    row_values(&rows[0])[0],
                    SqliteValue::Integer(0),
                    "the full cascade chain must have executed"
                );
                assert_trigger_program_state_clean(&at_limit);

                // 49 FK links: the tail trigger would be admission 51.
                let over_limit =
                    build_trigger_fk_trigger_chain(MAX_TRIGGER_PROGRAM_DEPTH - 1).await;
                let error = over_limit
                    .execute("DELETE FROM start WHERE id = 1;")
                    .await
                    .expect_err("aggregate admission 51 must be rejected");
                assert!(
                    matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                    "expected typed depth error, got {error:?}"
                );
                // Full statement rollback: the parent row, every chain row,
                // and the log must be untouched.
                let rows = over_limit
                    .query("SELECT COUNT(*) FROM start;")
                    .await
                    .unwrap();
                assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(1));
                for i in 0..MAX_TRIGGER_PROGRAM_DEPTH {
                    let rows = over_limit
                        .query(&format!("SELECT COUNT(*) FROM f{i};"))
                        .await
                        .unwrap();
                    assert_eq!(
                        row_values(&rows[0])[0],
                        SqliteValue::Integer(1),
                        "chain table f{i} must be rolled back"
                    );
                }
                let rows = over_limit
                    .query("SELECT COUNT(*) FROM trigger_log;")
                    .await
                    .unwrap();
                assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(0));
                assert_trigger_program_state_clean(&over_limit);
            });
        });
    }

    /// Build `FK → trigger → tail_fk_links FK cascades`: DELETE FROM p
    /// cascades into c (program 1); c's AFTER DELETE trigger (program 2)
    /// deletes the root of a second cascade chain (programs 3..).
    /// Aggregate admitted depth = `tail_fk_links + 2`.
    async fn build_fk_trigger_fk_chain(tail_fk_links: usize) -> Connection {
        let conn = Connection::open(":memory:").await.unwrap();
        conn.execute("PRAGMA foreign_keys = ON;").await.unwrap();
        conn.execute("CREATE TABLE p (id INTEGER PRIMARY KEY);")
            .await
            .unwrap();
        conn.execute(
            "CREATE TABLE c (id INTEGER PRIMARY KEY, \
             parent INTEGER REFERENCES p(id) ON DELETE CASCADE);",
        )
        .await
        .unwrap();
        conn.execute("CREATE TABLE g0 (id INTEGER PRIMARY KEY);")
            .await
            .unwrap();
        for i in 1..=tail_fk_links {
            let parent = i - 1;
            conn.execute(&format!(
                "CREATE TABLE g{i} (id INTEGER PRIMARY KEY, \
                 parent INTEGER REFERENCES g{parent}(id) ON DELETE CASCADE);"
            ))
            .await
            .unwrap();
        }
        conn.execute("INSERT INTO p VALUES (1);").await.unwrap();
        conn.execute("INSERT INTO c VALUES (1, 1);").await.unwrap();
        conn.execute("INSERT INTO g0 VALUES (1);").await.unwrap();
        for i in 1..=tail_fk_links {
            conn.execute(&format!("INSERT INTO g{i} VALUES (1, 1);"))
                .await
                .unwrap();
        }
        conn.execute(
            "CREATE TRIGGER c_trg AFTER DELETE ON c \
             BEGIN DELETE FROM g0 WHERE id = OLD.id; END;",
        )
        .await
        .unwrap();
        conn
    }

    /// bd-wymdl.2 criterion 3: FK → trigger → 48 FK succeeds at 50; the
    /// 49-link variant rejects attempt 51 with full unwind and rollback.
    #[test]
    fn mixed_fk_trigger_fk_boundary_is_exactly_fifty() {
        run_on_large_stack("fk-trigger-fk-50", || {
            asupersync::test_utils::run_test(|| async {
                let at_limit = build_fk_trigger_fk_chain(MAX_TRIGGER_PROGRAM_DEPTH - 2).await;
                at_limit
                    .execute("DELETE FROM p WHERE id = 1;")
                    .await
                    .expect("aggregate depth of exactly 50 must be admitted");
                let rows = at_limit
                    .query(&format!(
                        "SELECT COUNT(*) FROM g{};",
                        MAX_TRIGGER_PROGRAM_DEPTH - 2
                    ))
                    .await
                    .unwrap();
                assert_eq!(
                    row_values(&rows[0])[0],
                    SqliteValue::Integer(0),
                    "the deepest cascade (program 50) must have executed"
                );
                assert_trigger_program_state_clean(&at_limit);

                let over_limit = build_fk_trigger_fk_chain(MAX_TRIGGER_PROGRAM_DEPTH - 1).await;
                let error = over_limit
                    .execute("DELETE FROM p WHERE id = 1;")
                    .await
                    .expect_err("aggregate admission 51 must be rejected");
                assert!(
                    matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                    "expected typed depth error, got {error:?}"
                );
                let rows = over_limit.query("SELECT COUNT(*) FROM p;").await.unwrap();
                assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(1));
                let rows = over_limit.query("SELECT COUNT(*) FROM c;").await.unwrap();
                assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(1));
                for i in 0..MAX_TRIGGER_PROGRAM_DEPTH {
                    let rows = over_limit
                        .query(&format!("SELECT COUNT(*) FROM g{i};"))
                        .await
                        .unwrap();
                    assert_eq!(
                        row_values(&rows[0])[0],
                        SqliteValue::Integer(1),
                        "chain table g{i} must be rolled back"
                    );
                }
                assert_trigger_program_state_clean(&over_limit);
            });
        });
    }

    // ─── bd-wymdl.3: one recursive-program budget across ATTACH delegation ──

    /// bd-wymdl.3 criterion 1: attached-schema delegation seeds the child
    /// connection with the parent's active recursive-program depth and
    /// restores the child baseline afterwards.
    #[test]
    fn attached_delegation_seeds_child_recursive_program_budget() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let aux_path = dir.path().join("seed-aux.db");
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(&format!(
                "ATTACH DATABASE '{}' AS aux;",
                aux_path.to_string_lossy()
            ))
            .await
            .unwrap();

            let frame_guard = conn.push_trigger_frame(TriggerFrame {
                table_name: "t".to_owned(),
                trigger_name: "trg".to_owned(),
                column_names: Vec::new(),
                rowid_alias_col_idx: None,
                old_row: None,
                new_row: None,
            });
            let fk_guard = conn.enter_fk_cascade().unwrap();
            conn.with_attached_connection("aux", |child| {
                assert_eq!(
                    child.inherited_recursive_program_depth.get(),
                    2,
                    "delegation must seed the parent's active program depth"
                );
                assert_eq!(child.active_recursive_program_depth(), 2);
                child
                    .ensure_trigger_program_admission_available()
                    .expect("depth 2 of 50 must still admit programs");
                Ok(())
            })
            .unwrap();
            drop(fk_guard);
            drop(frame_guard);
            conn.with_attached_connection("aux", |child| {
                assert_eq!(
                    child.inherited_recursive_program_depth.get(),
                    0,
                    "the child baseline must be restored after delegation"
                );
                Ok(())
            })
            .unwrap();
        });
    }

    /// Build an `fk_links`-deep ON DELETE CASCADE chain living entirely in
    /// the attached `aux` schema.
    ///
    /// C SQLite's trigger grammar (and ours — see `parse_dml_target_name`)
    /// rejects qualified table names inside trigger bodies, and unqualified
    /// trigger-body names never resolve into attached schemas, so SQL alone
    /// cannot express "main trigger body drives an attached cascade". The
    /// cross-schema recursive program is therefore driven through the real
    /// delegation entry point — a top-level qualified DELETE — while the
    /// parent connection holds an active trigger frame (the exact state a
    /// delegated statement observes mid-program). Aggregate admitted depth =
    /// `fk_links + 1` (one main trigger frame + the child's FK cascade
    /// programs), which is only enforced if the delegated child charges the
    /// SAME budget as the parent.
    async fn build_cross_schema_fk_chain(
        aux_path: &std::path::Path,
        fk_links: usize,
    ) -> Connection {
        let conn = Connection::open(":memory:").await.unwrap();
        conn.execute(&format!(
            "ATTACH DATABASE '{}' AS aux;",
            aux_path.to_string_lossy()
        ))
        .await
        .unwrap();
        // PRAGMA forwarding to attached child connections does not exist yet,
        // so arm FK enforcement on the child directly (test-only access).
        conn.with_attached_connection("aux", |child| {
            child.pragma_state.borrow_mut().foreign_keys = true;
            Ok(())
        })
        .unwrap();
        conn.execute("CREATE TABLE aux.f0 (id INTEGER PRIMARY KEY);")
            .await
            .unwrap();
        for i in 1..=fk_links {
            let parent = i - 1;
            conn.execute(&format!(
                "CREATE TABLE aux.f{i} (id INTEGER PRIMARY KEY, \
                 parent INTEGER REFERENCES f{parent}(id) ON DELETE CASCADE);"
            ))
            .await
            .unwrap();
        }
        conn.execute("INSERT INTO aux.f0 VALUES (1);")
            .await
            .unwrap();
        for i in 1..=fk_links {
            conn.execute(&format!("INSERT INTO aux.f{i} VALUES (1, 1);"))
                .await
                .unwrap();
        }
        conn
    }

    /// Push one parent trigger frame (test seam standing in for an active
    /// main-schema trigger program — SQL cannot hold one open across a
    /// qualified statement, see [`build_cross_schema_fk_chain`]).
    fn push_parent_program_frame(conn: &Connection) -> TriggerFrameGuard<'_> {
        conn.push_trigger_frame(TriggerFrame {
            table_name: "start".to_owned(),
            trigger_name: "start_trg".to_owned(),
            column_names: Vec::new(),
            rowid_alias_col_idx: None,
            old_row: None,
            new_row: None,
        })
    }

    /// bd-wymdl.3 criterion 2: an active main program plus a delegated
    /// attached-FK-cascade charges ONE aggregate budget: depth 50 succeeds,
    /// attempt 51 fails, and the attached child does not reset the boundary
    /// to zero.
    #[test]
    fn cross_schema_recursive_program_budget_is_not_reset_by_attach_delegation() {
        run_on_large_stack("cross-schema-budget-50", || {
            asupersync::test_utils::run_test(|| async {
                let dir = tempfile::tempdir().unwrap();

                // 49 FK links + 1 main trigger frame = aggregate 50: admitted.
                let at_limit = build_cross_schema_fk_chain(
                    &dir.path().join("aux-at-limit.db"),
                    MAX_TRIGGER_PROGRAM_DEPTH - 1,
                )
                .await;
                let frame_guard = push_parent_program_frame(&at_limit);
                at_limit
                    .execute("DELETE FROM aux.f0 WHERE id = 1;")
                    .await
                    .expect("cross-schema aggregate depth of exactly 50 must be admitted");
                drop(frame_guard);
                let rows = at_limit
                    .query(&format!(
                        "SELECT COUNT(*) FROM aux.f{};",
                        MAX_TRIGGER_PROGRAM_DEPTH - 1
                    ))
                    .await
                    .unwrap();
                assert_eq!(
                    row_values(&rows[0])[0],
                    SqliteValue::Integer(0),
                    "the deepest attached cascade must have executed"
                );
                assert_trigger_program_state_clean(&at_limit);
                at_limit
                    .with_attached_connection("aux", |child| {
                        assert_eq!(child.fk_cascade_depth.get(), 0);
                        assert_eq!(child.inherited_recursive_program_depth.get(), 0);
                        Ok(())
                    })
                    .unwrap();

                // 50 FK links: the deepest cascade is aggregate admission 51
                // and must be rejected even though it runs on the child. If
                // delegation reset the budget to zero, the child would admit
                // all 50 cascade programs and the DELETE would succeed.
                let over_limit = build_cross_schema_fk_chain(
                    &dir.path().join("aux-over-limit.db"),
                    MAX_TRIGGER_PROGRAM_DEPTH,
                )
                .await;
                let frame_guard = push_parent_program_frame(&over_limit);
                let error = over_limit
                    .execute("DELETE FROM aux.f0 WHERE id = 1;")
                    .await
                    .expect_err(
                        "cross-schema aggregate admission 51 must be rejected; \
                         succeeding means ATTACH delegation reset the budget",
                    );
                assert!(
                    matches!(&error, FrankenError::TriggerRecursionDepthExceeded),
                    "expected typed depth error, got {error:?}"
                );
                drop(frame_guard);
                for i in 0..=MAX_TRIGGER_PROGRAM_DEPTH {
                    let rows = over_limit
                        .query(&format!("SELECT COUNT(*) FROM aux.f{i};"))
                        .await
                        .unwrap();
                    assert_eq!(
                        row_values(&rows[0])[0],
                        SqliteValue::Integer(1),
                        "the failed delegated statement must roll back aux.f{i}"
                    );
                }
                assert_trigger_program_state_clean(&over_limit);
                over_limit
                    .with_attached_connection("aux", |child| {
                        assert_eq!(child.fk_cascade_depth.get(), 0);
                        assert_eq!(child.inherited_recursive_program_depth.get(), 0);
                        Ok(())
                    })
                    .unwrap();
            });
        });
    }

    /// bd-wymdl.3 criterion 4: ATTACH/DETACH may not run while a recursive
    /// trigger/FK program is active; the registry must be untouched.
    #[test]
    fn attach_detach_rejected_during_active_recursive_program() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let aux_path = dir.path().join("reject-aux.db");
            let aux_sql = format!("ATTACH DATABASE '{}' AS aux;", aux_path.to_string_lossy());
            let conn = Connection::open(":memory:").await.unwrap();

            let frame_guard = conn.push_trigger_frame(TriggerFrame {
                table_name: "t".to_owned(),
                trigger_name: "trg".to_owned(),
                column_names: Vec::new(),
                rowid_alias_col_idx: None,
                old_row: None,
                new_row: None,
            });
            let error = conn
                .execute(&aux_sql)
                .await
                .expect_err("ATTACH during an active recursive program must fail closed");
            assert!(
                error.to_string().contains("ATTACH is not allowed"),
                "unexpected ATTACH rejection: {error}"
            );
            assert!(
                conn.attached_schemas.borrow().find("aux").is_none(),
                "the rejected ATTACH must not mutate the schema registry"
            );
            drop(frame_guard);

            // With no active program the same ATTACH succeeds, and DETACH is
            // then rejected under an active program.
            conn.execute(&aux_sql).await.expect("plain ATTACH works");
            let fk_guard = conn.enter_fk_cascade().unwrap();
            let error = conn
                .execute("DETACH DATABASE aux;")
                .await
                .expect_err("DETACH during an active recursive program must fail closed");
            assert!(
                error.to_string().contains("DETACH is not allowed"),
                "unexpected DETACH rejection: {error}"
            );
            assert!(
                conn.attached_schemas.borrow().find("aux").is_some(),
                "the rejected DETACH must not mutate the schema registry"
            );
            drop(fk_guard);
            conn.execute("DETACH DATABASE aux;")
                .await
                .expect("plain DETACH works after the program ends");
        });
    }

    /// bd-wymdl.3 criterion 4: ATTACH/DETACH inside trigger bodies fail
    /// closed before any registry mutation (C SQLite's trigger grammar cannot
    /// even express them).
    #[test]
    fn attach_detach_inside_trigger_bodies_fail_closed() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let attached_path = dir.path().join("body-attached.db");
            let new_path = dir.path().join("body-new.db");
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(&format!(
                "ATTACH DATABASE '{}' AS aux;",
                attached_path.to_string_lossy()
            ))
            .await
            .unwrap();
            conn.execute("CREATE TABLE t (n INTEGER);").await.unwrap();
            conn.execute("INSERT INTO t VALUES (0);").await.unwrap();

            // The parser enforces the same grammar C SQLite does: trigger
            // bodies admit only SELECT/INSERT/UPDATE/DELETE, so ATTACH and
            // DETACH fail closed at CREATE TRIGGER time — earlier than any
            // runtime admission, and before any registry mutation.
            let error = conn
                .execute(
                    "CREATE TRIGGER t_detach AFTER UPDATE ON t BEGIN DETACH DATABASE aux; END;",
                )
                .await
                .expect_err("DETACH inside a trigger body must fail closed at parse");
            assert!(
                error
                    .to_string()
                    .contains("trigger body statement must be SELECT, INSERT, UPDATE, or DELETE"),
                "unexpected trigger-body DETACH rejection: {error}"
            );
            assert!(
                conn.attached_schemas.borrow().find("aux").is_some(),
                "aux must remain attached after the rejected trigger definition"
            );

            let error = conn
                .execute(&format!(
                    "CREATE TRIGGER t_attach AFTER UPDATE ON t \
                     BEGIN ATTACH DATABASE '{}' AS extra; END;",
                    new_path.to_string_lossy()
                ))
                .await
                .expect_err("ATTACH inside a trigger body must fail closed at parse");
            assert!(
                error
                    .to_string()
                    .contains("trigger body statement must be SELECT, INSERT, UPDATE, or DELETE"),
                "unexpected trigger-body ATTACH rejection: {error}"
            );
            assert!(
                conn.attached_schemas.borrow().find("extra").is_none(),
                "the rejected trigger-body ATTACH must not mutate the registry"
            );

            // Neither rejected definition may leave a trigger behind or
            // disturb normal DML on the subject table.
            conn.execute("UPDATE t SET n = 1;").await.unwrap();
            let rows = conn.query("SELECT n FROM t;").await.unwrap();
            assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(1));
            assert_trigger_program_state_clean(&conn);
        });
    }

    /// Drive a probe workload, optionally without the TRACE-level test
    /// subscriber that `asupersync::test_utils::run_test` installs globally.
    /// The subscriber changes which branches of the statement dispatcher are
    /// live, so it materially changes measured frame sizes.
    fn block_on_probe<F, Fut>(quiet: bool, make: F)
    where
        F: FnOnce() -> Fut,
        Fut: std::future::Future<Output = ()>,
    {
        if quiet {
            let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
                .build()
                .expect("probe runtime should build");
            runtime.block_on(make());
        } else {
            asupersync::test_utils::run_test(make);
        }
    }

    fn probe_quiet() -> bool {
        std::env::var("FSQLITE_PROBE_QUIET").is_ok_and(|value| value == "1")
    }

    /// bd-wymdl diagnostic: measure the native stack cost of one level of
    /// trigger recursion by sampling the stack pointer at every pushed
    /// trigger frame.
    ///
    /// `cargo test -p fsqlite-core --lib diag_trigger_stack_bytes_per_level -- --ignored --nocapture`
    #[test]
    #[ignore = "diagnostic measurement, not a regression assertion"]
    fn diag_trigger_stack_bytes_per_level() {
        const PROBE_DEPTH: usize = 40;
        let quiet = probe_quiet();
        let handle = std::thread::Builder::new()
            .name("trigger-stack-probe".to_owned())
            .stack_size(512 * 1024 * 1024)
            .spawn(move || {
                // The override is thread-local and this probe runs on its own
                // thread, so it must be set here rather than by the caller.
                // Without it the chain trips the production cap long before
                // PROBE_DEPTH and no gradient can be sampled. The 512 MiB stack
                // above is what makes sampling this deep safe.
                set_trigger_depth_limit_override(Some(PROBE_DEPTH + 1));
                let base_marker: usize = 0;
                let thread_base = std::ptr::from_ref(&base_marker) as usize;
                block_on_probe(quiet, || async {
                    let conn = build_bounded_trigger_chain(PROBE_DEPTH).await;
                    // Arm only around the recursive statement so the schema
                    // setup does not pollute the sample sequence.
                    arm_trigger_stack_probe();
                    conn.execute("UPDATE a SET n = 1;").await.unwrap();
                });
                (thread_base, take_trigger_stack_probe())
            })
            .expect("spawn trigger stack probe thread");
        let (thread_base, samples) = handle.join().expect("probe thread panicked");
        let frames: Vec<usize> = samples
            .iter()
            .filter(|(site, _)| *site == super::trigger_probe_site::FRAME_PUSH)
            .map(|(_, addr)| *addr)
            .collect();
        assert!(
            frames.len() >= 8,
            "probe recorded too few trigger levels: {}",
            frames.len()
        );
        let deltas: Vec<usize> = frames
            .windows(2)
            .map(|w| w[0].saturating_sub(w[1]))
            .collect();
        // Skip the first few levels: entry into the recursion is not yet in
        // steady state (the outermost DML frame differs from the trigger-body
        // frames).
        let steady = &deltas[2..];
        let total: usize = steady.iter().sum();
        let mean = total / steady.len();
        let min = *steady.iter().min().unwrap();
        let max = *steady.iter().max().unwrap();
        let base = thread_base.saturating_sub(frames[0]);
        println!("=== bd-wymdl trigger recursion stack measurement (raw Connection API) ===");
        println!("tracing subscriber installed: {}", !quiet);
        println!("levels sampled: {}", frames.len());
        println!("base stack consumed before first trigger frame: {base} bytes");
        println!("steady-state per level: mean={mean} min={min} max={max}");
        for stack_mib in [1_usize, 2, 4, 8, 16, 32] {
            let budget = stack_mib * 1024 * 1024;
            let usable = budget.saturating_sub(base);
            println!(
                "  {stack_mib:>2} MiB stack -> predicted max depth ~= {} levels",
                usable / mean.max(1)
            );
        }

        // Per-site attribution over one steady-state cycle: how many bytes each
        // frame in the mutual-recursion chain contributes to a single level.
        println!("--- per-site attribution (one steady-state recursion cycle) ---");
        let cycle_start = samples
            .iter()
            .position(|(site, addr)| {
                *site == super::trigger_probe_site::FRAME_PUSH && *addr == frames[4]
            })
            .expect("locate steady-state cycle start");
        let cycle_end = samples
            .iter()
            .position(|(site, addr)| {
                *site == super::trigger_probe_site::FRAME_PUSH && *addr == frames[5]
            })
            .expect("locate next cycle start");
        for window in samples[cycle_start..=cycle_end].windows(2) {
            let (site, addr) = window[0];
            let (next_site, next_addr) = window[1];
            println!(
                "  {:>46} -> {:<46} {:>8} bytes",
                super::trigger_probe_site::name(site),
                super::trigger_probe_site::name(next_site),
                addr.saturating_sub(next_addr),
            );
        }
    }

    /// bd-wymdl diagnostic: run a bounded trigger chain on a pinned stack and
    /// report survival. Driven by `FSQLITE_PROBE_STACK_MIB` /
    /// `FSQLITE_PROBE_DEPTH`; a stack overflow aborts the process, so this is
    /// invoked out-of-process by the measurement sweep.
    #[test]
    #[ignore = "diagnostic measurement, not a regression assertion"]
    fn diag_trigger_depth_survival() {
        let stack_mib: usize = std::env::var("FSQLITE_PROBE_STACK_MIB")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(1);
        let depth: usize = std::env::var("FSQLITE_PROBE_DEPTH")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(8);
        let quiet = probe_quiet();
        std::thread::Builder::new()
            .name("trigger-depth-survival".to_owned())
            .stack_size(stack_mib * 1024 * 1024)
            .spawn(move || {
                block_on_probe(quiet, || async {
                    let conn = build_bounded_trigger_chain(depth).await;
                    conn.execute("UPDATE a SET n = 1;").await.unwrap();
                    let rows = conn.query("SELECT n FROM a;").await.unwrap();
                    println!(
                        "PROBE_RESULT stack_mib={stack_mib} depth={depth} a={:?}",
                        row_values(&rows[0])[0]
                    );
                });
            })
            .expect("spawn trigger depth survival thread")
            .join()
            .expect("survival thread panicked");
        println!("PROBE_SURVIVED stack_mib={stack_mib} depth={depth}");
    }

    /// bd-wymdl diagnostic: run the *exact* `test_recursive_trigger_depth_limit`
    /// workload (unbounded ping-pong triggers, no `WHEN` clause) on a pinned
    /// stack with an overridden depth limit, and report whether the limit fired
    /// as a clean error. A stack overflow aborts the process instead, so the
    /// sweep drives this out-of-process, one candidate limit per run.
    ///
    /// `FSQLITE_PROBE_STACK_MIB=1 FSQLITE_PROBE_LIMIT=8 <test-bin> \
    ///  connection::tests::diag_trigger_limit_fires_before_abort --ignored --exact`
    #[test]
    #[ignore = "diagnostic measurement, not a regression assertion"]
    fn diag_trigger_limit_fires_before_abort() {
        let stack_mib: usize = std::env::var("FSQLITE_PROBE_STACK_MIB")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(1);
        let limit: usize = std::env::var("FSQLITE_PROBE_LIMIT")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(MAX_TRIGGER_DEPTH);
        let quiet = probe_quiet();
        std::thread::Builder::new()
            .name("trigger-limit-probe".to_owned())
            .stack_size(stack_mib * 1024 * 1024)
            .spawn(move || {
                set_trigger_depth_limit_override(Some(limit));
                block_on_probe(quiet, || async {
                    let conn = Connection::open(":memory:").await.unwrap();
                    conn.execute("PRAGMA recursive_triggers = ON;")
                        .await
                        .unwrap();
                    conn.execute("CREATE TABLE a (n INTEGER);").await.unwrap();
                    conn.execute("CREATE TABLE b (n INTEGER);").await.unwrap();
                    conn.execute("INSERT INTO a VALUES (0);").await.unwrap();
                    conn.execute("INSERT INTO b VALUES (0);").await.unwrap();
                    conn.execute(
                        "CREATE TRIGGER trg_a AFTER UPDATE ON a \
                         BEGIN UPDATE b SET n = NEW.n + 1; END;",
                    )
                    .await
                    .unwrap();
                    conn.execute(
                        "CREATE TRIGGER trg_b AFTER UPDATE ON b \
                         BEGIN UPDATE a SET n = NEW.n + 1; END;",
                    )
                    .await
                    .unwrap();
                    let err = conn
                        .execute("UPDATE a SET n = 1;")
                        .await
                        .expect_err("depth limit should fire");
                    let message = format!("{err}");
                    assert!(
                        message.contains("too many levels of trigger recursion"),
                        "unexpected error: {message}"
                    );
                });
                set_trigger_depth_limit_override(None);
            })
            .expect("spawn trigger limit probe thread")
            .join()
            .expect("limit probe thread panicked");
        println!("PROBE_LIMIT_CLEAN stack_mib={stack_mib} limit={limit}");
    }

    #[test]
    fn test_trigger_large_table_column_binding_100_columns() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            let mut create_table_sql = String::from("CREATE TABLE t (");
            for idx in 1..=100 {
                if idx > 1 {
                    create_table_sql.push_str(", ");
                }
                create_table_sql.push('c');
                create_table_sql.push_str(&idx.to_string());
                create_table_sql.push_str(" INTEGER");
            }
            create_table_sql.push_str(");");
            conn.execute(&create_table_sql).await.unwrap();
            conn.execute("CREATE TABLE log (v INTEGER);").await.unwrap();
            conn.execute(
            "CREATE TRIGGER trg_large AFTER INSERT ON t BEGIN INSERT INTO log VALUES (NEW.c100); END;",
        ).await
        .unwrap();

            let mut insert_sql = String::from("INSERT INTO t VALUES (");
            for idx in 1..=100 {
                if idx > 1 {
                    insert_sql.push_str(", ");
                }
                insert_sql.push_str(&idx.to_string());
            }
            insert_sql.push_str(");");
            conn.execute(&insert_sql).await.unwrap();

            let rows = conn.query("SELECT v FROM log;").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(100));
            assert!(conn.trigger_frame_stack.borrow().is_empty());
        });
    }

    #[test]
    fn test_trigger_begin_concurrent_mode_with_old_new_bindings() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER, name TEXT);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE log (id INTEGER, name TEXT);")
                .await
                .unwrap();
            conn.execute(
            "CREATE TRIGGER trg_concurrent AFTER INSERT ON t BEGIN INSERT INTO log VALUES (NEW.id, NEW.name); END;",
        ).await
        .unwrap();

            conn.execute("BEGIN CONCURRENT;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'alice');")
                .await
                .unwrap();
            conn.execute("COMMIT;").await.unwrap();

            let rows = conn.query("SELECT id, name FROM log;").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(row_values(&rows[0])[0], SqliteValue::Integer(1));
            assert_eq!(row_values(&rows[0])[1], SqliteValue::Text("alice".into()));
            assert!(conn.trigger_frame_stack.borrow().is_empty());
        });
    }

