    #[test]
    fn test_vacuum_into_rejects_source_commit_between_receipt_and_hydration() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let source_path = dir.path().join("vacuum-into-source-race.db");
            let target_path = dir.path().join("vacuum-into-source-race-output.db");
            let source = source_path.to_string_lossy().into_owned();
            let target = target_path.to_string_lossy().into_owned();

            let conn = Connection::open(&source).await.unwrap();
            conn.execute("CREATE TABLE items(id INTEGER PRIMARY KEY, value TEXT NOT NULL UNIQUE);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (1,'alpha'),(2,'beta');")
                .await
                .unwrap();

            let writer_path = source.clone();
            *conn.vacuum_after_source_receipt_once.borrow_mut() = Some(Box::new(move || {
                asupersync::test_utils::run_test(|| async {
                    let writer = Connection::open(writer_path).await.unwrap();
                    writer
                        .execute("INSERT INTO items VALUES (3,'gamma');")
                        .await
                        .unwrap();
                    writer.close().await.unwrap();
                });
            }));

            let error = conn
                .execute_with_params(
                    "VACUUM INTO ?1;",
                    &[SqliteValue::Text(target.clone().into())],
                )
                .await
                .expect_err("a source generation change must reject VACUUM INTO");
            assert!(
                matches!(
                    error,
                    FrankenError::Busy | FrankenError::BusySnapshot { .. }
                ),
                "unexpected source receipt race error: {error}"
            );
            assert!(
                !target_path.exists(),
                "source receipt rejection must happen before output reservation"
            );
            conn.close().await.unwrap();

            let source_oracle = rusqlite::Connection::open(&source_path).unwrap();
            let values: Vec<String> = source_oracle
                .prepare("SELECT value FROM items ORDER BY id;")
                .unwrap()
                .query_map([], |row| row.get(0))
                .unwrap()
                .collect::<rusqlite::Result<Vec<_>>>()
                .unwrap();
            let integrity: String = source_oracle
                .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                .unwrap();
            assert_eq!(values, ["alpha", "beta", "gamma"]);
            assert_eq!(integrity, "ok");
        });
    }

    #[test]
    fn test_vacuum_into_rejects_same_inode_write_after_validation() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let source_path = dir.path().join("vacuum-into-target-race.db");
            let target_path = dir.path().join("vacuum-into-target-race-output.db");
            let source = source_path.to_string_lossy().into_owned();
            let target = target_path.to_string_lossy().into_owned();

            let conn = Connection::open(&source).await.unwrap();
            conn.execute("CREATE TABLE items(id INTEGER PRIMARY KEY, value TEXT NOT NULL UNIQUE);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (1,'alpha'),(2,'beta');")
                .await
                .unwrap();

            let raced_target = target_path.clone();
            *conn.vacuum_after_target_validation_once.borrow_mut() = Some(Box::new(move || {
                let writer = rusqlite::Connection::open(raced_target).unwrap();
                writer
                    .execute("INSERT INTO items VALUES (3,'intruder');", [])
                    .unwrap();
            }));

            let error = conn
                .execute_with_params(
                    "VACUUM INTO ?1;",
                    &[SqliteValue::Text(target.clone().into())],
                )
                .await
                .expect_err("a same-inode target write must reject VACUUM INTO");
            assert!(
                matches!(error, FrankenError::DatabaseCorrupt { .. }),
                "unexpected target receipt race error: {error}"
            );
            assert!(
                !target_path.exists(),
                "a modified exact reservation must be removed after rejection"
            );

            let rows = conn
                .query("SELECT value FROM items ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(rows[0].values()[0], SqliteValue::Text("alpha".into()));
            assert_eq!(rows[1].values()[0], SqliteValue::Text("beta".into()));
            conn.close().await.unwrap();
        });
    }

    #[test]
    fn test_vacuum_into_preserves_post_validation_path_replacement() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let source_path = dir.path().join("vacuum-into-path-race.db");
            let target_path = dir.path().join("vacuum-into-path-race-output.db");
            let displaced_path = dir.path().join("vacuum-into-path-race-displaced.db");
            let source = source_path.to_string_lossy().into_owned();
            let target = target_path.to_string_lossy().into_owned();

            let conn = Connection::open(&source).await.unwrap();
            conn.execute("CREATE TABLE items(id INTEGER PRIMARY KEY, value TEXT NOT NULL UNIQUE);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (1,'alpha'),(2,'beta');")
                .await
                .unwrap();

            let raced_target = target_path.clone();
            let raced_displaced = displaced_path.clone();
            *conn.vacuum_after_target_validation_once.borrow_mut() = Some(Box::new(move || {
                fsqlite_vfs::host_fs::rename(&raced_target, &raced_displaced).unwrap();
                fsqlite_vfs::host_fs::write(&raced_target, b"replacement-sentinel").unwrap();
            }));

            conn.execute_with_params(
                "VACUUM INTO ?1;",
                &[SqliteValue::Text(target.clone().into())],
            )
            .await
            .expect_err("a post-validation path replacement must reject VACUUM INTO");
            assert_eq!(
                fsqlite_vfs::host_fs::read(&target_path).unwrap(),
                b"replacement-sentinel",
                "identity-bound cleanup must preserve the replacement path entry"
            );
            assert!(
                displaced_path.exists(),
                "identity drift must preserve the displaced reserved image"
            );

            let rows = conn
                .query("SELECT value FROM items ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(rows[0].values()[0], SqliteValue::Text("alpha".into()));
            assert_eq!(rows[1].values()[0], SqliteValue::Text("beta".into()));
            conn.close().await.unwrap();
        });
    }

    #[test]
    fn test_vacuum_masks_cancellation_after_publication_and_rebinds_live_connection() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("vacuum-postcommit-cancel.db");
            let db_path_text = db_path.to_string_lossy().into_owned();

            let conn = Connection::open(&db_path_text).await.unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=OFF;")
                .await
                .unwrap();
            conn.execute("CREATE TABLE items(id INTEGER PRIMARY KEY, value TEXT NOT NULL);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (1,'alpha'),(2,'beta');")
                .await
                .unwrap();
            conn.cancel_vacuum_after_publish_once.set(true);

            conn.execute("VACUUM;")
                .await
                .expect("post-publication cancellation must not interrupt mandatory rebind");
            {
                // Operation contexts clone the connection root, so the injected
                // cancellation remains observable to later work. Mask it only for
                // this assertion that the live connection was nevertheless fully
                // rebound to the committed image.
                let _inspection_mask = conn.root_cx().masked();
                let rows = conn
                    .query("SELECT id, value FROM items ORDER BY id;")
                    .await
                    .unwrap();
                assert_eq!(rows.len(), 2);
                assert_eq!(rows[0].values()[1], SqliteValue::Text("alpha".into()));
                assert_eq!(rows[1].values()[1], SqliteValue::Text("beta".into()));
                assert!(conn.post_vacuum_rebind_failure.borrow().is_none());
            }
            drop(conn);

            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            let integrity: String = sqlite
                .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                .unwrap();
            let count: i64 = sqlite
                .query_row("SELECT COUNT(*) FROM items;", [], |row| row.get(0))
                .unwrap();
            assert_eq!(integrity, "ok");
            assert_eq!(count, 2);
            let leftovers = std::fs::read_dir(dir.path())
                .unwrap()
                .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
                .filter(|name| name.contains(".fsqlite-vacuum-rebuild-"))
                .collect::<Vec<_>>();
            assert!(leftovers.is_empty(), "{leftovers:?}");
        });
    }

    #[test]
    fn test_vacuum_postcommit_rebind_failure_poison_is_fail_closed_but_image_is_valid() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("vacuum-postcommit-poison.db");
            let db_path_text = db_path.to_string_lossy().into_owned();

            let conn = Connection::open(&db_path_text).await.unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=OFF;")
                .await
                .unwrap();
            conn.execute("CREATE TABLE items(id INTEGER PRIMARY KEY, value TEXT NOT NULL);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (1,'alpha'),(2,'beta');")
                .await
                .unwrap();
            conn.fail_vacuum_rebind_once.set(true);

            let error = conn.execute("VACUUM;").await.expect_err(
                "injected committed-image rebind failure must poison the old connection",
            );
            let message = error.to_string();
            assert!(
                message.contains("VACUUM committed successfully"),
                "{message}"
            );
            assert!(message.contains("poisoned"), "{message}");
            let subsequent = conn
                .query("SELECT COUNT(*) FROM items;")
                .await
                .expect_err("a stale post-VACUUM connection must reject all later statements");
            assert!(
                subsequent
                    .to_string()
                    .contains("connection is unusable after a committed VACUUM image"),
                "{subsequent}"
            );
            drop(conn);

            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            let integrity: String = sqlite
                .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                .unwrap();
            let count: i64 = sqlite
                .query_row("SELECT COUNT(*) FROM items;", [], |row| row.get(0))
                .unwrap();
            assert_eq!(integrity, "ok");
            assert_eq!(count, 2);

            let reopened = Connection::open(&db_path_text).await.unwrap();
            let rows = reopened.query("SELECT COUNT(*) FROM items;").await.unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(2));
            reopened.close().await.unwrap();
        });
    }

    #[test]
    fn test_vacuum_twice_on_same_live_connection_reopens_in_both_engines() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("vacuum-twice-live.db");
            let db_path_text = db_path.to_string_lossy().into_owned();

            let conn = Connection::open(&db_path_text).await.unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=OFF;")
                .await
                .unwrap();
            conn.execute("CREATE TABLE items(id INTEGER PRIMARY KEY, value TEXT NOT NULL);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (1,'alpha'),(2,'beta'),(3,'gamma');")
                .await
                .unwrap();

            for cycle in 1..=2 {
                conn.execute("VACUUM;").await.unwrap();
                let rows = conn
                    .query("SELECT id, value FROM items ORDER BY id;")
                    .await
                    .unwrap();
                assert_eq!(rows.len(), 3, "VACUUM cycle {cycle}");
                let quick_check = conn.query("PRAGMA quick_check;").await.unwrap();
                let integrity_check = conn.query("PRAGMA integrity_check;").await.unwrap();
                assert_eq!(
                    quick_check[0].values()[0],
                    SqliteValue::Text("ok".into()),
                    "VACUUM cycle {cycle}"
                );
                assert_eq!(
                    integrity_check[0].values()[0],
                    SqliteValue::Text("ok".into()),
                    "VACUUM cycle {cycle}"
                );
            }
            conn.execute("INSERT INTO items VALUES (4,'delta');")
                .await
                .unwrap();
            conn.close().await.unwrap();

            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            let row_count: i64 = sqlite
                .query_row("SELECT COUNT(*) FROM items;", [], |row| row.get(0))
                .unwrap();
            let quick_check: String = sqlite
                .query_row("PRAGMA quick_check;", [], |row| row.get(0))
                .unwrap();
            let integrity_check: String = sqlite
                .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                .unwrap();
            assert_eq!(row_count, 4);
            assert_eq!(quick_check, "ok");
            assert_eq!(integrity_check, "ok");
            drop(sqlite);

            let reopened = Connection::open_schema_only(&db_path_text).await.unwrap();
            let rows = reopened
                .query("SELECT id, value FROM items ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 4);
            assert_eq!(rows[3].values()[1], SqliteValue::Text("delta".into()));
            assert_eq!(
                reopened.query("PRAGMA quick_check;").await.unwrap()[0].values()[0],
                SqliteValue::Text("ok".into())
            );
            assert_eq!(
                reopened.query("PRAGMA integrity_check;").await.unwrap()[0].values()[0],
                SqliteValue::Text("ok".into())
            );
            reopened.close().await.unwrap();
        });
    }

    #[test]
    fn test_vacuum_shrinks_file_and_live_connection_remains_usable() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("vacuum-shrink-live.db");
            let db_path_text = db_path.to_string_lossy().into_owned();

            let conn = Connection::open_with_page_size(&db_path_text, 1024)
                .await
                .unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=OFF;")
                .await
                .unwrap();
            conn.execute("PRAGMA journal_mode = 'delete';")
                .await
                .unwrap();
            conn.execute("CREATE TABLE payloads(id INTEGER PRIMARY KEY, payload TEXT NOT NULL);")
                .await
                .unwrap();
            conn.execute("BEGIN IMMEDIATE;").await.unwrap();
            let payload = "x".repeat(1_800);
            for id in 1..=400_i64 {
                conn.execute_with_params(
                    "INSERT INTO payloads(id, payload) VALUES (?1, ?2);",
                    &[
                        SqliteValue::Integer(id),
                        SqliteValue::Text(payload.clone().into()),
                    ],
                )
                .await
                .unwrap();
            }
            conn.execute("COMMIT;").await.unwrap();
            conn.execute("DELETE FROM payloads WHERE id <= 390;")
                .await
                .unwrap();
            let before_size = std::fs::metadata(&db_path).unwrap().len();

            conn.execute("VACUUM;").await.unwrap();
            let after_size = std::fs::metadata(&db_path).unwrap().len();
            assert!(
                after_size < before_size,
                "VACUUM must shrink the main file: before={before_size} after={after_size}"
            );
            let rows = conn.query("SELECT COUNT(*) FROM payloads;").await.unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(10));
            conn.execute("INSERT INTO payloads(id, payload) VALUES (1000, 'still-live');")
                .await
                .unwrap();
            let rows = conn
                .query("SELECT payload FROM payloads WHERE id=1000;")
                .await
                .unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Text("still-live".into()));
            conn.close().await.unwrap();

            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            let row_count: i64 = sqlite
                .query_row("SELECT COUNT(*) FROM payloads;", [], |row| row.get(0))
                .unwrap();
            let quick_check: String = sqlite
                .query_row("PRAGMA quick_check;", [], |row| row.get(0))
                .unwrap();
            let integrity_check: String = sqlite
                .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                .unwrap();
            assert_eq!(row_count, 11);
            assert_eq!(quick_check, "ok");
            assert_eq!(integrity_check, "ok");
            drop(sqlite);

            let reopened = Connection::open_schema_only(&db_path_text).await.unwrap();
            let rows = reopened
                .query("SELECT COUNT(*) FROM payloads;")
                .await
                .unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(11));
            assert_eq!(
                reopened.query("PRAGMA integrity_check;").await.unwrap()[0].values()[0],
                SqliteValue::Text("ok".into())
            );
            reopened.close().await.unwrap();
        });
    }

