    #[test]
    fn test_group_by_simple_streaming_fast_path_for_sum_alias_order_by_limit() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            FSQLITE_GROUP_BY_STREAMING_FAST_PATH_HITS.store(0, AtomicOrdering::Relaxed);

            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE products (category INTEGER, price REAL);")
                .await
                .unwrap();
            conn.execute("INSERT INTO products VALUES (1, 10.0);")
                .await
                .unwrap();
            conn.execute("INSERT INTO products VALUES (1, 15.5);")
                .await
                .unwrap();
            conn.execute("INSERT INTO products VALUES (2, 20.0);")
                .await
                .unwrap();
            conn.execute("INSERT INTO products VALUES (2, 7.0);")
                .await
                .unwrap();
            conn.execute("INSERT INTO products VALUES (3, 50.0);")
                .await
                .unwrap();

            let rows = conn
            .query(
                "SELECT category, SUM(price) AS total FROM products GROUP BY category ORDER BY total DESC LIMIT 2;",
            ).await
            .unwrap();

            assert_eq!(rows.len(), 2);
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(3));
            assert_eq!(rows[0].values()[1], SqliteValue::Float(50.0));
            assert_eq!(rows[1].values()[0], SqliteValue::Integer(2));
            assert_eq!(rows[1].values()[1], SqliteValue::Float(27.0));
            assert!(
                FSQLITE_GROUP_BY_STREAMING_FAST_PATH_HITS.load(AtomicOrdering::Relaxed) > 0,
                "simple single-table GROUP BY should use the streaming fast path"
            );
        });
    }

