    #[test]
    fn test_cte_join_query_uses_memdb_join_fast_path_on_memory_database() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            FSQLITE_GROUP_BY_STREAMING_FAST_PATH_HITS.store(0, AtomicOrdering::Relaxed);
            FSQLITE_GROUP_BY_PROJECTION_PRUNE_HITS.store(0, AtomicOrdering::Relaxed);
            FSQLITE_GROUP_BY_MEM_SCAN_FAST_PATH_HITS.store(0, AtomicOrdering::Relaxed);
            FSQLITE_JOIN_MEM_SCAN_FAST_PATH_HITS.store(0, AtomicOrdering::Relaxed);

            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE products (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                price REAL NOT NULL,
                category_id INTEGER NOT NULL
            );",
            )
            .await
            .unwrap();
            conn.execute(
                "INSERT INTO products VALUES
                (1, 'a', 10.0, 1),
                (2, 'b', 11.0, 1),
                (3, 'c', 4.0, 2),
                (4, 'd', 5.0, 2),
                (5, 'e', 30.0, 3),
                (6, 'f', 25.0, 3);",
            )
            .await
            .unwrap();
            conn.execute("CREATE INDEX idx_products_category ON products(category_id);")
                .await
                .unwrap();

            let rows = conn
                .query(
                    "WITH top_cats AS (
                    SELECT category_id, SUM(price) AS total
                    FROM products
                    GROUP BY category_id
                    ORDER BY total DESC
                    LIMIT 2
                )
                SELECT p.name, p.price
                FROM products p
                JOIN top_cats tc ON p.category_id = tc.category_id
                ORDER BY p.id;",
                )
                .await
                .unwrap();

            assert_eq!(rows.len(), 4);
            assert_eq!(
                row_values(&rows[0]),
                vec![SqliteValue::Text("a".into()), SqliteValue::Float(10.0)]
            );
            assert_eq!(
                row_values(&rows[1]),
                vec![SqliteValue::Text("b".into()), SqliteValue::Float(11.0)]
            );
            assert_eq!(
                row_values(&rows[2]),
                vec![SqliteValue::Text("e".into()), SqliteValue::Float(30.0)]
            );
            assert_eq!(
                row_values(&rows[3]),
                vec![SqliteValue::Text("f".into()), SqliteValue::Float(25.0)]
            );
            assert!(
                FSQLITE_GROUP_BY_MEM_SCAN_FAST_PATH_HITS.load(AtomicOrdering::Relaxed) > 0,
                "CTE source aggregation should stay on the MemDatabase grouped scan fast path"
            );
            assert!(
                FSQLITE_JOIN_MEM_SCAN_FAST_PATH_HITS.load(AtomicOrdering::Relaxed) > 0,
                "benchmark-style stripped WITH inner joins on :memory: should use the MemDatabase hash join fallback"
            );
        });
    }

