    #[test]
    fn test_top_category_cte_fast_path_rejects_stale_source_name_for_aliased_cte_group() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE products (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                price REAL,
                category_id INTEGER NOT NULL
            );",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO products VALUES (1, 'a', 10.0, 1);")
                .await
                .unwrap();

            // The CTE exports `cat` (SELECT category_id AS cat), so `tc.category_id`
            // does not exist (verified vs C SQLite 3.46.1: "no such column:
            // tc.category_id"). The anchor accepted the query and deferred
            // rejection to execution; the release window's compile-time resolver
            // rejects it up front, matching stock SQLite.
            let prepared = conn
                .prepare(
                    "WITH top_cats AS (
                    SELECT category_id AS cat, SUM(price) AS total
                    FROM products
                    GROUP BY category_id
                    ORDER BY total DESC
                    LIMIT 1
                )
                SELECT p.name, p.price
                FROM products p
                JOIN top_cats tc ON p.category_id = tc.category_id;",
                )
                .await;
            let err = match prepared {
                Ok(stmt) => stmt
                    .query()
                    .await
                    .expect_err("stale tc.category_id must be rejected"),
                Err(err) => err,
            };
            assert!(
                matches!(err, FrankenError::NoSuchColumn { .. }),
                "expected no-such-column error, got: {err:?}"
            );
        });
    }

    #[test]
    fn test_inline_single_use_non_recursive_cte_join_select_rewrites_join_source_to_subquery() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let statement = conn
                .cached_parse_single(
                    "WITH top_cats AS (
                    SELECT category_id, SUM(price) AS total
                    FROM products
                    GROUP BY category_id
                    ORDER BY total DESC
                    LIMIT 5
                )
                SELECT p.name, p.price
                FROM products p
                JOIN top_cats tc ON p.category_id = tc.category_id;",
                )
                .unwrap();
            let Statement::Select(select) = statement.as_ref() else {
                panic!("expected SELECT statement");
            };

            let rewritten = conn
                .inline_single_use_non_recursive_cte_join_select(select)
                .expect("benchmark-style CTE join should inline to a subquery source");

            assert!(rewritten.with.is_none());
            let fsqlite_ast::SelectCore::Select {
                from: Some(from), ..
            } = &rewritten.body.select
            else {
                panic!("expected FROM clause");
            };
            assert_eq!(from.joins.len(), 1);
            match &from.joins[0].table {
                fsqlite_ast::TableOrSubquery::Subquery { alias, .. } => {
                    assert_eq!(alias.as_deref(), Some("tc"));
                }
                other => panic!("expected join source to be inlined as subquery, got {other:?}"),
            }
        });
    }

    #[test]
    fn test_cte_left_join_query_prefers_vdbe_path_on_memory_database() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            FSQLITE_JOIN_MEM_SCAN_FAST_PATH_HITS.store(0, AtomicOrdering::Relaxed);

            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE products (id INTEGER PRIMARY KEY, category_id INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO products VALUES (1, 1), (2, 2);")
                .await
                .unwrap();

            let rows = conn
                .query(
                    "WITH wanted AS (\n\
                     SELECT 1 AS category_id\n\
                 )\n\
                 SELECT p.id, w.category_id\n\
                 FROM products AS p\n\
                 LEFT JOIN wanted AS w ON p.category_id = w.category_id\n\
                 ORDER BY p.id;",
                )
                .await
                .unwrap();

            assert_eq!(rows.len(), 2);
            assert_eq!(
                row_values(&rows[0]),
                vec![SqliteValue::Integer(1), SqliteValue::Integer(1)]
            );
            assert_eq!(
                row_values(&rows[1]),
                vec![SqliteValue::Integer(2), SqliteValue::Null]
            );
            assert_eq!(
                FSQLITE_JOIN_MEM_SCAN_FAST_PATH_HITS.load(AtomicOrdering::Relaxed),
                0,
                "VDBE-eligible stripped WITH LEFT JOIN on :memory: should avoid the MemDatabase join fallback"
            );
        });
    }

    #[test]
    fn test_order_by_position_join() {
        asupersync::test_utils::run_test(|| async {
            // Uses a JOIN to exercise the fallback sort_rows_by_order_terms path.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE items (id INTEGER, name TEXT, price INTEGER);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE tags (item_id INTEGER, tag TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (1, 'banana', 2);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (2, 'apple', 3);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (3, 'cherry', 1);")
                .await
                .unwrap();
            conn.execute("INSERT INTO tags VALUES (1, 'fruit');")
                .await
                .unwrap();
            conn.execute("INSERT INTO tags VALUES (2, 'fruit');")
                .await
                .unwrap();
            conn.execute("INSERT INTO tags VALUES (3, 'fruit');")
                .await
                .unwrap();
            // ORDER BY 3 means order by the third result column (price).
            let rows = conn
            .query("SELECT items.name, tags.tag, items.price FROM items JOIN tags ON items.id = tags.item_id ORDER BY 3;").await
            .unwrap();
            assert_eq!(rows.len(), 3);
            assert_eq!(row_values(&rows[0])[0], SqliteValue::Text("cherry".into()));
            assert_eq!(row_values(&rows[1])[0], SqliteValue::Text("banana".into()));
            assert_eq!(row_values(&rows[2])[0], SqliteValue::Text("apple".into()));
        });
    }

    #[test]
    fn test_order_by_with_star_join() {
        asupersync::test_utils::run_test(|| async {
            // Regression: SELECT * FROM … JOIN … ORDER BY <col> must expand Star
            // before resolving ORDER BY column positions/names.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE items (id INTEGER, name TEXT, price INTEGER);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE tags (item_id INTEGER, tag TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (1, 'banana', 2);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (2, 'apple', 3);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES (3, 'cherry', 1);")
                .await
                .unwrap();
            conn.execute("INSERT INTO tags VALUES (1, 'fruit');")
                .await
                .unwrap();
            conn.execute("INSERT INTO tags VALUES (2, 'fruit');")
                .await
                .unwrap();
            conn.execute("INSERT INTO tags VALUES (3, 'fruit');")
                .await
                .unwrap();
            // ORDER BY position 3 (price) with Star — previously broken because
            // Star made columns.len() == 1, failing for positions > 1.
            let rows = conn
                .query("SELECT * FROM items JOIN tags ON items.id = tags.item_id ORDER BY 3;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 3);
            // price column is index 2 (third column): cherry=1, banana=2, apple=3
            assert_eq!(row_values(&rows[0])[2], SqliteValue::Integer(1));
            assert_eq!(row_values(&rows[1])[2], SqliteValue::Integer(2));
            assert_eq!(row_values(&rows[2])[2], SqliteValue::Integer(3));
            // Also verify column name ORDER BY with Star.
            let rows2 = conn
                .query(
                    "SELECT * FROM items JOIN tags ON items.id = tags.item_id ORDER BY price DESC;",
                )
                .await
                .unwrap();
            assert_eq!(rows2.len(), 3);
            assert_eq!(row_values(&rows2[0])[2], SqliteValue::Integer(3));
            assert_eq!(row_values(&rows2[2])[2], SqliteValue::Integer(1));
        });
    }

