            conn.execute("INSERT INTO parent VALUES (1);")
                .await
                .unwrap();
            conn.execute("INSERT INTO kv VALUES ('a', 1, 1);")
                .await
                .unwrap();

            conn.execute(
                "INSERT INTO kv VALUES ('a', 10, 1), ('b', 20, 1) \
             ON CONFLICT(k) DO UPDATE SET v = kv.v + excluded.v, parent_id = excluded.parent_id;",
            )
