    #[test]
    fn test_update_integer_primary_key_moves_rowid() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'alice');")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (2, 'bob');")
                .await
                .unwrap();

            let changed = conn
                .execute("UPDATE t SET id = 5 WHERE id = 1;")
                .await
                .unwrap();
            assert_eq!(changed, 1);

            let rows = conn
                .query("SELECT id, name FROM t ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(
                row_values(&rows[0]),
                vec![SqliteValue::Integer(2), SqliteValue::Text("bob".into())]
            );
            assert_eq!(
                row_values(&rows[1]),
                vec![SqliteValue::Integer(5), SqliteValue::Text("alice".into())]
            );

            let old_rows = conn.query("SELECT id FROM t WHERE id = 1;").await.unwrap();
            assert!(
                old_rows.is_empty(),
                "old rowid should be removed after PK update"
            );
        });
    }

