    #[test]
    fn test_full_dml_cycle() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE users (id INTEGER, name TEXT);")
                .await
                .unwrap();

            // INSERT
            conn.execute("INSERT INTO users VALUES (1, 'alice');")
                .await
                .unwrap();
            conn.execute("INSERT INTO users VALUES (2, 'bob');")
                .await
                .unwrap();
            let rows = conn.query("SELECT id, name FROM users;").await.unwrap();
            assert_eq!(rows.len(), 2);

            // UPDATE
            conn.execute("UPDATE users SET name = 'BOB' WHERE id = 2;")
                .await
                .unwrap();
            let rows = conn
                .query("SELECT name FROM users WHERE id = 2;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(row_values(&rows[0]), vec![SqliteValue::Text("BOB".into())]);

            // DELETE
            conn.execute("DELETE FROM users WHERE id = 1;")
                .await
                .unwrap();
            let rows = conn.query("SELECT id, name FROM users;").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(
                row_values(&rows[0]),
                vec![SqliteValue::Integer(2), SqliteValue::Text("BOB".into())]
            );
        });
    }

