    #[test]
    fn test_select_order_by_rowid() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (a INTEGER, b TEXT);")
                .await
                .unwrap();
            // Insert out of order by `a` to ensure sorting uses rowid, not `a`.
            conn.execute("INSERT INTO t VALUES (30, 'third');")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (10, 'first');")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (20, 'second');")
                .await
                .unwrap();

            // ORDER BY rowid should return rows in insertion order (rowid 1, 2, 3).
            let rows = conn
                .query("SELECT a, b FROM t ORDER BY rowid;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 3);
            assert_eq!(
                row_values(&rows[0]),
                vec![SqliteValue::Integer(30), SqliteValue::Text("third".into())]
            );
            assert_eq!(
                row_values(&rows[1]),
                vec![SqliteValue::Integer(10), SqliteValue::Text("first".into())]
            );
            assert_eq!(
                row_values(&rows[2]),
                vec![SqliteValue::Integer(20), SqliteValue::Text("second".into())]
            );

            // ORDER BY rowid DESC should return rows in reverse insertion order.
            let rows = conn
                .query("SELECT a, b FROM t ORDER BY rowid DESC;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 3);
            assert_eq!(
                row_values(&rows[0]),
                vec![SqliteValue::Integer(20), SqliteValue::Text("second".into())]
            );
            assert_eq!(
                row_values(&rows[2]),
                vec![SqliteValue::Integer(30), SqliteValue::Text("third".into())]
            );
        });
    }

