    #[test]
    fn test_compound_select_union_all() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t1 (a INTEGER);").await.unwrap();
            conn.execute("CREATE TABLE t2 (a INTEGER);").await.unwrap();
            conn.execute("INSERT INTO t1 VALUES (1);").await.unwrap();
            conn.execute("INSERT INTO t1 VALUES (2);").await.unwrap();
            conn.execute("INSERT INTO t2 VALUES (2);").await.unwrap();
            conn.execute("INSERT INTO t2 VALUES (3);").await.unwrap();

            // UNION ALL: concatenates all rows (including duplicates).
            let rows = conn
                .query("SELECT a FROM t1 UNION ALL SELECT a FROM t2;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 4);
            let vals: Vec<i64> = rows
                .iter()
                .filter_map(|r| match &r.values()[0] {
                    SqliteValue::Integer(n) => Some(*n),
                    _ => None,
                })
                .collect();
            assert_eq!(vals, vec![1, 2, 2, 3]);
        });
    }

