    #[test]
    fn test_cached_parse_single_reuses_statement_parse_scratch_capacity() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.cached_parse_single(
                "SELECT 'abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz' AS payload;",
            )
            .unwrap();
            let warmed_capacity = conn.statement_parse_scratch.borrow().token_capacity();
            assert!(
                warmed_capacity > 0,
                "statement parse scratch should warm token storage on a cache miss",
            );

            conn.cached_parse_single("SELECT 1;").unwrap();
            assert_eq!(
                conn.statement_parse_scratch.borrow().token_capacity(),
                warmed_capacity,
                "subsequent smaller cache misses should reuse warmed parser scratch capacity",
            );
        });
    }

    #[test]
    fn test_statement_parse_scratch_updates_arena_profile_counters() {
        asupersync::test_utils::run_test(|| async {
            let _guard = super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();

            conn.cached_parse_single(
                "SELECT 'abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz' AS payload;",
            )
            .unwrap();
            let warmed = super::hot_path_profile_snapshot();
            assert!(
                warmed.arena_alloc_bytes > 0,
                "warming parser scratch should report retained lookaside growth",
            );
            assert_eq!(
                warmed.fallback_to_general_allocator_count, 0,
                "parser scratch reuse should not require general-allocator fallback accounting",
            );

            super::reset_hot_path_profile();
            conn.cached_parse_single("SELECT 1;").unwrap();
            let reused = super::hot_path_profile_snapshot();
            assert_eq!(
                reused.arena_alloc_bytes, 0,
                "subsequent smaller cache misses should reuse warmed parser scratch without more retained-bytes growth",
            );

            super::reset_hot_path_profile();
            conn.reset_statement_lookaside();
            let after_reset = super::hot_path_profile_snapshot();
            assert_eq!(after_reset.arena_reset_count, 1);
        });
    }

