    #[test]
    #[allow(clippy::too_many_lines)]
    fn test_in_subquery_semantic_fallback_preserves_complete_select_semantics() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE rhs_semantics (y INTEGER, z INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO rhs_semantics VALUES (1, 30), (3, 10), (2, 20);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE outer_semantics (x INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO outer_semantics VALUES (1), (3);")
                .await
                .unwrap();

            for (sql, expected) in [
                (
                    "SELECT 3 IN (SELECT max(y) FROM rhs_semantics);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 3 IN (SELECT max(y ORDER BY y) \
                     FILTER (WHERE y > 0) FROM rhs_semantics);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 1 IN (SELECT row_number() OVER (ORDER BY y) \
                     FROM rhs_semantics ORDER BY y LIMIT 1);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 1 IN (SELECT (SELECT y) FROM rhs_semantics \
                     ORDER BY y LIMIT 1);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 1 IN (SELECT EXISTS(SELECT 1) FROM rhs_semantics \
                     ORDER BY y LIMIT 1);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 1 IN (SELECT y IN (1, 2) FROM rhs_semantics \
                     ORDER BY y LIMIT 1);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 1 IN (SELECT y FROM rhs_semantics \
                     WHERE (y, z) = (1, 30));",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 1 IN (SELECT y AS projected FROM rhs_semantics \
                     WHERE projected = 1);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 1 IN (SELECT y AS projected FROM rhs_semantics \
                     ORDER BY projected LIMIT 1);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 3 IN (SELECT y AS z FROM rhs_semantics \
                     WHERE z = 10);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 3 IN (SELECT y AS z FROM rhs_semantics \
                     ORDER BY z LIMIT 1);",
                    // ORDER BY resolves the output alias before a same-named
                    // source column, so this orders by projected y and keeps 1.
                    SqliteValue::Integer(0),
                ),
                (
                    "SELECT 1 IN (SELECT y FROM rhs_semantics \
                     ORDER BY +1 LIMIT 1);",
                    SqliteValue::Integer(1),
                ),
            ] {
                let rows = conn.query(sql).await.unwrap();
                assert_eq!(
                    rows[0].values(),
                    &[expected],
                    "unexpected result for `{sql}`"
                );
            }

            // bd-2fong red 4: stock SQLite 3.46.1 REJECTS a correlated outer
            // reference inside an IN-set subquery's statement-level ORDER BY
            // ('Error: in prepare, no such column: outer_semantics.x' —
            // oracle-verified 2026-08-12), while projection/CASE/HAVING
            // correlation is accepted. The previous shape here encoded
            // anti-parity acceptance of the ORDER BY form; it now asserts
            // stock's rejection explicitly below instead.
            let correlated_sql = "SELECT x, \
                       x IN (SELECT outer_semantics.x FROM rhs_semantics LIMIT 1), \
                       x IN (SELECT x FROM rhs_semantics LIMIT 1), \
                       x IN (SELECT CASE WHEN y > 0 THEN outer_semantics.x ELSE y END \
                             FROM rhs_semantics LIMIT 1), \
                       x IN (SELECT max(y) FROM rhs_semantics \
                             HAVING max(y) = outer_semantics.x) \
                   FROM outer_semantics ORDER BY x;";
            let expected = vec![
                vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(0),
                ],
                vec![
                    SqliteValue::Integer(3),
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(1),
                ],
            ];
            let order_by_correlated_err = conn
                .query(
                    "SELECT x IN (SELECT y FROM rhs_semantics \
                     ORDER BY abs(y - outer_semantics.x) LIMIT 1) \
                     FROM outer_semantics ORDER BY x;",
                )
                .await
                .expect_err(
                    "stock SQLite rejects a correlated outer reference in an \
                     IN-set subquery's ORDER BY at prepare; parity requires \
                     the same rejection",
                );
            assert!(
                matches!(
                    &order_by_correlated_err,
                    FrankenError::NoSuchColumn { name } if name == "outer_semantics.x"
                ),
                "expected stock-parity NoSuchColumn(outer_semantics.x), got \
                 {order_by_correlated_err:?}"
            );
            let direct = conn.query(correlated_sql).await.unwrap();
            assert_eq!(direct.iter().map(row_values).collect::<Vec<_>>(), expected);
            let prepared = conn.prepare(correlated_sql).await.unwrap();
            let prepared_rows = prepared.query().await.unwrap();
            assert_eq!(
                prepared_rows.iter().map(row_values).collect::<Vec<_>>(),
                expected
            );

            conn.execute("CREATE TABLE lhs_affinity (x INTEGER);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE rhs_affinity (v TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO lhs_affinity VALUES (1);")
                .await
                .unwrap();
            conn.execute("INSERT INTO rhs_affinity VALUES ('01');")
                .await
                .unwrap();
            let scalar_lhs_sql = "SELECT (SELECT x) IN \
                                  (SELECT v FROM rhs_affinity ORDER BY v LIMIT 1) \
                                  FROM lhs_affinity;";
            let scalar_lhs = conn.query(scalar_lhs_sql).await.unwrap();
            assert_eq!(scalar_lhs[0].values(), &[SqliteValue::Integer(1)]);
            let prepared_scalar_lhs = conn.prepare(scalar_lhs_sql).await.unwrap();
            let prepared_scalar_lhs_rows = prepared_scalar_lhs.query().await.unwrap();
            assert_eq!(
                prepared_scalar_lhs_rows[0].values(),
                &[SqliteValue::Integer(1)]
            );
            let native_scalar_lhs_sql = "SELECT (SELECT x FROM lhs_affinity) IN \
                 (SELECT v FROM rhs_affinity ORDER BY v LIMIT 1) \
                 FROM outer_semantics;";
            let native_scalar_lhs = conn.query(native_scalar_lhs_sql).await.unwrap();
            assert_eq!(native_scalar_lhs.len(), 2);
            assert!(
                native_scalar_lhs
                    .iter()
                    .all(|row| row.values() == [SqliteValue::Integer(1)])
            );
            let prepared_native_scalar_lhs = conn.prepare(native_scalar_lhs_sql).await.unwrap();
            let prepared_native_scalar_lhs_rows = prepared_native_scalar_lhs.query().await.unwrap();
            assert_eq!(prepared_native_scalar_lhs_rows.len(), 2);
            assert!(
                prepared_native_scalar_lhs_rows
                    .iter()
                    .all(|row| row.values() == [SqliteValue::Integer(1)])
            );

            conn.execute("CREATE TABLE rhs_collation (v TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO rhs_collation VALUES ('A');")
                .await
                .unwrap();
            for (sql, expected) in [
                (
                    "SELECT 'a' IN (SELECT v COLLATE NOCASE \
                     FROM rhs_collation ORDER BY v LIMIT 1);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 'a' COLLATE BINARY IN (SELECT v COLLATE NOCASE \
                     FROM rhs_collation ORDER BY v LIMIT 1);",
                    SqliteValue::Integer(0),
                ),
                (
                    "SELECT (SELECT 'a') IN ('A' COLLATE NOCASE);",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT (SELECT 'a') COLLATE BINARY IN ('A' COLLATE NOCASE);",
                    SqliteValue::Integer(0),
                ),
            ] {
                assert_eq!(
                    conn.query(sql).await.unwrap()[0].values(),
                    &[expected.clone()]
                );
                let prepared = conn.prepare(sql).await.unwrap();
                assert_eq!(prepared.query().await.unwrap()[0].values(), &[expected]);
            }

            conn.execute("CREATE TABLE lhs_nocase (v TEXT COLLATE NOCASE);")
                .await
                .unwrap();
            conn.execute("INSERT INTO lhs_nocase VALUES ('a');")
                .await
                .unwrap();
            let scalar_inner_collation_sql = "SELECT (SELECT v FROM lhs_nocase) IN \
                 (SELECT v FROM rhs_collation ORDER BY v LIMIT 1) \
                 FROM outer_semantics;";
            let scalar_inner_collation_rows = conn.query(scalar_inner_collation_sql).await.unwrap();
            assert!(
                scalar_inner_collation_rows
                    .iter()
                    .all(|row| row.values() == [SqliteValue::Integer(0)])
            );
            let prepared_scalar_inner_collation =
                conn.prepare(scalar_inner_collation_sql).await.unwrap();
            assert!(
                prepared_scalar_inner_collation
                    .query()
                    .await
                    .unwrap()
                    .iter()
                    .all(|row| row.values() == [SqliteValue::Integer(0)])
            );

            // Native complex-IN lowering stores the projected value once and
            // reuses it after DISTINCT/ORDER selection.
            for native_deferred_projection_sql in [
                "SELECT 1 IN (SELECT DISTINCT abs(y) AS x \
                 FROM rhs_semantics ORDER BY x LIMIT 1);",
                "SELECT 1 IN (SELECT DISTINCT abs(y) \
                 FROM rhs_semantics ORDER BY 1 LIMIT 1);",
                "SELECT 1 IN (SELECT DISTINCT abs(y) \
                 FROM rhs_semantics ORDER BY abs(rhs_semantics.y) LIMIT 1);",
            ] {
                let direct = conn.query(native_deferred_projection_sql).await.unwrap();
                assert_eq!(
                    direct[0].values(),
                    &[SqliteValue::Integer(1)],
                    "native stored projection failed for \
                     `{native_deferred_projection_sql}`"
                );
                let prepared = conn.prepare(native_deferred_projection_sql).await.unwrap();
                assert_eq!(
                    prepared.query().await.unwrap()[0].values(),
                    &[SqliteValue::Integer(1)],
                    "prepared native stored projection failed for \
                     `{native_deferred_projection_sql}`"
                );
            }

            // GROUP BY forces the generic eager fallback, which still cannot
            // preserve the selected representative's deferred projection.
            for fallback_deferred_projection_sql in [
                "SELECT 1 IN (SELECT DISTINCT abs(y) AS x \
                 FROM rhs_semantics GROUP BY y ORDER BY x LIMIT 1);",
                "SELECT 1 IN (SELECT DISTINCT abs(y) \
                 FROM rhs_semantics GROUP BY y ORDER BY 1 LIMIT 1);",
                "SELECT 1 IN (SELECT DISTINCT abs(y) \
                 FROM rhs_semantics GROUP BY y \
                 ORDER BY abs(rhs_semantics.y) LIMIT 1);",
            ] {
                let direct_error = conn
                    .query(fallback_deferred_projection_sql)
                    .await
                    .expect_err("unsafe fallback DISTINCT projection must fail closed");
                assert!(matches!(
                    direct_error,
                    FrankenError::NotImplemented(ref message)
                        if message.contains("deferred projection semantics")
                ));
                let prepared_error = conn.prepare(fallback_deferred_projection_sql).await;
                assert!(matches!(
                    prepared_error,
                    Err(FrankenError::NotImplemented(ref message))
                        if message.contains("deferred projection semantics")
                ));
            }

            for sql in [
                "SELECT 1 IN (SELECT y FROM rhs_semantics ORDER BY max(y));",
                "SELECT 1 IN (SELECT * FROM rhs_semantics);",
                "SELECT 1 IN (SELECT rhs_semantics.* FROM rhs_semantics);",
                "SELECT 1 IN (SELECT (y, z) FROM rhs_semantics);",
                "SELECT 1 IN (SELECT nope FROM rhs_semantics);",
                "SELECT 1 IN (SELECT y FROM rhs_semantics WHERE nope);",
                "SELECT 1 IN (SELECT y FROM rhs_semantics ORDER BY nope);",
                "SELECT 1 IN (SELECT y FROM rhs_semantics ORDER BY -1 LIMIT 1);",
                "SELECT 1 IN (SELECT y FROM rhs_semantics ORDER BY +2 LIMIT 1);",
                "SELECT 1 IN (SELECT abs(y) FILTER (WHERE y > 0) FROM rhs_semantics);",
                "SELECT 1 IN (SELECT abs(y ORDER BY y) FROM rhs_semantics);",
                "SELECT 1 IN (SELECT abs(y ORDER BY y) OVER () FROM rhs_semantics);",
                "SELECT (1, 2) IN (SELECT y FROM rhs_semantics);",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("unsupported IN shape must report a semantic error");
            }

            let invalid_prepared = conn
                .prepare("SELECT 1 IN (SELECT nope FROM rhs_semantics);")
                .await;
            if let Ok(invalid_prepared) = invalid_prepared {
                invalid_prepared
                    .query()
                    .await
                    .expect_err("prepared unknown IN projection must report an error");
            }
        });
    }

