    #[test]
    fn test_correlated_scalar_subquery_routes_unsupported_shapes_to_complete_evaluator() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE scalar_outer (x INTEGER NOT NULL);")
                .await
                .unwrap();
            conn.execute("INSERT INTO scalar_outer VALUES (1), (2);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE scalar_inner (a INTEGER, b INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO scalar_inner VALUES (10, 20);")
                .await
                .unwrap();

            let sql = "SELECT x, \
                              (SELECT x WHERE x > 1), \
                              (SELECT count(*) WHERE x > 1) \
                       FROM scalar_outer ORDER BY x;";
            let expected = vec![
                vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Null,
                    SqliteValue::Integer(0),
                ],
                vec![
                    SqliteValue::Integer(2),
                    SqliteValue::Integer(2),
                    SqliteValue::Integer(1),
                ],
            ];
            let direct = conn.query(sql).await.unwrap();
            assert_eq!(direct.iter().map(row_values).collect::<Vec<_>>(), expected);
            let prepared = conn.prepare(sql).await.unwrap();
            let prepared_rows = prepared.query().await.unwrap();
            assert_eq!(
                prepared_rows.iter().map(row_values).collect::<Vec<_>>(),
                expected
            );

            for sql in [
                "SELECT (SELECT * FROM scalar_inner) FROM scalar_outer;",
                "SELECT (SELECT scalar_inner.* FROM scalar_inner) FROM scalar_outer;",
                "SELECT (SELECT nope FROM scalar_inner) FROM scalar_outer;",
                "SELECT (SELECT bad.nope FROM scalar_inner) FROM scalar_outer;",
            ] {
                conn.query(sql)
                    .await
                    .expect_err("invalid scalar-subquery shape must report an error");
                if let Ok(prepared) = conn.prepare(sql).await {
                    prepared
                        .query()
                        .await
                        .expect_err("prepared invalid scalar subquery must report an error");
                }
            }
        });
    }

