    #[test]
    fn test_fts5_live_vtab_insert_select_multi_table_join_issue_62() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard =
                super::pager_routing_tests::StatementReuseHotPathProfileGuard::new();
            FSQLITE_JOIN_MEM_SCAN_FAST_PATH_HITS.store(0, AtomicOrdering::Relaxed);

            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE agents (id INTEGER PRIMARY KEY, slug TEXT NOT NULL)")
                .await
                .unwrap();
            conn.execute("CREATE TABLE workspaces (id INTEGER PRIMARY KEY, path TEXT)")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE conversations (
                id INTEGER PRIMARY KEY,
                agent_id INTEGER NOT NULL,
                workspace_id INTEGER,
                title TEXT NOT NULL,
                source_path TEXT NOT NULL
            )",
            )
            .await
            .unwrap();
            conn.execute(
                "CREATE TABLE messages (
                id INTEGER PRIMARY KEY,
                conversation_id INTEGER NOT NULL,
                created_at INTEGER NOT NULL,
                content TEXT NOT NULL
            )",
            )
            .await
            .unwrap();
            conn.execute(
                "CREATE VIRTUAL TABLE fts_messages USING fts5(
                content,
                title,
                agent,
                workspace,
                source_path,
                created_at UNINDEXED
            )",
            )
            .await
            .unwrap();

            conn.execute("INSERT INTO agents(id, slug) VALUES (1, 'codex'), (2, 'claude')")
                .await
                .unwrap();
            conn.execute("INSERT INTO workspaces(id, path) VALUES (1, '/ws/one')")
                .await
                .unwrap();
            conn.execute(
                "INSERT INTO conversations(id, agent_id, workspace_id, title, source_path) VALUES
                (1, 1, 1, 'Alpha Session', '/tmp/a.jsonl'),
                (2, 2, NULL, 'Beta Session', '/tmp/b.jsonl')",
            )
            .await
            .unwrap();
            conn.execute(
                "INSERT INTO messages(id, conversation_id, created_at, content) VALUES
                (11, 1, 100, 'alpha body'),
                (12, 2, 200, 'beta body')",
            )
            .await
            .unwrap();

            let insert_sql = "INSERT INTO fts_messages(rowid, content, title, agent, workspace, source_path, created_at)
             SELECT m.id, m.content, c.title, a.slug, w.path, c.source_path, m.created_at
             FROM messages m
             JOIN conversations c ON m.conversation_id = c.id
             JOIN agents a ON c.agent_id = a.id
             LEFT JOIN workspaces w ON c.workspace_id = w.id
             ORDER BY m.rowid;";
            let statement = conn.cached_parse_single(insert_sql).unwrap();
            let Statement::Insert(insert_stmt) = statement.as_ref() else {
                panic!("expected INSERT statement");
            };
            let fsqlite_ast::InsertSource::Select(select_stmt) = &insert_stmt.source else {
                panic!("expected SELECT source");
            };
            let insert_event = fsqlite_ast::TriggerEvent::Insert;
            assert!(
                conn.has_live_vtab_instance("fts_messages"),
                "issue-62 target should be treated as a live virtual table"
            );
            assert!(
                !conn.has_matching_triggers(
                    "fts_messages",
                    fsqlite_ast::TriggerTiming::Before,
                    &insert_event,
                ),
                "issue-62 target should not have BEFORE triggers blocking the live-vtab streaming path"
            );
            assert!(
                !conn.has_matching_triggers(
                    "fts_messages",
                    fsqlite_ast::TriggerTiming::After,
                    &insert_event,
                ),
                "issue-62 target should not have AFTER triggers blocking the live-vtab streaming path"
            );
            let prepared = conn
                .prepare_simple_join_select_rows_with_scanner(
                    select_stmt,
                    None,
                    async |_source| Ok(Some(Vec::new())),
                    |table_name| conn.has_live_vtab_instance(table_name),
                )
                .await
                .unwrap();
            assert!(
                prepared.is_some(),
                "issue-62 INSERT SELECT should qualify for the streaming join preparer"
            );
            conn.execute(insert_sql).await.unwrap();
            let before_refresh_ptr = live_vtab_instance_ptr(&conn, "fts_messages");
            let reload_cx = conn.op_cx().unwrap();
            conn.reload_memdb_from_pager(&reload_cx).await.unwrap();
            let after_refresh_ptr = live_vtab_instance_ptr(&conn, "fts_messages");
            assert_eq!(
                before_refresh_ptr, after_refresh_ptr,
                "issue-62 reload should refresh memdb without rebuilding the live FTS5 instance"
            );
            let count_rows = conn
                .query("SELECT count(*) FROM fts_messages;")
                .await
                .unwrap();
            assert_eq!(
                count_rows[0].get(0),
                Some(&SqliteValue::Integer(2)),
                "post-reload count should observe the freshly persisted FTS rows"
            );

            let rows = conn
            .query(
                "SELECT rowid, content, title, agent, COALESCE(workspace, ''), source_path, created_at
                 FROM fts_messages
                 ORDER BY rowid;",
            ).await
            .unwrap();
            assert_eq!(
                rows.iter().map(row_values).collect::<Vec<_>>(),
                vec![
                    vec![
                        SqliteValue::Integer(11),
                        SqliteValue::Text("alpha body".into()),
                        SqliteValue::Text("Alpha Session".into()),
                        SqliteValue::Text("codex".into()),
                        SqliteValue::Text("/ws/one".into()),
                        SqliteValue::Text("/tmp/a.jsonl".into()),
                        SqliteValue::Text("100".into()),
                    ],
                    vec![
                        SqliteValue::Integer(12),
                        SqliteValue::Text("beta body".into()),
                        SqliteValue::Text("Beta Session".into()),
                        SqliteValue::Text("claude".into()),
                        SqliteValue::Text("".into()),
                        SqliteValue::Text("/tmp/b.jsonl".into()),
                        SqliteValue::Text("200".into()),
                    ],
                ],
            );
            assert!(
                FSQLITE_JOIN_MEM_SCAN_FAST_PATH_HITS.load(AtomicOrdering::Relaxed) > 0,
                "issue-62 streaming INSERT SELECT should keep join source scans on the MemDatabase fast path"
            );
        });
    }

