    #[test]
    fn test_file_backed_live_vtab_count_star_reloads_after_external_commit() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("live_vtab_count_star_external_refresh.db");
            let db_str = db_path.to_string_lossy().to_string();
            let conn = Connection::open(&db_str).await.unwrap();

            conn.execute("CREATE VIRTUAL TABLE docs USING fts5(content);")
                .await
                .unwrap();
            conn.execute("INSERT INTO docs(rowid, content) VALUES (1, 'alpha body');")
                .await
                .unwrap();

            let before_ptr = live_vtab_instance_ptr(&conn, "docs");
            let initial_rows = conn.query("SELECT COUNT(*) FROM docs;").await.unwrap();
            assert_eq!(initial_rows[0].values()[0], SqliteValue::Integer(1));
            assert_eq!(
                before_ptr,
                live_vtab_instance_ptr(&conn, "docs"),
                "same-connection COUNT(*) should preserve the current live FTS instance"
            );

            let other = Connection::open(&db_str).await.unwrap();
            other
                .execute("INSERT INTO docs(rowid, content) VALUES (2, 'beta body');")
                .await
                .unwrap();

            let refreshed_rows = conn.query("SELECT COUNT(*) FROM docs;").await.unwrap();
            let after_ptr = live_vtab_instance_ptr(&conn, "docs");
            assert_eq!(refreshed_rows[0].values()[0], SqliteValue::Integer(2));
            assert_ne!(
                before_ptr, after_ptr,
                "COUNT(*) after an external commit should rebuild the stale live FTS instance"
            );
        });
    }

