    // ── Savepoint tests ─────────────────────────────────────────────────

    #[test]
    fn test_savepoint_rollback_to() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (x INTEGER);").await.unwrap();
            conn.execute("INSERT INTO t VALUES (1);").await.unwrap();

            conn.execute("SAVEPOINT sp1;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (2);").await.unwrap();

            conn.execute("SAVEPOINT sp2;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (3);").await.unwrap();

            // Verify 3 rows.
            let rows = conn.query("SELECT x FROM t;").await.unwrap();
            assert_eq!(rows.len(), 3);

            // Rollback to sp2: undo value 3 only.
            conn.execute("ROLLBACK TO sp2;").await.unwrap();
            let rows = conn.query("SELECT x FROM t;").await.unwrap();
            assert_eq!(rows.len(), 2);

            // Rollback to sp1: undo value 2 as well.
            conn.execute("ROLLBACK TO sp1;").await.unwrap();
            let rows = conn.query("SELECT x FROM t;").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(row_values(&rows[0]), vec![SqliteValue::Integer(1)]);
        });
    }

    #[test]
    fn test_savepoint_release() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (x INTEGER);").await.unwrap();

            conn.execute("SAVEPOINT sp1;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (1);").await.unwrap();

            conn.execute("SAVEPOINT sp2;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (2);").await.unwrap();

            // Release sp2: changes committed to sp1 scope.
            conn.execute("RELEASE sp2;").await.unwrap();

            let rows = conn.query("SELECT x FROM t;").await.unwrap();
            assert_eq!(rows.len(), 2);
        });
    }

