    #[test]
    fn test_nested_savepoints_deep() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (x INTEGER);").await.unwrap();

            conn.execute("BEGIN;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (1);").await.unwrap();

            conn.execute("SAVEPOINT a;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (2);").await.unwrap();

            conn.execute("SAVEPOINT b;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (3);").await.unwrap();

            conn.execute("SAVEPOINT c;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (4);").await.unwrap();

            // Rollback to b: undo values 3 and 4.
            conn.execute("ROLLBACK TO b;").await.unwrap();
            let rows = conn.query("SELECT x FROM t;").await.unwrap();
            assert_eq!(rows.len(), 2);

            // Commit the whole transaction.
            conn.execute("COMMIT;").await.unwrap();

            let rows = conn.query("SELECT x FROM t;").await.unwrap();
            assert_eq!(rows.len(), 2);
        });
    }

