    #[test]
    fn test_stmt_microbatch_coalesces_repeated_inserts() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute("BEGIN;").await.unwrap();
            let stmt = conn.prepare("INSERT INTO t VALUES (?1)").await.unwrap();
            let (hits_before, renewals_before) = conn.stmt_microbatch_counters();
            for i in 0..10_i64 {
                stmt.execute_with_params(&[SqliteValue::Integer(i)])
                    .await
                    .unwrap();
            }
            conn.execute("COMMIT;").await.unwrap();
            let (hits_after, renewals_after) = conn.stmt_microbatch_counters();
            // First in-txn call is always a renewal; subsequent ones hit.
            assert!(
                hits_after > hits_before,
                "expected micro-batch hits after 10 consecutive inserts: before={hits_before} after={hits_after}"
            );
            assert!(
                renewals_after > renewals_before,
                "expected at least one renewal (first call): before={renewals_before} after={renewals_after}"
            );
            // All 10 rows landed.
            let rows = conn.query("SELECT COUNT(*) FROM t;").await.unwrap();
            assert_eq!(row_values(&rows[0]), vec![SqliteValue::Integer(10)]);
        });
    }

