    #[test]
    fn test_commit_after_savepoint_rollback_releases_retained_page_locks() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            // Use a file-backed database because :memory: uses the serialized
            // fast path which bypasses the concurrent registry entirely.
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("savepoint_rollback_locks.db");
            let conn = Connection::open(db_path.to_str().unwrap()).await.unwrap();
            conn.execute("CREATE TABLE t(x INTEGER);").await.unwrap();
            conn.execute("BEGIN CONCURRENT;").await.unwrap();
            conn.execute("SAVEPOINT sp1;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (1);").await.unwrap();

            let session_id = conn
                .concurrent_session_id
                .borrow()
                .expect("BEGIN CONCURRENT should register a session");

            conn.execute("ROLLBACK TO sp1;").await.unwrap();
            conn.execute("RELEASE sp1;").await.unwrap();

            {
                let registry = lock_unpoisoned(&conn.concurrent_registry);
                let handle = registry
                    .get(session_id)
                    .expect("concurrent handle should remain registered after savepoint rollback");
                assert!(
                    !handle.held_locks().is_empty(),
                    "savepoint rollback should preserve already-acquired page ownership until commit"
                );
            }

            conn.execute("COMMIT;").await.unwrap();

            assert!(
                conn.concurrent_session_id.borrow().is_none(),
                "successful COMMIT after savepoint rollback must clear the connection session id"
            );
            let registry = lock_unpoisoned(&conn.concurrent_registry);
            assert!(
                registry.get(session_id).is_none(),
                "successful COMMIT after savepoint rollback must unregister the MVCC session and release page locks"
            );
        });
    }

    #[test]
    fn test_begin_uses_pager_publication_visibility_for_concurrent_snapshot() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let published = conn.pager.published_snapshot();
            conn.next_commit_seq
                .store(41, std::sync::atomic::Ordering::Release);

            conn.execute("BEGIN;").await.unwrap();
            let session_id = conn
                .concurrent_session_id
                .borrow()
                .expect("BEGIN should create a concurrent session");
            let snapshot_high = {
                let registry = lock_unpoisoned(&conn.concurrent_registry);
                registry
                    .get(session_id)
                    .expect("concurrent handle should exist")
                    .snapshot()
                    .high
            };

            assert_eq!(
                snapshot_high, published.visible_commit_seq,
                "BEGIN should bind to the pager publication plane, not the raw commit clock"
            );
            assert_ne!(
                snapshot_high,
                CommitSeq::new(40),
                "BEGIN must not derive its MVCC snapshot from next_commit_seq - 1"
            );

            conn.execute("ROLLBACK;").await.unwrap();
        });
    }

    #[test]
    fn test_memory_autocommit_publication_synthesizes_visibility_from_commit_clock() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let cx = conn.op_cx().unwrap();

            let publication = conn
                .bind_pager_publication(&cx, "autocommit_begin")
                .await
                .unwrap();
            let pager_snapshot = conn.pager.published_snapshot();
            let expected_visible_commit_seq = conn
                .current_global_commit_seq()
                .max(pager_snapshot.visible_commit_seq);

            assert_eq!(
                publication.source,
                super::PagerPublicationSource::SyntheticMemory
            );
            assert_eq!(
                publication.snapshot.visible_commit_seq,
                expected_visible_commit_seq
            );
            assert_eq!(publication.snapshot.snapshot_gen, 0);
            assert_eq!(publication.snapshot.page_set_size, 0);
            assert_eq!(
                publication.snapshot.journal_mode,
                pager_snapshot.journal_mode
            );
            assert_eq!(publication.snapshot.db_size, pager_snapshot.db_size);
            assert_eq!(
                publication.snapshot.freelist_count,
                pager_snapshot.freelist_count
            );
            assert_eq!(
                publication.snapshot.checkpoint_active,
                pager_snapshot.checkpoint_active
            );
            assert_eq!(publication.read_retry_count, 0);
        });
    }

    #[test]
    fn test_memory_synthetic_publication_preserves_schema_visibility_after_ddl() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v TEXT);")
                .await
                .unwrap();

            let cx = conn.op_cx().unwrap();
            assert!(
                conn.cached_write_txn.borrow().is_none(),
                "DDL autocommit should not retain the cached write txn on :memory:"
            );
            let fresh_read_txn_contains_t = {
                let mut txn = conn
                    .pager
                    .begin(&cx, fsqlite_pager::TransactionMode::ReadOnly)
                    .await
                    .expect("fresh read txn should open");
                let page1 = txn.get_page(&cx, PageNumber::ONE).await.unwrap();
                let header = super::parse_database_header_checked(page1.as_ref()).unwrap();
                let mut cursor = Connection::new_header_btree_cursor(
                    &mut txn,
                    PageNumber::ONE,
                    header.page_size,
                    header.reserved_per_page,
                    true,
                );
                let mut found = false;
                if cursor.first(&cx).await.unwrap() {
                    loop {
                        let payload = cursor.payload(&cx).await.unwrap();
                        let values = super::parse_record(&payload).unwrap();
                        if let Some(SqliteValue::Text(name)) = values.get(1)
                            && name.eq_ignore_ascii_case("t")
                        {
                            found = true;
                            break;
                        }
                        if !cursor.next(&cx).await.unwrap() {
                            break;
                        }
                    }
                }
                txn.rollback(&cx).await.unwrap();
                found
            };
            assert!(
                fresh_read_txn_contains_t,
                "sqlite_master visibility after CREATE TABLE regressed in a fresh read transaction"
            );
            assert!(
                conn.schema
                    .borrow()
                    .iter()
                    .any(|table| table.name.eq_ignore_ascii_case("t")),
                "CREATE TABLE should leave the connection schema aware of `t`"
            );

            let stmt = conn
                .prepare("INSERT INTO t VALUES (?1, 'val');")
                .await
                .unwrap();
            let affected = stmt
                .execute_with_params(&[SqliteValue::Integer(1)])
                .await
                .unwrap();
            assert_eq!(affected, 1);
        });
    }

