    #[test]
    fn test_begin_after_busy_snapshot_rollback_refreshes_execution_image() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let path = dir.path().join("begin_after_busy_snapshot_refresh.db");
            let path_str = path.to_str().unwrap();

            let conn_a = Connection::open(path_str).await.unwrap();
            conn_a
                .execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .await
                .unwrap();
            conn_a
                .execute("INSERT INTO t VALUES (1, 0);")
                .await
                .unwrap();

            let conn_b = Connection::open(path_str).await.unwrap();
            assert_eq!(
                conn_b
                    .query_row("SELECT v FROM t WHERE id = 1;")
                    .await
                    .unwrap()
                    .values()[0],
                SqliteValue::Integer(0),
                "seed read should populate conn_b's execution image before the conflict cycle"
            );

            conn_a
                .execute("BEGIN;")
                .await
                .unwrap_or_else(|err| panic!("first writer BEGIN failed unexpectedly: {err:?}"));
            conn_b
                .execute("BEGIN;")
                .await
                .unwrap_or_else(|err| panic!("second writer BEGIN failed unexpectedly: {err:?}"));

            conn_a
                .execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                .await
                .unwrap_or_else(|err| {
                    panic!("first writer UPDATE before conflict cycle failed: {err:?}")
                });
            let loser_err = match conn_b.execute("UPDATE t SET v = v + 1 WHERE id = 1;").await {
                Ok(changes) => {
                    assert_eq!(
                        changes, 1,
                        "second writer should affect one row when the stale-write conflict defers to COMMIT"
                    );
                    conn_a.execute("COMMIT;").await.unwrap_or_else(|err| {
                        panic!("first writer COMMIT failed unexpectedly: {err:?}")
                    });
                    conn_b.execute("COMMIT;").await.expect_err(
                    "second writer should fail transiently once the stale-snapshot conflict resolves",
                )
                }
                Err(err) => {
                    conn_a.execute("COMMIT;").await.unwrap_or_else(|commit_err| {
                    panic!("first writer COMMIT after loser UPDATE conflict failed unexpectedly: {commit_err:?}")
                });
                    err
                }
            };
            assert!(
                loser_err.is_transient(),
                "same-row concurrent writer must fail transiently, got {loser_err:?}"
            );
            conn_b.execute("ROLLBACK;").await.unwrap_or_else(|err| {
                panic!("losing writer ROLLBACK after transient stale-write failure failed: {err:?}")
            });

            conn_a
                .execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                .await
                .unwrap_or_else(|err| {
                    panic!("winner UPDATE after loser rollback failed unexpectedly: {err:?}")
                });
            let latest_commit_seq = conn_a.pager.published_snapshot().visible_commit_seq;

            conn_b.execute("BEGIN;").await.unwrap_or_else(|err| {
                panic!("retry BEGIN after transient stale-write rollback failed: {err:?}")
            });
            assert_eq!(
                conn_b.current_concurrent_snapshot_seq(),
                Some(latest_commit_seq.get()),
                "retry BEGIN after rollback must bind to the latest published commit sequence"
            );
            assert_eq!(
                conn_b
                    .query_row("SELECT v FROM t WHERE id = 1;")
                    .await
                    .unwrap()
                    .values()[0],
                SqliteValue::Integer(2),
                "retry BEGIN after rollback must refresh conn_b's execution image"
            );

            conn_b
                .execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                .await
                .unwrap_or_else(|err| {
                    panic!("retrying loser UPDATE after refreshed BEGIN failed: {err:?}")
                });
            conn_b
                .execute("COMMIT;")
                .await
                .unwrap_or_else(|err| panic!("retrying loser COMMIT failed unexpectedly: {err:?}"));

            assert_eq!(
                conn_a
                    .query_row("SELECT v FROM t WHERE id = 1;")
                    .await
                    .unwrap()
                    .values()[0],
                SqliteValue::Integer(3),
                "retry path should apply the next increment on top of the latest committed value"
            );
        });
    }

