    #[test]
    fn test_cached_concurrent_handle_clears_on_transaction_teardown() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            conn.execute("BEGIN CONCURRENT;").await.unwrap();
            let cached = conn
                .concurrent_session_handle()
                .unwrap()
                .expect("concurrent session should have a handle");
            assert!(conn.cached_concurrent_handle.borrow().is_some());
            drop(cached);

            conn.execute("COMMIT;").await.unwrap();
            assert!(conn.cached_concurrent_handle.borrow().is_none());
            assert!(!conn.has_concurrent_session());

            conn.execute("BEGIN CONCURRENT;").await.unwrap();
            let cached = conn
                .concurrent_session_handle()
                .unwrap()
                .expect("concurrent session should have a handle");
            assert!(conn.cached_concurrent_handle.borrow().is_some());
            drop(cached);

            conn.execute("ROLLBACK;").await.unwrap();
            assert!(conn.cached_concurrent_handle.borrow().is_none());
            assert!(!conn.has_concurrent_session());
        });
    }

    #[test]
    fn test_memory_explicit_concurrent_direct_dml_keeps_session_without_page_io_context()
    -> Result<()> {
        let mut outcome: Result<()> = Ok(());
        asupersync::test_utils::run_test(|| async {
            outcome = async {
        let conn = Connection::open(":memory:").await?;
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, value REAL);").await?;
        conn.execute("INSERT INTO t VALUES (1, 1.0), (2, 2.0);").await?;

        let update = conn.prepare("UPDATE t SET value = ?2 WHERE id = ?1").await?;
        let delete = conn.prepare("DELETE FROM t WHERE id = ?1").await?;
        let insert = conn.prepare("INSERT INTO t VALUES (?1, ?2)").await?;

        conn.execute("BEGIN;").await?;
        assert!(conn.is_concurrent_transaction());
        assert!(conn.has_concurrent_session());
        assert!(
            conn.concurrent_page_io_context()?.is_none(),
            "private :memory: direct DML should keep the concurrent session but skip shared page-I/O wrapping"
        );

        assert_eq!(
            update.execute_with_params(&[SqliteValue::Integer(1), SqliteValue::Float(3.0)]).await?,
            1
        );
        assert_eq!(delete.execute_with_params(&[SqliteValue::Integer(2)]).await?, 1);
        assert_eq!(
            insert.execute_with_params(&[SqliteValue::Integer(3), SqliteValue::Float(4.0)]).await?,
            1
        );
        conn.execute("COMMIT;").await?;

        let rows = conn.query("SELECT id, value FROM t ORDER BY id;").await?;
        assert_eq!(rows.len(), 2);
        let values = rows
            .iter()
            .map(|row| row.values().to_vec())
            .collect::<Vec<_>>();
        assert_eq!(
            values,
            vec![
                vec![SqliteValue::Integer(1), SqliteValue::Float(3.0)],
                vec![SqliteValue::Integer(3), SqliteValue::Float(4.0)],
            ]
        );
        assert!(!conn.has_concurrent_session());
        Ok(())
        }.await;
        });
        outcome
    }

