    // ── MVCC page-level locking tests (bd-kivg / 5E.2) ────────────────────

    #[test]
    fn test_mvcc_page_io_write_acquires_lock() {
        asupersync::test_utils::run_test(|| async {
            // Test that writing through concurrent_write_page acquires page locks.
            use fsqlite_mvcc::{ConcurrentHandle, concurrent_write_page};
            use fsqlite_types::{PageData, Snapshot, TxnEpoch, TxnId, TxnToken};

            // Create MVCC state.
            let snapshot = Snapshot::new(CommitSeq::ZERO, SchemaEpoch::new(0));
            let session_id = 1;
            let txn_token = TxnToken::new(TxnId::new(session_id).unwrap(), TxnEpoch::new(1));
            let mut handle = ConcurrentHandle::new(snapshot, txn_token);
            let lock_table = InProcessPageLockTable::new();

            // Write to a page.
            let page_no = PageNumber::new(2).unwrap();
            let data = PageData::from_vec(vec![0u8; 4096]);
            concurrent_write_page(&mut handle, &lock_table, session_id, page_no, data).unwrap();

            // Verify page lock is held.
            assert!(handle.held_locks().contains(&page_no));

            // Verify page is in write set.
            assert_eq!(handle.write_set_len(), 1);
            assert!(handle.write_set_pages().contains(&page_no));
        });
    }

    #[test]
    fn test_mvcc_page_io_read_own_writes() {
        asupersync::test_utils::run_test(|| async {
            // Test that reading through concurrent write/read sees own writes.
            use fsqlite_mvcc::{ConcurrentHandle, concurrent_read_page, concurrent_write_page};
            use fsqlite_types::{PageData, Snapshot, TxnEpoch, TxnId, TxnToken};

            let snapshot = Snapshot::new(CommitSeq::ZERO, SchemaEpoch::new(0));
            let session_id = 1;
            let txn_token = TxnToken::new(TxnId::new(session_id).unwrap(), TxnEpoch::new(1));
            let mut handle = ConcurrentHandle::new(snapshot, txn_token);
            let lock_table = InProcessPageLockTable::new();

            // Write distinctive data to a page.
            let page_no = PageNumber::new(2).unwrap();
            let mut data = vec![0u8; 4096];
            data[0..4].copy_from_slice(&[0xDE, 0xAD, 0xBE, 0xEF]);
            concurrent_write_page(
                &mut handle,
                &lock_table,
                session_id,
                page_no,
                PageData::from_vec(data),
            )
            .unwrap();

            // Read the same page - should see our write.
            let read_data = concurrent_read_page(&handle, page_no).unwrap();
            assert_eq!(&read_data.as_bytes()[0..4], &[0xDE, 0xAD, 0xBE, 0xEF]);
        });
    }

    #[test]
    fn test_mvcc_page_io_write_conflict_returns_busy() {
        asupersync::test_utils::run_test(|| async {
            // Test that two concurrent sessions writing same page conflicts.
            use fsqlite_mvcc::{ConcurrentHandle, MvccError, concurrent_write_page};
            use fsqlite_types::{PageData, Snapshot, TxnEpoch, TxnId, TxnToken};

            // Single shared lock table for both sessions - this is the key for testing.
            let lock_table = InProcessPageLockTable::new();

            // Session 1 writes to page 2.
            let snapshot1 = Snapshot::new(CommitSeq::ZERO, SchemaEpoch::new(0));
            let session_id_1 = 1;
            let txn_token_1 = TxnToken::new(TxnId::new(session_id_1).unwrap(), TxnEpoch::new(1));
            let mut handle1 = ConcurrentHandle::new(snapshot1, txn_token_1);

            let page_no = PageNumber::new(2).unwrap();
            concurrent_write_page(
                &mut handle1,
                &lock_table,
                session_id_1,
                page_no,
                PageData::from_vec(vec![0u8; 4096]),
            )
            .unwrap();

            // Session 2 tries to write to the same page - should fail with Busy.
            let snapshot2 = Snapshot::new(CommitSeq::ZERO, SchemaEpoch::new(0));
            let session_id_2 = 2;
            let txn_token_2 = TxnToken::new(TxnId::new(session_id_2).unwrap(), TxnEpoch::new(2));
            let mut handle2 = ConcurrentHandle::new(snapshot2, txn_token_2);

            let result = concurrent_write_page(
                &mut handle2,
                &lock_table,
                session_id_2,
                page_no,
                PageData::from_vec(vec![0u8; 4096]),
            );
            assert!(matches!(result, Err(MvccError::Busy)));

            // Session 2 can write to a different page.
            let page_no_3 = PageNumber::new(3).unwrap();
            concurrent_write_page(
                &mut handle2,
                &lock_table,
                session_id_2,
                page_no_3,
                PageData::from_vec(vec![0u8; 4096]),
            )
            .unwrap();
        });
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    #[allow(clippy::significant_drop_tightening)]
    fn test_sql_concurrent_updates_populate_write_sets() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("write_set_probe.db");
            let db = db_path.to_string_lossy().to_string();

            {
                let conn = Connection::open(&db).await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
                conn.execute(
                    "CREATE TABLE accounts (id INTEGER PRIMARY KEY, balance INTEGER NOT NULL);",
                )
                .await
                .unwrap();
                conn.execute("INSERT INTO accounts VALUES (1, 0);")
                    .await
                    .unwrap();
            }

            let conn1 = Connection::open(&db).await.unwrap();
            let conn2 = Connection::open(&db).await.unwrap();
            assert!(
                Arc::ptr_eq(
                    &conn1.concurrent_commit_index,
                    &conn2.concurrent_commit_index
                ),
                "connections on same path must share commit index"
            );
            assert!(
                Arc::ptr_eq(&conn1.concurrent_lock_table, &conn2.concurrent_lock_table),
                "connections on same path must share lock table"
            );
            conn1
                .execute("PRAGMA fsqlite.concurrent_mode=ON;")
                .await
                .unwrap();
            conn2
                .execute("PRAGMA fsqlite.concurrent_mode=ON;")
                .await
                .unwrap();

            conn1.execute("BEGIN CONCURRENT;").await.unwrap();
            conn2.execute("BEGIN CONCURRENT;").await.unwrap();

            assert_eq!(
                conn1
                    .execute("UPDATE accounts SET balance = balance + 1 WHERE id = 1;")
                    .await
                    .unwrap(),
                1,
                "first concurrent writer should update one row"
            );
            let update2 = conn2
                .execute("UPDATE accounts SET balance = balance + 1 WHERE id = 1;")
                .await;

            let s1 = conn1
                .concurrent_session_id
                .borrow()
                .expect("conn1 should have active concurrent session");
            {
                let reg1 = lock_unpoisoned(&conn1.concurrent_registry);
                let h1 = reg1.get(s1).expect("session1 handle missing");
                assert!(
                    h1.write_set_len() > 0,
                    "conn1 UPDATE should populate concurrent write set"
                );
                let mut pages = h1.write_set_pages();
                pages.sort_unstable();
                assert!(
                    !pages.is_empty(),
                    "conn1 write set should include at least one page"
                );
            }
            match update2 {
                Ok(changes2) => {
                    assert_eq!(changes2, 1, "second writer update should affect one row");
                    let s2 = conn2
                        .concurrent_session_id
                        .borrow()
                        .expect("conn2 should have active concurrent session");
                    let mut pages2 = {
                        let reg2 = lock_unpoisoned(&conn2.concurrent_registry);
                        let h2 = reg2.get(s2).expect("session2 handle missing");
                        assert!(
                            h2.write_set_len() > 0,
                            "conn2 UPDATE should populate concurrent write set"
                        );
                        let mut pages = h2.write_set_pages();
                        pages.sort_unstable();
                        pages
                    };
                    pages2.sort_unstable();

                    let pages1 = {
                        let reg1 = lock_unpoisoned(&conn1.concurrent_registry);
                        let h1 = reg1.get(s1).expect("session1 handle missing");
                        let mut pages = h1.write_set_pages();
                        pages.sort_unstable();
                        pages
                    };
                    let overlap = pages1.iter().any(|p| pages2.contains(p));
                    assert!(
                        overlap,
                        "same-row concurrent updates should overlap on at least one written page; pages1={pages1:?} pages2={pages2:?}"
                    );

                    let commit1 = conn1.execute("COMMIT;").await;
                    let commit2 = conn2.execute("COMMIT;").await;
                    assert!(
                        commit1.is_ok(),
                        "first commit should succeed in conflict probe: {commit1:?}"
                    );
                    assert!(
                        commit2.is_err(),
                        "second commit should fail with FCW conflict; pages1={pages1:?} pages2={pages2:?}"
                    );
                    if let Err(err) = commit2 {
                        assert!(
                            err.is_transient(),
                            "second commit should return transient busy/busy_snapshot, got {err}"
                        );
                    }
                }
                Err(err2) => {
                    assert!(
                        err2.is_transient(),
                        "second writer should fail with transient conflict (busy/busy_snapshot), got {err2}"
                    );
                    let commit1 = conn1.execute("COMMIT;").await;
                    assert!(
                        commit1.is_ok(),
                        "first commit should still succeed after second writer conflict: {commit1:?}"
                    );
                    let rollback2 = conn2.execute("ROLLBACK;").await;
                    assert!(
                        rollback2.is_ok(),
                        "second writer should remain rollback-able after transient conflict: {rollback2:?}"
                    );
                }
            }
        });
    }

    #[test]
    fn test_concurrent_deposit_sum_invariant_probe_bd_rjc() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            const WORKERS: usize = 8;
            const TXNS_PER_WORKER: usize = 240;
            const ACCOUNT_COUNT: i64 = 64;
            const INITIAL_BALANCE: i64 = 1_000;

            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("bd_rjc_sum_probe.db");
            let db = db_path.to_string_lossy().to_string();

            {
                let mut conn = Connection::open(&db).await.unwrap();
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
                conn.execute(
                    "CREATE TABLE accounts (id INTEGER PRIMARY KEY, balance INTEGER NOT NULL);",
                )
                .await
                .unwrap();
                for id in 1..=ACCOUNT_COUNT {
                    conn.execute(&format!(
                        "INSERT INTO accounts (id, balance) VALUES ({id}, {INITIAL_BALANCE});"
                    ))
                    .await
                    .unwrap();
                }
                conn.close_in_place().await.unwrap();
            }

            let start_barrier = Arc::new(std::sync::Barrier::new(WORKERS));
            let mut handles = Vec::with_capacity(WORKERS);
            for worker_id in 0..WORKERS {
                let db = db.clone();
                let barrier = Arc::clone(&start_barrier);
                handles.push(std::thread::spawn(move || -> (Vec<i64>, u64) {
                let mut worker_out: (Vec<i64>, u64) = (Vec::new(), 0);
                asupersync::test_utils::run_test(|| async {
                let mut conn = retry_busy_connection_bootstrap(|| Connection::open(&db))
                    .await
                    .unwrap();
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").await.unwrap();

                // Synchronize worker start to maximize overlap while preserving
                // deterministic per-worker operation streams.
                barrier.wait();

                let mut per_account_delta = vec![0_i64; usize::try_from(ACCOUNT_COUNT).unwrap()];
                let mut transient_retries = 0_u64;
                for txn_index in 0..TXNS_PER_WORKER {
                    let account = ((worker_id * TXNS_PER_WORKER + txn_index)
                        % usize::try_from(ACCOUNT_COUNT).unwrap())
                        + 1;
                    let amount = i64::try_from((worker_id + txn_index) % 3 + 1).unwrap();

                    loop {
                        // BEGIN CONCURRENT can legitimately return a transient
                        // BusySnapshot ("pager publication advanced between metadata
                        // bind and reload transaction") when a peer commits between
                        // this begin's metadata bind and its reload transaction — the
                        // engine surfaces it for the caller to restart from a fresh
                        // bind (reload_memdb_from_pager_with_prebound_publication).
                        // Retry it exactly like the UPDATE/COMMIT steps below.
                        match conn.execute("BEGIN CONCURRENT;").await {
                            Ok(_) => {}
                            Err(err) if err.is_transient() => {
                                transient_retries += 1;
                                drop(conn.execute("ROLLBACK;").await);
                                continue;
                            }
                            Err(err) => panic!(
                                "non-transient BEGIN CONCURRENT failure in worker={worker_id} txn={txn_index}: {err}"
                            ),
                        }
                        match conn.execute(&format!(
                            "UPDATE accounts SET balance = balance + {amount} WHERE id = {account};"
                        )).await {
                            Ok(changes) => {
                                assert_eq!(changes, 1, "expected one-row account update");
                                let session_id = conn
                                    .concurrent_session_id
                                    .borrow()
                                    .expect("concurrent session should stay active after UPDATE");
                                let write_set_len = {
                                    let registry = lock_unpoisoned(&conn.concurrent_registry);
                                    registry
                                        .get(session_id)
                                        .expect("concurrent session handle missing after UPDATE")
                                        .write_set_len()
                                };
                                assert!(
                                    write_set_len > 0,
                                    "UPDATE reported success but concurrent write set is empty \
                                     (worker={worker_id} txn={txn_index} account={account} amount={amount})"
                                );
                            }
                            Err(err) if err.is_transient() => {
                                transient_retries += 1;
                                drop(conn.execute("ROLLBACK;").await);
                                continue;
                            }
                            Err(err) => {
                                panic!(
                                    "non-transient update failure in worker={worker_id} txn={txn_index}: {err}"
                                );
                            }
                        }

                        match conn.execute("COMMIT;").await {
                            Ok(_) => {
                                per_account_delta[account - 1] += amount;
                                break;
                            }
                            Err(err) if err.is_transient() => {
                                transient_retries += 1;
                                drop(conn.execute("ROLLBACK;").await);
                            }
                            Err(err) => {
                                panic!(
                                    "non-transient commit failure in worker={worker_id} txn={txn_index}: {err}"
                                );
                            }
                        }
                    }
                }

                conn.close_without_checkpoint_in_place().await.unwrap();
                worker_out = (per_account_delta, transient_retries);
                });
                worker_out
            }));
            }

            let mut expected_per_account = vec![0_i64; usize::try_from(ACCOUNT_COUNT).unwrap()];
            let mut expected_delta = 0_i64;
            let mut total_retries = 0_u64;
            for handle in handles {
                let (deltas, retries) = handle.join().expect("worker thread should not panic");
                for (index, delta) in deltas.into_iter().enumerate() {
                    expected_per_account[index] += delta;
                    expected_delta += delta;
                }
                total_retries += retries;
            }

            let mut verifier = Connection::open(&db).await.unwrap();
            let sum_row = verifier
                .query_row("SELECT SUM(balance) FROM accounts;")
                .await
                .unwrap();
            let final_sum = match sum_row.get(0) {
                Some(SqliteValue::Integer(value)) => *value,
                Some(other) => panic!("expected integer sum row, got {other:?}"),
                None => panic!("sum query returned no column"),
            };
            let initial_sum = ACCOUNT_COUNT * INITIAL_BALANCE;
            let expected_sum = initial_sum + expected_delta;

            let rows = verifier
                .query("SELECT id, balance FROM accounts ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(
                rows.len(),
                usize::try_from(ACCOUNT_COUNT).unwrap(),
                "expected one balance row per account"
            );
            let mut mismatches = Vec::new();
            for (index, row) in rows.iter().enumerate() {
                let expected_id = i64::try_from(index + 1).unwrap();
                let id = match row.get(0) {
                    Some(SqliteValue::Integer(value)) => *value,
                    Some(other) => panic!("expected integer account id, got {other:?}"),
                    None => panic!("account row missing id column"),
                };
                assert_eq!(id, expected_id, "unexpected account id ordering");
                let balance = match row.get(1) {
                    Some(SqliteValue::Integer(value)) => *value,
                    Some(other) => panic!("expected integer balance, got {other:?}"),
                    None => panic!("account row missing balance column"),
                };
                let expected_balance = INITIAL_BALANCE + expected_per_account[index];
                if balance != expected_balance {
                    mismatches.push(format!(
                        "id={id} expected_balance={expected_balance} actual_balance={balance}"
                    ));
                }
            }
            let mismatch_preview = mismatches
                .iter()
                .take(8)
                .cloned()
                .collect::<Vec<_>>()
                .join(", ");
            assert_eq!(
                final_sum,
                expected_sum,
                "bd-rjc sum probe mismatch: final_sum={final_sum} expected_sum={expected_sum} initial_sum={initial_sum} expected_delta={expected_delta} retries={total_retries} mismatches={} sample=[{}]",
                mismatches.len(),
                mismatch_preview
            );
            assert!(
                mismatches.is_empty(),
                "bd-rjc per-account drift detected ({} mismatches): {}",
                mismatches.len(),
                mismatch_preview
            );
            verifier.close_without_checkpoint_in_place().await.unwrap();
        });
    }

    #[test]
    fn test_filebacked_concurrent_commit_uses_pager_sequence_after_clock_floor_race() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("filebacked_commit_clock_floor_race.db");
            let db = db_path.to_string_lossy().to_string();
            let mut conn = Connection::open(&db).await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 0);").await.unwrap();
            let table_root_pgno = PageNumber::new(
                u32::try_from(
                    conn.schema
                        .borrow()
                        .iter()
                        .find(|table| table.name.eq_ignore_ascii_case("t"))
                        .map(|table| table.root_page)
                        .expect("table t should exist after setup"),
                )
                .expect("root page should fit in u32"),
            )
            .expect("root page should be valid");

            let next_commit_seq = Arc::clone(&conn.next_commit_seq);
            let pager_visible_before_commit = conn.pager.published_snapshot().visible_commit_seq;
            next_commit_seq.fetch_max(
                pager_visible_before_commit.get().saturating_add(8),
                AtomicOrdering::AcqRel,
            );
            assert_eq!(
                conn.planned_concurrent_commit_seq(),
                pager_visible_before_commit.next(),
                "file-backed planning must ignore an ahead logical floor and predict from the pager clock"
            );
            let hook_calls = Arc::new(AtomicUsize::new(0));
            let hook_calls_for_callback = Arc::clone(&hook_calls);
            super::set_concurrent_commit_window_hook(Some(Arc::new(move || {
                hook_calls_for_callback.fetch_add(1, AtomicOrdering::SeqCst);
                let planned_seq = next_commit_seq.load(AtomicOrdering::Acquire);
                next_commit_seq.fetch_max(planned_seq.saturating_add(1), AtomicOrdering::AcqRel);
            })));
            struct CommitWindowHookGuard;
            impl Drop for CommitWindowHookGuard {
                fn drop(&mut self) {
                    super::set_concurrent_commit_window_hook(None);
                }
            }
            let hook_guard = CommitWindowHookGuard;

            conn.execute("BEGIN;").await.unwrap();
            assert_eq!(
                conn.execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                    .await
                    .unwrap(),
                1
            );
            conn.execute("COMMIT;").await.unwrap();
            drop(hook_guard);

            assert_eq!(
                hook_calls.load(AtomicOrdering::SeqCst),
                1,
                "the deterministic post-durable/pre-MVCC-publish race hook must fire once"
            );
            let pager_visible = conn.pager.published_snapshot().visible_commit_seq;
            assert_eq!(
                conn.concurrent_commit_index.latest(table_root_pgno),
                Some(pager_visible),
                "CommitIndex must publish the pager's durable commit identity even when a peer \
                 raises the shared logical clock floor before MVCC finalization"
            );
            assert_eq!(
                conn.current_global_commit_seq(),
                pager_visible,
                "the finalized logical clock must remain aligned with the durable pager sequence"
            );
            conn.close_without_checkpoint_in_place().await.unwrap();
        });
    }

    #[test]
    fn test_pending_conflict_page_revalidates_fcw_after_lock_acquisition() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let conn = Connection::open(":memory:").await.unwrap();
            let page = PageNumber::new(42).unwrap();
            let mut registry = ConcurrentRegistry::new();
            let session_id = registry
                .begin_concurrent(Snapshot::new(CommitSeq::new(5), SchemaEpoch::new(0)))
                .unwrap();

            let commit_index = Arc::clone(&conn.concurrent_commit_index);
            super::set_pending_conflict_lock_window_hook(Some(Arc::new(move || {
                commit_index.update(page, CommitSeq::new(6));
            })));
            struct PendingConflictLockWindowHookGuard;
            impl Drop for PendingConflictLockWindowHookGuard {
                fn drop(&mut self) {
                    super::set_pending_conflict_lock_window_hook(None);
                }
            }
            let hook_guard = PendingConflictLockWindowHookGuard;

            let error = conn
                .track_pending_conflict_pages_with_registry(&registry, session_id, &[page])
                .unwrap_err();
            drop(hook_guard);

            assert!(
                matches!(
                    error,
                    FrankenError::BusySnapshot { ref conflicting_pages }
                        if conflicting_pages == "42"
                ),
                "the stale writer must fail FCW after acquiring the page lock: {error}"
            );
            let handle = registry.get(session_id).unwrap();
            assert!(
                !handle.tracks_write_conflict_page(page),
                "the rejected pending page must not remain in the write-conflict surface"
            );
            assert!(
                !handle.holds_page_lock(page),
                "the rejected pending page must release its newly acquired lock"
            );
            drop(handle);
            conn.close().await.unwrap();
        });
    }

    #[test]
    fn test_bounded_hot_page_writers_refresh_snapshot_after_conflict() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            const WORKERS: usize = 8;
            const COMMITS_PER_WORKER: u64 = 4;
            const MAX_ATTEMPTS_PER_WORKER: u64 = 256;

            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("bounded_hot_page_snapshot_refresh.db");
            let db = db_path.to_string_lossy().to_string();
            let table_root_page = {
                let mut conn = Connection::open(&db).await.unwrap();
                conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                    .await
                    .unwrap();
                conn.execute("INSERT INTO t VALUES (1, 0);").await.unwrap();
                let root_page = conn
                    .schema
                    .borrow()
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case("t"))
                    .map(|table| table.root_page)
                    .expect("table t should exist after setup");
                conn.close_without_checkpoint_in_place().await.unwrap();
                root_page
            };
            let table_root_pgno = PageNumber::new(
                u32::try_from(table_root_page).expect("root page should fit in u32"),
            )
            .expect("root page should be valid");

            let start_barrier = Arc::new(std::sync::Barrier::new(WORKERS));
            let mut handles = Vec::with_capacity(WORKERS);
            for worker_id in 0..WORKERS {
                let db = db.clone();
                let barrier = Arc::clone(&start_barrier);
                handles.push(std::thread::spawn(move || -> Result<u64> {
                    let mut worker_result = Err(FrankenError::internal(
                        "bounded hot-page worker exited without a result",
                    ));
                    asupersync::test_utils::run_test(|| async {
                        worker_result = async {
                        let mut conn = Connection::open(&db).await?;
                        assert!(
                            conn.is_concurrent_mode_default(),
                            "worker {worker_id} lost the concurrent-writer default"
                        );
                        barrier.wait();

                        let clock_diagnostic = || {
                            let active_commit_seqs =
                                lock_unpoisoned(&conn.active_commit_seqs).clone();
                            format!(
                                "worker={worker_id} snapshot={:?} latest_root={:?} \
                                 pager_visible={} stable={} next={} memdb_visible={} \
                                 last_local={:?} active_commit_seqs={active_commit_seqs:?}",
                                conn.current_concurrent_snapshot_seq(),
                                conn.concurrent_commit_index.latest(table_root_pgno),
                                conn.pager.published_snapshot().visible_commit_seq.get(),
                                conn.current_global_commit_seq().get(),
                                conn.next_commit_seq.load(AtomicOrdering::Acquire),
                                conn.memdb_visible_commit_seq.borrow().get(),
                                conn.last_local_commit_seq(),
                            )
                        };

                        let mut commits = 0_u64;
                        let mut attempts = 0_u64;
                        while commits < COMMITS_PER_WORKER {
                            attempts += 1;
                            if attempts > MAX_ATTEMPTS_PER_WORKER {
                                return Err(FrankenError::internal(format!(
                                    "bounded hot-page worker exhausted its attempt budget: {}",
                                    clock_diagnostic()
                                )));
                            }

                            let latest_before_begin = conn
                                .concurrent_commit_index
                                .latest(table_root_pgno)
                                .unwrap_or(CommitSeq::ZERO);
                            match conn.execute("BEGIN;").await {
                                Ok(_) => {}
                                Err(error) if error.is_transient() => {
                                    std::thread::sleep(std::time::Duration::from_millis(1));
                                    continue;
                                }
                                Err(error) => return Err(error),
                            }

                            let snapshot_high = CommitSeq::new(
                                conn.current_concurrent_snapshot_seq()
                                    .expect("BEGIN should bind a concurrent snapshot"),
                            );
                            if snapshot_high < latest_before_begin {
                                let diagnostic = clock_diagnostic();
                                let _ = conn.execute("ROLLBACK;").await;
                                return Err(FrankenError::internal(format!(
                                    "BEGIN bound a snapshot behind the already-published hot page: \
                                     latest_before_begin={latest_before_begin:?}; {diagnostic}"
                                )));
                            }

                            match conn.execute("UPDATE t SET v = v + 1 WHERE id = 1;").await {
                                Ok(1) => {}
                                Ok(changes) => {
                                    return Err(FrankenError::internal(format!(
                                        "hot-page UPDATE affected {changes} rows; {}",
                                        clock_diagnostic()
                                    )));
                                }
                                Err(error) if error.is_transient() => {
                                    let rollback_result = conn.execute("ROLLBACK;").await;
                                    if rollback_result.is_err() && conn.in_transaction.get() {
                                        return Err(FrankenError::internal(format!(
                                            "transient UPDATE left an active transaction after \
                                             rollback {rollback_result:?}: {}",
                                            clock_diagnostic()
                                        )));
                                    }
                                    std::thread::sleep(std::time::Duration::from_millis(1));
                                    continue;
                                }
                                Err(error) => return Err(error),
                            }

                            match conn.execute("COMMIT;").await {
                                Ok(_) => {
                                    commits += 1;
                                    let latest_root_commit = conn
                                        .concurrent_commit_index
                                        .latest(table_root_pgno)
                                        .expect("successful hot-page commit should be indexed");
                                    let committed_seq = CommitSeq::new(
                                        conn.last_local_commit_seq().expect(
                                            "successful commit should record its local identity",
                                        ),
                                    );
                                    let pager_visible =
                                        conn.pager.published_snapshot().visible_commit_seq;
                                    if committed_seq > pager_visible {
                                        return Err(FrankenError::internal(format!(
                                            "successful hot-page commit reported a local identity \
                                             ahead of its durable pager publication: {}",
                                            clock_diagnostic()
                                        )));
                                    }
                                    if latest_root_commit < committed_seq {
                                        return Err(FrankenError::internal(format!(
                                            "successful hot-page commit was not present in the \
                                             shared CommitIndex: {}",
                                            clock_diagnostic()
                                        )));
                                    }
                                }
                                Err(error) if error.is_transient() => {
                                    let rollback_result = conn.execute("ROLLBACK;").await;
                                    if rollback_result.is_err() && conn.in_transaction.get() {
                                        return Err(FrankenError::internal(format!(
                                            "transient COMMIT left an active transaction after \
                                             rollback {rollback_result:?}: {}",
                                            clock_diagnostic()
                                        )));
                                    }
                                    std::thread::sleep(std::time::Duration::from_millis(1));
                                }
                                Err(error) => return Err(error),
                            }
                        }

                        conn.close_without_checkpoint_in_place().await?;
                        Ok(commits)
                        }
                        .await;
                    });
                    worker_result
                }));
            }

            for (worker_id, handle) in handles.into_iter().enumerate() {
                assert_eq!(
                    handle
                        .join()
                        .unwrap_or_else(|_| panic!("hot-page worker {worker_id} panicked"))
                        .unwrap_or_else(|error| {
                            panic!("hot-page worker {worker_id} failed: {error}")
                        }),
                    COMMITS_PER_WORKER,
                    "hot-page worker {worker_id} committed the wrong number of updates"
                );
            }

            let mut verifier = Connection::open(&db).await.unwrap();
            assert_eq!(
                verifier
                    .query_row("SELECT v FROM t WHERE id = 1;")
                    .await
                    .unwrap()
                    .values()[0],
                SqliteValue::Integer(
                    i64::try_from(WORKERS).unwrap() * i64::try_from(COMMITS_PER_WORKER).unwrap()
                )
            );
            verifier.close_without_checkpoint_in_place().await.unwrap();
        });
    }

    #[test]
    fn test_concurrent_single_account_increment_invariant_probe_bd_rjc() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            const WORKERS: usize = 2;
            const TXNS_PER_WORKER: usize = 320;

            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("bd_rjc_single_account_probe.db");
            let db = db_path.to_string_lossy().to_string();
            let table_root_page = {
                let conn = Connection::open(&db).await.unwrap();
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
                conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                    .await
                    .unwrap();
                let root_page = conn
                    .schema
                    .borrow()
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case("t"))
                    .map(|table| table.root_page)
                    .expect("table t should exist after CREATE TABLE");
                conn.execute("INSERT INTO t (id, v) VALUES (1, 0);")
                    .await
                    .unwrap();
                root_page
            };

            let start_barrier = Arc::new(std::sync::Barrier::new(WORKERS));
            let mut handles = Vec::with_capacity(WORKERS);
            for _worker_id in 0..WORKERS {
                let db = db.clone();
                let barrier = Arc::clone(&start_barrier);
                handles.push(std::thread::spawn(move || -> u64 {
                let mut retries_out = 0_u64;
                asupersync::test_utils::run_test(|| async {
                let conn = Connection::open(&db).await.unwrap();
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;").await.unwrap();
                let table_root_pgno = fsqlite_types::PageNumber::new(
                    u32::try_from(table_root_page).expect("root page should fit in u32"),
                )
                .expect("root page should be valid");
                async fn describe_row_via_txn(
                    txn: &mut fsqlite_pager::TransactionKind,
                    table_root_page: i32,
                ) -> String {
                        let cx = Cx::new();
                        let mut cursor = fsqlite_btree::BtCursor::new(
                            fsqlite_btree::TransactionPageIo::new(txn),
                            fsqlite_types::PageNumber::new(
                                u32::try_from(table_root_page)
                                    .expect("root page should fit in u32"),
                            )
                            .expect("root page should be valid"),
                            u32::try_from(fsqlite_types::PageSize::DEFAULT.as_usize())
                                .expect("page size should fit in u32"),
                            true,
                        );
                        let seek = match cursor.table_move_to(&cx, 1).await {
                            Ok(seek) => seek,
                            Err(err) => return format!("move_to_err:{err}"),
                        };
                        if !seek.is_found() {
                            return "row_missing".to_owned();
                        }
                        let payload = match cursor.payload(&cx).await {
                            Ok(payload) => payload,
                            Err(err) => return format!("payload_err:{err}"),
                        };
                        match fsqlite_types::record::parse_record(&payload) {
                            Some(values) => format!("{values:?}"),
                            None => format!("decode_err:payload_len={}", payload.len()),
                        }
                }
                async fn describe_active_txn_row(conn: &Connection, table_root_page: i32) -> String {
                    let mut active_txn = conn.active_txn.borrow_mut();
                    let Some(txn) = active_txn.as_mut() else {
                        return "no_active_txn".to_owned();
                    };
                    describe_row_via_txn(txn, table_root_page).await
                }
                async fn describe_fresh_conn_state(db: &str, table_root_page: i32) -> String {
                    let fresh = Connection::open(db).await.unwrap();
                    let sql_row = fresh
                        .query_row("SELECT v FROM t WHERE id = 1;")
                        .await
                        .ok()
                        .and_then(|row| row.get(0).cloned());
                    let pager_row = {
                        let cx = Cx::new();
                        let mut txn = fresh
                            .pager
                            .begin(&cx, fsqlite_pager::TransactionMode::ReadOnly)
                            .await
                            .unwrap();
                        describe_row_via_txn(&mut txn, table_root_page).await
                    };
                    format!("sql={sql_row:?} pager={pager_row}")
                }
                barrier.wait();
                let mut retries = 0_u64;
                for _ in 0..TXNS_PER_WORKER {
                    loop {
                        let pre_begin_latest_root_commit = conn
                            .concurrent_commit_index
                            .latest(table_root_pgno)
                            .map_or(0, CommitSeq::get);
                        match conn.execute("BEGIN CONCURRENT;").await {
                            Ok(_) => {}
                            Err(err) if err.is_transient() => {
                                retries += 1;
                                continue;
                            }
                            Err(err) => panic!("non-transient begin failure: {err}"),
                        }
                        let snapshot_high = conn
                            .current_concurrent_snapshot_seq()
                            .expect("BEGIN CONCURRENT should bind a snapshot");
                        let latest_root_commit = conn
                            .concurrent_commit_index
                            .latest(table_root_pgno)
                            .map_or(0, CommitSeq::get);
                        assert!(
                            snapshot_high >= pre_begin_latest_root_commit,
                            "BEGIN CONCURRENT bound stale snapshot in hot-row probe: snapshot_high={snapshot_high} pre_begin_latest_root_commit={pre_begin_latest_root_commit} latest_root_commit={latest_root_commit} retries={retries}"
                        );
                        match conn.execute("UPDATE t SET v = v + 1 WHERE id = 1;").await {
                            Ok(changes) => {
                                assert_eq!(changes, 1, "expected one-row update");
                                let session_id = conn
                                    .concurrent_session_id
                                    .borrow()
                                    .expect("concurrent session should stay active after UPDATE");
                                let concurrent_write_set_len = {
                                    let registry = lock_unpoisoned(&conn.concurrent_registry);
                                    registry
                                        .get(session_id)
                                        .expect("concurrent session handle missing after UPDATE")
                                        .write_set_len()
                                };
                                assert!(
                                    concurrent_write_set_len > 0,
                                    "UPDATE reported success but concurrent write set is empty"
                                );
                                let root_page_tracked = {
                                    let registry = lock_unpoisoned(&conn.concurrent_registry);
                                    registry
                                        .get(session_id)
                                        .expect("concurrent session handle missing after UPDATE")
                                        .write_set_pages()
                                        .contains(
                                            &fsqlite_types::PageNumber::new(
                                                u32::try_from(table_root_page)
                                                    .expect("root page should fit in u32"),
                                            )
                                            .expect("root page should be valid"),
                                        )
                                };
                                assert!(
                                    root_page_tracked,
                                    "UPDATE reported success but concurrent write set omitted table root page {table_root_page}"
                                );
                                let pager_has_pending_writes = conn
                                    .active_txn
                                    .borrow()
                                    .as_ref()
                                    .is_some_and(|txn| txn.has_pending_writes());
                                assert!(
                                    pager_has_pending_writes,
                                    "UPDATE reported success but pager transaction has no pending writes"
                                );
                                let staged_payload = {
                                    let mut active_txn = conn.active_txn.borrow_mut();
                                    let txn = active_txn
                                        .as_mut()
                                        .expect("active pager transaction should remain available after UPDATE");
                                    let mut cursor = fsqlite_btree::BtCursor::new(
                                        fsqlite_btree::TransactionPageIo::new(txn),
                                        fsqlite_types::PageNumber::new(
                                            u32::try_from(table_root_page)
                                                .expect("root page should fit in u32"),
                                        )
                                        .expect("root page should be valid"),
                                        u32::try_from(fsqlite_types::PageSize::DEFAULT.as_usize())
                                            .expect("page size should fit in u32"),
                                        true,
                                    );
                                    let seek = cursor
                                        .table_move_to(&Cx::new(), 1)
                                        .await
                                        .expect("staged row lookup should succeed");
                                    assert!(
                                        seek.is_found(),
                                        "UPDATE reported success but staged rowid 1 is missing from table root page {table_root_page}"
                                    );
                                    cursor
                                        .payload(&Cx::new())
                                        .await
                                        .expect("staged row payload should be readable")
                                };
                                let staged_values = fsqlite_types::record::parse_record(
                                    &staged_payload,
                                )
                                .expect("staged row payload should decode as a SQLite record");
                                assert_eq!(
                                    staged_values.len(),
                                    2,
                                    "UPDATE staged unexpected payload width before COMMIT: values={staged_values:?}"
                                );
                                assert!(
                                    matches!(staged_values[0], SqliteValue::Null),
                                    "UPDATE staged unexpected IPK placeholder before COMMIT: values={staged_values:?}"
                                );
                                assert!(
                                    matches!(staged_values[1], SqliteValue::Integer(_)),
                                    "UPDATE staged non-integer payload before COMMIT: values={staged_values:?}"
                                );
                            }
                            Err(err) if err.is_transient() => {
                                retries += 1;
                                drop(conn.execute("ROLLBACK;").await);
                                continue;
                            }
                            Err(err) => {
                                let active_txn_row =
                                    describe_active_txn_row(&conn, table_root_page).await;
                                drop(conn.execute("ROLLBACK;").await);
                                let fresh_conn_state =
                                    describe_fresh_conn_state(&db, table_root_page).await;
                                let wal_len = std::fs::metadata(wal_path_for_db_path(&db))
                                    .ok()
                                    .map(|meta| meta.len());
                                let sqlite_state = {
                                    let sqlite = rusqlite::Connection::open(&db).unwrap();
                                    let typeof_v: String = sqlite
                                        .query_row(
                                            "SELECT typeof(v) FROM t WHERE id = 1;",
                                            [],
                                            |row| row.get(0),
                                        )
                                        .unwrap();
                                    let quote_v: String = sqlite
                                        .query_row(
                                            "SELECT quote(v) FROM t WHERE id = 1;",
                                            [],
                                            |row| row.get(0),
                                        )
                                        .unwrap();
                                    let value: rusqlite::types::Value = sqlite
                                        .query_row("SELECT v FROM t WHERE id = 1;", [], |row| {
                                            row.get(0)
                                        })
                                        .unwrap();
                                    format!(
                                        "typeof={typeof_v:?} quote={quote_v:?} value={value:?}"
                                    )
                                };
                                panic!(
                                    "non-transient update failure: {err}; active_txn_row={active_txn_row}; fresh_conn={fresh_conn_state}; sqlite={sqlite_state}; retries={retries}; wal_len={wal_len:?}"
                                )
                            }
                        }
                        match conn.execute("COMMIT;").await {
                            Ok(_) => break,
                            Err(err) if err.is_transient() => {
                                retries += 1;
                                drop(conn.execute("ROLLBACK;").await);
                            }
                            Err(err) => panic!("non-transient commit failure: {err}"),
                        }
                    }
                }
                retries_out = retries;
                });
                retries_out
            }));
            }

            let mut retries = 0_u64;
            for handle in handles {
                retries += handle.join().expect("worker should not panic");
            }

            async fn read_single_column_row_via_pager(
                conn: &Connection,
                table_root_page: i32,
            ) -> Option<Vec<SqliteValue>> {
                let cx = Cx::new();
                let mut txn = conn
                    .pager
                    .begin(&cx, fsqlite_pager::TransactionMode::ReadOnly)
                    .await
                    .unwrap();
                let mut cursor = fsqlite_btree::BtCursor::new(
                    fsqlite_btree::TransactionPageIo::new(&mut txn),
                    fsqlite_types::PageNumber::new(
                        u32::try_from(table_root_page).expect("root page should fit in u32"),
                    )
                    .expect("root page should be valid"),
                    u32::try_from(fsqlite_types::PageSize::DEFAULT.as_usize())
                        .expect("page size should fit in u32"),
                    true,
                );
                let seek = cursor.table_move_to(&cx, 1).await.unwrap();
                if !seek.is_found() {
                    return None;
                }
                let payload = cursor.payload(&cx).await.unwrap();
                Some(
                    fsqlite_types::record::parse_record(&payload)
                        .expect("pager-backed row payload should decode as a SQLite record"),
                )
            }

            let verifier = Connection::open(&db).await.unwrap();
            let row = verifier
                .query_row("SELECT v FROM t WHERE id = 1;")
                .await
                .unwrap();
            let final_cell = row.get(0).cloned().unwrap_or(SqliteValue::Null);
            let pager_values_before_close =
                read_single_column_row_via_pager(&verifier, table_root_page).await;
            let wal_path = wal_path_for_db_path(&db);
            let wal_len_before_close = std::fs::metadata(&wal_path).ok().map(|meta| meta.len());
            let (
                sqlite_journal_mode_before_close,
                sqlite_integrity_before_close,
                sqlite_typeof_before_close,
                sqlite_quote_before_close,
                sqlite_value_before_close,
            ) = {
                let sqlite = rusqlite::Connection::open(&db).unwrap();
                let journal_mode: String = sqlite
                    .query_row("PRAGMA journal_mode;", [], |row| row.get(0))
                    .unwrap();
                let integrity_check: String = sqlite
                    .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                    .unwrap();
                let typeof_v: String = sqlite
                    .query_row("SELECT typeof(v) FROM t WHERE id = 1;", [], |row| {
                        row.get(0)
                    })
                    .unwrap();
                let quote_v: String = sqlite
                    .query_row("SELECT quote(v) FROM t WHERE id = 1;", [], |row| row.get(0))
                    .unwrap();
                let value: rusqlite::types::Value = sqlite
                    .query_row("SELECT v FROM t WHERE id = 1;", [], |row| row.get(0))
                    .unwrap();
                (journal_mode, integrity_check, typeof_v, quote_v, value)
            };
            drop(verifier);
            let reopened = Connection::open(&db).await.unwrap();
            let pager_values_after_close =
                read_single_column_row_via_pager(&reopened, table_root_page).await;
            drop(reopened);
            let wal_len_after_close = std::fs::metadata(&wal_path).ok().map(|meta| meta.len());
            let (
                sqlite_journal_mode_after_close,
                sqlite_integrity_after_close,
                sqlite_typeof_after_close,
                sqlite_quote_after_close,
                sqlite_value_after_close,
            ) = {
                let sqlite = rusqlite::Connection::open(&db).unwrap();
                let journal_mode: String = sqlite
                    .query_row("PRAGMA journal_mode;", [], |row| row.get(0))
                    .unwrap();
                let integrity_check: String = sqlite
                    .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                    .unwrap();
                let typeof_v: String = sqlite
                    .query_row("SELECT typeof(v) FROM t WHERE id = 1;", [], |row| {
                        row.get(0)
                    })
                    .unwrap();
                let quote_v: String = sqlite
                    .query_row("SELECT quote(v) FROM t WHERE id = 1;", [], |row| row.get(0))
                    .unwrap();
                let value: rusqlite::types::Value = sqlite
                    .query_row("SELECT v FROM t WHERE id = 1;", [], |row| row.get(0))
                    .unwrap();
                (journal_mode, integrity_check, typeof_v, quote_v, value)
            };
            let expected = i64::try_from(WORKERS * TXNS_PER_WORKER).unwrap();
            assert_eq!(
                pager_values_before_close,
                Some(vec![SqliteValue::Null, SqliteValue::Integer(expected)]),
                "bd-rjc pager-backed mismatch before close: final_cell={final_cell:?} expected={expected} retries={retries} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert_eq!(
                pager_values_after_close,
                Some(vec![SqliteValue::Null, SqliteValue::Integer(expected)]),
                "bd-rjc pager-backed mismatch after close: final_cell={final_cell:?} expected={expected} retries={retries} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert!(
                matches!(final_cell, SqliteValue::Integer(_)),
                "bd-rjc verifier returned non-integer: final_cell={final_cell:?} expected={expected} retries={retries} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert_eq!(
                sqlite_value_before_close,
                rusqlite::types::Value::Integer(expected),
                "bd-rjc oracle mismatch before close: final_cell={final_cell:?} expected={expected} retries={retries} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert_eq!(
                sqlite_value_after_close,
                rusqlite::types::Value::Integer(expected),
                "bd-rjc oracle mismatch after close: final_cell={final_cell:?} expected={expected} retries={retries} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert_eq!(
                final_cell,
                SqliteValue::Integer(expected),
                "bd-rjc single-account probe mismatch: final_cell={final_cell:?} expected={expected} retries={retries} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
        });
    }

    #[test]
    fn test_explicit_concurrent_rounds_single_connection_preserve_increment_base_bd_rjc() {
        asupersync::test_utils::run_test(|| async {
            const TXNS: usize = 128;

            let dir = tempfile::tempdir().unwrap();
            let db_path = dir
                .path()
                .join("bd_rjc_explicit_concurrent_rounds_single_conn.db");
            let db = db_path.to_string_lossy().to_string();

            let conn = Connection::open(&db).await.unwrap();
            conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                .await
                .unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t (id, v) VALUES (1, 0);")
                .await
                .unwrap();

            for round in 0..TXNS {
                conn.execute("BEGIN CONCURRENT;").await.unwrap();
                assert_eq!(
                    conn.execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                        .await
                        .unwrap(),
                    1,
                    "explicit concurrent round {round} should affect exactly one row"
                );
                conn.execute("COMMIT;").await.unwrap();

                let expected = i64::try_from(round + 1).unwrap();
                let observed = conn
                    .query_row("SELECT v FROM t WHERE id = 1;")
                    .await
                    .unwrap()
                    .get(0)
                    .cloned();
                assert_eq!(
                    observed,
                    Some(SqliteValue::Integer(expected)),
                    "single-connection explicit concurrent rounds must advance monotonically after round {round}"
                );
            }
        });
    }

    #[test]
    fn test_explicit_concurrent_rounds_two_connections_without_overlap_preserve_increment_base_bd_rjc()
     {
        asupersync::test_utils::run_test(|| async {
            const ROUNDS_PER_CONN: usize = 96;

            let dir = tempfile::tempdir().unwrap();
            let db_path = dir
                .path()
                .join("bd_rjc_explicit_concurrent_rounds_two_conn_no_overlap.db");
            let db = db_path.to_string_lossy().to_string();

            let setup = Connection::open(&db).await.unwrap();
            setup.execute("PRAGMA busy_timeout=5000;").await.unwrap();
            setup
                .execute("PRAGMA fsqlite.concurrent_mode=ON;")
                .await
                .unwrap();
            setup
                .execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                .await
                .unwrap();
            setup
                .execute("INSERT INTO t (id, v) VALUES (1, 0);")
                .await
                .unwrap();
            drop(setup);

            let conn_a = Connection::open(&db).await.unwrap();
            let conn_b = Connection::open(&db).await.unwrap();
            for conn in [&conn_a, &conn_b] {
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
            }

            let mut committed = 0_i64;
            for round in 0..ROUNDS_PER_CONN {
                for (label, conn) in [("a", &conn_a), ("b", &conn_b)] {
                    conn.execute("BEGIN CONCURRENT;").await.unwrap();
                    assert_eq!(
                        conn.execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                            .await
                            .unwrap(),
                        1,
                        "connection {label} round {round} should affect exactly one row"
                    );
                    conn.execute("COMMIT;").await.unwrap();

                    committed += 1;
                    let observed = conn
                        .query_row("SELECT v FROM t WHERE id = 1;")
                        .await
                        .unwrap()
                        .get(0)
                        .cloned();
                    assert_eq!(
                        observed,
                        Some(SqliteValue::Integer(committed)),
                        "two long-lived connections without overlap must keep rebinding the latest committed row after connection {label} round {round}"
                    );
                }
            }
        });
    }

    #[test]
    fn test_sequential_single_account_increment_oracle_probe_bd_rjc() {
        asupersync::test_utils::run_test(|| async {
            const TXNS: usize = 640;

            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("bd_rjc_sequential_single_account_probe.db");
            let db = db_path.to_string_lossy().to_string();
            let table_root_page = {
                let conn = Connection::open(&db).await.unwrap();
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
                conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                    .await
                    .unwrap();
                let root_page = conn
                    .schema
                    .borrow()
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case("t"))
                    .map(|table| table.root_page)
                    .expect("table t should exist after CREATE TABLE");
                conn.execute("INSERT INTO t (id, v) VALUES (1, 0);")
                    .await
                    .unwrap();
                root_page
            };

            let conn = Connection::open(&db).await.unwrap();
            conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
            conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                .await
                .unwrap();
            let table_root_pgno = fsqlite_types::PageNumber::new(
                u32::try_from(table_root_page).expect("root page should fit in u32"),
            )
            .expect("root page should be valid");
            async fn read_single_column_row_via_pager(
                conn: &Connection,
                table_root_pgno: fsqlite_types::PageNumber,
            ) -> Option<Vec<SqliteValue>> {
                let cx = Cx::new();
                let mut txn = conn
                    .pager
                    .begin(&cx, fsqlite_pager::TransactionMode::ReadOnly)
                    .await
                    .unwrap();
                let mut cursor = fsqlite_btree::BtCursor::new(
                    fsqlite_btree::TransactionPageIo::new(&mut txn),
                    table_root_pgno,
                    u32::try_from(fsqlite_types::PageSize::DEFAULT.as_usize())
                        .expect("page size should fit in u32"),
                    true,
                );
                let seek = cursor.table_move_to(&cx, 1).await.unwrap();
                if !seek.is_found() {
                    return None;
                }
                let payload = cursor.payload(&cx).await.unwrap();
                Some(
                    fsqlite_types::record::parse_record(&payload)
                        .expect("pager-backed row payload should decode as a SQLite record"),
                )
            }
            fn hex_prefix(bytes: &[u8], limit: usize) -> String {
                bytes
                    .iter()
                    .take(limit)
                    .map(|byte| format!("{byte:02x}"))
                    .collect()
            }
            async fn describe_root_page_layout(
                conn: &Connection,
                table_root_pgno: fsqlite_types::PageNumber,
            ) -> String {
                let cx = Cx::new();
                let txn = conn
                    .pager
                    .begin(&cx, fsqlite_pager::TransactionMode::ReadOnly)
                    .await
                    .unwrap();
                let page_data = txn.get_page(&cx, table_root_pgno).await.unwrap();
                let page = page_data.as_bytes();
                let header_offset = fsqlite_btree::header_offset_for_page(table_root_pgno);
                let header = match fsqlite_btree::BtreePageHeader::parse(page, header_offset) {
                    Ok(header) => header,
                    Err(err) => {
                        return format!("header_err={err} page_prefix={}", hex_prefix(page, 96));
                    }
                };
                let cell_pointers =
                    match fsqlite_btree::read_cell_pointers(page, &header, header_offset) {
                        Ok(pointers) => pointers,
                        Err(err) => {
                            return format!(
                                "header={header:?} ptr_err={err} page_prefix={}",
                                hex_prefix(page, 96)
                            );
                        }
                    };
                let usable_size =
                    u32::try_from(page.len()).expect("page length should fit into u32 for tests");
                let content_offset = header.content_offset(usable_size);
                let content_prefix = if content_offset < page.len() {
                    hex_prefix(&page[content_offset..], 96)
                } else {
                    "content_offset_at_end".to_owned()
                };
                let cells = cell_pointers
                .iter()
                .enumerate()
                .map(|(idx, &ptr)| {
                    let cell_offset = usize::from(ptr);
                    let raw_cell_prefix = if cell_offset < page.len() {
                        hex_prefix(&page[cell_offset..], 64)
                    } else {
                        "ptr_out_of_bounds".to_owned()
                    };
                    match fsqlite_btree::CellRef::parse(
                        page,
                        cell_offset,
                        header.page_type,
                        usable_size,
                    ) {
                        Ok(cell) => {
                            let on_page_size = fsqlite_btree::payload::cell_on_page_size(
                                &cell,
                                cell_offset,
                            );
                            let cell_end = cell_offset.saturating_add(on_page_size).min(page.len());
                            let cell_hex = hex_prefix(&page[cell_offset..cell_end], 96);
                            let payload = cell.local_payload(page);
                            let payload_values = fsqlite_types::record::parse_record(payload);
                            format!(
                                "idx={idx} ptr={ptr} rowid={:?} payload_size={} local_size={} payload_offset={} overflow={:?} payload_values={payload_values:?} raw_cell_prefix={} cell_hex={}",
                                cell.rowid,
                                cell.payload_size,
                                cell.local_size,
                                cell.payload_offset,
                                cell.overflow_page,
                                raw_cell_prefix,
                                cell_hex
                            )
                        }
                        Err(err) => {
                            format!(
                                "idx={idx} ptr={ptr} parse_err={err} raw_cell_prefix={raw_cell_prefix}"
                            )
                        }
                    }
                })
                .collect::<Vec<_>>()
                .join(" | ");
                format!(
                    "header={header:?} cell_pointers={cell_pointers:?} page_prefix={} content_prefix={} cells=[{}]",
                    hex_prefix(page, 96),
                    content_prefix,
                    cells
                )
            }
            for step in 0..TXNS {
                let query_before_step = conn
                    .query_row("SELECT v FROM t WHERE id = 1;")
                    .await
                    .ok()
                    .and_then(|row| row.get(0).cloned());
                let pager_before_step =
                    read_single_column_row_via_pager(&conn, table_root_pgno).await;
                match conn.execute("UPDATE t SET v = v + 1 WHERE id = 1;").await {
                    Ok(changes) => {
                        assert_eq!(changes, 1, "expected one-row sequential update");
                        if step == 0 {
                            let query_after_first_step = conn
                                .query_row("SELECT v FROM t WHERE id = 1;")
                                .await
                                .ok()
                                .and_then(|row| row.get(0).cloned());
                            let pager_after_first_step =
                                read_single_column_row_via_pager(&conn, table_root_pgno).await;
                            let sqlite_after_first_step = {
                                let sqlite = rusqlite::Connection::open(&db).unwrap();
                                let typeof_v: String = sqlite
                                    .query_row("SELECT typeof(v) FROM t WHERE id = 1;", [], |row| {
                                        row.get(0)
                                    })
                                    .unwrap();
                                let quote_v: String = sqlite
                                    .query_row("SELECT quote(v) FROM t WHERE id = 1;", [], |row| {
                                        row.get(0)
                                    })
                                    .unwrap();
                                let value: rusqlite::types::Value = sqlite
                                    .query_row("SELECT v FROM t WHERE id = 1;", [], |row| {
                                        row.get(0)
                                    })
                                    .unwrap();
                                (typeof_v, quote_v, value)
                            };
                            let root_page_layout_after_first_step =
                                describe_root_page_layout(&conn, table_root_pgno).await;
                            assert_eq!(
                                query_after_first_step,
                                Some(SqliteValue::Integer(1)),
                                "bd-rjc first sequential update corrupted SQL view: pager_after_first_step={pager_after_first_step:?} sqlite_after_first_step={sqlite_after_first_step:?} root_page_layout_after_first_step={root_page_layout_after_first_step}"
                            );
                            assert_eq!(
                                pager_after_first_step,
                                Some(vec![SqliteValue::Null, SqliteValue::Integer(1)]),
                                "bd-rjc first sequential update corrupted pager view: query_after_first_step={query_after_first_step:?} sqlite_after_first_step={sqlite_after_first_step:?} root_page_layout_after_first_step={root_page_layout_after_first_step}"
                            );
                            assert_eq!(
                                sqlite_after_first_step.2,
                                rusqlite::types::Value::Integer(1),
                                "bd-rjc first sequential update corrupted SQLite view: query_after_first_step={query_after_first_step:?} pager_after_first_step={pager_after_first_step:?} sqlite_after_first_step={sqlite_after_first_step:?} root_page_layout_after_first_step={root_page_layout_after_first_step}"
                            );
                        }
                    }
                    Err(err) => {
                        let sqlite_before_step = {
                            let sqlite = rusqlite::Connection::open(&db).unwrap();
                            let typeof_v: String = sqlite
                                .query_row("SELECT typeof(v) FROM t WHERE id = 1;", [], |row| {
                                    row.get(0)
                                })
                                .unwrap();
                            let quote_v: String = sqlite
                                .query_row("SELECT quote(v) FROM t WHERE id = 1;", [], |row| {
                                    row.get(0)
                                })
                                .unwrap();
                            let value: rusqlite::types::Value = sqlite
                                .query_row("SELECT v FROM t WHERE id = 1;", [], |row| row.get(0))
                                .unwrap();
                            (typeof_v, quote_v, value)
                        };
                        let root_page_layout_before_step =
                            describe_root_page_layout(&conn, table_root_pgno).await;
                        panic!(
                            "bd-rjc sequential update failed: step={step} query_before_step={query_before_step:?} pager_before_step={pager_before_step:?} sqlite_before_step={sqlite_before_step:?} root_page_layout_before_step={root_page_layout_before_step} err={err}"
                        );
                    }
                }
            }
            drop(conn);

            let verifier = Connection::open(&db).await.unwrap();
            let row = verifier
                .query_row("SELECT v FROM t WHERE id = 1;")
                .await
                .unwrap();
            let final_cell = row.get(0).cloned().unwrap_or(SqliteValue::Null);
            let pager_values_before_close =
                read_single_column_row_via_pager(&verifier, table_root_pgno).await;
            let wal_path = wal_path_for_db_path(&db);
            let wal_len_before_close = std::fs::metadata(&wal_path).ok().map(|meta| meta.len());
            let (
                sqlite_journal_mode_before_close,
                sqlite_integrity_before_close,
                sqlite_typeof_before_close,
                sqlite_quote_before_close,
                sqlite_value_before_close,
            ) = {
                let sqlite = rusqlite::Connection::open(&db).unwrap();
                let journal_mode: String = sqlite
                    .query_row("PRAGMA journal_mode;", [], |row| row.get(0))
                    .unwrap();
                let integrity_check: String = sqlite
                    .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                    .unwrap();
                let typeof_v: String = sqlite
                    .query_row("SELECT typeof(v) FROM t WHERE id = 1;", [], |row| {
                        row.get(0)
                    })
                    .unwrap();
                let quote_v: String = sqlite
                    .query_row("SELECT quote(v) FROM t WHERE id = 1;", [], |row| row.get(0))
                    .unwrap();
                let value: rusqlite::types::Value = sqlite
                    .query_row("SELECT v FROM t WHERE id = 1;", [], |row| row.get(0))
                    .unwrap();
                (journal_mode, integrity_check, typeof_v, quote_v, value)
            };
            drop(verifier);
            let reopened = Connection::open(&db).await.unwrap();
            let pager_values_after_close =
                read_single_column_row_via_pager(&reopened, table_root_pgno).await;
            drop(reopened);
            let wal_len_after_close = std::fs::metadata(&wal_path).ok().map(|meta| meta.len());
            let (
                sqlite_journal_mode_after_close,
                sqlite_integrity_after_close,
                sqlite_typeof_after_close,
                sqlite_quote_after_close,
                sqlite_value_after_close,
            ) = {
                let sqlite = rusqlite::Connection::open(&db).unwrap();
                let journal_mode: String = sqlite
                    .query_row("PRAGMA journal_mode;", [], |row| row.get(0))
                    .unwrap();
                let integrity_check: String = sqlite
                    .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                    .unwrap();
                let typeof_v: String = sqlite
                    .query_row("SELECT typeof(v) FROM t WHERE id = 1;", [], |row| {
                        row.get(0)
                    })
                    .unwrap();
                let quote_v: String = sqlite
                    .query_row("SELECT quote(v) FROM t WHERE id = 1;", [], |row| row.get(0))
                    .unwrap();
                let value: rusqlite::types::Value = sqlite
                    .query_row("SELECT v FROM t WHERE id = 1;", [], |row| row.get(0))
                    .unwrap();
                (journal_mode, integrity_check, typeof_v, quote_v, value)
            };
            let expected = i64::try_from(TXNS).unwrap();
            assert_eq!(
                pager_values_before_close,
                Some(vec![SqliteValue::Null, SqliteValue::Integer(expected)]),
                "bd-rjc sequential pager-backed mismatch before close: final_cell={final_cell:?} expected={expected} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert_eq!(
                pager_values_after_close,
                Some(vec![SqliteValue::Null, SqliteValue::Integer(expected)]),
                "bd-rjc sequential pager-backed mismatch after close: final_cell={final_cell:?} expected={expected} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert_eq!(
                sqlite_value_before_close,
                rusqlite::types::Value::Integer(expected),
                "bd-rjc sequential oracle mismatch before close: final_cell={final_cell:?} expected={expected} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert_eq!(
                sqlite_value_after_close,
                rusqlite::types::Value::Integer(expected),
                "bd-rjc sequential oracle mismatch after close: final_cell={final_cell:?} expected={expected} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
            assert_eq!(
                final_cell,
                SqliteValue::Integer(expected),
                "bd-rjc sequential single-account probe mismatch: final_cell={final_cell:?} expected={expected} pager_before={pager_values_before_close:?} pager_after={pager_values_after_close:?} wal_len_before_close={wal_len_before_close:?} wal_len_after_close={wal_len_after_close:?} sqlite_before=(journal_mode={sqlite_journal_mode_before_close:?}, integrity={sqlite_integrity_before_close:?}, typeof={sqlite_typeof_before_close:?}, quote={sqlite_quote_before_close:?}, value={sqlite_value_before_close:?}) sqlite_after=(journal_mode={sqlite_journal_mode_after_close:?}, integrity={sqlite_integrity_after_close:?}, typeof={sqlite_typeof_after_close:?}, quote={sqlite_quote_after_close:?}, value={sqlite_value_after_close:?})"
            );
        });
    }

