    #[test]
    fn test_pragma_utf16_setters_fail_closed_without_mutating_database_state() {
        asupersync::test_utils::run_test(|| async {
            for schema_initialized in [false, true] {
                let conn = Connection::open(":memory:").await.unwrap();
                if schema_initialized {
                    conn.execute(
                        "CREATE TABLE encoding_guard_t(\
                             id INTEGER PRIMARY KEY,\
                             note TEXT DEFAULT 'café'\
                         );",
                    )
                    .await
                    .unwrap();
                }

                let before_image = conn.export_bytes().await.unwrap();
                let before_schema = conn
                    .query("SELECT type, name, sql FROM sqlite_schema ORDER BY type, name;")
                    .await
                    .unwrap();
                let before_attached_schemas = conn.attached_schemas.borrow().count();
                let before_attached_connections = conn.attached_connections.borrow().len();

                for requested in ["UTF-16", "UTF-16le", "UTF-16be"] {
                    for sql in [
                        format!("PRAGMA encoding = '{requested}';"),
                        format!("PRAGMA encoding('{requested}');"),
                    ] {
                        let err = conn
                            .execute(&sql)
                            .await
                            .expect_err("UTF-16 encoding setter must fail closed");
                        assert!(
                            matches!(err, FrankenError::Unsupported),
                            "unexpected {requested} setter error for {sql}: {err:?}"
                        );
                    }

                    let rows = conn.query("PRAGMA encoding;").await.unwrap();
                    assert_eq!(
                        rows[0].values()[0],
                        SqliteValue::Text("UTF-8".into()),
                        "rejected {requested} setter must retain UTF-8"
                    );
                    assert_eq!(conn.export_bytes().await.unwrap(), before_image);
                    assert_eq!(
                        conn.query(
                            "SELECT type, name, sql FROM sqlite_schema ORDER BY type, name;"
                        )
                        .await
                        .unwrap(),
                        before_schema
                    );
                    assert_eq!(
                        conn.attached_schemas.borrow().count(),
                        before_attached_schemas
                    );
                    assert_eq!(
                        conn.attached_connections.borrow().len(),
                        before_attached_connections
                    );
                }
            }
        });
    }

    #[test]
    fn test_pragma_extended_connection_knobs_return_rows() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            let defaults = [
                ("PRAGMA temp_store;", 0_i64),
                ("PRAGMA mmap_size;", 0_i64),
                ("PRAGMA auto_vacuum;", 0_i64),
                ("PRAGMA wal_autocheckpoint;", 1000_i64),
                ("PRAGMA user_version;", 0_i64),
                ("PRAGMA application_id;", 0_i64),
                ("PRAGMA foreign_keys;", 0_i64),
                ("PRAGMA recursive_triggers;", 0_i64),
            ];
            for (sql, expected) in defaults {
                let rows = conn.query(sql).await.unwrap();
                assert_eq!(rows.len(), 1, "{sql} should return one row");
                assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Integer(expected));
            }

            conn.execute("PRAGMA temp_store=MEMORY;").await.unwrap();
            conn.execute("PRAGMA mmap_size=8192;").await.unwrap();
            conn.execute("PRAGMA auto_vacuum=INCREMENTAL;")
                .await
                .unwrap();
            conn.execute("PRAGMA wal_autocheckpoint=0;").await.unwrap();
            conn.execute("PRAGMA user_version=123;").await.unwrap();
            conn.execute("PRAGMA application_id=456;").await.unwrap();
            conn.execute("PRAGMA foreign_keys=ON;").await.unwrap();
            conn.execute("PRAGMA recursive_triggers=ON;").await.unwrap();

            let updated = [
                ("PRAGMA temp_store;", 2_i64),
                ("PRAGMA mmap_size;", 8192_i64),
                ("PRAGMA auto_vacuum;", 2_i64),
                ("PRAGMA wal_autocheckpoint;", 0_i64),
                ("PRAGMA user_version;", 123_i64),
                ("PRAGMA application_id;", 456_i64),
                ("PRAGMA foreign_keys;", 1_i64),
                ("PRAGMA recursive_triggers;", 1_i64),
            ];
            for (sql, expected) in updated {
                let rows = conn.query(sql).await.unwrap();
                assert_eq!(rows.len(), 1, "{sql} should return one row");
                assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Integer(expected));
            }
        });
    }

    #[test]
    fn test_explicit_txn_fk_violation_rolls_back_only_the_statement() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys=ON;").await.unwrap();
            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE child (parent_id INTEGER REFERENCES parent(id));")
                .await
                .unwrap();

            conn.execute("BEGIN;").await.unwrap();
            let err = conn
                .execute("INSERT INTO child VALUES (42);")
                .await
                .expect_err("INSERT should fail due to missing parent row");
            assert!(matches!(err, FrankenError::ForeignKeyViolation));
            assert!(
                conn.in_transaction(),
                "FK failure should not abort transaction"
            );

            let rows = conn.query("SELECT COUNT(*) FROM child;").await.unwrap();
            assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Integer(0));

            conn.execute("INSERT INTO parent VALUES (42);")
                .await
                .unwrap();
            conn.execute("INSERT INTO child VALUES (42);")
                .await
                .unwrap();
            conn.execute("COMMIT;").await.unwrap();

            let rows = conn.query("SELECT COUNT(*) FROM child;").await.unwrap();
            assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Integer(1));
        });
    }

    // ── Issue #110: transaction-scoped FK parent-validation cache ──────────

    /// Repeated parent ids across many prepared INSERTs in one transaction
    /// must succeed (the cache short-circuits redundant probes) and still see
    /// parents inserted earlier in the same transaction.
    #[test]
    fn test_issue110_fk_parent_cache_repeated_parent_inserts() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys=ON;").await.unwrap();
            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute(
            "CREATE TABLE child (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES parent(id));",
        ).await
        .unwrap();

            conn.execute("BEGIN;").await.unwrap();
            conn.execute("INSERT INTO parent VALUES (1);")
                .await
                .unwrap();
            let stmt = conn
                .prepare("INSERT INTO child (id, parent_id) VALUES (?1, ?2)")
                .await
                .unwrap();
            for i in 1..=200i64 {
                // Every child references parent id=1; only the first probe should
                // actually query, the rest are cache hits.
                conn.execute_prepared_with_params(
                    &stmt,
                    &[SqliteValue::Integer(i), SqliteValue::Integer(1)],
                )
                .await
                .unwrap();
            }
            // A child referencing a non-existent parent must still fail even though
            // a different parent id is cached.
            let err = conn
                .execute_prepared_with_params(
                    &stmt,
                    &[SqliteValue::Integer(999), SqliteValue::Integer(7)],
                )
                .await
                .expect_err("missing parent must fail");
            assert!(matches!(err, FrankenError::ForeignKeyViolation));
            conn.execute("COMMIT;").await.unwrap();

            let rows = conn.query("SELECT COUNT(*) FROM child;").await.unwrap();
            assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Integer(200));
        });
    }

    /// Deleting a parent inside the same transaction after it was validated
    /// and cached must invalidate the cache so a later child INSERT referencing
    /// the now-deleted parent fails.
    #[test]
    fn test_issue110_fk_parent_cache_invalidated_by_delete() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys=ON;").await.unwrap();
            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute(
            "CREATE TABLE child (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES parent(id));",
        ).await
        .unwrap();
            conn.execute("INSERT INTO parent VALUES (1);")
                .await
                .unwrap();

            conn.execute("BEGIN;").await.unwrap();
            // First child validates and caches parent id=1.
            conn.execute("INSERT INTO child VALUES (10, 1);")
                .await
                .unwrap();
            // Remove the child, then the parent, within the same transaction.
            // (Deleting the parent while a child references it would itself be an
            // FK violation — that is separately correct SQLite behavior.)
            conn.execute("DELETE FROM child WHERE id = 10;")
                .await
                .unwrap();
            conn.execute("DELETE FROM parent WHERE id = 1;")
                .await
                .unwrap();
            // A subsequent child referencing id=1 must NOT be accepted from cache.
            let err = conn
                .execute("INSERT INTO child VALUES (11, 1);")
                .await
                .expect_err("parent was deleted this txn — cache must be invalidated");
            assert!(matches!(err, FrankenError::ForeignKeyViolation));
            conn.execute("ROLLBACK;").await.unwrap();
        });
    }

    /// `INSERT OR REPLACE` that deletes a conflicting parent row (via a UNIQUE
    /// constraint) must invalidate a previously cached parent value.
    #[test]
    fn test_issue110_fk_parent_cache_invalidated_by_insert_or_replace() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys=ON;").await.unwrap();
            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY, tag TEXT UNIQUE);")
                .await
                .unwrap();
            conn.execute(
            // ON DELETE SET NULL: stock SQLite (verified vs C SQLite 3.46.1)
            // rejects the INSERT OR REPLACE below because it deletes the
            // referenced parent id=1, orphaning child id=10 ("FOREIGN KEY
            // constraint failed"). The anchor b612eb7b5 let that REPLACE
            // succeed (SQLite-divergent); SET NULL keeps the scenario valid
            // while still exercising parent-cache invalidation on the later
            // child insert that references the now-deleted id=1.
            "CREATE TABLE child (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES parent(id) ON DELETE SET NULL);",
        ).await
        .unwrap();
            conn.execute("INSERT INTO parent VALUES (1, 'a');")
                .await
                .unwrap();

            conn.execute("BEGIN;").await.unwrap();
            // Validate + cache parent id=1.
            conn.execute("INSERT INTO child VALUES (10, 1);")
                .await
                .unwrap();
            // REPLACE on the UNIQUE tag deletes the row with id=1 and inserts id=2,
            // so parent id=1 no longer exists.
            conn.execute("INSERT OR REPLACE INTO parent VALUES (2, 'a');")
                .await
                .unwrap();
            let err = conn
                .execute("INSERT INTO child VALUES (11, 1);")
                .await
                .expect_err("REPLACE deleted parent id=1 — cache must be invalidated");
            assert!(matches!(err, FrankenError::ForeignKeyViolation));
            conn.execute("ROLLBACK;").await.unwrap();
        });
    }

    /// ROLLBACK TO SAVEPOINT can roll away a parent inserted (and cached) after
    /// the savepoint; a later child INSERT referencing it must re-probe and
    /// fail.
    #[test]
    fn test_issue110_fk_parent_cache_invalidated_by_savepoint_rollback() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys=ON;").await.unwrap();
            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute(
            "CREATE TABLE child (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES parent(id));",
        ).await
        .unwrap();

            conn.execute("BEGIN;").await.unwrap();
            conn.execute("SAVEPOINT sp;").await.unwrap();
            conn.execute("INSERT INTO parent VALUES (5);")
                .await
                .unwrap();
            // Validate + cache parent id=5 (it exists right now).
            conn.execute("INSERT INTO child VALUES (50, 5);")
                .await
                .unwrap();
            // Roll the savepoint back: parent id=5 AND child id=50 are gone.
            conn.execute("ROLLBACK TO sp;").await.unwrap();
            // Referencing id=5 again must re-probe and fail (parent rolled away).
            let err = conn
                .execute("INSERT INTO child VALUES (51, 5);")
                .await
                .expect_err("savepoint rollback removed parent id=5 — cache must be invalidated");
            assert!(matches!(err, FrankenError::ForeignKeyViolation));
            conn.execute("ROLLBACK;").await.unwrap();

            let rows = conn.query("SELECT COUNT(*) FROM child;").await.unwrap();
            assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Integer(0));
        });
    }

    /// The cache must not leak across transactions: a parent validated in one
    /// transaction that is then deleted (in a later committed transaction)
    /// must not be accepted from a stale cache entry.
    #[test]
    fn test_issue110_fk_parent_cache_does_not_leak_across_transactions() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys=ON;").await.unwrap();
            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute(
            "CREATE TABLE child (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES parent(id));",
        ).await
        .unwrap();
            conn.execute("INSERT INTO parent VALUES (1);")
                .await
                .unwrap();

            conn.execute("BEGIN;").await.unwrap();
            conn.execute("INSERT INTO child VALUES (10, 1);")
                .await
                .unwrap();
            conn.execute("COMMIT;").await.unwrap();

            // Separate transaction deletes the parent (and its children first).
            conn.execute("DELETE FROM child;").await.unwrap();
            conn.execute("DELETE FROM parent WHERE id = 1;")
                .await
                .unwrap();

            conn.execute("BEGIN;").await.unwrap();
            let err = conn
                .execute("INSERT INTO child VALUES (11, 1);")
                .await
                .expect_err("parent id=1 was deleted — no stale cross-txn cache hit");
            assert!(matches!(err, FrankenError::ForeignKeyViolation));
            conn.execute("ROLLBACK;").await.unwrap();
        });
    }

