    #[test]
    fn test_pragma_journal_mode_set_and_query() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("journal_mode_set_and_query.db");
            let conn = Connection::open(db_path.to_str().unwrap()).await.unwrap();
            // Set returns the new value (quoted to avoid keyword clash with parser).
            let rows = conn.query("PRAGMA journal_mode='truncate';").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(
                *rows[0].get(0).unwrap(),
                SqliteValue::Text("truncate".into())
            );
            // Query reads back.
            let rows = conn.query("PRAGMA journal_mode;").await.unwrap();
            assert_eq!(
                *rows[0].get(0).unwrap(),
                SqliteValue::Text("truncate".into())
            );
            assert_eq!(
                conn.pager.journal_mode(),
                fsqlite_pager::JournalMode::Delete
            );

            // Pager mode should switch to WAL when requested.
            let rows = conn.query("PRAGMA journal_mode='wal';").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Text("wal".into()));
            assert_eq!(conn.pager.journal_mode(), fsqlite_pager::JournalMode::Wal);
        });
    }

