            let rows = conn.query("PRAGMA journal_mode='off';").await.unwrap();
            assert_eq!(*rows[0].get(0).unwrap(), SqliteValue::Text("off".into()));
            assert_eq!(conn.pragma_state().journal_mode, "off");
