    #[test]
    fn test_correlated_subquery_detection_and_substitution_share_nested_scopes() {
        let parse_select = |sql: &str| {
            let Statement::Select(select) = parse_single_statement(sql).unwrap() else {
                panic!("expected SELECT for `{sql}`");
            };
            select
        };
        let outer_row = [SqliteValue::Integer(7)];
        let outer_col_map = [("outer_t".to_owned(), "v".to_owned(), false)];

        for sql in [
            "WITH c AS (SELECT outer_t.v) SELECT * FROM c;",
            "SELECT 1 FROM inner_a UNION ALL SELECT outer_t.v FROM inner_b;",
            "SELECT (SELECT outer_t.v) FROM inner_t;",
            "SELECT EXISTS(SELECT 1 WHERE outer_t.v = 7) FROM inner_t;",
            "SELECT 1 IN (SELECT outer_t.v) FROM inner_t;",
            "SELECT * FROM (SELECT outer_t.v) AS nested;",
        ] {
            let mut select = parse_select(sql);
            assert!(
                is_correlated_subquery(&select),
                "external reference was not detected in `{sql}`"
            );
            substitute_outer_refs_in_select(&mut select, &outer_row, &outer_col_map, None, &[]);
            assert!(
                !is_correlated_subquery(&select),
                "external reference was not substituted in `{sql}`"
            );
        }

        for sql in [
            "SELECT 1 AS x WHERE x = 1 GROUP BY x HAVING x = 1;",
            "SELECT 1 AS x ORDER BY x;",
            "SELECT inner_a.v FROM inner_a UNION ALL SELECT inner_b.v FROM inner_b;",
            "SELECT EXISTS(SELECT inner_t.v) FROM inner_t;",
        ] {
            let select = parse_select(sql);
            assert!(
                !is_correlated_subquery(&select),
                "local reference was misclassified as external in `{sql}`"
            );
        }
    }

    #[test]
    fn test_correlated_unqualified_column_resolves_outward_only_when_inner_source_lacks_it() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE outer_t (outer_only INTEGER);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE inner_without (inner_only INTEGER);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE inner_with (inner_only INTEGER, outer_only INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO outer_t VALUES (7);")
                .await
                .unwrap();
            conn.execute("INSERT INTO inner_without VALUES (1);")
                .await
                .unwrap();
            conn.execute("INSERT INTO inner_with VALUES (1, 8);")
                .await
                .unwrap();

            let outward = conn
                .query(
                    "SELECT EXISTS(SELECT 1 FROM inner_without \
                     WHERE outer_only = outer_t.outer_only) FROM outer_t;",
                )
                .await
                .unwrap();
            assert_eq!(outward[0].values(), &[SqliteValue::Integer(1)]);

            let fully_unqualified = conn
                .query(
                    "SELECT (SELECT outer_only FROM inner_without LIMIT 1) \
                     FROM outer_t;",
                )
                .await
                .unwrap();
            assert_eq!(fully_unqualified[0].values(), &[SqliteValue::Integer(7)]);

            let shadowed = conn
                .query(
                    "SELECT EXISTS(SELECT 1 FROM inner_with \
                     WHERE outer_only = outer_t.outer_only) FROM outer_t;",
                )
                .await
                .unwrap();
            assert_eq!(shadowed[0].values(), &[SqliteValue::Integer(0)]);

            for sql in [
                "SELECT (SELECT inner_only FROM inner_without \
                 ORDER BY outer_t.outer_only LIMIT 1) FROM outer_t;",
                "SELECT (SELECT inner_only FROM inner_without \
                 LIMIT outer_t.outer_only) FROM outer_t;",
                "SELECT (SELECT count(*) FROM inner_without \
                 GROUP BY outer_t.outer_only) FROM outer_t;",
            ] {
                let error = conn
                    .query(sql)
                    .await
                    .expect_err("outer references are not visible in ORDER BY/LIMIT/GROUP BY");
                assert!(
                    error.to_string().contains("outer_only"),
                    "unexpected error for `{sql}`: {error}"
                );
            }

            conn.execute("CREATE TABLE outer_alias (q INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO outer_alias VALUES (11);")
                .await
                .unwrap();
            let grouped_alias = conn
                .query(
                    "SELECT (SELECT outer_alias.q AS q FROM inner_without GROUP BY q) \
                     FROM outer_alias;",
                )
                .await
                .unwrap();
            assert_eq!(grouped_alias[0].values(), &[SqliteValue::Integer(11)]);
            let self_alias = conn
                .query("SELECT (SELECT outer_alias.q AS q) FROM outer_alias;")
                .await
                .unwrap();
            assert_eq!(self_alias[0].values(), &[SqliteValue::Integer(11)]);
            let where_alias = conn
                .query(
                    "SELECT (SELECT outer_alias.q + 1 AS q \
                     FROM inner_without WHERE q = 12) FROM outer_alias;",
                )
                .await
                .unwrap();
            assert_eq!(where_alias[0].values(), &[SqliteValue::Integer(12)]);

            conn.execute("CREATE TABLE inner_alias_precedence (q INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO inner_alias_precedence VALUES (99);")
                .await
                .unwrap();
            let inner_wins = conn
                .query(
                    "SELECT (SELECT outer_alias.q + 1 AS q \
                     FROM inner_alias_precedence WHERE q = 99) FROM outer_alias;",
                )
                .await
                .unwrap();
            assert_eq!(inner_wins[0].values(), &[SqliteValue::Integer(12)]);

            conn.execute("CREATE TABLE shadowed_scope (main_only INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO shadowed_scope VALUES (8);")
                .await
                .unwrap();
            conn.execute("CREATE TEMP TABLE shadowed_scope (temp_only INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO temp.shadowed_scope VALUES (7);")
                .await
                .unwrap();
            let explicit_main = conn
                .query(
                    "SELECT EXISTS(SELECT 1 FROM main.shadowed_scope \
                     WHERE main_only = outer_t.outer_only) FROM outer_t;",
                )
                .await
                .unwrap();
            assert_eq!(explicit_main[0].values(), &[SqliteValue::Integer(0)]);

            let qualified_scope_outer_fallback = conn
                .query(
                    "SELECT \
                         (SELECT outer_only FROM main.shadowed_scope LIMIT 1), \
                         (SELECT outer_only FROM temp.shadowed_scope LIMIT 1), \
                         (SELECT main_only FROM main.shadowed_scope LIMIT 1), \
                         (SELECT temp_only FROM temp.shadowed_scope LIMIT 1) \
                     FROM outer_t;",
                )
                .await
                .expect("explicit main/TEMP sources must still resolve missing bare names outward");
            assert_eq!(
                qualified_scope_outer_fallback[0].values(),
                &[
                    SqliteValue::Integer(7),
                    SqliteValue::Integer(7),
                    SqliteValue::Integer(8),
                    SqliteValue::Integer(7),
                ],
                "schema-aware substitution must distinguish the shadowed main and TEMP inventories"
            );
        });
    }

    #[test]
    fn test_outer_substitution_uses_join_using_coalesced_value() {
        let parse_select = || {
            let Statement::Select(select) = parse_single_statement("SELECT x;").unwrap() else {
                panic!("expected SELECT");
            };
            select
        };
        let outer_row = [SqliteValue::Null, SqliteValue::Integer(9)];
        let outer_col_map = [
            ("left_t".to_owned(), "x".to_owned(), false),
            ("right_t".to_owned(), "x".to_owned(), false),
        ];
        let using_skip = HashSet::from([1_usize]);

        let mut coalesced = parse_select();
        substitute_outer_refs_in_select(
            &mut coalesced,
            &outer_row,
            &outer_col_map,
            Some(&using_skip),
            &[],
        );
        let SelectCore::Select { columns, .. } = &coalesced.body.select else {
            panic!("expected SELECT core");
        };
        assert!(matches!(
            columns.as_slice(),
            [ResultColumn::Expr {
                expr: Expr::Literal(Literal::Integer(9), _),
                ..
            }]
        ));

        let mut ambiguous = parse_select();
        substitute_outer_refs_in_select(&mut ambiguous, &outer_row, &outer_col_map, None, &[]);
        assert!(
            is_correlated_subquery(&ambiguous),
            "a non-USING duplicate must remain ambiguous instead of choosing a side"
        );
    }

