    #[test]
    fn test_helper_wal_crash_writer_subprocess() {
        asupersync::test_utils::run_test(|| async {
            let Ok(db_path) = std::env::var("FSQLITE_PHASE5_CRASH_DB") else {
                return;
            };

            let conn = Connection::open(&db_path)
                .await
                .expect("helper should open crash database path");
            conn.execute("PRAGMA synchronous=FULL;")
                .await
                .expect("helper should force WAL durability before crash");
            conn.execute("PRAGMA wal_autocheckpoint=0;")
                .await
                .expect("helper should disable autocheckpoint");
            let journal_mode_rows = conn
                .query("PRAGMA journal_mode=WAL;")
                .await
                .expect("helper should enable WAL mode");
            assert_eq!(journal_mode_rows.len(), 1);
            assert_eq!(
                journal_mode_rows[0].get(0).unwrap(),
                &SqliteValue::Text("wal".into())
            );
            conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY, v TEXT NOT NULL);")
                .await
                .expect("helper should create table");
            conn.execute("INSERT INTO t(v) VALUES ('alpha');")
                .await
                .expect("helper should insert committed row");

            // Simulate a process crash: exit the subprocess without running
            // Connection::drop, which would otherwise checkpoint the WAL.
            std::process::exit(0);
        });
    }

    #[test]
    fn test_reopen_recovers_wal_after_subprocess_crash_and_checkpoint_persists_main_db() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("wal_crash_recovery_roundtrip.db");
            let db_str = db_path.to_string_lossy().into_owned();
            let wal_path = std::path::PathBuf::from(format!("{db_str}-wal"));
            let helper_name = "test_helper_wal_crash_writer_subprocess";

            let status = std::process::Command::new(
                std::env::current_exe().expect("test binary path should be available"),
            )
            .arg(helper_name)
            .arg("--nocapture")
            .env("FSQLITE_PHASE5_CRASH_DB", &db_str)
            .status()
            .expect("helper subprocess should launch");
            assert!(
                status.success(),
                "helper subprocess should exit cleanly after simulating a crash: {status}"
            );
            assert!(
                wal_path.exists(),
                "crash simulation should leave a WAL sidecar for recovery"
            );
            assert_eq!(
                std::fs::metadata(&db_path).unwrap().len(),
                u64::from(PageSize::DEFAULT.get()),
                "main database should still be the one-page bootstrap image before checkpoint"
            );

            let conn = Connection::open(&db_str)
                .await
                .expect("reopen should recover the committed state from the WAL");
            let recovered_rows = conn
                .query("SELECT id, v FROM t ORDER BY id;")
                .await
                .expect("FrankenSQLite should read through the recovered WAL state");
            assert_eq!(recovered_rows.len(), 1);
            assert_eq!(recovered_rows[0].get(0).unwrap(), &SqliteValue::Integer(1));
            assert_eq!(
                recovered_rows[0].get(1).unwrap(),
                &SqliteValue::Text("alpha".into())
            );

            let checkpoint_rows = conn
                .query("PRAGMA wal_checkpoint(FULL);")
                .await
                .expect("checkpoint after crash recovery should succeed");
            assert_eq!(checkpoint_rows.len(), 1);
            let checkpoint_total = match checkpoint_rows[0].get(1).unwrap() {
                SqliteValue::Integer(value) => *value,
                other => panic!("expected integer WAL frame count, got {other:?}"),
            };
            let checkpoint_backfilled = match checkpoint_rows[0].get(2).unwrap() {
                SqliteValue::Integer(value) => *value,
                other => panic!("expected integer checkpoint backfill count, got {other:?}"),
            };
            assert!(
                checkpoint_total > 0,
                "checkpoint should see committed frames left by the crashed subprocess"
            );
            assert!(
                checkpoint_backfilled > 0,
                "checkpoint should backfill at least one recovered WAL frame"
            );
            conn.close().await.unwrap();

            let cx = Cx::new();
            let raw_pager = PagerBackend::open_with_page_buffer_max(&db_str, &cx, None, None)
                .await
                .expect("raw pager reopen should succeed after checkpoint");
            assert_eq!(
                raw_pager.published_snapshot().db_size,
                2,
                "checkpoint should persist the sqlite_master root and table root into the main database"
            );
            assert_eq!(
                std::fs::metadata(&db_path).unwrap().len(),
                u64::from(PageSize::DEFAULT.get()) * 2,
                "checkpoint should grow the main database file to include the table root page"
            );

            let oracle = rusqlite::Connection::open(&db_path).unwrap();
            let oracle_rows = oracle
                .prepare("SELECT id, v FROM t ORDER BY id;")
                .unwrap()
                .query_map([], |row| {
                    Ok((row.get::<_, i64>(0)?, row.get::<_, String>(1)?))
                })
                .unwrap()
                .collect::<rusqlite::Result<Vec<_>>>()
                .unwrap();
            assert_eq!(
                oracle_rows,
                vec![(1, "alpha".to_owned())],
                "rusqlite should observe the same checkpointed row set"
            );
        });
    }

