            FSQLITE_RECURSIVE_CTE_DIRECT_SUM_CONSUMER_HITS.store(0, AtomicOrdering::Relaxed);

            let conn = Connection::open(":memory:").await.unwrap();
            let row = conn
                .query_row(
                    "WITH RECURSIVE cnt(x) AS (\
                   SELECT 1 \
                   UNION ALL \
                   SELECT c.x + 1 FROM cnt AS c \
                   JOIN (SELECT 1) AS t ON 1 = 1 \
                   WHERE c.x < 5\
                 ) SELECT SUM(x) FROM cnt",
                )
                .await
                .unwrap();

            assert_eq!(row.get(0), Some(&SqliteValue::Integer(15)));
            assert_eq!(
                FSQLITE_RECURSIVE_CTE_DIRECT_SUM_CONSUMER_HITS.load(AtomicOrdering::Relaxed),
                0,
                "unsupported recursive-arm shapes should stay on the materialized fallback path"
            );
