    #[test]
    fn test_recursive_cte_direct_sum_consumer_supports_params_and_aliases() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            FSQLITE_RECURSIVE_CTE_DIRECT_SUM_CONSUMER_HITS.store(0, AtomicOrdering::Relaxed);
            FSQLITE_RECURSIVE_CTE_INTEGER_SERIES_SUM_HITS.store(0, AtomicOrdering::Relaxed);

            let conn = Connection::open(":memory:").await.unwrap();
            let row = conn
                .query_row_with_params(
                    "WITH RECURSIVE cnt(x) AS (\
                   SELECT ?1 \
                   UNION ALL \
                   SELECT x + 1 FROM cnt WHERE x < ?2\
                 ) SELECT SUM(c.x) FROM cnt AS c",
                    &[SqliteValue::Integer(1), SqliteValue::Integer(5)],
                )
                .await
                .unwrap();

            assert_eq!(row.get(0), Some(&SqliteValue::Integer(15)));
            assert!(
                FSQLITE_RECURSIVE_CTE_DIRECT_SUM_CONSUMER_HITS.load(AtomicOrdering::Relaxed) > 0,
                "parameterized recursive SUM with an aliased consumer should use the direct consumer fast path"
            );
            assert!(
                FSQLITE_RECURSIVE_CTE_INTEGER_SERIES_SUM_HITS.load(AtomicOrdering::Relaxed) > 0,
                "parameterized integer recursive SUM should use the series shortcut"
            );
        });
    }
