    #[test]
    fn test_memory_autocommit_ignores_prebound_publication_and_skips_concurrent_session() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let cx = conn.op_cx().unwrap();
            let bogus_publication = BoundPagerPublication {
                snapshot: PagerPublishedSnapshot {
                    snapshot_gen: 2,
                    visible_commit_seq: CommitSeq::new(999),
                    db_size: 7,
                    journal_mode: fsqlite_pager::JournalMode::Wal,
                    freelist_count: 3,
                    checkpoint_active: true,
                    page_set_size: 5,
                },
                read_retry_count: 41,
                source: super::PagerPublicationSource::PagerPlane,
            };

            let started = conn
                .ensure_autocommit_txn_with_publication_hint(&cx, Some(bogus_publication))
                .await
                .unwrap();
            assert!(started);
            assert!(
                conn.active_txn.borrow().is_some(),
                "autocommit should still begin a pager transaction"
            );
            assert!(
                !conn.is_concurrent_transaction(),
                ":memory: autocommit should ignore prebound publications and stay off the concurrent MVCC path"
            );
            assert!(
                !conn.has_concurrent_session(),
                ":memory: autocommit should not register a concurrent session even if a caller hands it a bound publication"
            );

            conn.resolve_autocommit_txn(true, true).await.unwrap();
        });
    }

