    #[test]
    fn file_backed_create_table_then_desc_index_has_clean_mvcc_and_pager_handoffs() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("sequential_ddl_handoffs.db");
            let conn = Connection::open(db_path.to_str().unwrap()).await.unwrap();

            let assert_quiescent = |phase: &str| {
                assert!(
                    conn.active_txn.borrow().is_none(),
                    "{phase}: active pager transaction leaked"
                );
                assert!(
                    !conn.has_concurrent_session(),
                    "{phase}: concurrent session leaked"
                );
                assert_eq!(
                    conn.concurrent_writer_count(),
                    0,
                    "{phase}: concurrent registry entry leaked"
                );
                assert_eq!(
                    conn.concurrent_lock_table.total_lock_count(),
                    0,
                    "{phase}: shared MVCC page lock leaked"
                );
                assert!(
                    conn.concurrent_lock_table.holder(PageNumber::ONE).is_none(),
                    "{phase}: sqlite_schema page lock leaked"
                );
                assert!(
                    !conn.pager.published_snapshot().checkpoint_active,
                    "{phase}: checkpoint remained active"
                );
            };

            assert_quiescent("before CREATE TABLE");
            conn.execute(
                "CREATE TABLE source_handles(\
                 provider_subject_id TEXT NOT NULL, \
                 known_at TEXT NOT NULL)",
            )
            .await
            .unwrap();
            assert_quiescent("after CREATE TABLE");

            let Statement::CreateIndex(create_index) = parse_single_statement(
                "CREATE INDEX idx_source_handles_provider_subject_id \
                 ON source_handles(provider_subject_id, known_at DESC)",
            )
            .unwrap() else {
                panic!("expected CREATE INDEX statement");
            };
            let cx = conn.op_cx().unwrap();
            let started = conn
                .ensure_autocommit_txn_with_cx(&cx)
                .await
                .expect("second DDL schema refresh and pager admission must not be Busy");
            assert!(started, "second DDL must start an autocommit transaction");
            assert!(conn.active_txn.borrow().is_some());
            assert!(conn.has_concurrent_session());
            assert_eq!(conn.concurrent_writer_count(), 1);

            conn.execute_create_index(&create_index)
                .await
                .expect("CREATE INDEX body and backfill must not be Busy");
            assert!(conn.active_txn.borrow().is_some());
            assert!(conn.has_concurrent_session());
            assert_eq!(
                conn.concurrent_lock_table.total_lock_count(),
                0,
                "CREATE INDEX body acquired or exposed a stale shared MVCC lock before commit"
            );
            assert!(
                conn.concurrent_lock_table.holder(PageNumber::ONE).is_none(),
                "CREATE INDEX body exposed a sqlite_schema page lock before commit"
            );

            conn.resolve_autocommit_txn_with_dirty_table_and_capture_and_cx(
                true, true, None, true, true, &cx,
            )
            .await
            .expect("CREATE INDEX concurrent commit planning and finalization must not be Busy");
            assert_quiescent("after CREATE INDEX commit");
            conn.close().await.unwrap();
        });
    }

    #[test]
    fn test_autocommit_failed_create_unique_index_restores_schema_state() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("autocommit_failed_unique_index.db");
            let db_str = db_path.to_str().unwrap();

            let conn = Connection::open(db_str).await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'dup');")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (2, 'dup');")
                .await
                .unwrap();
            let page_count_before =
                conn.query("PRAGMA page_count;").await.unwrap()[0].values()[0].clone();
            let freelist_count_before =
                conn.query("PRAGMA freelist_count;").await.unwrap()[0].values()[0].clone();

            let err = conn
                .execute("CREATE UNIQUE INDEX idx_name ON t(name);")
                .await
                .unwrap_err();
            let err_text = err.to_string();
            assert!(
                err_text.contains("UNIQUE")
                    || err_text.contains("unique")
                    || err_text.contains("secondary-index conflict"),
                "expected unique-index backfill failure, got: {err_text}"
            );

            let table = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .cloned()
                .expect("table should remain present");
            assert!(
                !table
                    .indexes
                    .iter()
                    .any(|index| index.name.eq_ignore_ascii_case("idx_name")),
                "failed autocommit DDL must not leak index metadata into connection-local schema"
            );
            assert_eq!(
                conn.query("PRAGMA page_count;").await.unwrap()[0].values()[0],
                page_count_before,
                "failed UNIQUE backfill must roll back its allocated root page"
            );
            assert_eq!(
                conn.query("PRAGMA freelist_count;").await.unwrap()[0].values()[0],
                freelist_count_before,
                "failed UNIQUE backfill must restore the freelist exactly"
            );

            conn.execute("CREATE INDEX idx_name ON t(name);")
                .await
                .unwrap();

            let reopened = Connection::open(db_str).await.unwrap();
            let rows = reopened
                .query(
                    "SELECT name, tbl_name FROM sqlite_master WHERE type='index' AND name='idx_name';",
                )
                .await
                .unwrap();
            assert_eq!(
                rows.len(),
                1,
                "reopened connection should see exactly one index"
            );
            assert_eq!(
                rows[0].values().to_vec(),
                vec![
                    SqliteValue::Text("idx_name".into()),
                    SqliteValue::Text("t".into()),
                ]
            );
        });
    }

    #[test]
    fn test_invalid_create_index_collation_fails_without_allocating_or_publishing() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("invalid_create_index_collation.db");
            let conn = Connection::open(db_path.to_str().unwrap()).await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            let page_count_before =
                conn.query("PRAGMA page_count;").await.unwrap()[0].values()[0].clone();
            let freelist_count_before =
                conn.query("PRAGMA freelist_count;").await.unwrap()[0].values()[0].clone();
            let schema_version_before =
                conn.query("PRAGMA schema_version;").await.unwrap()[0].values()[0].clone();

            let error = conn
                .execute("CREATE INDEX idx_bad_collation ON t(name COLLATE no_such_collation);")
                .await
                .expect_err("an unregistered index collation must fail before allocation");
            assert!(
                error.to_string().to_ascii_lowercase().contains("collation"),
                "unexpected CREATE INDEX error: {error}"
            );

            assert_eq!(
                conn.query("PRAGMA page_count;").await.unwrap()[0].values()[0],
                page_count_before,
                "failed pre-allocation CREATE INDEX must not grow the database"
            );
            assert_eq!(
                conn.query("PRAGMA freelist_count;").await.unwrap()[0].values()[0],
                freelist_count_before,
                "failed pre-allocation CREATE INDEX must not consume or release a page"
            );
            assert_eq!(
                conn.query("PRAGMA schema_version;").await.unwrap()[0].values()[0],
                schema_version_before,
                "failed pre-allocation CREATE INDEX must not advance the schema cookie"
            );
            assert!(
                conn.query(
                    "SELECT name FROM sqlite_master WHERE type='index' AND name='idx_bad_collation';"
                )
                .await
                .unwrap()
                .is_empty(),
                "failed pre-allocation CREATE INDEX must not publish sqlite_master metadata"
            );
            assert!(
                conn.schema.borrow()[0].indexes.is_empty(),
                "failed pre-allocation CREATE INDEX must not publish connection-local metadata"
            );
        });
    }

    #[test]
    fn test_invalid_create_index_functions_fail_before_allocating_or_publishing() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("invalid_create_index_functions.db");
            let conn = Connection::open(db_path.to_str().unwrap()).await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();

            let page_count_before =
                conn.query("PRAGMA page_count;").await.unwrap()[0].values()[0].clone();
            let freelist_count_before =
                conn.query("PRAGMA freelist_count;").await.unwrap()[0].values()[0].clone();
            let schema_version_before =
                conn.query("PRAGMA schema_version;").await.unwrap()[0].values()[0].clone();

            for (sql, expected) in [
                (
                    "CREATE INDEX idx_random ON t(random());",
                    "non-deterministic",
                ),
                ("CREATE INDEX idx_sum ON t(sum(name));", "aggregate"),
                (
                    "CREATE INDEX idx_unknown ON t(no_such_function(name));",
                    "no such function",
                ),
                (
                    "CREATE INDEX idx_wrong_arity ON t(lower(name, name));",
                    "wrong number of arguments",
                ),
                (
                    "CREATE INDEX idx_partial_random ON t(name) WHERE random() > 0;",
                    "non-deterministic",
                ),
                (
                    "CREATE INDEX idx_current_timestamp ON t(CURRENT_TIMESTAMP);",
                    "non-deterministic",
                ),
            ] {
                let error = conn
                    .execute(sql)
                    .await
                    .expect_err("invalid index function must fail on an empty table");
                assert!(
                    error.to_string().to_ascii_lowercase().contains(expected),
                    "unexpected CREATE INDEX error for `{sql}`: {error}"
                );
            }

            assert_eq!(
                conn.query("PRAGMA page_count;").await.unwrap()[0].values()[0],
                page_count_before,
                "failed function preflight must not grow the database"
            );
            assert_eq!(
                conn.query("PRAGMA freelist_count;").await.unwrap()[0].values()[0],
                freelist_count_before,
                "failed function preflight must not consume or release a page"
            );
            assert_eq!(
                conn.query("PRAGMA schema_version;").await.unwrap()[0].values()[0],
                schema_version_before,
                "failed function preflight must not advance the schema cookie"
            );
            assert!(
                conn.query("SELECT name FROM sqlite_master WHERE type='index';")
                    .await
                    .unwrap()
                    .is_empty(),
                "failed function preflight must not publish sqlite_master metadata"
            );
            assert!(
                conn.schema.borrow()[0].indexes.is_empty(),
                "failed function preflight must not publish connection-local metadata"
            );
        });
    }

    #[test]
    fn test_backfill_rejects_missing_or_ambiguous_key_representation() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            let table = conn.schema.borrow()[0].clone();

            let missing_column = IndexSchema {
                name: "idx_missing".to_owned(),
                columns: vec!["missing".to_owned()],
                key_expressions: Vec::new(),
                key_sort_directions: vec![SortDirection::Asc],
                where_clause: None,
                root_page: table.root_page + 1,
                is_unique: false,
                key_collations: vec![None],
                conflict_action: None,
            };
            let error = conn
                .backfill_index(&table, &missing_column)
                .await
                .expect_err("backfill must not silently omit an unresolved key column");
            assert!(matches!(&error, FrankenError::DatabaseCorrupt { .. }));
            assert!(
                error.to_string().contains("missing"),
                "unexpected missing-column backfill error: {error}"
            );

            let ambiguous_representation = IndexSchema {
                name: "idx_ambiguous".to_owned(),
                columns: vec!["name".to_owned()],
                key_expressions: vec!["lower(name)".to_owned()],
                key_sort_directions: vec![SortDirection::Asc],
                where_clause: None,
                root_page: table.root_page + 1,
                is_unique: false,
                key_collations: vec![None],
                conflict_action: None,
            };
            let error = conn
                .backfill_index(&table, &ambiguous_representation)
                .await
                .expect_err("backfill must reject competing key representations");
            assert!(matches!(&error, FrankenError::DatabaseCorrupt { .. }));
            assert!(
                error.to_string().contains("exactly one executable"),
                "unexpected ambiguous-representation error: {error}"
            );
        });
    }

    #[test]
    fn test_explicit_tx_failed_create_unique_index_restores_statement_state() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("explicit_tx_failed_unique_index.db");
            let db_str = db_path.to_str().unwrap();

            let conn = Connection::open(db_str).await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'dup');")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (2, 'dup');")
                .await
                .unwrap();

            conn.execute("BEGIN;").await.unwrap();

            let err = conn
                .execute("CREATE UNIQUE INDEX idx_name ON t(name);")
                .await
                .unwrap_err();
            let err_text = err.to_string();
            assert!(
                err_text.contains("UNIQUE")
                    || err_text.contains("unique")
                    || err_text.contains("secondary-index conflict"),
                "expected unique-index backfill failure, got: {err_text}"
            );

            let table = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .cloned()
                .expect("table should remain present");
            assert!(
                !table
                    .indexes
                    .iter()
                    .any(|index| index.name.eq_ignore_ascii_case("idx_name")),
                "failed CREATE INDEX inside BEGIN must not leak index metadata into connection schema"
            );

            let sqlite_master_rows = conn
                .query("SELECT name FROM sqlite_master WHERE type='index' AND name='idx_name';")
                .await
                .unwrap();
            assert!(
                sqlite_master_rows.is_empty(),
                "failed CREATE INDEX inside BEGIN must roll back sqlite_master changes"
            );

            conn.execute("CREATE INDEX idx_name ON t(name);")
                .await
                .unwrap();
            conn.execute("COMMIT;").await.unwrap();

            let reopened = Connection::open(db_str).await.unwrap();
            let rows = reopened
                .query(
                    "SELECT name, tbl_name FROM sqlite_master WHERE type='index' AND name='idx_name';",
                )
                .await
                .unwrap();
            assert_eq!(
                rows.len(),
                1,
                "successful CREATE INDEX after rollback should persist exactly one index"
            );
            assert_eq!(
                rows[0].values().to_vec(),
                vec![
                    SqliteValue::Text("idx_name".into()),
                    SqliteValue::Text("t".into()),
                ]
            );
        });
    }

    #[test]
    fn test_autocommit_plan_failure_reloads_dirty_memdb_state() {
        asupersync::test_utils::run_test(|| async {
            // :memory: databases use serialized mode (no concurrent registry),
            // so use a file-backed database to test concurrent session failure.
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("plan_failure_dirty_memdb.db");
            let conn = Connection::open(db_path.to_str().unwrap()).await.unwrap();
            let cx = conn.op_cx().unwrap();

            assert!(conn.ensure_autocommit_txn().await.unwrap());
            let dirty_root = conn.db.borrow_mut().create_table(1);
            {
                let mut txn_guard = conn.active_txn.borrow_mut();
                let txn = txn_guard.as_mut().expect("autocommit txn should be active");
                let page_no = txn.allocate_page(&cx).await.unwrap();
                let page_bytes = vec![0xAB; fsqlite_types::PageSize::DEFAULT.as_usize()];
                txn.write_page(&cx, page_no, &page_bytes).await.unwrap();
            }

            let session_id = conn
                .concurrent_session_id
                .borrow()
                .expect("concurrent session should exist");
            lock_unpoisoned(&conn.concurrent_registry).remove(session_id);

            let error = conn
                .resolve_autocommit_txn(true, true)
                .await
                .expect_err("missing concurrent session should fail commit planning");
            assert!(
                error.to_string().contains("MVCC session invalid")
                    || error
                        .to_string()
                        .contains("concurrent transaction missing session"),
                "unexpected error: {error}"
            );
            assert!(conn.active_txn.borrow().is_none());
            assert!(!conn.is_concurrent_transaction());
            assert!(
                conn.db.borrow().get_table(dirty_root).is_none(),
                "autocommit rollback must reload and discard dirty connection-local tables"
            );
        });
    }

