    #[test]
    fn test_rollback_to_savepoint_restores_schema_cookie() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t1 (a INTEGER);").await.unwrap();
            assert_eq!(conn.schema_cookie(), 1);

            conn.execute("BEGIN;").await.unwrap();
            conn.execute("SAVEPOINT ddl_step;").await.unwrap();
            conn.execute("CREATE TABLE t2 (b INTEGER);").await.unwrap();
            assert_eq!(conn.schema_cookie(), 2);

            conn.execute("ROLLBACK TO ddl_step;").await.unwrap();
            assert_eq!(conn.schema_cookie(), 1);
            assert!(conn.query("SELECT * FROM t2;").await.is_err());

            conn.execute("RELEASE ddl_step;").await.unwrap();
            conn.execute("COMMIT;").await.unwrap();
        });
    }

    #[test]
    fn test_rollback_to_savepoint_missing_concurrent_session_preserves_pager_state() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (x INTEGER);").await.unwrap();
            conn.execute("BEGIN;").await.unwrap();
            conn.execute("SAVEPOINT s1;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (1);").await.unwrap();

            assert!(
                conn.active_txn
                    .borrow()
                    .as_ref()
                    .is_some_and(|txn| txn.has_pending_writes()),
                "insert after savepoint should leave pending pager writes"
            );
            *conn.concurrent_session_id.borrow_mut() = None;

            let error = conn
                .execute("ROLLBACK TO s1;")
                .await
                .expect_err("missing concurrent session should abort savepoint rollback");
            assert!(
                error
                    .to_string()
                    .contains("concurrent savepoint present but no active session"),
                "unexpected error: {error}"
            );
            assert!(
                conn.active_txn
                    .borrow()
                    .as_ref()
                    .is_some_and(|txn| txn.has_pending_writes()),
                "failed savepoint rollback must not rewind the pager write-set"
            );
        });
    }

    #[test]
    fn test_statement_savepoint_cleanup_missing_concurrent_session_preserves_pager_state() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (x INTEGER);").await.unwrap();
            conn.execute("BEGIN CONCURRENT;").await.unwrap();

            let session_id = conn
                .concurrent_session_id
                .borrow()
                .expect("BEGIN CONCURRENT should register a session");
            let err = conn
                .with_internal_statement_savepoint(
                    "test_missing_session",
                    async || -> Result<()> {
                        conn.execute("INSERT INTO t VALUES (1);").await.unwrap();
                        *conn.concurrent_session_id.borrow_mut() = None;
                        Err(FrankenError::Internal(
                            "synthetic statement failure".to_owned(),
                        ))
                    },
                )
                .await
                .expect_err("missing concurrent session should abort statement cleanup");
            assert!(
                err.to_string()
                    .contains("concurrent transaction active but no session ID during rollback"),
                "unexpected error: {err}"
            );
            assert!(
                conn.active_txn
                    .borrow()
                    .as_ref()
                    .is_some_and(|txn| txn.has_pending_writes()),
                "failed statement cleanup must not rewind the pager write-set"
            );

            *conn.concurrent_session_id.borrow_mut() = Some(session_id);
            conn.execute("ROLLBACK;").await.unwrap();
        });
    }

    #[test]
    fn test_statement_savepoint_cleanup_skips_pager_release_after_rollback_failure() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let cx = conn.op_cx().unwrap();
            let pager = fsqlite_pager::traits::MockMvccPager;
            let txn = fsqlite_pager::MvccPager::begin(
                &pager,
                &cx,
                fsqlite_pager::TransactionMode::Deferred,
            )
            .await
            .unwrap();
            conn.in_transaction.set(true);
            *conn.active_txn.borrow_mut() = Some(txn.into());

            let err = conn
                .with_internal_statement_savepoint(
                    "test_rollback_failure",
                    async || -> Result<()> {
                        let replacement = fsqlite_pager::MvccPager::begin(
                            &pager,
                            &cx,
                            fsqlite_pager::TransactionMode::Deferred,
                        )
                        .await
                        .unwrap();
                        *conn.active_txn.borrow_mut() = Some(replacement.into());
                        Err(FrankenError::Internal(
                            "synthetic statement failure".to_owned(),
                        ))
                    },
                )
                .await
                .expect_err("statement cleanup should surface pager rollback failure");
            let err_text = err.to_string();
            assert!(
                err_text.contains("pager rollback_to_savepoint('"),
                "unexpected error: {err_text}",
            );
            assert!(
                err_text.contains("synthetic statement failure"),
                "unexpected error: {err_text}",
            );
            assert!(
                !err_text.contains("pager release_savepoint"),
                "statement cleanup must not release a pager savepoint after rollback failure: {err_text}",
            );
        });
    }

