    #[test]
    fn test_reopen_rejects_known_invalid_index_functions() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            for (case, create_sql, expected) in [
                (
                    "random",
                    "CREATE INDEX docs_title_idx ON docs(random())",
                    "non-deterministic",
                ),
                (
                    "aggregate",
                    "CREATE INDEX docs_title_idx ON docs(sum(title))",
                    "aggregate",
                ),
                (
                    "wrong_arity",
                    "CREATE INDEX docs_title_idx ON docs(lower(title, title))",
                    "wrong number of arguments",
                ),
                (
                    "current_timestamp",
                    "CREATE INDEX docs_title_idx ON docs(CURRENT_TIMESTAMP)",
                    "non-deterministic",
                ),
            ] {
                let db_path = dir.path().join(format!("invalid_index_function_{case}.db"));
                {
                    let sqlite = rusqlite::Connection::open(&db_path).unwrap();
                    sqlite
                        .execute_batch(
                            r"
                        CREATE TABLE docs (id INTEGER PRIMARY KEY, title TEXT);
                        CREATE INDEX docs_title_idx ON docs(title);
                        PRAGMA writable_schema = ON;
                        ",
                        )
                        .unwrap();
                    sqlite
                        .execute(
                            "UPDATE sqlite_master SET sql = ?1 WHERE name = 'docs_title_idx'",
                            [create_sql],
                        )
                        .unwrap();
                    sqlite
                        .execute_batch("PRAGMA writable_schema = OFF;")
                        .unwrap();
                }

                let error = Connection::open(db_path.to_str().unwrap())
                    .await
                    .expect_err("known-invalid persisted index function must corrupt the schema");
                assert!(matches!(&error, FrankenError::DatabaseCorrupt { .. }));
                let message = error.to_string().to_ascii_lowercase();
                assert!(
                    message.contains("docs_title_idx") && message.contains(expected),
                    "unexpected persisted-function reload error for `{create_sql}`: {error}"
                );
            }
        });
    }

    #[test]
    fn test_reopen_rejects_invalid_utf8_in_sqlite_master_record() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("corrupt_master_utf8.db");
            let db_str = db_path.to_string_lossy().to_string();

            {
                let rconn = rusqlite::Connection::open(&db_path).unwrap();
                rconn
                    .execute_batch(
                        r"
                    CREATE TABLE docs (id INTEGER PRIMARY KEY, title TEXT);
                    INSERT INTO docs VALUES (1, 'hello');
                    PRAGMA writable_schema = ON;
                    UPDATE sqlite_master
                    SET sql = CAST(x'FF' AS TEXT)
                    WHERE name = 'docs';
                    PRAGMA writable_schema = OFF;
                    ",
                    )
                    .unwrap();
            }

            // Oracle-corrected contract (bd-asupersync-043 triage): the
            // record TEXT loads byte-preserved after 84ebdf4b3; the failure
            // stock also exhibits is the unparseable schema SQL — assert the
            // malformed-schema class, not record-level UTF-8 rejection.
            let err = Connection::open(&db_str)
                .await
                .expect_err("unparseable sqlite_master SQL must fail schema load");
            let message = err.to_string();
            assert!(
                message.contains("could not parse CREATE TABLE SQL")
                    || message.to_ascii_lowercase().contains("malformed"),
                "unexpected reopen error class: {message}"
            );
        });
    }

    #[test]
    fn test_reopen_rejects_invalid_utf8_in_table_record() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("corrupt_table_utf8.db");
            let db_str = db_path.to_string_lossy().to_string();

            {
                let rconn = rusqlite::Connection::open(&db_path).unwrap();
                rconn
                    .execute_batch(
                        r"
                    CREATE TABLE docs (title TEXT);
                    INSERT INTO docs VALUES (CAST(x'FF' AS TEXT));
                    ",
                    )
                    .unwrap();
            }

            // Oracle-corrected contract (bd-asupersync-043 triage, receipt on
            // the release bead): stock SQLite preserves invalid-UTF-8 TEXT
            // bytes through the database file with no rejection — parity
            // after 84ebdf4b3 means hydration must SUCCEED and serve the raw
            // byte exactly.
            let conn = Connection::open(&db_str)
                .await
                .expect("lazy open should defer table row decoding");
            conn.set_reject_mem_fallback(false);
            let reload_cx = conn.op_cx().unwrap();
            conn.reload_memdb_from_pager(&reload_cx)
                .await
                .expect("invalid-UTF-8 TEXT must hydrate byte-preserved, matching stock");
            let rows = conn.query("SELECT hex(title) FROM docs;").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(
                rows[0].get(0),
                Some(&SqliteValue::Text("FF".into())),
                "raw TEXT byte must round-trip exactly like stock"
            );
        });
    }

