    #[test]
    fn test_file_backed_join_pager_scan_after_alter_add_column_pads_short_rows() -> Result<()> {
        let mut outcome: Result<()> = Ok(());
        asupersync::test_utils::run_test(|| async {
            let inner = async || -> Result<()> {
                let dir = tempfile::tempdir()?;
                let db_path = dir.path().join("join-pager-alter-short-row.db");
                let db_str = db_path.to_string_lossy().into_owned();

                let conn = Connection::open(db_str).await?;
                conn.execute(
                    "CREATE TABLE conversations (id INTEGER PRIMARY KEY, ended_at INTEGER);",
                )
                .await?;
                conn.execute("CREATE TABLE marker (id INTEGER PRIMARY KEY);")
                    .await?;
                conn.execute("INSERT INTO conversations(id, ended_at) VALUES (1, 1700000000000);")
                    .await?;
                conn.execute("INSERT INTO marker(id) VALUES (1);").await?;
                conn.execute("ALTER TABLE conversations ADD COLUMN last_message_idx INTEGER;")
                    .await?;
                conn.execute(
                    "ALTER TABLE conversations ADD COLUMN last_message_created_at INTEGER;",
                )
                .await?;

                conn.memdb_rows_loaded.set(false);
                conn.memdb_storage_count_shortcuts_safe.set(false);

                let rows = conn
                    .query(
                        "SELECT c.id, c.ended_at, c.last_message_idx, c.last_message_created_at \
                 FROM conversations c \
                 JOIN marker m ON m.id = c.id \
                 ORDER BY c.id;",
                    )
                    .await?;
                assert_eq!(
                    rows.iter()
                        .map(|row| row.values().to_vec())
                        .collect::<Vec<_>>(),
                    vec![vec![
                        SqliteValue::Integer(1),
                        SqliteValue::Integer(1_700_000_000_000),
                        SqliteValue::Null,
                        SqliteValue::Null,
                    ]],
                );
                Ok(())
            };
            outcome = inner().await;
        });
        outcome
    }

    #[test]
    fn test_reopened_autoincrement_table_where_order_by_returns_correct_columns() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("comments_ordered_reopen.db");
            let db_str = db_path.to_str().unwrap();

            {
                let conn = Connection::open(db_str).await.unwrap();
                conn.execute(
                    "CREATE TABLE comments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    issue_id TEXT NOT NULL,
                    author TEXT NOT NULL,
                    text TEXT NOT NULL,
                    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
                );",
                )
                .await
                .unwrap();
                conn.execute("CREATE INDEX idx_comments_issue ON comments (issue_id);")
                    .await
                    .unwrap();
                conn.execute("CREATE INDEX idx_comments_created_at ON comments (created_at);")
                    .await
                    .unwrap();
                conn.execute(
                    "INSERT INTO comments (issue_id, author, text, created_at) VALUES
                    ('bd-1', 'Ada', 'first', '2026-03-10T17:23:42+00:00'),
                    ('bd-2', 'Bea', 'other', '2026-03-10T17:23:43+00:00'),
                    ('bd-1', 'Cy', 'second', '2026-03-10T17:23:44+00:00');",
                )
                .await
                .unwrap();
            }

            let conn = Connection::open(db_str).await.unwrap();
            let rows = conn
                .query_with_params(
                    "SELECT id, issue_id, author, text, created_at
                 FROM comments
                 WHERE issue_id = ?
                 ORDER BY created_at ASC",
                    &[SqliteValue::from("bd-1")],
                )
                .await
                .unwrap();

            assert_eq!(rows.len(), 2);

            assert_eq!(
                rows[0].get(0).and_then(SqliteValue::as_integer),
                Some(1),
                "first row should expose the rowid/IPK as id",
            );
            assert_eq!(
                rows[0].get(1).and_then(SqliteValue::as_text),
                Some("bd-1"),
                "issue_id should remain a text column after reopen and ORDER BY planning",
            );
            assert_eq!(rows[0].get(2).and_then(SqliteValue::as_text), Some("Ada"));
            assert_eq!(rows[0].get(3).and_then(SqliteValue::as_text), Some("first"));
            assert_eq!(
                rows[0].get(4).and_then(SqliteValue::as_text),
                Some("2026-03-10T17:23:42+00:00"),
            );

            assert_eq!(rows[1].get(0).and_then(SqliteValue::as_integer), Some(3),);
            assert_eq!(rows[1].get(1).and_then(SqliteValue::as_text), Some("bd-1"));
            assert_eq!(rows[1].get(2).and_then(SqliteValue::as_text), Some("Cy"));
            assert_eq!(
                rows[1].get(3).and_then(SqliteValue::as_text),
                Some("second")
            );
            assert_eq!(
                rows[1].get(4).and_then(SqliteValue::as_text),
                Some("2026-03-10T17:23:44+00:00"),
            );
        });
    }

