    #[test]
    fn test_pragma_connection_stats_tracks_active_transactions_and_disconnects() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("pool-lifecycle.db");
            let db_path = db_path.to_string_lossy().into_owned();

            let mut conn1 = Connection::open(&db_path).await.unwrap();
            let conn2 = Connection::open(&db_path).await.unwrap();

            conn1.execute("BEGIN;").await.unwrap();
            let in_txn = txn_metrics_map(&conn2.query("PRAGMA connection_stats;").await.unwrap());
            assert_eq!(in_txn.get("pool_size_estimate"), Some(&2));
            assert_eq!(in_txn.get("active_transactions"), Some(&1));
            assert_eq!(in_txn.get("idle_connections"), Some(&1));
            assert!(
                in_txn
                    .get("transactions_started_total")
                    .copied()
                    .unwrap_or_default()
                    >= 1,
                "starting a transaction should be reflected in shared pool stats",
            );

            conn1.close_in_place().await.unwrap();

            let after_close = txn_metrics_map(
                &conn2
                    .query("PRAGMA fsqlite_connection_stats;")
                    .await
                    .unwrap(),
            );
            assert_eq!(after_close.get("pool_size_estimate"), Some(&1));
            assert_eq!(after_close.get("open_connections"), Some(&1));
            assert_eq!(after_close.get("active_transactions"), Some(&0));
            assert_eq!(after_close.get("disconnect_events"), Some(&1));
        });
    }

