    async fn open_connection_with_transient_retry(path: &str) -> Connection {
        let started = std::time::Instant::now();
        let mut attempt = 0_u32;
        loop {
            match Connection::open(path).await {
                Ok(conn) => return conn,
                Err(err)
                    if err.is_transient()
                        && started.elapsed() < std::time::Duration::from_secs(10) =>
                {
                    attempt = attempt.saturating_add(1);
                    std::thread::sleep(std::time::Duration::from_millis(1_u64 << attempt.min(6)));
                }
                Err(err) => panic!(
                    "open {path} failed after {:?} and {attempt} retries: {err}",
                    started.elapsed()
                ),
            }
        }
    }

