    #[test]
    fn test_file_backed_concurrent_write_conflict_produces_busy_snapshot() {
        asupersync::test_utils::run_test(|| async {
            // Two file-backed connections with concurrent mode, writing to the same
            // row. The second committer must get BusySnapshot (not a silent overwrite).
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("conflict_test.db");
            let path_str = db_path.to_str().unwrap();

            let conn1 = Connection::open(path_str).await.unwrap();
            conn1
                .execute("CREATE TABLE conflict_tbl (id INTEGER PRIMARY KEY, val INTEGER);")
                .await
                .unwrap();
            conn1
                .execute("INSERT INTO conflict_tbl VALUES (1, 0);")
                .await
                .unwrap();

            // Both connections start transactions and read the same row.
            let conn2 = Connection::open(path_str).await.unwrap();

            conn1.execute("BEGIN;").await.unwrap();
            conn2.execute("BEGIN;").await.unwrap();

            // Both read the current value.
            let _rows1 = conn1
                .query("SELECT val FROM conflict_tbl WHERE id = 1;")
                .await
                .unwrap();
            let _rows2 = conn2
                .query("SELECT val FROM conflict_tbl WHERE id = 1;")
                .await
                .unwrap();

            // conn1 writes and commits first.
            conn1
                .execute("UPDATE conflict_tbl SET val = 100 WHERE id = 1;")
                .await
                .unwrap();
            conn1.execute("COMMIT;").await.unwrap();

            // conn2 writes the same row against a stale snapshot. The transient
            // conflict may surface at UPDATE time or COMMIT time.
            let update_result = conn2
                .execute("UPDATE conflict_tbl SET val = 200 WHERE id = 1;")
                .await;

            match update_result {
                Err(err) => {
                    assert!(
                        err.is_transient(),
                        "stale concurrent write must be a transient error: {err}"
                    );
                }
                Ok(_) => {
                    let commit_result = conn2.execute("COMMIT;").await;
                    if let Err(err) = commit_result {
                        assert!(
                            err.is_transient(),
                            "commit conflict must be a transient error: {err}"
                        );
                    }
                }
            }

            let final_val = conn1
                .query("SELECT val FROM conflict_tbl WHERE id = 1;")
                .await
                .unwrap();
            let v = match final_val[0].values()[0] {
                SqliteValue::Integer(v) => v,
                _ => panic!("expected integer"),
            };
            assert!(
                v == 100 || v == 200,
                "final value must be from one committer: {v}"
            );
        });
    }

    #[test]
    fn test_busy_snapshot_retry_rebinds_latest_row_before_rewrite_bd_rjc() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("busy_snapshot_retry_rebind.db");
            let db = db_path.to_string_lossy().to_string();

            let table_root_page = {
                let conn = Connection::open(&db).await.unwrap();
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
                conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                    .await
                    .unwrap();
                let root_page = conn
                    .schema
                    .borrow()
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case("t"))
                    .map(|table| table.root_page)
                    .expect("table t should exist after CREATE TABLE");
                conn.execute("INSERT INTO t (id, v) VALUES (1, 0);")
                    .await
                    .unwrap();
                root_page
            };
            let table_root_pgno = fsqlite_types::PageNumber::new(
                u32::try_from(table_root_page).expect("root page should fit in u32"),
            )
            .expect("root page should be valid");

            async fn read_active_row(
                conn: &Connection,
                table_root_pgno: fsqlite_types::PageNumber,
            ) -> Vec<SqliteValue> {
                let mut active_txn = conn.active_txn.borrow_mut();
                let txn = active_txn
                    .as_mut()
                    .expect("active transaction should exist while probing staged row");
                let mut cursor = fsqlite_btree::BtCursor::new(
                    fsqlite_btree::TransactionPageIo::new(txn),
                    table_root_pgno,
                    u32::try_from(fsqlite_types::PageSize::DEFAULT.as_usize())
                        .expect("page size should fit in u32"),
                    true,
                );
                let seek = cursor
                    .table_move_to(&Cx::new(), 1)
                    .await
                    .expect("staged row lookup should succeed");
                assert!(seek.is_found(), "staged row must remain present");
                let payload = cursor
                    .payload(&Cx::new())
                    .await
                    .expect("staged row payload should be readable");
                fsqlite_types::record::parse_record(&payload)
                    .expect("staged row payload should decode as a SQLite record")
            }

            let conn1 = Connection::open(&db).await.unwrap();
            let conn2 = Connection::open(&db).await.unwrap();
            for conn in [&conn1, &conn2] {
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
            }

            conn1.execute("BEGIN CONCURRENT;").await.unwrap();
            conn2.execute("BEGIN CONCURRENT;").await.unwrap();

            assert_eq!(
                conn1
                    .execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                    .await
                    .unwrap(),
                1
            );
            assert_eq!(
                read_active_row(&conn1, table_root_pgno).await,
                vec![SqliteValue::Null, SqliteValue::Integer(1)],
                "first writer should stage v=1"
            );

            let loser_err = match conn2.execute("UPDATE t SET v = v + 1 WHERE id = 1;").await {
                Ok(changes) => {
                    assert_eq!(
                        changes, 1,
                        "second writer should affect one row when UPDATE wins"
                    );
                    assert_eq!(
                        read_active_row(&conn2, table_root_pgno).await,
                        vec![SqliteValue::Null, SqliteValue::Integer(1)],
                        "second writer should initially stage the same stale increment"
                    );
                    conn1.execute("COMMIT;").await.unwrap();
                    let loser_commit = conn2.execute("COMMIT;").await;
                    assert!(
                        loser_commit.is_err(),
                        "losing writer must fail transiently instead of silently overwriting"
                    );
                    loser_commit.unwrap_err()
                }
                Err(err) => {
                    conn1.execute("COMMIT;").await.unwrap();
                    err
                }
            };
            let winner_commit_seq = conn1
                .concurrent_commit_index
                .latest(table_root_pgno)
                .expect("winner commit should publish commit-index entry");
            assert!(
                loser_err.is_transient(),
                "losing writer should surface as transient retryable error: {loser_err}"
            );

            conn2.execute("ROLLBACK;").await.unwrap();

            let visible_after_rollback = conn2
                .query_row("SELECT v FROM t WHERE id = 1;")
                .await
                .unwrap();
            assert_eq!(
                visible_after_rollback.get(0),
                Some(&SqliteValue::Integer(1)),
                "loser connection must see winner state after rollback"
            );

            conn2.execute("BEGIN CONCURRENT;").await.unwrap();
            let retry_session_id = conn2
                .concurrent_session_id
                .borrow()
                .expect("retry BEGIN CONCURRENT should create a fresh session");
            let retry_snapshot_high = {
                let registry = lock_unpoisoned(&conn2.concurrent_registry);
                registry
                    .get(retry_session_id)
                    .expect("retry session handle should exist")
                    .snapshot()
                    .high
            };
            assert!(
                retry_snapshot_high >= winner_commit_seq,
                "retry BEGIN CONCURRENT bound stale snapshot_high={} winner_commit_seq={}",
                retry_snapshot_high.get(),
                winner_commit_seq.get()
            );

            assert_eq!(
                conn2
                    .execute("UPDATE t SET v = v + 1 WHERE id = 1;")
                    .await
                    .unwrap(),
                1
            );
            let retry_staged_row = read_active_row(&conn2, table_root_pgno).await;
            assert_eq!(
                retry_staged_row,
                vec![SqliteValue::Null, SqliteValue::Integer(2)],
                "retrying loser must re-read committed row before rewrite; snapshot_high={} winner_commit_seq={} latest_commit_index={:?}",
                retry_snapshot_high.get(),
                winner_commit_seq.get(),
                conn2
                    .concurrent_commit_index
                    .latest(table_root_pgno)
                    .map(|seq| seq.get())
            );

            conn2.execute("COMMIT;").await.unwrap();

            let final_row = conn1
                .query_row("SELECT v FROM t WHERE id = 1;")
                .await
                .unwrap();
            assert_eq!(
                final_row.get(0),
                Some(&SqliteValue::Integer(2)),
                "retrying loser should advance the row to 2 after rebinding"
            );
        });
    }

    #[test]
    fn test_disjoint_concurrent_prepared_inserts_keep_distinct_conflict_surfaces() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("disjoint_concurrent_prepared_inserts.db");
            let db = db_path.to_string_lossy().to_string();

            let (left_root_page, right_root_page) = {
                let conn = Connection::open(&db).await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
                conn.execute("CREATE TABLE left_t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                    .await
                    .unwrap();
                conn.execute("CREATE TABLE right_t (id INTEGER PRIMARY KEY, v INTEGER NOT NULL);")
                    .await
                    .unwrap();

                let schema = conn.schema.borrow();
                let left_root_page = schema
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case("left_t"))
                    .map(|table| table.root_page)
                    .expect("left_t root page must exist");
                let right_root_page = schema
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case("right_t"))
                    .map(|table| table.root_page)
                    .expect("right_t root page must exist");
                (left_root_page, right_root_page)
            };

            assert_ne!(
                left_root_page, right_root_page,
                "disjoint-table proof requires distinct root pages"
            );

            let left_root_pgno =
                PageNumber::new(u32::try_from(left_root_page).expect("left root page fits u32"))
                    .expect("left root page valid");
            let right_root_pgno =
                PageNumber::new(u32::try_from(right_root_page).expect("right root page fits u32"))
                    .expect("right root page valid");

            let conn1 = Connection::open(&db).await.unwrap();
            let conn2 = Connection::open(&db).await.unwrap();
            for conn in [&conn1, &conn2] {
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                conn.execute("PRAGMA fsqlite.concurrent_mode=ON;")
                    .await
                    .unwrap();
            }

            let insert_left = conn1
                .prepare("INSERT INTO left_t (id, v) VALUES (?1, ?2)")
                .await
                .unwrap();
            let insert_right = conn2
                .prepare("INSERT INTO right_t (id, v) VALUES (?1, ?2)")
                .await
                .unwrap();

            conn1.execute("BEGIN CONCURRENT;").await.unwrap();
            conn2.execute("BEGIN CONCURRENT;").await.unwrap();

            conn1
                .execute_prepared_with_params(
                    &insert_left,
                    &[SqliteValue::Integer(1), SqliteValue::Integer(11)],
                )
                .await
                .unwrap();
            conn2
                .execute_prepared_with_params(
                    &insert_right,
                    &[SqliteValue::Integer(1), SqliteValue::Integer(22)],
                )
                .await
                .unwrap();

            let left_conflict_surface = {
                let mut txn_guard = conn1.active_txn.borrow_mut();
                let txn = txn_guard
                    .as_mut()
                    .expect("left concurrent transaction should have active pager handle");
                txn.pending_conflict_pages().unwrap()
            };
            let right_conflict_surface = {
                let mut txn_guard = conn2.active_txn.borrow_mut();
                let txn = txn_guard
                    .as_mut()
                    .expect("right concurrent transaction should have active pager handle");
                txn.pending_conflict_pages().unwrap()
            };

            assert!(
                left_conflict_surface.contains(&left_root_pgno),
                "left insert must track its own table root in the conflict surface: {left_conflict_surface:?}"
            );
            assert!(
                !left_conflict_surface.contains(&right_root_pgno),
                "left insert must not pull in right_t root page: left={left_conflict_surface:?} right_root={right_root_pgno:?}"
            );
            assert!(
                right_conflict_surface.contains(&right_root_pgno),
                "right insert must track its own table root in the conflict surface: {right_conflict_surface:?}"
            );
            assert!(
                !right_conflict_surface.contains(&left_root_pgno),
                "right insert must not pull in left_t root page: right={right_conflict_surface:?} left_root={left_root_pgno:?}"
            );

            conn1.execute("COMMIT;").await.unwrap();
            conn2.execute("COMMIT;").await.unwrap();

            let rows = conn1
                .query("SELECT (SELECT COUNT(*) FROM left_t), (SELECT COUNT(*) FROM right_t);")
                .await
                .unwrap();
            assert_eq!(
                rows[0].values(),
                &[SqliteValue::Integer(1), SqliteValue::Integer(1)],
                "both disjoint concurrent inserts must commit successfully"
            );
        });
    }

    #[test]
    fn test_file_backed_disjoint_commit_sequence_fences_intermediate_snapshot() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("disjoint_commit_sequence_fence.db");
            let db = db_path.to_string_lossy().to_string();

            {
                let mut setup = Connection::open(&db).await.unwrap();
                setup
                    .execute(
                        "CREATE TABLE accounts (\
                             id INTEGER PRIMARY KEY,\
                             balance INTEGER NOT NULL,\
                             payload TEXT NOT NULL\
                         );",
                    )
                    .await
                    .unwrap();
                let payload = "x".repeat(512);
                for id in 0_i64..100 {
                    setup
                        .execute_with_params(
                            "INSERT INTO accounts VALUES (?1, 1000, ?2);",
                            &[
                                SqliteValue::Integer(id),
                                SqliteValue::Text(payload.clone().into()),
                            ],
                        )
                        .await
                        .unwrap();
                }
                setup.close_without_checkpoint_in_place().await.unwrap();
            }

            let conn_a = Connection::open(&db).await.unwrap();
            let conn_b = Connection::open(&db).await.unwrap();
            let conn_c = Connection::open(&db).await.unwrap();
            for conn in [&conn_a, &conn_b, &conn_c] {
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                assert!(conn.is_concurrent_mode_default());
            }

            conn_a.execute("BEGIN;").await.unwrap();
            conn_b.execute("BEGIN;").await.unwrap();
            let shared_begin = conn_a.current_concurrent_snapshot_seq().unwrap();
            assert_eq!(
                conn_b.current_concurrent_snapshot_seq(),
                Some(shared_begin),
                "the two disjoint writers must start from one WAL horizon"
            );
            assert_eq!(
                conn_a
                    .execute("UPDATE accounts SET balance = balance + 1 WHERE id = 1;")
                    .await
                    .unwrap(),
                1
            );
            assert_eq!(
                conn_b
                    .execute("UPDATE accounts SET balance = balance + 1 WHERE id = 50;")
                    .await
                    .unwrap(),
                1
            );

            conn_a.execute("COMMIT;").await.unwrap();
            conn_c.execute("BEGIN;").await.unwrap();
            let intermediate_snapshot = conn_c.current_concurrent_snapshot_seq().unwrap();
            assert!(
                intermediate_snapshot > shared_begin,
                "the intermediate reader must include writer A before writer B publishes"
            );

            conn_b.execute("COMMIT;").await.unwrap();
            let writer_b_commit = conn_b
                .last_local_commit_seq()
                .expect("writer B must publish a commit sequence");
            assert!(
                writer_b_commit > intermediate_snapshot,
                "a later durable WAL commit must be newer than a transaction that began before it: \
                 shared_begin={} intermediate_snapshot={} writer_b_commit={}",
                shared_begin,
                intermediate_snapshot,
                writer_b_commit
            );

            let stale_write = conn_c
                .execute("UPDATE accounts SET balance = balance + 1 WHERE id = 50;")
                .await;
            let stale_error = match stale_write {
                Err(error) => error,
                Ok(changes) => {
                    assert_eq!(changes, 1);
                    conn_c
                        .execute("COMMIT;")
                        .await
                        .expect_err("FCW must reject writer C's stale page image")
                }
            };
            assert!(
                stale_error.is_transient(),
                "the stale writer must fail with a retryable conflict: {stale_error}"
            );
            conn_c.execute("ROLLBACK;").await.unwrap();

            let balance = conn_a
                .query_row("SELECT balance FROM accounts WHERE id = 50;")
                .await
                .unwrap();
            assert_eq!(
                balance.get(0),
                Some(&SqliteValue::Integer(1001)),
                "writer B's committed row must survive the rejected stale writer"
            );
        });
    }

    #[test]
    fn test_file_backed_multi_page_write_set_survives_interleaved_peer_commit() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("multi_page_interleaved_peer.db");
            let db = db_path.to_string_lossy().to_string();

            {
                let mut setup = Connection::open(&db).await.unwrap();
                setup
                    .execute(
                        "CREATE TABLE accounts (\
                             id INTEGER PRIMARY KEY,\
                             balance INTEGER NOT NULL,\
                             payload TEXT NOT NULL\
                         );",
                    )
                    .await
                    .unwrap();
                let payload = "x".repeat(512);
                for id in 0_i64..100 {
                    setup
                        .execute_with_params(
                            "INSERT INTO accounts VALUES (?1, 1000, ?2);",
                            &[
                                SqliteValue::Integer(id),
                                SqliteValue::Text(payload.clone().into()),
                            ],
                        )
                        .await
                        .unwrap();
                }
                setup.close_without_checkpoint_in_place().await.unwrap();
            }

            let mut transfer = Connection::open(&db).await.unwrap();
            let mut peer = Connection::open(&db).await.unwrap();
            for conn in [&transfer, &peer] {
                conn.execute("PRAGMA busy_timeout=5000;").await.unwrap();
                assert!(conn.is_concurrent_mode_default());
            }

            transfer.execute("BEGIN;").await.unwrap();
            peer.execute("BEGIN;").await.unwrap();
            assert_eq!(
                transfer
                    .execute("UPDATE accounts SET balance = balance - 9 WHERE id = 0;")
                    .await
                    .unwrap(),
                1
            );
            let pages_after_debit = transfer
                .active_txn
                .borrow()
                .as_ref()
                .unwrap()
                .pending_conflict_pages_conservative();
            assert!(
                !pages_after_debit.is_empty(),
                "the staged debit must appear in the pager conflict surface"
            );

            assert_eq!(
                peer.execute("UPDATE accounts SET balance = balance + 1 WHERE id = 50;")
                    .await
                    .unwrap(),
                1
            );
            peer.execute("COMMIT;").await.unwrap();

            assert_eq!(
                transfer
                    .execute("UPDATE accounts SET balance = balance + 9 WHERE id = 99;")
                    .await
                    .unwrap(),
                1
            );
            let pages_after_credit = transfer
                .active_txn
                .borrow()
                .as_ref()
                .unwrap()
                .pending_conflict_pages_conservative();
            assert!(
                pages_after_debit
                    .iter()
                    .all(|page| pages_after_credit.contains(page)),
                "staging the credit must not discard the debit pages: debit={pages_after_debit:?} credit={pages_after_credit:?}"
            );
            assert!(
                pages_after_credit.len() > pages_after_debit.len(),
                "the distant credit must add a distinct leaf to the pager write set: debit={pages_after_debit:?} credit={pages_after_credit:?}"
            );

            transfer.execute("COMMIT;").await.unwrap();
            transfer.close_without_checkpoint_in_place().await.unwrap();
            peer.close_without_checkpoint_in_place().await.unwrap();

            let stock = rusqlite::Connection::open(&db_path).unwrap();
            let durable = stock
                .query_row(
                    "SELECT COUNT(*), SUM(balance),\
                     (SELECT balance FROM accounts WHERE id = 0),\
                     (SELECT balance FROM accounts WHERE id = 50),\
                     (SELECT balance FROM accounts WHERE id = 99)\
                     FROM accounts;",
                    [],
                    |row| {
                        Ok((
                            row.get::<_, i64>(0)?,
                            row.get::<_, i64>(1)?,
                            row.get::<_, i64>(2)?,
                            row.get::<_, i64>(3)?,
                            row.get::<_, i64>(4)?,
                        ))
                    },
                )
                .unwrap();
            assert_eq!(durable, (100, 100_001, 991, 1001, 1009));
            assert_eq!(
                stock
                    .query_row("PRAGMA integrity_check;", [], |row| row.get::<_, String>(0))
                    .unwrap(),
                "ok"
            );
        });
    }

    #[test]
    fn test_file_backed_begin_sequence_and_page_image_are_coherent() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("begin_sequence_page_image_coherence.db");
            let db = db_path.to_string_lossy().to_string();

            {
                let mut setup = Connection::open(&db).await.unwrap();
                setup
                    .execute(
                        "CREATE TABLE accounts (\
                             id INTEGER PRIMARY KEY,\
                             balance INTEGER NOT NULL,\
                             payload TEXT NOT NULL\
                         );",
                    )
                    .await
                    .unwrap();
                let payload = "x".repeat(512);
                for id in 0_i64..20 {
                    setup
                        .execute_with_params(
                            "INSERT INTO accounts VALUES (?1, 1000, ?2);",
                            &[
                                SqliteValue::Integer(id),
                                SqliteValue::Text(payload.clone().into()),
                            ],
                        )
                        .await
                        .unwrap();
                }
                setup.close_without_checkpoint_in_place().await.unwrap();
            }

            let mut pager_a = Connection::open(&db).await.unwrap();
            let pager_b = Connection::open(&db).await.unwrap();

            pager_a.execute("BEGIN;").await.unwrap();
            pager_a
                .execute("UPDATE accounts SET balance = balance + 1 WHERE id = 0;")
                .await
                .unwrap();
            pager_a.execute("COMMIT;").await.unwrap();

            pager_a.execute("BEGIN;").await.unwrap();
            pager_b.execute("BEGIN;").await.unwrap();
            pager_b
                .execute("UPDATE accounts SET balance = balance + 7 WHERE id = 0;")
                .await
                .unwrap();
            pager_b.execute("COMMIT;").await.unwrap();
            let peer_commit = pager_b.last_local_commit_seq().unwrap();

            pager_a
                .execute("UPDATE accounts SET balance = balance + 1 WHERE id = 19;")
                .await
                .unwrap();
            pager_a.execute("COMMIT;").await.unwrap();
            let gap_commit = pager_a.last_local_commit_seq().unwrap();
            assert!(gap_commit > peer_commit);

            pager_a.execute("BEGIN;").await.unwrap();
            let refreshed_snapshot = pager_a.current_concurrent_snapshot_seq().unwrap();
            assert!(
                refreshed_snapshot >= gap_commit,
                "the pager must bind at or after its gap-crossing commit: commit={gap_commit} snapshot={refreshed_snapshot}"
            );
            assert_eq!(
                pager_a
                    .query_row("SELECT balance FROM accounts WHERE id = 0;")
                    .await
                    .unwrap()
                    .get(0),
                Some(&SqliteValue::Integer(1008)),
                "a gap-crossing disjoint commit must not relabel the pre-peer page image at the new sequence"
            );
            pager_a
                .execute("UPDATE accounts SET balance = balance + 1 WHERE id = 1;")
                .await
                .unwrap();
            pager_a.execute("COMMIT;").await.unwrap();
            pager_a.close_without_checkpoint_in_place().await.unwrap();

            let stock = rusqlite::Connection::open(&db_path).unwrap();
            assert_eq!(
                stock
                    .query_row("SELECT balance FROM accounts WHERE id = 0;", [], |row| {
                        row.get::<_, i64>(0)
                    })
                    .unwrap(),
                1008,
                "a sibling-row write must preserve the prior committed page image"
            );
            assert_eq!(
                stock
                    .query_row("SELECT balance FROM accounts WHERE id = 1;", [], |row| {
                        row.get::<_, i64>(0)
                    })
                    .unwrap(),
                1001
            );
            assert_eq!(
                stock
                    .query_row("SELECT balance FROM accounts WHERE id = 19;", [], |row| {
                        row.get::<_, i64>(0)
                    })
                    .unwrap(),
                1001
            );
        });
    }

