    fn test_drop_table_if_exists() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            // Should not error when table doesn't exist.
            conn.execute("DROP TABLE IF EXISTS nonexistent;")
                .await
                .unwrap();
            conn.execute("CREATE TABLE tmp (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute("INSERT INTO tmp VALUES (1);").await.unwrap();
            conn.execute("DROP TABLE IF EXISTS tmp;").await.unwrap();
            // Table should be gone.
            let result = conn.query("SELECT * FROM tmp;").await;
            assert!(result.is_err(), "table should be dropped");
        });
    }

