            assert_eq!(rows[0].values()[1], SqliteValue::Integer(2)); // count(val) = 2
            assert_eq!(rows[0].values()[2], SqliteValue::Integer(40)); // sum = 10+30 = 40
            assert_eq!(rows[0].values()[3], SqliteValue::Float(20.0)); // avg = 40/2 = 20.0
