    #[test]
    fn test_value_slab_insert_10k_matches_rusqlite_oracle() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let fconn = Connection::open(":memory:").await.unwrap();
            let rconn = rusqlite::Connection::open_in_memory().unwrap();

            let create_sql =
                "CREATE TABLE slab_insert_oracle(id INTEGER PRIMARY KEY, score INTEGER, tag TEXT)";
            fconn.execute(create_sql).await.unwrap();
            rconn.execute_batch(&(create_sql.to_owned() + ";")).unwrap();

            fconn.execute("BEGIN").await.unwrap();
            rconn.execute_batch("BEGIN;").unwrap();

            let fstmt = fconn
                .prepare("INSERT INTO slab_insert_oracle (id, score, tag) VALUES (?1, ?2, ?3)")
                .await
                .unwrap();
            let mut rstmt = rconn
                .prepare("INSERT INTO slab_insert_oracle (id, score, tag) VALUES (?1, ?2, ?3)")
                .unwrap();

            for id in 1_i64..=10_000 {
                let score = (id * 3) - 7;
                let tag = format!("r{id}");
                fstmt
                    .execute_with_params(&[
                        SqliteValue::from(id),
                        SqliteValue::from(score),
                        SqliteValue::from(tag.clone()),
                    ])
                    .await
                    .unwrap();
                rstmt.execute(rusqlite::params![id, score, tag]).unwrap();
            }

            fconn.execute("COMMIT").await.unwrap();
            rconn.execute_batch("COMMIT;").unwrap();

            let queries = [
                "SELECT COUNT(*) FROM slab_insert_oracle",
                "SELECT id, score, tag FROM slab_insert_oracle ORDER BY id",
                "SELECT SUM(score), MIN(tag), MAX(tag) FROM slab_insert_oracle",
            ];

            let mismatches = oracle_compare(&fconn, &rconn, &queries).await;
            if !mismatches.is_empty() {
                for mismatch in &mismatches {
                    eprintln!("{mismatch}\n");
                }
                panic!("{} value slab 10k insert mismatches", mismatches.len());
            }
        });
    }

    #[test]
    fn test_value_slab_mixed_types_insert_matches_rusqlite_oracle() {
        asupersync::test_utils::run_test(|| async {
            let _serial = super::fsqlite_core_test_serializer();
            let fconn = Connection::open(":memory:").await.unwrap();
            let rconn = rusqlite::Connection::open_in_memory().unwrap();

            let create_sql = "CREATE TABLE slab_mixed_types(id INTEGER PRIMARY KEY, int_col INTEGER, text_col TEXT, blob_col BLOB, any_col)";
            fconn.execute(create_sql).await.unwrap();
            rconn.execute_batch(&(create_sql.to_owned() + ";")).unwrap();

            let fstmt = fconn
            .prepare(
                "INSERT INTO slab_mixed_types (id, int_col, text_col, blob_col, any_col) VALUES (?1, ?2, ?3, ?4, ?5)",
            )
            .await
            .unwrap();
            let mut rstmt = rconn
            .prepare(
                "INSERT INTO slab_mixed_types (id, int_col, text_col, blob_col, any_col) VALUES (?1, ?2, ?3, ?4, ?5)",
            )
            .unwrap();

            let rows = [
                (
                    1_i64,
                    SqliteValue::Integer(42),
                    SqliteValue::from("alpha"),
                    SqliteValue::from(vec![0x00_u8, 0x01, 0x02]),
                    SqliteValue::Null,
                    rusqlite::types::Value::Integer(42),
                    rusqlite::types::Value::Text(String::from("alpha")),
                    rusqlite::types::Value::Blob(vec![0x00_u8, 0x01, 0x02]),
                    rusqlite::types::Value::Null,
                ),
                (
                    2_i64,
                    SqliteValue::Integer(-7),
                    SqliteValue::from(""),
                    SqliteValue::from(Vec::<u8>::new()),
                    SqliteValue::from("tail"),
                    rusqlite::types::Value::Integer(-7),
                    rusqlite::types::Value::Text(String::new()),
                    rusqlite::types::Value::Blob(Vec::new()),
                    rusqlite::types::Value::Text(String::from("tail")),
                ),
                (
                    3_i64,
                    SqliteValue::Null,
                    SqliteValue::from("short-inline"),
                    SqliteValue::from(vec![0xAB_u8, 0xCD]),
                    SqliteValue::Integer(99),
                    rusqlite::types::Value::Null,
                    rusqlite::types::Value::Text(String::from("short-inline")),
                    rusqlite::types::Value::Blob(vec![0xAB_u8, 0xCD]),
                    rusqlite::types::Value::Integer(99),
                ),
                (
                    4_i64,
                    SqliteValue::Integer(1_000_000),
                    SqliteValue::Null,
                    SqliteValue::Null,
                    SqliteValue::from(vec![0xF0_u8, 0x0D]),
                    rusqlite::types::Value::Integer(1_000_000),
                    rusqlite::types::Value::Null,
                    rusqlite::types::Value::Null,
                    rusqlite::types::Value::Blob(vec![0xF0_u8, 0x0D]),
                ),
            ];

            for (id, int_col, text_col, blob_col, any_col, r_int, r_text, r_blob, r_any) in rows {
                fstmt
                    .execute_with_params(&[
                        SqliteValue::from(id),
                        int_col,
                        text_col,
                        blob_col,
                        any_col,
                    ])
                    .await
                    .unwrap();
                rstmt
                    .execute(rusqlite::params![id, r_int, r_text, r_blob, r_any])
                    .unwrap();
            }

            let queries = [
                "SELECT id, int_col, typeof(int_col), text_col, typeof(text_col), blob_col, typeof(blob_col), any_col, typeof(any_col) FROM slab_mixed_types ORDER BY id",
                "SELECT COUNT(*) FROM slab_mixed_types WHERE any_col IS NULL",
                "SELECT SUM(COALESCE(int_col, 0)) FROM slab_mixed_types",
            ];

            let mismatches = oracle_compare(&fconn, &rconn, &queries).await;
            if !mismatches.is_empty() {
                for mismatch in &mismatches {
                    eprintln!("{mismatch}\n");
                }
                panic!("{} value slab mixed-type mismatches", mismatches.len());
            }
        });
    }

    #[test]
