    #[test]
    fn test_prepared_update_delete_precompute_statement_savepoint_skip_hint() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
            "CREATE TABLE prep_ud_plain_skip (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .await
        .unwrap();
            conn.execute(
            "CREATE TABLE prep_ud_indexed_skip (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .await
        .unwrap();
            conn.execute(
                "CREATE INDEX prep_ud_indexed_skip_value_idx ON prep_ud_indexed_skip(value);",
            )
            .await
            .unwrap();

            let plain_update = conn
                .prepare("UPDATE prep_ud_plain_skip SET value = ?1 WHERE id = ?2")
                .await
                .unwrap();
            let indexed_update = conn
                .prepare("UPDATE prep_ud_indexed_skip SET value = ?1 WHERE id = ?2")
                .await
                .unwrap();
            let plain_delete = conn
                .prepare("DELETE FROM prep_ud_plain_skip WHERE id = ?1")
                .await
                .unwrap();
            let indexed_delete = conn
                .prepare("DELETE FROM prep_ud_indexed_skip WHERE id = ?1")
                .await
                .unwrap();

            assert!(matches!(
                plain_update.prepared_update_delete_fast_path.as_ref(),
                Some(super::PreparedUpdateDeleteFastPath {
                    skip_statement_savepoint_in_explicit_txn: true,
                    static_runtime_inputs: Some(_),
                    ..
                })
            ));
            assert!(
                plain_update.precompiled_dml().is_none(),
                "prepared UPDATE fast path should stay out of the precompiled INSERT dispatch"
            );
            assert!(
                plain_update.db.is_none(),
                "direct-simple prepared UPDATE should skip reusable table-program compilation"
            );
            assert!(
                plain_update.dispatch_precompiled_program().is_none(),
                "direct-simple prepared UPDATE should not carry a reusable table program"
            );
            let (plain_runtime_requirements, plain_runtime_inputs) =
                plain_update.prepared_table_program_runtime_inputs();
            assert_eq!(
                plain_runtime_requirements,
                super::TableExecutionRuntimeRequirements::write_path(None, false)
            );
            assert!(
                plain_runtime_inputs.is_some(),
                "prepared UPDATE fast path should surface precomputed static runtime inputs to the reuse executor"
            );
            assert!(matches!(
                indexed_update.prepared_update_delete_fast_path.as_ref(),
                Some(super::PreparedUpdateDeleteFastPath {
                    skip_statement_savepoint_in_explicit_txn: false,
                    static_runtime_inputs: Some(_),
                    ..
                })
            ));
            assert!(
                indexed_update.db.is_some(),
                "UPDATE that touches an indexed column should keep the reusable table program"
            );
            assert!(
                indexed_update.dispatch_precompiled_program().is_some(),
                "UPDATE that touches an indexed column should dispatch through its reusable table program"
            );
            assert!(matches!(
                plain_delete.prepared_update_delete_fast_path.as_ref(),
                Some(super::PreparedUpdateDeleteFastPath {
                    skip_statement_savepoint_in_explicit_txn: true,
                    static_runtime_inputs: Some(_),
                    ..
                })
            ));
            assert!(
                plain_delete.precompiled_dml().is_none(),
                "prepared DELETE fast path should stay out of the precompiled INSERT dispatch"
            );
            assert!(
                plain_delete.db.is_none(),
                "direct-simple prepared DELETE should skip reusable table-program compilation"
            );
            assert!(
                plain_delete.dispatch_precompiled_program().is_none(),
                "direct-simple prepared DELETE should not carry a reusable table program"
            );
            let (plain_delete_runtime_requirements, plain_delete_runtime_inputs) =
                plain_delete.prepared_table_program_runtime_inputs();
            assert_eq!(
                plain_delete_runtime_requirements,
                super::TableExecutionRuntimeRequirements::write_path(None, false)
            );
            assert!(
                plain_delete_runtime_inputs.is_some(),
                "prepared DELETE fast path should surface precomputed static runtime inputs to the reuse executor"
            );
            assert!(matches!(
                indexed_delete.prepared_update_delete_fast_path.as_ref(),
                Some(super::PreparedUpdateDeleteFastPath {
                    skip_statement_savepoint_in_explicit_txn: false,
                    static_runtime_inputs: Some(_),
                    ..
                })
            ));
            assert!(
                indexed_delete.db.is_some(),
                "DELETE on an indexed table should keep the reusable table program"
            );
            assert!(
                indexed_delete.dispatch_precompiled_program().is_some(),
                "DELETE on an indexed table should dispatch through its reusable table program"
            );
        });
    }

    #[test]
    fn test_prepared_update_write_after_write_defers_active_txn_memdb_reload_until_read_boundary() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
            "CREATE TABLE prep_ud_memdb_reload_skip (id INTEGER PRIMARY KEY, val TEXT NOT NULL);",
        )
        .await
        .unwrap();
            conn.execute("INSERT INTO prep_ud_memdb_reload_skip VALUES (1, 'a'), (2, 'b');")
                .await
                .unwrap();
            let root_page = {
                let schema = conn.schema.borrow();
                schema
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case("prep_ud_memdb_reload_skip"))
                    .map(|table| table.root_page)
                    .expect("prep_ud_memdb_reload_skip table should exist")
            };

            let stmt = conn
                .prepare("UPDATE prep_ud_memdb_reload_skip SET val = ?1 WHERE id = ?2")
                .await
                .unwrap();
            assert!(matches!(
                stmt.prepared_update_delete_fast_path.as_ref(),
                Some(super::PreparedUpdateDeleteFastPath {
                    skip_statement_savepoint_in_explicit_txn: true,
                    static_runtime_inputs: Some(_),
                    ..
                })
            ));

            let rows = conn
                .query("SELECT id, val FROM prep_ud_memdb_reload_skip ORDER BY id")
                .await
                .unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values().to_vec())
                    .collect::<Vec<_>>(),
                vec![
                    vec![SqliteValue::Integer(1), SqliteValue::Text("a".into()),],
                    vec![SqliteValue::Integer(2), SqliteValue::Text("b".into()),],
                ]
            );

            let memdb_values = |conn: &Connection| -> Vec<(i64, SqliteValue)> {
                let db = conn.db.borrow();
                let table = db
                    .get_table(root_page)
                    .expect("table should be present in MemDatabase");
                table
                    .iter_rows()
                    .map(|(rowid, values)| (rowid, values[1].clone()))
                    .collect()
            };

            assert_eq!(
                memdb_values(&conn),
                vec![
                    (1, SqliteValue::Text("a".into())),
                    (2, SqliteValue::Text("b".into())),
                ]
            );

            conn.execute("BEGIN;").await.unwrap();
            let first = stmt
                .execute_with_params(&[SqliteValue::Text("alpha".into()), SqliteValue::Integer(1)])
                .await
                .unwrap();
            assert_eq!(first, 1);
            assert!(
                conn.memdb_requires_active_txn_reload.get(),
                "prepared UPDATE should re-arm the active-txn MemDatabase dirty bit immediately after the first write in an explicit transaction"
            );
            assert!(
                !conn.memdb_storage_count_shortcuts_safe.get(),
                "prepared UPDATE should stop trusting MemDatabase count shortcuts after the first write in an explicit transaction"
            );
            let second = stmt
                .execute_with_params(&[SqliteValue::Text("beta".into()), SqliteValue::Integer(2)])
                .await
                .unwrap();
            assert_eq!(second, 1);
            assert!(
                conn.memdb_requires_active_txn_reload.get(),
                "prepared UPDATE should leave an already-armed active-txn MemDatabase dirty bit set until a read boundary refreshes it"
            );
            assert_eq!(
                memdb_values(&conn),
                vec![
                    (1, SqliteValue::Text("a".into())),
                    (2, SqliteValue::Text("b".into())),
                ],
                "programless direct UPDATEs should leave the MemDatabase mirror stale until the read boundary reloads active-txn contents"
            );

            let rows = conn
                .query("SELECT id, val FROM prep_ud_memdb_reload_skip ORDER BY id")
                .await
                .unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values().to_vec())
                    .collect::<Vec<_>>(),
                vec![
                    vec![SqliteValue::Integer(1), SqliteValue::Text("alpha".into()),],
                    vec![SqliteValue::Integer(2), SqliteValue::Text("beta".into()),],
                ]
            );
            assert!(
                !conn.memdb_requires_active_txn_reload.get(),
                "the first read boundary after repeated prepared UPDATEs should refresh the MemDatabase and clear the dirty bit"
            );
            assert_eq!(
                memdb_values(&conn),
                vec![
                    (1, SqliteValue::Text("alpha".into())),
                    (2, SqliteValue::Text("beta".into())),
                ]
            );

            conn.execute("ROLLBACK;").await.unwrap();
        });
    }

    fn test_table_root_page(conn: &Connection, table_name: &str) -> i32 {
        let schema = conn.schema.borrow();
        schema
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(table_name))
            .map(|table| table.root_page)
            .unwrap_or_else(|| panic!("table `{table_name}` should exist"))
    }

    fn memdb_column_values(
        conn: &Connection,
        root_page: i32,
        column_index: usize,
    ) -> Vec<(i64, SqliteValue)> {
        let db = conn.db.borrow();
        let table = db
            .get_table(root_page)
            .unwrap_or_else(|| panic!("root page {root_page} should be present in MemDatabase"));
        table
            .iter_rows()
            .map(|(rowid, values)| {
                (
                    rowid,
                    values
                        .get(column_index)
                        .cloned()
                        .unwrap_or(SqliteValue::Null),
                )
            })
            .collect()
    }

    #[test]
    fn test_lazy_dirty_clear_on_commit() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE lazy_dirty_commit (id INTEGER PRIMARY KEY, val TEXT NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO lazy_dirty_commit VALUES (1, 'before'), (2, 'keep');")
                .await
                .unwrap();
            let root_page = test_table_root_page(&conn, "lazy_dirty_commit");

            let stmt = conn
                .prepare("UPDATE lazy_dirty_commit SET val = ?1 WHERE id = ?2")
                .await
                .unwrap();
            assert!(stmt.prepared_update_delete_fast_path.is_some());

            conn.execute("BEGIN;").await.unwrap();
            let affected = stmt
                .execute_with_params(&[SqliteValue::Text("after".into()), SqliteValue::Integer(1)])
                .await
                .unwrap();
            assert_eq!(affected, 1);
            assert!(
                conn.memdb_requires_active_txn_reload.get(),
                "explicit prepared UPDATE should leave the MemDatabase mirror dirty until COMMIT or the next read boundary"
            );
            assert!(
                !conn.memdb_rows_loaded.get(),
                "explicit prepared UPDATE should mark row hydration stale before COMMIT rebuilds the mirror"
            );
            assert!(
                !conn.memdb_storage_count_shortcuts_safe.get(),
                "explicit prepared UPDATE should disable MemDatabase count shortcuts while the mirror is dirty"
            );

            conn.execute("COMMIT;").await.unwrap();
            assert!(
                !conn.memdb_requires_active_txn_reload.get(),
                "COMMIT should clear the deferred active-transaction MemDatabase reload bit"
            );
            assert!(
                conn.memdb_rows_loaded.get(),
                "COMMIT should rebuild the MemDatabase row image for :memory: connections"
            );
            assert!(
                conn.memdb_storage_count_shortcuts_safe.get(),
                "COMMIT should restore exact MemDatabase shortcut safety after rebuilding the mirror"
            );
            assert_eq!(
                memdb_column_values(&conn, root_page, 1),
                vec![
                    (1, SqliteValue::Text("after".into())),
                    (2, SqliteValue::Text("keep".into())),
                ],
                "COMMIT should leave the MemDatabase mirror exact after a lazy dirty explicit UPDATE"
            );

            let rows = conn
                .query("SELECT id, val FROM lazy_dirty_commit ORDER BY id")
                .await
                .unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values().to_vec())
                    .collect::<Vec<_>>(),
                vec![
                    vec![SqliteValue::Integer(1), SqliteValue::Text("after".into()),],
                    vec![SqliteValue::Integer(2), SqliteValue::Text("keep".into()),],
                ]
            );
        });
    }

