    async fn install_prepared_direct_simple_insert_test_table(conn: &Connection) -> i32 {
        let create_sql = "CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);";
        let root_page = conn.allocate_root_page().await.unwrap();
        conn.db.borrow_mut().create_table_at(root_page, 2);
        conn.schema.borrow_mut().push(TableSchema {
            name: "t".to_owned(),
            root_page,
            columns: vec![
                ColumnInfo {
                    name: "id".to_owned(),
                    affinity: 'D',
                    is_ipk: true,
                    type_name: Some("INTEGER".to_owned()),
                    notnull: false,
                    unique: true,
                    default_value: None,
                    strict_type: None,
                    generated_expr: None,
                    generated_stored: None,
                    collation: None,
                    conflict_action: None,
                },
                ColumnInfo {
                    name: "name".to_owned(),
                    affinity: 'B',
                    is_ipk: false,
                    type_name: Some("TEXT".to_owned()),
                    notnull: false,
                    unique: false,
                    default_value: None,
                    strict_type: None,
                    generated_expr: None,
                    generated_stored: None,
                    collation: None,
                    conflict_action: None,
                },
            ],
            indexes: Vec::new(),
            strict: false,
            without_rowid: false,
            primary_key_constraints: Vec::new(),
            foreign_keys: Vec::new(),
            check_constraints: Vec::new(),
        });
        conn.rowid_alias_columns
            .borrow_mut()
            .insert("t".to_owned(), 0);
        conn.rebuild_schema_indices();
        conn.original_ddl_sql
            .borrow_mut()
            .insert("t".to_owned(), create_sql.to_owned());
        conn.insert_sqlite_master_row("table", "t", "t", root_page, create_sql)
            .await
            .unwrap();
        root_page
    }

    #[test]
    fn test_prepared_direct_simple_insert_memory_missing_memdb_table_uses_autocommit_fast_path() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            let root_page = install_prepared_direct_simple_insert_test_table(&conn).await;
            let root = page_number_from_schema_root(root_page, "t", "table").unwrap();
            conn.with_pager_write_txn(async |cx, txn| {
                let mut cursor = Connection::new_pager_btree_cursor(cx, txn, root, true).await?;
                cursor
                    .table_insert(
                        cx,
                        1,
                        &serialize_record(&[SqliteValue::Null, SqliteValue::Text("first".into())]),
                    )
                    .await?;
                cursor
                    .table_insert(
                        cx,
                        2,
                        &serialize_record(&[SqliteValue::Null, SqliteValue::Text("second".into())]),
                    )
                    .await?;
                Ok(())
            })
            .await
            .unwrap();

            *conn.db.borrow_mut() = MemDatabase::new();
            conn.memdb_rows_loaded.set(false);
            conn.memdb_storage_count_shortcuts_safe.set(false);

            let stmt = conn
                .prepare("INSERT INTO t VALUES (NULL, ?1)")
                .await
                .unwrap();

            reset_hot_path_profile();
            let affected = conn
                .execute_prepared_with_params(&stmt, &[SqliteValue::Text("third".into())])
                .await
                .unwrap();
            assert_eq!(affected, 1);

            let profile = hot_path_profile_snapshot();
            assert_eq!(
                profile.prepared_direct_insert_executions, 1,
                "schema-only :memory: state must still execute through the direct prepared-insert body: {profile:?}"
            );

            let rows = conn.query("SELECT id FROM t ORDER BY id").await.unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values()[0].clone())
                    .collect::<Vec<_>>(),
                vec![
                    SqliteValue::Integer(1),
                    SqliteValue::Integer(2),
                    SqliteValue::Integer(3),
                ],
                "schema-only :memory: state must still derive implicit rowids from pager-backed storage"
            );
            assert!(
                conn.db.borrow().get_table(root_page).is_some(),
                "direct INSERT should recreate the missing MemDatabase table placeholder"
            );
        });
    }

