    // ── bd-1dp9.6.7.2.1: Prepared INSERT reuse tests ────────────────────

    #[test]
    fn test_prepared_insert_reuse_multiple_executions() {
        asupersync::test_utils::run_test(|| async {
            // Verify that a single prepared INSERT can be executed multiple times
            // with different parameters, reusing the prepared direct-dispatch plan.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE prep_reuse (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();

            let stmt = conn
                .prepare("INSERT INTO prep_reuse (id, name) VALUES (?1, ?2)")
                .await
                .unwrap();

            // The stmt should have db set (pre-compiled, not placeholder).
            assert!(
                stmt.db.is_some(),
                "simple VALUES INSERT should be pre-compiled with db set"
            );
            assert!(matches!(
                stmt.precompiled_dml(),
                Some(PreparedPrecompiledDml {
                    kind: PreparedDmlKind::Insert,
                    ..
                })
            ));

            for i in 1..=5 {
                let affected = stmt
                    .execute_with_params(&[
                        SqliteValue::Integer(i),
                        SqliteValue::Text(format!("name_{i}").into()),
                    ])
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }

            let rows = conn.query("SELECT COUNT(*) FROM prep_reuse").await.unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(5));

            let rows = conn
                .query("SELECT name FROM prep_reuse ORDER BY id")
                .await
                .unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Text("name_1".into()));
            assert_eq!(rows[4].values()[0], SqliteValue::Text("name_5".into()));
        });
    }

    #[test]
    fn test_prepare_direct_compiled_insert_skips_eager_vdbe_codegen() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE prep_direct_skip (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();

            reset_statement_reuse_measurement(&conn);
            let stmt = conn
                .prepare("INSERT INTO prep_direct_skip VALUES (?1, ('name_' || ?1))")
                .await
                .unwrap();
            let profile_after_prepare = hot_path_profile_snapshot();

            let direct = stmt
                .precompiled_dml()
                .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
                .expect("benchmark-style direct insert should keep direct metadata");
            assert!(
                !Connection::direct_simple_insert_prefers_reusable_table_program(direct),
                "prepared direct insert should stay on the compiled direct lane"
            );
            assert_eq!(
                profile_after_prepare.parser.compiled_cache_misses, 0,
                "direct compiled INSERT prepare should not eagerly compile a VDBE fallback program: {profile_after_prepare:?}"
            );
            assert_eq!(
                stmt.explain(),
                "-- prepared INSERT uses the direct compiled lane; VDBE fallback is compiled lazily"
            );

            let affected = stmt
                .execute_with_params(&[SqliteValue::Integer(1)])
                .await
                .expect("prepared direct insert should execute without a VDBE compile");
            assert_eq!(affected, 1);

            let profile_after_execute = hot_path_profile_snapshot();
            assert_eq!(
                profile_after_execute.parser.compiled_cache_misses, 0,
                "direct compiled INSERT execution should stay off lazy VDBE compile when the direct lane succeeds: {profile_after_execute:?}"
            );
        });
    }

