    // ── bd-#70 plan-cache epoch wedge regression tests ──────────────────

    /// bd-#70 wedge: after a write commits on a *separate* connection backed
    /// by the same database, the local prepared cache must invalidate any
    /// table-backed SELECT template so the next prepare reseeds against the
    /// post-commit visibility (root cause of beads_rust#252 stale reads).
    #[test]
    fn plan_cache_key_changes_after_write_commit() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("plan-cache-epoch.db");
            let db_path = db_path.to_string_lossy().into_owned();

            let reader = Connection::open(&db_path).await.unwrap();
            let writer = Connection::open(&db_path).await.unwrap();

            reader
                .execute("CREATE TABLE plan_cache_epoch (id INTEGER PRIMARY KEY, val TEXT)")
                .await
                .unwrap();
            reader
                .execute("INSERT INTO plan_cache_epoch VALUES (1, 'alpha')")
                .await
                .unwrap();

            let sql = "SELECT val FROM plan_cache_epoch WHERE id = ?1";
            let first = reader.prepare(sql).await.unwrap();
            assert!(
                first.db.is_some(),
                "test requires a table-backed prepared template"
            );
            drop(first);

            // Cache should be populated with the SELECT template.
            let cache_key = reader.prepared_cache_key(sql);
            assert!(
                reader.lookup_prepared_cache(cache_key, sql).is_some(),
                "initial prepare should populate the prepared cache"
            );
            let epoch_before = reader.current_global_commit_seq().get();

            // Write committed on the WRITER connection. The reader has done
            // nothing locally — without the bd-#70 wedge, its cache key for the
            // SELECT would be identical to before the cross-connection commit.
            writer
                .execute("UPDATE plan_cache_epoch SET val = 'beta' WHERE id = 1")
                .await
                .unwrap();

            let epoch_after = reader.current_global_commit_seq().get();
            assert!(
                epoch_after > epoch_before,
                "cross-connection commit must advance the global commit epoch \
             observed by other connections (before={epoch_before}, after={epoch_after})"
            );

            // With the wedge in place, the cached entry's epoch no longer matches
            // the current global epoch and lookup must evict + return None.
            assert!(
                reader.lookup_prepared_cache(cache_key, sql).is_none(),
                "cross-connection write commit must invalidate the cached \
             table-backed SELECT template (bd-#70 wedge)"
            );
        });
    }

    /// bd-#70 wedge: when connection A's plan cache has a SELECT template,
    /// and connection B commits a write against the same database, the next
    /// time connection A consults its prepared cache for that SELECT, the
    /// stale entry must be evicted — re-preparation is the load-bearing
    /// mechanism that lets a fresh memdb image reach the executor (the
    /// precise gap that lets beads_rust#252 ship stale row reads when one
    /// connection writes and another reads through a cached plan).
    ///
    /// This regression locks in the wedge itself (cache-key invalidation
    /// after cross-connection commit). End-to-end stale-read elimination
    /// also depends on the memdb refresh path consulting the bumped epoch,
    /// which is tracked separately in the broader #70 surface.
    #[test]
    fn cross_connection_commit_invalidates_cached_plans() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("plan-cache-cross-conn.db");
            let db_path = db_path.to_string_lossy().into_owned();

            let reader = Connection::open(&db_path).await.unwrap();
            let writer = Connection::open(&db_path).await.unwrap();

            writer
                .execute("CREATE TABLE plan_cache_cross (id INTEGER PRIMARY KEY, val TEXT)")
                .await
                .unwrap();
            writer
                .execute("INSERT INTO plan_cache_cross VALUES (1, 'alpha')")
                .await
                .unwrap();

            let sql = "SELECT val FROM plan_cache_cross WHERE id = ?1";

            // Connection A prepares once — seeds the cache with a table-backed
            // SELECT template tagged with the current commit epoch.
            let first = reader.prepare(sql).await.unwrap();
            assert!(
                first.db.is_some(),
                "test requires a table-backed prepared template"
            );
            drop(first);
            let cache_key = reader.prepared_cache_key(sql);
            assert!(
                reader.lookup_prepared_cache(cache_key, sql).is_some(),
                "prepare on reader must populate the prepared cache"
            );

            // Connection B's write commit advances the shared finalized
            // commit_epoch observed by every connection on this database.
            writer
                .execute("UPDATE plan_cache_cross SET val = 'beta' WHERE id = 1")
                .await
                .unwrap();

            // Without the bd-#70 wedge: `lookup_prepared_cache` would still hit,
            // and re-preparation would not be triggered — the reader could then
            // re-use a SELECT plan bound to its pre-commit row image.
            // With the wedge: the epoch comparison rejects the stale template
            // and the next prepare is a true cache miss.
            assert!(
                reader.lookup_prepared_cache(cache_key, sql).is_none(),
                "cross-connection write commit must evict the cached SELECT \
             template at the next lookup (bd-#70 / beads_rust#252)"
            );

            // Re-preparing the same SQL after the cross-connection commit must
            // produce a fresh template tagged with the new commit_epoch.
            let second = reader.prepare(sql).await.unwrap();
            drop(second);
            let cached_now = reader
                .lookup_prepared_cache(cache_key, sql)
                .expect("reader.prepare should reseed the prepared cache");
            let current_epoch = reader.current_global_commit_seq().get();
            assert_eq!(
                cached_now.template.commit_epoch, current_epoch,
                "reseeded template must capture the post-commit global epoch \
             so subsequent reads see a coherent plan boundary"
            );
        });
    }

    /// bd-#70 wedge extension (memdb-refresh + epoch coupling).
    ///
    /// When connection B commits a write against a file-backed database,
    /// connection A's first observation of the new pager publication
    /// (driven by `refresh_memdb_if_stale_*` and friends) must raise A's
    /// finalized commit clock floor so the plan-cache epoch lookup observes
    /// the cross-process commit. Without that coupling, A's
    /// `current_global_commit_seq` stays pinned at its pre-commit value,
    /// `matches_cache_identity` returns true for the stale template, and
    /// the plan-cache wedge silently no-ops — the precise gap responsible
    /// for `swarm_writer_harness::no_wrong_row_returns` continuing to fail
    /// after the original 6939d77e plan-cache wedge landed.
    #[test]
    fn cross_connection_commit_advances_reader_commit_clock_floor() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("memdb-refresh-epoch.db");
            let db_path = db_path.to_string_lossy().into_owned();

            let reader = Connection::open(&db_path).await.unwrap();
            let writer = Connection::open(&db_path).await.unwrap();

            writer
                .execute("CREATE TABLE memdb_refresh_epoch (id INTEGER PRIMARY KEY, val TEXT)")
                .await
                .unwrap();
            writer
                .execute("INSERT INTO memdb_refresh_epoch VALUES (1, 'alpha')")
                .await
                .unwrap();

            // Force the reader to observe the writer's pre-existing schema and
            // initial row image. Whatever epoch it lands on after this is our
            // baseline.
            reader.execute("SELECT 1").await.unwrap();
            let epoch_before = reader.current_global_commit_seq().get();

            // Cross-connection write commit on writer. Reader has issued no
            // statements in between — its local `stable_commit_seq` cannot
            // advance from local commits.
            writer
                .execute("UPDATE memdb_refresh_epoch SET val = 'beta' WHERE id = 1")
                .await
                .unwrap();

            // Reader's *next* statement is what drives the cross-process refresh
            // path. Pre-fix, this read returned without raising the reader's
            // `stable_commit_seq` (the floor stayed at `epoch_before`), so the
            // plan-cache identity check could never observe the writer's commit.
            // Post-fix, the memdb refresh path calls
            // `set_memdb_visible_commit_seq_from_publication`, which raises the
            // floor via `align_commit_clock_floor`.
            let row = reader
                .query_row_with_params(
                    "SELECT val FROM memdb_refresh_epoch WHERE id = ?1",
                    &[SqliteValue::Integer(1)],
                )
                .await
                .unwrap();
            assert_eq!(
                row.values()[0],
                SqliteValue::Text("beta".into()),
                "reader must see the post-commit value once the memdb refresh \
             path runs (this is the load-bearing data-freshness guarantee)"
            );

            let epoch_after = reader.current_global_commit_seq().get();
            assert!(
                epoch_after > epoch_before,
                "reader's finalized commit clock floor must advance past the \
             cross-connection commit so the plan-cache epoch wedge can \
             observe the new visibility (before={epoch_before}, \
             after={epoch_after})"
            );
        });
    }

