            assert_eq!(rows[0].values()[1], SqliteValue::Text("from_conn2".into()));
            assert_eq!(rows[1].values()[0], SqliteValue::Integer(2));
            assert_eq!(rows[1].values()[1], SqliteValue::Text("from_conn1".into()));

