    /// IMPL-9a regression guard: build-on-first-consult is disabled because it
    /// adds a full-table scan to the first direct-simple DELETE/UPDATE of an
    /// existing table. Absent rowids must still be handled correctly by the
    /// normal B-tree lookup path, with no QF short-circuit recorded.
    #[test]
    fn test_quotient_filter_disabled_does_not_short_circuit_absent_rowids_on_delete() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE qf_absent (id INTEGER PRIMARY KEY, val INTEGER NOT NULL);")
                .await
                .unwrap();
            conn.execute("BEGIN").await.unwrap();
            let ins = conn
                .prepare("INSERT INTO qf_absent VALUES (?1, ?1)")
                .await
                .unwrap();
            for i in 0..100i64 {
                ins.execute_with_params(&[SqliteValue::Integer(i)])
                    .await
                    .unwrap();
            }
            conn.execute("COMMIT").await.unwrap();

            // Reset the short-circuit counter so the INSERT-side maintenance
            // path (which never consults) can't inflate the count.
            conn.reset_quotient_filter_short_circuit_count();

            // Direct-simple DELETE is gated on explicit txn state. Wrap the
            // 100 phantom DELETEs in a single BEGIN/COMMIT so every one
            // takes the direct fast path (the VDBE fallback doesn't consult
            // the QF).
            conn.execute("BEGIN").await.unwrap();
            let del = conn
                .prepare("DELETE FROM qf_absent WHERE id = ?1")
                .await
                .unwrap();
            for i in 10_000..10_100i64 {
                let affected = del
                    .execute_with_params(&[SqliteValue::Integer(i)])
                    .await
                    .unwrap();
                assert_eq!(affected, 0, "absent rowid {i} cannot delete any rows");
            }
            conn.execute("COMMIT").await.unwrap();

            let short_circuits = conn.quotient_filter_short_circuit_count();
            assert_eq!(
                short_circuits, 0,
                "disabled QF consultation must not short-circuit absent deletes"
            );

            // Row count unaffected by the phantom DELETEs.
            let rows = conn.query("SELECT COUNT(*) FROM qf_absent").await.unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(100));
        });
    }

    /// IMPL-9a regression guard: a repeated DELETE of a rowid removed earlier
    /// in the same transaction still returns the correct affected-row count
    /// when QF consultation is dormant.
    #[test]
    fn test_quotient_filter_disabled_delete_then_redelete_uses_btree_lookup() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE qf_del (id INTEGER PRIMARY KEY, val INTEGER NOT NULL);")
                .await
                .unwrap();
            // Seed the table and commit so the first DELETE removes a real row.
            conn.execute("INSERT INTO qf_del VALUES (42, 42);")
                .await
                .unwrap();

            // Direct-simple DELETE requires an explicit transaction.
            conn.execute("BEGIN").await.unwrap();
            let del = conn
                .prepare("DELETE FROM qf_del WHERE id = ?1")
                .await
                .unwrap();
            // First DELETE removes 42 through the normal direct-simple path.
            let affected = del
                .execute_with_params(&[SqliteValue::Integer(42)])
                .await
                .unwrap();
            assert_eq!(affected, 1, "first DELETE should remove the row");

            conn.reset_quotient_filter_short_circuit_count();

            // Second DELETE of the same rowid still uses the normal lookup path
            // while quotient-filter consultation is disabled.
            let affected = del
                .execute_with_params(&[SqliteValue::Integer(42)])
                .await
                .unwrap();
            assert_eq!(affected, 0, "row is already gone; nothing to delete");
            assert_eq!(
                conn.quotient_filter_short_circuit_count(),
                0,
                "disabled QF consultation must leave the repeated DELETE on the normal lookup path"
            );
            conn.execute("COMMIT").await.unwrap();
        });
    }

    /// IMPL-9a regression guard: INSERT under a transaction, ROLLBACK the
    /// transaction, then DELETE the same rowid. With quotient-filter
    /// consultation disabled, no stale filter state may short-circuit the
    /// post-rollback lookup.
    #[test]
    fn test_quotient_filter_rollback_forces_reseed() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE qf_rb (id INTEGER PRIMARY KEY, val INTEGER NOT NULL);")
                .await
                .unwrap();

            // A missing DELETE must not create or consult a filter while
            // build-on-first-consult is disabled.
            let del = conn
                .prepare("DELETE FROM qf_rb WHERE id = ?1")
                .await
                .unwrap();
            del.execute_with_params(&[SqliteValue::Integer(999)])
                .await
                .unwrap();

            // Start a transaction and INSERT rowid=7. The dormant filter
            // maintenance path must remain a no-op.
            conn.execute("BEGIN").await.unwrap();
            let ins = conn
                .prepare("INSERT INTO qf_rb VALUES (?1, ?1)")
                .await
                .unwrap();
            ins.execute_with_params(&[SqliteValue::Integer(7)])
                .await
                .unwrap();

            // Rollback — discard the insert. No dormant filter entry should carry
            // transaction-local state across the rollback.
            conn.execute("ROLLBACK").await.unwrap();

            // Peek at the filter state directly — if future code creates entries,
            // rollback must still clear transaction-local modification state.
            {
                let filters = conn.quotient_filters.borrow();
                for entry in filters.values() {
                    assert!(
                        !entry.modified_in_txn,
                        "rollback must clear modified_in_txn on every filter entry"
                    );
                }
            }

            conn.reset_quotient_filter_short_circuit_count();

            // DELETE rowid=7 post-rollback. The row is absent in committed state,
            // so the normal lookup must return 0 without corrupting the B-tree.
            let affected = del
                .execute_with_params(&[SqliteValue::Integer(7)])
                .await
                .unwrap();
            assert_eq!(
                affected, 0,
                "post-rollback DELETE of the never-committed rowid must affect 0 rows"
            );

            // Committed row count is zero (INSERT was rolled back).
            let rows = conn.query("SELECT COUNT(*) FROM qf_rb").await.unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(0));
        });
    }

    /// Verify the direct fast path can update non-indexed columns on indexed
