    #[test]
    fn test_file_backed_single_writer_busy_wait_skips_prebegin_refresh_work() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("single_writer_busy_wait_refresh_skip.db");
            let db_path_str = db_path.to_str().unwrap();

            let holder = Connection::open(db_path_str).await.unwrap();
            holder
                .execute("CREATE TABLE t (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            holder
                .execute("PRAGMA fsqlite.concurrent_mode=OFF;")
                .await
                .unwrap();
            holder.execute("BEGIN IMMEDIATE;").await.unwrap();

            let waiter = Connection::open(db_path_str).await.unwrap();
            waiter
                .execute("PRAGMA fsqlite.concurrent_mode=OFF;")
                .await
                .unwrap();
            waiter.execute("PRAGMA busy_timeout=1;").await.unwrap();

            let cx = waiter.op_cx().unwrap();
            reset_hot_path_profile();
            let err = waiter
                .ensure_autocommit_txn_mode_with_cx(TransactionMode::Immediate, &cx, None)
                .await
                .expect_err(
                    "contending single-writer autocommit begin should time out with SQLITE_BUSY",
                );
            assert!(
                matches!(err, FrankenError::Busy),
                "expected SQLITE_BUSY from single-writer begin handoff timeout, got {err}"
            );
            let profile = hot_path_profile_snapshot();
            assert_eq!(
                profile.pager_publication_refreshes, 0,
                "single-writer busy wait should not bind fresh pager publications on each retry: {profile:?}"
            );
            assert_eq!(
                profile.memdb_refresh_count, 0,
                "single-writer busy wait should not reload MemDB while merely waiting for the writer baton: {profile:?}"
            );
            assert!(
                waiter.active_txn.borrow().is_none(),
                "timed-out single-writer waiter must not retain an active pager transaction"
            );

            holder.execute("ROLLBACK;").await.unwrap();
        });
    }

    #[test]
    fn test_file_backed_single_writer_begin_reloads_stale_memdb_from_open_txn() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("single_writer_begin_stale_reload.db");
            let db_path = db_path.to_string_lossy().into_owned();
            let conn_a = Connection::open(&db_path).await.unwrap();
            let conn_b = Connection::open(&db_path).await.unwrap();
            conn_a.set_reject_mem_fallback(true);
            conn_a.set_strict_mem_fallback_rejection(true);
            conn_b.set_reject_mem_fallback(true);
            conn_b.set_strict_mem_fallback_rejection(true);
            conn_a
                .execute("PRAGMA fsqlite.concurrent_mode=OFF;")
                .await
                .unwrap();
            conn_b
                .execute("PRAGMA fsqlite.concurrent_mode=OFF;")
                .await
                .unwrap();
            conn_a
                .execute("CREATE TABLE sw_begin_reload (id INTEGER PRIMARY KEY, val TEXT);")
                .await
                .unwrap();

            let initial_rows = conn_b
                .query("SELECT val FROM sw_begin_reload ORDER BY id;")
                .await
                .unwrap();
            assert!(initial_rows.is_empty(), "fresh table should start empty");

            conn_a
                .execute("INSERT INTO sw_begin_reload (id, val) VALUES (1, 'alpha');")
                .await
                .unwrap();
            if conn_a.retained_autocommit_txn.borrow().is_some() {
                // This regression is about cross-connection committed visibility,
                // not same-connection retained-batch semantics. Flush conn_a's
                // parked autocommit write so conn_b begins against a durable
                // external commit.
                let cx = conn_a.op_cx().unwrap();
                conn_a.flush_retained_autocommit_txn(&cx).await.unwrap();
            }

            conn_b.execute("BEGIN;").await.unwrap();
            let rows = conn_b
                .query("SELECT val FROM sw_begin_reload ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(
                rows.len(),
                1,
                "serialized BEGIN should see the external commit"
            );
            assert_eq!(rows[0].values()[0], SqliteValue::Text("alpha".into()));
            conn_b.execute("ROLLBACK;").await.unwrap();
        });
    }

