    #[test]
    fn test_statement_reuse_regression_ad_hoc_hot_path_metrics_and_row_counts() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE sr_hot (id INTEGER PRIMARY KEY, val TEXT);")
                .await
                .unwrap();

            let insert_sql = "INSERT INTO sr_hot (id, val) VALUES (?1, ?2)";
            for id in 1_i64..=4 {
                let affected = conn
                    .execute_with_params(
                        insert_sql,
                        &[
                            SqliteValue::Integer(id),
                            SqliteValue::Text(format!("v{id}").into()),
                        ],
                    )
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }

            let select_sql = "SELECT val FROM sr_hot WHERE id = ?1";
            for id in 1_i64..=4 {
                let row = conn
                    .query_row_with_params(select_sql, &[SqliteValue::Integer(id)])
                    .await
                    .unwrap();
                assert_eq!(row.values()[0], SqliteValue::Text(format!("v{id}").into()));
            }

            let update_sql = "UPDATE sr_hot SET val = ?1 WHERE id = ?2";
            for id in 1_i64..=4 {
                let affected = conn
                    .execute_with_params(
                        update_sql,
                        &[
                            SqliteValue::Text(format!("u{id}").into()),
                            SqliteValue::Integer(id),
                        ],
                    )
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }
            for id in 1_i64..=4 {
                let row = conn
                    .query_row_with_params(select_sql, &[SqliteValue::Integer(id)])
                    .await
                    .unwrap();
                assert_eq!(row.values()[0], SqliteValue::Text(format!("u{id}").into()));
            }

            let delete_sql = "DELETE FROM sr_hot WHERE id = ?1";
            for id in 1_i64..=4 {
                let affected = conn
                    .execute_with_params(delete_sql, &[SqliteValue::Integer(id)])
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }
            let remaining = conn.query_row("SELECT COUNT(*) FROM sr_hot").await.unwrap();
            assert_eq!(remaining.values()[0], SqliteValue::Integer(0));

            let profile = hot_path_profile_snapshot();
            assert!(
                profile.parser.parse_cache_hits >= 8,
                "expected repeated ad-hoc execution to hit parse cache: {profile:?}"
            );
            assert!(
                profile.parser.prepared_cache_hits >= 12,
                "expected repeated ad-hoc execution to reuse prepared templates after warmup: {profile:?}"
            );
            assert!(
                profile.parser.rewrite_calls <= 5,
                "ad-hoc prepared reuse should bound rewrite work to one pass per statement family (INSERT, SELECT, UPDATE, DELETE, and the final COUNT(*) verification query = five families): {profile:?}"
            );
            assert!(
                profile.parser.compiled_cache_misses <= 5,
                "ad-hoc prepared reuse should bound compilation work to one miss per statement family, including the final COUNT(*) verification query: {profile:?}"
            );
        });
    }

    #[test]
    fn test_statement_paths_take_one_background_status_check_per_operation() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE bg_status (id INTEGER PRIMARY KEY, val TEXT);")
                .await
                .unwrap();

            let insert_stmt = conn
                .prepare("INSERT INTO bg_status (id, val) VALUES (?1, ?2)")
                .await
                .unwrap();
            let select_stmt = conn
                .prepare("SELECT val FROM bg_status WHERE id = ?1")
                .await
                .unwrap();

            reset_hot_path_profile();
            for id in 1_i64..=4 {
                let affected = insert_stmt
                    .execute_with_params(&[
                        SqliteValue::Integer(id),
                        SqliteValue::Text(format!("v{id}").into()),
                    ])
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }
            let prepared_insert_profile = hot_path_profile_snapshot();
            assert!(
                prepared_insert_profile.background_status_time_ns > 0,
                "prepared INSERT should record background-status time alongside the gate count: {prepared_insert_profile:?}"
            );
            assert_eq!(
                prepared_insert_profile.statement_dispatch_background_gates, 0,
                "prepared INSERT should bypass the legacy execute_statement() background-status gate: {prepared_insert_profile:?}"
            );

            reset_hot_path_profile();
            for id in 1_i64..=4 {
                let rows = select_stmt
                    .query_with_params(&[SqliteValue::Integer(id)])
                    .await
                    .unwrap();
                assert_eq!(rows.len(), 1);
                assert_eq!(
                    rows[0].values()[0],
                    SqliteValue::Text(format!("v{id}").into())
                );
            }
            let prepared_select_profile = hot_path_profile_snapshot();
            assert!(
                prepared_select_profile.background_status_time_ns > 0,
                "prepared SELECT should record background-status time alongside the gate count: {prepared_select_profile:?}"
            );
            assert_eq!(
                prepared_select_profile.statement_dispatch_background_gates, 0,
                "prepared SELECT should bypass the legacy execute_statement() background-status gate: {prepared_select_profile:?}"
            );

            reset_hot_path_profile();
            for id in 10_i64..=13 {
                let affected = conn
                    .execute_with_params(
                        "INSERT INTO bg_status (id, val) VALUES (?1, ?2)",
                        &[
                            SqliteValue::Integer(id),
                            SqliteValue::Text(format!("adhoc{id}").into()),
                        ],
                    )
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }
            let ad_hoc_insert_profile = hot_path_profile_snapshot();
            assert_eq!(
                ad_hoc_insert_profile.statement_dispatch_background_gates, 0,
                "ad-hoc INSERT should bypass the legacy execute_statement() background-status gate after prepared reuse: {ad_hoc_insert_profile:?}"
            );
            assert!(
                ad_hoc_insert_profile.parser.prepared_cache_hits >= 3,
                "ad-hoc INSERT should reuse prepared templates after warmup: {ad_hoc_insert_profile:?}"
            );

            reset_hot_path_profile();
            for id in 1_i64..=4 {
                let row = conn
                    .query_row_with_params(
                        "SELECT val FROM bg_status WHERE id = ?1",
                        &[SqliteValue::Integer(id)],
                    )
                    .await
                    .unwrap();
                assert_eq!(row.values()[0], SqliteValue::Text(format!("v{id}").into()));
            }
            let ad_hoc_select_profile = hot_path_profile_snapshot();
            assert_eq!(
                ad_hoc_select_profile.statement_dispatch_background_gates, 0,
                "ad-hoc SELECT should bypass the legacy execute_statement() background-status gate: {ad_hoc_select_profile:?}"
            );
            assert!(
                ad_hoc_select_profile.parser.prepared_cache_hits >= 3,
                "ad-hoc SELECT should reuse prepared templates after warmup: {ad_hoc_select_profile:?}"
            );

            reset_hot_path_profile();
            for id in 10_i64..=13 {
                let affected = conn
                    .execute_with_params(
                        "UPDATE bg_status SET val = ?1 WHERE id = ?2",
                        &[
                            SqliteValue::Text(format!("upd{id}").into()),
                            SqliteValue::Integer(id),
                        ],
                    )
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }
            let ad_hoc_update_profile = hot_path_profile_snapshot();
            assert_eq!(
                ad_hoc_update_profile.statement_dispatch_background_gates, 0,
                "ad-hoc UPDATE should bypass the legacy execute_statement() background-status gate after prepared reuse: {ad_hoc_update_profile:?}"
            );
            assert!(
                ad_hoc_update_profile.parser.prepared_cache_hits >= 3,
                "ad-hoc UPDATE should reuse prepared templates after warmup: {ad_hoc_update_profile:?}"
            );

            reset_hot_path_profile();
            for id in 10_i64..=13 {
                let affected = conn
                    .execute_with_params(
                        "DELETE FROM bg_status WHERE id = ?1",
                        &[SqliteValue::Integer(id)],
                    )
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }
            let ad_hoc_delete_profile = hot_path_profile_snapshot();
            assert_eq!(
                ad_hoc_delete_profile.statement_dispatch_background_gates, 0,
                "ad-hoc DELETE should bypass the legacy execute_statement() background-status gate after prepared reuse: {ad_hoc_delete_profile:?}"
            );
            assert!(
                ad_hoc_delete_profile.parser.prepared_cache_hits >= 3,
                "ad-hoc DELETE should reuse prepared templates after warmup: {ad_hoc_delete_profile:?}"
            );
        });
    }

    #[test]
    fn test_statement_reuse_regression_prepared_trigger_constraint_row_count() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE sr_main (id INTEGER PRIMARY KEY, val TEXT UNIQUE);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE sr_audit (main_id INTEGER NOT NULL);")
                .await
                .unwrap();
            conn.execute(
                "CREATE TRIGGER sr_after_insert AFTER INSERT ON sr_main \
             BEGIN INSERT INTO sr_audit(main_id) VALUES (NEW.id); END;",
            )
            .await
            .unwrap();

            let stmt = conn
                .prepare("INSERT INTO sr_main (id, val) VALUES (?1, ?2)")
                .await
                .unwrap();

            assert_eq!(
                stmt.execute_with_params(&[
                    SqliteValue::Integer(1),
                    SqliteValue::Text("alpha".into()),
                ])
                .await
                .unwrap(),
                1
            );
            assert_eq!(
                stmt.execute_with_params(&[
                    SqliteValue::Integer(2),
                    SqliteValue::Text("beta".into()),
                ])
                .await
                .unwrap(),
                1
            );

            let err = stmt
                .execute_with_params(&[SqliteValue::Integer(3), SqliteValue::Text("beta".into())])
                .await
                .expect_err("duplicate UNIQUE value should fail");
            let err_text = err.to_string();
            assert!(
                err_text.contains("UNIQUE constraint failed")
                    || err_text.contains("constraint failed"),
                "unexpected constraint error: {err_text}"
            );

            assert_eq!(
                stmt.execute_with_params(&[
                    SqliteValue::Integer(3),
                    SqliteValue::Text("gamma".into()),
                ])
                .await
                .unwrap(),
                1
            );

            let main_count = conn
                .query_row("SELECT COUNT(*) FROM sr_main;")
                .await
                .unwrap();
            let audit_count = conn
                .query_row("SELECT COUNT(*) FROM sr_audit;")
                .await
                .unwrap();
            assert_eq!(main_count.values()[0], SqliteValue::Integer(3));
            assert_eq!(audit_count.values()[0], SqliteValue::Integer(3));
        });
    }

    #[test]
    fn test_statement_reuse_regression_binding_mismatch_does_not_poison_reuse() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE sr_bind (id INTEGER PRIMARY KEY, val TEXT);")
                .await
                .unwrap();

            let stmt = conn
                .prepare("INSERT INTO sr_bind (id, val) VALUES (?1, ?2)")
                .await
                .unwrap();
            let err = stmt
                .execute_with_params(&[SqliteValue::Integer(1)])
                .await
                .expect_err("missing prepared parameter should fail");
            assert!(matches!(err, FrankenError::OutOfRange { .. }));

            assert_eq!(
                stmt.execute_with_params(&[
                    SqliteValue::Integer(1),
                    SqliteValue::Text("prepared-ok".into()),
                ])
                .await
                .unwrap(),
                1
            );

            let err = conn
                .execute_with_params(
                    "INSERT INTO sr_bind (id, val) VALUES (?1, ?2)",
                    &[SqliteValue::Integer(2)],
                )
                .await
                .expect_err("missing ad-hoc parameter should fail");
            assert!(matches!(err, FrankenError::OutOfRange { .. }));

            assert_eq!(
                conn.execute_with_params(
                    "INSERT INTO sr_bind (id, val) VALUES (?1, ?2)",
                    &[
                        SqliteValue::Integer(2),
                        SqliteValue::Text("adhoc-ok".into()),
                    ],
                )
                .await
                .unwrap(),
                1
            );

            let rows = conn
                .query("SELECT val FROM sr_bind ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(rows[0].values()[0], SqliteValue::Text("prepared-ok".into()));
            assert_eq!(rows[1].values()[0], SqliteValue::Text("adhoc-ok".into()));
        });
    }

