    #[test]
    fn test_parse_cache_hash_match_requires_sql_equality() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE pc_hash (id INTEGER PRIMARY KEY, a TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO pc_hash VALUES (1, 'alpha');")
                .await
                .unwrap();

            let target_sql = "SELECT a FROM pc_hash";
            let key = Connection::sql_hash(target_sql);
            let cookie = *conn.schema_cookie.borrow();
            *conn.parse_cache_cookie.borrow_mut() = cookie;
            conn.parse_cache.borrow_mut().put(
                key,
                std::sync::Arc::new(ParseCacheEntry {
                    sql: "SELECT 1".to_owned(),
                    statement: Arc::new(parse_single_statement("SELECT 1").unwrap()),
                }),
            );

            // A hash-key match with different SQL text must not return wrong AST.
            let rows = conn.query(target_sql).await.unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Text("alpha".into()));

            let mut cache = conn.parse_cache.borrow_mut();
            let entry = cache
                .get(&key)
                .expect("cache entry should be refreshed for target SQL");
            assert_eq!(entry.sql, target_sql);
        });
    }

    #[test]
    fn test_parse_cache_drop_table_invalidates() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE pc5 (id INTEGER PRIMARY KEY, v TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO pc5 VALUES (1, 'val');")
                .await
                .unwrap();

            // Populate cache.
            let rows = conn.query("SELECT v FROM pc5").await.unwrap();
            assert_eq!(rows.len(), 1);

            // Drop + recreate with different schema.
            conn.execute("DROP TABLE pc5;").await.unwrap();
            conn.execute("CREATE TABLE pc5 (id INTEGER PRIMARY KEY, v TEXT, extra INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO pc5 VALUES (1, 'new', 42);")
                .await
                .unwrap();

            // Cache must be invalidated: fresh parse succeeds.
            let rows = conn.query("SELECT v FROM pc5").await.unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Text("new".into()));
        });
    }

