    #[test]
    fn test_compiled_planner_directives_decline_incompatible_collations() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE plan_eq_collation (a TEXT COLLATE NOCASE);")
                .await
                .unwrap();
            conn.execute(
                "CREATE INDEX idx_plan_eq_binary \
                 ON plan_eq_collation(a COLLATE BINARY);",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO plan_eq_collation VALUES ('X');")
                .await
                .unwrap();
            let equality = conn
                .query("SELECT a FROM plan_eq_collation WHERE a = 'x';")
                .await
                .unwrap();
            assert_eq!(equality.len(), 1);
            assert_eq!(equality[0].values(), &[SqliteValue::Text("X".into())]);
            for sql in [
                "SELECT a FROM plan_eq_collation WHERE a = ('x' COLLATE NOCASE);",
                "SELECT a FROM plan_eq_collation WHERE ('x' COLLATE NOCASE) = a;",
            ] {
                let explicit = conn.query(sql).await.unwrap();
                assert_eq!(explicit.len(), 1, "unexpected rows for `{sql}`");
                assert_eq!(explicit[0].values(), &[SqliteValue::Text("X".into())]);
            }

            conn.execute("CREATE TABLE plan_range_collation (a TEXT);")
                .await
                .unwrap();
            conn.execute(
                "CREATE INDEX idx_plan_range_nocase \
                 ON plan_range_collation(a COLLATE NOCASE);",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO plan_range_collation VALUES ('A'), ('a');")
                .await
                .unwrap();
            let range = conn
                .query("SELECT a FROM plan_range_collation WHERE a < 'a';")
                .await
                .unwrap();
            assert_eq!(range.len(), 1);
            assert_eq!(range[0].values(), &[SqliteValue::Text("A".into())]);
            for sql in [
                "SELECT a FROM plan_range_collation \
                 WHERE a < ('a' COLLATE NOCASE);",
                "SELECT a FROM plan_range_collation \
                 WHERE ('a' COLLATE NOCASE) > a;",
            ] {
                let explicit = conn.query(sql).await.unwrap();
                assert!(explicit.is_empty(), "unexpected rows for `{sql}`");
            }

            let glob = conn
                .query("SELECT a FROM plan_range_collation WHERE a GLOB 'A*';")
                .await
                .unwrap();
            assert_eq!(glob.len(), 1);
            assert_eq!(glob[0].values(), &[SqliteValue::Text("A".into())]);
        });
    }

    #[test]
    fn test_partial_index_directive_declines_replaced_predicate_function() {
        use fsqlite_func::ScalarFunction;

        struct AlwaysOneLength;

        impl ScalarFunction for AlwaysOneLength {
            fn invoke(&self, _args: &[SqliteValue]) -> Result<SqliteValue> {
                Ok(SqliteValue::Integer(1))
            }

            fn num_args(&self) -> i32 {
                1
            }

            fn name(&self) -> &str {
                "length"
            }
        }

        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE plan_partial_function (a TEXT);")
                .await
                .unwrap();
            conn.execute(
                "CREATE INDEX idx_plan_partial_function \
                 ON plan_partial_function(a) WHERE length(a) = 1;",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO plan_partial_function VALUES ('x'), ('xx');")
                .await
                .unwrap();
            conn.register_deterministic_scalar_function(AlwaysOneLength);

            let rows = conn
                .query(
                    "SELECT a FROM plan_partial_function \
                     WHERE a = 'xx' AND length(a) = 1;",
                )
                .await
                .unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].values(), &[SqliteValue::Text("xx".into())]);
        });
    }

