    #[test]
    fn test_planner_select_directive_partial_expression_index_fails_closed() {
        let mut schema = vec![TableSchema {
            name: "plan_expr".to_owned(),
            root_page: 2,
            columns: vec![
                ColumnInfo::basic("name", 'B', false),
                ColumnInfo::basic("active", 'D', false),
            ],
            indexes: vec![IndexSchema {
                name: "idx_plan_expr_active_lower_name".to_owned(),
                root_page: 3,
                columns: Vec::new(),
                key_expressions: vec!["lower(name)".to_owned()],
                key_sort_directions: vec![],
                where_clause: Some("active = 1".to_owned()),
                is_unique: false,
                key_collations: vec![],
                conflict_action: None,
            }],
            strict: false,
            without_rowid: false,
            primary_key_constraints: Vec::new(),
            foreign_keys: Vec::new(),
            check_constraints: Vec::new(),
        }];

        let missing_predicate =
            parse_select_statement("SELECT name FROM plan_expr WHERE lower(name) = ?1");
        let directive = Connection::planner_select_directive(&missing_predicate, &schema)
            .expect("an unusable partial index should fall back to a table-scan directive");
        assert_eq!(
            directive.access_kind,
            PlannerSelectAccessKind::FullTableScan
        );
        assert_eq!(directive.index_name, None);

        schema[0].indexes[0].where_clause = Some("active =".to_owned());
        let corrupt_predicate = parse_select_statement(
            "SELECT name FROM plan_expr WHERE lower(name) = ?1 AND active = 1",
        );
        let directive = Connection::planner_select_directive(&corrupt_predicate, &schema)
            .expect("an unparseable partial predicate should omit the index, not the query plan");
        assert_eq!(
            directive.access_kind,
            PlannerSelectAccessKind::FullTableScan
        );
        assert_eq!(directive.index_name, None);
    }

