    #[test]
    fn test_expression_index_probe_extractors_commute_and_fail_closed() {
        let table_name = "plan_expr";
        let table_alias = Some("p");
        let index = IndexSchema {
            name: "idx_plan_expr_lower_name".to_owned(),
            root_page: 3,
            columns: Vec::new(),
            key_expressions: vec!["lower(name)".to_owned()],
            key_sort_directions: vec![],
            where_clause: Some("active = 1".to_owned()),
            is_unique: false,
            key_collations: vec![],
            conflict_action: None,
        };

        let commuted_equality =
            fsqlite_parser::expr::parse_expr("active = 1 AND ?1 = lower(name)").unwrap();
        let equality_target = planner_directive_expression_index_equality_target(
            Some(&commuted_equality),
            &index,
            table_name,
            table_alias,
        );
        assert_eq!(
            equality_target,
            Some(fsqlite_parser::expr::parse_expr("?1").unwrap())
        );

        let commuted_range = fsqlite_parser::expr::parse_expr(
            "active = 1 AND ?1 < lower(name) AND ?2 > lower(name)",
        )
        .unwrap();
        let range_target = planner_directive_expression_index_range_target(
            Some(&commuted_range),
            &index,
            table_name,
            table_alias,
        )
        .expect("commuted range bounds beside a residual conjunct must be extracted");
        assert_eq!(
            range_target.lower,
            Some(PlannerIndexRangeBound {
                expr: fsqlite_parser::expr::parse_expr("?1").unwrap(),
                inclusive: false,
            })
        );
        assert_eq!(
            range_target.upper,
            Some(PlannerIndexRangeBound {
                expr: fsqlite_parser::expr::parse_expr("?2").unwrap(),
                inclusive: false,
            })
        );

        let conditional_equality =
            fsqlite_parser::expr::parse_expr("lower(name) = ?1 OR active = 1").unwrap();
        let conditional_equality_target = planner_directive_expression_index_equality_target(
            Some(&conditional_equality),
            &index,
            table_name,
            table_alias,
        );
        assert_eq!(
            conditional_equality_target, None,
            "an equality hidden under OR is not a mandatory probe"
        );

        let unproven_equality_residual =
            fsqlite_parser::expr::parse_expr("lower(name) = ?1 AND active = 1 AND tenant_id = 7")
                .unwrap();
        assert_eq!(
            planner_directive_expression_index_equality_target(
                Some(&unproven_equality_residual),
                &index,
                table_name,
                table_alias,
            ),
            None,
            "a residual not guaranteed by the partial index must fail closed"
        );

        let conditional_range =
            fsqlite_parser::expr::parse_expr("lower(name) > ?1 OR active = 1").unwrap();
        assert_eq!(
            planner_directive_expression_index_range_target(
                Some(&conditional_range),
                &index,
                table_name,
                table_alias,
            ),
            None,
            "a range hidden under OR is not a mandatory probe"
        );

        let duplicate_lower_bounds =
            fsqlite_parser::expr::parse_expr("lower(name) > ?1 AND lower(name) >= ?2").unwrap();
        let duplicate_range_target = planner_directive_expression_index_range_target(
            Some(&duplicate_lower_bounds),
            &index,
            table_name,
            table_alias,
        );
        assert_eq!(
            duplicate_range_target, None,
            "multiple bounds for one slot must fail closed until bound ordering is available"
        );

        let unproven_range_residual =
            fsqlite_parser::expr::parse_expr("lower(name) > ?1 AND active = 1 AND tenant_id = 7")
                .unwrap();
        assert_eq!(
            planner_directive_expression_index_range_target(
                Some(&unproven_range_residual),
                &index,
                table_name,
                table_alias,
            ),
            None,
            "an expression range may ignore only the predicate guaranteed by the partial index"
        );

        let qualified_equality =
            fsqlite_parser::expr::parse_expr("p.ACTIVE = 1 AND lower(p.Name) = ?1").unwrap();
        assert_eq!(
            planner_directive_expression_index_equality_target(
                Some(&qualified_equality),
                &index,
                table_name,
                table_alias,
            ),
            Some(fsqlite_parser::expr::parse_expr("?1").unwrap()),
            "a local alias and identifier case must not hide an expression-index probe"
        );

        let qualified_range = fsqlite_parser::expr::parse_expr(
            "p.active = 1 AND lower(p.NAME) >= ?1 AND lower(p.name) < ?2",
        )
        .unwrap();
        let range_target = planner_directive_expression_index_range_target(
            Some(&qualified_range),
            &index,
            table_name,
            table_alias,
        )
        .expect("qualified local expression-index bounds must be extracted");
        assert_eq!(
            range_target.lower,
            Some(PlannerIndexRangeBound {
                expr: fsqlite_parser::expr::parse_expr("?1").unwrap(),
                inclusive: true,
            })
        );
        assert_eq!(
            range_target.upper,
            Some(PlannerIndexRangeBound {
                expr: fsqlite_parser::expr::parse_expr("?2").unwrap(),
                inclusive: false,
            })
        );

        let negative_numeric_range =
            fsqlite_parser::expr::parse_expr("p.active = 1 AND lower(p.name) >= -2.5").unwrap();
        let negative_range_target = planner_directive_expression_index_range_target(
            Some(&negative_numeric_range),
            &index,
            table_name,
            table_alias,
        )
        .expect("signed numeric literals must use the same range contract as VDBE revalidation");
        assert_eq!(
            negative_range_target.lower,
            Some(PlannerIndexRangeBound {
                expr: fsqlite_parser::expr::parse_expr("-2.5").unwrap(),
                inclusive: true,
            })
        );

        let foreign_qualifier =
            fsqlite_parser::expr::parse_expr("p.active = 1 AND lower(other.name) = ?1").unwrap();
        assert_eq!(
            planner_directive_expression_index_equality_target(
                Some(&foreign_qualifier),
                &index,
                table_name,
                table_alias,
            ),
            None,
            "a foreign qualifier must not bind to the current table's expression index"
        );

        let qualified_cast = fsqlite_parser::expr::parse_expr("CAST(p.Name AS text)").unwrap();
        let indexed_cast = fsqlite_parser::expr::parse_expr("cast(NAME AS TEXT)").unwrap();
        assert!(
            planner_directive_expression_matches_index_key(
                &qualified_cast,
                &indexed_cast,
                table_name,
                table_alias,
            ),
            "local columns and type names must use SQLite's case-insensitive identifier semantics"
        );
    }

    #[test]
