    #[test]
    fn test_composite_expression_equality_keeps_desc_trailing_non_null_rows() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE expr_prefix_rows (
                    id INTEGER PRIMARY KEY,
                    name TEXT NOT NULL,
                    rank INTEGER
                );",
            )
            .await
            .unwrap();
            conn.execute(
                "CREATE INDEX idx_expr_prefix_rows
                 ON expr_prefix_rows(lower(name), rank DESC);",
            )
            .await
            .unwrap();
            conn.execute(
                "INSERT INTO expr_prefix_rows VALUES
                    (1, 'Alpha', 9),
                    (2, 'ALPHA', NULL),
                    (3, 'beta', 7);",
            )
            .await
            .unwrap();

            let sql = "SELECT id FROM expr_prefix_rows WHERE lower(name) = 'alpha'";
            let select = parse_select_statement(sql);
            let program = conn.compile_table_select(&select).await.unwrap();
            assert!(
                program.ops().iter().any(|op| {
                    op.opcode == Opcode::OpenRead
                        && matches!(&op.p4, P4::Index(name) if name == "idx_expr_prefix_rows")
                }),
                "precondition: the composite expression index must drive the equality query"
            );

            let mut ids = conn
                .query(sql)
                .await
                .unwrap()
                .into_iter()
                .map(|row| row.values()[0].to_integer())
                .collect::<Vec<_>>();
            ids.sort_unstable();
            assert_eq!(
                ids,
                vec![1, 2],
                "a prefix probe must start before both DESC non-NULL and NULL trailing keys"
            );
        });
    }

