    #[test]
    fn test_compiled_cache_invalidated_by_ddl() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE cc_ddl (id INTEGER PRIMARY KEY, val TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO cc_ddl VALUES (1, 'a');")
                .await
                .unwrap();

            // Populate compiled cache.
            let rows = conn.query("SELECT val FROM cc_ddl").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert!(
                conn.compiled_cache_len() > 0,
                "cache should be populated after query"
            );

            // DDL should invalidate compiled cache.
            conn.execute("ALTER TABLE cc_ddl ADD COLUMN extra TEXT DEFAULT 'x';")
                .await
                .unwrap();
            assert_eq!(
                conn.compiled_cache_len(),
                0,
                "DDL must clear compiled cache"
            );

            // Should recompile fresh (schema changed).
            let rows = conn.query("SELECT val, extra FROM cc_ddl").await.unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].values()[0], SqliteValue::Text("a".into()));
            assert_eq!(rows[0].values()[1], SqliteValue::Text("x".into()));
        });
    }

    #[test]
    fn test_compiled_cache_invalidated_by_aggregate_and_window_registration() {
        struct Product;

        impl fsqlite_func::AggregateFunction for Product {
            type State = i64;

            fn initial_state(&self) -> Self::State {
                1
            }

            fn step(
                &self,
                state: &mut Self::State,
                args: &[SqliteValue],
            ) -> fsqlite_error::Result<()> {
                *state *= args[0].to_integer();
                Ok(())
            }

            fn finalize(&self, state: Self::State) -> fsqlite_error::Result<SqliteValue> {
                Ok(SqliteValue::Integer(state))
            }

            fn num_args(&self) -> i32 {
                1
            }

            fn name(&self) -> &str {
                "product"
            }
        }

        struct MovingSum;

        impl fsqlite_func::WindowFunction for MovingSum {
            type State = i64;

            fn initial_state(&self) -> Self::State {
                0
            }

            fn step(
                &self,
                state: &mut Self::State,
                args: &[SqliteValue],
            ) -> fsqlite_error::Result<()> {
                *state += args[0].to_integer();
                Ok(())
            }

            fn inverse(
                &self,
                state: &mut Self::State,
                args: &[SqliteValue],
            ) -> fsqlite_error::Result<()> {
                *state -= args[0].to_integer();
                Ok(())
            }

            fn value(&self, state: &Self::State) -> fsqlite_error::Result<SqliteValue> {
                Ok(SqliteValue::Integer(*state))
            }

            fn finalize(&self, state: Self::State) -> fsqlite_error::Result<SqliteValue> {
                Ok(SqliteValue::Integer(state))
            }

            fn num_args(&self) -> i32 {
                1
            }

            fn name(&self) -> &str {
                "moving_sum"
            }
        }

        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE cc_udf (v INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO cc_udf VALUES (2), (3);")
                .await
                .unwrap();

            conn.query("SELECT SUM(v) FROM cc_udf;").await.unwrap();
            assert!(
                conn.compiled_cache_len() > 0,
                "aggregate query should populate compiled cache"
            );

            conn.register_aggregate_function(Product);
            assert_eq!(
                conn.compiled_cache_len(),
                0,
                "aggregate registration must clear compiled cache"
            );

            conn.query("SELECT SUM(v) FROM cc_udf;").await.unwrap();
            assert!(
                conn.compiled_cache_len() > 0,
                "compiled cache should repopulate after aggregate registration"
            );

            conn.register_window_function(MovingSum);
            assert_eq!(
                conn.compiled_cache_len(),
                0,
                "window registration must clear compiled cache"
            );
        });
    }

    #[test]
    fn test_create_table_rejects_custom_aggregate_default_expression() {
        struct Product;
        struct BinaryMax;

        impl fsqlite_func::AggregateFunction for Product {
            type State = i64;

            fn initial_state(&self) -> Self::State {
                1
            }

            fn step(
                &self,
                state: &mut Self::State,
                args: &[SqliteValue],
            ) -> fsqlite_error::Result<()> {
                *state *= args[0].to_integer();
                Ok(())
            }

            fn finalize(&self, state: Self::State) -> fsqlite_error::Result<SqliteValue> {
                Ok(SqliteValue::Integer(state))
            }

            fn num_args(&self) -> i32 {
                1
            }

            fn name(&self) -> &str {
                "product"
            }
        }

        impl fsqlite_func::AggregateFunction for BinaryMax {
            type State = ();

            fn initial_state(&self) -> Self::State {}

            fn step(&self, _state: &mut Self::State, _args: &[SqliteValue]) -> Result<()> {
                Ok(())
            }

            fn finalize(&self, _state: Self::State) -> Result<SqliteValue> {
                Ok(SqliteValue::Null)
            }

            fn num_args(&self) -> i32 {
                2
            }

            fn name(&self) -> &str {
                "max"
            }
        }

        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.register_aggregate_function(Product);
            let err = conn
                .execute("CREATE TABLE t(a INTEGER, b INTEGER DEFAULT (product(2)));")
                .await
                .expect_err("custom aggregate DEFAULT should be rejected");
            let msg = err.to_string();
            assert!(
                msg.contains("default value of column [b] is not constant"),
                "unexpected error: {msg}"
            );

            conn.register_aggregate_function(BinaryMax);
            let err = conn
                .execute("CREATE TABLE t2(a INTEGER DEFAULT (max(1, 2)));")
                .await
                .expect_err("a custom max/2 aggregate DEFAULT should be rejected");
            let msg = err.to_string();
            assert!(
                msg.contains("default value of column [a] is not constant"),
                "unexpected error: {msg}"
            );
        });
    }

