    #[test]
    fn test_scalar_function_registration_invalidates_prepared_and_plan_caches() {
        use fsqlite_func::ScalarFunction;
        let _profile_guard = StatementReuseHotPathProfileGuard::new();

        struct Double;

        impl ScalarFunction for Double {
            fn invoke(&self, args: &[SqliteValue]) -> Result<SqliteValue> {
                Ok(SqliteValue::Integer(args[0].to_integer() * 2))
            }

            fn num_args(&self) -> i32 {
                1
            }

            fn name(&self) -> &str {
                "scale1"
            }
        }

        struct Triple;

        impl ScalarFunction for Triple {
            fn invoke(&self, args: &[SqliteValue]) -> Result<SqliteValue> {
                Ok(SqliteValue::Integer(args[0].to_integer() * 3))
            }

            fn num_args(&self) -> i32 {
                1
            }

            fn name(&self) -> &str {
                "scale1"
            }
        }

        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE cc_scalar_udf (v INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO cc_scalar_udf VALUES (2), (3);")
                .await
                .unwrap();
            conn.register_deterministic_scalar_function(Double);

            let sql = "SELECT scale1(v) FROM cc_scalar_udf WHERE v = ?1";
            let stmt1 = conn.prepare(sql).await.unwrap();
            let row1 = stmt1
                .query_row_with_params(&[SqliteValue::Integer(2)])
                .await
                .unwrap();
            assert_eq!(row1.values()[0], SqliteValue::Integer(4));
            conn.compile_table_select(&parse_select_statement(sql))
                .await
                .unwrap();
            assert!(
                conn.prepared_cache_len() > 0,
                "prepare() should populate the prepared cache before invalidation"
            );
            assert!(
                conn.compiled_cache_len() > 0,
                "prepare() should populate the compiled cache before invalidation"
            );
            assert!(
                conn.planner_directive_cache_len() > 0,
                "table-select planning should populate the planner-directive cache before invalidation"
            );

            conn.register_deterministic_scalar_function(Triple);
            assert_eq!(
                conn.prepared_cache_len(),
                0,
                "scalar registration must clear prepared cache entries"
            );
            assert_eq!(
                conn.compiled_cache_len(),
                0,
                "scalar registration must clear compiled cache entries"
            );
            assert_eq!(
                conn.planner_directive_cache_len(),
                0,
                "scalar registration must clear planner-directive cache entries"
            );

            reset_hot_path_profile();
            let stmt2 = conn.prepare(sql).await.unwrap();
            let row2 = stmt2
                .query_row_with_params(&[SqliteValue::Integer(2)])
                .await
                .unwrap();
            assert_eq!(row2.values()[0], SqliteValue::Integer(6));

            let profile = hot_path_profile_snapshot();
            assert_eq!(
                profile.parser.prepared_cache_hits, 0,
                "scalar re-registration must force a prepared-cache miss: {profile:?}"
            );
            assert_eq!(
                profile.parser.prepared_cache_misses, 1,
                "the first prepare after scalar re-registration should miss the prepared cache: {profile:?}"
            );
            assert_eq!(
                profile.parser.compiled_cache_hits, 0,
                "scalar re-registration must force a compiled-cache miss: {profile:?}"
            );
            assert_eq!(
                profile.parser.compiled_cache_misses, 1,
                "the first prepare after scalar re-registration should miss the compiled cache: {profile:?}"
            );
        });
    }

