    #[test]
    fn test_replace_on_unique_constraint() {
        asupersync::test_utils::run_test(|| async {
            // INSERT OR REPLACE with UNIQUE constraint (non-IPK) deletes the
            // conflicting row and inserts the new one.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, email TEXT UNIQUE, name TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'a@b.com', 'Alice');")
                .await
                .unwrap();
            conn.execute("INSERT OR REPLACE INTO t VALUES (2, 'a@b.com', 'Bob');")
                .await
                .unwrap();
            let rows = conn
                .query("SELECT id, email, name FROM t ORDER BY id;")
                .await
                .unwrap();
            // REPLACE should remove old row (id=1) and insert new (id=2).
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(2));
            assert_eq!(rows[0].values()[1], SqliteValue::Text("a@b.com".into()));
            assert_eq!(rows[0].values()[2], SqliteValue::Text("Bob".into()));
        });
    }

    #[test]
    fn test_replace_cleans_partial_and_expression_index_victims_on_reopen() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("replace-index-victim-cleanup.db");
            let db_str = db_path.to_string_lossy().into_owned();

            {
                let conn = Connection::open(&db_str).await.unwrap();
                conn.execute_batch(
                    "CREATE TABLE partial_t (a TEXT, b INTEGER UNIQUE, c INTEGER);
                 CREATE INDEX partial_idx ON partial_t(a) WHERE c > 0;
                 INSERT INTO partial_t VALUES ('victim', 1, 5);
                 INSERT OR REPLACE INTO partial_t VALUES ('newrow', 1, 0);

                 CREATE TABLE expression_t (a TEXT, b INTEGER UNIQUE);
                 CREATE INDEX expression_idx ON expression_t(lower(a));
                 INSERT INTO expression_t VALUES ('VICTIM', 1);
                 INSERT OR REPLACE INTO expression_t VALUES ('other', 1);",
                )
                .await
                .unwrap();

                assert_eq!(
                    conn.query("SELECT a, b, c FROM partial_t;").await.unwrap()[0].values(),
                    &[
                        SqliteValue::Text("newrow".into()),
                        SqliteValue::Integer(1),
                        SqliteValue::Integer(0),
                    ]
                );
                assert_eq!(
                    conn.query("SELECT a, b FROM expression_t;").await.unwrap()[0].values(),
                    &[SqliteValue::Text("other".into()), SqliteValue::Integer(1),]
                );
            }

            let reopened = Connection::open(&db_str).await.unwrap();
            assert_eq!(
                reopened
                    .query("SELECT * FROM partial_t;")
                    .await
                    .unwrap()
                    .len(),
                1
            );
            assert_eq!(
                reopened
                    .query("SELECT * FROM expression_t;")
                    .await
                    .unwrap()
                    .len(),
                1
            );
            drop(reopened);

            let sqlite = rusqlite::Connection::open(&db_path).unwrap();
            let integrity: String = sqlite
                .query_row("PRAGMA integrity_check;", [], |row| row.get(0))
                .unwrap();
            assert_eq!(integrity, "ok");
            let stale_partial: i64 = sqlite
                .query_row(
                    "SELECT COUNT(*) FROM partial_t INDEXED BY partial_idx
                 WHERE a = 'victim' AND c > 0;",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(stale_partial, 0);
            let stale_expression: i64 = sqlite
                .query_row(
                    "SELECT COUNT(*) FROM expression_t INDEXED BY expression_idx
                 WHERE lower(a) = 'victim';",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(stale_expression, 0);
        });
    }

