    #[test]
    fn time_travel_snapshot_debug() {
        asupersync::test_utils::run_test(|| async {
            // Debug test: verify what's actually in the snapshots.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, val TEXT);")
                .await
                .unwrap();
            conn.execute("BEGIN;").await.unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'hello');")
                .await
                .unwrap();
            conn.execute("COMMIT;").await.unwrap();

            let snaps = conn.time_travel_snapshots.borrow();
            eprintln!("snapshot count: {}", snaps.len());
            for snap in snaps.iter() {
                let table_count = snap.db.tables.len();
                eprintln!(
                    "  seq={}, tables={}, timestamp_ns={}",
                    snap.commit_seq, table_count, snap.timestamp_ns
                );
                // Check if the table has rows by looking at the tables.
                for (root_page, table) in snap.db.tables.iter() {
                    let row_count = table.iter_rows().count();
                    eprintln!(
                        "    root_page={}, num_columns={}, rows={}",
                        root_page, table.num_columns, row_count
                    );
                }
            }
            drop(snaps);

            // Verify snapshot at seq 2 has 1 row.
            let snaps = conn.time_travel_snapshots.borrow();
            let snap_seq2 = snaps.iter().find(|s| s.commit_seq == 2);
            assert!(snap_seq2.is_some(), "snapshot at seq 2 should exist");
            let snap = snap_seq2.unwrap();
            let total_rows: usize = snap
                .db
                .tables
                .iter()
                .map(|(_, t)| t.iter_rows().count())
                .sum();
            assert!(
                total_rows > 0,
                "snapshot at seq 2 should have rows, got {total_rows}"
            );
        });
    }

    #[test]
    fn time_travel_snapshot_capture_keeps_timestamps_monotonic() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            let future_timestamp = SystemTime::now()
                .duration_since(SystemTime::UNIX_EPOCH)
                .map(|duration| duration.as_nanos() as u64)
                .unwrap_or(0)
                .saturating_add(1_000_000_000);

            conn.time_travel_snapshots
                .borrow_mut()
                .push(TimeTravelSnapshotEntry {
                    commit_seq: 41,
                    timestamp_ns: future_timestamp,
                    db: conn.db.borrow().clone(),
                });

            conn.capture_time_travel_snapshot(42).await;

            let snapshots = conn.time_travel_snapshots.borrow();
            let previous = snapshots
                .iter()
                .find(|snapshot| snapshot.commit_seq == 41)
                .expect("seed snapshot should exist");
            let captured = snapshots
                .iter()
                .find(|snapshot| snapshot.commit_seq == 42)
                .expect("captured snapshot should exist");
            assert_eq!(
                captured.timestamp_ns,
                previous.timestamp_ns.saturating_add(1),
                "snapshot capture should force timestamps to remain monotonic even if the wall clock moves backward"
            );
        });
    }

