    #[test]
    fn test_schema_only_attach_blocks_file_backed_attached_writes() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let main_path = dir.path().join("main.db");
            let aux_path = dir.path().join("aux.db");
            let main_path_str = main_path.to_string_lossy().into_owned();
            let aux_path_str = aux_path.to_string_lossy().into_owned();
            let aux_path_sql = aux_path.to_string_lossy().replace('\'', "''");

            let main = Connection::open(&main_path_str).await.unwrap();
            main.execute("CREATE TABLE main_t (id INTEGER PRIMARY KEY, value TEXT);")
                .await
                .unwrap();
            drop(main);

            let aux = Connection::open(&aux_path_str).await.unwrap();
            aux.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, value TEXT);")
                .await
                .unwrap();
            aux.execute("INSERT INTO t VALUES (1, 'alpha');")
                .await
                .unwrap();
            drop(aux);

            let conn = Connection::open_schema_only(&main_path_str).await.unwrap();
            conn.execute(&format!("ATTACH DATABASE '{aux_path_sql}' AS aux;"))
                .await
                .unwrap();

            let rows = conn
                .query("SELECT value FROM aux.t ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].values()[0], SqliteValue::Text("alpha".into()));

            let err = conn
                .execute("INSERT INTO aux.t VALUES (2, 'beta');")
                .await
                .expect_err(
                    "schema-only parent must not open attached file-backed schemas writable",
                );
            assert!(
                matches!(err, FrankenError::ReadOnly),
                "expected attached write through schema-only parent to fail read-only, got {err:?}"
            );
        });
    }

