    #[test]
    fn test_attached_upsert_in_table_shorthand_strips_same_schema_name() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("ATTACH DATABASE ':memory:' AS aux;")
                .await
                .unwrap();
            conn.execute("CREATE TABLE aux.allowed (v INTEGER);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE aux.kv (k TEXT PRIMARY KEY, v INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO aux.allowed VALUES (10);")
                .await
                .unwrap();
            conn.execute("INSERT INTO aux.kv VALUES ('a', 1);")
                .await
                .unwrap();

            let rows = conn
                .query(
                    "INSERT INTO aux.kv VALUES ('a', 10)
                 ON CONFLICT(k) DO UPDATE SET v = excluded.v IN aux.allowed
                 RETURNING v;",
                )
                .await
                .unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values().to_vec())
                    .collect::<Vec<_>>(),
                vec![vec![SqliteValue::Integer(1)]]
            );

            let persisted = conn.query("SELECT k, v FROM aux.kv;").await.unwrap();
            assert_eq!(
                persisted
                    .iter()
                    .map(|row| row.values().to_vec())
                    .collect::<Vec<_>>(),
                vec![vec![SqliteValue::Text("a".into()), SqliteValue::Integer(1)]]
            );
        });
    }

