    #[test]
    fn test_create_table_as_select_with_aliased_star_preserves_column_names_on_zero_rows() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE src (id INTEGER, value TEXT);")
                .await
                .unwrap();

            conn.execute("CREATE TABLE copy AS SELECT s.* FROM src AS s WHERE 0;")
                .await
                .unwrap();

            let pragma_rows = conn.query("PRAGMA table_info(copy);").await.unwrap();
            let column_names: Vec<String> = pragma_rows
                .iter()
                .map(|row| match &row.values()[1] {
                    SqliteValue::Text(name) => name.to_string(),
                    other => panic!("unexpected PRAGMA table_info name column: {other:?}"),
                })
                .collect();
            assert_eq!(column_names, vec!["id".to_owned(), "value".to_owned()]);

            let rows = conn.query("SELECT * FROM copy;").await.unwrap();
            assert!(rows.is_empty(), "zero-row CTAS should not materialize rows");
        });
    }

