    #[test]
    fn test_window_select_table_star_join_uses_precomputed_col_map_without_schema_reborrow()
    -> Result<()> {
        let mut outcome: Result<()> = Ok(());
        asupersync::test_utils::run_test(|| async {
            outcome = async {
                let conn = Connection::open(":memory:").await?;
                conn.execute("CREATE TABLE lhs (id INTEGER, payload TEXT);")
                    .await?;
                conn.execute("CREATE TABLE rhs (id INTEGER, tag TEXT);")
                    .await?;
                conn.execute("INSERT INTO lhs VALUES (1, 'left');").await?;
                conn.execute("INSERT INTO rhs VALUES (1, 'r1');").await?;

                let rows = conn
                    .query(
                        "SELECT lhs.*, ROW_NUMBER() OVER (ORDER BY lhs.id)
                 FROM lhs JOIN rhs ON rhs.id = lhs.id;",
                    )
                    .await?;
                assert_eq!(rows.len(), 1);
                assert_eq!(rows[0].values().len(), 3);
                assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
                assert_eq!(rows[0].values()[1], SqliteValue::Text("left".into()));
                assert_eq!(rows[0].values()[2], SqliteValue::Integer(1));

                let select = parse_select_statement(
                    "SELECT lhs.*, ROW_NUMBER() OVER (ORDER BY lhs.id)
             FROM lhs JOIN rhs ON rhs.id = lhs.id",
                );
                let SelectCore::Select {
                    from: Some(from), ..
                } = &select.body.select
                else {
                    return Err(FrankenError::Internal(
                        "fixture should parse as SELECT with FROM".to_owned(),
                    ));
                };
                let join_sources: Vec<&TableOrSubquery> = std::iter::once(&from.source)
                    .chain(from.joins.iter().map(|join| &join.table))
                    .collect();
                let col_map = conn.build_join_col_map(&select);
                let _schema_write = conn.schema.borrow_mut();
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    conn.expand_table_star_result_columns_from_col_map(
                        &join_sources,
                        &col_map,
                        &QualifiedName::bare("lhs"),
                    )
                }));
                let expanded = result.map_err(|_| {
                    FrankenError::Internal(
                        "table-star expansion should not borrow schema".to_owned(),
                    )
                })?;
                assert_eq!(expanded.len(), 2);
                Ok(())
            }
            .await;
        });
        outcome
    }

