    #[test]
    fn test_pragma_index_list() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (a TEXT, b INTEGER);")
                .await
                .unwrap();
            conn.execute("CREATE INDEX idx_a ON t(a);").await.unwrap();
            let rows = conn.query("PRAGMA index_list(t);").await.unwrap();
            assert!(!rows.is_empty());
            let names: Vec<_> = rows
                .iter()
                .filter_map(|r| {
                    if let SqliteValue::Text(s) = &r.values()[1] {
                        Some(s.clone())
                    } else {
                        None
                    }
                })
                .collect();
            assert!(
                names.iter().any(|n| n.contains("idx_a")),
                "expected idx_a in {names:?}"
            );
        });
    }

