    #[test]
    fn test_compound_order_by_collate_resolves() {
        asupersync::test_utils::run_test(|| async {
            // GH #217-#221: a COLLATE-wrapped ORDER BY term in a compound SELECT must
            // resolve (by output name, alias, or 1-based position) and sort with the
            // collation instead of erroring "not found in SELECT list".
            let conn = Connection::open(":memory:").await.unwrap();
            for sql in [
                "SELECT 'b' AS x UNION SELECT 'A' ORDER BY x COLLATE NOCASE",
                "SELECT 'b' AS x UNION ALL SELECT 'A' ORDER BY x COLLATE NOCASE",
                "SELECT 'b' UNION SELECT 'A' ORDER BY 1 COLLATE NOCASE",
            ] {
                let rows = conn
                    .query(sql)
                    .await
                    .unwrap_or_else(|e| panic!("{sql}: {e:?}"));
                assert_eq!(rows.len(), 2, "sql={sql}");
                assert_eq!(
                    rows[0].values()[0],
                    SqliteValue::Text("A".into()),
                    "sql={sql}"
                );
                assert_eq!(
                    rows[1].values()[0],
                    SqliteValue::Text("b".into()),
                    "sql={sql}"
                );
            }
        });
    }

    #[test]
    fn test_select_structure_follows_sqlite_depth_first_precedence() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            async fn direct_and_prepared_errors(conn: &Connection, sql: &str) -> Vec<FrankenError> {
                let direct = conn
                    .query(sql)
                    .await
                    .expect_err("direct execution must reject malformed SELECT structure");
                let prepared = match conn.prepare(sql).await {
                    Ok(statement) => statement
                        .query()
                        .await
                        .expect_err("prepared execution must retain structural validation"),
                    Err(error) => error,
                };
                vec![direct, prepared]
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT 1 ORDER BY nope + \
                 (SELECT 1 UNION SELECT 2, 3);",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::NoSuchColumn { name } if name == "nope"
                    ),
                    "the left ORDER expression must fail before its later child SELECT: {error:?}"
                );
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT 1 ORDER BY \
                 (SELECT 1 UNION SELECT 2, 3) + nope;",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::ParseError { detail, .. }
                            if detail
                                == "SELECTs to the left and right of UNION do not have the same number of result columns"
                    ),
                    "the leading child SELECT must fail before a later ORDER name: {error:?}"
                );
            }

            for sql in [
                "SELECT 1 ORDER BY 0 AND \
                 (SELECT 1 UNION SELECT 2, 3);",
                "SELECT 1 ORDER BY \
                 (SELECT 1 UNION SELECT 2, 3) AND 0;",
            ] {
                for error in direct_and_prepared_errors(&conn, sql).await {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::FunctionError(message)
                                if message
                                    == "1st ORDER BY term out of range - should be between 1 and 1"
                        ),
                        "integer-zero AND folding must become positional ORDER zero for `{sql}`: \
                         {error:?}"
                    );
                }
            }

            for sql in [
                "SELECT 1 ORDER BY FALSE AND \
                 (SELECT 1 UNION SELECT 2, 3);",
                "SELECT 1 ORDER BY 0.0 AND \
                 (SELECT 1 UNION SELECT 2, 3);",
                "SELECT 1 ORDER BY (0 COLLATE BINARY) AND \
                 (SELECT 1 UNION SELECT 2, 3);",
                "SELECT 1 ORDER BY +0 AND \
                 (SELECT 1 UNION SELECT 2, 3);",
            ] {
                for error in direct_and_prepared_errors(&conn, sql).await {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::ParseError { detail, .. }
                                if detail
                                    == "SELECTs to the left and right of UNION do not have the same number of result columns"
                        ),
                        "non-folding false-like operands must leave the child SELECT live for \
                         `{sql}`: {error:?}"
                    );
                }
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT 1 ORDER BY 99, \
                 (SELECT 1 UNION SELECT 2, 3);",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::ParseError { detail, .. }
                            if detail
                                == "SELECTs to the left and right of UNION do not have the same number of result columns"
                    ),
                    "a valid-domain ordinal must defer its width error until later ORDER terms \
                     resolve: {error:?}"
                );
            }

            for error in direct_and_prepared_errors(&conn, "SELECT 1 ORDER BY 65535, nope;").await {
                assert!(
                    matches!(
                        &error,
                        FrankenError::NoSuchColumn { name } if name == "nope"
                    ),
                    "a deferred positive ordinal must not mask a later unresolved name: {error:?}"
                );
            }

            for sql in [
                "SELECT 1 ORDER BY 70000, nope;",
                "SELECT 1 ORDER BY -1, nope;",
            ] {
                for error in direct_and_prepared_errors(&conn, sql).await {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::FunctionError(message)
                                if message
                                    == "1st ORDER BY term out of range - should be between 1 and 1"
                        ),
                        "an ordinal outside SQLite's immediate domain must fail before later \
                         ORDER terms for `{sql}`: {error:?}"
                    );
                }
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT 1 UNION SELECT 2 ORDER BY \
                 0 AND (SELECT 1 UNION SELECT 2, 3);",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message
                                == "1st ORDER BY term out of range - should be between 1 and 1"
                    ),
                    "compound ORDER must classify exact integer-zero AND folding as positional \
                     zero before inspecting the dead child: {error:?}"
                );
            }

            for (sql, expected_op) in [
                (
                    "SELECT (SELECT 1 EXCEPT SELECT 2, 3) \
                     FROM (SELECT 1) AS left_source \
                     JOIN (SELECT 1) AS right_source \
                       ON (SELECT 1 UNION SELECT 2, 3) \
                     WHERE (SELECT 1 INTERSECT SELECT 2, 3);",
                    "EXCEPT",
                ),
                (
                    "SELECT 1 \
                     FROM (SELECT 1) AS left_source \
                     JOIN (SELECT 1) AS right_source \
                       ON (SELECT 1 UNION SELECT 2, 3) \
                     WHERE (SELECT 1 INTERSECT SELECT 2, 3);",
                    "INTERSECT",
                ),
            ] {
                for error in direct_and_prepared_errors(&conn, sql).await {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::ParseError { detail, .. }
                                if detail
                                    == &format!(
                                        "SELECTs to the left and right of {expected_op} do not have the same number of result columns"
                                    )
                        ),
                        "projection and WHERE resolution must precede JOIN ON for `{sql}`: \
                         {error:?}"
                    );
                }
            }

            for error in direct_and_prepared_errors(
                &conn,
                "VALUES ((SELECT 1 INTERSECT SELECT 2, 3)), \
                        ((SELECT 1 UNION SELECT 2, 3));",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::ParseError { detail, .. }
                            if detail
                                == "SELECTs to the left and right of UNION do not have the same number of result columns"
                    ),
                    "multi-row VALUES expressions must resolve from the rightmost row first: \
                     {error:?}"
                );
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT 1 UNION SELECT 2 \
                 ORDER BY (SELECT 1, 2 ORDER BY 99);",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message
                                == "1st ORDER BY term does not match any column in the result set"
                    ),
                    "an unmatched compound ORDER expression must remain opaque: {error:?}"
                );
            }

            for sql in [
                "WITH unused AS \
                 (SELECT 1 UNION SELECT 2, 3) SELECT 1;",
                "WITH unused AS \
                 (SELECT 1 ORDER BY 0) SELECT 1;",
            ] {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(direct[0].values(), &[SqliteValue::Integer(1)]);
                let prepared = conn.prepare(sql).await.unwrap().query().await.unwrap();
                assert_eq!(prepared[0].values(), &[SqliteValue::Integer(1)]);
            }

            conn.execute("CREATE TABLE relation_scope_t (a INTEGER);")
                .await
                .unwrap();
            for (sql, expected_name) in [
                (
                    "SELECT missing_col FROM relation_scope_t \
                     UNION SELECT 1, 2 FROM missing_right_relation;",
                    "missing_right_relation",
                ),
                (
                    "SELECT 1 FROM missing_first_source \
                     JOIN missing_second_source;",
                    "missing_first_source",
                ),
                (
                    "WITH used AS (SELECT 1 FROM missing_cte_relation) \
                     SELECT * FROM used JOIN missing_later_relation;",
                    "missing_cte_relation",
                ),
                (
                    "SELECT * FROM \
                     (SELECT 1 FROM missing_derived_relation) AS derived \
                     JOIN missing_later_relation;",
                    "missing_derived_relation",
                ),
                (
                    "SELECT 1 UNION \
                     SELECT (SELECT 1 FROM missing_right_relation) \
                     LIMIT (SELECT count(*) FROM missing_limit_relation);",
                    "missing_right_relation",
                ),
                (
                    "SELECT (SELECT 1 FROM missing_left_relation) \
                     UNION SELECT 1 \
                     LIMIT (SELECT count(*) FROM missing_limit_relation);",
                    "missing_limit_relation",
                ),
                (
                    "WITH local_cte AS (SELECT 1) \
                     SELECT * FROM main.local_cte;",
                    "main.local_cte",
                ),
                (
                    "SELECT row_number() OVER w \
                     WINDOW w AS \
                       (ORDER BY (SELECT 1 FROM missing_used_window_relation));",
                    "missing_used_window_relation",
                ),
                (
                    "SELECT 1 WINDOW unused_relation AS \
                       (ORDER BY (SELECT 1 FROM missing_unused_window_relation));",
                    "missing_unused_window_relation",
                ),
            ] {
                for error in direct_and_prepared_errors(&conn, sql).await {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::NoSuchTable { name } if name == expected_name
                        ),
                        "relation expansion must preserve SQLite precedence for `{sql}`: \
                         {error:?}"
                    );
                }
            }

            for (sql, expected) in [
                (
                    "WITH unused AS (SELECT 1 FROM missing_unused_cte_relation) \
                     SELECT 1;",
                    SqliteValue::Integer(1),
                ),
                (
                    "SELECT 0 AND (SELECT 1 FROM missing_dead_relation);",
                    SqliteValue::Integer(0),
                ),
                (
                    "SELECT (SELECT 1 FROM missing_empty_in_relation) IN ();",
                    SqliteValue::Integer(0),
                ),
            ] {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(direct[0].values(), &[expected]);
                let prepared = conn.prepare(sql).await.unwrap().query().await.unwrap();
                assert_eq!(
                    prepared, direct,
                    "dead relation subtree changed for `{sql}`"
                );
            }

            conn.execute(
                "CREATE VIEW deferred_relation_view AS \
                 SELECT 1 FROM missing_view_relation;",
            )
            .await
            .unwrap();
            for error in
                direct_and_prepared_errors(&conn, "SELECT * FROM deferred_relation_view;").await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::NoSuchTable { name }
                            if name == "main.missing_view_relation"
                    ),
                    "CREATE VIEW must defer relation lookup until the view is referenced: \
                     {error:?}"
                );
            }

            for error in
                direct_and_prepared_errors(&conn, "SELECT * FROM missing_table_function(1);").await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::NoSuchTable { name }
                            if name == "missing_table_function"
                    ),
                    "an unknown table-valued function is an unresolved table source: {error:?}"
                );
            }

            for error in
                direct_and_prepared_errors(&conn, "SELECT * FROM relation_scope_t(1);").await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message == "'relation_scope_t' is not a function"
                    ),
                    "an existing ordinary relation cannot be called as a table function: \
                     {error:?}"
                );
            }

            conn.execute(
                "CREATE VIEW circular_relation_view AS \
                 SELECT * FROM circular_relation_view;",
            )
            .await
            .unwrap();
            for error in
                direct_and_prepared_errors(&conn, "SELECT * FROM circular_relation_view;").await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message
                                == "view circular_relation_view is circularly defined"
                    ),
                    "circular view expansion must terminate with SQLite's diagnostic: {error:?}"
                );
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT row_number() OVER child \
                 WINDOW base AS \
                            (ORDER BY \
                               (SELECT 1 FROM missing_suppressed_window_relation)), \
                        child AS (base ORDER BY 1);",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message
                                == "cannot override ORDER BY clause of window: base"
                    ),
                    "an invalid window override must suppress only its own nested relation walk: \
                     {error:?}"
                );
            }

            for sql in [
                "SELECT row_number() OVER child \
                 WINDOW child AS (base), \
                        base AS (ORDER BY (SELECT 1 UNION SELECT 2, 3));",
                "SELECT row_number() OVER () \
                 WINDOW unused AS (ORDER BY (SELECT 1 UNION SELECT 2, 3));",
                "SELECT 1 \
                 WINDOW w AS (ORDER BY (SELECT 1 UNION SELECT 2, 3)), \
                        w AS () \
                 ORDER BY row_number() OVER w;",
            ] {
                let direct = conn.query(sql).await.unwrap();
                assert_eq!(direct[0].values(), &[SqliteValue::Integer(1)]);
                let prepared = conn.prepare(sql).await.unwrap().query().await.unwrap();
                assert_eq!(prepared[0].values(), &[SqliteValue::Integer(1)]);
            }

            for sql in [
                "SELECT row_number() OVER w \
                 WINDOW w AS (ORDER BY (SELECT 1 INTERSECT SELECT 2, 3)), \
                        w AS (ORDER BY (SELECT 1 UNION SELECT 2, 3));",
                "SELECT row_number() OVER child \
                 WINDOW base AS (ORDER BY (SELECT 1 INTERSECT SELECT 2, 3)), \
                        base AS (ORDER BY (SELECT 1 UNION SELECT 2, 3)), \
                        child AS (base);",
                "SELECT row_number() OVER w \
                 WINDOW w AS (ORDER BY (SELECT 1 UNION SELECT 2, 3)), \
                        w AS (w);",
                "SELECT 1 \
                 WINDOW w AS (), \
                        w AS (ORDER BY (SELECT 1 UNION SELECT 2, 3)) \
                 ORDER BY row_number() OVER w;",
            ] {
                for error in direct_and_prepared_errors(&conn, sql).await {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::ParseError { detail, .. }
                                if detail
                                    == "SELECTs to the left and right of UNION do not have the same number of result columns"
                        ),
                        "named-window lookup must follow SQLite's latest-direct and strict-prior \
                         definition rules for `{sql}`: {error:?}"
                    );
                }
            }

            for (sql, expected_message) in [
                (
                    "SELECT row_number() OVER \
                     (missing ORDER BY (SELECT 1 UNION SELECT 2, 3));",
                    "no such window: missing",
                ),
                (
                    "SELECT row_number() OVER child \
                     WINDOW base AS \
                                (ORDER BY (SELECT 1 UNION SELECT 2, 3)), \
                            child AS (base ORDER BY 1);",
                    "cannot override ORDER BY clause of window: base",
                ),
            ] {
                for error in direct_and_prepared_errors(&conn, sql).await {
                    assert!(
                        matches!(
                            &error,
                            FrankenError::FunctionError(message)
                                if message == expected_message
                        ),
                        "window name/override errors must precede malformed nested expressions \
                         for `{sql}`: {error:?}"
                    );
                }
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT 1 WINDOW first AS (), later AS (missing);",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message == "no such window: missing"
                    ),
                    "a later missing base is invalid even when its window body is unused: \
                    {error:?}"
                );
            }

            for prepared in [false, true] {
                let sql = "VALUES (2), (1) UNION ALL SELECT 3 ORDER BY column1;";
                let rows = if prepared {
                    conn.prepare(sql).await.unwrap().query().await.unwrap()
                } else {
                    conn.query(sql).await.unwrap()
                };
                assert_eq!(
                    rows.iter().map(row_values).collect::<Vec<_>>(),
                    vec![
                        vec![SqliteValue::Integer(1)],
                        vec![SqliteValue::Integer(2)],
                        vec![SqliteValue::Integer(3)],
                    ],
                    "multi-row VALUES output names must resolve in compound ORDER"
                );
            }

            conn.execute("CREATE TABLE compound_star_layout (a INTEGER, b INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO compound_star_layout VALUES (2, 20);")
                .await
                .unwrap();
            for prepared in [false, true] {
                let sql = "SELECT *, a AS marker FROM compound_star_layout \
                     UNION ALL SELECT 1, 10, 1 ORDER BY marker;";
                let rows = if prepared {
                    conn.prepare(sql).await.unwrap().query().await.unwrap()
                } else {
                    conn.query(sql).await.unwrap()
                };
                assert_eq!(
                    rows.iter().map(row_values).collect::<Vec<_>>(),
                    vec![
                        vec![
                            SqliteValue::Integer(1),
                            SqliteValue::Integer(10),
                            SqliteValue::Integer(1),
                        ],
                        vec![
                            SqliteValue::Integer(2),
                            SqliteValue::Integer(20),
                            SqliteValue::Integer(2),
                        ],
                    ],
                    "a compound ORDER alias after star expansion must use the flattened slot"
                );
            }

            for sql in [
                "SELECT * FROM compound_star_layout \
                 UNION ALL SELECT 1, 10 ORDER BY b;",
                "SELECT compound_star_layout.* FROM compound_star_layout \
                 UNION ALL SELECT 1, 10 ORDER BY compound_star_layout.b;",
                "SELECT q.* FROM compound_star_layout AS q \
                 UNION ALL SELECT 1, 10 ORDER BY q.b;",
            ] {
                for prepared in [false, true] {
                    let rows = if prepared {
                        conn.prepare(sql).await.unwrap().query().await.unwrap()
                    } else {
                        conn.query(sql).await.unwrap()
                    };
                    assert_eq!(
                        rows.iter().map(row_values).collect::<Vec<_>>(),
                        vec![
                            vec![SqliteValue::Integer(1), SqliteValue::Integer(10)],
                            vec![SqliteValue::Integer(2), SqliteValue::Integer(20)],
                        ],
                        "compound ORDER must resolve names contributed by star expansion for \
                         `{sql}`"
                    );
                }
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT q.* FROM compound_star_layout AS q \
                 UNION ALL SELECT 1, 10 ORDER BY compound_star_layout.b;",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message
                                == "1st ORDER BY term does not match any column in the result set"
                    ),
                    "a table alias must hide the original qualifier in compound ORDER: {error:?}"
                );
            }

            for sql in [
                "SELECT * FROM (SELECT 2 AS x) \
                 UNION ALL SELECT 1 ORDER BY x;",
                "SELECT s.* FROM (SELECT 2 AS x) AS s \
                 UNION ALL SELECT 1 ORDER BY s.x;",
            ] {
                for prepared in [false, true] {
                    let rows = if prepared {
                        conn.prepare(sql).await.unwrap().query().await.unwrap()
                    } else {
                        conn.query(sql).await.unwrap()
                    };
                    assert_eq!(
                        rows.iter().map(row_values).collect::<Vec<_>>(),
                        vec![vec![SqliteValue::Integer(1)], vec![SqliteValue::Integer(2)],],
                        "derived-table star output must retain only real qualifiers for `{sql}`"
                    );
                }
            }

            for error in direct_and_prepared_errors(
                &conn,
                "SELECT * FROM (SELECT 2 AS x) \
                 UNION ALL SELECT 1 ORDER BY subquery.x;",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message
                                == "1st ORDER BY term does not match any column in the result set"
                    ),
                    "the internal anonymous-subquery label must never become a SQL qualifier: \
                     {error:?}"
                );
            }

            for sql in [
                "CREATE TABLE compound_star_left (a INTEGER, b INTEGER);",
                "CREATE TABLE compound_star_right (a INTEGER, c INTEGER);",
                "INSERT INTO compound_star_left VALUES (2, 20);",
                "INSERT INTO compound_star_right VALUES (2, 200);",
            ] {
                conn.execute(sql).await.unwrap();
            }
            for prepared in [false, true] {
                let sql = "SELECT * \
                     FROM compound_star_left AS left_source \
                     JOIN compound_star_right AS right_source USING (a) \
                     UNION ALL SELECT 1, 10, 100 ORDER BY left_source.a;";
                let rows = if prepared {
                    conn.prepare(sql).await.unwrap().query().await.unwrap()
                } else {
                    conn.query(sql).await.unwrap()
                };
                assert_eq!(
                    rows.iter().map(row_values).collect::<Vec<_>>(),
                    vec![
                        vec![
                            SqliteValue::Integer(1),
                            SqliteValue::Integer(10),
                            SqliteValue::Integer(100),
                        ],
                        vec![
                            SqliteValue::Integer(2),
                            SqliteValue::Integer(20),
                            SqliteValue::Integer(200),
                        ],
                    ],
                    "plain star must retain the left origin of a USING-coalesced output"
                );
            }
            for error in direct_and_prepared_errors(
                &conn,
                "SELECT * \
                 FROM compound_star_left AS left_source \
                 JOIN compound_star_right AS right_source USING (a) \
                 UNION ALL SELECT 1, 10, 100 ORDER BY right_source.a;",
            )
            .await
            {
                assert!(
                    matches!(
                        &error,
                        FrankenError::FunctionError(message)
                            if message
                                == "1st ORDER BY term does not match any column in the result set"
                    ),
                    "plain star must not expose the right duplicate of a USING column: {error:?}"
                );
            }
            for prepared in [false, true] {
                let sql = "SELECT right_source.* \
                     FROM compound_star_left AS left_source \
                     JOIN compound_star_right AS right_source USING (a) \
                     UNION ALL SELECT 1, 100 ORDER BY right_source.a;";
                let rows = if prepared {
                    conn.prepare(sql).await.unwrap().query().await.unwrap()
                } else {
                    conn.query(sql).await.unwrap()
                };
                assert_eq!(
                    rows.iter().map(row_values).collect::<Vec<_>>(),
                    vec![
                        vec![SqliteValue::Integer(1), SqliteValue::Integer(100)],
                        vec![SqliteValue::Integer(2), SqliteValue::Integer(200)],
                    ],
                    "qualified star must retain its own USING-column output"
                );
            }
        });
    }

    #[test]
    fn test_compound_collation_inherits_across_arms_and_order_aliases() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            let rows = conn
                .query("SELECT 'a' UNION SELECT 'A' COLLATE NOCASE;")
                .await
                .unwrap();
            assert_eq!(
                rows.iter().map(row_values).collect::<Vec<_>>(),
                vec![vec![SqliteValue::Text("A".into())]]
            );

            let rows = conn
                .query(
                    "SELECT 'a' COLLATE BINARY \
                     UNION SELECT 'A' COLLATE NOCASE ORDER BY 1;",
                )
                .await
                .unwrap();
            assert_eq!(
                rows.iter().map(row_values).collect::<Vec<_>>(),
                vec![
                    vec![SqliteValue::Text("A".into())],
                    vec![SqliteValue::Text("a".into())],
                ]
            );

            for (sql, expected) in [
                (
                    "SELECT 'B' UNION ALL SELECT 'a' COLLATE NOCASE ORDER BY 1;",
                    vec![
                        vec![SqliteValue::Text("a".into())],
                        vec![SqliteValue::Text("B".into())],
                    ],
                ),
                (
                    "SELECT 'B' COLLATE BINARY \
                     UNION ALL SELECT 'a' COLLATE NOCASE ORDER BY 1;",
                    vec![
                        vec![SqliteValue::Text("B".into())],
                        vec![SqliteValue::Text("a".into())],
                    ],
                ),
                (
                    "SELECT 'B' UNION ALL SELECT 'a' COLLATE NOCASE \
                     ORDER BY 1 COLLATE BINARY;",
                    vec![
                        vec![SqliteValue::Text("B".into())],
                        vec![SqliteValue::Text("a".into())],
                    ],
                ),
            ] {
                let rows = conn
                    .query(sql)
                    .await
                    .unwrap_or_else(|error| panic!("{sql}: {error}"));
                assert_eq!(
                    rows.iter().map(row_values).collect::<Vec<_>>(),
                    expected,
                    "sql={sql}"
                );
            }

            let rows = conn
                .query("SELECT 2 AS a UNION ALL SELECT 1 AS b ORDER BY b;")
                .await
                .unwrap();
            assert_eq!(
                rows.iter().map(row_values).collect::<Vec<_>>(),
                vec![vec![SqliteValue::Integer(1)], vec![SqliteValue::Integer(2)],]
            );

            let rows = conn
                .query(
                    "SELECT 'B', 1 COLLATE missing \
                     UNION ALL SELECT 'a', 2 ORDER BY 1 COLLATE NOCASE;",
                )
                .await
                .unwrap();
            assert_eq!(
                rows.iter().map(row_values).collect::<Vec<_>>(),
                vec![
                    vec![SqliteValue::Text("a".into()), SqliteValue::Integer(2)],
                    vec![SqliteValue::Text("B".into()), SqliteValue::Integer(1)],
                ]
            );
        });
    }

    #[test]
    fn test_order_by_collate_preserves_selected_expression_resolution() {
        asupersync::test_utils::run_test(|| async {
            // A COLLATE-wrapped selected expression must remain resolvable through
            // its inner output name. This guards the non-compound regression
            // exposed while fixing GH #217-#221.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE tags(tag TEXT COLLATE NOCASE);")
                .await
                .unwrap();
            conn.execute("INSERT INTO tags VALUES ('beta'), ('Alpha'), ('alpha');")
                .await
                .unwrap();

            let rows = conn
                .query(
                    "SELECT tag COLLATE BINARY, COUNT(*)
                 FROM tags
                 GROUP BY tag COLLATE BINARY
                 ORDER BY tag COLLATE BINARY",
                )
                .await
                .unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values().to_vec())
                    .collect::<Vec<_>>(),
                vec![
                    vec![SqliteValue::Text("Alpha".into()), SqliteValue::Integer(1),],
                    vec![SqliteValue::Text("alpha".into()), SqliteValue::Integer(1),],
                    vec![SqliteValue::Text("beta".into()), SqliteValue::Integer(1),],
                ]
            );
        });
    }

    #[test]
    fn test_order_by_output_reference_precedence() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();

            // A 1-based ordinal must win over structural equality with a later
            // selected integer literal, including when COLLATE wraps the ordinal.
            for sql in [
                "SELECT 2 AS sort_key, 1 AS literal_value
             UNION ALL
             SELECT 1, 1
             ORDER BY 1",
                "SELECT 2 AS sort_key, 1 AS literal_value
             UNION ALL
             SELECT 1, 1
             ORDER BY 1 COLLATE BINARY",
            ] {
                let rows = conn
                    .query(sql)
                    .await
                    .unwrap_or_else(|error| panic!("{sql}: {error}"));
                assert_eq!(
                    rows.iter()
                        .map(|row| row.values().to_vec())
                        .collect::<Vec<_>>(),
                    vec![
                        vec![SqliteValue::Integer(1), SqliteValue::Integer(1)],
                        vec![SqliteValue::Integer(2), SqliteValue::Integer(1)],
                    ],
                    "sql={sql}"
                );
            }

            // An output alias must likewise win over an earlier result expression
            // that structurally matches the underlying source column.
            conn.execute("CREATE TABLE order_aliases(source_value INTEGER, alias_value INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO order_aliases VALUES (2, 1), (1, 2);")
                .await
                .unwrap();
            let rows = conn
                .query(
                    "SELECT source_value, alias_value AS source_value
                 FROM order_aliases
                 ORDER BY source_value",
                )
                .await
                .unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values().to_vec())
                    .collect::<Vec<_>>(),
                vec![
                    vec![SqliteValue::Integer(2), SqliteValue::Integer(1)],
                    vec![SqliteValue::Integer(1), SqliteValue::Integer(2)],
                ]
            );
        });
    }

    #[test]
    fn test_pragma_table_info_excludes_generated_columns() {
        asupersync::test_utils::run_test(|| async {
            // GH #240: table_info omits generated columns and renumbers cid over the
            // remaining columns; table_xinfo still lists them at their real cid.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE t(a INTEGER, b INTEGER GENERATED ALWAYS AS (a*2) STORED, d INTEGER);",
            )
            .await
            .unwrap();
            let info = conn.query("PRAGMA table_info(t);").await.unwrap();
            let names: Vec<_> = info
                .iter()
                .map(|r| (r.values()[0].clone(), r.values()[1].clone()))
                .collect();
            assert_eq!(
                names,
                vec![
                    (SqliteValue::Integer(0), SqliteValue::Text("a".into())),
                    (SqliteValue::Integer(1), SqliteValue::Text("d".into())),
                ]
            );
            // xinfo still contains all three columns.
            let xinfo = conn.query("PRAGMA table_xinfo(t);").await.unwrap();
            assert_eq!(xinfo.len(), 3);
        });
    }

    #[test]
    fn test_create_index_name_collides_with_table_or_view() {
        asupersync::test_utils::run_test(|| async {
            // GH #232: an index cannot reuse a table/view name, even with
            // IF NOT EXISTS.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t(a);").await.unwrap();
            conn.execute("CREATE TABLE x(b);").await.unwrap();
            conn.execute("CREATE VIEW v AS SELECT * FROM x;")
                .await
                .unwrap();
            assert!(
                conn.execute("CREATE INDEX IF NOT EXISTS t ON x(b);")
                    .await
                    .is_err()
            );
            assert!(conn.execute("CREATE INDEX v ON x(b);").await.is_err());
            // A genuinely new index name still works.
            conn.execute("CREATE INDEX ix ON x(b);").await.unwrap();
        });
    }

    #[test]
    #[cfg(feature = "ext-json")]
    fn test_json_group_aggregate_order_by_and_distinct() {
        asupersync::test_utils::run_test(|| async {
            // GH #266/#267/#268: json_group_array/object honor in-aggregate ORDER BY
            // and DISTINCT.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t(x INTEGER);").await.unwrap();
            conn.execute("INSERT INTO t VALUES (3),(1),(1),(2);")
                .await
                .unwrap();

            let one = async |sql: &str| -> String {
                let rows = conn
                    .query(sql)
                    .await
                    .unwrap_or_else(|e| panic!("{sql}: {e:?}"));
                match &rows[0].values()[0] {
                    SqliteValue::Text(s) => s.to_string(),
                    other => panic!("{sql}: expected text, got {other:?}"),
                }
            };

            // #266: ORDER BY sorts the values (no dedup).
            assert_eq!(
                one("SELECT json_group_array(x ORDER BY x) FROM t").await,
                "[1,1,2,3]"
            );
            assert_eq!(
                one("SELECT json_group_array(x ORDER BY x DESC) FROM t").await,
                "[3,2,1,1]"
            );
            // #268: DISTINCT dedups, preserving first-seen order.
            assert_eq!(
                one("SELECT json_group_array(DISTINCT x) FROM t").await,
                "[3,1,2]"
            );
            // DISTINCT + ORDER BY: dedup then sort.
            assert_eq!(
                one("SELECT json_group_array(DISTINCT x ORDER BY x) FROM t").await,
                "[1,2,3]"
            );

            // #267: json_group_object ORDER BY.
            conn.execute("CREATE TABLE kv(k TEXT, v INTEGER);")
                .await
                .unwrap();
            conn.execute("INSERT INTO kv VALUES ('b',2),('a',1),('c',3);")
                .await
                .unwrap();
            assert_eq!(
                one("SELECT json_group_object(k, v ORDER BY k) FROM kv").await,
                r#"{"a":1,"b":2,"c":3}"#
            );
        });
    }

    #[test]
    fn test_row_value_is_between_distinct() {
        asupersync::test_utils::run_test(|| async {
            // GH #170/#171/#243: NULL-safe row-value IS/IS NOT, lexicographic
            // row-value BETWEEN, and row-value IS DISTINCT FROM.
            let conn = Connection::open(":memory:").await.unwrap();
            let b = async |sql: &str| -> i64 {
                let rows = conn
                    .query(sql)
                    .await
                    .unwrap_or_else(|e| panic!("{sql}: {e:?}"));
                match &rows[0].values()[0] {
                    SqliteValue::Integer(n) => *n,
                    other => panic!("{sql}: expected int, got {other:?}"),
                }
            };
            // #170: row-value IS / IS NOT are NULL-safe and componentwise.
            assert_eq!(b("SELECT (1,NULL) IS (1,NULL)").await, 1);
            assert_eq!(b("SELECT (1,NULL) IS (1,2)").await, 0);
            assert_eq!(b("SELECT (1,2) IS NOT (1,3)").await, 1);
            // #171: row-value BETWEEN / NOT BETWEEN (lexicographic).
            assert_eq!(b("SELECT (1,2) BETWEEN (1,1) AND (1,3)").await, 1);
            assert_eq!(b("SELECT (2,0) BETWEEN (1,1) AND (1,3)").await, 0);
            assert_eq!(b("SELECT (2,0) NOT BETWEEN (1,1) AND (1,3)").await, 1);
            // #243: row-value IS DISTINCT FROM (NULL-safe negation of IS).
            assert_eq!(b("SELECT (1,NULL) IS DISTINCT FROM (1,NULL)").await, 0);
            assert_eq!(b("SELECT (1,NULL) IS DISTINCT FROM (1,2)").await, 1);
        });
    }

