    #[test]
    fn test_pragma_integrity_check_reports_corrupt_table_root_page() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'Alice');")
                .await
                .unwrap();

            let root_page = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .map(|table| table.root_page)
                .expect("test table root page");

            // Release cached transactions before raw pager access. The retained
            // autocommit batch still counts as an active pager transaction, so it
            // must also be flushed before calling pager.begin().
            let cx = Cx::new();
            if conn.retained_autocommit_txn.borrow().is_some() {
                conn.flush_retained_autocommit_txn(&cx).await.unwrap();
            }
            conn.invalidate_cached_write_txn(&cx).await;
            conn.invalidate_cached_read_snapshot(&cx).await;
            let mut txn = conn
                .pager
                .begin(&cx, TransactionMode::Immediate)
                .await
                .unwrap();
            let page_no = PageNumber::new(u32::try_from(root_page).unwrap()).unwrap();
            let mut page = txn.get_page(&cx, page_no).await.unwrap().into_vec();
            page[0] = 0xFF;
            txn.write_page(&cx, page_no, &page).await.unwrap();
            txn.commit(&cx).await.unwrap();

            let rows = conn.query("PRAGMA integrity_check;").await.unwrap();
            assert_eq!(rows.len(), 1);
            let SqliteValue::Text(message) = &rows[0].values()[0] else {
                panic!("integrity_check should return a text diagnostic row");
            };
            assert_ne!(&**message, "ok");
            assert!(
                message.contains("invalid B-tree page type")
                    || message.contains("root page")
                    || message.contains("corrupt"),
                "unexpected integrity_check diagnostic: {message}"
            );
        });
    }

    #[test]
    fn test_integrity_checks_reject_empty_non_root_btree_pages_but_accept_empty_roots() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open_with_page_size(":memory:", 1024)
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE t (id INTEGER PRIMARY KEY, payload TEXT); \
                 CREATE INDEX idx_t_id ON t(id);",
            )
            .await
            .unwrap();

            // A zero-cell table root and a zero-cell index root are both valid.
            // Root-ness must come from the catalog walk entry, not page shape.
            for pragma in ["quick_check", "integrity_check"] {
                let rows = conn.query(&format!("PRAGMA {pragma};")).await.unwrap();
                assert_eq!(rows.len(), 1, "{pragma} should return one result row");
                assert_eq!(
                    rows[0].values()[0],
                    SqliteValue::Text("ok".into()),
                    "{pragma} must accept valid empty B-tree roots"
                );
            }

            let table_root_page = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .map(|table| PageNumber::new(u32::try_from(table.root_page).unwrap()).unwrap())
                .expect("test table root page");
            let payload = "z".repeat(900);
            for rowid in 1..=64 {
                conn.execute(&format!("INSERT INTO t VALUES ({rowid}, '{payload}');"))
                    .await
                    .unwrap();

                let cx = Cx::new();
                if conn.retained_autocommit_txn.borrow().is_some() {
                    conn.flush_retained_autocommit_txn(&cx).await.unwrap();
                }
                conn.invalidate_cached_write_txn(&cx).await;
                conn.invalidate_cached_read_snapshot(&cx).await;
                let mut txn = conn
                    .pager
                    .begin(&cx, TransactionMode::ReadOnly)
                    .await
                    .unwrap();
                let root_page = txn.get_page(&cx, table_root_page).await.unwrap();
                let header_offset = fsqlite_btree::header_offset_for_page(table_root_page);
                let root_header =
                    fsqlite_btree::BtreePageHeader::parse(root_page.as_ref(), header_offset)
                        .unwrap();
                let root_is_interior =
                    root_header.page_type == fsqlite_btree::BtreePageType::InteriorTable;
                txn.rollback(&cx).await.unwrap();
                if root_is_interior {
                    break;
                }
                assert!(
                    rowid < 64,
                    "table root did not split under sustained inserts"
                );
            }

            let cx = Cx::new();
            if conn.retained_autocommit_txn.borrow().is_some() {
                conn.flush_retained_autocommit_txn(&cx).await.unwrap();
            }
            conn.invalidate_cached_write_txn(&cx).await;
            conn.invalidate_cached_read_snapshot(&cx).await;
            let mut txn = conn
                .pager
                .begin(&cx, TransactionMode::Immediate)
                .await
                .unwrap();
            let root_page = txn.get_page(&cx, table_root_page).await.unwrap().into_vec();
            let header_offset = fsqlite_btree::header_offset_for_page(table_root_page);
            let root_header =
                fsqlite_btree::BtreePageHeader::parse(&root_page, header_offset).unwrap();
            assert_eq!(
                root_header.page_type,
                fsqlite_btree::BtreePageType::InteriorTable,
                "test setup requires an interior table root"
            );
            let child_page_no = root_header
                .right_child
                .expect("interior table root must reference a right-most child");
            let mut child_page = txn.get_page(&cx, child_page_no).await.unwrap().into_vec();
            let child_header = fsqlite_btree::BtreePageHeader::parse(&child_page, 0).unwrap();
            assert_eq!(
                child_header.page_type,
                fsqlite_btree::BtreePageType::LeafTable,
                "freshly split table root should reference leaf children"
            );
            assert!(
                child_header.cell_count > 0,
                "selected child must be non-empty before corruption"
            );

            let (usable_size, _) = Connection::current_btree_cursor_sizes_in_txn(&cx, &txn)
                .await
                .unwrap();
            child_page.fill(0);
            fsqlite_types::BTreePageHeader::write_empty_leaf_table(&mut child_page, 0, usable_size);
            txn.write_page(&cx, child_page_no, &child_page)
                .await
                .unwrap();
            txn.commit(&cx).await.unwrap();

            conn.invalidate_cached_write_txn(&cx).await;
            conn.invalidate_cached_read_snapshot(&cx).await;
            for pragma in ["quick_check", "integrity_check"] {
                let rows = conn.query(&format!("PRAGMA {pragma};")).await.unwrap();
                assert_eq!(rows.len(), 1, "{pragma} should return one result row");
                let SqliteValue::Text(message) = &rows[0].values()[0] else {
                    panic!("{pragma} should return a text diagnostic row");
                };
                assert!(
                    message.contains("empty non-root B-tree page"),
                    "unexpected {pragma} diagnostic: {message}"
                );
            }
        });
    }

    #[test]
    fn test_pragma_integrity_check_reports_corrupt_secondary_index_entry() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("CREATE INDEX idx_t_name ON t(name);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'Alice');")
                .await
                .unwrap();

            let index_root = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .and_then(|table| {
                    table
                        .indexes
                        .iter()
                        .find(|index| index.name.eq_ignore_ascii_case("idx_t_name"))
                        .map(|index| index.root_page)
                })
                .expect("test index root page");

            // Release cached transactions before raw pager access. The retained
            // autocommit batch still counts as an active pager transaction, so it
            // must also be flushed before calling pager.begin().
            let cx = Cx::new();
            if conn.retained_autocommit_txn.borrow().is_some() {
                conn.flush_retained_autocommit_txn(&cx).await.unwrap();
            }
            conn.invalidate_cached_write_txn(&cx).await;
            conn.invalidate_cached_read_snapshot(&cx).await;
            let mut txn = conn
                .pager
                .begin(&cx, TransactionMode::Immediate)
                .await
                .unwrap();
            let page_no = PageNumber::new(u32::try_from(index_root).unwrap()).unwrap();
            let mut page = txn.get_page(&cx, page_no).await.unwrap().into_vec();
            let header_offset = fsqlite_btree::header_offset_for_page(page_no);
            let header = fsqlite_btree::BtreePageHeader::parse(&page, header_offset).unwrap();
            let cell_pointers =
                fsqlite_btree::read_cell_pointers(&page, &header, header_offset).unwrap();
            let cell = fsqlite_btree::CellRef::parse(
                &page,
                usize::from(cell_pointers[0]),
                header.page_type,
                u32::try_from(page.len()).unwrap(),
            )
            .unwrap();
            let local_payload_end = cell.payload_offset + usize::try_from(cell.local_size).unwrap();
            page[local_payload_end - 1] ^= 0x01;
            txn.write_page(&cx, page_no, &page).await.unwrap();
            txn.commit(&cx).await.unwrap();

            let rows = conn.query("PRAGMA integrity_check;").await.unwrap();
            assert_eq!(rows.len(), 1);
            let SqliteValue::Text(message) = &rows[0].values()[0] else {
                panic!("integrity_check should return a text diagnostic row");
            };
            assert_ne!(&**message, "ok");
            assert!(
                message.contains("idx_t_name")
                    || message.contains("stale rowid")
                    || message.contains("does not match"),
                "unexpected integrity_check diagnostic: {message}"
            );
        });
    }

    #[test]
    fn test_pragma_integrity_check_reports_out_of_order_nocase_index_entry() {
        asupersync::test_utils::run_test(|| async {
            // frankensqlite#112 adversarial guard: applying the index collation in
            // the key-ordering check must NOT weaken genuine-corruption detection.
            // Build a valid NOCASE index (`'a'` rowid 1, `'B'` rowid 2 — NOCASE
            // order is a < B), then physically swap the two leaf cell pointers so
            // the stored traversal order becomes `'B','a'`, which violates NOCASE
            // ordering (NOCASE 'B' > 'a'). integrity_check must still flag this as
            // "out of order". Canonical sqlite3 3.46.1 confirms the unswapped index
            // is genuinely valid (scans a, B; integrity_check = ok), so the only
            // thing under test here is that the collation-aware comparator detects
            // a real physical misordering.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("CREATE INDEX idx_t_name ON t(name COLLATE NOCASE);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'a');")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (2, 'B');")
                .await
                .unwrap();

            // Sanity: as built, the NOCASE index is reported `ok`.
            let ok = conn.query("PRAGMA integrity_check;").await.unwrap();
            assert_eq!(
                *ok[0].get(0).unwrap(),
                SqliteValue::Text("ok".into()),
                "freshly built NOCASE index must pass integrity_check"
            );

            let index_root = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .and_then(|table| {
                    table
                        .indexes
                        .iter()
                        .find(|index| index.name.eq_ignore_ascii_case("idx_t_name"))
                        .map(|index| index.root_page)
                })
                .expect("test index root page");

            let cx = Cx::new();
            if conn.retained_autocommit_txn.borrow().is_some() {
                conn.flush_retained_autocommit_txn(&cx).await.unwrap();
            }
            conn.invalidate_cached_write_txn(&cx).await;
            conn.invalidate_cached_read_snapshot(&cx).await;
            let mut txn = conn
                .pager
                .begin(&cx, TransactionMode::Immediate)
                .await
                .unwrap();
            let page_no = PageNumber::new(u32::try_from(index_root).unwrap()).unwrap();
            let mut page = txn.get_page(&cx, page_no).await.unwrap().into_vec();
            let header_offset = fsqlite_btree::header_offset_for_page(page_no);
            let header = fsqlite_btree::BtreePageHeader::parse(&page, header_offset).unwrap();
            assert!(
                header.page_type.is_leaf(),
                "two-entry index root must be a single leaf page"
            );
            let mut cell_pointers =
                fsqlite_btree::read_cell_pointers(&page, &header, header_offset).unwrap();
            assert_eq!(
                cell_pointers.len(),
                2,
                "expected exactly two index leaf entries"
            );
            // Swap the two leaf cell pointers: traversal order flips to `'B','a'`,
            // which is out of NOCASE order. Payload bytes are untouched, so the
            // ONLY invariant violated is key ordering — isolating the collation
            // comparator rather than the payload-match check.
            cell_pointers.swap(0, 1);
            fsqlite_btree::write_cell_pointers(&mut page, header_offset, &header, &cell_pointers);
            txn.write_page(&cx, page_no, &page).await.unwrap();
            txn.commit(&cx).await.unwrap();

            let rows = conn.query("PRAGMA integrity_check;").await.unwrap();
            assert_eq!(rows.len(), 1);
            let SqliteValue::Text(message) = &rows[0].values()[0] else {
                panic!("integrity_check should return a text diagnostic row");
            };
            assert_ne!(
                &**message, "ok",
                "a physically misordered NOCASE leaf must not be reported ok"
            );
            assert!(
                message.contains("out of order") && message.contains("idx_t_name"),
                "expected an out-of-order diagnostic for idx_t_name, got: {message}"
            );
        });
    }

    #[test]
    fn test_in_txn_integrity_check_ignores_stale_freelist_count_header() {
        asupersync::test_utils::run_test(|| async {
            // GH#113: inside a write transaction the page-1 freelist_count (offset
            // 36) and the on-disk freelist trunk are a deferred commit-time
            // projection — they stay at the last-committed value until COMMIT runs
            // serialize_freelist_to_write_set. The in-transaction integrity walk
            // must therefore NOT validate the live btree against this stale header
            // (it uses the pager's live freelist set instead); doing so produced
            // false "freelist header claims N" / "malformed" reports for a database
            // whose committed state is consistent. A deliberately wrong committed
            // count poked here must be ignored mid-transaction. The committed-state
            // integrity_check (no active txn) still walks the on-disk trunk and
            // validates this header — see validate_page_ownership_in_txn.
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO t VALUES (1, 'Alice');")
                .await
                .unwrap();

            conn.execute("BEGIN IMMEDIATE;").await.unwrap();
            let cx = Cx::new();
            {
                let mut active_txn = conn.active_txn.borrow_mut();
                let txn = active_txn
                    .as_mut()
                    .expect("explicit BEGIN should create an active pager transaction");
                let mut page1 = txn.get_page(&cx, PageNumber::ONE).await.unwrap().into_vec();
                // A bogus committed freelist_count that does not match the live state.
                page1[36..40].copy_from_slice(&12345_u32.to_be_bytes());
                txn.write_page(&cx, PageNumber::ONE, &page1).await.unwrap();
            }

            let rows = conn.query("PRAGMA integrity_check;").await.unwrap();
            conn.execute("ROLLBACK;").await.unwrap();
            assert_eq!(rows.len(), 1);
            let SqliteValue::Text(message) = &rows[0].values()[0] else {
                panic!("integrity_check should return a text diagnostic row");
            };
            assert_eq!(
                &**message, "ok",
                "in-transaction integrity_check must ignore the deferred/stale freelist_count \
             header (GH#113); got: {message}"
            );
        });
    }

    #[test]
    fn test_pragma_quick_check_reports_lock_byte_page_reference() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open_with_page_size(":memory:", 1024)
                .await
                .unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, payload TEXT);")
                .await
                .unwrap();

            let table_root_page = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("t"))
                .map(|table| PageNumber::new(u32::try_from(table.root_page).unwrap()).unwrap())
                .expect("test table root page");

            let payload = "z".repeat(900);
            let root_is_interior = async || {
                let cx = Cx::new();
                if conn.retained_autocommit_txn.borrow().is_some() {
                    conn.flush_retained_autocommit_txn(&cx).await.unwrap();
                }
                conn.invalidate_cached_write_txn(&cx).await;
                conn.invalidate_cached_read_snapshot(&cx).await;
                let mut txn = conn
                    .pager
                    .begin(&cx, TransactionMode::ReadOnly)
                    .await
                    .unwrap();
                let page = txn.get_page(&cx, table_root_page).await.unwrap();
                let header = fsqlite_btree::BtreePageHeader::parse(
                    page.as_ref(),
                    fsqlite_btree::header_offset_for_page(table_root_page),
                )
                .unwrap();
                txn.rollback(&cx).await.unwrap();
                header.page_type == fsqlite_btree::BtreePageType::InteriorTable
            };

            for rowid in 1..=64 {
                conn.execute(&format!("INSERT INTO t VALUES ({rowid}, '{}');", payload))
                    .await
                    .unwrap();
                if root_is_interior().await {
                    break;
                }
                assert!(
                    rowid < 64,
                    "table root did not split under sustained inserts"
                );
            }

            let lock_page = PageNumber::new(fsqlite_pager::lock_byte_page(conn.pager.page_size()))
                .expect("lock-byte page number");
            let cx = Cx::new();
            if conn.retained_autocommit_txn.borrow().is_some() {
                conn.flush_retained_autocommit_txn(&cx).await.unwrap();
            }
            conn.invalidate_cached_write_txn(&cx).await;
            conn.invalidate_cached_read_snapshot(&cx).await;

            let mut txn = conn
                .pager
                .begin(&cx, TransactionMode::Immediate)
                .await
                .unwrap();
            let mut root_page = txn.get_page(&cx, table_root_page).await.unwrap().into_vec();
            let header_offset = fsqlite_btree::header_offset_for_page(table_root_page);
            let root_header =
                fsqlite_btree::BtreePageHeader::parse(&root_page, header_offset).unwrap();
            assert_eq!(
                root_header.page_type,
                fsqlite_btree::BtreePageType::InteriorTable,
                "test setup requires an interior table root"
            );
            root_page[header_offset + 8..header_offset + 12]
                .copy_from_slice(&lock_page.get().to_be_bytes());
            let lock_page_bytes =
                vec![0_u8; usize::try_from(conn.pager.page_size().get()).unwrap()];
            txn.write_page(&cx, lock_page, &lock_page_bytes)
                .await
                .unwrap();
            txn.write_page(&cx, table_root_page, &root_page)
                .await
                .unwrap();
            txn.commit(&cx).await.unwrap();

            conn.invalidate_cached_write_txn(&cx).await;
            conn.invalidate_cached_read_snapshot(&cx).await;
            let rows = conn.query("PRAGMA quick_check;").await.unwrap();
            assert_eq!(rows.len(), 1);
            let SqliteValue::Text(message) = &rows[0].values()[0] else {
                panic!("quick_check should return a text diagnostic row");
            };
            assert!(
                message.contains("reserved lock-byte page"),
                "unexpected quick_check diagnostic: {message}"
            );
        });
    }

    #[test]
    fn test_integrity_ownership_exempts_only_the_reserved_lock_byte_page() {
        for raw_page_size in [512_u32, 1_024, 2_048, 4_096, 8_192, 16_384, 65_536] {
            let page_size = PageSize::new(raw_page_size).expect("valid SQLite page size");
            let lock_page = fsqlite_pager::lock_byte_page(page_size);
            let total_pages = lock_page.saturating_add(1);

            let missing_only_lock =
                Connection::first_unowned_database_page(total_pages, page_size, |page_no| {
                    page_no.get() != lock_page
                });
            assert_eq!(
                missing_only_lock, None,
                "the 1 GiB lock-byte page must be exempt at page size {raw_page_size}"
            );

            for missing_page in [lock_page - 1, lock_page + 1] {
                let first_missing =
                    Connection::first_unowned_database_page(total_pages, page_size, |page_no| {
                        page_no.get() != missing_page
                    });
                assert_eq!(
                    first_missing.map(PageNumber::get),
                    Some(missing_page),
                    "neighboring page {missing_page} must still require ownership at page size {raw_page_size}"
                );
            }
        }
    }

