    #[cfg(feature = "ext-json")]
    #[test]
    fn test_jsonb_blobs_round_trip_through_stock_sqlite() {
        // bd-t75hg: a JSONB blob stored by FrankenSQLite must be readable by
        // stock SQLite (rusqlite = bundled C SQLite) and vice versa —
        // numeric payloads are ASCII text per the JSONB spec, so both
        // engines must render identical json() text from each other's blobs.
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let path = dir
                .path()
                .join("jsonb_interop.db")
                .to_string_lossy()
                .into_owned();
            let doc = r#"{"a":1,"b":-7,"c":1.5,"d":-0.0,"e":1e300,"f":[9223372036854775807,"x"],"g":"q\"z"}"#;

            // FrankenSQLite writes, stock reads.
            let conn = Connection::open(path.clone()).await.unwrap();
            conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, doc BLOB);")
                .await
                .unwrap();
            conn.execute(&format!(
                "INSERT INTO t VALUES (1, jsonb('{}'));",
                doc.replace('\'', "''")
            ))
            .await
            .unwrap();
            let ours = conn.query("SELECT json(doc) FROM t;").await.unwrap();
            let ours_text = match &ours[0].values()[0] {
                SqliteValue::Text(t) => t.to_string(),
                other => panic!("expected text, got {other:?}"),
            };
            conn.execute("PRAGMA wal_checkpoint(TRUNCATE);")
                .await
                .unwrap();
            conn.close().await.unwrap();

            let stock = rusqlite::Connection::open(&path).unwrap();
            let stock_text: String = stock
                .query_row("SELECT json(doc) FROM t", [], |row| row.get(0))
                .unwrap();
            assert_eq!(
                stock_text, ours_text,
                "stock sqlite3 must render our JSONB identically"
            );

            // Stock writes, FrankenSQLite reads.
            stock
                .execute(
                    "INSERT INTO t VALUES (2, jsonb(?1))",
                    rusqlite::params![doc],
                )
                .unwrap();
            let stock_text2: String = stock
                .query_row("SELECT json(doc) FROM t WHERE id = 2", [], |row| row.get(0))
                .unwrap();
            drop(stock);

            let conn = Connection::open(path).await.unwrap();
            let back = conn
                .query("SELECT json(doc) FROM t WHERE id = 2;")
                .await
                .unwrap();
            let back_text = match &back[0].values()[0] {
                SqliteValue::Text(t) => t.to_string(),
                other => panic!("expected text, got {other:?}"),
            };
            assert_eq!(
                back_text, stock_text2,
                "we must render stock-written JSONB identically"
            );
        });
    }

    #[test]
    fn test_delete_not_in_ordered_limited_subquery_matches_oracle() {
        // bd-brzp8 oracle (sqlite3 3.46.1): the mcp_agent_mail_rust prune
        // shape — DELETE ... WHERE pinned=0 AND id NOT IN (SELECT id ...
        // ORDER BY updated_ts DESC LIMIT ?) — keeps pinned rows plus the
        // most-recent N unpinned rows (kept ids {2,3,4} for LIMIT 2 on the
        // seed below). 0.3.0 halted with 'IN probe codegen invariant failed:
        // unsupported probe source'. File-backed: the failure is in the
        // compiled VDBE probe path.
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let path = dir
                .path()
                .join("brzp8_prune.db")
                .to_string_lossy()
                .into_owned();
            let conn = Connection::open(path).await.unwrap();
            conn.execute(
                "CREATE TABLE search_recipes(id INTEGER PRIMARY KEY, pinned INTEGER NOT NULL DEFAULT 0, updated_ts INTEGER NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute(
                "INSERT INTO search_recipes VALUES (1,0,100),(2,0,200),(3,1,50),(4,0,300),(5,0,150);",
            )
            .await
            .unwrap();

            // Parameterized LIMIT, exactly like the downstream statement.
            let stmt = conn
                .prepare(
                    "DELETE FROM search_recipes WHERE pinned=0 AND id NOT IN \
                     (SELECT id FROM search_recipes WHERE pinned=0 ORDER BY updated_ts DESC LIMIT ?1)",
                )
                .await
                .expect("prune statement must prepare");
            stmt.execute_with_params(&[SqliteValue::Integer(2)])
                .await
                .expect("prune statement must execute (bd-brzp8)");

            let rows = conn
                .query("SELECT id FROM search_recipes ORDER BY id;")
                .await
                .unwrap();
            let ids: Vec<_> = rows.iter().map(|row| row.values()[0].clone()).collect();
            assert_eq!(
                ids,
                vec![
                    SqliteValue::Integer(2),
                    SqliteValue::Integer(3),
                    SqliteValue::Integer(4),
                ],
                "prune must keep pinned + most-recent-2 unpinned (oracle parity)"
            );

            // Literal-LIMIT variant of the same shape must also run.
            conn.execute(
                "DELETE FROM search_recipes WHERE pinned=0 AND id NOT IN \
                 (SELECT id FROM search_recipes WHERE pinned=0 ORDER BY updated_ts DESC LIMIT 1)",
            )
            .await
            .expect("literal-limit prune must execute");
            let rows = conn
                .query("SELECT id FROM search_recipes ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 2, "kept pinned row 3 + newest unpinned row 4");

            // Strict no-fallback arm: the same shape must run on the COMPILED
            // path too — the downstream 0.3.0 failure was a VDBE halt, so a
            // keeper satisfied by the interpreted fallback alone would be
            // vacuous for the reported defect.
            conn.set_strict_mem_fallback_rejection(true);
            conn.execute("INSERT INTO search_recipes VALUES (6,0,400),(7,0,50);")
                .await
                .unwrap();
            conn.execute(
                "DELETE FROM search_recipes WHERE pinned=0 AND id NOT IN \
                 (SELECT id FROM search_recipes WHERE pinned=0 ORDER BY updated_ts DESC LIMIT 2)",
            )
            .await
            .expect("strict-mode prune must execute on the compiled path (bd-brzp8)");
            conn.set_strict_mem_fallback_rejection(false);
            let rows = conn
                .query("SELECT id FROM search_recipes ORDER BY id;")
                .await
                .unwrap();
            let ids: Vec<_> = rows.iter().map(|row| row.values()[0].clone()).collect();
            assert_eq!(
                ids,
                vec![
                    SqliteValue::Integer(3),
                    SqliteValue::Integer(4),
                    SqliteValue::Integer(6),
                ],
                "strict-mode prune keeps pinned 3 + top-2 unpinned {{6,4}}"
            );
        });
    }

    #[test]
    fn test_delete_not_in_ordered_limited_subquery_shape_variants_never_halt() {
        // bd-brzp8 fidelity sweep: the minimal bead shape passes at HEAD, but
        // the downstream 0.3.0 halt may have depended on schema context.
        // Every variant must at least EXECUTE (no 'VDBE halted' / probe
        // invariant failure); strict no-fallback keeps the compiled path hot.
        asupersync::test_utils::run_test(|| async {
            let variants: &[(&str, &str, &str)] = &[
                (
                    "without_rowid",
                    "CREATE TABLE sr(id TEXT PRIMARY KEY, pinned INTEGER NOT NULL DEFAULT 0, updated_ts INTEGER NOT NULL) WITHOUT ROWID;",
                    "INSERT INTO sr VALUES ('a',0,100),('b',0,200),('c',1,50),('d',0,300);",
                ),
                (
                    "text_pk_rowid",
                    "CREATE TABLE sr(id TEXT PRIMARY KEY, pinned INTEGER NOT NULL DEFAULT 0, updated_ts INTEGER NOT NULL);",
                    "INSERT INTO sr VALUES ('a',0,100),('b',0,200),('c',1,50),('d',0,300);",
                ),
                (
                    "indexed_wide",
                    "CREATE TABLE sr(id INTEGER PRIMARY KEY, name TEXT, query_json TEXT, pinned INTEGER NOT NULL DEFAULT 0, use_count INTEGER DEFAULT 0, updated_ts INTEGER NOT NULL); \
                     CREATE INDEX idx_sr_ts ON sr(updated_ts DESC); \
                     CREATE INDEX idx_sr_pinned ON sr(pinned) WHERE pinned=1;",
                    "INSERT INTO sr(id,name,query_json,pinned,updated_ts) VALUES (1,'a','{}',0,100),(2,'b','{}',0,200),(3,'c','{}',1,50),(4,'d','{}',0,300);",
                ),
            ];
            for (label, ddl, seed) in variants {
                let dir = tempfile::tempdir().unwrap();
                let path = dir
                    .path()
                    .join(format!("brzp8_{label}.db"))
                    .to_string_lossy()
                    .into_owned();
                let conn = Connection::open(path).await.unwrap();
                for stmt in ddl.split(';').map(str::trim).filter(|s| !s.is_empty()) {
                    conn.execute(stmt).await.unwrap();
                }
                conn.execute(seed).await.unwrap();
                conn.set_strict_mem_fallback_rejection(true);
                let result = conn
                    .execute(
                        "DELETE FROM sr WHERE pinned=0 AND id NOT IN \
                         (SELECT id FROM sr WHERE pinned=0 ORDER BY updated_ts DESC LIMIT 2)",
                    )
                    .await;
                conn.set_strict_mem_fallback_rejection(false);
                match &result {
                    Ok(_) => {}
                    Err(error) => {
                        let text = format!("{error:?}");
                        assert!(
                            !text.contains("halted") && !text.contains("invariant"),
                            "variant {label} reproduced the bd-brzp8 halt: {text}"
                        );
                        panic!("variant {label} failed unexpectedly: {text}");
                    }
                }
                let rows = conn.query("SELECT count(*) FROM sr;").await.unwrap();
                assert_eq!(
                    rows[0].values()[0],
                    SqliteValue::Integer(3),
                    "variant {label}: pinned + top-2 unpinned must remain"
                );
            }
        });
    }

    #[test]
    fn test_pragma_integrity_check_honors_collate_in_partial_index_predicate() {
        // bd-integrity-partial-collate-puctc oracle (sqlite3 3.46.1): the row
        // ('FiRe') satisfies `label COLLATE NOCASE = 'fire'`, is admitted to
        // the partial index at INSERT time, and integrity_check reports `ok`.
        // The integrity evaluator must re-evaluate the persisted predicate
        // with the same explicit-COLLATE semantics as the DML membership path.
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE t(id INTEGER PRIMARY KEY, value INTEGER NOT NULL, label TEXT NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute(
                "CREATE INDEX idx_t_live ON t(value) WHERE value >= 0 AND label COLLATE NOCASE = 'fire';",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO t(id,value,label) VALUES(1,1000,'FiRe');")
                .await
                .unwrap();

            let rows = conn.query("PRAGMA integrity_check;").await.unwrap();
            assert_eq!(
                rows[0].values()[0],
                SqliteValue::Text("ok".into()),
                "COLLATE NOCASE partial-index membership must match the oracle: {rows:?}"
            );

            // The bead's exact shape is file-backed: the persisted predicate
            // must survive sqlite_schema reload with its COLLATE intact.
            let dir = tempfile::tempdir().unwrap();
            let path = dir
                .path()
                .join("partial_collate.db")
                .to_string_lossy()
                .into_owned();
            let seed = Connection::open(path.clone()).await.unwrap();
            seed.execute(
                "CREATE TABLE t(id INTEGER PRIMARY KEY, value INTEGER NOT NULL, label TEXT NOT NULL);",
            )
            .await
            .unwrap();
            seed.execute(
                "CREATE INDEX idx_t_live ON t(value) WHERE value >= 0 AND label COLLATE NOCASE = 'fire';",
            )
            .await
            .unwrap();
            seed.execute("INSERT INTO t(id,value,label) VALUES(1,1000,'FiRe');")
                .await
                .unwrap();
            seed.close().await.unwrap();

            let reopened = Connection::open(path).await.unwrap();
            let rows = reopened.query("PRAGMA integrity_check;").await.unwrap();
            assert_eq!(
                rows[0].values()[0],
                SqliteValue::Text("ok".into()),
                "reloaded persisted COLLATE predicate must still match the oracle: {rows:?}"
            );
        });
    }

    #[test]
    fn test_foreign_key_check_without_rowid_child_reports_null_locator() {
        // bd-y18u1 oracle (sqlite3 3.46.1): a violating WITHOUT ROWID child
        // yields a diagnostic row whose child-row-locator column is NULL
        // (`guarded_wor||parent|0`), while a rowid child reports its integer
        // rowid (`child_rowid|7|parent|0`).
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE parent(pk INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE guarded_wor(a TEXT, b INTEGER REFERENCES parent(pk), PRIMARY KEY(a)) WITHOUT ROWID;",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO guarded_wor VALUES('x', 99);")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE child_rowid(id INTEGER PRIMARY KEY, r INTEGER REFERENCES parent(pk));",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO child_rowid VALUES(7, 88);")
                .await
                .unwrap();

            let mut rows = conn
                .query("PRAGMA foreign_key_check;")
                .await
                .expect("foreign_key_check must not abort on WITHOUT ROWID children")
                .into_iter()
                .map(|row| row.values().to_vec())
                .collect::<Vec<_>>();
            rows.sort_by(|a, b| format!("{a:?}").cmp(&format!("{b:?}")));
            assert_eq!(rows.len(), 2, "both violations must be reported: {rows:?}");
            assert_eq!(
                rows[0],
                vec![
                    SqliteValue::Text("child_rowid".into()),
                    SqliteValue::Integer(7),
                    SqliteValue::Text("parent".into()),
                    SqliteValue::Integer(0),
                ],
            );
            assert_eq!(
                rows[1],
                vec![
                    SqliteValue::Text("guarded_wor".into()),
                    SqliteValue::Null,
                    SqliteValue::Text("parent".into()),
                    SqliteValue::Integer(0),
                ],
            );
        });
    }

