    /// Multi-table JOIN patterns, self-join, CROSS JOIN, and complex
    /// WHERE conditions with subqueries and expressions.
    #[test]
    fn test_conformance_join_patterns() {
        asupersync::test_utils::run_test(|| async {
            let fconn = Connection::open(":memory:").await.unwrap();
            let rconn = rusqlite::Connection::open_in_memory().unwrap();

            let setup = [
                "CREATE TABLE t1 (id INTEGER PRIMARY KEY, val TEXT, grp INTEGER);",
                "INSERT INTO t1 VALUES (1, 'a', 1);",
                "INSERT INTO t1 VALUES (2, 'b', 1);",
                "INSERT INTO t1 VALUES (3, 'c', 2);",
                "INSERT INTO t1 VALUES (4, 'd', 2);",
                "INSERT INTO t1 VALUES (5, 'e', 3);",
                "CREATE TABLE t2 (id INTEGER PRIMARY KEY, t1_id INTEGER, score INTEGER);",
                "INSERT INTO t2 VALUES (1, 1, 100);",
                "INSERT INTO t2 VALUES (2, 2, 200);",
                "INSERT INTO t2 VALUES (3, 3, 300);",
                "INSERT INTO t2 VALUES (4, 1, 150);",
            ];
            for s in &setup {
                fconn.execute(s).await.unwrap();
                rconn.execute_batch(s).unwrap();
            }

            let queries = [
                // Self-join
                "SELECT a.val, b.val FROM t1 a, t1 b WHERE a.grp = b.grp AND a.id < b.id ORDER BY a.val, b.val",
                // CROSS JOIN
                "SELECT t1.val, t2.score FROM t1 CROSS JOIN t2 WHERE t1.id = 1 ORDER BY t2.score",
                // Multiple JOINs
                "SELECT t1.val, t2.score FROM t1 JOIN t2 ON t1.id = t2.t1_id ORDER BY t1.val, t2.score",
                // LEFT JOIN with IS NULL (anti-join pattern)
                "SELECT t1.val FROM t1 LEFT JOIN t2 ON t1.id = t2.t1_id WHERE t2.id IS NULL ORDER BY t1.val",
                // Subquery in WHERE with multiple conditions
                "SELECT val FROM t1 WHERE grp = (SELECT grp FROM t1 WHERE val = 'a') AND id > 1 ORDER BY val",
                // EXISTS with correlated subquery
                "SELECT val FROM t1 WHERE EXISTS (SELECT 1 FROM t2 WHERE t2.t1_id = t1.id AND t2.score > 150) ORDER BY val",
                // NOT IN with subquery
                "SELECT val FROM t1 WHERE id NOT IN (SELECT t1_id FROM t2) ORDER BY val",
                // Aggregate with HAVING and ORDER BY alias
                "SELECT grp, SUM(LENGTH(val)) AS total_len FROM t1 GROUP BY grp HAVING total_len > 1 ORDER BY grp",
                // Subquery as derived table with alias
                "SELECT sub.max_score FROM (SELECT t1_id, MAX(score) AS max_score FROM t2 GROUP BY t1_id) sub ORDER BY sub.max_score DESC",
                // UNION of self-join results
                "SELECT val FROM t1 WHERE grp = 1 UNION SELECT val FROM t1 WHERE grp = 2 ORDER BY 1",
            ];

            let mismatches = oracle_compare(&fconn, &rconn, &queries).await;
            if !mismatches.is_empty() {
                for m in &mismatches {
                    eprintln!("{m}\n");
                }
                panic!(
                    "{} join patterns conformance mismatches found",
                    mismatches.len()
                );
            }
        });
    }

    /// Deep probe: NULL propagation through arithmetic and comparisons,
    /// mixed-type IN lists, BETWEEN edge cases, complex CASE WHEN.
    #[test]
    fn test_conformance_null_and_type_edge_cases() {
        asupersync::test_utils::run_test(|| async {
            let fconn = Connection::open(":memory:").await.unwrap();
            let rconn = rusqlite::Connection::open_in_memory().unwrap();

            let setup = [
                "CREATE TABLE t (id INTEGER PRIMARY KEY, a INTEGER, b REAL, c TEXT, d BLOB);",
                "INSERT INTO t VALUES (1, 10, 1.5, 'hello', X'CAFE');",
                "INSERT INTO t VALUES (2, NULL, 2.5, NULL, NULL);",
                "INSERT INTO t VALUES (3, 0, 0.0, '', X'');",
                "INSERT INTO t VALUES (4, -5, -1.5, 'world', X'BABE');",
            ];
            for s in &setup {
                fconn.execute(s).await.unwrap();
                rconn.execute_batch(s).unwrap();
            }

            let queries = [
                // NULL arithmetic propagation
                "SELECT NULL + 1, NULL * 2, NULL - 3, NULL / 4",
                "SELECT a + NULL, NULL + a FROM t ORDER BY id",
                // NULL comparison returns NULL (not true/false)
                "SELECT NULL = NULL, NULL != NULL, NULL < 1, NULL > 1",
                "SELECT NULL = 0, NULL != 0",
                // NULL in CASE WHEN
                "SELECT CASE NULL WHEN NULL THEN 'match' ELSE 'no' END",
                "SELECT CASE WHEN NULL THEN 'true' ELSE 'false' END",
                // IN with mixed types
                "SELECT 1 IN (1, 2, 3), 1 IN (1.0, 2, 3)",
                "SELECT 'a' IN ('a', 'b', 'c')",
                "SELECT NULL IN (1, 2, 3), 1 IN (1, NULL, 3)",
                // BETWEEN edge cases
                "SELECT 5 BETWEEN 1 AND 10, 0 BETWEEN 1 AND 10",
                "SELECT NULL BETWEEN 1 AND 10, 5 BETWEEN NULL AND 10, 5 BETWEEN 1 AND NULL",
                // NOT BETWEEN
                "SELECT 5 NOT BETWEEN 1 AND 10, 0 NOT BETWEEN 1 AND 10",
                // Boolean expressions
                "SELECT 1 AND 1, 1 AND 0, 0 AND 0",
                "SELECT 1 OR 0, 0 OR 0, 1 OR 1",
                "SELECT NOT 1, NOT 0, NOT NULL",
                // Truthiness
                "SELECT CASE WHEN 0 THEN 'yes' ELSE 'no' END",
                "SELECT CASE WHEN '' THEN 'yes' ELSE 'no' END",
                "SELECT CASE WHEN 0.0 THEN 'yes' ELSE 'no' END",
                // IFNULL / NULLIF
                "SELECT ifnull(NULL, 'default'), ifnull('value', 'default')",
                "SELECT nullif(1, 1), nullif(1, 2), nullif(NULL, 1)",
                // Type affinity in comparisons
                "SELECT '10' > 9, '10' > '9'",
                "SELECT typeof('10' + 0), typeof(10 || '')",
                // Concatenation with NULL
                "SELECT 'a' || NULL, NULL || 'b', NULL || NULL",
            ];

            let mismatches = oracle_compare(&fconn, &rconn, &queries).await;
            if !mismatches.is_empty() {
                for m in &mismatches {
                    eprintln!("{m}\n");
                }
                panic!("{} NULL/type edge case mismatches found", mismatches.len());
            }
        });
    }

    /// VDBE codegen path: single-table queries with WHERE, ORDER BY, LIMIT,
    /// and index scans that go through compile_table_select.
    #[test]
    fn test_conformance_vdbe_codegen_path() {
        asupersync::test_utils::run_test(|| async {
            let fconn = Connection::open(":memory:").await.unwrap();
            let rconn = rusqlite::Connection::open_in_memory().unwrap();

            let setup = [
                "CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, age INTEGER, email TEXT);",
                "CREATE INDEX idx_users_age ON users(age);",
                "CREATE INDEX idx_users_name ON users(name);",
                "INSERT INTO users VALUES (1, 'Alice', 30, 'alice@example.com');",
                "INSERT INTO users VALUES (2, 'Bob', 25, 'bob@example.com');",
                "INSERT INTO users VALUES (3, 'Carol', 35, NULL);",
                "INSERT INTO users VALUES (4, 'Dave', 25, 'dave@example.com');",
                "INSERT INTO users VALUES (5, 'Eve', 40, 'eve@example.com');",
            ];
            for s in &setup {
                fconn.execute(s).await.unwrap();
                rconn.execute_batch(s).unwrap();
            }

            let queries = [
                // Basic full-table scan
                "SELECT * FROM users ORDER BY id",
                // Simple WHERE
                "SELECT name FROM users WHERE age > 30 ORDER BY name",
                // WHERE with AND
                "SELECT name FROM users WHERE age >= 25 AND age <= 35 ORDER BY name",
                // WHERE with OR
                "SELECT name FROM users WHERE age = 25 OR age = 40 ORDER BY name",
                // WHERE with NOT
                "SELECT name FROM users WHERE NOT (age > 30) ORDER BY name",
                // WHERE IS NULL
                "SELECT name FROM users WHERE email IS NULL",
                // WHERE IS NOT NULL
                "SELECT name FROM users WHERE email IS NOT NULL ORDER BY name",
                // ORDER BY DESC
                "SELECT name, age FROM users ORDER BY age DESC, name ASC",
                // LIMIT
                "SELECT name FROM users ORDER BY id LIMIT 3",
                // LIMIT with OFFSET
                "SELECT name FROM users ORDER BY id LIMIT 2 OFFSET 2",
                // LIMIT 0
                "SELECT name FROM users ORDER BY id LIMIT 0",
                // LIMIT 1
                "SELECT name FROM users ORDER BY id LIMIT 1",
                // COUNT with WHERE
                "SELECT COUNT(*) FROM users WHERE age > 30",
                // Multiple columns with expressions
                "SELECT id, name, age * 2 AS double_age FROM users ORDER BY id",
                // WHERE with LIKE
                "SELECT name FROM users WHERE name LIKE 'A%' ORDER BY name",
                // WHERE with IN list
                "SELECT name FROM users WHERE age IN (25, 35) ORDER BY name",
                // DISTINCT
                "SELECT DISTINCT age FROM users ORDER BY age",
                // WHERE with BETWEEN
                "SELECT name FROM users WHERE age BETWEEN 25 AND 35 ORDER BY name",
            ];

            let mismatches = oracle_compare(&fconn, &rconn, &queries).await;
            if !mismatches.is_empty() {
                for m in &mismatches {
                    eprintln!("{m}\n");
                }
                panic!(
                    "{} VDBE codegen conformance mismatches found",
                    mismatches.len()
                );
            }
        });
    }

    /// bd-2dgf5 fixture: the schema the C SQLite EQP strings below were captured on.
    async fn bd_2dgf5_conn() -> Connection {
        let conn = Connection::open(":memory:").await.unwrap();
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, k INTEGER, v TEXT);")
            .await
            .unwrap();
        conn.execute("CREATE INDEX idx_t_k ON t(k);").await.unwrap();
        for i in 1..=200_i64 {
            conn.execute(&format!("INSERT INTO t VALUES ({i}, {}, 'v{i}');", i % 10))
                .await
                .unwrap();
        }
        conn
    }

    async fn eqp_details(conn: &Connection, sql: &str) -> String {
        conn.query(&format!("EXPLAIN QUERY PLAN {sql}"))
            .await
            .unwrap()
            .into_iter()
            .map(|row| match &row.values[3] {
                SqliteValue::Text(detail) => detail.to_string(),
                other => panic!("expected EQP detail text, got {other:?}"),
            })
            .collect::<Vec<_>>()
            .join(";")
    }

    /// hfdt-3b8zl: `EXPLAIN` / `EXPLAIN QUERY PLAN` must refuse DML whose
    /// `INDEXED BY` names a missing index — exactly like executing it — instead
    /// of silently describing a plan that ignores the hint. C SQLite fails both
    /// plan surfaces at prepare time with `no such index`; an unknown relation
    /// remains `no such table` rather than becoming a synthetic scan.
    #[test]
    fn eqp_and_explain_refuse_missing_indexed_by_targets() {
        asupersync::test_utils::run_test(|| async {
            let conn = bd_2dgf5_conn().await;

            for (sql, expected) in [
                (
                    "EXPLAIN QUERY PLAN SELECT id FROM t INDEXED BY idx_missing WHERE k = 1;",
                    "no such index: idx_missing",
                ),
                (
                    "EXPLAIN SELECT id FROM t INDEXED BY idx_missing WHERE k = 1;",
                    "no such index: idx_missing",
                ),
                (
                    "EXPLAIN QUERY PLAN UPDATE t INDEXED BY idx_missing SET v = 'changed' WHERE k = 1;",
                    "no such index: idx_missing",
                ),
                (
                    "EXPLAIN QUERY PLAN DELETE FROM t INDEXED BY idx_missing WHERE k = 1;",
                    "no such index: idx_missing",
                ),
                (
                    "EXPLAIN QUERY PLAN SELECT id FROM missing_table INDEXED BY idx_missing;",
                    "no such table: missing_table",
                ),
            ] {
                let error = conn
                    .query(sql)
                    .await
                    .expect_err("an invalid INDEXED BY relation must refuse on plan surfaces");
                assert!(
                    error.to_string().contains(expected),
                    "unexpected error for `{sql}`: {error}"
                );
            }

            // Positive controls: an existing forced index still plans for all
            // three statement kinds and is named for SELECT.
            let named = eqp_details(&conn, "SELECT id FROM t INDEXED BY idx_t_k WHERE k = 1").await;
            assert!(
                named.contains("idx_t_k"),
                "EQP with an existing INDEXED BY target must name the index; got {named:?}"
            );
            for sql in [
                "EXPLAIN QUERY PLAN UPDATE t INDEXED BY idx_t_k SET v = 'changed' WHERE k = 1;",
                "EXPLAIN QUERY PLAN DELETE FROM t INDEXED BY idx_t_k WHERE k = 1;",
            ] {
                conn.query(sql).await.unwrap_or_else(|error| {
                    panic!("valid forced index rejected for `{sql}`: {error}")
                });
            }

            // Dropping the index flips the same plan query to the execution refusal.
            conn.execute("DROP INDEX idx_t_k;").await.unwrap();
            let dropped = conn
                .query("EXPLAIN QUERY PLAN SELECT id FROM t INDEXED BY idx_t_k WHERE k = 1;")
                .await
                .expect_err("EQP naming a dropped index must refuse");
            assert!(
                dropped.to_string().contains("no such index: idx_t_k"),
                "unexpected error after DROP INDEX: {dropped}"
            );
        });
    }

    /// bd-2dgf5 proof (a): `EXPLAIN QUERY PLAN` parity with C SQLite 3.x.
    ///
    /// Expected strings are verbatim `sqlite3` 3.46.1 output on this exact schema
    /// (`sqlite3 t.db "EXPLAIN QUERY PLAN <sql>"`, trailing tree glyphs stripped).
    /// Note `ORDER BY 1`: C SQLite still reports the covering search, and a version
    /// of this that re-derived codegen's gates in the EQP path declined the seek for
    /// exactly that shape while the program went on seeking anyway.
    #[test]
    fn bd_2dgf5_explain_query_plan_matches_c_sqlite() {
        asupersync::test_utils::run_test(|| async {
            let conn = bd_2dgf5_conn().await;
            let expected = [
                // Covering: nothing but the rowid and the indexed column is needed.
                (
                    "SELECT COUNT(*) FROM t WHERE k = 2",
                    "SEARCH t USING COVERING INDEX idx_t_k (k=?)",
                ),
                (
                    "SELECT SUM(id) FROM t WHERE k = 2",
                    "SEARCH t USING COVERING INDEX idx_t_k (k=?)",
                ),
                (
                    "SELECT COUNT(*) FROM t WHERE k = 2 ORDER BY 1",
                    "SEARCH t USING COVERING INDEX idx_t_k (k=?)",
                ),
                // `v` is not in the index, so the row must be fetched: not covering.
                (
                    "SELECT SUM(v) FROM t WHERE k = 2",
                    "SEARCH t USING INDEX idx_t_k (k=?)",
                ),
                // `NOT INDEXED` forbids the index, so both engines scan.
                ("SELECT COUNT(*) FROM t NOT INDEXED WHERE k = 2", "SCAN t"),
            ];

            for (sql, want) in expected {
                assert_eq!(
                    eqp_details(&conn, sql).await,
                    want,
                    "EQP text diverged from C SQLite 3.46.1 for `{sql}`"
                );
            }
        });
    }

    /// bd-2dgf5 proof (b): EQP text must agree with the program it claims to describe.
    ///
    /// Proof (a) alone is not enough. EQP renders separately from codegen, so the text
    /// can be right for a program that does something else entirely — that is bd-jyyae,
    /// where EQP reported `SEARCH` for an `IN (...)` whose program was `Rewind`/`Next`
    /// with no seek opcode at all. Pin the two together:
    ///
    ///   EQP says SEARCH   <=>  the program contains a Seek
    ///   EQP says COVERING <=>  the program contains no SeekRowid
    #[test]
    fn bd_2dgf5_explain_query_plan_agrees_with_emitted_program() {
        asupersync::test_utils::run_test(|| async {
            let conn = bd_2dgf5_conn().await;
            let queries = [
                "SELECT COUNT(*) FROM t WHERE k = 2",
                "SELECT SUM(id) FROM t WHERE k = 2",
                "SELECT SUM(k) FROM t WHERE k = 2",
                "SELECT MIN(id), MAX(id) FROM t WHERE k = 2",
                "SELECT COUNT(DISTINCT k) FROM t WHERE k = 2",
                "SELECT SUM(v) FROM t WHERE k = 2",
                "SELECT group_concat(v) FROM t WHERE k = 2",
                "SELECT COUNT(*) FILTER (WHERE id > 100) FROM t WHERE k = 2",
                "SELECT COUNT(*) FROM t WHERE k = 2 ORDER BY 1",
                "SELECT COUNT(*) FROM t WHERE v = 'v7'",
                "SELECT COUNT(*) FROM t WHERE id = 2",
                "SELECT COUNT(*) FROM t",
                "SELECT COUNT(*) FROM t NOT INDEXED WHERE k = 2",
                "SELECT COUNT(*) FROM t WHERE k = 2 GROUP BY k",
                "SELECT COUNT(*) FROM t WHERE k IN (1, 2)",
            ];

            for sql in queries {
                let eqp = eqp_details(&conn, sql).await;
                let ops = explain_opcodes(&conn, sql).await;
                let has_seek = ops.iter().any(|op| op == "SeekGE");
                let has_table_lookup = ops.iter().any(|op| op == "SeekRowid");

                assert_eq!(
                    eqp.contains("SEARCH"),
                    has_seek,
                    "EQP/program divergence for `{sql}`: eqp={eqp:?} has_seek={has_seek}"
                );
                if eqp.contains("SEARCH") {
                    assert_eq!(
                        eqp.contains("COVERING"),
                        !has_table_lookup,
                        "COVERING claim disagrees with SeekRowid presence for `{sql}`: \
                     eqp={eqp:?} has_table_lookup={has_table_lookup}"
                    );
                }
            }
        });
    }

    /// bd-jyyae: `IN (SELECT ...)` compiles to a full scan probing an
    /// ephemeral membership index, but the planner directive still claimed
    /// `SEARCH t USING INDEX idx_t_k (k=?)`. EQP must report what the
    /// emitted program does, never what the planner intended.
    #[test]
    fn bd_jyyae_in_subquery_eqp_matches_emitted_program() {
        asupersync::test_utils::run_test(|| async {
            let conn = bd_2dgf5_conn().await;
            conn.execute("CREATE TABLE r (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute("INSERT INTO r VALUES (2);").await.unwrap();

            for sql in [
                "SELECT * FROM t WHERE k IN (SELECT id FROM r)",
                "SELECT v FROM t WHERE k IN (SELECT id FROM r)",
            ] {
                let eqp = eqp_details(&conn, sql).await;
                let ops = explain_opcodes(&conn, sql).await;
                let has_seek = ops.iter().any(|op| op == "SeekGE");
                assert_eq!(
                    eqp.contains("SEARCH"),
                    has_seek,
                    "bd-jyyae: EQP claims an access path the program does not \
                     perform for `{sql}`: eqp={eqp:?} has_seek={has_seek}"
                );
            }
        });
    }

    async fn explain_opcodes(conn: &Connection, sql: &str) -> Vec<String> {
        conn.query(&format!("EXPLAIN {sql}"))
            .await
            .unwrap()
            .into_iter()
            .map(|row| match &row.values[1] {
                SqliteValue::Text(opcode) => opcode.to_string(),
                other => panic!("expected EXPLAIN opcode text in column 1, got {other:?}"),
            })
            .collect()
    }

    fn sqlite_explain_opcodes(conn: &rusqlite::Connection, sql: &str) -> Vec<String> {
        let mut stmt = conn.prepare(&format!("EXPLAIN {sql}")).unwrap();
        stmt.query_map([], |row| row.get::<_, String>(1))
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap()
    }

    async fn explain_query_plan_details(conn: &Connection, sql: &str) -> Vec<String> {
        conn.query(&format!("EXPLAIN QUERY PLAN {sql}"))
            .await
            .unwrap()
            .into_iter()
            .map(|row| match &row.values[3] {
                SqliteValue::Text(detail) => detail.to_string(),
                other => {
                    panic!("expected EXPLAIN QUERY PLAN detail text in column 3, got {other:?}")
                }
            })
            .collect()
    }

    fn sqlite_explain_query_plan_details(conn: &rusqlite::Connection, sql: &str) -> Vec<String> {
        let mut stmt = conn.prepare(&format!("EXPLAIN QUERY PLAN {sql}")).unwrap();
        stmt.query_map([], |row| row.get::<_, String>(3))
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap()
    }

    fn first_opcode_position(opcodes: &[String], target: &str) -> Option<usize> {
        opcodes.iter().position(|opcode| opcode == target)
    }

    #[test]
    fn test_explain_bytecode_fast_paths_match_sqlite_for_rowid_ipk_and_covering_index() {
        asupersync::test_utils::run_test(|| async {
            let fconn = Connection::open(":memory:").await.unwrap();
            let rconn = rusqlite::Connection::open_in_memory().unwrap();

            let setup = [
                "CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, age INTEGER);",
                "CREATE INDEX idx_users_age ON users(age);",
                "INSERT INTO users VALUES (1, 'Alice', 30);",
                "INSERT INTO users VALUES (2, 'Bob', 25);",
                "INSERT INTO users VALUES (3, 'Carol', 25);",
            ];
            for sql in &setup {
                fconn.execute(sql).await.unwrap();
                rconn.execute_batch(sql).unwrap();
            }

            let rowid_query = "SELECT name FROM users WHERE rowid = 2";
            let rowid_eqp = explain_query_plan_details(&fconn, rowid_query).await;
            assert_eq!(
                rowid_eqp,
                sqlite_explain_query_plan_details(&rconn, rowid_query),
                "rowid equality EQP diverged from SQLite"
            );
            let rowid_ops = explain_opcodes(&fconn, rowid_query).await;
            let sqlite_rowid_ops = sqlite_explain_opcodes(&rconn, rowid_query);
            assert!(
                rowid_ops.iter().any(|op| op == "SeekRowid"),
                "rowid equality should emit SeekRowid, got {rowid_ops:?}"
            );
            assert!(
                sqlite_rowid_ops.iter().any(|op| op == "SeekRowid"),
                "SQLite rowid equality no longer emits SeekRowid, got {sqlite_rowid_ops:?}"
            );
            assert!(
                !rowid_ops.iter().any(|op| op == "Rewind"),
                "rowid equality should not fall back to a scan loop, got {rowid_ops:?}"
            );

            let ipk_query = "SELECT name FROM users WHERE id = 2";
            let ipk_eqp = explain_query_plan_details(&fconn, ipk_query).await;
            assert_eq!(
                ipk_eqp,
                sqlite_explain_query_plan_details(&rconn, ipk_query),
                "INTEGER PRIMARY KEY equality EQP diverged from SQLite"
            );
            let ipk_ops = explain_opcodes(&fconn, ipk_query).await;
            let sqlite_ipk_ops = sqlite_explain_opcodes(&rconn, ipk_query);
            assert!(
                ipk_ops.iter().any(|op| op == "SeekRowid"),
                "INTEGER PRIMARY KEY equality should lower to SeekRowid, got {ipk_ops:?}"
            );
            assert!(
                sqlite_ipk_ops.iter().any(|op| op == "SeekRowid"),
                "SQLite INTEGER PRIMARY KEY equality no longer emits SeekRowid, got {sqlite_ipk_ops:?}"
            );
            assert!(
                !ipk_ops.iter().any(|op| op == "Rewind"),
                "INTEGER PRIMARY KEY equality should not scan, got {ipk_ops:?}"
            );

            let indexed_query = "SELECT name FROM users WHERE age = 25";
            let indexed_eqp = explain_query_plan_details(&fconn, indexed_query).await;
            assert_eq!(
                indexed_eqp,
                sqlite_explain_query_plan_details(&rconn, indexed_query),
                "non-covering indexed equality EQP diverged from SQLite"
            );
            let indexed_ops = explain_opcodes(&fconn, indexed_query).await;
            assert!(
                indexed_ops.iter().any(|op| op == "SeekGE"),
                "non-covering indexed equality should probe the index with SeekGE, got {indexed_ops:?}"
            );
            assert!(
                indexed_ops.iter().any(|op| op == "IdxRowid"),
                "non-covering indexed equality should read rowids from the index, got {indexed_ops:?}"
            );
            assert!(
                indexed_ops.iter().any(|op| op == "SeekRowid"),
                "non-covering indexed equality should still seek the table row, got {indexed_ops:?}"
            );
            let indexed_seek_ge_pos = first_opcode_position(&indexed_ops, "SeekGE").unwrap();
            let indexed_idx_rowid_pos = first_opcode_position(&indexed_ops, "IdxRowid").unwrap();
            let indexed_seek_rowid_pos = first_opcode_position(&indexed_ops, "SeekRowid").unwrap();
            if let Some(indexed_rewind_pos) = first_opcode_position(&indexed_ops, "Rewind") {
                assert!(
                    indexed_seek_ge_pos < indexed_rewind_pos,
                    "non-covering indexed equality should choose the seek path before any fallback scan, got {indexed_ops:?}"
                );
                assert!(
                    indexed_idx_rowid_pos < indexed_rewind_pos,
                    "non-covering indexed equality should extract rowids before any fallback scan, got {indexed_ops:?}"
                );
                assert!(
                    indexed_seek_rowid_pos < indexed_rewind_pos,
                    "non-covering indexed equality should seek the table row before any fallback scan, got {indexed_ops:?}"
                );
            }

            let covering_query = "SELECT age FROM users WHERE age = 25";
            let covering_eqp = explain_query_plan_details(&fconn, covering_query).await;
            assert_eq!(
                covering_eqp,
                sqlite_explain_query_plan_details(&rconn, covering_query),
                "covering indexed equality EQP diverged from SQLite"
            );
            let covering_ops = explain_opcodes(&fconn, covering_query).await;
            assert!(
                covering_ops.iter().any(|op| op == "SeekGE"),
                "covering indexed equality should probe the index with SeekGE, got {covering_ops:?}"
            );
            assert!(
                !covering_ops.iter().any(|op| op == "SeekRowid"),
                "covering indexed equality should not perform a table rowid lookup, got {covering_ops:?}"
            );
            let covering_seek_ge_pos = first_opcode_position(&covering_ops, "SeekGE").unwrap();
            if let Some(covering_rewind_pos) = first_opcode_position(&covering_ops, "Rewind") {
                assert!(
                    covering_seek_ge_pos < covering_rewind_pos,
                    "covering indexed equality should choose the seek path before any fallback scan, got {covering_ops:?}"
                );
            }
        });
    }

    #[test]
    fn test_explain_count_in_subquery_uses_index_probe_expansion() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE products (id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute("CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("CREATE INDEX idx_prod_cat ON products(category_id);")
                .await
                .unwrap();

            let opcodes = explain_opcodes(
            &conn,
            "SELECT COUNT(*) FROM products WHERE category_id IN (SELECT id FROM categories WHERE id <= 5)",
        )
        .await;

            assert!(
                !opcodes.iter().any(|op| op == "OpenAutoindex"),
                "bounded rowid/IPK IN subquery should skip RHS materialization and use the direct probe-source path: {opcodes:?}"
            );
            assert!(
                opcodes.iter().any(|op| op == "CountIndexEqRun"),
                "bounded rowid/IPK IN subquery should still use duplicate-run counting on the outer index: {opcodes:?}"
            );
            assert!(
                opcodes.iter().any(|op| op == "OpenRead"),
                "bounded rowid/IPK IN subquery should still read the RHS table directly: {opcodes:?}"
            );
            assert!(
                opcodes.iter().any(|op| op == "Gt" || op == "Ge"),
                "COUNT(*) indexed IN fast path should keep the bounded inner rowid stop check: {opcodes:?}"
            );
            assert!(
                opcodes.iter().any(|op| op == "Rowid"),
                "COUNT(*) indexed IN fast path should keep bounded inner rowid reads: {opcodes:?}"
            );
            assert!(
                !opcodes.iter().any(|op| op == "Eq"),
                "COUNT(*) indexed IN fast path should avoid interpreter-level duplicate-run equality loops: {opcodes:?}"
            );
            assert!(
                !opcodes.iter().any(|op| op == "Count"),
                "filtered COUNT(*) should not regress to the raw Count opcode: {opcodes:?}"
            );
            assert!(
                !opcodes.iter().any(|op| op == "AggStep" || op == "AggFinal"),
                "filtered COUNT(*) should stay on the direct counter path: {opcodes:?}"
            );
        });
    }

    #[test]
    fn test_explain_count_exists_semijoin_uses_index_probe_expansion() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE products (id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL);",
            )
            .await
            .unwrap();
            conn.execute("CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute("CREATE INDEX idx_prod_cat ON products(category_id);")
                .await
                .unwrap();

            let opcodes = explain_opcodes(
            &conn,
            "SELECT COUNT(*) FROM products p WHERE EXISTS (SELECT 1 FROM categories c WHERE c.id = p.category_id AND c.id <= 5)",
        )
        .await;

            assert!(
                opcodes.iter().any(|op| op == "Rewind"),
                "COUNT(*) EXISTS semijoin fast path should rewind into the indexed outer table when only an upper source bound is available: {opcodes:?}"
            );
            assert!(
                opcodes.iter().any(|op| op == "Gt" || op == "Ge"),
                "COUNT(*) EXISTS semijoin fast path should keep the bounded inner rowid stop check: {opcodes:?}"
            );
            assert_eq!(
                opcodes
                    .iter()
                    .filter(|op| op.as_str() == "OpenRead")
                    .count(),
                2,
                "COUNT(*) EXISTS semijoin fast path should open the outer index and the bounded inner probe source: {opcodes:?}"
            );
            assert!(
                opcodes.iter().any(|op| op == "CountIndexEqRun"),
                "COUNT(*) EXISTS semijoin fast path should use the fused duplicate-run counter opcode: {opcodes:?}"
            );
            assert!(
                !opcodes.iter().any(|op| op == "Eq"),
                "COUNT(*) EXISTS semijoin fast path should avoid interpreter-level duplicate-run equality loops: {opcodes:?}"
            );
            assert!(
                opcodes.iter().any(|op| op == "Rowid"),
                "COUNT(*) EXISTS semijoin fast path should keep bounded inner rowid reads: {opcodes:?}"
            );
            assert!(
                !opcodes.iter().any(|op| op == "Count"),
                "filtered COUNT(*) should not regress to the raw Count opcode: {opcodes:?}"
            );
            assert!(
                !opcodes.iter().any(|op| op == "AggStep" || op == "AggFinal"),
                "COUNT(*) EXISTS semijoin should stay on the direct counter path: {opcodes:?}"
            );
        });
    }

    #[test]
    fn test_count_indexed_in_list_honors_nocase_collation_without_double_counting() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE items (name TEXT COLLATE NOCASE NOT NULL);")
                .await
                .unwrap();
            conn.execute("CREATE INDEX idx_items_name ON items(name);")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES ('alpha');")
                .await
                .unwrap();
            conn.execute("INSERT INTO items VALUES ('beta');")
                .await
                .unwrap();

            let rows = conn
            .query(
                "SELECT COUNT(*) FROM items WHERE name IN ('alpha', 'ALPHA', 'gamma', 'delta', 'epsilon', 'zeta', 'eta', 'theta')",
            )
            .await
            .unwrap();
            assert_eq!(rows[0].values, vec![SqliteValue::Integer(1)]);

            let opcodes = explain_opcodes(
            &conn,
            "SELECT COUNT(*) FROM items WHERE name IN ('alpha', 'ALPHA', 'gamma', 'delta', 'epsilon', 'zeta', 'eta', 'theta')",
        )
        .await;
            assert!(
                opcodes.iter().any(|op| op == "OpenAutoindex"),
                "NOCASE COUNT(*) IN query should still use the indexed probe-set fast path: {opcodes:?}"
            );
            assert!(
                opcodes.iter().any(|op| op == "SeekGE"),
                "NOCASE COUNT(*) IN query should seek into the outer index per probe key: {opcodes:?}"
            );
            assert!(
                !opcodes.iter().any(|op| op == "AggStep" || op == "AggFinal"),
                "NOCASE COUNT(*) IN query should stay on the direct counter path: {opcodes:?}"
            );
        });
    }

    #[test]
    fn test_count_composite_index_rowid_subquery_streams_first_key_runs() {
        asupersync::test_utils::run_test(|| async {
            async fn scalar_count(conn: &Connection, sql: &str) -> i64 {
                let rows = conn.query(sql).await.unwrap();
                match rows.as_slice() {
                    [row] => match row.values() {
                        [SqliteValue::Integer(value)] => *value,
                        values => panic!("expected one integer count, got {values:?}"),
                    },
                    rows => panic!("expected one count row, got {rows:?}"),
                }
            }

            // Exact CASS schema/query shape: the only messages index is the
            // UNIQUE(conversation_id, idx) autoindex, while the RHS is the complete,
            // naturally ordered conversations rowid stream.  Deliberate orphans
            // must be excluded exactly like the reference inner join.
            let conn = Connection::open(":memory:").await.unwrap();
            for sql in [
                "PRAGMA foreign_keys = OFF;",
                "CREATE TABLE conversations (
                id INTEGER PRIMARY KEY,
                title TEXT NOT NULL
            );",
                "CREATE TABLE messages (
                id INTEGER PRIMARY KEY,
                conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
                idx INTEGER NOT NULL,
                body TEXT,
                UNIQUE(conversation_id, idx)
            );",
                "INSERT INTO conversations VALUES (1, 'one'), (2, 'two'), (4, 'four');",
                "INSERT INTO messages VALUES
                (1, 1, 0, 'a'),
                (2, 1, 1, 'b'),
                (3, 2, 0, 'c'),
                (4, 3, 0, 'orphan'),
                (5, 5, 0, 'orphan too');",
            ] {
                conn.execute(sql).await.unwrap();
            }

            let cass_sql = "SELECT COUNT(*)
            FROM messages INDEXED BY sqlite_autoindex_messages_1
            WHERE conversation_id IN (SELECT rowid FROM conversations)";
            let reference_sql = "SELECT COUNT(*)
            FROM messages AS m
            INNER JOIN conversations AS c ON c.rowid = m.conversation_id";
            assert_eq!(scalar_count(&conn, cass_sql).await, 3);
            assert_eq!(
                scalar_count(&conn, cass_sql).await,
                scalar_count(&conn, reference_sql).await
            );

            let prepared = conn.prepare(cass_sql).await.unwrap();
            let ops = prepared.program.ops();
            assert!(
                ops.iter().any(|op| op.opcode == Opcode::CountIndexEqRun),
                "composite first-key semijoin should count duplicate runs: {ops:?}"
            );
            assert!(
            ops.iter().any(|op| {
                op.opcode == Opcode::OpenRead
                    && matches!(&op.p4, P4::Index(name) if name == "sqlite_autoindex_messages_1")
            }),
            "the exact forced composite autoindex should drive the outer stream: {ops:?}"
        );
            assert!(
                ops.iter().any(|op| {
                    op.opcode == Opcode::OpenRead
                        && matches!(&op.p4, P4::Table(name) if name == "conversations")
                }),
                "the RHS conversations rowid source should be scanned directly: {ops:?}"
            );
            assert!(
                !ops.iter().any(|op| {
                    op.opcode == Opcode::OpenRead
                        && matches!(&op.p4, P4::Table(name) if name == "messages")
                }),
                "the covering composite-index counter must never open the messages table: {ops:?}"
            );
            assert_eq!(
                ops.iter()
                    .filter(|op| op.opcode == Opcode::OpenRead)
                    .count(),
                2,
                "only the outer index and RHS table should be opened: {ops:?}"
            );
            assert!(
                !ops.iter().any(|op| matches!(
                    op.opcode,
                    Opcode::OpenAutoindex | Opcode::Count | Opcode::AggStep | Opcode::AggFinal
                )),
                "the streaming counter must not materialize or enter generic aggregation: {ops:?}"
            );

            // Non-unique composite index, duplicate complete keys, nullable first
            // keys, matching non-BINARY collation, and a descending trailing term.
            // Only the first key controls the merge, so all of these are legitimate
            // and NULL rows must be skipped before the integer comparison loop.
            let nonunique = Connection::open(":memory:").await.unwrap();
            for sql in [
                "CREATE TABLE allowed_buckets (id INTEGER PRIMARY KEY);",
                "CREATE TABLE events (
                id INTEGER PRIMARY KEY,
                bucket_id INTEGER COLLATE NOCASE,
                position INTEGER NOT NULL,
                payload TEXT
            );",
                "CREATE INDEX idx_events_bucket_position
                ON events(bucket_id COLLATE NOCASE, position DESC);",
                "INSERT INTO allowed_buckets VALUES (1), (3);",
                "INSERT INTO events VALUES
                (1, NULL, 9, 'null'),
                (2, 1, 5, 'a'),
                (3, 1, 5, 'duplicate full key'),
                (4, 2, 8, 'excluded'),
                (5, 3, 7, 'b'),
                (6, 3, 6, 'c');",
            ] {
                nonunique.execute(sql).await.unwrap();
            }
            let nonunique_sql = "SELECT COUNT(*)
            FROM events INDEXED BY idx_events_bucket_position
            WHERE bucket_id IN (SELECT rowid FROM allowed_buckets)";
            let nonunique_reference = "SELECT COUNT(*)
            FROM events AS e
            INNER JOIN allowed_buckets AS b ON b.rowid = e.bucket_id";
            assert_eq!(
                scalar_count(
                    &nonunique,
                    "SELECT COUNT(*)
                     FROM events INDEXED BY idx_events_bucket_position
                     WHERE bucket_id IN (
                         SELECT rowid FROM allowed_buckets WHERE rowid = 1
                     )",
                )
                .await,
                2,
                "the first composite-key run should contain both bucket 1 rows"
            );
            assert_eq!(
                scalar_count(
                    &nonunique,
                    "SELECT COUNT(*)
                     FROM events INDEXED BY idx_events_bucket_position
                     WHERE bucket_id IN (
                         SELECT rowid FROM allowed_buckets WHERE rowid = 3
                     )",
                )
                .await,
                2,
                "the second composite-key run should contain both bucket 3 rows"
            );
            assert_eq!(scalar_count(&nonunique, nonunique_sql).await, 4);
            assert_eq!(
                scalar_count(&nonunique, nonunique_sql).await,
                scalar_count(&nonunique, nonunique_reference).await
            );
            let nonunique_ops = nonunique.prepare(nonunique_sql).await.unwrap();
            let nonunique_ops = nonunique_ops.program.ops();
            assert!(
                nonunique_ops
                    .iter()
                    .any(|op| op.opcode == Opcode::CountIndexEqRun),
                "non-unique composite first-key runs should use the fused counter: {nonunique_ops:?}"
            );
            assert!(
                nonunique_ops.iter().any(|op| op.opcode == Opcode::IsNull),
                "nullable first keys need an explicit NULL skip: {nonunique_ops:?}"
            );
            assert!(
                !nonunique_ops
                    .iter()
                    .any(|op| op.opcode == Opcode::OpenAutoindex),
                "matching NOCASE semantics must remain on the direct merge: {nonunique_ops:?}"
            );

            // The list/materialized-probe path deliberately remains single-key.
            // Its `(key, min-rowid)` seek record is not a valid lower bound for a
            // `(key, trailing-key, rowid)` composite index.
            let list_sql = "SELECT COUNT(*)
            FROM messages INDEXED BY sqlite_autoindex_messages_1
            WHERE conversation_id IN (1, 2, 4, 6, 7, 8, 9, 10)";
            assert_eq!(scalar_count(&conn, list_sql).await, 3);
            let list_ops = explain_opcodes(&conn, list_sql).await;
            assert!(
                !list_ops
                    .iter()
                    .any(|op| op == "CountIndexEqRun" || op == "SeekGE"),
                "composite IN-list must not enter the single-key probe-record path: {list_ops:?}"
            );
        });
    }

    #[test]
    fn test_count_composite_index_rowid_subquery_counts_each_run_once_file_backed() {
        asupersync::test_utils::run_test(|| async {
            let temp = tempfile::NamedTempFile::new().unwrap();
            let path = temp.path().to_string_lossy().into_owned();
            let conn = Connection::open(path).await.unwrap();
            for sql in [
                "CREATE TABLE conversations (id INTEGER PRIMARY KEY, title TEXT NOT NULL);",
                "CREATE TABLE messages (
                id INTEGER PRIMARY KEY,
                conversation_id INTEGER NOT NULL,
                idx INTEGER NOT NULL,
                body TEXT,
                UNIQUE(conversation_id, idx)
            );",
                "INSERT INTO conversations VALUES (1, 'one');",
                "INSERT INTO messages VALUES
                (1, 1, 0, 'zero'),
                (2, 1, 1, 'one'),
                (3, 1, 2, 'two'),
                (4, 1, 3, 'three'),
                (5, 1, 4, 'four');",
            ] {
                conn.execute(sql).await.unwrap();
            }

            let sql = "SELECT COUNT(*)
            FROM messages INDEXED BY sqlite_autoindex_messages_1
            WHERE conversation_id IN (SELECT rowid FROM conversations)";
            let rows = conn.query(sql).await.unwrap();
            assert_eq!(
                rows[0].values,
                vec![SqliteValue::Integer(5)],
                "a five-row equality run must contribute five, not the triangular sum fifteen"
            );

            let opcodes = explain_opcodes(&conn, sql).await;
            assert_eq!(
                opcodes
                    .iter()
                    .filter(|opcode| opcode.as_str() == "CountIndexEqRun")
                    .count(),
                1,
                "the merge program should contain one fused run counter: {opcodes:?}"
            );
            let count_pos = first_opcode_position(&opcodes, "CountIndexEqRun").unwrap();
            assert_eq!(
                opcodes.get(count_pos + 1).map(String::as_str),
                Some("IfNullRow"),
                "the run counter must test its advanced outer cursor before moving the probe source: {opcodes:?}"
            );
        });
    }

    #[test]
    fn test_temp_sparse_ipk_driver_join_preserves_all_parameterized_values() {
        asupersync::test_utils::run_test(|| async {
            let temp = tempfile::NamedTempFile::new().unwrap();
            let path = temp.path().to_string_lossy().into_owned();
            let conn = Connection::open(path).await.unwrap();
            conn.execute(
                "CREATE VIRTUAL TABLE fts_messages
             USING fts5(body, content='');",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO fts_messages(rowid, body) VALUES (1, 'seed');")
                .await
                .unwrap();
            conn.execute(
                "CREATE TEMP TABLE IF NOT EXISTS cass_fts_repair_probe_ids(
                id INTEGER PRIMARY KEY
            );",
            )
            .await
            .unwrap();
            conn.execute("DELETE FROM cass_fts_repair_probe_ids;")
                .await
                .unwrap();
            conn.execute_with_params(
                "INSERT INTO cass_fts_repair_probe_ids(id) VALUES(?1),(?2);",
                &[SqliteValue::Integer(1_000_000), SqliteValue::Integer(1)],
            )
            .await
            .unwrap();
            for rowid in [500_000_i64, 1_000_000] {
                conn.execute_with_params(
                    "INSERT INTO fts_messages_docsize(id, sz)
                 SELECT ?1, sz FROM fts_messages_docsize WHERE id = ?2;",
                    &[SqliteValue::Integer(rowid), SqliteValue::Integer(1)],
                )
                .await
                .unwrap();
            }

            let requested = conn
                .query("SELECT id FROM cass_fts_repair_probe_ids ORDER BY id;")
                .await
                .unwrap()
                .into_iter()
                .map(|row| row.values[0].clone())
                .collect::<Vec<_>>();
            assert_eq!(
                requested,
                vec![SqliteValue::Integer(1), SqliteValue::Integer(1_000_000)],
                "the parameterized multi-row VALUES insert must preserve both sparse IPKs"
            );

            let mut joined = conn
                .query(
                    "SELECT f.id
                 FROM cass_fts_repair_probe_ids AS requested
                 INNER JOIN fts_messages_docsize AS f ON f.id = requested.id;",
                )
                .await
                .unwrap()
                .into_iter()
                .map(|row| match row.values[0] {
                    SqliteValue::Integer(value) => value,
                    ref other => panic!("expected integer FTS shadow rowid, got {other:?}"),
                })
                .collect::<Vec<_>>();
            joined.sort_unstable();
            assert_eq!(
                joined,
                vec![1, 1_000_000],
                "the sparse TEMP-IPK repair driver must find every requested FTS shadow row"
            );
        });
    }

    #[test]
    fn test_temp_table_ddl_never_allocates_unowned_main_database_pages() {
        asupersync::test_utils::run_test(|| async {
            let temp = tempfile::NamedTempFile::new().unwrap();
            let path = temp.path().to_string_lossy().into_owned();
            let conn = Connection::open(&path).await.unwrap();
            conn.execute(
                "CREATE TABLE durable(
                id INTEGER PRIMARY KEY,
                key TEXT NOT NULL UNIQUE,
                value TEXT
            );",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO durable VALUES (1, 'seed', 'main');")
                .await
                .unwrap();
            let before =
                conn.query("PRAGMA page_count;").await.unwrap()[0].values()[0].to_integer();

            conn.execute(
                "CREATE TEMP TABLE repair_probe(
                id INTEGER PRIMARY KEY,
                external_id TEXT UNIQUE,
                ordinal INTEGER,
                tag TEXT,
                UNIQUE(ordinal, external_id)
            );",
            )
            .await
            .unwrap();
            conn.execute(
                "INSERT INTO repair_probe VALUES
                (1000000, 'high', 2, 'alpha'),
                (1, 'low', 1, 'beta');",
            )
            .await
            .unwrap();
            let rows = conn
                .query("SELECT id FROM repair_probe ORDER BY ordinal;")
                .await
                .unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values()[0].clone())
                    .collect::<Vec<_>>(),
                vec![SqliteValue::Integer(1), SqliteValue::Integer(1_000_000)]
            );
            for pragma in ["PRAGMA quick_check;", "PRAGMA integrity_check;"] {
                let result = conn.query(pragma).await.unwrap();
                assert_eq!(
                    result[0].values(),
                    &[SqliteValue::Text("ok".into())],
                    "main-database integrity checks must ignore connection-local TEMP roots"
                );
            }
            conn.execute("CREATE INDEX temp.idx_repair_ordinal ON repair_probe(ordinal);")
                .await
                .unwrap();
            conn.execute("CREATE UNIQUE INDEX temp.idx_repair_tag ON repair_probe(tag);")
                .await
                .unwrap();
            assert!(
                conn.execute("INSERT INTO repair_probe VALUES (2, 'other', 3, 'alpha');")
                    .await
                    .is_err(),
                "TEMP UNIQUE indexes must reject duplicate keys without a pager B-tree"
            );
            conn.execute("DROP INDEX temp.idx_repair_tag;")
                .await
                .unwrap();
            conn.execute("INSERT INTO repair_probe VALUES (2, 'other', 3, 'alpha');")
                .await
                .unwrap();
            conn.execute("DROP INDEX temp.idx_repair_ordinal;")
                .await
                .unwrap();
            let after = conn.query("PRAGMA page_count;").await.unwrap()[0].values()[0].to_integer();
            assert_eq!(
                after, before,
                "TEMP table roots and implicit indexes must not consume main-database pages"
            );
            drop(conn);

            let sqlite = rusqlite::Connection::open(temp.path()).unwrap();
            let quick: String = sqlite
                .query_row("PRAGMA quick_check", [], |row| row.get(0))
                .unwrap();
            let integrity: String = sqlite
                .query_row("PRAGMA integrity_check", [], |row| row.get(0))
                .unwrap();
            assert_eq!(quick, "ok");
            assert_eq!(integrity, "ok");
            let leaked: i64 = sqlite
                .query_row(
                    "SELECT COUNT(*) FROM sqlite_master WHERE name='repair_probe'",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(
                leaked, 0,
                "TEMP catalog entries must remain connection-local"
            );
        });
    }

    #[test]
    fn test_temp_root_namespace_survives_rollback_reload_and_later_allocations() {
        asupersync::test_utils::run_test(|| async {
            let dir = tempfile::tempdir().unwrap();
            let path = dir.path().join("temp-root-reload.db");
            let conn = Connection::open(path.to_string_lossy().into_owned())
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE durable(id INTEGER PRIMARY KEY, payload TEXT); \
                 INSERT INTO durable VALUES (1, 'committed'); \
                 CREATE TEMP TABLE temp_probe(id INTEGER PRIMARY KEY, payload TEXT); \
                 INSERT INTO temp_probe VALUES (7, 'preserved');",
            )
            .await
            .unwrap();

            let temp_root = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("temp_probe"))
                .expect("TEMP schema before rollback")
                .root_page;

            conn.execute("BEGIN; INSERT INTO durable VALUES (2, 'rolled-back'); ROLLBACK;")
                .await
                .unwrap();

            let temp_rows = conn
                .query("SELECT id, payload FROM temp_probe;")
                .await
                .unwrap();
            assert_eq!(
                temp_rows[0].values(),
                &[
                    SqliteValue::Integer(7),
                    SqliteValue::Text("preserved".into()),
                ],
                "pager reload must restore the connection-local TEMP image"
            );
            assert_eq!(
                conn.query("SELECT COUNT(*) FROM durable;").await.unwrap()[0].values(),
                &[SqliteValue::Integer(1)]
            );

            // Exercise both ordinary MemDatabase materialization callers after
            // the reload. A restored high TEMP root must not leave their
            // ascending allocator near i32::MAX.
            assert_eq!(
                conn.query("WITH c(x) AS (VALUES(1), (2)) SELECT SUM(x) FROM c;")
                    .await
                    .unwrap()[0]
                    .values(),
                &[SqliteValue::Integer(3)]
            );
            assert_eq!(
                conn.query("SELECT COUNT(*) FROM sqlite_schema WHERE name = 'durable';")
                    .await
                    .unwrap()[0]
                    .values(),
                &[SqliteValue::Integer(1)]
            );

            conn.execute(
                "CREATE TABLE after_reload(id INTEGER PRIMARY KEY); \
                 INSERT INTO after_reload VALUES (11);",
            )
            .await
            .unwrap();
            let after_root = conn
                .schema
                .borrow()
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case("after_reload"))
                .expect("main table created after reload")
                .root_page;
            assert_ne!(temp_root, after_root);
            assert_eq!(
                conn.query("SELECT id FROM after_reload;").await.unwrap()[0].values(),
                &[SqliteValue::Integer(11)]
            );
        });
    }

    #[test]
    fn test_count_composite_index_rowid_subquery_rejects_unsafe_index_shapes() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            for sql in [
                "CREATE TABLE probe_ids (id INTEGER PRIMARY KEY);",
                "INSERT INTO probe_ids VALUES (1), (3);",
                "CREATE TABLE desc_items (id INTEGER PRIMARY KEY, k INTEGER, seq INTEGER);",
                "CREATE INDEX idx_desc_items ON desc_items(k DESC, seq);",
                "CREATE TABLE partial_items (id INTEGER PRIMARY KEY, k INTEGER, seq INTEGER);",
                "CREATE INDEX idx_partial_items ON partial_items(k, seq) WHERE seq >= 0;",
                "CREATE TABLE expression_items (id INTEGER PRIMARY KEY, k INTEGER, seq INTEGER);",
                "CREATE INDEX idx_expression_items ON expression_items((k + 0), seq);",
                "CREATE TABLE collated_items (id INTEGER PRIMARY KEY, k INTEGER, seq INTEGER);",
                "CREATE INDEX idx_collated_items ON collated_items(k, seq);",
            ] {
                conn.execute(sql).await.unwrap();
            }

            let rejected = [
                "SELECT COUNT(*) FROM desc_items
                WHERE k IN (SELECT rowid FROM probe_ids)",
                "SELECT COUNT(*) FROM partial_items
                WHERE k IN (SELECT rowid FROM probe_ids)",
                "SELECT COUNT(*) FROM expression_items
                WHERE (k + 0) IN (SELECT rowid FROM probe_ids)",
                "SELECT COUNT(*) FROM collated_items
                WHERE k COLLATE NOCASE IN (SELECT rowid FROM probe_ids)",
                "SELECT COUNT(*) FROM collated_items NOT INDEXED
                WHERE k IN (SELECT rowid FROM probe_ids)",
            ];
            for sql in rejected {
                let opcodes = explain_opcodes(&conn, sql).await;
                assert!(
                    !opcodes.iter().any(|op| op == "CountIndexEqRun"),
                    "unsafe DESC/expression/partial/collation/NOT INDEXED shape must decline the composite-run counter for `{sql}`: {opcodes:?}"
                );
            }
        });
    }

    #[test]
    fn test_explain_parameterized_ipk_range_uses_bounded_seek_scan() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
            "CREATE TABLE bench (id INTEGER PRIMARY KEY, name TEXT NOT NULL, value REAL NOT NULL);",
        )
        .await
        .unwrap();

            let opcodes =
                explain_opcodes(&conn, "SELECT * FROM bench WHERE id >= ?1 AND id < ?2").await;

            assert!(
                opcodes.iter().any(|op| op == "SeekGE"),
                "parameterized IPK range should seek into the table instead of scanning: {opcodes:?}"
            );
            assert!(
                !opcodes.iter().any(|op| op == "Rewind"),
                "parameterized IPK range should not retain the planner full-scan directive: {opcodes:?}"
            );
        });
    }

    #[test]
    fn test_explain_query_plan_reports_planner_selected_detail() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, age INTEGER);",
            )
            .await
            .unwrap();
            conn.execute("CREATE INDEX idx_users_age ON users(age);")
                .await
                .unwrap();
            conn.execute("INSERT INTO users VALUES (1, 'Alice', 30);")
                .await
                .unwrap();
            conn.execute("INSERT INTO users VALUES (2, 'Bob', 25);")
                .await
                .unwrap();

            let rowid_rows = conn
                .query("EXPLAIN QUERY PLAN SELECT name FROM users WHERE rowid = 1")
                .await
                .unwrap();
            assert_eq!(
                rowid_rows[0].values[3],
                SqliteValue::Text("SEARCH users USING INTEGER PRIMARY KEY (rowid=?)".into()),
            );

            let index_rows = conn
                .query("EXPLAIN QUERY PLAN SELECT name FROM users WHERE age = 25")
                .await
                .unwrap();
            assert_eq!(
                index_rows[0].values[3],
                SqliteValue::Text("SEARCH users USING INDEX idx_users_age (age=?)".into()),
            );

            let covering_rows = conn
                .query("EXPLAIN QUERY PLAN SELECT age FROM users WHERE age = 25")
                .await
                .unwrap();
            assert_eq!(
                covering_rows[0].values[3],
                SqliteValue::Text("SEARCH users USING COVERING INDEX idx_users_age (age=?)".into()),
            );
        });
    }

