    #[test]
    fn test_prepared_insert_with_explicit_rowid_uses_direct_simple_insert_fast_path() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY, name TEXT, score INTEGER);")
                .await
                .unwrap();

            let stmt = conn
                .prepare("INSERT INTO t VALUES (?1, ('name_' || ?1), (?1 * 7));")
                .await
                .unwrap();
            let direct = stmt
                .precompiled_dml()
                .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
                .expect("benchmark-style insert should still precompute direct metadata");
            assert!(
                !Connection::direct_simple_insert_prefers_reusable_table_program(direct),
                "explicit rowid/IPK inserts should stay on the direct simple-insert path"
            );

            reset_statement_reuse_measurement(&conn);
            conn.execute("BEGIN;").await.unwrap();
            conn.execute_prepared_with_params(&stmt, &[SqliteValue::Integer(1)])
                .await
                .expect("prepared insert should execute");
            conn.execute_prepared_with_params(&stmt, &[SqliteValue::Integer(2)])
                .await
                .expect("prepared insert should execute");
            conn.execute("COMMIT;").await.unwrap();

            assert!(
                conn.cached_vdbe_engine.borrow().is_none(),
                "explicit rowid/IPK prepared inserts should not need the reusable VDBE engine cache"
            );

            let profile = hot_path_profile_snapshot();
            assert_eq!(
                profile.prepared_table_engine_fresh_allocs, 0,
                "explicit rowid/IPK direct inserts should not allocate a reusable table engine: {profile:?}"
            );
            assert_eq!(
                profile.prepared_table_engine_reuses, 0,
                "explicit rowid/IPK direct inserts should not reuse a table engine because they stay off the VDBE table-program lane: {profile:?}"
            );
            assert_eq!(
                profile.prepared_table_dml_affected_only_runs, 0,
                "explicit rowid/IPK direct inserts should avoid the affected-only VDBE execution handoff entirely: {profile:?}"
            );
            assert_eq!(
                profile.prepared_insert_fast_lane_hits, 2,
                "explicit rowid/IPK direct inserts should still stay on the prepared-insert fast lane: {profile:?}"
            );

            let row = conn
                .query_row("SELECT id, name, score FROM t WHERE id = 1;")
                .await
                .expect("query should succeed");
            assert_eq!(row.values()[0], SqliteValue::Integer(1));
            assert_eq!(row.values()[1], SqliteValue::Text("name_1".into()));
            assert_eq!(row.values()[2], SqliteValue::Integer(7));

            let second = conn
                .query_row("SELECT id, name, score FROM t WHERE id = 2;")
                .await
                .expect("query should succeed");
            assert_eq!(second.values()[0], SqliteValue::Integer(2));
            assert_eq!(second.values()[1], SqliteValue::Text("name_2".into()));
            assert_eq!(second.values()[2], SqliteValue::Integer(14));
        });
    }

    #[test]
    fn test_prepared_direct_insert_page_run_flushes_before_read() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE t(id INTEGER PRIMARY KEY, name TEXT, note TEXT, score INTEGER);",
            )
            .await
            .unwrap();
            let stmt = conn
                .prepare(
                    "INSERT INTO t VALUES (?1, ('name_' || ?1), \
                 ?2, \
                 (?1 * 7));",
                )
                .await
                .unwrap();
            let note = SqliteValue::Text(
                "bulk note payload "
                    .repeat(PREPARED_DIRECT_INSERT_PAGE_RUN_MIN_RECORD_BYTES / 16 + 8)
                    .into(),
            );

            conn.execute("BEGIN;").await.unwrap();
            for rowid in 1_i64..=64_i64 {
                conn.execute_prepared_with_params(
                    &stmt,
                    &[SqliteValue::Integer(rowid), note.clone()],
                )
                .await
                .expect("prepared insert should execute");
            }
            assert!(
                conn.pending_direct_insert_page_run.borrow().is_some(),
                "monotonic explicit inserts should be buffered until a visibility boundary"
            );

            let row = conn
                .query_row("SELECT count(*), sum(score) FROM t;")
                .await
                .expect("read should flush the pending page run");
            assert_eq!(row.values()[0], SqliteValue::Integer(64));
            assert_eq!(row.values()[1], SqliteValue::Integer(7 * (64 * 65 / 2)));
            assert!(
                conn.pending_direct_insert_page_run.borrow().is_none(),
                "read boundary should leave no pending page run"
            );
            conn.execute("COMMIT;").await.unwrap();

            let row = conn
                .query_row("SELECT name, score FROM t WHERE id = 64;")
                .await
                .expect("committed row should remain visible");
            assert_eq!(row.values()[0], SqliteValue::Text("name_64".into()));
            assert_eq!(row.values()[1], SqliteValue::Integer(448));
        });
    }

