    fn test_prepared_direct_insert_repeated_constant_page_run_flushes_before_read() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            let stmt = conn.prepare("INSERT INTO t VALUES (?1);").await.unwrap();

            conn.execute("BEGIN;").await.unwrap();
            for rowid in 0_i64..64_i64 {
                conn.execute_prepared_with_params(&stmt, &[SqliteValue::Integer(rowid)])
                    .await
                    .expect("prepared insert should execute");
            }
            {
                let pending = conn.pending_direct_insert_page_run.borrow();
                let run = pending
                    .as_ref()
                    .expect("monotonic constant-record inserts should be buffered");
                match &run.records {
                    PendingDirectInsertPageRunRecords::Repeated { rowids, record } => {
                        assert_eq!(rowids.len(), 64);
                        assert!(record.len() < PREPARED_DIRECT_INSERT_PAGE_RUN_MIN_RECORD_BYTES);
                    }
                    other => panic!("expected repeated-record page run, got {other:?}"),
                }
            }

            let row = conn
                .query_row("SELECT count(*), sum(id) FROM t;")
                .await
                .expect("read should flush the pending repeated-record page run");
            assert_eq!(row.values()[0], SqliteValue::Integer(64));
            assert_eq!(row.values()[1], SqliteValue::Integer(64 * 63 / 2));
            assert!(conn.pending_direct_insert_page_run.borrow().is_none());
            conn.execute("COMMIT;").await.unwrap();
        });
    }

