    #[test]
    fn test_failed_pending_direct_delete_monotone_leaf_run_flush_preserves_all_buffers() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE bench (id INTEGER PRIMARY KEY, name TEXT NOT NULL);")
                .await
                .unwrap();
            let insert = conn
                .prepare("INSERT INTO bench VALUES (?1, ?2);")
                .await
                .unwrap();
            conn.execute("BEGIN;").await.unwrap();
            for rowid in 1_i64..=1000_i64 {
                conn.execute_prepared_with_params(
                    &insert,
                    &[
                        SqliteValue::Integer(rowid),
                        SqliteValue::Text(format!("user_{rowid:04}_{}", "x".repeat(256)).into()),
                    ],
                )
                .await
                .expect("setup insert should execute");
            }
            conn.execute("COMMIT;").await.unwrap();

            let delete = conn
                .prepare("DELETE FROM bench WHERE id = ?1;")
                .await
                .unwrap();
            conn.execute("BEGIN;").await.unwrap();
            for idx in 0_i64..50_i64 {
                let rowid = idx * 20 + 1;
                assert_eq!(
                    conn.execute_prepared_with_params(&delete, &[SqliteValue::Integer(rowid)])
                        .await
                        .expect("prepared delete should execute"),
                    1
                );
            }
            let staged_count = conn.pending_direct_delete_leaf_runs.borrow().len();
            assert!(staged_count > 0);
            assert!(conn.pending_direct_delete_leaf_run.borrow().is_some());

            let cancelled = Cx::new();
            cancelled.transition_to_running();
            cancelled.cancel_with_reason(CancelReason::UserInterrupt);
            assert!(
                conn.flush_pending_direct_delete_leaf_run(&cancelled)
                    .await
                    .is_err(),
                "cancelled staged flush should report an error"
            );
            assert_eq!(
                conn.pending_direct_delete_leaf_runs.borrow().len(),
                staged_count
            );
            assert!(
                conn.pending_direct_delete_leaf_run.borrow().is_some(),
                "failed staged flush must preserve the active leaf run"
            );

            conn.execute("COMMIT;").await.unwrap();
            let row = conn
                .query_row("SELECT count(*) FROM bench;")
                .await
                .expect("retrying preserved staged delete runs at commit should succeed");
            assert_eq!(row.values()[0], SqliteValue::Integer(950));
        });
    }

