    #[test]
    fn test_ad_hoc_execute_reuses_prepared_simple_insert_fast_path() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY, name TEXT, score INTEGER);")
                .await
                .unwrap();

            reset_statement_reuse_measurement(&conn);
            let sql = "INSERT INTO t VALUES (NULL, 'fixed_name', 7);";
            conn.execute(sql).await.unwrap();
            conn.execute(sql).await.unwrap();

            let profile = hot_path_profile_snapshot();
            assert_eq!(
                profile.parser.prepared_cache_misses, 1,
                "first ad-hoc execute() should seed the prepared cache: {profile:?}"
            );
            assert_eq!(
                profile.parser.prepared_cache_hits, 1,
                "second identical ad-hoc execute() should reuse the prepared cache: {profile:?}"
            );
            assert_eq!(
                profile.prepared_insert_fast_lane_hits, 2,
                "ad-hoc execute() should route simple INSERTs through the prepared direct fast lane: {profile:?}"
            );

            let rows = conn
                .query("SELECT id, name, score FROM t ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 2);
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
            assert_eq!(rows[0].values()[1], SqliteValue::Text("fixed_name".into()));
            assert_eq!(rows[0].values()[2], SqliteValue::Integer(7));
            assert_eq!(rows[1].values()[0], SqliteValue::Integer(2));
            assert_eq!(rows[1].values()[1], SqliteValue::Text("fixed_name".into()));
            assert_eq!(rows[1].values()[2], SqliteValue::Integer(7));
        });
    }

    #[test]
    fn test_prepared_direct_simple_insert_large_profile_breakdown() {
        asupersync::test_utils::run_test(|| async {
            // The per-column preserialize attribution asserted below is
            // deep-gated (bd-he3ua); arm the test-only deep override.
            let _profile_guard = StatementReuseHotPathProfileGuard::new_with_deep_dml_profile();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE t(\
                id INTEGER PRIMARY KEY, \
                first_name TEXT NOT NULL, \
                last_name TEXT NOT NULL, \
                email TEXT NOT NULL, \
                department TEXT NOT NULL, \
                title TEXT NOT NULL, \
                bio TEXT NOT NULL, \
                address TEXT NOT NULL, \
                notes TEXT NOT NULL, \
                score INTEGER NOT NULL\
            );",
            )
            .await
            .unwrap();

            let stmt = conn
            .prepare(
                "INSERT INTO t VALUES (\
                    ?1, \
                    ('FirstName_' || ?1), \
                    ('LastName_' || ?1), \
                    ('employee' || ?1 || '@bigcorp.example.com'), \
                    ('Engineering_Dept_' || (?1 % 20)), \
                    ('Senior Software Engineer Level ' || (?1 % 5)), \
                    ('This is the biography for employee number ' || ?1 || '. They have been working at the company for many years and have contributed to numerous projects across multiple teams. Their expertise spans distributed systems, database internals, and performance optimization. They are known for their thorough code reviews and mentorship of junior engineers.'), \
                    (?1 || ' Technology Park, Building ' || (?1 % 50) || ', Suite ' || (?1 % 200) || ', Innovation City, CA 94000'), \
                    ('Internal notes: Employee ' || ?1 || ' - Performance rating: Exceeds Expectations. Last review date: 2026-01-15. Next review: 2026-07-15. Skills: Rust, C++, SQL, distributed systems, leadership.'), \
                    (?1 * 13)\
                );",
            ).await
            .unwrap();
            let direct = stmt
                .precompiled_dml()
                .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
                .expect("large benchmark-style insert should still precompute direct metadata");
            assert!(
                !Connection::direct_simple_insert_prefers_reusable_table_program(direct),
                "large benchmark-style insert should stay on the direct simple-insert path"
            );

            const ROWS: i64 = 1000;
            reset_hot_path_profile();
            conn.execute("BEGIN;").await.unwrap();
            for id in 0..ROWS {
                let affected = conn
                    .execute_prepared_with_params(&stmt, &[SqliteValue::Integer(id)])
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }
            conn.execute("COMMIT;").await.unwrap();

            let profile = hot_path_profile_snapshot();
            assert_eq!(
                profile.prepared_insert_fast_lane_hits, ROWS as u64,
                "large benchmark-style insert should stay on the prepared fast lane: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_executions, ROWS as u64,
                "large benchmark-style insert should execute entirely through the direct insert path: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_serialize_time_ns, 0,
                "large explicit-txn :memory: inserts should use the fused direct-record serializer instead of rebuilding row values then serializing: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_preserialize_time_ns > 0,
                "large explicit-txn inserts should attribute direct-record preserialization time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_preserialize_cell_time_ns > 0,
                "large explicit-txn inserts should attribute direct-record cell planning time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_preserialize_eval_time_ns > 0,
                "large explicit-txn inserts should attribute direct-record expression evaluation time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_preserialize_affinity_time_ns > 0,
                "large explicit-txn inserts should attribute direct-record affinity coercion time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_preserialize_layout_time_ns > 0,
                "large explicit-txn inserts should attribute direct-record cell layout time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_preserialize_encode_time_ns > 0,
                "large explicit-txn inserts should attribute direct-record byte encoding time: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_row_value_build_time_ns, 0,
                "large explicit-txn inserts should not rebuild row values after direct-record preserialization: {profile:?}"
            );

            let row = conn
            .query_row(
                "SELECT first_name, department, title, address, notes, score FROM t WHERE id = 17;",
            )
            .await
            .unwrap();
            assert_eq!(row.values()[0], SqliteValue::Text("FirstName_17".into()));
            assert_eq!(
                row.values()[1],
                SqliteValue::Text("Engineering_Dept_17".into())
            );
            assert_eq!(
                row.values()[2],
                SqliteValue::Text("Senior Software Engineer Level 2".into())
            );
            assert_eq!(
                row.values()[3],
                SqliteValue::Text(
                    "17 Technology Park, Building 17, Suite 17, Innovation City, CA 94000".into()
                )
            );
            assert_eq!(
            row.values()[4],
            SqliteValue::Text("Internal notes: Employee 17 - Performance rating: Exceeds Expectations. Last review date: 2026-01-15. Next review: 2026-07-15. Skills: Rust, C++, SQL, distributed systems, leadership.".into())
        );
            assert_eq!(row.values()[5], SqliteValue::Integer(221));
        });
    }

    #[test]
    fn test_insert_values_ingest_keeps_memdb_mirror_incrementally_exact() {
        asupersync::test_utils::run_test(|| async {
            // bd-vjmae keeper 1: multi-statement INSERT...VALUES ingest on a
            // file-backed database must maintain the MemDatabase mirror
            // INCREMENTALLY — no whole-database rematerialization per
            // statement — and the incremental mirror must be byte-equal to a
            // full rematerialization (fresh-connection oracle).
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("vjmae_ingest.db");
            let db_str = db_path.to_string_lossy().into_owned();
            let conn = Connection::open(&db_str).await.unwrap();
            conn.execute("CREATE TABLE ingest (id INTEGER PRIMARY KEY, a INTEGER, b TEXT);")
                .await
                .unwrap();
            // Hydrate the mirror to an exact state before measuring.
            let warm = conn.query("SELECT COUNT(*) FROM ingest;").await.unwrap();
            assert_eq!(warm.len(), 1);

            reset_hot_path_profile();
            for batch in 0..8i64 {
                let base = batch * 4;
                conn.execute(&format!(
                    "INSERT INTO ingest VALUES \
                     ({}, {}, 'r{}'), ({}, {}, 'r{}'), ({}, {}, 'r{}'), ({}, {}, 'r{}');",
                    base + 1,
                    base,
                    base + 1,
                    base + 2,
                    base,
                    base + 2,
                    base + 3,
                    base,
                    base + 3,
                    base + 4,
                    base,
                    base + 4,
                ))
                .await
                .unwrap();
                // The HFDT ingest interleaves read-backs; each one is a read
                // boundary that forces a whole-db rematerialization whenever
                // the preceding INSERT abandoned the mirror.
                let rows = conn.query("SELECT COUNT(*) FROM ingest;").await.unwrap();
                assert_eq!(
                    rows[0].get(0),
                    Some(&SqliteValue::Integer((batch + 1) * 4)),
                    "read-back after batch {batch}"
                );
            }
            let profile = hot_path_profile_snapshot();
            assert_eq!(
                profile.memdb_refresh_count, 0,
                "8 INSERT...VALUES statements with interleaved read-backs \
                 must not rematerialize the memdb mirror per statement: {profile:?}"
            );

            // Byte-equality mirror oracle: a fresh connection's fully
            // rematerialized mirror must match the incremental one row for
            // row and value for value.
            let incremental: Vec<Vec<SqliteValue>> = conn
                .query("SELECT id, a, b FROM ingest ORDER BY id;")
                .await
                .unwrap()
                .iter()
                .map(|row| row.values().to_vec())
                .collect();
            let oracle_conn = Connection::open(&db_str).await.unwrap();
            let rematerialized: Vec<Vec<SqliteValue>> = oracle_conn
                .query("SELECT id, a, b FROM ingest ORDER BY id;")
                .await
                .unwrap()
                .iter()
                .map(|row| row.values().to_vec())
                .collect();
            assert_eq!(incremental.len(), 32);
            assert_eq!(
                incremental, rematerialized,
                "incremental mirror must be value-equal to full rematerialization"
            );
        });
    }

    #[test]
    fn test_non_values_statements_still_take_full_memdb_path() {
        asupersync::test_utils::run_test(|| async {
            // bd-vjmae countermetric: statements that are NOT plain
            // INSERT...VALUES (here INSERT...SELECT) must keep the
            // full-rematerialization discipline — the mirror gets marked for
            // reload rather than incrementally patched.
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let dir = tempfile::tempdir().unwrap();
            let db_path = dir.path().join("vjmae_countermetric.db");
            let db_str = db_path.to_string_lossy().into_owned();
            let conn = Connection::open(&db_str).await.unwrap();
            conn.execute("CREATE TABLE src (id INTEGER PRIMARY KEY, v TEXT);")
                .await
                .unwrap();
            conn.execute("CREATE TABLE dst (id INTEGER PRIMARY KEY, v TEXT);")
                .await
                .unwrap();
            conn.execute("INSERT INTO src VALUES (1, 'x'), (2, 'y');")
                .await
                .unwrap();
            let _ = conn.query("SELECT COUNT(*) FROM dst;").await.unwrap();

            // INSERT...SELECT is exactly tracked at HEAD (row-stream replay
            // into per-row direct inserts) — mechanism-agnostic correctness
            // is the invariant: mirror equals a fresh-connection oracle.
            conn.execute("INSERT INTO dst SELECT id, v FROM src;")
                .await
                .unwrap();
            let rows = conn.query("SELECT COUNT(*) FROM dst;").await.unwrap();
            assert_eq!(rows[0].get(0), Some(&SqliteValue::Integer(2)));

            // Mechanism countermetric: a statement shape the engine provably
            // cannot exactly track — UPDATE ... RETURNING routes through the
            // fallback lane — must dirty the mirror and rematerialize at the
            // next read boundary rather than serve a stale image.
            reset_hot_path_profile();
            conn.execute("UPDATE dst SET v = 'z' WHERE id = 1 RETURNING v;")
                .await
                .unwrap();
            let rows = conn.query("SELECT v FROM dst WHERE id = 1;").await.unwrap();
            assert_eq!(rows[0].get(0), Some(&SqliteValue::Text("z".into())));
            let profile = hot_path_profile_snapshot();
            assert!(
                profile.prepared_update_delete_fallback_returning >= 1
                    || profile.memdb_refresh_count >= 1,
                "the untrackable RETURNING shape must take the full path: {profile:?}"
            );

            // Byte-equality oracle after the mixed workload.
            let incremental: Vec<Vec<SqliteValue>> = conn
                .query("SELECT id, v FROM dst ORDER BY id;")
                .await
                .unwrap()
                .iter()
                .map(|row| row.values().to_vec())
                .collect();
            let oracle_conn = Connection::open(&db_str).await.unwrap();
            let rematerialized: Vec<Vec<SqliteValue>> = oracle_conn
                .query("SELECT id, v FROM dst ORDER BY id;")
                .await
                .unwrap()
                .iter()
                .map(|row| row.values().to_vec())
                .collect();
            assert_eq!(
                incremental, rematerialized,
                "mirror must match full rematerialization after the mixed workload"
            );
        });
    }

    #[test]
    fn test_prepared_direct_insert_preserialize_fallback_does_not_publish_child_profile() {
        asupersync::test_utils::run_test(|| async {
            // The preserialize-family attribution asserted below is
            // deep-gated (bd-he3ua); arm the test-only deep override.
            let _profile_guard = StatementReuseHotPathProfileGuard::new_with_deep_dml_profile();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("CREATE TABLE t(id INTEGER PRIMARY KEY, score INTEGER);")
                .await
                .unwrap();

            let stmt = conn
                .prepare("INSERT INTO t VALUES (?1, ('not_numeric_' || ?1));")
                .await
                .unwrap();
            let direct = stmt
                .precompiled_dml()
                .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
                .expect("concat INSERT should still precompute direct metadata");
            assert!(
                !Connection::direct_simple_insert_prefers_reusable_table_program(direct),
                "concat INSERT should stay on the direct simple-insert path"
            );

            reset_hot_path_profile();
            conn.execute("BEGIN;").await.unwrap();
            for id in 1..=16 {
                assert_eq!(
                    conn.execute_prepared_with_params(&stmt, &[SqliteValue::Integer(id)])
                        .await
                        .unwrap(),
                    1
                );
            }
            conn.execute("COMMIT;").await.unwrap();

            let profile = hot_path_profile_snapshot();
            assert!(
                profile.prepared_direct_insert_preserialize_time_ns > 0,
                "the memory explicit-txn path should attempt direct-record preserialization: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_preserialize_cell_time_ns, 0,
                "fallback attempts must not publish successful direct-record cell planning time: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_preserialize_eval_time_ns, 0,
                "fallback attempts must not publish successful direct-record expression evaluation time: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_preserialize_affinity_time_ns, 0,
                "fallback attempts must not publish successful direct-record affinity coercion time: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_preserialize_layout_time_ns, 0,
                "fallback attempts must not publish successful direct-record cell layout time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_row_value_build_time_ns > 0,
                "fallback should continue through the row-value builder: {profile:?}"
            );

            let rows = conn
                .query("SELECT id, score FROM t ORDER BY id;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 16);
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(1));
            assert_eq!(
                rows[0].values()[1],
                SqliteValue::Text("not_numeric_1".into())
            );
            assert_eq!(rows[15].values()[0], SqliteValue::Integer(16));
            assert_eq!(
                rows[15].values()[1],
                SqliteValue::Text("not_numeric_16".into())
            );
        });
    }

    #[test]
    fn test_prepared_direct_simple_insert_autocommit_profile_breakdown() {
        asupersync::test_utils::run_test(|| async {
            let _profile_guard = StatementReuseHotPathProfileGuard::new();
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute(
                "CREATE TABLE t(\
                id INTEGER PRIMARY KEY, \
                first_name TEXT NOT NULL, \
                last_name TEXT NOT NULL, \
                email TEXT NOT NULL, \
                department TEXT NOT NULL, \
                title TEXT NOT NULL, \
                bio TEXT NOT NULL, \
                address TEXT NOT NULL, \
                notes TEXT NOT NULL, \
                score INTEGER NOT NULL\
            );",
            )
            .await
            .unwrap();

            let stmt = conn
            .prepare(
                "INSERT INTO t VALUES (\
                    ?1, \
                    ('FirstName_' || ?1), \
                    ('LastName_' || ?1), \
                    ('employee' || ?1 || '@bigcorp.example.com'), \
                    ('Engineering_Dept_' || (?1 % 20)), \
                    ('Senior Software Engineer Level ' || (?1 % 5)), \
                    ('This is the biography for employee number ' || ?1 || '. They have been working at the company for many years and have contributed to numerous projects across multiple teams. Their expertise spans distributed systems, database internals, and performance optimization. They are known for their thorough code reviews and mentorship of junior engineers.'), \
                    (?1 || ' Technology Park, Building ' || (?1 % 50) || ', Suite ' || (?1 % 200) || ', Innovation City, CA 94000'), \
                    ('Internal notes: Employee ' || ?1 || ' - Performance rating: Exceeds Expectations. Last review date: 2026-01-15. Next review: 2026-07-15. Skills: Rust, C++, SQL, distributed systems, leadership.'), \
                    (?1 * 13)\
                );",
            ).await
            .unwrap();
            let direct = stmt
                .precompiled_dml()
                .and_then(|dispatch| dispatch.direct_simple_insert.as_ref())
                .expect("large benchmark-style insert should still precompute direct metadata");
            assert!(
                !Connection::direct_simple_insert_prefers_reusable_table_program(direct),
                "large benchmark-style insert should stay on the direct simple-insert path"
            );

            const ROWS: i64 = 512;
            reset_hot_path_profile();
            for id in 0..ROWS {
                let affected = conn
                    .execute_prepared_with_params(&stmt, &[SqliteValue::Integer(id)])
                    .await
                    .unwrap();
                assert_eq!(affected, 1);
            }

            let profile = hot_path_profile_snapshot();
            assert_eq!(
                profile.prepared_insert_fast_lane_hits, ROWS as u64,
                "autocommit large benchmark-style insert should stay on the prepared fast lane: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_executions, ROWS as u64,
                "autocommit large benchmark-style insert should execute entirely through the direct insert path: {profile:?}"
            );
            assert_eq!(
                profile.prepared_direct_insert_autocommit_executions, ROWS as u64,
                "autocommit profile should count each prepared direct insert execution once: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_schema_validation_time_ns > 0,
                "autocommit profile should expose schema-validation time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_autocommit_begin_time_ns > 0,
                "autocommit profile should expose begin time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_change_tracking_time_ns > 0,
                "autocommit profile should expose change-tracking bookkeeping time: {profile:?}"
            );
            assert!(
                profile.prepared_direct_insert_autocommit_resolve_time_ns > 0,
                "autocommit profile should expose resolve/commit time: {profile:?}"
            );

            let count_rows = conn.query("SELECT COUNT(*) FROM t;").await.unwrap();
            assert_eq!(count_rows[0].values()[0], SqliteValue::Integer(ROWS));
        });
    }

    /// Conformance oracle: multiple ORDER BY expressions.
    #[test]
    fn test_conformance_multi_order_by_exprs() {
        asupersync::test_utils::run_test(|| async {
            let fconn = Connection::open(":memory:").await.unwrap();
            let rconn = rusqlite::Connection::open_in_memory().unwrap();

            let setup = [
                "CREATE TABLE scores(id INTEGER PRIMARY KEY, name TEXT, subject TEXT, score INTEGER)",
                "INSERT INTO scores VALUES(1,'alice','math',90),(2,'bob','math',85),(3,'alice','science',88),(4,'bob','science',92),(5,'charlie','math',90),(6,'charlie','science',85)",
            ];
            for s in &setup {
                fconn.execute(s).await.unwrap();
                rconn.execute_batch(s).unwrap();
            }

            let queries = [
                "SELECT name, subject, score FROM scores ORDER BY score DESC, name ASC",
                "SELECT name, subject, score FROM scores ORDER BY subject, score DESC, name",
                "SELECT name, SUM(score) AS total FROM scores GROUP BY name ORDER BY total DESC",
                "SELECT name, score FROM scores ORDER BY score DESC LIMIT 3",
                "SELECT name, score FROM scores ORDER BY score DESC LIMIT 3 OFFSET 2",
                // ORDER BY expression
                "SELECT name, score FROM scores ORDER BY -score, name",
                "SELECT name, score FROM scores ORDER BY score % 10, name",
            ];

            let mismatches = oracle_compare(&fconn, &rconn, &queries).await;
            if !mismatches.is_empty() {
                for m in &mismatches {
                    eprintln!("{m}\n");
                }
                panic!("{} multi ORDER BY mismatches", mismatches.len());
            }
        });
    }

