    /// Regression: updating a pre-ALTER row on an INTEGER PRIMARY KEY table
    /// must preserve existing NOT NULL columns when a nullable column is added
    /// later and then written in the same UPDATE.
    #[test]
    fn test_update_after_alter_add_column_preserves_existing_not_null_fields() {
        asupersync::test_utils::run_test(|| async {
            let fconn = Connection::open(":memory:").await.unwrap();
            let rconn = rusqlite::Connection::open_in_memory().unwrap();

            let setup = [
                "CREATE TABLE conversations (
                id INTEGER PRIMARY KEY,
                agent_id INTEGER NOT NULL,
                workspace_id INTEGER,
                source_id TEXT NOT NULL,
                source_path TEXT NOT NULL,
                started_at INTEGER
            )",
                "INSERT INTO conversations
             (id, agent_id, workspace_id, source_id, source_path, started_at)
             VALUES (1, 1, 1, 'local', '/sessions/a.jsonl', 1700000000000)",
                "INSERT INTO conversations
             (id, agent_id, workspace_id, source_id, source_path, started_at)
             VALUES (2, 2, 2, 'remote-ci', '/sessions/b.jsonl', 1700000001000)",
                "ALTER TABLE conversations ADD COLUMN origin_host TEXT",
            ];
            for s in &setup {
                fconn.execute(s).await.unwrap();
                rconn.execute_batch(s).unwrap();
            }

            let pre_update_queries = [
                "SELECT agent_id, workspace_id, source_id, source_path, started_at, origin_host FROM conversations WHERE id = 2",
            ];
            let pre_update_mismatches = oracle_compare(&fconn, &rconn, &pre_update_queries).await;
            if !pre_update_mismatches.is_empty() {
                for m in &pre_update_mismatches {
                    eprintln!("{m}\n");
                }
                panic!(
                    "{} pre-update alter-row mismatches",
                    pre_update_mismatches.len()
                );
            }

            let update = "UPDATE conversations SET source_id = '   ', origin_host = 'remote-ci' WHERE id = 2";
            fconn.execute(update).await.unwrap();
            rconn.execute_batch(update).unwrap();

            let queries = [
                "SELECT id, agent_id, workspace_id, source_id, origin_host, source_path, started_at FROM conversations ORDER BY id",
                "SELECT agent_id, workspace_id, source_id, origin_host FROM conversations WHERE id = 2",
            ];

            let mismatches = oracle_compare(&fconn, &rconn, &queries).await;
            if !mismatches.is_empty() {
                for m in &mismatches {
                    eprintln!("{m}\n");
                }
                panic!(
                    "{} update-after-alter-not-null preservation mismatches",
                    mismatches.len()
                );
            }
        });
    }

