    /// Regression: UPDATE SET with numbered placeholders (`?1`, `?2`) failed
    /// with "unsupported expression type: Placeholder" when all three
    /// conditions were met:
    /// 1. PRAGMA foreign_keys=ON
    /// 2. A table-level UNIQUE constraint exists
    /// 3. The schema includes ALTER TABLE ADD COLUMN history
    ///
    /// The root cause was `collect_update_trigger_rows` passing raw AST
    /// assignment expressions (still containing `Placeholder` nodes) to
    /// `eval_join_expr`, which had no arm for `Placeholder`.
    /// See: https://github.com/.../frankensqlite/issues/22
    #[test]
    fn test_update_numbered_placeholders_with_fk_on() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").await.unwrap();
            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute(
            "CREATE TABLE child (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES parent(id), val TEXT, UNIQUE(parent_id, val));",
        ).await
        .unwrap();
            // ALTER TABLE to add column history (third condition).
            conn.execute("ALTER TABLE child ADD COLUMN extra TEXT;")
                .await
                .unwrap();
            conn.execute("INSERT INTO parent VALUES (1, 'P1');")
                .await
                .unwrap();
            conn.execute("INSERT INTO child VALUES (1, 1, 'hello', NULL);")
                .await
                .unwrap();

            // This UPDATE with numbered placeholders should succeed.
            let affected = conn
                .execute_with_params(
                    "UPDATE child SET val = ?1, extra = ?2 WHERE id = ?3",
                    &[
                        SqliteValue::Text("world".into()),
                        SqliteValue::Text("extra_val".into()),
                        SqliteValue::Integer(1),
                    ],
                )
                .await
                .expect("UPDATE with numbered placeholders should succeed when FK is ON");
            assert_eq!(affected, 1, "should update exactly one row");

            let rows = conn
                .query("SELECT val, extra FROM child WHERE id = 1;")
                .await
                .unwrap();
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].values()[0], SqliteValue::Text("world".into()));
            assert_eq!(rows[0].values()[1], SqliteValue::Text("extra_val".into()));
        });
    }

    /// Regression test for issue #24: UPDATE on parent table with FK enforcement
    /// must NOT cascade-delete child rows when the FK-referenced column (PK) is
    /// unchanged.  Only non-PK columns are modified.
    #[test]
    fn test_update_parent_non_pk_column_preserves_children() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").await.unwrap();

            // TEXT PRIMARY KEY (not IPK) to test non-integer FK references.
            conn.execute("CREATE TABLE parent (id TEXT PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE child (
                id INTEGER PRIMARY KEY,
                parent_id TEXT NOT NULL REFERENCES parent(id) ON DELETE CASCADE,
                val TEXT
            );",
            )
            .await
            .unwrap();

            conn.execute("INSERT INTO parent (id, name) VALUES ('p1', 'original');")
                .await
                .unwrap();
            conn.execute("INSERT INTO child (id, parent_id, val) VALUES (1, 'p1', 'c1');")
                .await
                .unwrap();
            conn.execute("INSERT INTO child (id, parent_id, val) VALUES (2, 'p1', 'c2');")
                .await
                .unwrap();

            // Verify 2 children exist.
            let rows = conn
                .query("SELECT COUNT(*) FROM child WHERE parent_id = 'p1';")
                .await
                .unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(2));

            // UPDATE parent name (NOT the PK) using numbered placeholders.
            conn.execute_with_params(
                "UPDATE parent SET name = ?1 WHERE id = ?2",
                &[
                    SqliteValue::Text("updated".into()),
                    SqliteValue::Text("p1".into()),
                ],
            )
            .await
            .expect("UPDATE non-PK column should succeed");

            // Children MUST still exist — PK was not changed.
            let rows = conn
                .query("SELECT COUNT(*) FROM child WHERE parent_id = 'p1';")
                .await
                .unwrap();
            assert_eq!(
                rows[0].values()[0],
                SqliteValue::Integer(2),
                "child rows were incorrectly deleted by UPDATE of non-PK parent column"
            );

            // Verify parent name was actually updated.
            let rows = conn
                .query("SELECT name FROM parent WHERE id = 'p1';")
                .await
                .unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Text("updated".into()));
        });
    }

