    /// Regression test: UPDATE with ON UPDATE CASCADE correctly cascades
    /// when the FK-referenced column actually changes.
    #[test]
    fn test_update_parent_pk_column_cascades_correctly() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").await.unwrap();

            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY, name TEXT);")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE child (
                id INTEGER PRIMARY KEY,
                parent_id INTEGER REFERENCES parent(id) ON UPDATE CASCADE,
                val TEXT
            );",
            )
            .await
            .unwrap();

            conn.execute("INSERT INTO parent VALUES (1, 'original');")
                .await
                .unwrap();
            conn.execute("INSERT INTO child VALUES (1, 1, 'c1');")
                .await
                .unwrap();
            conn.execute("INSERT INTO child VALUES (2, 1, 'c2');")
                .await
                .unwrap();

            // Changing the PK with ON UPDATE CASCADE should update children.
            conn.execute("UPDATE parent SET id = 99 WHERE id = 1;")
                .await
                .unwrap();

            // Children should now reference the new PK.
            let rows = conn
                .query("SELECT COUNT(*) FROM child WHERE parent_id = 99;")
                .await
                .unwrap();
            assert_eq!(
                rows[0].values()[0],
                SqliteValue::Integer(2),
                "child rows should be cascaded to new parent PK"
            );

            // Old PK should have no children.
            let rows = conn
                .query("SELECT COUNT(*) FROM child WHERE parent_id = 1;")
                .await
                .unwrap();
            assert_eq!(rows[0].values()[0], SqliteValue::Integer(0));

            // Admission at the aggregate recursion cap must fail before either
            // side of the relationship is mutated.
            conn.fk_cascade_depth.set(MAX_TRIGGER_PROGRAM_DEPTH);
            let error = conn
                .execute("UPDATE parent SET id = 100 WHERE id = 99;")
                .await
                .expect_err("the next ON UPDATE action must be rejected at the depth cap");
            assert!(matches!(error, FrankenError::TriggerRecursionDepthExceeded));
            conn.fk_cascade_depth.set(0);
            let parent = conn
                .query("SELECT COUNT(*) FROM parent WHERE id = 99;")
                .await
                .unwrap();
            let children = conn
                .query("SELECT COUNT(*) FROM child WHERE parent_id = 99;")
                .await
                .unwrap();
            assert_eq!(parent[0].values()[0], SqliteValue::Integer(1));
            assert_eq!(children[0].values()[0], SqliteValue::Integer(2));
        });
    }

    #[test]
    fn test_fk_update_actions_observe_parent_update_and_precede_parent_after_trigger() {
        asupersync::test_utils::run_test(|| async {
            let conn = Connection::open(":memory:").await.unwrap();
            conn.execute("PRAGMA foreign_keys = ON;").await.unwrap();
            conn.execute("CREATE TABLE parent (id INTEGER PRIMARY KEY);")
                .await
                .unwrap();
            conn.execute(
                "CREATE TABLE child (
                    parent_id INTEGER REFERENCES parent(id) ON UPDATE CASCADE
                );",
            )
            .await
            .unwrap();
            conn.execute("CREATE TABLE action_log (message TEXT);")
                .await
                .unwrap();
            conn.execute(
                "CREATE TRIGGER child_after_update AFTER UPDATE ON child BEGIN
                    INSERT INTO action_log
                    SELECT 'child:' || COUNT(*) FROM parent WHERE id = NEW.parent_id;
                END;",
            )
            .await
            .unwrap();
            conn.execute(
                "CREATE TRIGGER parent_after_update AFTER UPDATE ON parent BEGIN
                    INSERT INTO action_log
                    SELECT 'parent:' || COUNT(*) FROM child WHERE parent_id = NEW.id;
                END;",
            )
            .await
            .unwrap();
            conn.execute("INSERT INTO parent VALUES (1);")
                .await
                .unwrap();
            conn.execute("INSERT INTO child VALUES (1);").await.unwrap();

            conn.execute("UPDATE parent SET id = 2 WHERE id = 1;")
                .await
                .unwrap();

            let rows = conn
                .query("SELECT message FROM action_log ORDER BY rowid;")
                .await
                .unwrap();
            assert_eq!(
                rows.iter()
                    .map(|row| row.values()[0].clone())
                    .collect::<Vec<_>>(),
                vec![
                    SqliteValue::Text("child:1".into()),
                    SqliteValue::Text("parent:1".into()),
                ],
                "the child FK program must see the new parent and finish before the parent AFTER trigger"
            );
        });
    }

